-- ── 127. a lecturer keeps their own profile: scalars, list sections and a photograph, upserted whole and read back (V107) ──
DO $$
DECLARE
    v_person uuid := '00000000-0000-0000-0000-0000000000c7';
    r        hrm.staff_profile;
    v_pubs   int; v_ct text; v_dept text;
BEGIN
    PERFORM set_config('moaum.actor_id', v_person::text, true);
    PERFORM set_config('moaum.actor_office', 'lecturer', true);
    PERFORM set_config('moaum.reason', 'CHECK staff profile', true);

    INSERT INTO iam.person (id, staff_number, surname, given_names)
    VALUES (v_person, 'MOAUM/CHK/PROF', 'CHECKPROF', 'Ada Lovelace')
    ON CONFLICT (id) DO NOTHING;

    -- first save
    r := hrm.save_my_staff_profile($json$
        {"email":"ada@example.com","phone":"08030000000","department":"Mathematics",
         "faculty":"Science","responsibility":"Examinations Officer",
         "scholarUrl":"https://scholar.google.com/citations?user=ADA",
         "researchInterests":"Numerical analysis, computability",
         "mastersGraduated":"7","phdGraduated":"2",
         "publications":["A note on engines, J. Analytical Eng., 1843"],
         "grants":["TETFund IBR 2024 — 5,000,000"],
         "collaborations":["University of Turin (international)"],
         "conferences":["ICM 2022, attended"],
         "assignments":["NUC accreditation panel (national)"],
         "innovations":["A teaching abacus"],"patents":["NG/PAT/2023/1"],
         "achievements":["Best lecturer 2021"],"contributions":["STEM outreach, rural schools"]}
    $json$::jsonb);

    -- upsert again with fewer fields: the row is replaced whole, not merged
    r := hrm.save_my_staff_profile('{"department":"Applied Mathematics","phdGraduated":"3"}'::jsonb);
    PERFORM hrm.set_my_staff_photo('image/png', 3, E'\\x89504e'::bytea);
    PERFORM hrm.set_my_staff_photo('image/jpeg', 2, E'\\xffd8'::bytea);  -- replaces, one row

    SELECT jsonb_array_length(publications), department INTO v_pubs, v_dept
      FROM hrm.staff_profile WHERE person_id = v_person;
    SELECT content_type INTO v_ct FROM hrm.staff_photo WHERE person_id = v_person;

    PERFORM pg_temp.assert(
      'A lecturer keeps their own profile: it upserts whole, the list sections are read back, and one photograph is held',
      r.person_id = v_person AND r.phd_graduated = 3 AND r.department = 'Applied Mathematics'
      AND v_dept = 'Applied Mathematics' AND v_pubs = 0
      AND (SELECT count(*) FROM hrm.staff_profile WHERE person_id = v_person) = 1
      AND (SELECT count(*) FROM hrm.staff_photo WHERE person_id = v_person) = 1
      AND v_ct = 'image/jpeg',
      format('phd=%s dept=%s pubs=%s photo=%s', r.phd_graduated, v_dept, v_pubs, v_ct));
END $$;

-- ── 129. the operational-data reset runs to completion, clearing suggestion_sent before the applications it hangs on (V089/V108) ──
-- Runs the real reset inside a savepoint and rolls it back, so it proves the
-- function executes end to end without disturbing the suite's data. With a
-- suggestion_sent row present it also guards the delete order: the pre-V108
-- reset would fail here with a foreign-key violation.
DO $$
DECLARE app uuid; res jsonb; ran boolean := false; had_app boolean;
BEGIN
    PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
    PERFORM set_config('moaum.actor_office', 'super', true);
    PERFORM set_config('moaum.reason', 'CHECK reset validation', true);

    SELECT id INTO app FROM admissions.application LIMIT 1;
    had_app := app IS NOT NULL;

    BEGIN
        IF had_app THEN
            INSERT INTO admissions.suggestion_sent (application_id, programmes, sent_by)
            VALUES (app, 'CHK suggestion', nullif(current_setting('moaum.actor_id', true), '')::uuid)
            ON CONFLICT (application_id) DO NOTHING;
        END IF;
        res := platform.reset_operational_data('RESET', 'CHECK reset validation');
        ran := (res->>'reset')::boolean;
        RAISE EXCEPTION 'chk_reset_rollback';   -- undo every delete; the point is only that it ran
    EXCEPTION WHEN raise_exception THEN
        IF SQLERRM <> 'chk_reset_rollback' THEN RAISE; END IF;   -- a real failure (e.g. FK order) propagates
    END;

    PERFORM pg_temp.assert(
        'The operational-data reset runs to completion, clearing suggestion_sent before the applications it references',
        ran,
        format('ran=%s had_application=%s', ran, had_app));
END $$;

-- ── 130. the session roll-over promotes active continuing students one level and enrols them, leaving final-year and withdrawn students (V110) ──
-- Runs the real roll-over inside a savepoint and rolls it back, so it neither
-- promotes the suite's other fixtures nor leaves a session behind.
DO $$
DECLARE
    v_active uuid := gen_random_uuid(); v_final uuid := gen_random_uuid(); v_wd uuid := gen_random_uuid();
    res jsonb; ran boolean := false; lvl_active int; lvl_final int; lvl_wd int; enrolled boolean;
BEGIN
    PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
    PERFORM set_config('moaum.actor_office', 'registrar', true);
    PERFORM set_config('moaum.reason', 'CHECK session rollover', true);

    INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode,
                                entry_session, entry_level, current_level, status, matriculated_at) VALUES
      (v_active, 'MOAUM/ADM/99/970001', 'MOAUM/RLA/99/0001', 'ROLLACTIVE', 'Two Hundred', 'C00061', 'UTME', '9990/9991', 100, 200, 'ACTIVE', now()),
      (v_final,  'MOAUM/ADM/99/970002', 'MOAUM/RLF/99/0002', 'ROLLFINAL',  'Final Year',  'C00019', 'UTME', '9990/9991', 100, 400, 'ACTIVE', now()),
      (v_wd,     'MOAUM/ADM/99/970003', 'MOAUM/RLW/99/0003', 'ROLLGONE',   'Withdrawn',   'C00061', 'UTME', '9990/9991', 100, 200, 'WITHDRAWN', now());

    BEGIN
        res := people.roll_over_session('9989/9990', 'ROLLOVER', 'CHECK session rollover');
        ran := (res->>'session') = '9989/9990';
        SELECT current_level INTO lvl_active FROM people.student WHERE id = v_active;
        SELECT current_level INTO lvl_final  FROM people.student WHERE id = v_final;
        SELECT current_level INTO lvl_wd     FROM people.student WHERE id = v_wd;
        SELECT EXISTS (SELECT 1 FROM people.enrolment WHERE student_id = v_active AND session = '9989/9990' AND level = 300) INTO enrolled;
        RAISE EXCEPTION 'chk_rollover_rollback';   -- undo the promotion and the created session
    EXCEPTION WHEN raise_exception THEN
        IF SQLERRM <> 'chk_rollover_rollback' THEN RAISE; END IF;
    END;

    PERFORM pg_temp.assert(
        'The session roll-over promotes an active continuing student one level and enrols them, and leaves a final-year and a withdrawn student where they are',
        ran AND lvl_active = 300 AND enrolled AND lvl_final = 400 AND lvl_wd = 200,
        format('ran=%s active=%s enrolled=%s final=%s withdrawn=%s', ran, lvl_active, enrolled, lvl_final, lvl_wd));
END $$;

-- ── 133. a re-sit replaces a failed Main capped at the pass mark; a Special is uncapped (V197–V199) ──
DO $$
DECLARE
    a uuid := gen_random_uuid();
    stu1 uuid := gen_random_uuid();   -- fails the Main, passes the re-sit
    stu2 uuid := gen_random_uuid();   -- absent in the Main, sits the Special
    prog text; dept text; sess text := '2093/2094';
    offR uuid := gen_random_uuid(); offS uuid := gen_random_uuid();
    regR uuid := gen_random_uuid(); regS uuid := gen_random_uuid();
    esMain uuid := gen_random_uuid(); esResit uuid := gen_random_uuid(); esSpecial uuid := gen_random_uuid();
    shRmain uuid := gen_random_uuid(); shSmain uuid := gen_random_uuid();
    shRresit uuid := gen_random_uuid(); shSspecial uuid := gen_random_uuid();
    v_pts numeric; v_out text; v_tot int; v_on_roll boolean; v_pts2 numeric; v_tot2 int;
BEGIN
    PERFORM set_config('moaum.actor_id', a::text, true);
    PERFORM set_config('moaum.actor_office', 'academic', true);
    PERFORM set_config('moaum.reason', 'check: resit/special', true);
    SELECT code INTO prog FROM ref.programme WHERE NOT archived ORDER BY code LIMIT 1;
    SELECT code INTO dept FROM ref.department ORDER BY code LIMIT 1;
    -- the session an offering hangs on (a far-future range so it cannot overlap another)
    INSERT INTO policy.academic_session (id, name, starts_on, ends_on)
    VALUES (gen_random_uuid(), sess, DATE '2093-10-01', DATE '2094-08-31') ON CONFLICT (name) DO NOTHING;

    INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, state) VALUES
        ('ZZR 401', 'Re-sit Test', 3, 1, 400, dept, 'LIVE'),
        ('ZZS 401', 'Special Test', 3, 1, 400, dept, 'LIVE');
    INSERT INTO catalogue.offering (id, course_code, session, semester) VALUES
        (offR, 'ZZR 401', sess, 1), (offS, 'ZZS 401', sess, 1);
    INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at) VALUES
        (stu1, 'MOAUM/ADM/20/990001', 'MOAUM/XX/20/9001', 'RESITONE', 'Invented', prog, 'UTME', '2020/2021', 100, 400, 'ACTIVE', now()),
        (stu2, 'MOAUM/ADM/20/990002', 'MOAUM/XX/20/9002', 'SPECIALTWO', 'Invented', prog, 'UTME', '2020/2021', 100, 400, 'ACTIVE', now());
    INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, approved_at) VALUES
        (regR, stu1, sess, 1, 400, 'APPROVED', now()), (regS, stu2, sess, 1, 400, 'APPROVED', now());
    INSERT INTO registration.entry (registration_id, offering_id, units, status) VALUES
        (regR, offR, 3, 'APPROVED'), (regS, offS, 3, 'APPROVED');
    INSERT INTO assessment.exam_session (id, session, semester, kind, exams_from, exams_to, sheets_due, state, opened_at) VALUES
        (esMain, sess, 1, 'MAIN', DATE '2094-01-08', DATE '2094-01-19', DATE '2094-02-16', 'OPEN', now()),
        (esResit, sess, 1, 'RESIT', DATE '2094-03-08', DATE '2094-03-19', DATE '2094-04-16', 'OPEN', now()),
        (esSpecial, sess, 1, 'SPECIAL', DATE '2094-03-08', DATE '2094-03-19', DATE '2094-04-16', 'OPEN', now());

    -- Main sittings published: stu1 fails ZZR 401 (25), stu2 absent in ZZS 401
    INSERT INTO assessment.score_sheet (id, offering_id, exam_session_id, stage, senate_minute, published_at, submitted_at) VALUES
        (shRmain, offR, esMain, 'PUBLISHED', 'SEN/2094/01', now(), now()),
        (shSmain, offS, esMain, 'PUBLISHED', 'SEN/2094/01', now(), now());
    INSERT INTO assessment.score (sheet_id, student_id, ca, exam, outcome) VALUES
        (shRmain, stu1, 10, 15, 'GRADED'), (shSmain, stu2, NULL, NULL, 'ABSENT');

    -- before the re-sit, the failed course is a fail on the record
    SELECT points, outcome INTO v_pts, v_out FROM assessment.student_results(stu1) WHERE course_code = 'ZZR 401';
    PERFORM pg_temp.assert('A failed Main sitting shows as a fail (0 points) before any re-sit',
        v_out = 'GRADED' AND coalesce(v_pts, -1) = 0, format('points=%s outcome=%s', v_pts, v_out));

    -- the re-sit sheet: its roster is the failed candidate, and a pass replaces the fail capped at the pass mark
    INSERT INTO assessment.score_sheet (id, offering_id, exam_session_id, stage, senate_minute, published_at, submitted_at)
        VALUES (shRresit, offR, esResit, 'ENTRY', NULL, NULL, NULL);
    SELECT EXISTS (SELECT 1 FROM assessment.sheet_candidates(shRresit) WHERE student_id = stu1) INTO v_on_roll;
    INSERT INTO assessment.score (sheet_id, student_id, ca, exam, outcome) VALUES (shRresit, stu1, 30, 35, 'GRADED');  -- 65, a clear pass
    UPDATE assessment.score_sheet SET stage = 'PUBLISHED', senate_minute = 'SEN/2094/07', published_at = now(), submitted_at = now() WHERE id = shRresit;
    SELECT points, total INTO v_pts, v_tot FROM assessment.student_results(stu1) WHERE course_code = 'ZZR 401';
    PERFORM pg_temp.assert('A passed re-sit is on the failed candidate''s roster and replaces the Main, capped at the pass mark (E/40/1.0)',
        v_on_roll AND coalesce(v_pts, -1) = 1.0 AND v_tot = 40, format('on_roll=%s points=%s total=%s', v_on_roll, v_pts, v_tot));

    -- the Special sitting: an absent candidate sits it, and the mark counts uncapped
    INSERT INTO assessment.score_sheet (id, offering_id, exam_session_id, stage, senate_minute, published_at, submitted_at)
        VALUES (shSspecial, offS, esSpecial, 'PUBLISHED', 'SEN/2094/08', now(), now());
    INSERT INTO assessment.score (sheet_id, student_id, ca, exam, outcome) VALUES (shSspecial, stu2, 30, 35, 'GRADED');  -- 65
    SELECT points, total INTO v_pts2, v_tot2 FROM assessment.student_results(stu2) WHERE course_code = 'ZZS 401';
    PERFORM pg_temp.assert('A Special sitting replaces an absence uncapped (65 -> B/4.0)',
        coalesce(v_pts2, -1) = 4.0 AND v_tot2 = 65, format('points=%s total=%s', v_pts2, v_tot2));

    -- cleanup
    DELETE FROM assessment.score WHERE sheet_id IN (shRmain, shSmain, shRresit, shSspecial);
    DELETE FROM assessment.score_sheet WHERE id IN (shRmain, shSmain, shRresit, shSspecial);
    DELETE FROM assessment.exam_session WHERE id IN (esMain, esResit, esSpecial);
    DELETE FROM registration.entry WHERE registration_id IN (regR, regS);
    DELETE FROM registration.course_registration WHERE id IN (regR, regS);
    DELETE FROM people.student WHERE id IN (stu1, stu2);
    DELETE FROM catalogue.offering WHERE id IN (offR, offS);
    DELETE FROM catalogue.course WHERE code IN ('ZZR 401', 'ZZS 401');
    DELETE FROM policy.academic_session WHERE name = sess;
END $$;

-- ── 17c. a script from a candidate not on the roll is held, released by an approved registration, lapsed past the date (V240) ──
DO $$
DECLARE sh uuid; o uuid; st uuid := gen_random_uuid(); st2 uuid := gen_random_uuid(); reg uuid := gen_random_uuid();
        hid uuid; hid2 uuid; refused boolean := false; l record; had_sem boolean; old_late date; lapsed int; rel_state text; lap_state text;
        held_before boolean;
BEGIN
    PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
    PERFORM set_config('moaum.actor_office', 'lecturer', true);
    SELECT s.id, o2.id INTO sh, o FROM assessment.score_sheet s JOIN catalogue.offering o2 ON o2.id = s.offering_id WHERE o2.course_code = 'CHK 901';
    INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
    VALUES (st,  'MOAUM/ADM/99/990902', 'MOAUM/CHK/99/0902', 'CHECKHELD',  'Invented', 'C00023', 'UTME', '9999/0000', 100, 100, 'ACTIVE', now()),
           (st2, 'MOAUM/ADM/99/990903', 'MOAUM/CHK/99/0903', 'CHECKLAPSE', 'Invented', 'C00023', 'UTME', '9999/0000', 100, 100, 'ACTIVE', now());
    -- a mark over the course's split is refused even while held; the number is read whatever its case
    BEGIN PERFORM assessment.hold_script(sh, 'MOAUM/CHK/99/0902', 35, 10, NULL, NULL); EXCEPTION WHEN check_violation THEN refused := true; END;
    hid := assessment.hold_script(sh, 'moaum/chk/99/0902', 25, 40, NULL, 'script 7');
    held_before := NOT EXISTS (SELECT 1 FROM assessment.latest_scores(sh) x WHERE x.student_id = st);
    -- the registration approved: the register releases the script into the sheet
    PERFORM set_config('moaum.actor_office', 'hod', true);
    INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, approved_at) VALUES (reg, st, '9999/0000', 1, 100, 'APPROVED', now());
    INSERT INTO registration.entry (registration_id, offering_id, units, status) VALUES (reg, o, 3, 'APPROVED');
    SELECT state INTO rel_state FROM assessment.held_script WHERE id = hid;
    SELECT * INTO l FROM assessment.latest_scores(sh) x WHERE x.student_id = st;
    -- past the semester's late-registration date, a held script lapses
    SELECT EXISTS (SELECT 1 FROM policy.semester WHERE session = '9999/0000' AND number = 1) INTO had_sem;
    IF NOT had_sem THEN INSERT INTO policy.semester (id, session, number, state) VALUES (gen_random_uuid(), '9999/0000', 1, 'CLOSED'); END IF;
    SELECT late_registration_closes INTO old_late FROM policy.semester WHERE session = '9999/0000' AND number = 1;
    PERFORM set_config('moaum.actor_office', 'lecturer', true);
    hid2 := assessment.hold_script(sh, 'MOAUM/CHK/99/0903', 20, 30, NULL, NULL);
    UPDATE policy.semester SET late_registration_closes = current_date - 1 WHERE session = '9999/0000' AND number = 1;
    lapsed := assessment.lapse_held_scripts();
    SELECT state INTO lap_state FROM assessment.held_script WHERE id = hid2;
    UPDATE policy.semester SET late_registration_closes = old_late WHERE session = '9999/0000' AND number = 1;
    IF NOT had_sem THEN DELETE FROM policy.semester WHERE session = '9999/0000' AND number = 1; END IF;
    PERFORM pg_temp.assert('A script from a candidate not on the roll is held (a mark over the split refused), stays off the sheet until the registration is approved, is then released as the mark, and lapses past the late-registration date',
        refused AND held_before AND rel_state = 'RELEASED' AND l.total = 65 AND l.version = 1 AND lapsed >= 1 AND lap_state = 'LAPSED',
        format('refused=%s held_before=%s released=%s total=%s version=%s lapsed=%s lapse_state=%s', refused, held_before, rel_state, l.total, l.version, lapsed, lap_state));
END $$;

-- ── 17d. the College of Health Sciences' tables hold the prospectus, and its rules answer as it says (V245) ──
DO $$
DECLARE n_blocks int; n_postings int; n_exams int; n_subjects int; n_slots int; n_procs int; n_rules int; med_weeks int;
        pe3_paed uuid; pe1_anat uuid; ok_pass boolean; ok_clin boolean; ok_fail boolean; ok_dist boolean; nxt1 text; nxt2 text; nxt3 text;
BEGIN
    SELECT count(*) INTO n_blocks FROM college.block;
    SELECT count(*) INTO n_postings FROM college.posting;
    SELECT count(*) INTO n_exams FROM college.professional_exam;
    SELECT count(*) INTO n_subjects FROM college.exam_subject;
    SELECT count(*) INTO n_slots FROM college.timetable_slot t JOIN college.posting p ON p.id = t.posting_id WHERE p.code = 'PSY';
    SELECT count(*) INTO n_procs FROM college.procedure_requirement;
    SELECT count(*) INTO n_rules FROM college.attendance_rule;
    SELECT sum(duration_weeks)::int INTO med_weeks FROM college.posting p JOIN college.block b ON b.id = p.block_id WHERE b.code = 'MED';
    SELECT s.id INTO pe3_paed FROM college.exam_subject s JOIN college.professional_exam e ON e.id = s.exam_id WHERE e.code = 'PE3' AND s.name = 'Paediatrics';
    SELECT s.id INTO pe1_anat FROM college.exam_subject s JOIN college.professional_exam e ON e.id = s.exam_id WHERE e.code = 'PE1' AND s.name = 'Anatomy';
    ok_pass := college.passes(pe1_anat, 20, 30);                 -- 50: a pass
    ok_fail := NOT college.passes(pe1_anat, 20, 29);             -- 49: not
    ok_clin := NOT college.passes(pe3_paed, 25, 40, 45) AND college.passes(pe3_paed, 25, 40, 50);   -- the clinical component must be 50 too
    ok_dist := college.distinction('C00061', 70) AND NOT college.distinction('C00061', 69);
    nxt1 := college.next_attempt('PE1', 3, 3);                   -- all three failed: repeat, no resit
    nxt2 := college.next_attempt('PE1', 1, 3);                   -- one failed: resit
    nxt3 := college.next_attempt('CPE', 1, 3);                   -- the CPE has no resit
    PERFORM pg_temp.assert('The College tables hold the prospectus — eight blocks, the postings, Internal Medicine 34 weeks, the CPE and four Professionals with 13 subjects, Psychiatry''s 200 slots, nine Paediatrics procedures, three attendance rules — and its rules answer as it says',
        n_blocks = 8 AND n_postings = 24 AND med_weeks = 34 AND n_exams = 5 AND n_subjects = 13 AND n_slots = 200 AND n_procs = 9 AND n_rules = 3
        AND ok_pass AND ok_fail AND ok_clin AND ok_dist AND nxt1 = 'REPEAT' AND nxt2 = 'RESIT' AND nxt3 = 'REPEAT',
        format('blocks=%s postings=%s med_weeks=%s exams=%s subjects=%s slots=%s procs=%s rules=%s pass=%s fail=%s clin=%s dist=%s next=%s/%s/%s',
               n_blocks, n_postings, med_weeks, n_exams, n_subjects, n_slots, n_procs, n_rules, ok_pass, ok_fail, ok_clin, ok_dist, nxt1, nxt2, nxt3));
END $$;

-- ── 17e. Senate's rule on probation and withdrawal answers as worded (V246) ──
DO $$
DECLARE a text; b text; c text; d text; e text; f text; g text; h text; i text;
BEGIN
    a := assessment.standing_of(100, 1, 0.80, NULL, false);    -- 100 level first semester: nothing pronounced
    b := assessment.standing_of(100, 2, 0.80, 0.90, false);    -- 100 level second semester under 1.0: to go on probation
    c := assessment.standing_of(200, 1, 0.90, 0.80, false);    -- 200 level first semester still under: the probation list
    d := assessment.standing_of(200, 1, 0.90, NULL, true);     -- a Direct Entry student's first semester: no standing
    e := assessment.standing_of(200, 2, 0.95, 0.90, false);    -- 200 level second semester still under: advised to withdraw
    f := assessment.standing_of(200, 2, 0.95, 1.20, false);    -- fell under only now: probation, not withdrawal
    g := assessment.standing_of(200, 2, 0.95, 0.90, true);     -- Direct Entry at 200 level: probation, their first year
    h := assessment.standing_of(300, 2, 0.95, 0.90, false);    -- the pattern repeats at every level
    i := assessment.standing_of(200, 2, 1.00, 0.90, false);    -- at 1.0 nothing is pronounced
    PERFORM pg_temp.assert('Senate''s rule: probation at 100 level second semester and every first semester from 200 under 1.0; advised to withdraw at the second semester still under 1.0; nothing for a Direct Entry first semester or at 1.0',
        a IS NULL AND b = 'PROBATION' AND c = 'PROBATION' AND d IS NULL AND e = 'ADVISED_TO_WITHDRAW' AND f = 'PROBATION' AND g = 'PROBATION' AND h = 'ADVISED_TO_WITHDRAW' AND i IS NULL,
        format('100/1=%s 100/2=%s 200/1=%s DE=%s 200/2=%s fresh=%s DE200/2=%s 300/2=%s at1=%s', a, b, c, d, e, f, g, h, i));
END $$;

-- ── 17f. four consecutive closed semesters without a registration make a voluntary withdrawal (V247) ──
DO $$
DECLARE st uuid := gen_random_uuid(); reg uuid := gen_random_uuid(); n0 int; n1 int; n2 int; due0 boolean; due1 boolean; closed int; st_status text; changed int;
BEGIN
    PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
    PERFORM set_config('moaum.actor_office', 'registrar', true);
    INSERT INTO policy.academic_session (id, name, starts_on, ends_on)
    VALUES (gen_random_uuid(), '9990/9991', date '9990-10-01', date '9991-08-31'), (gen_random_uuid(), '9991/9992', date '9991-10-01', date '9992-08-31')
    ON CONFLICT (name) DO NOTHING;   -- §101's legacy import may already have made 9991/9992
    INSERT INTO policy.semester (id, session, number, state)
    SELECT gen_random_uuid(), v.s, n, 'CLOSED' FROM (VALUES ('9990/9991'), ('9991/9992')) v(s) CROSS JOIN generate_series(1, 2) n
    ON CONFLICT (session, number) DO UPDATE SET state = 'CLOSED';
    -- the later test sessions other checks closed are set aside while this one counts (they are dated centuries ahead, so not yet open is true), and restored below
    CREATE TEMP TABLE IF NOT EXISTS vw_set_aside AS SELECT id FROM policy.semester WHERE false;
    INSERT INTO vw_set_aside SELECT id FROM policy.semester WHERE session > '9991/9992' AND state = 'CLOSED';
    UPDATE policy.semester SET state = 'NOT_YET_OPEN' WHERE id IN (SELECT id FROM vw_set_aside);
    INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
    VALUES (st, 'MOAUM/ADM/99/990904', 'MOAUM/CHK/99/0904', 'CHECKVOLUNTARY', 'Invented', 'C00023', 'UTME', '9990/9991', 100, 100, 'ACTIVE', now());
    SELECT semesters INTO n0 FROM registration.semesters_unregistered(st);                         -- four closed since entry, none registered
    due0 := EXISTS (SELECT 1 FROM registration.voluntary_withdrawals_due() d WHERE d.student_id = st);
    -- an approved registration in the third semester: only one closed semester follows it
    INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, approved_at) VALUES (reg, st, '9991/9992', 1, 100, 'APPROVED', now());
    SELECT semesters INTO n1 FROM registration.semesters_unregistered(st);
    due1 := EXISTS (SELECT 1 FROM registration.voluntary_withdrawals_due() d WHERE d.student_id = st);
    DELETE FROM registration.course_registration WHERE id = reg;
    SELECT semesters INTO n2 FROM registration.semesters_unregistered(st);
    -- the Registry closes the record due: the status changes on the regulation as its instrument, and the change is on the record
    closed := registration.effect_voluntary_withdrawals('University regulation: four consecutive semesters without course registration', st);
    SELECT status INTO st_status FROM people.student WHERE id = st;
    SELECT count(*) INTO changed FROM people.status_change WHERE student_id = st AND to_status = 'VOLUNTARY_WITHDRAWAL';
    DELETE FROM people.status_change WHERE student_id = st;
    DELETE FROM people.student WHERE id = st;
    UPDATE policy.semester SET state = 'CLOSED' WHERE id IN (SELECT id FROM vw_set_aside);
    DROP TABLE vw_set_aside;
    BEGIN   -- the sessions stay where another check's records still hang on them
        DELETE FROM policy.semester WHERE session IN ('9990/9991', '9991/9992');
        DELETE FROM policy.academic_session WHERE name IN ('9990/9991', '9991/9992');
    EXCEPTION WHEN foreign_key_violation THEN NULL;
    END;
    PERFORM pg_temp.assert('Four consecutive closed semesters without an approved registration make a voluntary withdrawal: due at four, not after a registration in the third, closed by the Registry on the regulation, on the record',
        n0 = 4 AND due0 AND n1 = 1 AND NOT due1 AND n2 = 4 AND closed = 1 AND st_status = 'VOLUNTARY_WITHDRAWAL' AND changed = 1,
        format('missed=%s due=%s after_reg=%s due_after=%s again=%s closed=%s status=%s changes=%s', n0, due0, n1, due1, n2, closed, st_status, changed));
END $$;

-- ── 17g. the College's progression: barred by attendance, the rule applied provisionally, the Board's confirmation moves the student (V248) ──
DO $$
DECLARE st uuid := gen_random_uuid(); ses text; anat uuid; bcm uuid; phs uuid; j record; barred_ok boolean; pass_ok boolean;
        o1 text; o2 text; st1 text; en_state text; n_conf int; o3 text; lvl int; en2_state text; hist int;
BEGIN
    PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
    PERFORM set_config('moaum.actor_office', 'collegesecretary', true);
    SELECT name INTO ses FROM policy.academic_session WHERE state = 'CURRENT' LIMIT 1;
    IF ses IS NULL THEN SELECT name INTO ses FROM policy.academic_session ORDER BY name DESC LIMIT 1; END IF;
    SELECT s.id INTO anat FROM college.exam_subject s JOIN college.professional_exam e ON e.id = s.exam_id WHERE e.code = 'PE1' AND s.name = 'Anatomy';
    SELECT s.id INTO bcm  FROM college.exam_subject s JOIN college.professional_exam e ON e.id = s.exam_id WHERE e.code = 'PE1' AND s.name = 'Medical Biochemistry';
    SELECT s.id INTO phs  FROM college.exam_subject s JOIN college.professional_exam e ON e.id = s.exam_id WHERE e.code = 'PE1' AND s.name = 'Physiology';
    -- attendance below the 1st Professional's 75% bars the candidate; at 75 the marks decide
    SELECT * INTO j FROM college.judge(anat, 20, 40, NULL, 60);  barred_ok := j.barred AND j.passed = false;
    SELECT * INTO j FROM college.judge(anat, 20, 40, NULL, 80);  pass_ok := NOT j.barred AND j.passed;
    -- a College student at 300 Level, registered for the year
    INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
    VALUES (st, 'MOAUM/ADM/99/990905', 'MOAUM/CHK/99/0905', 'CHECKCOLLEGE', 'Invented', 'C00061', 'UTME', ses, 100, 300, 'ACTIVE', now());
    INSERT INTO college.enrolment (student_id, level, session, registered_at, registered_items) VALUES (st, 300, ses, now(), 5);
    -- two subjects passed, Physiology failed at the first attempt: the rule says resit, applied provisionally
    INSERT INTO college.exam_result (student_id, subject_id, session, attempt, ca_score, exam_score, attendance_pct, passed, decided_on) VALUES
        (st, anat, ses, 'FIRST', 22, 45, 90, true, current_date), (st, bcm, ses, 'FIRST', 20, 40, 88, true, current_date);
    o1 := college.apply_provisional(st, 'PE1', ses);                                   -- incomplete: nothing applied
    INSERT INTO college.exam_result (student_id, subject_id, session, attempt, ca_score, exam_score, attendance_pct, passed, decided_on) VALUES
        (st, phs, ses, 'FIRST', 12, 25, 85, false, current_date);
    o2 := college.apply_provisional(st, 'PE1', ses);
    SELECT state INTO st1 FROM college.progression_decision WHERE student_id = st AND from_level = 300 AND session = ses;
    -- the Board confirms: the enrolment waits on the resit, the student stays at 300
    n_conf := college.confirm_decisions('PE1', ses, 'CAB/CHK/1');
    SELECT state INTO en_state FROM college.enrolment WHERE student_id = st AND level = 300 AND session = ses;
    -- the resit passed: the rule says promote; confirmed, the student is at 400 and the year is closed
    INSERT INTO college.exam_result (student_id, subject_id, session, attempt, ca_score, exam_score, attendance_pct, passed, decided_on) VALUES
        (st, phs, ses, 'RESIT', 18, 40, 85, true, current_date);
    o3 := college.apply_provisional(st, 'PE1', ses);
    PERFORM college.confirm_decisions('PE1', ses, 'CAB/CHK/2');
    SELECT current_level INTO lvl FROM people.student WHERE id = st;
    SELECT state INTO en2_state FROM college.enrolment WHERE student_id = st AND level = 300 AND session = ses;
    SELECT count(*) INTO hist FROM college.exam_result WHERE student_id = st;
    DELETE FROM college.progression_decision WHERE student_id = st;
    DELETE FROM college.exam_result WHERE student_id = st;
    DELETE FROM college.enrolment WHERE student_id = st;
    DELETE FROM people.status_change WHERE student_id = st;
    DELETE FROM people.student WHERE id = st;
    PERFORM pg_temp.assert('The College''s progression: attendance under the minimum bars; nothing applies until every subject is resulted; one fail at the first attempt is a provisional resit the Board confirms; the resit passed is a promotion that moves the student to 400 and closes the year',
        barred_ok AND pass_ok AND o1 IS NULL AND o2 = 'RESIT' AND st1 = 'PROVISIONAL' AND n_conf = 1 AND en_state = 'RESIT' AND o3 = 'PROMOTE' AND lvl = 400 AND en2_state = 'CLOSED' AND hist = 4,
        format('barred=%s pass=%s first=%s then=%s state=%s confirmed=%s enrolment=%s resit=%s level=%s closed=%s results=%s', barred_ok, pass_ok, o1, o2, st1, n_conf, en_state, o3, lvl, en2_state, hist));
END $$;

-- ── 17h. two cohorts at one level, each its own year: the cohort is the session's enrolments; the year's semesters; the end-of-year guard (V249) ──
DO $$
DECLARE a uuid := gen_random_uuid(); b uuid := gen_random_uuid(); s_old text; s_new text; ea uuid; eb uuid; n_old int; n_new int; sems int;
        cur_level int; cur_session text; reached_undated boolean; reached_ahead boolean; reached_now boolean; ls text; refused boolean := false;
BEGIN
    PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
    PERFORM set_config('moaum.actor_office', 'collegesecretary', true);
    SELECT name INTO s_new FROM policy.academic_session WHERE state = 'CURRENT' LIMIT 1;
    IF s_new IS NULL THEN SELECT name INTO s_new FROM policy.academic_session ORDER BY name DESC LIMIT 1; END IF;
    SELECT name INTO s_old FROM policy.academic_session WHERE name < s_new ORDER BY name DESC LIMIT 1;
    IF s_old IS NULL THEN s_old := s_new; END IF;
    -- cohort A began 200 Level in the earlier session; cohort B, promoted from 100, begins it in the current one
    INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at) VALUES
        (a, 'MOAUM/ADM/99/990906', 'MOAUM/CHK/99/0906', 'CHECKCOHORT', 'Earlier', 'C00061', 'UTME', s_old, 100, 200, 'ACTIVE', now()),
        (b, 'MOAUM/ADM/99/990907', 'MOAUM/CHK/99/0907', 'CHECKCOHORT', 'Later',   'C00061', 'UTME', s_new, 100, 200, 'ACTIVE', now());
    ea := college.open_enrolment(a, 200, s_old, NULL);
    eb := college.open_enrolment(b, 200, s_new, NULL);
    SELECT count(*) INTO sems FROM college.enrolment_semester WHERE enrolment_id = ea;                    -- the two semesters of 200 Level
    SELECT count(*) INTO n_old FROM college.cohort(200, s_old);                                          -- A's cohort holds A, not B
    SELECT count(*) INTO n_new FROM college.cohort(200, s_new) c WHERE c.student_id IN (a, b);           -- B's holds B, not A
    SELECT (college.current_enrolment(a)).level, (college.current_enrolment(a)).session INTO cur_level, cur_session;   -- A's current year is the old session's
    -- a second year cannot open while one is open
    BEGIN PERFORM college.open_enrolment(a, 200, s_new, NULL); EXCEPTION WHEN check_violation THEN refused := true; END;
    -- the end-of-year guard: undated, it blocks (V285: false until the calendar is dated); the final semester ahead blocks; begun, it opens
    reached_undated := college.year_reached_final(200, s_old);
    INSERT INTO college.semester (session, level, ordinal, length_weeks, starts_on, ends_on) VALUES (s_old, 200, 1, 17, current_date - 200, current_date - 80), (s_old, 200, 2, 17, current_date + 10, current_date + 130);
    reached_ahead := college.year_reached_final(200, s_old);
    UPDATE college.semester SET starts_on = current_date - 5 WHERE session = s_old AND level = 200 AND ordinal = 2;
    reached_now := college.year_reached_final(200, s_old);
    ls := college.level_session(200);                                                                    -- the latest session the College dated for the level
    DELETE FROM college.semester WHERE session = s_old AND level = 200;
    DELETE FROM college.enrolment_semester WHERE enrolment_id IN (ea, eb);
    DELETE FROM college.enrolment WHERE id IN (ea, eb);
    DELETE FROM people.student WHERE id IN (a, b);
    PERFORM pg_temp.assert('Two cohorts at one level each keep their own year: a cohort is the session''s enrolments, the year carries the prospectus''s two semesters, the current year is the open one whatever the University''s session, one year at a time, and results open only once the final semester has begun, and not while the calendar is undated',
        sems = 2 AND n_old = 1 AND n_new = 1 AND cur_level = 200 AND cur_session = s_old AND refused AND NOT reached_undated AND NOT reached_ahead AND reached_now AND ls = s_old,
        format('semesters=%s old_cohort=%s new_cohort=%s current=%s/%s refused=%s undated=%s ahead=%s now=%s level_session=%s', sems, n_old, n_new, cur_level, cur_session, refused, reached_undated, reached_ahead, reached_now, ls));
END $$;

-- ── 17i. the MBBS Coordinator is held by level, by a College lecturer only (V250) ──
DO $$
DECLARE p1 uuid := gen_random_uuid(); p2 uuid := gen_random_uuid(); who uuid := gen_random_uuid(); refused_outsider boolean := false; refused_level boolean := false; lvl int; dept text;
BEGIN
    PERFORM set_config('moaum.actor_id', who::text, true);
    PERFORM set_config('moaum.actor_office', 'registrar', true);
    INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (p1, 'MOAUM/CHK/0001', 'CHECKCOORD', 'Anatomy'), (p2, 'MOAUM/CHK/0002', 'CHECKCOORD', 'Mathematics');
    INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from) VALUES
        (gen_random_uuid(), p1, 'lecturer', 'department', 'ANT', 'check', who, current_date),
        (gen_random_uuid(), p2, 'lecturer', 'department', 'MTC', 'check', who, current_date);
    -- a Mathematics lecturer is refused the coordinatorship; a level outside 200 to 600 is refused
    BEGIN
        INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from)
        VALUES (gen_random_uuid(), p2, 'mbbscoordinator', 'level', '200', 'check', who, current_date);
    EXCEPTION WHEN check_violation THEN refused_outsider := true; END;
    BEGIN
        INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from)
        VALUES (gen_random_uuid(), p1, 'mbbscoordinator', 'level', '100', 'check', who, current_date);
    EXCEPTION WHEN check_violation THEN refused_level := true; END;
    -- the Anatomy lecturer holds 300 Level
    INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from)
    VALUES (gen_random_uuid(), p1, 'mbbscoordinator', 'level', ' 300 ', 'check', who, current_date);
    lvl := iam.coordinator_level(p1);
    dept := iam.college_lecturer_dept(p1);
    DELETE FROM iam.office_assignment WHERE person_id IN (p1, p2);
    DELETE FROM iam.person WHERE id IN (p1, p2);
    PERFORM pg_temp.assert('The MBBS Coordinator is held by level, 200 to 600, by a College lecturer only: an outsider is refused, a level outside the range is refused, and the level held is read back (trimmed)',
        refused_outsider AND refused_level AND lvl = 300 AND dept = 'ANT',
        format('outsider_refused=%s level_refused=%s level=%s dept=%s', refused_outsider, refused_level, lvl, dept));
END $$;

-- ── 17j. an ICT support ticket: a number of the right shape, the lifecycle held, the resolution required, the history written once (V251) ──
DO $$
DECLARE who uuid := gen_random_uuid(); agent uuid := gen_random_uuid(); st uuid := gen_random_uuid(); t uuid; num text;
        refused_resolve boolean := false; refused_skip boolean := false; refused_edit boolean := false; refused_reopen boolean := false;
        st_after text; n_events int; closed_reason text;
BEGIN
    PERFORM set_config('moaum.actor_id', who::text, true);
    PERFORM set_config('moaum.actor_office', 'ict', true);
    INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (agent, 'MOAUM/CHK/0003', 'CHECKAGENT', 'Support');
    INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from)
    VALUES (gen_random_uuid(), agent, 'ictagent', 'platform', NULL, 'check', who, current_date);
    INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
    VALUES (st, 'MOAUM/ADM/99/990990', 'MOAUM/MTC/20/9990', 'CHECKTICKET', 'Student', (SELECT code FROM ref.programme ORDER BY code LIMIT 1), 'UTME', '2020/2021', 100, 300, 'ACTIVE', now());

    -- submitted with the category's required fields: a number of the right shape, the priority the category suggests
    t := helpdesk.submit('STUDENT', st, 'CHECKTICKET, Student', 'MOAUM/MTC/20/9990', 'check@example.edu', '08012345678', NULL, NULL,
                         'PAYMENT', 'A payment that did not register', 'I paid on Monday and the portal still says unpaid.',
                         '{"payment_reference":"RRR-1","payment_date":"2026-09-01","payment_type":"School fees","amount":"45000"}'::jsonb);
    SELECT number INTO num FROM helpdesk.ticket WHERE id = t;

    -- an agent cannot resolve what is not in progress, nor skip from opened to closed without a reason
    PERFORM helpdesk.open_ticket(t, agent);
    BEGIN
        PERFORM helpdesk.resolve(t, agent, 'Fixed', 'The payment was matched to the ledger and the receipt reissued.');
    EXCEPTION WHEN check_violation THEN refused_resolve := true; END;
    BEGIN
        PERFORM helpdesk.transition(t, 'CLOSED', 'AGENT', agent, 'CHECKAGENT, Support', NULL);
    EXCEPTION WHEN check_violation THEN refused_skip := true; END;
    PERFORM helpdesk.transition(t, 'IN_PROGRESS', 'AGENT', agent, 'CHECKAGENT, Support', NULL);
    PERFORM helpdesk.resolve(t, agent, 'Payment matched', 'The payment was matched to the ledger and the receipt reissued to the student.');
    -- the requester is not satisfied: reopened on a reason, and only on a reason
    BEGIN
        PERFORM helpdesk.transition(t, 'REOPENED', 'REQUESTER', st, 'CHECKTICKET, Student', '');
    EXCEPTION WHEN check_violation THEN refused_reopen := true; END;
    PERFORM helpdesk.transition(t, 'REOPENED', 'REQUESTER', st, 'CHECKTICKET, Student', 'The receipt still shows the old amount');
    PERFORM helpdesk.transition(t, 'IN_PROGRESS', 'AGENT', agent, 'CHECKAGENT, Support', NULL);
    PERFORM helpdesk.resolve(t, agent, 'Receipt corrected', 'The receipt was regenerated with the amount as paid, and the student told.');
    PERFORM helpdesk.transition(t, 'CLOSED', 'REQUESTER', st, 'CHECKTICKET, Student', NULL);
    SELECT status, closure_reason INTO st_after, closed_reason FROM helpdesk.ticket WHERE id = t;
    SELECT count(*) INTO n_events FROM helpdesk.ticket_event WHERE ticket_id = t;
    -- the history is written once
    BEGIN
        UPDATE helpdesk.ticket_event SET detail = 'tampered' WHERE ticket_id = t;
    EXCEPTION WHEN check_violation THEN refused_edit := true; END;

    PERFORM set_config('moaum.maintenance', 'on', true);
    DELETE FROM helpdesk.ticket_event WHERE ticket_id = t;
    DELETE FROM helpdesk.ticket_comment WHERE ticket_id = t;
    DELETE FROM helpdesk.ticket WHERE id = t;
    PERFORM set_config('moaum.maintenance', '', true);
    DELETE FROM iam.office_assignment WHERE person_id = agent;
    DELETE FROM iam.person WHERE id = agent;
    DELETE FROM people.student WHERE id = st;

    PERFORM pg_temp.assert('A ticket is numbered TICK-YYYY-NNNNN and walks submitted → opened → in progress → resolved → closed',
        num ~ '^TICK-[0-9]{4}-[0-9]{5}$' AND refused_resolve AND refused_skip AND refused_reopen AND st_after = 'CLOSED' AND closed_reason = 'The requester confirmed the resolution',
        format('number=%s refused_resolve=%s refused_skip=%s refused_reopen=%s status=%s reason=%s', num, refused_resolve, refused_skip, refused_reopen, st_after, closed_reason));
    PERFORM pg_temp.assert('The ticket history holds every act and is written once',
        n_events = 8 AND refused_edit, format('events=%s refused_edit=%s', n_events, refused_edit));
END $$;

-- ── 17k. the nominal roll of non-academic staff is placed in its units; a dry run writes nothing; no sign-in is issued (V253) ──
DO $$
DECLARE who uuid := gen_random_uuid(); dry record; wet record; placed_unit text; placed_dept text; given text; has_login boolean; n_before int; n_after int;
BEGIN
    PERFORM set_config('moaum.actor_id', who::text, true);
    PERFORM set_config('moaum.actor_office', 'registrar', true);
    SELECT count(*) INTO n_before FROM iam.person WHERE staff_number IN ('P990001','P990002','P990003');
    SELECT * INTO dry FROM iam.import_staff('[
        {"pno":"990001","full_names":"CHECK TERFA ROLLONE","sex":"M","date_first_appointment":"04/01/2001","department":"BUR-DIRECTORATE OF FAT-[CASH OFFICE]","present_rank":"ACCOUNTANT","phone":"08000000001","contiss":"12"},
        {"pno":"990002","full_names":"CHECK ADI ROLLTWO","sex":"F","date_first_appointment":"29/04/1993","department":"CHS-DEPT. OF ANATOMY","present_rank":"SECRETARY","phone":"08000000002","contiss":"CONSOLIDATED"},
        {"pno":"990003","full_names":"CHECK NOBODY ROLLTHREE","sex":"M","date_first_appointment":"","department":"UNIT THAT DOES NOT EXIST","present_rank":"CLERK","phone":"","contiss":"7"}]'::jsonb, true);
    SELECT count(*) INTO n_after FROM iam.person WHERE staff_number IN ('P990001','P990002','P990003');
    SELECT * INTO wet FROM iam.import_staff('[
        {"pno":"990001","full_names":"CHECK TERFA ROLLONE","sex":"M","date_first_appointment":"04/01/2001","department":"BUR-DIRECTORATE OF FAT-[CASH OFFICE]","present_rank":"ACCOUNTANT","phone":"08000000001","contiss":"12"},
        {"pno":"990002","full_names":"CHECK ADI ROLLTWO","sex":"F","date_first_appointment":"29/04/1993","department":"CHS-DEPT. OF ANATOMY","present_rank":"SECRETARY","phone":"08000000002","contiss":"CONSOLIDATED"},
        {"pno":"990003","full_names":"CHECK NOBODY ROLLTHREE","sex":"M","date_first_appointment":"","department":"UNIT THAT DOES NOT EXIST","present_rank":"CLERK","phone":"","contiss":"7"}]'::jsonb, false);
    SELECT sr.home_unit, sr.unit_as_given INTO placed_unit, given FROM hrm.staff_record sr JOIN iam.person p ON p.id = sr.person_id WHERE p.staff_number = 'P990001';
    SELECT sr.home_department INTO placed_dept FROM hrm.staff_record sr JOIN iam.person p ON p.id = sr.person_id WHERE p.staff_number = 'P990002';
    SELECT EXISTS (SELECT 1 FROM iam.credential c JOIN iam.person p ON p.id = c.person_id WHERE p.staff_number IN ('P990001','P990002')) INTO has_login;
    DELETE FROM hrm.staff_record WHERE person_id IN (SELECT id FROM iam.person WHERE staff_number IN ('P990001','P990002'));
    DELETE FROM iam.person WHERE staff_number IN ('P990001','P990002');
    PERFORM pg_temp.assert('The nominal roll of non-academic staff is placed in its units, a dry run writes nothing, and no sign-in is issued',
        n_before = 0 AND n_after = 0 AND dry.rows = 3 AND dry.unplaced = 1 AND dry.unplaced_units = 'UNIT THAT DOES NOT EXIST'
        AND wet.created = 2 AND wet.unplaced = 1 AND placed_unit = 'BUR_FAT_CASH_OFFICE' AND placed_dept = 'ANT' AND given = 'BUR-DIRECTORATE OF FAT-[CASH OFFICE]' AND NOT has_login,
        format('dry=%s/%s/%s wet=%s/%s unit=%s dept=%s login=%s after_dry=%s', dry.rows, dry.unplaced, dry.unplaced_units, wet.created, wet.unplaced, placed_unit, placed_dept, has_login, n_after));
END $$;

-- ── 17l. an external examiner's assessment: scored within the maxima, the total computed, submitted once, reopened on a reason, the history written once (V254) ──
DO $$
DECLARE who uuid := gen_random_uuid(); px uuid := gen_random_uuid(); ex uuid; st uuid := gen_random_uuid(); pr uuid; asg uuid; ass uuid; rub uuid; c1 uuid; c2 uuid;
        refused_over boolean := false; refused_early boolean := false; refused_edit boolean := false; refused_reopen boolean := false; t_total numeric; t_pct numeric; t_grade text; st_after text; n_events int;
BEGIN
    PERFORM set_config('moaum.actor_id', who::text, true);
    PERFORM set_config('moaum.actor_office', 'academic', true);
    INSERT INTO iam.person (id, surname, given_names, email) VALUES (px, 'CHECKEXAMINER', 'External', 'check.examiner@example.edu');
    INSERT INTO extexam.examiner (person_id, email, institution, status, activated_at) VALUES (px, 'check.examiner@example.edu', 'Check University', 'ACTIVE', now()) RETURNING id INTO ex;
    INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
    VALUES (st, NULL, 'MOAUM/MTC/20/9991', 'CHECKPROJECT', 'Student', (SELECT code FROM ref.programme ORDER BY code LIMIT 1), 'UTME', '2020/2021', 100, 400, 'ACTIVE', now());
    INSERT INTO extexam.project (student_id, kind, session, title) VALUES (st, 'UNDERGRADUATE', '2090/2091', 'A check project') RETURNING id INTO pr;
    SELECT id INTO rub FROM extexam.rubric WHERE code = 'UG_DEFAULT';
    INSERT INTO extexam.assignment (project_id, examiner_id, rubric_id, deadline, assigned_by) VALUES (pr, ex, rub, current_date + 14, who) RETURNING id INTO asg;
    PERFORM extexam.record('PROJECT_ASSIGNED', who, 'Check', ex, pr, asg, NULL, (current_date + 14)::text, NULL);
    INSERT INTO extexam.assessment (assignment_id) VALUES (asg) RETURNING id INTO ass;
    -- a score over the maximum is refused; submission before every line is scored is refused
    SELECT id INTO c1 FROM extexam.criterion WHERE rubric_id = rub ORDER BY ordinal LIMIT 1;
    BEGIN PERFORM extexam.score(ass, c1, 999, NULL); EXCEPTION WHEN check_violation THEN refused_over := true; END;
    BEGIN PERFORM extexam.submit(ass, px, 'CHECKEXAMINER, External'); EXCEPTION WHEN check_violation THEN refused_early := true; END;
    -- every line scored at its maximum: the total is the form's total, 100 per cent, the top grade in force
    FOR c2 IN SELECT id FROM extexam.criterion WHERE rubric_id = rub AND active LOOP
        PERFORM extexam.score(ass, c2, (SELECT max_score FROM extexam.criterion WHERE id = c2), 'fine');
    END LOOP;
    UPDATE extexam.assessment SET general_comments = 'A thorough, well-argued and well-built piece of work.', final_recommendation = 'PASS' WHERE id = ass;
    PERFORM extexam.submit(ass, px, 'CHECKEXAMINER, External');
    SELECT total, percentage, grade INTO t_total, t_pct, t_grade FROM extexam.assessment WHERE id = ass;
    -- submitted means read-only; reopening needs a reason; reopened means scorable again
    BEGIN PERFORM extexam.score(ass, c1, 1, NULL); EXCEPTION WHEN check_violation THEN refused_edit := true; END;
    BEGIN PERFORM extexam.reopen(ass, who, 'Check', ''); EXCEPTION WHEN check_violation THEN refused_reopen := true; END;
    PERFORM extexam.reopen(ass, who, 'Check', 'The defence marks want a second look');
    SELECT status INTO st_after FROM extexam.assignment WHERE id = asg;
    SELECT count(*) INTO n_events FROM extexam.event WHERE assignment_id = asg;

    PERFORM set_config('moaum.maintenance', 'on', true);
    DELETE FROM extexam.event WHERE assignment_id = asg OR examiner_id = ex OR project_id = pr;
    PERFORM set_config('moaum.maintenance', '', true);
    DELETE FROM extexam.assessment_score WHERE assessment_id = ass;
    DELETE FROM extexam.assessment WHERE id = ass;
    DELETE FROM extexam.assignment WHERE id = asg;
    DELETE FROM extexam.project WHERE id = pr;
    DELETE FROM extexam.examiner WHERE id = ex;
    DELETE FROM people.student WHERE id = st;
    DELETE FROM iam.person WHERE id = px;

    PERFORM pg_temp.assert('An external assessment is scored within its maxima, totalled by the form, submitted once and reopened only on a reason',
        refused_over AND refused_early AND t_total = (SELECT sum(max_score) FROM extexam.criterion WHERE rubric_id = rub AND active) AND t_pct = 100 AND t_grade = 'A'
        AND refused_edit AND refused_reopen AND st_after = 'REOPENED' AND n_events = 3,
        format('over=%s early=%s total=%s pct=%s grade=%s edit=%s reopen=%s status=%s events=%s', refused_over, refused_early, t_total, t_pct, t_grade, refused_edit, refused_reopen, st_after, n_events));
END $$;

-- ── V292. the clean slate reaches every table that hangs on what it clears ──
-- Computed from the catalogue, not from data: a table added later that refers to
-- anything platform.reset_operational_data deletes, without ON DELETE CASCADE or
-- SET NULL, and that the reset does not clear itself, would make the go-live
-- reset fail with a foreign-key violation. It fails here the day it is added.
DO $$
DECLARE n int; lst text;
BEGIN
    WITH RECURSIVE cleared AS (
        SELECT DISTINCT m[1]::regclass AS t
          FROM pg_proc p, regexp_matches(p.prosrc, 'DELETE FROM ([a-z_]+\.[a-z_]+)', 'g') AS m
         WHERE p.oid = 'platform.reset_operational_data(text, text)'::regprocedure),
    blocking AS (
        SELECT c.conrelid::regclass AS t, c.confrelid::regclass AS parent
          FROM pg_constraint c
         WHERE c.contype = 'f' AND c.confdeltype IN ('a', 'r') AND c.conrelid <> c.confrelid
           AND c.confrelid IN (SELECT t FROM cleared) AND c.conrelid NOT IN (SELECT t FROM cleared)
        UNION
        SELECT c.conrelid::regclass, c.confrelid::regclass
          FROM pg_constraint c JOIN blocking b ON c.confrelid = b.t
         WHERE c.contype = 'f' AND c.confdeltype IN ('a', 'r') AND c.conrelid <> c.confrelid AND c.conrelid NOT IN (SELECT t FROM cleared))
    SELECT count(DISTINCT t), string_agg(DISTINCT t::text || ' → ' || parent::text, ', ') INTO n, lst FROM blocking;
    PERFORM pg_temp.assert('The data reset clears every table that hangs on what it clears, so it cannot fail on a foreign key',
                           n = 0, coalesce(lst, 'none left behind'));
END $$;

-- ── V294. the biodata upload: one sealed hash an upload, and the same rows again write nothing ──
-- A migrated student's sign-in is opened sealed: a cost-12 hash of a random secret nobody holds (the
-- first sign-in is the student's own number while must_change holds). Made once a row, that hash was
-- nine tenths of the upload's time; it is made once an upload. A re-upload of unchanged rows writes
-- nothing, so it adds nothing to the audit chain. The block undoes its own writes.
DO $$
DECLARE v_rows jsonb; c1 int; c2 int; a int; h int; ok12 boolean; t0 timestamptz; w int;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
        PERFORM set_config('moaum.actor_office', 'ict', true);
        SELECT jsonb_agg(jsonb_build_object('matric', 'MOAUM/CSC/19/' || lpad((9900 + i)::text, 4, '0'),
                   'surname', 'Sealcheck', 'otherNames', 'Row ' || i, 'level', '300',
                   'programme', (SELECT code FROM ref.programme WHERE NOT archived ORDER BY code LIMIT 1),
                   'phone', '0803000' || lpad(i::text, 4, '0'), 'nationality', 'Nigeria', 'lga', 'Makurdi'))
          INTO v_rows FROM generate_series(1, 5) i;
        SELECT created INTO c1 FROM people.import_biography(v_rows);
        SELECT count(*), count(DISTINCT x.password_hash), bool_and(x.password_hash LIKE '$2%$12$%' AND x.must_change)
          INTO a, h, ok12
          FROM iam.student_account x JOIN people.student s ON s.id = x.student_id
         WHERE s.matric_no LIKE 'MOAUM/CSC/19/99%';
        t0 := clock_timestamp();
        SELECT created INTO c2 FROM people.import_biography(v_rows);
        SELECT count(*) INTO w FROM audit.entries
         WHERE occurred_at >= t0
           AND subject_type IN ('people.student', 'people.student_contact', 'people.biodata', 'clearance.item');
        RAISE EXCEPTION 'the V294 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('The biodata upload seals its sign-ins with one cost-12 hash; unchanged rows again write nothing',
        coalesce(c1 = 5 AND c2 = 0 AND a = 5 AND h = 1 AND ok12 AND w = 0, false),
        format('created=%s again=%s accounts=%s hashes=%s cost12=%s written-again=%s', c1, c2, a, h, ok12, w));
END $$;

-- ── V295. admission status checking follows the application, the window and the fee — never the decision ──
-- Every applicant with a valid Post-UTME application (fee confirmed, submitted) may pay the admission checking fee and check
-- their status while the Director of ICT has checking open — not yet decided, not admitted or admitted alike; nobody else may,
-- and nobody while it is closed (it is closed until first opened). The fee is paid once; the status comes from the decision.
-- Nothing about an offer can be learned or acted on before it is checked: the acceptance fee, the undertaking and the decline
-- give one answer whatever the decision; an admission already read continues after checking closes.
DO $$
DECLARE pend uuid; notad uuid; incomp uuid; offer uuid; ref1 text; ref2 text; ref3 text;
        r_closed text := 'ok'; r_incomp text := 'ok'; r_unpaid text := 'ok'; r_again text := 'ok'; r_accept text := 'ok';
        r_und text := 'ok'; r_dec text := 'ok'; r_acc_unread text := 'ok'; und text; st_after text; acc_after text;
        st_closed text; st_open text; st_pend text; st_notad text; st_offer text; st_later text; tr_hidden text; n_refs bigint; n_checks bigint;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on, state) VALUES (gen_random_uuid(), '9984/9985', date '9984-09-01', date '9985-08-31', 'DRAFT') ON CONFLICT DO NOTHING;
        CREATE TEMP TABLE v295_apps (tag text, app uuid) ON COMMIT DROP;
        DECLARE t record; cand uuid; acct uuid; app uuid; n int := 0;
        BEGIN
            FOR t IN SELECT * FROM (VALUES ('pending', true, NULL::text, false), ('notadmitted', true, 'NOT_OFFERED', true),
                                           ('incomplete', false, NULL, false), ('offered', true, 'OFFERED', true)) v(tag, submitted, decision, released) LOOP
                n := n + 1; cand := gen_random_uuid(); acct := gen_random_uuid(); app := gen_random_uuid();
                INSERT INTO admissions.candidate (id, session, jamb_reg_no, surname, other_names, programme, entry_mode, entry_level, offer_state)
                VALUES (cand, '9984/9985', '99840000000' || n || 'CK', 'V295-' || t.tag, 'Check', (SELECT name FROM ref.programme WHERE NOT archived ORDER BY code LIMIT 1), 'UTME', 100, 'PROPOSED');
                INSERT INTO admissions.applicant_account (id, session, candidate_id, jamb_key, email, phone, password_hash)
                VALUES (acct, '9984/9985', cand, '99840000000' || n || 'CK', 'v295.' || t.tag || '@example.com', '08030000000', crypt('x', gen_salt('bf', 12)));
                INSERT INTO admissions.application (id, account_id, candidate_id, session, application_no, fee_confirmed_at, submitted_at, decision, decided_at, decision_released_at)
                VALUES (app, acct, cand, '9984/9985', 'APP/84/99990' || n, now(), CASE WHEN t.submitted THEN now() END, t.decision, CASE WHEN t.decision IS NOT NULL THEN now() END, CASE WHEN t.released THEN now() END);
                INSERT INTO v295_apps VALUES (t.tag, app);
            END LOOP;
        END;
        SELECT app INTO pend FROM v295_apps WHERE tag = 'pending';
        SELECT app INTO notad FROM v295_apps WHERE tag = 'notadmitted';
        SELECT app INTO incomp FROM v295_apps WHERE tag = 'incomplete';
        SELECT app INTO offer FROM v295_apps WHERE tag = 'offered';
        -- closed until the Director opens it
        SELECT status INTO st_closed FROM admissions.admission_status(notad);
        BEGIN PERFORM admissions.new_fee_reference(pend, 'CHECKING'); EXCEPTION WHEN check_violation THEN r_closed := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_office', 'ict', true);
        PERFORM policy.window_act('ADMISSION_STATUS_CHECKING', '9984/9985', NULL, 'OPEN', NULL, NULL, NULL, false, 'check', gen_random_uuid(), 'ict');
        PERFORM set_config('moaum.actor_office', 'applicant', true);
        SELECT status INTO st_open FROM admissions.admission_status(notad);
        SELECT string_agg(x->>'state', ',') INTO tr_hidden FROM jsonb_array_elements(admissions.admission_tracker(notad)) x WHERE x->>'key' = 'ADMISSION';
        BEGIN PERFORM admissions.new_fee_reference(incomp, 'CHECKING'); EXCEPTION WHEN check_violation THEN r_incomp := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM admissions.admission_status_checked(pend); EXCEPTION WHEN check_violation THEN r_unpaid := split_part(SQLERRM, ':', 1); END;
        -- an offer not yet read: accepting, declining or paying for it answers as for any applicant, and opens nothing
        BEGIN PERFORM admissions.sign_undertaking(offer); EXCEPTION WHEN check_violation THEN r_und := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM admissions.decline_offer(offer); EXCEPTION WHEN check_violation THEN r_dec := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM admissions.new_fee_reference(offer, 'ACCEPTANCE'); EXCEPTION WHEN check_violation THEN r_acc_unread := split_part(SQLERRM, ':', 1); END;
        -- open: the undecided, the not admitted and the admitted pay, once; a reference still open is the one returned
        ref1 := admissions.new_fee_reference(pend, 'CHECKING');
        ref2 := admissions.new_fee_reference(notad, 'CHECKING');
        ref3 := admissions.new_fee_reference(offer, 'CHECKING');
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM admissions.confirm_fee(ref1, 'Card', 'check');
        PERFORM admissions.confirm_fee(ref2, 'Card', 'check');
        PERFORM admissions.confirm_fee(ref3, 'Card', 'check');
        PERFORM set_config('moaum.actor_office', 'applicant', true);
        PERFORM admissions.admission_status_checked(pend);
        PERFORM admissions.admission_status_checked(notad);
        PERFORM admissions.admission_status_checked(offer);
        SELECT status INTO st_pend FROM admissions.admission_status(pend);
        SELECT status INTO st_notad FROM admissions.admission_status(notad);
        SELECT status INTO st_offer FROM admissions.admission_status(offer);
        BEGIN PERFORM admissions.new_fee_reference(pend, 'CHECKING'); EXCEPTION WHEN check_violation THEN r_again := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM admissions.new_fee_reference(notad, 'ACCEPTANCE'); EXCEPTION WHEN check_violation THEN r_accept := split_part(SQLERRM, ':', 1); END;
        -- the offer read: the undertaking follows; checking closes and the admission under way continues
        und := admissions.sign_undertaking(offer);
        PERFORM set_config('moaum.actor_office', 'ict', true);
        PERFORM policy.window_act('ADMISSION_STATUS_CHECKING', '9984/9985', NULL, 'CLOSE', NULL, NULL, NULL, false, 'check closed', gen_random_uuid(), 'ict');
        PERFORM set_config('moaum.actor_office', 'applicant', true);
        SELECT status INTO st_after FROM admissions.admission_status(offer);
        acc_after := left(admissions.new_fee_reference(offer, 'ACCEPTANCE'), 10);
        -- pending today, admitted later: checked again when checking reopens, without paying again
        PERFORM set_config('moaum.actor_office', 'ict', true);
        PERFORM policy.window_act('ADMISSION_STATUS_CHECKING', '9984/9985', NULL, 'REOPEN', NULL, NULL, NULL, false, 'check reopened', gen_random_uuid(), 'ict');
        PERFORM set_config('moaum.actor_office', 'academic', true);
        UPDATE admissions.application SET decision = 'OFFERED', decided_at = now(), decision_released_at = now() WHERE id = pend;
        PERFORM set_config('moaum.actor_office', 'applicant', true);
        PERFORM admissions.admission_status_checked(pend);
        SELECT status INTO st_later FROM admissions.admission_status(pend);
        SELECT count(*) INTO n_refs FROM admissions.fee_reference WHERE application_id = pend AND kind = 'CHECKING';
        SELECT count(*) INTO n_checks FROM admissions.status_check WHERE application_id = pend;
        RAISE EXCEPTION 'the V295 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('Admission status checking follows the application, the window and the fee, never the decision',
        coalesce(st_closed = 'CHECKING_CLOSED' AND r_closed = 'ADMISSION_CHECKING_CLOSED' AND st_open = 'CHECKING_FEE_PENDING' AND tr_hidden = 'now'
                 AND r_incomp = 'ADMISSION_CHECKING_NOT_ELIGIBLE' AND r_unpaid = 'ADMISSION_CHECKING_FEE_UNPAID' AND ref1 <> ref2
                 AND r_und = 'ADMISSION_STATUS_NOT_CHECKED' AND r_dec = 'ADMISSION_STATUS_NOT_CHECKED' AND r_acc_unread = 'ADMISSION_STATUS_NOT_CHECKED'
                 AND st_pend = 'PENDING' AND st_notad = 'NOT_ADMITTED' AND st_offer = 'ADMITTED' AND r_again = 'ADMISSION_CHECKING_PAID'
                 AND r_accept = 'ADMISSION_STATUS_NOT_CHECKED' AND und = 'undertaking signed' AND st_after = 'ACCEPTANCE_PENDING' AND acc_after = 'MOAUM-ACC-'
                 AND st_later = 'ADMITTED' AND n_refs = 1 AND n_checks = 2, false),
        format('closed=%s/%s open=%s tracker=%s incomplete=%s unpaid=%s unread=%s/%s/%s pending=%s notadmitted=%s offered=%s again=%s acceptance=%s undertaking=%s after-close=%s/%s later=%s refs=%s checks=%s',
               st_closed, r_closed, st_open, tr_hidden, r_incomp, r_unpaid, r_und, r_dec, r_acc_unread, st_pend, st_notad, st_offer, r_again, r_accept,
               und, st_after, acc_after, st_later, n_refs, n_checks));
END $$;

-- ── V296. the old-portal applicants come with their email and phone ──
-- A contact cell is read as people write it; a new applicant is imported with the file's email and phone, an applicant already
-- migrated takes them (the office's contacts replace the placeholders and what an earlier file gave), an account the applicant
-- opened keeps theirs, an email already on another account is not taken, and every row says what happened and why.
DO $$
DECLARE r1 record; r2 record; r3 record; r4 record; r5 record; r6 record; r7 record; r8 record; w1 text; w2 text; n_ev bigint; lst record;
        reads boolean;
BEGIN
    reads := admissions.first_email('Ada Obi <Ada.Obi@Gmail.com>, other@x.com') = 'ada.obi@gmail.com'
         AND admissions.first_email('x@migrate.moau.local') IS NULL AND admissions.first_email('not an email') IS NULL
         AND admissions.first_mobile('+234 803 123 4567') = '08031234567' AND admissions.first_mobile('8031234567') = '08031234567'
         AND admissions.first_mobile('08031234567 / 07061234567') = '08031234567' AND admissions.first_mobile('01234567890') IS NULL
         AND admissions.first_mobile('00000000000') IS NULL;
    BEGIN
        PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        DECLARE b uuid := gen_random_uuid(); i int;
        BEGIN
            INSERT INTO admissions.caps_batch (id, session, source, filename, file_sha256, rows_read, list_kind, downloaded_on, uploaded_by, uploaded_office, committed_at)
            VALUES (b, '9982/9983', 'CAPS_DOWNLOAD', 'check.xlsx', decode(md5(b::text), 'hex'), 4, 'UTME', current_date, gen_random_uuid(), 'academic', now());
            FOR i IN 1..4 LOOP
                INSERT INTO admissions.caps_row (id, batch_id, session, jamb_reg_no, raw, surname, other_names, jamb_code, aggregate, entry_mode, sex, state_of_origin, lga)
                VALUES (gen_random_uuid(), b, '9982/9983', '998200000' || i || 'CK', '{}'::jsonb, 'V296-' || i, 'Check', 'C00023', 220, 'UTME', 'F', 'Benue', 'Makurdi');
            END LOOP;
        END;
        SELECT * INTO r1 FROM admissions.import_applicant_row('9982/9983', '9982000001CK', 'One.V296@Mail.com', '+234 803 123 4567');   -- new, with contacts
        SELECT * INTO r2 FROM admissions.import_applicant_row('9982/9983', '9982000002ck', 'not-an-email', '');                        -- new, on placeholders, told why
        SELECT * INTO r3 FROM admissions.import_applicant_row('9982/9983', '9982000003CK', 'one.v296@mail.com', '0706 555 1234');      -- the email is another's
        SELECT * INTO r4 FROM admissions.import_applicant_row('9982/9983', '9982000002CK', 'two.v296@mail.com', '8061112222');         -- already migrated: filled
        SELECT * INTO r5 FROM admissions.import_applicant_row('9982/9983', '9982000001CK', 'one.new.v296@mail.com', '');               -- the office's newer email
        SELECT * INTO r6 FROM admissions.import_applicant_row('9982/9983', '9982000001CK', 'ONE.NEW.V296@mail.com', '08031234567');    -- nothing to change
        PERFORM set_config('moaum.actor_office', 'applicant', true);
        PERFORM admissions.register_applicant('9982/9983', '9982000004CK', 'own.v296@choice.com', '08099998888', crypt('x', gen_salt('bf', 12)));
        PERFORM set_config('moaum.actor_office', 'academic', true);
        SELECT * INTO r7 FROM admissions.import_applicant_row('9982/9983', '9982000004CK', 'office.v296@file.com', '08011112222');     -- the applicant's own are kept
        SELECT * INTO r8 FROM admissions.import_applicant_row('9982/9983', '9982000099CK', 'x.v296@y.com', '08031234567');             -- not on CAPS
        w1 := admissions.import_applicant('9982/9983', '9982000003CK', 'three.v296@mail.com', '');                                      -- the text answer of old
        w2 := admissions.import_applicant('9982/9983', 'NOT A NUMBER', '', '');
        SELECT count(*) INTO n_ev FROM admissions.applicant_event WHERE identifier LIKE '998200000%' AND outcome LIKE 'CONTACTS_UPDATED%';
        SELECT count(*) AS migrated, count(*) FILTER (WHERE has_email) AS e, count(*) FILTER (WHERE has_phone) AS p INTO lst FROM admissions.migrated_contacts('9982/9983');
        RAISE EXCEPTION 'the V296 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('The old-portal applicants come with their email and phone, and those already migrated take them',
        coalesce(reads
            AND r1.o_outcome = 'IMPORTED' AND r1.o_email = 'one.v296@mail.com' AND r1.o_phone = '08031234567' AND r1.o_email_note IS NULL AND r1.o_phone_note IS NULL
            AND r2.o_outcome = 'IMPORTED' AND r2.o_email = '9982000002ck@migrate.moau.local' AND r2.o_phone = '00000000000'
            AND r2.o_email_note LIKE 'not a usable email address%' AND r2.o_phone_note = 'no phone number in the file'
            AND r3.o_outcome = 'IMPORTED' AND r3.o_email LIKE '%@migrate.moau.local' AND r3.o_email_note LIKE 'already on another applicant%' AND r3.o_phone = '07065551234'
            AND r4.o_outcome = 'UPDATED' AND r4.o_email = 'two.v296@mail.com' AND r4.o_phone = '08061112222' AND r4.o_detail = 'email and phone updated'
            AND r5.o_outcome = 'UPDATED' AND r5.o_email = 'one.new.v296@mail.com' AND r5.o_phone = '08031234567' AND r5.o_phone_note IS NULL
            AND r6.o_outcome = 'EXISTS' AND r6.o_email_note IS NULL AND r6.o_phone_note IS NULL
            AND r7.o_outcome = 'EXISTS' AND r7.o_email = 'own.v296@choice.com' AND r7.o_email_note LIKE 'kept the email the applicant chose%' AND r7.o_phone_note LIKE 'kept the phone%'
            AND r8.o_outcome = 'SKIPPED' AND r8.o_detail = 'not on the JAMB CAPS list'
            AND w1 = 'exists' AND w2 = 'skip: bad JAMB number' AND n_ev = 3
            AND lst.migrated = 3 AND lst.e = 3 AND lst.p = 3, false),
        format('reads=%s r1=%s/%s/%s r2=%s/%s/%s r3=%s/%s r4=%s/%s r5=%s/%s r6=%s r7=%s/%s r8=%s/%s wrapper=%s/%s events=%s listed=%s/%s/%s',
               reads, r1.o_outcome, r1.o_email, r1.o_phone, r2.o_outcome, r2.o_email_note, r2.o_phone_note, r3.o_outcome, r3.o_email_note,
               r4.o_outcome, r4.o_detail, r5.o_outcome, r5.o_email, r6.o_outcome, r7.o_outcome, r7.o_email_note, r8.o_outcome, r8.o_detail,
               w1, w2, n_ev, lst.migrated, lst.e, lst.p));
END $$;

-- ── V297. an admission found in error is corrected after the decision, even after school fees, and every change is listed ──
-- The ordinary change is shut once the decision is released; a correction takes over up to matriculation (after it, a transfer).
-- It is recommended with the error described, decided by the Registrar's office and not by its recommender, keeps the fees paid
-- against the new programme (the position before and after on the record), returns the courses registered on the old one and
-- reissues the letter; the register lists the applicant with the programme applied for and the programme held now. The fee
-- schedule read for a programme named agrees with the fee schedule read for the programme held.
DO $$
DECLARE academic uuid := gen_random_uuid(); registrar uuid := gen_random_uuid();
        cand uuid := gen_random_uuid(); acct uuid := gen_random_uuid(); app uuid := gen_random_uuid(); st uuid; reg uuid;
        e_cand uuid := gen_random_uuid(); e_acct uuid := gen_random_uuid(); e_app uuid := gen_random_uuid();
        m_cand uuid := gen_random_uuid(); m_acct uuid := gen_random_uuid(); m_app uuid := gen_random_uuid(); m_st uuid;
        r_ordinary text := 'ok'; r_note text := 'ok'; r_elig text := 'ok'; r_approver text := 'ok'; r_same text := 'ok'; r_early text := 'ok'; r_mat text := 'ok';
        req uuid; pv jsonb; rt record; decided text; q record; reg_row record; st_row record; pos record; reg_line record; charges_same boolean;
        e_route text; m_route text; n_letters bigint; stage_after text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', academic::text, true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on, state) VALUES (gen_random_uuid(), '9986/9987', date '9986-09-01', date '9987-08-31', 'DRAFT') ON CONFLICT DO NOTHING;
        INSERT INTO finance.fee_schedule (session, item, amount, level, programme_code, ord)
        VALUES ('9986/9987', 'Tuition (V297 check)', 150000, 100, 'C00023', 1), ('9986/9987', 'Tuition (V297 check)', 120000, 100, 'C00019', 1);
        INSERT INTO admissions.candidate (id, session, jamb_reg_no, surname, other_names, programme, entry_mode, entry_level, offer_state)
        VALUES (cand, '9986/9987', '9986000001CK', 'V297-Corrected', 'Check', (SELECT name FROM ref.programme WHERE code = 'C00023'), 'UTME', 100, 'PROPOSED'),
               (e_cand, '9986/9987', '9986000002CK', 'V297-Undecided', 'Check', (SELECT name FROM ref.programme WHERE code = 'C00023'), 'UTME', 100, 'PROPOSED'),
               (m_cand, '9986/9987', '9986000003CK', 'V297-Matriculated', 'Check', (SELECT name FROM ref.programme WHERE code = 'C00023'), 'UTME', 100, 'PROPOSED');
        DECLARE b uuid := gen_random_uuid();
        BEGIN
            INSERT INTO admissions.caps_batch (id, session, source, filename, file_sha256, rows_read, list_kind, downloaded_on, uploaded_by, uploaded_office, committed_at)
            VALUES (b, '9986/9987', 'CAPS_DOWNLOAD', 'v297.xlsx', decode(md5(b::text), 'hex'), 2, 'UTME', current_date, academic, 'academic', now());
            INSERT INTO admissions.caps_row (id, batch_id, session, jamb_reg_no, raw, surname, other_names, jamb_code, aggregate, entry_mode, sex, state_of_origin, lga)
            VALUES (gen_random_uuid(), b, '9986/9987', '9986000001CK', '{}'::jsonb, 'V297-Corrected', 'Check', 'C00023', 220, 'UTME', 'F', 'Benue', 'Makurdi'),
                   (gen_random_uuid(), b, '9986/9987', '9986000003CK', '{}'::jsonb, 'V297-Matriculated', 'Check', 'C00023', 220, 'UTME', 'M', 'Benue', 'Gboko');
            UPDATE admissions.candidate c SET offer_state = 'ADMITTED', admitted_from = r.id FROM admissions.caps_row r
             WHERE r.batch_id = b AND r.jamb_reg_no = c.jamb_reg_no AND c.id IN (cand, m_cand);
        END;
        INSERT INTO admissions.applicant_account (id, session, candidate_id, jamb_key, email, phone, password_hash)
        VALUES (acct, '9986/9987', cand, '9986000001CK', 'v297.one@example.com', '08030000000', crypt('x', gen_salt('bf', 12))),
               (e_acct, '9986/9987', e_cand, '9986000002CK', 'v297.two@example.com', '08030000000', crypt('x', gen_salt('bf', 12))),
               (m_acct, '9986/9987', m_cand, '9986000003CK', 'v297.three@example.com', '08030000000', crypt('x', gen_salt('bf', 12)));
        INSERT INTO admissions.application (id, account_id, candidate_id, session, application_no, fee_confirmed_at, submitted_at, decision, decided_at, decision_released_at, accepted_at)
        VALUES (app, acct, cand, '9986/9987', 'APP/86/000001', now(), now(), 'OFFERED', now(), now(), now()),
               (e_app, e_acct, e_cand, '9986/9987', 'APP/86/000002', now(), now(), NULL, NULL, NULL, NULL),
               (m_app, m_acct, m_cand, '9986/9987', 'APP/86/000003', now(), now(), 'OFFERED', now(), now(), now());
        -- offered, accepted, on the register, school fees paid (150,000 on Computer Science), courses registered and approved, the letter issued
        st := people.intake_one(cand);
        m_st := people.intake_one(m_cand);
        UPDATE people.student SET matric_no = 'MOAUM/MTC/86/9701', matriculated_at = now() WHERE id = m_st;
        INSERT INTO finance.payment_reference (student_id, session, reference, purpose, amount, expires_at, confirmed_at, confirmed_by, channel, receipt_no)
        VALUES (st, '9986/9987', 'MOAUM-FEE-V297-0001', 'School fees 9986/9987', 150000, now() + interval '1 day', now(), academic, 'Card', 'RCPT-V297-0001');
        INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, approved_at) VALUES (gen_random_uuid(), st, '9986/9987', 1, 100, 'APPROVED', now()) RETURNING id INTO reg;
        PERFORM admissions.issue_admission_letter(app);
        SELECT * INTO rt FROM admissions.programme_change_route(app);
        SELECT route INTO e_route FROM admissions.programme_change_route(e_app);
        SELECT route INTO m_route FROM admissions.programme_change_route(m_app);
        charges_same := (SELECT coalesce(sum(amount), 0) FROM finance.charges(st, '9986/9987')) = 150000
                    AND finance.due_as(st, '9986/9987', NULL) = 150000 AND finance.due_as(st, '9986/9987', 'C00019') = 120000;
        pv := admissions.correction_preview(app, 'C00019');
        BEGIN PERFORM admissions.recommend_programme_change(app, 'C00019', 'ADMISSION_POLICY', NULL, academic, 'academic', false, NULL); EXCEPTION WHEN check_violation THEN r_ordinary := left(SQLERRM, 26); END;
        BEGIN PERFORM admissions.recommend_admission_correction(app, 'C00019', 'ADMISSION_ERROR', '  ', academic, 'academic', false, NULL); EXCEPTION WHEN check_violation THEN r_note := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM admissions.recommend_admission_correction(app, 'C00019', 'ADMISSION_ERROR', 'Admitted to Computer Science on a mis-keyed UTME score', academic, 'academic', false, NULL); EXCEPTION WHEN check_violation THEN r_elig := left(SQLERRM, 29); END;
        BEGIN PERFORM admissions.recommend_admission_correction(e_app, 'C00019', 'ADMISSION_ERROR', 'x', academic, 'academic', true, 'x'); EXCEPTION WHEN check_violation THEN r_early := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM admissions.recommend_admission_correction(m_app, 'C00019', 'ADMISSION_ERROR', 'x', academic, 'academic', true, 'x'); EXCEPTION WHEN check_violation THEN r_mat := split_part(SQLERRM, ':', 1); END;
        req := admissions.recommend_admission_correction(app, 'C00019', 'ADMISSION_ERROR', 'Admitted to Computer Science on a mis-keyed UTME score', academic, 'academic', true, 'Registrar''s directive on the audit of the list');
        BEGIN PERFORM admissions.decide_programme_change(req, 'APPROVE', NULL, academic); EXCEPTION WHEN check_violation THEN r_approver := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_office', 'registrar', true);
        BEGIN PERFORM admissions.decide_programme_change(req, 'APPROVE', NULL, academic); EXCEPTION WHEN check_violation THEN r_same := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_id', registrar::text, true);
        decided := admissions.decide_programme_change(req, 'APPROVE', 'Corrected on the audit of the admission list', registrar);
        SELECT * INTO q FROM admissions.programme_change_request WHERE id = req;
        SELECT * INTO reg_row FROM registration.course_registration WHERE id = reg;
        SELECT s.programme_code, c.programme INTO st_row FROM people.student s JOIN admissions.candidate c ON c.id = s.candidate_id WHERE s.id = st;
        SELECT * INTO pos FROM finance.position(st, '9986/9987');
        SELECT * INTO reg_line FROM admissions.programme_change_register('9986/9987') x WHERE x.application_id = app;
        SELECT count(*) INTO n_letters FROM credentials.issued WHERE application_id = app AND kind = 'ADMISSION_LETTER';
        stage_after := admissions.admission_stage(app);
        RAISE EXCEPTION 'the V297 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('An admission found in error is corrected after school fees, by the Registrar, and listed',
        coalesce(rt.route = 'CORRECTION' AND rt.stage = 'COURSES_REGISTERED' AND e_route = 'CHANGE' AND m_route = 'TRANSFER' AND charges_same
                 AND (pv #>> '{fees,dueAfter}')::numeric = 120000 AND (pv #>> '{fees,excessAfter}')::numeric = 30000 AND pv #>> '{target,result}' = 'UNVERIFIED'
                 AND r_ordinary = 'the Board''s decision on th' AND r_note = 'CORRECTION_NOTE_REQUIRED' AND r_elig = 'the candidate is not eligible'
                 AND r_early = 'CORRECTION_NOT_NEEDED' AND r_mat = 'CORRECTION_TRANSFER' AND r_approver = 'CORRECTION_APPROVER' AND r_same = 'CORRECTION_SAME_OFFICER'
                 AND decided = 'APPROVED' AND q.kind = 'CORRECTION' AND q.admission_stage = 'COURSES_REGISTERED' AND q.decided_office = 'registrar'
                 AND q.fees_paid = 150000 AND q.fees_due_before = 150000 AND q.fees_due_after = 120000 AND q.registrations_returned = 1 AND q.letter_reissued
                 AND reg_row.status = 'RETURNED' AND reg_row.approved_at IS NULL AND reg_row.returned_comment LIKE 'Your admission was corrected from%'
                 AND st_row.programme_code = 'C00019' AND st_row.programme = (SELECT name FROM ref.programme WHERE code = 'C00019')
                 AND pos.due = 120000 AND pos.paid = 150000 AND pos.balance = 0 AND n_letters = 2 AND stage_after = 'SCHOOL_FEES_PAID'
                 AND reg_line.applied_code = 'C00023' AND reg_line.current_code = 'C00019' AND reg_line.moved AND reg_line.stage = 'CORRECTION'
                 AND reg_line.reason = 'Error discovered in the admission' AND reg_line.fees_due_after = 120000 AND reg_line.history LIKE '%"kind": "CORRECTION"%', false),
        format('route=%s/%s early=%s matriculated=%s charges=%s preview=%s/%s/%s refusals=%s|%s|%s|%s|%s|%s|%s decided=%s request=%s/%s/%s fees=%s/%s/%s regs=%s letter=%s registration=%s/%s student=%s position=%s/%s/%s letters=%s stage=%s register=%s→%s %s %s',
               rt.route, rt.stage, e_route, m_route, charges_same, pv #>> '{fees,dueAfter}', pv #>> '{fees,excessAfter}', pv #>> '{target,result}',
               r_ordinary, r_note, r_elig, r_early, r_mat, r_approver, r_same, decided, q.kind, q.admission_stage, q.decided_office,
               q.fees_paid, q.fees_due_before, q.fees_due_after, q.registrations_returned, q.letter_reissued, reg_row.status, left(reg_row.returned_comment, 30),
               st_row.programme_code, pos.due, pos.paid, pos.balance, n_letters, stage_after, reg_line.applied_code, reg_line.current_code, reg_line.stage, reg_line.reason));
END $$;

-- ── V298 / V315. an O'Level upload is checked for duplicates ──
-- The same result again (the exam number written another way, or no number and the same grades) is not recorded again; the same
-- exam number with other grades is held, not recorded, until the Office keeps the one on record or uses the uploaded one in its
-- place; another exam number of the same body — the same year and series or not — is a sitting of its own (V315: results are
-- combined across sittings); the same exam number on another applicant's record is recorded and flagged until verified. Every
-- finding is kept, and the Office's word always says how it was verified.
DO $$
DECLARE officer uuid := gen_random_uuid(); k1 text := '9980000001OL'; k2 text := '9980000002OL';
        a1 uuid := gen_random_uuid(); a2 uuid := gen_random_uuid(); a3 uuid := gen_random_uuid(); a4 uuid := gen_random_uuid(); a5 uuid := gen_random_uuid(); a6 uuid := gen_random_uuid();
        n1 int; n2 int; n3 int; n4 int; n5 int; n6 int; s1 int; s1_after int; s2 int; held uuid; flagged uuid; st_use text; st_ver text;
        r_note text := 'ok'; r_again text := 'ok'; r_office text := 'ok'; numbers text; kinds text; listed bigint; helpers boolean; flag_other text; known_again boolean; known_new boolean;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', officer::text, true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        helpers := admissions.olevel_series_class('GCE', NULL) = 'EXTERNAL' AND admissions.olevel_series_class('WASSCE', 'MAY/JUNE') = 'INTERNAL'
               AND admissions.olevel_series_class('WAEC', 'Nov/Dec') = 'EXTERNAL' AND admissions.olevel_series_class('SSCE', NULL) = 'INTERNAL'
               AND admissions.olevel_exam_key(' 4250-101/001 ') = '4250101001' AND admissions.olevel_exam_key('  ') IS NULL
               AND admissions.olevel_year('MAY/JUNE 2023') = '2023' AND admissions.olevel_year('n/a') IS NULL;
        INSERT INTO admissions.attachment (id, session, kind, source_name, jamb_key, read_as, payload) VALUES (a1, '9980/9981', 'OLEVEL', 'v298-1', k1, 'COLUMN',
          '{"sittings":[{"type":"WASSCE","series":"MAY/JUNE","year":"2023","examNumber":"4250101001","subjects":[{"subject":"English Language","grade":"C6"},{"subject":"Mathematics","grade":"B3"},{"subject":"Physics","grade":"C5"}]},
                        {"type":"NECO","year":"2023","examNumber":"1234567890","subjects":[{"subject":"English Language","grade":"B3"},{"subject":"Chemistry","grade":"C4"}]}]}'::jsonb);
        n1 := admissions.olevel_from_attachment(a1);
        INSERT INTO admissions.attachment (id, session, kind, source_name, jamb_key, read_as, payload) VALUES (a2, '9980/9981', 'OLEVEL', 'v298-2', k1, 'COLUMN',
          '{"sittings":[{"type":"WAEC","year":"2023","examNumber":"4250101 001","subjects":[{"subject":"English Language","grade":"C6"},{"subject":"Mathematics","grade":"B3"},{"subject":"Physics","grade":"C5"}]}]}'::jsonb);
        n2 := admissions.olevel_from_attachment(a2);
        INSERT INTO admissions.attachment (id, session, kind, source_name, jamb_key, read_as, payload) VALUES (a3, '9980/9981', 'OLEVEL', 'v298-3', k1, 'COLUMN',
          '{"sittings":[{"type":"WASSCE","series":"MAY/JUNE","year":"2023","examNumber":"4250101002","subjects":[{"subject":"English Language","grade":"B2"},{"subject":"Mathematics","grade":"A1"},{"subject":"Physics","grade":"B3"}]},
                        {"type":"WAEC GCE","series":"NOV/DEC","year":"2023","examNumber":"4250999001","subjects":[{"subject":"Biology","grade":"C4"}]}]}'::jsonb);
        n3 := admissions.olevel_from_attachment(a3);
        INSERT INTO admissions.attachment (id, session, kind, source_name, jamb_key, read_as, payload) VALUES (a4, '9980/9981', 'OLEVEL', 'v298-4', k2, 'COLUMN',
          '{"sittings":[{"type":"WAEC","year":"2022","examNumber":"4250-101-001","subjects":[{"subject":"English Language","grade":"A1"}]}]}'::jsonb);
        n4 := admissions.olevel_from_attachment(a4);
        INSERT INTO admissions.attachment (id, session, kind, source_name, jamb_key, read_as, payload) VALUES (a5, '9980/9981', 'OLEVEL', 'v298-5', k1, 'COLUMN',
          '{"sittings":[{"type":"WAEC","year":"May/June 2023","subjects":[{"subject":"Physics","grade":"C5"},{"subject":"English Language","grade":"C6"},{"subject":"Mathematics","grade":"B3"}]}]}'::jsonb);
        n5 := admissions.olevel_from_attachment(a5);
        -- V315: the same exam number again with other grades is the one thing held
        INSERT INTO admissions.attachment (id, session, kind, source_name, jamb_key, read_as, payload) VALUES (a6, '9980/9981', 'OLEVEL', 'v315-6', k1, 'COLUMN',
          '{"sittings":[{"type":"WASSCE","series":"MAY/JUNE","year":"2023","examNumber":"4250101001","subjects":[{"subject":"English Language","grade":"B2"},{"subject":"Mathematics","grade":"A1"},{"subject":"Physics","grade":"B3"}]}]}'::jsonb);
        n6 := admissions.olevel_from_attachment(a6);
        s1 := admissions.olevel_sittings('9980/9981', k1);
        s2 := admissions.olevel_sittings('9980/9981', k2);
        -- a file sent again brings nothing new when every sitting is the same result on record; one with a second result does
        known_again := admissions.olevel_payload_known('9980/9981', k1, '{"sittings":[{"type":"WAEC","series":"May/June","year":"2023","examNumber":"4250 101 001","subjects":[{"subject":"English Language","grade":"C6"},{"subject":"Mathematics","grade":"B3"},{"subject":"Physics","grade":"C5"}]},{"type":"NECO","year":"2023","examNumber":"1234567890","subjects":[{"subject":"English Language","grade":"B3"},{"subject":"Chemistry","grade":"C4"}]}]}'::jsonb);
        known_new := admissions.olevel_payload_known('9980/9981', k1, '{"sittings":[{"type":"NECO","year":"2024","examNumber":"1234567891","subjects":[{"subject":"Chemistry","grade":"B3"}]}]}'::jsonb);
        SELECT string_agg(kind || ':' || state, ',' ORDER BY attachment_id = a2 DESC, attachment_id = a4 DESC, attachment_id = a5 DESC, attachment_id = a6 DESC) INTO kinds FROM admissions.olevel_duplicate WHERE session = '9980/9981';
        SELECT id INTO held FROM admissions.olevel_duplicate WHERE attachment_id = a6 AND kind = 'SAME_SITTING';
        SELECT id, other_jamb_key INTO flagged, flag_other FROM admissions.olevel_duplicate WHERE attachment_id = a4 AND kind = 'NUMBER_ELSEWHERE';
        BEGIN PERFORM admissions.olevel_duplicate_decide(held, 'USE', ' ', officer, 'academic'); EXCEPTION WHEN check_violation THEN r_note := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM admissions.olevel_duplicate_decide(held, 'USE', 'x', officer, 'bursar'); EXCEPTION WHEN check_violation THEN r_office := split_part(SQLERRM, ':', 1); END;
        st_use := admissions.olevel_duplicate_decide(held, 'USE', 'Verified on the WAEC result checker: 4250101002 is the candidate''s', officer, 'academic');
        BEGIN PERFORM admissions.olevel_duplicate_decide(held, 'KEEP', 'x', officer, 'academic'); EXCEPTION WHEN check_violation THEN r_again := split_part(SQLERRM, ':', 1); END;
        st_ver := admissions.olevel_duplicate_decide(flagged, 'VERIFIED', 'WAEC confirms 4250101001 is the first candidate''s', officer, 'academic');
        s1_after := admissions.olevel_sittings('9980/9981', k1);
        SELECT string_agg(exam_number, ',' ORDER BY exam_number) INTO numbers FROM admissions.olevel_sitting WHERE session = '9980/9981' AND jamb_key = k1;
        SELECT count(*) INTO listed FROM admissions.olevel_duplicates('9980/9981');
        RAISE EXCEPTION 'the V298 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('An O''Level upload is checked for duplicates: the same result skipped, the same exam number with other grades held, another number recorded, a shared number flagged',
        coalesce(helpers AND n1 = 2 AND n2 = 0 AND n3 = 2 AND n4 = 1 AND n5 = 0 AND n6 = 0 AND s1 = 4 AND s2 = 1
                 AND kinds = 'SAME_RESULT:SKIPPED,NUMBER_ELSEWHERE:OPEN,SAME_RESULT:SKIPPED,SAME_SITTING:HELD' AND flag_other = k1
                 AND r_note = 'OLEVEL_DUPLICATE_NOTE' AND r_office = 'OLEVEL_DUPLICATE_OFFICE' AND r_again = 'OLEVEL_DUPLICATE_DECIDED'
                 AND st_use = 'USED' AND st_ver = 'VERIFIED' AND s1_after = 4 AND numbers = '1234567890,4250101001,4250101002,4250999001' AND listed = 4
                 AND known_again AND NOT known_new, false),
        format('helpers=%s recorded=%s/%s/%s/%s/%s/%s sittings=%s/%s findings=%s flagged-with=%s refusals=%s/%s/%s decided=%s/%s after=%s numbers=%s listed=%s known=%s/%s',
               helpers, n1, n2, n3, n4, n5, n6, s1, s2, kinds, flag_other, r_note, r_office, r_again, st_use, st_ver, s1_after, numbers, listed, known_again, known_new));
END $$;

-- ── V299. Pay on Quickteller: the portal's own reference in cid, the amount if wanted, the biller of the payer's College ──
-- Off until the Bursary switches a biller on; a link can only be an Interswitch page. A College of Health
-- Sciences payer goes to the College's biller while it is in use, else to the University's. Quickteller's
-- question about a reference is answered from the reference itself; the collections import leaves a short
-- payment open. The block undoes its own writes.
DO $$
DECLARE s_main uuid := gen_random_uuid(); s_chs uuid := gen_random_uuid(); r_main text; r_chs text;
        off_link int; off_any boolean; r_link text; r_needs text; stored text; l_main text; l_chs_off int; l_chs text; l_chs_main text;
        cu record; cu_unknown record; cu_paid record; imp record; chs_open boolean; main_paid boolean; logged boolean;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at) VALUES
            (s_main, 'MOAUM/ADM/99/990299', 'MOAUM/CHK/99/0299', 'CHECKQT', 'Main', 'C00023', 'UTME', '9999/0000', 100, 100, 'ACTIVE', now()),
            (s_chs,  'MOAUM/ADM/99/990300', 'MOAUM/CHK/99/0300', 'CHECKQT', 'Health', 'C00061', 'UTME', '9999/0000', 100, 100, 'ACTIVE', now());
        r_main := finance.new_reference(s_main, '9999/0000', 51000, NULL);
        r_chs := finance.new_reference(s_chs, '9999/0000', 48000.50, NULL);

        -- off until switched on
        SELECT count(*) INTO off_link FROM finance.quickteller_link(r_main);
        off_any := finance.quickteller_redirect_on();
        -- a link to any other site is refused, and so is a redirect with nowhere to go
        BEGIN PERFORM finance.set_paydirect_biller('MAIN', '04255101', 'Benue State University, Makurdi', 'https://quickteller.example.com/bsum', true, true, true);
        EXCEPTION WHEN check_violation THEN r_link := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM finance.set_paydirect_biller('MAIN', '04255101', 'Benue State University, Makurdi', NULL, true, true, true);
        EXCEPTION WHEN check_violation THEN r_needs := split_part(SQLERRM, ':', 1); END;
        -- switched on: the host is read without regard to case, a trailing slash dropped
        SELECT pay_link INTO stored FROM finance.set_paydirect_biller('MAIN', '04255101', 'Benue State University, Makurdi', 'HTTPS://Quickteller.com/bsum/', true, true, true);
        SELECT url INTO l_main FROM finance.quickteller_link(r_main);
        -- the College's biller is in use but not switched on: its payer is not sent to the University's instead
        SELECT count(*) INTO l_chs_off FROM finance.quickteller_link(r_chs);
        PERFORM finance.set_paydirect_biller('CHS', '04263001', 'College of Health Sciences, Benue', 'https://quickteller.com/chsbsu', true, true, false);
        SELECT url INTO l_chs FROM finance.quickteller_link(r_chs);
        -- the College's biller out of use: its payers pay the University's
        PERFORM finance.set_paydirect_biller('CHS', '04263001', 'College of Health Sciences, Benue', 'https://quickteller.com/chsbsu', false, false, true);
        SELECT url INTO l_chs_main FROM finance.quickteller_link(r_chs);

        -- what Quickteller is told about a reference
        SELECT * INTO cu FROM finance.paydirect_customer(lower(r_main));
        SELECT * INTO cu_unknown FROM finance.paydirect_customer('MOAUM-FEE-NOSUCH-0000');
        -- the collections report: short of the amount stays open; the whole amount confirms
        SELECT * INTO imp FROM finance.import_paydirect(jsonb_build_array(
            jsonb_build_object('prn', r_chs, 'amount', '1000', 'rrn', 'RRNQT299A'),
            jsonb_build_object('prn', r_main, 'amount', '51000', 'rrn', 'RRNQT299B')));
        chs_open := (SELECT confirmed_at IS NULL FROM finance.payment_reference WHERE reference = r_chs);
        main_paid := (SELECT confirmed_at IS NOT NULL FROM finance.payment_reference WHERE reference = r_main);
        SELECT * INTO cu_paid FROM finance.paydirect_customer(r_main);
        -- the log keeps a reference check and a reversal as what they are
        PERFORM finance.log_gateway_event('paydirect', 'VALIDATE', 'validate', r_main, NULL, 51000, '0', true, 'VALID', NULL);
        PERFORM finance.log_gateway_event('paydirect', 'WEBHOOK', 'notification', r_main, 'PLOG299', -51000, 'reversal', true, 'REVERSED', NULL);
        logged := true;
        RAISE EXCEPTION 'the V299 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('Pay on Quickteller carries the portal''s own reference and the amount to the biller of the payer''s College, only once switched on and only to Interswitch',
        coalesce(off_link = 0 AND NOT off_any AND r_link = 'QUICKTELLER_LINK' AND r_needs = 'QUICKTELLER_REDIRECT_NEEDS_LINK'
                 AND stored = 'https://quickteller.com/bsum'
                 AND l_main = 'https://quickteller.com/bsum?cid=' || r_main || '&amount=51000'
                 AND l_chs_off = 0 AND l_chs = 'https://quickteller.com/chsbsu?cid=' || r_chs
                 AND l_chs_main = 'https://quickteller.com/bsum?cid=' || r_chs || '&amount=48000.50'
                 AND cu.valid AND cu.reference = r_main AND cu.surname = 'CHECKQT' AND cu.amount = 51000 AND cu.number = 'MOAUM/CHK/99/0299'
                 AND NOT cu_unknown.valid AND imp.matched = 1 AND imp.short_paid = 1 AND chs_open AND main_paid
                 AND NOT cu_paid.valid AND cu_paid.why = 'Already paid' AND logged, false),
        format('off=%s/%s refusals=%s/%s stored=%s main=%s chs_off=%s chs=%s chs_main=%s customer=%s/%s/%s unknown=%s import=%s/%s open=%s paid=%s after=%s/%s',
               off_link, off_any, r_link, r_needs, stored, l_main, l_chs_off, l_chs, l_chs_main, cu.valid, cu.surname, cu.amount,
               cu_unknown.valid, imp.matched, imp.short_paid, chs_open, main_paid, cu_paid.valid, cu_paid.why));
END $$;

-- ── V312: the application windows — open until the Director acts, the applicant's own writes refused while closed ──
DO $$
DECLARE st_default text; st_closed text; r_applicant text; r_office text; st_sched text; st_reopen text; msg text; pub record; n_ev int;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
        PERFORM set_config('moaum.actor_office', 'ict', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on, state) VALUES (gen_random_uuid(), '9983/9984', date '9983-09-01', date '9984-08-31', 'DRAFT') ON CONFLICT DO NOTHING;
        SELECT state INTO st_default FROM policy.window_state('POST_UTME_REGISTRATION', '9983/9984', NULL);
        PERFORM policy.window_act('POST_UTME_REGISTRATION', '9983/9984', NULL, 'CLOSE', NULL, NULL, NULL, false, 'check closed', gen_random_uuid(), 'ict');
        SELECT state INTO st_closed FROM policy.window_state('POST_UTME_REGISTRATION', '9983/9984', NULL);
        -- the applicant registering themselves is held at the door, before any constraint is reached
        PERFORM set_config('moaum.actor_office', 'applicant', true);
        BEGIN
            INSERT INTO admissions.applicant_account (id, session, candidate_id, jamb_key, email, phone, password_hash)
            VALUES (gen_random_uuid(), '9983/9984', gen_random_uuid(), '998300000001CK', 'v312@example.com', '08030000000', 'x');
            r_applicant := 'ALLOWED';
        EXCEPTION WHEN check_violation THEN r_applicant := split_part(SQLERRM, ':', 1); END;
        -- an office's write is not an applicant registering: it goes past the window to the constraints
        PERFORM set_config('moaum.actor_office', 'academic', true);
        BEGIN
            INSERT INTO admissions.applicant_account (id, session, candidate_id, jamb_key, email, phone, password_hash)
            VALUES (gen_random_uuid(), '9983/9984', gen_random_uuid(), '998300000002CK', 'v312b@example.com', '08030000000', 'x');
            r_office := 'ALLOWED';
        EXCEPTION WHEN OTHERS THEN r_office := split_part(SQLERRM, ':', 1); END;
        -- scheduled for later is not open; reopened is
        PERFORM set_config('moaum.actor_office', 'ict', true);
        PERFORM policy.window_act('POST_UTME_REGISTRATION', '9983/9984', NULL, 'SCHEDULE', now() + interval '1 day', now() + interval '30 days', NULL, false, NULL, gen_random_uuid(), 'ict');
        SELECT state INTO st_sched FROM policy.window_state('POST_UTME_REGISTRATION', '9983/9984', NULL);
        PERFORM policy.window_act('POST_UTME_REGISTRATION', '9983/9984', NULL, 'REOPEN', NULL, NULL, NULL, false, 'check reopened', gen_random_uuid(), 'ict');
        SELECT state INTO st_reopen FROM policy.window_state('POST_UTME_REGISTRATION', '9983/9984', NULL);
        -- the closure message is the Director's plain text, and the public reads it
        PERFORM policy.window_message_set('POSTGRADUATE_APPLICATION', E'<b>Closed</b> until <i>March</i>.\r\n\r\nWatch the website.', gen_random_uuid(), 'ict');
        SELECT message INTO msg FROM policy.portal_window_message WHERE window_type = 'POSTGRADUATE_APPLICATION';
        SELECT * INTO pub FROM policy.application_windows_public() WHERE window_type = 'POSTGRADUATE_APPLICATION';
        SELECT count(*) INTO n_ev FROM policy.portal_window_event WHERE window_type = 'POST_UTME_REGISTRATION' AND session = '9983/9984';
        RAISE EXCEPTION 'the V312 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('Application windows are open until the Director of ICT acts, hold the applicant''s own registration at the door while closed or scheduled, and carry the Director''s plain-text message to the public',
        coalesce(st_default = 'OPEN' AND st_closed = 'CLOSED' AND r_applicant = 'APPLICATION_CLOSED' AND r_office <> 'APPLICATION_CLOSED'
                 AND st_sched = 'SCHEDULED' AND st_reopen = 'OPEN'
                 AND msg = E'Closed until March.\n\nWatch the website.' AND pub.message = msg AND pub.state IN ('OPEN', 'CLOSED', 'SCHEDULED', 'EXPIRED')
                 AND n_ev = 3, false),
        format('default=%s closed=%s applicant=%s office=%s scheduled=%s reopened=%s msg=%s pub=%s/%s events=%s',
               st_default, st_closed, r_applicant, r_office, st_sched, st_reopen, msg, pub.state, pub.message, n_ev));
END $$;

-- ── V314: GST & EPS — the fee the Bursar states holds GST and EPS courses until the one confirmed payment lifts it ──
DO $$
DECLARE st uuid := gen_random_uuid(); dept text; o_gst uuid := gen_random_uuid(); o_ent uuid := gen_random_uuid(); reg uuid; e record;
        split_gst text; split_ent text; r_unstated text; r_unpaid text; r_ent text; r_other text; r_choose text; r_paid text; ref text;
        n_notice int; n_pop int; n_ent int; n_entries int;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        SELECT dept_code INTO dept FROM ref.programme WHERE code = 'C00061';
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (st, 'MOAUM/ADM/99/990314', 'MOAUM/CHK/99/0314', 'CHECKGST', 'Invented', 'C00061', 'UTME', '9999/0000', 100, 100, 'ACTIVE', now());
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state) VALUES
            ('GST 991', 'Check General Studies', 2, 1, 100, dept, 'GST', 'LIVE'),
            ('ENT 991', 'Check Venture Creation', 2, 1, 100, dept, 'GST', 'LIVE');
        INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES ('GST 991', 'C00061', 100, 'GST'), ('ENT 991', 'C00061', 100, 'GST');
        INSERT INTO catalogue.offering (id, course_code, session, semester) VALUES (o_gst, 'GST 991', '9999/0000', 1), (o_ent, 'ENT 991', '9999/0000', 1);
        SELECT general_office INTO split_gst FROM catalogue.course WHERE code = 'GST 991';
        SELECT general_office INTO split_ent FROM catalogue.course WHERE code = 'ENT 991';
        PERFORM set_config('moaum.actor_office', 'student', true);
        INSERT INTO people.student_contact (student_id, email, phone) VALUES (st, 'check.gst@example.com', '08030000314');
        -- no fee stated: nothing to pay, and no gate
        r_unstated := coalesce(registration.gst_gate(st, '9999/0000', 'GST 991'), 'OPEN');
        -- the Bursar states the fee: the GST course and the EPS course are held, another course is not
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM finance.state_gst_fee('9999/0000', 10000, NULL, NULL, NULL, NULL, NULL, 'check', gen_random_uuid(), 'bursar');
        r_unpaid := split_part(coalesce(registration.gst_gate(st, '9999/0000', 'GST 991'), 'OPEN'), ':', 1);
        r_ent := split_part(coalesce(registration.gst_gate(st, '9999/0000', 'ENT 991'), 'OPEN'), ':', 1);
        r_other := coalesce(registration.gst_gate(st, '9999/0000', 'CHK 101'), 'OPEN');
        -- the registration itself refuses the GST course to the unpaid student
        PERFORM set_config('moaum.actor_office', 'student', true);
        reg := registration.student_draft(st, '9999/0000', 1);
        BEGIN
            PERFORM registration.student_choose(reg, ARRAY[o_gst]);
            r_choose := 'ALLOWED';
        EXCEPTION WHEN check_violation THEN r_choose := split_part(SQLERRM, ':', 1); END;
        -- the one payment, confirmed on the ledger: entitled, the gate lifts for GST and EPS alike, the student is told
        ref := finance.new_gst_reference(st, '9999/0000');
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM finance.confirm_payment(ref, 'Bank transfer', 'check');
        SELECT * INTO e FROM finance.gst_entitlement(st, '9999/0000');
        r_paid := coalesce(registration.gst_gate(st, '9999/0000', 'GST 991'), 'OPEN');
        PERFORM set_config('moaum.actor_office', 'student', true);
        PERFORM registration.student_choose(reg, ARRAY[o_gst, o_ent]);
        SELECT count(*) INTO n_entries FROM registration.entry WHERE registration_id = reg AND entry_type = 'GST';
        SELECT count(*) INTO n_notice FROM platform.notice WHERE about_kind = 'student' AND about_id = st AND subject ILIKE 'GST fee%';
        SELECT count(*), count(*) FILTER (WHERE entitled AND gst_registered AND eps_registered AND pay_state = 'PAID')
          INTO n_pop, n_ent FROM finance.gst_population('9999/0000', NULL) WHERE student_id = st;
        RAISE EXCEPTION 'the V314 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('GST & EPS: the fee the Bursar states holds GST and EPS courses alone until the one confirmed payment lifts it, and the student is told',
        coalesce(split_gst = 'GST' AND split_ent = 'EPS' AND r_unstated = 'OPEN' AND r_unpaid = 'GST_PAYMENT_REQUIRED' AND r_ent = 'GST_PAYMENT_REQUIRED' AND r_other = 'OPEN'
                 AND r_choose = 'GST_PAYMENT_REQUIRED' AND e.entitled AND e.state = 'PAID' AND e.paid = 10000 AND r_paid = 'OPEN' AND n_entries = 2
                 AND n_notice >= 1 AND n_pop = 1 AND n_ent = 1, false),
        format('split=%s/%s unstated=%s unpaid=%s ent=%s other=%s choose=%s entitled=%s state=%s paid=%s after=%s entries=%s notices=%s population=%s/%s',
               split_gst, split_ent, r_unstated, r_unpaid, r_ent, r_other, r_choose, e.entitled, e.state, e.paid, r_paid, n_entries, n_notice, n_pop, n_ent));
END $$;

-- ── V316: a bounded office grant carries the register's code — a name resolves to it, an unknown name is refused ──
DO $$
DECLARE who uuid := gen_random_uuid(); g1 uuid := gen_random_uuid(); g2 uuid := gen_random_uuid(); g3 uuid := gen_random_uuid();
        s_dept text; s_prog text; s_fac text; r_unknown text := 'ALLOWED'; v_prog_name text; v_fac_name text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'registrar', true);
        INSERT INTO iam.person (id, surname, given_names, staff_number) VALUES (who, 'CHECKSCOPE', 'Invented', 'P-V316');
        SELECT name INTO v_prog_name FROM ref.programme WHERE code = 'C00023';
        SELECT name INTO v_fac_name FROM ref.faculty WHERE code = 'SC';
        -- typed as names: the Head of Department over the department's name, the Examinations Officer over the programme's name, the Dean over the faculty's name
        INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from)
        VALUES (g1, who, 'hod', 'department', 'mathematics and computer science', 'check', who, current_date),
               (g2, who, 'exams', 'programme', v_prog_name, 'check', who, current_date),
               (g3, who, 'dean', 'faculty', lower(v_fac_name), 'check', who, current_date);
        SELECT scope_id INTO s_dept FROM iam.office_assignment WHERE id = g1;
        SELECT scope_id INTO s_prog FROM iam.office_assignment WHERE id = g2;
        SELECT scope_id INTO s_fac FROM iam.office_assignment WHERE id = g3;
        -- a name the register does not know is refused
        BEGIN
            INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from)
            VALUES (gen_random_uuid(), who, 'hod', 'department', 'Department of Nowhere', 'check', who, current_date);
        EXCEPTION WHEN check_violation THEN r_unknown := split_part(SQLERRM, ':', 1); END;
        RAISE EXCEPTION 'the V316 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('A bounded office grant carries the register''s code: a department, programme or faculty typed by name is stored as its code, and an unknown name is refused',
        coalesce(s_dept = 'MTC' AND s_prog = 'C00023' AND s_fac = 'SC' AND r_unknown = 'OFFICE_SCOPE_UNKNOWN', false),
        format('department=%s programme=%s faculty=%s unknown=%s', s_dept, s_prog, s_fac, r_unknown));
END $$;

-- ── 161-162. V318: coverage is counted from the roll; an upload on behalf names its uploader and says why ──
DO $$
DECLARE sh uuid; o uuid; o2 uuid := gen_random_uuid(); sh2 uuid := gen_random_uuid(); s1 uuid; up uuid;
        lect uuid := gen_random_uuid(); officer uuid := gen_random_uuid();
        v_exp bigint; v_rec bigint; v_mis bigint; v_gra bigint;
        r_noreason text; r_teach text; r_blank text; v_by uuid; v_office text; v_owner uuid; e_by uuid; e_office text; e_behalf boolean;
BEGIN
    -- the sheet block 74 took through the chain: two on the roll, one graded and one absent — nothing missing
    SELECT s.id, oo.id INTO sh, o FROM assessment.score_sheet s JOIN catalogue.offering oo ON oo.id = s.offering_id WHERE oo.course_code = 'ZZC 101';
    SELECT id INTO s1 FROM people.student WHERE admission_no = 'MOAUM/ADM/99/000001';
    SELECT expected, received, missing, graded INTO v_exp, v_rec, v_mis, v_gra FROM assessment.sheet_coverage(sh);
    PERFORM pg_temp.assert('Coverage is counted from the roll: two candidates expected, two with a mark or an outcome, none missing, one graded',
        v_exp = 2 AND v_rec = 2 AND v_mis = 0 AND v_gra = 1, format('expected=%s received=%s missing=%s graded=%s', v_exp, v_rec, v_mis, v_gra));

    BEGIN
        PERFORM set_config('moaum.actor_id', officer::text, true);
        PERFORM set_config('moaum.actor_office', 'exams', true);
        INSERT INTO iam.person (id, surname, given_names, staff_number) VALUES (lect, 'CHECKLECT', 'Invented', 'P-V318-L'), (officer, 'CHECKEXAMS', 'Invented', 'P-V318-E');
        -- a second sitting of the course with its lecturer, and a sheet at entry
        INSERT INTO catalogue.offering (id, course_code, session, semester, lecturer_id) VALUES (o2, 'ZZC 101', '9999/0000', 2, lect);
        INSERT INTO assessment.score_sheet (id, offering_id) VALUES (sh2, o2);
        -- an upload on behalf without a reason is refused
        BEGIN
            PERFORM assessment.record_upload_on_behalf(sh2, NULL, 1);
        EXCEPTION WHEN check_violation THEN r_noreason := split_part(SQLERRM, ':', 1); END;
        -- the lecturer's own entry is not on anyone's behalf
        PERFORM set_config('moaum.actor_id', lect::text, true);
        PERFORM set_config('moaum.actor_office', 'lecturer', true);
        BEGIN
            PERFORM assessment.record_upload_on_behalf(sh2, 'lecturer away', 1);
        EXCEPTION WHEN check_violation THEN r_teach := split_part(SQLERRM, ':', 1); END;
        -- the officer, with the reason: the record names the uploader, their office and the lecturer of record
        PERFORM set_config('moaum.actor_id', officer::text, true);
        PERFORM set_config('moaum.actor_office', 'exams', true);
        up := assessment.record_upload_on_behalf(sh2, 'Lecturer on medical leave', 1);
        SELECT uploaded_by, uploader_office, owner_id INTO v_by, v_office, v_owner FROM assessment.sheet_upload WHERE id = up;
        -- a mark on behalf without its reason is refused by the table itself
        BEGIN
            INSERT INTO assessment.score (sheet_id, student_id, ca, exam, on_behalf) VALUES (sh2, s1, 30, 45, true);
        EXCEPTION WHEN check_violation THEN r_blank := 'refused'; END;
        INSERT INTO assessment.score (sheet_id, student_id, ca, exam, on_behalf, on_behalf_reason) VALUES (sh2, s1, 30, 45, true, 'Lecturer on medical leave');
        SELECT entered_by, entered_office, on_behalf INTO e_by, e_office, e_behalf FROM assessment.score WHERE sheet_id = sh2 AND student_id = s1;
        RAISE EXCEPTION 'the V318 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('An upload on behalf says why and names its uploader: refused without a reason, refused from the lecturer, recorded with the officer, their office and the lecturer of record; the mark itself refuses on-behalf without a reason and carries who wrote it',
        coalesce(r_noreason = 'RES_UPLOAD_ON_BEHALF_SAYS_WHY' AND r_teach = 'RES_NOT_ON_BEHALF' AND v_by = officer AND v_office = 'exams' AND v_owner = lect
                 AND r_blank = 'refused' AND e_by = officer AND e_office = 'exams' AND e_behalf, false),
        format('no reason=%s lecturer=%s by=%s office=%s owner=%s blank=%s entered_by=%s', r_noreason, r_teach, v_by = officer, v_office, v_owner = lect, r_blank, e_by = officer));
END $$;

-- ── 163. V319: a grant is amended with its reason, its scope normalised, and an ended grant is left as it was ──
DO $$
DECLARE who uuid := gen_random_uuid(); g1 uuid := gen_random_uuid(); g2 uuid := gen_random_uuid();
        r_noreason text; r_ended text; o_after text; s_after text; v_prog_name text; v_reason text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'registrar', true);
        INSERT INTO iam.person (id, surname, given_names, staff_number) VALUES (who, 'CHECKAMEND', 'Invented', 'P-V319');
        INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from, valid_to)
        VALUES (g1, who, 'hod', 'department', 'MTC', 'check', who, current_date, NULL),
               (g2, who, 'exams', 'programme', 'C00023', 'check', who, current_date - 30, current_date - 1);
        -- without a reason, refused
        BEGIN
            PERFORM iam.amend_grant(g1, 'exams', 'programme', 'C00023', 'check', NULL, NULL, NULL);
        EXCEPTION WHEN check_violation THEN r_noreason := split_part(SQLERRM, ':', 1); END;
        -- the office and the scope change in place, the scope typed as a name and stored as the register's code
        SELECT name INTO v_prog_name FROM ref.programme WHERE code = 'C00023';
        PERFORM iam.amend_grant(g1, 'exams', 'programme', v_prog_name, 'Registrar memo REG/2026/400', NULL, NULL,
                                'granted as Head of Department in error; the letter appoints an Examinations Officer');
        SELECT office_code, scope_id INTO o_after, s_after FROM iam.office_assignment WHERE id = g1;
        v_reason := current_setting('moaum.reason', true);
        -- an ended grant stays as it was
        BEGIN
            PERFORM iam.amend_grant(g2, 'exams', 'programme', 'C00023', 'check', NULL, NULL, 'too late');
        EXCEPTION WHEN check_violation THEN r_ended := split_part(SQLERRM, ':', 1); END;
        RAISE EXCEPTION 'the V319 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('A grant is amended with its reason: refused without one, the office and the scope changed in place with the scope as the register''s code, the reason on the audit context, and an ended grant left as it was',
        coalesce(r_noreason = 'IAM_AMEND_SAYS_WHY' AND o_after = 'exams' AND s_after = 'C00023' AND v_reason LIKE 'grant amended:%' AND r_ended = 'IAM_GRANT_ENDED', false),
        format('no reason=%s office=%s scope=%s reason=%s ended=%s', r_noreason, o_after, s_after, left(v_reason, 30), r_ended));
END $$;

-- ── 164-165. V320: one institution profile every document reads, changed with its rules and audited; an issued document on the record ──
DO $$
DECLARE n int; v_name text; r_blank text; r_mail text; v_motto text; audited int; who uuid := gen_random_uuid(); iss uuid; v_actor uuid; v_kind text;
BEGIN
    SELECT count(*), max(name) INTO n, v_name FROM platform.institution_profile;
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'ict', true);
        BEGIN
            PERFORM platform.set_institution_profile(' ', 'X', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, true, 'LONG');
        EXCEPTION WHEN check_violation THEN r_blank := split_part(SQLERRM, ':', 1); END;
        BEGIN
            PERFORM platform.set_institution_profile('A University', 'AU', NULL, NULL, NULL, NULL, NULL, NULL, 'not-an-address', NULL, NULL, true, true, 'LONG');
        EXCEPTION WHEN check_violation THEN r_mail := split_part(SQLERRM, ':', 1); END;
        v_motto := platform.set_institution_profile('A University', 'AU', ' Knowledge and Service ', NULL, 'Makurdi', NULL, NULL, NULL, 'info@example.edu.ng', 'www.example.edu.ng', NULL, true, true, 'SHORT') ->> 'motto';
        SELECT count(*) INTO audited FROM audit.entries WHERE subject_type = 'platform.institution_profile' AND action = 'UPDATE' AND actor_id = who;
        iss := platform.record_document_issue('receipt_downloaded', 'RCT/2026/000001', 'payment', 'RCT/2026/000001', '{"format":"pdf"}'::jsonb);
        SELECT actor_id, kind INTO v_actor, v_kind FROM platform.document_issue WHERE id = iss;
        RAISE EXCEPTION 'the V320 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('One institution profile heads every document: seeded with a name, a blank name and a malformed e-mail refused, a change trimmed and audited in the actor''s name',
        coalesce(n = 1 AND v_name <> '' AND r_blank = 'INSTITUTION_NAME_REQUIRED' AND r_mail = 'INSTITUTION_EMAIL_INVALID' AND v_motto = 'Knowledge and Service' AND audited >= 1, false),
        format('rows=%s blank=%s mail=%s motto=%s audited=%s', n, r_blank, r_mail, v_motto, audited));
    PERFORM pg_temp.assert('A document the portal issues is on the record in the actor''s name, its kind in capitals',
        coalesce(v_actor = who AND v_kind = 'RECEIPT_DOWNLOADED', false), format('actor=%s kind=%s', v_actor = who, v_kind));
END $$;

-- ── 166. V321: a bulk allocation import is recorded under a reference numbered in the session, and the same key never records twice ──
DO $$
DECLARE who uuid := gen_random_uuid(); k uuid := gen_random_uuid(); r1 catalogue.allocation_import; r2 catalogue.allocation_import; r3 catalogue.allocation_import;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'hod', true);
        r1 := catalogue.record_allocation_import(k, 'allocations.xlsx', '9999/0000', 1, 'MTC', 10, 8, 7, 1, 3, 2, 1, 'COMPLETED_WITH_ERRORS', '{"allowOverload":false}'::jsonb, '[]'::jsonb);
        r2 := catalogue.record_allocation_import(k, 'allocations.xlsx', '9999/0000', 1, 'MTC', 10, 8, 7, 1, 3, 2, 1, 'COMPLETED_WITH_ERRORS', '{}'::jsonb, '[]'::jsonb);
        r3 := catalogue.record_allocation_import(gen_random_uuid(), 'more.xlsx', '9999/0000', 2, 'MTC', 1, 1, 1, 0, 0, 0, 0, 'COMPLETED', '{}'::jsonb, '[]'::jsonb);
        RAISE EXCEPTION 'the V321 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('A bulk allocation import is recorded under a reference numbered in the session, in the uploader''s name; the same key answers with the record already made, and the next import takes the next number',
        coalesce(r1.reference ~ '^ALLOC/9999-0000/\d{5}$' AND r1.uploaded_by = who AND r1.uploader_office = 'hod' AND r2.id = r1.id AND r2.reference = r1.reference
                 AND r3.id <> r1.id AND r3.reference > r1.reference, false),
        format('first=%s again=%s next=%s', r1.reference, r2.reference, r3.reference));
END $$;

-- ── 167-168. V322: a CBT attempt is the server's — eligibility judged at the start, the second sign-in by policy, the paper drawn by a seed,
--                   the score in one transaction and never twice, the violation policy applied, the result a version with its reason ──
DO $$
DECLARE who uuid := gen_random_uuid(); st uuid := gen_random_uuid(); off uuid := gen_random_uuid(); ex assessment.cbt_exam; a assessment.cbt_attempt; a2 assessment.cbt_attempt; r assessment.cbt_result;
        q1 uuid := gen_random_uuid(); q2 uuid := gen_random_uuid(); q3 uuid := gen_random_uuid(); reg uuid; ref text;
        r_unpublished text; r_unregistered text; r_unpaid text; r_paid text; r_limit text; r_old_token text; r_publish_empty text;
        tok1 uuid; tok2 uuid; ev jsonb; v_status text; v_score numeric; v_pct numeric; v_grade text; v_passed boolean; v_events int; v_again numeric; v_versions int; v_sweep int; v_sweep_status text;
        v_live text; v_results text; v_student_sees numeric; v_student_hidden numeric; v_key_leak int;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'gst', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), '9995/9996', date '9995-10-01', date '9996-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state)
        SELECT 'GST 995', 'Check General Studies', 2, 1, 100, p.dept_code, 'GST', 'LIVE' FROM ref.programme p WHERE p.code = 'C00023';
        INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES ('GST 995', 'C00023', 100, 'GST');
        INSERT INTO catalogue.offering (id, course_code, session, semester) VALUES (off, 'GST 995', '9995/9996', 1);
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (st, 'MOAUM/ADM/95/000995', 'MOAUM/CHK/95/995', 'ZZCHECKCBT', 'Invented', 'C00023', 'UTME', '9995/9996', 100, 100, 'ACTIVE', now());
        INSERT INTO assessment.question (id, course_code, stem, options, answer, kind, marks) VALUES (q1, 'GST 995', 'one of four', '["a","b","c","d"]', 2, 'MCQ', 1), (q2, 'GST 995', 'true or false', '["True","False"]', 0, 'TRUE_FALSE', 1);
        INSERT INTO assessment.question (id, course_code, stem, options, answer, answers, kind, marks) VALUES (q3, 'GST 995', 'several', '["a","b","c","d"]', 0, ARRAY[3, 1], 'MULTI', 2);
        PERFORM pg_temp.moderated();
        -- the key is kept as a sorted array whatever the kind, and never appears in what a paper carries (the question ids only)
        SELECT count(*) INTO v_key_leak FROM assessment.question WHERE id IN (q1, q2, q3) AND NOT (answers = ARRAY[answer] OR (kind = 'MULTI' AND answers = ARRAY[1, 3]));
        ex := assessment.cbt_new_exam('GST', off, 'Check CBT', NULL, 30, 0, 'FIXED', false, false, 50, 1, 'STANDARD', 'REMOTE', 1, 'TERMINATE', 'CONTINUE', now() - interval '1 minute', now() + interval '2 hours');
        r_unpublished := split_part(assessment.cbt_eligibility(ex.id, st), ':', 1);
        BEGIN
            PERFORM assessment.cbt_exam_action(ex.id, 'publish', NULL);
        EXCEPTION WHEN check_violation THEN r_publish_empty := split_part(SQLERRM, ':', 1); END;
        INSERT INTO assessment.cbt_exam_question (exam_id, question_id, ordinal) VALUES (ex.id, q1, 1), (ex.id, q2, 2), (ex.id, q3, 3);
        PERFORM assessment.cbt_exam_action(ex.id, 'publish', NULL);
        SELECT assessment.cbt_live_state(e) INTO v_live FROM assessment.cbt_exam e WHERE e.id = ex.id;
        r_unregistered := split_part(assessment.cbt_eligibility(ex.id, st), ':', 1);
        reg := registration.student_draft(st, '9995/9996', 1);
        PERFORM registration.student_choose(reg, ARRAY[off]);
        UPDATE registration.course_registration SET status = 'SUBMITTED', submitted_at = now() WHERE id = reg;
        PERFORM finance.state_gst_fee('9995/9996', 5000, NULL, NULL, NULL, NULL, current_date, NULL, who, 'bursar');
        r_unpaid := split_part(assessment.cbt_eligibility(ex.id, st), ':', 1);
        ref := finance.new_gst_reference(st, '9995/9996');
        PERFORM finance.confirm_payment(ref, 'CARD', 'check');
        r_paid := coalesce(assessment.cbt_eligibility(ex.id, st), 'ELIGIBLE');
        -- the attempt: started, opened again (the token rotates, the second sign-in is on the record), the old screen refused
        PERFORM set_config('moaum.actor_id', st::text, true);
        PERFORM set_config('moaum.actor_office', 'student', true);
        a := assessment.cbt_start(ex.id, st, '10.0.0.1', 'check');
        tok1 := a.token;
        a2 := assessment.cbt_start(ex.id, st, '10.0.0.2', 'check');
        tok2 := a2.token;
        BEGIN
            PERFORM assessment.cbt_touch(a.id, tok1);
        EXCEPTION WHEN check_violation THEN r_old_token := split_part(SQLERRM, ':', 1); END;
        -- answers: two right, one wrong; one violation over the limit of one (the second sign-in counted) terminates and scores at once
        PERFORM assessment.cbt_save_answers(a.id, tok2, jsonb_build_array(jsonb_build_object('q', q1, 'a', jsonb_build_array(2)), jsonb_build_object('q', q2, 'a', jsonb_build_array(0)), jsonb_build_object('q', q3, 'a', jsonb_build_array(1))));
        ev := assessment.cbt_record_events(a.id, tok2, '[{"kind":"TAB_SWITCH"}]'::jsonb, '10.0.0.2');
        SELECT status, score, percentage, grade, passed INTO v_status, v_score, v_pct, v_grade, v_passed FROM assessment.cbt_attempt WHERE id = a.id;
        SELECT count(*) INTO v_events FROM assessment.cbt_event WHERE attempt_id = a.id AND kind IN ('STARTED', 'MULTIPLE_LOGIN', 'SESSION_REPLACED', 'TAB_SWITCH', 'TERMINATED');
        -- finalised once: a second finalisation changes nothing
        PERFORM assessment.cbt_finalize(a.id, 'SUBMITTED', 'again');
        SELECT score INTO v_again FROM assessment.cbt_attempt WHERE id = a.id;
        SELECT count(*) INTO v_versions FROM assessment.cbt_result WHERE attempt_id = a.id;
        r_limit := split_part(coalesce(assessment.cbt_eligibility(ex.id, st), 'ELIGIBLE'), ':', 1);
        -- the office: results hidden from the student until published; an amendment is a version with its reason
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'gst', true);
        SELECT x.percentage INTO v_student_hidden FROM assessment.cbt_student_exams(st, '9995/9996') x WHERE x.exam_id = ex.id;
        PERFORM assessment.cbt_exam_action(ex.id, 'close', NULL);
        PERFORM assessment.cbt_exam_action(ex.id, 'complete', NULL);
        PERFORM assessment.cbt_results_action(ex.id, 'review');
        r := assessment.cbt_amend_result(a.id, 2, 'SCORED', 'check: a key corrected');
        PERFORM assessment.cbt_results_action(ex.id, 'approve');
        PERFORM assessment.cbt_results_action(ex.id, 'publish');
        SELECT x.results_state INTO v_results FROM assessment.cbt_exam x WHERE x.id = ex.id;
        SELECT x.percentage INTO v_student_sees FROM assessment.cbt_student_exams(st, '9995/9996') x WHERE x.exam_id = ex.id;
        -- the clock: an attempt left past its end is finalised by the sweep
        UPDATE assessment.cbt_exam SET state = 'PUBLISHED', ends_at = now() + interval '1 hour', attempt_limit = 2 WHERE id = ex.id;
        PERFORM set_config('moaum.actor_id', st::text, true);
        PERFORM set_config('moaum.actor_office', 'student', true);
        a2 := assessment.cbt_start(ex.id, st, '10.0.0.1', 'check');
        UPDATE assessment.cbt_attempt SET ends_at = now() - interval '1 minute' WHERE id = a2.id;
        v_sweep := assessment.cbt_sweep();
        SELECT status INTO v_sweep_status FROM assessment.cbt_attempt WHERE id = a2.id;
        RAISE EXCEPTION 'the V322 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('A CBT attempt is the server''s: not eligible unpublished, the paper refused empty, refused unregistered, held on the GST fee and freed by the confirmed payment; a second sign-in rotates the token and the old screen is refused; the attempt limit holds',
        coalesce(v_key_leak = 0 AND r_unpublished = 'CBT_EXAM_NOT_OPEN' AND r_publish_empty = 'CBT_PAPER_EMPTY' AND v_live = 'OPEN' AND r_unregistered = 'CBT_COURSE_NOT_REGISTERED'
                 AND r_unpaid = 'GST_PAYMENT_REQUIRED' AND r_paid = 'ELIGIBLE' AND tok1 <> tok2 AND r_old_token = 'CBT_SESSION_REPLACED' AND r_limit = 'CBT_ATTEMPT_LIMIT', false),
        format('leak=%s unpublished=%s empty=%s live=%s unreg=%s unpaid=%s paid=%s rotated=%s old=%s limit=%s', v_key_leak, r_unpublished, r_publish_empty, v_live, r_unregistered, r_unpaid, r_paid, tok1 <> tok2, r_old_token, r_limit));
    PERFORM pg_temp.assert('The score is one transaction and never twice: the violation policy terminates over the limit and scores at once (2 of 4, 50%, C, passed at the pass mark), the events are on the record, a second finalisation changes nothing; the result is hidden from the student until published, an amendment is version 2 with its reason, and the sweep finalises an attempt past its end',
        coalesce(v_status = 'TERMINATED' AND v_score = 2 AND v_pct = 50 AND v_grade = 'C' AND v_passed AND v_events = 5 AND v_again = 2 AND v_versions = 1 AND r.version = 2 AND r.score = 2
                 AND v_student_hidden IS NULL AND v_results = 'PUBLISHED' AND v_student_sees = 50 AND v_sweep >= 1 AND v_sweep_status = 'TIME_EXPIRED', false),
        format('status=%s score=%s pct=%s grade=%s passed=%s events=%s again=%s versions=%s amended=%s hidden=%s results=%s sees=%s sweep=%s/%s', v_status, v_score, v_pct, v_grade, v_passed, v_events, v_again, v_versions, r.version, v_student_hidden, v_results, v_student_sees, v_sweep, v_sweep_status));
END $$;

-- ── 169-170. V323: an old-portal GST payment is staged once, matched by strong identifiers only, judged against THAT session's fee and the ledger,
--                   written to the one ledger on apply with its old reference and date, never twice; the student then reads PAID from the old portal ──
DO $$
DECLARE who uuid := gen_random_uuid(); sa uuid := gen_random_uuid(); sb uuid := gen_random_uuid(); sc uuid := gen_random_uuid(); imp uuid; r record; st record;
        v_matched int; v_validated int; v_tx1 text; v_tx2 text; v_tx3 text; v_tx4 text; v_tx5 text; v_tx6 text; v_dup_in_file int; v_before text; v_after text; v_source text; v_legacy_ref text;
        v_paid_at date; v_gate text; v_again int; v_ledger int; v_prev text; v_written_once text; v_steal text; v_sum record; v_relabel text; v_purpose text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), '9993/9994', date '9993-10-01', date '9994-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), '9992/9993', date '9992-10-01', date '9993-08-31') ON CONFLICT (name) DO NOTHING;
        PERFORM finance.state_gst_fee('9992/9993', 15000, NULL, NULL, NULL, NULL, current_date, NULL, who, 'bursar');
        PERFORM finance.state_gst_fee('9993/9994', 20000, NULL, NULL, NULL, NULL, current_date, NULL, who, 'bursar');
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state)
        SELECT 'GST 993', 'Check Legacy GST', 2, 1, 100, p.dept_code, 'GST', 'LIVE' FROM ref.programme p WHERE p.code = 'C00023';
        INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES ('GST 993', 'C00023', 100, 'GST');
        -- V366: the fee is owed for a GST course the session runs, so the session runs it
        INSERT INTO catalogue.offering (id, course_code, session, semester) VALUES (gen_random_uuid(), 'GST 993', '9993/9994', 1);
        INSERT INTO people.student (id, admission_no, matric_no, jamb_reg_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at) VALUES
            (sa, 'MOAUM/ADM/93/000001', 'MOAUM/CHK/93/0001', '93000001ZA', 'ZZCHKLEGA', 'Invented', 'C00023', 'UTME', '9993/9994', 100, 100, 'ACTIVE', now()),
            (sb, 'MOAUM/ADM/93/000002', 'MOAUM/CHK/93/0002', NULL, 'ZZCHKLEGB', 'Invented', 'C00023', 'UTME', '9993/9994', 100, 100, 'ACTIVE', now()),
            (sc, 'MOAUM/ADM/93/000003', 'MOAUM/CHK/93/0003', NULL, 'ZZCHKLEGC', 'Invented', 'C00023', 'UTME', '9993/9994', 100, 100, 'ACTIVE', now());
        -- C's money already on the ledger as school fees from the Old Fees History import
        INSERT INTO finance.payment_reference (student_id, session, reference, purpose, amount, expires_at, confirmed_at, confirmed_by, channel, receipt_no, note)
        VALUES (sc, '9993/9994', 'MOAUM-LEG-CHK930003-9993-9994', 'School fees (legacy)', 20000, '9993-09-16', '9993-09-16', who, 'Legacy', 'LEG-MOAUM-LEG-CHK930003-9993-9994', 'Imported from the old portal');
        SELECT state INTO v_before FROM finance.gst_entitlement(sa, '9993/9994');
        imp := (finance.legacy_gst_new_import('old.xlsx', '9993/9994', 'check')).id;
        SELECT already_staged INTO v_dup_in_file FROM finance.legacy_gst_stage(imp, jsonb_build_array(
            jsonb_build_object('transactionId', 'CHK-TX1', 'reference', 'CHK-OLD-1', 'matric', 'MOAUM/CHK/93/0001', 'jamb', '93000001ZA', 'paymentType', 'GST PAYMENT', 'amount', '20,000.00', 'paidAt', '15/09/9993', 'session', '9993/9994', 'status', 'SUCCESS'),
            jsonb_build_object('transactionId', 'CHK-TX2', 'reference', 'CHK-OLD-2', 'matric', 'MOAUM/CHK/93/0002', 'paymentType', 'GST', 'amount', '20000', 'paidAt', '9993-09-16', 'session', '9993/9994', 'status', 'FAILED'),
            jsonb_build_object('transactionId', 'CHK-TX3', 'reference', 'CHK-OLD-3', 'matric', 'MOAUM/CHK/93/0002', 'paymentType', 'GST', 'amount', '20000', 'paidAt', '9993-09-16', 'session', '9993/9994', 'status', 'REFUNDED'),
            jsonb_build_object('transactionId', 'CHK-TX4', 'reference', 'CHK-OLD-4', 'matric', 'MOAUM/CHK/93/0001', 'paymentType', 'GST', 'amount', '15000', 'paidAt', '9992-10-02', 'session', '9992/9993', 'status', 'PAID'),
            jsonb_build_object('transactionId', 'CHK-TX5', 'reference', 'CHK-OLD-5', 'matric', 'MOAUM/CHK/93/0003', 'paymentType', 'General Studies', 'amount', '20000', 'paidAt', '9993-09-16', 'session', '9993/9994', 'status', 'SUCCESS'),
            jsonb_build_object('transactionId', 'CHK-TX6', 'reference', 'CHK-OLD-6', 'matric', 'MOAUM/CHK/93/0099', 'name', 'ZZCHKLEGB Invented', 'paymentType', 'GST', 'amount', '20000', 'session', '9993/9994', 'status', 'SUCCESS'),
            jsonb_build_object('transactionId', 'CHK-TX1', 'reference', 'CHK-OLD-1', 'matric', 'MOAUM/CHK/93/0001', 'paymentType', 'GST', 'amount', '20000', 'session', '9993/9994', 'status', 'SUCCESS')));
        v_matched := finance.legacy_gst_match(imp);
        v_validated := finance.legacy_gst_validate(imp);
        SELECT rc.status || '/' || coalesce(rc.reason_code, '-') || '/' || coalesce(rc.match_method, '-') || '/' || coalesce(rc.fee_amount::text, '-') INTO v_tx1 FROM finance.legacy_gst_payment p JOIN finance.legacy_gst_reconciliation rc ON rc.payment_id = p.id WHERE p.source_transaction_id = 'CHK-TX1';
        SELECT rc.status || '/' || coalesce(rc.reason_code, '-') INTO v_tx2 FROM finance.legacy_gst_payment p JOIN finance.legacy_gst_reconciliation rc ON rc.payment_id = p.id WHERE p.source_transaction_id = 'CHK-TX2';
        SELECT rc.status || '/' || coalesce(rc.reason_code, '-') INTO v_tx3 FROM finance.legacy_gst_payment p JOIN finance.legacy_gst_reconciliation rc ON rc.payment_id = p.id WHERE p.source_transaction_id = 'CHK-TX3';
        SELECT rc.status || '/' || coalesce(rc.fee_amount::text, '-') INTO v_tx4 FROM finance.legacy_gst_payment p JOIN finance.legacy_gst_reconciliation rc ON rc.payment_id = p.id WHERE p.source_transaction_id = 'CHK-TX4';
        SELECT rc.status || '/' || coalesce(rc.reason_code, '-') INTO v_tx5 FROM finance.legacy_gst_payment p JOIN finance.legacy_gst_reconciliation rc ON rc.payment_id = p.id WHERE p.source_transaction_id = 'CHK-TX5';
        SELECT rc.status || '/' || coalesce(rc.reason_code, '-') || '/' || jsonb_array_length(coalesce(rc.candidates, '[]')) INTO v_tx6 FROM finance.legacy_gst_payment p JOIN finance.legacy_gst_reconciliation rc ON rc.payment_id = p.id WHERE p.source_transaction_id = 'CHK-TX6';
        BEGIN
            UPDATE finance.legacy_gst_payment SET amount = 1 WHERE source_transaction_id = 'CHK-TX1';
            v_written_once := 'allowed';
        EXCEPTION WHEN check_violation THEN v_written_once := split_part(SQLERRM, ':', 1); END;
        -- applied: A reads PAID from the old portal, with the old reference and the old date; the gate opens; last session's payment stands for last session; twice changes nothing
        SELECT reconciled INTO v_again FROM finance.legacy_gst_apply(imp);
        SELECT state, source, legacy_reference, paid_at::date INTO v_after, v_source, v_legacy_ref, v_paid_at FROM finance.gst_entitlement(sa, '9993/9994');
        SELECT state INTO v_prev FROM finance.gst_entitlement(sa, '9992/9993');
        v_gate := registration.gst_gate(sa, '9993/9994', 'GST 993');
        SELECT reconciled INTO v_ledger FROM finance.legacy_gst_apply(imp);
        SELECT count(*) INTO v_ledger FROM finance.payment_reference WHERE student_id = sa AND purpose LIKE 'GST fee %' AND confirmed_at IS NOT NULL;
        -- the officer: a row whose number names A cannot be moved onto B; C's row is relabelled from the school-fees row, one ledger row not two
        BEGIN
            PERFORM finance.legacy_gst_resolve((SELECT id FROM finance.legacy_gst_payment WHERE source_transaction_id = 'CHK-TX2'), 'MATCH', sa, 'guessing');
            v_steal := 'allowed';
        EXCEPTION WHEN check_violation THEN v_steal := split_part(SQLERRM, ':', 1); END;
        SELECT status INTO v_relabel FROM finance.legacy_gst_resolve((SELECT id FROM finance.legacy_gst_payment WHERE source_transaction_id = 'CHK-TX5'), 'RELABEL', NULL, 'the narration says GST');
        SELECT purpose INTO v_purpose FROM finance.payment_reference WHERE reference = 'MOAUM-LEG-CHK930003-9993-9994';
        SELECT * INTO v_sum FROM finance.legacy_gst_summary(imp, NULL);
        RAISE EXCEPTION 'the V323 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('An old-portal GST payment is staged once (the file''s repeat is counted, not staged), matched by the matriculation number at high confidence, judged against THAT session''s fee (15,000 last session, 20,000 this one), the failed and the refunded rejected, the same money as school fees held for review, a row nobody''s number carries left unmatched with name suggestions only, and the raw row written once',
        coalesce(v_dup_in_file = 1 AND v_matched = 6 AND v_tx1 = 'MATCHED/-/MATRIC_NO/20000.00' AND v_tx2 = 'REJECTED/PAYMENT_FAILED' AND v_tx3 = 'REJECTED/PAYMENT_REFUNDED'
                 AND v_tx4 = 'MATCHED/15000.00' AND v_tx5 = 'REQUIRES_REVIEW/POSSIBLE_RELABEL' AND v_tx6 = 'UNMATCHED/STUDENT_NOT_FOUND/1' AND v_written_once = 'LEGACY_PAYMENT_WRITTEN_ONCE', false),
        format('dup=%s matched=%s tx1=%s tx2=%s tx3=%s tx4=%s tx5=%s tx6=%s once=%s', v_dup_in_file, v_matched, v_tx1, v_tx2, v_tx3, v_tx4, v_tx5, v_tx6, v_written_once));
    PERFORM pg_temp.assert('Applied, the student reads PAID from the old portal with the old reference and the old date, the registration gate opens, last session''s payment stands for last session, a second apply writes nothing, a payment is never moved onto a student its number does not name, and the school-fees row is relabelled rather than doubled',
        coalesce(v_before = 'NOT_PAID' AND v_again = 2 AND v_after = 'PAID' AND v_source = 'LEGACY_PORTAL' AND v_legacy_ref = 'CHK-OLD-1' AND v_paid_at = date '9993-09-15' AND v_gate IS NULL AND v_prev = 'PAID'
                 AND v_ledger = 2 AND v_steal = 'LEGACY_IDENTIFIER_CONFLICT' AND v_relabel = 'RECONCILED' AND v_purpose = 'GST fee 9993/9994' AND v_sum.reconciled = 3 AND v_sum.rejected = 2 AND v_sum.unmatched = 1, false),
        format('before=%s applied=%s after=%s source=%s ref=%s paid=%s gate=%s prev=%s ledger=%s steal=%s relabel=%s purpose=%s sum=%s/%s/%s', v_before, v_again, v_after, v_source, v_legacy_ref, v_paid_at, v_gate, v_prev, v_ledger, v_steal, v_relabel, v_purpose, v_sum.reconciled, v_sum.rejected, v_sum.unmatched));
END $$;

-- ── 171. V324: a multiple-select question is marked by the examination's rule — all or nothing, or partial credit that never goes below zero ──
DO $$
DECLARE k int[] := ARRAY[1, 3];
BEGIN
    PERFORM pg_temp.assert('A multiple-select question earns its marks for exactly the key; with partial credit each right option earns a share and each wrong one costs a share, never below zero, and select-everything earns nothing; a single-answer question is never partial',
        assessment.cbt_marks_for('MULTI', k, ARRAY[1, 3], 2, false) = 2 AND assessment.cbt_marks_for('MULTI', k, ARRAY[1], 2, false) = 0
        AND assessment.cbt_marks_for('MULTI', k, ARRAY[1], 2, true) = 1 AND assessment.cbt_marks_for('MULTI', k, ARRAY[1, 2], 2, true) = 0
        AND assessment.cbt_marks_for('MULTI', k, ARRAY[0, 1, 2, 3], 2, true) = 0 AND assessment.cbt_marks_for('MULTI', ARRAY[0, 1, 2], ARRAY[0, 1], 3, true) = 2
        AND assessment.cbt_marks_for('MCQ', ARRAY[2], ARRAY[1], 1, true) = 0 AND assessment.cbt_marks_for('MCQ', ARRAY[2], ARRAY[2], 1, true) = 1
        AND assessment.cbt_marks_for('MULTI', k, NULL, 2, true) = 0,
        format('exact=%s off=%s half=%s mixed=%s all=%s two-of-three=%s mcq=%s/%s blank=%s',
               assessment.cbt_marks_for('MULTI', k, ARRAY[1, 3], 2, false), assessment.cbt_marks_for('MULTI', k, ARRAY[1], 2, false), assessment.cbt_marks_for('MULTI', k, ARRAY[1], 2, true),
               assessment.cbt_marks_for('MULTI', k, ARRAY[1, 2], 2, true), assessment.cbt_marks_for('MULTI', k, ARRAY[0, 1, 2, 3], 2, true), assessment.cbt_marks_for('MULTI', ARRAY[0, 1, 2], ARRAY[0, 1], 3, true),
               assessment.cbt_marks_for('MCQ', ARRAY[2], ARRAY[1], 1, true), assessment.cbt_marks_for('MCQ', ARRAY[2], ARRAY[2], 1, true), assessment.cbt_marks_for('MULTI', k, NULL, 2, true)));
END $$;

-- ── 172. V325: a bounded office is granted with its bound, and a desk explains the scope it reads ──
DO $$
DECLARE who uuid := gen_random_uuid(); r_kind text; r_blank text; s0 record; s1 record; s2 record; s3 record; v_live text := 'unset';
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'registrar', true);
        INSERT INTO iam.person (id, surname, given_names, staff_number) VALUES (who, 'CHECKBOUND', 'Invented', 'P-V325');
        -- a Head of Department over the University, and one over a department with none chosen: refused, the remedy in the hint
        BEGIN
            INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from)
            VALUES (gen_random_uuid(), who, 'hod', 'institution', NULL, 'check', who, current_date);
        EXCEPTION WHEN check_violation THEN r_kind := split_part(SQLERRM, ':', 1); END;
        BEGIN
            INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from)
            VALUES (gen_random_uuid(), who, 'hod', 'department', '  ', 'check', who, current_date);
        EXCEPTION WHEN check_violation THEN r_blank := split_part(SQLERRM, ':', 1); END;
        -- no live grant: the state says so
        SELECT * INTO s0 FROM iam.office_scope_state(who, 'hod');
        -- granted over a department by its name: the code is stored and the desk reads it through the grant
        INSERT INTO ref.department (code, name, faculty_code) VALUES ('ZZV325', 'CHECK DEPARTMENT V325', 'SC');
        INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from)
        VALUES (gen_random_uuid(), who, 'hod', 'department', 'check department v325', 'check', who, current_date);
        SELECT * INTO s1 FROM iam.office_scope_state(who, 'hod');
        -- the department ends: the grant no longer answers, and the state says why
        UPDATE ref.department SET ended_on = current_date - 1 WHERE code = 'ZZV325';
        SELECT * INTO s2 FROM iam.office_scope_state(who, 'hod');
        -- a lecturer grant over MTC: the desk reads MTC through it, and still says what is wrong with the office's own grant
        INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from)
        VALUES (gen_random_uuid(), who, 'lecturer', 'department', 'MTC', 'check', who, current_date);
        SELECT * INTO s3 FROM iam.office_scope_state(who, 'hod');
        v_live := iam.live_scope_code('department', 'ZZV325');
        RAISE EXCEPTION 'the V325 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('A bounded office is granted with its bound, chosen from the register, and a desk explains the scope it reads: no grant, the grant, the grant''s department ended, the lecturer grant answering instead',
        r_kind = 'OFFICE_SCOPE_REQUIRED' AND r_blank = 'OFFICE_SCOPE_REQUIRED'
        AND s0.bound_kind = 'department' AND s0.reason = 'NO_LIVE_GRANT' AND s0.resolved_code IS NULL
        AND s1.reason IS NULL AND s1.scope_id = 'ZZV325' AND s1.resolved_code = 'ZZV325' AND s1.source = 'OFFICE_GRANT'
        AND s2.reason = 'SCOPE_ENDED' AND s2.resolved_code IS NULL
        AND s3.reason = 'SCOPE_ENDED' AND s3.resolved_code = 'MTC' AND s3.source = 'LECTURER_GRANT'
        AND v_live IS NULL AND iam.acting_department(who, 'hod') IS NULL,
        format('refused=%s/%s none=%s/%s grant=%s/%s/%s/%s ended=%s/%s lecturer=%s/%s/%s live=%s',
               r_kind, r_blank, s0.reason, s0.resolved_code, s1.reason, s1.scope_id, s1.resolved_code, s1.source,
               s2.reason, s2.resolved_code, s3.reason, s3.resolved_code, s3.source, v_live));
END $$;

-- ── 173. V326: the Old Fees History import reads the old portal's payment item — a GST payment is the GST fee, a semester reads as First/Second, a row filed as school fees before is corrected, not doubled ──
DO $$
DECLARE who uuid := gen_random_uuid(); sd uuid := gen_random_uuid(); res record; again record;
        v_state text; v_source text; v_gst_ref text; v_gst_purpose text; v_school int; v_sems text; v_base_left int; v_other text; v_sem_words text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), '9995/9996', date '9995-10-01', date '9996-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (sd, 'MOAUM/ADM/95/000001', 'MOAUM/CHK/95/0001', 'ZZCHKLEGD', 'Invented', 'C00023', 'UTME', '9995/9996', 100, 100, 'ACTIVE', now());
        -- what an earlier upload of the same export left: the GST money as whole-session school fees, because the screen could not read the item
        INSERT INTO finance.payment_reference (student_id, session, reference, purpose, amount, expires_at, confirmed_at, confirmed_by, channel, receipt_no, note)
        VALUES (sd, '9995/9996', 'MOAUM-LEG-MOAUMCHK950001-9995-9996', 'School fees (legacy)', 4000, '9996-02-01', '9996-02-01', who, 'Legacy', 'LEG-MOAUM-LEG-MOAUMCHK950001-9995-9996', 'Imported from the old portal');
        -- the export, read with its item column
        SELECT * INTO res FROM finance.import_legacy_payments(jsonb_build_array(
            jsonb_build_object('matric', 'MOAUM/CHK/95/0001', 'session', '9995/9996', 'semester', 'First',   'amount', '4000',  'purpose', 'GST FEES',           'paidOn', '9996-02-01', 'receiptNo', '2019470000000001', 'channel', 'Interswitch'),
            jsonb_build_object('matric', 'MOAUM/CHK/95/0001', 'session', '9995/9996', 'semester', 'First',   'amount', '24510', 'purpose', 'SCHOOL FEES',        'paidOn', '9995-11-10', 'receiptNo', '2019470000000002', 'channel', 'Old Record'),
            jsonb_build_object('matric', 'MOAUM/CHK/95/0001', 'session', '9995/9996', 'semester', 'Second',  'amount', '24510', 'purpose', 'SCHOOL FEES',        'paidOn', '9996-03-02', 'receiptNo', '2019470000000003', 'channel', 'Old Record'),
            jsonb_build_object('matric', 'MOAUM/CHK/95/0001', 'session', '9995/9996', 'semester', 'Session', 'amount', '2000',  'purpose', 'ADMISSION CHECKING', 'paidOn', '9995-10-03', 'receiptNo', '2019470000000004', 'channel', 'Interswitch'),
            jsonb_build_object('matric', 'MOAUM/CHK/95/0001', 'session', '9995/9996', 'semester', 'First',   'amount', '4000',  'purpose', 'GST FEES',           'paidOn', '9996-02-01', 'receiptNo', '2019470000000001', 'channel', 'Interswitch')));   -- the same transaction listed twice
        SELECT state, source INTO v_state, v_source FROM finance.gst_entitlement(sd, '9995/9996');
        SELECT reference, purpose INTO v_gst_ref, v_gst_purpose FROM finance.payment_reference WHERE student_id = sd AND purpose LIKE 'GST fee %' ORDER BY reference LIMIT 1;
        SELECT count(*), string_agg(right(reference, 2), ',' ORDER BY reference) INTO v_school, v_sems FROM finance.payment_reference WHERE student_id = sd AND purpose LIKE 'School fees (legacy)%';
        SELECT count(*) INTO v_base_left FROM finance.payment_reference WHERE reference = 'MOAUM-LEG-MOAUMCHK950001-9995-9996';
        SELECT purpose INTO v_other FROM finance.payment_reference WHERE student_id = sd AND reference LIKE '%-ADMISSIONCHECKING';
        -- the same export again: nothing doubles, nothing is lost
        SELECT * INTO again FROM finance.import_legacy_payments(jsonb_build_array(
            jsonb_build_object('matric', 'MOAUM/CHK/95/0001', 'session', '9995/9996', 'semester', 'First',  'amount', '4000',  'purpose', 'GST FEES',    'paidOn', '9996-02-01'),
            jsonb_build_object('matric', 'MOAUM/CHK/95/0001', 'session', '9995/9996', 'semester', 'Second', 'amount', '24510', 'purpose', 'SCHOOL FEES', 'paidOn', '9996-03-02')));
        v_sem_words := finance.legacy_semester('First') || '/' || finance.legacy_semester('2nd') || '/' || finance.legacy_semester('Semester 1') || '/' || coalesce(finance.legacy_semester('Session')::text, 'whole') || '/' || coalesce(finance.legacy_semester('')::text, 'whole');
        RAISE EXCEPTION 'the V326 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('The Old Fees History import reads the payment item: a GST FEES row is the GST fee the gate counts (the row filed as school fees before is relabelled, not doubled), First/Second semesters each keep their school fees, another item is its own purpose, and the export loaded twice changes nothing',
        v_state = 'PAID' AND v_source = 'LEGACY_PORTAL'
        AND v_gst_ref = 'MOAUM-LEG-MOAUMCHK950001-9995-9996-S1-GST' AND v_gst_purpose = 'GST fee 9995/9996'
        AND v_school = 2 AND v_sems = 'S1,S2' AND v_base_left = 0
        AND v_other = 'ADMISSION CHECKING (legacy)'
        AND res.rows = 5 AND res.cleared = 3 AND res.corrected = 1 AND res.duplicates = 1
        AND again.cleared = 0 AND again.corrected = 0 AND again.duplicates = 2
        AND v_sem_words = '1/2/1/whole/whole',
        format('state=%s/%s gst=%s/%s school=%s/%s base_left=%s other=%s first=%s/%s/%s/%s again=%s/%s/%s sems=%s',
               v_state, v_source, v_gst_ref, v_gst_purpose, v_school, v_sems, v_base_left, v_other,
               res.cleared, res.corrected, res.duplicates, res.rows, again.cleared, again.corrected, again.duplicates, v_sem_words));
END $$;

-- ── 174. V327: the wallet keeps every naira to its source — a top-up only for the shortfall, the charge settled source by source, a refund only of the Fund's money that arrived after the fees were paid, never a grant ──
DO $$
DECLARE s1 uuid := gen_random_uuid(); s2 uuid := gen_random_uuid(); s3 uuid := gen_random_uuid(); who uuid := gen_random_uuid(); two uuid := gen_random_uuid(); three uuid := gen_random_uuid();
        e1 record; e2 record; e3 record; r_above text; r_none text; r_src text; r_nosrc text; r_over text; ref1 text; ref2 text; v_exp1 boolean; v_apply text; pos record;
        v_nel_applied numeric; v_self_applied numeric; v_avail numeric; w record; wd finance.wallet_withdrawal; v_nel_after numeric; v_grant numeric; v_bal numeric; v_refunded numeric; v_note text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at) VALUES
            (s1, 'MOAUM/ADM/99/990174', 'MOAUM/CHK/99/0174', 'CHECKSOURCE', 'Invented One', 'C00023', 'UTME', '9999/0000', 100, 100, 'ACTIVE', now()),
            (s2, 'MOAUM/ADM/99/990175', 'MOAUM/CHK/99/0175', 'CHECKSOURCE', 'Invented Two', 'C00023', 'UTME', '9999/0000', 100, 100, 'ACTIVE', now()),
            (s3, 'MOAUM/ADM/99/990176', 'MOAUM/CHK/99/0176', 'CHECKSOURCE', 'Invented Three', 'C00023', 'UTME', '9999/0000', 100, 100, 'ACTIVE', now());
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        -- a hand credit of no source is refused
        BEGIN PERFORM finance.credit_wallet(s3, '9999/0000', 10000, 'a credit from nowhere'); EXCEPTION WHEN check_violation THEN r_nosrc := split_part(SQLERRM, ':', 1); END;
        -- s1: the Fund remits 60,000 against a charge of 100,000 — the shortfall is 40,000, and a top-up is for exactly that
        PERFORM finance.credit_wallet(s1, '9999/0000', 60000, 'NELFUND remittance NLF/9999/174', 'NELFUND');
        SELECT * INTO e1 FROM finance.topup_eligibility(s1, '9999/0000');
        PERFORM set_config('moaum.actor_office', 'student', true);
        BEGIN ref1 := finance.wallet_topup_reference(s1, '9999/0000', 50000); EXCEPTION WHEN check_violation THEN r_above := split_part(SQLERRM, ':', 1); END;
        ref1 := finance.wallet_topup_reference(s1, '9999/0000', NULL);
        ref2 := finance.wallet_topup_reference(s1, '9999/0000', 40000);   -- a second request retires the first
        SELECT expires_at <= now() INTO v_exp1 FROM finance.payment_reference WHERE reference = ref1;
        SELECT note INTO v_note FROM finance.payment_reference WHERE reference = ref2;
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM finance.confirm_payment(ref2, 'WebPAY', 'check: the top-up paid');
        SELECT * INTO e2 FROM finance.topup_eligibility(s1, '9999/0000');
        PERFORM set_config('moaum.actor_office', 'student', true);
        BEGIN PERFORM finance.wallet_topup_reference(s1, '9999/0000', 1000); EXCEPTION WHEN check_violation THEN r_none := split_part(SQLERRM, ':', 1); END;
        -- applied: the loan first, then the student's own money; each source's share on its own entry
        v_apply := finance.apply_wallet(s1, '9999/0000', NULL);
        SELECT * INTO pos FROM finance.position(s1, '9999/0000');
        SELECT coalesce(sum(amount) FILTER (WHERE source_code = 'NELFUND'), 0), coalesce(sum(amount) FILTER (WHERE source_code = 'SELF'), 0)
          INTO v_nel_applied, v_self_applied FROM finance.wallet_entry WHERE student_id = s1 AND kind = 'APPLIED' AND reference = v_apply;
        SELECT coalesce(sum(available), 0) INTO v_avail FROM finance.wallet_balances(s1);
        SELECT * INTO e3 FROM finance.topup_eligibility(s1, '9998/9999');
        -- s2 pays the whole charge personally; then the Fund's 100,000 lands, and a 20,000 scholarship with it
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM finance.confirm_payment(finance.new_reference(s2, '9999/0000', 100000, NULL), 'WebPAY', 'check: paid personally');
        PERFORM finance.credit_wallet(s2, '9999/0000', 100000, 'NELFUND remittance NLF/9999/175', 'NELFUND');
        PERFORM finance.credit_wallet(s2, '9999/0000', 20000, 'State scholarship', 'SCHOLARSHIP');
        SELECT * INTO w FROM finance.withdrawal_eligibility(s2, '9999/0000');
        PERFORM set_config('moaum.actor_office', 'student', true);
        BEGIN PERFORM finance.request_withdrawal(s2, '9999/0000', 150000, 'Check Bank', '0123456789', 'CHECKSOURCE INVENTED TWO', 'NELFUND'); EXCEPTION WHEN check_violation THEN r_over := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM finance.request_withdrawal(s2, '9999/0000', 20000, 'Check Bank', '0123456789', 'CHECKSOURCE INVENTED TWO', 'SCHOLARSHIP'); EXCEPTION WHEN check_violation THEN r_src := split_part(SQLERRM, ':', 1); END;
        wd := finance.request_withdrawal(s2, '9999/0000', NULL, 'Check Bank', '0123456789', 'CHECKSOURCE INVENTED TWO', NULL);
        PERFORM set_config('moaum.actor_id', two::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        wd := finance.approve_withdrawal(wd.id);
        PERFORM set_config('moaum.actor_id', three::text, true);
        wd := finance.pay_withdrawal(wd.id, 'TRF-CHECK-174', (now() AT TIME ZONE 'Africa/Lagos')::date);
        SELECT coalesce(sum(available) FILTER (WHERE source_code = 'NELFUND'), 0), coalesce(sum(refunded) FILTER (WHERE source_code = 'NELFUND'), 0), coalesce(sum(available) FILTER (WHERE source_code = 'SCHOLARSHIP'), 0)
          INTO v_nel_after, v_refunded, v_grant FROM finance.wallet_balances(s2);
        v_bal := finance.wallet_balance(s2);
        RAISE EXCEPTION 'the V327 wallet check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('The wallet keeps every naira to its source: a top-up is refused above the shortfall and when nothing is short, an earlier top-up reference is retired, the charge settles loan first then own money on separate entries, a credit of no source is refused, and a refund is of the Fund''s money that arrived after the fees were paid — never the scholarship',
        r_nosrc = 'WALLET_SOURCE_REQUIRED'
        AND e1.allowed AND e1.reason = 'ALLOWED' AND e1.due = 100000 AND e1.outstanding = 100000 AND e1.wallet_available = 60000 AND e1.nelfund_available = 60000 AND e1.shortfall = 40000 AND e1.max_topup = 40000
        AND r_above = 'WALLET_TOPUP_ABOVE_SHORTFALL' AND ref1 LIKE 'MOAUM-FEE-%' AND v_exp1 AND v_note LIKE 'Shortfall top-up: fees 100000%'
        AND NOT e2.allowed AND e2.reason = 'NO_SHORTFALL' AND e2.wallet_available = 100000 AND r_none = 'WALLET_TOPUP_NOT_REQUIRED'
        AND pos.paid = 100000 AND pos.paid_in_full AND v_nel_applied = 60000 AND v_self_applied = 40000 AND v_avail = 0
        AND NOT e3.allowed AND e3.reason = 'NO_CHARGE_STATED'
        AND w.eligible AND w.nelfund_refundable = 100000 AND w.self_refundable = 0 AND w.grant_held = 20000 AND w.nelfund_after_settlement
        AND r_over = 'WALLET_REFUND_ABOVE_REFUNDABLE' AND r_src = 'WALLET_REFUND_SOURCE'
        AND wd.state = 'PAID' AND wd.source_code = 'NELFUND' AND wd.amount = 100000
        AND v_nel_after = 0 AND v_refunded = 100000 AND v_grant = 20000 AND v_bal = 20000,
        format('nosrc=%s e1=%s/%s/%s/%s/%s above=%s exp1=%s note=%s e2=%s/%s none=%s pos=%s/%s applied=%s/%s avail=%s e3=%s w=%s/%s/%s/%s/%s over=%s src=%s wd=%s/%s/%s after=%s/%s/%s bal=%s',
               r_nosrc, e1.reason, e1.due, e1.wallet_available, e1.shortfall, e1.max_topup, r_above, v_exp1, left(v_note, 40), e2.reason, e2.wallet_available, r_none, pos.paid, pos.paid_in_full,
               v_nel_applied, v_self_applied, v_avail, e3.reason, w.eligible, w.nelfund_refundable, w.self_refundable, w.grant_held, w.nelfund_after_settlement, r_over, r_src,
               wd.state, wd.source_code, wd.amount, v_nel_after, v_refunded, v_grant, v_bal));
END $$;

-- ── 175. V327: the old portal's NELFUND payments are staged once, matched by identifiers never by name, posted to the wallet once for the session they name, and what cannot be reconciled waits for an officer ──
DO $$
DECLARE s5 uuid := gen_random_uuid(); s6 uuid := gen_random_uuid(); s7 uuid := gen_random_uuid(); who uuid := gen_random_uuid(); imp uuid; imp2 uuid; st record; st2 record; ap record; ap2 record;
        r1 text; r2 text; r3 text; r4 text; r5 text; v_cands int; v_credited numeric; v_session text; v_origin text; v_legacy_ref text; r_conflict text; rc4 finance.legacy_nelfund_reconciliation; ap3 record; v_s6 numeric; v_summary record;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), '9997/9998', date '9997-10-01', date '9998-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO people.student (id, admission_no, matric_no, jamb_reg_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at) VALUES
            (s5, 'MOAUM/ADM/97/000005', 'MOAUM/CHK/97/0005', '97000005ZB', 'ZZCHKNELA', 'Invented', 'C00023', 'UTME', '9997/9998', 100, 100, 'ACTIVE', now()),
            (s6, 'MOAUM/ADM/97/000006', 'MOAUM/CHK/97/0006', '97000006ZB', 'ZZCHKNELB', 'Invented', 'C00023', 'UTME', '9997/9998', 100, 100, 'ACTIVE', now()),
            (s7, 'MOAUM/ADM/97/000007', 'MOAUM/CHK/97/0007', '97000007ZB', 'ZZCHKNELC', 'Invented', 'C00023', 'UTME', '9997/9998', 100, 100, 'ACTIVE', now());
        imp := (finance.legacy_nelfund_new_import('nelfund-old.xlsx', '9997/9998', 'check')).id;
        SELECT * INTO st FROM finance.legacy_nelfund_stage(imp, jsonb_build_array(
            jsonb_build_object('reference', 'NEL-1', 'matric', 'MOAUM/CHK/97/0005', 'amount', '150,000.00', 'paidAt', '20/11/9997', 'session', '9997/9998', 'status', 'SUCCESS'),
            jsonb_build_object('reference', 'NEL-2', 'matric', 'MOAUM/CHK/97/0005', 'amount', '50000', 'paidAt', '9997-12-01', 'session', '9997/9998', 'status', 'FAILED'),
            jsonb_build_object('reference', 'NEL-3', 'matric', 'MOAUM/CHK/97/0006', 'jamb', '97000007ZB', 'amount', '80000', 'paidAt', '9997-12-02', 'session', '9997/9998', 'status', 'PAID'),
            jsonb_build_object('reference', 'NEL-4', 'name', 'ZZCHKNELB Invented', 'amount', '90000', 'paidAt', '9997-12-03', 'session', '9997/9998', 'status', 'SUCCESS'),
            jsonb_build_object('reference', 'NEL-5', 'matric', 'MOAUM/CHK/97/0005', 'amount', '70000', 'paidAt', '9998-03-01', 'status', 'SUCCESS'),
            jsonb_build_object('reference', 'NEL-1', 'matric', 'MOAUM/CHK/97/0005', 'amount', '150000', 'session', '9997/9998', 'status', 'SUCCESS')));
        PERFORM finance.legacy_nelfund_match(imp);
        PERFORM finance.legacy_nelfund_validate(imp);
        SELECT rc.status || '/' || coalesce(rc.reason_code, '-') || '/' || coalesce(rc.match_method, '-') INTO r1 FROM finance.legacy_nelfund_payment p JOIN finance.legacy_nelfund_reconciliation rc ON rc.payment_id = p.id WHERE p.source_reference = 'NEL-1';
        SELECT rc.status || '/' || coalesce(rc.reason_code, '-') INTO r2 FROM finance.legacy_nelfund_payment p JOIN finance.legacy_nelfund_reconciliation rc ON rc.payment_id = p.id WHERE p.source_reference = 'NEL-2';
        SELECT rc.status || '/' || coalesce(rc.reason_code, '-') INTO r3 FROM finance.legacy_nelfund_payment p JOIN finance.legacy_nelfund_reconciliation rc ON rc.payment_id = p.id WHERE p.source_reference = 'NEL-3';
        SELECT rc.status || '/' || coalesce(rc.reason_code, '-'), jsonb_array_length(coalesce(rc.candidates, '[]')) INTO r4, v_cands FROM finance.legacy_nelfund_payment p JOIN finance.legacy_nelfund_reconciliation rc ON rc.payment_id = p.id WHERE p.source_reference = 'NEL-4';
        SELECT rc.status || '/' || coalesce(p.session, '-') INTO r5 FROM finance.legacy_nelfund_payment p JOIN finance.legacy_nelfund_reconciliation rc ON rc.payment_id = p.id WHERE p.source_reference = 'NEL-5';
        SELECT * INTO ap FROM finance.legacy_nelfund_apply(imp);
        SELECT * INTO ap2 FROM finance.legacy_nelfund_apply(imp);   -- twice changes nothing
        SELECT rc.status || '/' || coalesce(rc.reason_code, '-') || '/' || coalesce(rc.match_method, '-') INTO r1 FROM finance.legacy_nelfund_payment p JOIN finance.legacy_nelfund_reconciliation rc ON rc.payment_id = p.id WHERE p.source_reference = 'NEL-1';
        SELECT rc.status || '/' || coalesce(p.session, '-') INTO r5 FROM finance.legacy_nelfund_payment p JOIN finance.legacy_nelfund_reconciliation rc ON rc.payment_id = p.id WHERE p.source_reference = 'NEL-5';
        SELECT coalesce(sum(credited), 0) INTO v_credited FROM finance.wallet_balances_session(s5, '9997/9998') WHERE source_code = 'NELFUND';
        SELECT e.session, e.origin, e.legacy_reference INTO v_session, v_origin, v_legacy_ref FROM finance.wallet_statement(s5) e WHERE e.legacy_reference = 'NEL-1';
        -- the same file again: nothing is staged twice
        imp2 := (finance.legacy_nelfund_new_import('nelfund-old.xlsx', '9997/9998', 'check again')).id;
        SELECT * INTO st2 FROM finance.legacy_nelfund_stage(imp2, jsonb_build_array(
            jsonb_build_object('reference', 'NEL-1', 'matric', 'MOAUM/CHK/97/0005', 'amount', '150000', 'session', '9997/9998', 'status', 'SUCCESS'),
            jsonb_build_object('reference', 'NEL-5', 'matric', 'MOAUM/CHK/97/0005', 'amount', '70000', 'session', '9997/9998', 'status', 'SUCCESS')));
        -- the officer: the ambiguous row cannot be moved past its identifiers; the name-only row is matched on evidence and then posted
        BEGIN PERFORM finance.legacy_nelfund_resolve((SELECT id FROM finance.legacy_nelfund_payment WHERE source_reference = 'NEL-3'), 'MATCH', s6, 'guessing'); EXCEPTION WHEN check_violation THEN r_conflict := split_part(SQLERRM, ':', 1); END;
        rc4 := finance.legacy_nelfund_resolve((SELECT id FROM finance.legacy_nelfund_payment WHERE source_reference = 'NEL-4'), 'MATCH', s6, 'identity confirmed with the old portal''s receipt in hand');
        SELECT * INTO ap3 FROM finance.legacy_nelfund_apply(imp);
        SELECT coalesce(sum(credited), 0) INTO v_s6 FROM finance.wallet_balances_session(s6, '9997/9998') WHERE source_code = 'NELFUND';
        SELECT * INTO v_summary FROM finance.legacy_nelfund_summary(imp, NULL);
        RAISE EXCEPTION 'the V327 legacy check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('Old-portal NELFUND payments are staged once (the file''s repeat and a second upload stage nothing), matched by identifiers only (a name is a suggestion, two students a review), a failed payment is never credited, a session is read from the row or its date and kept on the credit, posting is once, and an officer resolves on evidence but never past the identifiers',
        st.total_rows = 6 AND st.staged = 5 AND st.already_staged = 1
        AND r1 = 'POSTED/-/MATRIC_NO' AND r2 = 'REJECTED/PAYMENT_FAILED' AND r3 = 'REQUIRES_REVIEW/AMBIGUOUS_STUDENT' AND r4 = 'UNMATCHED/STUDENT_NOT_FOUND' AND v_cands = 1 AND r5 = 'POSTED/9997/9998'
        AND ap.posted = 2 AND ap.amount = 220000 AND ap2.posted = 0 AND v_credited = 220000 AND v_session = '9997/9998' AND v_origin = 'OLD_PORTAL' AND v_legacy_ref = 'NEL-1'
        AND st2.staged = 0 AND st2.already_staged = 2
        AND r_conflict = 'LEGACY_IDENTIFIER_CONFLICT' AND rc4.status = 'MATCHED' AND rc4.match_method = 'MANUAL' AND ap3.posted = 1 AND v_s6 = 90000
        AND v_summary.posted = 3 AND v_summary.rejected = 1 AND v_summary.requires_review = 1 AND v_summary.amount_posted = 310000,
        format('stage=%s/%s/%s r1=%s r2=%s r3=%s r4=%s/%s r5=%s apply=%s/%s again=%s credited=%s session=%s origin=%s ref=%s stage2=%s/%s conflict=%s rc4=%s/%s ap3=%s s6=%s summary=%s/%s/%s/%s',
               st.total_rows, st.staged, st.already_staged, r1, r2, r3, r4, v_cands, r5, ap.posted, ap.amount, ap2.posted, v_credited, v_session, v_origin, v_legacy_ref, st2.staged, st2.already_staged,
               r_conflict, rc4.status, rc4.match_method, ap3.posted, v_s6, v_summary.posted, v_summary.rejected, v_summary.requires_review, v_summary.amount_posted));
END $$;

-- ── 176. V328: the support desk across the University — a ticket routed to its queue and to the posted agent who covers it, scope enforced, a transfer that never duplicates, an escalation only to the queue's office, a wait ended by the requester's reply, and no ticket left with an agent who is gone ──
DO $$
DECLARE who uuid := gen_random_uuid(); head uuid := gen_random_uuid(); a uuid := gen_random_uuid(); b uuid := gen_random_uuid(); c uuid := gen_random_uuid(); bur uuid := gen_random_uuid();
        s1 uuid := gen_random_uuid(); s2 uuid := gen_random_uuid(); t1 uuid; t2 uuid; t3 uuid; prog text; msg text;
        q1 text; a1 uuid; q2 text; a2 uuid; q3 text; a3 uuid; v_scope text; r_noreason text; q1b text; a1b uuid; n_tickets int; r_office text; st3 text; o3 text;
        r_notoffice text; st3b text; o3b uuid; n_internal int; st2 text; w2 boolean; st2b text; w2b boolean; n_swept int; st2c text; a2c uuid; n_off int; n_c int;
        v_hours numeric; ev text; n_queues int; n_rules int; n_offices int;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'ict', true);
        SELECT code INTO prog FROM ref.programme ORDER BY code LIMIT 1;
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (head, 'MOAUM/CHK/0176', 'CHECKHEAD', 'Desk'), (a, 'MOAUM/CHK/0177', 'CHECKAGENT', 'Faculty'),
               (b, 'MOAUM/CHK/0178', 'CHECKAGENT', 'Global'), (c, 'MOAUM/CHK/0179', 'CHECKAGENT', 'Bursary'), (bur, 'MOAUM/CHK/0180', 'CHECKBURSAR', 'Office');
        INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from) VALUES
            (gen_random_uuid(), head, 'helpdeskhead', 'platform', NULL, 'check', who, current_date),
            (gen_random_uuid(), a, 'ictagent', 'platform', NULL, 'check', who, current_date),
            (gen_random_uuid(), b, 'ictagent', 'platform', NULL, 'check', who, current_date),
            (gen_random_uuid(), c, 'ictagent', 'platform', NULL, 'check', who, current_date),
            (gen_random_uuid(), bur, 'bursar', 'platform', NULL, 'check', who, current_date);
        INSERT INTO helpdesk.agent_assignment (person_id, queue_code, scope_kind, scope_ref, assigned_by, reason) VALUES
            (a, 'ICT_SUPPORT', 'FACULTY', 'AC', head, 'check'), (b, 'ICT_SUPPORT', 'GLOBAL', NULL, head, 'check'), (c, 'BURSARY_SUPPORT', 'GLOBAL', NULL, head, 'check');
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (s1, 'MOAUM/ADM/97/970176', 'MOAUM/CHK/20/0176', 'CHECKDESK', 'One', prog, 'UTME', '2020/2021', 100, 300, 'ACTIVE', now()),
               (s2, 'MOAUM/ADM/97/970177', 'MOAUM/CHK/20/0177', 'CHECKDESK', 'Two', prog, 'UTME', '2020/2021', 100, 300, 'ACTIVE', now());
        SELECT count(*) INTO n_queues FROM helpdesk.queue WHERE active;
        SELECT count(*) INTO n_rules FROM helpdesk.routing_rule WHERE active;
        SELECT count(*) INTO n_offices FROM ref.office WHERE code = 'helpdeskhead';

        -- a login problem from the Faculty of Agriculture goes to the ICT Support queue and to the agent posted to that faculty, before the University-wide one
        t1 := helpdesk.submit('STUDENT', s1, 'CHECKDESK, One', 'MOAUM/CHK/20/0176', 'd1@example.edu', '08011111111', 'CSC', 'AC', 'LOGIN', 'Cannot log in', 'The portal says my password is wrong though I reset it.',
                              '{"account_type":"Student","username":"MOAUM/CHK/20/0176","error":"Password refused"}'::jsonb);
        q1 := helpdesk.route(t1);
        SELECT assigned_to INTO a1 FROM helpdesk.ticket WHERE id = t1;
        -- the same problem from another faculty goes to the University-wide agent
        t2 := helpdesk.submit('STUDENT', s2, 'CHECKDESK, Two', 'MOAUM/CHK/20/0177', 'd2@example.edu', '08022222222', 'ENG', 'ES', 'LOGIN', 'Cannot log in either', 'Same problem, another faculty.',
                              '{"account_type":"Student","username":"MOAUM/CHK/20/0177","error":"Password refused"}'::jsonb);
        q2 := helpdesk.route(t2);
        SELECT assigned_to INTO a2 FROM helpdesk.ticket WHERE id = t2;
        -- a payment problem goes to the Bursary's queue
        t3 := helpdesk.submit('STUDENT', s1, 'CHECKDESK, One', 'MOAUM/CHK/20/0176', 'd1@example.edu', '08011111111', 'CSC', 'AC', 'PAYMENT', 'Payment not reflecting', 'I paid on Monday and the portal still says unpaid.',
                              '{"payment_reference":"MOAUM-X","payment_date":"2020-01-01","payment_type":"School fees","amount":"50000"}'::jsonb);
        q3 := helpdesk.route(t3);
        SELECT assigned_to INTO a3 FROM helpdesk.ticket WHERE id = t3;
        -- scope: the faculty agent sees their faculty's ticket, not the other faculty's nor the Bursary's; the Bursary agent the converse; the Head everything
        v_scope := format('%s%s%s%s%s%s', helpdesk.can_view(a, t1), helpdesk.can_view(a, t2), helpdesk.can_view(a, t3), helpdesk.can_view(c, t3), helpdesk.can_view(c, t1),
                          helpdesk.can_view(head, t1) AND helpdesk.can_view(head, t2) AND helpdesk.can_view(head, t3));
        -- a transfer says why, moves the same ticket, and routes it to an agent of the new queue
        BEGIN PERFORM helpdesk.transfer(t1, 'BURSARY_SUPPORT', head, ''); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_noreason := split_part(msg, ':', 1); END;
        PERFORM helpdesk.transfer(t1, 'BURSARY_SUPPORT', head, 'It is a payment problem after all');
        SELECT queue_code, assigned_to INTO q1b, a1b FROM helpdesk.ticket WHERE id = t1;
        SELECT count(*) INTO n_tickets FROM helpdesk.ticket WHERE requester_id = s1 AND category_id = (SELECT id FROM helpdesk.category WHERE code = 'LOGIN');
        -- an escalation goes only to the queue's office or the Director of ICT; the office answers, and only the office
        BEGIN PERFORM helpdesk.escalate_to_office(t3, 'academic', c, 'Please decide'); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_office := split_part(msg, ':', 1); END;
        PERFORM helpdesk.escalate_to_office(t3, 'bursar', c, 'The payment is on the bank statement but not the ledger; the Bursary decides');
        SELECT status, escalated_office INTO st3, o3 FROM helpdesk.ticket WHERE id = t3;
        BEGIN PERFORM helpdesk.office_answer(t3, a, 'I am not the Bursar', true); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_notoffice := split_part(msg, ':', 1); END;
        PERFORM helpdesk.office_answer(t3, bur, 'Matched to the ledger by the Bursary; tell the student the receipt is reissued.', true);
        SELECT status, assigned_to INTO st3b, o3b FROM helpdesk.ticket WHERE id = t3;
        SELECT count(*) INTO n_internal FROM helpdesk.ticket_comment WHERE ticket_id = t3 AND internal AND author_name LIKE '%(Bursar)';
        -- waiting on the requester ends with their reply
        PERFORM helpdesk.transition(t2, 'OPENED', 'AGENT', b, 'CHECKAGENT, Global', NULL);
        PERFORM helpdesk.transition(t2, 'IN_PROGRESS', 'AGENT', b, 'CHECKAGENT, Global', NULL);
        PERFORM helpdesk.transition(t2, 'WAITING_FOR_STUDENT', 'AGENT', b, 'CHECKAGENT, Global', 'Send a screenshot of the error');
        SELECT status, waiting_since IS NOT NULL INTO st2, w2 FROM helpdesk.ticket WHERE id = t2;
        PERFORM helpdesk.comment(t2, 'REQUESTER', s2, 'CHECKDESK, Two', false, 'Here is the screenshot, attached.');
        SELECT status, waiting_since IS NULL INTO st2b, w2b FROM helpdesk.ticket WHERE id = t2;
        -- an agent on leave holds nothing: the sweep returns their open ticket to the queue
        UPDATE helpdesk.agent_assignment SET availability = 'ON_LEAVE' WHERE person_id = b;
        SELECT count(*) INTO n_swept FROM helpdesk.sweep_inactive_agents();
        SELECT status, assigned_to INTO st2c, a2c FROM helpdesk.ticket WHERE id = t2;
        -- the Head takes an agent off the desk: every open ticket with them returns
        n_off := helpdesk.deactivate_agent(c, head, 'Transferred out of the ICT unit');
        SELECT count(*) INTO n_c FROM helpdesk.agent_assignment WHERE person_id = c AND active;
        -- a critical ticket is due within its own SLA
        PERFORM helpdesk.set_priority(t1, 'CRITICAL', head);
        v_hours := round(EXTRACT(EPOCH FROM (helpdesk.due_at(now(), 'CRITICAL') - now())) / 3600);
        SELECT string_agg(action, ',' ORDER BY at) INTO ev FROM helpdesk.ticket_event WHERE ticket_id = t1;
        RAISE EXCEPTION 'the V328 support desk check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('The support desk across the University: the Head of ICT Support Desk is an office, the queues and the routing rules are seeded, a ticket is routed to its queue and to the agent posted to its faculty before the University-wide one, a payment problem goes to the Bursary''s queue, an agent sees only what their postings cover and the Head everything, a transfer says why and moves the one ticket to an agent of the new queue, an escalation goes only to the queue''s office or the Director of ICT and only that office answers (internally, back to the agent), a wait on the requester ends with their reply, an agent on leave or taken off the desk holds nothing, and a critical ticket is due within its own hours',
        n_offices = 1 AND n_queues >= 11 AND n_rules >= 17
        AND q1 = 'ICT_SUPPORT' AND a1 = a AND q2 = 'ICT_SUPPORT' AND a2 = b AND q3 = 'BURSARY_SUPPORT' AND a3 = c
        AND v_scope = 'tfftft'
        AND r_noreason = 'HELPDESK_REASON_REQUIRED' AND q1b = 'BURSARY_SUPPORT' AND a1b = c AND n_tickets = 1
        AND r_office = 'HELPDESK_ESCALATION_OFFICE' AND st3 = 'WAITING_FOR_OFFICE' AND o3 = 'bursar' AND r_notoffice = 'HELPDESK_NOT_THE_OFFICE' AND st3b = 'IN_PROGRESS' AND o3b = c AND n_internal = 1
        AND st2 = 'WAITING_FOR_STUDENT' AND w2 AND st2b = 'IN_PROGRESS' AND w2b
        AND n_swept = 1 AND st2c = 'OPENED' AND a2c IS NULL
        AND n_off = 2 AND n_c = 0 AND v_hours = 4
        AND ev = 'SUBMITTED,ROUTED,ASSIGNED,TRANSFERRED,ASSIGNED,RETURNED,PRIORITY_CHANGED',
        format('offices=%s queues=%s rules=%s t1=%s/%s t2=%s/%s t3=%s/%s scope=%s noreason=%s transfer=%s/%s tickets=%s office=%s st3=%s/%s notoffice=%s after=%s/%s internal=%s wait=%s/%s reply=%s/%s swept=%s t2=%s/%s off=%s/%s hours=%s events=%s',
               n_offices, n_queues, n_rules, q1, a1 = a, q2, a2 = b, q3, a3 = c, v_scope, r_noreason, q1b, a1b = c, n_tickets, r_office, st3, o3, r_notoffice, st3b, o3b = c, n_internal,
               st2, w2, st2b, w2b, n_swept, st2c, a2c IS NULL, n_off, n_c, v_hours, ev));
END $$;

-- ── 177. V329: a course nothing carries is removed outright, with its offers and empty offerings; one a record carries is refused and ended instead ──
DO $$
DECLARE who uuid := gen_random_uuid(); v_dept text; v_prog text; v_sess text; v_off uuid; msg text;
        gone1 boolean; r_fk text; r_legacy text; kept2 boolean; o record; out2 text; out4 text; st2 text; gone4 boolean; n_offers int;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        SELECT d.code, p.code INTO v_dept, v_prog FROM ref.department d JOIN ref.programme p ON p.dept_code = d.code ORDER BY d.code, p.code LIMIT 1;
        SELECT name INTO v_sess FROM policy.academic_session ORDER BY starts_on DESC LIMIT 1;
        -- a bare course: removed outright, its programme offer with it
        PERFORM catalogue.create_course('ZZQ 901', 'Check removal one', 3, 1, 100, v_dept, 'Core');
        INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES ('ZZQ 901', v_prog, 100, 'Core');
        PERFORM catalogue.remove_course('ZZQ 901');
        gone1 := NOT EXISTS (SELECT 1 FROM catalogue.course WHERE code = 'ZZQ 901');
        SELECT count(*) INTO n_offers FROM catalogue.course_offer WHERE course_code = 'ZZQ 901';
        -- a course with a timetabled offering: refused by the key that carries it
        PERFORM catalogue.create_course('ZZQ 902', 'Check removal two', 3, 1, 100, v_dept, 'Core');
        v_off := gen_random_uuid();
        INSERT INTO catalogue.offering (id, course_code, session, semester) VALUES (v_off, 'ZZQ 902', v_sess, 1);
        INSERT INTO assessment.exam_timetable (offering_id, held_on, starts_at, ends_at, venue) VALUES (v_off, current_date + 30, '09:00', '11:00', 'Check Hall');
        BEGIN PERFORM catalogue.remove_course('ZZQ 902'); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_fk := msg; END;
        kept2 := EXISTS (SELECT 1 FROM catalogue.course WHERE code = 'ZZQ 902' AND state <> 'ENDED') AND EXISTS (SELECT 1 FROM catalogue.offering WHERE id = v_off);
        -- a course an old-portal result names by code: refused too
        PERFORM catalogue.create_course('ZZQ 903', 'Check removal three', 3, 1, 100, v_dept, 'Core');
        INSERT INTO assessment.legacy_result_holding (session, semester, matric, course_code, raw) VALUES (v_sess, 1, 'MOAUM/CHK/00/0177', 'ZZQ 903', '{}'::jsonb);
        BEGIN PERFORM catalogue.remove_course('ZZQ 903'); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_legacy := msg; END;
        -- the list: the carried one is ended, the bare one removed, each reported
        PERFORM catalogue.create_course('ZZQ 904', 'Check removal four', 3, 1, 100, v_dept, 'Core');
        FOR o IN SELECT * FROM catalogue.remove_or_end(ARRAY['ZZQ 902', 'ZZQ 904']) LOOP
            IF o.code = 'ZZQ 902' THEN out2 := o.outcome; ELSIF o.code = 'ZZQ 904' THEN out4 := o.outcome; END IF;
        END LOOP;
        SELECT state INTO st2 FROM catalogue.course WHERE code = 'ZZQ 902';
        gone4 := NOT EXISTS (SELECT 1 FROM catalogue.course WHERE code = 'ZZQ 904');
        RAISE EXCEPTION 'the V329 removal check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('A course nothing carries is removed outright with its programme offer; one with a timetabled offering or an old-portal result is refused (COURSE_CARRIED) and kept whole; the list removes the bare and ends the carried, reporting each',
        gone1 AND n_offers = 0
        AND r_fk LIKE 'COURSE_CARRIED: ZZQ 902 is carried by the examination timetable%' AND kept2
        AND r_legacy LIKE 'COURSE_CARRIED: ZZQ 903 is named on 1 old-portal result%'
        AND out2 = 'ENDED' AND st2 = 'ENDED' AND out4 = 'REMOVED' AND gone4,
        format('gone1=%s offers=%s fk=%s kept2=%s legacy=%s out2=%s st2=%s out4=%s gone4=%s', gone1, n_offers, r_fk, kept2, r_legacy, out2, st2, out4, gone4));
END $$;

-- ── 178. V330: the level a student was at in a session is the registration's, else the enrolment's, else carried forward from entry — never today's level on a past record ──
DO $$
DECLARE who uuid := gen_random_uuid(); st uuid := gen_random_uuid(); prog text; s1 text; s2 text; s3 text; v_reg int; v_reg2 int; v_enrol int; v_carry int; v_now int; v_future int;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'registrar', true);
        SELECT code INTO prog FROM ref.programme ORDER BY code LIMIT 1;
        -- three consecutive sessions on the calendar, the earliest the entry session
        s1 := '2170/2171'; s2 := '2171/2172'; s3 := '2172/2173';
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on)
        VALUES (gen_random_uuid(), s1, '2170-10-01', '2171-09-30'), (gen_random_uuid(), s2, '2171-10-01', '2172-09-30'), (gen_random_uuid(), s3, '2172-10-01', '2173-09-30');
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (st, 'MOAUM/ADM/96/960178', 'MOAUM/CHK/20/0178', 'CHECKLEVEL', 'Student', prog, 'UTME', s1, 100, 300, 'ACTIVE', now());
        -- the register's own word: an approved registration at 100 level in the entry session; 200 in the next
        INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, submitted_at, approved_at, approved_by) VALUES (gen_random_uuid(), st, s1, 2, 100, 'APPROVED', now(), now(), who);
        INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, submitted_at, approved_at, approved_by) VALUES (gen_random_uuid(), st, s2, 1, 200, 'APPROVED', now(), now(), who);
        v_reg := people.level_in(st, s1, 2);
        v_reg2 := people.level_in(st, s2, 2);          -- the session's other semester reads the session's registration
        -- the third session has no registration: the enrolment answers
        INSERT INTO people.enrolment (id, student_id, session, level) VALUES (gen_random_uuid(), st, s3, 300);
        v_enrol := people.level_in(st, s3, 1);
        -- a session with neither: the entry level carried forward from the entry session
        DELETE FROM people.enrolment WHERE student_id = st;
        v_carry := people.level_in(st, s3, 1);
        -- the current level is the last resort only: a session before entry, with no record, falls to it
        v_now := (SELECT current_level FROM people.student WHERE id = st);
        RAISE EXCEPTION 'the V330 level check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('The level a student was at in a session is the registration''s (100 in the entry session, 200 the next, the session''s other semester reading the same), else the enrolment''s (300), else the entry level carried forward a session at a time (300), and never today''s level on a past record',
        v_reg = 100 AND v_reg2 = 200 AND v_enrol = 300 AND v_carry = 300 AND v_now = 300,
        format('reg=%s reg2=%s enrol=%s carry=%s now=%s', v_reg, v_reg2, v_enrol, v_carry, v_now));
END $$;

-- ── 179. V331: a student's standing is computed from the register, never from the matriculation year — a cancelled session merged carries its entrants, the Senate's award graduates, the programme's end with the record incomplete is spillover within the limit and review beyond it, and history is untouched ──
DO $$
DECLARE who uuid := gen_random_uuid(); prog text; a uuid := gen_random_uuid(); b uuid := gen_random_uuid(); c uuid := gen_random_uuid(); d uuid := gen_random_uuid(); e uuid := gen_random_uuid();
        r record; msg text; v uuid; k int; n_dec int;
        v_eff text; v_after text; v_elapsed int; r_cur text; r_merge text;
        pa record; pb record; pc record; pd record; pe record; dry record; wet record; c_status text; r_grad text; pe2 record; v_max int;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'registrar', true);
        UPDATE policy.academic_session SET state = 'CLOSED', completed_at = now() WHERE state = 'CURRENT';
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on, state) VALUES
          (gen_random_uuid(), '2169/2170', '2169-10-01', '2170-09-30', 'CLOSED'), (gen_random_uuid(), '2170/2171', '2170-10-01', '2171-09-30', 'CLOSED'),
          (gen_random_uuid(), '2171/2172', '2171-10-01', '2172-09-30', 'CLOSED'), (gen_random_uuid(), '2172/2173', '2172-10-01', '2173-09-30', 'CLOSED'),
          (gen_random_uuid(), '2173/2174', '2173-10-01', '2174-09-30', 'CLOSED'), (gen_random_uuid(), '2174/2175', '2174-10-01', '2175-09-30', 'CLOSED'),
          (gen_random_uuid(), '2175/2176', '2175-10-01', '2176-09-30', 'PLANNED'), (gen_random_uuid(), '2176/2177', '2176-10-01', '2177-09-30', 'PLANNED');
        UPDATE policy.academic_session SET state = 'CURRENT', made_current_at = now(), senate_minute = 'SEN/2175/01' WHERE name = '2175/2176';
        PERFORM policy.merge_session('2171/2172', '2172/2173', 'Session cancelled by Senate; cohort merged', 'SEN/2172/04');
        v_eff := policy.effective_session('2171/2172'); v_after := policy.session_after('2172/2173', 3); v_elapsed := policy.sessions_elapsed('2172/2173', '2175/2176');
        BEGIN UPDATE policy.academic_session SET state = 'CURRENT' WHERE name = '2171/2172'; EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_cur := split_part(msg, ':', 1); END;
        BEGIN PERFORM policy.merge_session('2175/2176', '2176/2177', 'x', NULL); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_merge := split_part(msg, ':', 1); END;
        SELECT code INTO prog FROM ref.programme WHERE final_level = 400 ORDER BY code LIMIT 1;
        -- A: entered in the cancelled session, matric /71/, four years, registered every session, 400 level and registered now
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (a, 'MOAUM/ADM/71/710179', 'MOAUM/CHK/71/000179', 'CHECKCOHORTA', 'Student', prog, 'UTME', '2171/2172', 100, 400, 'ACTIVE', now());
        INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, submitted_at, approved_at, approved_by) VALUES
          (gen_random_uuid(), a, '2172/2173', 1, 100, 'APPROVED', now(), now(), who), (gen_random_uuid(), a, '2175/2176', 1, 400, 'APPROVED', now(), now(), who);
        -- B: entered 2172/2173, matric /72/, enrolled now
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (b, 'MOAUM/ADM/72/720179', 'MOAUM/CHK/72/000179', 'CHECKCOHORTB', 'Student', prog, 'UTME', '2172/2173', 100, 400, 'ACTIVE', now());
        INSERT INTO people.enrolment (id, student_id, session, level) VALUES (gen_random_uuid(), b, '2175/2176', 400);
        -- C: entered 2170/2171, award approved by Senate, still ACTIVE on the record
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (c, 'MOAUM/ADM/70/700179', 'MOAUM/CHK/70/000179', 'CHECKCOHORTC', 'Student', prog, 'UTME', '2170/2171', 100, 400, 'ACTIVE', now());
        INSERT INTO records.graduand (id, student_id, session, cgpa, award, unmet, senate_state, senate_minute) VALUES (gen_random_uuid(), c, '2174/2175', 3.8, 'B.Sc.', NULL, 'APPROVED', 'SEN/2175/09');
        -- D: entered 2170/2171, no award, registered now: spillover year 1
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (d, 'MOAUM/ADM/70/700180', 'MOAUM/CHK/70/000180', 'CHECKCOHORTD', 'Student', prog, 'UTME', '2170/2171', 100, 400, 'ACTIVE', now());
        INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, submitted_at, approved_at, approved_by) VALUES (gen_random_uuid(), d, '2175/2176', 1, 400, 'APPROVED', now(), now(), who);
        -- E: entered 2169/2170, nothing since 2170/2171: beyond the limit once the limit is one
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (e, 'MOAUM/ADM/69/690179', 'MOAUM/CHK/69/000179', 'CHECKCOHORTE', 'Student', prog, 'UTME', '2169/2170', 100, 400, 'ACTIVE', now());
        INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, submitted_at, approved_at, approved_by) VALUES (gen_random_uuid(), e, '2170/2171', 1, 200, 'APPROVED', now(), now(), who);
        SELECT * INTO pa FROM people.academic_position WHERE student_id = a;
        SELECT * INTO pb FROM people.academic_position WHERE student_id = b;
        SELECT * INTO pc FROM people.academic_position WHERE student_id = c;
        SELECT * INTO pd FROM people.academic_position WHERE student_id = d;
        SELECT * INTO pe FROM people.academic_position WHERE student_id = e;
        -- the Senate's awards reconciled in bulk: counted first, then C graduated, nobody else moved
        SELECT * INTO dry FROM people.apply_cohort_rule('R1', NULL, 'CHK-179', true);
        SELECT * INTO wet FROM people.apply_cohort_rule('R1', NULL, 'CHK-179', false);
        SELECT status INTO c_status FROM people.student WHERE id = c;
        -- nobody is graduated by hand; a decision on evidence is recorded; a cohort corrected on evidence moves the expected completion
        BEGIN PERFORM people.decide_cohort(d, 'GRADUATED', 'He must have finished'); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_grad := split_part(msg, ':', 1); END;
        v := people.decide_cohort(d, 'ACTIVE', 'Spillover confirmed: two courses outstanding, registered this session', 'CHK-179');
        SELECT count(*) INTO n_dec FROM people.cohort_decision WHERE student_id = d AND batch_ref = 'CHK-179';
        PERFORM policy.set_max_spillover(1);
        SELECT * INTO pe2 FROM people.academic_position WHERE student_id = e;
        PERFORM people.set_cohort_override(e, '2173/2174', 'Re-admitted into 200 level in 2173/2174 on the Senate list');
        SELECT max_spillover_years INTO v_max FROM policy.progression_setting;
        SELECT count(*) INTO k FROM people.student WHERE surname LIKE 'CHECKCOHORT%' AND matric_no LIKE 'MOAUM/CHK/%' AND entry_session IN ('2169/2170','2170/2171','2171/2172','2172/2173');
        SELECT effective_cohort, cohort_source, expected_completion, spillover_years INTO r FROM people.academic_position WHERE student_id = e;
        RAISE EXCEPTION 'the V331 cohort check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('A student''s standing is computed from the register, never from the matriculation year: a cancelled session merged carries its entrants (A is ACTIVE at 400 in the merged cohort, expected to complete now, like B who entered the merged-into session), the Senate''s approved award graduates C in one counted act, D beyond the programme''s length with the record incomplete is a validated spillover student, E beyond the limit is for review, nobody is graduated by hand, a decision and a cohort correction are recorded, and every matriculation number and entry session stays',
        v_eff = '2172/2173' AND v_after = '2175/2176' AND v_elapsed = 3 AND r_cur = 'SESSION_CANCELLED' AND r_merge = 'SESSION_MERGE_CURRENT'
        AND pa.effective_cohort = '2172/2173' AND pa.cohort_source = 'MERGED' AND pa.jamb_year = 2171 AND pa.matric_year = 2071 AND pa.expected_completion = '2175/2176' AND pa.spillover_years = 0 AND pa.classification = 'ACTIVE' AND pa.rule = 'R3' AND pa.confidence = 'VALIDATED' AND pa.computed_level = 400
        AND pb.effective_cohort = '2172/2173' AND pb.cohort_source = 'ENTRY' AND pb.classification = 'ACTIVE' AND pb.expected_completion = '2175/2176'
        AND pc.classification = 'GRADUATED' AND pc.rule = 'R1' AND pc.confidence = 'VALIDATED' AND pc.proposed_status = 'GRADUATED' AND 'APPROVED_NOT_GRADUATED' = ANY(pc.issues)
        AND pd.classification = 'SPILLOVER' AND pd.spillover_years = 1 AND pd.spillover_state = 'SPILLOVER_YEAR_1' AND pd.confidence = 'VALIDATED' AND pd.proposed_status = 'ACTIVE'
        AND pe.classification = 'SPILLOVER' AND pe.spillover_years = 2 AND pe.confidence = 'LIKELY'
        AND dry.considered = 1 AND dry.applied = 0 AND wet.applied = 1 AND c_status = 'GRADUATED'
        AND r_grad = 'COHORT_GRADUATION_SENATE' AND n_dec = 1
        AND pe2.classification = 'SPILLOVER_LIMIT_REACHED' AND pe2.confidence = 'REVIEW' AND v_max = 1
        AND r.effective_cohort = '2173/2174' AND r.cohort_source = 'OVERRIDE' AND r.spillover_years = 0 AND r.expected_completion = '2176/2177'
        AND k = 5,
        format('eff=%s after=%s elapsed=%s cur=%s merge=%s | A=%s/%s/%s/%s/%s/%s/%s/%s | B=%s/%s/%s | C=%s/%s/%s/%s | D=%s/%s/%s/%s | E=%s/%s/%s | dry=%s/%s wet=%s c=%s grad=%s dec=%s | E2=%s/%s max=%s | over=%s/%s/%s/%s | kept=%s',
               v_eff, v_after, v_elapsed, r_cur, r_merge, pa.effective_cohort, pa.cohort_source, pa.jamb_year, pa.matric_year, pa.expected_completion, pa.spillover_years, pa.classification, pa.confidence,
               pb.effective_cohort, pb.classification, pb.expected_completion, pc.classification, pc.rule, pc.confidence, pc.proposed_status, pd.classification, pd.spillover_years, pd.spillover_state, pd.confidence,
               pe.classification, pe.spillover_years, pe.confidence, dry.considered, dry.applied, wet.applied, c_status, r_grad, n_dec, pe2.classification, pe2.confidence, v_max,
               r.effective_cohort, r.cohort_source, r.spillover_years, r.expected_completion, k));
END $$;

-- ── 180. V332: one course is offered to many programmes across departments without a second record — the owner's programme bound at once, another department's by its approval, the code renamed and the title edited with the identity and every binding kept, a binding ended kept on the record, and a structure upload binding another department's course without rewriting it ──
DO $$
DECLARE who uuid := gen_random_uuid(); d_a text; d_b text; p_a text; p_b text; v_id uuid; v_id2 uuid; v_id3 uuid; pr uuid; msg text;
        r_dup text; r_exists text; r_ended text; n_off int; n_off2 int; n_hist int; v_src text; v_out text; v_state text; n_prop int;
        v_title text; v_units int; v_basis text; imp record; v_new text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'registrar', true);
        -- two live departments in different faculties, each with an active programme
        SELECT d.code, p.code INTO d_a, p_a FROM ref.department d JOIN ref.programme p ON p.dept_code = d.code AND NOT coalesce(p.archived, false)
         WHERE d.ended_on IS NULL ORDER BY d.code, p.code LIMIT 1;
        SELECT d.code, p.code INTO d_b, p_b FROM ref.department d JOIN ref.programme p ON p.dept_code = d.code AND NOT coalesce(p.archived, false)
         WHERE d.ended_on IS NULL AND d.faculty_code <> (SELECT faculty_code FROM ref.department WHERE code = d_a) ORDER BY d.code, p.code LIMIT 1;
        PERFORM catalogue.create_course('ZZQ 332', 'Data Structures', 3, 1, 200, d_a, 'Core');
        SELECT id INTO v_id FROM catalogue.course WHERE code = 'ZZQ 332';
        PERFORM catalogue.bind_offer('ZZQ 332', p_a, 200, 'Core', NULL, 'COURSE');
        pr := catalogue.propose_offer('ZZQ 332', p_b, 200, 'Borrowed', NULL, 'Taken by the other programme', d_a);
        BEGIN PERFORM catalogue.propose_offer('ZZQ 332', p_b, 200, 'Borrowed', NULL, NULL, d_a); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_dup := split_part(msg, ':', 1); END;
        v_out := catalogue.decide_offer_proposal(pr, true, 'Approved at the board');
        SELECT count(*) INTO n_off FROM catalogue.course_offer WHERE course_code = 'ZZQ 332';
        SELECT source INTO v_src FROM catalogue.course_offer WHERE course_code = 'ZZQ 332' AND programme_code = p_b;
        BEGIN PERFORM catalogue.propose_offer('ZZQ 332', p_b, 200, 'Borrowed', NULL, NULL, d_a); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_exists := split_part(msg, ':', 1); END;
        -- the course edited and renamed is the same course; its bindings and its proposal follow
        PERFORM catalogue.update_course('ZZQ 332', 'Data Structures and Algorithms', 4, 1, 200, 'Core');
        v_new := catalogue.rename_course('ZZQ 332', 'zzq333');
        SELECT id, title, units INTO v_id2, v_title, v_units FROM catalogue.course WHERE code = v_new;
        SELECT count(*) INTO n_off2 FROM catalogue.course_offer WHERE course_code = v_new;
        SELECT count(*) INTO n_prop FROM catalogue.offer_proposal WHERE course_code = v_new AND state = 'APPROVED';
        -- a binding ended is kept on the record; an ended course is not offered
        v_state := catalogue.unbind_offer(v_new, p_b, 200, 'Dropped from the structure');
        SELECT count(*) INTO n_hist FROM catalogue.course_offer_history WHERE course_code = v_new AND programme_code = p_b;
        PERFORM catalogue.end_course(v_new);
        BEGIN PERFORM catalogue.bind_offer(v_new, p_b, 200, 'Borrowed', NULL, 'COURSE'); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_ended := split_part(msg, ':', 1); END;
        -- a structure upload that names another department's course binds it, and leaves its title and units to its owner
        PERFORM catalogue.create_course('ZZQ 334', 'Owned Elsewhere', 2, 2, 300, d_a, 'Core');
        SELECT * INTO imp FROM catalogue.import_courses(p_b, jsonb_build_array(jsonb_build_object('code', 'ZZQ 334', 'title', 'Rewritten Title', 'units', '9', 'level', '300', 'semester', '2', 'status', 'C')), NULL);
        SELECT title, units INTO v_title, v_units FROM catalogue.course WHERE code = 'ZZQ 334';
        SELECT basis INTO v_basis FROM catalogue.course_offer WHERE course_code = 'ZZQ 334' AND programme_code = p_b;
        SELECT id INTO v_id3 FROM catalogue.course WHERE code = 'ZZQ 334';
        RAISE EXCEPTION 'the V332 offering check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('One course is offered to many programmes across departments without a second record: the owner''s programme bound at once, another department''s by its approval (a repeat proposal and a proposal of what is offered refused), the code renamed and the title edited with the identity and both bindings kept, a binding ended kept on the record, an ended course refused, and a structure upload binding another department''s course as Borrowed without rewriting it',
        d_a IS NOT NULL AND d_b IS NOT NULL AND d_a <> d_b
        AND r_dup = 'CAT_PROPOSAL_PENDING' AND v_out = 'APPROVED' AND n_off = 2 AND v_src = 'PROPOSAL' AND r_exists = 'CAT_OFFER_EXISTS'
        AND v_new = 'ZZQ 333' AND v_id2 = v_id AND n_off2 = 2 AND n_prop = 1
        AND v_state = 'REMOVED' AND n_hist = 1 AND r_ended = 'CAT_ENDED'
        AND imp.existing = 1 AND imp.courses = 0 AND imp.offers = 1 AND v_title = 'Owned Elsewhere' AND v_units = 2 AND v_basis = 'Borrowed' AND v_id3 IS NOT NULL,
        format('depts=%s/%s dup=%s decided=%s offers=%s src=%s exists=%s | renamed=%s same_id=%s offers2=%s prop=%s | unbind=%s hist=%s ended=%s | import existing=%s courses=%s offers=%s title=%s units=%s basis=%s',
               d_a, d_b, r_dup, v_out, n_off, v_src, r_exists, v_new, (v_id2 = v_id), n_off2, n_prop, v_state, n_hist, r_ended, imp.existing, imp.courses, imp.offers, v_title, v_units, v_basis));
END $$;

-- ── 181. V333: a course code written without its hyphen is corrected in place — proposed from the known prefixes, renamed where the corrected code is free with the identity and every binding kept, left where the corrected code is another course already, and a code of neither form refused ──
DO $$
DECLARE who uuid := gen_random_uuid(); d_a text; p_a text; msg text; v_id uuid; v_id2 uuid; n_fix int; v_prop text; v_twin boolean; r_bad text; r_taken text;
        n_renamed int; n_twin int; n_off int; v_norm1 text; v_norm2 text; v_norm3 text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'registrar', true);
        SELECT d.code, p.code INTO d_a, p_a FROM ref.department d JOIN ref.programme p ON p.dept_code = d.code AND NOT coalesce(p.archived, false)
         WHERE d.ended_on IS NULL ORDER BY d.code, p.code LIMIT 1;
        -- uploaded as the old portal wrote them: the hyphen dropped (V386: the pool now refuses a twin, so the old data is made as it was)
        ALTER TABLE catalogue.course DISABLE TRIGGER trg_course_code_guard;
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state) VALUES
          ('MOAUCHM 181', 'Physical Chemistry I', 3, 1, 100, d_a, 'Core', 'LIVE'),
          ('BSUGEO 181', 'Map Reading', 2, 2, 100, d_a, 'Core', 'LIVE'),
          ('BSU-GEO 181', 'Map Reading', 2, 2, 100, d_a, 'Core', 'LIVE');
        ALTER TABLE catalogue.course ENABLE TRIGGER trg_course_code_guard;
        PERFORM catalogue.bind_offer('MOAUCHM 181', p_a, 100, 'Core', NULL, 'IMPORT');
        SELECT id INTO v_id FROM catalogue.course WHERE code = 'MOAUCHM 181';
        SELECT count(*) INTO n_fix FROM catalogue.code_fixes(d_a) WHERE code IN ('MOAUCHM 181', 'BSUGEO 181');
        SELECT proposed INTO v_prop FROM catalogue.code_fixes(d_a) WHERE code = 'MOAUCHM 181';
        SELECT twin_exists INTO v_twin FROM catalogue.code_fixes(d_a) WHERE code = 'BSUGEO 181';
        SELECT count(*) FILTER (WHERE outcome = 'RENAMED'), count(*) FILTER (WHERE outcome = 'TWIN_EXISTS') INTO n_renamed, n_twin
          FROM catalogue.apply_code_fixes(d_a) WHERE code IN ('MOAUCHM 181', 'BSUGEO 181');
        SELECT id INTO v_id2 FROM catalogue.course WHERE code = 'MOAU-CHM 181';
        SELECT count(*) INTO n_off FROM catalogue.course_offer WHERE course_code = 'MOAU-CHM 181';
        BEGIN PERFORM catalogue.rename_course('BSUGEO 181', 'bad code!'); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_bad := split_part(msg, ':', 1); END;
        BEGIN PERFORM catalogue.rename_course('BSUGEO 181', 'BSU-GEO 181'); EXCEPTION WHEN unique_violation THEN r_taken := 'TAKEN'; END;
        v_norm1 := catalogue.normal_code('moau - chm  101'); v_norm2 := catalogue.normal_code('csc311'); v_norm3 := catalogue.normal_code('CSC 309/CMP 441');
        RAISE EXCEPTION 'the V333 code-fix check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('A course code written without its hyphen is corrected in place: proposed from the known prefixes, renamed where the corrected code is free with the identity and the binding kept, left as a twin where the corrected code is another course already, a code of neither form refused, and every accepted form normalised',
        n_fix = 2 AND v_prop = 'MOAU-CHM 181' AND v_twin = true AND n_renamed = 1 AND n_twin = 1 AND v_id2 = v_id AND n_off = 1
        AND r_bad = 'CAT_CODE' AND r_taken = 'TAKEN' AND v_norm1 = 'MOAU-CHM 101' AND v_norm2 = 'CSC 311' AND v_norm3 = 'CSC 309/CMP 441',
        format('fixes=%s proposed=%s twin=%s renamed=%s twins=%s same_id=%s offers=%s bad=%s taken=%s norm=%s/%s/%s',
               n_fix, v_prop, v_twin, n_renamed, n_twin, (v_id2 = v_id), n_off, r_bad, r_taken, v_norm1, v_norm2, v_norm3));
END $$;

-- ── 182. V334: a support agent reaches the students their postings' scopes cover and does only what the Head granted — a posting carries only known capabilities, a person's are the union of their live postings', an office-scoped posting reaches no student, and every support act is written with its reason and filed on the ticket named ──
DO $$
DECLARE who uuid := gen_random_uuid(); agent uuid; d_a text; p_a text; f_a text; d_b text; p_b text; st_a uuid := gen_random_uuid(); st_b uuid := gen_random_uuid();
        q text; msg text; r_caps text; sees_a boolean; sees_b boolean; sees_none boolean; caps text[]; words text; r_reason text; v_act uuid; n_ev int; n_act int; v_ins boolean;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'helpdeskhead', true);
        SELECT d.code, p.code, d.faculty_code INTO d_a, p_a, f_a FROM ref.department d JOIN ref.programme p ON p.dept_code = d.code AND NOT coalesce(p.archived, false) WHERE d.ended_on IS NULL ORDER BY d.code, p.code LIMIT 1;
        SELECT d.code, p.code INTO d_b, p_b FROM ref.department d JOIN ref.programme p ON p.dept_code = d.code AND NOT coalesce(p.archived, false)
         WHERE d.ended_on IS NULL AND d.faculty_code <> f_a ORDER BY d.code, p.code LIMIT 1;
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at) VALUES
          (st_a, 'MOAUM/ADM/82/820182', 'MOAUM/CHK/82/000182', 'CHECKSUPPORTA', 'Student', p_a, 'UTME', '2082/2083', 100, 100, 'ACTIVE', now()),
          (st_b, 'MOAUM/ADM/82/820183', 'MOAUM/CHK/82/000183', 'CHECKSUPPORTB', 'Student', p_b, 'UTME', '2082/2083', 100, 100, 'ACTIVE', now());
        INSERT INTO iam.person (id, surname, given_names) VALUES (gen_random_uuid(), 'CHECKAGENT', 'Support') RETURNING id INTO agent;
        SELECT code INTO q FROM helpdesk.queue WHERE active ORDER BY ordinal LIMIT 1;
        -- a posting carries only known capabilities
        BEGIN
            INSERT INTO helpdesk.agent_assignment (person_id, queue_code, scope_kind, scope_ref, capabilities) VALUES (agent, q, 'FACULTY', f_a, ARRAY['VIEW_STUDENT', 'DELETE_EVERYTHING']);
        EXCEPTION WHEN check_violation THEN r_caps := 'REFUSED';
        END;
        -- an office-scoped posting reaches no student; a faculty posting reaches its own students
        INSERT INTO helpdesk.agent_assignment (person_id, queue_code, scope_kind, scope_ref, capabilities) VALUES (agent, q, 'OFFICE', 'bursar', ARRAY['VIEW_STUDENT']);
        sees_none := helpdesk.agent_may_see_student(agent, st_a);
        INSERT INTO helpdesk.agent_assignment (person_id, queue_code, scope_kind, scope_ref, capabilities) VALUES (agent, q, 'FACULTY', f_a, ARRAY['VIEW_STUDENT', 'EDIT_CONTACT']);
        INSERT INTO helpdesk.agent_assignment (person_id, queue_code, scope_kind, scope_ref, capabilities, effective_from, effective_to) VALUES (agent, q, 'DEPARTMENT', d_b, ARRAY['MANAGE_REGISTRATION'], current_date - 10, current_date - 1);
        sees_a := helpdesk.agent_may_see_student(agent, st_a);
        sees_b := helpdesk.agent_may_see_student(agent, st_b);
        caps := helpdesk.agent_capabilities(agent);
        SELECT s.words INTO words FROM helpdesk.agent_student_scope(agent) s;
        -- a support act says why, and is filed on the ticket named
        PERFORM set_config('moaum.actor_id', agent::text, true);
        PERFORM set_config('moaum.actor_office', 'ictagent', true);
        BEGIN PERFORM helpdesk.record_support_action(st_a, NULL, 'CONTACT_EDITED', 'mobile', '08011111111', '08022222222', '  '); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_reason := split_part(msg, ':', 1); END;
        v_act := helpdesk.record_support_action(st_a, NULL, 'CONTACT_EDITED', 'mobile', '08011111111', '08022222222', 'The student reported a wrong number');
        SELECT count(*) INTO n_act FROM helpdesk.support_action WHERE student_id = st_a AND agent_id = agent AND action = 'CONTACT_EDITED';
        v_ins := EXISTS (SELECT 1 FROM people.student_photo WHERE student_id = st_a);
        INSERT INTO people.student_photo (student_id, content, content_type, bytes, replaced_by, reason) VALUES (st_a, '\x00'::bytea, 'image/jpeg', 1, agent, 'replaced');
        SELECT count(*) INTO n_ev FROM people.student_photo WHERE student_id = st_a;
        RAISE EXCEPTION 'the V334 support check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('A support agent reaches the students their postings'' scopes cover and does only what the Head granted: a posting with an unknown capability is refused, an office-scoped posting reaches no student, a faculty posting reaches its own student and not another faculty''s, a person''s capabilities are the union of their live postings'' (an ended posting counts for nothing), the scope reads in words, a support act without a reason is refused and one with it is on the ledger, and a replacement photograph is kept',
        r_caps = 'REFUSED' AND sees_none = false AND sees_a = true AND sees_b = false AND caps = ARRAY['EDIT_CONTACT', 'VIEW_STUDENT'] AND words IS NOT NULL
        AND r_reason = 'SUPPORT_REASON' AND v_act IS NOT NULL AND n_act = 1 AND v_ins = false AND n_ev = 1,
        format('caps_refused=%s none=%s a=%s b=%s caps=%s words=%s reason=%s act=%s n=%s photo=%s/%s', r_caps, sees_none, sees_a, sees_b, caps, words, r_reason, v_act IS NOT NULL, n_act, v_ins, n_ev));
END $$;

-- ── 183. V337: the postgraduate lifecycle completed — the department decides a paid application, returns it for correction and decides again only when the School returns it; the School's word is final on a "not recommended"; a valid applicant checks once paid, the status the School's; screening holds an accepted applicant off the register until cleared, and clearance admits them; an endorsed postgraduate registration counts for matriculation ──
DO $$
DECLARE who uuid := gen_random_uuid(); prog text; fac text; appl uuid := gen_random_uuid(); app uuid := gen_random_uuid(); v_student uuid;
        msg text; r_unpaid text; r_note text; r_twice text; r_admit text; r_reason text; st_returned text; st_resub text; st_back text; st_final text;
        dept_cleared boolean; c record; c2 record; scr_open text; st_cleared text; ok_student boolean; registered boolean; kinds text[];
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'pgschool', true);
        INSERT INTO iam.person (id, surname, given_names) VALUES (who, 'CHECKPGDESK', 'Officer');
        SELECT p.code, p.faculty_code INTO prog, fac FROM ref.programme p WHERE p.category = 'POST GRADUATE' AND NOT coalesce(p.archived, false) AND p.dept_code IS NOT NULL ORDER BY p.code LIMIT 1;
        INSERT INTO admissions.pg_applicant (id, session, surname, other_names, email, password_hash, contact_address)
        VALUES (appl, '2083/2084', 'CHECKPGLIFE', 'Applicant', 'check.pglife@example.com', '$2a$12$checkcheckcheckcheckcheckcheckcheckcheckcheckcheckche', 'No. 1 Check Road');
        INSERT INTO admissions.pg_application (id, applicant_id, session, application_no, programme_code, entry_level, state, submitted_at)
        VALUES (app, appl, '2083/2084', 'PG/83/999183', prog, 800, 'SUBMITTED', now());

        -- the department decides a paid application only
        BEGIN PERFORM admissions.pg_dept_decide(app, true, NULL, who); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_unpaid := split_part(msg, ':', 1); END;
        UPDATE admissions.pg_application SET fee_confirmed_at = now() WHERE id = app;
        -- a return says what to correct; the applicant resubmits
        BEGIN PERFORM admissions.pg_dept_return(app, '  ', who); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_note := split_part(msg, ':', 1); END;
        PERFORM admissions.pg_dept_return(app, 'Upload the NYSC certificate', who);
        SELECT state INTO st_returned FROM admissions.pg_application WHERE id = app;
        PERFORM admissions.pg_resubmit(app);
        SELECT state INTO st_resub FROM admissions.pg_application WHERE id = app;
        -- not recommended: decided once; the School returns it, the department decides again, the School's word is final
        PERFORM admissions.pg_dept_decide(app, false, 'Weak', who);
        BEGIN PERFORM admissions.pg_dept_decide(app, true, NULL, who); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_twice := split_part(msg, ':', 1); END;
        PERFORM admissions.pg_school_return(app, 'Reconsider the HND', who);
        SELECT state, dept_decided_at IS NULL AND dept_note IS NULL INTO st_back, dept_cleared FROM admissions.pg_application WHERE id = app;
        PERFORM admissions.pg_dept_decide(app, false, NULL, who);
        -- before the School decides, a valid applicant may pay to check, and reads PENDING once paid
        SELECT * INTO c FROM admissions.pg_status_checking(app);
        PERFORM admissions.pg_spgs_decide(app, true, 'Offered on the School''s judgement', who);
        SELECT state INTO st_final FROM admissions.pg_application WHERE id = app;
        UPDATE admissions.pg_application SET checking_confirmed_at = now() WHERE id = app;
        SELECT * INTO c2 FROM admissions.pg_status_checking(app);

        -- the session screens: acceptance opens the screening; the register waits for clearance, which admits
        INSERT INTO admissions.pg_screening_policy (session, required, enabled_from, venue) VALUES ('2083/2084', true, now() - interval '1 minute', 'Check Hall');
        UPDATE admissions.pg_application SET acceptance_confirmed_at = now() WHERE id = app;
        UPDATE admissions.pg_application SET state = 'ACCEPTED', accepted_at = now() WHERE id = app;
        SELECT state INTO scr_open FROM admissions.pg_screening WHERE application_id = app;
        BEGIN PERFORM admissions.pg_admit(app); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_admit := split_part(msg, ':', 1); END;
        BEGIN PERFORM admissions.pg_screening_decide(app, 'NOT_CLEARED', NULL, NULL, NULL, NULL, ' ', who, 'pgsecretary'); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_reason := split_part(msg, ':', 1); END;
        PERFORM admissions.pg_screening_decide(app, 'CLEARED', ARRAY['First degree certificate'], NULL, NULL, 'Originals seen', NULL, who, 'pgsecretary');
        SELECT a.state, a.student_id INTO st_cleared, v_student FROM admissions.pg_application a WHERE a.id = app;
        ok_student := admissions.screening_ok_student(v_student);
        -- an endorsed postgraduate registration of the session is registration for matriculation
        INSERT INTO admissions.pg_registration (student_id, session, semester, mode, state, endorsed_at) VALUES (v_student, '2083/2084', 1, 'FULL_TIME', 'ENDORSED', now());
        SELECT m.registered INTO registered FROM people.matric_candidates('2083/2084', fac) m WHERE m.student_id = v_student;
        SELECT array_agg(kind ORDER BY at, kind) INTO kinds FROM admissions.pg_application_event WHERE application_id = app;
        RAISE EXCEPTION 'the V337 postgraduate lifecycle check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('The postgraduate lifecycle completed: the department decides only a paid application, returns one for correction with a note and the applicant resubmits it, decides once until the School returns it to them, and the School''s decision on a "not recommended" is final; a valid applicant may pay to check before any decision and reads the School''s status once paid; an accepted applicant of a screening session is screened, held off the register until cleared (a refusal needs its reason), and clearance admits them; an endorsed postgraduate registration counts for matriculation',
        r_unpaid = 'PG_FEE_UNCONFIRMED' AND r_note = 'PG_RETURN_NOTE_REQUIRED' AND st_returned = 'RETURNED' AND st_resub = 'SUBMITTED'
        AND r_twice = 'PG_NOT_WITH_DEPARTMENT' AND st_back = 'SUBMITTED' AND dept_cleared AND st_final = 'OFFERED'
        AND c.valid AND c.may_pay AND NOT c.may_check AND c.status = 'PENDING' AND c2.may_check AND c2.status = 'ADMITTED'
        AND scr_open = 'PENDING' AND r_admit = 'PG_SCREENING_NOT_CLEARED' AND r_reason = 'PG_SCREENING_REASON' AND st_cleared = 'ADMITTED'
        AND v_student IS NOT NULL AND ok_student AND registered
        AND kinds @> ARRAY['RETURNED', 'RESUBMITTED', 'RETURNED_TO_DEPARTMENT', 'SCREENING_PENDING', 'SCREENING_CLEARED', 'ADMITTED'],
        format('unpaid=%s note=%s returned=%s resub=%s twice=%s back=%s/%s final=%s check=%s/%s/%s/%s paid=%s/%s screening=%s admit=%s reason=%s cleared=%s student=%s ok=%s registered=%s kinds=%s',
               r_unpaid, r_note, st_returned, st_resub, r_twice, st_back, dept_cleared, st_final, c.valid, c.may_pay, c.may_check, c.status, c2.may_check, c2.status,
               scr_open, r_admit, r_reason, st_cleared, v_student IS NOT NULL, ok_student, registered, kinds));
END $$;

-- ── 184. V338 (the reset withdrawn by V340): the course catalogue — an upload makes ONE course per code with an offering per programme (CORE or ELECTIVE for each) and writes nothing while a row is invalid; a registered offering keeps its title; a re-upload updates the same course; an owner change is kept; no reset function remains ──
DO $$
DECLARE who uuid := gen_random_uuid(); st uuid := gen_random_uuid(); reg uuid := gen_random_uuid(); off uuid := gen_random_uuid();
        v_id uuid; v_id2 uuid; msg text; r_invalid text; r_owner text; n_courses int; n_offers int; basis_e text; r_res jsonb;
        n_entry int; title_off text; title_res text; st_back text; title_back text; n_owner int; owner_src text; no_reset boolean;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'ict', true);
        INSERT INTO iam.person (id, surname, given_names) VALUES (who, 'CHECKCATALOGUE', 'Officer');
        INSERT INTO ref.department (code, name, faculty_code) VALUES ('ZZC338', 'CHECK CATALOGUE ONE', 'SC'), ('ZZD338', 'CHECK CATALOGUE TWO', 'SC');
        INSERT INTO ref.programme (code, name, dept_code, faculty_code, min_score, category) VALUES
          ('C93381', 'CHECK PROGRAMME ONE', 'ZZC338', 'SC', 180, 'UNDER GRADUATE'),
          ('C93382', 'CHECK PROGRAMME TWO', 'ZZC338', 'SC', 180, 'UNDER GRADUATE'),
          ('C93383', 'CHECK PROGRAMME THREE', 'ZZD338', 'SC', 180, 'UNDER GRADUATE');
        -- an invalid row: nothing is written
        BEGIN
            PERFORM catalogue.import_catalogue(jsonb_build_array(
                jsonb_build_object('code', 'ZZX 338', 'title', 'Check Course', 'units', '3', 'level', '100', 'semester', '1', 'ownerDepartment', 'ZZC338', 'offeringProgramme', 'C93381', 'offeringType', 'CORE'),
                jsonb_build_object('code', 'ZZX 338', 'title', 'Check Course', 'units', '3', 'level', '100', 'semester', '1', 'ownerDepartment', 'ZZC338', 'offeringProgramme', 'C93382', 'offeringType', 'MAYBE')), true, 'check');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_invalid := split_part(msg, ':', 1);
        END;
        -- a valid file: one course, three offerings, an unused second course
        r_res := catalogue.import_catalogue(jsonb_build_array(
            jsonb_build_object('code', 'ZZX 338', 'title', 'Check Course', 'units', '3', 'level', '100', 'semester', '1', 'ownerDepartment', 'ZZC338', 'ownerProgramme', 'C93381', 'offeringProgramme', 'C93381', 'offeringType', 'CORE'),
            jsonb_build_object('code', 'ZZX 338', 'title', 'Check Course', 'units', '3', 'level', '100', 'semester', '1', 'ownerDepartment', 'ZZC338', 'ownerProgramme', 'C93381', 'offeringProgramme', 'C93382', 'offeringType', 'ELECTIVE'),
            jsonb_build_object('code', 'ZZX 338', 'title', 'Check Course', 'units', '3', 'level', '100', 'semester', '1', 'ownerDepartment', 'ZZC338', 'ownerProgramme', 'C93381', 'offeringProgramme', 'C93383', 'offeringType', 'CORE'),
            jsonb_build_object('code', 'ZZY 338', 'title', 'Check Unused', 'units', '2', 'level', '200', 'semester', '2', 'ownerDepartment', 'ZZC338', 'offeringProgramme', 'C93381', 'offeringType', 'CORE', 'prerequisite', 'ZZX 338')), true, 'check');
        SELECT count(*) INTO n_courses FROM catalogue.course WHERE code = 'ZZX 338';
        SELECT count(*) INTO n_offers FROM catalogue.course_offer WHERE course_code = 'ZZX 338';
        SELECT basis INTO basis_e FROM catalogue.course_offer WHERE course_code = 'ZZX 338' AND programme_code = 'C93382';
        SELECT id INTO v_id FROM catalogue.course WHERE code = 'ZZX 338';
        -- history on ZZX 338: a student registered on a session offering
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), '2083/2084', '2083-10-01', '2084-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status)
        VALUES (st, 'MOAUM/ADM/83/833380', 'CHECKCATALOGUE', 'Student', 'C93381', 'UTME', '2083/2084', 100, 100, 'ADMITTED');
        INSERT INTO catalogue.offering (id, course_code, session, semester) VALUES (off, 'ZZX 338', '2083/2084', 1);
        INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, submitted_at, approved_at) VALUES (reg, st, '2083/2084', 1, 100, 'APPROVED', now(), now());
        INSERT INTO registration.entry (registration_id, offering_id, units, entry_type, status) VALUES (reg, off, 3, 'CURRENT', 'APPROVED');
        -- a corrected title reaches the course; the registered offering keeps its own
        UPDATE catalogue.course SET title = 'Check Course Corrected' WHERE code = 'ZZX 338';
        SELECT title INTO title_off FROM catalogue.offering WHERE id = off;
        SELECT title INTO title_res FROM assessment.student_results(st) WHERE course_code = 'ZZX 338';
        -- the reset is withdrawn (V340): none of its functions remains
        no_reset := to_regprocedure('catalogue.course_reset(text,text,text,text)') IS NULL AND to_regprocedure('catalogue.course_reset_preview(text,text)') IS NULL
                    AND to_regprocedure('catalogue.reset_courses(text[],text[],text)') IS NULL AND to_regprocedure('catalogue.reset_scope(text,text)') IS NULL;
        -- a re-upload updates the same course; the registration on its offering is whole
        PERFORM catalogue.import_catalogue(jsonb_build_array(
            jsonb_build_object('code', 'ZZX 338', 'title', 'Check Course Again', 'units', '3', 'level', '100', 'semester', '1', 'ownerDepartment', 'ZZC338', 'offeringProgramme', 'C93381', 'offeringType', 'CORE')), true, 'check again');
        SELECT id, state, title INTO v_id2, st_back, title_back FROM catalogue.course WHERE code = 'ZZX 338';
        SELECT count(*) INTO n_entry FROM registration.entry WHERE offering_id = off;
        -- the owner moves, kept with its reason; an owner programme of another department is refused
        BEGIN PERFORM catalogue.change_owner('ZZX 338', 'ZZD338', 'C93381', 'wrong'); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_owner := split_part(msg, ':', 1); END;
        PERFORM catalogue.change_owner('ZZX 338', 'ZZD338', 'C93383', 'Taught by the second department');
        SELECT count(*), max(source) INTO n_owner, owner_src FROM catalogue.course_owner_history WHERE course_id = v_id AND to_dept = 'ZZD338';
        RAISE EXCEPTION 'the V338 catalogue check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('The course catalogue: an invalid upload writes nothing; a valid one makes one course per code with an offering per programme, Core or Elective for each; a registered offering keeps its title through a correction; a re-upload updates the same course, its registration whole; an owner change needs a programme of the new department and is kept; the withdrawn reset has no function left',
        r_invalid = 'CAT_IMPORT_INVALID' AND n_courses = 1 AND n_offers = 3 AND basis_e = 'Elective'
        AND title_off = 'Check Course' AND title_res = 'Check Course'
        AND no_reset AND n_entry = 1 AND v_id2 = v_id AND st_back = 'LIVE' AND title_back = 'Check Course Again'
        AND r_owner = 'CAT_OWNER_PROGRAMME' AND n_owner = 1 AND owner_src = 'DESK',
        format('invalid=%s courses=%s offers=%s elective=%s title=%s/%s noreset=%s entry=%s same=%s back=%s/%s owner=%s/%s/%s',
               r_invalid, n_courses, n_offers, basis_e, title_off, title_res, no_reset, n_entry, v_id2 = v_id, st_back, title_back, r_owner, n_owner, owner_src));
END $$;

-- ── 185. V339: JUPEB — the application window is closed until opened; the Bursary's defaults stand (₦15,000; ₦180,000 / ₦195,000 / ₦200,000 / ₦215,000; 70%); an O'Level needs five credits with English and Mathematics; the school fee follows Science-or-other and indigene status, is charged 70% then 30% in order and frozen once charged; the first instalment activates the student, who registers the combination's three subjects; an examination number is unique, a surname mismatch is held for review and a correction needs its reason ──
DO $$
DECLARE who uuid := gen_random_uuid(); acc1 uuid; acc2 uuid; app1 uuid; app2 uuid; s1 uuid; s2 uuid; s3 uuid; comb uuid; prog text; fac text; msg text;
        win text; d_app numeric; d_fees numeric[]; ok4 boolean; ok5 boolean; noeng boolean; sf record; r_order text; ref1 text; amt1 numeric; st_after text;
        n_reg int; r_taken text; r_reason text; imp jsonb; held text; frozen numeric; ses text := '2093/2094';
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'ict', true);
        win := (SELECT w.state FROM policy.window_state('JUPEB_APPLICATION', ses, NULL) w);
        d_app := (jupeb.fee_setting_of(ses)).application_fee;
        d_fees := ARRAY[jupeb.school_fee_amount(ses, 'OTHER', true), jupeb.school_fee_amount(ses, 'SCIENCE', true),
                        jupeb.school_fee_amount(ses, 'OTHER', false), jupeb.school_fee_amount(ses, 'SCIENCE', false), (jupeb.fee_setting_of(ses)).first_percent];
        SELECT code, faculty_code INTO prog, fac FROM ref.programme WHERE category = 'UNDER GRADUATE' AND NOT archived ORDER BY code LIMIT 1;
        INSERT INTO jupeb.fee_category (faculty_code, category) VALUES (fac, 'SCIENCE') ON CONFLICT (faculty_code) DO UPDATE SET category = 'SCIENCE';
        INSERT INTO jupeb.subject (code, title) VALUES ('ZZCHK1', 'Check One') RETURNING id INTO s1;
        INSERT INTO jupeb.subject (code, title) VALUES ('ZZCHK2', 'Check Two') RETURNING id INTO s2;
        INSERT INTO jupeb.subject (code, title) VALUES ('ZZCHK3', 'Check Three') RETURNING id INTO s3;
        INSERT INTO jupeb.combination (code, name, subject1, subject2, subject3) VALUES ('ZZCHK', 'Check combination', s1, s2, s3) RETURNING id INTO comb;
        INSERT INTO jupeb.account (email, password_hash) VALUES ('zz.check1@example.com', '$2a$12$abcdefghijklmnopqrstuuabcdefghijklmnopqrstuvwxyz12345') RETURNING id INTO acc1;
        INSERT INTO jupeb.account (email, password_hash) VALUES ('zz.check2@example.com', '$2a$12$abcdefghijklmnopqrstuuabcdefghijklmnopqrstuvwxyz12345') RETURNING id INTO acc2;
        INSERT INTO jupeb.application (account_id, session, application_no, surname, first_name, email, programme_code, combination_id, state_of_origin, state)
        VALUES (acc1, ses, 'JUPEB/APP/2093/900001', 'CHECKONE', 'Candidate', 'zz.check1@example.com', prog, comb, 'Benue', 'ADMITTED') RETURNING id INTO app1;
        INSERT INTO jupeb.application (account_id, session, application_no, surname, first_name, email, programme_code, combination_id, state_of_origin, state, subjects_registered_at, exam_no)
        VALUES (acc2, ses, 'JUPEB/APP/2093/900002', 'CHECKTWO', 'Candidate', 'zz.check2@example.com', prog, comb, 'Lagos', 'STUDENT', now(), 'ZZCHK-0002') RETURNING id INTO app2;
        INSERT INTO jupeb.olevel (application_id, sitting, exam_type, exam_number, exam_year, subject, grade) VALUES
            (app1, 1, 'WAEC', '4250001001', 2091, 'English Language', 'C6'), (app1, 1, 'WAEC', '4250001001', 2091, 'Mathematics', 'C5'),
            (app1, 1, 'WAEC', '4250001001', 2091, 'Physics', 'B3'), (app1, 1, 'WAEC', '4250001001', 2091, 'Chemistry', 'C4');
        ok4 := (SELECT k.ok FROM jupeb.olevel_check(app1) k);
        INSERT INTO jupeb.olevel (application_id, sitting, exam_type, exam_number, exam_year, subject, grade) VALUES (app1, 2, 'NECO', '1010002002', 2092, 'Biology', 'A1');
        ok5 := (SELECT k.ok FROM jupeb.olevel_check(app1) k);
        UPDATE jupeb.olevel SET grade = 'D7' WHERE application_id = app1 AND subject = 'English Language';
        noeng := (SELECT NOT k.ok AND NOT k.english FROM jupeb.olevel_check(app1) k);
        SELECT * INTO sf FROM jupeb.school_fees(app1);
        /* V342: an admitted candidate's school fees follow the confirmed acceptance fee */
        INSERT INTO jupeb.fee_reference (application_id, kind, reference, amount, session, expires_at, confirmed_at, channel)
        VALUES (app1, 'ACCEPTANCE', 'ZZCHK-ACC-0001', 15000, ses, now() + interval '1 day', now(), 'check');
        BEGIN PERFORM jupeb.new_fee_reference(app1, 'SCHOOL_SECOND'); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_order := split_part(msg, ':', 1); END;
        ref1 := jupeb.new_fee_reference(app1, 'SCHOOL_FIRST');
        amt1 := (SELECT amount FROM jupeb.fee_reference WHERE reference = ref1);
        UPDATE jupeb.school_fee SET amount = 999999 WHERE session = '*' AND category = 'SCIENCE' AND indigene;
        PERFORM jupeb.confirm_fee(ref1, 'check');
        st_after := (SELECT state FROM jupeb.application WHERE id = app1);
        frozen := (SELECT f.total FROM jupeb.school_fees(app1) f);
        n_reg := jupeb.register_subjects(app1, who);
        BEGIN PERFORM jupeb.set_exam_no(app1, 'ZZCHK-0002', NULL, 'DESK', NULL); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_taken := split_part(msg, ':', 1); END;
        imp := jupeb.import_exam_numbers(jsonb_build_array(jsonb_build_object('row', 2, 'applicationNo', 'JUPEB/APP/2093/900001', 'examNo', 'ZZCHK-0001', 'surname', 'SOMEBODY')), true, 'check', who);
        held := (SELECT exam_no FROM jupeb.application WHERE id = app1);
        PERFORM jupeb.set_exam_no(app1, 'ZZCHK-0001', NULL, 'DESK', NULL);
        BEGIN PERFORM jupeb.set_exam_no(app1, 'ZZCHK-0003', NULL, 'DESK', NULL); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_reason := split_part(msg, ':', 1); END;
        RAISE EXCEPTION 'the V339 JUPEB check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('JUPEB: the window is closed until opened; the Bursary''s defaults stand; five credits with English and Mathematics; Science/indigene ₦195,000 charged 70% then 30%, frozen once charged; the first instalment activates; three subjects registered; an examination number unique, a surname mismatch held for review, a correction needing its reason',
        win = 'CLOSED' AND d_app = 15000 AND d_fees = ARRAY[180000, 195000, 200000, 215000, 70]::numeric[]
        AND ok4 = false AND ok5 AND noeng
        AND sf.category = 'SCIENCE' AND sf.indigene AND sf.total = 195000 AND sf.first_amount = 136500 AND sf.second_amount = 58500
        AND r_order = 'JUPEB_FEE_ORDER' AND amt1 = 136500 AND st_after = 'STUDENT' AND frozen = 195000 AND n_reg = 3
        AND r_taken = 'JUPEB_EXAM_NO_TAKEN' AND (imp->>'review')::int = 1 AND held IS NULL AND r_reason = 'JUPEB_EXAM_NO_REASON',
        format('window=%s app=%s fees=%s ok4=%s ok5=%s noeng=%s fee=%s/%s/%s/%s/%s order=%s first=%s state=%s frozen=%s reg=%s taken=%s review=%s held=%s reason=%s',
               win, d_app, d_fees, ok4, ok5, noeng, sf.category, sf.indigene, sf.total, sf.first_amount, sf.second_amount, r_order, amt1, st_after, frozen, n_reg,
               r_taken, imp->>'review', held, r_reason));
END $$;

-- ── 186. V341 (V342): JUPEB — Science or Non-Science (V341's Arts): the applicant's stream decides the school fee (Non-Science pays the other fee); a draft without a stream is incomplete; a student registers a combination of their own stream ──
DO $$
DECLARE who uuid := gen_random_uuid(); acc uuid; app uuid; s1 uuid; s2 uuid; s3 uuid; s4 uuid; c_sci uuid; c_art uuid; msg text;
        cat text; total numeric; miss boolean; r_choose text; r_stream text; n_reg int; held uuid; ses text := '2092/2093';
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'ict', true);
        INSERT INTO jupeb.subject (code, title) VALUES ('ZZS1', 'Check S One') RETURNING id INTO s1;
        INSERT INTO jupeb.subject (code, title) VALUES ('ZZS2', 'Check S Two') RETURNING id INTO s2;
        INSERT INTO jupeb.subject (code, title) VALUES ('ZZS3', 'Check S Three') RETURNING id INTO s3;
        INSERT INTO jupeb.subject (code, title) VALUES ('ZZS4', 'Check S Four') RETURNING id INTO s4;
        INSERT INTO jupeb.combination (code, name, subject1, subject2, subject3, area) VALUES ('ZZSCI', 'Check science', s1, s2, s3, 'Science') RETURNING id INTO c_sci;
        INSERT INTO jupeb.combination (code, name, subject1, subject2, subject3, area) VALUES ('ZZART', 'Check arts', s2, s3, s4, 'Arts') RETURNING id INTO c_art;
        INSERT INTO jupeb.account (email, password_hash) VALUES ('zz.check.stream@example.com', '$2a$12$abcdefghijklmnopqrstuuabcdefghijklmnopqrstuvwxyz12345') RETURNING id INTO acc;
        INSERT INTO jupeb.application (account_id, session, application_no, surname, first_name, email, state_of_origin, state)
        VALUES (acc, ses, 'JUPEB/APP/2092/900001', 'CHECKSTREAM', 'Candidate', 'zz.check.stream@example.com', 'Benue', 'DRAFT') RETURNING id INTO app;
        miss := 'Choose Science or Non-Science' = ANY(jupeb.missing(app));
        UPDATE jupeb.application SET stream = 'NON_SCIENCE', state = 'STUDENT' WHERE id = app;
        SELECT f.category, f.total INTO cat, total FROM jupeb.school_fees(app) f;
        BEGIN PERFORM jupeb.register_subjects(app, who); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_choose := split_part(msg, ':', 1); END;
        BEGIN PERFORM jupeb.register_subjects(app, who, c_sci); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_stream := split_part(msg, ':', 1); END;
        n_reg := jupeb.register_subjects(app, who, c_art);
        held := (SELECT combination_id FROM jupeb.application WHERE id = app);
        RAISE EXCEPTION 'the V341 JUPEB check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('JUPEB Science or Non-Science: a draft without a stream is incomplete; Non-Science with Benue pays the indigene other fee (NGN 180,000); a student must choose a combination of their own stream to register its three subjects',
        miss AND cat = 'OTHER' AND total = 180000 AND r_choose = 'JUPEB_COMBINATION_CHOOSE' AND r_stream = 'JUPEB_COMBINATION_STREAM' AND n_reg = 3 AND held = c_art,
        format('missing=%s fee=%s/%s choose=%s stream=%s reg=%s held=%s', miss, cat, total, r_choose, r_stream, n_reg, held = c_art));
END $$;

-- ── 187. V342: JUPEB — admission status checking is closed until opened and paid once (₦1,000) before any decision shows; the acceptance fee (₦15,000) follows an ADMITTED status and precedes school fees; an accepted admission cannot be withdrawn; two declared sittings need two O'Level documents; the grade point is out of 16 with a point for passing all three (X counts nothing); the Board's 46 combinations are seeded; a subject or combination not offered cannot be chosen and its holder is told; attendance corrections need a reason and a locked register is closed; no minimum, no verdict ──
DO $$
DECLARE who uuid := gen_random_uuid(); acc uuid; app uuid; s1 uuid; s2 uuid; s3 uuid; comb uuid; ses text := jupeb.current_session(); msg text;
        win text; d_chk numeric; d_acc numeric; masked boolean; r_closed text; ref_chk text; amt_chk numeric; r_once text; seen text; r_acc_early text; r_school text;
        ref_acc text; amt_acc numeric; accepted boolean; r_withdraw text; docs_short boolean; docs_full boolean; gp1 record; gp2 record;
        n_seed int; n_sci int; r_choose_off text; told int; prog_msg text; reg uuid; r_reason text; r_locked text; n_changes int; verdict text; rate numeric;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'ict', true);
        INSERT INTO iam.person (id, surname, given_names) VALUES (who, 'ZZCHECK', 'Attendance');
        win := (SELECT w.state FROM policy.window_state('JUPEB_ADMISSION_STATUS_CHECKING', ses, NULL) w);
        d_chk := (jupeb.fee_setting_of(ses)).checking_fee;
        d_acc := (jupeb.fee_setting_of(ses)).acceptance_fee;
        n_seed := (SELECT count(*) FROM jupeb.combination WHERE code ~ '^SC-0[0-4][0-9]$' AND jupeb.combination_offered(id));
        n_sci := (SELECT count(*) FROM jupeb.combination WHERE code ~ '^SC-' AND jupeb.combination_suits(area, 'SCIENCE'));
        INSERT INTO jupeb.subject (code, title) VALUES ('ZZV1', 'Check V One') RETURNING id INTO s1;
        INSERT INTO jupeb.subject (code, title) VALUES ('ZZV2', 'Check V Two') RETURNING id INTO s2;
        INSERT INTO jupeb.subject (code, title) VALUES ('ZZV3', 'Check V Three') RETURNING id INTO s3;
        INSERT INTO jupeb.combination (code, name, subject1, subject2, subject3, area) VALUES ('ZZVCOMB', 'Check V', s1, s2, s3, 'Science') RETURNING id INTO comb;
        INSERT INTO jupeb.account (email, password_hash) VALUES ('zz.check.v342@example.com', '$2a$12$abcdefghijklmnopqrstuuabcdefghijklmnopqrstuvwxyz12345') RETURNING id INTO acc;
        INSERT INTO jupeb.application (account_id, session, application_no, surname, first_name, email, sex, date_of_birth, nin, phone, state_of_origin, lga, contact_address,
                                       next_of_kin_name, next_of_kin_phone, olevel_sittings, state)
        VALUES (acc, ses, 'JUPEB/APP/2091/900001', 'CHECKV', 'Candidate', 'zz.check.v342@example.com', 'F', '2007-01-01', '12345678901', '08012345678', 'Benue', 'Makurdi', '1 Road',
                'Kin', '08011111111', 2, 'DRAFT') RETURNING id INTO app;
        PERFORM jupeb.choose(app, 'SCIENCE', 'ZZVCOMB');
        -- the office stops offering a subject of the chosen combination: the candidate is told, and the programme step asks again
        told := (SELECT o.told FROM jupeb.set_offered('SUBJECT', ARRAY['zzv2'], false, who) o);
        BEGIN PERFORM jupeb.choose(app, 'SCIENCE', 'ZZVCOMB'); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_choose_off := split_part(msg, ':', 1); END;
        prog_msg := (SELECT p->>'message' FROM jsonb_array_elements(jupeb.step_status(app)->'steps') st, jsonb_array_elements(st->'problems') p WHERE st->>'step' = 'PROGRAMME' LIMIT 1);
        PERFORM jupeb.set_offered('SUBJECT', ARRAY['ZZV2'], true, who);
        -- two sittings: both results, each its own document
        INSERT INTO jupeb.olevel (application_id, sitting, exam_type, exam_number, exam_year, subject, grade) VALUES
            (app, 1, 'WAEC', '4250009001', 2090, 'English Language', 'C5'), (app, 1, 'WAEC', '4250009001', 2090, 'Mathematics', 'B3'),
            (app, 1, 'WAEC', '4250009001', 2090, 'Physics', 'C6'), (app, 1, 'WAEC', '4250009001', 2090, 'Chemistry', 'C4'),
            (app, 2, 'NECO', '1010009002', 2090, 'Biology', 'B2');
        INSERT INTO jupeb.document (application_id, kind, sitting, filename, content_type, size_bytes) VALUES (app, 'OLEVEL_RESULT', 1, 'waec.pdf', 'application/pdf', 10);
        INSERT INTO jupeb.document (application_id, kind, filename, content_type, size_bytes)
        SELECT app, k.code, k.code || '.pdf', 'application/pdf', 10 FROM jupeb.document_kind k WHERE k.required AND k.active AND k.code <> 'OLEVEL_RESULT';
        docs_short := (SELECT NOT (st->>'ok')::boolean FROM jsonb_array_elements(jupeb.step_status(app)->'steps') st WHERE st->>'step' = 'DOCUMENTS');
        INSERT INTO jupeb.document (application_id, kind, sitting, filename, content_type, size_bytes) VALUES (app, 'OLEVEL_RESULT', 2, 'neco.pdf', 'application/pdf', 10);
        docs_full := (SELECT (st->>'ok')::boolean FROM jsonb_array_elements(jupeb.step_status(app)->'steps') st WHERE st->>'step' = 'DOCUMENTS');
        UPDATE jupeb.application SET fee_confirmed_at = now() WHERE id = app;
        PERFORM jupeb.submit(app);
        PERFORM jupeb.decide_eligibility(app, true, NULL, NULL);
        PERFORM jupeb.decide_admission(app, 'ADMITTED', 'Welcome', NULL);
        -- the decision is not readable, and checking not payable, until the Director of ICT opens checking
        masked := (SELECT NOT c.may_check AND NOT c.may_pay FROM jupeb.status_checking(app) c);
        BEGIN PERFORM jupeb.new_fee_reference(app, 'STATUS_CHECKING'); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_closed := split_part(msg, ':', 1); END;
        BEGIN PERFORM jupeb.new_fee_reference(app, 'ACCEPTANCE'); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_acc_early := split_part(msg, ':', 1); END;
        PERFORM policy.window_act('JUPEB_ADMISSION_STATUS_CHECKING', ses, NULL, 'OPEN', NULL, NULL, NULL, false, 'check', who, 'ict');
        ref_chk := jupeb.new_fee_reference(app, 'STATUS_CHECKING');
        amt_chk := (SELECT amount FROM jupeb.fee_reference WHERE reference = ref_chk);
        PERFORM jupeb.confirm_fee(ref_chk, 'check');
        BEGIN PERFORM jupeb.new_fee_reference(app, 'STATUS_CHECKING'); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_once := split_part(msg, ':', 1); END;
        seen := (SELECT c.status FROM jupeb.status_checking(app) c WHERE c.may_check);
        BEGIN PERFORM jupeb.new_fee_reference(app, 'SCHOOL_FIRST'); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_school := split_part(msg, ':', 1); END;
        ref_acc := jupeb.new_fee_reference(app, 'ACCEPTANCE');
        amt_acc := (SELECT amount FROM jupeb.fee_reference WHERE reference = ref_acc);
        PERFORM jupeb.confirm_fee(ref_acc, 'check');
        accepted := (SELECT c.accepted FROM jupeb.status_checking(app) c);
        BEGIN PERFORM jupeb.decide_admission(app, 'NOT_ADMITTED', 'withdrawn', NULL); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_withdraw := split_part(msg, ':', 1); END;
        -- results: A, B, C is 12 + 1 of 16; an absence (X) earns nothing and no point is added
        UPDATE jupeb.application SET state = 'STUDENT' WHERE id = app;
        PERFORM jupeb.register_subjects(app, who);
        INSERT INTO jupeb.result (application_id, subject_id, grade, points) VALUES (app, s1, 'A', 5), (app, s2, 'B', 4), (app, s3, 'C', 3);
        SELECT * INTO gp1 FROM jupeb.grade_point(app);
        UPDATE jupeb.result SET grade = 'X', points = 0 WHERE application_id = app AND subject_id = s3;
        SELECT * INTO gp2 FROM jupeb.grade_point(app);
        -- attendance: a correction needs its reason; a locked register is closed to the instructor; no minimum, no verdict
        INSERT INTO attendance.instructor (context, session, subject_ref, person_id) VALUES ('JUPEB', ses, s1, who);
        reg := attendance.open_register('JUPEB', ses, 1, s1, NULL, current_date, 'Check', who);
        PERFORM attendance.save_marks(reg, jsonb_build_array(jsonb_build_object('member', app, 'status', 'PRESENT')), NULL, who, false);
        BEGIN PERFORM attendance.save_marks(reg, jsonb_build_array(jsonb_build_object('member', app, 'status', 'LATE')), NULL, who, false);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_reason := split_part(msg, ':', 1); END;
        PERFORM attendance.save_marks(reg, jsonb_build_array(jsonb_build_object('member', app, 'status', 'LATE')), 'arrived late, recorded wrongly', who, false);
        n_changes := (SELECT count(*) FROM attendance.mark_change WHERE register_id = reg AND reason IS NOT NULL);
        PERFORM attendance.lock_register(reg, who, true, NULL);
        BEGIN PERFORM attendance.save_marks(reg, jsonb_build_array(jsonb_build_object('member', app, 'status', 'ABSENT')), 'again', who, false);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_locked := split_part(msg, ':', 1); END;
        SELECT m.verdict, m.rate INTO verdict, rate FROM attendance.member_summary('JUPEB', app, ses) m LIMIT 1;
        RAISE EXCEPTION 'the V342 JUPEB check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('JUPEB V342: status checking closed until opened, ₦1,000 once, before any decision shows; acceptance ₦15,000 after ADMITTED and before school fees; accepted admission kept; two sittings two documents; grade point 13/16, X nothing; 46 combinations seeded; a disabled subject withdraws its combinations and tells the holder; attendance corrections need a reason, a locked register is closed, no minimum no verdict',
        win = 'CLOSED' AND d_chk = 1000 AND d_acc = 15000 AND masked AND r_closed = 'JUPEB_CHECKING_CLOSED' AND r_acc_early = 'JUPEB_ACCEPTANCE_NOT_YET'
        AND amt_chk = 1000 AND ref_chk LIKE 'MOAUM-JUPEBCHK-' || substr(ses, 1, 4) || '-%' AND r_once = 'JUPEB_FEE_PAID' AND seen = 'ADMITTED' AND r_school = 'JUPEB_ACCEPTANCE_FIRST' AND amt_acc = 15000 AND accepted
        AND r_withdraw = 'JUPEB_ADMISSION_PAID' AND docs_short AND docs_full
        AND gp1.total = 13 AND gp1.out_of = 16 AND gp1.bonus = 1 AND gp2.total = 9 AND gp2.bonus = 0
        AND n_seed = 46 AND n_sci = 14 AND told = 1 AND r_choose_off = 'JUPEB_COMBINATION' AND prog_msg LIKE 'ZZVCOMB is no longer offered%'
        AND r_reason = 'ATT_REASON' AND n_changes = 1 AND r_locked = 'ATT_LOCKED' AND verdict IS NULL AND rate = 100,
        format('win=%s fees=%s/%s masked=%s closed=%s acc_early=%s chk=%s once=%s seen=%s school=%s acc=%s accepted=%s withdraw=%s docs=%s/%s gp=%s/%s+%s,%s+%s seed=%s sci=%s told=%s choose=%s prog=%s reason=%s changes=%s locked=%s verdict=%s rate=%s',
               win, d_chk, d_acc, masked, r_closed, r_acc_early, amt_chk, r_once, seen, r_school, amt_acc, accepted, r_withdraw, docs_short, docs_full,
               gp1.total, gp1.out_of, gp1.bonus, gp2.total, gp2.bonus, n_seed, n_sci, told, r_choose_off, prog_msg, r_reason, n_changes, r_locked, verdict, rate));
END $$;

-- ── 188. V343: JUPEB — a paper's code is issued only for what the record supports, kept while the record is unchanged, shows superseded after a change and not genuine once revoked; a change request needs its reason, is one at a time, is declined only with a note, defers only an accepted admission, and a combination change re-registers the subjects; reminders come when due, once a day, spaced and capped by the office's rule, and not at all when switched off ──
DO $$
DECLARE who uuid := gen_random_uuid(); acc uuid; acc2 uuid; app uuid; app2 uuid; ses text := jupeb.current_session(); msg text;
        c31 uuid; c33 uuid; r_noissue text; ack text; ack_again text; v_ok jsonb; v_after jsonb; v_rev jsonb; r_reason text; r_pending text; r_note text;
        r_defer text; rq uuid; rq2 uuid; subj_after text; due1 text; due_same int; due_later text; due_off int; sent jsonb; code_ok boolean;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'jupeb', true);
        c31 := (SELECT id FROM jupeb.combination WHERE code = 'SC-031');
        c33 := (SELECT id FROM jupeb.combination WHERE code = 'SC-033');
        INSERT INTO jupeb.account (email, password_hash) VALUES ('zz.check.v343@example.com', '$2a$12$abcdefghijklmnopqrstuuabcdefghijklmnopqrstuvwxyz12345') RETURNING id INTO acc;
        INSERT INTO jupeb.application (account_id, session, application_no, surname, first_name, email, stream, combination_id, state, submitted_at, fee_confirmed_at)
        VALUES (acc, ses, 'JUPEB/APP/2090/900001', 'CHECKP', 'Candidate', 'zz.check.v343@example.com', 'SCIENCE', c31, 'DRAFT', NULL, now()) RETURNING id INTO app;
        BEGIN PERFORM jupeb.issue_paper(app, 'ACKNOWLEDGEMENT', NULL, false, NULL, 'applicant'); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_noissue := split_part(msg, ':', 1); END;
        UPDATE jupeb.application SET state = 'SUBMITTED', submitted_at = now() WHERE id = app;
        ack := jupeb.issue_paper(app, 'ACKNOWLEDGEMENT', NULL, false, NULL, 'applicant');
        ack_again := jupeb.issue_paper(app, 'ACKNOWLEDGEMENT', NULL, false, NULL, 'applicant');
        code_ok := ack ~ '^[A-HJ-NP-Z2-9]{4}-[A-HJ-NP-Z2-9]{4}-[A-HJ-NP-Z2-9]{4}$';
        v_ok := jupeb.verify_paper(lower(replace(ack, '-', '')));
        -- the change requests
        BEGIN PERFORM jupeb.request_change(app, 'CHANGE_COMBINATION', NULL, 'SC-033', NULL, 'short', who, 'applicant'); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_reason := split_part(msg, ':', 1); END;
        BEGIN PERFORM jupeb.request_change(app, 'DEFER', NULL, NULL, NULL, 'Medical treatment this session', who, 'applicant'); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_defer := split_part(msg, ':', 1); END;
        rq := jupeb.request_change(app, 'CHANGE_COMBINATION', NULL, 'SC-033', NULL, 'Mathematics in place of Physics', who, 'applicant');
        BEGIN PERFORM jupeb.request_change(app, 'WITHDRAW', NULL, NULL, NULL, 'A second request at once', who, 'applicant'); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_pending := split_part(msg, ':', 1); END;
        BEGIN PERFORM jupeb.decide_change(rq, false, ' ', who, 'jupeb'); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_note := split_part(msg, ':', 1); END;
        /* a student with subjects registered and no examination number: the change re-registers the new combination's three */
        UPDATE jupeb.application SET state = 'STUDENT' WHERE id = app;
        INSERT INTO jupeb.subject_registration (application_id, subject_id, session, registered_by)
        SELECT app, s, ses, who FROM jupeb.combination c, unnest(ARRAY[c.subject1, c.subject2, c.subject3]) s WHERE c.id = c31;
        UPDATE jupeb.application SET subjects_registered_at = now() WHERE id = app;
        PERFORM jupeb.decide_change(rq, true, NULL, who, 'jupeb');
        subj_after := (SELECT string_agg(s.code, ',' ORDER BY s.code) FROM jupeb.subject_registration r JOIN jupeb.subject s ON s.id = r.subject_id WHERE r.application_id = app);
        v_after := jupeb.verify_paper(ack);
        PERFORM jupeb.revoke_paper(ack, 'Issued in error at the desk', who);
        v_rev := jupeb.verify_paper(ack);
        -- the reminders: a draft three days old, unpaid, while the window is open
        PERFORM policy.window_act('JUPEB_APPLICATION', ses, NULL, 'OPEN', NULL, NULL, NULL, false, 'check', who, 'ict');
        INSERT INTO jupeb.account (email, password_hash) VALUES ('zz.check.v343b@example.com', '$2a$12$abcdefghijklmnopqrstuuabcdefghijklmnopqrstuvwxyz12345') RETURNING id INTO acc2;
        INSERT INTO jupeb.application (account_id, session, application_no, surname, first_name, email, state, created_at)
        VALUES (acc2, ses, 'JUPEB/APP/2090/900002', 'CHECKR', 'Candidate', 'zz.check.v343b@example.com', 'DRAFT', now() - interval '3 days') RETURNING id INTO app2;
        due1 := (SELECT d.kind FROM jupeb.due_reminders(now()) d WHERE d.application_id = app2);
        sent := jupeb.send_reminders(now(), 'https://portal.example', 1000, 'OFFICE');
        due_same := (SELECT count(*) FROM jupeb.due_reminders(now() + interval '2 hours') d WHERE d.application_id = app2);
        due_later := (SELECT d.kind FROM jupeb.due_reminders(now() + interval '3 days 1 hour') d WHERE d.application_id = app2);
        UPDATE jupeb.reminder_rule SET enabled = false;
        due_off := (SELECT count(*) FROM jupeb.due_reminders(now() + interval '10 days'));
        RAISE EXCEPTION 'the V343 JUPEB check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('JUPEB V343: paper codes issued for the record as it is, kept, superseded after a change, void once revoked; change requests with a reason, one at a time, declined with a note, deferment only of an accepted admission, a combination change re-registering the subjects; reminders when due, once a day, spaced, off when switched off',
        r_noissue = 'JUPEB_PAPER_NOT_ISSUABLE' AND code_ok AND ack = ack_again AND (v_ok->>'genuine')::boolean AND (v_ok->>'current')::boolean
        AND r_reason = 'JUPEB_CHANGE_REASON' AND r_defer = 'JUPEB_DEFER_STATE' AND r_pending = 'JUPEB_CHANGE_PENDING' AND r_note = 'JUPEB_CHANGE_NOTE'
        AND subj_after = 'BIO,CHM,MTH' AND (v_after->>'genuine')::boolean AND NOT (v_after->>'current')::boolean
        AND NOT (v_rev->>'genuine')::boolean AND (v_rev->>'revoked')::boolean
        AND due1 = 'FEE_UNPAID' AND (sent->'byKind'->>'FEE_UNPAID')::int >= 1 AND due_same = 0 AND due_later IS NOT NULL AND due_off = 0,
        format('noissue=%s code=%s same=%s ok=%s reason=%s defer=%s pending=%s note=%s subjects=%s after=%s/%s revoked=%s due=%s sent=%s same_day=%s later=%s off=%s',
               r_noissue, code_ok, ack = ack_again, v_ok->>'current', r_reason, r_defer, r_pending, r_note, subj_after, v_after->>'genuine', v_after->>'current',
               v_rev->>'revoked', due1, sent, due_same, due_later, due_off));
END $$;

-- ── 189. V344: JUPEB attendance minimum — with no minimum nobody is below it or warned; with one, a subject under it is below (warned once enough classes are counted), one above it within the band is at risk; the warning names the subject and its rate, and the office's warning reaches it even when another reminder comes first ──
DO $$
DECLARE who uuid := gen_random_uuid(); acc uuid; app uuid; ses text := jupeb.current_session(); comb uuid; bio uuid; chm uuid; rg uuid; k int;
        none_flag int; none_due int; bio_v text; bio_w boolean; chm_r boolean; chm_v text; words text; warned jsonb; few boolean;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'jupeb', true);
        INSERT INTO iam.person (id, surname, given_names) VALUES (who, 'ZZCHECK', 'Attendance');
        comb := (SELECT id FROM jupeb.combination WHERE code = 'SC-031');
        bio := (SELECT id FROM jupeb.subject WHERE code = 'BIO');
        chm := (SELECT id FROM jupeb.subject WHERE code = 'CHM');
        DELETE FROM attendance.policy WHERE context = 'JUPEB';
        INSERT INTO jupeb.account (email, password_hash) VALUES ('zz.check.v344@example.com', '$2a$12$abcdefghijklmnopqrstuuabcdefghijklmnopqrstuvwxyz12345') RETURNING id INTO acc;
        INSERT INTO jupeb.application (account_id, session, application_no, surname, first_name, email, stream, combination_id, state, activated_at, subjects_registered_at)
        VALUES (acc, ses, 'JUPEB/APP/2089/900001', 'CHECKATT', 'Candidate', 'zz.check.v344@example.com', 'SCIENCE', comb, 'STUDENT', now() - interval '30 days', now())
        RETURNING id INTO app;
        INSERT INTO jupeb.subject_registration (application_id, subject_id, session, registered_by)
        SELECT app, x, ses, who FROM unnest(ARRAY[bio, chm, (SELECT id FROM jupeb.subject WHERE code = 'PHY')]) x;
        FOR k IN 1..4 LOOP   -- Biology: 2 of 4 (50%)
            rg := attendance.open_register('JUPEB', ses, 1, bio, NULL, current_date - k, NULL, who);
            PERFORM attendance.save_marks(rg, jsonb_build_array(jsonb_build_object('member', app, 'status', CASE WHEN k <= 2 THEN 'ABSENT' ELSE 'PRESENT' END)), NULL, who, true);
        END LOOP;
        FOR k IN 1..5 LOOP   -- Chemistry: 4 of 5 (80%)
            rg := attendance.open_register('JUPEB', ses, 1, chm, NULL, current_date - k, NULL, who);
            PERFORM attendance.save_marks(rg, jsonb_build_array(jsonb_build_object('member', app, 'status', CASE WHEN k = 1 THEN 'ABSENT' ELSE 'PRESENT' END)), NULL, who, true);
        END LOOP;
        none_flag := (SELECT count(*) FROM attendance.jupeb_standing(ses) st WHERE st.member_ref = app AND (st.verdict IS NOT NULL OR st.at_risk OR st.warnable));
        none_due := (SELECT count(*) FROM jupeb.due_reminders(now(), 'ATTENDANCE_LOW') d WHERE d.application_id = app);
        INSERT INTO attendance.policy (context, session, min_percent, warn_band, min_classes) VALUES ('JUPEB', ses, 75, 10, 3);
        SELECT st.verdict, st.warnable INTO bio_v, bio_w FROM attendance.jupeb_standing(ses) st WHERE st.member_ref = app AND st.code = 'BIO';
        SELECT st.verdict, st.at_risk INTO chm_v, chm_r FROM attendance.jupeb_standing(ses) st WHERE st.member_ref = app AND st.code = 'CHM';
        words := (jupeb.reminder_words(app, 'ATTENDANCE_LOW', '{}', 'https://portal.example'))[2];
        warned := jupeb.send_reminders(now(), 'https://portal.example', 1000, 'OFFICE', 'ATTENDANCE_LOW');
        UPDATE attendance.policy SET min_classes = 6 WHERE context = 'JUPEB' AND session = ses;
        few := (SELECT st.warnable FROM attendance.jupeb_standing(ses) st WHERE st.member_ref = app AND st.code = 'BIO');
        RAISE EXCEPTION 'the V344 JUPEB check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('JUPEB V344: no minimum, nobody below or warned; under the minimum is below (warned after enough classes), within the band above it is at risk; the warning names the subject; the office warning reaches it',
        none_flag = 0 AND none_due = 0 AND bio_v = 'NOT_ELIGIBLE' AND bio_w AND chm_v = 'ELIGIBLE' AND chm_r
        AND words LIKE '%minimum of 75% in: Biology 50%' || '%' AND (warned->'byKind'->>'ATTENDANCE_LOW')::int = 1 AND NOT few,
        format('none=%s/%s bio=%s/%s chm=%s/%s words=%s warned=%s few=%s', none_flag, none_due, bio_v, bio_w, chm_v, chm_r, left(words, 60), warned, few));
END $$;

-- ── 190. V345: JUPEB students from the old portal — a preview writes nothing; a row without a valid email is refused and listed, an unreadable phone or NIN is left out and said; the upload makes STUDENT records on the old App No with a temporary password to change, announces nothing, and the same file again adds nothing; no fee reminder reaches them; their registration sets the programme from the combination ──
DO $$
DECLARE who uuid := gen_random_uuid(); ses text := jupeb.current_session(); rows jsonb; prev jsonb; done jsonb; again jsonb; app uuid;
        n_prev int; st_bad text; st_review text; phone text; dob text; v_state text; v_must boolean; v_told int; v_fee int; v_stream text; n_reg int;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'jupeb', true);
        rows := jsonb_build_array(
            jsonb_build_object('row', 2, 'appNo', 'S0CHECK190001', 'firstName', 'IWANGER', 'surname', 'UVA', 'sex', 'Female', 'phone', '7052428202', 'dob', '9/1/2004',
                               'nin', '13181803004', 'email', 'zz.check190.a@gmail.'),
            jsonb_build_object('row', 3, 'appNo', 's0check190002', 'firstName', 'Paul', 'middleName', 'Shater', 'surname', 'Kegh', 'sex', 'Male', 'phone', '8089894004',
                               'dob', '21/10/2006', 'nin', '1171459604', 'email', 'zz.check190.b@example.com',
                               'passwordHash', '$2a$12$abcdefghijklmnopqrstuuabcdefghijklmnopqrstuvwxyz12345'));
        prev := jupeb.import_old_portal_students(rows, ses, true, false, 'check.xlsx', who);
        n_prev := (SELECT count(*) FROM jupeb.application WHERE upper(application_no) LIKE 'S0CHECK190%');
        st_bad := prev->'rows'->0->>'status';
        st_review := prev->'rows'->1->>'status';
        phone := prev->'rows'->1->>'phone';
        dob := prev->'rows'->1->>'dob';
        done := jupeb.import_old_portal_students(rows, ses, true, true, 'check.xlsx', who);
        app := (SELECT id FROM jupeb.application WHERE application_no = 'S0CHECK190002');
        SELECT a.state, acc.must_change_password INTO v_state, v_must FROM jupeb.application a JOIN jupeb.account acc ON acc.id = a.account_id WHERE a.id = app;
        v_told := (SELECT count(*) FROM platform.notice WHERE about_id = app);
        again := jupeb.import_old_portal_students(rows, ses, true, true, 'check.xlsx', who);
        v_fee := (SELECT count(*) FROM jupeb.due_reminders(now() + interval '60 days') d WHERE d.application_id = app AND d.kind = 'SCHOOL_FEE_UNPAID');
        n_reg := jupeb.register_subjects(app, who, (SELECT id FROM jupeb.combination WHERE code = 'SC-001'));
        v_stream := (SELECT stream FROM jupeb.application WHERE id = app);
        RAISE EXCEPTION 'the V345 JUPEB check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('JUPEB V345: the old portal''s students — a preview writes nothing; a bad email refused, an unreadable NIN left out and said; STUDENT records on the old App No with a temporary password to change, announced to nobody, not twice, spared fee reminders; registration sets the programme',
        n_prev = 0 AND st_bad = 'INVALID' AND st_review = 'REVIEW' AND phone = '08089894004' AND dob = '2006-10-21'
        AND (done->>'applied')::int = 1 AND v_state = 'STUDENT' AND v_must AND v_told = 0
        AND (again->>'applied')::int = 0 AND (again->>'exists')::int = 1 AND v_fee = 0 AND n_reg = 3 AND v_stream = 'NON_SCIENCE',
        format('prev=%s bad=%s review=%s phone=%s dob=%s applied=%s state=%s must=%s told=%s again=%s/%s fee=%s reg=%s stream=%s',
               n_prev, st_bad, st_review, phone, dob, done->>'applied', v_state, v_must, v_told, again->>'applied', again->>'exists', v_fee, n_reg, v_stream));
END $$;

-- ── 191. V346: ICT Support resolves a student's problem through the engines, never around them — a support act filed on the ticket reaches its timeline; a capability reaches a student only through a posting that covers them; the registration window and the engine's menu are set aside only by an override written with the rule it set aside, never fees, units or a closed semester; a dropped course is kept as DROPPED; an entitlement is refreshed only for a confirmed payment and makes none; no password reaches the ledger and a temporary one always forces a change ──
DO $$
DECLARE who uuid := gen_random_uuid(); agent uuid; f_a text; d_a text; p_a text; f_b text; d_b text; st uuid := gen_random_uuid(); ses text := '2071/2072';
        o_a uuid := gen_random_uuid(); o_b uuid := gen_random_uuid(); o_c uuid := gen_random_uuid(); o_d uuid := gen_random_uuid(); o_e uuid := gen_random_uuid();
        reg1 uuid := gen_random_uuid(); reg2 uuid := gen_random_uuid(); tkt uuid; msg text; q text;
        r_blocked text; r_period text; r_fees text; r_units text; r_closed text; r_noticket text; r_unconfirmed text; r_pw text; r_temp text; r_caps text;
        added jsonb; dropped jsonb; refreshed jsonb; n_checks int; v_marked boolean; v_rule text; n_ev int; v_ev_detail text; n_kept int; v_drop_status text;
        caps_for text[]; n_refs_before int; n_refs_after int; v_ref text; v_ok_cap boolean := false;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'helpdeskhead', true);
        INSERT INTO iam.person (id, surname, given_names) VALUES (who, 'CHECKSUPPORTHEAD', 'Support');
        SELECT d.faculty_code, d.code, p.code INTO f_a, d_a, p_a FROM ref.department d JOIN ref.programme p ON p.dept_code = d.code AND NOT coalesce(p.archived, false)
         WHERE d.ended_on IS NULL ORDER BY d.code, p.code LIMIT 1;
        SELECT d.faculty_code, d.code INTO f_b, d_b FROM ref.department d WHERE d.ended_on IS NULL AND d.faculty_code <> f_a ORDER BY d.code LIMIT 1;
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), ses, make_date(2071, 10, 1), make_date(2072, 8, 31)) ON CONFLICT (name) DO NOTHING;
        -- the first semester is not yet open (the window is shut); the second is closed (its registrations are history)
        INSERT INTO policy.semester (id, session, number, state) VALUES (gen_random_uuid(), ses, 1, 'NOT_YET_OPEN'), (gen_random_uuid(), ses, 2, 'CLOSED');
        -- the student owes nothing from any other session, so the Bursary's clearance reads this session alone
        UPDATE finance.fee_schedule SET ended_at = now() WHERE ended_at IS NULL AND session < ses;
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (st, 'MOAUM/ADM/71/710191', 'MOAUM/CHK/71/000191', 'CHECKSUPPORTREG', 'Student', p_a, 'UTME', ses, 100, 100, 'ACTIVE', now());
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, state) VALUES
            ('CHK 191A', 'On the menu', 3, 1, 100, d_a, 'LIVE'), ('CHK 191B', 'Mapped to no programme', 3, 1, 300, d_b, 'LIVE'),
            ('CHK 191C', 'A second-semester course', 3, 2, 100, d_a, 'LIVE'), ('CHK 191D', 'Already registered', 3, 1, 100, d_a, 'LIVE'),
            ('CHK 191E', 'Another on the menu', 3, 1, 100, d_a, 'LIVE');
        INSERT INTO catalogue.course_offer (course_code, programme_code, level) VALUES ('CHK 191A', p_a, 100), ('CHK 191D', p_a, 100), ('CHK 191E', p_a, 100), ('CHK 191C', p_a, 100);
        INSERT INTO catalogue.offering (id, course_code, session, semester) VALUES (o_a, 'CHK 191A', ses, 1), (o_b, 'CHK 191B', ses, 1), (o_c, 'CHK 191C', ses, 2),
                                                                               (o_d, 'CHK 191D', ses, 1), (o_e, 'CHK 191E', ses, 1);
        INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, submitted_at, approved_at) VALUES
            (reg1, st, ses, 1, 100, 'APPROVED', now(), now()), (reg2, st, ses, 2, 100, 'APPROVED', now(), now());
        INSERT INTO registration.entry (registration_id, offering_id, units, status) VALUES (reg1, o_d, 3, 'APPROVED'), (reg2, o_c, 3, 'APPROVED');

        -- the window shut: refused without an override, and the rule named
        BEGIN PERFORM registration.support_add(st, ses, 1, o_a, false, who, 'asked'); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_blocked := split_part(msg, ':', 1); END;
        -- a course of another semester is never placed, override or not
        BEGIN PERFORM registration.support_add(st, ses, 1, o_c, true, who, 'asked'); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_period := split_part(msg, ':', 1); END;
        n_checks := (SELECT count(*) FROM registration.support_add_checks(st, ses, 1, o_b));
        -- a course mapped to no programme, the window shut: the override places it, the override named on the entry
        added := registration.support_add(st, ses, 1, o_b, true, who, 'Portal fault: the course is missing from the student''s list');
        v_marked := EXISTS (SELECT 1 FROM registration.entry WHERE registration_id = reg1 AND offering_id = o_b AND status = 'APPROVED' AND support_override_at IS NOT NULL);
        v_rule := added->>'normalRule';
        -- the override goes on the ledger only on a ticket, and the ticket's timeline takes it
        PERFORM set_config('moaum.actor_office', 'ictagent', true);
        BEGIN
            PERFORM helpdesk.record_support_action(st, NULL, 'COURSE_ADDED', 'CHK 191B', 'Not registered', 'Registered', 'Portal fault', ses, 1,
                    jsonb_build_object('override', true, 'normalRule', v_rule, 'description', 'Missing from the list'));
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_noticket := split_part(msg, ':', 1);
        END;
        tkt := helpdesk.submit('STUDENT', st, 'CHECKSUPPORTREG, Student', 'MOAUM/CHK/71/000191', 'check.support191@example.com', NULL, d_a, f_a, 'REGISTRATION', 'CHK 191B is missing', 'It is not on my list',
                               jsonb_build_object('session', ses, 'semester', '1', 'level', '100'));
        PERFORM helpdesk.record_support_action(st, tkt, 'COURSE_ADDED', 'CHK 191B', 'Not registered', 'Registered', 'Portal fault', ses, 1,
                jsonb_build_object('override', true, 'normalRule', v_rule, 'description', 'Missing from the list', 'summary', 'CHK 191B added to the first semester registration'));
        SELECT count(*), max(detail) INTO n_ev, v_ev_detail FROM helpdesk.ticket_event WHERE ticket_id = tkt AND action = 'SUPPORT_COURSE_ADDED';
        -- a drop is refused while the window is shut, and with the override the course is marked DROPPED, never deleted
        dropped := registration.support_drop(st, ses, 1, o_d, true, who, 'Registered in error by a portal fault');
        SELECT count(*), max(status) INTO n_kept, v_drop_status FROM registration.entry WHERE registration_id = reg1 AND offering_id = o_d;
        -- a closed semester's registration is history: not changed, override or not
        BEGIN PERFORM registration.support_drop(st, ses, 2, o_c, true, who, 'asked'); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_closed := split_part(msg, ':', 1); END;
        -- the fees are never set aside: a schedule for the session, unpaid, refuses the override
        INSERT INTO finance.fee_schedule (session, item, amount, level, programme_code) VALUES (ses, 'School fees', 50000, 100, p_a);
        BEGIN PERFORM registration.support_add(st, ses, 1, o_a, true, who, 'asked'); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_fees := split_part(msg, ':', 1); END;
        -- an entitlement follows only a confirmed payment, and the refresh makes no payment
        v_ref := finance.new_purpose_reference(st, ses, 50000, 'School fees ' || ses);
        BEGIN PERFORM finance.refresh_entitlement(v_ref); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_unconfirmed := split_part(msg, ':', 1); END;
        PERFORM finance.confirm_payment(v_ref, 'BANK_BRANCH', 'teller for the check');
        n_refs_before := (SELECT count(*) FROM finance.payment_reference WHERE student_id = st);
        refreshed := finance.refresh_entitlement(v_ref);
        n_refs_after := (SELECT count(*) FROM finance.payment_reference WHERE student_id = st);
        -- the unit ceiling is never set aside either
        UPDATE policy.level_limit SET max_units = 4, min_units = 0 WHERE level = 100;
        BEGIN PERFORM registration.support_add(st, ses, 1, o_e, true, who, 'asked'); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_units := split_part(msg, ':', 1); END;
        -- no password on the ledger; a temporary password always forces the change
        BEGIN
            PERFORM helpdesk.record_support_action(st, NULL, 'PASSWORD_RESET', NULL, NULL, 'Secret123', 'Locked out', NULL, NULL, jsonb_build_object('method', 'TEMPORARY_PASSWORD'));
        EXCEPTION WHEN check_violation THEN r_pw := 'REFUSED';
        END;
        BEGIN
            INSERT INTO iam.student_account (id, student_id, password_hash, must_change, temp_expires_at, temp_issued_by)
            VALUES (gen_random_uuid(), st, '$2a$12$abcdefghijklmnopqrstuuabcdefghijklmnopqrstuvwxyz12345', false, now() + interval '1 day', who);
        EXCEPTION WHEN check_violation THEN r_temp := 'REFUSED';
        END;
        -- a capability reaches a student only through a posting that covers them; a result-changing capability is not one
        PERFORM set_config('moaum.actor_office', 'helpdeskhead', true);
        INSERT INTO iam.person (id, surname, given_names) VALUES (gen_random_uuid(), 'CHECKSUPPORTCPO', 'Agent') RETURNING id INTO agent;
        SELECT code INTO q FROM helpdesk.queue WHERE active ORDER BY ordinal LIMIT 1;
        INSERT INTO helpdesk.agent_assignment (person_id, queue_code, scope_kind, scope_ref, capabilities) VALUES (agent, q, 'GLOBAL', NULL, ARRAY['VIEW_STUDENT']);
        INSERT INTO helpdesk.agent_assignment (person_id, queue_code, scope_kind, scope_ref, capabilities) VALUES (agent, q, 'FACULTY', f_b, ARRAY['OVERRIDE_REGISTRATION', 'RESET_PASSWORD']);
        v_ok_cap := true;
        caps_for := helpdesk.agent_capabilities_for(agent, st);
        BEGIN
            INSERT INTO helpdesk.agent_assignment (person_id, queue_code, scope_kind, scope_ref, capabilities) VALUES (agent, q, 'GLOBAL', NULL, ARRAY['EDIT_RESULTS']);
        EXCEPTION WHEN check_violation THEN r_caps := 'REFUSED';
        END;
        RAISE EXCEPTION 'the V346 support check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('ICT Support resolves through the engines, never around them: the window and the menu set aside only by an override named with the rule it set aside and filed on the ticket''s timeline; a course of another semester, unpaid fees, the unit ceiling and a closed semester never set aside; a drop marks DROPPED and keeps the entry; an entitlement refreshed only for a confirmed payment, making none; no password on the ledger; a temporary password forces a change; a capability reaches only the students its posting covers, and no result-changing one exists',
        r_blocked = 'REG_BLOCKED' AND r_period = 'REG_RULE' AND n_checks = 16 AND (added->>'overridden')::boolean AND v_marked AND v_rule LIKE '%not on the engine%'
        AND r_noticket = 'SUPPORT_OVERRIDE_TICKET' AND n_ev = 1 AND v_ev_detail LIKE 'NORMAL RULE: Registration blocked because %SUPPORT ACTION: Override approved because Portal fault%'
        AND (dropped->>'overridden')::boolean AND n_kept = 1 AND v_drop_status = 'DROPPED' AND r_closed = 'REG_RULE'
        AND r_fees = 'REG_RULE' AND r_unconfirmed = 'PAY_NOT_CONFIRMED' AND (refreshed->'after'->>'paidInFull')::boolean AND n_refs_before = n_refs_after
        AND r_units = 'REG_RULE' AND r_pw = 'REFUSED' AND r_temp = 'REFUSED'
        AND v_ok_cap AND caps_for = ARRAY['VIEW_STUDENT'] AND r_caps = 'REFUSED',
        format('blocked=%s period=%s checks=%s added=%s marked=%s rule=%s noticket=%s ev=%s/%s dropped=%s kept=%s/%s closed=%s fees=%s unconfirmed=%s refreshed=%s refs=%s/%s units=%s pw=%s temp=%s caps_for=%s caps=%s',
               r_blocked, r_period, n_checks, added->>'overridden', v_marked, v_rule, r_noticket, n_ev, left(v_ev_detail, 60), dropped->>'overridden', n_kept, v_drop_status, r_closed,
               r_fees, r_unconfirmed, refreshed->'after'->>'paidInFull', n_refs_before, n_refs_after, r_units, r_pw, r_temp, caps_for, r_caps));
END $$;

-- ── 192. V347: JUPEB — the old portal's payments posted once as confirmed fees (matched by App No, never a failed or repeated one) and the student then reached by fee reminders; a correction of identity details applied only on the office's approval; a practice test scored by the server with the answer key hidden until submission; a class never double-booked; ICT Support reaches JUPEB records only through a posting that does, its acts on the same ledger and only on the candidate's own ticket; the report reads the session ──
DO $$
DECLARE who uuid := gen_random_uuid(); ses text := jupeb.current_session(); app uuid; prev jsonb; done jsonb; again jsonb; v_kinds text[]; v_fee_status text;
        v_exempt_before boolean; v_exempt_after boolean; req uuid; v_surname_pending text; v_surname_after text; v_dob_after date; r_same text; msg text;
        t uuid; att uuid; q1 uuid; paper_before jsonb; paper_after jsonb; v_score int; r_clash text; s1 uuid; k uuid; agent uuid; tkt uuid; r_ticket text;
        caps_none text[]; caps_jupeb text[]; n_led int; rep jsonb; r_temp text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'jupeb', true);
        INSERT INTO iam.person (id, surname, given_names) VALUES (who, 'CHECKJUPEB347', 'Officer');
        PERFORM set_config('moaum.jupeb_quiet', 'on', true);
        done := jupeb.import_old_portal_students(jsonb_build_array(jsonb_build_object('row', 2, 'appNo', 'S0CHECK192001', 'firstName', 'Ada', 'surname', 'Check',
                     'sex', 'Female', 'phone', '08011112222', 'dob', '1/2/2005', 'email', 'zz.check192@example.com',
                     'passwordHash', '$2a$12$abcdefghijklmnopqrstuuabcdefghijklmnopqrstuvwxyz12345')), ses, true, true, 'check.xlsx', who);
        PERFORM set_config('moaum.jupeb_quiet', 'off', true);
        app := (SELECT id FROM jupeb.application WHERE application_no = 'S0CHECK192001');
        PERFORM jupeb.register_subjects(app, who, (SELECT id FROM jupeb.combination WHERE code = 'SC-001'));
        v_exempt_before := jupeb.reminder_exempt(app, 'SCHOOL_FEE_UNPAID');
        -- the old portal's payments: a preview writes nothing; a failed one, an unknown App No and a repeat are listed, not posted
        prev := jupeb.import_old_portal_payments(jsonb_build_array(
                    jsonb_build_object('row', 2, 'appNo', 's0check192001', 'reference', 'OLD-192-A', 'purpose', 'School Fees (First Instalment)', 'amount', '80,000', 'date', '15/11/2024', 'status', 'Successful'),
                    jsonb_build_object('row', 3, 'appNo', 'S0CHECK192001', 'reference', 'OLD-192-B', 'purpose', 'School Fees (Second Instalment)', 'amount', '40000', 'date', '15/01/2025', 'status', 'Failed'),
                    jsonb_build_object('row', 4, 'appNo', 'S0NOSUCH192', 'reference', 'OLD-192-C', 'purpose', 'Acceptance Fee', 'amount', '10000', 'date', '01/10/2024', 'status', 'Paid'),
                    jsonb_build_object('row', 5, 'appNo', 'S0CHECK192001', 'reference', 'OLD-192-A', 'purpose', 'School Fees (First Instalment)', 'amount', '80000', 'date', '15/11/2024', 'status', 'Paid')),
                true, false, 'pay.xlsx', who);
        done := jupeb.import_old_portal_payments(jsonb_build_array(
                    jsonb_build_object('row', 2, 'appNo', 's0check192001', 'reference', 'OLD-192-A', 'purpose', 'School Fees (First Instalment)', 'amount', '80,000', 'date', '15/11/2024', 'status', 'Successful')),
                true, true, 'pay.xlsx', who);
        again := jupeb.import_old_portal_payments(jsonb_build_array(
                    jsonb_build_object('row', 2, 'appNo', 'S0CHECK192001', 'reference', 'old-192-a', 'purpose', 'School Fees (First Instalment)', 'amount', '80000', 'date', '15/11/2024', 'status', 'Successful')),
                true, true, 'pay.xlsx', who);
        v_kinds := ARRAY(SELECT kind || ':' || channel FROM jupeb.fee_reference WHERE application_id = app AND confirmed_at IS NOT NULL ORDER BY kind);
        v_fee_status := (SELECT paid::text FROM jupeb.school_fees(app));
        v_exempt_after := jupeb.reminder_exempt(app, 'SCHOOL_FEE_UNPAID');
        -- a correction of identity details: pending, then applied on approval
        PERFORM set_config('moaum.actor_office', 'applicant', true);
        req := jupeb.request_correction(app, jsonb_build_object('surname', 'Checkmore', 'date_of_birth', '2005-02-01'), 'My surname is misspelt on the old portal record', app, 'applicant');
        v_surname_pending := (SELECT surname FROM jupeb.application WHERE id = app);
        BEGIN PERFORM jupeb.request_correction(app, jsonb_build_object('surname', 'X'), 'Another request while one is pending', app, 'applicant');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_same := split_part(msg, ':', 1); END;
        PERFORM set_config('moaum.actor_office', 'jupeb', true);
        PERFORM jupeb.decide_change(req, true, 'Birth certificate sighted', who, 'jupeb');
        SELECT surname, date_of_birth INTO v_surname_after, v_dob_after FROM jupeb.application WHERE id = app;
        -- a practice test: the answer key hidden until submission, then the score
        t := (SELECT id FROM jupeb.subject s WHERE s.id IN (SELECT subject_id FROM jupeb.subject_registration WHERE application_id = app) ORDER BY s.code LIMIT 1);
        INSERT INTO jupeb.practice_test (subject_id, title, questions_per_attempt, attempts_allowed, open) VALUES (t, 'Check practice', 2, 1, true) RETURNING id INTO t;
        PERFORM jupeb.practice_upload(t, jsonb_build_array(jsonb_build_object('row', 2, 'question', 'Two and two?', 'a', '3', 'b', '4', 'answer', 'B', 'explanation', 'Count them'),
                                                          jsonb_build_object('row', 3, 'question', 'Three and one?', 'a', '4', 'b', '5', 'answer', 'A'),
                                                          jsonb_build_object('row', 4, 'question', 'Bad row', 'a', '1', 'b', '2', 'answer', 'D')), false);
        att := jupeb.practice_start(app, t);
        paper_before := jupeb.practice_paper(app, att);
        q1 := (SELECT id FROM jupeb.practice_question WHERE test_id = t AND stem = 'Two and two?');
        PERFORM jupeb.practice_answer_set(app, att, q1, 'b');
        PERFORM jupeb.practice_submit(app, att);
        paper_after := jupeb.practice_paper(app, att);
        v_score := (SELECT score FROM jupeb.practice_attempt WHERE id = att);
        -- a room is never booked twice in the same hour (V351: parallel lectures in other rooms are the rule)
        s1 := (SELECT subject_id FROM jupeb.subject_registration WHERE application_id = app ORDER BY subject_id LIMIT 1);
        INSERT INTO jupeb.room (code) VALUES ('LT1') ON CONFLICT (code) DO NOTHING;  -- V354: a room is one of the list
        INSERT INTO jupeb.timetable_slot (session, semester, subject_id, weekday, starts_at, ends_at, venue) VALUES (ses, 1, s1, 2, '08:00', '10:00', 'LT 1');
        BEGIN
            INSERT INTO jupeb.timetable_slot (session, semester, subject_id, weekday, starts_at, ends_at, venue) VALUES (ses, 1, s1, 2, '09:00', '11:00', 'LT 1');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_clash := split_part(msg, ':', 1);
        END;
        -- ICT Support: no reach without a posting that reaches JUPEB; the JUPEB queue's posting does; the act on the ledger, only on the candidate's ticket
        PERFORM set_config('moaum.actor_office', 'helpdeskhead', true);
        INSERT INTO iam.person (id, surname, given_names) VALUES (gen_random_uuid(), 'CHECKJUPEBAGENT', 'Agent') RETURNING id INTO agent;
        INSERT INTO helpdesk.agent_assignment (person_id, queue_code, scope_kind, scope_ref, capabilities) VALUES (agent, 'ICT_SUPPORT', 'FACULTY', 'SC', ARRAY['RESET_PASSWORD']);
        caps_none := helpdesk.agent_jupeb_capabilities(agent);
        INSERT INTO helpdesk.agent_assignment (person_id, queue_code, scope_kind, scope_ref, capabilities) VALUES (agent, 'JUPEB_SUPPORT', 'GLOBAL', NULL, ARRAY['VIEW_STUDENT', 'EDIT_CONTACT']);
        caps_jupeb := helpdesk.agent_jupeb_capabilities(agent);
        PERFORM set_config('moaum.actor_id', agent::text, true);
        PERFORM set_config('moaum.actor_office', 'ictagent', true);
        tkt := helpdesk.submit('JUPEB', gen_random_uuid(), 'Someone else', NULL, 'someone@example.com', NULL, NULL, NULL, 'JUPEB', 'Not theirs', 'Another candidate''s ticket', jsonb_build_object('jupeb_issue', 'Other'));
        BEGIN PERFORM helpdesk.record_jupeb_support_action(app, tkt, 'CONTACT_EDITED', 'phone', '08011112222', '08033334444', 'Wrong ticket');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_ticket := split_part(msg, ':', 1); END;
        PERFORM helpdesk.record_jupeb_support_action(app, NULL, 'CONTACT_EDITED', 'phone', '08011112222', '08033334444', 'The student reported a new number at the desk');
        n_led := (SELECT count(*) FROM helpdesk.support_action WHERE jupeb_application_id = app AND student_id IS NULL);
        BEGIN
            UPDATE jupeb.account SET temp_expires_at = now() + interval '1 day', temp_issued_by = agent, must_change_password = false
             WHERE id = (SELECT account_id FROM jupeb.application WHERE id = app);
        EXCEPTION WHEN check_violation THEN r_temp := 'REFUSED';
        END;
        rep := jupeb.report(ses);
        RAISE EXCEPTION 'the V347 JUPEB check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('JUPEB V347: old-portal payments posted once as confirmed fees and the student then reminded; a correction applied only on approval; a practice test scored by the server, its key hidden until submission; no double-booked class; ICT Support reaches JUPEB only through a posting that does, on the same ledger and the candidate''s own ticket; the report reads the session',
        (prev->>'valid')::int = 1 AND (prev->>'invalid')::int = 2 AND (prev->>'exists')::int = 1 AND (done->>'applied')::int = 1 AND (again->>'applied')::int = 0
        AND v_kinds = ARRAY['SCHOOL_FIRST:Old portal'] AND v_fee_status::numeric = 80000 AND v_exempt_before AND NOT v_exempt_after
        AND v_surname_pending = 'CHECK' AND r_same = 'JUPEB_CHANGE_PENDING' AND v_surname_after = 'CHECKMORE' AND v_dob_after = '2005-02-01'
        AND NOT (paper_before->'questions'->0 ? 'answer') AND (paper_after->'questions'->0 ? 'answer') AND v_score = 1 AND jsonb_array_length(paper_before->'questions') = 2
        AND r_clash = 'JUPEB_SLOT_CLASH' AND caps_none = '{}'::text[] AND caps_jupeb = ARRAY['EDIT_CONTACT', 'VIEW_STUDENT'] AND r_ticket = 'SUPPORT_TICKET' AND n_led = 1
        AND r_temp = 'REFUSED' AND (rep->'enrolment'->'totals'->>'fromOldPortal')::int >= 1 AND jsonb_typeof(rep->'results') = 'array',
        format('prev=%s/%s/%s applied=%s again=%s kinds=%s fees=%s exempt=%s/%s pending=%s same=%s after=%s/%s key=%s/%s score=%s clash=%s caps=%s/%s ticket=%s ledger=%s temp=%s old=%s',
               prev->>'valid', prev->>'invalid', prev->>'exists', done->>'applied', again->>'applied', v_kinds, v_fee_status, v_exempt_before, v_exempt_after,
               v_surname_pending, r_same, v_surname_after, v_dob_after, paper_before->'questions'->0 ? 'answer', paper_after->'questions'->0 ? 'answer', v_score,
               r_clash, caps_none, caps_jupeb, r_ticket, n_led, r_temp, rep->'enrolment'->'totals'->>'fromOldPortal'));
END $$;

-- ── 193. V348: a stored file is held by every table that points at it — each column keeping an object id references platform.file_object, so the store's orphan sweep (which asks the catalogue, not a list) can never remove an object a row still shows; the JUPEB documents lost before are recorded and asked for again ──
DO $$
DECLARE unheld text; who uuid := gen_random_uuid(); app uuid; obj uuid; r_forget text := 'REMOVED'; n_lost_table int;
BEGIN
    unheld := (SELECT string_agg(c.table_schema || '.' || c.table_name, ', ' ORDER BY 1)
                 FROM information_schema.columns c JOIN information_schema.tables t
                   ON t.table_schema = c.table_schema AND t.table_name = c.table_name AND t.table_type = 'BASE TABLE'
                WHERE c.column_name = 'object_id' AND c.data_type = 'uuid' AND c.table_schema NOT IN ('pg_catalog', 'information_schema')
                  AND NOT (c.table_schema = 'platform' AND c.table_name = 'file_object')
                  AND NOT EXISTS (SELECT 1 FROM pg_constraint k
                                   WHERE k.contype = 'f' AND k.conrelid = (quote_ident(c.table_schema) || '.' || quote_ident(c.table_name))::regclass
                                     AND k.confrelid = 'platform.file_object'::regclass
                                     AND k.conkey = ARRAY[(SELECT a.attnum FROM pg_attribute a WHERE a.attrelid = k.conrelid AND a.attname = 'object_id')]));
    n_lost_table := (SELECT count(*) FROM information_schema.tables WHERE table_schema = 'jupeb' AND table_name = 'document_lost');
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'jupeb', true);
        PERFORM set_config('moaum.jupeb_quiet', 'on', true);
        INSERT INTO iam.person (id, surname, given_names) VALUES (who, 'CHECKFILES348', 'Officer');
        PERFORM jupeb.import_old_portal_students(jsonb_build_array(jsonb_build_object('row', 2, 'appNo', 'S0CHECK193001', 'firstName', 'Ada', 'surname', 'Check',
                     'sex', 'Female', 'phone', '08011112222', 'dob', '1/2/2005', 'email', 'zz.check193@example.com',
                     'passwordHash', '$2a$12$abcdefghijklmnopqrstuuabcdefghijklmnopqrstuvwxyz12345')), jupeb.current_session(), true, true, 'check.xlsx', who);
        app := (SELECT id FROM jupeb.application WHERE application_no = 'S0CHECK193001');
        INSERT INTO platform.file_object (id, object_key, content_type, size_bytes, sha256, owner_table, owner_id)
        VALUES (gen_random_uuid(), 'jupeb/document/check193/x.pdf', 'application/pdf', 5, '\x00'::bytea, 'jupeb.document', app::text) RETURNING id INTO obj;
        INSERT INTO jupeb.document (application_id, kind, filename, content_type, size_bytes, object_id) VALUES (app, 'NIN', 'nin.pdf', 'application/pdf', 5, obj);
        -- what FileObjects.forget does: the record first — refused while a document still points at it
        BEGIN
            DELETE FROM platform.file_object WHERE id = obj;
        EXCEPTION WHEN foreign_key_violation THEN r_forget := 'REFUSED';
        END;
        RAISE EXCEPTION 'the V348 files check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('A stored file is held by every table that points at it: each object id column references platform.file_object, so an object a JUPEB document (or any row) still shows is never removed',
        unheld IS NULL AND r_forget = 'REFUSED' AND n_lost_table = 1,
        format('unheld=%s forget=%s lost_table=%s', coalesce(unheld, 'none'), r_forget, n_lost_table));
END $$;

-- ── 194. V349: JUPEB — a notice reaches exactly its audience (the session, the stage, one class, combination or programme; never a withdrawn application) and is emailed only to those it reaches; a practice question answered once is never rewritten — an edit makes a new version that takes the image along, and a student sees an image only inside an attempt that drew it; the identity card is issued for an active student with a passport photograph, states no NIN, birth date or contact, and a replaced card stops verifying ──
DO $$
DECLARE who uuid := gen_random_uuid(); ses text := jupeb.current_session(); app uuid; other uuid; k uuid; n_all int; n_class int; n_mine int; n_other int; n_notified int;
        ann uuid; t uuid; q1 uuid; q2 uuid; att uuid; v_old_stem text; v_img_new boolean; v_visible boolean; v_hidden boolean; r_card text := 'ISSUED'; code1 text; code2 text;
        facts jsonb; v1 jsonb; v2 jsonb;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'jupeb', true);
        PERFORM set_config('moaum.jupeb_quiet', 'on', true);
        INSERT INTO iam.person (id, surname, given_names) VALUES (who, 'CHECKJUPEB349', 'Officer');
        PERFORM jupeb.import_old_portal_students(jsonb_build_array(
                    jsonb_build_object('row', 2, 'appNo', 'S0CHECK194001', 'firstName', 'Ada', 'surname', 'Check', 'sex', 'Female', 'phone', '08011112222', 'dob', '1/2/2005',
                                       'email', 'zz.check194a@example.com', 'passwordHash', '$2a$12$abcdefghijklmnopqrstuuabcdefghijklmnopqrstuvwxyz12345'),
                    jsonb_build_object('row', 3, 'appNo', 'S0CHECK194002', 'firstName', 'Ben', 'surname', 'Check', 'sex', 'Male', 'phone', '08011113333', 'dob', '1/3/2005',
                                       'email', 'zz.check194b@example.com', 'passwordHash', '$2a$12$abcdefghijklmnopqrstuuabcdefghijklmnopqrstuvwxyz12345')), ses, true, true, 'check.xlsx', who);
        PERFORM set_config('moaum.jupeb_quiet', 'off', true);
        app := (SELECT id FROM jupeb.application WHERE application_no = 'S0CHECK194001');
        other := (SELECT id FROM jupeb.application WHERE application_no = 'S0CHECK194002');
        PERFORM jupeb.register_subjects(app, who, (SELECT id FROM jupeb.combination WHERE code = 'SC-001'));
        INSERT INTO jupeb.class (session, name) VALUES (ses, 'CHECK 194 CLASS') RETURNING id INTO k;
        UPDATE jupeb.application SET class_id = k WHERE id = app;
        -- whom a notice reaches
        n_all := jupeb.announcement_reach(ses, 'STUDENTS', NULL);
        n_class := jupeb.announcement_reach(ses, 'CLASS', k::text);
        INSERT INTO jupeb.announcement (session, audience, audience_ref, title, body, send_email, created_by) VALUES (ses, 'CLASS', k::text, 'Class notice', 'For the class only.', true, who)
        RETURNING id INTO ann;
        n_notified := jupeb.announcement_notify(ann);
        n_mine := (SELECT count(*) FROM jupeb.application a WHERE a.id = app AND jupeb.audience_reaches(ses, 'CLASS', k::text, a));
        n_other := (SELECT count(*) FROM jupeb.application a WHERE a.id = other AND jupeb.audience_reaches(ses, 'CLASS', k::text, a));
        -- a question answered is versioned, its image along; the image only inside an attempt that drew it
        t := (SELECT subject_id FROM jupeb.subject_registration WHERE application_id = app ORDER BY subject_id LIMIT 1);
        INSERT INTO jupeb.practice_test (subject_id, title, questions_per_attempt, attempts_allowed, open) VALUES (t, 'Check 194', 1, 1, true) RETURNING id INTO t;
        q1 := jupeb.practice_add(t, jsonb_build_object('question', 'Energy is $\frac{1}{2}mv^2$?', 'a', 'Yes', 'b', 'No', 'answer', 'A'));
        INSERT INTO jupeb.practice_image (question_id, filename, content_type, size_bytes) VALUES (q1, 'd.png', 'image/png', 4);
        INSERT INTO jupeb.practice_image_blob (question_id, bytes) VALUES (q1, '\x89504e47'::bytea);
        att := jupeb.practice_start(app, t);
        v_visible := jupeb.practice_image_visible(app, att, q1);
        v_hidden := jupeb.practice_image_visible(other, att, q1);
        PERFORM jupeb.practice_answer_set(app, att, q1, 'A');
        PERFORM jupeb.practice_submit(app, att);
        q2 := jupeb.practice_edit(t, q1, jsonb_build_object('question', 'Kinetic energy is $\frac{1}{2}mv^2$?', 'a', 'Yes', 'b', 'No', 'answer', 'A'));
        v_img_new := EXISTS (SELECT 1 FROM jupeb.practice_image_blob WHERE question_id = q2);
        v_old_stem := (SELECT stem FROM jupeb.practice_question WHERE id = q1);
        -- the identity card
        BEGIN PERFORM jupeb.issue_paper(app, 'ID_CARD', NULL, true, who, 'jupeb');
        EXCEPTION WHEN check_violation THEN r_card := 'REFUSED';
        END;
        INSERT INTO jupeb.document (application_id, kind, filename, content_type, size_bytes) VALUES (app, 'PASSPORT', 'p.png', 'image/png', 4);
        code1 := jupeb.issue_paper(app, 'ID_CARD', NULL, true, who, 'jupeb');
        facts := (SELECT p.facts FROM jupeb.paper p WHERE p.code = code1);
        PERFORM jupeb.revoke_paper(code1, 'Card replaced: lost', who);
        code2 := jupeb.issue_paper(app, 'ID_CARD', NULL, true, who, 'jupeb');
        v1 := jupeb.verify_paper(code1);
        v2 := jupeb.verify_paper(code2);
        RAISE EXCEPTION 'the V349 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('JUPEB V349: a notice reaches exactly its audience and is emailed to them alone; an answered question is versioned with its image; the image is seen only in an attempt that drew it; the identity card needs a photograph, states no NIN, birth date or contact, and a replaced card stops verifying',
        n_all >= 1 AND n_class = 1 AND n_notified = 1 AND n_mine = 1 AND n_other = 0
        AND v_visible AND NOT v_hidden AND q2 <> q1 AND v_img_new AND v_old_stem = 'Energy is $\frac{1}{2}mv^2$?'
        AND r_card = 'REFUSED' AND facts->>'validFor' = ses AND NOT (facts ?| ARRAY['nin', 'dateOfBirth', 'email', 'phone'])
        AND code2 <> code1 AND (v1->>'revoked')::boolean AND (v2->>'genuine')::boolean,
        format('all=%s class=%s notified=%s mine=%s other=%s visible=%s/%s versioned=%s image=%s old=%s card=%s valid=%s codes=%s/%s revoked=%s genuine=%s',
               n_all, n_class, n_notified, n_mine, n_other, v_visible, v_hidden, q2 <> q1, v_img_new, v_old_stem, r_card, facts->>'validFor', code1, code2,
               v1->>'revoked', v2->>'genuine'));
END $$;

-- ── 195. V350: a JUPEB withdrawal opens a refund claim with the fees paid on the portal (none when nothing was paid); the Bursary raises a refund only once the candidate gave the account, through finance.refund, never beyond what was paid on the payment in all, maker and checker different; a claim with a refund raised is not declined; the paid refund is on the record; the day book names every JUPEB fee; practice results weakest first; a notice to one student reaches no other ──
DO $$
DECLARE maker uuid := gen_random_uuid(); checker uuid := gen_random_uuid(); ses text := jupeb.current_session(); app uuid; other uuid; claim uuid; ref text;
        n_claim_other int; r_details text; r_over text; r_same text; r_decline text; rf uuid; v_status text; v_paid numeric; n_ev int; v_label text; msg text;
        t uuid; att uuid; v_first uuid; n_reach int;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', maker::text, true);
        PERFORM set_config('moaum.actor_office', 'jupeb', true);
        PERFORM set_config('moaum.jupeb_quiet', 'on', true);
        INSERT INTO iam.person (id, surname, given_names) VALUES (maker, 'CHECKREFUND350', 'Maker'), (checker, 'CHECKREFUND350', 'Checker');
        PERFORM jupeb.import_old_portal_students(jsonb_build_array(
                    jsonb_build_object('row', 2, 'appNo', 'S0CHECK195001', 'firstName', 'Ada', 'surname', 'Check', 'sex', 'Female', 'phone', '08011112222', 'dob', '1/2/2005',
                                       'email', 'zz.check195a@example.com', 'passwordHash', '$2a$12$abcdefghijklmnopqrstuuabcdefghijklmnopqrstuvwxyz12345'),
                    jsonb_build_object('row', 3, 'appNo', 'S0CHECK195002', 'firstName', 'Ben', 'surname', 'Check', 'sex', 'Male', 'phone', '08011113333', 'dob', '1/3/2005',
                                       'email', 'zz.check195b@example.com', 'passwordHash', '$2a$12$abcdefghijklmnopqrstuuabcdefghijklmnopqrstuvwxyz12345')), ses, true, true, 'check.xlsx', maker);
        app := (SELECT id FROM jupeb.application WHERE application_no = 'S0CHECK195001');
        other := (SELECT id FROM jupeb.application WHERE application_no = 'S0CHECK195002');
        INSERT INTO jupeb.fee_reference (application_id, kind, reference, amount, session, expires_at, confirmed_at, channel)
        VALUES (app, 'ACCEPTANCE', 'CHECK195-ACC', 75000, ses, now(), now(), 'Bank') RETURNING reference INTO ref;
        -- the withdrawal opens the claim; one with nothing paid opens none
        UPDATE jupeb.application SET state = 'WITHDRAWN', withdrawn_at = now() WHERE id IN (app, other);
        claim := (SELECT id FROM jupeb.refund_claim WHERE application_id = app);
        n_claim_other := (SELECT count(*) FROM jupeb.refund_claim WHERE application_id = other);
        BEGIN PERFORM jupeb.propose_claim_refund(claim, ref, 50000, 'Withdrawal');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_details := split_part(msg, ':', 1); END;
        UPDATE jupeb.refund_claim SET bank_name = 'First Bank', account_name = 'Ada Check', account_number = '3012345671', details_at = now() WHERE id = claim;
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        rf := jupeb.propose_claim_refund(claim, ref, 50000, 'Withdrawal before lectures');
        BEGIN PERFORM jupeb.propose_claim_refund(claim, ref, 30000, 'The rest');
        EXCEPTION WHEN check_violation THEN r_over := 'REFUSED'; END;
        BEGIN PERFORM jupeb.decline_refund_claim(claim, 'Not refundable', maker);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_decline := split_part(msg, ':', 1); END;
        BEGIN PERFORM finance.approve_refund(rf);
        EXCEPTION WHEN check_violation THEN r_same := 'REFUSED'; END;
        PERFORM set_config('moaum.actor_id', checker::text, true);
        PERFORM finance.approve_refund(rf);
        PERFORM finance.pay_refund(rf, 'CHK-TRF-PAID', (now() AT TIME ZONE 'Africa/Lagos')::date);
        v_status := jupeb.refund_claim_state(claim)->>'status';
        v_paid := (jupeb.refund_claim_state(claim)->>'paid')::numeric;
        n_ev := (SELECT count(*) FROM jupeb.application_event WHERE application_id = app AND kind IN ('REFUND_CLAIM_OPENED', 'REFUND_PROPOSED', 'REFUND_PAID'));
        v_label := (SELECT purpose FROM finance.day_book(current_date, current_date) WHERE reference = 'CHECK195-ACC');
        -- practice results, and a notice to one student
        PERFORM set_config('moaum.actor_office', 'jupeb', true);
        UPDATE jupeb.application SET state = 'STUDENT', withdrawn_at = NULL WHERE id = other;
        PERFORM jupeb.register_subjects(other, maker, (SELECT id FROM jupeb.combination WHERE code = 'SC-001'));
        t := (SELECT subject_id FROM jupeb.subject_registration WHERE application_id = other ORDER BY subject_id LIMIT 1);
        INSERT INTO jupeb.practice_test (subject_id, title, questions_per_attempt, attempts_allowed, open) VALUES (t, 'Check 195', 1, 1, true) RETURNING id INTO t;
        PERFORM jupeb.practice_upload(t, jsonb_build_array(jsonb_build_object('row', 2, 'question', 'Q?', 'a', '1', 'b', '2', 'answer', 'B')), false);
        att := jupeb.practice_start(other, t);
        PERFORM jupeb.practice_answer_set(other, att, (SELECT id FROM jupeb.practice_question WHERE test_id = t), 'A');
        PERFORM jupeb.practice_submit(other, att);
        v_first := (SELECT application_id FROM jupeb.practice_results(ses) ORDER BY average, name LIMIT 1);
        n_reach := jupeb.announcement_reach(ses, 'STUDENT', other::text);
        RAISE EXCEPTION 'the V350 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('JUPEB V350: a withdrawal opens a refund claim (none when nothing was paid); the Bursary refunds through finance.refund only to the account given, never beyond what was paid, maker and checker apart, a raised claim not declined; the day book names the fee; practice results weakest first; a notice to one student reaches one',
        claim IS NOT NULL AND n_claim_other = 0 AND r_details = 'JUPEB_REFUND_DETAILS' AND r_over = 'REFUSED' AND r_decline = 'JUPEB_REFUND_RAISED' AND r_same = 'REFUSED'
        AND v_status = 'REFUND_PAID' AND v_paid = 50000 AND n_ev = 3 AND v_label = 'JUPEB acceptance fee' AND v_first = other AND n_reach = 1,
        format('claim=%s other=%s details=%s over=%s decline=%s same=%s status=%s paid=%s events=%s label=%s first=%s reach=%s',
               claim IS NOT NULL, n_claim_other, r_details, r_over, r_decline, r_same, v_status, v_paid, n_ev, v_label, v_first = other, n_reach));
END $$;

-- ── 196. V351: the JUPEB programme names its own current session — the JUPEB windows follow it, the University's stays as it is, and cleared the University's applies again; the 2026/2027 first-semester timetable is on the record, every course at least three hours a week and every practical at least two, each lecture with its course code; a room or a class is never booked twice in the same hour while lectures in other rooms run side by side; a course code is kept as the Board prints it ──
DO $$
DECLARE who uuid := gen_random_uuid(); named text; uni text; v_cur text; v_app text; v_uni text; v_back text; r_bad text;
        n_seed int; n_short int; n_prac int; n_short_prac int; n_nocode int; n_noroom int;
        s1 uuid; s2 uuid; k uuid; v_code text; r_room text; r_class text; r_code text; n_side int; msg text;
BEGIN
    named := (SELECT current_session FROM jupeb.setting WHERE session = '*');
    -- the timetable as the JUPEB Office gave it
    n_seed := (SELECT count(*) FROM jupeb.timetable_slot WHERE session = '2026/2027' AND semester = 1 AND active);
    n_short := (SELECT count(*) FROM (SELECT course_code FROM jupeb.timetable_slot WHERE session = '2026/2027' AND semester = 1 AND active AND NOT practical
                                       GROUP BY course_code HAVING sum(ends_at - starts_at) < interval '3 hours') x);
    n_prac := (SELECT count(DISTINCT subject_id) FROM jupeb.timetable_slot WHERE session = '2026/2027' AND semester = 1 AND active AND practical);
    n_short_prac := (SELECT count(*) FROM (SELECT subject_id FROM jupeb.timetable_slot WHERE session = '2026/2027' AND semester = 1 AND active AND practical
                                            GROUP BY subject_id HAVING sum(ends_at - starts_at) < interval '2 hours') x);
    n_nocode := (SELECT count(*) FROM jupeb.timetable_slot WHERE session = '2026/2027' AND semester = 1 AND active AND NOT practical AND course_code IS NULL);
    n_noroom := (SELECT count(*) FROM jupeb.timetable_slot WHERE session = '2026/2027' AND semester = 1 AND active AND venue IS NULL);
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'jupeb', true);
        uni := policy.application_session('POST_UTME_REGISTRATION');
        UPDATE jupeb.setting SET current_session = '2031/2032' WHERE session = '*';
        v_cur := jupeb.current_session();
        v_app := policy.application_session('JUPEB_APPLICATION');
        v_uni := policy.application_session('POST_UTME_REGISTRATION');
        UPDATE jupeb.setting SET current_session = NULL WHERE session = '*';
        v_back := jupeb.current_session();
        BEGIN UPDATE jupeb.setting SET current_session = '2031-2032' WHERE session = '*';
        EXCEPTION WHEN check_violation THEN r_bad := 'REFUSED'; END;
        -- a room or a class never twice in the same hour; other rooms side by side
        s1 := (SELECT id FROM jupeb.subject WHERE code = 'GEO');
        s2 := (SELECT id FROM jupeb.subject ORDER BY code OFFSET 1 LIMIT 1);
        INSERT INTO jupeb.class (session, name) VALUES ('2031/2032', 'CHECK196 A') RETURNING id INTO k;
        INSERT INTO jupeb.timetable_slot (session, semester, subject_id, class_id, weekday, starts_at, ends_at, venue, course_code)
        VALUES ('2031/2032', 1, s1, k, 1, '08:00', '10:00', 'LR8', 'gry001') RETURNING course_code INTO v_code;
        BEGIN INSERT INTO jupeb.timetable_slot (session, semester, subject_id, weekday, starts_at, ends_at, venue) VALUES ('2031/2032', 1, s2, 1, '09:00', '10:00', 'lr 8');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_room := split_part(msg, ':', 1); END;
        BEGIN INSERT INTO jupeb.timetable_slot (session, semester, subject_id, class_id, weekday, starts_at, ends_at, venue) VALUES ('2031/2032', 1, s2, k, 1, '09:00', '11:00', 'LR9');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_class := split_part(msg, ':', 1); END;
        INSERT INTO jupeb.timetable_slot (session, semester, subject_id, weekday, starts_at, ends_at, venue) VALUES ('2031/2032', 1, s2, 1, '08:00', '10:00', 'LR9');
        INSERT INTO jupeb.timetable_slot (session, semester, subject_id, weekday, starts_at, ends_at, venue) VALUES ('2031/2032', 1, s2, 1, '10:00', '11:00', 'LR8');
        n_side := (SELECT count(*) FROM jupeb.timetable_slot WHERE session = '2031/2032' AND active);
        BEGIN INSERT INTO jupeb.timetable_slot (session, semester, subject_id, weekday, starts_at, ends_at, venue, course_code) VALUES ('2031/2032', 2, s1, 1, '08:00', '09:00', 'LR8', 'GEOGRAPHY 1');
        EXCEPTION WHEN check_violation THEN r_code := 'REFUSED'; END;
        RAISE EXCEPTION 'the V351 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('JUPEB V351: the JUPEB Office names the programme''s current session (2026/2027) and the JUPEB windows follow it, the University''s untouched, cleared the University''s again; the 2026/2027 first-semester timetable has every course three hours and every practical two, each lecture coded; a room or a class never twice in an hour, other rooms side by side; a course code as the Board prints it',
        -- cleared, JUPEB falls back to the University's current session (since V378 Post-UTME is filed under the intake session instead)
        named = '2026/2027' AND v_cur = '2031/2032' AND v_app = '2031/2032' AND v_uni = uni AND v_back = policy.university_current_session() AND r_bad = 'REFUSED'
        AND n_seed = 56 AND n_short = 0 AND n_prac = 3 AND n_short_prac = 0 AND n_nocode = 0 AND n_noroom = 1
        AND v_code = 'GRY 001' AND r_room = 'JUPEB_SLOT_CLASH' AND r_class = 'JUPEB_SLOT_CLASH' AND n_side = 3 AND r_code = 'REFUSED',
        format('named=%s current=%s app=%s uni=%s/%s back=%s/%s bad=%s seed=%s short=%s prac=%s short_prac=%s nocode=%s noroom=%s code=%s room=%s class=%s side=%s badcode=%s',
               named, v_cur, v_app, v_uni, uni, v_back, policy.university_current_session(), r_bad, n_seed, n_short, n_prac, n_short_prac, n_nocode, n_noroom, v_code, r_room, r_class, n_side, r_code));
END $$;

-- ── 197. V353: the JUPEB syllabus 2027–2031 — nineteen of the Board's subjects under the portal's, 77 course units with their semesters, credit units and topics (BIO 002 Botany in the first semester, as the Biology section has it); a combination's courses: MAT 004A for a Science combination, 004B for a Management Sciences one, and both options of an either/or subject until the student chooses, then that one only; the option is one of the subject's own, chosen by the student only until the examination number and changed by the office only with a reason; a timetable course is one of the subject's units, taught in that semester; the live timetable says ECN and GRY, each lecture linked to its unit ──
DO $$
DECLARE who uuid := gen_random_uuid(); ses text := jupeb.current_session(); acc uuid; app uuid; sub uuid; crs uuid; iss uuid; yor uuid; bio uuid; msg text;
        n_board int; n_units int; n_topics int; v_bio text; v_bio_sem int; v_mat_sci text; v_mat_mgt text; n_sc001 int; n_mine int; v_mine text;
        r_wrong text; r_locked text; r_reason text; v_final text; n_events int; r_course text; r_sem text; n_old int; n_unlinked int;
BEGIN
    n_board := (SELECT count(*) FROM jupeb.board_subject b JOIN jupeb.syllabus y ON y.id = b.syllabus_id WHERE y.code = '2027-2031');
    n_units := (SELECT count(*) FROM jupeb.subject_unit WHERE board_subject_id IS NOT NULL AND semester IS NOT NULL AND credit_units = 3);
    n_topics := (SELECT count(*) FROM jupeb.unit_topic);
    SELECT title, semester INTO v_bio, v_bio_sem FROM jupeb.subject_unit WHERE code = 'BIO 002';
    v_mat_sci := (SELECT string_agg(u.code, ',') FROM jupeb.units_for((SELECT id FROM jupeb.combination WHERE code = 'SC-038'), NULL) u WHERE u.code LIKE 'MAT 004%');
    v_mat_mgt := (SELECT string_agg(u.code, ',') FROM jupeb.units_for((SELECT id FROM jupeb.combination WHERE code = 'SC-024'), NULL) u WHERE u.code LIKE 'MAT 004%');
    n_sc001 := (SELECT count(*) FROM jupeb.units_for((SELECT id FROM jupeb.combination WHERE code = 'SC-001'), NULL));
    n_old := (SELECT count(*) FROM jupeb.timetable_slot WHERE session = '2026/2027' AND course_code ~ '^(ECO|GEO) ');
    n_unlinked := (SELECT count(*) FROM jupeb.timetable_slot WHERE session = '2026/2027' AND course_code IS NOT NULL AND unit_id IS NULL);
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'jupeb', true);
        PERFORM set_config('moaum.jupeb_quiet', 'on', true);
        INSERT INTO iam.person (id, surname, given_names) VALUES (who, 'CHECKSYLLABUS353', 'Officer');
        INSERT INTO jupeb.account (email, password_hash) VALUES ('zz.check197@example.com', '$2a$12$abcdefghijklmnopqrstuuabcdefghijklmnopqrstuvwxyz12345') RETURNING id INTO acc;
        INSERT INTO jupeb.application (account_id, session, application_no, surname, first_name, email, stream, combination_id, state)
        VALUES (acc, ses, 'CHECK197/0001', 'CHECK', 'Option', 'zz.check197@example.com', 'NON_SCIENCE', (SELECT id FROM jupeb.combination WHERE code = 'SC-001'), 'STUDENT')
        RETURNING id INTO app;
        PERFORM jupeb.register_subjects(app, who, (SELECT id FROM jupeb.combination WHERE code = 'SC-001'));
        sub := (SELECT id FROM jupeb.subject WHERE code = 'CRS/ISS');
        crs := (SELECT id FROM jupeb.board_subject WHERE prefix = 'CRS');
        iss := (SELECT id FROM jupeb.board_subject WHERE prefix = 'ISS');
        yor := (SELECT id FROM jupeb.board_subject WHERE prefix = 'YOR');
        BEGIN PERFORM jupeb.choose_option(app, sub, yor, false, NULL);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_wrong := split_part(msg, ':', 1); END;
        PERFORM jupeb.choose_option(app, sub, iss, false, NULL);
        n_mine := (SELECT count(*) FROM jupeb.units_for(NULL, app));
        v_mine := (SELECT string_agg(DISTINCT u.prefix, ',') FROM jupeb.units_for(NULL, app) u WHERE u.subject_code = 'CRS/ISS');
        UPDATE jupeb.application SET exam_no = 'CHK197000001' WHERE id = app;
        BEGIN PERFORM jupeb.choose_option(app, sub, crs, false, NULL);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_locked := split_part(msg, ':', 1); END;
        BEGIN PERFORM jupeb.choose_option(app, sub, crs, true, NULL);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_reason := split_part(msg, ':', 1); END;
        PERFORM jupeb.choose_option(app, sub, crs, true, 'The candidate sits Christian Religious Studies');
        v_final := (SELECT b.prefix FROM jupeb.subject_registration r JOIN jupeb.board_subject b ON b.id = r.board_subject_id WHERE r.application_id = app AND r.subject_id = sub);
        n_events := (SELECT count(*) FROM jupeb.application_event WHERE application_id = app AND kind = 'SUBJECT_OPTION');
        -- the timetable: a course of the subject, in its semester
        bio := (SELECT id FROM jupeb.subject WHERE code = 'BIO');
        BEGIN INSERT INTO jupeb.timetable_slot (session, semester, subject_id, weekday, starts_at, ends_at, venue, course_code) VALUES ('2031/2032', 1, bio, 6, '08:00', '09:00', 'LR8', 'BIO 009');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_course := split_part(msg, ':', 1); END;
        BEGIN INSERT INTO jupeb.timetable_slot (session, semester, subject_id, weekday, starts_at, ends_at, venue, course_code) VALUES ('2031/2032', 1, bio, 6, '08:00', '09:00', 'LR8', 'bio003');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_sem := split_part(msg, ':', 1); END;
        RAISE EXCEPTION 'the V353 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('JUPEB V353: the syllabus 2027–2031 — 19 Board subjects, 77 units with semesters and topics, BIO 002 Botany in the first semester; MAT 004A for Science, 004B for Management Sciences; both options until chosen, then that one; an option among the subject''s own, by the student until the examination number, by the office with a reason; a timetable course is a unit of the subject in its semester; ECN and GRY on the live timetable, each lecture linked',
        n_board = 19 AND n_units = 77 AND n_topics = 946 AND v_bio = 'Botany' AND v_bio_sem = 1 AND v_mat_sci = 'MAT 004A' AND v_mat_mgt = 'MAT 004B' AND n_sc001 = 16
        AND r_wrong = 'JUPEB_OPTION' AND n_mine = 12 AND v_mine = 'ISS' AND r_locked = 'JUPEB_OPTION_LOCKED' AND r_reason = 'JUPEB_OPTION_REASON' AND v_final = 'CRS' AND n_events = 2
        AND r_course = 'JUPEB_SLOT_COURSE' AND r_sem = 'JUPEB_SLOT_SEMESTER' AND n_old = 0 AND n_unlinked = 0,
        format('board=%s units=%s topics=%s bio002=%s/%s mat=%s|%s sc001=%s wrong=%s mine=%s/%s locked=%s reason=%s final=%s events=%s course=%s sem=%s old=%s unlinked=%s',
               n_board, n_units, n_topics, v_bio, v_bio_sem, v_mat_sci, v_mat_mgt, n_sc001, r_wrong, n_mine, v_mine, r_locked, r_reason, v_final, n_events, r_course, r_sem, n_old, n_unlinked));
END $$;

-- ── 198. V354: the Board's 2026/2027 calendar is on the record and copied forward a year as a plan (titles' years too); the semester is the second only from the day the calendar says; a venue is one of the list of rooms, a closed room takes no new lecture, a renamed room renames its lectures; a semester's timetable copies into the next with each course moved to its place (MAT 002 → MAT 004A, 004B noted), never into one with lectures; a lecture's register opens from its slot on its weekday only, once, apart from another lecture of the subject that day; a lecture not held is not opened, and one with marks is not called not held; the lectures due say which is which; a notice to a subject reaches its students only; the clearance says what is outstanding ──
DO $$
DECLARE who uuid := gen_random_uuid(); ses text := jupeb.current_session(); today date := (now() AT TIME ZONE 'Africa/Lagos')::date; wd int := extract(isodow FROM (now() AT TIME ZONE 'Africa/Lagos')::date)::int;
        n_cal int; v_teach date; v_reg date; v_exams date; v_sem_now int; v_sem_before int; v_sem_after int; n_copy int; v_exam28 date; v_title28 text; v_planned boolean; r_cal text;
        geo uuid; acc uuid; lr8 uuid; r_room text; r_closed text; v_renamed text; n_tt int; v_gry text; v_mat text; v_mat_note text; r_tt text;
        sa uuid; sb uuid; ra uuid; ra2 uuid; rb uuid; r_day text; v_state_a text; v_state_b text; r_notheld text; r_marked text;
        acct uuid; app uuid; v_reach_mine boolean; v_reach_other boolean; v_clear boolean; v_out text[]; msg text;
BEGIN
    n_cal := (SELECT count(*) FROM jupeb.calendar_event WHERE session = '2026/2027' AND source = 'BOARD' AND removed_at IS NULL);
    v_teach := jupeb.calendar_date('2026/2027', 'TEACHING_STARTS');
    v_reg := jupeb.calendar_date('2026/2027', 'BOARD_REGISTRATION');
    v_exams := jupeb.calendar_date('2026/2027', 'EXAMINATIONS');
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'jupeb', true);
        PERFORM set_config('moaum.jupeb_quiet', 'on', true);
        INSERT INTO iam.person (id, surname, given_names) VALUES (who, 'CHECKCALENDAR354', 'Officer');
        -- the semester by the calendar, the calendar copied forward
        v_sem_now := jupeb.current_semester('2026/2027', DATE '2026-10-07');
        INSERT INTO jupeb.calendar_event (session, starts_on, title, marker) VALUES ('2026/2027', '2027-02-15', 'Second semester lectures begin', 'SEMESTER_2_STARTS');
        v_sem_before := jupeb.current_semester('2026/2027', DATE '2027-02-14');
        v_sem_after := jupeb.current_semester('2026/2027', DATE '2027-03-01');
        n_copy := jupeb.copy_calendar('2026/2027', '2027/2028', who);
        SELECT starts_on, title, planned INTO v_exam28, v_title28, v_planned FROM jupeb.calendar_event WHERE session = '2027/2028' AND marker = 'EXAMINATIONS';
        BEGIN PERFORM jupeb.copy_calendar('2026/2027', '2027/2028', who);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_cal := split_part(msg, ':', 1); END;
        -- the rooms
        geo := (SELECT id FROM jupeb.subject WHERE code = 'GEO');
        acc := (SELECT id FROM jupeb.subject WHERE code = 'ACC');
        lr8 := (SELECT id FROM jupeb.room WHERE code = 'LR8');
        BEGIN INSERT INTO jupeb.timetable_slot (session, semester, subject_id, weekday, starts_at, ends_at, venue) VALUES ('2031/2032', 1, geo, 7, '08:00', '09:00', 'Hall Z 99');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_room := split_part(msg, ':', 1); END;
        INSERT INTO jupeb.room (code, kind, active) VALUES ('CHK198', 'HALL', false);
        BEGIN INSERT INTO jupeb.timetable_slot (session, semester, subject_id, weekday, starts_at, ends_at, venue) VALUES ('2031/2032', 1, geo, 7, '08:00', '09:00', 'chk 198');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_closed := split_part(msg, ':', 1); END;
        UPDATE jupeb.room SET active = true WHERE code = 'CHK198';
        INSERT INTO jupeb.timetable_slot (session, semester, subject_id, weekday, starts_at, ends_at, venue) VALUES ('2031/2032', 1, geo, 7, '08:00', '09:00', 'chk 198');
        UPDATE jupeb.room SET code = 'chk 199' WHERE code = 'CHK198';
        v_renamed := (SELECT venue FROM jupeb.timetable_slot WHERE session = '2031/2032' AND weekday = 7 AND starts_at = '08:00');
        -- the first semester copied into the second
        n_tt := jupeb.copy_timetable('2026/2027', 1, '2026/2027', 2, who);
        v_gry := (SELECT string_agg(DISTINCT course_code, ',') FROM jupeb.timetable_slot WHERE session = '2026/2027' AND semester = 2 AND course_code LIKE 'GRY%');
        SELECT course_code, note INTO v_mat, v_mat_note FROM jupeb.timetable_slot WHERE session = '2026/2027' AND semester = 2 AND course_code LIKE 'MAT 004%' LIMIT 1;
        BEGIN PERFORM jupeb.copy_timetable('2026/2027', 1, '2026/2027', 2, who);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_tt := split_part(msg, ':', 1); END;
        -- two lectures of a subject today: a register each, from the slot, on its weekday only
        INSERT INTO jupeb.timetable_slot (session, semester, subject_id, weekday, starts_at, ends_at, room_id) VALUES ('2031/2032', 1, acc, wd, '10:00', '11:00', lr8) RETURNING id INTO sa;
        INSERT INTO jupeb.timetable_slot (session, semester, subject_id, weekday, starts_at, ends_at, room_id) VALUES ('2031/2032', 1, acc, wd, '14:00', '15:00', lr8) RETURNING id INTO sb;
        ra := jupeb.open_lecture_register(sa, today, who);
        ra2 := jupeb.open_lecture_register(sa, today, who);
        BEGIN PERFORM jupeb.open_lecture_register(sa, today - 1, who);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_day := split_part(msg, ':', 1); END;
        PERFORM jupeb.record_not_held(sb, today, 'Public holiday declared', who, 'jupeb');
        BEGIN rb := jupeb.open_lecture_register(sb, today, who);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_notheld := split_part(msg, ':', 1); END;
        v_state_a := (SELECT state FROM jupeb.lectures_due('2031/2032', today, today) WHERE slot_id = sa);
        v_state_b := (SELECT state FROM jupeb.lectures_due('2031/2032', today, today) WHERE slot_id = sb);
        INSERT INTO attendance.mark (register_id, member_ref, status, marked_by) VALUES (ra, gen_random_uuid(), 'PRESENT', who);
        BEGIN PERFORM jupeb.record_not_held(sa, today, 'It was not held after all', who, 'jupeb');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_marked := split_part(msg, ':', 1); END;
        -- a notice to a subject's students; the clearance of a student with much outstanding
        INSERT INTO jupeb.account (email, password_hash) VALUES ('zz.check198@example.com', '$2a$12$abcdefghijklmnopqrstuuabcdefghijklmnopqrstuvwxyz12345') RETURNING id INTO acct;
        INSERT INTO jupeb.application (account_id, session, application_no, surname, first_name, email, stream, combination_id, state)
        VALUES (acct, ses, 'CHECK198/0001', 'CHECK', 'Clearance', 'zz.check198@example.com', 'NON_SCIENCE', (SELECT id FROM jupeb.combination WHERE code = 'SC-001'), 'STUDENT')
        RETURNING id INTO app;
        PERFORM jupeb.register_subjects(app, who, (SELECT id FROM jupeb.combination WHERE code = 'SC-001'));
        v_reach_mine := jupeb.audience_reaches(ses, 'SUBJECT', (SELECT id::text FROM jupeb.subject WHERE code = 'GOV'), (SELECT a FROM jupeb.application a WHERE a.id = app));
        v_reach_other := jupeb.audience_reaches(ses, 'SUBJECT', acc::text, (SELECT a FROM jupeb.application a WHERE a.id = app));
        SELECT cleared, outstanding INTO v_clear, v_out FROM jupeb.exam_clearance(ses) WHERE application_id = app;
        RAISE EXCEPTION 'the V354 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('JUPEB V354: the Board''s 2026/2027 calendar, copied forward a year as a plan; the second semester only from its day; rooms from the list, a closed one refused, a rename followed; the first semester copied into the second (MAT 004A, 004B noted), never into one with lectures; a register per lecture from its slot on its weekday; not held, not opened; marked, not called not held; the lectures due say which; a subject''s notice reaches its students; the clearance says what is outstanding',
        n_cal = 36 AND v_teach = DATE '2026-09-28' AND v_reg = DATE '2026-11-13' AND v_exams = DATE '2027-07-26'
        AND v_sem_now = 1 AND v_sem_before = 1 AND v_sem_after = 2 AND n_copy = 37 AND v_exam28 = DATE '2028-07-26' AND v_title28 = '2028 examinations in all universities' AND v_planned
        AND r_cal = 'JUPEB_CALENDAR_EXISTS' AND r_room = 'JUPEB_ROOM_UNKNOWN' AND r_closed = 'JUPEB_ROOM_CLOSED' AND v_renamed = 'CHK199'
        AND n_tt = 56 AND v_gry = 'GRY 003,GRY 004' AND v_mat = 'MAT 004A' AND v_mat_note LIKE '%MAT 004B%' AND r_tt = 'JUPEB_TIMETABLE_NOT_EMPTY'
        AND ra = ra2 AND r_day = 'ATT_SLOT_DAY' AND r_notheld = 'JUPEB_LECTURE_NOT_HELD' AND v_state_a = 'OPEN' AND v_state_b = 'NOT_HELD' AND r_marked = 'JUPEB_LECTURE_RECORDED'
        AND v_reach_mine AND NOT v_reach_other AND NOT v_clear
        AND 'Say which is taken: Christian / Islamic Religious Studies' = ANY (v_out) AND 'No examination number from the Board yet' = ANY (v_out)
        AND NOT ('No minimum attendance is set' = ANY (v_out)),
        format('cal=%s teach=%s reg=%s exams=%s sem=%s/%s/%s copy=%s exam28=%s title28=%s planned=%s again=%s room=%s closed=%s renamed=%s tt=%s gry=%s mat=%s/%s ttagain=%s same=%s day=%s notheld=%s states=%s/%s marked=%s reach=%s/%s cleared=%s out=%s',
               n_cal, v_teach, v_reg, v_exams, v_sem_now, v_sem_before, v_sem_after, n_copy, v_exam28, v_title28, v_planned, r_cal, r_room, r_closed, v_renamed, n_tt, v_gry,
               v_mat, v_mat_note, r_tt, ra = ra2, r_day, r_notheld, v_state_a, v_state_b, r_marked, v_reach_mine, v_reach_other, v_clear, v_out));
END $$;

-- ── 199. V355: a record goes to the Board only when ready, and one changed since it was sent is flagged with what changed until the correction is sent; a correction asked is said; the topics a lecture covered are its course's and count to the course's coverage; an assessment score is within its part's maximum, the total out of the parts', and a locked subject takes none; a calendar reminder is sent once; the examination timetable is read from an upload, its papers shown to a student once published (the option they sit), and an admit card only for one cleared; a practice question names a course and topic of the syllabus; a mock is sat once, in its window, its results held until released ──
DO $$
DECLARE who uuid := gen_random_uuid(); ses text := jupeb.current_session(); today date := (now() AT TIME ZONE 'Africa/Lagos')::date; wd int := extract(isodow FROM (now() AT TIME ZONE 'Africa/Lagos')::date)::int;
        acct uuid; app uuid; sub uuid; iss uuid; gov uuid; msg text;
        v_problems text[]; r_notready text; v_ready boolean; v_changed boolean; v_facts text[]; v_after boolean; r_note text; v_stage text;
        slot uuid; reg uuid; n_topics int; t1 uuid; t2 uuid; other_topic uuid; r_topic text; v_covered int;
        c1 uuid; c2 uuid; r_range text; v_total numeric; v_out numeric; v_complete boolean; r_locked text;
        ev uuid; v_rem1 jsonb; v_rem2 jsonb; n_rem int;
        v_upload jsonb; n_before int; n_after int; v_iss_papers int; v_admit jsonb;
        tst uuid; q1 uuid; r_tag text; v_tagged boolean; mock uuid; r_mock_ck text; r_window text; att uuid; v_paper jsonb; n_topics_before int; n_topics_after int;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'jupeb', true);
        PERFORM set_config('moaum.jupeb_quiet', 'on', true);
        INSERT INTO iam.person (id, surname, given_names) VALUES (who, 'CHECKEXAMYEAR355', 'Officer');
        INSERT INTO jupeb.account (email, password_hash) VALUES ('zz.check199@example.com', '$2a$12$abcdefghijklmnopqrstuuabcdefghijklmnopqrstuvwxyz12345') RETURNING id INTO acct;
        INSERT INTO jupeb.application (account_id, session, application_no, surname, first_name, email, stream, combination_id, state)
        VALUES (acct, ses, 'CHECK199/0001', 'CHECK', 'Board', 'zz.check199@example.com', 'NON_SCIENCE', (SELECT id FROM jupeb.combination WHERE code = 'SC-001'), 'STUDENT')
        RETURNING id INTO app;
        PERFORM jupeb.register_subjects(app, who, (SELECT id FROM jupeb.combination WHERE code = 'SC-001'));
        sub := (SELECT id FROM jupeb.subject WHERE code = 'CRS/ISS');
        gov := (SELECT id FROM jupeb.subject WHERE code = 'GOV');
        iss := (SELECT id FROM jupeb.board_subject WHERE prefix = 'ISS');
        -- the Board: not ready, then ready and sent; a change flagged; a correction asked and sent
        v_problems := jupeb.board_problems(app);
        BEGIN PERFORM jupeb.board_mark(ARRAY[app], ses, 'SENT', NULL, NULL, who, 'jupeb');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_notready := split_part(msg, ':', 1); END;
        UPDATE jupeb.application SET sex = 'F', date_of_birth = '2007-01-02', nin = '12345678901', phone = '08012340199', state_of_origin = 'Benue', lga = 'Makurdi' WHERE id = app;
        PERFORM jupeb.choose_option(app, sub, iss, false, NULL);
        INSERT INTO jupeb.document (application_id, kind, filename, content_type, size_bytes) VALUES (app, 'PASSPORT', 'p.jpg', 'image/jpeg', 10);
        v_ready := (SELECT ready FROM jupeb.board_status(ses) WHERE application_id = app);
        PERFORM jupeb.board_mark(ARRAY[app], ses, 'SENT', NULL, NULL, who, 'jupeb');
        UPDATE jupeb.application SET phone = '08012340299' WHERE id = app;
        SELECT changed, changed_facts INTO v_changed, v_facts FROM jupeb.board_status(ses) WHERE application_id = app;
        BEGIN PERFORM jupeb.board_mark(ARRAY[app], ses, 'CORRECTION_NEEDED', '', NULL, who, 'jupeb');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_note := split_part(msg, ':', 1); END;
        PERFORM jupeb.board_mark(ARRAY[app], ses, 'CORRECTED', 'Phone corrected', NULL, who, 'jupeb');
        SELECT changed, stage INTO v_after, v_stage FROM jupeb.board_status(ses) WHERE application_id = app;
        -- the syllabus covered: a lecture's topics are its course's
        INSERT INTO jupeb.timetable_slot (session, semester, subject_id, weekday, starts_at, ends_at, room_id, course_code)
        VALUES ('2031/2032', 1, gov, wd, '07:00', '08:00', (SELECT id FROM jupeb.room WHERE code = 'LR8'), 'GOV 001') RETURNING id INTO slot;
        reg := jupeb.open_lecture_register(slot, today, who);
        n_topics := (SELECT count(*) FROM jupeb.register_topics(reg));
        SELECT topic_id INTO t1 FROM jupeb.register_topics(reg) ORDER BY ord LIMIT 1;
        SELECT topic_id INTO t2 FROM jupeb.register_topics(reg) ORDER BY ord OFFSET 1 LIMIT 1;
        other_topic := (SELECT x.id FROM jupeb.unit_topic x JOIN jupeb.subject_unit u ON u.id = x.unit_id WHERE u.code = 'GOV 002' LIMIT 1);
        BEGIN PERFORM jupeb.set_register_topics(reg, ARRAY[t1, other_topic], who);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_topic := split_part(msg, ':', 1); END;
        PERFORM jupeb.set_register_topics(reg, ARRAY[t1, t2], who);
        v_covered := (SELECT covered FROM jupeb.coverage('2031/2032', 1) WHERE code = 'GOV 001');
        -- continuous assessment
        INSERT INTO jupeb.ca_component (session, code, title, max_score, ord) VALUES (ses, 'CHK199A', 'Test one', 10, 1) RETURNING id INTO c1;
        INSERT INTO jupeb.ca_component (session, code, title, max_score, ord) VALUES (ses, 'CHK199B', 'Assignment', 20, 2) RETURNING id INTO c2;
        BEGIN PERFORM jupeb.ca_save(app, gov, c1, 12, who, 'lecturer');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_range := split_part(msg, ':', 1); END;
        PERFORM jupeb.ca_save(app, gov, c1, 8, who, 'lecturer');
        PERFORM jupeb.ca_save(app, gov, c2, 15, who, 'lecturer');
        SELECT total, out_of, complete INTO v_total, v_out, v_complete FROM jupeb.ca_sheet(ses, gov, NULL) WHERE application_id = app;
        INSERT INTO jupeb.ca_lock (session, subject_id, locked_by) VALUES (ses, gov, who);
        BEGIN PERFORM jupeb.ca_save(app, gov, c1, 9, who, 'lecturer');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_locked := split_part(msg, ':', 1); END;
        -- a reminder, once
        INSERT INTO jupeb.calendar_event (session, starts_on, title, for_students) VALUES (ses, today + 7, 'Check 199 lecture-free day', true) RETURNING id INTO ev;
        v_rem1 := jupeb.send_calendar_reminders(now(), '');
        v_rem2 := jupeb.send_calendar_reminders(now(), '');
        n_rem := (SELECT count(*) FROM jupeb.calendar_reminder WHERE event_id = ev AND audience = 'STUDENTS');
        -- the examination timetable: uploaded, held until published; the option the student sits; no admit card uncleared
        n_before := (SELECT count(*) FROM jupeb.exam_schedule(app, false));
        v_upload := jupeb.exam_paper_upload(ses, jsonb_build_array(
            jsonb_build_object('row', 2, 'subject', 'GOV', 'paper', 'Government Paper I', 'kind', 'CBT', 'date', '2027-07-26', 'start', '09:00', 'end', '11:00'),
            jsonb_build_object('row', 3, 'subject', 'ISS', 'paper', 'Islamic Studies Paper I', 'kind', 'PAPER', 'date', '27/07/2027', 'start', '09:00', 'end', '11:00'),
            jsonb_build_object('row', 4, 'subject', 'CRS', 'paper', 'Christian Religious Studies Paper I', 'date', '2027-07-27', 'start', '09:00', 'end', '11:00'),
            jsonb_build_object('row', 5, 'subject', 'Astronomy', 'paper', 'Stars', 'date', '2027-07-28', 'start', '09:00', 'end', '11:00')), false, who);
        INSERT INTO jupeb.exam_timetable (session, published_at, published_by) VALUES (ses, now(), who)
        ON CONFLICT (session) DO UPDATE SET published_at = now();
        n_after := (SELECT count(*) FROM jupeb.exam_schedule(app, false) WHERE title LIKE '%Paper I');
        v_iss_papers := (SELECT count(*) FROM jupeb.exam_schedule(app, false) WHERE title LIKE 'Christian%');
        v_admit := jupeb.paper_facts(app, 'ADMIT_CARD', NULL, true);
        -- practice by topic; the mock
        INSERT INTO jupeb.practice_test (subject_id, title, questions_per_attempt, attempts_allowed, open) VALUES (gov, 'Check 199 practice', 1, 3, true) RETURNING id INTO tst;
        q1 := jupeb.practice_add(tst, jsonb_build_object('question', 'Q?', 'a', '1', 'b', '2', 'answer', 'A', 'course', 'gov001', 'topic', '1'));
        v_tagged := (SELECT unit_id IS NOT NULL AND topic_id IS NOT NULL FROM jupeb.practice_question WHERE id = q1);
        BEGIN PERFORM jupeb.practice_add(tst, jsonb_build_object('question', 'Q2?', 'a', '1', 'b', '2', 'answer', 'A', 'course', 'GOV 009'));
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_tag := split_part(msg, ':', 1); END;
        BEGIN INSERT INTO jupeb.practice_test (subject_id, title, kind, attempts_allowed, opens_at, closes_at) VALUES (gov, 'Check 199 bad mock', 'MOCK', 2, now(), now() + interval '1 hour');
        EXCEPTION WHEN check_violation THEN r_mock_ck := 'REFUSED'; END;
        INSERT INTO jupeb.practice_test (subject_id, title, kind, questions_per_attempt, attempts_allowed, open, opens_at, closes_at)
        VALUES (gov, 'Check 199 mock', 'MOCK', 1, 1, true, now() + interval '1 day', now() + interval '2 days') RETURNING id INTO mock;
        PERFORM jupeb.practice_add(mock, jsonb_build_object('question', 'M?', 'a', '1', 'b', '2', 'answer', 'A', 'course', 'GOV 001', 'topic', '1'));
        BEGIN PERFORM jupeb.practice_start(app, mock);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_window := split_part(msg, ':', 1); END;
        UPDATE jupeb.practice_test SET opens_at = now() - interval '1 hour' WHERE id = mock;
        att := jupeb.practice_start(app, mock);
        PERFORM jupeb.practice_answer_set(app, att, (SELECT question_ids[1] FROM jupeb.practice_attempt WHERE id = att), 'A');
        PERFORM jupeb.practice_submit(app, att);
        v_paper := jupeb.practice_paper(app, att);
        n_topics_before := (SELECT count(*) FROM jupeb.practice_topics(app));
        UPDATE jupeb.practice_test SET results_released_at = now() WHERE id = mock;
        n_topics_after := (SELECT count(*) FROM jupeb.practice_topics(app));
        RAISE EXCEPTION 'the V355 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('JUPEB V355: to the Board only when ready, a change flagged until corrected; a lecture''s topics its course''s, counted to its coverage; an assessment within its maxima, locked against change; a reminder once; the examination timetable from an upload, published, the option sat; no admit card uncleared; practice by syllabus topic; a mock once, in its window, results held until released',
        'No passport photograph' = ANY (v_problems) AND 'Say which is taken: Christian / Islamic Religious Studies' = ANY (v_problems) AND r_notready = 'JUPEB_BOARD_NOT_READY' AND v_ready
        AND v_changed AND v_facts = ARRAY['phone'] AND r_note = 'JUPEB_BOARD_NOTE' AND NOT v_after AND v_stage = 'CORRECTED'
        AND n_topics > 1 AND r_topic = 'JUPEB_COVERAGE_TOPIC' AND v_covered = 2
        AND r_range = 'JUPEB_CA_RANGE' AND v_total = 23 AND v_out = 30 AND v_complete AND r_locked = 'JUPEB_CA_LOCKED'
        AND (v_rem1->>'students')::int >= 1 AND (v_rem2->>'students')::int = 0 AND n_rem = 1
        AND (v_upload->>'added')::int = 3 AND jsonb_array_length(v_upload->'refused') = 1 AND n_before = 0 AND n_after = 2 AND v_iss_papers = 0 AND v_admit IS NULL
        AND v_tagged AND r_tag = 'JUPEB_PRACTICE_TOPIC' AND r_mock_ck = 'REFUSED' AND r_window = 'JUPEB_MOCK_WINDOW'
        AND (v_paper->'attempt'->>'score') IS NULL AND (v_paper->'attempt'->>'resultsHeld')::boolean AND n_topics_before = 0 AND n_topics_after = 1,
        format('problems=%s notready=%s ready=%s changed=%s/%s note=%s after=%s/%s topics=%s topic=%s covered=%s range=%s total=%s/%s complete=%s locked=%s rem=%s/%s/%s upload=%s before=%s after=%s crs=%s admit=%s tagged=%s tag=%s mockck=%s window=%s paper=%s held=%s pt=%s/%s',
               v_problems, r_notready, v_ready, v_changed, v_facts, r_note, v_after, v_stage, n_topics, r_topic, v_covered, r_range, v_total, v_out, v_complete, r_locked,
               v_rem1, v_rem2, n_rem, v_upload, n_before, n_after, v_iss_papers, v_admit IS NULL, v_tagged, r_tag, r_mock_ck, r_window,
               v_paper->'attempt'->>'score', v_paper->'attempt'->>'resultsHeld', n_topics_before, n_topics_after));
END $$;

-- ── 200. V356: the next JUPEB session is set up from the last item by item, only into what it does not have of its own — the classes before the lectures and lecturers that name them (a class matched by name), a lecturer who has left not carried, the calendar a year on and planned; the fees only by the Bursary, into a session on the University's calendar; every carry on the record; a lecturer's practice by topic counts their classes only ──
DO $$
DECLARE who uuid := gen_random_uuid(); gone uuid := gen_random_uuid(); stays uuid := gen_random_uuid(); fr text := '2088/2089'; t text := '2089/2090'; msg text;
        gov uuid; ka uuid; kb uuid; ka2 uuid; v_plan_before text; r_first text; r_exists text; r_fees_office text; r_no_session text; r_later text; r_nothing text;
        v_classes jsonb; v_tt jsonb; v_lect jsonb; v_cal jsonb; v_fees jsonb; v_set jsonb; v_ca jsonb; v_pol jsonb;
        v_slot_class text; v_lect_class text; v_first_day date; v_planned boolean; v_fee numeric; v_plan_after text; n_log int;
        acct uuid; acct2 uuid; atp uuid; app1 uuid; app2 uuid; tst uuid; q uuid; att uuid; n_mine int; n_all int;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'jupeb', true);
        PERFORM set_config('moaum.jupeb_quiet', 'on', true);
        INSERT INTO iam.person (id, surname, given_names) VALUES (who, 'CHECKROLL356', 'Officer');
        INSERT INTO iam.person (id, surname, given_names, ended_on, ended_reason) VALUES (gone, 'CHECKROLL356', 'Gone', current_date - 1, 'retired');
        INSERT INTO iam.person (id, surname, given_names) VALUES (stays, 'CHECKROLL356', 'Stays');
        gov := (SELECT id FROM jupeb.subject WHERE code = 'GOV');
        -- 2088/2089 as a session set up in full
        INSERT INTO jupeb.setting (session, application_prefix, screening_required, screening_venue, screening_starts_on, exam_month, updated_by)
        VALUES (fr, 'JUPEB/APP', true, 'JUPEB Hall', date '2088-11-02', 'July 2089', who);
        INSERT INTO jupeb.class (session, name, capacity, created_by) VALUES (fr, 'CHK A', 40, who) RETURNING id INTO ka;
        INSERT INTO jupeb.class (session, name, capacity, created_by) VALUES (fr, 'CHK B', 40, who) RETURNING id INTO kb;
        INSERT INTO jupeb.calendar_event (session, ord, starts_on, title, marker, for_students, created_by) VALUES (fr, 1, date '2088-09-25', 'Teaching commences 2088', 'TEACHING_STARTS', true, who);
        INSERT INTO jupeb.timetable_slot (session, semester, class_id, subject_id, weekday, starts_at, ends_at, room_id, course_code)
        VALUES (fr, 1, ka, gov, 2, '08:00', '09:00', (SELECT id FROM jupeb.room WHERE code = 'LR8'), 'GOV 001');
        INSERT INTO jupeb.ca_component (session, code, title, max_score, created_by) VALUES (fr, 'TEST1', 'First test', 15, who);
        INSERT INTO attendance.policy (context, session, min_percent, min_classes, updated_by) VALUES ('JUPEB', fr, 75, 5, who);
        INSERT INTO attendance.instructor (context, session, subject_ref, class_ref, person_id, assigned_by) VALUES ('JUPEB', fr, gov, ka, stays, who), ('JUPEB', fr, gov, NULL, gone, who);
        INSERT INTO jupeb.fee_setting (session, application_fee, checking_fee, acceptance_fee, first_percent, allow_full, activation, indigene_state, updated_by, updated_office)
        VALUES (fr, 16000, 1200, 16000, 60, true, 'FIRST_INSTALMENT', 'Benue', who, 'bursar');
        INSERT INTO jupeb.school_fee (session, category, indigene, amount, updated_by, updated_office) VALUES (fr, 'SCIENCE', false, 230000, who, 'bursar');
        v_plan_before := (SELECT string_agg(item || '=' || state, ',' ORDER BY item) FROM jupeb.rollover_plan(fr, t));
        -- the lectures and lecturers name classes the next session has not: the classes first
        BEGIN PERFORM jupeb.rollover_carry(fr, t, 'TIMETABLE', who, 'jupeb');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_first := split_part(msg, ':', 1); END;
        v_classes := jupeb.rollover_carry(fr, t, 'CLASSES', who, 'jupeb');
        BEGIN PERFORM jupeb.rollover_carry(fr, t, 'CLASSES', who, 'jupeb');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_exists := split_part(msg, ':', 1); END;
        v_tt := jupeb.rollover_carry(fr, t, 'TIMETABLE', who, 'jupeb');
        v_lect := jupeb.rollover_carry(fr, t, 'LECTURERS', who, 'jupeb');
        v_cal := jupeb.rollover_carry(fr, t, 'CALENDAR', who, 'jupeb');
        v_set := jupeb.rollover_carry(fr, t, 'SETTINGS', who, 'jupeb');
        v_ca := jupeb.rollover_carry(fr, t, 'CA_PARTS', who, 'jupeb');
        v_pol := jupeb.rollover_carry(fr, t, 'ATTENDANCE_POLICY', who, 'jupeb');
        ka2 := (SELECT id FROM jupeb.class WHERE session = t AND name = 'CHK A');
        v_slot_class := (SELECT k.name FROM jupeb.timetable_slot s JOIN jupeb.class k ON k.id = s.class_id WHERE s.session = t);
        v_lect_class := (SELECT coalesce(k.name, 'every class') FROM attendance.instructor i LEFT JOIN jupeb.class k ON k.id = i.class_ref WHERE i.session = t AND i.person_id = stays);
        SELECT starts_on, planned INTO v_first_day, v_planned FROM jupeb.calendar_event WHERE session = t;
        -- the fees: the Bursary's, into a session on the University's calendar; never the JUPEB Office's
        BEGIN PERFORM jupeb.rollover_carry(fr, t, 'FEES', who, 'jupeb');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_fees_office := split_part(msg, ':', 1); END;
        BEGIN PERFORM jupeb.carry_fees(fr, t, who, 'bursar');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_no_session := split_part(msg, ':', 1); END;
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), t, date '2089-09-01', date '2090-08-31') ON CONFLICT (name) DO NOTHING;
        v_fees := jupeb.carry_fees(fr, t, who, 'bursar');
        v_fee := jupeb.school_fee_amount(t, 'SCIENCE', false);
        BEGIN PERFORM jupeb.rollover_carry(t, fr, 'CLASSES', who, 'jupeb');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_later := split_part(msg, ':', 1); END;
        BEGIN PERFORM jupeb.rollover_carry('2090/2091', '2091/2092', 'CA_PARTS', who, 'jupeb');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_nothing := split_part(msg, ':', 1); END;
        v_plan_after := (SELECT string_agg(item || '=' || state, ',' ORDER BY item) FROM jupeb.rollover_plan(fr, t));
        n_log := (SELECT count(*) FROM jupeb.session_rollover WHERE from_session = fr AND to_session = t);
        -- a lecturer's classes only: two students, one in class A, practising Government by topic
        INSERT INTO jupeb.account (email, password_hash) VALUES ('zz.check200@example.com', '$2a$12$abcdefghijklmnopqrstuuabcdefghijklmnopqrstuvwxyz12345') RETURNING id INTO acct;
        INSERT INTO jupeb.application (account_id, session, application_no, surname, first_name, email, stream, combination_id, class_id, state)
        VALUES (acct, fr, 'CHECK200/0001', 'CHECK', 'A', 'zz.check200@example.com', 'NON_SCIENCE', (SELECT id FROM jupeb.combination WHERE code = 'SC-001'), ka, 'STUDENT') RETURNING id INTO app1;
        INSERT INTO jupeb.account (email, password_hash) VALUES ('zz.check200b@example.com', '$2a$12$abcdefghijklmnopqrstuuabcdefghijklmnopqrstuvwxyz12345') RETURNING id INTO acct2;
        INSERT INTO jupeb.application (account_id, session, application_no, surname, first_name, email, stream, combination_id, class_id, state)
        VALUES (acct2, fr, 'CHECK200/0002', 'CHECK', 'B', 'zz.check200b@example.com', 'NON_SCIENCE', (SELECT id FROM jupeb.combination WHERE code = 'SC-001'), kb, 'STUDENT') RETURNING id INTO app2;
        INSERT INTO jupeb.practice_test (subject_id, title, duration_minutes, questions_per_attempt, attempts_allowed, show_answers, open) VALUES (gov, 'CHK topics', 10, 1, 5, true, true) RETURNING id INTO tst;
        INSERT INTO jupeb.practice_question (test_id, ordinal, stem, option_a, option_b, answer, unit_id, topic_id)
        SELECT tst, 1, 'Government is', 'x', 'y', 'A', u.id, (SELECT x.id FROM jupeb.unit_topic x WHERE x.unit_id = u.id ORDER BY x.ord LIMIT 1)
          FROM jupeb.subject_unit u WHERE u.code = 'GOV 001' RETURNING id INTO q;
        FOR att IN SELECT unnest(ARRAY[app1, app2]) LOOP
            INSERT INTO jupeb.practice_attempt (test_id, application_id, number, question_ids, ends_at, total, submitted_at) VALUES (tst, att, 1, ARRAY[q], now() + interval '1 hour', 1, now())
            RETURNING id INTO atp;
            INSERT INTO jupeb.practice_answer (attempt_id, question_id, chosen, correct) VALUES (atp, q, 'A', true);
        END LOOP;
        n_mine := (SELECT sum(students) FROM jupeb.practice_topics_classes(fr, gov, ARRAY[ka]));
        n_all := (SELECT sum(students) FROM jupeb.practice_topics_class(fr, gov, NULL));
        RAISE EXCEPTION 'the V356 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('JUPEB V356: the next session from the last, item by item, never over its own; the classes first, matched by name; a lecturer who left not carried; the calendar a year on, planned; the fees the Bursary''s alone, into a session on the calendar; every carry recorded; a lecturer''s classes only',
        v_plan_before = 'ATTENDANCE_POLICY=READY,CALENDAR=READY,CA_PARTS=READY,CLASSES=READY,FEES=READY,LECTURERS=READY,SETTINGS=READY,TIMETABLE=READY'
        AND r_first = 'JUPEB_ROLLOVER_CLASSES_FIRST' AND (v_classes->>'carried')::int = 2 AND r_exists = 'JUPEB_ROLLOVER_EXISTS'
        AND (v_tt->>'carried')::int = 1 AND v_slot_class = 'CHK A' AND (v_lect->>'carried')::int = 1 AND (v_lect->>'skipped')::int = 1 AND v_lect_class = 'CHK A'
        AND (v_cal->>'carried')::int = 1 AND v_first_day = date '2089-09-25' AND v_planned
        AND (v_set->>'carried')::int = 1 AND (v_ca->>'carried')::int = 1 AND (v_pol->>'carried')::int = 1
        AND r_fees_office = 'JUPEB_ROLLOVER_FEES' AND r_no_session = 'JUPEB_ROLLOVER_NO_SESSION' AND (v_fees->>'carried')::int = 2 AND v_fee = 230000
        AND r_later = 'JUPEB_ROLLOVER_LATER' AND r_nothing = 'JUPEB_ROLLOVER_NOTHING'
        AND v_plan_after = 'ATTENDANCE_POLICY=DONE,CALENDAR=DONE,CA_PARTS=DONE,CLASSES=DONE,FEES=DONE,LECTURERS=DONE,SETTINGS=DONE,TIMETABLE=DONE' AND n_log = 8
        AND n_mine = 1 AND n_all = 2,
        format('before=%s first=%s classes=%s exists=%s tt=%s/%s lect=%s/%s cal=%s/%s/%s set=%s ca=%s pol=%s feesoffice=%s nosession=%s fees=%s/%s later=%s nothing=%s after=%s log=%s mine=%s all=%s',
               v_plan_before, r_first, v_classes, r_exists, v_tt, v_slot_class, v_lect, v_lect_class, v_cal, v_first_day, v_planned, v_set, v_ca, v_pol,
               r_fees_office, r_no_session, v_fees, v_fee, r_later, r_nothing, v_plan_after, n_log, n_mine, n_all));
END $$;

-- ── 201. V357: each stage of a sheet is taken (and a sheet returned) only by its own desk; a script is held only on a sheet at entry, and a mark released only into a sheet at entry — an approval while the sheet is with a later desk waits, does not lapse, and is released when the sheet is returned; a published sheet tells each student by email, with one text a day ──
DO $$
DECLARE o1 uuid := gen_random_uuid(); o2 uuid := gen_random_uuid(); o3 uuid := gen_random_uuid();
        sh1 uuid := gen_random_uuid(); sh2 uuid := gen_random_uuid(); sh3 uuid := gen_random_uuid();
        st uuid := gen_random_uuid(); late uuid := gen_random_uuid(); reg uuid := gen_random_uuid(); reg2 uuid := gen_random_uuid();
        stg text; wrong text; n_refused int := 0; n_taken int := 0; r_return text; r_hold text; hid uuid; msg text;
        had_sem boolean; old_late date; v_wait timestamptz; v_state_wait text; v_state_lapse text; v_state_after text; v_mark boolean; v_mark_before boolean;
        n_mail int; n_text int; n_mail2 int; n_text2 int; v_same boolean;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state)
        VALUES ('CHK 357', 'Check Desks', 3, 1, 100, 'MTC', 'Core', 'LIVE'), ('CHK 358', 'Check Publication', 3, 1, 100, 'MTC', 'Core', 'LIVE'),
               ('CHK 359', 'Check Waiting', 3, 1, 100, 'MTC', 'Core', 'LIVE');
        INSERT INTO catalogue.offering (id, course_code, session, semester) VALUES (o1, 'CHK 357', '9999/0000', 1), (o2, 'CHK 358', '9999/0000', 1), (o3, 'CHK 359', '9999/0000', 1);
        INSERT INTO assessment.score_sheet (id, offering_id) VALUES (sh1, o1), (sh2, o2), (sh3, o3);
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (st, 'MOAUM/ADM/99/993571', 'MOAUM/CHK/99/3571', 'CHECKDESK', 'Invented', 'C00023', 'UTME', '9999/0000', 100, 100, 'ACTIVE', now()),
               (late, 'MOAUM/ADM/99/993572', 'MOAUM/CHK/99/3572', 'CHECKWAIT', 'Invented', 'C00023', 'UTME', '9999/0000', 100, 100, 'ACTIVE', now());
        INSERT INTO people.student_contact (student_id, email, phone) VALUES (st, 'zz.check201@example.com', '08012340201')
        ON CONFLICT (student_id) DO UPDATE SET email = EXCLUDED.email, phone = EXCLUDED.phone;
        INSERT INTO assessment.score (sheet_id, student_id, ca, exam) VALUES (sh1, st, 30, 40), (sh2, st, 20, 30);

        -- each stage refused to another desk, taken by its own; a return refused to a desk not holding the sheet
        LOOP
            stg := (SELECT stage FROM assessment.score_sheet WHERE id = sh1);
            EXIT WHEN stg = 'PUBLISHED';
            wrong := CASE WHEN stg = 'FACULTY_BOARD' THEN 'hod' ELSE 'dean' END;
            PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
            PERFORM set_config('moaum.actor_office', wrong, true);
            BEGIN
                PERFORM assessment.advance(sh1, NULL, 'SEN/9999/357');
            EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
                IF split_part(msg, ':', 1) = 'RES_NOT_YOUR_STAGE' THEN n_refused := n_refused + 1; END IF;
            END;
            IF stg = 'DEPT_BOARD' THEN
                PERFORM set_config('moaum.actor_office', 'exams', true);
                BEGIN PERFORM assessment.return_sheet(sh1, 'not mine to return');
                EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_return := split_part(msg, ':', 1); END;
            END IF;
            PERFORM set_config('moaum.actor_office', (assessment.stage_offices(stg))[1], true);
            PERFORM assessment.advance(sh1, NULL, CASE WHEN stg = 'SENATE' THEN 'SEN/9999/357' END);
            n_taken := n_taken + 1;
        END LOOP;
        n_mail := (SELECT count(*) FROM platform.notice WHERE channel = 'EMAIL' AND about_kind = 'student' AND about_id = st AND subject = 'Your result in CHK 357 is published'
                     AND body NOT LIKE '%70%');
        n_text := (SELECT count(*) FROM platform.notice WHERE channel = 'SMS' AND about_kind = 'student' AND about_id = st AND subject = 'Results published');
        -- a second sheet published the same day: another email, no second text
        UPDATE assessment.score_sheet SET stage = 'SENATE' WHERE id = sh2;
        PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
        PERFORM set_config('moaum.actor_office', 'dregistrar', true);
        PERFORM assessment.advance(sh2, NULL, 'SEN/9999/358');
        n_mail2 := (SELECT count(*) FROM platform.notice WHERE channel = 'EMAIL' AND about_kind = 'student' AND about_id = st AND subject LIKE 'Your result in CHK 35_ is published');
        n_text2 := (SELECT count(*) FROM platform.notice WHERE channel = 'SMS' AND about_kind = 'student' AND about_id = st AND subject = 'Results published');

        -- a script is held only on a sheet at entry
        PERFORM set_config('moaum.actor_office', 'lecturer', true);
        BEGIN PERFORM assessment.hold_script(sh2, 'MOAUM/CHK/99/3572', 20, 30, NULL, NULL);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_hold := split_part(msg, ':', 1); END;
        -- held at entry; the sheet moves on; the registration approved in time: the mark waits, off the sheet
        SELECT EXISTS (SELECT 1 FROM policy.semester WHERE session = '9999/0000' AND number = 1) INTO had_sem;
        IF NOT had_sem THEN INSERT INTO policy.semester (id, session, number, state) VALUES (gen_random_uuid(), '9999/0000', 1, 'CLOSED'); END IF;
        SELECT late_registration_closes INTO old_late FROM policy.semester WHERE session = '9999/0000' AND number = 1;
        UPDATE policy.semester SET late_registration_closes = current_date + 7 WHERE session = '9999/0000' AND number = 1;
        hid := assessment.hold_script(sh3, 'MOAUM/CHK/99/3572', 20, 30, NULL, NULL);
        UPDATE assessment.score_sheet SET stage = 'DEPT_BOARD' WHERE id = sh3;
        PERFORM set_config('moaum.actor_office', 'hod', true);
        INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, approved_at) VALUES (reg, late, '9999/0000', 1, 100, 'APPROVED', now());
        INSERT INTO registration.entry (registration_id, offering_id, units, status) VALUES (reg, o3, 3, 'APPROVED');
        SELECT state, waiting_since INTO v_state_wait, v_wait FROM assessment.held_script WHERE id = hid;
        v_mark_before := EXISTS (SELECT 1 FROM assessment.latest_scores(sh3) x WHERE x.student_id = late);
        -- past the late-registration date it does not lapse while it waits
        UPDATE policy.semester SET late_registration_closes = current_date - 1 WHERE session = '9999/0000' AND number = 1;
        PERFORM assessment.lapse_held_scripts();
        v_state_lapse := (SELECT state FROM assessment.held_script WHERE id = hid);
        -- the Head of Department returns the sheet: the waiting mark is released into it
        PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
        PERFORM assessment.return_sheet(sh3, 'a held script waits for the sheet');
        v_state_after := (SELECT state FROM assessment.held_script WHERE id = hid);
        v_mark := EXISTS (SELECT 1 FROM assessment.latest_scores(sh3) x WHERE x.student_id = late AND x.total = 50);
        UPDATE policy.semester SET late_registration_closes = old_late WHERE session = '9999/0000' AND number = 1;
        v_same := (SELECT array_agg(s ORDER BY s) FROM unnest(assessment.stage_offices('ENTRY')) s) = ARRAY['eps', 'exams', 'gst', 'lecturer'];
        RAISE EXCEPTION 'the V357 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V357: each of the eight stages refused to another desk and taken by its own, a return refused to a desk not holding the sheet; one email a published sheet (no mark in it) and one text a day; a script held only at entry; an approval while the sheet is with a later desk waits, does not lapse, and is released when the sheet is returned',
        n_refused = 8 AND n_taken = 8 AND r_return = 'RES_NOT_YOUR_STAGE' AND n_mail = 1 AND n_text = 1 AND n_mail2 = 2 AND n_text2 = 1
        AND r_hold = 'HELD_SHEET_NOT_AT_ENTRY' AND v_state_wait = 'HELD' AND v_wait IS NOT NULL AND NOT v_mark_before AND v_state_lapse = 'HELD'
        AND v_state_after = 'RELEASED' AND v_mark AND v_same,
        format('refused=%s taken=%s return=%s mail=%s text=%s mail2=%s text2=%s hold=%s wait=%s/%s before=%s lapse=%s after=%s mark=%s entry=%s',
               n_refused, n_taken, r_return, n_mail, n_text, n_mail2, n_text2, r_hold, v_state_wait, v_wait IS NOT NULL, v_mark_before, v_state_lapse, v_state_after, v_mark, v_same));
END $$;

-- ── 202. V358: a published mark is corrected only by an amendment — raised by the desk of entry with its reason (the query answered CORRECTED linked), approved by each desk in turn, applied on the Senate minute as a new version with the original kept; refused by a desk, withdrawn only by its raiser. An offer neither accepted nor paid by its deadline is lapsed and then not taken up; each freed place is filled from the waiting list by the office's choice, in the order freed, never beyond the places freed ──
DO $$
DECLARE sh uuid; s1 uuid; q uuid := gen_random_uuid(); amd uuid; amd2 uuid; stg text; msg text; lect uuid := gen_random_uuid();
        r_same text; r_split text; r_desk text; r_twice text; r_minute text; r_withdraw text; v_link boolean; v_total int; v_version int; v_was int; n_told int;
        v_refused text;
        v_pol uuid := gen_random_uuid(); v_batch uuid := gen_random_uuid(); prog text; pname text; r record; apps uuid[] := ARRAY[]::uuid[];
        n_past int; n_lapsed int; v_cand text; r_under text; r_fee text; n_vac int; n_wait int; r_many text; n_prom int; v_for uuid; v_basis text;
        n_vac2 int; r_notwait text; r_days text; v_first uuid;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', lect::text, true);
        PERFORM set_config('moaum.actor_office', 'lecturer', true);
        INSERT INTO iam.person (id, surname, given_names, email) VALUES (lect, 'CHECKAMEND', 'Lecturer', 'zz.check202@example.com');
        SELECT s.id INTO sh FROM assessment.score_sheet s JOIN catalogue.offering o ON o.id = s.offering_id WHERE o.course_code = 'ZZC 101' AND s.stage = 'PUBLISHED';
        SELECT id INTO s1 FROM people.student WHERE admission_no = 'MOAUM/ADM/99/000001';
        INSERT INTO people.student_contact (student_id, email, phone) VALUES (s1, 'zz.check202s@example.com', '08012340202')
        ON CONFLICT (student_id) DO UPDATE SET email = EXCLUDED.email, phone = EXCLUDED.phone;
        SELECT version INTO v_was FROM assessment.latest_scores(sh) x WHERE x.student_id = s1;
        INSERT INTO assessment.result_query (id, ref, student_id, sheet_id, part, said, routed_dept, state, answer, answered_at, answered_by)
        VALUES (q, 'QRY-9999-00202', s1, sh, 'CA', 'My CA was left out', 'MTC', 'CORRECTED', 'The CA script was found', now(), lect);
        -- the same mark, a mark over the split, another desk: refused
        BEGIN PERFORM assessment.raise_amendment(sh, s1, 30, 45, 'GRADED', 'nothing at all to change here', NULL);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_same := split_part(msg, ':', 1); END;
        BEGIN PERFORM assessment.raise_amendment(sh, s1, 99, 1, 'GRADED', 'a CA beyond the course split', NULL);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_split := split_part(msg, ':', 1); END;
        PERFORM set_config('moaum.actor_office', 'hod', true);
        BEGIN PERFORM assessment.raise_amendment(sh, s1, 32, 45, 'GRADED', 'the CA script was found after the query', NULL);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_desk := split_part(msg, ':', 1); END;
        PERFORM set_config('moaum.actor_office', 'lecturer', true);
        amd := assessment.raise_amendment(sh, s1, 32, 45, 'GRADED', 'the CA script was found after the query', NULL);
        v_link := (SELECT query_id = q FROM assessment.amendment WHERE id = amd);
        BEGIN PERFORM assessment.raise_amendment(sh, s1, 33, 45, 'GRADED', 'a second one while the first is open', NULL);
        EXCEPTION WHEN unique_violation THEN r_twice := 'refused'; END;
        -- each desk in turn; Senate without its minute refused, then applied on it
        LOOP
            stg := (SELECT stage FROM assessment.amendment WHERE id = amd);
            EXIT WHEN stg = 'APPLIED';
            PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
            PERFORM set_config('moaum.actor_office', (assessment.stage_offices(stg))[1], true);
            IF stg = 'SENATE' THEN
                BEGIN PERFORM assessment.advance_amendment(amd, NULL, NULL);
                EXCEPTION WHEN check_violation THEN r_minute := 'refused'; END;
                PERFORM assessment.advance_amendment(amd, NULL, 'SEN/9999/202');
            ELSE
                PERFORM assessment.advance_amendment(amd, 'seen', NULL);
            END IF;
        END LOOP;
        SELECT total, version INTO v_total, v_version FROM assessment.latest_scores(sh) x WHERE x.student_id = s1;
        n_told := (SELECT count(*) FROM platform.notice WHERE about_kind = 'student' AND about_id = s1 AND subject IN ('Your result in ZZC 101 is amended', 'Result amended'));
        -- a second amendment refused at its desk; a third withdrawn only by its raiser
        PERFORM set_config('moaum.actor_id', lect::text, true);
        PERFORM set_config('moaum.actor_office', 'lecturer', true);
        amd2 := assessment.raise_amendment(sh, s1, 32, 40, 'GRADED', 'an examination mark re-added in error', NULL);
        PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
        PERFORM set_config('moaum.actor_office', 'exams', true);
        PERFORM assessment.refuse_amendment(amd2, 'the script shows the published mark is right');
        v_refused := (SELECT stage FROM assessment.amendment WHERE id = amd2);
        PERFORM set_config('moaum.actor_id', lect::text, true);
        PERFORM set_config('moaum.actor_office', 'lecturer', true);
        amd2 := assessment.raise_amendment(sh, s1, 31, 45, 'GRADED', 'one more correction to be withdrawn', NULL);
        PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
        BEGIN PERFORM assessment.withdraw_amendment(amd2, 'not mine to withdraw');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_withdraw := split_part(msg, ':', 1); END;
        PERFORM set_config('moaum.actor_id', lect::text, true);
        PERFORM assessment.withdraw_amendment(amd2, 'raised on the wrong student');

        -- offers: a session's policy, quota and pool of four
        PERFORM set_config('moaum.actor_office', 'academic', true);
        SELECT code, name INTO prog, pname FROM ref.programme WHERE NOT archived ORDER BY code LIMIT 1;
        INSERT INTO admissions.session_policy (id, session, nuc_quota, weight_utme, weight_putme, ratio_utme, ratio_de, instrument, in_force, state)
        VALUES (v_pol, '9993/9994', 4, 70, 30, 100, 0, 'CHECK CAC/9993/1', tstzrange(now(), NULL), 'IN_FORCE');
        INSERT INTO admissions.selection_criterion (policy_id, criterion, percent) VALUES (v_pol, 'NATIONAL_MERIT', 50), (v_pol, 'STATE_MERIT', 30), (v_pol, 'ELG', 10), (v_pol, 'LOCALITY', 10);
        INSERT INTO admissions.programme_rule (policy_id, programme_code, quota, olevel_text, utme_text, de_text) VALUES (v_pol, prog, 2, 'check', 'check', 'check');
        INSERT INTO admissions.programme_olevel_allowance (policy_id, programme_code, subject) VALUES (v_pol, prog, 'English Language'), (v_pol, prog, 'Mathematics');
        INSERT INTO admissions.caps_batch (id, session, source, list_kind, file_sha256, rows_read, downloaded_on, uploaded_by, uploaded_office)
        VALUES (v_batch, '9993/9994', 'CAPS_DOWNLOAD', 'UTME', '\xB2'::bytea, 4, current_date, gen_random_uuid(), 'academic');
        FOR r IN SELECT * FROM (VALUES ('W1', '20939990001', 'Kano', 'Nassarawa', 300, '000001'), ('W2', '20939990002', 'Benue', 'Makurdi', 290, '000002'),
                                       ('W3', '20939990003', 'Benue', 'Gboko', 280, '000003'), ('W4', '20939990004', 'Benue', 'Vandeikya', 270, '000004')) AS t(tag, jamb, state, lga, utme, seq) LOOP
            DECLARE cr uuid := gen_random_uuid(); cand uuid := gen_random_uuid(); acct uuid := gen_random_uuid(); ap uuid := gen_random_uuid();
            BEGIN
                INSERT INTO admissions.caps_row (id, batch_id, session, jamb_reg_no, raw, surname, other_names, jamb_code, aggregate, entry_mode, sex, state_of_origin, lga)
                VALUES (cr, v_batch, '9993/9994', r.jamb, '{}'::jsonb, 'CHECKWAIT', r.tag, prog, r.utme, 'UTME', 'M', r.state, r.lga);
                INSERT INTO admissions.candidate (id, session, jamb_reg_no, surname, other_names, programme, entry_mode, entry_level, offer_state, admitted_from)
                VALUES (cand, '9993/9994', r.jamb, 'CHECKWAIT', r.tag, pname, 'UTME', 100, 'PROPOSED', cr);
                INSERT INTO admissions.applicant_account (id, session, candidate_id, jamb_key, email, phone, password_hash)
                VALUES (acct, '9993/9994', cand, r.jamb, lower(r.jamb) || '@example.com', '08030000002', crypt('x', gen_salt('bf', 12)));
                INSERT INTO admissions.application (id, account_id, candidate_id, session, application_no, fee_confirmed_at, submitted_at, screening_score, score_entered_at, score_released_at)
                VALUES (ap, acct, cand, '9993/9994', 'APP/93/' || r.seq, now(), now(), 50, now(), now());
                apps := apps || ap;
            END;
        END LOOP;
        -- W1 and W2 offered and released twenty days ago (W2 then declined ten days ago); W3 and W4 on the waiting list
        UPDATE admissions.application SET decision = 'OFFERED', decision_basis = 'NM', decided_at = now() - interval '20 days', decision_released_at = now() - interval '20 days' WHERE id = apps[1];
        UPDATE admissions.application SET decision = 'OFFERED', decision_basis = 'SM', decided_at = now() - interval '20 days', decision_released_at = now() - interval '20 days',
               declined_at = now() - interval '10 days' WHERE id = apps[2];
        UPDATE admissions.application SET decision = 'WAITING', decided_at = now() - interval '20 days', decision_released_at = now() - interval '20 days' WHERE id IN (apps[3], apps[4]);
        UPDATE admissions.candidate SET offer_state = 'ADMITTED' WHERE id = (SELECT candidate_id FROM admissions.application WHERE id = apps[1]);
        -- no deadline set: nothing lapses; fourteen days after release: W1 is past it
        n_past := (SELECT count(*) FROM admissions.offers_past_deadline('9993/9994'));
        INSERT INTO admissions.offer_deadline (session, days_after_release, set_by) VALUES ('9993/9994', 14, lect);
        n_past := n_past * 10 + (SELECT count(*) FROM admissions.offers_past_deadline('9993/9994'));
        n_lapsed := admissions.lapse_offers('9993/9994', NULL);
        v_cand := (SELECT c.offer_state FROM admissions.candidate c JOIN admissions.application a ON a.candidate_id = c.id WHERE a.id = apps[1]);
        BEGIN UPDATE admissions.application SET undertaking_at = now() WHERE id = apps[1];
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_under := split_part(msg, ':', 1); END;
        BEGIN INSERT INTO admissions.fee_reference (application_id, kind, reference, amount) VALUES (apps[1], 'ACCEPTANCE', 'CHK-358-ACC', 1000);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_fee := split_part(msg, ':', 1); END;
        -- two places freed (W2's declined first, then W1's lapsed); two waiting
        n_vac := (SELECT count(*) FROM admissions.vacancies('9993/9994') WHERE programme = prog);
        n_wait := (SELECT count(*) FROM admissions.waiting_list('9993/9994', prog));
        v_first := (SELECT app_id FROM admissions.waiting_list('9993/9994', prog) ORDER BY rank LIMIT 1);
        BEGIN PERFORM admissions.promote_waiting('9993/9994', prog, ARRAY[apps[3], apps[4], apps[1]], lect);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_many := split_part(msg, ':', 1); END;
        BEGIN PERFORM admissions.promote_waiting('9993/9994', prog, ARRAY[apps[1]], lect);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_notwait := split_part(msg, ':', 1); END;
        n_prom := admissions.promote_waiting('9993/9994', prog, ARRAY[apps[3]], lect);
        SELECT promoted_for, decision_basis INTO v_for, v_basis FROM admissions.application WHERE id = apps[3];
        n_vac2 := (SELECT count(*) FROM admissions.vacancies('9993/9994') WHERE programme = prog);
        -- the session's date passed with no days allowed: no promotion until the days are set
        UPDATE admissions.offer_deadline SET accept_by = current_date - 1, days_after_release = NULL WHERE session = '9993/9994';
        BEGIN PERFORM admissions.promote_waiting('9993/9994', prog, ARRAY[apps[4]], lect);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_days := split_part(msg, ':', 1); END;
        RAISE EXCEPTION 'the V358 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V358: a published mark amended only through the chain — the same mark, a mark over the split and another desk refused, one open at a time, the query linked, each desk in turn, applied on the Senate minute as a new version with the student told; refused by a desk; withdrawn only by its raiser. Offers lapse only past a deadline set, unpaid; a lapsed offer is not taken up; places freed are filled from the waiting list by choice, in the order freed, never beyond them, and not after the date without days allowed',
        r_same = 'RES_AMEND_SAME' AND r_split = 'RES_AMEND_SPLIT' AND r_desk = 'RES_NOT_YOUR_STAGE' AND v_link AND r_twice = 'refused' AND r_minute = 'refused'
        AND v_total = 77 AND v_version = v_was + 1 AND n_told = 2 AND v_refused = 'REFUSED' AND r_withdraw = 'RES_AMEND_NOT_YOURS'
        AND n_past = 1 AND n_lapsed = 1 AND v_cand = 'LAPSED' AND r_under = 'ADMISSION_OFFER_LAPSED' AND r_fee = 'ADMISSION_OFFER_LAPSED'
        AND n_vac = 2 AND n_wait = 2 AND v_first = apps[3] AND r_many = 'ADMISSION_NO_VACANCY' AND r_notwait = 'ADMISSION_NOT_WAITING'
        AND n_prom = 1 AND v_for = apps[2] AND v_basis = 'SM' AND n_vac2 = 1 AND r_days = 'ADMISSION_DEADLINE_DAYS',
        format('same=%s split=%s desk=%s link=%s twice=%s minute=%s total=%s version=%s/%s told=%s refused=%s withdraw=%s past=%s lapsed=%s cand=%s under=%s fee=%s vac=%s wait=%s first=%s many=%s notwait=%s prom=%s for=%s basis=%s vac2=%s days=%s',
               r_same, r_split, r_desk, v_link, r_twice, r_minute, v_total, v_version, v_was, n_told, v_refused, r_withdraw, n_past, n_lapsed, v_cand, r_under, r_fee,
               n_vac, n_wait, v_first = apps[3], r_many, r_notwait, n_prom, v_for = apps[2], v_basis, n_vac2, r_days));
END $$;

-- ── 203. V359: a score sheet at entry is chased for real — reminded to its lecturer by text or email to what they have on record, escalated once late to the Head of Department of its department in the first five days and to the Dean of its faculty after (the lecturer told), each kind at most once a day; not by a lecturer, not past entry, not before the due date, not to an office no one holds; every reminder kept. A hostel allocation carries a random check code of its own ──
DO $$
DECLARE sh uuid; o2 uuid := gen_random_uuid(); sh2 uuid := gen_random_uuid(); lect uuid := gen_random_uuid(); hod uuid := gen_random_uuid(); dean uuid := gen_random_uuid();
        officer uuid := gen_random_uuid(); grant_dean uuid := gen_random_uuid(); msg text; j jsonb;
        r_lect text; r_entry text; r_notlate text; r_soon text; r_nobody text;
        v_rem_told int; n_sms int; n_mail int; v_hod_to text; v_hod_told int; n_hod_mail int; n_lect_esc int; v_dean_to text; v_dean_told int;
        m_office text; n_kept int; v_reminders int; v_escalations int; v_last_to text; v_code boolean; v_default boolean;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', officer::text, true);
        PERFORM set_config('moaum.actor_office', 'exams', true);
        -- a lecturer with a phone only, a Head of Department of MTC with an email, a Dean of SC with a phone
        INSERT INTO iam.person (id, surname, given_names, staff_number, phone) VALUES (lect, 'CHECKCHASE', 'Lecturer', 'P-V359-L', '08030359001');
        INSERT INTO iam.person (id, surname, given_names, staff_number, email) VALUES (hod, 'CHECKCHASE', 'Head', 'P-V359-H', 'zz.check203.hod@example.com');
        INSERT INTO iam.person (id, surname, given_names, staff_number, phone) VALUES (dean, 'CHECKCHASE', 'Dean', 'P-V359-D', '08030359003'),
                                                                                     (officer, 'CHECKCHASE', 'Officer', 'P-V359-E', NULL);
        INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from)
        VALUES (gen_random_uuid(), hod, 'hod', 'department', 'MTC', 'CHECK V359', officer, current_date - 10),
               (grant_dean, dean, 'dean', 'faculty', 'SC', 'CHECK V359', officer, current_date - 10);
        -- a second sitting of the course with its lecturer, a sheet at entry due in two days
        INSERT INTO catalogue.offering (id, course_code, session, semester, lecturer_id) VALUES (o2, 'ZZC 101', '9999/0000', 2, lect);
        INSERT INTO assessment.score_sheet (id, offering_id, due_on) VALUES (sh2, o2, current_date + 2);
        -- a lecturer does not chase; a published sheet is past entry; a sheet not yet due is not escalated
        PERFORM set_config('moaum.actor_office', 'lecturer', true);
        BEGIN PERFORM assessment.chase_sheet(sh2, 'REMIND', NULL);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_lect := split_part(msg, ':', 1); END;
        PERFORM set_config('moaum.actor_office', 'exams', true);
        SELECT s.id INTO sh FROM assessment.score_sheet s JOIN catalogue.offering o ON o.id = s.offering_id WHERE o.course_code = 'ZZC 101' AND s.stage = 'PUBLISHED';
        BEGIN PERFORM assessment.chase_sheet(sh, 'REMIND', NULL);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_entry := split_part(msg, ':', 1); END;
        BEGIN PERFORM assessment.chase_sheet(sh2, 'ESCALATE', NULL);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_notlate := split_part(msg, ':', 1); END;
        -- reminded: one text to the lecturer's phone, no email (none on record); a second the same day refused
        j := assessment.chase_sheet(sh2, 'REMIND', 'The Board sits on Friday');
        v_rem_told := (j->>'told')::int;
        n_sms := (SELECT count(*) FROM platform.notice WHERE about_kind = 'score_sheet' AND about_id = sh2 AND channel = 'SMS' AND recipient = '08030359001' AND subject = 'Score sheet reminder');
        n_mail := (SELECT count(*) FROM platform.notice WHERE about_kind = 'score_sheet' AND about_id = sh2 AND channel = 'EMAIL');
        BEGIN PERFORM assessment.chase_sheet(sh2, 'REMIND', NULL);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_soon := split_part(msg, ':', 1); END;
        -- three days late: escalated to the Head of Department of MTC (email), the lecturer told by text
        UPDATE assessment.score_sheet SET due_on = current_date - 3 WHERE id = sh2;
        j := assessment.chase_sheet(sh2, 'ESCALATE', NULL);
        v_hod_to := j->>'toOffice'; v_hod_told := (j->>'told')::int;
        n_hod_mail := (SELECT count(*) FROM platform.notice WHERE about_id = sh2 AND channel = 'EMAIL' AND recipient = 'zz.check203.hod@example.com');
        n_lect_esc := (SELECT count(*) FROM platform.notice WHERE about_id = sh2 AND channel = 'SMS' AND recipient = '08030359001' AND subject = 'Score sheet escalated');
        -- eight days late, the last escalation a day ago: the Dean of SC
        UPDATE assessment.sheet_chase SET sent_at = sent_at - interval '25 hours' WHERE sheet_id = sh2;
        UPDATE assessment.score_sheet SET due_on = current_date - 8 WHERE id = sh2;
        j := assessment.chase_sheet(sh2, 'ESCALATE', NULL);
        v_dean_to := j->>'toOffice'; v_dean_told := (j->>'told')::int;
        -- the Dean's post ended: no one to escalate to, refused
        UPDATE assessment.sheet_chase SET sent_at = sent_at - interval '25 hours' WHERE sheet_id = sh2;
        UPDATE iam.office_assignment SET valid_to = current_date - 1 WHERE id = grant_dean;
        BEGIN PERFORM assessment.chase_sheet(sh2, 'ESCALATE', NULL);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_nobody := split_part(msg, ':', 1); END;
        -- the rule the monitor shows, and what the lists read
        m_office := concat_ws('/', assessment.chase_office(NULL, NULL), assessment.chase_office(1, NULL), assessment.chase_office(5, NULL),
                              assessment.chase_office(6, NULL), assessment.chase_office(3, 'GST'));
        n_kept := (SELECT count(*) FROM assessment.sheet_chase WHERE sheet_id = sh2);
        SELECT reminders, escalations, escalated_to INTO v_reminders, v_escalations, v_last_to FROM assessment.chase_summary(ARRAY[sh2]);
        -- a hostel allocation's check code: random, eighteen hex digits, never assumed
        v_default := (SELECT pg_get_expr(d.adbin, d.adrelid) LIKE '%gen_random_bytes%' FROM pg_attrdef d JOIN pg_attribute a ON a.attrelid = d.adrelid AND a.attnum = d.adnum
                       WHERE d.adrelid = 'hostel.allocation'::regclass AND a.attname = 'verify_code');
        v_code := (SELECT bool_and(verify_code ~ '^[0-9a-f]{18}$') IS NOT FALSE AND count(*) = count(DISTINCT verify_code) FROM hostel.allocation);
        RAISE EXCEPTION 'the V359 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V359: a sheet at entry chased for real — not by a lecturer, not past entry, not escalated before it is due; reminded by text to the lecturer''s phone (no email on record), once a day; escalated to the Head of Department three days late (the lecturer told), to the Dean eight days late, refused with no one posted; the monitor''s rule; every reminder kept and summed for the lists. A hostel allocation carries a random check code of its own',
        r_lect = 'RESULT_CHASE_DESK' AND r_entry = 'RESULT_CHASE_NOT_AT_ENTRY' AND r_notlate = 'RESULT_CHASE_NOT_LATE'
        AND v_rem_told = 1 AND n_sms = 1 AND n_mail = 0 AND r_soon = 'RESULT_CHASE_TOO_SOON'
        AND v_hod_to = 'hod' AND v_hod_told = 1 AND n_hod_mail = 1 AND n_lect_esc = 1 AND v_dean_to = 'dean' AND v_dean_told = 1
        AND r_nobody = 'RESULT_CHASE_NO_HOLDER' AND m_office = 'hod/hod/dean/gst'
        AND n_kept = 3 AND v_reminders = 1 AND v_escalations = 2 AND v_last_to = 'Dean' AND v_default AND v_code,
        format('lect=%s entry=%s notlate=%s told=%s sms=%s mail=%s soon=%s hod=%s/%s/%s lectesc=%s dean=%s/%s nobody=%s rule=%s kept=%s summary=%s/%s/%s default=%s code=%s',
               r_lect, r_entry, r_notlate, v_rem_told, n_sms, n_mail, r_soon, v_hod_to, v_hod_told, n_hod_mail, n_lect_esc, v_dean_to, v_dean_told, r_nobody, m_office,
               n_kept, v_reminders, v_escalations, v_last_to, v_default, v_code));
END $$;

-- ── 204. V360: when the signed check codes began is kept, once. A student is told by email and by at most one text a day under the same heading; course material published, an assignment set and a submission marked tell the course's students — the mark is not in the message; a PG registration endorsed and a PG score recorded tell the student, the score once a day for the course and never in the message ──
DO $$
DECLARE o uuid; s1 uuid; lect uuid := gen_random_uuid(); mat uuid := gen_random_uuid(); asg uuid := gen_random_uuid(); sub uuid := gen_random_uuid();
        reg uuid := gen_random_uuid(); crs uuid := gen_random_uuid(); ent uuid := gen_random_uuid(); prog text;
        v_cut int; n_class int; n_mat int; n_asg int; v_marked boolean; n_mail int; n_sms int; v_mark_hidden boolean;
        v_end boolean; v_scored boolean; v_scored2 boolean; n_score_mail int; v_score_hidden boolean; v_twice boolean;
BEGIN
    v_cut := (SELECT count(*) FROM platform.check_code_cutover);
    BEGIN
        PERFORM set_config('moaum.actor_id', lect::text, true);
        PERFORM set_config('moaum.actor_office', 'lecturer', true);
        INSERT INTO iam.person (id, surname, given_names, staff_number) VALUES (lect, 'CHECKTELL', 'Lecturer', 'P-V360-L');
        SELECT x.id INTO o FROM catalogue.offering x WHERE x.course_code = 'ZZC 101' AND x.session = '9999/0000' AND x.semester = 1;
        SELECT id INTO s1 FROM people.student WHERE admission_no = 'MOAUM/ADM/99/000001';
        INSERT INTO people.student_contact (student_id, email, phone) VALUES (s1, 'zz.check204@example.com', '08012340204')
        ON CONFLICT (student_id) DO UPDATE SET email = EXCLUDED.email, phone = EXCLUDED.phone;
        n_class := (SELECT count(DISTINCT g.student_id) FROM lms.gradebook(o) g);
        -- material published, an assignment set: two emails to s1, one text (the second the same day is held)
        INSERT INTO lms.material (id, offering_id, week, title, kind, link, published_at, published_by) VALUES (mat, o, 3, 'Week three notes', 'NOTES', 'https://example.com/n', now(), lect);
        n_mat := lms.tell_material(mat);
        INSERT INTO lms.assignment (id, offering_id, title, kind, opens_at, closes_at, weight, out_of, created_by)
        VALUES (asg, o, 'Problem set one', 'INDIVIDUAL', now(), now() + interval '7 days', 10, 20, lect);
        n_asg := lms.tell_assignment(asg);
        n_mail := (SELECT count(*) FROM platform.notice WHERE about_kind = 'student' AND about_id = s1 AND channel = 'EMAIL'
                    AND subject IN ('New material in ZZC 101: Week three notes', 'New assignment in ZZC 101: Problem set one'));
        n_sms := (SELECT count(*) FROM platform.notice WHERE about_kind = 'student' AND about_id = s1 AND channel = 'SMS' AND subject = 'Course update');
        -- a submission marked 17.25: the student told, the mark not in the message
        INSERT INTO lms.submission (id, assignment_id, student_id, text, mark, marked_at, marked_by) VALUES (sub, asg, s1, 'my answers', 17.25, now(), lect);
        v_marked := lms.tell_marked(sub);
        v_mark_hidden := NOT EXISTS (SELECT 1 FROM platform.notice WHERE about_id = s1 AND subject = 'Your ZZC 101 submission is marked' AND body LIKE '%17.25%')
                         AND EXISTS (SELECT 1 FROM platform.notice WHERE about_id = s1 AND subject = 'Your ZZC 101 submission is marked');
        -- a PG registration endorsed and a score recorded twice the same day: told once, the score not in the message
        SELECT code INTO prog FROM ref.programme WHERE NOT archived ORDER BY code LIMIT 1;
        INSERT INTO admissions.pg_registration (id, student_id, session, semester, mode, state, endorsed_by, endorsed_at)
        VALUES (reg, s1, '9999/0000', 1, 'FULL_TIME', 'ENDORSED', lect, now());
        v_end := admissions.tell_pg_endorsed(reg);
        INSERT INTO admissions.pg_course (id, programme_code, code, title, units, kind, semester) VALUES (crs, prog, 'ZZP 801', 'A course for the check', 3, 'CORE', 1);
        INSERT INTO admissions.pg_registration_entry (id, registration_id, course_id) VALUES (ent, reg, crs);
        PERFORM admissions.pg_record_score(ent, 31, 42, lect);
        v_scored := admissions.tell_pg_scored(ent);
        PERFORM admissions.pg_record_score(ent, 32, 42, lect);
        v_scored2 := admissions.tell_pg_scored(ent);
        n_score_mail := (SELECT count(*) FROM platform.notice WHERE about_id = s1 AND channel = 'EMAIL' AND subject = 'A score is recorded in ZZP 801');
        v_score_hidden := NOT EXISTS (SELECT 1 FROM platform.notice WHERE about_id = s1 AND subject IN ('A score is recorded in ZZP 801', 'Coursework score')
                                        AND (body LIKE '%73%' OR body LIKE '%74%'));
        v_twice := (SELECT count(*) FROM platform.notice WHERE about_id = s1 AND channel = 'SMS' AND subject = 'Registration endorsed') = 1;
        RAISE EXCEPTION 'the V360 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V360: the cutover kept once; a student told by email and at most one text a day under a heading — course material and an assignment tell the course''s students, a marked submission its student without the mark; a PG endorsement and a PG score tell the student, the score once a day and never in the message',
        v_cut = 1 AND n_class >= 1 AND n_mat >= 1 AND n_asg = n_mat AND n_mail = 2 AND n_sms = 1 AND v_marked AND v_mark_hidden
        AND v_end AND v_twice AND v_scored AND NOT v_scored2 AND n_score_mail = 1 AND v_score_hidden,
        format('cut=%s class=%s mat=%s asg=%s mail=%s sms=%s marked=%s hidden=%s endorsed=%s/%s scored=%s/%s scoremail=%s scorehidden=%s',
               v_cut, n_class, n_mat, n_asg, n_mail, n_sms, v_marked, v_mark_hidden, v_end, v_twice, v_scored, v_scored2, n_score_mail, v_score_hidden));
END $$;

-- ── 205. V361: a session's school fees must be stated for the student before they are cleared — with no fee line that applies to them, course registration is refused with the reason (not "not fully paid") and no semester is cleared; a ₦0 line stated on purpose clears without a payment; a fee stated is cleared only when paid ──
DO $$
DECLARE s1 uuid; reg uuid := gen_random_uuid(); officer uuid := gen_random_uuid(); msg text; r_submit text;
        v_stated0 boolean; v_cleared0 boolean; v_stated_free boolean; v_cleared_free boolean; v_cleared_owed boolean; v_cleared_paid boolean;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', officer::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        SELECT id INTO s1 FROM people.student WHERE admission_no = 'MOAUM/ADM/99/000001';
        -- 9997/9998: nothing stated for the student
        v_stated0 := finance.fee_stated(s1, '9997/9998');
        v_cleared0 := finance.semester_cleared(s1, '9997/9998', 1);
        INSERT INTO registration.course_registration (id, student_id, session, semester, level, status) VALUES (reg, s1, '9997/9998', 1, 100, 'DRAFT');
        BEGIN PERFORM registration.student_submit(reg);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_submit := split_part(msg, ':', 1); END;
        -- the Bursary states ₦0 on purpose for the programme: stated, and cleared with nothing paid
        INSERT INTO finance.fee_schedule (id, session, item, amount, programme_code, kind, ord) VALUES (gen_random_uuid(), '9997/9998', 'School Fees', 0, 'C00023', 'FEE', 1);
        v_stated_free := finance.fee_stated(s1, '9997/9998');
        v_cleared_free := finance.semester_cleared(s1, '9997/9998', 1);
        -- a fee stated is cleared only when paid
        UPDATE finance.fee_schedule SET amount = 50000 WHERE session = '9997/9998' AND programme_code = 'C00023' AND item = 'School Fees';
        v_cleared_owed := finance.semester_cleared(s1, '9997/9998', 1);
        INSERT INTO finance.payment_reference (id, student_id, session, reference, purpose, amount, expires_at, confirmed_at, confirmed_by, channel, receipt_no)
        VALUES (gen_random_uuid(), s1, '9997/9998', 'CHK-361-PAID', 'School fees (full session)', 50000, now() + interval '1 day', now(), officer, 'BANK', 'RCT-CHK-361');
        v_cleared_paid := finance.semester_cleared(s1, '9997/9998', 1);
        RAISE EXCEPTION 'the V361 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V361: nothing stated, nothing cleared and registration refused with the reason; ₦0 stated on purpose clears without payment; a fee stated clears only when paid',
        NOT v_stated0 AND NOT v_cleared0 AND r_submit = 'REG_FEES_NOT_STATED' AND v_stated_free AND v_cleared_free AND NOT v_cleared_owed AND v_cleared_paid,
        format('stated0=%s cleared0=%s submit=%s free=%s/%s owed=%s paid=%s', v_stated0, v_cleared0, r_submit, v_stated_free, v_cleared_free, v_cleared_owed, v_cleared_paid));
END $$;

-- ── 206. V362: from the first session of the portal's fee schedule, nothing is cleared for a student whose fees for the session are not stated — the examination, the results, the identity card — though their position reads "paid in full" on ₦0; a session before the schedule began is taken as stated (its fees were the old portal's); the registrations made without the semester's fees cleared are listed, read only ──
DO $$
DECLARE s1 uuid; reg uuid := gen_random_uuid(); officer uuid := gen_random_uuid(); v_from text; v_before boolean; v_after boolean;
        v_full boolean; v_exam boolean; v_results boolean; v_listed text; v_count int;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', officer::text, true);
        PERFORM set_config('moaum.actor_office', 'registrar', true);
        SELECT id INTO s1 FROM people.student WHERE admission_no = 'MOAUM/ADM/99/000001';
        v_from := finance.schedule_from();
        v_before := finance.fee_stated(s1, '9990/9991');        -- before the schedule began
        v_after := finance.fee_stated(s1, '9997/9998');         -- after it, with no line for the student
        v_full := (SELECT paid_in_full FROM finance.position(s1, '9997/9998'));
        v_exam := finance.clears(s1, '9997/9998', 'EXAMINATION');
        v_results := finance.clears(s1, '9997/9998', 'RESULTS');
        INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, submitted_at) VALUES (reg, s1, '9997/9998', 1, 100, 'SUBMITTED', now());
        SELECT count(*), max(CASE WHEN registration_id = reg THEN (CASE WHEN stated THEN 'STATED' ELSE 'NOT_STATED' END) END)
          INTO v_count, v_listed FROM finance.registrations_without_fees('9997/9998');
        RAISE EXCEPTION 'the V362 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V362: unstated fees clear nothing from the schedule''s first session (the examination, the results), though the position reads paid in full on nothing; a session before the schedule is taken as stated; the unpaid registrations are listed',
        v_from IS NOT NULL AND v_before AND NOT v_after AND v_full AND NOT v_exam AND NOT v_results AND v_count >= 1 AND v_listed = 'NOT_STATED',
        format('from=%s before=%s after=%s full=%s exam=%s results=%s listed=%s/%s', v_from, v_before, v_after, v_full, v_exam, v_results, v_count, v_listed));
END $$;

-- ── 207. V363: a person who cannot sign in asks the desk from the sign-in page — a Login Issues ticket that names no account (its requester is itself, no department or faculty), routed as any other; a name is letters, an option one of those offered, and an email keeps at most three such requests open ──
DO $$
DECLARE t1 uuid; v_kind text; v_self boolean; v_dept text; v_cat text; v_number text; v_routed boolean;
        bad_name boolean := false; bad_option boolean := false; fourth boolean := false; v_open int;
        d jsonb := '{"account_type": "Student portal", "username": "MOAUM/ZZ/99/0001", "error": "Invalid password"}';
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', '00000000-0000-0000-0000-000000000000', true);
        PERFORM set_config('moaum.actor_office', 'ict', true);
        t1 := helpdesk.submit_public('Ada Okafor', 'zz-v363@example.com', '08030000000', d, 'The reset link never arrives.');
        PERFORM helpdesk.route(t1);
        SELECT t.requester_kind, t.requester_id = t.id, t.department_code, c.code, t.requester_number, t.queue_code IS NOT NULL OR t.assigned_to IS NOT NULL
          INTO v_kind, v_self, v_dept, v_cat, v_number, v_routed
          FROM helpdesk.ticket t JOIN helpdesk.category c ON c.id = t.category_id WHERE t.id = t1;
        BEGIN
            PERFORM helpdesk.submit_public('Visit www.example.com', 'zz-v363@example.com', NULL, d, 'x');
        EXCEPTION WHEN check_violation THEN bad_name := true;
        END;
        BEGIN
            PERFORM helpdesk.submit_public('Ada Okafor', 'zz-v363@example.com', NULL, d || '{"account_type": "Bank account"}', 'x');
        EXCEPTION WHEN check_violation THEN bad_option := true;
        END;
        PERFORM helpdesk.submit_public('Ada Okafor', 'zz-v363@example.com', NULL, d, 'second');
        PERFORM helpdesk.submit_public('Ada Okafor', 'ZZ-V363@example.com', NULL, d, 'third');
        BEGIN
            PERFORM helpdesk.submit_public('Ada Okafor', 'zz-v363@example.com', NULL, d, 'fourth');
        EXCEPTION WHEN check_violation THEN fourth := true;
        END;
        SELECT count(*) INTO v_open FROM helpdesk.ticket WHERE requester_kind = 'PUBLIC' AND requester_email = 'zz-v363@example.com';
        RAISE EXCEPTION 'the V363 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V363: sign-in help from a person not signed in is a Login Issues ticket naming no account, routed; a name is letters, an option one offered; three open per email',
        v_kind = 'PUBLIC' AND v_self AND v_dept IS NULL AND v_cat = 'LOGIN' AND v_number = 'MOAUM/ZZ/99/0001' AND v_routed AND bad_name AND bad_option AND fourth AND v_open = 3,
        format('kind=%s self=%s dept=%s cat=%s number=%s routed=%s bad_name=%s bad_option=%s fourth=%s open=%s', v_kind, v_self, v_dept, v_cat, v_number, v_routed, bad_name, bad_option, fourth, v_open));
END $$;

-- ── 208. V364: the CBT engine for every CBT-enabled course — a course not allowed CBT is refused, a General Studies course starts allowed; a blueprint
--            the pool cannot satisfy is refused with what is short, and the draw follows it; a pool too small says so; the paper is frozen, so an edit of
--            the bank changes no attempt; a late save never overwrites a newer one; a cleared answer is kept; negative marking never below nought; the
--            warning waits for its threshold; an attempt out of contact past the limit is submitted with what was saved ──
DO $$
DECLARE who uuid := gen_random_uuid(); st uuid := gen_random_uuid(); off uuid := gen_random_uuid(); off2 uuid := gen_random_uuid();
        ex assessment.cbt_exam; ex2 assessment.cbt_exam; a assessment.cbt_attempt; reg uuid; qs uuid[] := ARRAY[]::uuid[]; i int;
        v_gst_default boolean; r_not_enabled text; r_short text; r_pool text; v_easy int; v_hard int; v_ver int; v_frozen int; v_kept int[];
        v_cleared int; ev jsonb; v_level text; v_status text; v_score numeric; v_max int; v_reason text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'gst', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), '9993/9994', date '9993-10-01', date '9994-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state)
        SELECT 'GST 993', 'Check General Studies V364', 2, 1, 100, p.dept_code, 'GST', 'LIVE' FROM ref.programme p WHERE p.code = 'C00023';
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state)
        SELECT 'ZZC 993', 'Check departmental course V364', 2, 1, 100, p.dept_code, 'Core', 'LIVE' FROM ref.programme p WHERE p.code = 'C00023';
        SELECT cbt_enabled INTO v_gst_default FROM catalogue.course WHERE code = 'GST 993';
        INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES ('GST 993', 'C00023', 100, 'GST');
        INSERT INTO catalogue.offering (id, course_code, session, semester) VALUES (off, 'GST 993', '9993/9994', 1), (off2, 'ZZC 993', '9993/9994', 1);
        BEGIN
            ex2 := assessment.cbt_new_exam('EXAMS', off2, 'Not a CBT course', NULL, 30, 0, 'FIXED', false, false, 50, 1, 'STANDARD', 'REMOTE', 1, 'WARN', 'CONTINUE', NULL, NULL);
        EXCEPTION WHEN check_violation THEN r_not_enabled := split_part(SQLERRM, ':', 1); END;
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (st, 'MOAUM/ADM/93/000993', 'MOAUM/CHK/93/993', 'ZZCHECKV364', 'Invented', 'C00023', 'UTME', '9993/9994', 100, 100, 'ACTIVE', now());
        FOR i IN 1..6 LOOP
            qs := qs || gen_random_uuid();
            INSERT INTO assessment.question (id, course_code, stem, options, answer, kind, marks, difficulty)
            VALUES (qs[i], 'GST 993', 'V364 question ' || i, '["a","b","c","d"]', 0, 'MCQ', 1, CASE WHEN i <= 3 THEN 'EASY' ELSE 'HARD' END);
        END LOOP;
        PERFORM pg_temp.moderated();
        ex := assessment.cbt_new_exam('GST', off, 'V364 check', NULL, 30, 4, 'RANDOM', true, true, 50, 1, 'STANDARD', 'REMOTE', 3, 'WARN', 'CONTINUE', now() - interval '1 minute', now() + interval '2 hours');
        BEGIN
            PERFORM assessment.cbt_set_blueprint(ex.id, 'DIFFICULTY', '[{"value": "HARD", "questions": 4}]');
        EXCEPTION WHEN check_violation THEN r_short := SQLERRM; END;
        PERFORM assessment.cbt_set_blueprint(ex.id, 'DIFFICULTY', '[{"value": "EASY", "questions": 1}, {"value": "HARD", "questions": 3}]');
        PERFORM assessment.cbt_configure(ex.id, '{"negativeMarks": 0.5, "warnAt": 2, "finalWarnAt": 3, "disconnectMinutes": 2}');
        ex2 := assessment.cbt_new_exam('GST', off, 'V364 pool', NULL, 30, 10, 'RANDOM', true, false, 50, 1, 'STANDARD', 'REMOTE', 1, 'WARN', 'CONTINUE', NULL, NULL);
        r_pool := assessment.cbt_paper_ready(ex2.id);
        PERFORM assessment.cbt_exam_action(ex.id, 'publish', NULL);
        reg := registration.student_draft(st, '9993/9994', 1);
        PERFORM registration.student_choose(reg, ARRAY[off]);
        UPDATE registration.course_registration SET status = 'SUBMITTED', submitted_at = now() WHERE id = reg;
        PERFORM set_config('moaum.actor_id', st::text, true);
        PERFORM set_config('moaum.actor_office', 'student', true);
        a := assessment.cbt_start(ex.id, st, '10.0.0.9', 'check');
        SELECT count(*) FILTER (WHERE q.difficulty = 'EASY'), count(*) FILTER (WHERE q.difficulty = 'HARD') INTO v_easy, v_hard
          FROM unnest(a.question_ids) u(id) JOIN assessment.question q ON q.id = u.id;
        -- the bank changes under the attempt: the first question's key is changed (a new version); the attempt keeps the version it drew
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'gst', true);
        UPDATE assessment.question SET answer = 1, answers = ARRAY[1] WHERE id = a.question_ids[1];
        SELECT version INTO v_ver FROM assessment.question WHERE id = a.question_ids[1];
        SELECT a2.question_versions[1] INTO v_frozen FROM assessment.cbt_attempt a2 WHERE a2.id = a.id;
        PERFORM set_config('moaum.actor_id', st::text, true);
        PERFORM set_config('moaum.actor_office', 'student', true);
        -- answers: the first right on the version drawn, the second wrong; a late save of the first (a lower sequence) changes nothing; the third chosen then cleared
        PERFORM assessment.cbt_save_answers(a.id, a.token, jsonb_build_array(jsonb_build_object('q', a.question_ids[1], 'a', jsonb_build_array(0), 'seq', 5),
                                                                             jsonb_build_object('q', a.question_ids[2], 'a', jsonb_build_array(1), 'seq', 1),
                                                                             jsonb_build_object('q', a.question_ids[3], 'a', jsonb_build_array(2), 'seq', 1)));
        PERFORM assessment.cbt_save_answers(a.id, a.token, jsonb_build_array(jsonb_build_object('q', a.question_ids[1], 'a', jsonb_build_array(3), 'seq', 3),
                                                                             jsonb_build_object('q', a.question_ids[3], 'a', '[]'::jsonb, 'seq', 2)));
        SELECT chosen INTO v_kept FROM assessment.cbt_answer WHERE attempt_id = a.id AND question_id = a.question_ids[1];
        SELECT count(*) INTO v_cleared FROM assessment.cbt_answer WHERE attempt_id = a.id AND question_id = a.question_ids[3] AND cardinality(chosen) = 0;
        -- one counted violation: recorded, below the warning threshold of two
        ev := assessment.cbt_record_events(a.id, a.token, '[{"kind": "TAB_SWITCH", "n": 2, "ms": 4000}]'::jsonb, '10.0.0.9');
        v_level := ev ->> 'level';
        -- three minutes out of contact, past the two allowed: the clock submits it with what was saved
        UPDATE assessment.cbt_attempt SET last_activity_at = now() - interval '3 minutes' WHERE id = a.id;
        PERFORM assessment.cbt_sweep();
        SELECT status, score, max_marks, finished_reason INTO v_status, v_score, v_max, v_reason FROM assessment.cbt_attempt WHERE id = a.id;
        RAISE EXCEPTION 'the V364 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V364: CBT only on a CBT-enabled course (GST starts allowed); a blueprint the pool cannot satisfy is refused and the draw follows it; the paper is frozen; a late save never wins; negative marking floored; thresholds; out of contact submitted',
        v_gst_default AND r_not_enabled = 'CBT_COURSE_NOT_ENABLED' AND r_short LIKE 'CBT_BLUEPRINT_SHORT: %Hard needs 4, the pool holds 3%'
        AND r_pool LIKE 'CBT_POOL_TOO_SMALL: Insufficient eligible questions. This examination requires 10 questions but only 6 valid questions are available.'
        AND v_easy = 1 AND v_hard = 3 AND v_ver = 2 AND v_frozen = 1 AND v_kept = ARRAY[0] AND v_cleared = 1 AND v_level IS NULL
        AND v_status = 'SUBMITTED' AND v_score = 0.5 AND v_max = 4 AND v_reason LIKE 'no contact for 2 minutes%',
        format('gst=%s enabled=%s short=%s pool=%s easy=%s hard=%s ver=%s frozen=%s kept=%s cleared=%s level=%s status=%s score=%s/%s reason=%s',
               v_gst_default, r_not_enabled, r_short, r_pool, v_easy, v_hard, v_ver, v_frozen, v_kept, v_cleared, v_level, v_status, v_score, v_max, v_reason));
END $$;

-- ── 209. V365: JUPEB on the one CBT engine — a subject not allowed CBT is refused; a JUPEB student sits only admitted, registered for the
--            subject and with the semester's share of the school fee paid; the attempt names the JUPEB candidate; the result goes into the
--            part of the JUPEB continuous assessment the office named, scaled to its maximum, through the JUPEB Office's own door ──
DO $$
DECLARE who uuid := gen_random_uuid(); ses text := '2092/2093'; prog text; sub uuid; s2 uuid; s3 uuid; comb uuid; acc uuid; acc2 uuid; app uuid; app2 uuid;
        ex assessment.cbt_exam; a assessment.cbt_attempt; q1 uuid := gen_random_uuid(); q2 uuid := gen_random_uuid(); comp uuid;
        r_not_enabled text; r_not_student text; r_not_reg text; r_fees text; r_paid text; v_kind text; v_cand int; v_written int; v_ca numeric; r_exam_sheet text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'jupeb', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), ses, date '2092-10-01', date '2093-08-31') ON CONFLICT (name) DO NOTHING;
        SELECT code INTO prog FROM ref.programme WHERE category = 'UNDER GRADUATE' AND NOT archived ORDER BY code LIMIT 1;
        INSERT INTO jupeb.subject (code, title) VALUES ('ZZV365A', 'V365 Check Subject') RETURNING id INTO sub;
        INSERT INTO jupeb.subject (code, title) VALUES ('ZZV365B', 'V365 Check Two') RETURNING id INTO s2;
        INSERT INTO jupeb.subject (code, title) VALUES ('ZZV365C', 'V365 Check Three') RETURNING id INTO s3;
        INSERT INTO jupeb.combination (code, name, subject1, subject2, subject3) VALUES ('ZZV365', 'V365 combination', sub, s2, s3) RETURNING id INTO comb;
        INSERT INTO jupeb.account (email, password_hash) VALUES ('zz.v365a@example.com', '$2a$12$abcdefghijklmnopqrstuuabcdefghijklmnopqrstuvwxyz12345') RETURNING id INTO acc;
        INSERT INTO jupeb.account (email, password_hash) VALUES ('zz.v365b@example.com', '$2a$12$abcdefghijklmnopqrstuuabcdefghijklmnopqrstuvwxyz12345') RETURNING id INTO acc2;
        INSERT INTO jupeb.application (account_id, session, application_no, surname, first_name, email, programme_code, combination_id, state_of_origin, state, subjects_registered_at, exam_no)
        VALUES (acc, ses, 'JUPEB/APP/2092/936501', 'ZZVTHREESIXFIVE', 'Candidate', 'zz.v365a@example.com', prog, comb, 'Benue', 'STUDENT', now(), 'ZZV365-0001') RETURNING id INTO app;
        INSERT INTO jupeb.application (account_id, session, application_no, surname, first_name, email, programme_code, combination_id, state_of_origin, state)
        VALUES (acc2, ses, 'JUPEB/APP/2092/936502', 'ZZVTHREESIXFIVE', 'Applicant', 'zz.v365b@example.com', prog, comb, 'Benue', 'ADMITTED') RETURNING id INTO app2;
        BEGIN
            ex := assessment.cbt_new_jupeb_exam(sub, ses, 1, 'V365 not yet a CBT subject', NULL, 30, 0, 'FIXED', false, false, 40, 1, 'STANDARD', 'REMOTE', 2, 'WARN', 'CONTINUE', NULL, NULL);
        EXCEPTION WHEN check_violation THEN r_not_enabled := split_part(SQLERRM, ':', 1); END;
        PERFORM jupeb.set_subject_cbt(sub, true);
        ex := assessment.cbt_new_jupeb_exam(sub, ses, 1, 'V365 JUPEB test', NULL, 30, 0, 'FIXED', false, false, 40, 1, 'STANDARD', 'REMOTE', 2, 'WARN', 'CONTINUE',
                                            now() - interval '1 minute', now() + interval '2 hours');
        INSERT INTO assessment.question (id, jupeb_subject_id, stem, options, answer, kind, marks) VALUES (q1, sub, 'V365 one', '["a","b"]', 0, 'MCQ', 1), (q2, sub, 'V365 two', '["a","b"]', 1, 'MCQ', 1);
        PERFORM pg_temp.moderated();
        INSERT INTO assessment.cbt_exam_question (exam_id, question_id, ordinal) VALUES (ex.id, q1, 1), (ex.id, q2, 2);
        INSERT INTO jupeb.ca_component (session, code, title, max_score) VALUES (ses, 'ZZV365', 'V365 CBT test', 20) RETURNING id INTO comp;
        BEGIN
            PERFORM assessment.cbt_configure(ex.id, '{"sheetComponent": "EXAM"}');
        EXCEPTION WHEN check_violation THEN r_exam_sheet := split_part(SQLERRM, ':', 1); END;
        PERFORM assessment.cbt_configure(ex.id, jsonb_build_object('sheetComponent', 'CA', 'jupebCaComponentId', comp));
        PERFORM assessment.cbt_exam_action(ex.id, 'publish', NULL);
        r_not_student := split_part(assessment.cbt_eligibility(ex.id, app2), ':', 1);
        r_not_reg := split_part(assessment.cbt_eligibility(ex.id, app), ':', 1);
        INSERT INTO jupeb.subject_registration (application_id, subject_id, session) VALUES (app, sub, ses);
        r_fees := split_part(assessment.cbt_eligibility(ex.id, app), ':', 1);
        INSERT INTO jupeb.fee_reference (application_id, kind, reference, amount, session, expires_at, confirmed_at)
        VALUES (app, 'SCHOOL_FIRST', 'ZZV365-SF1', 1000, ses, now() + interval '1 day', now());
        r_paid := coalesce(assessment.cbt_eligibility(ex.id, app), 'ELIGIBLE');
        PERFORM set_config('moaum.actor_id', app::text, true);
        PERFORM set_config('moaum.actor_office', 'applicant', true);
        a := assessment.cbt_start(ex.id, app, '10.0.0.5', 'check');
        v_kind := CASE WHEN a.jupeb_application_id = app AND a.student_id IS NULL AND a.candidate_id = app THEN 'JUPEB' END;
        PERFORM assessment.cbt_save_answers(a.id, a.token, jsonb_build_array(jsonb_build_object('q', q1, 'a', jsonb_build_array(0)), jsonb_build_object('q', q2, 'a', jsonb_build_array(1))));
        PERFORM assessment.cbt_submit(a.id, a.token);
        SELECT count(*) INTO v_cand FROM assessment.cbt_candidates(ex.id) c WHERE c.student_id = app AND c.attempt_status = 'SUBMITTED' AND c.eligible;
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'jupeb', true);
        PERFORM assessment.cbt_exam_action(ex.id, 'close', NULL);
        PERFORM assessment.cbt_exam_action(ex.id, 'complete', NULL);
        PERFORM assessment.cbt_results_action(ex.id, 'approve');
        v_written := assessment.cbt_to_sheet(ex.id);
        SELECT score INTO v_ca FROM jupeb.ca_score WHERE application_id = app AND subject_id = sub AND component_id = comp;
        RAISE EXCEPTION 'the V365 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V365: JUPEB on the one CBT engine — a subject not allowed is refused; admitted, registered and paid; the attempt names the JUPEB candidate; the result into the named part of the JUPEB CA',
        r_not_enabled = 'CBT_COURSE_NOT_ENABLED' AND r_exam_sheet = 'CBT_SETTING' AND r_not_student = 'CBT_JUPEB_NOT_STUDENT' AND r_not_reg = 'CBT_JUPEB_SUBJECT_NOT_REGISTERED'
        AND r_fees = 'CBT_JUPEB_FEES' AND r_paid = 'ELIGIBLE' AND v_kind = 'JUPEB' AND v_cand = 1 AND v_written = 1 AND v_ca = 20,
        format('enabled=%s sheet=%s student=%s reg=%s fees=%s paid=%s kind=%s cand=%s written=%s ca=%s', r_not_enabled, r_exam_sheet, r_not_student, r_not_reg, r_fees, r_paid, v_kind, v_cand, v_written, v_ca));
END $$;

-- ── V366: GST & EPS owed only for a course the student must take — the programme's offering at the level, a carryover, never level alone ──
DO $$
DECLARE who uuid := gen_random_uuid(); S text := '9978/9979'; S0 text := '9977/9978'; pa text := 'C00023'; pb text := 'C00061'; dept text;
        a1 uuid := gen_random_uuid(); a2 uuid := gen_random_uuid(); b3 uuid := gen_random_uuid(); b4 uuid := gen_random_uuid(); b5 uuid := gen_random_uuid();
        b6 uuid := gen_random_uuid(); a6 uuid := gen_random_uuid(); a7 uuid := gen_random_uuid(); a9 uuid := gen_random_uuid();
        o1 uuid := gen_random_uuid(); o2 uuid := gen_random_uuid(); o3 uuid := gen_random_uuid(); p1 uuid := gen_random_uuid(); p2 uuid := gen_random_uuid(); p3 uuid := gen_random_uuid();
        sh1 uuid := gen_random_uuid(); sh2 uuid := gen_random_uuid(); sh3 uuid := gen_random_uuid(); r uuid; ref text;
        e1 record; e2 record; e3 record; e4 record; e5 record; e6 record; e6a record; e7 record; e7n record; e9 record; e11 record; g1 record; g4 record; g4p record; g7 record;
        r_gate1 text; r_gate4 text; r_gate4all text; r_gate1all text; r_gate7 text; r_gate7paid text; r_ref4 text; n_pay4 int; n_refund4 int;
        menu_a1 boolean; menu_a6 boolean; menu_b5 boolean; carry_b5 boolean; n_pop int; n_mismatch int; pop_b4 record; sem2_a1 boolean; sem2_a2 boolean;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S0, date '9977-10-01', date '9978-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9978-10-01', date '9979-08-31') ON CONFLICT (name) DO NOTHING;
        UPDATE finance.gst_setting SET required_for_gst_eps = true, required_for_all = false, covers_eps = true WHERE id = 1;
        SELECT dept_code INTO dept FROM ref.programme WHERE code = pa;
        -- one canonical course each: GST 981 at 100 and GST 982 at 200 for both programmes; EPS 983 at 300 for programme A alone
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state) VALUES
            ('GST 981', 'Check Use of English', 2, 1, 100, dept, 'GST', 'LIVE'),
            ('GST 982', 'Check Philosophy and Logic', 2, 2, 200, dept, 'GST', 'LIVE'),
            ('EPS 983', 'Check Venture Creation', 2, 1, 300, dept, 'GST', 'LIVE');
        INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES
            ('GST 981', pa, 100, 'GST'), ('GST 981', pb, 100, 'GST'), ('GST 982', pa, 200, 'GST'), ('GST 982', pb, 200, 'GST'), ('EPS 983', pa, 300, 'GST');
        INSERT INTO catalogue.offering (id, course_code, session, semester) VALUES
            (o1, 'GST 981', S, 1), (o2, 'GST 982', S, 2), (o3, 'EPS 983', S, 1), (p1, 'GST 981', S0, 1), (p2, 'GST 982', S0, 2), (p3, 'EPS 983', S0, 1);
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at) VALUES
            (a1, 'MOAUM/ADM/78/978001', 'MOAUM/CHK/78/9801', 'ZZV366A', 'Hundred', pa, 'UTME', S, 100, 100, 'ACTIVE', now()),
            (a2, 'MOAUM/ADM/78/978002', 'MOAUM/CHK/78/9802', 'ZZV366B', 'TwoHundred', pa, 'UTME', S0, 100, 200, 'ACTIVE', now()),
            (b3, 'MOAUM/ADM/78/978003', 'MOAUM/CHK/78/9803', 'ZZV366C', 'ThreeHundredB', pb, 'UTME', S0, 100, 300, 'ACTIVE', now()),
            (b4, 'MOAUM/ADM/78/978004', 'MOAUM/CHK/78/9804', 'ZZV366D', 'FourHundredB', pb, 'UTME', S0, 100, 400, 'ACTIVE', now()),
            (b5, 'MOAUM/ADM/78/978005', 'MOAUM/CHK/78/9805', 'ZZV366E', 'CarryGst', pb, 'UTME', S0, 100, 300, 'ACTIVE', now()),
            (b6, 'MOAUM/ADM/78/978006', 'MOAUM/CHK/78/9806', 'ZZV366F', 'PassedBoth', pb, 'UTME', S0, 100, 400, 'ACTIVE', now()),
            (a6, 'MOAUM/ADM/78/978007', 'MOAUM/CHK/78/9807', 'ZZV366G', 'RepeatsLevel', pa, 'UTME', S0, 100, 100, 'ACTIVE', now()),
            (a7, 'MOAUM/ADM/78/978008', 'MOAUM/CHK/78/9808', 'ZZV366H', 'EpsAtThree', pa, 'UTME', S0, 100, 300, 'ACTIVE', now()),
            (a9, 'MOAUM/ADM/78/978009', 'MOAUM/CHK/78/9809', 'ZZV366I', 'CarryEps', pa, 'UTME', S0, 100, 400, 'ACTIVE', now());
        -- last session's record: b5 failed GST 981; b6 passed GST 981 and GST 982; a6 passed GST 981; a9 failed EPS 983 — all published
        r := gen_random_uuid(); INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, approved_at) VALUES (r, b5, S0, 1, 200, 'APPROVED', now());
        INSERT INTO registration.entry (registration_id, offering_id, units, status) VALUES (r, p1, 2, 'APPROVED');
        r := gen_random_uuid(); INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, approved_at) VALUES (r, b6, S0, 1, 300, 'APPROVED', now());
        INSERT INTO registration.entry (registration_id, offering_id, units, status) VALUES (r, p1, 2, 'APPROVED');
        r := gen_random_uuid(); INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, approved_at) VALUES (r, b6, S0, 2, 300, 'APPROVED', now());
        INSERT INTO registration.entry (registration_id, offering_id, units, status) VALUES (r, p2, 2, 'APPROVED');
        r := gen_random_uuid(); INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, approved_at) VALUES (r, a6, S0, 1, 100, 'APPROVED', now());
        INSERT INTO registration.entry (registration_id, offering_id, units, status) VALUES (r, p1, 2, 'APPROVED');
        r := gen_random_uuid(); INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, approved_at) VALUES (r, a9, S0, 1, 300, 'APPROVED', now());
        INSERT INTO registration.entry (registration_id, offering_id, units, status) VALUES (r, p3, 2, 'APPROVED');
        INSERT INTO assessment.score_sheet (id, offering_id, stage, senate_minute, published_at, submitted_at) VALUES
            (sh1, p1, 'PUBLISHED', 'SEN/9978/01', now(), now()), (sh2, p2, 'PUBLISHED', 'SEN/9978/01', now(), now()), (sh3, p3, 'PUBLISHED', 'SEN/9978/01', now(), now());
        INSERT INTO assessment.score (sheet_id, student_id, ca, exam, outcome) VALUES
            (sh1, b5, 10, 15, 'GRADED'), (sh1, b6, 30, 40, 'GRADED'), (sh1, a6, 30, 40, 'GRADED'), (sh2, b6, 30, 40, 'GRADED'), (sh3, a9, 10, 15, 'GRADED');
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM finance.state_gst_fee(S, 8000, NULL, NULL, NULL, NULL, current_date, 'V366 check', who, 'bursar');

        SELECT * INTO e1 FROM finance.gst_eps_eligibility(a1, S);    -- TEST 1
        SELECT * INTO g1 FROM finance.gst_entitlement(a1, S);
        r_gate1 := split_part(coalesce(registration.gst_gate(a1, S, 'GST 981'), 'OPEN'), ':', 1);   -- TEST 15
        SELECT * INTO e2 FROM finance.gst_eps_eligibility(a2, S);    -- TEST 2
        SELECT * INTO e3 FROM finance.gst_eps_eligibility(b3, S);    -- TEST 3, 8
        SELECT * INTO e4 FROM finance.gst_eps_eligibility(b4, S);    -- TEST 4, 10, 13
        SELECT * INTO g4 FROM finance.gst_entitlement(b4, S);
        r_gate4 := coalesce(registration.gst_gate(b4, S, 'GST 981'), 'OPEN');
        BEGIN PERFORM finance.new_gst_reference(b4, S); r_ref4 := 'ALLOWED'; EXCEPTION WHEN check_violation THEN r_ref4 := split_part(SQLERRM, ':', 1); END;
        SELECT * INTO e5 FROM finance.gst_eps_eligibility(b5, S);    -- TEST 5
        SELECT * INTO e6 FROM finance.gst_eps_eligibility(b6, S);    -- TEST 6
        SELECT * INTO e6a FROM finance.gst_eps_eligibility(a6, S);   -- passed, repeating the level
        SELECT * INTO e7 FROM finance.gst_eps_eligibility(a7, S);    -- TEST 7, 14
        r_gate7 := split_part(coalesce(registration.gst_gate(a7, S, 'EPS 983'), 'OPEN'), ':', 1);
        SELECT * INTO e9 FROM finance.gst_eps_eligibility(a9, S);    -- TEST 9
        -- the registration menu agrees: GST 981 on a1's form, not on a6's (passed), on b5's as a carryover
        SELECT EXISTS (SELECT 1 FROM registration.student_menu(a1, S, 1) WHERE course_code = 'GST 981' AND NOT carryover) INTO menu_a1;
        SELECT EXISTS (SELECT 1 FROM registration.student_menu(a6, S, 1) WHERE course_code = 'GST 981') INTO menu_a6;
        SELECT EXISTS (SELECT 1 FROM registration.student_menu(b5, S, 1) WHERE course_code = 'GST 981' AND carryover) INTO menu_b5;
        SELECT EXISTS (SELECT 1 FROM registration.carryovers(b5) WHERE course_code = 'GST 981') INTO carry_b5;
        -- the whole-registration rule holds a student who owes the fee, never one who does not (TEST 13, 18)
        UPDATE finance.gst_setting SET required_for_all = true WHERE id = 1;
        r_gate1all := split_part(coalesce(registration.gst_gate(a1, S, 'ZZZ 101'), 'OPEN'), ':', 1);
        r_gate4all := coalesce(registration.gst_gate(b4, S, 'ZZZ 101'), 'OPEN');
        UPDATE finance.gst_setting SET required_for_all = false WHERE id = 1;
        -- the offices' population is the same answer, student for student; a semester narrows it to the courses run in it
        SELECT count(*), count(*) FILTER (WHERE p.required IS DISTINCT FROM e.required OR p.gst_required IS DISTINCT FROM e.gst_required OR p.eps_required IS DISTINCT FROM e.eps_required
                                                 OR p.gst_reason IS DISTINCT FROM e.gst_reason OR p.eps_reason IS DISTINCT FROM e.eps_reason)
          INTO n_pop, n_mismatch
          FROM finance.gst_population(S, NULL) p CROSS JOIN LATERAL finance.gst_eps_eligibility(p.student_id, S) e
         WHERE p.student_id IN (a1, a2, b3, b4, b5, b6, a6, a7, a9);
        SELECT gst_required INTO sem2_a1 FROM finance.gst_population(S, 2) WHERE student_id = a1;
        SELECT gst_required INTO sem2_a2 FROM finance.gst_population(S, 2) WHERE student_id = a2;
        -- TEST 14: the EPS student pays the one GST fee and the EPS course opens
        PERFORM set_config('moaum.actor_office', 'student', true);
        ref := finance.new_gst_reference(a7, S);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM finance.confirm_payment(ref, 'Bank transfer', 'V366 check');
        SELECT * INTO g7 FROM finance.gst_entitlement(a7, S);
        r_gate7paid := coalesce(registration.gst_gate(a7, S, 'EPS 983'), 'OPEN');
        -- TEST 12: a payment no course requires stands, flagged for review — not deleted, not refunded
        ref := finance.new_purpose_reference(b4, S, 8000, 'GST fee ' || S);
        PERFORM finance.confirm_payment(ref, 'Bank transfer', 'V366 check');
        SELECT * INTO g4p FROM finance.gst_entitlement(b4, S);
        SELECT * INTO pop_b4 FROM finance.gst_population(S, NULL) WHERE student_id = b4;
        SELECT count(*) INTO n_pay4 FROM finance.payment_reference WHERE student_id = b4 AND purpose LIKE 'GST fee %' AND confirmed_at IS NOT NULL;
        SELECT count(*) INTO n_refund4 FROM finance.refund WHERE reference = ref;
        -- where the GST payment does not cover EPS, an EPS course alone owes no GST fee
        UPDATE finance.gst_setting SET covers_eps = false WHERE id = 1;
        SELECT * INTO e7n FROM finance.gst_eps_eligibility(a7, S);
        UPDATE finance.gst_setting SET covers_eps = true WHERE id = 1;
        -- TEST 11: the approved change of programme is read at once — B to A brings EPS 983 at 300
        PERFORM set_config('moaum.actor_office', 'registrar', true);
        UPDATE people.student SET programme_code = pa WHERE id = b3;
        SELECT * INTO e11 FROM finance.gst_eps_eligibility(b3, S);
        RAISE EXCEPTION 'the V366 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V366: GST & EPS are owed for a course the student must take — the programme''s offering at the level, a carryover — never for the level alone; the gate, the reference, the menu and the offices'' population read the one answer',
        coalesce(
            -- TEST 1, 15: 100 level, GST 981 offered — required, unpaid, held
            e1.required AND e1.gst_required AND e1.gst_reason = 'GST_REQUIRED_COURSE_OFFERING' AND e1.gst_courses = ARRAY['GST 981'] AND g1.state = 'NOT_PAID' AND r_gate1 = 'GST_PAYMENT_REQUIRED'
            -- TEST 2: 200 level, GST 982
            AND e2.required AND e2.gst_courses = ARRAY['GST 982']
            -- TEST 3, 8: 300 level in B, no GST course, no EPS 983 — nothing
            AND NOT e3.required AND e3.gst_reason = 'GST_NOT_APPLICABLE' AND e3.eps_reason = 'EPS_NOT_APPLICABLE'
            -- TEST 4, 10, 13: 400 level in B — nothing owed, no reference, no gate even under the whole-registration rule
            AND NOT e4.required AND g4.state = 'NOT_REQUIRED' AND r_gate4 = 'OPEN' AND r_ref4 = 'GST_NOT_REQUIRED' AND r_gate4all = 'OPEN' AND r_gate1all = 'GST_PAYMENT_REQUIRED'
            -- TEST 5: 300 level with GST 981 failed — a carryover, and the menu and registration.carryovers say so too
            AND e5.required AND e5.gst_reason = 'GST_REQUIRED_CARRYOVER' AND e5.gst_carryovers = ARRAY['GST 981'] AND menu_b5 AND carry_b5
            -- TEST 6: 400 level, both passed — nothing; a student repeating 100 level who passed GST 981 is not offered it again
            AND NOT e6.required AND e6.gst_reason = 'GST_NOT_APPLICABLE' AND NOT e6a.required AND e6a.gst_reason = 'GST_ALREADY_COMPLETED' AND menu_a1 AND NOT menu_a6
            -- TEST 7, 14: 300 level in A, EPS 983 offered — the one GST fee owed for EPS, held until paid, open after
            AND e7.required AND NOT e7.gst_required AND e7.eps_required AND e7.eps_reason = 'EPS_REQUIRED_COURSE_OFFERING' AND r_gate7 = 'GST_PAYMENT_REQUIRED'
            AND g7.state = 'PAID' AND r_gate7paid = 'OPEN' AND NOT e7n.required AND e7n.eps_required AND e7n.reason = 'EPS_NOT_COVERED_BY_GST_FEE'
            -- TEST 9: 400 level with EPS 983 failed
            AND e9.eps_required AND e9.eps_reason = 'EPS_REQUIRED_CARRYOVER'
            -- TEST 11: programme changed from B to A — recalculated on the new programme
            AND e11.eps_required AND e11.required
            -- TEST 12: paid though nothing requires it — kept, flagged for review, no refund made
            AND g4p.state = 'PAID' AND g4p.review AND NOT g4p.required AND pop_b4.review AND n_pay4 = 1 AND n_refund4 = 0
            -- the population, student for student; semester 2 runs GST 982 and not GST 981
            AND n_pop = 9 AND n_mismatch = 0 AND NOT sem2_a1 AND sem2_a2, false),
        format('e1=%s/%s/%s/%s g1=%s gate1=%s | e2=%s/%s | e3=%s/%s/%s | e4=%s g4=%s gate4=%s ref4=%s all4=%s all1=%s | e5=%s/%s/%s menu=%s carry=%s | e6=%s/%s e6a=%s/%s menu_a1=%s menu_a6=%s | e7=%s/%s/%s/%s gate7=%s paid=%s after=%s e7n=%s/%s/%s | e9=%s/%s | e11=%s/%s | g4p=%s/%s/%s pop=%s pay=%s refund=%s | pop=%s mismatch=%s sem2=%s/%s',
               e1.required, e1.gst_required, e1.gst_reason, e1.gst_courses, g1.state, r_gate1, e2.required, e2.gst_courses, e3.required, e3.gst_reason, e3.eps_reason,
               e4.required, g4.state, r_gate4, r_ref4, r_gate4all, r_gate1all, e5.required, e5.gst_reason, e5.gst_carryovers, menu_b5, carry_b5,
               e6.required, e6.gst_reason, e6a.required, e6a.gst_reason, menu_a1, menu_a6, e7.required, e7.gst_required, e7.eps_required, e7.eps_reason, r_gate7, g7.state, r_gate7paid,
               e7n.required, e7n.eps_required, e7n.reason, e9.eps_required, e9.eps_reason, e11.eps_required, e11.required, g4p.state, g4p.review, g4p.required, pop_b4.review, n_pay4, n_refund4,
               n_pop, n_mismatch, sem2_a1, sem2_a2));
END $$;

-- ── V367: a GST refund counts, a payment no course requires is decided by the Bursary, the session's offerings are checked ──
DO $$
DECLARE maker uuid := gen_random_uuid(); checker uuid := gen_random_uuid(); S text := '9976/9977'; SC text := '9974/9975'; pa text := 'C00023'; dept text;
        s1 uuid := gen_random_uuid(); s2 uuid := gen_random_uuid(); s3 uuid := gen_random_uuid(); ref1 text; ref1b text; ref2 text; ref3 text; rf text; d finance.gst_payment_review;
        n_gap_before int; n_opened int; n_again int; n_gap_after int; r_closed text; e1 record; e1r record; r_gate1 text; r_pending text;
        e2 record; e2k record; pop2 boolean; e3 record; e3p record; e3x record; e3z record; v_src text; v_rfstate text; r_note text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', maker::text, true);
        PERFORM set_config('moaum.actor_office', 'gst', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9976-10-01', date '9977-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on, state) VALUES (gen_random_uuid(), SC, date '9974-10-01', date '9975-08-31', 'CLOSED') ON CONFLICT (name) DO NOTHING;
        UPDATE finance.gst_setting SET required_for_gst_eps = true, required_for_all = false, covers_eps = true WHERE id = 1;
        SELECT dept_code INTO dept FROM ref.programme WHERE code = pa;
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state) VALUES ('GST 971', 'Check Communication', 2, 1, 100, dept, 'GST', 'LIVE');
        INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES ('GST 971', pa, 100, 'GST');
        -- the course is bound but not opened: named as a gap; opened once, in its own semester; a closed session refused
        SELECT count(*) INTO n_gap_before FROM catalogue.gst_offering_gaps(S, 'GST') WHERE course_code = 'GST 971';
        n_opened := catalogue.open_gst_offerings(S, 'GST');
        n_again := catalogue.open_gst_offerings(S, 'GST');
        SELECT count(*) INTO n_gap_after FROM catalogue.gst_offering_gaps(S, 'GST') WHERE course_code = 'GST 971';
        BEGIN PERFORM catalogue.open_gst_offerings(SC, 'GST'); r_closed := 'ALLOWED'; EXCEPTION WHEN check_violation THEN r_closed := split_part(SQLERRM, ':', 1); END;
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at) VALUES
            (s1, 'MOAUM/ADM/76/976001', 'MOAUM/CHK/76/9761', 'ZZV367A', 'Owes', pa, 'UTME', S, 100, 100, 'ACTIVE', now()),
            (s2, 'MOAUM/ADM/76/976002', 'MOAUM/CHK/76/9762', 'ZZV367B', 'Kept', pa, 'UTME', S, 100, 300, 'ACTIVE', now()),
            (s3, 'MOAUM/ADM/76/976003', 'MOAUM/CHK/76/9763', 'ZZV367C', 'Refunded', pa, 'UTME', S, 100, 300, 'ACTIVE', now());
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM finance.state_gst_fee(S, 6000, NULL, NULL, NULL, NULL, current_date, 'V367 check', maker, 'bursar');
        -- s1 owes and pays; refunded in full by maker and checker, the payment no longer entitles and the gate holds again
        ref1 := finance.new_gst_reference(s1, S);
        PERFORM finance.confirm_payment(ref1, 'Bank transfer', 'V367 check');
        SELECT * INTO e1 FROM finance.gst_entitlement(s1, S);
        rf := finance.propose_refund(s1, 'ZZV367A Owes', 'V367 check: paid twice', 6000, NULL, NULL, NULL, ref1);
        PERFORM set_config('moaum.actor_id', checker::text, true);
        PERFORM finance.approve_refund((SELECT id FROM finance.refund WHERE reference = rf));
        PERFORM set_config('moaum.actor_id', maker::text, true);
        SELECT * INTO e1r FROM finance.gst_entitlement(s1, S);
        r_gate1 := split_part(coalesce(registration.gst_gate(s1, S, 'GST 971'), 'OPEN'), ':', 1);
        -- a payment a course requires is not the Bursary's to decide as "not required"
        ref1b := finance.new_gst_reference(s1, S);
        PERFORM finance.confirm_payment(ref1b, 'Bank transfer', 'V367 check');
        BEGIN PERFORM finance.decide_gst_payment(ref1b, 'KEEP', 'check'); r_pending := 'ALLOWED'; EXCEPTION WHEN check_violation THEN r_pending := split_part(SQLERRM, ':', 1); END;
        -- s2 paid though nothing requires it: in review, then kept with a note — out of review, the payment untouched
        ref2 := finance.new_purpose_reference(s2, S, 6000, 'GST fee ' || S);
        PERFORM finance.confirm_payment(ref2, 'Bank transfer', 'V367 check');
        SELECT * INTO e2 FROM finance.gst_entitlement(s2, S);
        BEGIN PERFORM finance.decide_gst_payment(ref2, 'KEEP', '  '); r_note := 'ALLOWED'; EXCEPTION WHEN check_violation THEN r_note := split_part(SQLERRM, ':', 1); END;
        d := finance.decide_gst_payment(ref2, 'KEEP', 'Programme change to a GST programme pending at the Registry');
        SELECT * INTO e2k FROM finance.gst_entitlement(s2, S);
        SELECT review INTO pop2 FROM finance.gst_population(S, NULL) WHERE student_id = s2;
        -- s3 paid though nothing requires it: REFUND proposes a refund against the payment; rejected, back in review; refunded, gone
        ref3 := finance.new_purpose_reference(s3, S, 6000, 'GST fee ' || S);
        PERFORM finance.confirm_payment(ref3, 'Bank transfer', 'V367 check');
        SELECT * INTO e3 FROM finance.gst_entitlement(s3, S);
        d := finance.decide_gst_payment(ref3, 'REFUND', 'No GST course at 300 level for the programme');
        SELECT source_reference, state INTO v_src, v_rfstate FROM finance.refund WHERE id = d.refund_id;
        SELECT * INTO e3p FROM finance.gst_entitlement(s3, S);
        PERFORM finance.reject_refund(d.refund_id, 'bank details to be confirmed');
        SELECT * INTO e3x FROM finance.gst_entitlement(s3, S);
        d := finance.decide_gst_payment(ref3, 'REFUND', 'Bank details confirmed');
        PERFORM set_config('moaum.actor_id', checker::text, true);
        PERFORM finance.approve_refund(d.refund_id);
        SELECT * INTO e3z FROM finance.gst_entitlement(s3, S);
        RAISE EXCEPTION 'the V367 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V367: a GST refund approved against the payment takes the entitlement back; a payment no course requires stays in review until the Bursary keeps it or refunds it through maker and checker; the session''s unopened GST/EPS courses are named and opened once',
        coalesce(n_gap_before = 1 AND n_opened >= 1 AND n_again = 0 AND n_gap_after = 0 AND r_closed = 'GST_SESSION_CLOSED'
                 AND e1.state = 'PAID' AND NOT e1r.entitled AND e1r.state = 'NOT_PAID' AND r_gate1 = 'GST_PAYMENT_REQUIRED' AND r_pending = 'GST_REVIEW_NOT_PENDING'
                 AND e2.review AND r_note = 'GST_REVIEW_NOTE' AND NOT e2k.review AND e2k.state = 'PAID' AND NOT pop2
                 AND e3.review AND v_src = ref3 AND v_rfstate = 'PROPOSED' AND NOT e3p.review AND e3p.state = 'PAID' AND e3x.review
                 AND e3z.state = 'NOT_REQUIRED' AND NOT e3z.entitled AND NOT e3z.review, false),
        format('gaps=%s opened=%s again=%s after=%s closed=%s | e1=%s refunded=%s/%s gate=%s pending=%s | e2=%s note=%s kept=%s/%s pop=%s | e3=%s src=%s rf=%s proposed=%s/%s rejected=%s refunded=%s/%s/%s',
               n_gap_before, n_opened, n_again, n_gap_after, r_closed, e1.state, e1r.entitled, e1r.state, r_gate1, r_pending, e2.review, r_note, e2k.review, e2k.state, pop2,
               e3.review, v_src = ref3, v_rfstate, e3p.review, e3p.state, e3x.review, e3z.state, e3z.entitled, e3z.review));
END $$;

-- ── V367: a GST/EPS course is an office's by its code family, never by default; a departmental course an upload marked general owes no GST fee ──
DO $$
DECLARE who uuid := gen_random_uuid(); S text := '9973/9974'; pa text := 'C00023'; dept text; st uuid := gen_random_uuid(); o_mth uuid := gen_random_uuid(); ex assessment.cbt_exam;
        g_gst text; g_ent text; g_mth text; g_ges text; g_bus text; g_bus2 text; n_stats int; e record; r_gate text; r_gst_exam text; v_exam_office text; v_exam_after text;
        g_mth_family text; n_assigned int; k_agr text; b_agr text; g_mth_back text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9973-10-01', date '9974-08-31') ON CONFLICT (name) DO NOTHING;
        UPDATE finance.gst_setting SET required_for_gst_eps = true, required_for_all = false, covers_eps = true WHERE id = 1;
        SELECT dept_code INTO dept FROM ref.programme WHERE code = pa;
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state) VALUES
            ('GST 951', 'Check Use of English', 2, 1, 100, dept, 'GST', 'LIVE'),
            ('ENT 952', 'Check Venture Creation', 2, 1, 200, dept, 'GST', 'LIVE'),
            ('MTH 953', 'Check General Mathematics', 3, 1, 100, dept, 'GST', 'LIVE'),          -- a departmental course an upload marked G
            ('GES 954', 'Check Entrepreneurship and Innovation', 2, 1, 300, dept, 'GST', 'LIVE'),
            ('BUS 955', 'Check Business Creation', 2, 1, 300, dept, 'GST', 'LIVE'),
            ('AGR 956', 'Check Introductory Agriculture', 2, 1, 100, dept, 'GST', 'LIVE');
        SELECT general_office INTO g_gst FROM catalogue.course WHERE code = 'GST 951';
        SELECT general_office INTO g_ent FROM catalogue.course WHERE code = 'ENT 952';
        SELECT general_office INTO g_mth FROM catalogue.course WHERE code = 'MTH 953';
        SELECT general_office INTO g_ges FROM catalogue.course WHERE code = 'GES 954';
        SELECT general_office INTO g_bus FROM catalogue.course WHERE code = 'BUS 955';
        -- the departmental course bound to a programme and offered: not on the GST office's courses, owes no GST fee, no gate
        INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES ('MTH 953', pa, 100, 'GST'), ('AGR 956', pa, 100, 'GST');
        INSERT INTO catalogue.offering (id, course_code, session, semester) VALUES (o_mth, 'MTH 953', S, 1);
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (st, 'MOAUM/ADM/73/973001', 'MOAUM/CHK/73/9731', 'ZZV367D', 'Departmental', pa, 'UTME', S, 100, 100, 'ACTIVE', now());
        PERFORM finance.state_gst_fee(S, 5000, NULL, NULL, NULL, NULL, current_date, 'V367 check', who, 'bursar');
        SELECT count(*) INTO n_stats FROM finance.gst_course_stats(S, NULL, 'GST') WHERE course_code = 'MTH 953';
        SELECT * INTO e FROM finance.gst_entitlement(st, S);
        r_gate := coalesce(registration.gst_gate(st, S, 'MTH 953'), 'OPEN');
        -- its CBT examination is the examinations office's, not the GST office's
        BEGIN
            PERFORM assessment.cbt_new_exam('GST', o_mth, 'Check', NULL, 30, 0, 'FIXED', false, false, 50, 1, 'STANDARD', 'REMOTE', 1, 'TERMINATE', 'CONTINUE', now(), now() + interval '1 hour');
            r_gst_exam := 'ALLOWED';
        EXCEPTION WHEN check_violation THEN r_gst_exam := split_part(SQLERRM, ':', 1); END;
        ex := assessment.cbt_new_exam('EXAMS', o_mth, 'Check', NULL, 30, 0, 'FIXED', false, false, 50, 1, 'STANDARD', 'REMOTE', 1, 'TERMINATE', 'CONTINUE', now(), now() + interval '1 hour');
        v_exam_office := ex.office;
        -- the EPS office claims a course its families miss; a family added files the courses it reaches, and their examinations follow
        PERFORM catalogue.claim_general_course('BUS 955', 'EPS');
        SELECT general_office INTO g_bus2 FROM catalogue.course WHERE code = 'BUS 955';
        n_assigned := catalogue.set_general_family('MTH', 'GST');
        SELECT general_office INTO g_mth_family FROM catalogue.course WHERE code = 'MTH 953';
        SELECT office INTO v_exam_after FROM assessment.cbt_exam WHERE id = ex.id;
        PERFORM catalogue.set_general_family('MTH', NULL);
        -- a course no office runs, given back to its department: Core, its GST bindings Core
        PERFORM catalogue.return_general_course('AGR 956', 'a departmental course the structure marked G');
        SELECT kind INTO k_agr FROM catalogue.course WHERE code = 'AGR 956';
        SELECT basis INTO b_agr FROM catalogue.course_offer WHERE course_code = 'AGR 956' AND programme_code = pa;
        RAISE EXCEPTION 'the V367 classification check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V367: a course is the GST office''s by a General Studies family, the EPS office''s by an Entrepreneurship family or title, and no office''s otherwise — it owes no GST fee, is not on the GST desk and is examined by the examinations office; an office claims what its families miss',
        coalesce(g_gst = 'GST' AND g_ent = 'EPS' AND g_mth IS NULL AND g_ges = 'EPS' AND g_bus IS NULL
                 AND n_stats = 0 AND NOT e.required AND e.state = 'NOT_REQUIRED' AND r_gate = 'OPEN'
                 AND r_gst_exam = 'CBT_NOT_OFFICE_COURSE' AND v_exam_office = 'EXAMS'
                 AND g_bus2 = 'EPS' AND n_assigned = 1 AND g_mth_family = 'GST' AND v_exam_after = 'GST'
                 AND k_agr = 'Core' AND b_agr = 'Core', false),
        format('gst=%s ent=%s mth=%s ges=%s bus=%s | stats=%s required=%s state=%s gate=%s | gst exam=%s exams office=%s | claimed=%s family=%s/%s exam=%s | returned=%s/%s',
               g_gst, g_ent, g_mth, g_ges, g_bus, n_stats, e.required, e.state, r_gate, r_gst_exam, v_exam_office, g_bus2, n_assigned, g_mth_family, v_exam_after, k_agr, b_agr));
END $$;

-- ── V368: an upload keeps an EPS classification and a course given back; every move is listed; the old-portal reconciliation reads refunds by their payment ──
DO $$
DECLARE who uuid := gen_random_uuid(); checker uuid := gen_random_uuid(); S text := '9972/9973'; pa text := 'C00023'; dept text; st uuid := gen_random_uuid();
        g_bus text; g_mth text; k_agr text; b_agr text; k_agr2 text; g_agr2 text; rel_agr2 timestamptz; n_return int; n_claim int; n_upload int; v_conf timestamptz; mv uuid;
        ref text; rf text; imp uuid; v_status text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9972-10-01', date '9973-08-31') ON CONFLICT (name) DO NOTHING;
        SELECT dept_code INTO dept FROM ref.programme WHERE code = pa;
        -- the upload: a course classified EPS is the EPS office's, whatever its code; one classified GST outside the families is no office's
        PERFORM catalogue.import_catalogue(jsonb_build_array(
            jsonb_build_object('code', 'BUS 941', 'title', 'Check Business Creation', 'units', '2', 'level', '300', 'semester', '1', 'ownerDepartment', dept, 'offeringProgramme', pa, 'classification', 'EPS'),
            jsonb_build_object('code', 'MTH 942', 'title', 'Check General Mathematics', 'units', '3', 'level', '100', 'semester', '1', 'ownerDepartment', dept, 'offeringProgramme', pa, 'classification', 'GST'),
            jsonb_build_object('code', 'AGR 943', 'title', 'Check Introductory Agriculture', 'units', '2', 'level', '100', 'semester', '1', 'ownerDepartment', dept, 'offeringProgramme', pa, 'classification', 'GST')),
            true, 'v368.xlsx');
        SELECT general_office INTO g_bus FROM catalogue.course WHERE code = 'BUS 941';
        SELECT general_office INTO g_mth FROM catalogue.course WHERE code = 'MTH 942';
        -- given back, it stays given back: the next upload marking it GST changes neither the course nor its binding
        PERFORM catalogue.return_general_course('AGR 943', 'a departmental course');
        PERFORM catalogue.import_catalogue(jsonb_build_array(
            jsonb_build_object('code', 'AGR 943', 'title', 'Check Introductory Agriculture', 'units', '2', 'level', '100', 'semester', '1', 'ownerDepartment', dept, 'offeringProgramme', pa, 'classification', 'GST')),
            true, 'v368-again.xlsx');
        SELECT kind INTO k_agr FROM catalogue.course WHERE code = 'AGR 943';
        SELECT basis INTO b_agr FROM catalogue.course_offer WHERE course_code = 'AGR 943' AND programme_code = pa AND level = 100;
        -- an office takes it back on purpose
        PERFORM catalogue.claim_general_course('AGR 943', 'GST');
        SELECT kind, general_office, general_released_at INTO k_agr2, g_agr2, rel_agr2 FROM catalogue.course WHERE code = 'AGR 943';
        -- every move kept with its cause, and confirmed by the office it touches
        SELECT count(*) FILTER (WHERE cause = 'RETURN'), count(*) FILTER (WHERE cause = 'CLAIM') INTO n_return, n_claim FROM catalogue.general_reclassification WHERE course_code = 'AGR 943';
        SELECT id INTO mv FROM catalogue.general_reclassification WHERE course_code = 'AGR 943' AND cause = 'CLAIM';
        PERFORM catalogue.confirm_reclassification(mv);
        SELECT confirmed_at INTO v_conf FROM catalogue.general_reclassification WHERE id = mv;
        -- the old-portal reconciliation: a student whose GST payment here was refunded is not refused the old portal's as a duplicate
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM finance.state_gst_fee(S, 5000, NULL, NULL, NULL, NULL, current_date, 'V368 check', who, 'bursar');
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (st, 'MOAUM/ADM/72/972001', 'MOAUM/CHK/72/9721', 'ZZV368A', 'Refunded', pa, 'UTME', S, 100, 100, 'ACTIVE', now());
        ref := finance.new_purpose_reference(st, S, 5000, 'GST fee ' || S);
        PERFORM finance.confirm_payment(ref, 'Bank transfer', 'V368 check');
        rf := finance.propose_refund(st, 'ZZV368A Refunded', 'V368 check: duplicate', 5000, NULL, NULL, NULL, ref);
        PERFORM set_config('moaum.actor_id', checker::text, true);
        PERFORM finance.approve_refund((SELECT id FROM finance.refund WHERE reference = rf));
        PERFORM set_config('moaum.actor_id', who::text, true);
        imp := (finance.legacy_gst_new_import('v368.xlsx', S, 'check')).id;
        PERFORM finance.legacy_gst_stage(imp, jsonb_build_array(jsonb_build_object('transactionId', 'CHK-V368-1', 'reference', 'CHK-V368-OLD', 'matric', 'MOAUM/CHK/72/9721',
                                                                                    'paymentType', 'GST', 'amount', '5000', 'paidAt', '9972-10-15', 'session', S, 'status', 'SUCCESS')));
        PERFORM finance.legacy_gst_match(imp);
        PERFORM finance.legacy_gst_validate(imp);
        SELECT rc.status INTO v_status FROM finance.legacy_gst_payment p JOIN finance.legacy_gst_reconciliation rc ON rc.payment_id = p.id WHERE p.source_transaction_id = 'CHK-V368-1';
        RAISE EXCEPTION 'the V368 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V368: an upload classified EPS files the course with the EPS office and one classified GST outside the families with nobody; a course given back stays its department''s through the next upload until an office claims it; every move is kept with its cause and confirmed; a refunded GST payment does not make an old-portal payment a duplicate',
        coalesce(g_bus = 'EPS' AND g_mth IS NULL AND k_agr = 'Core' AND b_agr = 'Core' AND k_agr2 = 'GST' AND g_agr2 = 'GST' AND rel_agr2 IS NULL
                 AND n_return = 1 AND n_claim = 1 AND v_conf IS NOT NULL AND v_status = 'MATCHED', false),
        format('bus=%s mth=%s | after upload=%s/%s | claimed=%s/%s/%s | moves return=%s claim=%s confirmed=%s | legacy=%s',
               g_bus, g_mth, k_agr, b_agr, k_agr2, g_agr2, rel_agr2, n_return, n_claim, v_conf IS NOT NULL, v_status));
END $$;

-- ── V369: a course passes between the GST and EPS offices by request; a structure upload is previewed and keeps an office's course; the office is told ──
DO $$
DECLARE ict uuid := gen_random_uuid(); g_holder uuid := gen_random_uuid(); e_holder uuid := gen_random_uuid(); pa text := 'C00023'; rows jsonb; pv jsonb;
        c_gst text; c_ent text; c_mth text; a_gst text; a_ent_kind text; a_ent text; a_mth_kind text; a_mth text;
        n_gst_notice int; n_eps_notice int; up_cause text; up_conf timestamptz; r_claim text; t catalogue.general_transfer; r_again text; r_notyours text; r_noreason text;
        n_ask int; a_after text; tr_cause text; tr_conf timestamptz; t2 catalogue.general_transfer; t2_state text; own_conf timestamptz;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', ict::text, true);
        PERFORM set_config('moaum.actor_office', 'ict', true);
        INSERT INTO iam.person (id, surname, given_names, staff_number, email) VALUES
            (g_holder, 'CHECKMOVE', 'General Studies', 'P-V369-G', 'zz.check214.gst@example.com'),
            (e_holder, 'CHECKMOVE', 'Entrepreneurship', 'P-V369-E', 'zz.check214.eps@example.com'),
            (ict, 'CHECKMOVE', 'ICT', 'P-V369-I', NULL);
        INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from)
        VALUES (gen_random_uuid(), g_holder, 'gst', 'institution', NULL, 'CHECK V369', ict, current_date - 10),
               (gen_random_uuid(), e_holder, 'eps', 'institution', NULL, 'CHECK V369', ict, current_date - 10);
        -- the EPS office's own course, made by the EPS office: no move to tell
        PERFORM set_config('moaum.actor_id', e_holder::text, true);
        PERFORM set_config('moaum.actor_office', 'eps', true);
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state)
        SELECT 'ENT 962', 'Check Venture Creation', 2, 1, 300, p.dept_code, 'GST', 'LIVE' FROM ref.programme p WHERE p.code = pa;
        -- the structure: a new GST course, the EPS course marked C, a new course marked G that no family reaches
        rows := jsonb_build_array(
            jsonb_build_object('code', 'GST 961', 'title', 'Check Use of English', 'units', '2', 'status', 'G', 'level', '100', 'semester', '1'),
            jsonb_build_object('code', 'ENT 962', 'title', 'Check Venture Creation', 'units', '2', 'status', 'C', 'level', '300', 'semester', '1'),
            jsonb_build_object('code', 'MTH 963', 'title', 'Check General Mathematics', 'units', '3', 'status', 'G', 'level', '100', 'semester', '1'));
        pv := catalogue.structure_placements(jsonb_build_array(jsonb_build_object('programme', pa, 'rows', rows)));
        SELECT x->>'change' INTO c_gst FROM jsonb_array_elements(pv->'placements') x WHERE x->>'code' = 'GST 961';
        SELECT x->>'change' INTO c_ent FROM jsonb_array_elements(pv->'placements') x WHERE x->>'code' = 'ENT 962';
        SELECT x->>'change' INTO c_mth FROM jsonb_array_elements(pv->'placements') x WHERE x->>'code' = 'MTH 963';
        -- loaded by the Directorate of ICT: what the preview said is what happens
        PERFORM set_config('moaum.actor_id', ict::text, true);
        PERFORM set_config('moaum.actor_office', 'ict', true);
        PERFORM catalogue.import_courses(pa, rows, 'CCMAS');
        SELECT general_office INTO a_gst FROM catalogue.course WHERE code = 'GST 961';
        SELECT kind, general_office INTO a_ent_kind, a_ent FROM catalogue.course WHERE code = 'ENT 962';
        SELECT kind, general_office INTO a_mth_kind, a_mth FROM catalogue.course WHERE code = 'MTH 963';
        SELECT cause, confirmed_at INTO up_cause, up_conf FROM catalogue.general_reclassification WHERE course_code = 'GST 961';
        -- at commit the GST office's holders are told once; the EPS office lost nothing and hears nothing
        SET CONSTRAINTS ALL IMMEDIATE;
        SELECT count(*) INTO n_gst_notice FROM platform.notice WHERE recipient = 'zz.check214.gst@example.com' AND subject LIKE '%moved to or from the GST office' AND body LIKE '%GST 961%';
        SELECT count(*) INTO n_eps_notice FROM platform.notice WHERE recipient = 'zz.check214.eps@example.com';
        -- the GST office cannot take the EPS office's course; it asks, once
        PERFORM set_config('moaum.actor_id', g_holder::text, true);
        PERFORM set_config('moaum.actor_office', 'gst', true);
        BEGIN PERFORM catalogue.claim_general_course('ENT 962', 'GST'); r_claim := 'TAKEN';
        EXCEPTION WHEN check_violation THEN r_claim := split_part(SQLERRM, ':', 1); END;
        t := catalogue.request_general_transfer('ENT 962', 'GST', 'the GST office teaches it');
        BEGIN PERFORM catalogue.request_general_transfer('ENT 962', 'GST', 'again'); r_again := 'ASKED';
        EXCEPTION WHEN check_violation THEN r_again := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM catalogue.decide_general_transfer(t.id, true, NULL); r_notyours := 'DECIDED';
        EXCEPTION WHEN check_violation THEN r_notyours := split_part(SQLERRM, ':', 1); END;
        SELECT count(*) INTO n_ask FROM platform.notice WHERE recipient = 'zz.check214.eps@example.com' AND subject = 'The GST office asks for ENT 962';
        -- the EPS office must say why it declines; it accepts, and the move is confirmed by the answer
        PERFORM set_config('moaum.actor_id', e_holder::text, true);
        PERFORM set_config('moaum.actor_office', 'eps', true);
        BEGIN PERFORM catalogue.decide_general_transfer(t.id, false, NULL); r_noreason := 'DECLINED';
        EXCEPTION WHEN check_violation THEN r_noreason := split_part(SQLERRM, ':', 1); END;
        t := catalogue.decide_general_transfer(t.id, true, NULL);
        SELECT general_office INTO a_after FROM catalogue.course WHERE code = 'ENT 962';
        SELECT cause, confirmed_at INTO tr_cause, tr_conf FROM catalogue.general_reclassification WHERE course_code = 'ENT 962' ORDER BY changed_at DESC LIMIT 1;
        -- the EPS office asks for it back; the GST office gives it to its department instead, and the request lapses
        t2 := catalogue.request_general_transfer('ENT 962', 'EPS', 'it is an entrepreneurship course');
        PERFORM set_config('moaum.actor_id', g_holder::text, true);
        PERFORM set_config('moaum.actor_office', 'gst', true);
        PERFORM catalogue.return_general_course('ENT 962', 'a departmental course after all');
        SELECT state INTO t2_state FROM catalogue.general_transfer WHERE id = t2.id;
        -- a course no office holds, taken by the GST office: its own move, confirmed by its making
        PERFORM catalogue.claim_general_course('MTH 963', 'GST');
        SELECT confirmed_at INTO own_conf FROM catalogue.general_reclassification WHERE course_code = 'MTH 963' AND cause = 'CLAIM';
        RAISE EXCEPTION 'the V369 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V369: a structure upload is previewed as it loads — a new GST course to the GST office, an office''s course kept with the office though marked C, a course no family reaches marked general with no office — and the GST office alone is told, once; a course passes between the offices only by a request the holding office answers (a decline says why); a request lapses when the course moves first; an office''s own move is confirmed by its making',
        coalesce(c_gst = 'NEW_TO_OFFICE' AND c_ent = 'KEPT_WITH_OFFICE' AND c_mth = 'NEW_NO_OFFICE'
                 AND a_gst = 'GST' AND a_ent_kind = 'GST' AND a_ent = 'EPS' AND a_mth_kind = 'GST' AND a_mth IS NULL
                 AND up_cause = 'UPLOAD' AND up_conf IS NULL AND n_gst_notice = 1 AND n_eps_notice = 0
                 AND r_claim = 'GEN_OTHER_OFFICE' AND t.state = 'ACCEPTED' AND r_again = 'GEN_TRANSFER_PENDING' AND r_notyours = 'GEN_TRANSFER_NOT_YOURS'
                 AND n_ask = 1 AND r_noreason = 'GEN_REASON' AND a_after = 'GST' AND tr_cause = 'TRANSFER' AND tr_conf IS NOT NULL
                 AND t2_state = 'LAPSED' AND own_conf IS NOT NULL, false),
        format('preview=%s/%s/%s | loaded gst=%s ent=%s/%s mth=%s/%s | upload move=%s/%s | told gst=%s eps=%s | claim=%s again=%s not-yours=%s asked=%s no-reason=%s | accepted=%s now=%s move=%s/%s | lapse=%s | own=%s',
               c_gst, c_ent, c_mth, a_gst, a_ent_kind, a_ent, a_mth_kind, a_mth, up_cause, up_conf IS NOT NULL, n_gst_notice, n_eps_notice,
               r_claim, r_again, r_notyours, n_ask, r_noreason, t.state, a_after, tr_cause, tr_conf IS NOT NULL, t2_state, own_conf IS NOT NULL));
END $$;

-- ── V370: the structure upload reads EPS whole; a holder with no email is told by text; a request nobody answers is chased ──
DO $$
DECLARE ict uuid := gen_random_uuid(); g_holder uuid := gen_random_uuid(); e_holder uuid := gen_random_uuid(); a_holder uuid := gen_random_uuid();
        pa text := 'C00023'; rows jsonb; pv jsonb; c_bus text; o_bus text; c_gst text;
        k_bus text; g_bus text; k_ele text; k_gst text; g_gst text; t catalogue.general_transfer; n_sms int;
        ch1 record; ch2 record; ch3 record; rem timestamptz; esc timestamptz; n_acad int; r_set text; r_order text; v_set catalogue.general_transfer_setting;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', ict::text, true);
        PERFORM set_config('moaum.actor_office', 'ict', true);
        -- the GST office's holder has an email; the EPS office's only a phone; the Academic Office's an email
        INSERT INTO iam.person (id, surname, given_names, staff_number, email, phone) VALUES
            (g_holder, 'CHECKREACH', 'General Studies', 'P-V370-G', 'zz.check215.gst@example.com', NULL),
            (e_holder, 'CHECKREACH', 'Entrepreneurship', 'P-V370-E', NULL, '08030370215'),
            (a_holder, 'CHECKREACH', 'Academic', 'P-V370-A', 'zz.check215.academic@example.com', NULL),
            (ict, 'CHECKREACH', 'ICT', 'P-V370-I', NULL, NULL);
        INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from)
        VALUES (gen_random_uuid(), g_holder, 'gst', 'institution', NULL, 'CHECK V370', ict, current_date - 10),
               (gen_random_uuid(), e_holder, 'eps', 'institution', NULL, 'CHECK V370', ict, current_date - 10),
               (gen_random_uuid(), a_holder, 'academic', 'institution', NULL, 'CHECK V370', ict, current_date - 10);
        -- the GST office's own course
        PERFORM set_config('moaum.actor_id', g_holder::text, true);
        PERFORM set_config('moaum.actor_office', 'gst', true);
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state)
        SELECT 'GST 984', 'Check Communication Skills', 2, 1, 100, p.dept_code, 'GST', 'LIVE' FROM ref.programme p WHERE p.code = pa;
        -- the structure: status EPS on a new course, E on another, EPS on the GST office's course
        rows := jsonb_build_array(
            jsonb_build_object('code', 'BUS 981', 'title', 'Check Business Ideas', 'units', '2', 'status', 'EPS', 'level', '200', 'semester', '1'),
            jsonb_build_object('code', 'BUS 982', 'title', 'Check Marketing', 'units', '2', 'status', 'E', 'level', '200', 'semester', '1'),
            jsonb_build_object('code', 'GST 984', 'title', 'Check Communication Skills', 'units', '2', 'status', 'EPS', 'level', '100', 'semester', '1'));
        pv := catalogue.structure_placements(jsonb_build_array(jsonb_build_object('programme', pa, 'rows', rows)));
        SELECT x->>'change', x->>'afterOffice' INTO c_bus, o_bus FROM jsonb_array_elements(pv->'placements') x WHERE x->>'code' = 'BUS 981';
        SELECT x->>'change' INTO c_gst FROM jsonb_array_elements(pv->'placements') x WHERE x->>'code' = 'GST 984';
        PERFORM set_config('moaum.actor_id', ict::text, true);
        PERFORM set_config('moaum.actor_office', 'ict', true);
        PERFORM catalogue.import_courses(pa, rows, 'CCMAS');
        SELECT kind, general_office INTO k_bus, g_bus FROM catalogue.course WHERE code = 'BUS 981';
        SELECT kind INTO k_ele FROM catalogue.course WHERE code = 'BUS 982';
        SELECT kind, general_office INTO k_gst, g_gst FROM catalogue.course WHERE code = 'GST 984';
        -- the GST office asks for BUS 981: the EPS office's holder, with no email, is told by text
        PERFORM set_config('moaum.actor_id', g_holder::text, true);
        PERFORM set_config('moaum.actor_office', 'gst', true);
        t := catalogue.request_general_transfer('BUS 981', 'GST', 'the GST office teaches it');
        SELECT count(*) INTO n_sms FROM platform.notice WHERE channel = 'SMS' AND recipient = '08030370215' AND body LIKE 'MOAUM: The GST office asks for BUS 981%';
        -- not answered: reminded once after the reminder days, then put to the Academic Office after the escalation days
        UPDATE catalogue.general_transfer SET requested_at = now() - interval '4 days' WHERE id = t.id;
        SELECT * INTO ch1 FROM catalogue.chase_general_transfers();
        SELECT * INTO ch2 FROM catalogue.chase_general_transfers();
        UPDATE catalogue.general_transfer SET requested_at = now() - interval '8 days' WHERE id = t.id;
        SELECT * INTO ch3 FROM catalogue.chase_general_transfers();
        SELECT reminded_at, escalated_at INTO rem, esc FROM catalogue.general_transfer WHERE id = t.id;
        SELECT count(*) INTO n_acad FROM platform.notice WHERE recipient = 'zz.check215.academic@example.com' AND subject LIKE '%waits for your decision: BUS 981';
        -- the days are the Academic Office's to set, and the escalation comes after the reminder
        BEGIN PERFORM catalogue.set_general_transfer_setting(2, 5); r_set := 'SET';
        EXCEPTION WHEN check_violation THEN r_set := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_id', a_holder::text, true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        BEGIN PERFORM catalogue.set_general_transfer_setting(5, 5); r_order := 'SET';
        EXCEPTION WHEN check_violation THEN r_order := split_part(SQLERRM, ':', 1); END;
        v_set := catalogue.set_general_transfer_setting(2, 5);
        RAISE EXCEPTION 'the V370 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V370: a structure row of status EPS files a new course with the EPS office (previewed so) and E stays Elective; the GST office''s course marked EPS stays the GST office''s (previewed so); a holder with no email is told by text; an unanswered request is reminded once, then put to the Academic Office; the Academic Office sets the days',
        coalesce(c_bus = 'NEW_TO_OFFICE' AND o_bus = 'EPS' AND c_gst = 'OTHER_OFFICE_HOLDS'
                 AND k_bus = 'GST' AND g_bus = 'EPS' AND k_ele = 'Elective' AND k_gst = 'GST' AND g_gst = 'GST'
                 AND n_sms = 1 AND ch1.reminded = 1 AND ch2.reminded = 0 AND ch3.escalated = 1 AND rem IS NOT NULL AND esc IS NOT NULL AND n_acad = 1
                 AND r_set = 'GEN_TRANSFER_SETTING' AND r_order = 'GEN_TRANSFER_SETTING' AND v_set.remind_after_days = 2 AND v_set.escalate_after_days = 5, false),
        format('preview bus=%s/%s gst=%s | loaded bus=%s/%s ele=%s gst=%s/%s | sms=%s | chase %s/%s then %s/%s then %s/%s, reminded=%s escalated=%s academic=%s | setting by gst=%s order=%s set=%s/%s',
               c_bus, o_bus, c_gst, k_bus, g_bus, k_ele, k_gst, g_gst, n_sms, ch1.reminded, ch1.escalated, ch2.reminded, ch2.escalated, ch3.reminded, ch3.escalated,
               rem IS NOT NULL, esc IS NOT NULL, n_acad, r_set, r_order, v_set.remind_after_days, v_set.escalate_after_days));
END $$;

-- ── V371: the office previews its paper as a candidate sees it — the paper's questions at their current version, never the key ──
DO $$
DECLARE who uuid := gen_random_uuid(); off uuid := gen_random_uuid(); q1 uuid := gen_random_uuid(); q2 uuid := gen_random_uuid(); q3 uuid := gen_random_uuid();
        ex assessment.cbt_exam; n_rows int; m_first int; stem_first text; opts text; v_result text; n_attempts int;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'gst', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), '9967/9968', date '9967-10-01', date '9968-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state)
        SELECT 'GST 967', 'Check paper preview', 2, 1, 100, p.dept_code, 'GST', 'LIVE' FROM ref.programme p WHERE p.code = 'C00023';
        INSERT INTO catalogue.offering (id, course_code, session, semester) VALUES (off, 'GST 967', '9967/9968', 1);
        INSERT INTO assessment.question (id, course_code, stem, options, answer, kind, marks) VALUES
            (q1, 'GST 967', 'V371 first, as written', '["a","b","c","d"]', 2, 'MCQ', 1),
            (q2, 'GST 967', 'V371 second', '["yes","no"]', 0, 'MCQ', 1),
            (q3, 'GST 967', 'V371 not on the paper', '["a","b"]', 1, 'MCQ', 1);
        -- the first question corrected after it was written: the preview shows its current version
        UPDATE assessment.question SET stem = 'V371 first, corrected' WHERE id = q1;
        ex := assessment.cbt_new_exam('GST', off, 'V371 preview', NULL, 30, 0, 'FIXED', false, false, 50, 1, 'STANDARD', 'REMOTE', 1, 'WARN', 'CONTINUE', NULL, NULL);
        INSERT INTO assessment.cbt_exam_question (exam_id, question_id, ordinal, marks) VALUES (ex.id, q1, 1, 3), (ex.id, q2, 2, NULL);
        SELECT count(*) INTO n_rows FROM assessment.cbt_preview_paper(ex.id);
        SELECT marks, stem, (SELECT string_agg(o->>'i' || '=' || (o->>'text'), ',') FROM jsonb_array_elements(options) o) INTO m_first, stem_first, opts
          FROM assessment.cbt_preview_paper(ex.id) WHERE n = 1;
        v_result := pg_get_function_result('assessment.cbt_preview_paper(uuid)'::regprocedure);
        SELECT count(*) INTO n_attempts FROM assessment.cbt_attempt WHERE exam_id = ex.id;
        RAISE EXCEPTION 'the V371 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V371: the office''s preview is the paper''s questions in order, at their current version, with the paper''s marks and the options as written — and the function returns no key and no explanation; previewing makes no attempt',
        coalesce(n_rows = 2 AND m_first = 3 AND stem_first = 'V371 first, corrected' AND opts = '0=a,1=b,2=c,3=d'
                 AND v_result !~* 'answer|explanation|key' AND n_attempts = 0, false),
        format('rows=%s marks=%s stem=%s options=%s result=%s attempts=%s', n_rows, m_first, stem_first, opts, v_result, n_attempts));
END $$;

-- ── V372: a paper checked before publishing; each question analysed once the examination has ended ──
DO $$
DECLARE who uuid := gen_random_uuid(); off uuid := gen_random_uuid(); ex assessment.cbt_exam; ex2 assessment.cbt_exam;
        qa uuid := gen_random_uuid(); qb uuid := gen_random_uuid(); qc uuid := gen_random_uuid(); qd uuid := gen_random_uuid();
        qe uuid := gen_random_uuid(); qf uuid := gen_random_uuid(); k1 uuid := gen_random_uuid(); k2 uuid := gen_random_uuid(); k3 uuid := gen_random_uuid();
        checks text; st uuid; att uuid; r int; v_q1 text; v_q2 text; v_q3 text; d1 numeric; d3 numeric; f2 numeric; c1 jsonb; u1 jsonb; pa text := 'C00023';
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'gst', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), '9965/9966', date '9965-10-01', date '9966-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state)
        SELECT 'GST 965', 'Check paper and analysis', 2, 1, 100, p.dept_code, 'GST', 'LIVE' FROM ref.programme p WHERE p.code = pa;
        INSERT INTO catalogue.offering (id, course_code, session, semester) VALUES (off, 'GST 965', '9965/9966', 1);
        -- a paper with its options shuffled for each candidate, and every fault the checks look for
        INSERT INTO assessment.question (id, course_code, stem, options, answer, answers, kind, marks) VALUES
            (qa, 'GST 965', 'V372 positional', '["Lagos","Abuja","Kano","All of the above"]', 3, NULL, 'MCQ', 1),
            (qb, 'GST 965', 'V372 repeated', '["Lagos","Abuja","lagos ","Kano"]', 0, NULL, 'MCQ', 1),
            (qc, 'GST 965', 'V372 twice', '["one","two"]', 0, NULL, 'MCQ', 1),
            (qd, 'GST 965', 'V372   twice', '["two","one"]', 0, NULL, 'MCQ', 1),
            (qe, 'GST 965', 'V372 multi with one key', '["a","b","c"]', 1, ARRAY[1], 'MULTI', 1),
            (qf, 'GST 965', 'V372 blank option', '["a",""]', 0, NULL, 'MCQ', 1);
        ex := assessment.cbt_new_exam('GST', off, 'V372 checks', NULL, 30, 0, 'FIXED', false, true, 50, 1, 'STANDARD', 'REMOTE', 1, 'WARN', 'CONTINUE', NULL, NULL);
        INSERT INTO assessment.cbt_exam_question (exam_id, question_id, ordinal) VALUES (ex.id, qa, 1), (ex.id, qb, 2), (ex.id, qc, 3), (ex.id, qd, 4), (ex.id, qe, 5), (ex.id, qf, 6);
        PERFORM pg_temp.moderated();
        SELECT string_agg(coalesce(c.n::text, '-') || ':' || c.code || ':' || c.severity, ',' ORDER BY c.n, c.code) INTO checks FROM assessment.cbt_paper_checks(ex.id) c;
        -- an ended examination of three questions sat by twenty candidates: the top five all chose C on the first question, keyed A
        INSERT INTO assessment.question (id, course_code, stem, options, answer, kind, marks) VALUES
            (k1, 'GST 965', 'V372 wrong key?', '["a","b","c","d"]', 0, 'MCQ', 1),
            (k2, 'GST 965', 'V372 everyone right', '["a","b"]', 1, 'MCQ', 1),
            (k3, 'GST 965', 'V372 separates', '["a","b","c","d"]', 0, 'MCQ', 1);
        ex2 := assessment.cbt_new_exam('GST', off, 'V372 analysis', NULL, 30, 0, 'FIXED', false, false, 50, 1, 'STANDARD', 'REMOTE', 1, 'WARN', 'CONTINUE', NULL, NULL);
        INSERT INTO assessment.cbt_exam_question (exam_id, question_id, ordinal) VALUES (ex2.id, k1, 1), (ex2.id, k2, 2), (ex2.id, k3, 3);
        FOR r IN 1..20 LOOP
            st := gen_random_uuid(); att := gen_random_uuid();
            INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
            VALUES (st, 'MOAUM/ADM/65/' || lpad(r::text, 6, '0'), 'MOAUM/CHK/65/' || r, 'ZZV372', 'Candidate ' || r, pa, 'UTME', '9965/9966', 100, 100, 'ACTIVE', now());
            INSERT INTO assessment.cbt_attempt (id, exam_id, student_id, ends_at, submitted_at, status, question_ids, seed, max_marks, score, outcome, question_versions, question_marks)
            VALUES (att, ex2.id, st, now(), now(), 'SUBMITTED', ARRAY[k1, k2, k3], r, 3, 21 - r, 'SCORED', ARRAY[1, 1, 1], ARRAY[1, 1, 1]);
            INSERT INTO assessment.cbt_answer (attempt_id, question_id, chosen) VALUES
                (att, k1, CASE WHEN r <= 5 THEN ARRAY[2] ELSE ARRAY[0] END),
                (att, k2, ARRAY[1]),
                (att, k3, CASE WHEN r <= 10 THEN ARRAY[0] ELSE ARRAY[3] END);
        END LOOP;
        SELECT array_to_string(flags, '/'), discrimination, choices, upper_choices INTO v_q1, d1, c1, u1 FROM assessment.cbt_item_analysis(ex2.id) WHERE n = 1;
        SELECT array_to_string(flags, '/'), facility INTO v_q2, f2 FROM assessment.cbt_item_analysis(ex2.id) WHERE n = 2;
        SELECT array_to_string(flags, '/'), discrimination INTO v_q3, d3 FROM assessment.cbt_item_analysis(ex2.id) WHERE n = 3;
        RAISE EXCEPTION 'the V372 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V372: the paper checks name the positional option under shuffling, two options that read the same (HIGH when one is the key), the duplicate question, the blank option and the one-key multiple-select; the analysis flags the question the strongest candidates answered against its key, a very easy one, and leaves a well-separating one alone',
        coalesce(checks = '1:POSITIONAL_OPTION:HIGH,2:REPEATED_OPTION:HIGH,4:DUPLICATE_QUESTION:MEDIUM,5:MULTI_ONE_KEY:LOW,6:BLANK_OPTION:HIGH'
                 AND v_q1 = 'POSSIBLE_WRONG_KEY/NEGATIVE_DISCRIMINATION' AND d1 = -1.00 AND c1 = '{"0": 15, "2": 5}'::jsonb AND u1 = '{"2": 5}'::jsonb
                 AND v_q2 = 'WEAK_DISCRIMINATION/VERY_EASY' AND f2 = 1.00 AND v_q3 = '' AND d3 = 1.00, false),
        format('checks=%s | q1=%s d=%s choices=%s top=%s | q2=%s f=%s | q3=[%s] d=%s', checks, v_q1, d1, c1, u1, v_q2, f2, v_q3, d3));
END $$;

-- ── V373: a wrong key corrected with a record; candidates seated in sittings; extra time for a named candidate ──
DO $$
DECLARE who uuid := gen_random_uuid(); off uuid := gen_random_uuid(); pa text := 'C00023'; S text := '9963/9964';
        ex assessment.cbt_exam; ex2 assessment.cbt_exam; q1 uuid := gen_random_uuid(); q2 uuid := gen_random_uuid(); k1 uuid := gen_random_uuid(); k2 uuid := gen_random_uuid();
        st uuid[] := ARRAY[gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid()]; at uuid[] := ARRAY[gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid()];
        ca uuid[] := ARRAY[gen_random_uuid(), gen_random_uuid(), gen_random_uuid()]; i int; reg uuid;
        r_live text; r_one text; r_same text; r_pub text; pv text; kc assessment.cbt_key_correction; after text; s3_versions int; bank_key int[]; bank_ver int; key_now int[];
        s1 assessment.cbt_sitting; s2 assessment.cbt_sitting; seated record; a_a assessment.cbt_attempt; r_b text; r_c text; r_move text; r_remove text;
        ends_first interval; ends_after interval;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'gst', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9963-10-01', date '9964-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state)
        SELECT 'GST 963', 'Check key, sittings, time', 2, 1, 100, p.dept_code, 'GST', 'LIVE' FROM ref.programme p WHERE p.code = pa;
        INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES ('GST 963', pa, 100, 'GST');
        INSERT INTO catalogue.offering (id, course_code, session, semester) VALUES (off, 'GST 963', S, 1);

        -- (1) a key corrected: four candidates sat question 1, keyed A; the right answer was B
        INSERT INTO assessment.question (id, course_code, stem, options, answer, kind, marks) VALUES
            (k1, 'GST 963', 'V373 keyed wrongly', '["a","b","c"]', 0, 'MCQ', 1), (k2, 'GST 963', 'V373 keyed rightly', '["a","b"]', 0, 'MCQ', 1);
        ex2 := assessment.cbt_new_exam('GST', off, 'V373 key', NULL, 30, 0, 'FIXED', false, false, 50, 1, 'STANDARD', 'REMOTE', 1, 'WARN', 'CONTINUE', NULL, NULL);
        INSERT INTO assessment.cbt_exam_question (exam_id, question_id, ordinal) VALUES (ex2.id, k1, 1), (ex2.id, k2, 2);
        FOR i IN 1..4 LOOP
            INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
            VALUES (st[i], 'MOAUM/ADM/63/' || lpad(i::text, 6, '0'), 'MOAUM/CHK/63/' || i, 'ZZV373', 'Key ' || i, pa, 'UTME', S, 100, 100, 'ACTIVE', now());
            INSERT INTO assessment.cbt_attempt (id, exam_id, student_id, ends_at, submitted_at, status, question_ids, seed, max_marks, score, outcome, question_versions, question_marks)
            VALUES (at[i], ex2.id, st[i], now(), now(), 'SUBMITTED', ARRAY[k1, k2], i, 2, 0, CASE WHEN i = 4 THEN 'VOID' ELSE 'SCORED' END, ARRAY[1, 1], ARRAY[1, 1]);
            INSERT INTO assessment.cbt_answer (attempt_id, question_id, chosen) VALUES (at[i], k1, CASE WHEN i = 2 THEN ARRAY[0] ELSE ARRAY[1] END), (at[i], k2, ARRAY[0]);
            UPDATE assessment.cbt_attempt SET score = assessment.cbt_computed_score(at[i]) WHERE id = at[i];
            INSERT INTO assessment.cbt_result (attempt_id, version, score, max_marks, percentage, grade, passed, outcome)
            SELECT a.id, 1, a.score, 2, a.score * 50, NULL, a.score >= 1, a.outcome FROM assessment.cbt_attempt a WHERE a.id = at[i];
        END LOOP;
        -- the third candidate's score was cut by hand (a deduction); the correction must keep that
        PERFORM assessment.cbt_amend_result(at[3], 0, 'SCORED', 'deduction for a malpractice finding');
        BEGIN PERFORM assessment.cbt_correct_key(ex2.id, k1, ARRAY[1], 'B is right', true); r_live := 'CORRECTED';
        EXCEPTION WHEN check_violation THEN r_live := split_part(SQLERRM, ':', 1); END;
        UPDATE assessment.cbt_exam SET state = 'CLOSED', closed_at = now(), starts_at = now() - interval '3 hours', ends_at = now() - interval '1 hour', results_state = 'UNDER_REVIEW' WHERE id = ex2.id;
        BEGIN PERFORM assessment.cbt_correct_key(ex2.id, k1, ARRAY[0, 1], 'two keys', false); r_one := 'CORRECTED';
        EXCEPTION WHEN check_violation THEN r_one := split_part(SQLERRM, ':', 1); END;
        SELECT string_agg(p.number || ':' || trim_scale(p.old_score) || '>' || trim_scale(p.new_score), ',' ORDER BY p.number) INTO pv FROM assessment.cbt_key_correction_preview(ex2.id, k1, ARRAY[1]) p;
        kc := assessment.cbt_correct_key(ex2.id, k1, ARRAY[1], 'B is the right answer; the key was entered wrongly', true);
        SELECT string_agg(s.matric_no || ':' || trim_scale(a.score) || '/' || a.outcome, ',' ORDER BY s.matric_no) INTO after
          FROM assessment.cbt_attempt a JOIN people.student s ON s.id = a.student_id WHERE a.exam_id = ex2.id;
        SELECT count(*) INTO s3_versions FROM assessment.cbt_result WHERE attempt_id = at[3];
        SELECT answers, version INTO bank_key, bank_ver FROM assessment.question WHERE id = k1;
        key_now := assessment.cbt_key(ex2.id, k1, 1);
        BEGIN PERFORM assessment.cbt_correct_key(ex2.id, k1, ARRAY[1], 'again', false); r_same := 'CORRECTED';
        EXCEPTION WHEN check_violation THEN r_same := split_part(SQLERRM, ':', 1); END;
        UPDATE assessment.cbt_exam SET results_state = 'PUBLISHED' WHERE id = ex2.id;
        BEGIN PERFORM assessment.cbt_correct_key(ex2.id, k2, ARRAY[1], 'published', false); r_pub := 'CORRECTED';
        EXCEPTION WHEN check_violation THEN r_pub := split_part(SQLERRM, ':', 1); END;

        -- (2) sittings, and (3) extra time: three candidates, two sittings of one seat each
        INSERT INTO assessment.question (id, course_code, stem, options, answer, kind, marks) VALUES (q1, 'GST 963', 'V373 sitting one', '["a","b"]', 0, 'MCQ', 1), (q2, 'GST 963', 'V373 sitting two', '["a","b"]', 1, 'MCQ', 1);
        PERFORM pg_temp.moderated();
        ex := assessment.cbt_new_exam('GST', off, 'V373 sittings', NULL, 30, 0, 'FIXED', false, false, 50, 1, 'STANDARD', 'REMOTE', 1, 'WARN', 'CONTINUE', now() - interval '20 minutes', now() + interval '3 hours');
        INSERT INTO assessment.cbt_exam_question (exam_id, question_id, ordinal) VALUES (ex.id, q1, 1), (ex.id, q2, 2);
        FOR i IN 1..3 LOOP
            INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
            VALUES (ca[i], 'MOAUM/ADM/63/' || lpad((10 + i)::text, 6, '0'), 'MOAUM/CHK/63/1' || i, 'ZZV373', 'Seat ' || i, pa, 'UTME', S, 100, 100, 'ACTIVE', now());
            reg := registration.student_draft(ca[i], S, 1);
            PERFORM registration.student_choose(reg, ARRAY[off]);
            UPDATE registration.course_registration SET status = 'SUBMITTED', submitted_at = now() WHERE id = reg;
        END LOOP;
        PERFORM assessment.cbt_exam_action(ex.id, 'publish', NULL);
        s1 := assessment.cbt_add_sitting(ex.id, 'Sitting 1', 'CBT Lab A', now() - interval '10 minutes', now() + interval '50 minutes', 1);
        s2 := assessment.cbt_add_sitting(ex.id, 'Sitting 2', 'CBT Lab A', now() + interval '1 hour', now() + interval '2 hours', 1);
        SELECT * INTO seated FROM assessment.cbt_seat_all(ex.id, 'NUMBER');
        PERFORM assessment.cbt_grant_extra_time(ex.id, ca[1], 15, 'a candidate with a visual impairment');
        PERFORM set_config('moaum.actor_id', ca[1]::text, true);
        PERFORM set_config('moaum.actor_office', 'student', true);
        a_a := assessment.cbt_start(ex.id, ca[1], '10.0.0.1', 'check');
        ends_first := a_a.ends_at - now();
        PERFORM set_config('moaum.actor_id', ca[2]::text, true);
        BEGIN PERFORM assessment.cbt_start(ex.id, ca[2], '10.0.0.2', 'check'); r_b := 'STARTED';
        EXCEPTION WHEN check_violation THEN r_b := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_id', ca[3]::text, true);
        BEGIN PERFORM assessment.cbt_start(ex.id, ca[3], '10.0.0.3', 'check'); r_c := 'STARTED';
        EXCEPTION WHEN check_violation THEN r_c := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'gst', true);
        PERFORM assessment.cbt_grant_extra_time(ex.id, ca[1], 25, 'more time agreed by the office');
        SELECT a.ends_at - now() INTO ends_after FROM assessment.cbt_attempt a WHERE a.id = a_a.id;
        BEGIN PERFORM assessment.cbt_seat_candidate(ex.id, ca[3], s1.id); r_move := 'MOVED';
        EXCEPTION WHEN check_violation THEN r_move := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM assessment.cbt_remove_sitting(s1.id); r_remove := 'REMOVED';
        EXCEPTION WHEN check_violation THEN r_remove := split_part(SQLERRM, ':', 1); END;
        RAISE EXCEPTION 'the V373 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V373: a key is corrected only once the examination has ended — the preview is what is applied, a deduction made by hand is kept, a void result is untouched, the bank''s question corrected, the same key refused, published results the Registrar''s; candidates are seated by the sittings'' seats and start only in their own sitting; extra time lengthens the attempt at the start and while it runs',
        coalesce(r_live = 'CBT_KEY_LIVE' AND r_one = 'CBT_KEY_ONE'
                 AND pv = 'MOAUM/CHK/63/1:1>2,MOAUM/CHK/63/2:2>1,MOAUM/CHK/63/3:0>1,MOAUM/CHK/63/4:1>1'
                 AND kc.attempts_seen = 4 AND kc.scores_changed = 3 AND kc.bank_fixed AND kc.old_key = ARRAY[0] AND kc.new_key = ARRAY[1]
                 AND after = 'MOAUM/CHK/63/1:2/SCORED,MOAUM/CHK/63/2:1/SCORED,MOAUM/CHK/63/3:1/SCORED,MOAUM/CHK/63/4:1/VOID' AND s3_versions = 3
                 AND bank_key = ARRAY[1] AND bank_ver = 2 AND key_now = ARRAY[1] AND r_same = 'CBT_KEY_SAME' AND r_pub = 'CBT_KEY_PUBLISHED'
                 AND seated.seated = 2 AND seated.unseated = 1 AND r_b = 'CBT_NOT_YOUR_SITTING' AND r_c = 'CBT_NO_SITTING'
                 AND ends_first BETWEEN interval '44 minutes' AND interval '46 minutes' AND ends_after BETWEEN interval '54 minutes' AND interval '56 minutes'
                 AND r_move = 'CBT_SITTING_FULL' AND r_remove = 'CBT_SITTING_SAT', false),
        format('live=%s one=%s | preview=%s | seen=%s changed=%s bank=%s %s>%s | after=%s s3 versions=%s | bank=%s v%s key=%s same=%s pub=%s | seated=%s/%s b=%s c=%s | ends %s then %s | move=%s remove=%s',
               r_live, r_one, pv, kc.attempts_seen, kc.scores_changed, kc.bank_fixed, kc.old_key, kc.new_key, after, s3_versions, bank_key, bank_ver, key_now, r_same, r_pub,
               seated.seated, seated.unseated, r_b, r_c, ends_first, ends_after, r_move, r_remove));
END $$;

-- ── V374: questions moderated before a paper uses them; invigilators, attendance and late entry in a sitting ──
DO $$
DECLARE who uuid := gen_random_uuid(); mod uuid := gen_random_uuid(); inv uuid := gen_random_uuid(); nobody uuid := gen_random_uuid();
        off uuid := gen_random_uuid(); pa text := 'C00023'; S text := '9961/9962'; ex assessment.cbt_exam; ex2 assessment.cbt_exam; ex3 assessment.cbt_exam;
        q1 uuid := gen_random_uuid(); q2 uuid := gen_random_uuid(); q3 uuid := gen_random_uuid();
        ca uuid[] := ARRAY[gen_random_uuid(), gen_random_uuid(), gen_random_uuid()]; i int; reg uuid;
        st0 text; r_ready text; r_own text; st1 text; r_ready2 text; v2 int; st2 text; by2 uuid; r_note text; st3 text; decisions int; r_direct text;
        pool_n int; checks text; s1 assessment.cbt_sitting; s2 assessment.cbt_sitting; told int; r_busy text; r_staff text;
        r_late text; r_minutes text; a1 assessment.cbt_attempt; left1 interval; r_absent_begun text; r_absent text; r_after_clear text; rest int;
        board text; r_kept text; r_remove text; aud0 int; aud1 int; aud2 int;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'gst', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9961-10-01', date '9962-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state)
        SELECT 'GST 961', 'Check moderation and invigilation', 2, 1, 100, p.dept_code, 'GST', 'LIVE' FROM ref.programme p WHERE p.code = pa;
        INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES ('GST 961', pa, 100, 'GST');
        INSERT INTO catalogue.offering (id, course_code, session, semester) VALUES (off, 'GST 961', S, 1);

        -- (1) moderation: a question written waits, whatever the writer says; its setter cannot approve it; someone else does
        INSERT INTO assessment.question (id, course_code, stem, options, answer, kind, marks, moderation, moderated_by) VALUES
            (q1, 'GST 961', 'V374 one', '["a","b"]', 0, 'MCQ', 1, 'APPROVED', who), (q2, 'GST 961', 'V374 two', '["a","b"]', 1, 'MCQ', 1, 'APPROVED', mod),
            (q3, 'GST 961', 'V374 three', '["a","b"]', 1, 'MCQ', 1, 'PENDING', NULL);
        SELECT moderation INTO st0 FROM assessment.question WHERE id = q1;
        ex := assessment.cbt_new_exam('GST', off, 'V374 paper', NULL, 30, 0, 'FIXED', false, false, 50, 1, 'STANDARD', 'REMOTE', 1, 'WARN', 'CONTINUE', now() - interval '20 minutes', now() + interval '3 hours');
        INSERT INTO assessment.cbt_exam_question (exam_id, question_id, ordinal) VALUES (ex.id, q1, 1), (ex.id, q2, 2);
        r_ready := split_part(assessment.cbt_paper_ready(ex.id), ':', 1);
        SELECT string_agg(coalesce(c.n::text, '-') || ':' || c.code, ',' ORDER BY c.n, c.code) INTO checks FROM assessment.cbt_paper_checks(ex.id) c WHERE c.code = 'NOT_MODERATED';
        BEGIN PERFORM assessment.question_moderate(q1, 'approve', NULL); r_own := 'APPROVED';
        EXCEPTION WHEN check_violation THEN r_own := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_id', mod::text, true);
        PERFORM assessment.question_moderate(q1, 'approve', NULL);
        PERFORM assessment.question_moderate(q2, 'approve', 'clear and fair');
        SELECT moderation INTO st1 FROM assessment.question WHERE id = q1;
        r_ready2 := coalesce(assessment.cbt_paper_ready(ex.id), 'READY');
        -- a whole-bank paper draws approved questions only (q3 waits)
        ex3 := assessment.cbt_new_exam('GST', off, 'V374 whole bank', NULL, 30, 2, 'RANDOM', false, false, 50, 1, 'STANDARD', 'REMOTE', 1, 'WARN', 'CONTINUE', NULL, NULL);
        SELECT count(*) INTO pool_n FROM assessment.cbt_pool(ex3.id);
        -- a change is a new version, made by its changer, waiting again; returned only with a note; set approved by its setter, refused
        PERFORM set_config('moaum.actor_id', who::text, true);
        UPDATE assessment.question SET stem = 'V374 one, reworded' WHERE id = q1;
        SELECT version, moderation, updated_by INTO v2, st2, by2 FROM assessment.question WHERE id = q1;
        BEGIN UPDATE assessment.question SET moderation = 'APPROVED', moderated_by = who, moderated_at = now() WHERE id = q1; r_direct := 'APPROVED';
        EXCEPTION WHEN check_violation THEN r_direct := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_id', mod::text, true);
        BEGIN PERFORM assessment.question_moderate(q1, 'return', '  '); r_note := 'RETURNED';
        EXCEPTION WHEN check_violation THEN r_note := split_part(SQLERRM, ':', 1); END;
        PERFORM assessment.question_moderate(q1, 'return', 'say which a and b');
        SELECT moderation INTO st3 FROM assessment.question WHERE id = q1;
        SELECT count(*) INTO decisions FROM assessment.question_moderation WHERE question_id = q1;
        PERFORM assessment.question_moderate(q1, 'approve', NULL);

        -- (2) invigilators: staff only, never two overlapping sittings, told when named
        FOR i IN 1..3 LOOP
            INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
            VALUES (ca[i], 'MOAUM/ADM/61/' || lpad(i::text, 6, '0'), 'MOAUM/CHK/61/' || i, 'ZZV374', 'Seat ' || i, pa, 'UTME', S, 100, 100, 'ACTIVE', now());
            reg := registration.student_draft(ca[i], S, 1);
            PERFORM registration.student_choose(reg, ARRAY[off]);
            UPDATE registration.course_registration SET status = 'SUBMITTED', submitted_at = now() WHERE id = reg;
        END LOOP;
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM assessment.cbt_exam_action(ex.id, 'publish', NULL);
        PERFORM assessment.cbt_set_late_entry(ex.id, 5);
        s1 := assessment.cbt_add_sitting(ex.id, 'Sitting 1', 'CBT Lab B', now() - interval '10 minutes', now() + interval '50 minutes', 3);
        PERFORM assessment.cbt_seat_all(ex.id, 'NUMBER');
        ex2 := assessment.cbt_new_exam('GST', off, 'V374 other paper', NULL, 30, 0, 'FIXED', false, false, 50, 1, 'STANDARD', 'REMOTE', 1, 'WARN', 'CONTINUE', now() - interval '1 hour', now() + interval '3 hours');
        s2 := assessment.cbt_add_sitting(ex2.id, 'Other sitting', 'CBT Lab C', now(), now() + interval '40 minutes', 10);
        INSERT INTO iam.person (id, staff_number, surname, given_names, email) VALUES (inv, 'CHECK/V374', 'ZZINVIGILATOR', 'Invented', 'invigilator@example.invalid'),
                                                                                     (nobody, 'CHECK/V374/X', 'ZZNOOFFICE', 'Invented', NULL);
        INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from, valid_to)
        VALUES (gen_random_uuid(), inv, 'hod', 'department', 'MTC', 'check', gen_random_uuid(), current_date, NULL);
        PERFORM assessment.cbt_assign_invigilator(s1.id, inv, true);
        SELECT count(*) INTO told FROM platform.notice WHERE about_kind = 'person' AND about_id = inv;
        BEGIN PERFORM assessment.cbt_assign_invigilator(s2.id, inv, false); r_busy := 'ASSIGNED';
        EXCEPTION WHEN check_violation THEN r_busy := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM assessment.cbt_assign_invigilator(s1.id, nobody, false); r_staff := 'ASSIGNED';
        EXCEPTION WHEN check_violation THEN r_staff := split_part(SQLERRM, ':', 1); END;

        -- (3) attendance and late entry: ten minutes in, past the five-minute limit
        PERFORM set_config('moaum.actor_id', ca[1]::text, true);
        PERFORM set_config('moaum.actor_office', 'student', true);
        BEGIN PERFORM assessment.cbt_start(ex.id, ca[1], '10.0.0.1', 'check'); r_late := 'STARTED';
        EXCEPTION WHEN check_violation THEN r_late := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_id', inv::text, true);
        PERFORM set_config('moaum.actor_office', 'hod', true);
        BEGIN PERFORM assessment.cbt_admit_late(s1.id, ca[1], 30, 'came from the clinic'); r_minutes := 'ADMITTED';
        EXCEPTION WHEN check_violation THEN r_minutes := split_part(SQLERRM, ':', 1); END;
        PERFORM assessment.cbt_admit_late(s1.id, ca[1], 10, 'came from the clinic');
        PERFORM set_config('moaum.actor_id', ca[1]::text, true);
        PERFORM set_config('moaum.actor_office', 'student', true);
        a1 := assessment.cbt_start(ex.id, ca[1], '10.0.0.1', 'check');
        left1 := a1.ends_at - now();
        -- (5) a heartbeat is not audited; a violation is
        SELECT count(*) INTO aud0 FROM audit.entries WHERE subject_id = a1.id;
        UPDATE assessment.cbt_attempt SET last_activity_at = now() + interval '1 second', answered = 1 WHERE id = a1.id;
        SELECT count(*) INTO aud1 FROM audit.entries WHERE subject_id = a1.id;
        UPDATE assessment.cbt_attempt SET violations = violations + 1, last_activity_at = now() WHERE id = a1.id;
        SELECT count(*) INTO aud2 FROM audit.entries WHERE subject_id = a1.id;
        PERFORM set_config('moaum.actor_id', inv::text, true);
        PERFORM set_config('moaum.actor_office', 'hod', true);
        BEGIN PERFORM assessment.cbt_mark_absent(s1.id, ca[1], NULL); r_absent_begun := 'MARKED';
        EXCEPTION WHEN check_violation THEN r_absent_begun := split_part(SQLERRM, ':', 1); END;
        PERFORM assessment.cbt_mark_absent(s1.id, ca[2], 'not in the hall');
        PERFORM set_config('moaum.actor_id', ca[2]::text, true);
        PERFORM set_config('moaum.actor_office', 'student', true);
        BEGIN PERFORM assessment.cbt_start(ex.id, ca[2], '10.0.0.2', 'check'); r_absent := 'STARTED';
        EXCEPTION WHEN check_violation THEN r_absent := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_id', inv::text, true);
        PERFORM set_config('moaum.actor_office', 'hod', true);
        PERFORM assessment.cbt_clear_mark(s1.id, ca[2]);
        PERFORM set_config('moaum.actor_id', ca[2]::text, true);
        PERFORM set_config('moaum.actor_office', 'student', true);
        BEGIN PERFORM assessment.cbt_start(ex.id, ca[2], '10.0.0.2', 'check'); r_after_clear := 'STARTED';
        EXCEPTION WHEN check_violation THEN r_after_clear := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_id', inv::text, true);
        PERFORM set_config('moaum.actor_office', 'hod', true);
        rest := assessment.cbt_mark_rest_absent(s1.id, 'did not come');
        SELECT string_agg(b.seat_no || ':' || b.state || coalesce('/' || b.mark, ''), ',' ORDER BY b.seat_no) INTO board FROM assessment.cbt_sitting_board(s1.id) b;
        BEGIN PERFORM assessment.cbt_clear_mark(s1.id, ca[1]); r_kept := 'CLEARED';
        EXCEPTION WHEN check_violation THEN r_kept := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'gst', true);
        INSERT INTO assessment.cbt_seat (exam_id, sitting_id, candidate_id, seat_no, assigned_by) VALUES (ex2.id, s2.id, ca[3], 1, who);
        INSERT INTO assessment.cbt_attendance (sitting_id, candidate_id, exam_id, status, marked_by) VALUES (s2.id, ca[3], ex2.id, 'ABSENT', inv);
        BEGIN PERFORM assessment.cbt_remove_sitting(s2.id); r_remove := 'REMOVED';
        EXCEPTION WHEN check_violation THEN r_remove := split_part(SQLERRM, ':', 1); END;
        RAISE EXCEPTION 'the V374 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V374: a question written waits for moderation and only someone other than its setter approves it; a paper holding one not approved is not ready and the checks name it; a whole-bank paper draws approved questions only; an invigilator is staff, told, never in two sittings at once; past the late-entry limit a candidate starts once admitted, with at most the minutes lost given back; one marked absent does not start; the marks stay on the record; an attempt''s heartbeat is not audited, its other changes are',
        coalesce(st0 = 'PENDING' AND r_ready = 'CBT_NOT_MODERATED' AND checks = '1:NOT_MODERATED,2:NOT_MODERATED' AND r_own = 'CBT_MODERATE_OWN' AND st1 = 'APPROVED'
                 AND r_ready2 = 'READY' AND pool_n = 2 AND v2 = 2 AND st2 = 'PENDING' AND by2 = who AND r_direct = 'CBT_MODERATE_OWN' AND r_note = 'CBT_REASON_REQUIRED'
                 AND st3 = 'RETURNED' AND decisions = 2 AND told = 1 AND r_busy = 'CBT_INVIGILATOR_BUSY' AND r_staff = 'CBT_INVIGILATOR_NOT_STAFF'
                 AND r_late = 'CBT_LATE_ENTRY' AND r_minutes = 'CBT_LATE_MINUTES' AND left1 BETWEEN interval '39 minutes' AND interval '41 minutes'
                 AND r_absent_begun = 'CBT_ABSENT_BEGUN' AND r_absent = 'CBT_MARKED_ABSENT' AND r_after_clear = 'CBT_LATE_ENTRY' AND rest = 2
                 AND board = '1:WRITING/LATE,2:ABSENT/ABSENT,3:ABSENT/ABSENT' AND r_kept = 'CBT_MARK_KEPT' AND r_remove = 'CBT_SITTING_MARKED'
                 AND aud0 >= 1 AND aud1 = aud0 AND aud2 = aud0 + 1, false),
        format('st0=%s ready=%s checks=%s own=%s st1=%s ready2=%s pool=%s | v2=%s st2=%s by=%s direct=%s note=%s st3=%s decisions=%s | told=%s busy=%s staff=%s | late=%s minutes=%s left=%s begun=%s absent=%s cleared=%s rest=%s board=%s kept=%s remove=%s | audit %s/%s/%s',
               st0, r_ready, checks, r_own, st1, r_ready2, pool_n, v2, st2, by2 = who, r_direct, r_note, st3, decisions, told, r_busy, r_staff,
               r_late, r_minutes, left1, r_absent_begun, r_absent, r_after_clear, rest, board, r_kept, r_remove, aud0, aud1, aud2));
END $$;

-- ── V375: candidates checked in at the door; the sitting report and its incidents; moderation told and decided by sample ──
DO $$
DECLARE who uuid := gen_random_uuid(); inv uuid := gen_random_uuid(); setter uuid := gen_random_uuid(); mod uuid := gen_random_uuid();
        off uuid := gen_random_uuid(); pa text := 'C00023'; S text := '9959/9960'; ex assessment.cbt_exam; s1 assessment.cbt_sitting;
        q1 uuid := gen_random_uuid(); q2 uuid := gen_random_uuid();
        ca uuid[] := ARRAY[gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid()]; i int; reg uuid;
        a1 assessment.cbt_attempt; a3 assessment.cbt_attempt; a4 assessment.cbt_attempt; m assessment.cbt_attendance;
        r_unchecked text; r_late text; first_at timestamptz; again_at timestamptz; r_absent text; method3 text; board text; absent_in timestamptz;
        r_running text; r_who text; r_twice text; rep assessment.cbt_sitting_report; inc_attempt uuid; after boolean;
        bq uuid[] := '{}'; told int; told_again int; noticed int; r_size text; r_open text; r_unfinished text;
        smp assessment.question_moderation_sample; closed assessment.question_moderation_sample; failed assessment.question_moderation_sample; rest_note text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'gst', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9959-10-01', date '9960-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state)
        SELECT 'GST 959', 'Check check-in, reports, sampling', 2, 1, 100, p.dept_code, 'GST', 'LIVE' FROM ref.programme p WHERE p.code = pa;
        INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES ('GST 959', pa, 100, 'GST');
        INSERT INTO catalogue.offering (id, course_code, session, semester) VALUES (off, 'GST 959', S, 1);
        INSERT INTO iam.person (id, staff_number, surname, given_names, email) VALUES
            (inv, 'CHECK/V375/I', 'ZZINV375', 'Invented', NULL), (setter, 'CHECK/V375/S', 'ZZSET375', 'Invented', 'setter375@example.invalid'),
            (mod, 'CHECK/V375/M', 'ZZMOD375', 'Invented', NULL);
        INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from, valid_to)
        VALUES (gen_random_uuid(), inv, 'hod', 'department', 'MTC', 'check', gen_random_uuid(), current_date, NULL);
        INSERT INTO assessment.question (id, course_code, stem, options, answer, kind, marks) VALUES (q1, 'GST 959', 'V375 one', '["a","b"]', 0, 'MCQ', 1), (q2, 'GST 959', 'V375 two', '["a","b"]', 1, 'MCQ', 1);
        PERFORM pg_temp.moderated();
        ex := assessment.cbt_new_exam('GST', off, 'V375 hall', NULL, 30, 0, 'FIXED', false, false, 50, 1, 'STANDARD', 'REMOTE', 1, 'WARN', 'CONTINUE', now() - interval '20 minutes', now() + interval '3 hours');
        INSERT INTO assessment.cbt_exam_question (exam_id, question_id, ordinal) VALUES (ex.id, q1, 1), (ex.id, q2, 2);
        FOR i IN 1..4 LOOP
            INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
            VALUES (ca[i], 'MOAUM/ADM/59/' || lpad(i::text, 6, '0'), 'MOAUM/CHK/59/' || i, 'ZZV375', 'Seat ' || i, pa, 'UTME', S, 100, 100, 'ACTIVE', now());
            reg := registration.student_draft(ca[i], S, 1);
            PERFORM registration.student_choose(reg, ARRAY[off]);
            UPDATE registration.course_registration SET status = 'SUBMITTED', submitted_at = now() WHERE id = reg;
        END LOOP;
        PERFORM assessment.cbt_exam_action(ex.id, 'publish', NULL);
        s1 := assessment.cbt_add_sitting(ex.id, 'Hall 1', 'CBT Lab D', now() - interval '10 minutes', now() + interval '50 minutes', 4);
        PERFORM assessment.cbt_seat_all(ex.id, 'NUMBER');
        PERFORM assessment.cbt_assign_invigilator(s1.id, inv, true);
        PERFORM assessment.cbt_set_check_in_required(ex.id, true);
        PERFORM assessment.cbt_set_late_entry(ex.id, 5);

        -- (1) check-in: required, so an unchecked candidate does not start; checked in after the limit, admitted late; at the door in time, not late
        PERFORM set_config('moaum.actor_id', ca[1]::text, true);
        PERFORM set_config('moaum.actor_office', 'student', true);
        BEGIN PERFORM assessment.cbt_start(ex.id, ca[1], '10.0.0.1', 'check'); r_unchecked := 'STARTED';
        EXCEPTION WHEN check_violation THEN r_unchecked := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_id', inv::text, true);
        PERFORM set_config('moaum.actor_office', 'hod', true);
        m := assessment.cbt_check_in(s1.id, ca[1], 'SCAN');
        first_at := m.checked_in_at;
        m := assessment.cbt_check_in(s1.id, ca[1], 'SCAN');
        again_at := m.checked_in_at;
        PERFORM set_config('moaum.actor_id', ca[1]::text, true);
        PERFORM set_config('moaum.actor_office', 'student', true);
        BEGIN PERFORM assessment.cbt_start(ex.id, ca[1], '10.0.0.1', 'check'); r_late := 'STARTED';
        EXCEPTION WHEN check_violation THEN r_late := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_id', inv::text, true);
        PERFORM set_config('moaum.actor_office', 'hod', true);
        PERFORM assessment.cbt_admit_late(s1.id, ca[1], 5, 'checked in after the limit');
        PERFORM assessment.cbt_mark_absent(s1.id, ca[2], 'not in the hall');
        BEGIN PERFORM assessment.cbt_check_in(s1.id, ca[2], 'SCAN'); r_absent := 'CHECKED_IN';
        EXCEPTION WHEN check_violation THEN r_absent := split_part(SQLERRM, ':', 1); END;
        PERFORM assessment.cbt_admit_late(s1.id, ca[3], 0, 'no slip; identity checked');
        SELECT check_method INTO method3 FROM assessment.cbt_attendance WHERE sitting_id = s1.id AND candidate_id = ca[3];
        -- the fourth was at the door within the five minutes
        PERFORM assessment.cbt_check_in(s1.id, ca[4], 'MANUAL');
        UPDATE assessment.cbt_attendance SET checked_in_at = s1.starts_at + interval '2 minutes' WHERE sitting_id = s1.id AND candidate_id = ca[4];
        PERFORM set_config('moaum.actor_office', 'student', true);
        PERFORM set_config('moaum.actor_id', ca[1]::text, true);
        a1 := assessment.cbt_start(ex.id, ca[1], '10.0.0.1', 'check');
        PERFORM set_config('moaum.actor_id', ca[3]::text, true);
        a3 := assessment.cbt_start(ex.id, ca[3], '10.0.0.3', 'check');
        PERFORM set_config('moaum.actor_id', ca[4]::text, true);
        a4 := assessment.cbt_start(ex.id, ca[4], '10.0.0.4', 'check');
        SELECT string_agg(b.seat_no || ':' || b.state || '/' || coalesce(b.check_method, '-'), ',' ORDER BY b.seat_no) INTO board FROM assessment.cbt_sitting_board(s1.id) b;

        -- (2) the sitting report: incidents as they happen; filed once nobody is writing; filed once; added to, never rewritten
        PERFORM set_config('moaum.actor_id', inv::text, true);
        PERFORM set_config('moaum.actor_office', 'hod', true);
        PERFORM assessment.cbt_record_incident(s1.id, NULL, 'power', 'the generator failed; candidates waited', 5, now() - interval '5 minutes');
        SELECT x.attempt_id INTO inc_attempt FROM assessment.cbt_record_incident(s1.id, ca[1], 'MALPRACTICE', 'a phone under the desk', NULL, NULL) x;
        BEGIN PERFORM assessment.cbt_file_sitting_report(s1.id, s1.starts_at, now(), ARRAY[inv], 'went well'); r_running := 'FILED';
        EXCEPTION WHEN check_violation THEN r_running := split_part(SQLERRM, ':', 1); END;
        PERFORM assessment.cbt_finalize(a1.id, 'SUBMITTED', NULL);
        PERFORM assessment.cbt_finalize(a3.id, 'SUBMITTED', NULL);
        PERFORM assessment.cbt_finalize(a4.id, 'SUBMITTED', NULL);
        BEGIN PERFORM assessment.cbt_file_sitting_report(s1.id, s1.starts_at, now(), ARRAY[inv, setter], NULL); r_who := 'FILED';
        EXCEPTION WHEN check_violation THEN r_who := split_part(SQLERRM, ':', 1); END;
        rep := assessment.cbt_file_sitting_report(s1.id, s1.starts_at + interval '3 minutes', now(), ARRAY[inv], 'five minutes lost to the generator');
        BEGIN PERFORM assessment.cbt_file_sitting_report(s1.id, s1.starts_at, now(), ARRAY[inv], NULL); r_twice := 'FILED';
        EXCEPTION WHEN check_violation THEN r_twice := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'gst', true);
        rep := assessment.cbt_sitting_report_addendum(s1.id, 'the malpractice case went to the committee');
        SELECT x.after_filing INTO after FROM assessment.cbt_record_incident(s1.id, ca[1], 'OTHER', 'a further statement taken', NULL, NULL) x;
        PERFORM assessment.cbt_mark_absent(s1.id, ca[2], 'confirmed');
        SELECT checked_in_at INTO absent_in FROM assessment.cbt_attendance WHERE sitting_id = s1.id AND candidate_id = ca[2];

        -- (3) moderation: the setter told once, per bank, with no question in the notice; a sample decided
        PERFORM set_config('moaum.actor_id', setter::text, true);
        PERFORM set_config('moaum.actor_office', 'gst', true);
        FOR i IN 1..6 LOOP
            bq := bq || gen_random_uuid();
            INSERT INTO assessment.question (id, course_code, stem, options, answer, kind, marks, authored_by) VALUES (bq[i], 'GST 959', 'V375 bank ' || i, '["a","b"]', 0, 'MCQ', 1, setter);
        END LOOP;
        PERFORM set_config('moaum.actor_id', mod::text, true);
        PERFORM assessment.question_moderate(bq[1], 'approve', NULL);
        PERFORM assessment.question_moderate(bq[2], 'return', 'the stem is ambiguous');
        told := assessment.notify_moderation(interval '0');
        told_again := assessment.notify_moderation(interval '0');
        SELECT count(*) INTO noticed FROM platform.notice n WHERE n.about_kind = 'person' AND n.about_id = setter AND n.body LIKE '%1 approved and 1 returned%' AND n.body NOT LIKE '%V375 bank%' AND n.body NOT LIKE '%ambiguous%';
        BEGIN PERFORM assessment.question_sample_draw('GST 959', NULL, 5); r_size := 'DRAWN';
        EXCEPTION WHEN check_violation THEN r_size := split_part(SQLERRM, ':', 1); END;
        smp := assessment.question_sample_draw('GST 959', NULL, 2);
        BEGIN PERFORM assessment.question_sample_draw('GST 959', NULL, 1); r_open := 'DRAWN';
        EXCEPTION WHEN check_violation THEN r_open := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM assessment.question_sample_close(smp.id); r_unfinished := 'CLOSED';
        EXCEPTION WHEN check_violation THEN r_unfinished := split_part(SQLERRM, ':', 1); END;
        PERFORM assessment.question_moderate(smp.sample[1], 'approve', NULL);
        PERFORM assessment.question_moderate(smp.sample[2], 'approve', NULL);
        closed := assessment.question_sample_close(smp.id);
        SELECT string_agg(DISTINCT q.moderation_note, '|') INTO rest_note FROM assessment.question q WHERE q.id = ANY (smp.population) AND NOT (q.id = ANY (smp.sample));
        -- a sample with a question returned fails; the rest wait
        PERFORM set_config('moaum.actor_id', setter::text, true);
        bq := ARRAY[gen_random_uuid(), gen_random_uuid()];
        INSERT INTO assessment.question (id, course_code, stem, options, answer, kind, marks, authored_by) VALUES (bq[1], 'GST 959', 'V375 more 1', '["a","b"]', 0, 'MCQ', 1, setter),
                                                                                                       (bq[2], 'GST 959', 'V375 more 2', '["a","b"]', 0, 'MCQ', 1, setter);
        PERFORM set_config('moaum.actor_id', mod::text, true);
        failed := assessment.question_sample_draw('GST 959', NULL, 1);
        PERFORM assessment.question_moderate(failed.sample[1], 'return', 'not clear');
        failed := assessment.question_sample_close(failed.id);
        RAISE EXCEPTION 'the V375 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V375: where the office requires it a candidate starts once checked in; a check-in is once, never of a candidate marked absent, an admission is one, and a candidate at the door within the late-entry limit is not late; a sitting''s report is filed once nobody is writing, names only its invigilators, is filed once and added to; a setter is told per bank with no question in the notice; a sample approves the rest when every sampled question is approved, and fails when one is returned',
        coalesce(r_unchecked = 'CBT_NOT_CHECKED_IN' AND first_at IS NOT NULL AND again_at = first_at AND r_late = 'CBT_LATE_ENTRY' AND r_absent = 'CBT_CHECK_IN_ABSENT'
                 AND method3 = 'ADMITTED' AND board = '1:WRITING/SCAN,2:ABSENT/-,3:WRITING/ADMITTED,4:WRITING/MANUAL'
                 AND inc_attempt = a1.id AND r_running = 'CBT_SITTING_RUNNING' AND r_who = 'CBT_REPORT_INVIGILATORS' AND r_twice = 'CBT_REPORT_FILED'
                 AND (rep.counts->>'seated')::int = 4 AND (rep.counts->>'checked_in')::int = 3 AND (rep.counts->>'absent')::int = 1 AND (rep.counts->>'incidents')::int = 2
                 AND (rep.counts->>'minutes_lost')::int = 5 AND (rep.counts->>'submitted')::int = 3 AND rep.addendum LIKE '%went to the committee%' AND after AND absent_in IS NULL
                 AND told >= 1 AND told_again = 0 AND noticed = 1 AND r_size = 'CBT_SAMPLE_SIZE' AND r_open = 'CBT_SAMPLE_OPEN' AND r_unfinished = 'CBT_SAMPLE_UNFINISHED'
                 AND cardinality(smp.population) = 4 AND closed.state = 'APPROVED' AND closed.approved = 2 AND closed.left_as_they_were = 0 AND rest_note LIKE 'Approved by sample: 2 of 4%'
                 AND failed.state = 'FAILED' AND failed.left_as_they_were = 1, false),
        format('unchecked=%s in=%s/%s late=%s absent=%s m3=%s board=%s | incident=%s running=%s who=%s twice=%s counts=%s addendum=%s after=%s absent_in=%s | told=%s/%s noticed=%s size=%s open=%s unfinished=%s pop=%s closed=%s/%s/%s note=%s failed=%s/%s',
               r_unchecked, first_at IS NOT NULL, again_at = first_at, r_late, r_absent, method3, board, inc_attempt = a1.id, r_running, r_who, r_twice, rep.counts,
               rep.addendum IS NOT NULL, after, absent_in, told, told_again, noticed, r_size, r_open, r_unfinished, cardinality(smp.population),
               closed.state, closed.approved, closed.left_as_they_were, rest_note, failed.state, failed.left_as_they_were));
END $$;

-- ── V376: images in questions, frozen with the version; time back after an incident; never two sittings at once ──
DO $$
DECLARE who uuid := gen_random_uuid(); off uuid := gen_random_uuid(); pa text := 'C00023'; S text := '9957/9958';
        q uuid := gen_random_uuid(); img1 uuid := gen_random_uuid(); img2 uuid := gen_random_uuid(); img3 uuid := gen_random_uuid();
        ca uuid[] := ARRAY[gen_random_uuid(), gen_random_uuid(), gen_random_uuid()]; i int; reg uuid;
        ex assessment.cbt_exam; ex2 assessment.cbt_exam; ex3 assessment.cbt_exam; s1 assessment.cbt_sitting; s2 assessment.cbt_sitting; s3 assessment.cbt_sitting;
        sh assessment.cbt_sitting; v_ver int; v_mod text; r_mismatch text; a1 assessment.cbt_attempt; a2 assessment.cbt_attempt; a3 assessment.cbt_attempt;
        paper_img uuid; opt_img text; shows boolean; shows_other boolean; inc assessment.cbt_sitting_incident; ends_before timestamptz; ends_after timestamptz;
        extra_reason text; r_twice text; r_clash text; seat2 record; clashes int; ca2_sitting text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'gst', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9957-10-01', date '9958-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state)
        SELECT 'GST 957', 'Check images, time back, clashes', 2, 1, 100, p.dept_code, 'GST', 'LIVE' FROM ref.programme p WHERE p.code = pa;
        INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES ('GST 957', pa, 100, 'GST');
        INSERT INTO catalogue.offering (id, course_code, session, semester) VALUES (off, 'GST 957', S, 1);

        -- (1) a diagram for the question and an image for option B: each a new version, waiting for moderation again
        INSERT INTO assessment.question_image (id, filename, content_type, size_bytes) VALUES
            (img1, 'circuit.png', 'image/png', 100), (img2, 'graph-b.png', 'image/png', 100), (img3, 'circuit-2.png', 'image/png', 100);
        INSERT INTO assessment.question (id, course_code, stem, options, answer, kind, marks) VALUES (q, 'GST 957', 'V376 the current in $R_1$ is', '["1 A","2 A","3 A"]', 1, 'MCQ', 1);
        UPDATE assessment.question SET image_id = img1 WHERE id = q;
        UPDATE assessment.question SET option_images = ARRAY[NULL, img2, NULL]::uuid[] WHERE id = q;
        SELECT version, moderation INTO v_ver, v_mod FROM assessment.question WHERE id = q;
        BEGIN UPDATE assessment.question SET option_images = ARRAY[img2]::uuid[] WHERE id = q; r_mismatch := 'SET';
        EXCEPTION WHEN check_violation THEN r_mismatch := 'REFUSED'; END;
        PERFORM pg_temp.moderated();
        ex := assessment.cbt_new_exam('GST', off, 'V376 hall', NULL, 30, 0, 'FIXED', false, false, 50, 1, 'STANDARD', 'REMOTE', 1, 'WARN', 'CONTINUE', now() - interval '1 hour', now() + interval '6 hours');
        INSERT INTO assessment.cbt_exam_question (exam_id, question_id, ordinal) VALUES (ex.id, q, 1);
        FOR i IN 1..3 LOOP
            INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
            VALUES (ca[i], 'MOAUM/ADM/57/' || lpad(i::text, 6, '0'), 'MOAUM/CHK/57/' || i, 'ZZV376', 'Seat ' || i, pa, 'UTME', S, 100, 100, 'ACTIVE', now());
            reg := registration.student_draft(ca[i], S, 1);
            PERFORM registration.student_choose(reg, ARRAY[off]);
            UPDATE registration.course_registration SET status = 'SUBMITTED', submitted_at = now() WHERE id = reg;
        END LOOP;
        PERFORM assessment.cbt_exam_action(ex.id, 'publish', NULL);
        sh := assessment.cbt_add_sitting(ex.id, 'Hall', 'CBT Lab E', now() - interval '30 minutes', now() + interval '60 minutes', 10);
        PERFORM assessment.cbt_seat_all(ex.id, 'NUMBER');
        PERFORM set_config('moaum.actor_office', 'student', true);
        FOR i IN 1..3 LOOP
            PERFORM set_config('moaum.actor_id', ca[i]::text, true);
            IF i = 1 THEN a1 := assessment.cbt_start(ex.id, ca[i], '10.0.0.1', 'check'); END IF;
            IF i = 2 THEN a2 := assessment.cbt_start(ex.id, ca[i], '10.0.0.2', 'check'); END IF;
            IF i = 3 THEN a3 := assessment.cbt_start(ex.id, ca[i], '10.0.0.3', 'check'); END IF;
        END LOOP;
        SELECT p.image, (SELECT string_agg(o->>'i' || '=' || coalesce(o->>'image', '-'), ',' ORDER BY (o->>'i')::int) FROM jsonb_array_elements(p.options) o)
          INTO paper_img, opt_img FROM assessment.cbt_candidate_paper(a1.id) p;
        -- the bank's diagram replaced after the attempt began: the attempt keeps the one it drew
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'gst', true);
        UPDATE assessment.question SET image_id = img3 WHERE id = q;
        shows := assessment.cbt_attempt_shows_image(a1.id, img1) AND assessment.cbt_attempt_shows_image(a1.id, img2);
        shows_other := assessment.cbt_attempt_shows_image(a1.id, img3);

        -- (2) time back: a power cut five minutes ago; the first two were writing then, the second has finished since, the third started after
        UPDATE assessment.cbt_attempt SET started_at = now() - interval '10 minutes' WHERE id IN (a1.id, a2.id);
        PERFORM assessment.cbt_finalize(a2.id, 'SUBMITTED', NULL);
        PERFORM assessment.cbt_grant_extra_time(ex.id, ca[1], 15, 'a candidate with a visual impairment');
        SELECT ends_at INTO ends_before FROM assessment.cbt_attempt WHERE id = a1.id;
        inc := assessment.cbt_record_incident(sh.id, NULL, 'POWER', 'the mains failed', 7, now() - interval '5 minutes');
        inc := assessment.cbt_give_time_back(inc.id, 7);
        SELECT ends_at INTO ends_after FROM assessment.cbt_attempt WHERE id = a1.id;
        SELECT reason INTO extra_reason FROM assessment.cbt_extra_time WHERE exam_id = ex.id AND candidate_id = ca[1];
        BEGIN PERFORM assessment.cbt_give_time_back(inc.id, 7); r_twice := 'GIVEN';
        EXCEPTION WHEN check_violation THEN r_twice := split_part(SQLERRM, ':', 1); END;

        -- (3) clashes: the first candidate sits a third examination at four hours; another examination's sitting at the same time refuses them,
        --     and seating everyone passes them over; a sitting moved onto that time afterwards is listed as a clash
        ex3 := assessment.cbt_new_exam('GST', off, 'V376 first', NULL, 30, 0, 'FIXED', false, false, 50, 1, 'STANDARD', 'REMOTE', 1, 'WARN', 'CONTINUE', now() - interval '1 hour', now() + interval '6 hours');
        s1 := assessment.cbt_add_sitting(ex3.id, 'At four', 'CBT Lab G', now() + interval '4 hours', now() + interval '5 hours', 1);
        PERFORM assessment.cbt_seat_all(ex3.id, 'NUMBER');
        ex2 := assessment.cbt_new_exam('GST', off, 'V376 other', NULL, 30, 0, 'FIXED', false, false, 50, 1, 'STANDARD', 'REMOTE', 1, 'WARN', 'CONTINUE', now() - interval '1 hour', now() + interval '6 hours');
        s2 := assessment.cbt_add_sitting(ex2.id, 'Same time', 'CBT Lab F', now() + interval '4 hours 15 minutes', now() + interval '5 hours', 2);
        BEGIN PERFORM assessment.cbt_seat_candidate(ex2.id, ca[1], s2.id); r_clash := 'SEATED';
        EXCEPTION WHEN check_violation THEN r_clash := split_part(SQLERRM, ':', 1); END;
        SELECT * INTO seat2 FROM assessment.cbt_seat_all(ex2.id, 'NUMBER');
        s3 := assessment.cbt_add_sitting(ex2.id, 'Later', 'CBT Lab F', now() + interval '5 hours 10 minutes', now() + interval '5 hours 50 minutes', 5);
        PERFORM assessment.cbt_seat_candidate(ex2.id, ca[1], s3.id);
        PERFORM assessment.cbt_update_sitting(s3.id, 'Later', 'CBT Lab F', now() + interval '4 hours', now() + interval '4 hours 40 minutes', 5);
        SELECT count(*) INTO clashes FROM assessment.cbt_seat_clashes(ex2.id) c WHERE c.candidate_id = ca[1];
        RAISE EXCEPTION 'the V376 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V376: a question''s diagram and its options'' images are content — each change a new version waiting for moderation, the options matched one for one — and an attempt shows the images of the version it drew; time lost to an incident goes back once, to those writing then and still writing, on their extra time with the incident named; a candidate is never seated in two sittings at the same time, and a clash made later is listed',
        coalesce(v_ver = 3 AND v_mod = 'PENDING' AND r_mismatch = 'REFUSED' AND paper_img = img1 AND opt_img = '0=-,1=' || img2 || ',2=-' AND shows AND NOT shows_other
                 AND inc.time_given_to = 1 AND inc.time_given_minutes = 7 AND ends_after - ends_before BETWEEN interval '6 minutes 59 seconds' AND interval '7 minutes 1 second'
                 AND extra_reason LIKE 'a candidate with a visual impairment; 7 minutes given back for the power cut at %' AND r_twice = 'CBT_TIME_GIVEN'
                 AND r_clash = 'CBT_SEAT_CLASH' AND seat2.seated = 2 AND seat2.clashed = 1 AND clashes = 1, false),
        format('v=%s mod=%s mismatch=%s paper=%s opts=%s shows=%s other=%s | given to %s (%s min) moved %s reason=%s twice=%s | clash=%s seat_all=%s/%s/%s listed=%s',
               v_ver, v_mod, r_mismatch, paper_img = img1, opt_img, shows, shows_other, inc.time_given_to, inc.time_given_minutes, ends_after - ends_before,
               extra_reason, r_twice, r_clash, seat2.seated, seat2.unseated, seat2.clashed, clashes));
END $$;

-- ── V379: CCE — the route's own session, JAMB's list read and reconciled, a listed person applies, the Centre reviews, the Academic Office publishes, a part-time student in the CCE session ──
DO $$
DECLARE acad uuid := gen_random_uuid(); cce1 uuid := gen_random_uuid(); cce2 uuid := gen_random_uuid(); burs uuid := gen_random_uuid();
        S text := '9953/9954'; pa text := 'C00023'; v_session text; r_reason text; r_office text; b1 uuid; b2 uuid; cnt jsonb; cnt2 jsonb; applied jsonb;
        r_dup text; r_nodob text; r_prog text; look text; look_bad text; acct uuid; app uuid; r_again text; r_dob text; r_sit2 text; probs int;
        ref1 text; amount1 numeric; r_submit text; r_own text; r_pub_office text; pub jsonb; vis boolean; st_status text; ref2 text; amount2 numeric;
        stu people.student; ctx_session text; gate text; r_guard text; r_chk text; letter credentials.issued; stats jsonb; doc uuid; ugs text;
        fee_total numeric; old_stated boolean; ref_chk text; amount_chk numeric; r_closed text; st_closed text; st_fee text; vis_before boolean;
BEGIN
    BEGIN
        PERFORM set_config('moaum.reason', 'check V379', true);
        PERFORM set_config('moaum.actor_id', acad::text, true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9953-10-01', date '9954-08-31') ON CONFLICT (name) DO NOTHING;

        -- (1) the session: one behind undergraduate by default; a named session needs its reason and the Academic Office
        PERFORM set_config('moaum.actor_id', acad::text, true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        ugs := policy.university_current_session();
        v_session := policy.route_session('CCE');
        BEGIN PERFORM policy.set_route_session('CCE', -1, S, NULL, NULL); r_reason := 'SET';
        EXCEPTION WHEN check_violation THEN r_reason := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_office', 'cce', true);
        BEGIN PERFORM policy.set_route_session('CCE', -1, S, 'the check', NULL); r_office := 'SET';
        EXCEPTION WHEN check_violation THEN r_office := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_office', 'academic', true);
        PERFORM policy.set_route_session('CCE', -1, S, 'the check runs in a session of its own', NULL);
        PERFORM ref.set_programme_route(pa, 'CCE', true, NULL, NULL, 'the check');

        -- (2) the list read: one new, the same number again, one with no date of birth, one in a programme the Centre does not offer
        b1 := admissions.cce_preview(S, 'cce-list.xlsx', repeat('a', 64), jsonb_build_array(
            jsonb_build_object('jamb_reg_no', '99530000001CC', 'surname', 'Tersoo', 'first_name', 'Mimi', 'middle_name', 'Ngodoo', 'date_of_birth', '17/04/1990',
                               'sex', 'Female', 'phone', '+234 803 555 0101', 'email', 'mimi@example.com', 'programme_code', pa, 'admission_session', S, 'study_mode', 'Part Time'),
            jsonb_build_object('jamb_reg_no', '99530000001CC', 'surname', 'Tersoo', 'first_name', 'Mimi', 'date_of_birth', '1990-04-17', 'programme_code', pa),
            jsonb_build_object('jamb_reg_no', '99530000002CC', 'surname', 'Adeyi', 'first_name', 'Peter', 'programme_code', pa),
            jsonb_build_object('jamb_reg_no', '99530000003CC', 'surname', 'Ochai', 'first_name', 'Grace', 'date_of_birth', '32874',
                               'programme_code', (SELECT code FROM ref.programme WHERE category = 'UNDER GRADUATE' AND NOT archived AND code <> pa ORDER BY code LIMIT 1))));
        SELECT counts INTO cnt FROM admissions.cce_batch WHERE id = b1;
        SELECT classification INTO r_dup FROM admissions.cce_batch_row WHERE batch_id = b1 AND row_no = 2;
        SELECT classification INTO r_nodob FROM admissions.cce_batch_row WHERE batch_id = b1 AND row_no = 3;
        SELECT classification INTO r_prog FROM admissions.cce_batch_row WHERE batch_id = b1 AND row_no = 4;
        applied := admissions.cce_commit(b1);
        -- the list again, the phone changed: UPDATED, matched by number
        b2 := admissions.cce_preview(S, 'cce-list-2.xlsx', repeat('b', 64), jsonb_build_array(
            jsonb_build_object('jamb_reg_no', '99530000001cc', 'surname', 'Tersoo', 'first_name', 'Mimi', 'middle_name', 'Ngodoo', 'date_of_birth', '17/04/1990',
                               'sex', 'F', 'phone', '08035550199', 'email', 'mimi@example.com', 'programme_code', pa)));
        SELECT counts INTO cnt2 FROM admissions.cce_batch WHERE id = b2;
        PERFORM admissions.cce_commit(b2);

        -- (3) the listed person applies: the JAMB number with the wrong date reads as not listed; the window is the Director of ICT's
        SELECT state INTO look_bad FROM admissions.cce_lookup('99530000001CC', date '1990-04-18');
        PERFORM policy.window_act('CCE_APPLICATION', S, NULL, 'OPEN', NULL, NULL, NULL, NULL, NULL, acad, 'ict');
        SELECT state INTO look FROM admissions.cce_lookup('99530000001CC', date '1990-04-17');
        acct := admissions.cce_register('99530000001CC', date '1990-04-17', 'mimi.tersoo@example.com', '08035550199', '$2a$12$' || repeat('x', 53));
        SELECT id INTO app FROM admissions.application WHERE account_id = acct;
        BEGIN PERFORM admissions.cce_register('99530000001CC', date '1990-04-17', 'other@example.com', '08035550199', '$2a$12$' || repeat('x', 53)); r_again := 'REGISTERED TWICE';
        EXCEPTION WHEN check_violation THEN r_again := split_part(SQLERRM, ':', 1); END;

        -- (4) the Bursary states the CCE fees (V404: the admission checking fee among them); the application fee is paid first
        PERFORM set_config('moaum.actor_id', burs::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM admissions.set_route_fee(S, 'CCE', 7000, 500, 30000, 2500);
        ref1 := admissions.new_fee_reference(app, 'APPLICATION');
        SELECT amount INTO amount1 FROM admissions.fee_reference WHERE reference = ref1;
        BEGIN PERFORM admissions.new_fee_reference(app, 'CHECKING'); r_chk := 'ISSUED';
        EXCEPTION WHEN check_violation THEN r_chk := split_part(SQLERRM, ':', 1); END;
        PERFORM admissions.confirm_fee(ref1, 'BANK', 'check');
        PERFORM set_config('moaum.actor_id', acct::text, true);
        PERFORM set_config('moaum.actor_office', 'applicant', true);

        -- (5) the form: the date of birth is the list's; a second sitting is complete or not given
        BEGIN PERFORM admissions.cce_save_biodata(app, '{"date_of_birth": "1991-01-01"}'); r_dob := 'SAVED';
        EXCEPTION WHEN check_violation THEN r_dob := split_part(SQLERRM, ':', 1); END;
        PERFORM admissions.cce_save_biodata(app, '{"date_of_birth": "17/04/1990", "home_address": "12 Gboko Road, Makurdi", "state_of_origin": "Benue", "lga": "Makurdi",
                                                  "nationality": "Nigeria", "mobile": "08035550199", "kin_name": "Aondona Tersoo", "kin_relationship": "Brother", "kin_mobile": "08035550111"}');
        BEGIN PERFORM admissions.cce_save_olevel(app, '[{"sitting": 1, "exam_body": "WAEC", "exam_number": "4250101001", "exam_year": "2008", "subjects": [{"subject": "English Language", "grade": "C5"}]},
                                                        {"sitting": 2, "exam_body": "NECO", "exam_number": "", "exam_year": "2009", "subjects": []}]'); r_sit2 := 'SAVED';
        EXCEPTION WHEN check_violation THEN r_sit2 := split_part(SQLERRM, ':', 1); END;
        PERFORM admissions.cce_save_olevel(app, '[{"sitting": 1, "exam_body": "WAEC", "exam_number": "4250101001", "exam_year": "2008", "subjects": [
                                                    {"subject": "English Language", "grade": "C5"}, {"subject": "Biology", "grade": "B3"}, {"subject": "Economics", "grade": "C6"}]},
                                                  {"sitting": 2, "exam_body": "NECO", "exam_number": "1003200456", "exam_year": "2009", "subjects": [
                                                    {"subject": "Mathematics", "grade": "C4"}, {"subject": "Physics", "grade": "C6"}, {"subject": "Chemistry", "grade": "B2"}]}]');
        PERFORM admissions.cce_confirm_programme(app);
        SELECT count(*) INTO probs FROM admissions.cce_application_problems(app);   -- the passport, each sitting's result, the birth certificate, the certificate of state of origin
        INSERT INTO admissions.application_document (id, application_id, kind, filename, content_type, bytes)
        VALUES (gen_random_uuid(), app, 'PASSPORT', 'passport.jpg', 'image/jpeg', 1000), (gen_random_uuid(), app, 'OLEVEL_STATEMENT', 'waec.pdf', 'application/pdf', 1000),
               (gen_random_uuid(), app, 'OLEVEL_STATEMENT_2', 'neco.pdf', 'application/pdf', 1000), (gen_random_uuid(), app, 'BIRTH_CERT', 'birth.pdf', 'application/pdf', 1000),
               (gen_random_uuid(), app, 'STATE_OF_ORIGIN', 'origin.pdf', 'application/pdf', 1000);
        r_submit := admissions.cce_submit(app, '127.0.0.1');
        -- submitted, not yet published: checking is closed to the applicant (V404)
        SELECT status INTO st_closed FROM admissions.admission_status(app);
        BEGIN PERFORM admissions.new_fee_reference(app, 'CHECKING'); r_closed := 'ISSUED';
        EXCEPTION WHEN check_violation THEN r_closed := split_part(SQLERRM, ':', 1); END;

        -- (6) the Centre reviews: documents verified, recommended by one officer, approved by another; the Academic Office publishes
        PERFORM set_config('moaum.actor_id', cce1::text, true);
        PERFORM set_config('moaum.actor_office', 'cce', true);
        PERFORM admissions.cce_act(app, 'START', NULL);
        FOR doc IN SELECT id FROM admissions.application_document WHERE application_id = app LOOP PERFORM admissions.cce_review_document(doc, 'ACCEPTED', NULL); END LOOP;
        PERFORM admissions.cce_act(app, 'RECOMMEND', 'Credits in English and Mathematics over two sittings');
        BEGIN PERFORM admissions.cce_act(app, 'APPROVE', NULL); r_own := 'APPROVED';
        EXCEPTION WHEN check_violation THEN r_own := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM admissions.cce_publish(S, NULL); r_pub_office := 'PUBLISHED';
        EXCEPTION WHEN check_violation THEN r_pub_office := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_id', acad::text, true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        PERFORM admissions.cce_act(app, 'APPROVE', NULL);
        pub := admissions.cce_publish(S, NULL);

        -- (7) published: the applicant pays the CCE admission checking fee (V404), reads the outcome, accepts and pays the CCE
        -- acceptance fee: on the register
        SELECT decision_visible INTO vis_before FROM admissions.status_checking(app);
        SELECT status INTO st_fee FROM admissions.admission_status(app);
        PERFORM set_config('moaum.actor_id', acct::text, true);
        PERFORM set_config('moaum.actor_office', 'applicant', true);
        ref_chk := admissions.new_fee_reference(app, 'CHECKING');
        SELECT amount INTO amount_chk FROM admissions.fee_reference WHERE reference = ref_chk;
        PERFORM set_config('moaum.actor_id', burs::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM admissions.confirm_fee(ref_chk, 'BANK', 'check');
        SELECT decision_visible INTO vis FROM admissions.status_checking(app);
        SELECT status INTO st_status FROM admissions.admission_status(app);
        PERFORM set_config('moaum.actor_id', acct::text, true);
        PERFORM set_config('moaum.actor_office', 'applicant', true);
        PERFORM admissions.admission_status_checked(app);
        PERFORM admissions.sign_undertaking(app);
        ref2 := admissions.new_fee_reference(app, 'ACCEPTANCE');
        SELECT amount INTO amount2 FROM admissions.fee_reference WHERE reference = ref2;
        PERFORM set_config('moaum.actor_id', burs::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM admissions.confirm_fee(ref2, 'BANK', 'check');
        SELECT s.* INTO stu FROM people.student s JOIN admissions.application a ON a.candidate_id = s.candidate_id WHERE a.id = app;
        SELECT x.session INTO ctx_session FROM people.academic_context(stu.id) x;
        -- (8) the CCE student is charged only what the Bursary states for CCE: the full-time line of the same session never reaches them
        INSERT INTO finance.fee_schedule (session, item, amount, level, entry_mode, ord, spillover, kind) VALUES
            (S, 'School fees (full-time)', 99000, 100, NULL, 1, false, 'FEE'), (S, 'School fees (CCE)', 45000, 100, 'CCE', 1, false, 'FEE');
        fee_total := finance.session_fee_total(stu.id, S);
        old_stated := finance.fee_stated(stu.id, '2001/2002');   -- before the portal's fee schedule: stated for the old portal's students, not for CCE
        gate := registration.registration_gate(stu.id, S, 1);
        PERFORM set_config('moaum.actor_office', 'records', true);
        BEGIN UPDATE people.student SET study_mode = 'FULL_TIME' WHERE id = stu.id; r_guard := 'CHANGED';
        EXCEPTION WHEN check_violation THEN r_guard := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_office', 'registrar', true);
        letter := admissions.issue_admission_letter(app);
        stats := admissions.cce_stats(S);
        RAISE EXCEPTION 'the V379 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V379: CCE — the route''s session follows undergraduate one behind unless the Academic Office names one with its reason; JAMB''s CCE list is read and reconciled by number (new, the same number again, no date of birth, a programme the Centre does not offer, then an update); only a listed number with its date of birth registers, once, while the window is open; a second sitting is complete or absent; the CCE fees are the Bursary''s and the application fee is paid before the form; the officer who recommends does not approve, and the Academic Office publishes; checking stays closed until the outcome is published and the published offer is read once the CCE admission checking fee is paid (V404), accepted, and the student comes onto the register CCE, part-time, in the CCE session, with the CCE letter, course registration waiting for the Centre''s classes, charged only the fees stated for CCE, and the study mode not changed behind the Academic Office',
        coalesce(v_session = policy.session_before(ugs, 1) AND r_reason = 'CCE_SESSION_REASON' AND r_office = 'CCE_SESSION_OFFICE'
                 AND (cnt->>'NEW')::int = 1 AND (cnt->>'DUPLICATE')::int = 1 AND (cnt->>'INVALID')::int = 1 AND (cnt->>'REQUIRES_REVIEW')::int = 1
                 AND r_dup = 'DUPLICATE' AND r_nodob = 'INVALID' AND r_prog = 'REQUIRES_REVIEW' AND (applied->>'added')::int = 1
                 AND (cnt2->>'UPDATED')::int = 1 AND look_bad = 'nomatch' AND look = 'found' AND r_again = 'CCE_REGISTERED'
                 AND r_dob = 'CCE_DATE_OF_BIRTH' AND r_sit2 = 'CCE_OLEVEL_NUMBER' AND probs = 5 AND amount1 = 7500 AND r_chk = 'ADMISSION_CHECKING_NOT_ELIGIBLE'
                 AND st_closed = 'CHECKING_CLOSED' AND r_closed = 'ADMISSION_CHECKING_CLOSED' AND NOT vis_before AND st_fee = 'CHECKING_FEE_PENDING' AND amount_chk = 2500
                 AND r_submit = 'submitted' AND r_own = 'CCE_APPROVE_OWN' AND r_pub_office = 'CCE_OFFICE' AND (pub->>'admitted')::int = 1
                 AND vis AND st_status = 'ADMITTED' AND amount2 = 30000 AND stu.entry_mode = 'CCE' AND stu.study_mode = 'PART_TIME' AND stu.entry_session = S
                 AND stu.date_of_birth = date '1990-04-17' AND ctx_session = S AND gate LIKE 'Course registration for the first semester of ' || S || ' opens when the Centre for Continuing Education''s classes for it are set up.'
                 AND r_guard = 'STUDENT_ROUTE_LOCKED' AND fee_total = 45000 AND NOT old_stated AND letter.statement->>'studyMode' = 'PART-TIME' AND (letter.statement->>'durationYears')::int = 6
                 AND (stats->>'admitted')::int = 1 AND (stats->>'activated')::int = 1, false),
        format('session %s (ug %s) reason=%s office=%s | counts %s dup=%s nodob=%s prog=%s applied=%s again=%s | look %s/%s twice=%s | dob=%s sit2=%s problems=%s | fee %s chk=%s submit=%s | own=%s pub_office=%s pub=%s | closed %s/%s fee-pending %s/%s checking %s | visible=%s status=%s acceptance=%s | student %s %s %s dob=%s ctx=%s gate=%s guard=%s fees=%s old_stated=%s letter=%s/%s | stats %s',
               v_session, ugs, r_reason, r_office, cnt, r_dup, r_nodob, r_prog, applied, cnt2, look_bad, look, r_again, r_dob, r_sit2, probs, amount1, r_chk, r_submit,
               r_own, r_pub_office, pub, st_closed, r_closed, vis_before, st_fee, amount_chk, vis, st_status, amount2, stu.entry_mode, stu.study_mode, stu.entry_session, stu.date_of_birth, ctx_session, gate, r_guard, fee_total, old_stated,
               letter.statement->>'studyMode', letter.statement->>'durationYears', stats));
END $$;

-- ── V383: an Interswitch test reference — payable for the days the Bursar chooses, answered 0 until it is paid or expires ──
-- Issued from the Bursary's desk only, for a small amount, for 1 to 14 days (7 unless said), purpose 'Gateway test by the
-- Bursary' (counts for nothing against the fees). Quickteller is answered from the reference as for every other: Status 0
-- with the name and the amount while it is unpaid and unexpired, Status 1 once it is paid, expired or withdrawn. Every other
-- reference keeps its own expiry. Time cannot pass inside the block, so an expiry is reached by moving it into the past.
-- The block undoes its own writes.
DO $$
DECLARE s uuid := gen_random_uuid(); burs uuid := gen_random_uuid();
        r_test text; r_short text; r_wd text; r_other text; pr finance.payment_reference; t finance.gateway_test_reference; wd finance.payment_reference;
        span_test interval; span_short interval; span_other interval; cat text; cu record; cu_old record; cu_paid record; paid numeric;
        r_days text; r_amount text; r_office text; r_again text; r_paid text; r_not_one text; wd_by uuid;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', burs::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (s, 'MOAUM/ADM/99/990383', 'MOAUM/CHK/99/0383', 'CHECKITR', 'Tester Invented', 'C00023', 'UTME', '9999/0000', 100, 100, 'ACTIVE', now());
        -- seven days unless said; three when the Bursar says three
        r_test := finance.new_gateway_test_reference(s, '9999/0000', 100, NULL);
        r_short := finance.new_gateway_test_reference(s, '9999/0000', 50, 3);
        r_wd := finance.new_gateway_test_reference(s, '9999/0000', 100, 14);
        SELECT expires_at - generated_at INTO span_test FROM finance.payment_reference WHERE reference = r_test;
        SELECT expires_at - generated_at INTO span_short FROM finance.payment_reference WHERE reference = r_short;
        SELECT * INTO pr FROM finance.payment_reference WHERE reference = r_test;
        cat := finance.categorise(NULL, pr.purpose);
        SELECT * INTO t FROM finance.gateway_test_reference WHERE reference = r_test;
        -- any other reference keeps its own 24 hours
        r_other := finance.new_purpose_reference(s, '9999/0000', 500, 'Library fine 9999/0000');
        SELECT expires_at - generated_at INTO span_other FROM finance.payment_reference WHERE reference = r_other;
        -- refused: fifteen days, more than a small amount, another office
        BEGIN PERFORM finance.new_gateway_test_reference(s, '9999/0000', 100, 15); EXCEPTION WHEN check_violation THEN r_days := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM finance.new_gateway_test_reference(s, '9999/0000', 50000, 7); EXCEPTION WHEN check_violation THEN r_amount := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_office', 'academic', true);
        BEGIN PERFORM finance.new_gateway_test_reference(s, '9999/0000', 100, 7); EXCEPTION WHEN check_violation THEN r_office := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_office', 'bursar', true);

        -- Quickteller, while it is open: Status 0 with the name and the amount
        SELECT * INTO cu FROM finance.paydirect_customer(lower(r_test));
        -- three days on: expired, Status 1
        UPDATE finance.payment_reference SET expires_at = now() - interval '1 minute' WHERE reference = r_short;
        SELECT * INTO cu_old FROM finance.paydirect_customer(r_short);
        -- withdrawn: it expires now, once; a payer's own reference is not withdrawn here
        wd := finance.withdraw_gateway_test_reference(lower(r_wd));
        SELECT withdrawn_by INTO wd_by FROM finance.gateway_test_reference WHERE reference = r_wd;
        BEGIN PERFORM finance.withdraw_gateway_test_reference(r_wd); EXCEPTION WHEN check_violation THEN r_again := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM finance.withdraw_gateway_test_reference(r_other); EXCEPTION WHEN check_violation THEN r_not_one := split_part(SQLERRM, ':', 1); END;
        -- paid: Status 1, nothing counted against the fees, and not withdrawn
        PERFORM finance.confirm_payment(r_test, 'Quickteller PayDirect', 'check');
        SELECT * INTO cu_paid FROM finance.paydirect_customer(r_test);
        SELECT x.paid INTO paid FROM finance.position(s, '9999/0000') x;
        BEGIN PERFORM finance.withdraw_gateway_test_reference(r_test); EXCEPTION WHEN check_violation THEN r_paid := split_part(SQLERRM, ':', 1); END;
        RAISE EXCEPTION 'the V383 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V383: an Interswitch test reference is issued from the Bursary''s desk only, for a small amount, payable for 1 to 14 days (7 unless said), as a gateway test that counts for nothing against the fees; Quickteller is answered 0 with the name and the amount while it is open, and 1 once it is paid, expired or withdrawn; a paid one is not withdrawn, nor a payer''s own reference; every other reference keeps its 24 hours',
        coalesce(span_test = interval '7 days' AND span_short = interval '3 days' AND span_other = interval '24 hours'
                 AND pr.purpose = 'Gateway test by the Bursary' AND pr.amount = 100 AND cat = 'GATEWAY_TEST'
                 AND t.days = 7 AND t.issued_by = burs AND t.issued_office = 'bursar'
                 AND r_days = 'GATEWAY_TEST_DAYS' AND r_amount = 'GATEWAY_TEST_AMOUNT' AND r_office = 'GATEWAY_TEST_OFFICE'
                 AND cu.valid AND cu.reference = r_test AND cu.surname = 'CHECKITR' AND cu.other_names = 'Tester Invented' AND cu.amount = 100
                 AND cu.number = 'MOAUM/CHK/99/0383'
                 AND NOT cu_old.valid AND cu_old.why LIKE 'Expired%'
                 AND wd.expires_at = now() AND wd_by = burs AND r_again = 'GATEWAY_TEST_CLOSED' AND r_not_one = 'GATEWAY_TEST_NOT_ONE'
                 AND NOT cu_paid.valid AND cu_paid.why = 'Already paid' AND paid = 0 AND r_paid = 'GATEWAY_TEST_PAID', false),
        format('spans %s/%s/%s | purpose=%s amount=%s category=%s | days=%s by=%s office=%s | refusals %s/%s/%s | open %s/%s/%s/%s/%s | expired %s/%s | withdrawn %s/%s again=%s not_one=%s | paid %s/%s counted=%s withdraw=%s',
               span_test, span_short, span_other, pr.purpose, pr.amount, cat, t.days, t.issued_by = burs, t.issued_office, r_days, r_amount, r_office,
               cu.valid, cu.surname, cu.other_names, cu.amount, cu.number, cu_old.valid, cu_old.why, wd.expires_at = now(), wd_by = burs, r_again, r_not_one,
               cu_paid.valid, cu_paid.why, paid, r_paid));
END $$;

-- ── V380: CCE classes in the CCE session, registration by the CCE calendar and windows, the evening timetable, attendance on the register, CCE fees kept apart ──
-- The Centre opens its own classes in the CCE session beside the full-time classes of the same courses; a CCE student is offered and
-- registered only on the Centre's, a full-time student only on the full-time ones (the database refuses a mix). Registration opens by
-- the CCE calendar (set by the Centre, opened only in the CCE session) and the CCE window, never by the full-time ones of the same
-- session; the semesters a CCE student missed are the CCE calendar's. A CCE class is put on the timetable by the Centre, with no
-- venue or lecturer in two CCE classes at once. Attendance is the register's (late, corrected with a reason, locked). The fee
-- structure is replaced by its own kind, the late fees read the CCE windows, the GST/EPS fee does not reach a CCE student, and
-- examination sessions stay the full-time classes'. The block undoes its own writes.
DO $$
DECLARE acad uuid := gen_random_uuid(); cce1 uuid := gen_random_uuid(); lect uuid := gen_random_uuid(); lect2 uuid := gen_random_uuid();
        S text := '9951/9952'; T text := '9949/9950'; pa text := 'C00023'; stu uuid := gen_random_uuid(); ft uuid := gen_random_uuid();
        ft_class uuid := gen_random_uuid(); c101 uuid; c102 uuid; reg uuid := gen_random_uuid(); ft_reg uuid := gen_random_uuid(); n_open int;
        r_cal_office text; r_cal_session text; r_cal_reason text; r_cls_session text; r_cls_office text; gate0 text; gate1 text; gate_ug_closed text;
        gate_cce_closed text; gate_reopened text; menu_cce text; menu_ft text; units int; r_mix text; chk_period boolean; chk_msg text; add_drop boolean;
        missed int; r_slot_office text; r_venue text; r_lecturer text; clash_kinds text; ft_slot boolean; rg uuid; roster int; marked jsonb;
        r_att_reason text; r_att_locked text; r_att_list text; r_att_offering text; summ record; rep int; ug_late boolean; cce_late boolean;
        wt_cce text; wt_ft text; ft_lines int; cce_lines int; ft_after int; cce_after int; gst_rows int; gst_gate text; r_in_use text; r_not_cce text;
        withdrawn boolean; ex uuid; sheets_ft int; sheets_cce int; r_archive text; gst_opened int; slot101 uuid;
        load_before text; load_cce text; load_ft text; r_load_office text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.reason', 'check V380', true);
        PERFORM set_config('moaum.actor_id', acad::text, true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9951-10-01', date '9952-08-31'),
               (gen_random_uuid(), T, date '9949-10-01', date '9950-08-31') ON CONFLICT (name) DO NOTHING;
        PERFORM policy.set_route_session('CCE', -1, S, 'the check runs in a session of its own', NULL);
        PERFORM ref.set_programme_route(pa, 'CCE', true, NULL, NULL, 'the check');
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state)
        SELECT x.code, x.title, 3, 1, 100, p.dept_code, 'Core', 'LIVE' FROM ref.programme p,
               (VALUES ('CCX 101', 'Check evening one'), ('CCX 102', 'Check evening two')) x(code, title) WHERE p.code = pa;
        INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES ('CCX 101', pa, 100, 'Core'), ('CCX 102', pa, 100, 'Core');
        INSERT INTO catalogue.offering (id, course_code, session, semester) VALUES (ft_class, 'CCX 101', S, 1);   -- the full-time class of the same course and session
        INSERT INTO iam.person (id, staff_number, surname, given_names, email) VALUES (lect, 'CHECK/V380/L', 'ZZLECT380', 'Invented', NULL),
               (lect2, 'CHECK/V380/M', 'ZZLECT380B', 'Invented', NULL);
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, study_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (stu, 'MOAUM/ADM/51/990380', 'MOAUM/CHK/51/0380', 'ZZCCE380', 'Evening Student', pa, 'CCE', 'PART_TIME', S, 100, 100, 'ACTIVE', now()),
               (ft, 'MOAUM/ADM/51/990381', 'MOAUM/CHK/51/0381', 'ZZFT380', 'Day Student', pa, 'UTME', 'FULL_TIME', S, 100, 100, 'ACTIVE', now());

        -- (1) the CCE calendar: the Centre's, opened only in the CCE session, a change to a set semester with its reason
        PERFORM set_config('moaum.actor_office', 'records', true);
        BEGIN PERFORM policy.set_route_semester('CCE', S, 1, 'OPEN', NULL, NULL, current_date - 1, current_date + 20, NULL, NULL, NULL, NULL, NULL); r_cal_office := 'SET';
        EXCEPTION WHEN check_violation THEN r_cal_office := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_id', cce1::text, true);
        PERFORM set_config('moaum.actor_office', 'cce', true);
        BEGIN PERFORM policy.set_route_semester('CCE', T, 1, 'OPEN', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL); r_cal_session := 'SET';
        EXCEPTION WHEN check_violation THEN r_cal_session := split_part(SQLERRM, ':', 1); END;
        PERFORM policy.set_route_semester('CCE', S, 1, 'NOT_YET_OPEN', NULL, NULL, current_date - 1, current_date + 20, NULL, NULL, NULL, NULL, NULL);
        BEGIN PERFORM policy.set_route_semester('CCE', S, 1, 'OPEN', NULL, NULL, current_date - 1, current_date + 20, NULL, NULL, NULL, NULL, NULL); r_cal_reason := 'SET';
        EXCEPTION WHEN check_violation THEN r_cal_reason := split_part(SQLERRM, ':', 1); END;
        PERFORM policy.set_route_semester('CCE', S, 1, 'OPEN', NULL, NULL, current_date - 1, current_date + 20, NULL, NULL, NULL, NULL, 'registration opens');
        gate0 := registration.registration_gate(stu, S, 1);   -- no CCE class yet

        -- (2) the Centre's classes: opened by the Centre in the CCE session, beside the full-time class of the same course
        BEGIN PERFORM catalogue.cce_open_classes(T, 1); r_cls_session := 'OPENED';
        EXCEPTION WHEN check_violation THEN r_cls_session := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_office', 'hod', true);
        BEGIN PERFORM catalogue.cce_open_classes(S, 1); r_cls_office := 'OPENED';
        EXCEPTION WHEN check_violation THEN r_cls_office := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_office', 'cce', true);
        n_open := catalogue.cce_open_classes(S, 1);
        SELECT id INTO c101 FROM catalogue.offering WHERE course_code = 'CCX 101' AND session = S AND semester = 1 AND stream = 'CCE';
        SELECT id INTO c102 FROM catalogue.offering WHERE course_code = 'CCX 102' AND session = S AND semester = 1 AND stream = 'CCE';

        -- (3) the gate and the menu: the CCE window governs a CCE student, the full-time window of the same session does not
        gate1 := registration.registration_gate(stu, S, 1);
        PERFORM policy.window_act('COURSE_REGISTRATION', S, 1, 'CLOSE', NULL, NULL, NULL, NULL, 'the full-time semester is over', acad, 'ict');
        gate_ug_closed := registration.registration_gate(stu, S, 1);
        PERFORM policy.window_act('CCE_COURSE_REGISTRATION', S, 1, 'CLOSE', NULL, NULL, NULL, NULL, 'the Centre pauses registration', acad, 'ict');
        gate_cce_closed := registration.registration_gate(stu, S, 1);
        PERFORM policy.window_act('CCE_COURSE_REGISTRATION', S, 1, 'REOPEN', NULL, NULL, NULL, NULL, 'resumed', acad, 'ict');
        gate_reopened := registration.registration_gate(stu, S, 1);
        SELECT string_agg(m.course_code || '@' || o.stream, ',' ORDER BY m.course_code) INTO menu_cce
          FROM registration.student_menu(stu, S, 1) m JOIN catalogue.offering o ON o.id = m.offering_id WHERE m.course_code LIKE 'CCX%';
        SELECT string_agg(m.course_code || '@' || o.stream, ',' ORDER BY m.course_code) INTO menu_ft
          FROM registration.student_menu(ft, S, 1) m JOIN catalogue.offering o ON o.id = m.offering_id WHERE m.course_code LIKE 'CCX%';

        -- (4) the registration: the engine's, on the student's stream; the database refuses a mix; add/drop and the missed semesters by the CCE calendar
        INSERT INTO registration.course_registration (id, student_id, session, semester, level, status) VALUES (reg, stu, S, 1, 100, 'DRAFT');
        units := registration.student_choose(reg, ARRAY[c101, c102, ft_class]);
        BEGIN INSERT INTO registration.entry (registration_id, offering_id, units, entry_type) VALUES (reg, ft_class, 3, 'CURRENT'); r_mix := 'MIXED';
        EXCEPTION WHEN check_violation THEN r_mix := split_part(SQLERRM, ':', 1); END;
        SELECT k.passed, k.message INTO chk_period, chk_msg FROM registration.support_add_checks(stu, S, 1, ft_class) k WHERE k.rule = 'OFFERING_PERIOD';
        add_drop := registration.add_drop_open(stu, S, 1);
        INSERT INTO policy.semester (id, session, number, state) VALUES (gen_random_uuid(), S, 3, 'CLOSED') ON CONFLICT (session, number) DO UPDATE SET state = 'CLOSED';
        PERFORM policy.set_route_semester('CCE', S, 2, 'CLOSED', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
        SELECT u.semesters INTO missed FROM registration.semesters_unregistered(stu) u;   -- the CCE second semester, not the full-time third
        -- the course load: the University's range until the Academic Office states the CCE load; the Centre does not state it
        SELECT l.min_units || '-' || l.max_units INTO load_before FROM registration.unit_limit(stu, 100) l;
        BEGIN PERFORM policy.set_route_level_limit('CCE', 100, 6, 12, NULL, NULL); r_load_office := 'SET';
        EXCEPTION WHEN check_violation THEN r_load_office := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_office', 'academic', true);
        PERFORM policy.set_route_level_limit('CCE', 100, 6, 12, NULL, 'the check''s Senate minute');
        PERFORM set_config('moaum.actor_office', 'cce', true);
        SELECT l.min_units || '-' || l.max_units INTO load_cce FROM registration.unit_limit(stu, 100) l;
        SELECT l.min_units || '-' || l.max_units INTO load_ft FROM registration.unit_limit(ft, 100) l;
        UPDATE registration.course_registration SET status = 'SUBMITTED', submitted_at = now() WHERE id = reg;
        INSERT INTO registration.course_registration (id, student_id, session, semester, level, status) VALUES (ft_reg, ft, S, 1, 100, 'DRAFT');
        PERFORM registration.student_choose(ft_reg, ARRAY[ft_class]);

        -- (5) the evening timetable: the Centre's; no venue or lecturer twice at once; the rest reported
        PERFORM catalogue.allocate_offering(c101, lect, NULL, true);
        PERFORM set_config('moaum.actor_office', 'hod', true);
        BEGIN INSERT INTO catalogue.class_slot (offering_id, weekday, starts_at, ends_at, venue) VALUES (c101, 1, '16:00', '18:00', 'LT1'); r_slot_office := 'SET';
        EXCEPTION WHEN check_violation THEN r_slot_office := split_part(SQLERRM, ':', 1); END;
        INSERT INTO catalogue.class_slot (offering_id, weekday, starts_at, ends_at, venue) VALUES (ft_class, 1, '10:00', '12:00', 'LT1');   -- the department's full-time slot, as before
        ft_slot := true;
        PERFORM set_config('moaum.actor_office', 'cce', true);
        INSERT INTO catalogue.class_slot (id, offering_id, weekday, starts_at, ends_at, venue) VALUES (gen_random_uuid(), c101, 1, '16:00', '18:00', 'LT1') RETURNING id INTO slot101;
        BEGIN INSERT INTO catalogue.class_slot (offering_id, weekday, starts_at, ends_at, venue) VALUES (c102, 1, '17:00', '19:00', ' lt1'); r_venue := 'SET';
        EXCEPTION WHEN check_violation THEN r_venue := split_part(SQLERRM, ':', 1); END;
        PERFORM catalogue.allocate_offering(c102, lect, NULL, true);
        BEGIN INSERT INTO catalogue.class_slot (offering_id, weekday, starts_at, ends_at, venue) VALUES (c102, 1, '17:00', '19:00', 'LT2'); r_lecturer := 'SET';
        EXCEPTION WHEN check_violation THEN r_lecturer := split_part(SQLERRM, ':', 1); END;
        PERFORM catalogue.allocate_offering(c102, lect2, NULL, true);
        INSERT INTO catalogue.class_slot (offering_id, weekday, starts_at, ends_at, venue) VALUES (c102, 1, '17:00', '19:00', 'LT2');
        SELECT string_agg(DISTINCT k.kind, ',' ORDER BY k.kind) INTO clash_kinds FROM catalogue.cce_clashes(S, 1) k;

        -- (6) attendance on the register: the class's registered students; late; a correction says why; a locked register is not changed
        PERFORM set_config('moaum.actor_id', lect::text, true);
        PERFORM set_config('moaum.actor_office', 'lecturer', true);
        rg := attendance.open_register('COURSE', S, 1, c101, NULL, current_date, 'Week one', lect);
        UPDATE attendance.register SET slot_ref = slot101 WHERE id = rg;
        SELECT count(*) INTO roster FROM attendance.roster(rg);
        marked := attendance.save_marks(rg, jsonb_build_array(jsonb_build_object('member', stu, 'status', 'LATE')), NULL, lect, false);
        BEGIN PERFORM attendance.save_marks(rg, jsonb_build_array(jsonb_build_object('member', stu, 'status', 'PRESENT')), NULL, lect, false); r_att_reason := 'CHANGED';
        EXCEPTION WHEN check_violation THEN r_att_reason := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM attendance.save_marks(rg, jsonb_build_array(jsonb_build_object('member', ft, 'status', 'PRESENT')), NULL, lect, false); r_att_list := 'MARKED';
        EXCEPTION WHEN check_violation THEN r_att_list := split_part(SQLERRM, ':', 1); END;
        PERFORM attendance.lock_register(rg, lect, true, NULL);
        BEGIN PERFORM attendance.save_marks(rg, jsonb_build_array(jsonb_build_object('member', stu, 'status', 'ABSENT')), 'wrong', lect, false); r_att_locked := 'CHANGED';
        EXCEPTION WHEN check_violation THEN r_att_locked := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM attendance.open_register('COURSE', S, 2, c101, NULL, current_date, NULL, lect); r_att_offering := 'OPENED';
        EXCEPTION WHEN check_violation THEN r_att_offering := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_id', cce1::text, true);
        PERFORM set_config('moaum.actor_office', 'cce', true);
        PERFORM attendance.set_cce_policy(S, 75, 10, 3, true, false);
        SELECT * INTO summ FROM attendance.course_summary(stu, S) x WHERE x.course_code = 'CCX 101';
        SELECT count(*) INTO rep FROM attendance.course_report('CCE', S, 1, NULL, NULL, pa, NULL, current_date - 7, current_date);

        -- (7) the fees: the windows a CCE student answers to; the structure replaced by its own kind; the late fee and the GST/EPS fee
        wt_cce := policy.window_type_for(stu, 'SCHOOL_FEES_PAYMENT');
        wt_ft := policy.window_type_for(ft, 'SCHOOL_FEES_PAYMENT');
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM finance.import_fee_structure(S, '[{"faculty": "", "programmeCode": "C00023", "level": "100", "semester": "1", "amount": "99000"}]');
        PERFORM finance.import_fee_structure(S, '[{"programmeCode": "C00023", "level": "100", "semester": "1", "entryMode": "CCE", "amount": "45000"}]');
        SELECT count(*) FILTER (WHERE entry_mode IS DISTINCT FROM 'CCE'), count(*) FILTER (WHERE entry_mode = 'CCE') INTO ft_lines, cce_lines
          FROM finance.fee_schedule WHERE session = S AND ended_at IS NULL;
        PERFORM finance.import_fee_structure(S, '[{"programmeCode": "C00023", "level": "100", "semester": "1", "amount": "98000"}]');
        SELECT count(*) FILTER (WHERE entry_mode IS DISTINCT FROM 'CCE'), count(*) FILTER (WHERE entry_mode = 'CCE') INTO ft_after, cce_after
          FROM finance.fee_schedule WHERE session = S AND ended_at IS NULL;
        PERFORM policy.window_act('COURSE_REGISTRATION', S, 1, 'REOPEN', now() - interval '3 days', now() - interval '1 day', now() + interval '5 days', true, 'late registration', acad, 'ict');
        ug_late := finance.late_registration_applies(ft, S);
        cce_late := finance.late_registration_applies(stu, S);
        SELECT count(*) INTO gst_rows FROM finance.gst_eps_rows(S, stu);
        gst_gate := registration.gst_gate(stu, S, 'CCX 101');
        PERFORM set_config('moaum.actor_office', 'gst', true);
        gst_opened := catalogue.open_gst_offerings(S, 'GST');

        -- (8) a class nobody used is withdrawn; one with history stays; a full-time class is not the Centre's
        PERFORM set_config('moaum.actor_office', 'cce', true);
        BEGIN PERFORM catalogue.cce_withdraw_class(c101, 'opened in error'); r_in_use := 'WITHDRAWN';
        EXCEPTION WHEN check_violation THEN r_in_use := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM catalogue.cce_withdraw_class(ft_class, 'not ours'); r_not_cce := 'WITHDRAWN';
        EXCEPTION WHEN check_violation THEN r_not_cce := split_part(SQLERRM, ':', 1); END;
        DELETE FROM registration.entry WHERE offering_id = c102;
        PERFORM catalogue.cce_withdraw_class(c102, 'no student took it');
        withdrawn := NOT EXISTS (SELECT 1 FROM catalogue.offering WHERE id = c102);

        -- (9) the examination session stays the full-time classes'; the CCE session is not archived under the Centre
        PERFORM set_config('moaum.actor_office', 'exams', true);
        PERFORM catalogue.allocate_offering(ft_class, lect2, NULL, true);
        ex := gen_random_uuid();
        INSERT INTO assessment.exam_session (id, session, semester, kind, exams_from, exams_to, sheets_due, state) VALUES (ex, S, 1, 'MAIN', current_date, current_date + 5, current_date + 10, 'OPEN');
        PERFORM assessment.release_exam_sheets(ex);
        SELECT count(*) FILTER (WHERE o.stream = 'REGULAR'), count(*) FILTER (WHERE o.stream = 'CCE') INTO sheets_ft, sheets_cce
          FROM assessment.score_sheet sh JOIN catalogue.offering o ON o.id = sh.offering_id WHERE sh.exam_session_id = ex;
        UPDATE policy.academic_session SET state = 'CLOSED' WHERE name = S;
        BEGIN PERFORM policy.archive_session(S, 'the check'); r_archive := 'ARCHIVED';
        EXCEPTION WHEN check_violation THEN r_archive := split_part(SQLERRM, ':', 1); END;
        RAISE EXCEPTION 'the V380 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V380: CCE — the Centre opens its classes in the CCE session beside the full-time classes of the same courses; a CCE student is offered and registered only on the Centre''s, a full-time student only on the full-time ones, and the database refuses a mix; registration opens by the CCE calendar (the Centre''s, opened only in the CCE session, changed with a reason) and the CCE window, never by the full-time window of the same session; add/drop and the missed semesters read the CCE calendar; a CCE student registers within the CCE course load the Academic Office states (the University''s until it does); a CCE class is timetabled by the Centre with no venue or lecturer twice at once, and the rest reported; attendance is the register''s (late, a correction with its reason, locked, the class list only); an uploaded fee structure replaces only its own kind; the late fee reads the CCE window and the GST/EPS fee does not reach a CCE student; examination sessions stay the full-time classes''; the CCE session is not archived under the Centre',
        coalesce(r_cal_office = 'CCE_OFFICE' AND r_cal_session = 'CCE_CALENDAR_SESSION' AND r_cal_reason = 'CCE_CALENDAR_REASON'
                 AND gate0 LIKE 'Course registration for the first semester of ' || S || ' opens when the Centre for Continuing Education''s classes for it are set up.'
                 AND r_cls_session = 'CCE_CLASS_SESSION' AND r_cls_office = 'CCE_OFFICE' AND n_open >= 2 AND c101 IS NOT NULL AND c102 IS NOT NULL AND c101 <> ft_class
                 AND gate1 IS NULL AND gate_ug_closed IS NULL AND gate_cce_closed LIKE 'CCE course registration is currently closed%' AND gate_reopened IS NULL
                 AND menu_cce = 'CCX 101@CCE,CCX 102@CCE' AND menu_ft = 'CCX 101@REGULAR'
                 AND units = 6 AND r_mix = 'REGISTRATION_STREAM' AND NOT chk_period AND chk_msg LIKE '%full-time class; a student of the Centre%' AND add_drop AND missed = 1
                 AND load_before = load_ft AND load_cce = '6-12' AND r_load_office = 'CCE_OFFICE'
                 AND r_slot_office = 'CCE_SLOT_OFFICE' AND ft_slot AND r_venue = 'CCE_SLOT_VENUE_CLASH' AND r_lecturer = 'CCE_SLOT_LECTURER_CLASH'
                 AND clash_kinds = 'STUDENTS'
                 AND roster = 1 AND (marked->>'marked')::int = 1 AND r_att_reason = 'ATT_REASON' AND r_att_list = 'ATT_NOT_ON_LIST' AND r_att_locked = 'ATT_LOCKED'
                 AND r_att_offering = 'ATT_OFFERING' AND summ.total = 1 AND summ.late = 1 AND summ.rate = 100 AND summ.verdict = 'ELIGIBLE' AND rep = 1
                 AND wt_cce = 'CCE_SCHOOL_FEES_PAYMENT' AND wt_ft = 'SCHOOL_FEES_PAYMENT' AND ft_lines = 1 AND cce_lines = 1 AND ft_after = 1 AND cce_after = 1
                 AND ug_late AND NOT cce_late AND gst_rows = 0 AND gst_gate IS NULL AND gst_opened >= 0
                 AND r_in_use = 'CCE_CLASS_IN_USE' AND r_not_cce = 'CCE_CLASS_NOT_CCE' AND withdrawn
                 AND sheets_ft = 1 AND sheets_cce = 0 AND r_archive = 'SESSION_ARCHIVE_REFUSED', false),
        format('calendar %s/%s/%s | gate0=%s | classes %s/%s opened=%s 101=%s 102=%s | gates %s/%s/%s/%s | menu %s / %s | units=%s mix=%s period=%s (%s) add_drop=%s missed=%s | load %s/%s/%s %s | slots %s/%s/%s/%s clashes=%s | register roster=%s marked=%s reason=%s list=%s locked=%s offering=%s summary=%s/%s/%s/%s report=%s | windows %s/%s lines %s/%s then %s/%s late %s/%s gst %s/%s/%s | withdraw %s/%s/%s | sheets %s/%s archive=%s',
               r_cal_office, r_cal_session, r_cal_reason, gate0, r_cls_session, r_cls_office, n_open, c101 IS NOT NULL, c102 IS NOT NULL,
               gate1, gate_ug_closed, gate_cce_closed, gate_reopened, menu_cce, menu_ft, units, r_mix, chk_period, chk_msg, add_drop, missed, load_before, load_cce, load_ft, r_load_office,
               r_slot_office, ft_slot, r_venue, r_lecturer, clash_kinds, roster, marked, r_att_reason, r_att_list, r_att_locked, r_att_offering,
               summ.total, summ.late, summ.rate, summ.verdict, rep, wt_cce, wt_ft, ft_lines, cce_lines, ft_after, cce_after, ug_late, cce_late,
               gst_rows, gst_gate, gst_opened, r_in_use, r_not_cce, withdrawn, sheets_ft, sheets_cce, r_archive));
END $$;

-- ── V381: CCE examinations in a session of their own, the attendance bar, the CCE student's place in the programme, deferment on the CCE calendar, the CCE matriculation series, the route on the transcript, old-portal CCE students ──
-- An examination session is the full-time classes' or the Centre's; each releases sheets to its own stream's classes and a sheet
-- is refused against the other's; the examination card lists the student's own stream's papers. The Centre may let attendance
-- below its minimum bar the examination (never without a minimum). A CCE student's expected completion and spillover run from
-- the CCE entry session for the CCE duration against the CCE session, and six years elapsing graduates nobody; a deferment's
-- dates are the CCE calendar's. The Registry sets the CCE series and segment with a reason; the statement names the route and
-- the study mode; the old portal's CCE students come over as CCE and part-time. The block undoes its own writes.
DO $$
DECLARE acad uuid := gen_random_uuid(); cce1 uuid := gen_random_uuid(); lect uuid := gen_random_uuid(); reg_uuid uuid := gen_random_uuid();
        S text := '9947/9948'; OLD text := '9941/9942'; pa text := 'C00023'; stu uuid := gen_random_uuid(); old_stu uuid := gen_random_uuid();
        ft uuid := gen_random_uuid(); ft_class uuid := gen_random_uuid(); c101 uuid; c102 uuid; ex_ft uuid := gen_random_uuid(); ex_cce uuid := gen_random_uuid();
        r_cce uuid := gen_random_uuid(); r_ft uuid := gen_random_uuid(); sheets_cce int; sheets_ft int; r_stream text; auto_sheet boolean; dock_cce int; dock_ft int;
        r_bar_min text; bar_on text; bar_off text; rg uuid; pos people.academic_position; pos_old people.academic_position; pos_ft people.academic_position;
        start_cce date; start_ft date; ret record; tl record; r_m_office text; r_m_series text; comps record; prev record; ft_series text;
        stmt jsonb; imp record; imported people.student; stored_cur text; moved_cur text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.reason', 'check V381', true);
        PERFORM set_config('moaum.actor_id', acad::text, true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9947-10-01', date '9948-08-31'),
               (gen_random_uuid(), OLD, date '9941-10-01', date '9942-08-31') ON CONFLICT (name) DO NOTHING;
        PERFORM policy.set_route_session('CCE', -1, S, 'the check runs in a session of its own', NULL);
        PERFORM ref.set_programme_route(pa, 'CCE', true, NULL, NULL, 'the check');
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state)
        SELECT x.code, x.title, 3, 1, 100, p.dept_code, 'Core', 'LIVE' FROM ref.programme p,
               (VALUES ('CCZ 101', 'Check exam one'), ('CCZ 102', 'Check exam two')) x(code, title) WHERE p.code = pa;
        INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES ('CCZ 101', pa, 100, 'Core'), ('CCZ 102', pa, 100, 'Core');
        INSERT INTO iam.person (id, staff_number, surname, given_names, email) VALUES (lect, 'CHECK/V381/L', 'ZZLECT381', 'Invented', NULL);
        INSERT INTO catalogue.offering (id, course_code, session, semester, lecturer_id) VALUES (ft_class, 'CCZ 101', S, 1, lect);
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, study_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (stu, 'MOAUM/ADM/47/990381', 'MOAUM/CHK/47/0381', 'ZZCCE381', 'Examined', pa, 'CCE', 'PART_TIME', S, 100, 100, 'ACTIVE', now()),
               (old_stu, 'MOAUM/ADM/41/990382', 'MOAUM/CHK/41/0382', 'ZZCCE381', 'Spilling over', pa, 'CCE', 'PART_TIME', OLD, 100, 600, 'ACTIVE', now()),
               (ft, 'MOAUM/ADM/47/990383', 'MOAUM/CHK/47/0383', 'ZZFT381', 'Day', pa, 'UTME', 'FULL_TIME', S, 100, 100, 'ACTIVE', now());
        PERFORM set_config('moaum.actor_id', cce1::text, true);
        PERFORM set_config('moaum.actor_office', 'cce', true);
        PERFORM policy.set_route_semester('CCE', S, 1, 'OPEN', date '9947-11-02', date '9948-02-27', current_date - 1, current_date + 30, NULL, NULL, NULL, NULL, NULL);
        PERFORM policy.set_route_semester('CCE', S, 2, 'NOT_YET_OPEN', date '9948-03-09', date '9948-07-31', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
        PERFORM catalogue.cce_open_classes(S, 1);
        SELECT id INTO c101 FROM catalogue.offering WHERE course_code = 'CCZ 101' AND session = S AND semester = 1 AND stream = 'CCE';
        SELECT id INTO c102 FROM catalogue.offering WHERE course_code = 'CCZ 102' AND session = S AND semester = 1 AND stream = 'CCE';
        PERFORM catalogue.allocate_offering(c101, lect, NULL, true);
        INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, submitted_at, approved_at, approved_by)
        VALUES (r_cce, stu, S, 1, 100, 'APPROVED', now(), now(), acad), (r_ft, ft, S, 1, 100, 'APPROVED', now(), now(), acad);
        INSERT INTO registration.entry (registration_id, offering_id, units, entry_type, status) VALUES (r_cce, c101, 3, 'CURRENT', 'APPROVED'), (r_cce, c102, 3, 'CURRENT', 'APPROVED'),
               (r_ft, ft_class, 3, 'CURRENT', 'APPROVED');

        -- (1) the examination sessions: a full-time and a CCE one of the same session, semester and kind; each releases its own stream's sheets
        PERFORM set_config('moaum.actor_office', 'ict', true);
        INSERT INTO assessment.exam_session (id, session, semester, kind, exams_from, exams_to, sheets_due, state, stream)
        VALUES (ex_ft, S, 1, 'MAIN', current_date, current_date + 5, current_date + 10, 'OPEN', 'REGULAR'),
               (ex_cce, S, 1, 'MAIN', current_date, current_date + 5, current_date + 10, 'OPEN', 'CCE');
        PERFORM assessment.release_exam_sheets(ex_ft);
        PERFORM assessment.release_exam_sheets(ex_cce);
        SELECT count(*) FILTER (WHERE sh.exam_session_id = ex_cce AND o.stream = 'CCE'), count(*) FILTER (WHERE sh.exam_session_id = ex_ft AND o.stream = 'REGULAR')
          INTO sheets_cce, sheets_ft
          FROM assessment.score_sheet sh JOIN catalogue.offering o ON o.id = sh.offering_id WHERE sh.exam_session_id IN (ex_cce, ex_ft);
        BEGIN INSERT INTO assessment.score_sheet (id, offering_id, exam_session_id, due_on) VALUES (gen_random_uuid(), c102, ex_ft, current_date + 10); r_stream := 'MADE';
        EXCEPTION WHEN check_violation THEN r_stream := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_office', 'cce', true);
        PERFORM catalogue.allocate_offering(c102, lect, NULL, true);   -- the CCE session is open and released: its sheet follows the lecturer
        auto_sheet := EXISTS (SELECT 1 FROM assessment.score_sheet WHERE offering_id = c102 AND exam_session_id = ex_cce);
        SELECT count(*) INTO dock_cce FROM assessment.student_docket(stu, ex_cce);
        SELECT count(*) INTO dock_ft FROM assessment.student_docket(stu, ex_ft);

        -- (2) attendance bars the examination only where the Centre says so, and only against a minimum
        BEGIN PERFORM attendance.set_cce_policy(S, NULL, NULL, 1, true, true); r_bar_min := 'SET';
        EXCEPTION WHEN check_violation THEN r_bar_min := split_part(SQLERRM, ':', 1); END;
        rg := attendance.open_register('COURSE', S, 1, c101, NULL, current_date, 'Week one', lect);
        PERFORM attendance.save_marks(rg, jsonb_build_array(jsonb_build_object('member', stu, 'status', 'ABSENT')), NULL, lect, false);
        PERFORM attendance.set_cce_policy(S, 75, NULL, 1, true, false);
        bar_off := attendance.exam_bar(stu, c101);
        PERFORM attendance.set_cce_policy(S, 75, NULL, 1, true, true);
        bar_on := attendance.exam_bar(stu, c101);

        -- (3) the CCE student's place: the CCE session, six years, registered now; one six years in spills over and is not graduated
        SELECT * INTO pos FROM people.academic_position_rows(stu);
        SELECT * INTO pos_old FROM people.academic_position_rows(old_stu);
        SELECT * INTO pos_ft FROM people.academic_position_rows(ft);
        -- the stored position follows the CCE session mapping
        stored_cur := (SELECT current_session FROM people.academic_position WHERE student_id = stu);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        PERFORM policy.set_route_session('CCE', -1, OLD, 'the check moves the CCE session', NULL);
        moved_cur := (SELECT current_session FROM people.academic_position WHERE student_id = stu);
        PERFORM policy.set_route_session('CCE', -1, S, 'the check moves it back', NULL);
        PERFORM set_config('moaum.actor_office', 'cce', true);

        -- (4) deferment dates on the CCE calendar
        start_cce := people.period_start(stu, S, 1);
        start_ft := people.period_start(ft, S, 1);
        SELECT * INTO ret FROM people.deferment_return(stu, 'SEMESTER', S, 1);
        SELECT * INTO tl FROM people.programme_timeline(stu);

        -- (5) the CCE matriculation series and segment: the Registry's, with a reason
        BEGIN PERFORM people.set_route_matric('CCE', NULL, 'CCE', 'the check'); r_m_office := 'SET';
        EXCEPTION WHEN check_violation THEN r_m_office := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_office', 'registrar', true);
        BEGIN PERFORM people.set_route_matric('CCE', 'NOSUCH381', 'CCE', 'the check'); r_m_series := 'SET';
        EXCEPTION WHEN check_violation THEN r_m_series := split_part(SQLERRM, ':', 1); END;
        INSERT INTO people.matric_series (code, name, last_issued, active) VALUES ('CCEX381', 'CCE check series', 40, true);
        PERFORM people.set_route_matric('CCE', 'CCEX381', 'CCE', 'the Centre''s own run of numbers');
        SELECT * INTO comps FROM people.matric_components(stu);
        SELECT * INTO prev FROM people.matric_preview(stu);
        SELECT c.series_code INTO ft_series FROM people.matric_components(ft) c;

        -- (6) the statement names the route and the study mode; the old portal's CCE student comes over CCE and part-time
        stmt := credentials.build_statement(stu, 'TRANSCRIPT', NULL, NULL);
        SELECT * INTO imp FROM people.import_students_rows(jsonb_build_array(jsonb_build_object(
            'matric', 'MOAUM/CCE/47/9381', 'surname', 'ZZOLDCCE', 'otherNames', 'Migrated', 'programme', pa, 'entryMode', 'Part time', 'entrySession', S, 'level', '300')));
        SELECT * INTO imported FROM people.student WHERE matric_no = 'MOAUM/CCE/47/9381';
        RAISE EXCEPTION 'the V381 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V381: CCE — a CCE examination session beside the full-time one of the same session, semester and kind releases sheets to the Centre''s classes only, and a sheet is refused against the other stream''s session; the card lists the student''s own stream''s papers; attendance bars the examination only where the Centre says so and only against a minimum; a CCE student stands in the CCE session for six years, and six years elapsing spills over and graduates nobody; deferment dates are the CCE calendar''s; the Registry sets the CCE series and segment with a reason; the statement names the route and the study mode; an old-portal CCE student comes over CCE and part-time',
        coalesce(sheets_cce = 1 AND sheets_ft = 1 AND r_stream = 'EXAM_STREAM' AND auto_sheet AND dock_cce = 2 AND dock_ft = 0
                 AND r_bar_min = 'CCE_ATTENDANCE_BAR' AND bar_off IS NULL AND bar_on LIKE 'CBT_ATTENDANCE:%'
                 AND pos.current_session = S AND pos.duration_years = 6 AND pos.expected_completion = policy.session_after(S, 5) AND pos.registered_current
                 AND pos.spillover_years = 0 AND pos_old.spillover_years >= 1 AND pos_old.spillover_state LIKE 'SPILLOVER%' AND pos_old.classification <> 'GRADUATED'
                 AND pos_ft.current_session IS DISTINCT FROM S AND stored_cur = S AND moved_cur = OLD
                 AND start_cce = date '9947-11-02' AND start_ft IS DISTINCT FROM date '9947-11-02' AND ret.return_session = S AND ret.return_semester = 2
                 AND ret.return_on = date '9948-03-09' AND tl.original_completion_session = policy.session_after(S, 5)
                 AND r_m_office = 'CCE_OFFICE' AND r_m_series = 'CCE_MATRIC_SERIES' AND comps.series_code = 'CCEX381' AND comps.university_code LIKE '%/CCE'
                 AND prev.matric_no LIKE '%/CCE/%' AND people.matric_shape_ok(prev.matric_no) AND ft_series IS DISTINCT FROM 'CCEX381'
                 AND stmt->>'studyMode' = 'Part-time' AND stmt->>'route' LIKE 'Centre for Continuing Education%' AND (stmt->>'durationYears')::int = 6
                 AND imp.created = 1 AND imported.entry_mode = 'CCE' AND imported.study_mode = 'PART_TIME', false),
        format('sheets %s/%s stream=%s auto=%s docket %s/%s | bar min=%s off=%s on=%s | pos %s/%s/%s reg=%s spill=%s old=%s/%s/%s ft=%s stored=%s moved=%s | defer %s/%s return %s/%s/%s timeline=%s | matric %s/%s %s/%s %s shape=%s ft=%s | stmt %s/%s/%s | import %s %s/%s',
               sheets_cce, sheets_ft, r_stream, auto_sheet, dock_cce, dock_ft, r_bar_min, bar_off, bar_on,
               pos.current_session, pos.duration_years, pos.expected_completion, pos.registered_current, pos.spillover_years,
               pos_old.spillover_years, pos_old.spillover_state, pos_old.classification, pos_ft.current_session, stored_cur, moved_cur,
               start_cce, start_ft, ret.return_session, ret.return_semester, ret.return_on, tl.original_completion_session,
               r_m_office, r_m_series, comps.series_code, comps.university_code, prev.matric_no, people.matric_shape_ok(prev.matric_no), ft_series,
               stmt->>'studyMode', stmt->>'route', stmt->>'durationYears', imp.created, imported.entry_mode, imported.study_mode));
END $$;

-- ── V385. Post-UTME examined on the one CBT engine: the Director's windows closed until opened; a Post-UTME bank and examination of an
--          admission session; the candidate verified by JAMB number and the examination's second factor (yes or no, never which), judged on
--          the record and the window; the attempt owned by the application; no score through the examination door; the official file
--          generated only from approved results, sent, received, previewed and imported into the screening score (a released score never
--          touched, a different one replaced only with a reason and the old value kept); the released score read only on its own window ──
DO $$
DECLARE S text := '9961/9962'; who uuid := gen_random_uuid(); cand uuid := gen_random_uuid(); acct uuid := gen_random_uuid(); app uuid := gen_random_uuid();
        cr uuid := gen_random_uuid(); batch uuid := gen_random_uuid(); q1 uuid := gen_random_uuid(); q2 uuid := gen_random_uuid(); q3 uuid := gen_random_uuid();
        ex assessment.cbt_exam; a assessment.cbt_attempt; x admissions.putme_score_export; imp admissions.putme_score_import; imp2 admissions.putme_score_import; imp3 admissions.putme_score_import; imp4 admissions.putme_score_import; rc record;
        w_cbt text; w_res text; w_cbt2 text; v_office int; r_bank text; r_sos text; r_nopro text; v_pub text; v_right uuid; v_wrong uuid; v_factor text;
        e_before text; e_after text; n_cand int; n_elig int; m_cand bigint; v_owned boolean; r_deny text; v_score numeric; v_hidden numeric; v_status text;
        r_unapproved text; r_publish text; v_rows int; v_hash text; v_sent text; v_recv text; v_prev text; v_app_score numeric;
        v_hist int; v_hist_prev numeric; r_cancel text; rc_closed text; rc_unrel text; rc_wrong text; rc_rel text; rc_score numeric; v_summary text; v_count bigint;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'ict', true); PERFORM set_config('moaum.reason', 'CHECK V385', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9961-10-01', date '9962-08-31') ON CONFLICT (name) DO NOTHING;
        -- (1) the office of the examination token, and the two windows closed until the Director opens them
        SELECT count(*) INTO v_office FROM ref.office WHERE code = 'putmecbt';
        SELECT state INTO w_cbt FROM policy.window_state('POST_UTME_CBT', S, NULL);
        SELECT state INTO w_res FROM policy.window_state('POST_UTME_RESULT_CHECKING', S, NULL);
        -- (2) a question is in one bank only
        BEGIN
            INSERT INTO assessment.question (id, course_code, putme_session, stem, options, answer, kind, marks) VALUES (gen_random_uuid(), 'GST 101', S, 'two banks', '["a","b"]', 0, 'MCQ', 1);
            r_bank := 'ACCEPTED';
        EXCEPTION WHEN check_violation THEN r_bank := 'REFUSED'; END;
        INSERT INTO assessment.question (id, putme_session, stem, options, answer, kind, marks) VALUES
            (q1, S, 'one', '["a","b","c","d"]', 1, 'MCQ', 1), (q2, S, 'two', '["a","b","c","d"]', 2, 'MCQ', 1), (q3, S, 'three', '["a","b","c","d"]', 3, 'MCQ', 1);
        PERFORM pg_temp.moderated();
        -- (3) the applicant on the record: on the CAPS list, registered, paid, submitted
        INSERT INTO admissions.caps_batch (id, session, source, list_kind, file_sha256, rows_read, downloaded_on, uploaded_by, uploaded_office)
        VALUES (batch, S, 'CAPS_DOWNLOAD', 'UTME', '\xB385'::bytea, 1, current_date, who, 'academic');
        INSERT INTO admissions.caps_row (id, batch_id, session, jamb_reg_no, raw, surname, other_names, jamb_code, aggregate, entry_mode, sex, state_of_origin, lga)
        VALUES (cr, batch, S, '20619610001', '{"Subject1":"Use of English","Subject2":"Lit. in English","Subject3":"Christian Rel. Know","Subject4":"Government"}'::jsonb, 'CHECKPUTME', 'Cand', 'C00066', 250, 'UTME', 'F', 'Benue', 'Makurdi');
        INSERT INTO admissions.candidate (id, session, jamb_reg_no, surname, other_names, programme, entry_mode, entry_level, offer_state, admitted_from)
        VALUES (cand, S, '20619610001', 'CHECKPUTME', 'Cand', (SELECT name FROM ref.programme WHERE code = 'C00066'), 'UTME', 100, 'PROPOSED', cr);
        INSERT INTO admissions.applicant_account (id, session, candidate_id, jamb_key, email, phone, password_hash)
        VALUES (acct, S, cand, '20619610001', 'checkputme@example.com', '08031234567', crypt('x', gen_salt('bf', 12)));
        INSERT INTO admissions.application (id, account_id, candidate_id, session, application_no, fee_confirmed_at, submitted_at)
        VALUES (app, acct, cand, S, 'APP/61/000001', now(), now());
        -- (4) the examination: a score on submission refused; published only once a programme is screened by examination
        ex := assessment.cbt_new_putme_exam(S, 'Check Post-UTME', 'read', 30, 3, 'FIXED', false, false, 0, 1, 'STANDARD', 'LAB', 3, 'WARN', 'DENY', now() - interval '1 minute', now() + interval '2 hours');
        INSERT INTO assessment.cbt_exam_question (exam_id, question_id, ordinal) VALUES (ex.id, q1, 1), (ex.id, q2, 2), (ex.id, q3, 3);
        BEGIN ex := assessment.cbt_configure(ex.id, '{"scoreOnSubmit":true}'::jsonb); r_sos := 'ACCEPTED'; EXCEPTION WHEN check_violation THEN r_sos := split_part(SQLERRM, ':', 1); END;
        ex := assessment.cbt_configure(ex.id, '{"putmeVerify":"APPLICATION_NO"}'::jsonb);
        BEGIN PERFORM assessment.cbt_exam_action(ex.id, 'publish', NULL); r_nopro := 'PUBLISHED'; EXCEPTION WHEN check_violation THEN r_nopro := split_part(SQLERRM, ':', 1); END;
        INSERT INTO admissions.screening_exam_programme (session, programme_code) VALUES (S, 'C00066');
        ex := assessment.cbt_exam_action(ex.id, 'publish', NULL);
        v_pub := ex.state;
        -- (5) the door: yes or no
        v_right := admissions.putme_cbt_verify(S, '20619610001', 'app/61/000001');
        v_wrong := admissions.putme_cbt_verify(S, '20619610001', 'APP/61/000009');
        v_factor := admissions.putme_cbt_factor(S);
        -- (6) the Director's window gates the sitting; the record decides the rest
        e_before := split_part(assessment.cbt_putme_eligibility(ex.id, app), ':', 1);
        PERFORM policy.window_act('POST_UTME_CBT', S, NULL, 'OPEN', NULL, NULL, NULL, false, 'check', who, 'ict');
        SELECT state INTO w_cbt2 FROM policy.window_state('POST_UTME_CBT', S, NULL);
        e_after := coalesce(assessment.cbt_putme_eligibility(ex.id, app), 'ELIGIBLE');
        SELECT count(*), count(*) FILTER (WHERE eligible) INTO n_cand, n_elig FROM assessment.cbt_candidates(ex.id);
        SELECT candidates INTO m_cand FROM assessment.cbt_monitor_counts(ex.id);
        -- (7) the attempt is the application's; a second screen is refused by the examination's rule; the score is the engine's and never the candidate's
        PERFORM set_config('moaum.actor_id', app::text, true); PERFORM set_config('moaum.actor_office', 'putmecbt', true);
        a := assessment.cbt_start(ex.id, app, '10.0.0.1', 'check');
        v_owned := a.application_id = app AND a.candidate_id = app AND a.student_id IS NULL AND a.jupeb_application_id IS NULL;
        BEGIN PERFORM assessment.cbt_start(ex.id, app, '10.0.0.2', 'check'); r_deny := 'STARTED'; EXCEPTION WHEN check_violation THEN r_deny := split_part(SQLERRM, ':', 1); END;
        PERFORM assessment.cbt_save_answers(a.id, a.token, (SELECT jsonb_agg(jsonb_build_object('q', q.question_id, 'a', to_jsonb(q.answers))) FROM assessment.cbt_attempt_questions(a.id) q));
        PERFORM assessment.cbt_submit(a.id, a.token);
        SELECT score INTO v_score FROM assessment.cbt_attempt WHERE id = a.id;
        SELECT percentage, attempt_status INTO v_hidden, v_status FROM assessment.cbt_putme_exams(app, NULL) WHERE exam_id = ex.id;
        -- (8) the file: only from approved results; never published to candidates through the examination
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'ict', true);
        BEGIN x := admissions.putme_export_scores(S, NULL, who, 'ict'); r_unapproved := 'EXPORTED'; EXCEPTION WHEN check_violation THEN r_unapproved := split_part(SQLERRM, ':', 1); END;
        PERFORM assessment.cbt_exam_action(ex.id, 'close', NULL); PERFORM assessment.cbt_exam_action(ex.id, 'complete', NULL);
        PERFORM assessment.cbt_results_action(ex.id, 'review'); PERFORM assessment.cbt_results_action(ex.id, 'approve');
        BEGIN PERFORM assessment.cbt_results_action(ex.id, 'publish'); r_publish := 'PUBLISHED'; EXCEPTION WHEN check_violation THEN r_publish := split_part(SQLERRM, ':', 1); END;
        x := admissions.putme_export_scores(S, NULL, who, 'ict');
        v_rows := x.rows_count; v_hash := x.sha256;
        x := admissions.putme_send_export(x.id, 'please import', who);
        v_sent := x.state;
        -- (9) the Academic Office: received, previewed, imported once; a different score kept or replaced with a reason; a released score never touched
        PERFORM set_config('moaum.actor_office', 'academic', true);
        x := admissions.putme_export_act(x.id, 'RECEIVE', NULL, who); v_recv := x.state;
        SELECT outcome INTO v_prev FROM admissions.putme_import_preview(x.id);
        imp := admissions.putme_import_scores(x.id, 'KEEP', NULL, who, 'academic');
        SELECT screening_score INTO v_app_score FROM admissions.application WHERE id = app;
        imp2 := admissions.putme_import_scores(x.id, 'KEEP', NULL, who, 'academic');
        UPDATE admissions.application SET screening_score = 50 WHERE id = app;
        imp3 := admissions.putme_import_scores(x.id, 'REPLACE', 'check: the engine''s score stands', who, 'academic');
        SELECT count(*), max(previous_score) INTO v_hist, v_hist_prev FROM admissions.putme_score_history WHERE application_id = app;
        BEGIN x := admissions.putme_export_act(x.id, 'CANCEL', 'too late', who); r_cancel := 'CANCELLED'; EXCEPTION WHEN check_violation THEN r_cancel := split_part(SQLERRM, ':', 1); END;
        -- (10) the candidate reads a score only on the result-checking window, only once released
        SELECT * INTO rc FROM admissions.putme_result_check(S, '20619610001', 'APP/61/000001'); rc_closed := rc.outcome;
        PERFORM set_config('moaum.actor_office', 'ict', true);
        PERFORM policy.window_act('POST_UTME_RESULT_CHECKING', S, NULL, 'OPEN', NULL, NULL, NULL, false, 'check', who, 'ict');
        SELECT * INTO rc FROM admissions.putme_result_check(S, '20619610001', 'APP/61/000001'); rc_unrel := rc.outcome;
        SELECT * INTO rc FROM admissions.putme_result_check(S, '20619610001', 'wrong'); rc_wrong := rc.outcome;
        PERFORM set_config('moaum.actor_office', 'academic', true);
        PERFORM admissions.release_scores(S);
        SELECT * INTO rc FROM admissions.putme_result_check(S, '20619610001', 'APP/61/000001'); rc_rel := rc.outcome; rc_score := rc.score;
        imp4 := admissions.putme_import_scores(x.id, 'REPLACE', 'check: after release', who, 'academic');
        SELECT exams || '/' || candidates INTO v_summary FROM assessment.cbt_office_summary('POST_UTME', S);
        v_count := assessment.cbt_candidate_count(ex);
        RAISE EXCEPTION 'the V385 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V385: Post-UTME on the one CBT engine — the candidate''s office exists; the CBT and result-checking windows are closed until opened; a question is in one bank; a score on submission is refused; publishing needs a programme screened by examination; the door answers yes or no; the window gates the start and the record decides eligibility; the attempt is the application''s and a second screen is refused; the engine scores and the candidate sees nothing; export needs approved results and results are never published through the examination; the file is sent, received, previewed and imported once, a different score replaced only with a reason and the old value kept, a released score never touched, an imported file never cancelled; the result-checking page reads only a released score on its own window',
        coalesce(v_office = 1 AND w_cbt = 'CLOSED' AND w_res = 'CLOSED' AND r_bank = 'REFUSED' AND r_sos = 'CBT_PUTME_NO_SCORE_ON_SUBMIT' AND r_nopro = 'CBT_PUTME_NO_PROGRAMME' AND v_pub = 'PUBLISHED'
                 AND v_right = app AND v_wrong IS NULL AND v_factor = 'APPLICATION_NO'
                 AND e_before = 'CBT_PUTME_WINDOW' AND w_cbt2 = 'OPEN' AND e_after = 'ELIGIBLE' AND n_cand = 1 AND n_elig = 1 AND m_cand = 1
                 AND v_owned AND r_deny = 'CBT_SECOND_SESSION_DENIED' AND v_score = 3 AND v_hidden IS NULL AND v_status = 'SUBMITTED'
                 AND r_unapproved = 'PUTME_EXPORT_UNAPPROVED' AND r_publish = 'CBT_PUTME_NOT_PUBLISHED_HERE' AND v_rows = 1 AND length(v_hash) = 64 AND v_sent = 'SENT_TO_ACADEMIC'
                 AND v_recv = 'RECEIVED' AND v_prev = 'NEW' AND imp.applied = 1 AND v_app_score = 100 AND imp2.applied = 0 AND imp2.unchanged = 1
                 AND imp3.replaced = 1 AND v_hist = 2 AND v_hist_prev = 50 AND r_cancel = 'PUTME_EXPORT_STATE'
                 AND rc_closed = 'CLOSED' AND rc_unrel = 'NOT_RELEASED' AND rc_wrong = 'NOT_VERIFIED' AND rc_rel = 'RELEASED' AND rc_score = 100
                 AND imp4.released = 1 AND imp4.replaced = 0 AND v_summary = '1/1' AND v_count = 1, false),
        format('office=%s windows=%s/%s/%s bank=%s sos=%s nopro=%s pub=%s | verify=%s/%s factor=%s | elig %s→%s cands=%s/%s monitor=%s | owned=%s deny=%s score=%s hidden=%s status=%s | export %s publish=%s rows=%s hash=%s sent=%s | recv=%s prev=%s imp=%s score=%s again=%s/%s replace=%s hist=%s/%s cancel=%s | rc %s/%s/%s/%s=%s released-import=%s/%s | summary=%s count=%s',
               v_office, w_cbt, w_res, w_cbt2, r_bank, r_sos, r_nopro, v_pub, v_right = app, v_wrong, v_factor, e_before, e_after, n_cand, n_elig, m_cand, v_owned, r_deny, v_score, v_hidden, v_status,
               r_unapproved, r_publish, v_rows, length(v_hash), v_sent, v_recv, v_prev, imp.applied, v_app_score, imp2.applied, imp2.unchanged, imp3.replaced, v_hist, v_hist_prev, r_cancel,
               rc_closed, rc_unrel, rc_wrong, rc_rel, rc_score, imp4.released, imp4.replaced, v_summary, v_count));
END $$;

-- ── V388. The Post-UTME CBT door by the JAMB registration number alone: NONE is the default and opens the door on the JAMB number,
--          an unknown number is still refused; the result-checking page still asks for the application number; the setting accepts
--          NONE and refuses anything else ──
DO $$
DECLARE S text := '9963/9964'; who uuid := gen_random_uuid(); cand uuid := gen_random_uuid(); acct uuid := gen_random_uuid(); app uuid := gen_random_uuid();
        cr uuid := gen_random_uuid(); batch uuid := gen_random_uuid(); q1 uuid := gen_random_uuid(); q2 uuid := gen_random_uuid();
        ex assessment.cbt_exam; ex2 assessment.cbt_exam; rc record;
        v_default text; v_factor text; v_alone uuid; v_null uuid; v_unknown uuid; v_strict uuid; v_rfactor text; rc_alone text; rc_number text; r_none text; r_bogus text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'ict', true); PERFORM set_config('moaum.reason', 'CHECK V388', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9963-10-01', date '9964-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO assessment.question (id, putme_session, stem, options, answer, kind, marks) VALUES
            (q1, S, 'one', '["a","b","c","d"]', 1, 'MCQ', 1), (q2, S, 'two', '["a","b","c","d"]', 2, 'MCQ', 1);
        PERFORM pg_temp.moderated();
        INSERT INTO admissions.caps_batch (id, session, source, list_kind, file_sha256, rows_read, downloaded_on, uploaded_by, uploaded_office)
        VALUES (batch, S, 'CAPS_DOWNLOAD', 'UTME', '\xB388'::bytea, 1, current_date, who, 'academic');
        INSERT INTO admissions.caps_row (id, batch_id, session, jamb_reg_no, raw, surname, other_names, jamb_code, aggregate, entry_mode, sex, state_of_origin, lga)
        VALUES (cr, batch, S, '20639630001', '{"Subject1":"Use of English","Subject2":"Lit. in English","Subject3":"Christian Rel. Know","Subject4":"Government"}'::jsonb, 'CHECKJAMB', 'Cand', 'C00066', 250, 'UTME', 'F', 'Benue', 'Makurdi');
        INSERT INTO admissions.candidate (id, session, jamb_reg_no, surname, other_names, programme, entry_mode, entry_level, offer_state, admitted_from)
        VALUES (cand, S, '20639630001', 'CHECKJAMB', 'Cand', (SELECT name FROM ref.programme WHERE code = 'C00066'), 'UTME', 100, 'PROPOSED', cr);
        INSERT INTO admissions.applicant_account (id, session, candidate_id, jamb_key, email, phone, password_hash)
        VALUES (acct, S, cand, '20639630001', 'checkjamb@example.com', '08031234568', crypt('x', gen_salt('bf', 12)));
        INSERT INTO admissions.application (id, account_id, candidate_id, session, application_no, fee_confirmed_at, submitted_at)
        VALUES (app, acct, cand, S, 'APP/63/000001', now(), now());
        INSERT INTO admissions.screening_exam_programme (session, programme_code) VALUES (S, 'C00066');
        -- (1) an examination made without a word on the door asks for the JAMB number alone
        ex := assessment.cbt_new_putme_exam(S, 'Check JAMB alone', 'read', 30, 2, 'FIXED', false, false, 0, 1, 'STANDARD', 'LAB', 3, 'WARN', 'DENY', now() - interval '1 minute', now() + interval '2 hours');
        v_default := ex.putme_verify;
        INSERT INTO assessment.cbt_exam_question (exam_id, question_id, ordinal) VALUES (ex.id, q1, 1), (ex.id, q2, 2);
        ex := assessment.cbt_exam_action(ex.id, 'publish', NULL);
        -- (2) the door: the JAMB number alone; an unknown number refused; the stricter factor still needs its proof
        v_factor := admissions.putme_cbt_factor(S);
        v_alone := admissions.putme_cbt_verify(S, '20639630001', '');
        v_null := admissions.putme_cbt_verify(S, ' 20639630001 ', NULL);
        v_unknown := admissions.putme_cbt_verify(S, '20639639999', '');
        v_strict := admissions.putme_verify_as(S, '20639630001', '', 'APPLICATION_NO');
        -- (3) the result-checking page asks for the application number
        v_rfactor := admissions.putme_result_factor(S);
        PERFORM policy.window_act('POST_UTME_RESULT_CHECKING', S, NULL, 'OPEN', NULL, NULL, NULL, false, 'check', who, 'ict');
        SELECT * INTO rc FROM admissions.putme_result_check(S, '20639630001', ''); rc_alone := rc.outcome;
        SELECT * INTO rc FROM admissions.putme_result_check(S, '20639630001', 'APP/63/000001'); rc_number := rc.outcome;
        -- (4) the setting accepts NONE and refuses anything else
        ex2 := assessment.cbt_new_putme_exam(S, 'Check JAMB alone 2', 'read', 30, 2, 'FIXED', false, false, 0, 1, 'STANDARD', 'LAB', 3, 'WARN', 'DENY', now() + interval '1 day', now() + interval '2 days');
        ex2 := assessment.cbt_configure(ex2.id, '{"putmeVerify":"APPLICATION_NO"}'::jsonb);
        ex2 := assessment.cbt_configure(ex2.id, '{"putmeVerify":"none"}'::jsonb); r_none := ex2.putme_verify;
        BEGIN ex2 := assessment.cbt_configure(ex2.id, '{"putmeVerify":"PASSWORD"}'::jsonb); r_bogus := 'ACCEPTED'; EXCEPTION WHEN check_violation THEN r_bogus := split_part(SQLERRM, ':', 1); END;
        RAISE EXCEPTION 'the V388 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V388: the Post-UTME CBT door by the JAMB registration number alone — an examination asks for nothing more by default and the door opens on the JAMB number, an unknown number is refused, a stricter factor still needs its proof; the result-checking page asks for the application number; the setting accepts NONE and refuses anything else',
        coalesce(v_default = 'NONE' AND v_factor = 'NONE' AND v_alone = app AND v_null = app AND v_unknown IS NULL AND v_strict IS NULL
                 AND v_rfactor = 'APPLICATION_NO' AND rc_alone = 'NOT_VERIFIED' AND rc_number = 'NOT_RELEASED' AND r_none = 'NONE' AND r_bogus = 'CBT_SETTING', false),
        format('default=%s factor=%s alone=%s null=%s unknown=%s strict=%s | result factor=%s alone=%s number=%s | setting none=%s bogus=%s',
               v_default, v_factor, v_alone = app, v_null = app, v_unknown, v_strict, v_rfactor, rc_alone, rc_number, r_none, r_bogus));
END $$;

-- ── V386: one course held once — the uploads match the pool, a course in both semesters, the twins merged ──
-- A course taught in both semesters is opened in each and registered once a session; a code written differently, a
-- merged code or a session copy resolves to the course held, and the pool refuses to hold it twice; the structure upload
-- binds the course held; the twins already held are listed, a dry run moves nothing, and the merge by the Registry with a
-- reason moves every class, registration, binding and question to the course kept and leaves the old code an alias of it.
-- The BSU- and MOAU- codes are never merged. The block undoes its own writes.
DO $$
DECLARE who uuid := gen_random_uuid(); S text := '9935/9936'; d_a text; p_a text; stu uuid := gen_random_uuid(); r1 uuid := gen_random_uuid(); r2 uuid := gen_random_uuid();
        n_cls int; c1 uuid; c2 uuid; r_once text; r_both text; v_both boolean; v_res1 text; v_res2 text; v_res3 text; v_res4 text;
        r_twin text; r_copy text; r_taken text; imp record; n_zqk int; v_bound boolean; v_upl_both boolean; n_dups int; v_dup_keep text;
        dry jsonb; n_after_dry int; r_office text; r_reason text; merged jsonb; v_alias text; v_gone boolean; n_cls_keep int; n_q int;
        v_entry_course text; r_merged text; v_res_alias text; r_family text; r_clash text; q_id uuid := gen_random_uuid(); msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.reason', 'check V386', true);
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        SELECT d.code, p.code INTO d_a, p_a FROM ref.department d JOIN ref.programme p ON p.dept_code = d.code AND NOT coalesce(p.archived, false)
         WHERE d.ended_on IS NULL ORDER BY d.code, p.code LIMIT 1;
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9935-10-01', date '9936-08-31') ON CONFLICT (name) DO NOTHING;

        -- (1) a course taught in both semesters: a class in each, registered once a session
        INSERT INTO catalogue.course (code, title, units, semester, both_semesters, level, dept_code, kind, state)
        VALUES ('ZQK 101', 'Check Both Semesters', 2, 1, true, 100, d_a, 'Core', 'LIVE');
        INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES ('ZQK 101', p_a, 100, 'Core');
        PERFORM registration.open_course_registration(S, 1);
        PERFORM registration.open_course_registration(S, 2);
        SELECT count(*) INTO n_cls FROM catalogue.offering WHERE course_code = 'ZQK 101' AND session = S AND stream = 'REGULAR';
        SELECT id INTO c1 FROM catalogue.offering WHERE course_code = 'ZQK 101' AND session = S AND semester = 1 AND stream = 'REGULAR';
        SELECT id INTO c2 FROM catalogue.offering WHERE course_code = 'ZQK 101' AND session = S AND semester = 2 AND stream = 'REGULAR';
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, study_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (stu, 'MOAUM/ADM/35/990386', 'MOAUM/CHK/35/0386', 'ZZBOTH386', 'Twice', p_a, 'UTME', 'FULL_TIME', S, 100, 100, 'ACTIVE', now());
        INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, submitted_at)
        VALUES (r1, stu, S, 1, 100, 'SUBMITTED', now()), (r2, stu, S, 2, 100, 'SUBMITTED', now());
        INSERT INTO registration.entry (registration_id, offering_id, units, entry_type, status) VALUES (r1, c1, 2, 'CURRENT', 'REGISTERED');
        BEGIN INSERT INTO registration.entry (registration_id, offering_id, units, entry_type, status) VALUES (r2, c2, 2, 'CURRENT', 'REGISTERED'); r_once := 'SET';
        EXCEPTION WHEN check_violation THEN r_once := split_part(SQLERRM, ':', 1); END;
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state) VALUES ('ZQK 301', 'Check Third Semester', 2, 3, 300, d_a, 'Core', 'LIVE');
        BEGIN PERFORM catalogue.update_course('ZQK 301', 'Check Third Semester', 2, 3, 300, 'Core', true); r_both := 'SET';
        EXCEPTION WHEN check_violation THEN r_both := split_part(SQLERRM, ':', 1); END;
        PERFORM catalogue.update_course('ZQK 301', 'Check Third Semester', 2, 2, 300, 'Core', true);
        SELECT both_semesters INTO v_both FROM catalogue.course WHERE code = 'ZQK 301';

        -- (2) a code resolves to the course held; the pool refuses a second record of it
        v_res1 := catalogue.resolve_course_code('zqk101');
        v_res2 := catalogue.resolve_course_code('ZQK-101');
        v_res3 := catalogue.resolve_course_code('ZQK 101 2025/2026');
        v_res4 := catalogue.resolve_course_code('zqk 999');
        BEGIN INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state) VALUES ('ZQK101', 'Check Both Semesters', 2, 1, 100, d_a, 'Core', 'LIVE'); r_twin := 'MADE';
        EXCEPTION WHEN check_violation THEN r_twin := split_part(SQLERRM, ':', 1); END;
        BEGIN INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state) VALUES ('ZQK 101 2025/2026', 'Check Both Semesters', 2, 1, 100, d_a, 'Core', 'LIVE'); r_copy := 'MADE';
        EXCEPTION WHEN check_violation THEN r_copy := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM catalogue.rename_course('ZQK 301', 'ZQK 101'); r_taken := 'RENAMED';
        EXCEPTION WHEN unique_violation THEN r_taken := 'TAKEN'; WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_taken := split_part(msg, ':', 1); END;

        -- (3) the structure upload binds the course held, however written; a semester may be both
        SELECT * INTO imp FROM catalogue.import_courses_rows(p_a, jsonb_build_array(
            jsonb_build_object('code', 'zqk101', 'title', 'Check Both Semesters', 'units', '2', 'level', '200', 'semester', 'Both', 'status', 'C'),
            jsonb_build_object('code', 'ZQK 205', 'title', 'Check Upload Both', 'units', '3', 'level', '200', 'semester', '1 & 2', 'status', 'C')));
        SELECT count(*) INTO n_zqk FROM catalogue.course WHERE catalogue.code_key(code) = 'ZQK101';
        v_bound := EXISTS (SELECT 1 FROM catalogue.course_offer WHERE course_code = 'ZQK 101' AND programme_code = p_a AND level = 200);
        SELECT both_semesters INTO v_upl_both FROM catalogue.course WHERE code = 'ZQK 205';

        -- (4) the twins the pool already held (made as the old data made them), listed and merged
        ALTER TABLE catalogue.course DISABLE TRIGGER trg_course_code_guard;
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state) VALUES
          ('ZQK102', 'Check Twin', 2, 1, 100, d_a, 'Core', 'LIVE'), ('ZQK 102', 'Check Twin', 2, 1, 100, d_a, 'Core', 'LIVE'),
          ('BSU-ZQK 181', 'Check Family', 2, 1, 100, d_a, 'Core', 'LIVE'), ('MOAU-ZQK 181', 'Check Family', 2, 1, 100, d_a, 'Core', 'LIVE');
        ALTER TABLE catalogue.course ENABLE TRIGGER trg_course_code_guard;
        INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES ('ZQK102', p_a, 100, 'Core'), ('ZQK 102', p_a, 100, 'Core'), ('ZQK102', p_a, 200, 'Core');
        INSERT INTO catalogue.offering (id, course_code, session, semester) VALUES (gen_random_uuid(), 'ZQK102', S, 1);
        UPDATE registration.entry SET status = 'DROPPED' WHERE registration_id = r1;
        INSERT INTO registration.entry (registration_id, offering_id, units, entry_type, status)
        SELECT r1, o.id, 2, 'CURRENT', 'REGISTERED' FROM catalogue.offering o WHERE o.course_code = 'ZQK102' AND o.session = S;
        SELECT count(*), min(keep_code) INTO n_dups, v_dup_keep FROM catalogue.duplicate_codes() WHERE merge_code IN ('ZQK102', 'ZQK 102');
        dry := catalogue.merge_course('ZQK 102', 'ZQK102', NULL, true);
        SELECT count(*) INTO n_after_dry FROM catalogue.course WHERE code = 'ZQK102';
        PERFORM set_config('moaum.actor_office', 'hod', true);
        BEGIN PERFORM catalogue.merge_course('ZQK 102', 'ZQK102', 'the check', false); r_office := 'MERGED';
        EXCEPTION WHEN check_violation THEN r_office := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_office', 'registrar', true);
        BEGIN PERFORM catalogue.merge_course('ZQK 102', 'ZQK102', ' ', false); r_reason := 'MERGED';
        EXCEPTION WHEN check_violation THEN r_reason := split_part(SQLERRM, ':', 1); END;
        merged := catalogue.merge_course('ZQK 102', 'ZQK102', 'the old portal wrote it without its space', false);
        SELECT course_code INTO v_alias FROM catalogue.course_alias WHERE alias_code = 'ZQK102';
        v_gone := NOT EXISTS (SELECT 1 FROM catalogue.course WHERE code = 'ZQK102');
        SELECT count(*) INTO n_cls_keep FROM catalogue.offering WHERE course_code = 'ZQK 102' AND session = S;
        SELECT count(*) INTO n_q FROM assessment.question WHERE course_code = 'ZQK 102';
        SELECT o.course_code INTO v_entry_course FROM registration.entry e JOIN catalogue.offering o ON o.id = e.offering_id WHERE e.registration_id = r1 AND e.status = 'REGISTERED';
        v_res_alias := catalogue.resolve_course_code('zqk102');
        BEGIN INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state) VALUES ('ZQK102', 'Check Twin', 2, 1, 100, d_a, 'Core', 'LIVE'); r_merged := 'MADE';
        EXCEPTION WHEN check_violation THEN r_merged := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM catalogue.merge_course('MOAU-ZQK 181', 'BSU-ZQK 181', 'the check', false); r_family := 'MERGED';
        EXCEPTION WHEN check_violation THEN r_family := split_part(SQLERRM, ':', 1); END;
        r_clash := (catalogue.merge_course('ZQK 101', 'ZQK 205', 'the check', true))->>'blocked';
        RAISE EXCEPTION 'the V386 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V386: one course held once — a course in both semesters is opened in each and registered once a session; a code written differently, a session copy or a merged code resolves to the course held and the pool refuses to hold it twice; the structure upload binds the course held; the twins already held are listed, a dry run moves nothing, the merge by the Registry with a reason moves the classes, registrations and bindings to the course kept and leaves the old code its alias; the BSU- and MOAU- codes are never merged',
        coalesce(n_cls = 2 AND r_once = 'REGISTRATION_ONCE_A_SESSION' AND r_both = 'CAT_SEMESTER_BOTH' AND v_both
                 AND v_res1 = 'ZQK 101' AND v_res2 = 'ZQK 101' AND v_res3 = 'ZQK 101' AND v_res4 = 'ZQK 999'
                 AND r_twin = 'COURSE_DUPLICATE_CODE' AND r_copy = 'COURSE_SESSION_COPY' AND r_taken = 'TAKEN'
                 AND imp.offers = 2 AND n_zqk = 1 AND v_bound AND v_upl_both
                 AND n_dups = 1 AND v_dup_keep = 'ZQK 102' AND (dry->>'evidence') = 'SAME_CODE_WRITTEN_DIFFERENTLY' AND (dry->>'blocked') IS NULL
                 AND (dry->'moved'->>'catalogue.offering.course_code')::int = 1 AND n_after_dry = 1
                 AND r_office = 'MERGE_OFFICE' AND r_reason = 'MERGE_REASON' AND (merged->'moved'->>'bindingsAlreadyHeld')::int = 1
                 AND v_alias = 'ZQK 102' AND v_gone AND n_cls_keep = 1 AND v_entry_course = 'ZQK 102' AND v_res_alias = 'ZQK 102'
                 AND r_merged = 'COURSE_CODE_MERGED' AND r_family = 'MERGE_FAMILY' AND r_clash LIKE 'MERGE_NOT_SAME%', false),
        format('both: classes=%s once=%s third=%s both=%s | resolve %s/%s/%s/%s | guard twin=%s copy=%s taken=%s | upload offers=%s held=%s bound=%s both=%s | dups=%s keep=%s dry=%s after=%s | merge office=%s reason=%s moved=%s alias=%s gone=%s classes=%s questions=%s entry=%s resolve=%s again=%s family=%s other=%s',
               n_cls, r_once, r_both, v_both, v_res1, v_res2, v_res3, v_res4, r_twin, r_copy, r_taken, imp.offers, n_zqk, v_bound, v_upl_both,
               n_dups, v_dup_keep, dry, n_after_dry, r_office, r_reason, merged->'moved', v_alias, v_gone, n_cls_keep, n_q, v_entry_course, v_res_alias, r_merged, r_family, r_clash));
END $$;

-- ── V387. The Quick Operational Manual: the first edition seeded and published for every office; a person reads only the
--          procedures bound to the keys they act under (the office, the sidebar beside it, everyone) and, for a capability-bound
--          procedure, only with a posting that carries it; a draft is unseen until published; an edit keeps the previous version;
--          the edition steps on every publication and on a release; an archived procedure is restored before it is edited; an
--          unknown office, an empty step and a taken key are refused; readings and acts are on the record ──
DO $$
DECLARE who uuid := gen_random_uuid(); n_seed int; n_unpub int; n_bad_office int; n_student int; n_student_leak int; n_bursar_sign int;
        n_agent int; n_agent_caps int; n_ctx int; n_search int; n_pg int; ed0 text; ed1 text; ed2 text; ed3 text; r manual.procedure; v_seen int; v_seen2 int;
        v_ver int; v_snap int; v_old_title text; r_state text; r_arch text; r_unknown text; r_empty text; r_taken text; n_reorder int; n_views int; n_audit int;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'super', true); PERFORM set_config('moaum.reason', 'CHECK V387', true);
        -- (1) the first edition: seeded, published, bound to offices the portal knows
        SELECT count(*) FILTER (WHERE seeded), count(*) FILTER (WHERE seeded AND state <> 'PUBLISHED') INTO n_seed, n_unpub FROM manual.procedure;
        SELECT count(*) INTO n_bad_office FROM manual.procedure p, unnest(p.offices) o WHERE NOT (o = ANY (manual.known_keys()));
        -- (2) who reads what: a student reads nothing of ICT's or the Bursary's; everyone signs in; a capability gates the CPO's course change
        SELECT count(*) INTO n_student FROM manual.procedures_for(ARRAY['student'], '{}');
        SELECT count(*) INTO n_student_leak FROM manual.procedures_for(ARRAY['student'], '{}') WHERE 'ict' = ANY (offices) OR 'bursar' = ANY (offices);
        SELECT count(*) INTO n_bursar_sign FROM manual.procedures_for(ARRAY['bursar'], '{}') WHERE slug = 'sign-in';
        SELECT count(*) INTO n_agent FROM manual.procedures_for(ARRAY['ictagent'], '{}') WHERE slug = 'cpo-add-course';
        SELECT count(*) INTO n_agent_caps FROM manual.procedures_for(ARRAY['ictagent'], ARRAY['MANAGE_REGISTRATION']) WHERE slug = 'cpo-add-course';
        SELECT count(*) INTO n_ctx FROM manual.context_for(ARRAY['student'], '{}', 's/register') WHERE slug = 'student-register';
        SELECT count(*) INTO n_search FROM manual.search(ARRAY['academic'], '{}', 'matriculation') WHERE slug = 'matric-issue';
        SELECT count(*) INTO n_pg FROM manual.procedures_for(ARRAY['student', 'pgstudent'], '{}') WHERE slug = 'pg-progress';
        -- (3) Manual Management: draft, publish, edit, unpublish, archive, restore; the refusals; the edition; order, readings, audit
        ed0 := manual.edition_text();
        r := manual.save_procedure(NULL, 'check-v387', 'Check', 'Check purpose', 'DASHBOARD', ARRAY['bursar'], '{}', 't/payments', NULL, ARRAY['Open {menu:t/payments}.'], 'Done', 5, who, 'super', 'check');
        SELECT count(*) INTO v_seen FROM manual.procedures_for(ARRAY['bursar'], '{}') WHERE slug = 'check-v387';
        r := manual.set_state(r.id, 'PUBLISH', who, 'super', NULL);
        ed1 := manual.edition_text();
        SELECT count(*) INTO v_seen2 FROM manual.procedures_for(ARRAY['bursar'], '{}') WHERE slug = 'check-v387';
        r := manual.save_procedure(r.id, 'check-v387', 'Check edited', 'Check purpose', 'DASHBOARD', ARRAY['bursar'], '{}', 't/payments', NULL, ARRAY['Open {menu:t/payments}.', 'Click `Export Excel`.'], 'Done', 5, who, 'super', 'edit');
        v_ver := r.version;
        SELECT count(*), max(snapshot ->> 'title') INTO v_snap, v_old_title FROM manual.procedure_version WHERE procedure_id = r.id;
        r := manual.set_state(r.id, 'UNPUBLISH', who, 'super', NULL);
        r_state := r.state;
        r := manual.set_state(r.id, 'ARCHIVE', who, 'super', 'old');
        BEGIN PERFORM manual.save_procedure(r.id, 'check-v387', 'x', 'x', 'DASHBOARD', ARRAY['bursar'], '{}', NULL, NULL, ARRAY['x'], 'x', 5, who, 'super', NULL); r_arch := 'EDITED'; EXCEPTION WHEN check_violation THEN r_arch := split_part(SQLERRM, ':', 1); END;
        r := manual.set_state(r.id, 'RESTORE', who, 'super', NULL);
        BEGIN PERFORM manual.save_procedure(NULL, 'check-v387-b', 'x', 'x', 'DASHBOARD', ARRAY['nobody'], '{}', NULL, NULL, ARRAY['x'], 'x', 5, who, 'super', NULL); r_unknown := 'SAVED'; EXCEPTION WHEN check_violation THEN r_unknown := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM manual.save_procedure(NULL, 'check-v387-c', 'x', 'x', 'DASHBOARD', ARRAY['bursar'], '{}', NULL, NULL, ARRAY['x', ' '], 'x', 5, who, 'super', NULL); r_empty := 'SAVED'; EXCEPTION WHEN check_violation THEN r_empty := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM manual.save_procedure(NULL, 'sign-in', 'x', 'x', 'DASHBOARD', ARRAY['bursar'], '{}', NULL, NULL, ARRAY['x'], 'x', 5, who, 'super', NULL); r_taken := 'SAVED'; EXCEPTION WHEN check_violation THEN r_taken := split_part(SQLERRM, ':', 1); END;
        ed2 := manual.edition_text();
        ed3 := manual.bump_edition(who, 'super', 'release', true);
        n_reorder := manual.reorder(ARRAY(SELECT id FROM manual.procedure WHERE 'bursar' = ANY (offices) ORDER BY title LIMIT 3), who, 'super');
        PERFORM manual.record_view(who, 'super', 'OPEN', NULL, NULL); PERFORM manual.record_view(who, 'super', 'PROCEDURE', r.id, NULL);
        SELECT count(*) INTO n_views FROM manual.view WHERE person_id = who;
        SELECT count(*) INTO n_audit FROM audit.entries WHERE actor_id = who AND subject_type ILIKE '%procedure%';
        RAISE EXCEPTION 'the V387 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V387: the Quick Operational Manual — seeded and published for every office; read by the keys a person acts under and a posting''s capability; a draft unseen until published; an edit versioned; the edition stepping; an archived procedure restored before edited; unknown office, empty step and taken key refused; readings and acts recorded',
        coalesce(n_seed >= 200 AND n_unpub = 0 AND n_bad_office = 0
                 AND n_student >= 20 AND n_student_leak = 0 AND n_bursar_sign = 1 AND n_agent = 0 AND n_agent_caps = 1 AND n_ctx = 1 AND n_search = 1 AND n_pg = 1
                 AND ed0 ~ '^[0-9]+\.[0-9]+$' AND v_seen = 0 AND v_seen2 = 1 AND ed1 = split_part(ed0, '.', 1) || '.' || (split_part(ed0, '.', 2)::int + 1) AND v_ver = 2 AND v_snap = 1 AND v_old_title = 'Check' AND r_state = 'DRAFT'
                 AND r_arch = 'MANUAL_ARCHIVED' AND r_unknown = 'MANUAL_OFFICE_UNKNOWN' AND r_empty = 'MANUAL_STEP_EMPTY' AND r_taken = 'MANUAL_SLUG_TAKEN'
                 AND ed2 = split_part(ed0, '.', 1) || '.' || (split_part(ed0, '.', 2)::int + 5) AND ed3 = (split_part(ed0, '.', 1)::int + 1) || '.0' AND n_reorder = 3 AND n_views = 2 AND n_audit >= 3, false),
        format('seed=%s unpublished=%s bad_office=%s | student=%s leaks=%s bursar_signin=%s agent=%s/%s ctx=%s search=%s pg=%s | edition %s→%s→%s→%s seen=%s/%s ver=%s snap=%s/%s state=%s | arch=%s unknown=%s empty=%s taken=%s | reorder=%s views=%s audit=%s',
               n_seed, n_unpub, n_bad_office, n_student, n_student_leak, n_bursar_sign, n_agent, n_agent_caps, n_ctx, n_search, n_pg, ed0, ed1, ed2, ed3, v_seen, v_seen2, v_ver, v_snap, v_old_title, r_state,
               r_arch, r_unknown, r_empty, r_taken, n_reorder, n_views, n_audit));
END $$;

-- ── V389: postgraduate coursework on the University's engines ──
-- A PG course is a course of the pool, held once whatever the programmes that take it and bound to each at its level (a
-- deficiency course earning no credit); a PG student is the stream PG, on the School's calendar and gate and the PG
-- windows; the School opens its classes in its own session (no other office), and the full-time opening leaves them be;
-- the student registers on the engine on the School's classes only, and the old registration refuses new registrations;
-- a PG class is read on the School's scale; the PG GPA reads the old coursework (without the deficiency course); the
-- School's students are told once when registration opens; the next steps are the record's. The block undoes its writes.
DO $$
DECLARE who uuid := gen_random_uuid(); S text := '9931/9932'; pa text; pb text; lvl int; stu uuid := gen_random_uuid(); ft uuid := gen_random_uuid();
        crs1 uuid := gen_random_uuid(); crs2 uuid := gen_random_uuid(); crs3 uuid := gen_random_uuid(); n_pool int; n_bind int; v_basis text; v_mapped text;
        v_stream text; v_wt text; v_cal text; r_gate0 text; r_office text; n_open int; v_gate text; v_menu int; v_regular int; c1 uuid;
        r1 uuid := gen_random_uuid(); r2 uuid := gen_random_uuid(); r_ft text; r_moved text; v_scope text; v_pg_f text; v_ug_d text;
        lreg uuid := gen_random_uuid(); le1 uuid := gen_random_uuid(); le2 uuid := gen_random_uuid(); v_cgpa numeric; n_res int;
        n_told int; n_told2 int; n_opened int; steps jsonb; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.reason', 'check V389', true);
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        SELECT code INTO pa FROM ref.programme WHERE category = 'POST GRADUATE' AND NOT coalesce(archived, false) ORDER BY code LIMIT 1;
        SELECT code INTO pb FROM ref.programme WHERE category = 'POST GRADUATE' AND NOT coalesce(archived, false) AND code <> pa ORDER BY code LIMIT 1;
        SELECT admissions.pg_award_level(pg_award) INTO lvl FROM ref.programme WHERE code = pa;
        INSERT INTO iam.person (id, staff_number, surname, given_names, email) VALUES (who, 'CHECK/V389/P', 'ZZPGCHECK', 'Invented', NULL);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9931-10-01', date '9932-08-31'),
               (gen_random_uuid(), '9929/9930', date '9929-10-01', date '9930-08-31') ON CONFLICT (name) DO NOTHING;
        UPDATE admissions.pg_academic_session SET state = 'PLANNED' WHERE state = 'CURRENT';
        INSERT INTO admissions.pg_academic_session (name, starts_on, ends_on, semesters, state) VALUES (S, date '9931-10-01', date '9932-08-31', 2, 'CURRENT');
        INSERT INTO admissions.pg_semester (session, number, registration_opens, registration_closes, lectures_from, state)
        VALUES (S, 1, current_date - 1, current_date + 10, current_date, 'OPEN');

        -- (1) the courses into the pool: one course for the code however many programmes, a deficiency course bound as such
        INSERT INTO admissions.pg_course (id, programme_code, code, title, units, kind, semester) VALUES
          (crs1, pa, 'ZPG 801', 'Check PG Core', 3, 'CORE', 1), (crs2, pb, 'ZPG801', 'Check PG Core', 3, 'CORE', 1),
          (crs3, pa, 'ZPG 702', 'Check PG Deficiency', 2, 'DEFICIENCY', 1);
        PERFORM catalogue.pg_bind_course(pa, 'ZPG 801', 'Check PG Core', 3, 1, 'CORE');
        PERFORM catalogue.pg_bind_course(pb, 'zpg801', 'Check PG Core', 3, 1, 'CORE');
        v_mapped := catalogue.pg_bind_course(pa, 'ZPG 702', 'Check PG Deficiency', 2, 1, 'DEFICIENCY');
        SELECT count(*) INTO n_pool FROM catalogue.course WHERE catalogue.code_key(code) = 'ZPG801';
        SELECT count(*) INTO n_bind FROM catalogue.course_offer WHERE course_code = 'ZPG 801' AND programme_code IN (pa, pb);
        SELECT basis INTO v_basis FROM catalogue.course_offer WHERE course_code = 'ZPG 702' AND programme_code = pa;

        -- (2) the PG student: the stream PG, the School's calendar and the PG windows
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (stu, 'MOAUM/ADM/31/990389', 'MOAUM/CHK/31/0389', 'ZZPG389', 'Coursework', pa, 'POSTGRADUATE', S, lvl, lvl, 'ACTIVE', now()),
               (ft, 'MOAUM/ADM/31/990390', 'MOAUM/CHK/31/0390', 'ZZFT389', 'Daytime', (SELECT code FROM ref.programme WHERE category IS DISTINCT FROM 'POST GRADUATE' AND NOT coalesce(archived, false) ORDER BY code LIMIT 1),
                'UTME', S, 100, 100, 'ACTIVE', now());
        INSERT INTO people.student_contact (student_id, phone, email, updated_at) VALUES (stu, '08030000389', 'zzpg389@example.invalid', now()) ON CONFLICT (student_id) DO NOTHING;
        v_stream := people.student_stream(stu);
        v_wt := policy.window_type_for(stu, 'COURSE_REGISTRATION');
        SELECT calendar INTO v_cal FROM registration.calendar_semester(stu, S, 1);
        r_gate0 := registration.registration_gate(stu, S, 1);

        -- (3) the School opens its classes; no other office may; the full-time opening leaves them be
        PERFORM set_config('moaum.actor_office', 'cce', true);
        BEGIN PERFORM catalogue.pg_open_classes(S, 1); r_office := 'OPENED';
        EXCEPTION WHEN check_violation THEN r_office := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_office', 'pgschool', true);
        n_open := catalogue.pg_open_classes(S, 1);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        PERFORM registration.open_course_registration(S, 1);
        SELECT count(*) INTO v_regular FROM catalogue.offering WHERE course_code = 'ZPG 801' AND session = S AND stream = 'REGULAR';
        SELECT id INTO c1 FROM catalogue.offering WHERE course_code = 'ZPG 801' AND session = S AND semester = 1 AND stream = 'PG';
        v_gate := registration.registration_gate(stu, S, 1);
        SELECT count(*) INTO v_menu FROM registration.student_menu(stu, S, 1) m WHERE m.offering_id = c1;

        -- (4) registration on the engine, on the School's class only; the old registration refuses
        INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, submitted_at) VALUES (r1, stu, S, 1, lvl, 'SUBMITTED', now()), (r2, ft, S, 1, 100, 'DRAFT', NULL);
        INSERT INTO registration.entry (registration_id, offering_id, units, entry_type, status) VALUES (r1, c1, 3, 'CURRENT', 'REGISTERED');
        BEGIN INSERT INTO registration.entry (registration_id, offering_id, units, entry_type, status) VALUES (r2, c1, 3, 'CURRENT', 'REGISTERED'); r_ft := 'REGISTERED';
        EXCEPTION WHEN check_violation THEN r_ft := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM admissions.pg_register(stu, S, 1, 'FULL_TIME', ARRAY[crs1]); r_moved := 'REGISTERED';
        EXCEPTION WHEN check_violation THEN r_moved := split_part(SQLERRM, ':', 1); END;

        -- (5) the School's scale on its classes; the PG CGPA reads the old coursework without the deficiency course
        v_scope := policy.grading_scope(c1);
        SELECT grade INTO v_pg_f FROM policy.grade_of(45, current_date, 'POSTGRADUATE');
        SELECT grade INTO v_ug_d FROM policy.grade_of(45, current_date, 'UNIVERSITY');
        INSERT INTO admissions.pg_registration (id, student_id, session, semester, mode, state, endorsed_by, endorsed_at) VALUES (lreg, stu, '9929/9930', 1, 'FULL_TIME', 'ENDORSED', who, now());
        INSERT INTO admissions.pg_registration_entry (id, registration_id, course_id) VALUES (le1, lreg, crs1), (le2, lreg, crs3);
        PERFORM admissions.pg_record_score(le1, 30, 45, who);   -- 75: A
        PERFORM admissions.pg_record_score(le2, 10, 20, who);   -- 30: F, on a deficiency course
        v_cgpa := admissions.pg_cgpa(stu);
        SELECT count(*) INTO n_res FROM admissions.pg_course_results(stu);

        -- (6) the School's students told once that registration is open; the next steps from the record
        n_told := admissions.pg_tell_registration();
        n_told2 := admissions.pg_tell_registration();
        SELECT count(*) INTO n_opened FROM admissions.pg_registration_notice WHERE session = S AND semester = 1 AND kind = 'OPENED';
        steps := admissions.pg_next_steps(stu);
        RAISE EXCEPTION 'the V389 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V389: postgraduate coursework on the University''s engines — a PG course is one course of the pool bound to each programme (a deficiency course as Deficiency); a PG student is the stream PG on the School''s calendar, gate and windows; only the School opens its classes and the full-time opening leaves them be; registration is on the engine on the School''s class only and the old registration refuses; a PG class is read on the School''s scale; the PG CGPA reads the old coursework without the deficiency course; the students are told once that registration opens; the next steps are the record''s',
        coalesce(n_pool = 1 AND n_bind = 2 AND v_basis = 'Deficiency' AND v_mapped = 'ZPG 702'
                 AND v_stream = 'PG' AND v_wt = 'PG_COURSE_REGISTRATION' AND v_cal = 'PG' AND r_gate0 LIKE '%classes%'
                 AND r_office = 'PG_OFFICE' AND n_open >= 2 AND v_regular = 0 AND c1 IS NOT NULL AND v_gate IS NULL AND v_menu = 1
                 AND r_ft = 'REGISTRATION_STREAM' AND r_moved = 'PG_REGISTRATION_MOVED'
                 AND v_scope = 'POSTGRADUATE' AND v_pg_f = 'F' AND v_ug_d = 'D' AND v_cgpa = 5.00 AND n_res = 2
                 AND n_told >= 1 AND n_told2 = 0 AND n_opened = 1
                 AND jsonb_path_exists(steps, '$[*] ? (@.key == "REGISTRATION" && @.state == "WAITING")')
                 AND jsonb_path_exists(steps, '$[*] ? (@.key == "FEES")') AND jsonb_path_exists(steps, '$[*] ? (@.key == "MATRICULATION" && @.state == "DONE")'), false),
        format('pool=%s bind=%s basis=%s mapped=%s | stream=%s window=%s calendar=%s gate0=%s | office=%s opened=%s regular=%s gate=%s menu=%s | ft=%s moved=%s | scope=%s pg45=%s ug45=%s cgpa=%s results=%s | told=%s/%s opened=%s | steps=%s',
               n_pool, n_bind, v_basis, v_mapped, v_stream, v_wt, v_cal, r_gate0, r_office, n_open, v_regular, v_gate, v_menu, r_ft, r_moved,
               v_scope, v_pg_f, v_ug_d, v_cgpa, n_res, n_told, n_told2, n_opened, left(steps::text, 400)));
END $$;

-- ── V390. A fee reference is drawn until a free one is found: the four random digits that make MOAUM-APP-000001-dddd may repeat
--          another application's reference (the last six digits are the session's running number, shared across sessions); the draw
--          that lands on a taken reference is drawn again, the format unchanged, and the applicant is never answered with a clash ──
DO $$
DECLARE S text := '9962/9963'; who uuid := gen_random_uuid(); cand uuid := gen_random_uuid(); acct uuid := gen_random_uuid(); app uuid := gen_random_uuid();
        cr uuid := gen_random_uuid(); batch uuid := gen_random_uuid(); other uuid := gen_random_uuid(); v_first int; v_taken text; v_ref text; n_refs int; v_amount numeric;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'ict', true); PERFORM set_config('moaum.reason', 'CHECK V390', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9962-10-01', date '9963-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO admissions.caps_batch (id, session, source, list_kind, file_sha256, rows_read, downloaded_on, uploaded_by, uploaded_office)
        VALUES (batch, S, 'CAPS_DOWNLOAD', 'UTME', '\xB390'::bytea, 1, current_date, who, 'academic');
        INSERT INTO admissions.caps_row (id, batch_id, session, jamb_reg_no, raw, surname, other_names, jamb_code, aggregate, entry_mode, sex, state_of_origin, lga)
        VALUES (cr, batch, S, '20629620001', '{}'::jsonb, 'CHECKFEEREF', 'Cand', 'C00066', 250, 'UTME', 'F', 'Benue', 'Makurdi');
        INSERT INTO admissions.candidate (id, session, jamb_reg_no, surname, other_names, programme, entry_mode, entry_level, offer_state, admitted_from)
        VALUES (cand, S, '20629620001', 'CHECKFEEREF', 'Cand', (SELECT name FROM ref.programme WHERE code = 'C00066'), 'UTME', 100, 'PROPOSED', cr);
        INSERT INTO admissions.applicant_account (id, session, candidate_id, jamb_key, email, phone, password_hash)
        VALUES (acct, S, cand, '20629620001', 'checkfeeref@example.com', '08031234567', crypt('x', gen_salt('bf', 12)));
        INSERT INTO admissions.application (id, account_id, candidate_id, session, application_no) VALUES (app, acct, cand, S, 'APP/62/000001');
        -- the draw is the session's random(): seeded, the first draw is known, so a reference another application took with those four
        -- digits is put in its way; the function must step past it to the second draw
        PERFORM setseed(0.4321);
        v_first := floor(random() * 10000)::int;
        v_taken := 'MOAUM-APP-000001-' || lpad(v_first::text, 4, '0');
        -- (another application of a session whose running number ends the same way holds that reference already)
        INSERT INTO admissions.candidate (id, session, jamb_reg_no, surname, other_names, programme, entry_mode, entry_level, offer_state, admitted_from)
        VALUES (other, S, '20629620002', 'CHECKFEEREF', 'Other', (SELECT name FROM ref.programme WHERE code = 'C00066'), 'UTME', 100, 'PROPOSED', cr);
        INSERT INTO admissions.applicant_account (id, session, candidate_id, jamb_key, email, phone, password_hash)
        VALUES (gen_random_uuid(), S, other, '20629620002', 'checkfeeref2@example.com', '08031234568', crypt('x', gen_salt('bf', 12)));
        INSERT INTO admissions.application (id, account_id, candidate_id, session, application_no)
        SELECT gen_random_uuid(), a.id, other, S, 'APP/61/000001' FROM admissions.applicant_account a WHERE a.candidate_id = other;
        INSERT INTO admissions.fee_reference (id, application_id, kind, reference, amount, expires_at)
        SELECT gen_random_uuid(), x.id, 'APPLICATION', v_taken, 1, now() + interval '1 day' FROM admissions.application x WHERE x.candidate_id = other;
        PERFORM setseed(0.4321);
        v_ref := admissions.new_fee_reference(app, 'APPLICATION');
        SELECT count(*), max(amount) INTO n_refs, v_amount FROM admissions.fee_reference WHERE application_id = app;
        RAISE EXCEPTION 'the V390 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V390: a fee reference landing on a taken one is drawn again — the format kept, the amount the session''s, the applicant never answered with a clash',
        coalesce(v_ref IS NOT NULL AND v_ref <> v_taken AND v_ref ~ '^MOAUM-APP-000001-[0-9]{4}$' AND n_refs = 1 AND v_amount > 0, false),
        format('taken=%s drawn=%s refs=%s amount=%s', v_taken, v_ref, n_refs, v_amount));
END $$;

-- ── V391: a postgraduate student owes only the School's fee lines ──
-- A line for every student (no level, entry mode, programme or postgraduate group) reaches the full-time student and never
-- the postgraduate one; a line naming a postgraduate level, the POSTGRADUATE entry mode, the programme or the Postgraduate
-- group reaches the postgraduate student and not the full-time one — read alike by the charges, the session total, the
-- semester's due, the stated test and the Bursary's bulk positions. While only the full-time line stands, the PG student's
-- own submission refuses on the fees not stated; once the School's lines are stated, the student registered in that
-- session is on its matriculation list, unpaid. The block undoes its writes.
DO $$
DECLARE who uuid := gen_random_uuid(); S text := '9941/9942'; pa text; fac text; ug text; lvl int; pg uuid := gen_random_uuid(); ft uuid := gen_random_uuid();
        st0 boolean; ft_lines0 int; pg_lines int; pg_total numeric; pg_due numeric; pg_bulk numeric; st1 boolean; reg uuid := gen_random_uuid(); r_submit text;
        ft_lines int; ft_total numeric; ft_bulk numeric; m1 record; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.reason', 'check V391', true);
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        SELECT code, faculty_code, admissions.pg_award_level(pg_award) INTO pa, fac, lvl FROM ref.programme
         WHERE category = 'POST GRADUATE' AND NOT coalesce(archived, false) AND faculty_code IS NOT NULL ORDER BY code LIMIT 1;
        SELECT code INTO ug FROM ref.programme WHERE category = 'UNDER GRADUATE' AND NOT coalesce(archived, false) ORDER BY code LIMIT 1;
        INSERT INTO iam.person (id, staff_number, surname, given_names, email) VALUES (who, 'CHECK/V391/P', 'ZZFEECHECK', 'Invented', NULL);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9941-10-01', date '9942-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status)
        VALUES (pg, 'MOAUM/ADM/41/990391', 'ZZPG391', 'Fees', pa, 'POSTGRADUATE', S, lvl, lvl, 'ADMITTED'),
               (ft, 'MOAUM/ADM/41/990392', 'ZZFT391', 'Fees', ug, 'UTME', S, 100, 100, 'ADMITTED');

        -- (1) the full-time line alone: it reaches the full-time student, never the postgraduate one
        INSERT INTO finance.fee_schedule (session, item, amount, level) VALUES (S, 'Check: every student', 1000, NULL);
        st0 := finance.fee_stated(pg, S);
        SELECT count(*) INTO ft_lines0 FROM finance.charges_of_as(ft, S, ARRAY['FEE'], NULL);
        -- the student's own submission refuses: the School's fees are not stated, and the full-time line does not stand in
        INSERT INTO registration.course_registration (id, student_id, session, semester, level, status) VALUES (reg, pg, S, 1, lvl, 'DRAFT');
        BEGIN PERFORM registration.student_submit(reg); r_submit := 'SUBMITTED';
        EXCEPTION WHEN check_violation THEN r_submit := split_part(SQLERRM, ':', 1); END;

        -- (2) the lines addressed to a postgraduate student: a level, the Postgraduate group, the entry mode, the programme
        INSERT INTO finance.fee_schedule (session, item, amount, level, entry_mode, programme_code, fee_group) VALUES
          (S, 'Check: PG level', 2000, lvl, NULL, NULL, NULL), (S, 'Check: PG group', 300, NULL, NULL, NULL, 'PG'),
          (S, 'Check: PG entry mode', 40, NULL, 'POSTGRADUATE', NULL, NULL), (S, 'Check: the programme', 5, NULL, NULL, pa, NULL);
        st1 := finance.fee_stated(pg, S);
        SELECT count(*) INTO pg_lines FROM finance.charges_of_as(pg, S, ARRAY['FEE'], NULL);
        pg_total := finance.session_fee_total(pg, S);
        pg_due := finance.due_for_semester(pg, S, 1);
        SELECT due INTO pg_bulk FROM finance.session_fee_positions(S) WHERE student_id = pg;
        SELECT count(*) INTO ft_lines FROM finance.charges_of_as(ft, S, ARRAY['FEE'], NULL);
        ft_total := finance.session_fee_total(ft, S);
        SELECT due INTO ft_bulk FROM finance.session_fee_positions(S) WHERE student_id = ft;
        UPDATE registration.course_registration SET status = 'APPROVED', approved_at = now() WHERE id = reg;
        SELECT registered, paid, eligible, reason INTO m1 FROM people.matric_candidates(S, fac) WHERE student_id = pg;
        RAISE EXCEPTION 'the V391 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V391 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V391: a postgraduate student owes only the School''s fee lines — a line for every student reaches the full-time student and never the postgraduate one; a line naming a PG level, the Postgraduate group, the POSTGRADUATE entry mode or the programme reaches the PG student and not the full-time one, read alike by the charges, the session total, the semester''s due, the stated test and the bulk positions; with only the full-time line the PG student''s submission refuses on the fees not stated; registered in the School''s session, the student is on its matriculation list',
        coalesce(st0 = false AND ft_lines0 = 1 AND r_submit = 'REG_FEES_NOT_STATED'
                 AND st1 AND pg_lines = 4 AND pg_total = 2345 AND pg_due = 2345 AND pg_bulk = 2345
                 AND ft_lines = 1 AND ft_total = 1000 AND ft_bulk = 1000
                 AND m1.registered AND NOT m1.paid AND m1.reason LIKE '%not settled%', false),
        format('stated0=%s ft0=%s | submit=%s | stated1=%s pg lines=%s total=%s due=%s bulk=%s | ft lines=%s total=%s bulk=%s | list1 reg=%s paid=%s reason=%s',
               st0, ft_lines0, r_submit, st1, pg_lines, pg_total, pg_due, pg_bulk, ft_lines, ft_total, ft_bulk,
               m1.registered, m1.paid, m1.reason));
END $$;

-- ── V393: postgraduate fees after V391, read only ──
-- A PG student who paid against a full-time line is on the Bursary's review with what they owe, what they paid, the excess
-- and the reference — a full-time student never is; the live PG students with no line stated are listed by level and
-- programme until a PG line reaches them; the School's readiness names its session, its open semester and its classes,
-- and is not ready while a piece is missing. Nothing is changed by any of the three. The block undoes its writes.
DO $$
DECLARE who uuid := gen_random_uuid(); S text := '9951/9952'; pa text; ug text; lvl int; pg uuid := gen_random_uuid(); pg2 uuid := gen_random_uuid(); ft uuid := gen_random_uuid();
        r0 record; n_ft0 int; u0 bigint; r1 record; u1 bigint; rd jsonb; n_refs0 int; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.reason', 'check V393', true);
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        SELECT code, admissions.pg_award_level(pg_award) INTO pa, lvl FROM ref.programme
         WHERE category = 'POST GRADUATE' AND NOT coalesce(archived, false) AND faculty_code IS NOT NULL ORDER BY code LIMIT 1;
        SELECT code INTO ug FROM ref.programme WHERE category = 'UNDER GRADUATE' AND NOT coalesce(archived, false) ORDER BY code LIMIT 1;
        INSERT INTO iam.person (id, staff_number, surname, given_names, email) VALUES (who, 'CHECK/V393/P', 'ZZFEEREVIEW', 'Invented', NULL);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9951-10-01', date '9952-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (pg, 'MOAUM/ADM/51/990393', NULL, 'ZZPG393', 'Review', pa, 'POSTGRADUATE', S, lvl, lvl, 'ADMITTED', NULL),
               (pg2, 'MOAUM/ADM/51/990394', 'MOAUM/CHK/51/0394', 'ZZPG393', 'Unstated', pa, 'POSTGRADUATE', S, lvl, lvl, 'ACTIVE', now()),
               (ft, 'MOAUM/ADM/51/990395', NULL, 'ZZFT393', 'Review', ug, 'UTME', S, 100, 100, 'ADMITTED', NULL);

        -- (1) a full-time line, and both a PG and a full-time student paid against it
        INSERT INTO finance.fee_schedule (session, item, amount, level) VALUES (S, 'Check: every student', 1000, NULL);
        INSERT INTO finance.payment_reference (student_id, session, reference, purpose, amount, expires_at, confirmed_at, confirmed_by, channel, receipt_no)
        VALUES (pg, S, 'CHK-V393-PG', 'School fees ' || S, 1000, now() + interval '1 day', now(), who, 'BANK', 'CHK-RCPT-V393-PG'),
               (ft, S, 'CHK-V393-FT', 'School fees ' || S, 1000, now() + interval '1 day', now(), who, 'BANK', 'CHK-RCPT-V393-FT');
        SELECT due, paid, excess INTO r0 FROM finance.pg_fee_review(S) WHERE student_id = pg;
        SELECT jsonb_array_length(payments) INTO n_refs0 FROM finance.pg_fee_review(S) WHERE student_id = pg AND payments @> '[{"reference": "CHK-V393-PG"}]';
        SELECT count(*) INTO n_ft0 FROM finance.pg_fee_review(S) WHERE student_id = ft;
        SELECT students INTO u0 FROM finance.pg_unstated(S) WHERE level = lvl AND programme_code = pa;

        -- (2) the Bursary states the School's line for the level: the excess shrinks, nobody of the programme is unstated
        INSERT INTO finance.fee_schedule (session, item, amount, level) VALUES (S, 'Check: PG level', 600, lvl);
        SELECT due, paid, excess INTO r1 FROM finance.pg_fee_review(S) WHERE student_id = pg;
        SELECT coalesce(sum(students), 0) INTO u1 FROM finance.pg_unstated(S) WHERE level = lvl AND programme_code = pa;

        -- (3) the School's readiness: its current session and open semester, no class yet, so not ready
        UPDATE admissions.pg_academic_session SET state = 'PLANNED' WHERE state = 'CURRENT';
        INSERT INTO admissions.pg_academic_session (name, starts_on, ends_on, semesters, state) VALUES (S, date '9951-10-01', date '9952-08-31', 2, 'CURRENT');
        INSERT INTO admissions.pg_semester (session, number, registration_opens, registration_closes, lectures_from, state)
        VALUES (S, 1, current_date - 1, current_date + 10, current_date, 'OPEN');
        rd := admissions.pg_readiness();
        RAISE EXCEPTION 'the V393 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V393 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V393: postgraduate fees after V391, read only — a PG student who paid against a full-time line is on the Bursary''s review with what they owe, what they paid, the excess and the reference, a full-time student never; the live PG students with no line stated are listed until a PG line reaches them; the School''s readiness names its session, semester and classes and is not ready while a piece is missing',
        coalesce(r0.due = 0 AND r0.paid = 1000 AND r0.excess = 1000 AND n_refs0 = 1 AND n_ft0 = 0 AND u0 = 2
                 AND r1.due = 600 AND r1.excess = 400 AND u1 = 0
                 AND rd->>'session' = S AND (rd->>'current')::boolean AND (rd->>'semester')::int = 1 AND (rd->>'classes')::int = 0
                 AND NOT (rd->>'ready')::boolean, false),
        format('review0 due=%s paid=%s excess=%s refs=%s ft=%s unstated0=%s | review1 due=%s excess=%s unstated1=%s | readiness=%s',
               r0.due, r0.paid, r0.excess, n_refs0, n_ft0, u0, r1.due, r1.excess, u1, rd));
END $$;

-- ── V397: a refused candidate is suggested programmes of the faculty they applied to only ──
DO $$
DECLARE who uuid := gen_random_uuid(); fac text; other text; p_app text; p_same text; p_other text;
        cand uuid := gen_random_uuid(); acct uuid := gen_random_uuid(); app uuid := gen_random_uuid(); run uuid := gen_random_uuid();
        n int; v_same boolean; v_other boolean; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        -- a faculty with two programmes, and a programme of another faculty
        SELECT faculty_code INTO fac FROM ref.programme WHERE faculty_code IS NOT NULL AND NOT archived
         GROUP BY faculty_code HAVING count(*) >= 2 ORDER BY faculty_code LIMIT 1;
        SELECT code INTO p_app FROM ref.programme WHERE faculty_code = fac AND NOT archived ORDER BY code LIMIT 1;
        SELECT code INTO p_same FROM ref.programme WHERE faculty_code = fac AND NOT archived AND code <> p_app ORDER BY code LIMIT 1;
        SELECT code, faculty_code INTO p_other, other FROM ref.programme WHERE faculty_code IS NOT NULL AND faculty_code <> fac AND NOT archived ORDER BY code LIMIT 1;
        INSERT INTO admissions.candidate (id, session, jamb_reg_no, surname, other_names, programme, entry_mode, entry_level, offer_state)
        VALUES (cand, '9940/9941', '994099000001CK', 'CHECKFACULTY', 'Candidate', (SELECT name FROM ref.programme WHERE code = p_app), 'UTME', 100, 'PROPOSED');
        INSERT INTO admissions.applicant_account (id, session, candidate_id, jamb_key, email, phone, password_hash)
        VALUES (acct, '9940/9941', cand, '994099000001CK', 'check.faculty.9940@example.com', '08030000000', 'SET_ON_FIRST_LOGIN');
        INSERT INTO admissions.application (id, account_id, candidate_id, session, application_no) VALUES (app, acct, cand, '9940/9941', 'APP/40/999001');
        INSERT INTO admissions.eligibility_run (id, application_id, candidate_id, session, jamb_key, entry_mode, applied_programme_code, applied_programme, applied_result, trigger_kind)
        VALUES (run, app, cand, '9940/9941', '994099000001CK', 'UTME', p_app, (SELECT name FROM ref.programme WHERE code = p_app), 'NOT_ELIGIBLE', 'SYSTEM');
        -- both eligible; the other faculty's ranked first
        INSERT INTO admissions.eligibility_result (run_id, programme_code, programme, faculty_code, kind, result, checks, ord) VALUES
          (run, p_other, 'another faculty''s programme', other, 'ALTERNATIVE', 'ELIGIBLE', '[]'::jsonb, 1),
          (run, p_same, 'a programme of the same faculty', fac, 'ALTERNATIVE', 'ELIGIBLE', '[]'::jsonb, 2);
        n := admissions.rank_alternatives(run, 3);
        SELECT suggested INTO v_same FROM admissions.eligibility_result WHERE run_id = run AND programme_code = p_same;
        SELECT suggested INTO v_other FROM admissions.eligibility_result WHERE run_id = run AND programme_code = p_other;
        RAISE EXCEPTION 'the V397 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V397 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V397: a refused candidate is suggested programmes of the faculty they applied to only — an eligible programme of another faculty, though ranked first, is kept for the desk but never suggested',
        coalesce(n = 1 AND v_same AND NOT v_other, false),
        format('faculty=%s applied=%s same=%s suggested=%s | other=%s (%s) suggested=%s | n=%s', fac, p_app, p_same, v_same, p_other, other, v_other, n));
END $$;

-- ── V395. A student's payment reference is drawn until a free one is found: MOAUM-FEE, the end of the student's number and
--          four random digits may repeat a reference another student took (students whose numbers end alike share the first
--          part); both generators — school fees and every other purpose, the GST/EPS fee among them — draw again, the format
--          unchanged, and the student is never answered with a clash ──
DO $$
DECLARE S text := '9955/9956'; who uuid := gen_random_uuid(); st uuid := gen_random_uuid(); other uuid := gen_random_uuid();
        v_first int; v_taken text; v_school text; v_purpose text; n_refs int; v_sessions text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'bursar', true); PERFORM set_config('moaum.reason', 'CHECK V395', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9955-10-01', date '9956-08-31') ON CONFLICT (name) DO NOTHING;
        -- two students whose numbers end alike: the first part of their references is the same
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (st, 'MOAUM/ADM/95/939501', 'MOAUM/CHK/95/9395', 'CHECKFEEREF', 'Student', 'C00023', 'UTME', S, 100, 100, 'ACTIVE', now()),
               (other, 'MOAUM/ADM/95/939502', 'MOAUM/CKB/95/9395', 'CHECKFEEREF', 'Other', 'C00023', 'UTME', S, 100, 100, 'ACTIVE', now());
        INSERT INTO finance.fee_schedule (session, item, amount) VALUES (S, 'School fees (check V395)', 120000);
        -- the draw is the session's random(): seeded, the first draw is known, so the reference the other student holds is put in its way
        PERFORM setseed(0.5395);
        v_first := floor(random() * 10000)::int;
        v_taken := 'MOAUM-FEE-959395-' || lpad(v_first::text, 4, '0');
        INSERT INTO finance.payment_reference (student_id, session, reference, purpose, amount, expires_at)
        VALUES (other, S, v_taken, 'School fees ' || S, 1000, now() + interval '1 day');
        -- school fees: the first draw is taken, the second is the student's
        PERFORM setseed(0.5395);
        v_school := finance.new_reference(st, S, 50000, NULL);
        -- another purpose: the first two draws are now both taken, the third is the student's
        PERFORM setseed(0.5395);
        v_purpose := finance.new_purpose_reference(st, S, 6000, 'GST fee ' || S);
        SELECT count(*), string_agg(DISTINCT session, ',') INTO n_refs, v_sessions FROM finance.payment_reference WHERE student_id = st;
        RAISE EXCEPTION 'the V395 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V395: a student''s payment reference landing on a taken one is drawn again — school fees and every other purpose, the format kept, the student never answered with a clash',
        coalesce(v_school ~ '^MOAUM-FEE-959395-[0-9]{4}$' AND v_purpose ~ '^MOAUM-FEE-959395-[0-9]{4}$'
                 AND v_school <> v_taken AND v_purpose <> v_taken AND v_purpose <> v_school AND n_refs = 2 AND v_sessions = S, false),
        format('taken=%s school=%s purpose=%s refs=%s sessions=%s', v_taken, v_school, v_purpose, n_refs, v_sessions));
END $$;

-- ── V396. A BSU- course and its MOAU- twin are taught once: the pair is suggested by the duplicates rule and linked by a person
--          (one course: same department, level and semester); allocating either class allocates both and the load counts the
--          pair once; a co-lecturer follows; a class opened later takes the allocation; a slot on either class is on both
--          codes' timetables once; one register marks both codes' students, each on their own class; unlinked with a reason ──
DO $$
DECLARE S text := '9954/9955'; S2 text := '9953/9954'; who uuid := gen_random_uuid();
        lec uuid := gen_random_uuid(); sec uuid := gen_random_uuid(); co uuid := gen_random_uuid();
        ob uuid := gen_random_uuid(); om uuid := gen_random_uuid(); o9 uuid := gen_random_uuid(); ob2 uuid := gen_random_uuid(); om2 uuid := gen_random_uuid();
        sb uuid := gen_random_uuid(); sm uuid := gen_random_uuid(); rb uuid := gen_random_uuid(); rm uuid := gen_random_uuid();
        tw uuid; n_sugg int; r_mismatch text; r_taken text; m_lec uuid; m_sec uuid; r_load text; co_on_b boolean; co_gone boolean;
        later_lec uuid; slots_m int; slots_b int; att text; r_reason text; fam_after int; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'hod', true); PERFORM set_config('moaum.reason', 'CHECK V396', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9954-10-01', date '9955-08-31'), (gen_random_uuid(), S2, date '9953-10-01', date '9954-08-31')
        ON CONFLICT (name) DO NOTHING;
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (who, 'ZZTWIN-H', 'TWINHOD', 'Check'), (lec, 'ZZTWIN-L', 'TWINLECTURER', 'Check'),
          (sec, 'ZZTWIN-S', 'TWINSECOND', 'Check'), (co, 'ZZTWIN-C', 'TWINCO', 'Check');
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, state) VALUES
          ('BSU-ZZT 113', 'Twin Check Course', 3, 1, 100, 'MTC', 'LIVE'), ('MOAU-ZZT 113', 'Twin  check course', 3, 1, 100, 'MTC', 'LIVE'),
          ('MOAU-ZZT 213', 'Another Twin Check', 3, 1, 200, 'MTC', 'LIVE'), ('ZZT 999', 'Nine Units Of Check', 9, 1, 100, 'MTC', 'LIVE');
        -- suggested by the duplicates rule (title compared without case or extra spaces)
        n_sugg := (SELECT count(*) FROM catalogue.twin_suggestions('MTC') x WHERE x.bsu_code = 'BSU-ZZT 113' AND x.moau_code = 'MOAU-ZZT 113');
        -- not one course: refused
        BEGIN PERFORM catalogue.link_twin('BSU-ZZT 113', 'MOAU-ZZT 213');
        EXCEPTION WHEN check_violation THEN r_mismatch := split_part(SQLERRM, ':', 1); END;
        tw := catalogue.link_twin('bsu-zzt 113', 'MOAU-ZZT 113');
        BEGIN PERFORM catalogue.link_twin('BSU-ZZT 113', 'MOAU-ZZT 213');
        EXCEPTION WHEN check_violation THEN r_taken := split_part(SQLERRM, ':', 1); END;
        -- the classes of the session; allocating one allocates both
        INSERT INTO catalogue.offering (id, course_code, session, semester) VALUES (ob, 'BSU-ZZT 113', S, 1), (om, 'MOAU-ZZT 113', S, 1), (o9, 'ZZT 999', S, 1);
        PERFORM catalogue.allocate_offering(ob, lec, sec, false);
        SELECT lecturer_id, second_examiner_id INTO m_lec, m_sec FROM catalogue.offering WHERE id = om;
        -- the pair is 3 units, not 6: with the 9-unit class the lecturer is at 12, within the load
        BEGIN PERFORM catalogue.allocate_offering(o9, lec, NULL, false); r_load := 'ALLOCATED';
        EXCEPTION WHEN check_violation THEN r_load := SQLERRM; END;
        -- a co-lecturer added to one class is on both, and removed from both
        INSERT INTO catalogue.offering_teacher (offering_id, lecturer_id, added_by) VALUES (om, co, who);
        co_on_b := EXISTS (SELECT 1 FROM catalogue.offering_teacher WHERE offering_id = ob AND lecturer_id = co);
        DELETE FROM catalogue.offering_teacher WHERE offering_id = ob AND lecturer_id = co;
        co_gone := NOT EXISTS (SELECT 1 FROM catalogue.offering_teacher WHERE lecturer_id = co AND offering_id IN (ob, om));
        -- a class of the twin opened later takes the allocation already made
        INSERT INTO catalogue.offering (id, course_code, session, semester) VALUES (ob2, 'BSU-ZZT 113', S2, 1);
        PERFORM catalogue.allocate_offering(ob2, lec, NULL, false);
        INSERT INTO catalogue.offering (id, course_code, session, semester) VALUES (om2, 'MOAU-ZZT 113', S2, 1);
        later_lec := (SELECT lecturer_id FROM catalogue.offering WHERE id = om2);
        -- a 300-level student on the BSU- code and a 100-level student on the MOAU- code
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level)
        VALUES (sb, 'MOAUM/ADM/54/990001', 'CHECKTWIN', 'Bsu Student', 'C00023', 'UTME', S, 300, 300),
               (sm, 'MOAUM/ADM/54/990002', 'CHECKTWIN', 'Moau Student', 'C00023', 'UTME', S, 100, 100);
        INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, approved_at)
        VALUES (rb, sb, S, 1, 300, 'APPROVED', now()), (rm, sm, S, 1, 100, 'APPROVED', now());
        INSERT INTO registration.entry (registration_id, offering_id, units, status) VALUES (rb, ob, 3, 'APPROVED'), (rm, om, 3, 'APPROVED');
        -- one slot, entered on the BSU- class: both students see it, once
        INSERT INTO catalogue.class_slot (offering_id, weekday, starts_at, ends_at, venue, kind) VALUES (ob, 2, '10:00', '12:00', 'LT 1', 'LECTURE');
        slots_m := (SELECT count(*) FROM registration.student_timetable(sm, S, 1) x WHERE x.course_code = 'MOAU-ZZT 113');
        slots_b := (SELECT count(*) FROM registration.student_timetable(sb, S, 1) x WHERE x.course_code = 'BSU-ZZT 113');
        -- one register, taken on the BSU- class, marks both students, each on their own class
        PERFORM registration.mark_attendance(ob, date '9954-11-03', ARRAY[sm]);
        att := (SELECT string_agg(o.course_code || '=' || a.present, ',' ORDER BY o.course_code)
                  FROM registration.attendance a JOIN catalogue.offering o ON o.id = a.offering_id
                 WHERE a.held_on = date '9954-11-03' AND a.student_id IN (sb, sm));
        -- unlinked with a reason; each code is its own class again
        BEGIN PERFORM catalogue.unlink_twin(tw, ' ');
        EXCEPTION WHEN check_violation THEN r_reason := split_part(SQLERRM, ':', 1); END;
        PERFORM catalogue.unlink_twin(tw, 'check: the pair is taught apart from next session');
        fam_after := (SELECT count(*) FROM catalogue.offering_family(ob));
        RAISE EXCEPTION 'the V396 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V396: a BSU- course and its MOAU- twin are taught once — linked by a person, allocated together and counted once, one timetable, one register; results per code',
        coalesce(n_sugg = 1 AND r_mismatch = 'COURSE_TWIN_MISMATCH' AND tw IS NOT NULL AND r_taken = 'COURSE_TWIN_TAKEN'
                 AND m_lec = lec AND m_sec = sec AND r_load = 'ALLOCATED' AND co_on_b AND co_gone AND later_lec = lec
                 AND slots_m = 1 AND slots_b = 1 AND att = 'BSU-ZZT 113=false,MOAU-ZZT 113=true'
                 AND r_reason = 'COURSE_TWIN_REASON' AND fam_after = 1, false),
        format('sugg=%s mismatch=%s linked=%s taken=%s twin_lec=%s/%s load=%s co=%s/%s later=%s slots=%s/%s att=%s reason=%s family_after=%s',
               n_sugg, r_mismatch, tw IS NOT NULL, r_taken, m_lec = lec, m_sec = sec, r_load, co_on_b, co_gone, later_lec = lec, slots_m, slots_b, att, r_reason, fam_after));
END $$;

-- ── V398. A BSU- course and its MOAU- twin are examined once: a CBT examination on either class seats both codes' candidates
--          (the list, its count, the student's own examinations, the registration check), a second examination of the kind
--          on the twin is refused, each score goes to the sheet of the code the candidate registered on, by that course's CA
--          maximum, and linking copies the paper's slot ──
DO $$
DECLARE S text := '9952/9953'; who uuid := gen_random_uuid(); ob uuid := gen_random_uuid(); om uuid := gen_random_uuid();
        sb uuid := gen_random_uuid(); sm uuid := gen_random_uuid(); su uuid := gen_random_uuid(); rb uuid := gen_random_uuid(); rm uuid := gen_random_uuid();
        shb uuid := gen_random_uuid(); shm uuid := gen_random_uuid(); ex assessment.cbt_exam;
        n_cand int; n_count int; n_mine int; r_twin text; r_sm text; r_su text; n_written int; v_b record; v_m record; v_slot date;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'academic', true); PERFORM set_config('moaum.reason', 'CHECK V398', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9952-10-01', date '9953-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (who, 'ZZEXTWIN', 'EXAMTWIN', 'Check');
        -- two codes of one course, CBT courses; the MOAU- code keeps a different continuous-assessment maximum
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, state, ca_max) VALUES
          ('BSU-ZZU 113', 'Examined Twin Check', 3, 1, 100, 'MTC', 'LIVE', 40), ('MOAU-ZZU 113', 'Examined Twin Check', 3, 1, 100, 'MTC', 'LIVE', 30);
        UPDATE catalogue.course SET cbt_enabled = true WHERE code IN ('BSU-ZZU 113', 'MOAU-ZZU 113');
        INSERT INTO catalogue.offering (id, course_code, session, semester) VALUES (ob, 'BSU-ZZU 113', S, 1), (om, 'MOAU-ZZU 113', S, 1);
        -- the paper's slot set on the BSU- class before the pair is linked: linking copies it
        INSERT INTO assessment.exam_timetable (offering_id, held_on, starts_at, ends_at, venue) VALUES (ob, date '9953-02-10', '09:00', '11:00', 'CBT Hall A');
        PERFORM catalogue.link_twin('BSU-ZZU 113', 'MOAU-ZZU 113');
        v_slot := (SELECT held_on FROM assessment.exam_timetable WHERE offering_id = om);
        -- a student on each code, and one on neither
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (sb, 'MOAUM/ADM/52/952001', 'MOAUM/CHK/52/9521', 'CHECKEXTWIN', 'Bsu', 'C00023', 'UTME', S, 300, 300, 'ACTIVE', now()),
               (sm, 'MOAUM/ADM/52/952002', 'MOAUM/CHK/52/9522', 'CHECKEXTWIN', 'Moau', 'C00023', 'UTME', S, 100, 100, 'ACTIVE', now()),
               (su, 'MOAUM/ADM/52/952003', 'MOAUM/CHK/52/9523', 'CHECKEXTWIN', 'Neither', 'C00023', 'UTME', S, 100, 100, 'ACTIVE', now());
        INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, approved_at)
        VALUES (rb, sb, S, 1, 300, 'APPROVED', now()), (rm, sm, S, 1, 100, 'APPROVED', now());
        INSERT INTO registration.entry (registration_id, offering_id, units, status) VALUES (rb, ob, 3, 'APPROVED'), (rm, om, 3, 'APPROVED');
        -- one examination, set on the BSU- class, seats both codes' candidates
        ex := assessment.cbt_new_exam('EXAMS', ob, 'Twin examination', NULL, 30, 0, 'FIXED', false, false, 50, 1, 'STANDARD', 'REMOTE', 1, 'TERMINATE', 'CONTINUE',
                                      now() - interval '1 minute', now() + interval '1 hour');
        n_cand := (SELECT count(*) FROM assessment.cbt_candidates(ex.id) c WHERE c.student_id IN (sb, sm));
        n_count := (SELECT assessment.cbt_candidate_count(x) FROM assessment.cbt_exam x WHERE x.id = ex.id);
        -- a second examination of the kind on the twin class is refused
        BEGIN PERFORM assessment.cbt_new_exam('EXAMS', om, 'Twin examination again', NULL, 30, 0, 'FIXED', false, false, 50, 1, 'STANDARD', 'REMOTE', 1, 'TERMINATE', 'CONTINUE', NULL, NULL);
        EXCEPTION WHEN check_violation THEN r_twin := split_part(SQLERRM, ':', 1); END;
        -- open, the MOAU- student is past the registration check (the next gate is the fees); a student on neither code is not
        UPDATE assessment.cbt_exam SET state = 'PUBLISHED' WHERE id = ex.id;
        -- the MOAU- student's own list of examinations carries it
        n_mine := (SELECT count(*) FROM assessment.cbt_student_exams(sm, S) m WHERE m.exam_id = ex.id);
        r_sm := split_part(coalesce(assessment.cbt_eligibility(ex.id, sm), 'ELIGIBLE'), ':', 1);
        r_su := split_part(coalesce(assessment.cbt_eligibility(ex.id, su), 'ELIGIBLE'), ':', 1);
        -- both sat; approved, each score goes to the sheet of their own code, by that course's CA maximum
        INSERT INTO assessment.score_sheet (id, offering_id, stage) VALUES (shb, ob, 'ENTRY'), (shm, om, 'ENTRY');
        INSERT INTO assessment.cbt_attempt (exam_id, student_id, ends_at, status, question_ids, question_versions, question_marks, seed, max_marks, percentage)
        VALUES (ex.id, sb, now(), 'SUBMITTED', '{}', '{}', '{}', 1, 10, 80), (ex.id, sm, now(), 'SUBMITTED', '{}', '{}', '{}', 1, 10, 80);
        UPDATE assessment.cbt_exam SET state = 'COMPLETED', results_state = 'APPROVED', sheet_component = 'EXAM' WHERE id = ex.id;
        n_written := assessment.cbt_to_sheet(ex.id);
        SELECT s.sheet_id, s.exam INTO v_b FROM assessment.score s WHERE s.student_id = sb ORDER BY s.version DESC LIMIT 1;
        SELECT s.sheet_id, s.exam INTO v_m FROM assessment.score s WHERE s.student_id = sm ORDER BY s.version DESC LIMIT 1;
        RAISE EXCEPTION 'the V398 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V398: a BSU- course and its MOAU- twin are examined once — one CBT examination seats both codes, scores to each code''s own sheet, the slot shared',
        coalesce(v_slot = date '9953-02-10' AND n_cand = 2 AND n_count = 2 AND n_mine = 1 AND r_twin = 'CBT_TWIN_EXAMINED'
                 AND r_sm <> 'CBT_COURSE_NOT_REGISTERED' AND r_su = 'CBT_COURSE_NOT_REGISTERED'
                 AND n_written = 2 AND v_b.sheet_id = shb AND v_b.exam = 48 AND v_m.sheet_id = shm AND v_m.exam = 56, false),
        format('slot=%s cand=%s count=%s mine=%s twin=%s moau=%s neither=%s written=%s bsu=%s/%s moau=%s/%s',
               v_slot, n_cand, n_count, n_mine, r_twin, r_sm, r_su, n_written, v_b.sheet_id = shb, v_b.exam, v_m.sheet_id = shm, v_m.exam));
END $$;

-- ── V399: applicants told of another faculty's programme put right; a change of programme stays in the faculty ──
DO $$
DECLARE who uuid := gen_random_uuid(); S text := '9939/9940'; fac text; p_app text; p_same text; p_other text; n_same text; n_other text;
        cand uuid := gen_random_uuid(); acct uuid := gen_random_uuid(); app uuid := gen_random_uuid(); run uuid := gen_random_uuid(); req uuid := gen_random_uuid();
        t1 record; t2 record; v_out text; v_again text; n_corr int; n_notice int; v_corrected text; r_app text; r_rec text; v_rej text; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        SELECT faculty_code INTO fac FROM ref.programme WHERE faculty_code IS NOT NULL AND NOT archived AND name NOT LIKE '%,%'
         GROUP BY faculty_code HAVING count(*) >= 2 ORDER BY faculty_code LIMIT 1;
        SELECT code INTO p_app FROM ref.programme WHERE faculty_code = fac AND NOT archived AND name NOT LIKE '%,%' ORDER BY code LIMIT 1;
        SELECT code, name INTO p_same, n_same FROM ref.programme WHERE faculty_code = fac AND NOT archived AND name NOT LIKE '%,%' AND code <> p_app ORDER BY code LIMIT 1;
        SELECT code, name INTO p_other, n_other FROM ref.programme WHERE faculty_code IS NOT NULL AND faculty_code <> fac AND NOT archived AND name NOT LIKE '%,%'
           AND upper(name) NOT IN (SELECT upper(name) FROM ref.programme WHERE faculty_code = fac) ORDER BY code LIMIT 1;
        INSERT INTO admissions.candidate (id, session, jamb_reg_no, surname, other_names, programme, entry_mode, entry_level, offer_state)
        VALUES (cand, S, '993999000001CK', 'CHECKTOLD', 'Applicant', (SELECT name FROM ref.programme WHERE code = p_app), 'UTME', 100, 'PROPOSED');
        INSERT INTO admissions.applicant_account (id, session, candidate_id, jamb_key, email, phone, password_hash)
        VALUES (acct, S, cand, '993999000001CK', 'check.told.9939@example.com', '08030000000', 'SET_ON_FIRST_LOGIN');
        INSERT INTO admissions.application (id, account_id, candidate_id, session, application_no) VALUES (app, acct, cand, S, 'APP/39/999001');
        -- the engine's current reading suggests the faculty's own programme (V397)
        INSERT INTO admissions.eligibility_run (id, application_id, candidate_id, session, jamb_key, entry_mode, applied_programme_code, applied_programme, applied_result, trigger_kind)
        VALUES (run, app, cand, S, '993999000001CK', 'UTME', p_app, (SELECT name FROM ref.programme WHERE code = p_app), 'NOT_ELIGIBLE', 'SYSTEM');
        INSERT INTO admissions.eligibility_result (run_id, programme_code, programme, faculty_code, kind, result, checks, ord, suggested)
        VALUES (run, p_same, n_same, fac, 'ALTERNATIVE', 'ELIGIBLE', '[]'::jsonb, 1, true);
        -- before V397 the reconsiderations emailed another faculty's programme with it, and the applicant asked to move to it
        INSERT INTO admissions.suggestion_sent (application_id, programmes, sent_at, sent_by) VALUES (app, n_other || ', ' || n_same, now() - interval '3 days', who);
        INSERT INTO admissions.programme_change_request (id, application_id, candidate_id, session, from_programme_code, from_programme, to_programme_code, to_programme, eligibility_at_request, requested_by_kind)
        VALUES (req, app, cand, S, p_app, (SELECT name FROM ref.programme WHERE code = p_app), p_other, n_other, 'ELIGIBLE', 'APPLICANT');
        SELECT * INTO t1 FROM admissions.cross_faculty_told(S) t WHERE t.application_id = app;
        -- the request is not approved, nor another faculty's programme recommended without the Registrar's override
        BEGIN PERFORM admissions.decide_programme_change(req, 'APPROVE', 'within quota', who);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_app := split_part(msg, ':', 1); END;
        BEGIN PERFORM admissions.recommend_programme_change(app, p_other, 'OLEVEL_NOT_MET', NULL, who, 'academic', false, NULL);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_rec := split_part(msg, ':', 1); END;
        -- the corrected list: sent, recorded, the last list now; asked again, nothing to correct
        v_out := admissions.correct_suggestion(app, who);
        v_again := admissions.correct_suggestion(app, who);
        n_corr := (SELECT count(*) FROM admissions.suggestion_correction WHERE application_id = app);
        v_corrected := (SELECT corrected_to FROM admissions.suggestion_correction WHERE application_id = app);
        n_notice := (SELECT count(*) FROM platform.notice WHERE about_kind = 'application' AND about_id = app AND channel = 'EMAIL' AND subject LIKE '%suggested programmes corrected%');
        -- the request rejected with its reason; the applicant leaves the list
        v_rej := admissions.decide_programme_change(req, 'REJECT', 'Only programmes of the faculty applied to are offered as a change of programme.', who);
        SELECT * INTO t2 FROM admissions.cross_faculty_told(S) t WHERE t.application_id = app;
        RAISE EXCEPTION 'the V399 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V399 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V399: an applicant told of another faculty''s programme before V397 is listed with what was named and when, and sent the programmes of their own faculty once; a request for another faculty''s programme is not approved, nor recommended without the Registrar''s override, and is rejected with its reason',
        coalesce(t1.told_other = ARRAY[n_other] AND t1.suggested_now = ARRAY[n_same] AND t1.request_id = req AND t1.corrected_at IS NULL
                 AND r_app = 'PROGRAMME_CHANGE_OTHER_FACULTY' AND r_rec = 'PROGRAMME_CHANGE_OTHER_FACULTY'
                 AND v_out = 'CORRECTED' AND v_again = 'NOTHING_TO_CORRECT' AND n_corr = 1 AND v_corrected = n_same AND n_notice = 1
                 AND v_rej = 'REJECTED' AND t2.application_id IS NULL, false),
        format('told=%s now=%s req=%s | approve=%s recommend=%s | correct=%s/%s rows=%s to=%s notices=%s | reject=%s listed_after=%s',
               t1.told_other, t1.suggested_now, t1.request_id = req, r_app, r_rec, v_out, v_again, n_corr, v_corrected, n_notice, v_rej, t2.application_id IS NOT NULL));
END $$;

-- ── V400. Two sessions overlapping, followed up: the session current on a day comes from the transition log, else the one
--          already running; the transition checks say what is still open in the session being completed, without blocking;
--          the offices are reminded once a day once the current session has run past its end date ──
DO $$
DECLARE who uuid := gen_random_uuid(); A text := '9950/9951'; B text := '9951/9952'; r_nolog text; r_outside text; r_before text; r_after text;
        open_txt text; informative boolean; n_remind int; n_again int; v_subject text; v_days int;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'registrar', true); PERFORM set_config('moaum.reason', 'CHECK V400', true);
        -- A, and B beginning inside it (V377)
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on)
        VALUES (gen_random_uuid(), A, date '9950-10-01', date '9951-12-31'), (gen_random_uuid(), B, date '9951-09-01', date '9952-08-31') ON CONFLICT (name) DO NOTHING;
        -- no transition logged: a day in the overlap belongs to the session already running; a day outside it to the one that holds it
        r_nolog := policy.session_current_on(date '9951-10-15');
        r_outside := policy.session_current_on(date '9952-03-01');
        -- the transition into B logged on 1 Nov 9951: before it A was current, after it B
        INSERT INTO policy.session_transition (from_session, to_session, outcome, mode, reason, at) VALUES (A, B, 'DONE', 'MANUAL', 'check', timestamptz '9951-11-01 10:00+01');
        r_before := policy.session_current_on(date '9951-10-15');
        r_after := policy.session_current_on(date '9951-11-20');
        DELETE FROM policy.session_transition WHERE to_session = B;
        -- A current and past its end date, a semester of it open: the readiness of B says so and does not block; the reminder, once a day
        UPDATE policy.academic_session SET state = 'CLOSED' WHERE state = 'CURRENT';
        UPDATE policy.academic_session SET starts_on = current_date - 400, ends_on = current_date - 3, state = 'CURRENT', senate_minute = 'SEN/9950/1' WHERE name = A;
        INSERT INTO policy.semester (id, session, number, state) VALUES (gen_random_uuid(), A, 1, 'OPEN') ON CONFLICT (session, number) DO UPDATE SET state = 'OPEN';
        SELECT detail INTO open_txt FROM policy.transition_readiness(B) WHERE code = 'CURRENT_SEMESTERS_OPEN';
        SELECT bool_and(ok AND NOT blocking) INTO informative FROM policy.transition_readiness(B) WHERE code IN ('CURRENT_SEMESTERS_OPEN', 'CURRENT_SHEETS_PENDING', 'CURRENT_REGISTRATIONS_PENDING');
        SELECT count(*), max(subject), max(days_over) INTO n_remind, v_subject, v_days FROM policy.remind_session_overrun();
        SELECT count(*) INTO n_again FROM policy.remind_session_overrun();
        RAISE EXCEPTION 'the V400 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V400: overlapping sessions followed up — the session current on a day, what is still open in the session being completed, a daily reminder once the current session has run past its end',
        coalesce(r_nolog = A AND r_outside = B AND r_before = A AND r_after = B AND open_txt LIKE '1 semester of ' || A || ' still open%' AND informative
                 AND n_remind = 1 AND v_days = 3 AND v_subject LIKE 'Academic session ' || A || ' is still current 3 days%' AND n_again = 0, false),
        format('nolog=%s outside=%s before=%s after=%s open=%s informative=%s remind=%s days=%s subject=%s again=%s',
               r_nolog, r_outside, r_before, r_after, open_txt, informative, n_remind, v_days, v_subject, n_again));
END $$;

-- ── V401. A session whose applicant fees are not stated: under the Bursary's rule CARRY the last stated session's amounts apply,
--          as before; under REFUSE no fee reference is issued until they are stated, and stating them opens the door ──
DO $$
DECLARE S text := '9949/9950'; who uuid := gen_random_uuid(); cand uuid := gen_random_uuid(); acct uuid := gen_random_uuid(); app uuid := gen_random_uuid();
        cr uuid := gen_random_uuid(); batch uuid := gen_random_uuid(); v_default text; v_policy text; r_refused text; r_stated text; r_carry text; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'bursar', true); PERFORM set_config('moaum.reason', 'CHECK V401', true);
        v_default := admissions.applicant_fee_policy();
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9949-10-01', date '9950-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO admissions.caps_batch (id, session, source, list_kind, file_sha256, rows_read, downloaded_on, uploaded_by, uploaded_office)
        VALUES (batch, S, 'CAPS_DOWNLOAD', 'UTME', '\xB401'::bytea, 1, current_date, who, 'academic');
        INSERT INTO admissions.caps_row (id, batch_id, session, jamb_reg_no, raw, surname, other_names, jamb_code, aggregate, entry_mode, sex, state_of_origin, lga)
        VALUES (cr, batch, S, '20494910001', '{}'::jsonb, 'CHECKFEEPOLICY', 'Cand', 'C00066', 250, 'UTME', 'F', 'Benue', 'Makurdi');
        INSERT INTO admissions.candidate (id, session, jamb_reg_no, surname, other_names, programme, entry_mode, entry_level, offer_state, admitted_from)
        VALUES (cand, S, '20494910001', 'CHECKFEEPOLICY', 'Cand', (SELECT name FROM ref.programme WHERE code = 'C00066'), 'UTME', 100, 'PROPOSED', cr);
        INSERT INTO admissions.applicant_account (id, session, candidate_id, jamb_key, email, phone, password_hash)
        VALUES (acct, S, cand, '20494910001', 'checkfeepolicy@example.com', '08031234567', crypt('x', gen_salt('bf', 12)));
        INSERT INTO admissions.application (id, account_id, candidate_id, session, application_no) VALUES (app, acct, cand, S, 'APP/49/000001');
        DELETE FROM admissions.applicant_fee WHERE session = S;
        -- REFUSE: nothing is paid for a session whose fees are not stated
        UPDATE finance.fee_setting SET applicant_fee_unstated = 'REFUSE' WHERE id = 1;
        v_policy := admissions.applicant_fee_policy();
        BEGIN PERFORM admissions.new_fee_reference(app, 'APPLICATION'); r_refused := 'ISSUED';
        EXCEPTION WHEN check_violation THEN r_refused := split_part(SQLERRM, ':', 1); msg := SQLERRM; END;
        -- stated for the session: issued
        INSERT INTO admissions.applicant_fee (session, application_fee, portal_charge, acceptance_fee, checking_fee) VALUES (S, 2500, 0, 25000, 3000);
        r_stated := left(admissions.new_fee_reference(app, 'APPLICATION'), 10);
        -- CARRY: an unstated session's reference is issued at the carried amounts, as before
        DELETE FROM admissions.fee_reference WHERE application_id = app;
        DELETE FROM admissions.applicant_fee WHERE session = S;
        UPDATE finance.fee_setting SET applicant_fee_unstated = 'CARRY' WHERE id = 1;
        r_carry := left(admissions.new_fee_reference(app, 'APPLICATION'), 10);
        RAISE EXCEPTION 'the V401 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V401: a session whose applicant fees are not stated — carried forward by default, refused under the Bursary''s rule until stated, issued once stated',
        coalesce(v_default = 'CARRY' AND v_policy = 'REFUSE' AND r_refused = 'APPLICANT_FEE_NOT_STATED' AND r_stated = 'MOAUM-APP-' AND r_carry = 'MOAUM-APP-', false),
        format('default=%s policy=%s refused=%s stated=%s carry=%s %s', v_default, v_policy, r_refused, r_stated, r_carry, coalesce(msg, '')));
END $$;

-- ── V402. BSU- and MOAU- codes are offered by cohort, not linked: where both codes of a course reach a student, the student
--          sees their cohort's (MOAU- from the stated entry session, BSU- before it); a code whose twin is not on offer, or the
--          rule unstated, is shown to everyone ──
DO $$
DECLARE S text := '9948/9949'; who uuid := gen_random_uuid(); dept text := 'ZZF9'; a uuid := gen_random_uuid(); b uuid := gen_random_uuid();
        v_saved text; r_a text; r_b text; r_a_none text; r_b_lone text; r_both text; v_fam_a text; v_fam_b text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'academic', true); PERFORM set_config('moaum.reason', 'CHECK V402', true);
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (who, 'CHK/V402', 'CHECKV402', 'Office');
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9948-10-01', date '9949-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO ref.department (code, name, faculty_code) VALUES (dept, 'Check V402', (SELECT faculty_code FROM ref.programme WHERE code = 'C00023'));
        -- the same course under both codes; one BSU- code with no twin; one MOAU- code whose twin is held but not offered
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state) VALUES
            ('BSU-ZZF 101', 'Check code families', 2, 1, 100, dept, 'Core', 'LIVE'), ('MOAU-ZZF 101', 'Check code families', 2, 1, 100, dept, 'Core', 'LIVE'),
            ('BSU-ZZF 102', 'Check lone BSU code', 2, 1, 100, dept, 'Core', 'LIVE'),
            ('BSU-ZZF 103', 'Check twin not offered', 2, 1, 100, dept, 'Core', 'LIVE'), ('MOAU-ZZF 103', 'Check twin not offered', 2, 1, 100, dept, 'Core', 'LIVE');
        INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES
            ('BSU-ZZF 101', 'C00023', 100, 'Core'), ('MOAU-ZZF 101', 'C00023', 100, 'Core'), ('BSU-ZZF 102', 'C00023', 100, 'Core'), ('MOAU-ZZF 103', 'C00023', 100, 'Core');
        INSERT INTO catalogue.offering (id, course_code, session, semester)
        SELECT gen_random_uuid(), c, S, 1 FROM unnest(ARRAY['BSU-ZZF 101', 'MOAU-ZZF 101', 'BSU-ZZF 102', 'MOAU-ZZF 103']) c;
        -- two students of the programme at 100 level: one admitted in the stated session, one before it
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at) VALUES
            (a, 'MOAUM/ADM/48/000401', 'MOAUM/CHK/48/401', 'CHECKV402A', 'Invented', 'C00023', 'UTME', S, 100, 100, 'ACTIVE', now()),
            (b, 'MOAUM/ADM/48/000402', 'MOAUM/CHK/48/402', 'CHECKV402B', 'Invented', 'C00023', 'UTME', '9940/9941', 100, 100, 'ACTIVE', now());
        SELECT moau_from_entry_session INTO v_saved FROM catalogue.code_family_setting WHERE id = 1;
        UPDATE catalogue.code_family_setting SET moau_from_entry_session = S, stated_by = who, stated_at = now() WHERE id = 1;
        v_fam_a := catalogue.student_code_family(a); v_fam_b := catalogue.student_code_family(b);
        SELECT string_agg(m.course_code, ',' ORDER BY m.course_code) INTO r_a FROM registration.student_menu(a, S, 1) m WHERE m.course_code LIKE '%ZZF%';
        SELECT string_agg(m.course_code, ',' ORDER BY m.course_code) INTO r_b FROM registration.student_menu(b, S, 1) m WHERE m.course_code LIKE '%ZZF%';
        -- the rule unstated: both codes reach both students
        UPDATE catalogue.code_family_setting SET moau_from_entry_session = NULL WHERE id = 1;
        SELECT string_agg(m.course_code, ',' ORDER BY m.course_code) INTO r_both FROM registration.student_menu(b, S, 1) m WHERE m.course_code LIKE '%ZZF%';
        UPDATE catalogue.code_family_setting SET moau_from_entry_session = v_saved WHERE id = 1;
        RAISE EXCEPTION 'the V402 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V402: BSU- and MOAU- codes are offered by cohort — where both reach a student the cohort''s is shown; a lone code and a code whose twin is not offered reach everyone; unstated, both do',
        v_fam_a = 'MOAU' AND v_fam_b = 'BSU'
        AND r_a = 'BSU-ZZF 102,MOAU-ZZF 101,MOAU-ZZF 103'
        AND r_b = 'BSU-ZZF 101,BSU-ZZF 102,MOAU-ZZF 103'
        AND r_both = 'BSU-ZZF 101,BSU-ZZF 102,MOAU-ZZF 101,MOAU-ZZF 103',
        format('family a=%s b=%s | a sees %s | b sees %s | unstated b sees %s', v_fam_a, v_fam_b, r_a, r_b, r_both));
END $$;

-- ── V403: the Board's result sheet — numbers, combination, subjects and grades from one upload ──
-- A row found by name gets its JUPEB number, the combination and subjects the Board graded (a registered subject the Board
-- did not examine re-pointed, never deleted) and its grades; a name two candidates share is held for review until the row
-- names the application; the CRS/ISS option is the column graded; a grade already recorded changes only with a reason;
-- a row whose subjects are no combination of the Board is invalid and nothing is written; uploading again changes nothing.
DO $$
DECLARE who uuid := gen_random_uuid(); ses text := '9963/9964'; prog text; acc uuid[] := '{}'; acc1 uuid; i int;
        sc1 uuid; sc5 uuid; crs uuid; gov uuid; lit uuid; fre uuid; aOne uuid; aTwo uuid; aTwin uuid; aThree uuid;
        rows jsonb; pv jsonb; r_invalid text; cm jsonb; again jsonb;
        v_no1 text; v_comb1 text; v_regs1 int; v_fre1 int; v_opt1 text; v_res1 int; v_ev1 int; v_no2 text; v_opt2 text; v_twin text;
        v_lit3 text; v_chg3 int; v_batch int; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'jupeb', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), ses, date '9963-10-01', date '9964-08-31') ON CONFLICT (name) DO NOTHING;
        SELECT code INTO prog FROM ref.programme WHERE category = 'UNDER GRADUATE' AND NOT archived ORDER BY code LIMIT 1;
        SELECT id INTO sc1 FROM jupeb.combination WHERE code = 'SC-001';    -- CRS/ISS, GOV, LIT
        SELECT id INTO sc5 FROM jupeb.combination WHERE code = 'SC-005';    -- CRS/ISS, FRE, GOV
        SELECT id INTO crs FROM jupeb.subject WHERE code = 'CRS/ISS';
        SELECT id INTO gov FROM jupeb.subject WHERE code = 'GOV';
        SELECT id INTO lit FROM jupeb.subject WHERE code = 'LIT';
        SELECT id INTO fre FROM jupeb.subject WHERE code = 'FRE';
        FOR i IN 1 .. 4 LOOP
            INSERT INTO jupeb.account (email, password_hash) VALUES ('zz.v403.' || i || '@example.com', '$2a$12$abcdefghijklmnopqrstuuabcdefghijklmnopqrstuvwxyz12345') RETURNING id INTO acc1;
            acc := acc || acc1;
        END LOOP;
        INSERT INTO jupeb.application (account_id, session, application_no, surname, first_name, middle_name, email, programme_code, combination_id, state_of_origin, state, subjects_registered_at)
        VALUES (acc[1], ses, 'JUPEB/APP/9963/940301', 'ZZBOARDONE', 'Mary', 'Enenoyi', 'zz.v403.1@example.com', prog, sc5, 'Benue', 'STUDENT', now()) RETURNING id INTO aOne;
        INSERT INTO jupeb.application (account_id, session, application_no, surname, first_name, email, programme_code, combination_id, state_of_origin, state, subjects_registered_at)
        VALUES (acc[2], ses, 'JUPEB/APP/9963/940302', 'ZZBOARDTWO', 'Peter', 'zz.v403.2@example.com', prog, sc1, 'Benue', 'STUDENT', now()) RETURNING id INTO aTwo;
        INSERT INTO jupeb.application (account_id, session, application_no, surname, first_name, email, programme_code, combination_id, state_of_origin, state, subjects_registered_at)
        VALUES (acc[3], ses, 'JUPEB/APP/9963/940303', 'ZZBOARDTWO', 'Peter', 'zz.v403.3@example.com', prog, sc1, 'Benue', 'STUDENT', now()) RETURNING id INTO aTwin;
        INSERT INTO jupeb.application (account_id, session, application_no, surname, first_name, email, programme_code, combination_id, state_of_origin, state, subjects_registered_at, exam_no)
        VALUES (acc[4], ses, 'JUPEB/APP/9963/940304', 'ZZBOARDTHREE', 'Ann', 'zz.v403.4@example.com', prog, sc1, 'Benue', 'STUDENT', now(), 'ZZ403-0003') RETURNING id INTO aThree;
        INSERT INTO jupeb.subject_registration (application_id, subject_id, session, registered_by)
        SELECT x.app, s, ses, who FROM (VALUES (aOne, ARRAY[crs, fre, gov]), (aTwo, ARRAY[crs, gov, lit]), (aTwin, ARRAY[crs, gov, lit]), (aThree, ARRAY[crs, gov, lit])) x(app, subs), unnest(x.subs) s;
        INSERT INTO jupeb.result (application_id, subject_id, grade, points, batch_ref, recorded_by) VALUES (aThree, lit, 'C', jupeb.grade_points('C'), 'CHECK-V403', who);

        -- (1) the preview: one found by name, one name two candidates share, one by JUPEB number with an unreasoned change, one no combination
        rows := jsonb_build_array(
            jsonb_build_object('row', 4, 'examNo', 'ZZ403-0001', 'surname', 'ZZBOARDONE', 'otherNames', 'MARY  ENENOYI', 'g_CRS', 'F', 'g_GOV', 'C', 'g_LIT', 'C'),
            jsonb_build_object('row', 5, 'examNo', 'ZZ403-0002', 'surname', 'ZZBOARDTWO', 'otherNames', 'PETER', 'g_ISS', 'E', 'g_GOV', 'C', 'g_LIT', 'D'),
            jsonb_build_object('row', 6, 'examNo', 'ZZ403-0003', 'surname', 'ZZBOARDTHREE', 'otherNames', 'ANN', 'g_CRS', 'B', 'g_GOV', 'B', 'g_LIT', 'A'),
            jsonb_build_object('row', 7, 'examNo', 'ZZ403-0004', 'surname', 'ZZNOBODY', 'otherNames', 'X', 'g_CRS', 'A', 'g_PHY', 'B', 'g_LIT', 'C'));
        pv := jupeb.import_board_results(rows, false, 'check.xlsx', who);
        BEGIN PERFORM jupeb.import_board_results(rows, true, 'check.xlsx', who); r_invalid := 'COMMITTED';
        EXCEPTION WHEN check_violation THEN r_invalid := split_part(SQLERRM, ':', 1); END;

        -- (2) the office names the twin's application and gives the change its reason; the invalid row taken out
        rows := jsonb_build_array(rows->0,
                                  (rows->1) || jsonb_build_object('applicationNo', 'JUPEB/APP/9963/940302'),
                                  (rows->2) || jsonb_build_object('reason', 'The Board''s corrected result'));
        cm := jupeb.import_board_results(rows, true, 'check.xlsx', who);
        SELECT a.exam_no, c.code INTO v_no1, v_comb1 FROM jupeb.application a JOIN jupeb.combination c ON c.id = a.combination_id WHERE a.id = aOne;
        SELECT count(*), count(*) FILTER (WHERE subject_id = fre) INTO v_regs1, v_fre1 FROM jupeb.subject_registration WHERE application_id = aOne;
        SELECT b.prefix INTO v_opt1 FROM jupeb.subject_registration r JOIN jupeb.board_subject b ON b.id = r.board_subject_id WHERE r.application_id = aOne AND r.subject_id = crs;
        SELECT count(*) INTO v_res1 FROM jupeb.result WHERE application_id = aOne;
        SELECT count(*) INTO v_ev1 FROM jupeb.application_event WHERE application_id = aOne AND kind = 'BOARD_COMBINATION';
        SELECT exam_no INTO v_no2 FROM jupeb.application WHERE id = aTwo;
        SELECT b.prefix INTO v_opt2 FROM jupeb.subject_registration r JOIN jupeb.board_subject b ON b.id = r.board_subject_id WHERE r.application_id = aTwo AND r.subject_id = crs;
        SELECT coalesce(exam_no, 'none') INTO v_twin FROM jupeb.application WHERE id = aTwin;
        SELECT grade INTO v_lit3 FROM jupeb.result WHERE application_id = aThree AND subject_id = lit;
        SELECT count(*) INTO v_chg3 FROM jupeb.result_change WHERE application_id = aThree AND subject_id = lit AND new_grade = 'A';
        SELECT count(*) INTO v_batch FROM jupeb.import_batch WHERE kind = 'BOARD_RESULTS' AND ref = cm->>'ref';

        -- (3) the same sheet again changes nothing
        again := jupeb.import_board_results(rows, false, 'check.xlsx', who);
        RAISE EXCEPTION 'the V403 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V403 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V403: the Board''s result sheet — a row found by name gets its JUPEB number, the combination and subjects the Board graded (a registered subject re-pointed, never deleted) and its grades; a shared name is held for review until the row names the application; the CRS/ISS option is the column graded; a recorded grade changes only with a reason; a row that is no combination of the Board is invalid and nothing is written; the same sheet again changes nothing',
        coalesce((pv->>'invalid')::int = 1 AND (pv->>'review')::int = 2 AND (pv->>'new')::int = 1 AND r_invalid = 'JUPEB_IMPORT_INVALID'
                 AND (pv->'rows'->1->>'status') = 'REQUIRES_REVIEW' AND (pv->'rows'->2->>'status') = 'REQUIRES_REVIEW' AND (pv->'rows'->3->>'status') = 'INVALID'
                 AND (cm->>'applied')::int = 3 AND (cm->>'invalid')::int = 0
                 AND v_no1 = 'ZZ403-0001' AND v_comb1 = 'SC-001' AND v_regs1 = 3 AND v_fre1 = 0 AND v_opt1 = 'CRS' AND v_res1 = 3 AND v_ev1 = 1
                 AND v_no2 = 'ZZ403-0002' AND v_opt2 = 'ISS' AND v_twin = 'none'
                 AND v_lit3 = 'A' AND v_chg3 = 1 AND v_batch = 1
                 AND (again->>'unchanged')::int = 3 AND (again->>'new')::int = 0 AND (again->>'updated')::int = 0, false),
        format('preview invalid=%s review=%s new=%s commit-with-invalid=%s | commit applied=%s | one %s %s regs=%s fre=%s option=%s results=%s events=%s | two %s option=%s twin=%s | three lit=%s changes=%s batch=%s | again unchanged=%s | rows: %s',
               pv->>'invalid', pv->>'review', pv->>'new', r_invalid, cm->>'applied', v_no1, v_comb1, v_regs1, v_fre1, v_opt1, v_res1, v_ev1,
               v_no2, v_opt2, v_twin, v_lit3, v_chg3, v_batch, again->>'unchanged', left((SELECT string_agg(x->>'status' || ':' || coalesce(x->>'message', ''), ' / ') FROM jsonb_array_elements(pv->'rows') x), 400)));
END $$;

-- ── V404: CCE applicants — the checking fee the Bursary states, the application fee first, the documents the Centre needs ──
-- The Bursary states application, admission checking and acceptance fees (none left out, no other office); a listed applicant
-- who has not paid cannot fill the form, and is told the fee comes first; the documents asked include the birth certificate
-- and the certificate of state of origin; paid, the form opens; checking is closed until the Centre publishes, then costs the
-- stated checking fee; where nothing is charged for the application the form opens at once; a row stated before V404 has no
-- checking fee: owed, refused until stated, and the applicant is told so. The block undoes its writes.
DO $$
DECLARE acad uuid := gen_random_uuid(); burs uuid := gen_random_uuid(); S text := '9947/9948'; pa text := 'C00023'; b uuid;
        acct uuid; app uuid; acct2 uuid; app2 uuid; r_amount text; r_office text; r_first text; pay_msg text; doc_kinds text;
        ref1 text; amount1 numeric; r_after text; r_early text; sc record; r_free text; fee_null numeric; req_null boolean;
        r_unstated text; st_detail text; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.reason', 'check V404', true);
        PERFORM set_config('moaum.actor_id', acad::text, true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9947-10-01', date '9948-08-31') ON CONFLICT (name) DO NOTHING;
        PERFORM policy.set_route_session('CCE', -1, S, 'the check runs in a session of its own', NULL);
        PERFORM ref.set_programme_route(pa, 'CCE', true, NULL, NULL, 'the check');
        b := admissions.cce_preview(S, 'cce-404.xlsx', repeat('d', 64), jsonb_build_array(
            jsonb_build_object('jamb_reg_no', '99470000001CC', 'surname', 'Ushie', 'first_name', 'Doom', 'date_of_birth', '1991-05-02', 'sex', 'F',
                               'phone', '08035550301', 'email', 'doom@example.com', 'programme_code', pa),
            jsonb_build_object('jamb_reg_no', '99470000002CC', 'surname', 'Agbo', 'first_name', 'Ene', 'date_of_birth', '1992-06-03', 'sex', 'F',
                               'phone', '08035550302', 'email', 'ene@example.com', 'programme_code', pa)));
        PERFORM admissions.cce_commit(b);
        PERFORM policy.window_act('CCE_APPLICATION', S, NULL, 'OPEN', NULL, NULL, NULL, NULL, NULL, acad, 'ict');
        acct := admissions.cce_register('99470000001CC', date '1991-05-02', 'doom.ushie@example.com', '08035550301', '$2a$12$' || repeat('x', 53));
        SELECT id INTO app FROM admissions.application WHERE account_id = acct;
        acct2 := admissions.cce_register('99470000002CC', date '1992-06-03', 'ene.agbo@example.com', '08035550302', '$2a$12$' || repeat('x', 53));
        SELECT id INTO app2 FROM admissions.application WHERE account_id = acct2;

        -- (1) the Bursary states the three fees: without the checking fee, or by another office, refused
        PERFORM set_config('moaum.actor_id', burs::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        BEGIN PERFORM admissions.set_route_fee(S, 'CCE', 10000, 0, 10000, NULL); r_amount := 'STATED';
        EXCEPTION WHEN check_violation THEN r_amount := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_office', 'academic', true);
        BEGIN PERFORM admissions.set_route_fee(S, 'CCE', 10000, 0, 10000, 3000); r_office := 'STATED';
        EXCEPTION WHEN check_violation THEN r_office := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM admissions.set_route_fee(S, 'CCE', 10000, 0, 10000, 3000);

        -- (2) not paid: the form is shut, the fee is asked for first, the documents asked include the two certificates
        PERFORM set_config('moaum.actor_id', acct::text, true);
        PERFORM set_config('moaum.actor_office', 'applicant', true);
        BEGIN PERFORM admissions.cce_save_biodata(app, '{"home_address": "1 Gboko Road, Makurdi"}'); r_first := 'SAVED';
        EXCEPTION WHEN check_violation THEN r_first := split_part(SQLERRM, ':', 1); END;
        SELECT message INTO pay_msg FROM admissions.cce_application_problems(app) WHERE step = 'PAYMENT';
        SELECT string_agg(field, ',' ORDER BY field) INTO doc_kinds FROM admissions.cce_application_problems(app) WHERE step = 'DOCUMENTS';

        -- (3) paid: the form opens; checking is closed until the Centre publishes, and costs the stated checking fee
        ref1 := admissions.new_fee_reference(app, 'APPLICATION');
        SELECT amount INTO amount1 FROM admissions.fee_reference WHERE reference = ref1;
        PERFORM set_config('moaum.actor_id', burs::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM admissions.confirm_fee(ref1, 'BANK', 'check');
        PERFORM set_config('moaum.actor_id', acct::text, true);
        PERFORM set_config('moaum.actor_office', 'applicant', true);
        PERFORM admissions.cce_save_biodata(app, '{"home_address": "1 Gboko Road, Makurdi"}'); r_after := 'SAVED';
        UPDATE admissions.application SET submitted_at = now() WHERE id = app;
        BEGIN PERFORM admissions.new_fee_reference(app, 'CHECKING'); r_early := 'ISSUED';
        EXCEPTION WHEN check_violation THEN r_early := split_part(SQLERRM, ':', 1); END;
        SELECT * INTO sc FROM admissions.status_checking(app);

        -- (4) nothing charged for the application: the form opens at once
        PERFORM set_config('moaum.actor_id', burs::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM admissions.set_route_fee(S, 'CCE', 0, 0, 10000, 3000);
        PERFORM set_config('moaum.actor_id', acct2::text, true);
        PERFORM set_config('moaum.actor_office', 'applicant', true);
        BEGIN PERFORM admissions.cce_save_biodata(app2, '{"home_address": "2 Otukpo Road, Makurdi"}'); r_free := 'SAVED';
        EXCEPTION WHEN check_violation THEN r_free := split_part(SQLERRM, ':', 1); END;

        -- (5) a statement from before V404 (no checking fee): owed and not payable; once published the applicant is told why
        UPDATE admissions.route_fee SET checking_fee = NULL WHERE session = S AND route = 'CCE';
        UPDATE admissions.application SET decision = 'NOT_OFFERED', decided_at = now(), decision_released_at = now() WHERE id = app;
        SELECT fee, fee_required INTO fee_null, req_null FROM admissions.status_checking(app);
        BEGIN PERFORM admissions.new_fee_reference(app, 'CHECKING'); r_unstated := 'ISSUED';
        EXCEPTION WHEN check_violation THEN r_unstated := split_part(SQLERRM, ':', 1); END;
        SELECT detail INTO st_detail FROM admissions.admission_status(app);
        RAISE EXCEPTION 'the V404 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V404 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V404: CCE applicants — the Bursary states the application, admission checking and acceptance fees (none left out, no other office); the form opens once the application fee is paid (at once where nothing is charged), the fee asked for first; the birth certificate and the certificate of state of origin are asked for; checking is closed until the Centre publishes and costs the stated checking fee; a checking fee never stated is owed, refused, and the applicant told why',
        coalesce(r_amount = 'CCE_FEE_AMOUNT' AND r_office = 'CCE_OFFICE' AND r_first = 'CCE_FEE_FIRST' AND pay_msg LIKE 'Pay the CCE application fee; the form opens%'
                 AND doc_kinds = 'BIRTH_CERT,OLEVEL_STATEMENT,PASSPORT,STATE_OF_ORIGIN' AND amount1 = 10000 AND r_after = 'SAVED'
                 AND r_early = 'ADMISSION_CHECKING_CLOSED' AND sc.window_state = 'CLOSED' AND sc.fee = 3000 AND sc.fee_required AND NOT sc.decision_visible
                 AND r_free = 'SAVED' AND fee_null IS NULL AND req_null AND r_unstated = 'CCE_FEE_NOT_STATED' AND st_detail LIKE '%has not yet stated the CCE admission checking fee%', false),
        format('amount=%s office=%s first=%s pay=%s docs=%s | paid %s after=%s | early=%s window=%s fee=%s required=%s visible=%s | free=%s | unstated fee=%s required=%s ref=%s detail=%s',
               r_amount, r_office, r_first, pay_msg, doc_kinds, amount1, r_after, r_early, sc.window_state, sc.fee, sc.fee_required, sc.decision_visible,
               r_free, fee_null, req_null, r_unstated, st_detail));
END $$;

-- ── V405/V406. A course that joins a programme's structure after a semester's classes were opened gets its class in that semester
--          when asked (catalogue.open_classes_for_courses, the desk's opening) — never unasked; a semester not yet opened gets
--          nothing; the allocation desk lists a department's courses without a class and says why ──
DO $$
DECLARE S text := '9947/9948'; who uuid := gen_random_uuid(); dept text := 'ZZG9';
        v_unasked int; v_later int; v_sem2 int; v_ended int; v_restored int; v_missing text; v_opened int; v_after text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'academic', true); PERFORM set_config('moaum.reason', 'CHECK V405', true);
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (who, 'CHK/V405', 'CHECKV405', 'Office');
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9947-10-01', date '9948-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO ref.department (code, name, faculty_code) VALUES (dept, 'Check V405', (SELECT faculty_code FROM ref.programme WHERE code = 'C00023'));
        -- the semester's classes were opened with one course in the structure
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state) VALUES ('ZZG 101', 'Check first course', 2, 1, 100, dept, 'Core', 'LIVE');
        INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES ('ZZG 101', 'C00023', 100, 'Core');
        INSERT INTO catalogue.offering (id, course_code, session, semester) VALUES (gen_random_uuid(), 'ZZG 101', S, 1);
        -- a course uploaded into the structure afterwards: no class until asked; asked, its class opens; one of the second semester waits for that semester
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state) VALUES
            ('MOAU-ZZG 102', 'Check later course', 2, 1, 100, dept, 'Core', 'LIVE'), ('MOAU-ZZG 103', 'Check second-semester course', 2, 2, 100, dept, 'Core', 'LIVE'),
            ('BSU-ZZG 104', 'Check course in no structure', 2, 1, 100, dept, 'Core', 'LIVE'), ('ZZG 105', 'Check restored course', 2, 1, 100, dept, 'Core', 'LIVE');
        INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES
            ('MOAU-ZZG 102', 'C00023', 100, 'Core'), ('MOAU-ZZG 103', 'C00023', 100, 'Core'), ('ZZG 105', 'C00023', 100, 'Core');
        SELECT count(*) INTO v_unasked FROM catalogue.offering WHERE course_code IN ('MOAU-ZZG 102', 'MOAU-ZZG 103', 'ZZG 105') AND session = S;
        PERFORM catalogue.open_classes_for_courses(ARRAY['MOAU-ZZG 102', 'MOAU-ZZG 103']);
        SELECT count(*) INTO v_later FROM catalogue.offering WHERE course_code = 'MOAU-ZZG 102' AND session = S AND semester = 1 AND stream = 'REGULAR';
        SELECT count(*) INTO v_sem2 FROM catalogue.offering WHERE course_code = 'MOAU-ZZG 103' AND session = S;
        -- an ended course gets none while ended; restored and asked, it gets its class
        UPDATE catalogue.course SET state = 'ENDED', ended_on = current_date WHERE code = 'ZZG 105';
        PERFORM catalogue.open_classes_for_courses(ARRAY['ZZG 105']);
        SELECT count(*) INTO v_ended FROM catalogue.offering WHERE course_code = 'ZZG 105';
        UPDATE catalogue.course SET state = 'LIVE', ended_on = NULL WHERE code = 'ZZG 105';
        PERFORM catalogue.open_classes_for_courses(ARRAY['ZZG 105']);
        SELECT count(*) INTO v_restored FROM catalogue.offering WHERE course_code = 'ZZG 105' AND session = S AND semester = 1;
        -- the desk: the course in no structure is listed and named as such; the second-semester course is not (its semester is not open)
        SELECT string_agg(w.code || ':' || w.reason, ',' ORDER BY w.code) INTO v_missing FROM catalogue.courses_without_class(dept, S) w;
        -- opening the session's classes again, as the desk does, refuses nothing and leaves the department's list as it was (it opens every
        -- structure course's class in that semester, University-wide, as the calendar did)
        v_opened := registration.open_course_registration(S, 1);
        SELECT string_agg(w.code || ':' || w.reason, ',' ORDER BY w.code) INTO v_after FROM catalogue.courses_without_class(dept, S) w;
        RAISE EXCEPTION 'the V405 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V405/V406: a course that joins the structure later gets its class in every opened semester when asked, never unasked; the desk lists what has none and why',
        v_unasked = 0 AND v_later = 1 AND v_sem2 = 0 AND v_ended = 0 AND v_restored = 1 AND v_missing = 'BSU-ZZG 104:NOT_IN_STRUCTURE' AND v_opened >= 0 AND v_after = 'BSU-ZZG 104:NOT_IN_STRUCTURE',
        format('unasked=%s later=%s sem2=%s ended=%s restored=%s missing=%s opened_again=%s after=%s', v_unasked, v_later, v_sem2, v_ended, v_restored, v_missing, v_opened, v_after));
END $$;

-- ── V408. Course allocation from the ICT dashboards: a support posting may carry the course allocation capabilities; every
--          allocation, by any desk, is on catalogue.allocation_event with its reason, its desk and whom it replaced, the import's
--          as the import's; the checks say before anything is written why a person may not take a class; the conflicts list a
--          lead who holds no lecturer office ──
DO $$
DECLARE S text := '9981/9982'; who uuid := gen_random_uuid(); a uuid := gen_random_uuid(); b uuid := gen_random_uuid(); n uuid := gen_random_uuid();
        gone uuid := gen_random_uuid(); dept text := 'ZZJ9'; o uuid := gen_random_uuid(); heavy uuid := gen_random_uuid();
        v_caps boolean; v_events text; v_dup text; v_teach text; v_active text; v_cross text; v_load text; v_conflict text; v_import text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'ict', true); PERFORM set_config('moaum.reason', 'CHECK V408', true);
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (who, 'CHK/V408', 'CHECKV408', 'Director'),
            (a, 'CHK/V408A', 'CHECKV408A', 'Lecturer'), (b, 'CHK/V408B', 'CHECKV408B', 'Lecturer'), (n, 'CHK/V408N', 'CHECKV408N', 'Officeless');
        INSERT INTO iam.person (id, staff_number, surname, given_names, ended_on, ended_reason) VALUES (gone, 'CHK/V408G', 'CHECKV408G', 'Retired', current_date - 1, 'Retired');
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9981-10-01', date '9982-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO ref.department (code, name, faculty_code) VALUES (dept, 'Check V408', (SELECT faculty_code FROM ref.programme WHERE code = 'C00023'));
        INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from) VALUES
            (gen_random_uuid(), a, 'lecturer', 'department', dept, 'check', who, current_date),
            (gen_random_uuid(), b, 'lecturer', 'department', 'MTC', 'check', who, current_date),
            (gen_random_uuid(), gone, 'lecturer', 'department', dept, 'check', who, current_date);
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state) VALUES
            ('ZZJ 301', 'Check allocation', 3, 1, 300, dept, 'Core', 'LIVE'), ('ZZJ 302', 'Check heavy course', 10, 1, 300, dept, 'Core', 'LIVE');
        INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES ('ZZJ 301', 'C00023', 300, 'Core');
        INSERT INTO catalogue.offering (id, course_code, session, semester) VALUES (o, 'ZZJ 301', S, 1), (heavy, 'ZZJ 302', S, 1);
        -- a posting may carry the course allocation capabilities
        v_caps := ARRAY['VIEW_ALLOCATIONS', 'ALLOCATE_COURSES', 'REMOVE_ALLOCATIONS', 'BULK_ALLOCATE'] <@ helpdesk.support_capabilities();
        -- the checks before anything: a person who has left, one with no lecturer office, a lecturer of another department (allowed, said)
        SELECT level INTO v_active FROM catalogue.allocation_checks(o, gone, 'LECTURER') WHERE code = 'ACTIVE';
        SELECT level INTO v_teach FROM catalogue.allocation_checks(o, n, 'LECTURER') WHERE code = 'TEACHING';
        SELECT level || ':' || (words LIKE '%teaching across departments%')::text INTO v_cross FROM catalogue.allocation_checks(o, b, 'CO_LECTURER') WHERE code = 'TEACHING';
        -- allocated; the same allocation again refused in the University's words; reassigned with a reason; a co-lecturer added and removed
        PERFORM catalogue.allocate_offering(o, a, NULL, false);
        SELECT level || ':' || words INTO v_dup FROM catalogue.allocation_checks(o, a, 'LECTURER') WHERE code = 'DUPLICATE';
        PERFORM set_config('moaum.reason', 'CHECK V408 reassigned', true);
        PERFORM catalogue.allocate_offering(o, b, NULL, false);
        INSERT INTO catalogue.offering_teacher (offering_id, lecturer_id, added_by) VALUES (o, a, who);
        DELETE FROM catalogue.offering_teacher WHERE offering_id = o AND lecturer_id = a;
        SELECT string_agg(action || '/' || role || '/' || source || '/' || coalesce(actor_office, '-')
                          || CASE WHEN action = 'REASSIGNED' THEN '/' || (previous_lecturer_id = a)::text || '/' || reason ELSE '' END, ',' ORDER BY at)
          INTO v_events FROM catalogue.allocation_event WHERE offering_id = o;
        -- a lead over twelve units is said before the engine refuses it
        SELECT level INTO v_load FROM catalogue.allocation_checks(heavy, b, 'LECTURER') WHERE code = 'LOAD';
        -- a lead who holds no lecturer office, as an old record may stand, is listed as a conflict
        UPDATE catalogue.offering SET lecturer_id = n WHERE id = heavy;
        SELECT string_agg(kind, ',' ORDER BY kind) INTO v_conflict FROM catalogue.allocation_conflicts(S, 1) WHERE offering_id = heavy;
        -- the bulk import's writes are the import's on the history
        PERFORM set_config('moaum.allocation_source', 'IMPORT', true);
        INSERT INTO catalogue.offering_teacher (offering_id, lecturer_id, added_by) VALUES (heavy, a, who);
        SELECT source INTO v_import FROM catalogue.allocation_event WHERE offering_id = heavy AND action = 'CO_LECTURER_ADDED';
        PERFORM set_config('moaum.allocation_source', '', true);
        RAISE EXCEPTION 'the V408 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V408: a support posting may carry course allocation; every allocation is on the history with its reason, its desk and whom it replaced, the import''s as the import''s; the checks refuse a person who left, one with no lecturer office and the same allocation twice, allow teaching across departments and warn of an overload; a lead with no lecturer office is a conflict',
        v_caps AND v_active = 'ERROR' AND v_teach = 'ERROR' AND v_cross = 'OK:true'
        AND v_dup = 'ERROR:Course already allocated to this lecturer for the selected session and semester.'
        AND v_events = 'ALLOCATED/LECTURER/DESK/ict,REASSIGNED/LECTURER/DESK/ict/true/CHECK V408 reassigned,CO_LECTURER_ADDED/CO_LECTURER/DESK/ict,CO_LECTURER_REMOVED/CO_LECTURER/DESK/ict'
        AND v_load = 'WARNING' AND v_conflict = 'NO_TEACHING_OFFICE' AND v_import = 'IMPORT',
        format('caps=%s active=%s teach=%s cross=%s dup=%s events=%s load=%s conflict=%s import=%s', v_caps, v_active, v_teach, v_cross, v_dup, v_events, v_load, v_conflict, v_import));
END $$;

-- ── V409. Every payment classified by programme type, purpose, source module and responsible office: a payer's programme
--          type from their entry mode, then their programme's category; the owner of a payment by the most particular rule
--          (a GST fee is the GST office's whatever the programme); every category names its purpose; a student's payment on
--          the one ledger carries every dimension; a type the Bursary maps reclassifies at once ──
DO $$
DECLARE S text := '9985/9986'; who uuid := gen_random_uuid(); st uuid; v_types text; v_routes text; v_owners text; v_cats text; v_row text; v_mapped text; ref text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'registrar', true); PERFORM set_config('moaum.reason', 'CHECK V409', true);
        -- the programme types and the admission routes
        v_types := concat_ws(',', finance.programme_type_for('UTME', 'UNDER GRADUATE'), finance.programme_type_for('DIRECT_ENTRY', NULL),
                                  finance.programme_type_for('POSTGRADUATE', 'POST GRADUATE'), finance.programme_type_for('CCE', NULL),
                                  finance.programme_type_for('SANDWICH', NULL), finance.programme_type_for('JUPEB', NULL), finance.programme_type_for(NULL, 'ZZ NO SUCH'));
        v_routes := concat_ws(',', finance.admission_route_of('UTME'), finance.admission_route_of('DIRECT_ENTRY'), finance.admission_route_of('CCE'));
        -- who owns what: the most particular rule
        SELECT string_agg(x.purpose || '+' || x.ptype || '=' || o.source_module || '/' || o.responsible_office, ',' ORDER BY x.n) INTO v_owners
          FROM (VALUES (1, 'SCHOOL_FEES', 'UNDERGRADUATE'), (2, 'APPLICATION', 'UNDERGRADUATE'), (3, 'ACCEPTANCE_FEE', 'POSTGRADUATE'), (4, 'GST_FEE', 'CCE'),
                       (5, 'SCHOOL_FEES', 'SANDWICH'), (6, 'APPLICATION', 'JUPEB'), (7, 'HOSTEL_FEE', 'UNDERGRADUATE')) x(n, purpose, ptype)
          CROSS JOIN LATERAL finance.payment_owner(x.purpose, x.ptype) o;
        -- every category names its purpose; JUPEB's and EPS's payments fall in theirs
        SELECT concat_ws(',', (SELECT count(*) FROM finance.payment_category WHERE purpose IS NULL),
                              (SELECT purpose FROM finance.payment_category WHERE code = finance.categorise('JUPEB_APPLICATION', NULL)),
                              (SELECT purpose FROM finance.payment_category WHERE code = finance.categorise(NULL, 'EPS fee 2026/2027'))) INTO v_cats;
        -- a Sandwich student's school fees on the one ledger, every dimension on the row
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (who, 'CHK/V409', 'CHECKV409', 'Registry');
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9985-10-01', date '9986-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, sex, programme_code, entry_mode, entry_session, entry_level, current_level, status, study_mode, matriculated_at)
        VALUES (gen_random_uuid(), 'MOAUM/ADM/85/009985', 'MOAUM/CHK/85/409', 'CHECKV409', 'Sandwich', 'F', 'C00023', 'SANDWICH', S, 100, 100, 'ACTIVE', 'FULL_TIME', now())
        RETURNING id INTO st;
        ref := finance.new_purpose_reference(st, S, 200000, 'School fees (full session)');
        SELECT concat_ws('/', v.programme_type, v.admission_route, v.purpose_code, v.source_module, v.responsible_office, v.ledger_status) INTO v_row
          FROM reporting.payments v WHERE v.reference = ref;
        -- the Bursary maps a programme category to Preliminary: a programme of it is Preliminary at once
        PERFORM finance.set_programme_type('PRELIMINARY', 'Preliminary', '{}', ARRAY['ZZ PRELIMINARY'], NULL, 60, true, NULL);
        v_mapped := finance.programme_type_for(NULL, 'ZZ PRELIMINARY');
        RAISE EXCEPTION 'the V409 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V409: every payment is classified by programme type (entry mode, then programme category), purpose, source module and responsible office (the most particular rule; a GST fee is the GST office''s whatever the programme); every category names its purpose; a student''s payment carries every dimension on the one ledger; a category the Bursary maps reclassifies at once',
        v_types = 'UNDERGRADUATE,UNDERGRADUATE,POSTGRADUATE,CCE,SANDWICH,JUPEB,OTHER'
        AND v_routes = 'POST_UTME,DIRECT_ENTRY,CCE'
        AND v_owners = 'SCHOOL_FEES+UNDERGRADUATE=STUDENT_FINANCE/bursar,APPLICATION+UNDERGRADUATE=ADMISSIONS/academic,ACCEPTANCE_FEE+POSTGRADUATE=PG/pgschool,GST_FEE+CCE=GST/gst,SCHOOL_FEES+SANDWICH=SANDWICH/bursar,APPLICATION+JUPEB=JUPEB/jupeb,HOSTEL_FEE+UNDERGRADUATE=HOSTEL/housing'
        AND v_cats = '0,APPLICATION,EPS_FEE'
        AND v_row = 'SANDWICH/SANDWICH/SCHOOL_FEES/SANDWICH/bursar/PENDING'
        AND v_mapped = 'PRELIMINARY',
        format('types=%s routes=%s owners=%s cats=%s row=%s mapped=%s', v_types, v_routes, v_owners, v_cats, v_row, v_mapped));
END $$;

-- ── V410. The general-ledger sync posts in batches: at most the limit asked, oldest first, saying how many remain; what
--          remains is counted on the terms it is posted (every payment of the one ledger, paid refunds, paid vouchers);
--          every transaction is posted once whatever the batches; a sync of nothing at a time is refused; the sync without
--          a limit posts everything as before ──
DO $$
DECLARE S text := '9984/9985'; who uuid := gen_random_uuid(); st uuid; u0 bigint; u1 bigint; b1 record; b2 record; v_first text; v_after bigint;
        v_once text; v_zero text := 'accepted';
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'bursar', true); PERFORM set_config('moaum.reason', 'CHECK V410', true);
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (who, 'CHK/V410', 'CHECKV410', 'Bursary');
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9984-10-01', date '9985-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, sex, programme_code, entry_mode, entry_session, entry_level, current_level, status, study_mode, matriculated_at)
        VALUES (gen_random_uuid(), 'MOAUM/ADM/84/009984', 'MOAUM/CHK/84/410', 'CHECKV410', 'Ledger', 'M', 'C00023', 'UTME', S, 100, 100, 'ACTIVE', 'FULL_TIME', now())
        RETURNING id INTO st;
        SELECT payments + refunds + vouchers + wallet INTO u0 FROM finance.gl_unposted();
        -- three confirmed school-fee payments, older than anything else on the register
        INSERT INTO finance.payment_reference (student_id, session, reference, purpose, amount, expires_at, confirmed_at, confirmed_by, channel, receipt_no)
        SELECT st, S, 'MOAUM-FEE-V410-000' || n, 'School fees ' || S, 1000 * n, now() + interval '1 day', timestamptz '1901-01-01' + n * interval '1 day', who, 'Card', 'RCPT-V410-000' || n
          FROM generate_series(1, 3) n;
        SELECT payments + refunds + vouchers + wallet INTO u1 FROM finance.gl_unposted();
        -- one at a time: the oldest first, the rest counted
        SELECT * INTO b1 FROM finance.gl_sync(1);
        SELECT source_ref INTO v_first FROM finance.gl_journal WHERE source_type = 'PAYMENT' AND source_ref LIKE 'MOAUM-FEE-V410-%';
        -- two more, then everything without a limit, as before
        SELECT * INTO b2 FROM finance.gl_sync(2);
        PERFORM finance.gl_sync();
        SELECT payments + refunds + vouchers + wallet INTO v_after FROM finance.gl_unposted();
        -- every one posted once, balanced, whatever the batches
        SELECT string_agg(j.source_ref || '=' || (SELECT count(*) FROM finance.gl_posting p WHERE p.journal_id = j.id)
                          || '/' || (SELECT sum(p.debit) - sum(p.credit) FROM finance.gl_posting p WHERE p.journal_id = j.id), ',' ORDER BY j.source_ref) INTO v_once
          FROM finance.gl_journal j WHERE j.source_type = 'PAYMENT' AND j.source_ref LIKE 'MOAUM-FEE-V410-%';
        BEGIN
            PERFORM finance.gl_sync(0);
        EXCEPTION WHEN invalid_parameter_value THEN v_zero := 'refused';
        END;
        RAISE EXCEPTION 'the V410 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V410: the general-ledger sync posts at most the limit asked, oldest first, and says how many remain; what remains is counted on the terms it is posted; every transaction posts once, balanced, whatever the batches; a sync of nothing at a time is refused; the sync without a limit posts everything as before',
        u1 = u0 + 3
        AND b1.payments + b1.refunds + b1.vouchers = 1 AND b1.remaining = u1 - 1
        AND v_first = 'MOAUM-FEE-V410-0001'
        AND b2.payments + b2.refunds + b2.vouchers = 2 AND b2.remaining = u1 - 3
        AND v_after = 0
        AND v_once = 'MOAUM-FEE-V410-0001=2/0.00,MOAUM-FEE-V410-0002=2/0.00,MOAUM-FEE-V410-0003=2/0.00'
        AND v_zero = 'refused',
        format('u0=%s u1=%s b1=%s b2=%s first=%s after=%s once=%s zero=%s', u0, u1, b1, b2, v_first, v_after, v_once, v_zero));
END $$;

-- ── V411. The manual's new edition: the allocation desk's procedures read by the desks, an agent's only with the
--          posting's capability; the Payments Report by the offices that own a purpose; the Bursary's classification;
--          a first-edition procedure revised keeps its earlier wording as a version; the edition took its major step ──
DO $$
DECLARE v_ict text; v_agent text; v_owner text; v_bursar text; v_kept text; v_edition int;
BEGIN
    SELECT string_agg(slug, ',' ORDER BY slug) INTO v_ict FROM manual.procedures_for(ARRAY['ict'], '{}') WHERE slug LIKE 'alloc-desk-%';
    SELECT string_agg(slug, ',' ORDER BY slug) INTO v_agent FROM manual.procedures_for(ARRAY['ictagent'], ARRAY['VIEW_ALLOCATIONS']) WHERE slug LIKE 'cpo-allocat%';
    SELECT string_agg(o, ',' ORDER BY o) INTO v_owner FROM unnest(ARRAY['jupeb', 'cce', 'gst', 'eps', 'housing', 'student']) o
     WHERE EXISTS (SELECT 1 FROM manual.procedures_for(ARRAY[o], '{}') p WHERE p.slug = 'office-payments-report');
    SELECT string_agg(slug, ',' ORDER BY slug) INTO v_bursar FROM manual.procedures_for(ARRAY['bursar'], '{}') WHERE slug IN ('bursar-classification', 'bursar-books');
    -- the revision kept what the first edition said (where Manual Management had not edited it first)
    SELECT string_agg(p.slug || '=' || p.version || '/' || (SELECT count(*) FROM manual.procedure_version v WHERE v.procedure_id = p.id AND v.version = 1), ',' ORDER BY p.slug) INTO v_kept
      FROM manual.procedure p WHERE p.slug IN ('hod-allocate', 'bursar-books', 'jupeb-idcards-import') AND p.seeded;
    SELECT major INTO v_edition FROM manual.edition;
    PERFORM pg_temp.assert('V411: the manual''s new edition — the allocation desk''s procedures for the desks, an agent''s only with the posting''s capability; the Payments Report for the offices that own a purpose; the Bursary''s classification and batched sync; a revised procedure keeps its first wording as a version; the edition took its major step',
        v_ict = 'alloc-desk-allocate,alloc-desk-bulk,alloc-desk-lists,alloc-desk-reassign'
        AND v_agent = 'cpo-allocation-view'
        AND v_owner = 'cce,eps,gst,housing,jupeb'
        AND v_bursar = 'bursar-books,bursar-classification'
        AND (SELECT steps[2] LIKE '%2,000 at a time%' FROM manual.procedure WHERE slug = 'bursar-books')
        AND v_kept = 'bursar-books=2/1,hod-allocate=2/1,jupeb-idcards-import=2/1'
        AND v_edition >= 2,
        format('ict=%s agent=%s owner=%s bursar=%s kept=%s edition=%s', v_ict, v_agent, v_owner, v_bursar, v_kept, v_edition));
END $$;

-- ── V412: CCE — the readiness read, the documents an application lacks asked for in one click, the CCE checking fee named ──
-- The readiness of a CCE session in use is not ready until the Bursary states its three fees; an application's missing
-- documents are the ones not uploaded or rejected; asking sends it back for exactly those (the Centre only); nothing missing
-- is refused; asking a whole session leaves a recommended application alone; a CCE applicant's checking receipt says "CCE
-- admission checking"; the Director of ICT's checking rows leave CCE out. The block undoes its writes.
DO $$
DECLARE acad uuid := gen_random_uuid(); burs uuid := gen_random_uuid(); cce1 uuid := gen_random_uuid(); S text := '9945/9946'; pa text := 'C00023';
        b uuid; acct uuid; apps uuid[] := '{}'; i int; r0 jsonb; r1 jsonb; miss1 text; miss2 text; miss4 text; note1 text; st1 text;
        r_none text; r_office text; r_bulk_office text; bulk jsonb; st3 text; st4 text; ref text; receipt int; ict_rows int; cce_rows int; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.reason', 'check V412', true);
        PERFORM set_config('moaum.actor_id', acad::text, true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9945-10-01', date '9946-08-31') ON CONFLICT (name) DO NOTHING;
        PERFORM policy.set_route_session('CCE', -1, S, 'the check runs in a session of its own', NULL);
        PERFORM ref.set_programme_route(pa, 'CCE', true, NULL, NULL, 'the check');
        b := admissions.cce_preview(S, 'cce-412.xlsx', repeat('f', 64), (SELECT jsonb_agg(jsonb_build_object('jamb_reg_no', '994500000' || n || '0CC', 'surname', 'Zzfour', 'first_name', 'Twelve' || n,
                     'date_of_birth', '1990-01-0' || n, 'sex', 'F', 'phone', '0803555040' || n, 'email', 'v412.' || n || '@example.com', 'programme_code', pa)) FROM generate_series(1, 4) n));
        PERFORM admissions.cce_commit(b);
        PERFORM policy.window_act('CCE_APPLICATION', S, NULL, 'OPEN', NULL, NULL, NULL, NULL, NULL, acad, 'ict');
        FOR i IN 1 .. 4 LOOP
            acct := admissions.cce_register('994500000' || i || '0CC', ('1990-01-0' || i)::date, 'zz.v412.' || i || '@example.com', '0803555040' || i, '$2a$12$' || repeat('x', 53));
            apps := apps || (SELECT id FROM admissions.application WHERE account_id = acct);
        END LOOP;

        -- (1) the readiness: in use (a list), not ready until the Bursary states the three fees
        r0 := admissions.cce_readiness(S);
        PERFORM set_config('moaum.actor_id', burs::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM admissions.set_route_fee(S, 'CCE', 10000, 0, 10000, 3000);
        r1 := admissions.cce_readiness(S);

        -- (2) four submitted applications: two documents of four; all four; recommended with two; under review with one rejected
        UPDATE admissions.application SET fee_confirmed_at = now(), submitted_at = now() WHERE id = ANY (apps);
        UPDATE admissions.cce_review SET state = 'SUBMITTED', submitted_at = now() WHERE application_id IN (apps[1], apps[2]);
        UPDATE admissions.cce_review SET state = 'RECOMMENDED', submitted_at = now(), recommended_at = now(), recommended_by = cce1 WHERE application_id = apps[3];
        UPDATE admissions.cce_review SET state = 'UNDER_REVIEW', submitted_at = now(), review_started_at = now(), review_started_by = cce1 WHERE application_id = apps[4];
        INSERT INTO admissions.application_document (id, application_id, kind, filename, content_type, bytes)
        SELECT gen_random_uuid(), x.app, x.kind, lower(x.kind) || '.pdf', 'application/pdf', 1000
          FROM (VALUES (apps[1], 'PASSPORT'), (apps[1], 'OLEVEL_STATEMENT'),
                       (apps[2], 'PASSPORT'), (apps[2], 'OLEVEL_STATEMENT'), (apps[2], 'BIRTH_CERT'), (apps[2], 'STATE_OF_ORIGIN'),
                       (apps[3], 'PASSPORT'), (apps[3], 'OLEVEL_STATEMENT'),
                       (apps[4], 'PASSPORT'), (apps[4], 'OLEVEL_STATEMENT'), (apps[4], 'BIRTH_CERT')) x(app, kind);
        INSERT INTO admissions.application_document (id, application_id, kind, filename, content_type, bytes, status, review_note, reviewed_at, reviewed_by)
        VALUES (gen_random_uuid(), apps[4], 'STATE_OF_ORIGIN', 'origin.pdf', 'application/pdf', 1000, 'REJECTED', 'Not legible', now(), cce1);
        miss1 := array_to_string(admissions.cce_missing_documents(apps[1]), ',');
        miss2 := array_to_string(admissions.cce_missing_documents(apps[2]), ',');
        miss4 := array_to_string(admissions.cce_missing_documents(apps[4]), ',');

        -- (3) asked for exactly those: by the Centre only; nothing missing is refused; a session at once leaves the recommended one
        PERFORM set_config('moaum.actor_id', acad::text, true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        BEGIN PERFORM admissions.cce_ask_missing(apps[1]); r_office := 'ASKED';
        EXCEPTION WHEN check_violation THEN r_office := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM admissions.cce_ask_missing_all(S); r_bulk_office := 'ASKED';
        EXCEPTION WHEN check_violation THEN r_bulk_office := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_id', cce1::text, true);
        PERFORM set_config('moaum.actor_office', 'cce', true);
        note1 := admissions.cce_ask_missing(apps[1]);
        SELECT state INTO st1 FROM admissions.cce_review WHERE application_id = apps[1];
        BEGIN PERFORM admissions.cce_ask_missing(apps[2]); r_none := 'ASKED';
        EXCEPTION WHEN check_violation THEN r_none := split_part(SQLERRM, ':', 1); END;
        bulk := admissions.cce_ask_missing_all(S);
        SELECT state INTO st3 FROM admissions.cce_review WHERE application_id = apps[3];
        SELECT state INTO st4 FROM admissions.cce_review WHERE application_id = apps[4];

        -- (4) published, the CCE checking fee paid: the receipt says CCE admission checking; ICT's rows leave CCE out
        UPDATE admissions.application SET decision = 'NOT_OFFERED', decided_at = now(), decision_released_at = now() WHERE id = apps[2];
        PERFORM set_config('moaum.actor_id', burs::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        ref := admissions.new_fee_reference(apps[2], 'CHECKING');
        PERFORM admissions.confirm_fee(ref, 'BANK', 'check');
        SELECT count(*) INTO receipt FROM platform.notice WHERE about_id = apps[2] AND channel = 'EMAIL' AND body LIKE '%CCE admission checking fee%'
                                                           AND body LIKE '%read the outcome of your application%';
        SELECT count(*) INTO ict_rows FROM admissions.status_checking_rows(S);
        SELECT count(*) INTO cce_rows FROM admissions.status_checking_rows(S, true);
        RAISE EXCEPTION 'the V412 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V412 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V412: CCE — a CCE session in use is not ready until the Bursary states its three fees; an application''s missing documents (not uploaded or rejected) are asked for in one click by the Centre only, nothing missing is refused, a whole session leaves a recommended one; the CCE checking receipt says so; the ICT checking rows leave CCE out',
        coalesce((r0->>'inUse')::boolean AND NOT (r0->>'feesStated')::boolean AND NOT (r0->>'ready')::boolean AND (r0->>'listed')::int = 4
                 AND (r1->>'feesStated')::boolean AND (r1->>'checkingStated')::boolean AND (r1->>'ready')::boolean AND (r1->>'checkingFee')::numeric = 3000
                 AND miss1 = 'BIRTH_CERT,STATE_OF_ORIGIN' AND miss2 = '' AND miss4 = 'STATE_OF_ORIGIN'
                 AND r_office = 'CCE_OFFICE' AND r_bulk_office = 'CCE_OFFICE'
                 AND note1 = 'Upload your birth certificate and your certificate of state of origin, then send the application back to the Centre.'
                 AND st1 = 'DOCUMENTS_PENDING' AND r_none = 'CCE_NOTHING_MISSING'
                 AND (bulk->>'asked')::int = 1 AND (bulk->>'recommendedLeft')::int = 1 AND st3 = 'RECOMMENDED' AND st4 = 'DOCUMENTS_PENDING'
                 AND receipt = 1 AND ict_rows = 0 AND cce_rows = 4, false),
        format('before %s | after %s | missing %s / %s / %s | office %s bulk-office %s | note %s state %s none %s | bulk %s three %s four %s | receipt %s ict %s cce %s',
               r0, r1, miss1, miss2, miss4, r_office, r_bulk_office, note1, st1, r_none, bulk, st3, st4, receipt, ict_rows, cce_rows));
END $$;

-- ── V413. A registration holding the other code family's code is listed for the session and moved to the cohort's class (opened if
--          owed); a line with a score on it is not moved; the sweep's repeated answer for a reference is counted on its open row ──
DO $$
DECLARE S text := '9946/9947'; who uuid := gen_random_uuid(); dept text := 'ZZH9'; st uuid := gen_random_uuid(); reg uuid := gen_random_uuid();
        om uuid := gen_random_uuid(); ob uuid; es uuid := gen_random_uuid(); sh uuid := gen_random_uuid();
        v_saved text; v_listed text; v_moved uuid; v_after text; v_entry text; r_scored text; v_ev uuid; v_first boolean; v_second boolean; v_times int;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'academic', true); PERFORM set_config('moaum.reason', 'CHECK V413', true);
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (who, 'CHK/V413', 'CHECKV413', 'Office');
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9946-10-01', date '9947-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO ref.department (code, name, faculty_code) VALUES (dept, 'Check V413', (SELECT faculty_code FROM ref.programme WHERE code = 'C00023'));
        -- the same course under both codes, both in the structure; the MOAU- class open, the BSU- class not yet
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state) VALUES
            ('BSU-ZZH 301', 'Check code family move', 3, 1, 300, dept, 'Core', 'LIVE'), ('MOAU-ZZH 301', 'Check code family move', 3, 1, 300, dept, 'Core', 'LIVE');
        INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES ('BSU-ZZH 301', 'C00023', 300, 'Core'), ('MOAU-ZZH 301', 'C00023', 300, 'Core');
        INSERT INTO catalogue.offering (id, course_code, session, semester) VALUES (om, 'MOAU-ZZH 301', S, 1);
        -- a 300-level student of the BSU- cohort, registered on the MOAU- class before V402
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (st, 'MOAUM/ADM/46/000413', 'MOAUM/CHK/46/413', 'CHECKV413', 'Invented', 'C00023', 'UTME', '9940/9941', 100, 300, 'ACTIVE', now());
        INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, submitted_at) VALUES (reg, st, S, 1, 300, 'SUBMITTED', now());
        INSERT INTO registration.entry (registration_id, offering_id, units, status) VALUES (reg, om, 3, 'REGISTERED');
        SELECT moau_from_entry_session INTO v_saved FROM catalogue.code_family_setting WHERE id = 1;
        UPDATE catalogue.code_family_setting SET moau_from_entry_session = S WHERE id = 1;   -- this cohort (9940/9941) registers BSU-
        SELECT string_agg(x.course_code || '>' || coalesce(x.own_code, '-') || ':' || CASE WHEN x.own_offering_id IS NULL THEN 'no class' ELSE 'class' END || '/' || x.scored, ',')
          INTO v_listed FROM catalogue.other_family_registrations(S) x WHERE x.student_id = st;
        -- moved: the BSU- class is opened (the structure offers it, the semester has classes) and the line is on it
        v_moved := catalogue.move_entry_to_own_code(reg, om, 'registered before the cohort rule');
        SELECT o.course_code INTO v_entry FROM registration.entry e JOIN catalogue.offering o ON o.id = e.offering_id WHERE e.registration_id = reg AND e.status = 'REGISTERED';
        SELECT coalesce(string_agg(x.course_code, ','), '') INTO v_after FROM catalogue.other_family_registrations(S) x WHERE x.student_id = st;
        -- a line with a score on it is not moved: back on the MOAU- class with a score entered
        UPDATE registration.entry SET offering_id = om WHERE registration_id = reg AND offering_id = v_moved;
        INSERT INTO assessment.exam_session (id, session, semester, kind, exams_from, exams_to, sheets_due, state) VALUES (es, S, 1, 'MAIN', date '9947-01-10', date '9947-01-20', date '9947-02-10', 'OPEN') ON CONFLICT DO NOTHING;
        INSERT INTO assessment.score_sheet (id, offering_id, exam_session_id, stage) VALUES (sh, om, (SELECT id FROM assessment.exam_session WHERE session = S AND semester = 1 AND kind = 'MAIN' LIMIT 1), 'ENTRY');
        INSERT INTO assessment.score (sheet_id, student_id, ca, exam) VALUES (sh, st, 20, 40);
        BEGIN PERFORM catalogue.move_entry_to_own_code(reg, om, 'again'); r_scored := 'MOVED';
        EXCEPTION WHEN check_violation THEN r_scored := split_part(SQLERRM, ':', 1); END;
        UPDATE catalogue.code_family_setting SET moau_from_entry_session = v_saved WHERE id = 1;
        -- the sweep's repeats: the first answer is a row, the same answer again is counted on it, a different answer is not
        v_ev := finance.log_gateway_event('quickteller', 'SWEEP', 'verify', 'ZZH-SWEEP-413', NULL, NULL, 'empty answer', true, 'GATEWAY_ERROR', '{}'::jsonb);
        v_first := finance.collapse_sweep_repeat('quickteller', 'ZZH-SWEEP-413', 'empty answer', '{"again": true}'::jsonb);
        v_second := finance.collapse_sweep_repeat('quickteller', 'ZZH-SWEEP-413', 'a different answer', '{}'::jsonb);
        SELECT times INTO v_times FROM finance.gateway_event WHERE id = v_ev;
        RAISE EXCEPTION 'the V413 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V413: a registration under the other code family is listed and moved to the cohort''s class, not when scored; sweep repeats are counted on one row',
        v_listed = 'MOAU-ZZH 301>BSU-ZZH 301:no class/false' AND v_moved IS NOT NULL AND v_entry = 'BSU-ZZH 301' AND v_after = ''
        AND r_scored = 'CODE_FAMILY_SCORED' AND v_first AND NOT v_second AND v_times = 2,
        format('listed=%s moved=%s entry=%s after=%s scored=%s first=%s second=%s times=%s', v_listed, v_moved IS NOT NULL, v_entry, v_after, r_scored, v_first, v_second, v_times));
END $$;

-- ── V417. A stored gateway secret shown to a person is a row on the record, by a person with a reason, carried by the audit spine ──
DO $$
DECLARE who uuid := gen_random_uuid(); v uuid; r_nobody text; r_why text; v_audited int;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', '', true); PERFORM set_config('moaum.actor_office', '', true);
        BEGIN PERFORM finance.note_secret_view('paydirect', 'notification key', 'certification'); r_nobody := 'NOTED';
        EXCEPTION WHEN check_violation THEN r_nobody := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'ict', true); PERFORM set_config('moaum.reason', 'CHECK V417', true);
        BEGIN PERFORM finance.note_secret_view('paydirect', 'notification key', '  '); r_why := 'NOTED';
        EXCEPTION WHEN check_violation THEN r_why := split_part(SQLERRM, ':', 1); END;
        v := finance.note_secret_view('paydirect', 'notification key', 'given to Interswitch again');
        SELECT count(*) INTO v_audited FROM audit.entries e WHERE e.subject_type = 'finance.gateway_secret_view' AND e.subject_id = v;
        RAISE EXCEPTION 'the V417 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V417: a stored gateway secret shown to a person is a row on the record — by a person, with a reason — carried by the audit spine',
        r_nobody = 'SECRET_VIEW_ACTOR' AND r_why = 'SECRET_VIEW_REASON' AND v IS NOT NULL AND v_audited >= 1,
        format('nobody=%s why=%s noted=%s audited=%s', r_nobody, r_why, v IS NOT NULL, v_audited));
END $$;

-- ── V415. Fresh and final clearance as workflows on the one clearance engine: a student who is not eligible is started
--          only by an override with a reason; a process carries a public reference; the hostel stage does not apply to a
--          student with no hostel and does to one who applied; a sequential stage waits for the earlier ones; the Bursary
--          and the Library clear only against the record (fees stated and paid, nothing on loan) unless overridden with a
--          reason, kept with the state it replaced; a hold needs a reason; the clearance completes when every required stage that applies is cleared, the
--          student told at each word; the final clearance is the convocation gate, held only by the stages that apply;
--          the workflow purposes are not gates of the Bursar's scheme ──
DO $$
DECLARE S text := '9979/9980'; who uuid := gen_random_uuid(); a uuid := gen_random_uuid(); b uuid := gen_random_uuid(); fin uuid := gen_random_uuid();
        pa uuid; pb uuid; pf uuid; v_elig text; v_refused text := 'accepted'; v_ref text; v_stages text; v_wait text := 'accepted'; v_bursary text := 'accepted';
        v_reason text := 'accepted'; v_override text; v_overall text; v_done boolean; v_hostel text; v_told int; v_gate text; v_gate_clear boolean;
        v_alumni text; v_gates text; v_owed text; v_unstated text; v_loan text := 'accepted'; itm uuid := gen_random_uuid(); ln uuid := gen_random_uuid();
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'registrar', true); PERFORM set_config('moaum.reason', 'CHECK V415', true);
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (who, 'CHK/V415', 'CHECKV415', 'Registry');
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9979-10-01', date '9980-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO people.student (id, admission_no, surname, other_names, sex, programme_code, entry_mode, entry_session, entry_level, current_level, status, study_mode)
        VALUES (a, 'MOAUM/ADM/79/009971', 'CHECKV415', 'Fresh', 'F', 'C00023', 'UTME', S, 100, 100, 'ADMITTED', 'FULL_TIME'),
               (b, 'MOAUM/ADM/79/009972', 'CHECKV415', 'Hostel', 'M', 'C00023', 'UTME', S, 100, 100, 'ADMITTED', 'FULL_TIME');
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, sex, programme_code, entry_mode, entry_session, entry_level, current_level, status, study_mode, matriculated_at)
        VALUES (fin, 'MOAUM/ADM/79/009973', 'MOAUM/CHK/79/415', 'CHECKV415', 'Finalist', 'F', 'C00023', 'UTME', S, 100, 400, 'ACTIVE', 'FULL_TIME', now());
        INSERT INTO people.student_contact (student_id, phone, email) VALUES (a, '08000000415', 'v415@example.test');
        INSERT INTO hostel.application (id, student_id, session, applied_at, state) VALUES (gen_random_uuid(), b, S, now(), 'APPLIED');
        -- not eligible (no admission on the portal): refused, unless an override with a reason
        SELECT array_to_string(reasons, ';') INTO v_elig FROM clearance.eligibility_rows('FRESH', S, ARRAY[a]);
        BEGIN PERFORM clearance.start('FRESH', a, S, 'MANUAL', NULL, who, 'registrar'); EXCEPTION WHEN check_violation THEN v_refused := split_part(SQLERRM, ':', 1); END;
        pa := clearance.start('FRESH', a, S, 'OVERRIDE', 'CHECK: admitted before the portal kept admissions', who, 'registrar');
        pb := clearance.start('FRESH', b, S, 'OVERRIDE', 'CHECK: admitted before the portal kept admissions', who, 'registrar');
        SELECT reference INTO v_ref FROM clearance.process WHERE id = pa;
        SELECT string_agg(unit || '=' || state, ',' ORDER BY ord) INTO v_stages FROM clearance.stage_rows('FRESH', S, ARRAY[a]);
        SELECT state INTO v_hostel FROM clearance.stage_rows('FRESH', S, ARRAY[b]) WHERE unit = 'HOSTEL';
        -- a sequential stage waits; the Bursary clears only against the record; a hold names its reason
        BEGIN PERFORM clearance.decide(pa, 'DEPARTMENT', 'CLEARED', NULL, NULL, NULL, false, who, 'registrar'); EXCEPTION WHEN check_violation THEN v_wait := split_part(SQLERRM, ':', 1); END;
        v_owed := clearance.blocker(pa, 'BURSARY', '{"stated": true, "outstanding": 5000}'::jsonb);
        v_unstated := clearance.blocker(pa, 'BURSARY', '{"stated": false}'::jsonb);
        BEGIN PERFORM clearance.decide(pa, 'BURSARY', 'NOT_CLEARED', NULL, NULL, NULL, false, who, 'bursar'); EXCEPTION WHEN check_violation THEN v_reason := split_part(SQLERRM, ':', 1); END;
        PERFORM clearance.decide(pa, 'BURSARY', 'CLEARED', 'CHECK: paid on the old ledger, verified by the Bursar', NULL, NULL, true, who, 'registrar');
        SELECT override || '/' || previous_state INTO v_override FROM clearance.item WHERE process_id = pa AND unit = 'BURSARY' ORDER BY decided_at DESC LIMIT 1;
        PERFORM clearance.decide(pa, 'DEPARTMENT', 'CLEARED', NULL, NULL, NULL, false, who, 'hod');
        PERFORM clearance.decide(pa, 'FACULTY', 'CLEARED', NULL, NULL, NULL, false, who, 'dean');
        -- the Library clears against its loans: refused while a book is out, cleared once it is back
        INSERT INTO library.item (id, title) VALUES (itm, 'CHECK V415 book');
        INSERT INTO library.copy (accession, item_id, state) VALUES ('CHK/9415', itm, 'ON_LOAN');
        INSERT INTO library.loan (id, accession, student_id, due_on) VALUES (ln, 'CHK/9415', a, current_date + 7);
        BEGIN PERFORM clearance.decide(pa, 'LIBRARY', 'CLEARED', NULL, NULL, NULL, false, who, 'library'); EXCEPTION WHEN check_violation THEN v_loan := split_part(SQLERRM, ':', 2); END;
        UPDATE library.loan SET returned_at = now() WHERE id = ln;
        PERFORM clearance.decide(pa, 'LIBRARY', 'CLEARED', NULL, NULL, NULL, false, who, 'library');
        v_overall := clearance.decide(pa, 'HEALTH', 'CLEARED', NULL, NULL, NULL, false, who, 'services');
        SELECT completed_at IS NOT NULL INTO v_done FROM clearance.process WHERE id = pa;
        SELECT count(*) INTO v_told FROM platform.notice WHERE about_id = a;
        -- final clearance is the convocation gate: held by the stages that apply, never by a hostel the student never had
        pf := clearance.start('FINAL', fin, S, 'MANUAL', NULL, who, 'registrar');
        SELECT string_agg(unit, ',' ORDER BY ord) INTO v_gate FROM clearance.position(fin, 'CONVOCATION');
        v_gate_clear := clearance.is_clear(fin, 'CONVOCATION');
        v_alumni := clearance.blocker(pf, 'ALUMNI', clearance.evidence(pf, 'ALUMNI'));
        SELECT string_agg(code, ',' ORDER BY code) INTO v_gates FROM ref.clearance_purpose WHERE NOT gate;
        RAISE EXCEPTION 'the V415 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V415: fresh and final clearance as workflows — an ineligible student only by an override with a reason; a public reference; the hostel stage only for a student who applied; a sequential stage waits; the Bursary clears only against the record unless overridden (kept with the state it replaced); a hold needs a reason; complete when every required stage that applies is cleared, the student told; final clearance is the convocation gate held only by the stages that apply; the workflows are not gates of the Bursar''s scheme',
        v_elig = 'No admission on the portal: start by hand'
        AND v_refused = 'CLR_NOT_ELIGIBLE'
        AND v_ref ~ '^CLR/[0-9]{4}/[0-9]{6}$'
        AND v_stages = 'BURSARY=PENDING,DEPARTMENT=WAITING,FACULTY=WAITING,LIBRARY=WAITING,HEALTH=WAITING,HOSTEL=NOT_APPLICABLE'
        AND v_hostel = 'WAITING'
        AND v_wait = 'CLR_STAGE_WAITING' AND v_reason = 'CLR_REASON'
        AND v_owed = 'Outstanding fees: ₦5,000 for 9979/9980' AND v_unstated LIKE 'The 9979/9980 fees are not stated%'
        AND btrim(v_loan) = '1 item(s) on loan not returned'
        AND v_override = 'true/PENDING'
        AND v_overall = 'CLEARED' AND v_done AND v_told >= 6
        AND v_gate = 'BURSARY,DEPARTMENT,FACULTY,LIBRARY,HEALTH,WORKS,ALUMNI' AND NOT v_gate_clear
        AND v_alumni = 'The student has not confirmed their alumni details'
        AND v_gates = 'FRESH,RETURNING',
        format('elig=%s refused=%s ref=%s stages=%s hostel=%s wait=%s owed=%s unstated=%s loan=%s reason=%s override=%s overall=%s done=%s told=%s gate=%s/%s alumni=%s gates=%s',
               v_elig, v_refused, v_ref, v_stages, v_hostel, v_wait, v_owed, v_unstated, v_loan, v_reason, v_override, v_overall, v_done, v_told, v_gate, v_gate_clear, v_alumni, v_gates));
END $$;

-- ── V414: the current session is never a draft or cancelled one; what a CCE applicant still has to do ──
-- With a newer DRAFT and a newer CANCELLED session on the calendar, policy.university_current_session() answers the CURRENT
-- session, else the latest that ran, else a PLANNED one — never the draft or the cancelled. A CCE applicant's outstanding list
-- follows the application: the fee first, then the form, nothing while the Centre reviews, what the Centre asks for, the
-- checking fee once the outcome is published, the acceptance fee once the offer is read, nothing once accepted.
DO $$
DECLARE acad uuid := gen_random_uuid(); burs uuid := gen_random_uuid(); cce1 uuid := gen_random_uuid(); S text := '9943/9944'; pa text := 'C00023';
        b uuid; acct uuid; app uuid; cur text; cur_state text; expected text; o1 text; o1_amount numeric; o2 text; o3 int; o4 text; o4_detail text;
        o5 text; o5_amount numeric; o6 text; o6_amount numeric; o7 int; ref text; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.reason', 'check V414', true);
        PERFORM set_config('moaum.actor_id', acad::text, true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        -- (1) a newer draft and a newer cancelled session never become the University's current one
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on, state) VALUES (gen_random_uuid(), '9998/9999', date '9998-10-01', date '9999-08-31', 'DRAFT')
        ON CONFLICT (name) DO NOTHING;
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on, state, merged_reason) VALUES (gen_random_uuid(), '9996/9997', date '9996-10-01', date '9997-08-31', 'CANCELLED', 'the check')
        ON CONFLICT (name) DO NOTHING;
        cur := policy.university_current_session();
        SELECT state INTO cur_state FROM policy.academic_session WHERE name = cur;
        expected := coalesce((SELECT name FROM policy.academic_session WHERE state = 'CURRENT' LIMIT 1),
                             (SELECT max(name) FROM policy.academic_session WHERE state IN ('CLOSED', 'ARCHIVED')),
                             (SELECT max(name) FROM policy.academic_session WHERE state = 'PLANNED' AND (now() AT TIME ZONE 'Africa/Lagos')::date BETWEEN starts_on AND ends_on),
                             (SELECT max(name) FROM policy.academic_session WHERE state = 'PLANNED'));

        -- (2) a CCE applicant, the fees stated: the fee first
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9943-10-01', date '9944-08-31') ON CONFLICT (name) DO NOTHING;
        PERFORM policy.set_route_session('CCE', -1, S, 'the check runs in a session of its own', NULL);
        PERFORM ref.set_programme_route(pa, 'CCE', true, NULL, NULL, 'the check');
        b := admissions.cce_preview(S, 'cce-413.xlsx', repeat('7', 64), jsonb_build_array(
            jsonb_build_object('jamb_reg_no', '99430000013CC', 'surname', 'Zzthirteen', 'first_name', 'Owed', 'date_of_birth', '1990-02-02', 'sex', 'F',
                               'phone', '08035550613', 'email', 'v413@example.com', 'programme_code', pa)));
        PERFORM admissions.cce_commit(b);
        PERFORM policy.window_act('CCE_APPLICATION', S, NULL, 'OPEN', NULL, NULL, NULL, NULL, NULL, acad, 'ict');
        acct := admissions.cce_register('99430000013CC', date '1990-02-02', 'zz.v413@example.com', '08035550613', '$2a$12$' || repeat('x', 53));
        SELECT id INTO app FROM admissions.application WHERE account_id = acct;
        PERFORM set_config('moaum.actor_id', burs::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM admissions.set_route_fee(S, 'CCE', 10000, 0, 10000, 3000);
        SELECT string_agg(item, ','), max(amount) INTO o1, o1_amount FROM admissions.cce_outstanding(app);
        -- (3) paid: the form; (4) submitted: nothing while the Centre reviews; (5) the Centre asks: what it asked
        ref := admissions.new_fee_reference(app, 'APPLICATION');
        PERFORM admissions.confirm_fee(ref, 'BANK', 'check');
        SELECT string_agg(item, ',') INTO o2 FROM admissions.cce_outstanding(app);
        UPDATE admissions.application SET submitted_at = now() WHERE id = app;
        UPDATE admissions.cce_review SET state = 'SUBMITTED', submitted_at = now() WHERE application_id = app;
        SELECT count(*) INTO o3 FROM admissions.cce_outstanding(app);
        PERFORM set_config('moaum.actor_id', cce1::text, true);
        PERFORM set_config('moaum.actor_office', 'cce', true);
        PERFORM admissions.cce_ask_missing(app);
        SELECT string_agg(item, ','), max(detail) INTO o4, o4_detail FROM admissions.cce_outstanding(app);
        -- (6) published: the checking fee; (7) paid and read: the acceptance fee; (8) accepted: nothing
        UPDATE admissions.cce_review SET state = 'UNDER_REVIEW' WHERE application_id = app;   -- the review's own path is V379's; here only the release matters
        UPDATE admissions.application SET decision = 'OFFERED', decision_basis = 'OTHER', decided_at = now(), decision_released_at = now() WHERE id = app;
        SELECT string_agg(item, ','), max(amount) INTO o5, o5_amount FROM admissions.cce_outstanding(app);
        PERFORM set_config('moaum.actor_id', burs::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        ref := admissions.new_fee_reference(app, 'CHECKING');
        PERFORM admissions.confirm_fee(ref, 'BANK', 'check');
        PERFORM set_config('moaum.actor_id', acct::text, true);
        PERFORM set_config('moaum.actor_office', 'applicant', true);
        PERFORM admissions.admission_status_checked(app);
        SELECT string_agg(item, ','), max(amount) INTO o6, o6_amount FROM admissions.cce_outstanding(app);
        UPDATE admissions.application SET accepted_at = now(), acceptance_confirmed_at = now() WHERE id = app;
        SELECT count(*) INTO o7 FROM admissions.cce_outstanding(app);
        RAISE EXCEPTION 'the V414 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V414 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V414: the University''s current session is the CURRENT one, else the latest that ran, else a PLANNED one — never a draft or a cancelled session; a CCE applicant''s outstanding list follows the application: the fee first, the form, nothing under review, what the Centre asks, the checking fee once published, the acceptance fee once the offer is read, nothing once accepted',
        coalesce(cur = expected AND cur_state NOT IN ('DRAFT', 'CANCELLED') AND cur NOT IN ('9998/9999', '9996/9997')
                 AND o1 = 'APPLICATION_FEE' AND o1_amount = 10000 AND o2 = 'FORM' AND o3 = 0
                 AND o4 = 'CENTRE_ASKED' AND o4_detail LIKE 'Upload your passport photograph%'
                 AND o5 = 'CHECKING_FEE' AND o5_amount = 3000 AND o6 = 'ACCEPTANCE_FEE' AND o6_amount = 10000 AND o7 = 0, false),
        format('current %s (%s, expected %s) | fee %s %s | paid %s | submitted %s | asked %s: %s | published %s %s | read %s %s | accepted %s',
               cur, cur_state, expected, o1, o1_amount, o2, o3, o4, o4_detail, o5, o5_amount, o6, o6_amount, o7));
END $$;

-- ── V419. When an application window opens for a session whose applicant fees are not stated, the Bursary is told once, with what
--          the rule does meanwhile; a session whose fees are stated opens quietly ──
DO $$
DECLARE S text := '9945/9946'; T text := '9944/9945'; who uuid := gen_random_uuid(); bursar uuid := gen_random_uuid();
        v_before int; v_after int; v_subject text; v_body text; v_stated_after int;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'ict', true); PERFORM set_config('moaum.reason', 'CHECK V419', true);
        INSERT INTO iam.person (id, staff_number, surname, given_names, email) VALUES (bursar, 'CHK/V419', 'CHECKBURSAR', 'Office', 'check-v419-bursar@example.com');
        INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from) VALUES (gen_random_uuid(), bursar, 'bursar', 'institution', NULL, 'CHECK V419', who, current_date - 1);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9945-10-01', date '9946-08-31'), (gen_random_uuid(), T, date '9944-10-01', date '9945-08-31') ON CONFLICT (name) DO NOTHING;
        DELETE FROM admissions.applicant_fee WHERE session IN (S, T);
        SELECT count(*) INTO v_before FROM platform.notice WHERE recipient = 'check-v419-bursar@example.com';
        -- the window opened for a session with no fees stated: the Bursary is told once
        PERFORM policy.window_act('POST_UTME_REGISTRATION', S, NULL, 'OPEN', NULL, NULL, NULL, false, 'check: window opened', who, 'ict');
        SELECT count(*), max(subject), max(body) INTO v_after, v_subject, v_body FROM platform.notice WHERE recipient = 'check-v419-bursar@example.com';
        -- a session whose fees are stated opens without a word
        INSERT INTO admissions.applicant_fee (session, application_fee, portal_charge, acceptance_fee) VALUES (T, 2000, 300, 50000);
        PERFORM policy.window_act('POST_UTME_REGISTRATION', T, NULL, 'OPEN', NULL, NULL, NULL, false, 'check: window opened', who, 'ict');
        SELECT count(*) INTO v_stated_after FROM platform.notice WHERE recipient = 'check-v419-bursar@example.com';
        RAISE EXCEPTION 'the V419 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V419: the Bursary is told once when an application window opens on unstated applicant fees; a stated session opens quietly',
        v_after = v_before + 1 AND v_subject LIKE 'Applicant fees for ' || S || ' are not stated%' AND v_body LIKE '%' || S || '%' AND v_stated_after = v_after,
        format('before=%s after=%s stated_after=%s subject=%s', v_before, v_after, v_stated_after, v_subject));
END $$;

-- ── V418: CCE applicants reminded of what is outstanding ──
-- A CCE applicant who has not paid is reminded of the application fee once the rule's days have passed, by email and SMS, with
-- the link to the step; not again the same day, nor before the rule's interval, nor more than the rule's times; not while the
-- rule is off or the application window is closed; once paid, the form is what they are reminded of. The rules are the
-- Centre's (or the Academic Office's); the Centre's "send now" needs the Centre, the Academic Office or super. Time is the
-- functions' own clock (p_now), so nothing waits. The block undoes its writes.
DO $$
DECLARE acad uuid := gen_random_uuid(); burs uuid := gen_random_uuid(); cce1 uuid := gen_random_uuid(); S text := '9941/9942'; pa text := 'C00023';
        b uuid; acct uuid; app uuid; t0 timestamptz; due0 int; due2 text; off_due int; r1 jsonb; mail int; sms int; link int; again_day int; again_soon int;
        again_later text; capped int; closed int; form_item text; r_office text; r_rule_office text; r_item text; ref text; msg text; i int;
BEGIN
    BEGIN
        PERFORM set_config('moaum.reason', 'check V418', true);
        PERFORM set_config('moaum.actor_id', acad::text, true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9941-10-01', date '9942-08-31') ON CONFLICT (name) DO NOTHING;
        PERFORM policy.set_route_session('CCE', -1, S, 'the check runs in a session of its own', NULL);
        PERFORM ref.set_programme_route(pa, 'CCE', true, NULL, NULL, 'the check');
        b := admissions.cce_preview(S, 'cce-418.xlsx', repeat('8', 64), jsonb_build_array(
            jsonb_build_object('jamb_reg_no', '99410000018CC', 'surname', 'Zzeighteen', 'first_name', 'Remind', 'date_of_birth', '1990-03-03', 'sex', 'M',
                               'phone', '08035550718', 'email', 'v418@example.com', 'programme_code', pa)));
        PERFORM admissions.cce_commit(b);
        PERFORM policy.window_act('CCE_APPLICATION', S, NULL, 'OPEN', NULL, NULL, NULL, NULL, NULL, acad, 'ict');
        acct := admissions.cce_register('99410000018CC', date '1990-03-03', 'zz.v418@example.com', '08035550718', '$2a$12$' || repeat('x', 53));
        SELECT id, created_at INTO app, t0 FROM admissions.application WHERE account_id = acct;
        PERFORM set_config('moaum.actor_id', burs::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM admissions.set_route_fee(S, 'CCE', 10000, 0, 10000, 3000);

        -- (1) not yet due on the day; due after the rule's two days; not while the rule is off
        SELECT count(*) INTO due0 FROM admissions.cce_due_reminders(t0 + interval '1 hour') d WHERE d.application_id = app;
        SELECT d.item INTO due2 FROM admissions.cce_due_reminders(t0 + interval '2 days 1 hour') d WHERE d.application_id = app;
        PERFORM set_config('moaum.actor_id', cce1::text, true);
        PERFORM set_config('moaum.actor_office', 'cce', true);
        PERFORM admissions.cce_set_reminder_rule('APPLICATION_FEE', false, NULL, NULL, NULL, NULL);
        SELECT count(*) INTO off_due FROM admissions.cce_due_reminders(t0 + interval '2 days 1 hour') d WHERE d.application_id = app;
        PERFORM admissions.cce_set_reminder_rule('APPLICATION_FEE', true, 2, 3, 2, true);

        -- (2) sent by the schedule: an email and an SMS, each pointing at the application; logged
        r1 := admissions.cce_send_reminders(t0 + interval '2 days 1 hour', 'https://portal.example', 500, 'SCHEDULE');
        SELECT count(*) FILTER (WHERE channel = 'EMAIL'), count(*) FILTER (WHERE channel = 'SMS'), count(*) FILTER (WHERE body LIKE '%https://portal.example/applicant/cce%')
          INTO mail, sms, link FROM platform.notice WHERE about_id = app AND subject = 'Your CCE application: pay the CCE application fee';

        -- (3) not again the same day, nor before three days; again after; never more than the rule's two times
        SELECT count(*) INTO again_day FROM admissions.cce_due_reminders(t0 + interval '2 days 5 hours') d WHERE d.application_id = app;
        SELECT count(*) INTO again_soon FROM admissions.cce_due_reminders(t0 + interval '4 days 1 hour') d WHERE d.application_id = app;
        SELECT d.item INTO again_later FROM admissions.cce_due_reminders(t0 + interval '5 days 2 hours') d WHERE d.application_id = app;
        PERFORM admissions.cce_send_reminders(t0 + interval '5 days 2 hours', 'https://portal.example', 500, 'OFFICE');
        SELECT count(*) INTO capped FROM admissions.cce_due_reminders(t0 + interval '30 days') d WHERE d.application_id = app;

        -- (4) the window closed: no application-fee reminder; paid: the form is what is due
        PERFORM admissions.cce_set_reminder_rule('APPLICATION_FEE', true, 2, 3, 3, true);
        PERFORM policy.window_act('CCE_APPLICATION', S, NULL, 'CLOSE', NULL, NULL, NULL, NULL, 'the check', acad, 'ict');
        SELECT count(*) INTO closed FROM admissions.cce_due_reminders(t0 + interval '30 days') d WHERE d.application_id = app;
        PERFORM policy.window_act('CCE_APPLICATION', S, NULL, 'REOPEN', NULL, NULL, NULL, NULL, 'the check', acad, 'ict');
        PERFORM set_config('moaum.actor_id', burs::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        ref := admissions.new_fee_reference(app, 'APPLICATION');
        PERFORM admissions.confirm_fee(ref, 'BANK', 'check');
        SELECT d.item INTO form_item FROM admissions.cce_due_reminders(t0 + interval '9 days') d WHERE d.application_id = app;

        -- (5) the offices: the Bursary neither sends now nor sets a rule; no such step
        BEGIN PERFORM admissions.cce_send_reminders(now(), NULL, 10, 'OFFICE'); r_office := 'SENT';
        EXCEPTION WHEN check_violation THEN r_office := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM admissions.cce_set_reminder_rule('FORM', false, NULL, NULL, NULL, NULL); r_rule_office := 'SET';
        EXCEPTION WHEN check_violation THEN r_rule_office := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_office', 'cce', true);
        BEGIN PERFORM admissions.cce_set_reminder_rule('SCHOOL_FEES', true, NULL, NULL, NULL, NULL); r_item := 'SET';
        EXCEPTION WHEN check_violation THEN r_item := split_part(SQLERRM, ':', 1); END;
        RAISE EXCEPTION 'the V418 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V418 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V418: a CCE applicant is reminded of the earliest outstanding step once the rule''s days pass, by email and SMS with the link to it; not twice a day, not before the interval, not beyond the rule''s times, not while the rule is off or the window closed; once paid, the form; the rules and "send now" are the Centre''s',
        coalesce(due0 = 0 AND due2 = 'APPLICATION_FEE' AND off_due = 0 AND (r1->>'sent')::int >= 1 AND mail = 1 AND sms = 1 AND link = 2
                 AND again_day = 0 AND again_soon = 0 AND again_later = 'APPLICATION_FEE' AND capped = 0 AND closed = 0 AND form_item = 'FORM'
                 AND r_office = 'CCE_OFFICE' AND r_rule_office = 'CCE_OFFICE' AND r_item = 'CCE_REMINDER_ITEM', false),
        format('day0 %s | due %s | off %s | sent %s mail %s sms %s link %s | same day %s soon %s later %s capped %s | closed %s | paid %s | office %s rule-office %s item %s',
               due0, due2, off_due, r1, mail, sms, link, again_day, again_soon, again_later, capped, closed, form_item, r_office, r_rule_office, r_item));
END $$;

-- ── V420: an applicant fee confirmed by hand in error, reversed by the Bursary ──
-- A confirmation made by hand, posted to the ledger, is reversed by the Bursary with its reason: the reference loses its
-- confirmation and receipt and is no longer payable, the application is unpaid again, the ledger journal is reversed by one of
-- its own, the reversal is kept and the applicant told. Another office, a short reason, a payment the gateway settled, a fee
-- already relied upon (the application submitted) and an unknown reference are refused. The block undoes its writes.
DO $$
DECLARE acad uuid := gen_random_uuid(); burs uuid := gen_random_uuid(); S text := '9939/9940'; pa text := 'C00023';
        b uuid; acct uuid; app1 uuid; app2 uuid; ref1 text; ref2 text; ref3 text; jr uuid; pre record; rev jsonb;
        r_office text; r_reason text; r_gateway text; r_in_use text; r_unknown text; why_gw text;
        f_conf timestamptz; f_receipt text; f_expired boolean; a_fee timestamptz; j_status text; j_new int; kept int; told int; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.reason', 'check V420', true);
        PERFORM set_config('moaum.actor_id', acad::text, true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9939-10-01', date '9940-08-31') ON CONFLICT (name) DO NOTHING;
        PERFORM policy.set_route_session('CCE', -1, S, 'the check runs in a session of its own', NULL);
        PERFORM ref.set_programme_route(pa, 'CCE', true, NULL, NULL, 'the check');
        b := admissions.cce_preview(S, 'cce-420.xlsx', repeat('6', 64), jsonb_build_array(
            jsonb_build_object('jamb_reg_no', '99390000020CC', 'surname', 'Zztwenty', 'first_name', 'Wrong', 'date_of_birth', '1990-04-04', 'sex', 'F', 'phone', '08035550920', 'email', 'v420a@example.com', 'programme_code', pa),
            jsonb_build_object('jamb_reg_no', '99390000021CC', 'surname', 'Zztwenty', 'first_name', 'Gateway', 'date_of_birth', '1990-05-05', 'sex', 'M', 'phone', '08035550921', 'email', 'v420b@example.com', 'programme_code', pa)));
        PERFORM admissions.cce_commit(b);
        PERFORM policy.window_act('CCE_APPLICATION', S, NULL, 'OPEN', NULL, NULL, NULL, NULL, NULL, acad, 'ict');
        acct := admissions.cce_register('99390000020CC', date '1990-04-04', 'zz.v420a@example.com', '08035550920', '$2a$12$' || repeat('x', 53));
        SELECT id INTO app1 FROM admissions.application WHERE account_id = acct;
        acct := admissions.cce_register('99390000021CC', date '1990-05-05', 'zz.v420b@example.com', '08035550921', '$2a$12$' || repeat('x', 53));
        SELECT id INTO app2 FROM admissions.application WHERE account_id = acct;
        PERFORM set_config('moaum.actor_id', burs::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM admissions.set_route_fee(S, 'CCE', 10000, 0, 10000, 3000);

        -- (1) confirmed by hand and posted to the ledger: reversible; another office and a short reason refused; reversed
        ref1 := admissions.new_fee_reference(app1, 'APPLICATION');
        PERFORM admissions.confirm_fee(ref1, 'BANK', 'check');
        jr := finance.gl_post(current_date, 'check V420 payment', 'MANUAL', 'PAYMENT', ref1,
                              '[{"account": "1010", "debit": 10000, "credit": 0}, {"account": "4030", "debit": 0, "credit": 10000}]'::jsonb);
        SELECT * INTO pre FROM admissions.fee_reversal_check(ref1);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        BEGIN PERFORM admissions.reverse_fee_confirmation(ref1, 'Confirmed against the wrong reference'); r_office := 'REVERSED';
        EXCEPTION WHEN check_violation THEN r_office := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        BEGIN PERFORM admissions.reverse_fee_confirmation(ref1, 'wrong'); r_reason := 'REVERSED';
        EXCEPTION WHEN check_violation THEN r_reason := split_part(SQLERRM, ':', 1); END;
        rev := admissions.reverse_fee_confirmation(lower(ref1), 'Confirmed against the wrong applicant''s reference');
        SELECT confirmed_at, receipt_no, expires_at <= now() INTO f_conf, f_receipt, f_expired FROM admissions.fee_reference WHERE reference = ref1;
        SELECT fee_confirmed_at INTO a_fee FROM admissions.application WHERE id = app1;
        SELECT status INTO j_status FROM finance.gl_journal WHERE id = jr;
        SELECT count(*) INTO j_new FROM finance.gl_journal WHERE reverses = jr;
        SELECT count(*) INTO kept FROM admissions.fee_reversal WHERE reference = ref1 AND reversed_by = burs AND reversed_office = 'bursar' AND receipt_no IS NOT NULL;
        SELECT count(*) INTO told FROM platform.notice WHERE about_id = app1 AND channel = 'EMAIL' AND subject = 'A payment recorded on your application was reversed';

        -- (2) relied upon: paid again, the application submitted — no reversal
        ref2 := admissions.new_fee_reference(app1, 'APPLICATION');
        PERFORM admissions.confirm_fee(ref2, 'BANK', 'check');
        UPDATE admissions.application SET submitted_at = now() WHERE id = app1;
        BEGIN PERFORM admissions.reverse_fee_confirmation(ref2, 'Confirmed against the wrong applicant''s reference'); r_in_use := 'REVERSED';
        EXCEPTION WHEN check_violation THEN r_in_use := split_part(SQLERRM, ':', 1); END;

        -- (3) settled by the gateway: refunded, never reversed
        ref3 := admissions.new_fee_reference(app2, 'APPLICATION');
        PERFORM admissions.confirm_fee(ref3, 'Card · Quickteller', 'check');
        INSERT INTO finance.gateway_event (gateway, source, reference, amount, status, signature_ok, outcome)
        VALUES ('quickteller', 'WEBHOOK', ref3, 10000, 'success', true, 'SETTLED');
        SELECT why_not INTO why_gw FROM admissions.fee_reversal_check(ref3);
        BEGIN PERFORM admissions.reverse_fee_confirmation(ref3, 'Confirmed against the wrong applicant''s reference'); r_gateway := 'REVERSED';
        EXCEPTION WHEN check_violation THEN r_gateway := split_part(SQLERRM, ':', 1); END;

        -- (4) a reference this portal never generated
        BEGIN PERFORM admissions.reverse_fee_confirmation('MOAUM-APP-000000-0000', 'Confirmed against the wrong applicant''s reference'); r_unknown := 'REVERSED';
        EXCEPTION WHEN check_violation THEN r_unknown := split_part(SQLERRM, ':', 1); END;
        RAISE EXCEPTION 'the V420 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V420 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V420: an applicant fee confirmed by hand in error is reversed by the Bursary with its reason — confirmation and receipt gone, unpayable, the application unpaid, the ledger reversed, the reversal kept, the applicant told; another office, a short reason, a fee relied upon, a gateway settlement and an unknown reference are refused',
        coalesce(pre.reversible AND r_office = 'FEE_REVERSAL_OFFICE' AND r_reason = 'FEE_REVERSAL_REASON' AND (rev->>'ledgerReversed')::boolean
                 AND f_conf IS NULL AND f_receipt IS NULL AND f_expired AND a_fee IS NULL AND j_status = 'REVERSED' AND j_new = 1 AND kept = 1 AND told = 1
                 AND r_in_use = 'FEE_REVERSAL_IN_USE' AND r_gateway = 'FEE_REVERSAL_GATEWAY' AND why_gw LIKE 'The payment gateway settled it%'
                 AND r_unknown = 'FEE_REVERSAL_UNKNOWN', false),
        format('check %s | office %s reason %s | reversed %s: confirmed %s receipt %s expired %s app fee %s journal %s reversals %s kept %s told %s | in use %s | gateway %s (%s) | unknown %s',
               pre.reversible, r_office, r_reason, rev, f_conf, f_receipt, f_expired, a_fee, j_status, j_new, kept, told, r_in_use, r_gateway, why_gw, r_unknown));
END $$;

-- ── V416. Clearance read for whole lists and the offices told what waits on them: the set-based read says what the gate
--          says of each student (a workflow purpose and a gate purpose alike); the people who sign a stage are the unit's
--          office within the student's department or faculty, never another department's Head; a student's upload is told
--          to them by e-mail; a stage open past its deadline is chased once with them, and not again within the week ──
DO $$
DECLARE S text := '9969/9970'; who uuid := gen_random_uuid(); hod uuid := gen_random_uuid(); other_hod uuid := gen_random_uuid();
        st uuid := gen_random_uuid(); pf uuid; v_same text; v_gate text; v_people text; v_upload int; v_first int; v_again int; v_chased int;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'registrar', true); PERFORM set_config('moaum.reason', 'CHECK V416', true);
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (who, 'CHK/V416', 'CHECKV416', 'Registry');
        INSERT INTO iam.person (id, staff_number, surname, given_names, email) VALUES
            (hod, 'CHK/V416/H1', 'CHECKV416', 'Head', 'v416.head@example.test'),
            (other_hod, 'CHK/V416/H2', 'CHECKV416', 'Other', 'v416.other@example.test');
        INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from) VALUES
            (gen_random_uuid(), hod, 'hod', 'department', 'MTC', 'CHECK V416', who, current_date),
            (gen_random_uuid(), other_hod, 'hod', 'department', 'ASS', 'CHECK V416', who, current_date);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9969-10-01', date '9970-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, sex, programme_code, entry_mode, entry_session, entry_level, current_level, status, study_mode, matriculated_at)
        VALUES (st, 'MOAUM/ADM/69/009969', 'MOAUM/CHK/69/416', 'CHECKV416', 'Finalist', 'F', 'C00023', 'UTME', S, 100, 400, 'ACTIVE', 'FULL_TIME', now());
        pf := clearance.start('FINAL', st, S, 'MANUAL', NULL, who, 'registrar');
        -- the set-based read says what the gate says, for the workflow purpose and a gate purpose alike
        SELECT c.cleared::text || '/' || c.holding || '=' || clearance.is_clear(st, 'CONVOCATION')::text || '/' || (SELECT count(*) FROM clearance.position(st, 'CONVOCATION') WHERE state <> 'CLEARED')
          INTO v_same FROM clearance.cleared_many('CONVOCATION', ARRAY[st]) c;
        SELECT c.cleared::text || '=' || clearance.is_clear(st, 'TRANSCRIPT')::text INTO v_gate FROM clearance.cleared_many('TRANSCRIPT', ARRAY[st]) c;
        -- the Department stage is signed by the Head over the student's department, not another
        SELECT string_agg(name, ',' ORDER BY name) INTO v_people FROM clearance.office_people('DEPARTMENT', st);
        -- a deadline on the Bursary stage, already past: the Bursary is chased once, and not again within the week
        UPDATE clearance.workflow_stage SET deadline_days = 1 WHERE workflow = 'FINAL' AND unit = 'BURSARY';
        UPDATE clearance.process SET started_at = now() - interval '5 days' WHERE id = pf;
        INSERT INTO iam.person (id, staff_number, surname, given_names, email) VALUES (gen_random_uuid(), 'CHK/V416/B', 'CHECKV416', 'Bursar', 'v416.bursar@example.test');
        INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from)
        SELECT gen_random_uuid(), id, 'bursar', 'institution', NULL, 'CHECK V416', who, current_date FROM iam.person WHERE staff_number = 'CHK/V416/B';
        v_first := clearance.chase_offices(7);
        SELECT count(*) INTO v_chased FROM clearance.chase WHERE process_id = pf AND unit = 'BURSARY';
        v_again := clearance.chase_offices(7);
        -- a student's upload to the Department stage is told to the Head, by e-mail
        PERFORM clearance.decide(pf, 'BURSARY', 'CLEARED', 'CHECK: fees settled on the old ledger', NULL, NULL, true, who, 'registrar');
        PERFORM clearance.add_document(pf, 'DEPARTMENT', 'Project report', 'report.pdf', 'application/pdf', 1000, NULL, st, 'student');
        SELECT count(*) INTO v_upload FROM platform.notice WHERE channel = 'EMAIL' AND recipient = 'v416.head@example.test' AND subject LIKE 'Clearance document to review:%';
        RAISE EXCEPTION 'the V416 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V416: the set-based clearance read says what the gate says; a stage''s signers are its office within the student''s department or faculty; a student''s upload is told to them; a stage past its deadline is chased once with them, not again within the week',
        v_same = 'false/7=false/7' AND v_gate = 'false=false'
        AND v_people LIKE '%Head CHECKV416%' AND v_people NOT LIKE '%Other CHECKV416%'
        AND v_first >= 1 AND v_chased = 1 AND v_again = 0
        AND v_upload = 1,
        format('same=%s gate=%s people=%s first=%s chased=%s again=%s upload=%s', v_same, v_gate, v_people, v_first, v_chased, v_again, v_upload));
END $$;

-- ── V421: a missing result is not a zero, and never probation ──
-- Eight invented students in a semester of their own (and one older session): A's registration came over but no result did —
-- on sheets the old-portal upload published for others — so A has no result, no CGPA, no standing, no carryover, and is told
-- the result is not available; B's published CGPA under the threshold is probation (and the real F a carryover); C's above it
-- is good; D's partial semester (one F published, one course with no sheet) is incomplete and pronounces nothing; E's result
-- under verification and F's at Senate are pending, never probation; G's older session stands as pronounced on its own
-- session while the current one is not available; H's recorded absence is still an F. The threshold is the University's
-- setting, the Academic Office's or the Registry's to change; the offices count students by result status, probation only
-- from complete published results. The block undoes its writes.
DO $$
DECLARE who uuid := gen_random_uuid(); S0 text := '9933/9934'; S1 text := '9935/9936'; dept text;
        a uuid := gen_random_uuid(); b uuid := gen_random_uuid(); c uuid := gen_random_uuid(); d uuid := gen_random_uuid();
        e uuid := gen_random_uuid(); f uuid := gen_random_uuid(); g uuid := gen_random_uuid(); h uuid := gen_random_uuid();
        o4 uuid := gen_random_uuid(); o5 uuid := gen_random_uuid(); o6 uuid := gen_random_uuid(); x uuid; reg uuid; i int;
        a_stage text; a_pub int; a_cgpa numeric; a_st text; a_status text; a_msg text; a_carry int;
        b_st text; b_cgpa numeric; b_carry int; b_msg_sess text; c_st text;
        d_status text; d_st text; e_status text; e_st text; f_status text; f_st text;
        g_st text; g_sess text; g_status text; g_status_sess text; h_st text; h_grade text;
        b_low_st text; r_office text; counts jsonb; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'records', true);
        PERFORM set_config('moaum.reason', 'check V421', true);
        SELECT dept_code INTO dept FROM ref.programme WHERE code = 'C00061';
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S0, date '9933-10-01', date '9934-08-31'), (gen_random_uuid(), S1, date '9935-10-01', date '9936-08-31')
        ON CONFLICT (name) DO NOTHING;
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state)
        SELECT 'ZZP 10' || n, 'Check standing ' || n, 3, 2, 100, dept, 'Core', 'LIVE' FROM generate_series(1, 6) n;
        i := 0;
        FOREACH x IN ARRAY ARRAY[a, b, c, d, e, f, g, h] LOOP
            i := i + 1;
            INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
            VALUES (x, 'MOAUM/ADM/99/99421' || i, 'MOAUM/ZZP/99/042' || i, 'ZZSTANDING', 'Student ' || i, 'C00061', 'UTME', S0, 100, 100, 'ACTIVE', now());
        END LOOP;

        -- the old portal's results, published as they came: B, C, D, H in S1; G in S0
        PERFORM assessment.import_legacy_semester(S1, 2, jsonb_build_array(
            jsonb_build_object('matric', 'MOAUM/ZZP/99/0422', 'course', 'ZZP 101', 'total', '42', 'level', '100'),
            jsonb_build_object('matric', 'MOAUM/ZZP/99/0422', 'course', 'ZZP 102', 'total', '41', 'level', '100'),
            jsonb_build_object('matric', 'MOAUM/ZZP/99/0422', 'course', 'ZZP 103', 'total', '30', 'level', '100'),
            jsonb_build_object('matric', 'MOAUM/ZZP/99/0423', 'course', 'ZZP 101', 'total', '46', 'level', '100'),
            jsonb_build_object('matric', 'MOAUM/ZZP/99/0423', 'course', 'ZZP 102', 'total', '42', 'level', '100'),
            jsonb_build_object('matric', 'MOAUM/ZZP/99/0424', 'course', 'ZZP 101', 'total', '30', 'level', '100'),
            jsonb_build_object('matric', 'MOAUM/ZZP/99/0428', 'course', 'ZZP 101', 'outcome', 'ABSENT', 'level', '100'),
            jsonb_build_object('matric', 'MOAUM/ZZP/99/0428', 'course', 'ZZP 102', 'total', '30', 'level', '100')), true);
        PERFORM assessment.import_legacy_semester(S0, 2, jsonb_build_array(
            jsonb_build_object('matric', 'MOAUM/ZZP/99/0427', 'course', 'ZZP 101', 'total', '65', 'level', '100')), true);

        -- the registrations that came over without results: A (ZZP 101, ZZP 102), G in S1 (ZZP 102); D's second course has no sheet;
        -- E's sheet is at verification, F's at Senate
        INSERT INTO catalogue.offering (id, course_code, session, semester) VALUES (o4, 'ZZP 104', S1, 2), (o5, 'ZZP 105', S1, 2), (o6, 'ZZP 106', S1, 2);
        INSERT INTO assessment.score_sheet (id, offering_id, stage) VALUES (gen_random_uuid(), o5, 'VERIFICATION'), (gen_random_uuid(), o6, 'SENATE');
        FOREACH x IN ARRAY ARRAY[a, d, e, f, g] LOOP
            SELECT id INTO reg FROM registration.course_registration WHERE student_id = x AND session = S1 AND semester = 2;
            IF reg IS NULL THEN
                reg := gen_random_uuid();
                INSERT INTO people.enrolment (id, student_id, session, level) VALUES (gen_random_uuid(), x, S1, 100) ON CONFLICT (student_id, session) DO NOTHING;
                INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, submitted_at, approved_at, approved_by)
                VALUES (reg, x, S1, 2, 100, 'APPROVED', now(), now(), who);
            END IF;
            INSERT INTO registration.entry (registration_id, offering_id, units, entry_type, status)
            SELECT reg, o.id, 3, 'CURRENT', 'APPROVED' FROM catalogue.offering o
             WHERE o.session = S1 AND o.semester = 2 AND o.stream = 'REGULAR'
               AND o.course_code = ANY (CASE WHEN x = a THEN ARRAY['ZZP 101', 'ZZP 102'] WHEN x = d THEN ARRAY['ZZP 104'] WHEN x = e THEN ARRAY['ZZP 105']
                                             WHEN x = f THEN ARRAY['ZZP 106'] ELSE ARRAY['ZZP 102'] END)
            ON CONFLICT (registration_id, offering_id) DO NOTHING;
        END LOOP;

        -- A: no result — no grade, no CGPA, no standing, no carryover; told the result is not available
        SELECT string_agg(DISTINCT stage, ','), count(*) FILTER (WHERE published) INTO a_stage, a_pub FROM assessment.student_results(a);
        SELECT cgpa INTO a_cgpa FROM assessment.student_gpa(a) ORDER BY session DESC, semester DESC LIMIT 1;
        SELECT standing INTO a_st FROM assessment.student_standing(a);
        SELECT status, message INTO a_status, a_msg FROM assessment.student_result_status(a);
        SELECT count(*) INTO a_carry FROM registration.carryovers(a);
        -- B: under the threshold on complete published results — probation, the real F a carryover; C above it — good
        SELECT standing, cgpa, pronounced_session INTO b_st, b_cgpa, b_msg_sess FROM assessment.student_standing(b);
        SELECT count(*) INTO b_carry FROM registration.carryovers(b);
        SELECT standing INTO c_st FROM assessment.student_standing(c);
        -- D partial, E under verification, F at Senate: pending, never probation
        SELECT status INTO d_status FROM assessment.student_result_status(d);
        SELECT standing INTO d_st FROM assessment.student_standing(d);
        SELECT status INTO e_status FROM assessment.student_result_status(e);
        SELECT standing INTO e_st FROM assessment.student_standing(e);
        SELECT status INTO f_status FROM assessment.student_result_status(f);
        SELECT standing INTO f_st FROM assessment.student_standing(f);
        -- G: the older session stands on its own session; the current one is not available
        SELECT standing, pronounced_session INTO g_st, g_sess FROM assessment.student_standing(g);
        SELECT status, session INTO g_status, g_status_sess FROM assessment.student_result_status(g);
        -- H: a recorded absence is still an F
        SELECT standing INTO h_st FROM assessment.student_standing(h);
        SELECT grade INTO h_grade FROM assessment.student_results(h) WHERE course_code = 'ZZP 101';

        -- the threshold is the University's: at 0.5, B is in good standing; only the Academic Office or the Registry sets it
        PERFORM set_config('moaum.actor_office', 'academic', true);
        PERFORM policy.set_probation_below_cgpa(0.5);
        SELECT standing INTO b_low_st FROM assessment.student_standing(b);
        PERFORM policy.set_probation_below_cgpa(1.0);
        PERFORM set_config('moaum.actor_office', 'lecturer', true);
        BEGIN PERFORM policy.set_probation_below_cgpa(2.0); r_office := 'SET';
        EXCEPTION WHEN check_violation THEN r_office := split_part(SQLERRM, ':', 1); END;

        -- the offices' counts for the semester
        SELECT jsonb_object_agg(status, students) INTO counts FROM assessment.result_status_counts(dept, NULL, NULL, S1, 2);
        RAISE EXCEPTION 'the V421 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V421 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V421: a missing result is no result — no CGPA, no standing, no carryover, the student told it is not available; probation only on complete published results under the University''s threshold; partial, under verification and at Senate are pending; an older session stands on its own session; a recorded absence is still an F; the offices count by result status',
        coalesce(a_stage = 'NO_RESULT' AND a_pub = 0 AND a_cgpa IS NULL AND a_st = 'NOT_AVAILABLE' AND a_status = 'NOT_AVAILABLE'
                 AND a_msg = 'Your result for the ' || S1 || ' second semester has not yet been uploaded or published.' AND a_carry = 0
                 AND b_st = 'PROBATION' AND b_cgpa = 0.67 AND b_msg_sess = S1 AND b_carry = 1 AND c_st = 'GOOD'
                 AND d_status = 'INCOMPLETE' AND d_st = 'NOT_AVAILABLE' AND e_status = 'UNDER_VERIFICATION' AND e_st = 'NOT_AVAILABLE'
                 AND f_status = 'PROCESSING' AND f_st = 'NOT_AVAILABLE'
                 AND g_st = 'GOOD' AND g_sess = S0 AND g_status = 'NOT_AVAILABLE' AND g_status_sess = S1
                 AND h_st = 'PROBATION' AND h_grade = 'F' AND b_low_st = 'GOOD' AND r_office = 'STANDING_SETTING_OFFICE'
                 AND (counts->>'NOT_AVAILABLE')::int = 2 AND (counts->>'PUBLISHED')::int = 3 AND (counts->>'INCOMPLETE')::int = 1
                 AND (counts->>'UNDER_VERIFICATION')::int = 1 AND (counts->>'PROCESSING')::int = 1 AND (counts->>'PROBATION')::int = 2, false),
        format('A %s pub=%s cgpa=%s standing=%s status=%s msg=%s carry=%s | B %s %s %s carry=%s | C %s | D %s %s | E %s %s | F %s %s | G %s %s %s %s | H %s %s | at 0.5 B %s | office %s | counts %s',
               a_stage, a_pub, a_cgpa, a_st, a_status, a_msg, a_carry, b_st, b_cgpa, b_msg_sess, b_carry, c_st, d_status, d_st, e_status, e_st,
               f_status, f_st, g_st, g_sess, g_status, g_status_sess, h_st, h_grade, b_low_st, r_office, counts));
END $$;

-- ── V422: a late result through the chain, and every outcome read alike ──
-- Invented students in a semester of their own. L is on a published sheet's roll with no mark (registered after the old
-- portal's results were published): L is a late-result candidate; the desk of entry raises a LATE result, which no other
-- candidate's mark can be; it passes each desk of the chain, a different person at each, and is applied on the Senate minute
-- as L's first mark, the score saying "Late result", L told the result is published; a student not on the roll is refused
-- (RES_AMEND_NO_MARK), and a student with a mark is amended, never late. The outcomes: X recorded absent owes the course (a carryover, and a GST/EPS course owed again); W's
-- withheld and Z's malpractice are held for the Senate — never counted, never owed, the semester HELD and no standing
-- pronounced; Y's exemption is not counted or owed and Y's semester is complete. The block undoes its writes.
DO $$
DECLARE who uuid := gen_random_uuid(); SL text := '9937/9938'; SN text := '9939/9940'; dept text; gst_ok boolean := true;
        l uuid := gen_random_uuid(); m uuid := gen_random_uuid(); w uuid := gen_random_uuid(); x uuid := gen_random_uuid();
        y uuid := gen_random_uuid(); z uuid := gen_random_uuid(); sheet uuid; reg uuid; amd uuid; st uuid; i int; step text;
        offices text[] := ARRAY['exams', 'hod', 'facultyexams', 'facultyofficer', 'dean', 'records', 'registrar'];
        cand_before int; cand_after int; kind text; was_v int; refused text; m_kind text; applied text; l_grade text; l_pub boolean; reason text; told int;
        x_carry text; x_gst text; w_status text; w_st text; w_carry int; w_msg text; w_gpa_units int; z_status text; z_st text;
        y_status text; y_st text; y_carry int; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'records', true);
        PERFORM set_config('moaum.reason', 'check V422', true);
        SELECT dept_code INTO dept FROM ref.programme WHERE code = 'C00061';
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), SL, date '9937-10-01', date '9938-08-31'), (gen_random_uuid(), SN, date '9939-10-01', date '9940-08-31')
        ON CONFLICT (name) DO NOTHING;
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state)
        SELECT 'ZZL 10' || n, 'Check late ' || n, 3, 2, 100, dept, 'Core', 'LIVE' FROM generate_series(1, 3) n;
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state, general_office)
        VALUES ('GST 942', 'Check general studies', 2, 2, 100, dept, 'GST', 'LIVE', 'GST');
        i := 0;
        FOREACH st IN ARRAY ARRAY[l, m, w, x, y, z] LOOP
            i := i + 1;
            INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
            VALUES (st, 'MOAUM/ADM/99/99422' || i, 'MOAUM/ZZL/99/042' || i, 'ZZLATE', 'Student ' || i, 'C00061', 'UTME', SL, 100, 100, 'ACTIVE', now());
        END LOOP;

        -- the old portal's results for the semester: W withheld + a pass, X absent (and absent from the GST course), Y exempted + a
        -- pass, Z malpractice + a pass; M's mark makes ZZL 101's sheet
        PERFORM assessment.import_legacy_semester(SL, 2, jsonb_build_array(
            jsonb_build_object('matric', 'MOAUM/ZZL/99/0422', 'course', 'ZZL 101', 'total', '55', 'level', '100'),
            jsonb_build_object('matric', 'MOAUM/ZZL/99/0423', 'course', 'ZZL 101', 'outcome', 'WITHHELD', 'level', '100'),
            jsonb_build_object('matric', 'MOAUM/ZZL/99/0423', 'course', 'ZZL 102', 'total', '60', 'level', '100'),
            jsonb_build_object('matric', 'MOAUM/ZZL/99/0424', 'course', 'ZZL 101', 'outcome', 'ABSENT', 'level', '100'),
            jsonb_build_object('matric', 'MOAUM/ZZL/99/0424', 'course', 'GST 942', 'outcome', 'ABSENT', 'level', '100'),
            jsonb_build_object('matric', 'MOAUM/ZZL/99/0425', 'course', 'ZZL 101', 'outcome', 'EXEMPTED', 'level', '100'),
            jsonb_build_object('matric', 'MOAUM/ZZL/99/0425', 'course', 'ZZL 102', 'total', '70', 'level', '100'),
            jsonb_build_object('matric', 'MOAUM/ZZL/99/0426', 'course', 'ZZL 101', 'outcome', 'MALPRACTICE', 'level', '100'),
            jsonb_build_object('matric', 'MOAUM/ZZL/99/0426', 'course', 'ZZL 102', 'total', '64', 'level', '100')), true);
        SELECT s.id INTO sheet FROM assessment.score_sheet s JOIN catalogue.offering o ON o.id = s.offering_id
         WHERE o.course_code = 'ZZL 101' AND o.session = SL AND o.semester = 2;

        -- L registered on ZZL 101 after its results were published: on the roll, with no mark
        reg := gen_random_uuid();
        INSERT INTO people.enrolment (id, student_id, session, level) VALUES (gen_random_uuid(), l, SL, 100) ON CONFLICT (student_id, session) DO NOTHING;
        INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, submitted_at, approved_at, approved_by)
        VALUES (reg, l, SL, 2, 100, 'APPROVED', now(), now(), who);
        INSERT INTO people.student_contact (student_id, email) VALUES (l, 'zzlate.v422@example.invalid');
        INSERT INTO registration.entry (registration_id, offering_id, units, entry_type, status)
        SELECT reg, o.id, 3, 'CURRENT', 'APPROVED' FROM catalogue.offering o WHERE o.course_code = 'ZZL 101' AND o.session = SL AND o.semester = 2;

        -- (1) the late result: raised by the desk of entry, through every desk, applied on the minute
        SELECT count(*) INTO cand_before FROM assessment.late_candidates(sheet) c WHERE c.student_id = l;
        PERFORM set_config('moaum.actor_office', 'exams', true);
        amd := assessment.raise_amendment(sheet, m, 30, 40, 'GRADED', 'M has a mark: this corrects it, never a late result', NULL);
        SELECT a.kind INTO m_kind FROM assessment.amendment a WHERE a.id = amd;
        BEGIN PERFORM assessment.raise_amendment(sheet, gen_random_uuid(), 30, 40, 'GRADED', 'a student nowhere on this sheet', NULL); refused := 'RAISED';
        EXCEPTION WHEN check_violation THEN refused := split_part(SQLERRM, ':', 1);
                  WHEN OTHERS THEN refused := SQLSTATE; END;
        amd := assessment.raise_amendment(sheet, l, 28, 40, 'GRADED', 'L registered after the sheet was published; the script was marked', NULL);
        SELECT a.kind, a.was_version INTO kind, was_v FROM assessment.amendment a WHERE a.id = amd;
        SELECT count(*) INTO cand_after FROM assessment.late_candidates(sheet) c WHERE c.student_id = l;
        FOREACH step IN ARRAY offices LOOP
            PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
            PERFORM set_config('moaum.actor_office', step, true);
            applied := assessment.advance_amendment(amd, 'check V422', CASE WHEN step = 'registrar' THEN 'SEN/9938/422' END);
        END LOOP;
        SELECT grade, published INTO l_grade, l_pub FROM assessment.student_results(l) WHERE course_code = 'ZZL 101';
        SELECT sc.reason INTO reason FROM assessment.score sc WHERE sc.sheet_id = sheet AND sc.student_id = l;
        SELECT count(*) INTO told FROM platform.notice n WHERE n.about_id = l AND n.subject LIKE 'Your result in ZZL 101 is published';
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'records', true);

        -- (2) the outcomes
        SELECT string_agg(course_code, ',' ORDER BY course_code) INTO x_carry FROM registration.carryovers(x);
        SELECT string_agg(g.source || ':' || coalesce(g.last_grade, '-'), ',') INTO x_gst FROM finance.gst_eps_rows(SN, x) g WHERE g.course_code = 'GST 942';
        SELECT status, message INTO w_status, w_msg FROM assessment.student_result_status(w);
        SELECT standing INTO w_st FROM assessment.student_standing(w);
        SELECT count(*) INTO w_carry FROM registration.carryovers(w);
        SELECT units INTO w_gpa_units FROM assessment.student_gpa(w) WHERE session = SL AND semester = 2;
        SELECT status INTO z_status FROM assessment.student_result_status(z);
        SELECT standing INTO z_st FROM assessment.student_standing(z);
        SELECT status INTO y_status FROM assessment.student_result_status(y);
        SELECT standing INTO y_st FROM assessment.student_standing(y);
        SELECT count(*) INTO y_carry FROM registration.carryovers(y);
        RAISE EXCEPTION 'the V422 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V422 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V422: a late result for a candidate on a published sheet''s roll with no mark passes every desk and is applied on the Senate minute as the first mark; a student with a mark is amended, one not on the roll refused; an absence is owed (carryover, GST/EPS again); withheld and malpractice are held — not counted, not owed, the semester HELD, no standing; an exemption is not counted or owed and the semester complete',
        coalesce(cand_before = 1 AND cand_after = 0 AND m_kind = 'AMEND' AND refused = 'RES_AMEND_NO_MARK' AND kind = 'LATE' AND was_v IS NULL AND applied = 'APPLIED' AND l_pub AND l_grade IS NOT NULL
                 AND reason LIKE 'Late result AMD-%SEN/9938/422%' AND told >= 1
                 AND x_carry = 'GST 942,ZZL 101' AND x_gst = 'CARRYOVER:F'
                 AND w_status = 'HELD' AND w_st = 'NOT_AVAILABLE' AND w_carry = 0 AND w_gpa_units = 3 AND w_msg LIKE '%1 course held for the Senate%'
                 AND z_status = 'HELD' AND z_st = 'NOT_AVAILABLE'
                 AND y_status = 'PUBLISHED' AND y_st = 'GOOD' AND y_carry = 0, false),
        format('late cand %s->%s M=%s refused=%s kind=%s was=%s applied=%s L %s/%s reason=%s told=%s | X carry=%s gst=%s | W %s %s carry=%s units=%s msg=%s | Z %s %s | Y %s %s carry=%s',
               cand_before, cand_after, m_kind, refused, kind, was_v, applied, l_pub, l_grade, reason, told, x_carry, x_gst, w_status, w_st, w_carry, w_gpa_units, w_msg,
               z_status, z_st, y_status, y_st, y_carry));
END $$;
-- ── V423. The student biodata completion gate: OFF by default, and every student passes; turned on only by the ICT
--          Director or an administrator, and not twice; a student whose required items are incomplete is REQUIRED, the
--          missing items named in the form's order, the contact the student gave counting where the portal keeps it; an
--          exception lets a named student through until it ends — granted only by the ICT Director or an administrator,
--          within 30 days, one at a time — and revoked or ended, the gate applies again; a JAMB field or a health field is
--          never required; while ON an incomplete student is reminded once in a week, never while OFF; complete (the
--          photograph and the fields given), the student passes, and a field written carries when ──
DO $$
DECLARE S text := '9979/9980'; who uuid := gen_random_uuid(); a uuid := gen_random_uuid(); ex uuid;
        st_off text; st_req text; st_exc text; st_revoked text; st_expired text; st_done text; st_after_off text;
        miss text; req_n int; done_n int; miss_done text;
        r_office text := 'accepted'; r_twice text := 'accepted'; r_locked text := 'accepted'; r_health text := 'accepted';
        r_cpo text := 'accepted'; r_long text := 'accepted'; r_active text := 'accepted';
        told int; sent1 int; sent2 int; reminded_off int; touched boolean;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'ict', true); PERFORM set_config('moaum.reason', 'CHECK V423', true);
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (who, 'CHK/V423', 'CHECKV423', 'ICT');
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9979-10-01', date '9980-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO people.student (id, admission_no, surname, other_names, sex, programme_code, entry_mode, entry_session, entry_level, current_level, status, study_mode)
        VALUES (a, 'MOAUM/ADM/79/009423', 'CHECKV423', 'Gate', 'F', 'C00023', 'UTME', S, 100, 100, 'ADMITTED', 'FULL_TIME');
        INSERT INTO iam.student_account (id, student_id, password_hash, must_change) VALUES (gen_random_uuid(), a, '$2a$12$CHECKV423CHECKV423CHECKV423CHECKV423CHECKV423CHECKV42', true);
        INSERT INTO people.student_contact (student_id, phone, email) VALUES (a, '08000000423', 'v423@example.test');
        st_off := people.biodata_gate_state(a);
        -- turned on only by the ICT Director or an administrator, and not twice
        BEGIN PERFORM people.set_biodata_gate(true, 'CHECK', who, 'bursar'); EXCEPTION WHEN check_violation THEN r_office := split_part(SQLERRM, ':', 1); END;
        PERFORM people.set_biodata_gate(true, 'CHECK go-live', who, 'ict');
        BEGIN PERFORM people.set_biodata_gate(true, 'CHECK', who, 'ict'); EXCEPTION WHEN check_violation THEN r_twice := split_part(SQLERRM, ':', 1); END;
        st_req := people.biodata_gate_state(a);
        SELECT array_to_string(missing, ','), required, completed INTO miss, req_n, done_n FROM people.biodata_completion(ARRAY[a]);
        -- never a JAMB field, never a health field
        BEGIN PERFORM people.set_biodata_requirement('university_email', true, who, 'ict'); EXCEPTION WHEN check_violation THEN r_locked := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM people.set_biodata_requirement('genotype', true, who, 'ict'); EXCEPTION WHEN check_violation THEN r_health := split_part(SQLERRM, ':', 1); END;
        -- an exception: the ICT Director's, within 30 days, one at a time; revoked or ended, the gate applies again
        BEGIN PERFORM people.grant_biodata_exception(a, 'CHECK reason', now(), now() + interval '2 days', who, 'cpo'); EXCEPTION WHEN check_violation THEN r_cpo := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM people.grant_biodata_exception(a, 'CHECK reason', now(), now() + interval '40 days', who, 'ict'); EXCEPTION WHEN check_violation THEN r_long := split_part(SQLERRM, ':', 1); END;
        ex := people.grant_biodata_exception(a, 'CHECK: an examination tomorrow', now(), now() + interval '2 days', who, 'ict');
        BEGIN PERFORM people.grant_biodata_exception(a, 'CHECK again', now(), now() + interval '1 day', who, 'ict'); EXCEPTION WHEN check_violation THEN r_active := split_part(SQLERRM, ':', 1); END;
        st_exc := people.biodata_gate_state(a);
        PERFORM people.revoke_biodata_exception(ex, 'CHECK: done', who, 'ict');
        st_revoked := people.biodata_gate_state(a);
        INSERT INTO people.biodata_gate_exception (student_id, reason, granted_by, granted_office, starts_at, expires_at)
        VALUES (a, 'CHECK: an exception that ended', who, 'ict', now() - interval '10 days', now() - interval '1 day');
        st_expired := people.biodata_gate_state(a);
        -- reminded while ON, once in the week
        PERFORM people.remind_biodata(1000000);
        SELECT count(*) INTO told FROM platform.notice WHERE about_id = a AND subject LIKE 'Complete your biodata%';
        SELECT sent INTO sent1 FROM people.biodata_reminder WHERE student_id = a;
        PERFORM people.remind_biodata(1000000);
        SELECT sent INTO sent2 FROM people.biodata_reminder WHERE student_id = a;
        -- complete: the photograph and the fields given (the mobile and e-mail already counted from the contact)
        INSERT INTO people.student_photo (student_id, content, content_type, bytes, reason) VALUES (a, decode('ffd8ffd9', 'hex'), 'image/jpeg', 4, 'CHECK V423');
        INSERT INTO people.biodata (student_id, field, value) VALUES
            (a, 'nationality', 'Nigeria'), (a, 'home_address', 'CHECK house, Makurdi'), (a, 'state_of_origin', 'Benue'), (a, 'lga', 'Makurdi'),
            (a, 'kin_name', 'CHECK Kin'), (a, 'kin_relationship', 'Mother'), (a, 'kin_mobile', '08000000424');
        SELECT array_to_string(missing, ',') INTO miss_done FROM people.biodata_completion(ARRAY[a]);
        st_done := people.biodata_gate_state(a);
        SELECT bool_and(updated_at IS NOT NULL) INTO touched FROM people.biodata WHERE student_id = a;
        -- OFF: every student passes, and nobody is reminded
        PERFORM people.set_biodata_gate(false, 'CHECK', who, 'ict');
        DELETE FROM people.biodata WHERE student_id = a AND field = 'kin_mobile';
        st_after_off := people.biodata_gate_state(a);
        reminded_off := people.remind_biodata(1000000);
        RAISE EXCEPTION 'the V423 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V423: the biodata gate is OFF until the ICT Director turns it on (not twice, not by another office); then an incomplete student is REQUIRED with the missing items named, the contact counting; an exception (ICT only, within 30 days, one at a time) lets them through until revoked or ended; JAMB and health fields are never required; reminded once a week while ON, never while OFF; complete, the student passes',
        coalesce(st_off = 'OFF' AND r_office = 'BIO_GATE_OFFICE' AND r_twice = 'BIO_GATE_UNCHANGED' AND st_req = 'REQUIRED'
                 AND miss = 'PASSPORT,nationality,home_address,state_of_origin,lga,kin_name,kin_relationship,kin_mobile' AND req_n = 10 AND done_n = 2
                 AND r_locked = 'BIO_REQ_LOCKED' AND r_health = 'BIO_REQ_HEALTH'
                 AND r_cpo = 'BIO_GATE_OFFICE' AND r_long = 'BIO_GATE_EXPIRY' AND r_active = 'BIO_GATE_EXCEPTION_ACTIVE'
                 AND st_exc = 'EXCEPTION' AND st_revoked = 'REQUIRED' AND st_expired = 'REQUIRED'
                 AND told = 2 AND sent1 = 1 AND sent2 = 1
                 AND miss_done = '' AND st_done = 'COMPLETE' AND touched AND st_after_off = 'OFF' AND reminded_off = 0, false),
        format('off=%s office=%s twice=%s req=%s miss=%s %s/%s locked=%s health=%s cpo=%s long=%s active=%s exc=%s revoked=%s expired=%s told=%s sent %s->%s done=[%s] %s touched=%s off=%s reminded_off=%s',
               st_off, r_office, r_twice, st_req, miss, done_n, req_n, r_locked, r_health, r_cpo, r_long, r_active, st_exc, st_revoked, st_expired,
               told, sent1, sent2, miss_done, st_done, touched, st_after_off, reminded_off));
END $$;
-- ── V424: results held for the Senate listed and reminded; who the absent rule now affects ──
-- Invented students in sessions of their own. W's withheld and Z's malpractice result are listed as held, with how long they
-- have waited and the amendment that carries a decision once one is raised; a held result later decided is no longer held.
-- The Registry is reminded of the results held past the University's days — once a week at most, never when the days are
-- 0 — and only the Academic Office or the Registry sets the days (7 to 365, or 0). A, Z (decided absent) and G owe the course
-- they were recorded absent from; B owed it already for an earlier graded F and is not listed; C passed after
-- the absence and owes nothing; D, graduated, is not listed. G owes a GST course again because of an absence. The block
-- undoes its writes.
DO $$
DECLARE who uuid := gen_random_uuid(); S0 text := '9941/9942'; SA text := '9943/9944'; SB text := '9945/9946'; dept text;
        w uuid := gen_random_uuid(); z uuid := gen_random_uuid(); a uuid := gen_random_uuid(); b uuid := gen_random_uuid();
        c uuid := gen_random_uuid(); d uuid := gen_random_uuid(); g uuid := gen_random_uuid(); x uuid; i int; sheet uuid; amd uuid;
        held_w text; held_z text; w_days int; w_amd text; decided int; first_told int; logged text; again int; zero_days int;
        r_office text; r_days text; absent_list text; gst_list text; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'records', true);
        PERFORM set_config('moaum.reason', 'check V424', true);
        SELECT dept_code INTO dept FROM ref.programme WHERE code = 'C00061';
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on)
        VALUES (gen_random_uuid(), S0, date '9941-10-01', date '9942-08-31'), (gen_random_uuid(), SA, date '9943-10-01', date '9944-08-31'),
               (gen_random_uuid(), SB, date '9945-10-01', date '9946-08-31')
        ON CONFLICT (name) DO NOTHING;
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state)
        SELECT 'ZZM 10' || n, 'Check held ' || n, 3, 2, 100, dept, 'Core', 'LIVE' FROM generate_series(1, 2) n;
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state, general_office)
        VALUES ('GST 943', 'Check general studies absent', 2, 2, 100, dept, 'GST', 'LIVE', 'GST');
        i := 0;
        FOREACH x IN ARRAY ARRAY[w, z, a, b, c, d, g] LOOP
            i := i + 1;
            INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
            VALUES (x, 'MOAUM/ADM/99/99424' || i, 'MOAUM/ZZM/99/042' || i, 'ZZHELD', 'Student ' || i, 'C00061', 'UTME', S0, 100, 100,
                    CASE WHEN x = d THEN 'GRADUATED' ELSE 'ACTIVE' END, now());
        END LOOP;

        -- the old portal's results: B fails ZZM 102 in S0, then is absent from it in SA; C absent in S0, passes in SA
        PERFORM assessment.import_legacy_semester(S0, 2, jsonb_build_array(
            jsonb_build_object('matric', 'MOAUM/ZZM/99/0424', 'course', 'ZZM 102', 'total', '20', 'level', '100'),
            jsonb_build_object('matric', 'MOAUM/ZZM/99/0425', 'course', 'ZZM 102', 'outcome', 'ABSENT', 'level', '100')), true);
        PERFORM assessment.import_legacy_semester(SA, 2, jsonb_build_array(
            jsonb_build_object('matric', 'MOAUM/ZZM/99/0421', 'course', 'ZZM 101', 'outcome', 'WITHHELD', 'level', '100'),
            jsonb_build_object('matric', 'MOAUM/ZZM/99/0422', 'course', 'ZZM 101', 'outcome', 'MALPRACTICE', 'level', '100'),
            jsonb_build_object('matric', 'MOAUM/ZZM/99/0423', 'course', 'ZZM 101', 'outcome', 'ABSENT', 'level', '100'),
            jsonb_build_object('matric', 'MOAUM/ZZM/99/0424', 'course', 'ZZM 102', 'outcome', 'ABSENT', 'level', '100'),
            jsonb_build_object('matric', 'MOAUM/ZZM/99/0425', 'course', 'ZZM 102', 'total', '65', 'level', '100'),
            jsonb_build_object('matric', 'MOAUM/ZZM/99/0426', 'course', 'ZZM 101', 'outcome', 'ABSENT', 'level', '100'),
            jsonb_build_object('matric', 'MOAUM/ZZM/99/0427', 'course', 'GST 943', 'outcome', 'ABSENT', 'level', '100')), true);
        SELECT s.id INTO sheet FROM assessment.score_sheet s JOIN catalogue.offering o ON o.id = s.offering_id
         WHERE o.course_code = 'ZZM 101' AND o.session = SA AND o.semester = 2;
        -- the sheet was published 40 days ago
        UPDATE assessment.score_sheet SET published_at = now() - interval '40 days' WHERE id = sheet;
        UPDATE assessment.score SET entered_at = now() - interval '40 days' WHERE sheet_id = sheet;

        -- (1) the held results: listed with their days; an amendment raised for W shows; Z decided is no longer held
        PERFORM set_config('moaum.actor_office', 'exams', true);
        amd := assessment.raise_amendment(sheet, w, 20, 40, 'GRADED', 'The Senate released the withheld result', NULL);
        PERFORM set_config('moaum.actor_office', 'records', true);
        SELECT h.outcome, h.days, h.amendment_stage INTO held_w, w_days, w_amd FROM assessment.held_results(NULL, NULL, NULL, SA) h WHERE h.student_id = w;
        SELECT h.outcome INTO held_z FROM assessment.held_results(NULL, dept, NULL, NULL) h WHERE h.student_id = z;
        INSERT INTO assessment.score (sheet_id, student_id, version, ca, exam, outcome, reason)
        VALUES (sheet, z, 2, NULL, NULL, 'ABSENT', 'check V424: the Senate''s decision');
        SELECT count(*) INTO decided FROM assessment.held_results(NULL, NULL, NULL, SA) h WHERE h.student_id = z;

        -- the reminder: past 30 days, once; not again within the week; never at 0 days
        DELETE FROM assessment.held_reminder_log;
        first_told := assessment.remind_held_results();
        SELECT l.held || '/' || l.oldest INTO logged FROM assessment.held_reminder_log l ORDER BY l.sent_at DESC LIMIT 1;
        again := assessment.remind_held_results() + (SELECT count(*) - 1 FROM assessment.held_reminder_log)::int;
        DELETE FROM assessment.held_reminder_log;
        PERFORM set_config('moaum.actor_office', 'academic', true);
        PERFORM policy.set_held_remind_days(0);
        zero_days := assessment.remind_held_results() + (SELECT count(*) FROM assessment.held_reminder_log)::int;
        PERFORM policy.set_held_remind_days(30);
        PERFORM set_config('moaum.actor_office', 'lecturer', true);
        BEGIN PERFORM policy.set_held_remind_days(14); r_office := 'SET';
        EXCEPTION WHEN check_violation THEN r_office := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_office', 'registrar', true);
        BEGIN PERFORM policy.set_held_remind_days(3); r_days := 'SET';
        EXCEPTION WHEN check_violation THEN r_days := split_part(SQLERRM, ':', 1); END;

        -- (2) who the absent rule now affects
        SELECT string_agg(right(x.number, 4) || ':' || x.course_code || ':' || x.absent_in, ',' ORDER BY x.number) INTO absent_list
          FROM assessment.absence_carryovers(NULL, NULL, 'C00061') x WHERE x.number LIKE 'MOAUM/ZZM/99/%';
        SELECT string_agg(right(x.number, 4) || ':' || x.course_code || ':' || x.office || ':' || x.absent_in, ',') INTO gst_list
          FROM finance.gst_eps_owed_for_absence(SB) x WHERE x.number LIKE 'MOAUM/ZZM/99/%';
        RAISE EXCEPTION 'the V424 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V424 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V424: held results listed with their days and open amendment, gone once decided; the Registry reminded of those past the University''s days once a week, never at 0, the days set only by the Academic Office or the Registry; carryovers from a recorded absence and GST/EPS owed again because of one listed, never from an earlier graded F, a later pass or a graduate',
        coalesce(held_w = 'WITHHELD' AND w_days = 40 AND w_amd = 'VERIFICATION' AND held_z = 'MALPRACTICE' AND decided = 0
                 AND first_told >= 0 AND logged = '1/40' AND again = 0 AND zero_days = 0
                 AND r_office = 'STANDING_SETTING_OFFICE' AND r_days = 'STANDING_SETTING_HELD_DAYS'
                 AND absent_list = '0422:ZZM 101:' || SA || ' semester 2,0423:ZZM 101:' || SA || ' semester 2,0427:GST 943:' || SA || ' semester 2'
                 AND gst_list = '0427:GST 943:GST:' || SA || ' semester 2', false),
        format('W %s %s days amd=%s | Z %s decided=%s | told=%s logged=%s again=%s zero=%s | office=%s days=%s | absent=%s | gst=%s',
               held_w, w_days, w_amd, held_z, decided, first_told, logged, again, zero_days, r_office, r_days, absent_list, gst_list));
END $$;

-- ── V425. The central notification engine: a template rendered for one student reaches them by e-mail, SMS and on the portal
--          with every token filled, and the same event never reaches them twice on a channel; an address that is not one is
--          recorded FAILED and never tried; a portal notice counts unread until read; a window's message runs as a job the
--          scheduler drains and reaches the session's students once; a student's biodata status reads INCOMPLETE, then
--          REVIEW_REQUIRED for a record nobody wrote to or confirmed, then UP_TO_DATE once confirmed; a staff member's
--          profile e-mail becomes the person's ──
DO $$
DECLARE S text := '9981/9982'; who uuid := gen_random_uuid(); a uuid := gen_random_uuid(); b uuid := gen_random_uuid(); staff uuid := gen_random_uuid();
        n_first int; n_second int; v_subject text; v_body text; v_tokens int; v_channels text;
        st_bad text; err_bad text; st_phone text; err_phone text; v_bad uuid; v_badphone uuid;
        unread1 int; unread2 int;
        job uuid; r1 record; r2 record; told_a int; told_b int; job_state text;
        s_incomplete text; s_review text; s_done text; conf timestamptz; r_confirm text := 'accepted';
        staff_email text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'ict', true); PERFORM set_config('moaum.reason', 'CHECK V425', true);
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (who, 'CHK/V425', 'CHECKV425', 'ICT');
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9981-10-01', date '9982-08-31') ON CONFLICT (name) DO NOTHING;
        -- two students of the session: one with every address, one with only a phone
        -- the first came over from the old portal: a matriculation number the portal never issued (matriculation_run empty)
        INSERT INTO people.student (id, admission_no, matric_no, matriculated_at, surname, other_names, sex, programme_code, entry_mode, entry_session, entry_level, current_level, status, study_mode)
        VALUES (a, 'MOAUM/ADM/81/009425', 'MOAUM/CHK/81/9425', now(), 'CHECKV425', 'Engine Ada', 'F', 'C00023', 'UTME', S, 100, 100, 'ACTIVE', 'FULL_TIME'),
               (b, 'MOAUM/ADM/81/009426', NULL, NULL, 'CHECKV425B', 'Engine Bola', 'M', 'C00023', 'UTME', S, 100, 100, 'ADMITTED', 'FULL_TIME');
        INSERT INTO iam.student_account (id, student_id, password_hash, must_change) VALUES (gen_random_uuid(), a, '$2a$12$CHECKV425CHECKV425CHECKV425CHECKV425CHECKV425CHECKV42', true);
        INSERT INTO people.student_contact (student_id, phone, email) VALUES (a, '08000000425', 'v425@example.test'), (b, '08000000426', NULL);
        PERFORM platform.set_portal_url('https://portal.example.test/', who, 'ict');
        -- 1. a template rendered for one student: three channels, every token filled, once per event
        n_first := platform.tell_student(a, 'WINDOW_OPENED', 'COURSE_REGISTRATION',
                       jsonb_build_object('WINDOW', 'Course registration', 'SESSION', S, 'SEMESTER', ', semester 1', 'CLOSES_NOTE', 'It closes on 1 December 9981 23:59.'), 'check:v425:open');
        n_second := platform.tell_student(a, 'WINDOW_OPENED', 'COURSE_REGISTRATION',
                       jsonb_build_object('WINDOW', 'Course registration', 'SESSION', S, 'SEMESTER', ', semester 1'), 'check:v425:open');
        SELECT subject, body INTO v_subject, v_body FROM platform.notice WHERE about_id = a AND channel = 'EMAIL' AND event_key = 'check:v425:open';
        SELECT count(*) INTO v_tokens FROM platform.notice WHERE about_id = a AND event_key = 'check:v425:open' AND (subject ~ '\[[A-Z_]+\]' OR body ~ '\[[A-Z_]+\]');
        SELECT string_agg(channel, ',' ORDER BY channel) INTO v_channels FROM platform.notice WHERE about_id = a AND event_key = 'check:v425:open';
        -- 2. an address that is not one is FAILED at once, never queued
        v_bad := platform.queue_notice('EMAIL', 'nobody-at-nowhere', 'CHECK', 'CHECK', 'test', NULL, NULL, NULL, NULL);
        v_badphone := platform.queue_notice('SMS', '12', 'CHECK', 'CHECK', 'test', NULL, NULL, NULL, NULL);
        SELECT state, last_error INTO st_bad, err_bad FROM platform.notice WHERE id = v_bad;
        SELECT state, last_error INTO st_phone, err_phone FROM platform.notice WHERE id = v_badphone;
        -- 3. the portal notice counts unread until read
        unread1 := platform.unread_count('student', a);
        PERFORM platform.mark_all_read('student', a);
        unread2 := platform.unread_count('student', a);
        -- 4. a window's message as a job: the session's students reached once, the job done when nobody is further
        PERFORM policy.window_act('COURSE_REGISTRATION', S, 1, 'OPEN', NULL, NULL, NULL, false, 'CHECK V425: window opened', who, 'ict');
        job := platform.queue_window_job('COURSE_REGISTRATION', S, 1, 'OPEN', who, 'ict');
        SELECT * INTO r1 FROM platform.run_notice_job(1000000);
        SELECT * INTO r2 FROM platform.run_notice_job(1000000);
        SELECT count(*) INTO told_a FROM platform.notice WHERE about_id = a AND event_key LIKE 'window:%:OPEN';
        SELECT count(*) INTO told_b FROM platform.notice WHERE about_id = b AND event_key LIKE 'window:%:OPEN';
        SELECT state INTO job_state FROM platform.notice_job WHERE id = job;
        -- 5. the biodata status: incomplete, then (only the photograph and the contact required) complete but never written to or
        --    confirmed = REVIEW_REQUIRED, then confirmed = UP_TO_DATE; a confirmation while incomplete is refused
        s_incomplete := (people.biodata_status(a)).status;
        BEGIN PERFORM people.confirm_biodata(a, a); EXCEPTION WHEN check_violation THEN r_confirm := split_part(SQLERRM, ':', 1); END;
        UPDATE people.biodata_requirement SET required = false WHERE item NOT IN ('PASSPORT', 'mobile', 'personal_email');
        INSERT INTO people.student_photo (student_id, content, content_type, bytes, reason) VALUES (a, decode('ffd8ffd9', 'hex'), 'image/jpeg', 4, 'CHECK V425');
        s_review := (people.biodata_status(a)).status;
        conf := people.confirm_biodata(a, a);
        s_done := (people.biodata_status(a)).status;
        -- 6. a staff member's profile e-mail becomes the person's
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (staff, 'CHK/V425S', 'CHECKV425', 'Staff');
        INSERT INTO hrm.staff_profile (person_id, email, phone) VALUES (staff, 'staff-v425@example.test', '08000000427');
        SELECT email INTO staff_email FROM iam.person WHERE id = staff;
        RAISE EXCEPTION 'the V425 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V425: a template reaches a student on every channel once per event with the tokens filled; a bad address fails at once; a portal notice counts unread until read; a window job reaches the session once; the biodata status reads INCOMPLETE, REVIEW_REQUIRED, UP_TO_DATE; a staff profile e-mail becomes the person''s',
        coalesce(n_first = 3 AND n_second = 0 AND v_channels = 'EMAIL,PORTAL,SMS'
                 AND v_subject = 'Course registration for ' || S || ', semester 1 is open' AND v_body LIKE 'Dear Engine,%' AND v_body LIKE '%https://portal.example.test%' AND v_tokens = 0
                 AND st_bad = 'FAILED' AND err_bad = 'INVALID_EMAIL' AND st_phone = 'FAILED' AND err_phone = 'INVALID_PHONE'
                 AND unread1 = 1 AND unread2 = 0
                 AND r1.reached = 2 AND r1.done AND r2.job_id IS NULL AND told_a = 3 AND told_b = 2 AND job_state = 'DONE'
                 AND s_incomplete = 'INCOMPLETE' AND r_confirm = 'BIODATA_INCOMPLETE' AND s_review = 'REVIEW_REQUIRED' AND conf IS NOT NULL AND s_done = 'UP_TO_DATE'
                 AND staff_email = 'staff-v425@example.test', false),
        format('first=%s second=%s channels=%s subject=%s tokens=%s bad=%s/%s phone=%s/%s unread=%s->%s job: reached=%s done=%s second=%s told a=%s b=%s state=%s status=%s/%s/%s confirm=%s staff=%s',
               n_first, n_second, v_channels, v_subject, v_tokens, st_bad, err_bad, st_phone, err_phone, unread1, unread2,
               r1.reached, r1.done, r2.job_id IS NULL, told_a, told_b, job_state, s_incomplete, s_review, s_done, r_confirm, staff_email));
END $$;

-- ── V426. A campaign reaches the students its filters name, once per person and channel, as a job the scheduler drains, and
--          is reported by channel; a Dean addresses only their own faculty's students; a preview counts the addresses; a
--          student's preference switches an optional message's SMS off but never a mandatory one; the offices' compliance
--          reading counts and lists the students by status within a faculty ──
DO $$
DECLARE S text := '9983/9984'; who uuid := gen_random_uuid(); dean uuid := gen_random_uuid();
        a uuid := gen_random_uuid(); b uuid := gen_random_uuid(); c uuid := gen_random_uuid(); camp uuid; camp2 uuid; job uuid;
        fac_a text; fac_c text; dept_a text; prog_c text;
        pv_total int; pv_email_ok int; pv_email_missing int; pv_phone_ok int;
        r1 record; r2 record; st_after text; told_a int; told_b int; told_c int; rep_email int; rep_sms int; rep_portal int;
        r_scope text := 'accepted'; r_empty text := 'accepted'; r_sent_edit text := 'accepted'; r_cancel text := 'accepted';
        ann_sms int; win_sms int; ann_q int; win_q int;
        sum_total int; sum_inc int; sum_rev int; list_n int; list_total bigint; computed timestamptz;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'ict', true); PERFORM set_config('moaum.reason', 'CHECK V426', true);
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (who, 'CHK/V426', 'CHECKV426', 'ICT'), (dean, 'CHK/V426D', 'CHECKV426', 'Dean');
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9983-10-01', date '9984-08-31') ON CONFLICT (name) DO NOTHING;
        -- two faculties: a and b (migrated, one with no e-mail) in the first, c in another
        SELECT p.faculty_code, p.dept_code INTO fac_a, dept_a FROM ref.programme p WHERE p.code = 'C00023';
        SELECT p.code, p.faculty_code INTO prog_c, fac_c FROM ref.programme p WHERE p.faculty_code <> fac_a AND NOT coalesce(p.archived, false) ORDER BY p.code LIMIT 1;
        INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from)
        VALUES (gen_random_uuid(), dean, 'dean', 'faculty', fac_a, 'CHECK V426', who, current_date);
        INSERT INTO people.student (id, admission_no, matric_no, matriculated_at, surname, other_names, sex, programme_code, entry_mode, entry_session, entry_level, current_level, status, study_mode)
        VALUES (a, 'MOAUM/ADM/83/009426', 'MOAUM/CHK/83/9426', now(), 'CHECKV426', 'Campaign Ada', 'F', 'C00023', 'UTME', S, 100, 100, 'ACTIVE', 'FULL_TIME'),
               (b, 'MOAUM/ADM/83/009427', 'MOAUM/CHK/83/9427', now(), 'CHECKV426B', 'Campaign Bola', 'M', 'C00023', 'UTME', S, 100, 100, 'ACTIVE', 'FULL_TIME'),
               (c, 'MOAUM/ADM/83/009428', NULL, NULL, 'CHECKV426C', 'Campaign Chidi', 'M', prog_c, 'UTME', S, 100, 100, 'ADMITTED', 'FULL_TIME');
        INSERT INTO people.student_contact (student_id, phone, email) VALUES (a, '08000009426', 'v426a@example.test'), (b, '08000009427', NULL), (c, '08000009428', 'v426c@example.test');
        PERFORM platform.set_portal_url('https://portal.example.test', who, 'ict');
        -- 1. the Dean of a's faculty: their own faculty only, never the other, never the staff
        PERFORM set_config('moaum.actor_office', 'dean', true);
        BEGIN PERFORM platform.campaign_save(NULL, 'CHECK dean elsewhere', 'PORTAL_MIGRATION', jsonb_build_object('students', true, 'filters', jsonb_build_object('faculty', fac_c)), ARRAY['EMAIL'], '{}'::jsonb, dean, 'dean');
        EXCEPTION WHEN check_violation THEN r_scope := split_part(SQLERRM, ':', 1); END;
        camp2 := platform.campaign_save(NULL, 'CHECK dean own', 'PORTAL_MIGRATION', jsonb_build_object('students', true, 'filters', jsonb_build_object('faculty', fac_a, 'session', S)), ARRAY['EMAIL'], '{}'::jsonb, dean, 'dean');
        PERFORM set_config('moaum.actor_office', 'ict', true);
        -- 2. ICT's migration campaign to the session's students who came over, in a's faculty: the preview counts a and b only
        camp := platform.campaign_save(NULL, 'CHECK welcome', 'PORTAL_MIGRATION', jsonb_build_object('students', true, 'filters', jsonb_build_object('faculty', fac_a, 'session', S, 'migrated', true)),
                                       ARRAY['EMAIL', 'SMS', 'PORTAL'], '{}'::jsonb, who, 'ict');
        SELECT total, email_ok, email_missing, phone_ok INTO pv_total, pv_email_ok, pv_email_missing, pv_phone_ok FROM platform.campaign_preview(camp) WHERE kind = 'student';
        -- an empty audience is refused
        BEGIN PERFORM platform.campaign_send(platform.campaign_save(NULL, 'CHECK nobody', 'PORTAL_MIGRATION', jsonb_build_object('applicants', true, 'filters', jsonb_build_object('session', S)), ARRAY['EMAIL'], '{}'::jsonb, who, 'ict'), who, 'ict');
        EXCEPTION WHEN check_violation THEN r_empty := split_part(SQLERRM, ':', 1); END;
        -- 3. sent as a job: one batch reaches a and b; a second run finds nothing; the campaign is SENT; the report counts by channel
        job := platform.campaign_send(camp, who, 'ict');
        SELECT * INTO r1 FROM platform.run_notice_job(1000000);
        SELECT * INTO r2 FROM platform.run_notice_job(1000000);
        SELECT state INTO st_after FROM platform.notice_campaign WHERE id = camp;
        SELECT count(*) INTO told_a FROM platform.notice WHERE about_id = a AND event_key = 'campaign:' || camp;
        SELECT count(*) INTO told_b FROM platform.notice WHERE about_id = b AND event_key = 'campaign:' || camp;
        SELECT count(*) INTO told_c FROM platform.notice WHERE about_id = c AND event_key = 'campaign:' || camp;
        SELECT coalesce(sum(total) FILTER (WHERE channel = 'EMAIL'), 0), coalesce(sum(total) FILTER (WHERE channel = 'SMS'), 0), coalesce(sum(total) FILTER (WHERE channel = 'PORTAL'), 0)
          INTO rep_email, rep_sms, rep_portal FROM platform.campaign_report(camp);
        BEGIN PERFORM platform.campaign_save(camp, 'CHECK edited', 'PORTAL_MIGRATION', jsonb_build_object('students', true), ARRAY['EMAIL'], '{}'::jsonb, who, 'ict');
        EXCEPTION WHEN check_violation THEN r_sent_edit := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM platform.campaign_cancel(camp, 'CHECK', who, 'ict');
        EXCEPTION WHEN check_violation THEN r_cancel := split_part(SQLERRM, ':', 1); END;
        -- 4. a's preference: SMS off — an announcement (optional) skips the SMS, a window (mandatory) does not
        PERFORM platform.set_preference('student', a, 'SMS', false);
        ann_q := platform.tell_student(a, 'ANNOUNCEMENT', NULL, jsonb_build_object('TITLE', 'CHECK', 'MESSAGE', 'Hello', 'SMS_MESSAGE', 'Hello', 'SIGNATURE', 'Registry'), 'check:v426:ann');
        SELECT count(*) INTO ann_sms FROM platform.notice WHERE about_id = a AND event_key = 'check:v426:ann' AND channel = 'SMS';
        win_q := platform.tell_student(a, 'WINDOW_OPENED', 'COURSE_REGISTRATION', jsonb_build_object('WINDOW', 'Course registration', 'SESSION', S, 'SEMESTER', ''), 'check:v426:win');
        SELECT count(*) INTO win_sms FROM platform.notice WHERE about_id = a AND event_key = 'check:v426:win' AND channel = 'SMS';
        -- 5. the compliance reading: a and b incomplete in a's faculty; c elsewhere; the list within the faculty
        PERFORM people.refresh_biodata_snapshot(NULL);
        SELECT total, incomplete, review_required, computed_at INTO sum_total, sum_inc, sum_rev, computed FROM people.biodata_compliance_summary(fac_a, NULL);
        SELECT count(*), max(total) INTO list_n, list_total FROM people.biodata_status_list('INCOMPLETE', fac_a, NULL, NULL, NULL, S, NULL, NULL, 'CHECKV426', 50, 0);
        RAISE EXCEPTION 'the V426 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V426: a campaign reaches the students its filters name once per person and channel as a job, is reported by channel and never edited once sent; a Dean addresses only their own faculty; the preview counts addresses; a preference switches an optional SMS off but never a mandatory one; the compliance reading counts and lists by status within a faculty',
        coalesce(r_scope = 'CAMPAIGN_SCOPE' AND camp2 IS NOT NULL
                 AND pv_total = 2 AND pv_email_ok = 1 AND pv_email_missing = 1 AND pv_phone_ok = 2 AND r_empty = 'CAMPAIGN_EMPTY'
                 AND r1.reached = 2 AND r1.done AND r2.job_id IS NULL AND st_after = 'SENT'
                 AND told_a = 3 AND told_b = 2 AND told_c = 0 AND rep_email = 1 AND rep_sms = 2 AND rep_portal = 2
                 AND r_sent_edit = 'CAMPAIGN_NOT_DRAFT' AND r_cancel = 'CAMPAIGN_FINISHED'
                 AND ann_q = 2 AND ann_sms = 0 AND win_q = 3 AND win_sms = 1
                 AND sum_total >= 2 AND sum_inc >= 2 AND computed IS NOT NULL AND list_n = 2 AND list_total = 2, false),
        format('scope=%s own=%s preview total=%s email ok=%s missing=%s phone ok=%s empty=%s | run1 reached=%s done=%s run2 none=%s state=%s told a=%s b=%s c=%s report email=%s sms=%s portal=%s edit=%s cancel=%s | ann q=%s sms=%s win q=%s sms=%s | summary total=%s inc=%s rev=%s computed=%s list=%s/%s',
               r_scope, camp2 IS NOT NULL, pv_total, pv_email_ok, pv_email_missing, pv_phone_ok, r_empty, r1.reached, r1.done, r2.job_id IS NULL, st_after, told_a, told_b, told_c,
               rep_email, rep_sms, rep_portal, r_sent_edit, r_cancel, ann_q, ann_sms, win_q, win_sms, sum_total, sum_inc, sum_rev, computed IS NOT NULL, list_n, list_total));
END $$;

-- ── V430. Staff reach: an active person with an office counts as reachable, phone-only, e-mail-only or unreachable; the weekly
--          reminder runs only on ICT's switch, reaches a phone-only person by SMS and on the portal, once in seven days, and tells
--          the HR office once a week how many cannot be reached; the contact prompt asks a person with no usable address,
--          stays away for seven days once put off, and never asks one the portal can reach ──
DO $$
DECLARE who uuid := gen_random_uuid(); a uuid := gen_random_uuid(); b uuid := gen_random_uuid(); c uuid := gen_random_uuid(); dept text;
        s_total int; s_reach int; s_phone int; s_unreach int; s_never int;
        l_n int; l_total bigint; l_status text;
        p_ask text; p_skip text; p_none text; p_student text;
        r_off int; r_on int; r_again int; told_a int; told_a_sms int; told_b int; hr_told int; hr_again int; week_now text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'ict', true); PERFORM set_config('moaum.reason', 'CHECK V430', true);
        SELECT code INTO dept FROM ref.department WHERE ended_on IS NULL ORDER BY code LIMIT 1;
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (who, 'CHK/V430', 'CHECKV430', 'ICT');
        -- a: a lecturer with a phone and no e-mail; b: a registry officer with neither; c: reachable on both
        INSERT INTO iam.person (id, staff_number, surname, given_names, email, phone) VALUES
            (a, 'CHK/V430A', 'CHECKV430', 'Staff Ada', NULL, '08000009430'),
            (b, 'CHK/V430B', 'CHECKV430', 'Staff Bola', NULL, NULL),
            (c, 'CHK/V430C', 'CHECKV430', 'Staff Chidi', 'v430c@example.test', '08000009432');
        INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from) VALUES
            (gen_random_uuid(), a, 'lecturer', 'department', dept, 'CHECK V430', who, current_date),
            (gen_random_uuid(), b, 'registrar', 'institution', NULL, 'CHECK V430', who, current_date),
            (gen_random_uuid(), c, 'lecturer', 'department', dept, 'CHECK V430', who, current_date);
        PERFORM platform.set_portal_url('https://portal.example.test', who, 'ict');
        -- 1. the reading
        SELECT total, reachable, phone_only, unreachable, never_signed_in INTO s_total, s_reach, s_phone, s_unreach, s_never FROM iam.staff_reach_summary(NULL);
        SELECT count(*), max(total), max(status) INTO l_n, l_total, l_status FROM iam.staff_reach_list('PHONE_ONLY', NULL, 'CHECKV430', 50, 0);
        -- 2. the prompt: asked of a, put off, not asked for seven days; never asked of c; a student with a contact not asked
        p_ask := (SELECT state FROM platform.contact_prompt_for('person', a));
        PERFORM platform.contact_prompt_skip('person', a);
        p_skip := (SELECT state FROM platform.contact_prompt_for('person', a));
        p_none := (SELECT state FROM platform.contact_prompt_for('person', c));
        -- 3. the reminder: nothing while the switch is off; on, a and b once (a by SMS and the portal, b on the portal only), not again
        UPDATE platform.notice_setting SET staff_contact_remind = false, staff_digest_week = NULL WHERE id;
        r_off := iam.remind_staff_contact(1000);
        UPDATE platform.notice_setting SET staff_contact_remind = true WHERE id;
        r_on := iam.remind_staff_contact(1000);
        r_again := iam.remind_staff_contact(1000);
        SELECT count(*), count(*) FILTER (WHERE channel = 'SMS') INTO told_a, told_a_sms FROM platform.notice WHERE about_id = a AND template_key = 'STAFF_CONTACT_REMINDER';
        SELECT count(*) INTO told_b FROM platform.notice WHERE about_id = b AND template_key = 'STAFF_CONTACT_REMINDER';
        week_now := to_char(now() AT TIME ZONE 'Africa/Lagos', 'IYYY-"W"IW');
        hr_told := CASE WHEN (SELECT staff_digest_week FROM platform.notice_setting WHERE id) = week_now THEN 1 ELSE 0 END;
        RAISE EXCEPTION 'the V430 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V430: the staff reach reading counts reachable, phone-only and unreachable; the prompt asks a person with no usable address, stays away once put off and never asks a reachable one; the weekly reminder runs on the switch only, once in seven days, by the channel the person has, and the HR office is told once a week',
        coalesce(s_total >= 3 AND s_reach >= 1 AND s_phone >= 1 AND s_unreach >= 1 AND s_never >= 3
                 AND l_n = 1 AND l_total = 1 AND l_status = 'PHONE_ONLY'
                 AND p_ask = 'ASK' AND p_skip = 'NONE' AND p_none = 'NONE'
                 AND r_off = 0 AND r_on >= 2 AND r_again = 0 AND told_a = 2 AND told_a_sms = 1 AND told_b = 1 AND hr_told = 1, false),
        format('summary total=%s reach=%s phone=%s unreach=%s never=%s | list n=%s total=%s status=%s | prompt ask=%s skip=%s none=%s | remind off=%s on=%s again=%s told a=%s (sms %s) b=%s hr=%s',
               s_total, s_reach, s_phone, s_unreach, s_never, l_n, l_total, l_status, p_ask, p_skip, p_none, r_off, r_on, r_again, told_a, told_a_sms, told_b, hr_told));
END $$;
-- ── V427. Payments classified fast and each required biodata item counted: the rules' answers are kept per input — the
--          category per purpose or kind, the programme type per entry mode and programme category, the owner per purpose and
--          programme type — every one equal to the rule's own; a payment with a purpose never met before is learnt as it is
--          created; a category the Bursary states reaches the ledger at once; an input the memo has lost still gets the rule's
--          answer; the applicants' programme by name is the one admissions.programme_code_of chooses; and for each item that
--          can be required, the students who lack it, the complete ones it would hold and the held ones it alone holds ──
DO $$
DECLARE S text := '9979/9980'; who uuid := gen_random_uuid(); a uuid := gen_random_uuid(); b uuid := gen_random_uuid(); c uuid := gen_random_uuid();
        purpose text := 'CHECK V427 hostel maintenance levy'; ref1 text := 'MOAUM-CHK-V427-0001';
        n_memo int; cat_ok boolean; pt_ok boolean; own_ok boolean; learnt boolean; view_cat text; fn_cat text; cat_after text; fallback_cat text;
        prog_ok boolean; i0 jsonb; i1 jsonb; d_students int; d_kin_missing int; d_kin_freed int; d_religion_held int; d_passport_missing int;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'bursar', true); PERFORM set_config('moaum.reason', 'CHECK V427', true);
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (who, 'CHK/V427', 'CHECKV427', 'Bursary');
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9979-10-01', date '9980-08-31') ON CONFLICT (name) DO NOTHING;
        -- the memo holds the rules' own answers
        SELECT count(*) INTO n_memo FROM finance.category_memo;
        SELECT coalesce(bool_and(m.code = finance.categorise(nullif(m.kind, ''), nullif(m.purpose, ''))), true) INTO cat_ok FROM finance.category_memo m;
        SELECT coalesce(bool_and(m.code = finance.programme_type_for(nullif(m.entry_mode, ''), nullif(m.category, ''))), true) INTO pt_ok FROM finance.programme_type_memo m;
        SELECT coalesce(bool_and(o.source_module IS NOT DISTINCT FROM m.source_module AND o.responsible_office IS NOT DISTINCT FROM m.responsible_office), true) INTO own_ok
          FROM finance.owner_memo m LEFT JOIN LATERAL finance.payment_owner(m.purpose, m.programme_type) o(source_module, responsible_office) ON true;
        -- the counts before the students of this check
        SELECT jsonb_object_agg(x.item, jsonb_build_object('students', x.students, 'missing', x.missing, 'held', x.newly_held, 'freed', x.freed)) INTO i0
          FROM people.biodata_requirement_impact() x;
        INSERT INTO people.student (id, admission_no, surname, other_names, sex, programme_code, entry_mode, entry_session, entry_level, current_level, status, study_mode)
        VALUES (a, 'MOAUM/ADM/79/009427', 'CHECKV427', 'Payer', 'F', 'C00023', 'UTME', S, 100, 100, 'ADMITTED', 'FULL_TIME'),
               (b, 'MOAUM/ADM/79/009428', 'CHECKV427', 'Held by one', 'M', 'C00023', 'UTME', S, 100, 100, 'ADMITTED', 'FULL_TIME'),
               (c, 'MOAUM/ADM/79/009429', 'CHECKV427', 'Complete', 'F', 'C00023', 'UTME', S, 100, 100, 'ADMITTED', 'FULL_TIME');
        -- a payment with a purpose nobody has paid for: learnt as it is created, classified as the rule classifies it
        INSERT INTO finance.payment_reference (student_id, session, reference, purpose, amount, expires_at, confirmed_at, confirmed_by, channel, receipt_no)
        VALUES (a, S, ref1, purpose, 1000, now() + interval '1 day', now(), who, 'Card', 'RCPT-V427-0001');
        learnt := EXISTS (SELECT 1 FROM finance.category_memo WHERE kind = '' AND finance.category_memo.purpose = 'CHECK V427 hostel maintenance levy');
        SELECT v.category_code INTO view_cat FROM reporting.payments v WHERE v.reference = ref1;
        fn_cat := finance.categorise(NULL, purpose);
        -- the Bursary states a category that matches it: recomputed in the same transaction, the ledger follows
        INSERT INTO finance.payment_category (code, label, pattern, ord, revenue, active) VALUES ('CHKV427', 'CHECK V427 levy', '^check v427', 0, true, true);
        SELECT v.category_code INTO cat_after FROM reporting.payments v WHERE v.reference = ref1;
        -- an input the memo has lost is still the rule's
        DELETE FROM finance.category_memo WHERE finance.category_memo.purpose = 'CHECK V427 hostel maintenance levy';
        SELECT v.category_code INTO fallback_cat FROM reporting.payments v WHERE v.reference = ref1;
        -- the applicants' programme by name, as programme_code_of chooses
        SELECT coalesce(bool_and(v.programme_code IS NOT DISTINCT FROM admissions.programme_code_of(cd.programme)), true) INTO prog_ok
          FROM reporting.payments v JOIN admissions.application ap ON ap.id = v.application_id JOIN admissions.candidate cd ON cd.id = ap.candidate_id
         WHERE v.source = 'APPLICANT';
        -- b has every required item but the next of kin's phone; c has every required item and no religion
        INSERT INTO people.student_contact (student_id, phone, email) VALUES (b, '08000000427', 'v427b@example.test'), (c, '08000000428', 'v427c@example.test');
        INSERT INTO people.student_photo (student_id, content, content_type, bytes, reason) VALUES (b, decode('ffd8ffd9', 'hex'), 'image/jpeg', 4, 'CHECK V427'),
                                                                                                (c, decode('ffd8ffd9', 'hex'), 'image/jpeg', 4, 'CHECK V427');
        INSERT INTO people.biodata (student_id, field, value)
        SELECT s.id, f.field, f.value FROM (VALUES (b), (c)) s(id)
         CROSS JOIN (VALUES ('nationality', 'Nigeria'), ('home_address', 'CHECK house, Makurdi'), ('state_of_origin', 'Benue'), ('lga', 'Makurdi'),
                            ('kin_name', 'CHECK Kin'), ('kin_relationship', 'Mother')) f(field, value);
        INSERT INTO people.biodata (student_id, field, value) VALUES (c, 'kin_mobile', '08000000429');
        SELECT jsonb_object_agg(x.item, jsonb_build_object('students', x.students, 'missing', x.missing, 'held', x.newly_held, 'freed', x.freed)) INTO i1
          FROM people.biodata_requirement_impact() x;
        d_students := (i1->'kin_mobile'->>'students')::int - (i0->'kin_mobile'->>'students')::int;
        d_kin_missing := (i1->'kin_mobile'->>'missing')::int - (i0->'kin_mobile'->>'missing')::int;
        d_kin_freed := (i1->'kin_mobile'->>'freed')::int - (i0->'kin_mobile'->>'freed')::int;
        d_religion_held := (i1->'religion'->>'held')::int - (i0->'religion'->>'held')::int;
        d_passport_missing := (i1->'PASSPORT'->>'missing')::int - (i0->'PASSPORT'->>'missing')::int;
        RAISE EXCEPTION 'the V427 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V427: the memo holds each classification rule''s own answer, a new purpose is learnt as it is paid, a category the Bursary states reaches the ledger at once, a lost memo row still gets the rule''s answer, the applicants'' programme is programme_code_of''s; the impact counts a student held by one item as freed by it and a complete student as held by a new item',
        coalesce(n_memo > 0 AND cat_ok AND pt_ok AND own_ok AND learnt AND view_cat = fn_cat AND cat_after = 'CHKV427' AND fallback_cat = 'CHKV427' AND prog_ok
                 AND d_students = 3 AND d_kin_missing = 2 AND d_kin_freed = 1 AND d_religion_held = 1 AND d_passport_missing = 1, false),
        format('memo=%s cat=%s pt=%s own=%s learnt=%s view=%s fn=%s after=%s fallback=%s prog=%s | students +%s kin missing +%s freed +%s religion held +%s passport missing +%s',
               n_memo, cat_ok, pt_ok, own_ok, learnt, view_cat, fn_cat, cat_after, fallback_cat, prog_ok, d_students, d_kin_missing, d_kin_freed, d_religion_held, d_passport_missing));
END $$;
-- ── V428: a person's own number is never their password ──
-- The migration desk's "default passwords", which wrote each student's own number as the password, are retired: the function
-- refuses with the way in. The teaching-staff upload gives an invented lecturer a first password nobody knows — never the staff
-- number. The block undoes its writes.
DO $$
DECLARE who uuid := gen_random_uuid(); dept text; refused text; own boolean; made int; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'ict', true);
        PERFORM set_config('moaum.reason', 'check V428', true);
        BEGIN PERFORM iam.set_migrated_default_passwords(); refused := 'SET';
        EXCEPTION WHEN check_violation THEN refused := split_part(SQLERRM, ':', 1); END;
        SELECT dept_code INTO dept FROM ref.programme WHERE code = 'C00061';
        SELECT x.credentialed INTO made FROM iam.import_lecturers(jsonb_build_array(
            jsonb_build_object('pno', '994281', 'full_names', 'Dr Invented Checkfour', 'department', dept, 'sex', 'F'))) x;
        SELECT crypt('P994281', c.password_hash) = c.password_hash INTO own FROM iam.credential c WHERE c.username = 'p994281';
        RAISE EXCEPTION 'the V428 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V428 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V428: a person''s own number is never their password — the migration desk''s default passwords refuse; the teaching-staff upload gives a password nobody knows',
        coalesce(refused = 'AUTH_DEFAULT_PASSWORD_RETIRED' AND made = 1 AND own = false, false),
        format('default passwords: %s | upload credentialed %s, own number opens it: %s', refused, made, own));
END $$;
-- ── V429: intake never makes a second student ──
-- Invented candidates admitted for a session of their own. A is already on the register under A's JAMB number, unlinked: intake links
-- that student, drawing no second admission number. B's earlier record names another programme and carries nothing: intake links it
-- and moves it to the admitted programme. C's earlier record names another programme and carries a registration: intake refuses
-- (INTAKE_DUPLICATE_JAMB). A second record sharing a JAMB number is listed for the Registry. The block undoes its writes.
DO $$
DECLARE who uuid := gen_random_uuid(); S text := '9947/9948'; prog text; prog_name text; other text;
        ca uuid := gen_random_uuid(); cb uuid := gen_random_uuid(); cc uuid := gen_random_uuid();
        sa uuid := gen_random_uuid(); sb uuid := gen_random_uuid(); sc uuid := gen_random_uuid(); dup uuid := gen_random_uuid();
        bt uuid := gen_random_uuid(); ra uuid := gen_random_uuid(); rb uuid := gen_random_uuid(); rc uuid := gen_random_uuid();
        got_a uuid; got_b uuid; b_prog text; c_refused text; n_a bigint; listed int; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        PERFORM set_config('moaum.reason', 'check V429', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9947-10-01', date '9948-08-31') ON CONFLICT (name) DO NOTHING;
        SELECT code, name INTO prog, prog_name FROM ref.programme WHERE code = 'C00061';
        SELECT code INTO other FROM ref.programme WHERE code <> 'C00061' AND NOT archived ORDER BY code LIMIT 1;
        -- admitted from a CAPS row, as every admission is (ck_candidate_needs_caps)
        INSERT INTO admissions.caps_batch (id, session, source, list_kind, file_sha256, rows_read, downloaded_on, uploaded_by, uploaded_office)
        VALUES (bt, S, 'CAPS_DOWNLOAD', 'UTME', '47'::bytea, 3, date '9947-09-01', who, 'academic');
        INSERT INTO admissions.caps_row (id, batch_id, session, jamb_reg_no, raw, surname, other_names, jamb_code, aggregate, entry_mode)
        VALUES (ra, bt, S, '994700000001ZA', '{}'::jsonb, 'ZZINTAKE', 'Candidate A', prog, 250, 'UTME'),
               (rb, bt, S, '994700000002ZB', '{}'::jsonb, 'ZZINTAKE', 'Candidate B', prog, 250, 'UTME'),
               (rc, bt, S, '994700000003ZC', '{}'::jsonb, 'ZZINTAKE', 'Candidate C', prog, 250, 'UTME');
        INSERT INTO admissions.candidate (id, session, jamb_reg_no, surname, other_names, programme, entry_mode, entry_level, offer_state, admitted_from)
        VALUES (ca, S, '994700000001ZA', 'ZZINTAKE', 'Candidate A', prog_name, 'UTME', 100, 'ADMITTED', ra),
               (cb, S, '994700000002ZB', 'ZZINTAKE', 'Candidate B', prog_name, 'UTME', 100, 'ADMITTED', rb),
               (cc, S, '994700000003ZC', 'ZZINTAKE', 'Candidate C', prog_name, 'UTME', 100, 'ADMITTED', rc);
        INSERT INTO people.student (id, admission_no, jamb_reg_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status)
        VALUES (sa, 'MOAUM/ADM/47/994701', '994700000001ZA', 'ZZINTAKE', 'Candidate A', prog, 'UTME', S, 100, 100, 'ADMITTED'),
               (sb, 'MOAUM/ADM/47/994702', '994700000002ZB', 'ZZINTAKE', 'Candidate B', other, 'UTME', S, 100, 100, 'ADMITTED'),
               (sc, 'MOAUM/ADM/47/994703', '994700000003ZC', 'ZZINTAKE', 'Candidate C', other, 'UTME', S, 100, 100, 'ADMITTED'),
               (dup, 'MOAUM/ADM/47/994704', '994700000003ZC', 'ZZINTAKE', 'Candidate C copy', other, 'UTME', S, 100, 100, 'ADMITTED');
        INSERT INTO people.enrolment (id, student_id, session, level) VALUES (gen_random_uuid(), sc, S, 100);
        INSERT INTO registration.course_registration (id, student_id, session, semester, level, status) VALUES (gen_random_uuid(), sc, S, 1, 100, 'DRAFT');

        got_a := people.intake_one(ca);
        SELECT count(*) INTO n_a FROM people.student WHERE upper(jamb_reg_no) = '994700000001ZA';
        got_b := people.intake_one(cb);
        SELECT programme_code INTO b_prog FROM people.student WHERE id = sb;
        BEGIN PERFORM people.intake_one(cc); c_refused := 'TAKEN';
        EXCEPTION WHEN check_violation THEN c_refused := split_part(SQLERRM, ':', 1); END;
        SELECT count(*) INTO listed FROM people.duplicate_students() d WHERE d.kind = 'SAME_JAMB' AND d.match_key = '994700000003ZC';
        RAISE EXCEPTION 'the V429 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V429 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V429: intake links the student already on the register under the JAMB number — never a second admission number; an untouched earlier record takes the admitted programme; one with a history on another programme is refused for the Registry; a shared JAMB number is listed',
        coalesce(got_a = sa AND n_a = 1 AND got_b = sb AND b_prog = prog AND c_refused = 'INTAKE_DUPLICATE_JAMB' AND listed = 2, false),
        format('A %s (records %s) | B %s on %s | C %s | listed %s', got_a = sa, n_a, got_b = sb, b_prog, c_refused, listed));
END $$;

-- ── V433. The PAYDirect door: every call counted by its address; kept to its list only once an address is listed and one of
--          them has been seen at the door, the last listed address never removed while kept; the silence watch judges by the
--          door's own rhythm (never less than the set hours), says nothing of a door with too few calls to judge by, tells the
--          Directorate of ICT and the Bursary once per silence, and falls quiet again when a call arrives ──
DO $$
DECLARE who uuid := gen_random_uuid(); b uuid := gen_random_uuid();
        adm_open boolean; r_none text; r_unseen text; r_on boolean; adm_out boolean; adm_in boolean; seen_n int; seen_refused bigint;
        removed int; r_last text; r_bad text;
        st_quiet text; told_quiet int; st_state text; st_n14 bigint; st_gap numeric; st_thr numeric; told int; again int;
        told_b int; told_b_email int; subj text; st_after text; told_after int;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'ict', true); PERFORM set_config('moaum.reason', 'CHECK V433', true);
        INSERT INTO iam.person (id, staff_number, surname, given_names, email) VALUES
            (who, 'CHK/V433', 'CHECKV433', 'ICT', 'v433ict@example.test'),
            (b, 'CHK/V433B', 'CHECKV433', 'Bursar', 'v433b@example.test');
        INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from) VALUES
            (gen_random_uuid(), who, 'ict', 'institution', NULL, 'CHECK V433', who, current_date),
            (gen_random_uuid(), b, 'bursar', 'institution', NULL, 'CHECK V433', who, current_date);
        -- 1. the door: open, every call counted; kept to the list only with care
        UPDATE finance.paydirect_setting SET restrict_addresses = false, watch_enabled = true, silence_hours = 6, last_alert_seen_at = NULL WHERE id;
        DELETE FROM finance.paydirect_allowed_address;
        adm_open := finance.paydirect_door_admit('41.223.145.174', 'validate');
        BEGIN PERFORM finance.set_paydirect_door(true, NULL, NULL); EXCEPTION WHEN check_violation THEN r_none := SQLERRM; END;
        PERFORM finance.add_paydirect_address('154.72.34.174', 'Interswitch live');
        BEGIN PERFORM finance.set_paydirect_door(true, NULL, NULL); EXCEPTION WHEN check_violation THEN r_unseen := SQLERRM; END;
        PERFORM finance.add_paydirect_address('41.223.145.0/24', 'Interswitch live range');
        r_on := (SELECT x.restrict_addresses FROM finance.set_paydirect_door(true, NULL, NULL) x);
        adm_out := finance.paydirect_door_admit('203.0.113.9', 'message');
        adm_in := finance.paydirect_door_admit('41.223.145.174', 'notify');
        SELECT count(*), sum(s.refused) FILTER (WHERE s.address = '203.0.113.9') INTO seen_n, seen_refused
          FROM finance.paydirect_addresses_seen(7) s WHERE s.address IN ('41.223.145.174', '203.0.113.9');
        removed := finance.remove_paydirect_address('154.72.34.174');
        BEGIN PERFORM finance.remove_paydirect_address('41.223.145.0/24'); EXCEPTION WHEN check_violation THEN r_last := SQLERRM; END;
        BEGIN PERFORM finance.add_paydirect_address('not an address', NULL); EXCEPTION WHEN check_violation THEN r_bad := SQLERRM; END;
        -- 2. the watch: anything newer on the log moved out of the way (undone with the rest); one call ten hours ago is quiet with no rhythm to judge by
        UPDATE finance.gateway_event SET received_at = received_at - interval '60 days' WHERE gateway = 'paydirect' AND received_at > now() - interval '10 hours';
        INSERT INTO finance.gateway_event (gateway, source, event, reference, signature_ok, outcome, received_at)
        VALUES ('paydirect', 'VALIDATE', 'validate', 'CHK-V433-0', true, 'IGNORED', now() - interval '10 hours');
        st_quiet := (SELECT x.state FROM finance.paydirect_door_status() x);
        told_quiet := finance.watch_paydirect();
        -- twenty-four more, two hours apart before it: a rhythm of two hours; ten hours of silence is reported, once, to both offices
        INSERT INTO finance.gateway_event (gateway, source, event, reference, signature_ok, outcome, received_at)
        SELECT 'paydirect', CASE WHEN i % 2 = 0 THEN 'VALIDATE' ELSE 'WEBHOOK' END, 'validate', 'CHK-V433-' || i, true, 'IGNORED',
               now() - interval '10 hours' - make_interval(hours => 2 * i)
          FROM generate_series(1, 24) i;
        SELECT x.state, x.calls_14d, x.longest_gap_hours, x.threshold_hours INTO st_state, st_n14, st_gap, st_thr FROM finance.paydirect_door_status() x;
        told := finance.watch_paydirect();
        again := finance.watch_paydirect();
        SELECT count(*), count(*) FILTER (WHERE n.channel = 'EMAIL') INTO told_b, told_b_email FROM platform.notice n WHERE n.about_id = b AND n.template_key = 'PAYDIRECT_SILENT';
        subj := (SELECT n.subject FROM platform.notice n WHERE n.about_id = b AND n.template_key = 'PAYDIRECT_SILENT' AND n.channel = 'EMAIL');
        -- a call arrives: within its rhythm again, nothing more said
        INSERT INTO finance.gateway_event (gateway, source, event, reference, signature_ok, outcome) VALUES ('paydirect', 'WEBHOOK', 'notification', 'CHK-V433-NOW', true, 'IGNORED');
        st_after := (SELECT x.state FROM finance.paydirect_door_status() x);
        told_after := finance.watch_paydirect();
        RAISE EXCEPTION 'the V433 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V433: the PAYDirect door counts every caller, is kept to its list only once a listed address has been seen, keeps its last listed address while kept, and refuses what is not an address; the watch judges by the door''s own rhythm, says nothing of too few calls, tells ICT and the Bursary once per silence, and falls quiet when a call arrives',
        coalesce(adm_open AND r_none LIKE 'PAYDIRECT_NO_ADDRESS%' AND r_unseen LIKE 'PAYDIRECT_ADDRESS_UNSEEN%' AND r_on
                 AND NOT adm_out AND adm_in AND seen_n = 2 AND seen_refused = 1
                 AND removed = 1 AND r_last LIKE 'PAYDIRECT_LAST_ADDRESS%' AND r_bad LIKE 'PAYDIRECT_ADDRESS_INVALID%'
                 AND st_quiet = 'QUIET' AND told_quiet = 0
                 AND st_state = 'SILENT' AND st_n14 = 25 AND st_gap = 2.0 AND st_thr = 6.0
                 AND told >= 4 AND again = 0 AND told_b = 2 AND told_b_email = 1 AND subj = 'The Quickteller payment door has gone quiet'
                 AND st_after = 'OK' AND told_after = 0, false),
        format('door open=%s none=%s unseen=%s on=%s out=%s in=%s seen=%s refused=%s removed=%s last=%s bad=%s | quiet=%s told=%s | state=%s n14=%s gap=%s thr=%s told=%s again=%s b=%s (email %s) subject=%s | after=%s told=%s',
               adm_open, left(r_none, 24), left(r_unseen, 28), r_on, adm_out, adm_in, seen_n, seen_refused, removed, left(r_last, 24), left(r_bad, 28),
               st_quiet, told_quiet, st_state, st_n14, st_gap, st_thr, told, again, told_b, told_b_email, subj, st_after, told_after));
END $$;
-- ── V434. One biodata compliance screen: the students behind a count are listed by the item they miss and by sex as well,
--          the V426 form still answering; what is missing and the counts by faculty are read from the same reading ──
DO $$
DECLARE S text := '9979/9980'; who uuid := gen_random_uuid(); a uuid := gen_random_uuid(); b uuid := gen_random_uuid();
        fac text; by_missing text; by_sex text; old_form int; kin0 int; kin1 int; unit0 int; unit1 int;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'ict', true); PERFORM set_config('moaum.reason', 'CHECK V434', true);
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (who, 'CHK/V434', 'CHECKV434', 'ICT');
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9979-10-01', date '9980-08-31') ON CONFLICT (name) DO NOTHING;
        SELECT faculty_code INTO fac FROM ref.programme WHERE code = 'C00023';
        SELECT coalesce((SELECT students FROM people.biodata_missing_items(NULL, NULL) WHERE item = 'kin_mobile'), 0) INTO kin0;
        SELECT coalesce((SELECT total FROM people.biodata_compliance_units(NULL, NULL) WHERE code = fac), 0) INTO unit0;
        INSERT INTO people.student (id, admission_no, surname, other_names, sex, programme_code, entry_mode, entry_session, entry_level, current_level, status, study_mode)
        VALUES (a, 'MOAUM/ADM/79/009434', 'CHECKV434', 'Held', 'F', 'C00023', 'UTME', S, 100, 100, 'ADMITTED', 'FULL_TIME'),
               (b, 'MOAUM/ADM/79/009435', 'CHECKV434', 'Complete', 'M', 'C00023', 'UTME', S, 100, 100, 'ADMITTED', 'FULL_TIME');
        INSERT INTO people.student_contact (student_id, phone, email) VALUES (a, '08000000434', 'v434a@example.test'), (b, '08000000435', 'v434b@example.test');
        INSERT INTO people.student_photo (student_id, content, content_type, bytes, reason) VALUES (a, decode('ffd8ffd9', 'hex'), 'image/jpeg', 4, 'CHECK V434'),
                                                                                                (b, decode('ffd8ffd9', 'hex'), 'image/jpeg', 4, 'CHECK V434');
        INSERT INTO people.biodata (student_id, field, value)
        SELECT st.id, f.field, f.value FROM (VALUES (a), (b)) st(id)
         CROSS JOIN (VALUES ('nationality', 'Nigeria'), ('home_address', 'CHECK house, Makurdi'), ('state_of_origin', 'Benue'), ('lga', 'Makurdi'),
                            ('kin_name', 'CHECK Kin'), ('kin_relationship', 'Mother')) f(field, value);
        INSERT INTO people.biodata (student_id, field, value) VALUES (b, 'kin_mobile', '08000000436');
        PERFORM people.refresh_biodata_snapshot(ARRAY[a, b]);
        SELECT string_agg(other_names, ',' ORDER BY other_names) INTO by_missing
          FROM people.biodata_status_list(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'CHECKV434', 50, 0, 'kin_mobile', NULL);
        SELECT string_agg(other_names, ',' ORDER BY other_names) INTO by_sex
          FROM people.biodata_status_list(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'CHECKV434', 50, 0, NULL, 'M');
        SELECT count(*) INTO old_form FROM people.biodata_status_list(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'CHECKV434', 50, 0);
        SELECT coalesce((SELECT students FROM people.biodata_missing_items(NULL, NULL) WHERE item = 'kin_mobile'), 0) INTO kin1;
        SELECT coalesce((SELECT total FROM people.biodata_compliance_units(NULL, NULL) WHERE code = fac), 0) INTO unit1;
        RAISE EXCEPTION 'the V434 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V434: the students behind a count are listed by the item they miss and by sex, the V426 form still answering; what is missing and the counts by faculty come from the same reading',
        coalesce(by_missing = 'Held' AND by_sex = 'Complete' AND old_form = 2 AND kin1 - kin0 = 1 AND unit1 - unit0 = 2, false),
        format('missing=%s sex=%s old=%s kin %s->%s unit %s->%s', by_missing, by_sex, old_form, kin0, kin1, unit0, unit1));
END $$;

-- ── V436. The outbox paused, switched and cleared: a portal notice is not made while the portal switch is off; e-mail and SMS are
--          still generated while their delivery is off; the pending queue is cleared only while processing is paused, on e-mail,
--          SMS or both, with a reason — what waits is cancelled, never deleted, with when, by whom and why; the sent and failed
--          history stays as it was; the clearance is written with its counts; a job cancelled never runs again ──
DO $$
DECLARE who uuid := gen_random_uuid(); e1 uuid; e2 uuid; s1 uuid; f1 uuid; p_off uuid; p_on uuid; d record;
        r_dispatching text; r_channel text; r_reason text; c1 platform.notice_clearance; c2 platform.notice_clearance;
        n_email_q int; n_sms_q int; n_cancel int; n_failed int; reason_kept text; by_kept uuid;
        job uuid; j_open int; j_kind text; r_again text; j_state text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'ict', true); PERFORM set_config('moaum.reason', 'CHECK V436', true);
        INSERT INTO iam.person (id, staff_number, surname, given_names, email) VALUES (who, 'CHK/V436', 'CHECKV436', 'ICT', 'v434@example.test');
        -- 1. the switches: the portal switch keeps a portal notice from being made; e-mail and SMS are generated and held while their delivery is off
        PERFORM platform.set_delivery(NULL, false, false, false, who, 'ict');
        p_off := platform.queue_notice('PORTAL', NULL, 'CHK V436 portal', 'body', 'person', who, 'chk-v434:portal-off', NULL, NULL);
        e1 := platform.queue_notice('EMAIL', 'v434-a@example.test', 'CHK V436 e-mail 1', 'body', 'test', NULL);
        e2 := platform.queue_notice('EMAIL', 'v434-b@example.test', 'CHK V436 e-mail 2', 'body', 'test', NULL);
        s1 := platform.queue_notice('SMS', '08000004340', 'CHK V436 sms', 'body', 'test', NULL);
        f1 := platform.queue_notice('EMAIL', 'not an address', 'CHK V436 failed', 'body', 'test', NULL);
        PERFORM platform.set_delivery(NULL, true, true, true, who, 'ict');
        p_on := platform.queue_notice('PORTAL', NULL, 'CHK V436 portal', 'body', 'person', who, 'chk-v434:portal-on', NULL, NULL);
        SELECT * INTO d FROM platform.delivery();
        -- 2. the clearance: refused while processing runs, for the portal, without a reason; e-mail cleared first and SMS left waiting; then the rest
        BEGIN PERFORM platform.clear_notice_queue(ARRAY['EMAIL'], 'CHECK', who, 'ict'); EXCEPTION WHEN check_violation THEN r_dispatching := SQLERRM; END;
        PERFORM platform.set_delivery(false, NULL, NULL, NULL, who, 'ict');
        BEGIN PERFORM platform.clear_notice_queue(ARRAY['PORTAL'], 'CHECK', who, 'ict'); EXCEPTION WHEN check_violation THEN r_channel := SQLERRM; END;
        BEGIN PERFORM platform.clear_notice_queue(ARRAY['EMAIL'], '  ', who, 'ict'); EXCEPTION WHEN check_violation THEN r_reason := SQLERRM; END;
        c1 := platform.clear_notice_queue(ARRAY['email'], 'Pending queue cancelled during portal testing', who, 'ict');
        SELECT count(*) FILTER (WHERE n.state = 'QUEUED' AND n.channel = 'EMAIL'), count(*) FILTER (WHERE n.state = 'QUEUED' AND n.channel = 'SMS'),
               count(*) FILTER (WHERE n.state = 'CANCELLED')
          INTO n_email_q, n_sms_q, n_cancel FROM platform.notice n WHERE n.id IN (e1, e2, s1);
        SELECT n.cancel_reason, n.cancelled_by INTO reason_kept, by_kept FROM platform.notice n WHERE n.id = e1;
        n_failed := (SELECT count(*) FROM platform.notice n WHERE n.id = f1 AND n.state = 'FAILED');
        c2 := platform.clear_notice_queue(ARRAY['EMAIL', 'SMS'], 'The rest', who, 'ict');
        -- 3. a job cancelled never runs again
        INSERT INTO platform.notice_job (kind, payload, created_by, created_office)
        VALUES ('WINDOW', '{"type":"COURSE_REGISTRATION","action":"OPENED","session":"2099/2100"}', who, 'ict') RETURNING id INTO job;
        j_open := (SELECT count(*) FROM platform.open_notice_jobs() x WHERE x.id = job);
        j_kind := platform.cancel_notice_job(job, 'CHECK', who, 'ict');
        BEGIN PERFORM platform.cancel_notice_job(job, 'CHECK', who, 'ict'); EXCEPTION WHEN check_violation THEN r_again := SQLERRM; END;
        PERFORM platform.run_notice_job(NULL);
        j_state := (SELECT x.state FROM platform.notice_job x WHERE x.id = job);
        RAISE EXCEPTION 'the V436 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V436: the portal switch keeps a portal notice from being made while e-mail and SMS are generated and held; the pending queue is cleared only while processing is paused, by channel, with a reason — cancelled, never deleted, with who and why, the failed history untouched, the clearance written with its counts; a job cancelled never runs again',
        coalesce(p_off IS NULL AND p_on IS NOT NULL AND e1 IS NOT NULL AND e2 IS NOT NULL AND s1 IS NOT NULL AND f1 IS NOT NULL AND d.dispatch_enabled
                 AND r_dispatching LIKE 'NOTICE_CLEAR_DISPATCHING%' AND r_channel LIKE 'NOTICE_CLEAR_CHANNEL%' AND r_reason LIKE 'NOTICE_CLEAR_REASON%'
                 AND c1.channels = ARRAY['EMAIL'] AND c1.email_pending_before >= 2 AND c1.sms_pending_before >= 1 AND c1.email_cancelled >= 2 AND c1.sms_cancelled = 0
                 AND c1.email_remaining = 0 AND c1.sms_remaining >= 1
                 AND n_email_q = 0 AND n_sms_q = 1 AND n_cancel = 2 AND reason_kept = 'Pending queue cancelled during portal testing' AND by_kept = who AND n_failed = 1
                 AND c2.email_cancelled = 0 AND c2.sms_cancelled >= 1 AND c2.sms_remaining = 0
                 AND j_open = 1 AND j_kind = 'WINDOW' AND r_again LIKE 'NOTICE_JOB_FINISHED%' AND j_state = 'CANCELLED', false),
        format('portal off=%s on=%s | dispatch on=%s | refused dispatching=%s channel=%s reason=%s | c1 channels=%s before e=%s s=%s cancelled e=%s s=%s remaining e=%s s=%s | rows email q=%s sms q=%s cancelled=%s reason=%s by ok=%s failed kept=%s | c2 e=%s s=%s remaining s=%s | job open=%s kind=%s again=%s state=%s',
               p_off IS NULL, p_on IS NOT NULL, d.dispatch_enabled, left(r_dispatching, 26), left(r_channel, 20), left(r_reason, 19),
               c1.channels, c1.email_pending_before, c1.sms_pending_before, c1.email_cancelled, c1.sms_cancelled, c1.email_remaining, c1.sms_remaining,
               n_email_q, n_sms_q, n_cancel, reason_kept, by_kept = who, n_failed, c2.email_cancelled, c2.sms_cancelled, c2.sms_remaining,
               j_open, j_kind, left(r_again, 19), j_state));
END $$;
-- ── V437. The idle session timeout: the policy is ON by default at 120 seconds with a 30-second warning; set only by the
--          Directorate of ICT or an administrator, a timeout under 30 seconds, over eight hours, or a warning not shorter
--          than it refused; an office without a scope of its own is held to GLOBAL; a session left alone is ended for
--          inactivity with the reason and the sign-in record told, once; the monitor counts the open sessions active or
--          idle and today's ends ──
DO $$
DECLARE who uuid := gen_random_uuid(); p1 uuid := gen_random_uuid(); s_old bytea := gen_random_bytes(32); s_new bytea := gen_random_bytes(32);
        d_enabled boolean; d_idle int; d_warn int; fb int;
        r_office text := 'accepted'; r_min text := 'accepted'; r_max text := 'accepted'; r_warn text := 'accepted';
        set_idle int; set_by text; ended_once boolean; ended_twice boolean; reason text; ev int; m record; listed text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'ict', true); PERFORM set_config('moaum.reason', 'CHECK V437', true);
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (who, 'CHK/V437', 'CHECKV437', 'ICT');
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (p1, 'CHK/V437B', 'CHECKV437', 'Idle');
        SELECT idle_enabled, idle_seconds, warning_seconds INTO d_enabled, d_idle, d_warn FROM platform.session_policy WHERE scope = 'GLOBAL';
        SELECT idle_seconds INTO fb FROM platform.session_policy_for('bursar');
        BEGIN PERFORM platform.set_session_policy(true, 300, 30, true, 'CHECK', who, 'bursar'); EXCEPTION WHEN check_violation THEN r_office := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM platform.set_session_policy(true, 20, 5, true, 'CHECK', who, 'ict'); EXCEPTION WHEN check_violation THEN r_min := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM platform.set_session_policy(true, 90000, 30, true, 'CHECK', who, 'ict'); EXCEPTION WHEN check_violation THEN r_max := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM platform.set_session_policy(true, 120, 120, true, 'CHECK', who, 'ict'); EXCEPTION WHEN check_violation THEN r_warn := split_part(SQLERRM, ':', 1); END;
        PERFORM platform.set_session_policy(true, 300, 60, true, 'CHECK: testing', who, 'ict');
        SELECT idle_seconds, updated_office INTO set_idle, set_by FROM platform.session_policy WHERE scope = 'GLOBAL';
        -- a session left alone, ended once with the reason; one seen just now, active
        INSERT INTO platform.session (id, person_id, active_office, absolute_end, last_seen_at)
        VALUES (s_old, p1, 'registrar', now() + interval '12 hours', now() - interval '20 minutes'),
               (s_new, p1, 'registrar', now() + interval '12 hours', now());
        SELECT m0.open_sessions, m0.active, m0.idle INTO m FROM platform.session_monitor() m0;
        SELECT string_agg(status, ',' ORDER BY status) INTO listed FROM platform.open_sessions(1000) WHERE person_id = p1;
        ended_once := platform.session_expire_idle(s_old);
        ended_twice := platform.session_expire_idle(s_old);
        SELECT ended_reason INTO reason FROM platform.session WHERE id = s_old;
        SELECT count(*) INTO ev FROM iam.sign_in_event WHERE session_id = s_old AND outcome = 'EXPIRED_IDLE' AND person_id = p1;
        RAISE EXCEPTION 'the V437 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V437: the idle timeout is ON at 120 s with a 30 s warning by default, GLOBAL for every office, set only by ICT or an administrator within its limits (30 s to 8 h, the warning shorter); an idle session is ended once with the reason and the sign-in record told; the monitor counts active and idle sessions',
        coalesce(d_enabled AND d_idle = 120 AND d_warn = 30 AND fb = 120
                 AND r_office = 'SESSION_POLICY_OFFICE' AND r_min = 'SESSION_POLICY_IDLE_MIN' AND r_max = 'SESSION_POLICY_IDLE_MAX' AND r_warn = 'SESSION_POLICY_WARNING'
                 AND set_idle = 300 AND set_by = 'ict'
                 AND m.open_sessions >= 2 AND m.active >= 1 AND m.idle >= 1 AND listed = 'ACTIVE,IDLE'
                 AND ended_once AND NOT ended_twice AND reason = 'expired: idle' AND ev = 1, false),
        format('default %s/%s/%s fallback=%s office=%s min=%s max=%s warn=%s set=%s/%s monitor=%s/%s/%s listed=%s ended=%s/%s reason=%s events=%s',
               d_enabled, d_idle, d_warn, fb, r_office, r_min, r_max, r_warn, set_idle, set_by, m.open_sessions, m.active, m.idle, listed, ended_once, ended_twice, reason, ev));
END $$;

-- ── V438. Reminders before a window closes: three days and one day before a registration window closes, the students of the
--          session without a submitted registration are reminded through WINDOW_CLOSING, once per deadline and day, a registered
--          student never, a student with no fees stated never for fees; the pass queues nothing twice and nothing while switched
--          off. Delivery receipts: a provider's word lands on the SENT message it names as DELIVERED or BOUNCED, a report on a
--          cancelled message or on nothing is only logged, a word that says nothing is ignored, the door's token is checked ──
DO $$
DECLARE who uuid := gen_random_uuid(); a uuid := gen_random_uuid(); b uuid := gen_random_uuid(); S text := '9988/9989';
        w uuid; v_closes timestamptz; q1 int; q2 int; q3 int; q_off int; told_a3 int; told_b3 int; told_a1 int; told_b1 int; subj3 text; sms1 text;
        done_a boolean; done_b boolean; done_fees boolean;
        e1 uuid; c1 uuid; r1 text; r2 text; r3 text; r4 text; r5 text; st1 text; ds1 text; dd1 text; st_c text; ds_c text; tok text; ok_t boolean; ok_f boolean; n_log int;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'ict', true); PERFORM set_config('moaum.reason', 'CHECK V438', true);
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (who, 'CHK/V438', 'CHECKV438', 'ICT');
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9988-10-01', date '9989-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO people.student (id, admission_no, matric_no, matriculated_at, surname, other_names, sex, programme_code, entry_mode, entry_session, entry_level, current_level, status, study_mode)
        VALUES (a, 'MOAUM/ADM/88/009438', NULL, NULL, 'CHECKV438', 'Closing Ada', 'F', 'C00023', 'UTME', S, 100, 100, 'ADMITTED', 'FULL_TIME'),
               (b, 'MOAUM/ADM/88/009439', NULL, NULL, 'CHECKV438', 'Closing Bola', 'M', 'C00023', 'UTME', S, 100, 100, 'ADMITTED', 'FULL_TIME');
        INSERT INTO people.student_contact (student_id, phone, email) VALUES (a, '08000004381', 'v438a@example.test'), (b, '08000004382', 'v438b@example.test');
        -- B has submitted; the window closes at noon, Lagos, three days from today
        INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, submitted_at) VALUES (gen_random_uuid(), b, S, 1, 100, 'SUBMITTED', now());
        v_closes := (((now() AT TIME ZONE 'Africa/Lagos')::date + 3)::timestamp + interval '12 hours') AT TIME ZONE 'Africa/Lagos';
        INSERT INTO policy.portal_window (window_type, session, semester, opens_at, closes_at, created_office) VALUES ('COURSE_REGISTRATION', S, 1, now() - interval '1 day', v_closes, 'ict') RETURNING id INTO w;
        done_a := policy.window_done('COURSE_REGISTRATION', S, 1, a);
        done_b := policy.window_done('COURSE_REGISTRATION', S, 1, b);
        done_fees := policy.window_done('SCHOOL_FEES_PAYMENT', S, NULL, a);
        UPDATE platform.notice_setting SET closing_reminders = true WHERE id;
        PERFORM platform.set_portal_url('https://portal.example.test', who, 'ict');
        -- 1. three days before: A reminded on every channel, B not; the same day again queues nothing
        q1 := platform.queue_closing_reminders(now());
        FOR i IN 1..5 LOOP PERFORM platform.run_notice_job(100000); END LOOP;
        SELECT count(*) INTO told_a3 FROM platform.notice n WHERE n.about_id = a AND n.template_key LIKE 'WINDOW_CLOSING%' AND n.event_key = 'window-closing:' || w || ':' || to_char(v_closes AT TIME ZONE 'Africa/Lagos', 'YYYY-MM-DD') || ':3';
        SELECT count(*) INTO told_b3 FROM platform.notice n WHERE n.about_id = b AND n.template_key LIKE 'WINDOW_CLOSING%';
        subj3 := (SELECT n.subject FROM platform.notice n WHERE n.about_id = a AND n.template_key LIKE 'WINDOW_CLOSING%' AND n.channel = 'EMAIL' AND n.event_key LIKE '%:3');
        q2 := platform.queue_closing_reminders(now());
        -- 2. the day before: A again under a new key, B still not
        q3 := platform.queue_closing_reminders(v_closes - interval '1 day');
        FOR i IN 1..5 LOOP PERFORM platform.run_notice_job(100000); END LOOP;
        SELECT count(*) INTO told_a1 FROM platform.notice n WHERE n.about_id = a AND n.template_key LIKE 'WINDOW_CLOSING%' AND n.event_key LIKE 'window-closing:' || w || ':%:1';
        SELECT count(*) INTO told_b1 FROM platform.notice n WHERE n.about_id = b AND n.template_key LIKE 'WINDOW_CLOSING%';
        sms1 := (SELECT n.body FROM platform.notice n WHERE n.about_id = a AND n.template_key LIKE 'WINDOW_CLOSING%' AND n.channel = 'SMS' AND n.event_key LIKE '%:1');
        -- 3. switched off: nothing queued
        UPDATE platform.notice_setting SET closing_reminders = false WHERE id;
        q_off := platform.queue_closing_reminders(v_closes - interval '1 day');
        -- 4. receipts: the token; a provider's word on a sent message; on a cancelled one; on nothing; a word that says nothing
        tok := platform.new_receipt_token(who, 'ict');
        ok_t := platform.receipt_token_ok(tok); ok_f := platform.receipt_token_ok('wrong');
        e1 := platform.queue_notice('EMAIL', 'v438-r@example.test', 'CHK V438 receipt', 'body', 'test', NULL);
        c1 := platform.queue_notice('EMAIL', 'v438-c@example.test', 'CHK V438 cancelled', 'body', 'test', NULL);
        UPDATE platform.notice SET state = 'SENT', sent_at = now(), provider_id = 'rs-chk-438' WHERE id = e1;
        UPDATE platform.notice SET state = 'CANCELLED', cancelled_at = now(), cancel_reason = 'CHECK' WHERE id = c1;
        r1 := (SELECT x.outcome FROM platform.record_receipt('resend', 'rs-chk-438', 'email.delivered', NULL, '{"type":"email.delivered"}'::jsonb) x);
        r2 := (SELECT x.outcome FROM platform.record_receipt('resend', 'rs-chk-438', 'email.bounced', 'mailbox full', '{"type":"email.bounced"}'::jsonb) x);
        SELECT n.state, n.delivery_state, n.delivery_detail INTO st1, ds1, dd1 FROM platform.notice n WHERE n.id = e1;
        r3 := (SELECT x.outcome FROM platform.record_receipt('ebulksms', c1::text, 'DELIVRD', NULL, '{}'::jsonb) x);
        SELECT n.state, n.delivery_state INTO st_c, ds_c FROM platform.notice n WHERE n.id = c1;
        r4 := (SELECT x.outcome FROM platform.record_receipt('generic', 'nothing-438', 'delivered', NULL, '{}'::jsonb) x);
        r5 := (SELECT x.outcome FROM platform.record_receipt('generic', 'rs-chk-438', 'queued', NULL, '{}'::jsonb) x);
        n_log := (SELECT count(*) FROM platform.notice_receipt r WHERE r.provider_id IN ('rs-chk-438', c1::text, 'nothing-438'));
        RAISE EXCEPTION 'the V438 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V438: the students not yet registered are reminded three days and one day before the window closes, once per deadline and day, on every channel; a registered student never; nothing to pay is nothing to be reminded of; the pass queues nothing twice and nothing while off; a provider''s word lands on the sent message as DELIVERED or BOUNCED and never touches a cancelled one; a report on nothing or saying nothing is only logged; the door''s token is checked',
        coalesce(NOT done_a AND done_b AND done_fees
                 AND q1 >= 1 AND told_a3 = 3 AND told_b3 = 0 AND subj3 LIKE '%closes in 3 days%' AND q2 = 0
                 AND q3 >= 1 AND told_a1 = 3 AND told_b1 = 0 AND sms1 LIKE '%closes tomorrow%' AND q_off = 0
                 AND length(tok) = 64 AND ok_t AND NOT ok_f
                 AND r1 = 'DELIVERED' AND r2 = 'BOUNCED' AND st1 = 'SENT' AND ds1 = 'BOUNCED' AND dd1 = 'mailbox full'
                 AND r3 = 'NOT_SENT' AND st_c = 'CANCELLED' AND ds_c IS NULL AND r4 = 'UNMATCHED' AND r5 = 'IGNORED' AND n_log = 5, false),
        format('done a=%s b=%s fees=%s | q1=%s told a=%s b=%s subject=%s q2=%s | q3=%s told a=%s b=%s sms=%s | off=%s | token len=%s ok=%s wrong=%s | r=%s/%s state=%s ds=%s detail=%s | cancelled r=%s state=%s ds=%s | unmatched=%s ignored=%s logged=%s',
               done_a, done_b, done_fees, q1, told_a3, told_b3, subj3, q2, q3, told_a1, told_b1, left(sms1, 60), q_off, length(tok), ok_t, ok_f,
               r1, r2, st1, ds1, dd1, r3, st_c, ds_c, r4, r5, n_log));
END $$;
-- ── V431: the Registry resolves a duplicate student ──
-- Invented records for a session of their own. K and E share a JAMB number; a candidate stands behind E. Keeping K ends E: E is
-- WITHDRAWN with no matriculation number, points at K, carries the change of status on the kept number's instrument, and K takes the
-- candidate; the pair leaves the duplicates list and E is not flagged as missing its matriculation number. A pair whose record to end
-- carries a registration is refused (DUPLICATE_HAS_HISTORY); two records sharing nothing are refused (DUPLICATE_NOT_A_PAIR); E cannot
-- be ended twice (DUPLICATE_ALREADY_ENDED). The block undoes its writes.
DO $$
DECLARE who uuid := gen_random_uuid(); S text := '9943/9944'; prog text;
        k uuid := gen_random_uuid(); e uuid := gen_random_uuid(); h1 uuid := gen_random_uuid(); h2 uuid := gen_random_uuid(); ce uuid := gen_random_uuid();
        r jsonb; e_status text; e_dup uuid; k_cand uuid; e_cand uuid; instr text; listed int; flagged boolean;
        hist text; notpair text; twice text; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'registrar', true);
        PERFORM set_config('moaum.reason', 'check V431', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9943-10-01', date '9944-08-31') ON CONFLICT (name) DO NOTHING;
        SELECT code INTO prog FROM ref.programme WHERE code = 'C00061';
        INSERT INTO admissions.candidate (id, session, jamb_reg_no, surname, other_names, programme, entry_mode, entry_level, offer_state)
        VALUES (ce, S, '994300000001ZK', 'ZZDUPLICATE', 'Kept Person', (SELECT name FROM ref.programme WHERE code = prog), 'UTME', 100, 'PROPOSED');
        INSERT INTO people.student (id, admission_no, jamb_reg_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, candidate_id)
        VALUES (k, 'MOAUM/ADM/43/994311', '994300000001ZK', 'ZZDUPLICATE', 'Kept Person', prog, 'UTME', S, 100, 100, 'ADMITTED', NULL),
               (e, 'MOAUM/ADM/43/994312', '994300000001ZK', 'ZZDUPLICATE', 'Kept Person', prog, 'UTME', S, 100, 100, 'ADMITTED', ce),
               (h1, 'MOAUM/ADM/43/994313', '994300000002ZH', 'ZZDUPLICATE', 'History Person', prog, 'UTME', S, 100, 100, 'ADMITTED', NULL),
               (h2, 'MOAUM/ADM/43/994314', '994300000002ZH', 'ZZDUPLICATE', 'History Person', prog, 'UTME', S, 100, 100, 'ADMITTED', NULL);
        INSERT INTO people.enrolment (id, student_id, session, level) VALUES (gen_random_uuid(), h2, S, 100);
        INSERT INTO registration.course_registration (id, student_id, session, semester, level, status) VALUES (gen_random_uuid(), h2, S, 1, 100, 'DRAFT');

        r := people.resolve_duplicate(k, e, 'Same JAMB number; the candidate applied once');
        SELECT status, duplicate_of, candidate_id INTO e_status, e_dup, e_cand FROM people.student WHERE id = e;
        SELECT candidate_id INTO k_cand FROM people.student WHERE id = k;
        SELECT instrument INTO instr FROM people.status_change WHERE student_id = e AND to_status = 'WITHDRAWN';
        SELECT count(*) INTO listed FROM people.duplicate_students() d WHERE d.match_key = '994300000001ZK';
        SELECT 'MISSING_MATRIC' = ANY (p.issues) INTO flagged FROM people.academic_position_rows(e) p;
        BEGIN PERFORM people.resolve_duplicate(h1, h2, 'Same JAMB number, history on one'); hist := 'TAKEN';
        EXCEPTION WHEN check_violation THEN hist := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM people.resolve_duplicate(k, h1, 'Not the same person at all'); notpair := 'TAKEN';
        EXCEPTION WHEN check_violation THEN notpair := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM people.resolve_duplicate(k, e, 'Asked a second time on purpose'); twice := 'TAKEN';
        EXCEPTION WHEN check_violation THEN twice := split_part(SQLERRM, ':', 1); END;
        RAISE EXCEPTION 'the V431 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V431 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V431: keeping one record of a duplicate pair ends the other — withdrawn without a matriculation number, pointing at the kept record, the change recorded on the kept number, the candidate moved — and lists it no more; a record with a history, two records that are not a pair, and a second ending are refused',
        coalesce(e_status = 'WITHDRAWN' AND e_dup = k AND e_cand IS NULL AND k_cand = ce AND (r ->> 'candidateMoved')::boolean
                 AND instr LIKE '%MOAUM/ADM/43/994311' AND listed = 0 AND NOT flagged
                 AND hist = 'DUPLICATE_HAS_HISTORY' AND notpair = 'DUPLICATE_NOT_A_PAIR' AND twice = 'DUPLICATE_ALREADY_ENDED', false),
        format('E %s dup=%s cand=%s | K cand=%s | instr %s | listed %s | flagged %s | history %s | not a pair %s | twice %s',
               e_status, e_dup = k, e_cand, k_cand = ce, instr, listed, flagged, hist, notpair, twice));
END $$;
-- ── V432: the foreign-key indexes that measured worth it ──
-- Removing a file object finds its holders in admissions.attachment through an index, and a session's enrolments and registrations
-- are read through one: each of the three foreign keys timed on the live-shaped copy leads an index.
DO $$
DECLARE missing text;
BEGIN
    SELECT string_agg(t.tbl || '.' || t.col, ', ') INTO missing
      FROM (VALUES ('admissions.attachment', 'object_id'), ('people.enrolment', 'session'), ('registration.course_registration', 'session')) t(tbl, col)
     WHERE NOT EXISTS (SELECT 1 FROM pg_index i JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = i.indkey[0]
                        WHERE i.indrelid = t.tbl::regclass AND a.attname = t.col);
    PERFORM pg_temp.assert('V432: the foreign keys timed on the live-shaped copy — a file object''s attachments, a session''s enrolments and registrations — each lead an index',
        missing IS NULL, coalesce('no index leads ' || missing, 'all three indexed'));
END $$;
-- ── V435: a deferment letter is verified by the check code its QR carries ──
-- Every deferment carries a check code of eighteen hex digits, drawn at random (two deferments made one after the other carry two
-- codes), so the public page can refuse a reference given without its code. The block undoes its writes.
DO $$
DECLARE who uuid := gen_random_uuid(); st uuid := gen_random_uuid(); a text; b text; shaped boolean; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'registrar', true);
        PERFORM set_config('moaum.reason', 'check V435', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), '9935/9936', date '9935-10-01', date '9936-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), '9936/9937', date '9936-10-01', date '9937-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (st, 'MOAUM/ADM/35/993501', 'MOAUM/QRV/35/9935', 'ZZDEFERCODE', 'Invented', 'C00061', 'UTME', '9935/9936', 100, 100, 'ACTIVE', now());
        INSERT INTO people.deferment (reference, student_id, kind, session, reason_code, state)
        VALUES ('DEF-9935-00001', st, 'SESSION', '9935/9936', (SELECT code FROM people.deferment_reason ORDER BY code LIMIT 1), 'DRAFT') RETURNING verify_code INTO a;
        INSERT INTO people.deferment (reference, student_id, kind, session, reason_code, state)
        VALUES ('DEF-9935-00002', st, 'SESSION', '9936/9937', (SELECT code FROM people.deferment_reason ORDER BY code LIMIT 1), 'DRAFT') RETURNING verify_code INTO b;
        shaped := NOT EXISTS (SELECT 1 FROM people.deferment WHERE verify_code !~ '^[0-9a-f]{18}$');
        RAISE EXCEPTION 'the V435 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V435 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V435: every deferment carries a random check code of eighteen hex digits — two deferments, two codes — for its letter''s QR',
        coalesce(a ~ '^[0-9a-f]{18}$' AND b ~ '^[0-9a-f]{18}$' AND a <> b AND shaped, false), format('codes %s / %s, all shaped %s', a, b, shaped));
END $$;
-- ── V441. The Privacy Policy and its engine: version 1 is seeded as a DRAFT of 36 sections with eight review points; it is
--          drafted and published by ICT or an administrator only, and never while a review point is unconfirmed; publication
--          archives (keeps) the version before it; one draft at a time, edited or withdrawn, its sections checked; acceptance is
--          by the person's own act, once per version, asked again for a new version and never for an unchanged one; the privacy
--          contact is set with its period; a request filed through the portal lands on the governance log under its reference,
--          due in that period, five open at most; the register's CBT row says what the engine does ──
DO $$
DECLARE who uuid := gen_random_uuid(); stu uuid := gen_random_uuid(); d1 uuid; d2 uuid; d3 uuid; k text;
        seeded record; r_pending text := 'accepted'; r_office text := 'accepted'; r_second text := 'accepted'; r_bad text := 'accepted';
        r_contact text := 'accepted'; r_limit text := 'accepted'; r_unpub text := 'accepted';
        pub record; v2 record; wd text; need1 int; acc1 boolean; acc2 boolean; need2 int; summ record; need3 int; v1_after record;
        c record; ref1 text; req record; mine int; cbt text; cur record; i int;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'ict', true); PERFORM set_config('moaum.reason', 'CHECK V441', true);
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (who, 'CHK/V441', 'CHECKV441', 'ICT');
        SELECT id, version, status, jsonb_array_length(sections) AS n, jsonb_array_length(review_points) AS p, requires_acceptance AS req
          INTO seeded FROM platform.legal_document WHERE kind = 'PRIVACY_POLICY' ORDER BY version LIMIT 1;
        d1 := seeded.id;
        -- not yet: the review points stand; not by the Bursary at all
        BEGIN PERFORM platform.legal_document_publish(d1, current_date, who, 'ict'); EXCEPTION WHEN check_violation THEN r_pending := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM platform.legal_document_publish(d1, current_date, who, 'bursar'); EXCEPTION WHEN check_violation THEN r_office := split_part(SQLERRM, ':', 1); END;
        -- nothing to accept while nothing is published
        BEGIN PERFORM platform.policy_accept('STUDENT', stu, d1, '10.0.0.1', 'CHECK'); EXCEPTION WHEN check_violation THEN r_unpub := split_part(SQLERRM, ':', 1); END;
        FOR k IN SELECT p->>'key' FROM jsonb_array_elements((SELECT review_points FROM platform.legal_document WHERE id = d1)) p LOOP
            PERFORM platform.legal_review_confirm(d1, k, true, who, 'ict');
        END LOOP;
        SELECT status, effective_on, published_at IS NOT NULL AS published, version INTO pub FROM platform.legal_document_publish(d1, current_date, who, 'ict');
        SELECT version INTO cur FROM platform.legal_published('PRIVACY_POLICY');
        -- a second draft: version 2, its points unconfirmed again; a third draft refused while it is open; bad sections refused; withdrawn, kept
        SELECT id, version, status, (SELECT count(*) FROM jsonb_array_elements(review_points) p WHERE p->>'confirmed_at' IS NULL) AS unconfirmed
          INTO v2 FROM platform.legal_document_draft('PRIVACY_POLICY', who, 'ict');
        d2 := v2.id;
        BEGIN PERFORM platform.legal_document_draft('PRIVACY_POLICY', who, 'ict'); EXCEPTION WHEN check_violation THEN r_second := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM platform.legal_document_update(d2, 'Privacy Policy', NULL, '[{"heading": "x"}]'::jsonb, NULL, true, who, 'ict'); EXCEPTION WHEN check_violation THEN r_bad := split_part(SQLERRM, ':', 1); END;
        PERFORM platform.legal_document_update(d2, 'Privacy Policy', 'A summary', '[{"key": "a", "heading": "One", "body": "Body one."}]'::jsonb, NULL, true, who, 'ict');
        SELECT status INTO wd FROM platform.legal_document_withdraw(d2, who, 'ict');
        -- acceptance: asked once, recorded once, never again for the same version
        SELECT count(*) INTO need1 FROM platform.policy_acceptance_needed('STUDENT', stu);
        acc1 := platform.policy_accept('STUDENT', stu, d1, '10.0.0.1', 'CHECK browser');
        acc2 := platform.policy_accept('STUDENT', stu, d1, '10.0.0.1', 'CHECK browser');
        SELECT count(*) INTO need2 FROM platform.policy_acceptance_needed('STUDENT', stu);
        SELECT accepted INTO summ FROM platform.policy_acceptance_summary(d1) WHERE subject_kind = 'STUDENT';
        -- a new version published: the old one archived and kept, the student asked again
        SELECT id INTO d3 FROM platform.legal_document_draft('PRIVACY_POLICY', who, 'ict');
        FOR k IN SELECT p->>'key' FROM jsonb_array_elements((SELECT review_points FROM platform.legal_document WHERE id = d3)) p LOOP
            PERFORM platform.legal_review_confirm(d3, k, true, who, 'ict');
        END LOOP;
        PERFORM platform.legal_document_publish(d3, current_date + 7, who, 'ict');
        SELECT status, archive_note INTO v1_after FROM platform.legal_document WHERE id = d1;
        SELECT count(*) INTO need3 FROM platform.policy_acceptance_needed('STUDENT', stu);
        -- the privacy contact, by the right offices, with its period; a request filed by the person lands on the governance log
        BEGIN PERFORM platform.privacy_contact_set('A', 'B', 'C', 'dpo@example.edu', '080', 'D', 30, NULL, who, 'bursar'); EXCEPTION WHEN check_violation THEN r_contact := split_part(SQLERRM, ':', 1); END;
        SELECT dpo_email, request_days, updated_office INTO c FROM platform.privacy_contact_set('Dr Check', 'Data Protection Officer', 'Registry', 'DPO@Example.edu', '0800', 'Makurdi', 21, NULL, who, 'ict');
        ref1 := governance.dsr_file('COMPLAINT', 'STUDENT', stu, 'me@example.com', 'The record shows a wrong state of origin.');
        SELECT kind, due_on - received_on AS days, filed_via, subject_id, requester INTO req FROM governance.dsr WHERE reference = ref1;
        FOR i IN 1..4 LOOP PERFORM governance.dsr_file('ACCESS', 'STUDENT', stu, NULL, 'A copy of everything held about me, please.'); END LOOP;
        BEGIN PERFORM governance.dsr_file('INQUIRY', 'STUDENT', stu, NULL, 'One more question about my data.'); EXCEPTION WHEN check_violation THEN r_limit := split_part(SQLERRM, ':', 1); END;
        SELECT count(*) INTO mine FROM governance.dsr_mine('STUDENT', stu);
        SELECT activity INTO cbt FROM governance.processing_activity WHERE activity LIKE 'Camera presence signals at CBT%';
        RAISE EXCEPTION 'the V441 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V441: the Privacy Policy v1 is a seeded draft of 36 sections and 8 review points; published only by ICT/admin once every point is confirmed; one draft at a time, checked, withdrawable, kept; acceptance once per version by the person, asked again for a new version; the contact and its period set by the right offices; a request filed through the portal lands on the governance log under its reference, five open at most; the register''s CBT row says what the engine does',
        coalesce(seeded.version = 1 AND seeded.status = 'DRAFT' AND seeded.n = 36 AND seeded.p = 8 AND seeded.req
                 AND r_pending = 'LEGAL_REVIEW_PENDING' AND r_office = 'LEGAL_OFFICE' AND r_unpub = 'LEGAL_NOT_PUBLISHED'
                 AND pub.status = 'PUBLISHED' AND pub.published AND pub.effective_on = current_date AND cur.version = 1
                 AND v2.version = 2 AND v2.status = 'DRAFT' AND v2.unconfirmed = 8 AND r_second = 'LEGAL_DRAFT_EXISTS' AND r_bad = 'LEGAL_SECTIONS' AND wd = 'ARCHIVED'
                 AND need1 = 1 AND acc1 AND NOT acc2 AND need2 = 0 AND summ.accepted = 1
                 AND v1_after.status = 'ARCHIVED' AND v1_after.archive_note = 'replaced by version 3' AND need3 = 1
                 AND r_contact = 'PRIVACY_CONTACT_OFFICE' AND c.dpo_email = 'dpo@example.edu' AND c.request_days = 21 AND c.updated_office = 'ict'
                 AND ref1 LIKE 'DSR-%' AND req.kind = 'COMPLAINT' AND req.days = 21 AND req.filed_via = 'PORTAL' AND req.subject_id = stu AND req.requester LIKE 'Student %'
                 AND r_limit = 'DSR_OPEN_LIMIT' AND mine = 5 AND cbt IS NOT NULL, false),
        format('seed=%s/%s/%s/%s/%s pending=%s office=%s unpub=%s pub=%s/%s/%s cur=%s v2=%s/%s/%s second=%s bad=%s wd=%s need=%s/%s/%s acc=%s/%s summ=%s v1=%s/%s contact=%s/%s/%s/%s req=%s/%s/%s/%s/%s limit=%s mine=%s cbt=%s',
               seeded.version, seeded.status, seeded.n, seeded.p, seeded.req, r_pending, r_office, r_unpub, pub.status, pub.published, pub.effective_on, cur.version,
               v2.version, v2.status, v2.unconfirmed, r_second, r_bad, wd, need1, need2, need3, acc1, acc2, summ.accepted, v1_after.status, v1_after.archive_note,
               r_contact, c.dpo_email, c.request_days, c.updated_office, ref1, req.kind, req.days, req.filed_via, req.requester, r_limit, mine, cbt));
END $$;

-- ── V440. Applicant deadlines: before Post-UTME registration closes the applicants who have not submitted are reminded and the
--          submitted are not; before admission status checking closes the submitted-and-unchecked are reminded and the
--          never-submitted are not. A person's messages are read newest first; a failed message is sent again once to the
--          address the record holds now, never a queued one nor a portal notice. The manual carries the twelve new procedures,
--          published, and the edition has stepped ──
DO $$
DECLARE who uuid := gen_random_uuid(); S text := '9990/9991'; ca uuid := gen_random_uuid(); cb uuid := gen_random_uuid();
        acc_a uuid := gen_random_uuid(); acc_b uuid := gen_random_uuid(); app_a uuid := gen_random_uuid(); app_b uuid := gen_random_uuid();
        w_reg uuid; w_chk uuid; v_closes timestamptz; q1 int; q2 int;
        told_a int; told_b int; subj_a text; told_b_chk int; told_a_chk int; done_b boolean;
        st uuid := gen_random_uuid(); e_fail uuid; e_portal uuid; e_again uuid; e_queued uuid;
        r_state text; r_channel text; r_done text; again_state text; again_to text; again_from uuid; n_msgs int; n_resent int;
        n_manual int; ed_major int; ed_minor int;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'ict', true); PERFORM set_config('moaum.reason', 'CHECK V440', true);
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (who, 'CHK/V440', 'CHECKV440', 'ICT');
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9990-10-01', date '9991-08-31') ON CONFLICT (name) DO NOTHING;
        PERFORM platform.set_portal_url('https://portal.example.test', who, 'ict');
        UPDATE platform.notice_setting SET closing_reminders = true, portal_delivery = true, email_delivery = true, sms_delivery = true WHERE id;
        -- two applicants of the session with accounts: A started and never submitted, B submitted
        INSERT INTO admissions.candidate (id, session, jamb_reg_no, surname, other_names, programme, entry_mode, entry_level, offer_state) VALUES
            (ca, S, '9990000001AD', 'CHECKV440', 'Applicant Ada', (SELECT name FROM ref.programme WHERE code = 'C00061'), 'UTME', 100, 'PROPOSED'),
            (cb, S, '9990000002BD', 'CHECKV440', 'Applicant Bola', (SELECT name FROM ref.programme WHERE code = 'C00061'), 'UTME', 100, 'PROPOSED');
        INSERT INTO admissions.applicant_account (id, session, candidate_id, jamb_key, email, phone, password_hash) VALUES
            (acc_a, S, ca, '9990000001AD', 'v440a@example.test', '08000004401', 'SET_ON_FIRST_LOGIN'),
            (acc_b, S, cb, '9990000002BD', 'v440b@example.test', '08000004402', 'SET_ON_FIRST_LOGIN');
        INSERT INTO admissions.application (id, account_id, candidate_id, session, application_no, submitted_at) VALUES
            (app_a, acc_a, ca, S, 'APP/90/004401', NULL), (app_b, acc_b, cb, S, 'APP/90/004402', now());
        -- 1. Post-UTME registration closes in three days
        v_closes := (((now() AT TIME ZONE 'Africa/Lagos')::date + 3)::timestamp + interval '12 hours') AT TIME ZONE 'Africa/Lagos';
        INSERT INTO policy.portal_window (window_type, session, semester, opens_at, closes_at, created_office) VALUES ('POST_UTME_REGISTRATION', S, NULL, now() - interval '1 day', v_closes, 'ict') RETURNING id INTO w_reg;
        q1 := platform.queue_closing_reminders(now());
        FOR i IN 1..5 LOOP PERFORM platform.run_notice_job(100000); END LOOP;
        SELECT count(*) INTO told_a FROM platform.notice n WHERE n.about_kind = 'application' AND n.about_id = app_a AND n.template_key = 'WINDOW_CLOSING:POST_UTME_REGISTRATION' AND n.event_key LIKE 'window-closing:' || w_reg || ':%:3';
        SELECT count(*) INTO told_b FROM platform.notice n WHERE n.about_kind = 'application' AND n.about_id = app_b AND n.template_key = 'WINDOW_CLOSING:POST_UTME_REGISTRATION';
        subj_a := (SELECT n.subject FROM platform.notice n WHERE n.about_id = app_a AND n.template_key = 'WINDOW_CLOSING:POST_UTME_REGISTRATION' AND n.channel = 'EMAIL');
        -- 2. admission status checking closes tomorrow: B submitted and unchecked is reminded, A never submitted is not; once B checks, done
        v_closes := (((now() AT TIME ZONE 'Africa/Lagos')::date + 1)::timestamp + interval '12 hours') AT TIME ZONE 'Africa/Lagos';
        INSERT INTO policy.portal_window (window_type, session, semester, opens_at, closes_at, created_office) VALUES ('ADMISSION_STATUS_CHECKING', S, NULL, now() - interval '1 day', v_closes, 'ict') RETURNING id INTO w_chk;
        q2 := platform.queue_closing_reminders(now());
        FOR i IN 1..5 LOOP PERFORM platform.run_notice_job(100000); END LOOP;
        SELECT count(*) INTO told_b_chk FROM platform.notice n WHERE n.about_id = app_b AND n.template_key = 'WINDOW_CLOSING:ADMISSION_STATUS_CHECKING' AND n.event_key LIKE 'window-closing:' || w_chk || ':%:1';
        SELECT count(*) INTO told_a_chk FROM platform.notice n WHERE n.about_id = app_a AND n.template_key = 'WINDOW_CLOSING:ADMISSION_STATUS_CHECKING';
        INSERT INTO admissions.status_check (application_id, session, result) VALUES (app_b, S, 'NOT_YET');
        done_b := policy.applicant_window_done('ADMISSION_STATUS_CHECKING', S, app_b);
        -- 3. a student's messages, and one sent again to the address the record holds now
        INSERT INTO people.student (id, admission_no, matric_no, matriculated_at, surname, other_names, sex, programme_code, entry_mode, entry_session, entry_level, current_level, status, study_mode)
        VALUES (st, 'MOAUM/ADM/90/004403', NULL, NULL, 'CHECKV440', 'Message Ada', 'F', 'C00023', 'UTME', S, 100, 100, 'ADMITTED', 'FULL_TIME');
        e_fail := platform.queue_notice('EMAIL', 'not an address', 'CHK V440 failed', 'body', 'student', st);
        e_portal := platform.queue_notice('PORTAL', NULL, 'CHK V440 portal', 'body', 'student', st, 'chk-v440:portal', NULL, NULL);
        e_queued := platform.queue_notice('SMS', '08000004403', 'CHK V440 queued', 'body', 'student', st);
        BEGIN PERFORM platform.resend_notice(e_queued, who, 'ict'); EXCEPTION WHEN check_violation THEN r_state := SQLERRM; END;
        BEGIN PERFORM platform.resend_notice(e_portal, who, 'ict'); EXCEPTION WHEN check_violation THEN r_channel := SQLERRM; END;
        INSERT INTO people.student_contact (student_id, phone, email) VALUES (st, '08000004403', 'v440s@example.test');
        e_again := platform.resend_notice(e_fail, who, 'ict');
        SELECT n.state, n.recipient, n.resent_from INTO again_state, again_to, again_from FROM platform.notice n WHERE n.id = e_again;
        BEGIN PERFORM platform.resend_notice(e_fail, who, 'ict'); EXCEPTION WHEN check_violation THEN r_done := SQLERRM; END;
        SELECT count(*), count(*) FILTER (WHERE m.resent) INTO n_msgs, n_resent FROM platform.messages_for('student', st, 100) m;
        -- 4. the manual
        SELECT count(*) INTO n_manual FROM manual.procedure p WHERE p.state = 'PUBLISHED' AND p.seeded
           AND p.slug IN ('notify-templates-words', 'notify-templates-test', 'notify-settings-reminders', 'notify-campaign-send', 'notify-delivery-switches', 'notify-queue-clear',
                          'notify-receipts-door', 'biodata-compliance-read', 'biodata-staff-reach', 'quickteller-door-watch', 'quickteller-door-list', 'student-messages-resend');
        SELECT e.major, e.minor INTO ed_major, ed_minor FROM manual.edition e;
        RAISE EXCEPTION 'the V440 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V440: the applicants not yet submitted are reminded before registration closes and the submitted are not; the submitted-and-unchecked before status checking closes and the never-submitted not; a failed message is sent again once to the record''s address, never a queued one nor a portal notice; the manual carries the new procedures and the edition has stepped',
        coalesce(q1 >= 1 AND told_a = 3 AND told_b = 0 AND subj_a LIKE '%closes in 3 days%'
                 AND q2 >= 1 AND told_b_chk = 3 AND told_a_chk = 0 AND done_b
                 AND r_state LIKE 'NOTICE_RESEND_STATE%' AND r_channel LIKE 'NOTICE_RESEND_CHANNEL%'
                 AND e_again IS NOT NULL AND again_state = 'QUEUED' AND again_to = 'v440s@example.test' AND again_from = e_fail AND r_done LIKE 'NOTICE_RESEND_DONE%'
                 AND n_msgs = 4 AND n_resent = 1
                 AND n_manual = 12 AND (ed_major > 2 OR (ed_major = 2 AND ed_minor >= 1)), false),
        format('reg q=%s told a=%s b=%s subject=%s | check q=%s told b=%s a=%s done b=%s | resend queued=%s portal=%s | again state=%s to=%s from ok=%s done=%s | messages=%s resent=%s | manual=%s edition=%s.%s',
               q1, told_a, told_b, subj_a, q2, told_b_chk, told_a_chk, done_b, left(r_state, 20), left(r_channel, 22), again_state, again_to, again_from = e_fail, left(r_done, 19), n_msgs, n_resent, n_manual, ed_major, ed_minor));
END $$;
-- ── V439: the staff identity card register ──
-- An invented member of staff with a staff number and a live office is issued a card (MOAUM/SID/YY/NNNNN, valid to 31 December three
-- years on); issued again, the first card is replaced and one card stays live; reported lost, none is. A person with no staff number is
-- refused (STAFF_CARD_NO_NUMBER), and so is one holding no office (STAFF_CARD_NO_OFFICE). The block undoes its writes.
DO $$
DECLARE who uuid := gen_random_uuid(); p uuid := gen_random_uuid(); q uuid := gen_random_uuid(); r uuid := gen_random_uuid();
        a text; b text; live_after int; replaced text; valid date; lost int; live_lost int; no_number text; no_office text; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'library', true);
        PERFORM set_config('moaum.reason', 'check V439', true);
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (who, 'ZZ-ISSUER-439', 'ZZISSUER', 'Card Desk'),
               (p, 'P4390001', 'ZZSTAFFCARD', 'Invented'), (q, NULL, 'ZZSTAFFCARD', 'No Number'), (r, 'P4390002', 'ZZSTAFFCARD', 'No Office');
        INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from)
        VALUES (gen_random_uuid(), p, 'lecturer', 'department', 'MTC', 'check V439', who, current_date),
               (gen_random_uuid(), q, 'lecturer', 'department', 'MTC', 'check V439', who, current_date);
        a := credentials.issue_staff_card(p, NULL);
        b := credentials.issue_staff_card(p, 'damaged');
        SELECT count(*) INTO live_after FROM credentials.staff_identity_card WHERE person_id = p AND state = 'ISSUED';
        SELECT state INTO replaced FROM credentials.staff_identity_card WHERE card_no = a;
        SELECT valid_to INTO valid FROM credentials.staff_identity_card WHERE card_no = b;
        lost := credentials.report_staff_card_lost(p, 'dropped at the gate');
        SELECT count(*) INTO live_lost FROM credentials.staff_identity_card WHERE person_id = p AND state = 'ISSUED';
        BEGIN PERFORM credentials.issue_staff_card(q, NULL); no_number := 'ISSUED';
        EXCEPTION WHEN check_violation THEN no_number := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM credentials.issue_staff_card(r, NULL); no_office := 'ISSUED';
        EXCEPTION WHEN check_violation THEN no_office := split_part(SQLERRM, ':', 1); END;
        RAISE EXCEPTION 'the V439 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V439 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V439: a staff identity card is issued on the staff number to a member of staff in office, one live at a time (the old one replaced), valid to 31 December three years on, and ended when reported lost; no staff number or no office, no card',
        coalesce(a ~ '^MOAUM/SID/[0-9]{2}/[0-9]{5}$' AND b <> a AND live_after = 1 AND replaced = 'REPLACED'
                 AND valid = make_date(extract(year FROM current_date)::int + 3, 12, 31) AND lost = 1 AND live_lost = 0
                 AND no_number = 'STAFF_CARD_NO_NUMBER' AND no_office = 'STAFF_CARD_NO_OFFICE', false),
        format('cards %s then %s, live %s, first %s, valid %s, lost %s (live after %s), no number %s, no office %s', a, b, live_after, replaced, valid, lost, live_lost, no_number, no_office));
END $$;

-- ── V442. The providers watched: attempts are counted by channel, provider and hour; a channel is FAILING when enough was
--          tried and most failed, STUCK when a message waits with nothing tried, LOW_BALANCE below the SMS threshold, OFF when
--          its delivery is switched off; ICT is told once per episode on the channels that still work, and afresh after a
--          recovery. The accounts still on their first password are counted, listed and reached by a campaign's filter as the
--          doors judge them ──
DO $$
DECLARE who uuid := gen_random_uuid(); S text := '9992/9993'; a uuid := gen_random_uuid(); b uuid := gen_random_uuid(); c uuid := gen_random_uuid();
        st_fail text; told1 int; told2 int; told_sms int; told_email int; st_ok text; told3 int; told4 int; st_stuck text; st_off text; st_low text; told_low int;
        tally_tried int; tally_failed int; tally_err text;
        sum_first bigint; sum_never bigint; sum_signed bigint; n_list int; l_first uuid; staff_first bigint; n_units int;
        camp uuid := gen_random_uuid(); n_reach int; reach_is_a boolean;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'ict', true); PERFORM set_config('moaum.reason', 'CHECK V442', true);
        INSERT INTO iam.person (id, staff_number, surname, given_names, email, phone) VALUES (who, 'CHK/V442', 'CHECKV442', 'ICT', 'v442@example.test', '08000004420');
        INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from)
        VALUES (gen_random_uuid(), who, 'ict', 'institution', NULL, 'CHECK V442', who, current_date);
        PERFORM platform.set_portal_url('https://portal.example.test', who, 'ict');
        -- a clean slate for the reading: switches on, no counts, nothing old waiting, no episode open
        UPDATE platform.notice_setting SET dispatch_enabled = true, email_delivery = true, sms_delivery = true, portal_delivery = true,
               provider_watch = true, failing_share = 50, failing_min = 10, stuck_minutes = 30, sms_low_balance = 500 WHERE id;
        DELETE FROM platform.dispatch_tally;
        UPDATE platform.notice SET state = 'CANCELLED', cancelled_at = now(), cancel_reason = 'CHECK V442' WHERE state = 'QUEUED';
        UPDATE platform.provider_health SET state = 'IDLE', since = now(), alerted_state = NULL, alerted_at = NULL, balance = NULL, balance_raw = NULL;
        -- 1. the dispatcher's attempts counted
        PERFORM platform.record_attempt('EMAIL', 'smtp', true, NULL);
        FOR i IN 1..11 LOOP PERFORM platform.record_attempt('EMAIL', 'smtp', false, 'AuthenticationFailedException: 535'); END LOOP;
        SELECT tried, failed, last_error INTO tally_tried, tally_failed, tally_err FROM platform.dispatch_tally WHERE channel = 'EMAIL' AND provider = 'smtp';
        -- 2. e-mail failing: told once, by SMS and the portal, never by the failing e-mail
        st_fail := (SELECT x.state FROM platform.provider_status() x WHERE x.channel = 'EMAIL');
        told1 := platform.watch_providers();
        told2 := platform.watch_providers();
        SELECT count(*) FILTER (WHERE n.channel = 'SMS'), count(*) FILTER (WHERE n.channel = 'EMAIL') INTO told_sms, told_email
          FROM platform.notice n WHERE n.about_id = who AND n.template_key = 'PROVIDER_PROBLEM:FAILING';
        -- 3. recovered: the episode ends; failing again is told afresh
        DELETE FROM platform.dispatch_tally;
        FOR i IN 1..12 LOOP PERFORM platform.record_attempt('EMAIL', 'smtp', true, NULL); END LOOP;
        told3 := platform.watch_providers();
        st_ok := (SELECT h.state FROM platform.provider_health h WHERE h.channel = 'EMAIL');
        DELETE FROM platform.dispatch_tally;
        FOR i IN 1..12 LOOP PERFORM platform.record_attempt('EMAIL', 'smtp', false, 'again'); END LOOP;
        told4 := platform.watch_providers();
        -- 4. SMS stuck: a message waiting an hour with nothing tried; off when its delivery is switched off; low balance
        PERFORM platform.queue_notice('SMS', '08000004421', 'CHK V442 waiting', 'body', 'test', NULL);
        UPDATE platform.notice SET created_at = now() - interval '1 hour' WHERE subject = 'CHK V442 waiting';
        st_stuck := (SELECT x.state FROM platform.provider_status() x WHERE x.channel = 'SMS');
        UPDATE platform.notice_setting SET sms_delivery = false WHERE id;
        st_off := (SELECT x.state FROM platform.provider_status() x WHERE x.channel = 'SMS');
        UPDATE platform.notice_setting SET sms_delivery = true WHERE id;
        UPDATE platform.notice SET state = 'CANCELLED', cancelled_at = now(), cancel_reason = 'CHECK V442' WHERE subject = 'CHK V442 waiting';
        PERFORM platform.record_sms_balance('120.5', 120.5);
        st_low := (SELECT x.state FROM platform.provider_status() x WHERE x.channel = 'SMS');
        PERFORM platform.watch_providers();
        told_low := (SELECT count(*) FROM platform.notice n WHERE n.about_id = who AND n.template_key = 'PROVIDER_PROBLEM:LOW_BALANCE' AND n.channel = 'EMAIL');
        -- 5. first passwords: A on its first password and never signed in, B signed in and not yet changed, C changed
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9992-10-01', date '9993-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO people.student (id, admission_no, matric_no, matriculated_at, surname, other_names, sex, programme_code, entry_mode, entry_session, entry_level, current_level, status, study_mode) VALUES
            (a, 'MOAUM/ADM/92/004421', NULL, NULL, 'CHECKV442', 'First Ada', 'F', 'C00023', 'UTME', S, 100, 100, 'ADMITTED', 'FULL_TIME'),
            (b, 'MOAUM/ADM/92/004422', NULL, NULL, 'CHECKV442', 'First Bola', 'M', 'C00023', 'UTME', S, 100, 100, 'ADMITTED', 'FULL_TIME'),
            (c, 'MOAUM/ADM/92/004423', NULL, NULL, 'CHECKV442', 'First Chidi', 'M', 'C00023', 'UTME', S, 100, 100, 'ADMITTED', 'FULL_TIME');
        INSERT INTO people.student_contact (student_id, phone, email) VALUES (a, '08000004422', 'v442a@example.test'), (b, '08000004423', 'v442b@example.test'), (c, '08000004424', 'v442c@example.test');
        INSERT INTO iam.student_account (id, student_id, password_hash, must_change, last_signed_in_at) VALUES
            (gen_random_uuid(), a, '$2a$12$CHECKV442CHECKV442CHECKV442CHECKV442CHECKV442CHECKV44', true, NULL),
            (gen_random_uuid(), b, '$2a$12$CHECKV442CHECKV442CHECKV442CHECKV442CHECKV442CHECKV44', true, now()),
            (gen_random_uuid(), c, '$2a$12$CHECKV442CHECKV442CHECKV442CHECKV442CHECKV442CHECKV44', false, now());
        SELECT x.students_first, x.students_first_never, x.students_signed_in_first INTO sum_first, sum_never, sum_signed
          FROM iam.first_password_summary((SELECT faculty_code FROM ref.programme WHERE code = 'C00023'), (SELECT dept_code FROM ref.programme WHERE code = 'C00023')) x;
        SELECT count(*), max(x.student_id::text)::uuid INTO n_list, l_first FROM iam.first_password_students(NULL, NULL, NULL, NULL, true, 'CHECKV442', 50, 0) x;
        n_units := (SELECT count(*) FROM iam.first_password_units(NULL, NULL) u WHERE u.code = (SELECT faculty_code FROM ref.programme WHERE code = 'C00023'));
        INSERT INTO iam.credential (person_id, username, password_hash, must_change, set_by) VALUES (who, 'chk/v442', '$2a$12$CHECKV442CHECKV442CHECKV442CHECKV442CHECKV442CHECKV44', true, who);
        staff_first := (SELECT count(*) FROM iam.first_password_staff(NULL, true, 'CHECKV442', 50, 0));
        -- 6. the campaign's filter: of the three, only those still on their first password
        INSERT INTO platform.notice_campaign (id, name, template_key, audience, channels, vars, state, created_by, created_office)
        VALUES (camp, 'CHK V442', 'FIRST_PASSWORD_REMINDER', jsonb_build_object('students', true, 'filters', jsonb_build_object('session', S, 'first_password', true)),
                ARRAY['EMAIL'], '{}'::jsonb, 'DRAFT', who, 'ict');
        SELECT count(*), bool_and(r.id IN (a, b)) INTO n_reach, reach_is_a FROM platform.campaign_recipients(camp, 'student', NULL, 100) r;
        RAISE EXCEPTION 'the V442 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V442: attempts are counted; a failing channel is told to ICT once on the channels that still work and afresh after a recovery; stuck, off and low balance are read; the first passwords are counted, listed and reached by a campaign as the doors judge them',
        coalesce(tally_tried = 12 AND tally_failed = 11 AND tally_err LIKE 'AuthenticationFailedException%'
                 AND st_fail = 'FAILING' AND told1 >= 2 AND told2 = 0 AND told_sms = 1 AND told_email = 0
                 AND told3 = 0 AND st_ok = 'OK' AND told4 >= 2
                 AND st_stuck = 'STUCK' AND st_off = 'OFF' AND st_low = 'LOW_BALANCE' AND told_low = 1
                 AND sum_first >= 2 AND sum_never >= 1 AND sum_signed >= 1 AND n_list = 1 AND l_first = a AND n_units = 1 AND staff_first = 1
                 AND n_reach = 2 AND reach_is_a, false),
        format('tally %s/%s err=%s | failing=%s told=%s again=%s sms=%s email=%s | recovered told=%s state=%s refailed told=%s | stuck=%s off=%s low=%s told low=%s | first=%s never=%s signed=%s list=%s is a=%s units=%s staff=%s | campaign reach=%s only a,b=%s',
               tally_tried, tally_failed, left(tally_err, 30), st_fail, told1, told2, told_sms, told_email, told3, st_ok, told4, st_stuck, st_off, st_low, told_low,
               sum_first, sum_never, sum_signed, n_list, l_first = a, n_units, staff_first, n_reach, reach_is_a));
END $$;
-- ── V443. A course is never tied to a session: a class is opened for a course in any session on the register (not a cancelled
--          or merged one) when it is allocated — the same class returned the second time, a course that has ended or is not
--          taught in that semester refused; and a course belongs to the department whose code it carries: a course inserted
--          under another department's prefix goes to that department at once (its owner programme dropped when it is not
--          that department's), a prefix that is no department's code is named to one by the Academic Office — not the
--          Bursary — and applied to the pool on the owner trail as CODE, a department's own code refused as a prefix, and a
--          deliberate Change owner afterwards stands ──
DO $$
DECLARE who uuid := gen_random_uuid(); d_a text := 'CKQ' || chr(65 + extract(minute FROM now())::int % 26); d_b text := 'CKY' || chr(65 + extract(second FROM now())::int % 26); fac text; ses text;
        c1 uuid; c2 uuid; r_ended text := 'accepted'; r_sem text := 'accepted'; r_sess text := 'accepted'; r_gone text := 'accepted';
        own1 text; own2 text; prog1 text; moved int; own3 text; trail record; r_office text := 'accepted'; r_dept text := 'accepted';
        r_isdept text := 'accepted'; mapped int; own4 text; listed record; dropped boolean; kept text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'academic', true); PERFORM set_config('moaum.reason', 'CHECK V443', true);
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (who, 'CHK/V443', 'CHECKV443', 'Academic');
        SELECT faculty_code INTO fac FROM ref.department WHERE ended_on IS NULL ORDER BY code LIMIT 1;
        INSERT INTO ref.department (code, name, faculty_code) VALUES (d_a, 'CHECK V443 DEPARTMENT A', fac), (d_b, 'CHECK V443 DEPARTMENT B', fac);
        SELECT name INTO ses FROM policy.academic_session WHERE state NOT IN ('CANCELLED') AND merged_into IS NULL ORDER BY name DESC LIMIT 1;
        -- (1) a class on allocation: opened once, the same again; refused for an ended course, the wrong semester, no session
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state) VALUES (d_a || ' 101', 'Check one', 2, 1, 100, d_a, 'Core', 'LIVE');
        c1 := catalogue.open_class(d_a || ' 101', ses, 1, NULL);
        c2 := catalogue.open_class(d_a || ' 101', ses, 1, NULL);
        BEGIN PERFORM catalogue.open_class(d_a || ' 101', ses, 2, NULL); EXCEPTION WHEN check_violation THEN r_sem := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM catalogue.open_class(d_a || ' 101', '1900/1901', 1, NULL); EXCEPTION WHEN foreign_key_violation THEN r_sess := split_part(SQLERRM, ':', 1); END;
        UPDATE catalogue.course SET state = 'ENDED', ended_on = current_date WHERE code = d_a || ' 101';
        BEGIN PERFORM catalogue.open_class(d_a || ' 101', ses, 1, NULL); EXCEPTION WHEN check_violation THEN r_ended := split_part(SQLERRM, ':', 1); END;
        -- (2) the code names the owner: a course inserted under A's prefix by B belongs to A; its owner programme, B's, is dropped
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state) VALUES (d_a || ' 202', 'Check two', 2, 1, 200, d_b, 'Core', 'LIVE');
        SELECT dept_code, owner_programme INTO own1, prog1 FROM catalogue.course WHERE code = d_a || ' 202';
        -- a course astray, moved by the rule on the owner trail as CODE
        ALTER TABLE catalogue.course DISABLE TRIGGER trg_course_owner_by_code;
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state) VALUES ('MOAU-' || d_a || ' 303', 'Check three', 3, 2, 300, d_b, 'Core', 'LIVE');
        ALTER TABLE catalogue.course ENABLE TRIGGER trg_course_owner_by_code;
        SELECT dept_code INTO own2 FROM catalogue.course WHERE code = 'MOAU-' || d_a || ' 303';
        moved := catalogue.apply_code_owners(d_a, 'CHECK: the rule applied');
        SELECT dept_code INTO own3 FROM catalogue.course WHERE code = 'MOAU-' || d_a || ' 303';
        SELECT h.from_dept, h.to_dept, h.source INTO trail FROM catalogue.course_owner_history h WHERE h.course_code = 'MOAU-' || d_a || ' 303' ORDER BY h.changed_at DESC LIMIT 1;
        -- a prefix that is no department's code, named by the Academic Office (not the Bursary; not a department's own code; a live department)
        BEGIN PERFORM catalogue.set_code_prefix('CKZ', d_a, NULL, false, NULL, who, 'bursar'); EXCEPTION WHEN check_violation THEN r_office := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM catalogue.set_code_prefix(d_a, d_b, NULL, false, NULL, who, 'academic'); EXCEPTION WHEN check_violation THEN r_isdept := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM catalogue.set_code_prefix('CKZ', 'NO SUCH DEPARTMENT', NULL, false, NULL, who, 'academic'); EXCEPTION WHEN check_violation THEN r_dept := split_part(SQLERRM, ':', 1); END;
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state) VALUES ('CKZ 404', 'Check four', 2, 1, 400, d_b, 'Core', 'LIVE');
        mapped := catalogue.set_code_prefix('CKZ', d_a, 'checked', true, 'CHECK: CKZ named', who, 'academic');
        SELECT dept_code INTO own4 FROM catalogue.course WHERE code = 'CKZ 404';
        SELECT is_department, mapped_dept, owner_by_code, astray INTO listed FROM catalogue.code_owners() WHERE prefix = 'CKZ';
        -- a deliberate Change owner afterwards stands: the rule runs at insert, not at update
        PERFORM catalogue.change_owner('CKZ 404', d_b, NULL, 'CHECK: moved back on purpose');
        SELECT dept_code INTO kept FROM catalogue.course WHERE code = 'CKZ 404';
        dropped := catalogue.unset_code_prefix('CKZ', 'academic');
        RAISE EXCEPTION 'the V443 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V443: a class is opened for a course in a session when it is allocated and found again the second time, refused for an ended course, the wrong semester or no such session; a course inserted under another department''s code belongs to that department; the courses astray move on the owner trail as CODE; a prefix that is no department''s code is named by the Academic Office only, never a department''s own code, and applied to the pool; a deliberate Change owner afterwards stands',
        coalesce(c1 IS NOT NULL AND c1 = c2 AND r_sem = 'CLASS_NOT_IN_SEMESTER' AND r_sess = 'CLASS_SESSION' AND r_ended = 'ALLOC_ENDED'
                 AND own1 = d_a AND prog1 IS NULL AND own2 = d_b AND moved = 1 AND own3 = d_a AND trail.from_dept = d_b AND trail.to_dept = d_a AND trail.source = 'CODE'
                 AND r_office = 'CODE_OWNER_OFFICE' AND r_isdept = 'CODE_PREFIX_IS_DEPARTMENT' AND r_dept = 'CODE_OWNER_DEPT'
                 AND mapped = 1 AND own4 = d_a AND NOT listed.is_department AND listed.mapped_dept = d_a AND listed.owner_by_code = d_a AND listed.astray = 0
                 AND kept = d_b AND dropped, false),
        format('class=%s/%s sem=%s sess=%s ended=%s own1=%s/%s own2=%s moved=%s own3=%s trail=%s/%s/%s office=%s isdept=%s dept=%s mapped=%s own4=%s listed=%s/%s/%s/%s kept=%s dropped=%s',
               c1, c2, r_sem, r_sess, r_ended, own1, prog1, own2, moved, own3, trail.from_dept, trail.to_dept, trail.source, r_office, r_isdept, r_dept, mapped, own4,
               listed.is_department, listed.mapped_dept, listed.owner_by_code, listed.astray, kept, dropped));
END $$;

-- ── V444. The SMS cost of a campaign: pages are counted as the providers charge them (GSM-7 160/153, an extension character
--          twice, Unicode 70/67); a campaign's SMS is costed for its recipients with a phone and set against the balance; the
--          send is refused on a known shortfall and goes when the office accepts it. The JUPEB and postgraduate application
--          windows remind their own drafts, on the addresses their modules hold, and never the submitted ──
DO $$
DECLARE who uuid := gen_random_uuid(); S text := '9994/9995'; st uuid := gen_random_uuid(); camp uuid := gen_random_uuid();
        u_short int; u_160 int; u_161 int; u_306 int; u_307 int; u_ext80 int; u_ext81 int; u_uni70 int; u_uni71 int; u_empty int;
        k record; r_credit text; job uuid;
        ja uuid := gen_random_uuid(); jb uuid := gen_random_uuid(); jacc uuid := gen_random_uuid(); jacc2 uuid := gen_random_uuid(); w_j uuid; w_p uuid;
        pa uuid := gen_random_uuid(); pg uuid := gen_random_uuid(); q1 int; q2 int;
        told_ja int; told_jb int; told_pg int; subj_j text; sms_pg text; done_jb boolean; done_pg boolean;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'ict', true); PERFORM set_config('moaum.reason', 'CHECK V444', true);
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (who, 'CHK/V444', 'CHECKV444', 'ICT');
        PERFORM platform.set_portal_url('https://portal.example.test', who, 'ict');
        UPDATE platform.notice_setting SET closing_reminders = true, portal_delivery = true WHERE id;
        -- 1. pages
        u_short := platform.sms_units('Hello');
        u_160 := platform.sms_units(repeat('a', 160));
        u_161 := platform.sms_units(repeat('a', 161));
        u_306 := platform.sms_units(repeat('a', 306));
        u_307 := platform.sms_units(repeat('a', 307));
        u_ext80 := platform.sms_units(repeat('€', 80));
        u_ext81 := platform.sms_units(repeat('€', 81));
        u_uni70 := platform.sms_units(repeat('ọ', 70));
        u_uni71 := platform.sms_units(repeat('ọ', 71));
        u_empty := platform.sms_units('');
        -- 2. a campaign's SMS against the balance: one student with a phone, a long announcement, a balance too small
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9994-10-01', date '9995-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO people.student (id, admission_no, matric_no, matriculated_at, surname, other_names, sex, programme_code, entry_mode, entry_session, entry_level, current_level, status, study_mode)
        VALUES (st, 'MOAUM/ADM/94/004441', NULL, NULL, 'CHECKV444', 'Credit Ada', 'F', 'C00023', 'UTME', S, 100, 100, 'ADMITTED', 'FULL_TIME');
        INSERT INTO people.student_contact (student_id, phone, email) VALUES (st, '08000004441', 'v444@example.test');
        INSERT INTO platform.notice_campaign (id, name, template_key, audience, channels, vars, state, created_by, created_office)
        VALUES (camp, 'CHK V444', 'ANNOUNCEMENT', jsonb_build_object('students', true, 'filters', jsonb_build_object('session', S)), ARRAY['EMAIL', 'SMS', 'PORTAL'],
                jsonb_build_object('TITLE', 'Credit', 'MESSAGE', 'Hello', 'SMS_MESSAGE', repeat('Lectures resume on Monday. ', 12), 'SIGNATURE', 'Registry'), 'DRAFT', who, 'ict');
        UPDATE platform.provider_health SET balance = 1, balance_raw = '1', balance_at = now() WHERE channel = 'SMS';
        SELECT * INTO k FROM platform.campaign_sms_cost(camp, 1000);
        BEGIN PERFORM platform.campaign_send(camp, who, 'ict'); EXCEPTION WHEN check_violation THEN r_credit := SQLERRM; END;
        job := platform.campaign_send(camp, who, 'ict', true);
        -- 3. the JUPEB and postgraduate application deadlines: a draft reminded, the submitted not
        INSERT INTO jupeb.account (id, email, password_hash) VALUES (jacc, 'v444j@example.test', '$2a$12$CHECKV444CHECKV444CHECKV444CHECKV444CHECKV444CHECKV44'),
            (jacc2, 'v444j2@example.test', '$2a$12$CHECKV444CHECKV444CHECKV444CHECKV444CHECKV444CHECKV44');
        INSERT INTO jupeb.application (id, account_id, session, application_no, surname, first_name, email, phone, state, submitted_at) VALUES
            (ja, jacc, S, 'CHK/V444/JA', 'CHECKV444', 'Jupeb Ada', 'v444ja@example.test', '08000004442', 'DRAFT', NULL),
            (jb, jacc2, S, 'CHK/V444/JB', 'CHECKV444', 'Jupeb Bola', 'v444jb@example.test', '08000004443', 'SUBMITTED', now());
        INSERT INTO admissions.pg_applicant (id, session, surname, other_names, email, phone, password_hash)
        VALUES (pa, S, 'CHECKV444', 'Postgrad Chidi', 'v444pg@example.test', '08000004444', '$2a$12$CHECKV444CHECKV444CHECKV444CHECKV444CHECKV444CHECKV44');
        INSERT INTO admissions.pg_application (id, applicant_id, session, application_no, programme_code, entry_level, state)
        VALUES (pg, pa, S, 'PG/94/004444', 'C00023', 800, 'DRAFT');
        INSERT INTO policy.portal_window (window_type, session, semester, opens_at, closes_at, created_office) VALUES
            ('JUPEB_APPLICATION', S, NULL, now() - interval '1 day', (((now() AT TIME ZONE 'Africa/Lagos')::date + 3)::timestamp + interval '12 hours') AT TIME ZONE 'Africa/Lagos', 'ict')
        RETURNING id INTO w_j;
        INSERT INTO policy.portal_window (window_type, session, semester, opens_at, closes_at, created_office) VALUES
            ('POSTGRADUATE_APPLICATION', S, NULL, now() - interval '1 day', (((now() AT TIME ZONE 'Africa/Lagos')::date + 1)::timestamp + interval '12 hours') AT TIME ZONE 'Africa/Lagos', 'ict')
        RETURNING id INTO w_p;
        UPDATE platform.notice_job SET state = 'CANCELLED', finished_at = now() WHERE state IN ('QUEUED', 'RUNNING') AND id <> job;   -- only this check's jobs drain below
        UPDATE platform.notice_job SET state = 'CANCELLED', finished_at = now() WHERE id = job;
        q1 := platform.queue_closing_reminders(now());
        FOR i IN 1..8 LOOP PERFORM platform.run_notice_job(100000); END LOOP;
        SELECT count(*) INTO told_ja FROM platform.notice n WHERE n.about_kind = 'jupeb_application' AND n.about_id = ja AND n.template_key = 'WINDOW_CLOSING:JUPEB_APPLICATION' AND n.event_key LIKE 'window-closing:' || w_j || ':%:3';
        SELECT count(*) INTO told_jb FROM platform.notice n WHERE n.about_id = jb AND n.template_key LIKE 'WINDOW_CLOSING%';
        SELECT count(*) INTO told_pg FROM platform.notice n WHERE n.about_kind = 'pg_application' AND n.about_id = pg AND n.template_key = 'WINDOW_CLOSING:POSTGRADUATE_APPLICATION' AND n.event_key LIKE 'window-closing:' || w_p || ':%:1';
        subj_j := (SELECT n.subject FROM platform.notice n WHERE n.about_id = ja AND n.channel = 'EMAIL' AND n.template_key = 'WINDOW_CLOSING:JUPEB_APPLICATION');
        sms_pg := (SELECT n.body FROM platform.notice n WHERE n.about_id = pg AND n.channel = 'SMS' AND n.template_key = 'WINDOW_CLOSING:POSTGRADUATE_APPLICATION');
        done_jb := policy.applicant_window_done('JUPEB_APPLICATION', S, jb);
        UPDATE admissions.pg_application SET state = 'SUBMITTED', submitted_at = now() WHERE id = pg;
        done_pg := policy.applicant_window_done('POSTGRADUATE_APPLICATION', S, pg);
        RAISE EXCEPTION 'the V444 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V444: SMS pages are counted as charged (GSM-7, extension characters twice, Unicode); a campaign''s SMS is costed against the balance, refused on a known shortfall and sent when accepted; the JUPEB and postgraduate drafts are reminded before their windows close, on their own modules'' addresses, and the submitted never',
        coalesce(u_short = 1 AND u_160 = 1 AND u_161 = 2 AND u_306 = 2 AND u_307 = 3 AND u_ext80 = 1 AND u_ext81 = 2 AND u_uni70 = 1 AND u_uni71 = 2 AND u_empty = 0
                 AND k.sms_on AND k.units_each >= 3 AND k.recipients = 1000 AND k.units_total = 1000 * k.units_each AND k.covers IS FALSE
                 AND r_credit LIKE 'CAMPAIGN_SMS_CREDIT%' AND job IS NOT NULL
                 AND q1 >= 2 AND told_ja = 3 AND told_jb = 0 AND told_pg = 3 AND subj_j LIKE 'JUPEB applications for%close in 3 days%'
                 AND sms_pg LIKE '%close tomorrow%' AND done_jb AND done_pg, false),
        format('units %s/%s/%s/%s/%s ext %s/%s uni %s/%s empty %s | cost on=%s each=%s rcpt=%s total=%s covers=%s | refused=%s job=%s | q=%s jupeb a=%s b=%s pg=%s subj=%s sms=%s done jb=%s pg=%s',
               u_short, u_160, u_161, u_306, u_307, u_ext80, u_ext81, u_uni70, u_uni71, u_empty, k.sms_on, k.units_each, k.recipients, k.units_total, k.covers,
               left(r_credit, 20), job IS NOT NULL, q1, told_ja, told_jb, told_pg, subj_j, left(sms_pg, 60), done_jb, done_pg));
END $$;
-- ── V445. Central course management completed: a course carries a review status set by the central offices or the owning
--          department's Head (a Head outside the owner refused; INCORRECT_OWNER needs a note), created/updated stamps kept
--          by trigger; the review flags issues without deciding — the code names another department, the owner offers it
--          to no programme of its own, it is in no structure, a possible duplicate by title; possible duplicates by title
--          are listed, never merged; a course's history reads its field changes, its owner changes and its bindings from the
--          spine; many courses move to one owner in one act, all or none, each on the trail as BULK ──
DO $$
DECLARE who uuid := gen_random_uuid(); d_a text := 'CKQ' || chr(65 + extract(minute FROM now())::int % 26); d_b text := 'CKY' || chr(65 + extract(second FROM now())::int % 26);
        fac text; prog_a text; stamp_created timestamptz; stamp_updated timestamptz; stamp_after timestamptz; by_after uuid;
        r_status text := 'accepted'; r_office text := 'accepted'; r_scope text := 'accepted'; r_note text := 'accepted'; rv record;
        issues1 text[]; issues2 text[]; issues3 text[]; dup record; hist_fields text; hist_owner int; summ record;
        r_empty text := 'accepted'; bulk_n int; own_after text; own_b text; trail_src text; r_bulk text := 'accepted'; own_untouched text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'academic', true); PERFORM set_config('moaum.reason', 'CHECK V445', true);
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (who, 'CHK/V445', 'CHECKV445', 'Academic');
        SELECT faculty_code INTO fac FROM ref.department WHERE ended_on IS NULL ORDER BY code LIMIT 1;
        INSERT INTO ref.department (code, name, faculty_code) VALUES (d_a, 'CHECK V445 DEPARTMENT A', fac), (d_b, 'CHECK V445 DEPARTMENT B', fac);
        SELECT 'C' || lpad(x::text, 5, '0') INTO prog_a FROM generate_series(90000, 99999) x
         WHERE NOT EXISTS (SELECT 1 FROM ref.programme p WHERE p.code = 'C' || lpad(x::text, 5, '0')) ORDER BY random() LIMIT 1;
        INSERT INTO ref.programme (code, name, dept_code, faculty_code, category, min_score) VALUES (prog_a, 'CHECK V445 PROGRAMME A', d_a, fac, 'UNDER GRADUATE', 0);
        -- (1) stamps by trigger
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state) VALUES (d_a || ' 101', 'Introduction to Checking', 2, 1, 100, d_a, 'Core', 'LIVE');
        SELECT created_at, updated_at INTO stamp_created, stamp_updated FROM catalogue.course WHERE code = d_a || ' 101';
        PERFORM pg_sleep(0.01);
        UPDATE catalogue.course SET title = 'Introduction to Checking I' WHERE code = d_a || ' 101';
        SELECT updated_at, updated_by INTO stamp_after, by_after FROM catalogue.course WHERE code = d_a || ' 101';
        -- (2) the review: a bad status, a wrong office, a Head outside the owner, INCORRECT_OWNER without a note — refused; then set
        BEGIN PERFORM catalogue.set_course_review(d_a || ' 101', 'MAYBE', NULL, who, 'academic', NULL); EXCEPTION WHEN check_violation THEN r_status := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM catalogue.set_course_review(d_a || ' 101', 'CORRECT', NULL, who, 'bursar', NULL); EXCEPTION WHEN check_violation THEN r_office := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM catalogue.set_course_review(d_a || ' 101', 'CORRECT', NULL, who, 'hod', d_b); EXCEPTION WHEN check_violation THEN r_scope := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM catalogue.set_course_review(d_a || ' 101', 'INCORRECT_OWNER', NULL, who, 'academic', NULL); EXCEPTION WHEN check_violation THEN r_note := split_part(SQLERRM, ':', 1); END;
        SELECT review_status, reviewed_office, review_note INTO rv FROM catalogue.set_course_review(d_a || ' 101', 'REQUIRES_REVIEW', 'owner to be confirmed', who, 'hod', d_a);
        -- (3) the issues: in no structure; owned by B under A's code (the rule disabled to plant it) → CODE_NAMES_OTHER; a title twin → POSSIBLE_DUPLICATE
        issues1 := catalogue.course_issues(d_a || ' 101');
        ALTER TABLE catalogue.course DISABLE TRIGGER trg_course_owner_by_code;
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state) VALUES (d_a || ' 202', 'Checking Two', 3, 2, 200, d_b, 'Core', 'LIVE');
        ALTER TABLE catalogue.course ENABLE TRIGGER trg_course_owner_by_code;
        INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES (d_a || ' 202', prog_a, 200, 'Borrowed');
        issues2 := catalogue.course_issues(d_a || ' 202');
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state) VALUES (d_a || ' 303', 'Intro to Checking I', 2, 1, 100, d_a, 'Core', 'LIVE');
        issues3 := catalogue.course_issues(d_a || ' 101');
        SELECT p.evidence, p.keep_code, p.merge_code INTO dup FROM catalogue.possible_duplicates() p WHERE p.keep_code IN (d_a || ' 101', d_a || ' 303') LIMIT 1;
        -- (4) the history: the title change on the spine, the binding added
        SELECT string_agg(h.field || ':' || coalesce(h.old_value, '') || '>' || coalesce(h.new_value, ''), ',' ORDER BY h.at) INTO hist_fields
          FROM catalogue.course_history(d_a || ' 101') h WHERE h.action = 'CHANGED' AND h.field = 'title';
        -- (5) bulk: empty refused; a wrong department refuses the whole act (nothing moved); then both to B with one reason, each on the trail as BULK
        BEGIN PERFORM catalogue.change_owner_bulk(ARRAY[]::text[], d_b, NULL, 'CHECK'); EXCEPTION WHEN check_violation THEN r_empty := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM catalogue.change_owner_bulk(ARRAY[d_a || ' 101', d_a || ' 303'], 'NO SUCH DEPARTMENT', NULL, 'CHECK'); EXCEPTION WHEN check_violation THEN r_bulk := split_part(SQLERRM, ':', 1); END;
        SELECT dept_code INTO own_untouched FROM catalogue.course WHERE code = d_a || ' 101';
        SELECT count(*) INTO bulk_n FROM catalogue.change_owner_bulk(ARRAY[d_a || ' 101', d_a || ' 303'], d_b, NULL, 'CHECK: uploaded under the wrong department');
        SELECT dept_code INTO own_after FROM catalogue.course WHERE code = d_a || ' 101';
        SELECT dept_code INTO own_b FROM catalogue.course WHERE code = d_a || ' 303';
        SELECT h.source INTO trail_src FROM catalogue.course_owner_history h JOIN catalogue.course c ON c.id = h.course_id WHERE c.code = d_a || ' 101' ORDER BY h.changed_at DESC LIMIT 1;
        SELECT count(*) INTO hist_owner FROM catalogue.course_history(d_a || ' 101') h WHERE h.action = 'OWNER_CHANGED';
        SELECT s.total, s.not_reviewed, s.requires_review, s.with_issues INTO summ FROM catalogue.review_summary() s;
        RAISE EXCEPTION 'the V445 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V445: a course carries created/updated stamps by trigger and a review status set by the central offices or the owning department''s Head with a note where the status needs one; the review flags issues (code names another department, in no structure, possible duplicate by title) without changing anything; possible duplicates by title are listed; the history reads field changes and owner changes; many courses move to one owner in one act, all or none, on the trail as BULK',
        coalesce(stamp_created IS NOT NULL AND stamp_updated IS NOT NULL AND stamp_after >= stamp_updated AND by_after = who
                 AND r_status = 'REVIEW_STATUS' AND r_office = 'REVIEW_OFFICE' AND r_scope = 'REVIEW_SCOPE' AND r_note = 'REVIEW_NOTE'
                 AND rv.review_status = 'REQUIRES_REVIEW' AND rv.reviewed_office = 'hod' AND rv.review_note = 'owner to be confirmed'
                 AND 'NOT_IN_STRUCTURE' = ANY (issues1) AND 'CODE_NAMES_OTHER' = ANY (issues2) AND 'POSSIBLE_DUPLICATE' = ANY (issues3)
                 AND dup.evidence = 'SAME_TITLE_LEVEL_AND_SEMESTER'
                 AND hist_fields LIKE '%title:Introduction to Checking>Introduction to Checking I%'
                 AND r_empty = 'CAT_OWNER_BULK_EMPTY' AND r_bulk = 'CAT_OWNER_DEPT' AND own_untouched = d_a
                 AND bulk_n = 2 AND own_after = d_b AND own_b = d_b AND trail_src = 'BULK' AND hist_owner >= 1
                 AND summ.total >= 3 AND summ.requires_review >= 1 AND summ.with_issues >= 1, false),
        format('stamps=%s/%s/%s/%s refused=%s/%s/%s/%s review=%s/%s/%s issues=%s/%s/%s dup=%s/%s/%s hist=%s bulk=%s/%s/%s/%s/%s/%s/%s/%s summary=%s/%s/%s/%s',
               stamp_created IS NOT NULL, stamp_updated IS NOT NULL, stamp_after >= stamp_updated, by_after = who, r_status, r_office, r_scope, r_note,
               rv.review_status, rv.reviewed_office, rv.review_note, issues1, issues2, issues3, dup.evidence, dup.keep_code, dup.merge_code, hist_fields,
               r_empty, r_bulk, own_untouched, bulk_n, own_after, own_b, trail_src, hist_owner, summ.total, summ.not_reviewed, summ.requires_review, summ.with_issues));
END $$;
-- ── V446. Preliminary Science on the shared applicant stack: an applicant with no JAMB number registers while the programme's
--          window is open and gets an ordinary application number; the application fee comes from the route's fees (no other
--          fee is invented) and is paid before the form opens; an awaiting result is refused; the eligibility (four credits, at most
--          two sittings, three of Mathematics, Chemistry, Physics and Biology) and the completion remediation are worked out by the
--          backend; a target is an existing undergraduate programme; the Office recommends only on accepted documents, a verified
--          O'Level and an eligible record, someone else approves, the Academic Office publishes; the letter names Preliminary
--          Science and the target as an intended progression; the application stays out of every Post-UTME flow ──
DO $$
DECLARE a_off uuid := gen_random_uuid(); b_off uuid := gen_random_uuid(); acc uuid; app uuid; v_session text; fac text; d_code text := 'CKP' || chr(65 + extract(second FROM now())::int % 26);
        prog text; prog_pg text; r record; c record; v_ref text; v_ref2 text; v_amt numeric; v_chk text := 'accepted'; v_first text := 'accepted'; v_await text := 'accepted';
        v_await2 text := 'accepted'; v_three text := 'accepted'; e_a text; e_b text; e_c text; e_d text; e_max1 text; e_f text; rem_a text[]; rem_a_status text;
        v_bad_target text := 'accepted'; v_pg_target text := 'accepted'; v_dup_target text := 'accepted'; v_closed text := 'accepted'; v_sub text;
        v_unver text := 'accepted'; v_olev text := 'accepted'; v_own text := 'accepted'; v_office text := 'accepted'; pub jsonb; st record; letter credentials.issued;
        v_dup text := 'accepted'; v_mail text := 'accepted'; notices int; utme_aud boolean; scr boolean; rows_ict int; cls record; stats jsonb; v_sub_at timestamptz;
        v_sitting_word text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', a_off::text, true); PERFORM set_config('moaum.actor_office', 'academic', true); PERFORM set_config('moaum.reason', 'CHECK V446', true);
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (a_off, 'CHK/V446A', 'CHECKV446', 'Officer'), (b_off, 'CHK/V446B', 'CHECKV446', 'Approver');
        v_session := policy.route_session('PRELIMINARY_SCIENCE');
        -- the window open for the check whatever its state on this database
        PERFORM policy.window_act('PRELIMINARY_SCIENCE_APPLICATION', v_session, NULL, 'OPEN', NULL, NULL, NULL, false, 'CHECK V446', a_off, 'ict');
        -- a target programme of the check's own: an undergraduate programme of a department of its own
        SELECT faculty_code INTO fac FROM ref.department WHERE ended_on IS NULL ORDER BY code LIMIT 1;
        INSERT INTO ref.department (code, name, faculty_code) VALUES (d_code, 'CHECK V446 DEPARTMENT', fac);
        SELECT 'C' || lpad(x::text, 5, '0') INTO prog FROM generate_series(90000, 99999) x
         WHERE NOT EXISTS (SELECT 1 FROM ref.programme p WHERE p.code = 'C' || lpad(x::text, 5, '0')) ORDER BY random() LIMIT 1;
        INSERT INTO ref.programme (code, name, dept_code, faculty_code, category, min_score) VALUES (prog, 'B.Sc. CHECK V446 SCIENCE', d_code, fac, 'UNDER GRADUATE', 0);
        SELECT 'C' || lpad(x::text, 5, '0') INTO prog_pg FROM generate_series(90000, 99999) x
         WHERE NOT EXISTS (SELECT 1 FROM ref.programme p WHERE p.code = 'C' || lpad(x::text, 5, '0')) ORDER BY random() LIMIT 1;
        INSERT INTO ref.programme (code, name, dept_code, faculty_code, category, min_score) VALUES (prog_pg, 'M.Sc. CHECK V446', d_code, fac, 'POST GRADUATE', 0);
        PERFORM admissions.prelim_add_target('PRELIMINARY_SCIENCE', prog, 'Check', 999, 'CHECK V446');
        BEGIN PERFORM admissions.prelim_add_target('PRELIMINARY_SCIENCE', prog, 'Check', 999, 'CHECK V446'); EXCEPTION WHEN check_violation THEN v_dup_target := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM admissions.prelim_add_target('PRELIMINARY_SCIENCE', prog_pg, 'Check', 999, 'CHECK V446'); EXCEPTION WHEN check_violation THEN v_pg_target := split_part(SQLERRM, ':', 1); END;
        -- (1) the applicant registers: no JAMB number, an ordinary application number, the fee first
        PERFORM set_config('moaum.actor_office', 'applicant', true); PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
        acc := admissions.prelim_register('PRELIMINARY_SCIENCE', 'Checkv446', 'Ada', 'Ene', 'F', DATE '2007-03-01', 'v446.check@example.test', '08031234567',
                                          '$2a$12$abcdefghijklmnopqrstuuabcdefghijklmnopqrstuvwxyzABCDE');
        SELECT a.id INTO app FROM admissions.application a WHERE a.account_id = acc;
        SELECT a.application_no, ca.jamb_reg_no, ca.entry_mode, ca.entry_level, ca.sex, rv.state, acct.jamb_key INTO c
          FROM admissions.application a JOIN admissions.candidate ca ON ca.id = a.candidate_id JOIN admissions.prelim_review rv ON rv.application_id = a.id
          JOIN admissions.applicant_account acct ON acct.id = a.account_id WHERE a.id = app;
        BEGIN PERFORM admissions.prelim_register('PRELIMINARY_SCIENCE', 'CHECKV446', 'ada', NULL, 'F', DATE '2007-03-01', 'v446.other@example.test', '08031234568',
                                                 '$2a$12$abcdefghijklmnopqrstuuabcdefghijklmnopqrstuvwxyzABCDE');
        EXCEPTION WHEN check_violation THEN v_dup := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM admissions.prelim_register('PRELIMINARY_SCIENCE', 'OTHERV446', 'Bola', NULL, 'M', DATE '2006-03-01', 'V446.CHECK@example.test', '08031234569',
                                                 '$2a$12$abcdefghijklmnopqrstuuabcdefghijklmnopqrstuvwxyzABCDE');
        EXCEPTION WHEN unique_violation THEN v_mail := 'DUPLICATE_EMAIL'; END;
        BEGIN PERFORM admissions.prelim_save_olevel(app, '[{"sitting":1,"exam_body":"WAEC","exam_number":"4250101001","exam_year":"2024","subjects":[{"subject":"Mathematics","grade":"C5"}]}]'::jsonb);
        EXCEPTION WHEN check_violation THEN v_first := split_part(SQLERRM, ':', 1); END;
        -- (2) the fee: the route's application fee, one open reference at a time; no checking fee was ever stated
        v_ref := admissions.new_fee_reference(app, 'APPLICATION');
        v_ref2 := admissions.new_fee_reference(app, 'APPLICATION');
        SELECT amount INTO v_amt FROM admissions.fee_reference WHERE reference = v_ref;
        BEGIN PERFORM admissions.new_fee_reference(app, 'CHECKING'); EXCEPTION WHEN check_violation THEN v_chk := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_office', 'bursar', true); PERFORM set_config('moaum.actor_id', a_off::text, true);
        PERFORM admissions.confirm_fee(v_ref, 'WEBPAY', 'CHECK V446');
        -- (3) the form: an awaiting result refused, a third sitting refused; the eligibility read on every save
        PERFORM set_config('moaum.actor_office', 'applicant', true); PERFORM set_config('moaum.actor_id', acc::text, true);
        BEGIN PERFORM admissions.prelim_save_olevel(app, '[{"sitting":1,"exam_body":"WAEC","exam_number":"4250101001","exam_year":"2024","awaiting":true,"subjects":[{"subject":"Mathematics","grade":"C5"}]}]'::jsonb);
        EXCEPTION WHEN check_violation THEN v_await := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM admissions.prelim_save_olevel(app, '[{"sitting":1,"exam_body":"WAEC","exam_number":"4250101001","exam_year":"2024","subjects":[{"subject":"Mathematics","grade":"AR"}]}]'::jsonb);
        EXCEPTION WHEN check_violation THEN v_await2 := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM admissions.prelim_save_olevel(app, '[{"sitting":1,"exam_body":"WAEC","exam_number":"1","exam_year":"2024","subjects":[{"subject":"Mathematics","grade":"C5"}]},{"sitting":2,"exam_body":"NECO","exam_number":"2","exam_year":"2024","subjects":[{"subject":"Physics","grade":"C5"}]},{"sitting":2,"exam_body":"NECO","exam_number":"3","exam_year":"2025","subjects":[{"subject":"Biology","grade":"C5"}]}]'::jsonb);
        EXCEPTION WHEN check_violation THEN v_three := split_part(SQLERRM, ':', 1); END;
        -- (a) four credits, three of the core: eligible, Physics to be made up
        PERFORM admissions.prelim_save_olevel(app, '[{"sitting":1,"exam_body":"WAEC","exam_type":"SSCE","exam_number":"4250101001","exam_year":"2024","subjects":[{"subject":"English Language","grade":"C6"},{"subject":"Mathematics","grade":"C5"},{"subject":"Chemistry","grade":"C6"},{"subject":"Physics","grade":"D7"},{"subject":"Biology","grade":"C5"}]}]'::jsonb);
        SELECT eligibility_status, remediation_subjects, remediation_status INTO e_a, rem_a, rem_a_status FROM admissions.prelim_review WHERE application_id = app;
        -- (b) four credits, two of the core: not eligible
        PERFORM admissions.prelim_save_olevel(app, '[{"sitting":1,"exam_body":"WAEC","exam_number":"4250101001","exam_year":"2024","subjects":[{"subject":"English Language","grade":"B3"},{"subject":"Mathematics","grade":"C5"},{"subject":"Chemistry","grade":"C6"},{"subject":"Economics","grade":"C4"},{"subject":"Physics","grade":"D7"},{"subject":"Biology","grade":"E8"}]}]'::jsonb);
        SELECT eligibility_status INTO e_b FROM admissions.prelim_review WHERE application_id = app;
        -- (c) three credits: not eligible
        PERFORM admissions.prelim_save_olevel(app, '[{"sitting":1,"exam_body":"NECO","exam_number":"4250101001","exam_year":"2024","subjects":[{"subject":"Mathematics","grade":"C5"},{"subject":"Chemistry","grade":"C6"},{"subject":"Physics","grade":"C4"},{"subject":"Biology","grade":"D7"},{"subject":"English Language","grade":"E8"}]}]'::jsonb);
        SELECT eligibility_status INTO e_c FROM admissions.prelim_review WHERE application_id = app;
        -- (d) two sittings, each kept apart, the better grade of a subject counted once: five credits, all four core — eligible, nothing to make up
        PERFORM admissions.prelim_save_olevel(app, '[{"sitting":1,"exam_body":"WAEC","exam_number":"4250101001","exam_year":"2023","subjects":[{"subject":"Mathematics","grade":"C6"},{"subject":"English Language","grade":"C5"},{"subject":"Chemistry","grade":"D7"}]},{"sitting":2,"exam_body":"NECO","exam_type":"GCE","exam_number":"9988776655","exam_year":"2024","subjects":[{"subject":"Chemistry","grade":"C5"},{"subject":"Physics","grade":"C4"},{"subject":"Biology","grade":"B3"},{"subject":"English Language","grade":"C6"}]}]'::jsonb);
        SELECT eligibility_status || '/' || coalesce(remediation_status, '-') || '/' || sittings || '/' || total_credits || '/' || core_credits INTO e_d FROM admissions.prelim_review WHERE application_id = app;
        SELECT string_agg(DISTINCT exam_body || ':' || sitting, ',' ORDER BY exam_body || ':' || sitting) INTO v_sitting_word FROM admissions.screening_olevel WHERE application_id = app AND active;
        -- (e) the Academic Office allows one sitting only: the two-sitting record is no longer eligible; then two again
        PERFORM set_config('moaum.actor_office', 'academic', true); PERFORM set_config('moaum.actor_id', a_off::text, true);
        PERFORM admissions.prelim_set_rules('PRELIMINARY_SCIENCE', '{"max_sittings": 1}'::jsonb, 'CHECK V446: one sitting');
        SELECT eligibility_status INTO e_max1 FROM admissions.prelim_review WHERE application_id = app;
        PERFORM admissions.prelim_set_rules('PRELIMINARY_SCIENCE', '{"max_sittings": 2}'::jsonb, 'CHECK V446: two sittings again');
        SELECT eligibility_status INTO e_f FROM admissions.prelim_review WHERE application_id = app;
        -- (4) the rest of the form: biodata, the target (a configured one only), the documents of two sittings
        PERFORM set_config('moaum.actor_office', 'applicant', true); PERFORM set_config('moaum.actor_id', acc::text, true);
        PERFORM admissions.prelim_save_biodata(app, '{"home_address":"1 Check Road, Makurdi","state_of_origin":"Benue","lga":"Makurdi","nationality":"Nigerian","kin_name":"Ene Checkv446","kin_relationship":"Mother","kin_mobile":"08031230000"}'::jsonb, 'F');
        BEGIN PERFORM admissions.prelim_set_target(app, prog_pg, NULL); EXCEPTION WHEN check_violation THEN v_bad_target := split_part(SQLERRM, ':', 1); END;
        PERFORM admissions.prelim_set_target(app, prog, NULL);
        INSERT INTO admissions.application_document (id, application_id, kind, filename, content_type, bytes, status)
        SELECT gen_random_uuid(), app, k, lower(k) || '.pdf', 'application/pdf', 100, 'PENDING'
          FROM unnest(ARRAY['PASSPORT', 'PASSPORT_2', 'OLEVEL_STATEMENT', 'OLEVEL_STATEMENT_2', 'LGA_ID', 'BIRTH_CERT']) k;
        -- (5) submitted only while the window is open
        PERFORM set_config('moaum.actor_office', 'ict', true); PERFORM set_config('moaum.actor_id', a_off::text, true);
        PERFORM policy.window_act('PRELIMINARY_SCIENCE_APPLICATION', v_session, NULL, 'CLOSE', NULL, NULL, NULL, false, 'CHECK V446: closed', a_off, 'ict');
        PERFORM set_config('moaum.actor_office', 'applicant', true); PERFORM set_config('moaum.actor_id', acc::text, true);
        BEGIN PERFORM admissions.prelim_submit(app, '127.0.0.1'); EXCEPTION WHEN check_violation THEN v_closed := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_office', 'ict', true); PERFORM set_config('moaum.actor_id', a_off::text, true);
        PERFORM policy.window_act('PRELIMINARY_SCIENCE_APPLICATION', v_session, NULL, 'REOPEN', NULL, NULL, NULL, false, 'CHECK V446: reopened', a_off, 'ict');
        PERFORM set_config('moaum.actor_office', 'applicant', true); PERFORM set_config('moaum.actor_id', acc::text, true);
        v_sub := admissions.prelim_submit(app, '127.0.0.1');
        SELECT submitted_at INTO v_sub_at FROM admissions.application WHERE id = app;
        -- (6) the review: the wrong office refused; documents, then the O'Level, before a recommendation; someone else approves
        PERFORM set_config('moaum.actor_office', 'bursar', true); PERFORM set_config('moaum.actor_id', a_off::text, true);
        BEGIN PERFORM admissions.prelim_act(app, 'START', NULL); EXCEPTION WHEN check_violation THEN v_office := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_office', 'prelim', true);
        PERFORM admissions.prelim_act(app, 'START', NULL);
        BEGIN PERFORM admissions.prelim_act(app, 'RECOMMEND', NULL); EXCEPTION WHEN check_violation THEN v_unver := split_part(SQLERRM, ':', 1); END;
        PERFORM admissions.prelim_review_document(d.id, 'ACCEPTED', NULL) FROM admissions.application_document d WHERE d.application_id = app AND d.superseded_at IS NULL;
        BEGIN PERFORM admissions.prelim_act(app, 'RECOMMEND', NULL); EXCEPTION WHEN check_violation THEN v_olev := split_part(SQLERRM, ':', 1); END;
        PERFORM admissions.prelim_verify_olevel(app, 'VERIFIED', NULL);
        PERFORM admissions.prelim_act(app, 'RECOMMEND', 'meets the entry requirement');
        PERFORM set_config('moaum.actor_office', 'academic', true);
        BEGIN PERFORM admissions.prelim_act(app, 'APPROVE', NULL); EXCEPTION WHEN check_violation THEN v_own := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_id', b_off::text, true);
        PERFORM admissions.prelim_act(app, 'APPROVE', NULL);
        pub := admissions.prelim_publish('PRELIMINARY_SCIENCE', v_session, ARRAY[app]);
        SELECT * INTO st FROM admissions.admission_status(app);
        letter := admissions.issue_admission_letter(app);
        SELECT count(*) INTO notices FROM platform.notice n WHERE n.about_kind = 'application' AND n.about_id = app AND n.template_key LIKE 'PRELIMINARY_SCIENCE%';
        -- (7) kept apart from Post-UTME
        utme_aud := EXISTS (SELECT 1 FROM platform.applicant_window_audience('POST_UTME_REGISTRATION', v_session, NULL, 100000) x WHERE x = app);
        scr := admissions.screening_required(app);
        SELECT count(*) INTO rows_ict FROM admissions.status_checking_rows(v_session, false) x WHERE x.application_id = app;
        SELECT programme_type, source_module, responsible_office INTO cls FROM reporting.payments WHERE reference = v_ref;
        stats := admissions.prelim_stats('PRELIMINARY_SCIENCE', v_session);
        RAISE EXCEPTION 'the V446 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V446: a Preliminary Science applicant registers with no JAMB number for an ordinary application number while the window is open; the route''s application fee is paid before the form opens and no other fee is invented; an awaiting result is refused; the backend reads four credits, at most two sittings and three of the core (remediation for what the completion rule lacks); a target is an existing undergraduate programme; the Office recommends on accepted documents and a verified O''Level, someone else approves, the Academic Office publishes; the letter names the programme and the target as a progression; Post-UTME never takes it up',
        coalesce(c.application_no ~ '^APP/[0-9]{2}/[0-9]{6}$' AND c.jamb_reg_no IS NULL AND c.entry_mode = 'PRELIMINARY' AND c.entry_level = 0 AND c.sex = 'F' AND c.state = 'DRAFT' AND c.jamb_key IS NULL
                 AND v_dup = 'PRELIM_DUPLICATE' AND v_mail = 'DUPLICATE_EMAIL' AND v_first = 'PRELIM_FEE_FIRST'
                 AND v_amt = 5000 AND v_ref = v_ref2 AND v_chk = 'PRELIM_FEE_NOT_CONFIGURED'
                 AND v_await = 'PRELIM_AWAITING_RESULT' AND v_await2 = 'PRELIM_AWAITING_RESULT' AND v_three = 'PRELIM_OLEVEL_SITTINGS'
                 AND e_a = 'ELIGIBLE_WITH_REMEDIATION' AND rem_a = ARRAY['Physics'] AND rem_a_status = 'REQUIRED' AND e_b = 'NOT_ELIGIBLE' AND e_c = 'NOT_ELIGIBLE'
                 AND e_d = 'ELIGIBLE/NOT_REQUIRED/2/5/4' AND v_sitting_word = 'NECO:2,WAEC:1' AND e_max1 = 'NOT_ELIGIBLE' AND e_f = 'ELIGIBLE'
                 AND v_dup_target = 'PRELIM_TARGET_DUPLICATE' AND v_pg_target = 'PRELIM_TARGET_NOT_UNDERGRADUATE' AND v_bad_target = 'PRELIM_TARGET_NOT_OFFERED'
                 AND v_closed = 'APPLICATION_CLOSED' AND v_sub = 'submitted' AND v_sub_at IS NULL
                 AND v_office = 'PRELIM_OFFICE' AND v_unver = 'PRELIM_DOCUMENTS_UNVERIFIED' AND v_olev = 'PRELIM_OLEVEL_UNVERIFIED' AND v_own = 'PRELIM_APPROVE_OWN'
                 AND (pub->>'admitted')::int = 1 AND st.status = 'ADMITTED' AND st.label LIKE '%Preliminary Science%'
                 AND letter.statement->>'admissionRoute' = 'PRELIMINARY_SCIENCE' AND letter.statement->>'degreeType' = 'PRELIMINARY / REMEDIAL'
                 AND letter.statement->>'targetProgramme' = 'B.Sc. CHECK V446 SCIENCE' AND letter.statement->>'targetNote' LIKE '%does not constitute admission%'
                 AND notices >= 4 AND NOT utme_aud AND NOT scr AND rows_ict = 0
                 AND cls.programme_type = 'PRELIMINARY' AND cls.source_module = 'PRELIMINARY_SCIENCE' AND cls.responsible_office = 'prelim'
                 AND (stats->>'admitted')::int >= 1, false),
        format('reg=%s/%s/%s/%s/%s/%s/%s dup=%s/%s first=%s fee=%s/%s/%s await=%s/%s three=%s elig=%s/%s/%s/%s/%s sittings=%s max1=%s/%s target=%s/%s/%s closed=%s sub=%s/%s office=%s unver=%s/%s own=%s pub=%s status=%s/%s letter=%s/%s/%s notices=%s apart=%s/%s/%s class=%s/%s/%s stats=%s',
               c.application_no, c.jamb_reg_no, c.entry_mode, c.entry_level, c.sex, c.state, c.jamb_key, v_dup, v_mail, v_first, v_amt, v_ref = v_ref2, v_chk,
               v_await, v_await2, v_three, e_a, rem_a, rem_a_status, e_b, e_c, e_d || ' ' || coalesce(v_sitting_word, ''), e_max1, e_f, v_dup_target, v_pg_target, v_bad_target,
               v_closed, v_sub, v_sub_at, v_office, v_unver, v_olev, v_own, pub, st.status, st.label,
               letter.statement->>'admissionRoute', letter.statement->>'degreeType', letter.statement->>'targetProgramme', notices, utme_aud, scr, rows_ict,
               cls.programme_type, cls.source_module, cls.responsible_office, stats->>'admitted'));
END $$;

-- ── V448. A faculty's fee lines are copied to another for a session: every faculty-wide live line, as it stands (semester,
--          level, entry mode, indigene, kind, amount), never a programme's own line nor an ended one; only into a faculty with
--          no live line in that session; a second run copies nothing; a student of the receiving faculty is then charged ──
DO $$
DECLARE who uuid := gen_random_uuid(); v_ses text := '9996/9997'; st uuid := gen_random_uuid(); v_prog text; v_ss_prog text;
        n1 int; n2 int; n3 int; n_cm int; n_same int; n_prog int; n_ended int; charged int; stated boolean;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'bursar', true); PERFORM set_config('moaum.reason', 'CHECK V448', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), v_ses, date '9996-10-01', date '9997-08-31') ON CONFLICT (name) DO NOTHING;
        v_ss_prog := (SELECT code FROM ref.programme WHERE faculty_code = 'SS' AND NOT coalesce(archived, false) ORDER BY code LIMIT 1);
        -- Social Sciences for the session: four faculty-wide lines, one programme's own line, one ended line
        INSERT INTO finance.fee_schedule (id, session, item, amount, level, entry_mode, faculty_code, programme_code, ord, semester, indigene, spillover, kind, ended_at) VALUES
            (gen_random_uuid(), v_ses, 'School fees (semester 1)', 85294.86, 200, 'UTME', 'SS', NULL, 1, 1, 'INDIGENE', false, 'FEE', NULL),
            (gen_random_uuid(), v_ses, 'School fees (semester 1)', 112735.00, 200, 'UTME', 'SS', NULL, 1, 1, 'NON_INDIGENE', false, 'FEE', NULL),
            (gen_random_uuid(), v_ses, 'School fees (semester 2)', 36554.94, 200, 'UTME', 'SS', NULL, 2, 2, 'INDIGENE', false, 'FEE', NULL),
            (gen_random_uuid(), v_ses, 'School fees (semester 2)', 48315.00, 200, 'UTME', 'SS', NULL, 2, 2, 'NON_INDIGENE', false, 'FEE', NULL),
            (gen_random_uuid(), v_ses, 'Programme levy', 5000.00, 200, 'UTME', 'SS', v_ss_prog, 3, NULL, NULL, false, 'FEE', NULL),
            (gen_random_uuid(), v_ses, 'Old line', 1.00, 200, 'UTME', 'SS', NULL, 4, NULL, NULL, false, 'FEE', now());
        n1 := finance.copy_faculty_fees('SS', 'CM', v_ses);
        n2 := finance.copy_faculty_fees('SS', 'CM', v_ses);
        SELECT count(*) INTO n_cm FROM finance.fee_schedule WHERE session = v_ses AND faculty_code = 'CM' AND ended_at IS NULL;
        -- each copied line is its Social Sciences line, field for field
        SELECT count(*) INTO n_same FROM finance.fee_schedule c JOIN finance.fee_schedule s
            ON s.session = c.session AND s.faculty_code = 'SS' AND s.programme_code IS NULL AND s.ended_at IS NULL
           AND s.item = c.item AND s.amount = c.amount AND s.level = c.level AND s.entry_mode = c.entry_mode AND s.semester = c.semester
           AND s.indigene = c.indigene AND s.spillover = c.spillover AND s.kind = c.kind AND s.ord = c.ord
         WHERE c.session = v_ses AND c.faculty_code = 'CM' AND c.ended_at IS NULL;
        SELECT count(*) INTO n_prog FROM finance.fee_schedule WHERE session = v_ses AND faculty_code = 'CM' AND programme_code IS NOT NULL;
        SELECT count(*) INTO n_ended FROM finance.fee_schedule WHERE session = v_ses AND faculty_code = 'CM' AND item = 'Old line';
        -- the same faculty, an unknown faculty, a faculty onto itself: nothing
        n3 := finance.copy_faculty_fees('SS', 'SS', v_ses) + finance.copy_faculty_fees('SS', 'NO_SUCH_FACULTY', v_ses);
        -- a 200-level UTME student of the receiving faculty (non-indigene) is charged both semesters
        v_prog := (SELECT code FROM ref.programme WHERE faculty_code = 'CM' AND NOT coalesce(archived, false) AND coalesce(category, '') <> 'POST GRADUATE' ORDER BY code LIMIT 1);
        IF v_prog IS NOT NULL THEN
            INSERT INTO people.student (id, admission_no, matric_no, matriculated_at, surname, other_names, sex, programme_code, entry_mode, entry_session, entry_level, current_level, status, study_mode, state_of_origin)
            VALUES (st, 'MOAUM/ADM/96/004481', NULL, NULL, 'CHECKV448', 'Media Ada', 'F', v_prog, 'UTME', v_ses, 200, 200, 'ADMITTED', 'FULL_TIME', 'Ondo');
            UPDATE finance.fee_setting SET home_state = coalesce(home_state, 'Benue') WHERE id = 1;
            charged := (SELECT count(*) FROM finance.charges(st, v_ses));
            stated := finance.fee_stated(st, v_ses);
        END IF;
        RAISE EXCEPTION 'the V448 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V448: a faculty''s live faculty-wide fee lines are copied to another for a session as they stand, never a programme''s own line nor an ended one, only into a faculty with no line in the session, once; a student of the receiving faculty is then charged',
        coalesce(n1 = 4 AND n2 = 0 AND n_cm = 4 AND n_same = 4 AND n_prog = 0 AND n_ended = 0 AND n3 = 0
                 AND (v_prog IS NULL OR (charged = 2 AND stated)), false),
        format('copied %s then %s | CM lines %s, alike %s, programme %s, ended %s | self/unknown %s | programme %s charged %s stated %s',
               n1, n2, n_cm, n_same, n_prog, n_ended, n3, v_prog, charged, stated));
END $$;


-- ── V447: the live PG students with no fee line stated, counted once per group of alike students ──
-- finance.pg_unstated asks finance.fee_stated once per group of students alike in what it reads (programme, level, entry
-- mode, home-state origin); its count is the per-student count, row for row: here with indigenes and non-indigenes of one
-- programme and level split by an indigene-only PG line, a second level of the programme left unstated, and a second
-- programme stated whole. The block undoes its writes.
DO $$
DECLARE who uuid := gen_random_uuid(); S text := '9947/9948'; pa text; pb text; lvl int; lvl_b int; home text;
        only_grouped int; only_each int; u_pa int; u_pa2 int; u_pb int; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.reason', 'check V447', true);
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        SELECT home_state INTO home FROM finance.fee_setting WHERE id = 1;
        SELECT code, admissions.pg_award_level(pg_award) INTO pa, lvl FROM ref.programme
         WHERE category = 'POST GRADUATE' AND NOT coalesce(archived, false) AND faculty_code IS NOT NULL ORDER BY code LIMIT 1;
        SELECT code, admissions.pg_award_level(pg_award) INTO pb, lvl_b FROM ref.programme
         WHERE category = 'POST GRADUATE' AND NOT coalesce(archived, false) AND faculty_code IS NOT NULL AND code <> pa ORDER BY code LIMIT 1;
        INSERT INTO iam.person (id, staff_number, surname, given_names, email) VALUES (who, 'CHECK/V447/P', 'ZZPGALIKE', 'Invented', NULL);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9947-10-01', date '9948-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at, state_of_origin)
        VALUES (gen_random_uuid(), 'MOAUM/ADM/47/990471', NULL, 'ZZPG447', 'Indigene', pa, 'POSTGRADUATE', S, lvl, lvl, 'ADMITTED', NULL, ' ' || upper(home) || ' '),
               (gen_random_uuid(), 'MOAUM/ADM/47/990472', NULL, 'ZZPG447', 'Indigene Two', pa, 'POSTGRADUATE', S, lvl, lvl, 'ADMITTED', NULL, home),
               (gen_random_uuid(), 'MOAUM/ADM/47/990473', NULL, 'ZZPG447', 'Other State', pa, 'POSTGRADUATE', S, lvl, lvl, 'ADMITTED', NULL, 'Lagos'),
               (gen_random_uuid(), 'MOAUM/ADM/47/990474', NULL, 'ZZPG447', 'No State', pa, 'POSTGRADUATE', S, lvl, lvl, 'ADMITTED', NULL, NULL),
               (gen_random_uuid(), 'MOAUM/ADM/47/990475', NULL, 'ZZPG447', 'Next Level', pa, 'POSTGRADUATE', S, lvl, lvl + 100, 'ADMITTED', NULL, home),
               (gen_random_uuid(), 'MOAUM/ADM/47/990476', NULL, 'ZZPG447', 'Programme B', pb, 'POSTGRADUATE', S, lvl_b, lvl_b, 'ADMITTED', NULL, 'Lagos');
        INSERT INTO finance.fee_schedule (session, item, amount, entry_mode, programme_code, level, indigene) VALUES
            (S, 'Check V447: indigenes of A at the level', 1000, 'POSTGRADUATE', pa, lvl, 'INDIGENE'),
            (S, 'Check V447: all of B', 1000, 'POSTGRADUATE', pb, NULL, NULL);
        -- the grouped count against the per-student count, over every live PG student
        WITH each AS (
            SELECT st.current_level AS level, st.programme_code, p.name AS programme, count(*) AS students
              FROM people.student st JOIN ref.programme p ON p.code = st.programme_code
             WHERE people.is_postgraduate(st.entry_mode, p.category) AND st.status IN ('ADMITTED', 'ACTIVE', 'PROBATION')
               AND NOT finance.fee_stated(st.id, S)
             GROUP BY st.current_level, st.programme_code, p.name),
             grouped AS (SELECT * FROM finance.pg_unstated(S))
        SELECT (SELECT count(*) FROM (SELECT * FROM grouped EXCEPT ALL SELECT * FROM each) x),
               (SELECT count(*) FROM (SELECT * FROM each EXCEPT ALL SELECT * FROM grouped) x)
          INTO only_grouped, only_each;
        SELECT coalesce(sum(students), 0) INTO u_pa FROM finance.pg_unstated(S) WHERE programme_code = pa AND level = lvl;
        SELECT coalesce(sum(students), 0) INTO u_pa2 FROM finance.pg_unstated(S) WHERE programme_code = pa AND level = lvl + 100;
        SELECT coalesce(sum(students), 0) INTO u_pb FROM finance.pg_unstated(S) WHERE programme_code = pb;
        RAISE EXCEPTION 'the V447 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V447 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V447: the live PG students with no fee line stated are counted once per group of students alike in what finance.fee_stated reads (programme, level, entry mode, home-state origin), and the count is the per-student count row for row: indigenes stated by an indigene-only line, the other students of the level and the next level not, a programme stated whole',
        coalesce(only_grouped = 0 AND only_each = 0 AND u_pa = 2 AND u_pa2 = 1 AND u_pb = 0, false),
        format('only grouped=%s only each=%s | A at the level=%s (expected 2: other state, no state) A next level=%s B=%s', only_grouped, only_each, u_pa, u_pa2, u_pb));
END $$;

-- ── V449. An old-portal school-fees payment recorded twice (a whole-session record repeating a per-semester one of the same
--          reference base, amount and day) is withdrawn: its ledger posting reversed, the record kept on the register, the
--          per-semester record untouched; a whole-session record of another amount or another day is not a duplicate; one a
--          refund points at is left and counted; the importer records a semesterless row of the same payment never again ──
DO $$
DECLARE who uuid := gen_random_uuid(); v_ses text := '9998/9999';
        x uuid := gen_random_uuid(); y uuid := gen_random_uuid(); z uuid := gen_random_uuid(); w uuid := gen_random_uuid();
        v_day timestamptz := timestamptz '9998-11-13 00:00:00+01'; v_journal uuid; v_income text;
        pairs_before int; r record; gone boolean; kept boolean; reg record; j_status text; other_kept int; linked_kept boolean; day_kept boolean;
        paid_after numeric; imp record; imp2 record; n_whole int; n_new int;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'bursar', true); PERFORM set_config('moaum.reason', 'CHECK V449', true);
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (who, 'CHK/V449', 'CHECKV449', 'Bursary');
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), v_ses, date '9998-10-01', date '9999-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO people.student (id, admission_no, matric_no, matriculated_at, surname, other_names, sex, programme_code, entry_mode, entry_session, entry_level, current_level, status, study_mode) VALUES
            (x, 'MOAUM/ADM/98/004491', 'MOAUM/CHK/98/4491', now(), 'CHECKV449', 'Twice Ada', 'F', 'C00023', 'UTME', v_ses, 100, 100, 'ACTIVE', 'FULL_TIME'),
            (y, 'MOAUM/ADM/98/004492', 'MOAUM/CHK/98/4492', now(), 'CHECKV449', 'Other Bola', 'M', 'C00023', 'UTME', v_ses, 100, 100, 'ACTIVE', 'FULL_TIME'),
            (z, 'MOAUM/ADM/98/004493', 'MOAUM/CHK/98/4493', now(), 'CHECKV449', 'Refund Chidi', 'M', 'C00023', 'UTME', v_ses, 100, 100, 'ACTIVE', 'FULL_TIME'),
            (w, 'MOAUM/ADM/98/004494', 'MOAUM/CHK/98/4494', now(), 'CHECKV449', 'Day Dayo', 'M', 'C00023', 'UTME', v_ses, 100, 100, 'ACTIVE', 'FULL_TIME');
        -- X: the same payment twice; Y: a whole-session record of another amount; Z: twice, but a refund points at it; W: another day
        INSERT INTO finance.payment_reference (student_id, session, reference, purpose, amount, expires_at, confirmed_at, confirmed_by, channel, receipt_no, note) VALUES
            (x, v_ses, 'MOAUM-LEG-MOAUMCHK984491-9998-9999-S1', 'School fees (legacy) · semester 1', 112735, v_day, v_day, who, 'Legacy', 'LEG-X1', '1 school-fees payment(s), migrated'),
            (x, v_ses, 'MOAUM-LEG-MOAUMCHK984491-9998-9999', 'School fees (legacy)', 112735, v_day, v_day, who, 'Legacy', 'LEG-X', 'Imported from the old portal'),
            (y, v_ses, 'MOAUM-LEG-MOAUMCHK984492-9998-9999-S1', 'School fees (legacy) · semester 1', 112735, v_day, v_day, who, 'Legacy', 'LEG-Y1', NULL),
            (y, v_ses, 'MOAUM-LEG-MOAUMCHK984492-9998-9999', 'School fees (legacy)', 48315, v_day, v_day, who, 'Legacy', 'LEG-Y', NULL),
            (z, v_ses, 'MOAUM-LEG-MOAUMCHK984493-9998-9999-S1', 'School fees (legacy) · semester 1', 112735, v_day, v_day, who, 'Legacy', 'LEG-Z1', NULL),
            (z, v_ses, 'MOAUM-LEG-MOAUMCHK984493-9998-9999', 'School fees (legacy)', 112735, v_day, v_day, who, 'Legacy', 'LEG-Z', NULL),
            (w, v_ses, 'MOAUM-LEG-MOAUMCHK984494-9998-9999-S1', 'School fees (legacy) · semester 1', 112735, v_day, v_day, who, 'Legacy', 'LEG-W1', NULL),
            (w, v_ses, 'MOAUM-LEG-MOAUMCHK984494-9998-9999', 'School fees (legacy)', 112735, v_day + interval '3 days', v_day + interval '3 days', who, 'Legacy', 'LEG-W', NULL);
        INSERT INTO finance.refund (reference, student_id, payer, reason, amount, proposed_by, source_reference)
        VALUES ('CHK-V449-RF', z, 'CHECKV449 Refund Chidi', 'CHECK', 100, who, 'MOAUM-LEG-MOAUMCHK984493-9998-9999');
        -- X's duplicate had reached the ledger
        v_income := finance.gl_income_account(finance.payment_category('School fees (legacy)'));
        v_journal := finance.gl_post(current_date, 'Fee receipt MOAUM-LEG-MOAUMCHK984491-9998-9999', 'AUTO', 'PAYMENT', 'MOAUM-LEG-MOAUMCHK984491-9998-9999',
            jsonb_build_array(jsonb_build_object('account', '1010', 'debit', 112735, 'narration', 'CHECK', 'session', v_ses),
                              jsonb_build_object('account', v_income, 'credit', 112735, 'narration', 'CHECK', 'session', v_ses)));
        pairs_before := (SELECT count(*) FROM finance.legacy_duplicate_pairs() p WHERE p.student_id IN (x, y, z, w));
        SELECT * INTO r FROM finance.withdraw_legacy_duplicates('CHECK V449');
        gone := NOT EXISTS (SELECT 1 FROM finance.payment_reference WHERE reference = 'MOAUM-LEG-MOAUMCHK984491-9998-9999');
        kept := EXISTS (SELECT 1 FROM finance.payment_reference WHERE reference = 'MOAUM-LEG-MOAUMCHK984491-9998-9999-S1');
        SELECT * INTO reg FROM finance.legacy_duplicate_withdrawn WHERE reference = 'MOAUM-LEG-MOAUMCHK984491-9998-9999';
        j_status := (SELECT status FROM finance.gl_journal WHERE id = v_journal);
        other_kept := (SELECT count(*) FROM finance.payment_reference WHERE student_id = y AND session = v_ses);
        linked_kept := EXISTS (SELECT 1 FROM finance.payment_reference WHERE reference = 'MOAUM-LEG-MOAUMCHK984493-9998-9999');
        day_kept := EXISTS (SELECT 1 FROM finance.payment_reference WHERE reference = 'MOAUM-LEG-MOAUMCHK984494-9998-9999');
        paid_after := (SELECT coalesce(sum(amount), 0) FROM finance.payment_reference WHERE student_id = x AND session = v_ses AND confirmed_at IS NOT NULL);
        -- the importer: the same payment without a semester is a duplicate; another amount is recorded
        SELECT * INTO imp FROM finance.import_legacy_payments(jsonb_build_array(
            jsonb_build_object('matric', 'MOAUM/CHK/98/4491', 'session', v_ses, 'amount', '112735', 'paidOn', '9998-11-13', 'purpose', 'SCHOOL FEES')));
        n_whole := (SELECT count(*) FROM finance.payment_reference WHERE reference = 'MOAUM-LEG-MOAUMCHK984491-9998-9999');
        SELECT * INTO imp2 FROM finance.import_legacy_payments(jsonb_build_array(
            jsonb_build_object('matric', 'MOAUM/CHK/98/4491', 'session', v_ses, 'amount', '48315', 'paidOn', '9999-03-02', 'purpose', 'SCHOOL FEES')));
        n_new := (SELECT count(*) FROM finance.payment_reference WHERE reference = 'MOAUM-LEG-MOAUMCHK984491-9998-9999');
        RAISE EXCEPTION 'the V449 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V449: a school-fees payment recorded twice is withdrawn — its ledger posting reversed, the record kept on the register, the per-semester record untouched; another amount, another day or a refund''s record is left; the importer never records the same payment twice again',
        coalesce(pairs_before = 2 AND r.withdrawn >= 1 AND r.ledger_reversed >= 1 AND r.left_linked >= 1
                 AND gone AND kept AND reg.kept_reference = 'MOAUM-LEG-MOAUMCHK984491-9998-9999-S1' AND reg.amount = 112735
                 AND reg.ledger_journal = v_journal AND reg.reversal_journal IS NOT NULL AND j_status = 'REVERSED'
                 AND other_kept = 2 AND linked_kept AND day_kept AND paid_after = 112735
                 AND imp.duplicates = 1 AND imp.cleared = 0 AND n_whole = 0 AND imp2.cleared = 1 AND n_new = 1, false),
        format('pairs %s | withdrawn %s reversed %s left %s | gone %s kept %s register kept=%s journal ok=%s reversal=%s status=%s | Y %s, refund kept %s, other day kept %s | paid %s | import dup=%s cleared=%s whole=%s then cleared=%s whole=%s',
               pairs_before, r.withdrawn, r.ledger_reversed, r.left_linked, gone, kept, reg.kept_reference, reg.ledger_journal = v_journal, reg.reversal_journal IS NOT NULL, j_status,
               other_kept, linked_kept, day_kept, paid_after, imp.duplicates, imp.cleared, n_whole, imp2.cleared, n_new));
END $$;

-- ── V450. The faculties charged another's fees by the University's word are never left without lines: in the current session
--          and every planned one, Communication and Media Studies has lines whenever Social Sciences has (V448), Technology
--          and Industrial Studies whenever Education has (V450); and the copy from Education reaches a TI student ──
DO $$
DECLARE who uuid := gen_random_uuid(); v_ses text := '9990/9991'; st uuid := gen_random_uuid(); v_prog text;
        bare_cm int; bare_ti int; n int; charged int;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'bursar', true); PERFORM set_config('moaum.reason', 'CHECK V450', true);
        -- the standing property, over the sessions the portal charges in
        SELECT count(*) FILTER (WHERE has_ss AND NOT has_cm AND finance.fee_source_of('CM', x.name) IS DISTINCT FROM 'SS'), count(*) FILTER (WHERE has_ed AND NOT has_ti AND finance.fee_source_of('TI', x.name) IS DISTINCT FROM 'ED') INTO bare_cm, bare_ti
          FROM (SELECT a.name,
                       EXISTS (SELECT 1 FROM finance.fee_schedule f WHERE f.session = a.name AND f.faculty_code = 'SS' AND f.programme_code IS NULL AND f.ended_at IS NULL) AS has_ss,
                       EXISTS (SELECT 1 FROM finance.fee_schedule f WHERE f.session = a.name AND f.faculty_code = 'CM' AND f.ended_at IS NULL) AS has_cm,
                       EXISTS (SELECT 1 FROM finance.fee_schedule f WHERE f.session = a.name AND f.faculty_code = 'ED' AND f.programme_code IS NULL AND f.ended_at IS NULL) AS has_ed,
                       EXISTS (SELECT 1 FROM finance.fee_schedule f WHERE f.session = a.name AND f.faculty_code = 'TI' AND f.ended_at IS NULL) AS has_ti
                  FROM policy.academic_session a
                 WHERE a.name = policy.university_current_session() OR a.state = 'PLANNED') x;
        -- the copy from Education reaches a TI student
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), v_ses, date '9990-10-01', date '9991-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO finance.fee_schedule (id, session, item, amount, level, entry_mode, faculty_code, programme_code, ord, semester, indigene, spillover, kind) VALUES
            (gen_random_uuid(), v_ses, 'School fees (semester 1)', 109150.86, 100, 'UTME', 'ED', NULL, 1, 1, NULL, false, 'FEE'),
            (gen_random_uuid(), v_ses, 'School fees (semester 2)', 46779.00, 100, 'UTME', 'ED', NULL, 2, 2, NULL, false, 'FEE');
        n := finance.copy_faculty_fees('ED', 'TI', v_ses);
        v_prog := (SELECT code FROM ref.programme WHERE faculty_code = 'TI' AND NOT coalesce(archived, false) AND coalesce(category, '') <> 'POST GRADUATE' ORDER BY code LIMIT 1);
        IF v_prog IS NOT NULL THEN
            INSERT INTO people.student (id, admission_no, matric_no, matriculated_at, surname, other_names, sex, programme_code, entry_mode, entry_session, entry_level, current_level, status, study_mode)
            VALUES (st, 'MOAUM/ADM/90/004501', NULL, NULL, 'CHECKV450', 'Tech Ada', 'F', v_prog, 'UTME', v_ses, 100, 100, 'ADMITTED', 'FULL_TIME');
            charged := (SELECT count(*) FROM finance.charges(st, v_ses));
        END IF;
        RAISE EXCEPTION 'the V450 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V450: in the current and planned sessions Communication and Media Studies has fee lines (or is charged as Social Sciences by the V451 rule) whenever Social Sciences has, Technology and Industrial Studies (or as Education) whenever Education has; the Education copy reaches a TI student',
        coalesce(bare_cm = 0 AND bare_ti = 0 AND n = 2 AND (v_prog IS NULL OR charged = 2), false),
        format('sessions with SS and no CM: %s, with ED and no TI: %s | copied %s | programme %s charged %s', bare_cm, bare_ti, n, v_prog, charged));
END $$;
-- V452: postgraduate applications are filed under the intake session. On an invented PG calendar (a current session and two
-- planned after it) the intake is the first planned one after the current, and the postgraduate application window reads it;
-- a session the Bursary has stated no PG fees for carries the latest earlier stated ones, its own once stated, and a session
-- earlier than any stated one takes the amounts V202 wrote in. The block undoes its writes.
DO $$
DECLARE who uuid := gen_random_uuid(); v_intake text; v_app text; carried text; stated text; none_yet text; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'pgschool', true);
        PERFORM set_config('moaum.reason', 'check V452', true);
        UPDATE admissions.pg_academic_session SET state = 'CLOSED' WHERE state = 'CURRENT';
        INSERT INTO admissions.pg_academic_session (name, state) VALUES ('9952/9953', 'CURRENT'), ('9953/9954', 'PLANNED'), ('9954/9955', 'PLANNED');
        v_intake := admissions.pg_intake_session();
        v_app := policy.application_session('POSTGRADUATE_APPLICATION');
        INSERT INTO admissions.pg_fee (session, application_fee, acceptance_fee, checking_fee) VALUES ('9952/9953', 11, 22, 3);
        carried := (SELECT application_fee || '/' || acceptance_fee || '/' || checking_fee FROM admissions.pg_fee_rule('9953/9954'));
        INSERT INTO admissions.pg_fee (session, application_fee, acceptance_fee, checking_fee) VALUES ('9953/9954', 12, 23, 4);
        stated := (SELECT application_fee || '/' || acceptance_fee || '/' || checking_fee FROM admissions.pg_fee_rule('9953/9954'));
        RAISE EXCEPTION 'the V452 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V452 check undoes its writes' THEN RAISE; END IF;
    END;
    none_yet := (SELECT application_fee || '/' || acceptance_fee || '/' || checking_fee FROM admissions.pg_fee_rule('0001/0002'));
    PERFORM pg_temp.assert('V452: postgraduate applications are filed under the intake — the first planned PG session after the current — and a session with no PG fees stated carries the latest earlier stated ones',
        coalesce(v_intake = '9953/9954' AND v_app = '9953/9954' AND carried = '11.00/22.00/3.00' AND stated = '12.00/23.00/4.00' AND none_yet = '20000/50000/3000', false),
        format('intake %s, application window %s | carried %s, stated %s, before any %s', v_intake, v_app, carried, stated, none_yet));
END $$;
-- V453: every ICT support agent in service holds the support baseline on every student. An invented person holding the ICT
-- support agent office and never posted reaches any student with exactly the baseline (open the student, course registration,
-- payment support) and the University as scope; taken off the desk (their posting ended) they reach no one; a person
-- without the office gains nothing. The block undoes its writes.
DO $$
DECLARE who uuid := gen_random_uuid(); agent uuid := gen_random_uuid(); stranger uuid := gen_random_uuid(); st uuid := gen_random_uuid();
        v_prog text; q text; sees boolean; caps text[]; words text; sees_off boolean; caps_off text[]; sees_stranger boolean; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'helpdeskhead', true);
        PERFORM set_config('moaum.reason', 'check V453', true);
        v_prog := (SELECT code FROM ref.programme WHERE NOT coalesce(archived, false) AND coalesce(category, '') <> 'POST GRADUATE' ORDER BY code LIMIT 1);
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (st, 'MOAUM/ADM/53/845301', 'MOAUM/CHK/53/045301', 'CHECKBASELINE', 'Student', v_prog, 'UTME', '2082/2083', 100, 100, 'ACTIVE', now());
        INSERT INTO iam.person (id, surname, given_names) VALUES (agent, 'CHECKBASELINE', 'Agent'), (stranger, 'CHECKBASELINE', 'Stranger');
        INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from)
        VALUES (gen_random_uuid(), agent, 'ictagent', 'platform', NULL, 'check V453', who, current_date);
        sees := helpdesk.agent_may_see_student(agent, st);
        caps := helpdesk.agent_capabilities_for(agent, st);
        SELECT s.words INTO words FROM helpdesk.agent_student_scope(agent) s;
        sees_stranger := helpdesk.agent_may_see_student(stranger, st) OR cardinality(helpdesk.agent_capabilities(stranger)) > 0;
        -- taken off the desk: a posting, ended
        SELECT code INTO q FROM helpdesk.queue WHERE active ORDER BY ordinal LIMIT 1;
        INSERT INTO helpdesk.agent_assignment (person_id, queue_code, scope_kind, scope_ref, capabilities, active, effective_to)
        VALUES (agent, q, 'OFFICE', 'bursar', ARRAY['VIEW_STUDENT'], false, current_date);
        sees_off := helpdesk.agent_may_see_student(agent, st);
        caps_off := helpdesk.agent_capabilities(agent);
        RAISE EXCEPTION 'the V453 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V453 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V453: every ICT support agent in service opens any student with the support baseline (the student, course registration, payment support) across the University; taken off the desk, or without the office, no one',
        coalesce(sees AND caps @> helpdesk.agent_baseline() AND helpdesk.agent_baseline() @> caps AND words = 'The University' AND NOT sees_off AND cardinality(caps_off) = 0 AND NOT sees_stranger, false),
        format('sees %s caps %s scope %s | off the desk: sees %s caps %s | no office: %s', sees, caps, words, sees_off, caps_off, sees_stranger));
END $$;

-- ── V451. A faculty charged as another by a standing rule: while it has no full-time fee line of its own in a session, the
--          source faculty's lines reach its undergraduates — never a CCE student — alike in every matcher; once it states its
--          own, they alone apply; a rule never chains nor names itself. The students with no fee stated are listed by group, an
--          open semester with no line counted as missing, and the Bursary is told of a new group once, and again if it reopens ──
DO $$
DECLARE who uuid := gen_random_uuid(); v_ses text := '9990/9991'; st uuid := gen_random_uuid(); cce uuid := gen_random_uuid();
        fa text; fb text; v_prog text; key_prof text;
        gap_missing int[]; un_sem int[]; told1 int; told2 int; told3 int;
        n_rule int; n_cce int; tot numeric; d1 numeric; d2 numeric; stated boolean; sums_ok boolean; gaps_after int;
        own int; src_after text; chain text; self text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'bursar', true); PERFORM set_config('moaum.reason', 'CHECK V451', true);
        INSERT INTO iam.person (id, staff_number, surname, given_names, email, phone) VALUES (who, 'CHK/V451', 'CHECKV451', 'Bursar', 'v451@example.test', '08000004510');
        INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from)
        VALUES (gen_random_uuid(), who, 'bursar', 'institution', NULL, 'CHECK V451', who, current_date);
        -- two faculties no rule names; A with an undergraduate programme
        SELECT p.faculty_code, p.code INTO fa, v_prog FROM ref.programme p
         WHERE NOT coalesce(p.archived, false) AND coalesce(p.category, '') <> 'POST GRADUATE'
           AND p.faculty_code NOT IN (SELECT r.faculty_code FROM finance.faculty_fee_source r UNION SELECT r.source_faculty_code FROM finance.faculty_fee_source r)
         ORDER BY p.faculty_code, p.code LIMIT 1;
        SELECT f.code INTO fb FROM ref.faculty f
         WHERE f.code <> fa AND f.code NOT IN (SELECT r.faculty_code FROM finance.faculty_fee_source r UNION SELECT r.source_faculty_code FROM finance.faculty_fee_source r)
         ORDER BY f.code LIMIT 1;
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), v_ses, date '9990-10-01', date '9991-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO policy.semester (id, session, number, state) VALUES (gen_random_uuid(), v_ses, 1, 'CLOSED'), (gen_random_uuid(), v_ses, 2, 'OPEN')
            ON CONFLICT (session, number) DO UPDATE SET state = excluded.state;
        PERFORM finance.set_faculty_fee_source(fa, fb, NULL, 'CHECK V451');
        -- B states the first semester, and a CCE line
        INSERT INTO finance.fee_schedule (id, session, item, amount, level, entry_mode, faculty_code, programme_code, ord, semester, indigene, spillover, kind) VALUES
            (gen_random_uuid(), v_ses, 'School fees (semester 1)', 100000, 100, 'UTME', fb, NULL, 1, 1, NULL, false, 'FEE'),
            (gen_random_uuid(), v_ses, 'School fees (semester 1)', 70000, NULL, 'CCE', fb, NULL, 1, 1, NULL, false, 'FEE');
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, study_mode, entry_session, entry_level, current_level, status, matriculated_at) VALUES
            (st, 'MOAUM/ADM/90/004511', NULL, 'CHECKV451', 'Rule Ada', v_prog, 'UTME', 'FULL_TIME', v_ses, 100, 100, 'ADMITTED', NULL),
            (cce, 'MOAUM/ADM/90/004512', NULL, 'CHECKV451', 'Evening Bola', v_prog, 'CCE', 'PART_TIME', v_ses, 100, 100, 'ADMITTED', NULL);
        -- the open second semester has no line: listed, the student's page told, the Bursary told once
        gap_missing := (SELECT g.missing FROM finance.fee_gaps(v_ses) g WHERE g.programme_code = v_prog AND g.level = 100 AND g.entry_mode = 'UTME' LIMIT 1);
        un_sem := finance.fee_unstated_semesters(st, v_ses);
        told1 := finance.watch_fee_gaps(v_ses);
        told2 := finance.watch_fee_gaps(v_ses);
        -- the second semester stated: charged both by the rule, every matcher alike; the CCE student reached by none
        INSERT INTO finance.fee_schedule (id, session, item, amount, level, entry_mode, faculty_code, programme_code, ord, semester, indigene, spillover, kind) VALUES
            (gen_random_uuid(), v_ses, 'School fees (semester 2)', 50000, 100, 'UTME', fb, NULL, 2, 2, NULL, false, 'FEE');
        n_rule := (SELECT count(*) FROM finance.charges(st, v_ses));
        n_cce := (SELECT count(*) FROM finance.charges(cce, v_ses));
        tot := finance.session_fee_total(st, v_ses); d1 := finance.due_for_semester(st, v_ses, 1); d2 := finance.due_for_semester(st, v_ses, 2);
        stated := finance.fee_stated(st, v_ses);
        key_prof := (SELECT pr.profile_key FROM finance.fee_profiles() pr WHERE pr.student_id = st);
        sums_ok := (SELECT s.due_before = 100000 AND s.due_upto = 150000 AND s.fee = 150000 FROM finance.fee_sums(v_ses, 2) s WHERE s.profile_key = key_prof);
        gaps_after := (SELECT count(*) FROM finance.fee_gaps(v_ses) g WHERE g.programme_code = v_prog AND g.level = 100 AND g.entry_mode = 'UTME');
        PERFORM finance.watch_fee_gaps(v_ses);
        -- A states its own first semester: the rule waits, A's line alone applies, and the second semester is missing again — told again
        INSERT INTO finance.fee_schedule (id, session, item, amount, level, entry_mode, faculty_code, programme_code, ord, semester, indigene, spillover, kind) VALUES
            (gen_random_uuid(), v_ses, 'School fees (semester 1)', 90000, 100, 'UTME', fa, NULL, 1, 1, NULL, false, 'FEE');
        own := (SELECT count(*) FROM finance.charges(st, v_ses));
        src_after := finance.fee_source_of(fa, v_ses);
        told3 := finance.watch_fee_gaps(v_ses);
        -- a chain, and a faculty charged as itself, refused
        BEGIN
            PERFORM finance.set_faculty_fee_source(fb, fa, NULL, NULL); chain := 'accepted';
        EXCEPTION WHEN check_violation THEN chain := split_part(SQLERRM, ':', 1);
        END;
        BEGIN
            PERFORM finance.set_faculty_fee_source(fa, fa, NULL, NULL); self := 'accepted';
        EXCEPTION WHEN check_violation THEN self := split_part(SQLERRM, ':', 1);
        END;
        RAISE EXCEPTION 'the V451 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V451: a faculty charged as another reads the source''s lines while it has none of its own, alike in every matcher and never for a CCE student; its own lines end the rule; no chain nor self; the unstated open semester listed, and told once and again on reopening',
        coalesce(fa IS NOT NULL AND fb IS NOT NULL
             AND gap_missing = '{2}' AND un_sem = '{2}' AND told1 > 0 AND told2 = 0 AND told3 > 0
             AND n_rule = 2 AND n_cce = 0 AND tot = 150000 AND d1 = 100000 AND d2 = 150000 AND stated AND sums_ok AND gaps_after = 0
             AND own = 1 AND src_after IS NULL AND chain = 'FEE_SOURCE_CHAIN' AND self = 'FEE_SOURCE_SELF', false),
        format('A %s B %s | missing %s, student page %s, told %s/%s/%s | charged %s, CCE %s, total %s, S1 %s, S2 %s, stated %s, sums %s, gaps after %s | own %s, rule after %s | chain %s, self %s',
               fa, fb, gap_missing, un_sem, told1, told2, told3, n_rule, n_cce, tot, d1, d2, stated, sums_ok, gaps_after, own, src_after, chain, self));
END $$;

-- ── V454: a school-fees balance under one naira counts as paid ──
-- A second-semester line stated with kobo (₦53,488.42) paid in whole naira (₦53,488.00): the student is paid in full, owes
-- nothing, the semester clears for course registration, the College report reads fully paid, the Bursary's set-based list
-- agrees, and the session is no arrears in the next one; a shortfall of one naira is still owed and still arrears; the first
-- instalment (half the charge) is likewise met short by kobo; Quickteller is refused a ₦0.42 school-fees reference, and no
-- reference can be raised for kobo. The block undoes its writes.
DO $$
DECLARE who uuid := gen_random_uuid(); S text := '9945/9946'; S2 text := '9946/9947'; prog text; fac text;
        k1 uuid := gen_random_uuid(); k2 uuid := gen_random_uuid(); k3 uuid := gen_random_uuid();
        p1 record; p2 record; p3 record; c1 boolean; c2 boolean; rep text; sfp boolean; arr1 boolean; arr2 boolean;
        cust record; r_new text := 'accepted'; owed numeric; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.reason', 'check V454', true);
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        SELECT code, faculty_code INTO prog, fac FROM ref.programme
         WHERE category = 'UNDER GRADUATE' AND NOT coalesce(archived, false) AND faculty_code IS NOT NULL ORDER BY code LIMIT 1;
        INSERT INTO iam.person (id, staff_number, surname, given_names, email) VALUES (who, 'CHECK/V454/P', 'ZZKOBO', 'Invented', NULL);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9945-10-01', date '9946-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S2, date '9946-10-01', date '9947-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (k1, 'MOAUM/ADM/45/990454', NULL, 'ZZKOBO454', 'Kobo Short', prog, 'UTME', S, 100, 100, 'ADMITTED', NULL),
               (k2, 'MOAUM/ADM/45/990455', NULL, 'ZZKOBO454', 'Naira Short', prog, 'UTME', S, 100, 100, 'ADMITTED', NULL),
               (k3, 'MOAUM/ADM/45/990456', NULL, 'ZZKOBO454', 'Half Paid', prog, 'UTME', S, 100, 100, 'ADMITTED', NULL);
        -- the programme's lines: a first semester in whole naira, a second with kobo; the next session's, so arrears are read
        INSERT INTO finance.fee_schedule (session, item, amount, level, programme_code, semester) VALUES
            (S, 'Check V454: school fees (semester 1)', 100000.00, 100, prog, 1),
            (S, 'Check V454: school fees (semester 2)', 53488.42, 100, prog, 2),
            (S2, 'Check V454: school fees', 1000.00, 100, prog, NULL);
        INSERT INTO finance.payment_reference (student_id, session, reference, purpose, amount, expires_at, confirmed_at, confirmed_by, channel, receipt_no) VALUES
            (k1, S, 'CHK-V454-K1-A', 'School fees ' || S, 100000.00, now() + interval '1 day', now(), who, 'Legacy', 'CHK-RCPT-V454-1A'),
            (k1, S, 'CHK-V454-K1-B', 'School fees ' || S, 53488.00, now() + interval '1 day', now(), who, 'Legacy', 'CHK-RCPT-V454-1B'),
            (k2, S, 'CHK-V454-K2-A', 'School fees ' || S, 100000.00, now() + interval '1 day', now(), who, 'Legacy', 'CHK-RCPT-V454-2A'),
            (k2, S, 'CHK-V454-K2-B', 'School fees ' || S, 53487.42, now() + interval '1 day', now(), who, 'Legacy', 'CHK-RCPT-V454-2B'),
            (k3, S, 'CHK-V454-K3-A', 'School fees ' || S, 76744.00, now() + interval '1 day', now(), who, 'Legacy', 'CHK-RCPT-V454-3A');
        SELECT * INTO p1 FROM finance.position(k1, S);
        SELECT * INTO p2 FROM finance.position(k2, S);
        SELECT * INTO p3 FROM finance.position(k3, S);
        c1 := finance.semester_cleared(k1, S, 2);
        c2 := finance.semester_cleared(k2, S, 2);
        SELECT status INTO rep FROM finance.payment_position(k1, S, NULL);
        SELECT f.paid_in_full INTO sfp FROM finance.session_fee_positions(S) f WHERE f.student_id = k1;
        SELECT has_arrears INTO arr1 FROM finance.position(k1, S2);
        SELECT has_arrears INTO arr2 FROM finance.position(k2, S2);
        -- a ₦0.42 school-fees reference, as one was raised before: Quickteller is told it pays nothing
        INSERT INTO finance.payment_reference (student_id, session, reference, purpose, amount, expires_at) VALUES
            (k1, S, 'MOAUM-FEE-990454-0042', 'School fees ' || S, 0.42, now() + interval '1 day');
        SELECT * INTO cust FROM finance.paydirect_customer('MOAUM-FEE-990454-0042');
        BEGIN PERFORM finance.new_reference(k1, S, 0.42, 'School fees ' || S); EXCEPTION WHEN check_violation THEN r_new := SQLERRM; END;
        owed := finance.fee_owed(53488.42, 53488.00) + finance.fee_owed(53488.42, 53487.42);
        RAISE EXCEPTION 'the V454 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V454 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V454: a school-fees balance under one naira counts as paid — paid in full, nothing owed, the semester cleared, the College report and the Bursary''s list agree, no arrears after; one naira short is still owed and arrears; half the charge short by kobo is the first instalment; Quickteller is refused a ₦0.42 school-fees reference and none can be raised',
        coalesce(p1.paid_in_full AND p1.balance = 0 AND p1.instalments_paid = 2 AND c1 AND rep = 'FULLY_PAID' AND sfp AND NOT arr1
                 AND NOT p2.paid_in_full AND p2.balance = 1.00 AND NOT c2 AND arr2
                 AND p3.instalments_paid = 1 AND NOT p3.paid_in_full
                 AND NOT cust.valid AND cust.why LIKE 'Nothing to pay%' AND r_new <> 'accepted' AND owed = 1.00, false),
        format('kobo: full=%s bal=%s inst=%s cleared=%s report=%s list=%s arrears=%s | naira: full=%s bal=%s cleared=%s arrears=%s | half: inst=%s full=%s | quickteller=%s/%s | new=%s | owed=%s',
               p1.paid_in_full, p1.balance, p1.instalments_paid, c1, rep, sfp, arr1, p2.paid_in_full, p2.balance, c2, arr2,
               p3.instalments_paid, p3.paid_in_full, cust.valid, cust.why, left(r_new, 60), owed));
END $$;

-- ── V455. A postgraduate student keeps a postgraduate level: either old-portal upload files a postgraduate programme's row
--          POSTGRADUATE at 700/800/900, never lowers a postgraduate student below 700, and re-files one wrongly filed as
--          undergraduate; an undergraduate row keeps the 100–600 rule; the repair restores a postgraduate programme's student
--          left at 100; their level in any session is their own ──
DO $$
DECLARE who uuid := gen_random_uuid(); v_prog text; v_rule int; v_ug text; st uuid; st2 uuid := gen_random_uuid(); v_ses text;
        a_mode text; a_el int; a_cl int; b_cl int; c_cl int; d_mode text; d_cl int; ug_mode text; ug_cl int;
        r_n int; r_mode int; r_lvl int; e_mode text; e_cl int; lvl_in int;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'registrar', true); PERFORM set_config('moaum.reason', 'CHECK V455', true);
        v_prog := (SELECT code FROM ref.programme WHERE category = 'POST GRADUATE' AND NOT coalesce(archived, false) ORDER BY code LIMIT 1);
        v_rule := people.pg_level_of(v_prog);
        v_ug := (SELECT code FROM ref.programme WHERE category = 'UNDER GRADUATE' AND NOT coalesce(archived, false) ORDER BY code LIMIT 1);
        v_ses := policy.university_current_session();
        -- a new row of a postgraduate programme with no level: POSTGRADUATE at the programme's level
        PERFORM people.import_students_rows(jsonb_build_array(jsonb_build_object('matric', 'CHK/PG/PHD/55/0455', 'name', 'CHECKV455, Ada', 'programme', v_prog)));
        SELECT id, entry_mode, entry_level, current_level INTO st, a_mode, a_el, a_cl FROM people.student WHERE matric_no = 'CHK/PG/PHD/55/0455';
        -- at 900, as the postgraduate register would set it; the register again with the old 100, then the biodata upload blank: kept
        UPDATE people.student SET entry_level = 900, current_level = 900 WHERE id = st;
        PERFORM people.import_students_rows(jsonb_build_array(jsonb_build_object('matric', 'CHK/PG/PHD/55/0455', 'name', 'CHECKV455, Ada', 'programme', v_prog, 'level', '100')));
        b_cl := (SELECT current_level FROM people.student WHERE id = st);
        PERFORM people.import_biography_rows(jsonb_build_array(jsonb_build_object('matric', 'CHK/PG/PHD/55/0455', 'name', 'CHECKV455, Ada', 'programme', v_prog)));
        c_cl := (SELECT current_level FROM people.student WHERE id = st);
        -- a student of the postgraduate programme left as UTME at 100 is re-filed POSTGRADUATE at its level by the next upload
        INSERT INTO people.student (id, matric_no, surname, other_names, programme_code, entry_mode, study_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (st2, 'CHK/PG/MSC/55/0456', 'CHECKV455', 'Bola', v_prog, 'UTME', 'FULL_TIME', v_ses, 100, 100, 'ACTIVE', now());
        PERFORM people.import_biography_rows(jsonb_build_array(jsonb_build_object('matric', 'CHK/PG/MSC/55/0456', 'name', 'CHECKV455, Bola', 'programme', v_prog, 'level', '100')));
        SELECT entry_mode, current_level INTO d_mode, d_cl FROM people.student WHERE id = st2;
        -- an undergraduate row keeps the undergraduate rule: a level outside 100–600 is the entry level
        PERFORM people.import_students_rows(jsonb_build_array(jsonb_build_object('matric', 'CHK/UG/ABC/55/0457', 'name', 'CHECKV455, Chi', 'programme', v_ug, 'level', '900')));
        SELECT entry_mode, current_level INTO ug_mode, ug_cl FROM people.student WHERE matric_no = 'CHK/UG/ABC/55/0457';
        -- the repair: the postgraduate student left as UTME at 100 is restored to the programme's level
        UPDATE people.student SET entry_mode = 'UTME', entry_level = 100, current_level = 100 WHERE id = st;
        SELECT * INTO r_n, r_mode, r_lvl FROM people.repair_postgraduate_levels();
        SELECT entry_mode, current_level INTO e_mode, e_cl FROM people.student WHERE id = st;
        lvl_in := people.level_in(st, v_ses);
        RAISE EXCEPTION 'the V455 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V455: an old-portal upload files a postgraduate programme''s row POSTGRADUATE at 700/800/900 and never lowers one below 700; the undergraduate rule unchanged; the repair restores one left at 100; a postgraduate''s level in a session is their own',
        coalesce(v_prog IS NOT NULL AND v_rule IN (700, 800, 900)
             AND a_mode = 'POSTGRADUATE' AND a_el = v_rule AND a_cl = v_rule AND b_cl = 900 AND c_cl = 900
             AND d_mode = 'POSTGRADUATE' AND d_cl = v_rule AND ug_mode = 'UTME' AND ug_cl = 100
             AND r_n >= 1 AND r_mode >= 1 AND r_lvl >= 1 AND e_mode = 'POSTGRADUATE' AND e_cl = v_rule AND lvl_in = v_rule, false),
        format('programme %s rule %s | new %s/%s/%s | kept %s, %s | re-filed %s %s | undergraduate %s %s | repair %s/%s/%s -> %s %s | level_in %s',
               v_prog, v_rule, a_mode, a_el, a_cl, b_cl, c_cl, d_mode, d_cl, ug_mode, ug_cl, r_n, r_mode, r_lvl, e_mode, e_cl, lvl_in));
END $$;
-- V456: every ICT support agent in service reaches JUPEB records with the support baseline. An invented person holding the ICT
-- support agent office and never posted reaches JUPEB records with exactly the baseline; taken off the desk (their posting
-- ended) they reach none and hold nothing there; a person without the office gains nothing. The block undoes its writes.
DO $$
DECLARE who uuid := gen_random_uuid(); agent uuid := gen_random_uuid(); stranger uuid := gen_random_uuid();
        q text; reach boolean; caps text[]; reach_off boolean; caps_off text[]; reach_stranger boolean; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'helpdeskhead', true);
        PERFORM set_config('moaum.reason', 'check V456', true);
        INSERT INTO iam.person (id, surname, given_names) VALUES (agent, 'CHECKJUPEBBASE', 'Agent'), (stranger, 'CHECKJUPEBBASE', 'Stranger');
        INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from)
        VALUES (gen_random_uuid(), agent, 'ictagent', 'platform', NULL, 'check V456', who, current_date);
        reach := helpdesk.agent_reaches_jupeb(agent);
        caps := helpdesk.agent_jupeb_capabilities(agent);
        reach_stranger := helpdesk.agent_reaches_jupeb(stranger) OR cardinality(helpdesk.agent_jupeb_capabilities(stranger)) > 0;
        SELECT code INTO q FROM helpdesk.queue WHERE active AND code <> 'JUPEB_SUPPORT' ORDER BY ordinal LIMIT 1;
        INSERT INTO helpdesk.agent_assignment (person_id, queue_code, scope_kind, scope_ref, capabilities, active, effective_to)
        VALUES (agent, q, 'OFFICE', 'bursar', ARRAY['VIEW_STUDENT'], false, current_date);
        reach_off := helpdesk.agent_reaches_jupeb(agent);
        caps_off := helpdesk.agent_jupeb_capabilities(agent);
        RAISE EXCEPTION 'the V456 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V456 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V456: every ICT support agent in service reaches JUPEB records with the support baseline (the record and its payments); taken off the desk, or without the office, none',
        coalesce(reach AND caps @> helpdesk.agent_baseline() AND helpdesk.agent_baseline() @> caps AND NOT reach_off AND cardinality(caps_off) = 0 AND NOT reach_stranger, false),
        format('reach %s caps %s | off the desk: reach %s caps %s | no office: %s', reach, caps, reach_off, caps_off, reach_stranger));
END $$;

-- ── V458. A postgraduate student's registrations and enrolments at their own level: one written at 100 (as a registration
--          made while V455's fault held) is set to the student's level, an undergraduate's is left as it is, and the
--          postgraduate's level in that session reads their own ──
DO $$
DECLARE who uuid := gen_random_uuid(); st uuid := gen_random_uuid(); ug uuid := gen_random_uuid();
        v_prog text; v_ug_prog text; v_ses text; r_reg int; r_enr int; pg_reg int; pg_enr int; ug_reg int; lvl int;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'registrar', true); PERFORM set_config('moaum.reason', 'CHECK V458', true);
        v_prog := (SELECT code FROM ref.programme WHERE category = 'POST GRADUATE' AND NOT coalesce(archived, false) ORDER BY code LIMIT 1);
        v_ug_prog := (SELECT code FROM ref.programme WHERE category = 'UNDER GRADUATE' AND NOT coalesce(archived, false) ORDER BY code LIMIT 1);
        v_ses := policy.university_current_session();
        INSERT INTO people.student (id, matric_no, surname, other_names, programme_code, entry_mode, study_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (st, 'CHK/PG/PHD/58/0458', 'CHECKV458', 'Ada', v_prog, 'POSTGRADUATE', 'FULL_TIME', v_ses, 900, 900, 'ACTIVE', now()),
               (ug, 'CHK/UG/ABC/58/0459', 'CHECKV458', 'Bola', v_ug_prog, 'UTME', 'FULL_TIME', v_ses, 100, 200, 'ACTIVE', now());
        INSERT INTO registration.course_registration (id, student_id, session, semester, level, status)
        VALUES (gen_random_uuid(), st, v_ses, 1, 100, 'DRAFT'), (gen_random_uuid(), ug, v_ses, 1, 200, 'DRAFT');
        INSERT INTO people.enrolment (id, student_id, session, level) VALUES (gen_random_uuid(), st, v_ses, 100), (gen_random_uuid(), ug, v_ses, 200);
        SELECT * INTO r_reg, r_enr FROM people.repair_postgraduate_session_levels();
        pg_reg := (SELECT level FROM registration.course_registration WHERE student_id = st AND session = v_ses AND semester = 1);
        pg_enr := (SELECT level FROM people.enrolment WHERE student_id = st AND session = v_ses);
        ug_reg := (SELECT level FROM registration.course_registration WHERE student_id = ug AND session = v_ses AND semester = 1);
        lvl := people.level_in(st, v_ses, 1);
        RAISE EXCEPTION 'the V458 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V458: a postgraduate student''s registration and enrolment written at 100 are set to their own level, an undergraduate''s left, and their level in the session reads their own',
        coalesce(r_reg >= 1 AND r_enr >= 1 AND pg_reg = 900 AND pg_enr = 900 AND ug_reg = 200 AND lvl = 900, false),
        format('repaired %s/%s | postgraduate registration %s enrolment %s | undergraduate %s | level_in %s', r_reg, r_enr, pg_reg, pg_enr, ug_reg, lvl));
END $$;

-- ── V459. A register upload changes a level only when the file states one, and its preview says what it would do: a blank
--          level (or the old 100 for a doctorate) leaves an undergraduate's level and a PhD's 900 as they stand — the
--          postgraduate upload no longer sets a flat 800 — a stated level changes it; refused rows and new students counted ──
DO $$
DECLARE who uuid := gen_random_uuid(); ug uuid := gen_random_uuid(); pg uuid := gen_random_uuid();
        v_ug_prog text; v_pg_prog text; v_ses text; f1 jsonb; f2 jsonb; f3 jsonb; f4 jsonb;
        p1 jsonb; p2 jsonb; p3 jsonb; p4 jsonb; ug1 int; pg1 int; new1 boolean; ug2 int; pg3 int; pg4 int;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'registrar', true); PERFORM set_config('moaum.reason', 'CHECK V459', true);
        v_ug_prog := (SELECT code FROM ref.programme WHERE category = 'UNDER GRADUATE' AND NOT coalesce(archived, false) ORDER BY code LIMIT 1);
        v_pg_prog := (SELECT code FROM ref.programme WHERE category = 'POST GRADUATE' AND NOT coalesce(archived, false) ORDER BY code LIMIT 1);
        v_ses := policy.university_current_session();
        INSERT INTO people.student (id, matric_no, surname, other_names, programme_code, entry_mode, study_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (ug, 'CHK/UG/ABC/59/0460', 'CHECKV459', 'Ada', v_ug_prog, 'UTME', 'FULL_TIME', v_ses, 100, 300, 'ACTIVE', now()),
               (pg, 'CHK/PG/PHD/59/0461', 'CHECKV459', 'Bola', v_pg_prog, 'POSTGRADUATE', 'FULL_TIME', v_ses, 900, 900, 'ACTIVE', now());
        -- the Students register: the undergraduate with no level, the PhD with the old 100, a bad number, an unknown programme, a new student
        f1 := jsonb_build_array(
            jsonb_build_object('matric', 'CHK/UG/ABC/59/0460', 'surname', 'CHECKV459', 'otherNames', 'Ada', 'programme', v_ug_prog, 'level', ''),
            jsonb_build_object('matric', 'CHK/PG/PHD/59/0461', 'surname', 'CHECKV459', 'otherNames', 'Bola', 'programme', v_pg_prog, 'level', '100'),
            jsonb_build_object('matric', 'NOT A NUMBER', 'surname', 'X'),
            jsonb_build_object('matric', 'CHK/UG/ABC/59/0462', 'surname', 'CHECKV459', 'programme', 'NO SUCH PROGRAMME'),
            jsonb_build_object('matric', 'CHK/UG/ABC/59/0463', 'surname', 'CHECKV459', 'otherNames', 'Chi', 'programme', v_ug_prog, 'level', '100'));
        p1 := people.preview_register_upload('students', f1);
        PERFORM people.import_students_rows(f1);
        ug1 := (SELECT current_level FROM people.student WHERE id = ug);
        pg1 := (SELECT current_level FROM people.student WHERE id = pg);
        new1 := EXISTS (SELECT 1 FROM people.student WHERE matric_no = 'CHK/UG/ABC/59/0463');
        -- a stated level changes the undergraduate's: previewed as raised, then made
        f2 := jsonb_build_array(jsonb_build_object('matric', 'CHK/UG/ABC/59/0460', 'surname', 'CHECKV459', 'otherNames', 'Ada', 'programme', v_ug_prog, 'level', '400'));
        p2 := people.preview_register_upload('students', f2);
        PERFORM people.import_students_rows(f2);
        ug2 := (SELECT current_level FROM people.student WHERE id = ug);
        -- the postgraduate upload with no level leaves the PhD at 900; one stating 800 lowers them, previewed as lowered
        f3 := jsonb_build_array(jsonb_build_object('matric', 'CHK/PG/PHD/59/0461', 'surname', 'CHECKV459', 'otherNames', 'Bola', 'programme', v_pg_prog));
        p3 := people.preview_register_upload('postgraduate', f3);
        PERFORM people.import_postgraduate(f3);
        pg3 := (SELECT current_level FROM people.student WHERE id = pg);
        f4 := jsonb_build_array(jsonb_build_object('matric', 'CHK/PG/PHD/59/0461', 'surname', 'CHECKV459', 'otherNames', 'Bola', 'programme', v_pg_prog, 'level', '800'));
        p4 := people.preview_register_upload('postgraduate', f4);
        PERFORM people.import_postgraduate(f4);
        pg4 := (SELECT current_level FROM people.student WHERE id = pg);
        RAISE EXCEPTION 'the V459 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V459: a register upload changes a level only when the file states one (never a PhD to 800 or 100), and its preview counts the rows, refusals, new students and each change it then makes',
        coalesce((p1->>'rows')::int = 5 AND (p1->>'badNumber')::int = 1 AND (p1->>'noProgramme')::int = 1 AND (p1->>'newStudents')::int = 1
             AND (p1->>'existing')::int = 2 AND (p1->>'unchanged')::int = 2 AND jsonb_array_length(p1->'changes') = 0
             AND ug1 = 300 AND pg1 = 900 AND new1
             AND (p2->>'levelRaised')::int = 1 AND p2->'changes'->0->>'from' = '300' AND p2->'changes'->0->>'to' = '400' AND ug2 = 400
             AND jsonb_array_length(p3->'changes') = 0 AND pg3 = 900
             AND (p4->>'levelLowered')::int = 1 AND p4->'changes'->0->>'to' = '800' AND pg4 = 800, false),
        format('students file: %s | kept %s/%s new %s | stated: %s -> %s | postgraduate blank: %s -> %s | stated 800: %s -> %s',
               p1 - 'changes', ug1, pg1, new1, p2->'changes', ug2, p3->'changes', pg3, p4->'changes', pg4));
END $$;
-- V460: a course's units per programme, and a change is the department's that sees it. An invented 3-unit course is taken by
-- a programme of its own department, by another department's programme at 2 units of its own, and by a third department's
-- programme at the course's units. The second programme's change reaches its unscored student at once and no one else; a
-- student already scored keeps the units examined (on a class of their own since V464, which holds a whole examined class). A change of the course's own units (3 → 4) reaches only its own
-- department's programme; the third department's programme keeps 3, pinned on its binding. The block undoes its writes.
DO $$
DECLARE who uuid := gen_random_uuid(); v_dept text; p1 text; p2 text; p4 text; v_ses text := '9460/9461'; v_off uuid := gen_random_uuid(); v_sheet uuid := gen_random_uuid();
        v_off3 uuid := gen_random_uuid();
        s1 uuid := gen_random_uuid(); s2 uuid := gen_random_uuid(); s3 uuid := gen_random_uuid(); s4 uuid := gen_random_uuid();
        r1 uuid := gen_random_uuid(); r2 uuid := gen_random_uuid(); r3 uuid := gen_random_uuid(); r4 uuid := gen_random_uuid();
        u_p1 int; u_p2 int; e1_a int; e2_a int; e3_a int; menu_p2 int; e1_b int; e2_b int; e4_b int; pinned int; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        PERFORM set_config('moaum.reason', 'check V460', true);
        SELECT p.dept_code, p.code INTO v_dept, p1 FROM ref.programme p
         WHERE NOT coalesce(p.archived, false) AND coalesce(p.category, '') <> 'POST GRADUATE' AND p.dept_code IS NOT NULL ORDER BY p.code LIMIT 1;
        SELECT p.code INTO p2 FROM ref.programme p WHERE NOT coalesce(p.archived, false) AND coalesce(p.category, '') <> 'POST GRADUATE'
           AND p.dept_code IS NOT NULL AND p.dept_code <> v_dept ORDER BY p.code LIMIT 1;
        SELECT p.code INTO p4 FROM ref.programme p WHERE NOT coalesce(p.archived, false) AND coalesce(p.category, '') <> 'POST GRADUATE'
           AND p.dept_code IS NOT NULL AND p.dept_code <> v_dept AND p.code <> p2 ORDER BY p.code LIMIT 1;
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), v_ses, date '9460-10-01', date '9461-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state) VALUES ('ZZU 101', 'Units per programme', 3, 1, 100, v_dept, 'Core', 'LIVE');
        INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES ('ZZU 101', p1, 100, 'Core'), ('ZZU 101', p2, 100, 'Borrowed'), ('ZZU 101', p4, 100, 'Borrowed');
        INSERT INTO catalogue.offering (id, course_code, session, semester) VALUES (v_off, 'ZZU 101', v_ses, 1), (v_off3, 'ZZU 101', v_ses, 2);
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status) VALUES
          (s1, 'MOAUM/ADM/60/946001', 'CHECKUNITS', 'One', p1, 'UTME', v_ses, 100, 100, 'ADMITTED'),
          (s2, 'MOAUM/ADM/60/946002', 'CHECKUNITS', 'Two', p2, 'UTME', v_ses, 100, 100, 'ADMITTED'),
          (s3, 'MOAUM/ADM/60/946003', 'CHECKUNITS', 'Three', p2, 'UTME', v_ses, 100, 100, 'ADMITTED'),
          (s4, 'MOAUM/ADM/60/946004', 'CHECKUNITS', 'Four', p4, 'UTME', v_ses, 100, 100, 'ADMITTED');
        INSERT INTO registration.course_registration (id, student_id, session, semester, level) VALUES
          (r1, s1, v_ses, 1, 100), (r2, s2, v_ses, 1, 100), (r3, s3, v_ses, 2, 100), (r4, s4, v_ses, 1, 100);
        INSERT INTO registration.entry (registration_id, offering_id, units, entry_type) VALUES
          (r1, v_off, 3, 'CURRENT'), (r2, v_off, 3, 'CURRENT'), (r3, v_off3, 3, 'CURRENT'), (r4, v_off, 3, 'CURRENT');
        -- the third student is already scored, on a class of their own
        INSERT INTO assessment.score_sheet (id, offering_id) VALUES (v_sheet, v_off3);
        INSERT INTO assessment.score (sheet_id, student_id, ca, exam) VALUES (v_sheet, s3, 20, 40);
        -- the second department's programme takes the course at 2 units
        UPDATE catalogue.course_offer SET units = 2 WHERE course_code = 'ZZU 101' AND programme_code = p2 AND level = 100;
        u_p1 := catalogue.units_for('ZZU 101', p1, 100);
        u_p2 := catalogue.units_for('ZZU 101', p2, 100);
        SELECT units INTO e1_a FROM registration.entry WHERE registration_id = r1;
        SELECT units INTO e2_a FROM registration.entry WHERE registration_id = r2;
        SELECT units INTO e3_a FROM registration.entry WHERE registration_id = r3;
        menu_p2 := (SELECT m.units FROM registration.student_menu(s2, v_ses, 1) m WHERE m.course_code = 'ZZU 101');
        -- the course's own units change, on its page: its own department's programme follows; the others keep theirs
        UPDATE catalogue.course SET units = 4 WHERE code = 'ZZU 101';
        SELECT units INTO e1_b FROM registration.entry WHERE registration_id = r1;
        SELECT units INTO e2_b FROM registration.entry WHERE registration_id = r2;
        SELECT units INTO e4_b FROM registration.entry WHERE registration_id = r4;
        SELECT units INTO pinned FROM catalogue.course_offer WHERE course_code = 'ZZU 101' AND programme_code = p4 AND level = 100;
        RAISE EXCEPTION 'the V460 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V460 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V460: a course''s units are per programme and a change is the department''s that sees it — a programme''s own units reach only its unscored students; the course''s own change only its department''s programmes, another department''s kept and pinned; a scored student keeps the units examined',
        coalesce(u_p1 = 3 AND u_p2 = 2 AND e1_a = 3 AND e2_a = 2 AND e3_a = 3 AND (menu_p2 IS NULL OR menu_p2 = 2)
                 AND e1_b = 4 AND e2_b = 2 AND e4_b = 3 AND pinned = 3, false),
        format('units_for %s/%s | programme change: own dept %s, other %s, scored %s, menu %s | course change: own dept %s, own units %s, third dept %s pinned %s',
               u_p1, u_p2, e1_a, e2_a, e3_a, menu_p2, e1_b, e2_b, e4_b, pinned));
END $$;

-- ── V457: students with no fee stated, the Bursary told by SMS as well ──
-- A live undergraduate of a session whose open semester has no fee line: the watch tells a Bursary office holder by
-- e-mail, on the portal and by SMS, on the phone on their staff record; read again with nothing new, it tells nobody.
-- The block undoes its writes.
DO $$
DECLARE who uuid := gen_random_uuid(); bur uuid := gen_random_uuid(); st uuid := gen_random_uuid(); v_ses text := '9943/9944'; v_prog text;
        told1 int; told2 int; chans text; sms_to text; sms_body text; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.reason', 'check V457', true);
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        SELECT p.code INTO v_prog FROM ref.programme p
         WHERE NOT coalesce(p.archived, false) AND coalesce(p.category, '') <> 'POST GRADUATE' AND p.faculty_code IS NOT NULL
           AND p.faculty_code NOT IN (SELECT r.faculty_code FROM finance.faculty_fee_source r)
         ORDER BY p.code LIMIT 1;
        INSERT INTO iam.person (id, staff_number, surname, given_names, email, phone) VALUES
            (who, 'CHECK/V457/P', 'ZZFEEGAPSMS', 'Invented', NULL, NULL),
            (bur, 'CHECK/V457/B', 'ZZFEEGAPSMS', 'Bursar', 'v457.bursar@example.test', '08000004570');
        INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from)
        VALUES (gen_random_uuid(), bur, 'bursar', 'institution', NULL, 'CHECK V457', who, current_date);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), v_ses, date '9943-10-01', date '9944-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO policy.semester (id, session, number, state) VALUES (gen_random_uuid(), v_ses, 1, 'OPEN')
            ON CONFLICT (session, number) DO UPDATE SET state = excluded.state;
        -- one line of the session's, for a level nobody here is at: the session is on the fee schedule, the student's group is not
        INSERT INTO finance.fee_schedule (session, item, amount, level, semester) VALUES (v_ses, 'Check V457: another level', 1000, 900, 1);
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, study_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (st, 'MOAUM/ADM/43/004571', NULL, 'CHECKV457', 'No Fee', v_prog, 'UTME', 'FULL_TIME', v_ses, 100, 100, 'ADMITTED', NULL);
        told1 := finance.watch_fee_gaps(v_ses);
        told2 := finance.watch_fee_gaps(v_ses);
        SELECT string_agg(DISTINCT n.channel, ',' ORDER BY n.channel) INTO chans
          FROM platform.notice n WHERE n.template_key = 'FEE_GAPS' AND n.about_kind = 'person' AND n.about_id = bur AND n.event_key LIKE 'fee-gaps:' || v_ses || ':%';
        SELECT n.recipient, n.body INTO sms_to, sms_body
          FROM platform.notice n WHERE n.template_key = 'FEE_GAPS' AND n.about_id = bur AND n.channel = 'SMS' AND n.event_key LIKE 'fee-gaps:' || v_ses || ':%' LIMIT 1;
        RAISE EXCEPTION 'the V457 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V457 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V457: students with no fee stated — the Bursary told by e-mail, on the portal and by SMS on the phone of their staff record, and once',
        coalesce(v_prog IS NOT NULL AND told1 > 0 AND told2 = 0 AND chans = 'EMAIL,PORTAL,SMS' AND sms_to LIKE '%4570' AND sms_body LIKE '%no school fee stated for ' || v_ses || '%', false),
        format('told %s then %s | channels %s | sms to %s: %s', told1, told2, chans, sms_to, left(sms_body, 90)));
END $$;

-- ── V461. A semester whose fees are not stated is not registered for, and the gap sheet comes back as lines: with the first
--          semester's line stated and the open second semester's not, the second-semester registration is refused
--          (REG_SEMESTER_FEES_NOT_STATED) and the semester never reads as cleared, paid or not; the filled sheet adds the line (once — again, nothing twice), leaves out a blank
--          amount and an unknown programme, and never gives a faculty charged as another a line of its own ──
DO $$
DECLARE who uuid := gen_random_uuid(); st uuid := gen_random_uuid(); reg uuid := gen_random_uuid(); v_ses text := '9990/9991';
        fa text; fb text; v_prog text; unstated int[]; refused1 text; refused2 text; a1 record; a2 record; a3 record; src_after text;
        cleared_before boolean; cleared_after boolean;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'bursar', true); PERFORM set_config('moaum.reason', 'CHECK V461', true);
        -- two faculties no rule names; A with an undergraduate programme, A to be charged as B
        SELECT p.faculty_code, p.code INTO fa, v_prog FROM ref.programme p
         WHERE NOT coalesce(p.archived, false) AND coalesce(p.category, '') <> 'POST GRADUATE'
           AND p.faculty_code NOT IN (SELECT r.faculty_code FROM finance.faculty_fee_source r UNION SELECT r.source_faculty_code FROM finance.faculty_fee_source r)
         ORDER BY p.faculty_code, p.code LIMIT 1;
        SELECT f.code INTO fb FROM ref.faculty f
         WHERE f.code <> fa AND f.code NOT IN (SELECT r.faculty_code FROM finance.faculty_fee_source r UNION SELECT r.source_faculty_code FROM finance.faculty_fee_source r)
         ORDER BY f.code LIMIT 1;
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), v_ses, date '9990-10-01', date '9991-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO policy.semester (id, session, number, state) VALUES (gen_random_uuid(), v_ses, 1, 'CLOSED'), (gen_random_uuid(), v_ses, 2, 'OPEN')
            ON CONFLICT (session, number) DO UPDATE SET state = excluded.state;
        -- the student's programme has its first-semester line, not its second
        INSERT INTO finance.fee_schedule (id, session, item, amount, level, entry_mode, faculty_code, programme_code, ord, semester, indigene, spillover, kind)
        VALUES (gen_random_uuid(), v_ses, 'School fees (semester 1)', 100000, 100, 'UTME', fa, v_prog, 1, 1, NULL, false, 'FEE');
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, study_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (st, 'MOAUM/ADM/90/004611', NULL, 'CHECKV461', 'Ada', v_prog, 'UTME', 'FULL_TIME', v_ses, 100, 100, 'ADMITTED', NULL);
        INSERT INTO registration.course_registration (id, student_id, session, semester, level, status) VALUES (reg, st, v_ses, 2, 100, 'DRAFT');
        -- paid in full for both semesters' worth: the unstated second semester still never reads as cleared
        INSERT INTO finance.payment_reference (student_id, session, reference, purpose, amount, expires_at, confirmed_at, confirmed_by, channel, receipt_no)
        VALUES (st, v_ses, 'CHK-V461-PAID', 'School fees ' || v_ses, 160000.00, now() + interval '1 day', now(), who, 'Legacy', 'CHK-RCPT-V461');
        unstated := finance.fee_unstated_semesters(st, v_ses);
        cleared_before := finance.semester_cleared(st, v_ses, 2);
        BEGIN
            PERFORM registration.student_submit(reg); refused1 := 'submitted';
        EXCEPTION WHEN check_violation THEN refused1 := split_part(SQLERRM, ':', 1);
        END;
        -- the filled sheet: the second semester's line, a blank amount, an unknown programme; then the same again
        SELECT * INTO a1 FROM finance.add_fee_lines(v_ses, jsonb_build_array(
            jsonb_build_object('programmeCode', v_prog, 'level', '100', 'entryMode', 'UTME', 'semester', '2', 'indigene', '', 'spillover', 'No', 'amount', '₦60,000'),
            jsonb_build_object('programmeCode', v_prog, 'level', '200', 'entryMode', 'UTME', 'semester', '2', 'amount', ''),
            jsonb_build_object('programmeCode', 'NO-SUCH', 'level', '100', 'semester', '1', 'amount', '5')));
        cleared_after := finance.semester_cleared(st, v_ses, 2);
        SELECT * INTO a2 FROM finance.add_fee_lines(v_ses, jsonb_build_array(
            jsonb_build_object('programmeCode', v_prog, 'level', '100', 'entryMode', 'UTME', 'semester', '2', 'indigene', '', 'spillover', 'No', 'amount', '60000')));
        -- stated now: the submission passes the semester's test (and stops on what is unpaid instead)
        BEGIN
            PERFORM registration.student_submit(reg); refused2 := 'submitted';
        EXCEPTION WHEN check_violation THEN refused2 := coalesce(nullif(split_part(SQLERRM, ':', 1), SQLERRM), SQLERRM);
        END;
        -- a faculty charged as another is never given a line of its own by the sheet; the faculty it follows is
        PERFORM finance.set_faculty_fee_source(fa, fb, NULL, 'CHECK V461');
        UPDATE finance.fee_schedule SET ended_at = now() WHERE session = v_ses AND faculty_code = fa AND ended_at IS NULL;
        SELECT * INTO a3 FROM finance.add_fee_lines(v_ses, jsonb_build_array(
            jsonb_build_object('programmeCode', v_prog, 'level', '300', 'entryMode', 'UTME', 'semester', '1', 'amount', '1'),
            jsonb_build_object('facultyCode', fb, 'level', '300', 'entryMode', 'UTME', 'semester', '1', 'amount', '1')));
        src_after := finance.fee_source_of(fa, v_ses);
        RAISE EXCEPTION 'the V461 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V461: a semester whose fees are not stated for the student is refused at registration; the filled sheet adds its line once, leaves out a blank amount and an unknown programme, and never gives a faculty charged as another a line of its own',
        coalesce(fa IS NOT NULL AND fb IS NOT NULL AND unstated = '{2}' AND refused1 = 'REG_SEMESTER_FEES_NOT_STATED'
             AND NOT cleared_before AND cleared_after
             AND a1.added = 1 AND a1.no_amount = 1 AND a1.no_programme = 1 AND a2.added = 0 AND a2.already = 1
             AND refused2 <> 'REG_SEMESTER_FEES_NOT_STATED'
             AND a3.charged_as = 1 AND a3.added = 1 AND src_after = fb, false),
        format('A %s B %s | unstated %s, refused %s, cleared before %s after %s | sheet %s, again %s | then %s | charged as: %s, rule after %s',
               fa, fb, unstated, refused1, cleared_before, cleared_after, to_jsonb(a1), to_jsonb(a2), refused2, to_jsonb(a3), src_after));
END $$;

-- ── V462. The class-stream refusal names the course and both routes: a postgraduate student put on a full-time class is
--          told it is a full-time undergraduate class and that a postgraduate student registers only on the School's classes
--          (not, as before, about the Centre for Continuing Education); an undergraduate on a CCE class is told so; the code
--          stays REGISTRATION_STREAM ──
DO $$
DECLARE who uuid := gen_random_uuid(); v_ses text := '9990/9991'; v_course text;
        pg uuid := gen_random_uuid(); ug uuid := gen_random_uuid(); r_pg uuid := gen_random_uuid(); r_ug uuid := gen_random_uuid();
        ft_class uuid := gen_random_uuid(); cce_class uuid := gen_random_uuid(); m_pg text; m_ug text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true); PERFORM set_config('moaum.actor_office', 'academic', true); PERFORM set_config('moaum.reason', 'CHECK V462', true);
        v_course := (SELECT code FROM catalogue.course ORDER BY code LIMIT 1);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), v_ses, date '9990-10-01', date '9991-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO catalogue.offering (id, course_code, session, semester, stream) VALUES (ft_class, v_course, v_ses, 1, 'REGULAR'), (cce_class, v_course, v_ses, 1, 'CCE');
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, study_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (pg, 'MOAUM/ADM/90/004621', NULL, 'CHECKV462', 'Ada',
                (SELECT code FROM ref.programme WHERE category = 'POST GRADUATE' AND NOT coalesce(archived, false) ORDER BY code LIMIT 1),
                'POSTGRADUATE', 'FULL_TIME', v_ses, 800, 800, 'ADMITTED', NULL),
               (ug, 'MOAUM/ADM/90/004622', NULL, 'CHECKV462', 'Bola',
                (SELECT code FROM ref.programme WHERE category = 'UNDER GRADUATE' AND NOT coalesce(archived, false) ORDER BY code LIMIT 1),
                'UTME', 'FULL_TIME', v_ses, 100, 100, 'ADMITTED', NULL);
        INSERT INTO registration.course_registration (id, student_id, session, semester, level, status)
        VALUES (r_pg, pg, v_ses, 1, 800, 'DRAFT'), (r_ug, ug, v_ses, 1, 100, 'DRAFT');
        BEGIN
            INSERT INTO registration.entry (registration_id, offering_id, units, entry_type) VALUES (r_pg, ft_class, 3, 'CURRENT'); m_pg := 'accepted';
        EXCEPTION WHEN check_violation THEN m_pg := SQLERRM;
        END;
        BEGIN
            INSERT INTO registration.entry (registration_id, offering_id, units, entry_type) VALUES (r_ug, cce_class, 3, 'CURRENT'); m_ug := 'accepted';
        EXCEPTION WHEN check_violation THEN m_ug := SQLERRM;
        END;
        RAISE EXCEPTION 'the V462 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        NULL;
    END;
    PERFORM pg_temp.assert('V462: the class-stream refusal names the course, the class''s stream and the student''s route — never the CCE to a postgraduate student',
        coalesce(m_pg LIKE 'REGISTRATION_STREAM: ' || v_course || ' is a full-time undergraduate class, and a postgraduate student registers only on the School''s postgraduate classes'
             AND m_pg NOT LIKE '%Continuing Education%'
             AND m_ug LIKE 'REGISTRATION_STREAM: ' || v_course || ' is a class of the Centre for Continuing Education, and a full-time undergraduate registers only on full-time undergraduate classes', false),
        format('postgraduate on a full-time class: %s | undergraduate on a CCE class: %s', m_pg, m_ug));
END $$;

-- ── V463: register uploads fast — the academic position refreshed once per batch, and only when it moved ──
-- An upload of two new students leaves each one's position exactly as a fresh reading gives it, written once, and ends its
-- deferral; re-uploading them unchanged rewrites no position; a level the file raises is refreshed by the upload's one pass;
-- outside an upload a student moved is refreshed at once and a student rewritten unchanged is not; the one-student and the
-- many-student readings agree; a deferral already begun is not begun twice. The block undoes its writes.
DO $$
DECLARE who uuid := gen_random_uuid(); v_prog text; a uuid; b uuid; r record; same_a boolean; same_b boolean; c0 tid; c1 tid; c2 tid; c3 tid; c4 tid; cb tid;
        defer_after text; lvl_after int; one_many boolean; nested boolean; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.reason', 'check V463', true);
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'registrar', true);
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (who, 'CHECK/V463/P', 'ZZPOSITION', 'Invented');
        SELECT p.code INTO v_prog FROM ref.programme p
         WHERE NOT coalesce(p.archived, false) AND p.category = 'UNDER GRADUATE' AND p.faculty_code IS NOT NULL ORDER BY p.code LIMIT 1;
        -- 1. two new students in one upload: their positions written once, as a fresh reading gives them; the deferral ended
        SELECT * INTO r FROM people.import_students(jsonb_build_array(
            jsonb_build_object('matric', 'MOAUM/CKP/26/4631', 'name', 'CHECKV463, Ada', 'programme', v_prog, 'level', '200', 'entrySession', '2024/2025'),
            jsonb_build_object('matric', 'MOAUM/CKP/26/4632', 'name', 'CHECKV463, Bola', 'programme', v_prog, 'level', '100', 'entrySession', '2025/2026')));
        SELECT id INTO a FROM people.student WHERE matric_no = 'MOAUM/CKP/26/4631';
        SELECT id INTO b FROM people.student WHERE matric_no = 'MOAUM/CKP/26/4632';
        same_a := (SELECT to_jsonb(ap) - 'computed_at' FROM people.academic_position ap WHERE ap.student_id = a)
                = (SELECT to_jsonb(x) - 'computed_at' FROM people.academic_position_rows(a) x);
        same_b := (SELECT to_jsonb(ap) - 'computed_at' FROM people.academic_position ap WHERE ap.student_id = b)
                = (SELECT to_jsonb(x) - 'computed_at' FROM people.academic_position_rows(b) x);
        defer_after := coalesce(current_setting('moaum.position_defer', true), '');
        -- 2. the same file again: nothing moved, no position rewritten
        SELECT ctid INTO c0 FROM people.academic_position WHERE student_id = a;
        PERFORM people.import_students(jsonb_build_array(
            jsonb_build_object('matric', 'MOAUM/CKP/26/4631', 'name', 'CHECKV463, Ada', 'programme', v_prog, 'level', '200', 'entrySession', '2024/2025')));
        SELECT ctid INTO c1 FROM people.academic_position WHERE student_id = a;
        -- 3. the file raises the level: the upload's one pass refreshes it
        PERFORM people.import_students(jsonb_build_array(
            jsonb_build_object('matric', 'MOAUM/CKP/26/4631', 'name', 'CHECKV463, Ada', 'programme', v_prog, 'level', '300', 'entrySession', '2024/2025')));
        SELECT ctid, current_level INTO c2, lvl_after FROM people.academic_position WHERE student_id = a;
        -- 4. outside an upload: rewritten unchanged, not refreshed; moved, refreshed at once
        SELECT ctid INTO cb FROM people.academic_position WHERE student_id = b;
        UPDATE people.student SET current_level = current_level, status = status WHERE id = b;
        SELECT ctid INTO c3 FROM people.academic_position WHERE student_id = b;
        UPDATE people.student SET current_level = 200 WHERE id = b;
        SELECT ctid INTO c4 FROM people.academic_position WHERE student_id = b;
        -- 5. one and many read alike; a deferral already begun is not begun again
        one_many := (SELECT jsonb_agg(to_jsonb(x) - 'computed_at' ORDER BY x.student_id) FROM people.academic_position_rows_of(ARRAY[a, b]) x)
                  = (SELECT jsonb_agg(y ORDER BY y->>'student_id') FROM (SELECT to_jsonb(x) - 'computed_at' AS y FROM people.academic_position_rows(a) x
                                                                         UNION ALL SELECT to_jsonb(x) - 'computed_at' FROM people.academic_position_rows(b) x) z);
        PERFORM people.defer_positions();
        nested := NOT people.defer_positions();
        PERFORM people.refresh_deferred_positions();
        RAISE EXCEPTION 'the V463 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V463 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V463: a register upload writes each student''s academic position once, as a fresh reading gives it, and ends its deferral; an unchanged re-upload or rewrite refreshes nothing; a moved student is refreshed, in the upload''s one pass or at once; one and many read alike',
        coalesce(r.created = 2 AND same_a AND same_b AND defer_after = '' AND c1 = c0 AND c2 <> c1 AND lvl_after = 300
                 AND c3 = cb AND c4 <> c3 AND one_many AND nested, false),
        format('created %s, fresh %s/%s, defer after "%s" | same file %s→%s, raised %s level %s | rewrite %s→%s, moved %s | one=many %s, nested %s',
               r.created, same_a, same_b, defer_after, c0, c1, c2, lvl_after, cb, c3, c4, one_many, nested));
END $$;
-- ── V464. Units held for a class whose results are worked on, and a programme's change reaching its carry-overs: an
--          invented 3-unit course bound into a programme at 100 level. Its classes: one with a classmate already scored,
--          one whose sheet has left ENTRY, and one of another session with a student of the programme at 100 level, a
--          carry-over taken at 200 and a student of another programme. Before the programme takes it at 2 units the
--          impact says 2 follow and 3 keep theirs; after, exactly those two moved, the examined classes and the other
--          programme kept 3, and back to the course's own number the two return. The block undoes its writes ──
DO $$
DECLARE who uuid := gen_random_uuid(); v_dept text; p1 text; p2 text; v_s1 text := '9464/9465'; v_s2 text := '9466/9467';
        o_a uuid := gen_random_uuid(); o_b uuid := gen_random_uuid(); o_d uuid := gen_random_uuid(); sh_a uuid := gen_random_uuid(); sh_b uuid := gen_random_uuid();
        st uuid[] := ARRAY[gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid()];
        rg uuid[] := ARRAY[gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid()];
        before record; again record; back record; after_units text; back_units text; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        PERFORM set_config('moaum.reason', 'check V464', true);
        SELECT p.dept_code, p.code INTO v_dept, p1 FROM ref.programme p
         WHERE NOT coalesce(p.archived, false) AND coalesce(p.category, '') <> 'POST GRADUATE' AND p.dept_code IS NOT NULL ORDER BY p.code LIMIT 1;
        SELECT p.code INTO p2 FROM ref.programme p WHERE NOT coalesce(p.archived, false) AND coalesce(p.category, '') <> 'POST GRADUATE'
           AND p.dept_code IS NOT NULL AND p.code <> p1 ORDER BY p.code LIMIT 1;
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES
          (gen_random_uuid(), v_s1, date '9464-10-01', date '9465-08-31'), (gen_random_uuid(), v_s2, date '9466-10-01', date '9467-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state) VALUES ('ZZV 101', 'Units held by class', 3, 1, 100, v_dept, 'Core', 'LIVE');
        INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES ('ZZV 101', p1, 100, 'Core'), ('ZZV 101', p2, 100, 'Borrowed');
        INSERT INTO catalogue.offering (id, course_code, session, semester) VALUES (o_a, 'ZZV 101', v_s1, 1), (o_b, 'ZZV 101', v_s1, 2), (o_d, 'ZZV 101', v_s2, 1);
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status)
        SELECT st[i], 'MOAUM/ADM/60/94640' || i, 'CHECKV464', 'S' || i, CASE WHEN i = 6 THEN p2 ELSE p1 END, 'UTME', v_s1, 100, CASE WHEN i = 4 THEN 200 ELSE 100 END, 'ADMITTED'
          FROM generate_series(1, 6) i;
        -- 1 and 2 on class A (2 scored), 3 on class B (its sheet past ENTRY, no score), 4 a carry-over at 200, 5 at 100 and 6 of the other programme on class D
        INSERT INTO registration.course_registration (id, student_id, session, semester, level) VALUES
          (rg[1], st[1], v_s1, 1, 100), (rg[2], st[2], v_s1, 1, 100), (rg[3], st[3], v_s1, 2, 100),
          (rg[4], st[4], v_s2, 1, 200), (rg[5], st[5], v_s2, 1, 100), (rg[6], st[6], v_s2, 1, 100);
        INSERT INTO registration.entry (registration_id, offering_id, units, entry_type) VALUES
          (rg[1], o_a, 3, 'CURRENT'), (rg[2], o_a, 3, 'CURRENT'), (rg[3], o_b, 3, 'CURRENT'), (rg[4], o_d, 3, 'CURRENT'), (rg[5], o_d, 3, 'CURRENT'), (rg[6], o_d, 3, 'CURRENT');
        INSERT INTO assessment.score_sheet (id, offering_id) VALUES (sh_a, o_a);
        INSERT INTO assessment.score (sheet_id, student_id, ca, exam) VALUES (sh_a, st[2], 20, 40);
        INSERT INTO assessment.score_sheet (id, offering_id, stage) VALUES (sh_b, o_b, 'VERIFICATION');
        SELECT * INTO before FROM catalogue.units_change_impact('ZZV 101', p1, 100, 2);
        UPDATE catalogue.course_offer SET units = 2 WHERE course_code = 'ZZV 101' AND programme_code = p1 AND level = 100;
        after_units := (SELECT string_agg(e.units::text, ',' ORDER BY i) FROM generate_series(1, 6) i JOIN registration.entry e ON e.registration_id = rg[i]);
        SELECT * INTO again FROM catalogue.units_change_impact('ZZV 101', p1, 100, 2);
        SELECT * INTO back FROM catalogue.units_change_impact('ZZV 101', p1, 100, 3);
        UPDATE catalogue.course_offer SET units = NULL WHERE course_code = 'ZZV 101' AND programme_code = p1 AND level = 100;
        back_units := (SELECT string_agg(e.units::text, ',' ORDER BY i) FROM generate_series(1, 6) i JOIN registration.entry e ON e.registration_id = rg[i]);
        RAISE EXCEPTION 'the V464 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V464 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V464: a class whose results are worked on keeps its units, a programme''s change reaches its carry-overs, and the impact says beforehand what follows and what keeps',
        coalesce(before.now_units = 3 AND before.new_units = 2 AND before.follow = 2 AND before.kept = 3
                 AND after_units = '3,3,3,2,2,3' AND again.follow = 0 AND again.kept = 3
                 AND back.new_units = 3 AND back.follow = 2 AND back.kept = 0 AND back_units = '3,3,3,3,3,3', false),
        format('before %s | after %s | again %s | back %s -> %s', to_jsonb(before), after_units, to_jsonb(again), to_jsonb(back), back_units));
END $$;

-- ── V466: the school-fees payment closure message, the Directorate of ICT's to write ──
-- It starts as the portal's present words; the Director writes another, which is kept and put on the window's history; an empty
-- message is refused, and course registration (no student reads a closure message for it) carries none. The block undoes its writes.
DO $$
DECLARE who uuid := gen_random_uuid(); seeded text; after text; logged int; r_blank text := 'accepted'; r_reg text := 'accepted'; msg text;
BEGIN
    SELECT m.message INTO seeded FROM policy.portal_window_message m WHERE m.window_type = 'SCHOOL_FEES_PAYMENT';
    BEGIN
        PERFORM set_config('moaum.reason', 'check V466', true);
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'ict', true);
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (who, 'CHECK/V466/P', 'ZZWINDOWMSG', 'Invented');
        PERFORM policy.window_message_set('SCHOOL_FEES_PAYMENT', 'CHECK V466: payment reopens on Monday.', who, 'ict');
        SELECT m.message INTO after FROM policy.portal_window_message m WHERE m.window_type = 'SCHOOL_FEES_PAYMENT';
        SELECT count(*) INTO logged FROM policy.portal_window_event e WHERE e.window_type = 'SCHOOL_FEES_PAYMENT' AND e.action = 'MESSAGE' AND e.new_state LIKE 'CHECK V466%';
        BEGIN PERFORM policy.window_message_set('SCHOOL_FEES_PAYMENT', '   ', who, 'ict'); EXCEPTION WHEN check_violation THEN r_blank := SQLERRM; END;
        BEGIN PERFORM policy.window_message_set('COURSE_REGISTRATION', 'no such message', who, 'ict'); EXCEPTION WHEN check_violation THEN r_reg := SQLERRM; END;
        RAISE EXCEPTION 'the V466 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V466 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V466: school fees payment carries a closure message — the portal''s present words until the Director writes another, which is kept and on the window''s history; never blank; none for course registration',
        coalesce(seeded LIKE 'The University has not currently opened the payment portal%' AND after = 'CHECK V466: payment reopens on Monday.' AND logged = 1
                 AND r_blank LIKE '%cannot be blank%' AND r_reg LIKE 'no closure message for%', false),
        format('seeded "%s" | after "%s", logged %s | blank: %s | registration: %s', left(seeded, 40), after, logged, r_blank, r_reg));
END $$;

-- ── V465. Units corrected for an examined class through the amendment chain, and what a change of the course's own units
--          reaches counted first: an invented 3-unit course taken by a programme of its department and by another
--          department's. A programme's change reaches its student on the class with no result, not the two on the class with
--          a score. A units correction is refused to another desk, for the units already carried, for a class not examined,
--          and while one is open; then approved by each desk and applied on the Senate minute — the programme's two students
--          on the class carry 2, the other programme's keeps 3, the two told by e-mail. The course's own change to 4 is
--          counted first (1 follows, 2 kept, 1 binding pinned) and does exactly that. The block undoes its writes ──
DO $$
DECLARE who uuid := gen_random_uuid(); lect uuid := gen_random_uuid(); v_dept text; p1 text; p2 text; v_ses text := '9465/9466';
        o1 uuid := gen_random_uuid(); o2 uuid := gen_random_uuid(); sh uuid := gen_random_uuid(); sh2 uuid := gen_random_uuid();
        st uuid[] := ARRAY[gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid()];
        rg uuid[] := ARRAY[gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid()];
        imp record; cimp record; amd uuid; stg text; msg text; r_desk text; r_same text; r_notex text; r_open text; r_minute text;
        units_after text; applied int; told int; listed text; cls text; course_after text; pinned_units int; n_steps int := 0;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        PERFORM set_config('moaum.reason', 'check V465', true);
        INSERT INTO iam.person (id, surname, given_names, email) VALUES (lect, 'CHECKV465', 'Lecturer', 'zz.check465@example.com');
        SELECT p.dept_code, p.code INTO v_dept, p1 FROM ref.programme p
         WHERE NOT coalesce(p.archived, false) AND coalesce(p.category, '') <> 'POST GRADUATE' AND p.dept_code IS NOT NULL ORDER BY p.code LIMIT 1;
        SELECT p.code INTO p2 FROM ref.programme p WHERE NOT coalesce(p.archived, false) AND coalesce(p.category, '') <> 'POST GRADUATE'
           AND p.dept_code IS NOT NULL AND p.dept_code <> v_dept ORDER BY p.code LIMIT 1;
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), v_ses, date '9465-10-01', date '9466-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state) VALUES ('ZZW 101', 'Units corrected by amendment', 3, 1, 100, v_dept, 'Core', 'LIVE');
        INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES ('ZZW 101', p1, 100, 'Core'), ('ZZW 101', p2, 100, 'Borrowed');
        INSERT INTO catalogue.offering (id, course_code, session, semester) VALUES (o1, 'ZZW 101', v_ses, 1), (o2, 'ZZW 101', v_ses, 2);
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status)
        SELECT st[i], 'MOAUM/ADM/60/94650' || i, 'CHECKV465', 'S' || i, CASE WHEN i IN (3, 5) THEN p2 ELSE p1 END, 'UTME', v_ses, 100, 100, 'ADMITTED'
          FROM generate_series(1, 5) i;
        INSERT INTO people.student_contact (student_id, email) SELECT st[i], 'zz.check465.' || i || '@example.com' FROM generate_series(1, 5) i
        ON CONFLICT (student_id) DO UPDATE SET email = EXCLUDED.email;
        -- 1 and 2 of the first programme and 3 of the second on class 1 (1 scored); 4 of the first and 5 of the second on class 2 (no result)
        INSERT INTO registration.course_registration (id, student_id, session, semester, level) VALUES
          (rg[1], st[1], v_ses, 1, 100), (rg[2], st[2], v_ses, 1, 100), (rg[3], st[3], v_ses, 1, 100), (rg[4], st[4], v_ses, 2, 100), (rg[5], st[5], v_ses, 2, 100);
        INSERT INTO registration.entry (registration_id, offering_id, units, entry_type) VALUES
          (rg[1], o1, 3, 'CURRENT'), (rg[2], o1, 3, 'CURRENT'), (rg[3], o1, 3, 'CURRENT'), (rg[4], o2, 3, 'CURRENT'), (rg[5], o2, 3, 'CURRENT');
        INSERT INTO assessment.score_sheet (id, offering_id) VALUES (sh, o1), (sh2, o2);
        INSERT INTO assessment.score (sheet_id, student_id, ca, exam) VALUES (sh, st[1], 20, 40);
        SELECT * INTO imp FROM catalogue.units_change_impact('ZZW 101', p1, 100, 2);

        -- the units correction: another desk, the units already carried, a class not examined — refused
        PERFORM set_config('moaum.actor_id', lect::text, true);
        PERFORM set_config('moaum.actor_office', 'hod', true);
        BEGIN PERFORM assessment.raise_units_amendment(sh, p1, 2, 'the programme takes the course at two units');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_desk := split_part(msg, ':', 1); END;
        PERFORM set_config('moaum.actor_office', 'lecturer', true);
        BEGIN PERFORM assessment.raise_units_amendment(sh, p1, 3, 'the programme takes the course at three units');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_same := split_part(msg, ':', 1); END;
        BEGIN PERFORM assessment.raise_units_amendment(sh2, p1, 2, 'the programme takes the course at two units');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_notex := split_part(msg, ':', 1); END;
        amd := assessment.raise_units_amendment(sh, p1, 2, 'the programme takes the course at two units');
        BEGIN PERFORM assessment.raise_units_amendment(sh, p1, 1, 'a second correction while the first is open');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_open := split_part(msg, ':', 1); END;
        listed := (SELECT a.kind || ' ' || a.programme_code || ' ' || a.units || ' was ' || a.was_units FROM assessment.amendments_of(sh) a WHERE a.id = amd);
        -- each desk in turn; Senate without its minute refused, then applied on it
        LOOP
            stg := (SELECT stage FROM assessment.amendment WHERE id = amd);
            EXIT WHEN stg = 'APPLIED' OR n_steps > 10;
            n_steps := n_steps + 1;
            PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
            PERFORM set_config('moaum.actor_office', (assessment.stage_offices(stg))[1], true);
            IF stg = 'SENATE' THEN
                BEGIN PERFORM assessment.advance_amendment(amd, NULL, NULL);
                EXCEPTION WHEN check_violation THEN r_minute := 'refused'; END;
                PERFORM assessment.advance_amendment(amd, NULL, 'SEN/9465/1');
            ELSE
                PERFORM assessment.advance_amendment(amd, 'seen', NULL);
            END IF;
        END LOOP;
        units_after := (SELECT string_agg(e.units::text, ',' ORDER BY i) FROM generate_series(1, 5) i JOIN registration.entry e ON e.registration_id = rg[i]);
        applied := (SELECT applied_count FROM assessment.amendment WHERE id = amd);
        told := (SELECT count(*) FROM platform.notice WHERE about_kind = 'student' AND about_id IN (st[1], st[2], st[3]) AND subject = 'Your units in ZZW 101 are corrected');
        cls := (SELECT string_agg(c.programme_code || ':' || c.students || ':' || array_to_string(c.carried, '/') || ':' || c.examined, ' ' ORDER BY c.programme_code = p1 DESC)
                  FROM assessment.class_units(sh) c);

        -- the course's own units to 4: counted first, then made
        PERFORM set_config('moaum.actor_office', 'academic', true);
        SELECT * INTO cimp FROM catalogue.course_units_change_impact('ZZW 101', 4);
        UPDATE catalogue.course SET units = 4 WHERE code = 'ZZW 101';
        course_after := (SELECT string_agg(e.units::text, ',' ORDER BY i) FROM generate_series(1, 5) i JOIN registration.entry e ON e.registration_id = rg[i]);
        pinned_units := (SELECT units FROM catalogue.course_offer WHERE course_code = 'ZZW 101' AND programme_code = p2 AND level = 100);
        RAISE EXCEPTION 'the V465 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V465 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V465: an examined class''s units corrected only through the amendment chain — refused to another desk, for the units carried, for a class not examined and while one is open; applied on the Senate minute to the programme''s students alone, each told; a change of the course''s own units counted before it is made, exactly as it then reaches',
        coalesce(imp.follow = 1 AND imp.kept = 2 AND r_desk IS NOT NULL AND r_same = 'RES_AMEND_SAME' AND r_notex = 'RES_UNITS_NOT_EXAMINED' AND r_open = 'RES_UNITS_OPEN'
                 AND listed = 'UNITS ' || p1 || ' 2 was 3' AND r_minute = 'refused' AND units_after = '2,2,3,3,3' AND applied = 2 AND told = 2
                 AND cls = p1 || ':2:2:true ' || p2 || ':1:3:true'
                 AND cimp.now_units = 3 AND cimp.new_units = 4 AND cimp.follow = 1 AND cimp.kept = 2 AND cimp.pinned = 1
                 AND course_after = '2,2,3,4,3' AND pinned_units = 3, false),
        format('impact %s | desk %s same %s not examined %s open %s | listed %s | minute %s | after %s applied %s told %s | class %s | course impact %s -> %s pinned %s',
               to_jsonb(imp), r_desk, r_same, r_notex, r_open, listed, r_minute, units_after, applied, told, cls, to_jsonb(cimp), course_after, pinned_units));
END $$;

-- ── V467. A units change on an examined class flags the transcripts already issued, as a changed mark does: a student with
--          an issued transcript, registered on a class with no result and on a class with a score. Units changed on the first
--          leave the transcript unflagged; on the second they flag it, with the reason. The e-mails of a mark amendment and a
--          units correction say the transcript goes to the Documents Office and is reissued if it no longer matches. The block
--          undoes its writes ──
DO $$
DECLARE who uuid := gen_random_uuid(); v_ses text := '9467/9468'; v_prog text; st uuid := gen_random_uuid(); doc uuid := gen_random_uuid();
        o1 uuid := gen_random_uuid(); o2 uuid := gen_random_uuid(); sh uuid := gen_random_uuid(); rg1 uuid := gen_random_uuid(); rg2 uuid := gen_random_uuid();
        after_open timestamptz; after_examined timestamptz; why text; mail_mark text; mail_units text; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        PERFORM set_config('moaum.reason', 'check V467', true);
        SELECT code INTO v_prog FROM ref.programme WHERE NOT coalesce(archived, false) AND coalesce(category, '') <> 'POST GRADUATE' AND dept_code IS NOT NULL ORDER BY code LIMIT 1;
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), v_ses, date '9467-10-01', date '9468-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state)
        VALUES ('ZZX 101', 'Units flag documents', 3, 1, 100, (SELECT dept_code FROM ref.programme WHERE code = v_prog), 'Core', 'LIVE');
        INSERT INTO catalogue.offering (id, course_code, session, semester) VALUES (o1, 'ZZX 101', v_ses, 1), (o2, 'ZZX 101', v_ses, 2);
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status)
        VALUES (st, 'MOAUM/ADM/60/946701', 'CHECKV467', 'One', v_prog, 'UTME', v_ses, 100, 100, 'ADMITTED');
        INSERT INTO people.student_contact (student_id, email) VALUES (st, 'zz.check467@example.com') ON CONFLICT (student_id) DO UPDATE SET email = EXCLUDED.email;
        INSERT INTO registration.course_registration (id, student_id, session, semester, level) VALUES (rg1, st, v_ses, 1, 100), (rg2, st, v_ses, 2, 100);
        INSERT INTO registration.entry (registration_id, offering_id, units, entry_type) VALUES (rg1, o1, 3, 'CURRENT'), (rg2, o2, 3, 'CURRENT');
        INSERT INTO assessment.score_sheet (id, offering_id) VALUES (sh, o2);
        INSERT INTO assessment.score (sheet_id, student_id, ca, exam) VALUES (sh, st, 20, 40);
        -- the transcript issued after the mark
        INSERT INTO credentials.issued (id, kind, student_id, verification_code, statement, signature, issuing_name, issued_on, issued_by, issued_office)
        VALUES (doc, 'TRANSCRIPT', st, credentials.new_code(), '{}'::jsonb, '\x00'::bytea, 'Check V467', current_date, who, 'registrar');
        UPDATE registration.entry SET units = 2 WHERE registration_id = rg1;
        after_open := (SELECT flagged_at FROM credentials.issued WHERE id = doc);
        UPDATE registration.entry SET units = 2 WHERE registration_id = rg2;
        SELECT flagged_at, flag_reason INTO after_examined, why FROM credentials.issued WHERE id = doc;
        PERFORM assessment.tell_amended(st, 'ZZX 101', 'AMD-9467-00001');
        PERFORM assessment.tell_units_amended(sh, v_prog, 'ZZX 101', 2, 'AMD-9467-00002');
        mail_mark := (SELECT body FROM platform.notice WHERE about_kind = 'student' AND about_id = st AND subject = 'Your result in ZZX 101 is amended' AND channel = 'EMAIL' LIMIT 1);
        mail_units := (SELECT body FROM platform.notice WHERE about_kind = 'student' AND about_id = st AND subject = 'Your units in ZZX 101 are corrected' LIMIT 1);
        RAISE EXCEPTION 'the V467 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V467 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V467: a units change on an examined class flags the transcripts already issued, one on a class with no result does not; the e-mails say a transcript issued before is checked and reissued, not that it is superseded',
        coalesce(after_open IS NULL AND after_examined IS NOT NULL AND why = 'The units of a course on the student''s record changed after issue'
                 AND mail_mark LIKE '%goes to the Documents Office to be checked%reissued%' AND mail_mark NOT LIKE '%is superseded%'
                 AND mail_units LIKE '%goes to the Documents Office%reissued%' AND mail_units NOT LIKE '%is superseded%', false),
        format('open class flagged %s | examined class flagged %s (%s) | mark e-mail %s | units e-mail %s',
               after_open IS NOT NULL, after_examined IS NOT NULL, why, mail_mark IS NOT NULL AND mail_mark LIKE '%reissued%', mail_units IS NOT NULL AND mail_units LIKE '%reissued%'));
END $$;


-- ── V468: the GST/EPS desk answers on a whole register ──
-- The desk's population reads the course engine over the whole register through finance.gst_eps_rows_all, which is planned
-- with nested loops off (a function with its own setting is planned on its own; inlined, the engine took about two minutes
-- on live-shaped data). The wrapper gives exactly the engine's rows, and the one-student engine is left as it was.
DO $$
DECLARE s text := policy.university_current_session(); cfg text[]; rows_hint real; reads boolean; one_kept boolean;
        only_all bigint; only_engine bigint; n bigint;
BEGIN
    SELECT p.proconfig, p.prorows INTO cfg, rows_hint FROM pg_proc p WHERE p.oid = 'finance.gst_eps_rows_all(text)'::regprocedure;
    reads := (SELECT p.prosrc LIKE '%finance.gst_eps_rows_all(p_session)%' AND p.prosrc NOT LIKE '%finance.gst_eps_rows(p_session, NULL)%'
                FROM pg_proc p WHERE p.oid = 'finance.gst_population(text,integer)'::regprocedure);
    one_kept := (SELECT p.proconfig IS NULL FROM pg_proc p WHERE p.oid = 'finance.gst_eps_rows(text,uuid)'::regprocedure);
    n := (SELECT count(*) FROM finance.gst_eps_rows_all(s));
    only_all := (SELECT count(*) FROM (SELECT * FROM finance.gst_eps_rows_all(s) EXCEPT ALL SELECT * FROM finance.gst_eps_rows(s, NULL)) x);
    only_engine := (SELECT count(*) FROM (SELECT * FROM finance.gst_eps_rows(s, NULL) EXCEPT ALL SELECT * FROM finance.gst_eps_rows_all(s)) x);
    PERFORM pg_temp.assert('V468: the GST/EPS population reads the whole-register engine planned without nested loops — the engine''s own rows, the one-student engine as it was',
        coalesce('enable_nestloop=off' = ANY (cfg) AND rows_hint >= 10000 AND reads AND one_kept AND only_all = 0 AND only_engine = 0, false),
        format('config %s rows %s | population reads the wrapper %s | one-student engine unset %s | %s rows, only in the wrapper %s, only in the engine %s',
               cfg, rows_hint, reads, one_kept, n, only_all, only_engine));
END $$;


-- ── V470: score reads stay fast — the grading read once a sheet, the same grades ──
-- A full-time and a postgraduate class's scores read by assessment.latest_scores come out as the per-score reading gives
-- them (grace_total and grade_of on the class's scope): the grace mark at each scheme's own pass mark (the University's
-- and the School's), an absence ungraded, an imported total taken as it is. grace_total is grace_apply on pass_floor,
-- and pass_floor is the lowest passing band of the version in force. The block undoes its writes.
DO $$
DECLARE dept text; o_ft uuid := gen_random_uuid(); o_pg uuid := gen_random_uuid(); sh_ft uuid := gen_random_uuid(); sh_pg uuid := gen_random_uuid();
        st uuid[] := ARRAY[]::uuid[]; t int[] := ARRAY[0, 38, 39, 40, 48, 49, 50, 100]; i int; s uuid;
        floor_u int; floor_p int; mismatched int; read int; graced_ft text; graced_pg text; absent_ok boolean; imported_ok boolean;
        rule_bad int; floor_bad int; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', '00000000-0000-0000-0000-000000000000', true);
        PERFORM set_config('moaum.actor_office', 'registrar', true);
        PERFORM set_config('moaum.reason', 'check V470', true);
        SELECT code INTO dept FROM ref.department ORDER BY code LIMIT 1;
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), '9999/0000', date '9999-01-01', date '9999-12-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state, ca_max)
        VALUES ('ZZG 470', 'Check grading read once a sheet', 3, 1, 100, dept, 'Core', 'LIVE', 30);
        INSERT INTO catalogue.offering (id, course_code, session, semester, stream) VALUES (o_ft, 'ZZG 470', '9999/0000', 1, 'REGULAR'), (o_pg, 'ZZG 470', '9999/0000', 2, 'PG');
        INSERT INTO assessment.score_sheet (id, offering_id) VALUES (sh_ft, o_ft), (sh_pg, o_pg);
        FOR i IN 1 .. array_length(t, 1) + 2 LOOP
            s := gen_random_uuid();
            st := st || s;
            INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
            VALUES (s, 'MOAUM/ADM/99/4700' || lpad(i::text, 2, '0'), 'MOAUM/CHK/99/47' || lpad(i::text, 2, '0'), 'CHECKV470', 'Invented ' || i, 'C00023', 'UTME', '9999/0000', 100, 100, 'ACTIVE', now());
        END LOOP;
        -- each total on both sheets, split within the course's 30/70; then an absence and an imported total
        FOR i IN 1 .. array_length(t, 1) LOOP
            INSERT INTO assessment.score (sheet_id, student_id, ca, exam) VALUES
                (sh_ft, st[i], least(t[i], 30), t[i] - least(t[i], 30)), (sh_pg, st[i], least(t[i], 30), t[i] - least(t[i], 30));
        END LOOP;
        i := array_length(t, 1);
        INSERT INTO assessment.score (sheet_id, student_id, outcome, reason) VALUES (sh_ft, st[i + 1], 'ABSENT', 'check V470'), (sh_pg, st[i + 1], 'ABSENT', 'check V470');
        INSERT INTO assessment.score (sheet_id, student_id, ca, exam, total, imported) VALUES (sh_ft, st[i + 2], 29, 10, 39, true), (sh_pg, st[i + 2], 29, 20, 49, true);

        -- the per-score reading, as V389 gave it
        WITH sc AS (SELECT sh.id AS sheet, x.*, policy.grading_scope(sh.offering_id) AS scope
                      FROM assessment.score_sheet sh
                      CROSS JOIN LATERAL (SELECT DISTINCT ON (student_id) * FROM assessment.score WHERE sheet_id = sh.id ORDER BY student_id, version DESC) x
                     WHERE sh.id IN (sh_ft, sh_pg)),
             was AS (SELECT sc.sheet, sc.student_id, t.total, g.grade, g.points FROM sc
                      CROSS JOIN LATERAL (SELECT CASE WHEN sc.outcome <> 'GRADED' THEN NULL
                                                      WHEN sc.ca IS NOT NULL AND sc.exam IS NOT NULL AND NOT sc.imported
                                                        THEN CASE WHEN sc.ca + sc.exam = (SELECT min(b.low) FROM policy.grade_band b
                                                                                             WHERE b.version_id = coalesce(policy.in_force('grading', sc.scope, current_date), policy.in_force('grading', 'UNIVERSITY', current_date))
                                                                                               AND b.points > 0) - 1
                                                                  THEN sc.ca + sc.exam + 1 ELSE sc.ca + sc.exam END
                                                      ELSE coalesce(sc.ca + sc.exam, sc.total) END AS total) t
                      LEFT JOIN LATERAL policy.grade_of(t.total, current_date, sc.scope) g ON true),
             now_ AS (SELECT sh AS sheet, x.student_id, x.total, x.grade, x.points FROM unnest(ARRAY[sh_ft, sh_pg]) sh CROSS JOIN LATERAL assessment.latest_scores(sh) x)
        SELECT (SELECT count(*) FROM (SELECT * FROM was EXCEPT ALL SELECT * FROM now_) a) + (SELECT count(*) FROM (SELECT * FROM now_ EXCEPT ALL SELECT * FROM was) b),
               (SELECT count(*) FROM now_)
          INTO mismatched, read;

        floor_u := (SELECT min(b.low) FROM policy.grade_band b WHERE b.version_id = policy.in_force('grading', 'UNIVERSITY', current_date) AND b.points > 0);
        floor_p := (SELECT min(b.low) FROM policy.grade_band b WHERE b.version_id = coalesce(policy.in_force('grading', 'POSTGRADUATE', current_date), policy.in_force('grading', 'UNIVERSITY', current_date)) AND b.points > 0);
        graced_ft := (SELECT string_agg(x.total::text, ',' ORDER BY x.total) FROM assessment.latest_scores(sh_ft) x JOIN assessment.score sc ON sc.sheet_id = sh_ft AND sc.student_id = x.student_id
                       WHERE NOT sc.imported AND sc.ca + sc.exam IN (floor_u - 1, floor_p - 1));
        graced_pg := (SELECT string_agg(x.total::text, ',' ORDER BY x.total) FROM assessment.latest_scores(sh_pg) x JOIN assessment.score sc ON sc.sheet_id = sh_pg AND sc.student_id = x.student_id
                       WHERE NOT sc.imported AND sc.ca + sc.exam IN (floor_u - 1, floor_p - 1));
        absent_ok := (SELECT bool_and(x.total IS NULL AND x.grade IS NULL) FROM assessment.latest_scores(sh_ft) x WHERE x.outcome = 'ABSENT');
        imported_ok := (SELECT x.total FROM assessment.latest_scores(sh_ft) x WHERE x.student_id = st[array_length(t, 1) + 2]) = 39;
        -- the rule and the floor read alone, for each total and scope
        rule_bad := (SELECT count(*) FROM generate_series(0, 100) r CROSS JOIN unnest(ARRAY['UNIVERSITY', 'POSTGRADUATE', NULL]) sc
                      WHERE assessment.grace_total(r, current_date, sc) IS DISTINCT FROM
                            CASE WHEN r = (CASE WHEN sc = 'POSTGRADUATE' THEN floor_p ELSE floor_u END) - 1 THEN r + 1 ELSE r END)
                  + (SELECT count(*) FROM generate_series(0, 100) r WHERE assessment.grace_total(r) IS DISTINCT FROM CASE WHEN r = floor_u - 1 THEN r + 1 ELSE r END);
        floor_bad := (CASE WHEN assessment.pass_floor(current_date, 'UNIVERSITY') = floor_u THEN 0 ELSE 1 END)
                   + (CASE WHEN assessment.pass_floor(current_date, 'POSTGRADUATE') = floor_p THEN 0 ELSE 1 END)
                   + (CASE WHEN assessment.pass_floor(current_date, NULL) = floor_u THEN 0 ELSE 1 END);
        RAISE EXCEPTION 'the V470 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V470 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V470: a class''s scores read with its grading resolved once a sheet are the per-score reading''s — the grace mark at the University''s and the School''s own pass marks, an absence ungraded, an imported total as it is; grace_total is the rule on pass_floor',
        coalesce(mismatched = 0 AND read = 20 AND graced_ft = format('%s,%s', floor_u, floor_p - 1) AND graced_pg = format('%s,%s', floor_u - 1, floor_p)
                 AND absent_ok AND imported_ok AND rule_bad = 0 AND floor_bad = 0, false),
        format('mismatched %s of %s read | full-time graced %s, postgraduate graced %s (floors %s/%s) | absence ungraded %s | imported as is %s | rule %s floor %s',
               mismatched, read, graced_ft, graced_pg, floor_u, floor_p, absent_ok, imported_ok, rule_bad, floor_bad));
END $$;


-- ── V471: the postgraduate programme structure, and the ICT Support Desk's access to it ──
-- The desk's vocabulary carries the structure's four capabilities; every agent in service holds, across the University,
-- viewing the structure and course allocation (the bulk import and the structure's edits stay a posting's); an agent taken
-- off the desk holds none of it. An offer from the course's side takes a postgraduate programme's bases and levels.
-- A prerequisite never requires its own course, however far round. The checks find a
-- postgraduate programme with no course and a binding off its levels; the School's counts see them; a change made on a
-- ticket is on the ticket's timeline. The block undoes its writes.
DO $$
DECLARE caps_ok boolean; base_ok boolean; agent uuid := gen_random_uuid(); dept text; fac text; alloc_free boolean; bind_free boolean; bind_none boolean;
        alloc_off boolean; self_msg text := ''; cycle_msg text := ''; removed int; empty_found boolean; off_found boolean; cycle_found boolean;
        summary_ok boolean; tkt uuid; noted int; msg text; offer_pg boolean := false; offer_low text := ''; offer_ug text := '';
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', '00000000-0000-0000-0000-000000000000', true);
        PERFORM set_config('moaum.actor_office', 'ict', true);
        PERFORM set_config('moaum.reason', 'check V471', true);
        caps_ok := helpdesk.support_capabilities() @> ARRAY['VIEW_PROGRAMME_STRUCTURE', 'EDIT_COURSES', 'BIND_COURSES', 'MANAGE_PREREQUISITES'];
        base_ok := helpdesk.agent_baseline() @> ARRAY['VIEW_PROGRAMME_STRUCTURE', 'VIEW_ALLOCATIONS', 'ALLOCATE_COURSES', 'REMOVE_ALLOCATIONS']
                   AND NOT helpdesk.agent_baseline() && ARRAY['BULK_ALLOCATE', 'EDIT_COURSES', 'BIND_COURSES', 'MANAGE_PREREQUISITES'];

        -- an agent in service, never posted: allocation everywhere, binding nowhere; taken off the desk: nothing
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (agent, 'ZZ-CHK-471', 'CHECKV471', 'Invented');
        INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from)
        VALUES (gen_random_uuid(), agent, 'ictagent', 'platform', NULL, 'check V471', agent, current_date);
        SELECT global INTO alloc_free FROM helpdesk.agent_scope_for(agent, 'ALLOCATE_COURSES');
        SELECT global, cardinality(faculties) + cardinality(departments) = 0 INTO bind_free, bind_none FROM helpdesk.agent_scope_for(agent, 'BIND_COURSES');
        INSERT INTO helpdesk.agent_assignment (person_id, queue_code, scope_kind, scope_ref, capabilities, active, effective_to)
        VALUES (agent, (SELECT code FROM helpdesk.queue ORDER BY ordinal LIMIT 1), 'GLOBAL', NULL, ARRAY['VIEW_STUDENT'], false, current_date);
        SELECT global INTO alloc_off FROM helpdesk.agent_scope_for(agent, 'ALLOCATE_COURSES');

        -- prerequisites: a chain, then a loop and a course requiring itself refused
        SELECT d.code, d.faculty_code INTO dept, fac FROM ref.department d WHERE d.faculty_code IS NOT NULL ORDER BY d.code LIMIT 1;
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state)
        VALUES ('ZZQ 701', 'Check prerequisite one', 3, 1, 700, dept, 'Core', 'LIVE'), ('ZZQ 702', 'Check prerequisite two', 3, 1, 700, dept, 'Core', 'LIVE'),
               ('ZZQ 703', 'Check prerequisite three', 3, 1, 700, dept, 'Core', 'LIVE'), ('ZZQ 301', 'Check off level', 3, 1, 300, dept, 'Core', 'LIVE');
        PERFORM catalogue.add_prerequisite('ZZQ 703', 'ZZQ 702');
        PERFORM catalogue.add_prerequisite('ZZQ 702', 'ZZQ 701');
        BEGIN PERFORM catalogue.add_prerequisite('ZZQ 701', 'ZZQ 703'); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS cycle_msg = MESSAGE_TEXT; END;
        BEGIN PERFORM catalogue.add_prerequisite('ZZQ 701', 'ZZQ 701'); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS self_msg = MESSAGE_TEXT; END;

        -- a postgraduate programme with nothing bound, then one binding off its levels; and a loop written behind the desk
        INSERT INTO ref.programme (code, name, dept_code, faculty_code, min_score, category, pg_award)
        VALUES ('C99471', 'Check V471 M.Sc.', dept, fac, 0, 'POST GRADUATE', 'MSC');
        -- an offer from the course's side: Research at 800 for a postgraduate programme; 300 level, or Research for an undergraduate one, refused
        BEGIN PERFORM catalogue.assert_offerable('ZZQ 701', 'C99471', 800, 'Research', NULL); offer_pg := true; EXCEPTION WHEN check_violation THEN offer_pg := false; END;
        BEGIN PERFORM catalogue.assert_offerable('ZZQ 701', 'C99471', 300, 'Core', NULL); EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS offer_low = MESSAGE_TEXT; END;
        BEGIN PERFORM catalogue.assert_offerable('ZZQ 301', (SELECT code FROM ref.programme WHERE category = 'UNDER GRADUATE' AND NOT archived AND dept_code IN (SELECT code FROM ref.department WHERE ended_on IS NULL) ORDER BY code LIMIT 1), 300, 'Research', NULL);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS offer_ug = MESSAGE_TEXT; END;
        empty_found := EXISTS (SELECT 1 FROM catalogue.structure_issues('POST GRADUATE') i WHERE i.kind = 'PROGRAMME_WITHOUT_COURSES' AND i.programme_code = 'C99471');
        INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES ('ZZQ 301', 'C99471', 300, 'Core');
        off_found := EXISTS (SELECT 1 FROM catalogue.structure_issues('POST GRADUATE') i WHERE i.kind = 'LEVEL_OFF_PROGRAMME' AND i.programme_code = 'C99471' AND i.course_code = 'ZZQ 301')
                     AND NOT EXISTS (SELECT 1 FROM catalogue.structure_issues('POST GRADUATE') i WHERE i.kind = 'PROGRAMME_WITHOUT_COURSES' AND i.programme_code = 'C99471');
        INSERT INTO catalogue.course_prerequisite (course_code, requires_code) VALUES ('ZZQ 701', 'ZZQ 703');
        cycle_found := EXISTS (SELECT 1 FROM catalogue.structure_issues(NULL) i WHERE i.kind = 'PREREQUISITE_CYCLE' AND i.course_code = 'ZZQ 701');
        DELETE FROM catalogue.course_prerequisite WHERE course_code = 'ZZQ 701';
        removed := catalogue.remove_prerequisite('ZZQ 703', 'zzq 702');
        SELECT s.programmes_with_courses >= 1 AND s.courses >= 1 AND s.issues >= 1 INTO summary_ok FROM catalogue.pg_structure_summary() s;

        -- a change made on a ticket, on its timeline
        INSERT INTO helpdesk.ticket (number, category_id, subject, description, requester_kind, requester_id, requester_name, queue_code)
        SELECT 'TICK-0471-00001', c.id, 'Check V471', 'A course missing from a programme', 'STAFF', agent, 'CHECKV471', (SELECT code FROM helpdesk.queue ORDER BY ordinal LIMIT 1)
          FROM helpdesk.category c ORDER BY c.code LIMIT 1
        RETURNING id INTO tkt;
        PERFORM helpdesk.note_structure(tkt, 'Bound ZZQ 701 into C99471 at 700 level', 'the student could not see it');
        noted := (SELECT count(*) FROM helpdesk.ticket_event e WHERE e.ticket_id = tkt AND e.action = 'SUPPORT_PROGRAMME_STRUCTURE' AND e.detail LIKE '%Reason: the student could not see it');
        RAISE EXCEPTION 'the V471 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V471 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V471: the desk carries the structure''s capabilities; every agent in service views the structure and allocates across the University, binding only by a posting, nothing once off the desk; a prerequisite never loops; the checks and the School''s counts find a programme with no course and a binding off its levels; a ticket''s change is on its timeline',
        coalesce(caps_ok AND base_ok AND alloc_free AND NOT bind_free AND bind_none AND NOT alloc_off
                 AND cycle_msg LIKE 'CAT_PREREQ_CYCLE:%' AND self_msg LIKE 'CAT_PREREQ_SELF:%' AND removed = 1
                 AND empty_found AND off_found AND cycle_found AND summary_ok AND noted = 1
                 AND offer_pg AND offer_low LIKE 'CAT_PG_LEVEL:%' AND offer_ug LIKE 'CAT_BASIS:%', false),
        format('caps %s baseline %s | allocation free %s, binding free %s none %s, off the desk %s | cycle "%s" self "%s" removed %s | empty %s off-level %s cycle %s summary %s | noted %s | offer pg %s low "%s" ug "%s"',
               caps_ok, base_ok, alloc_free, bind_free, bind_none, alloc_off, cycle_msg, self_msg, removed, empty_found, off_found, cycle_found, summary_ok, noted, offer_pg, offer_low, offer_ug));
END $$;
-- ── V469. The central student classification: every learner classified from structured fields — a decision, the entry mode,
--    the programme category, never a name or a number; a record nothing claims, or whose type does not admit its programme,
--    REQUIRES_CLASSIFICATION and counts as no type; only the Academic Office or the Registry decides, with a reason, each
--    decision kept; JUPEB and Preliminary learners in the one learner view as their own types (a Preliminary target never makes
--    an undergraduate); a progression keeps the earlier record; the registry carries ids, centres and the offices it binds ──
DO $$
DECLARE
    v_ses text := policy.university_current_session();
    v_actor uuid := gen_random_uuid();
    v_ug text; v_pg text; v_named text; v_fac text; v_dept text;
    s1 uuid := gen_random_uuid(); s2 uuid := gen_random_uuid(); s3 uuid := gen_random_uuid(); s4 uuid := gen_random_uuid(); s5 uuid := gen_random_uuid();
    cand uuid := gen_random_uuid(); acct uuid := gen_random_uuid(); app uuid := gen_random_uuid();
    jacc uuid; japp uuid; jdraft uuid; jacc2 uuid;
    c1 record; c2 record; c3 record; c4 record; c2b record;
    lj record; lp record; lp2 record;
    v_lecturer text; v_noreason text; v_jupeb_type text; v_centre_hod text; v_dup text; v_name text; v_bad_office text;
    v_decisions int; v_current int; v_events int; v_kind text; v_register_ok boolean; v_draft_absent boolean;
    v_ids_ok boolean; v_registry_ok boolean; v_future_ok boolean; v_named_ug boolean;
BEGIN
    PERFORM set_config('moaum.actor_id', v_actor::text, true);
    PERFORM set_config('moaum.actor_office', 'academic', true);
    PERFORM set_config('moaum.reason', 'CHECK V469', true);

    SELECT p.code, p.faculty_code, p.dept_code INTO v_ug, v_fac, v_dept FROM ref.programme p WHERE p.category = 'UNDER GRADUATE' AND NOT p.archived ORDER BY p.code LIMIT 1;
    SELECT p.code INTO v_pg FROM ref.programme p WHERE p.category = 'POST GRADUATE' AND NOT p.archived ORDER BY p.code LIMIT 1;
    -- a programme whose NAME reads postgraduate but whose category is undergraduate: the name decides nothing
    SELECT 'C' || lpad(x::text, 5, '0') INTO v_named FROM generate_series(90000, 99999) x
     WHERE NOT EXISTS (SELECT 1 FROM ref.programme p WHERE p.code = 'C' || lpad(x::text, 5, '0')) ORDER BY x LIMIT 1;
    INSERT INTO ref.programme (code, name, dept_code, faculty_code, category, min_score) VALUES (v_named, 'M.Sc. CHECK V469 (A NAME ONLY)', v_dept, v_fac, 'UNDER GRADUATE', 0);

    INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, study_mode, entry_session, entry_level, current_level, status) VALUES
        (s1, 'MOAUM/ADM/69/469001', 'CHECKV469A', 'Named', v_named, 'UTME', 'FULL_TIME', v_ses, 100, 100, 'ADMITTED'),
        (s2, 'MOAUM/ADM/69/469002', 'CHECKV469B', 'Conflicting', v_ug, 'POSTGRADUATE', 'FULL_TIME', v_ses, 100, 100, 'ADMITTED'),
        (s3, 'MOAUM/ADM/69/469003', 'CHECKV469C', 'Continuing', v_ug, 'CCE', 'PART_TIME', v_ses, 100, 100, 'ADMITTED'),
        (s4, 'MOAUM/ADM/69/469004', 'CHECKV469D', 'Postgraduate', v_pg, 'POSTGRADUATE', 'FULL_TIME', v_ses, 700, 700, 'ADMITTED'),
        (s5, 'MOAUM/ADM/69/469005', 'CHECKV469P', 'Progressed', v_ug, 'UTME', 'FULL_TIME', v_ses, 100, 100, 'ADMITTED');

    SELECT * INTO c1 FROM people.student_classification WHERE student_id = s1;
    SELECT * INTO c2 FROM people.student_classification WHERE student_id = s2;
    SELECT * INTO c3 FROM people.student_classification WHERE student_id = s3;
    SELECT * INTO c4 FROM people.student_classification WHERE student_id = s4;
    v_named_ug := c1.programme_type = 'UNDERGRADUATE' AND c1.type_source = 'ENTRY_MODE' AND c1.admission_route = 'UTME' AND c1.centre_code = 'MAIN_CAMPUS'
                  AND c1.centre_source = 'PROGRAMME_TYPE' AND c1.classification_status = 'CLASSIFIED';

    -- only the Academic Office or the Registry decides, and never without a reason
    PERFORM set_config('moaum.actor_office', 'lecturer', true);
    BEGIN PERFORM people.classify_student(s2, 'UNDERGRADUATE', 'UTME', NULL, 'not mine'); EXCEPTION WHEN insufficient_privilege THEN v_lecturer := split_part(SQLERRM, ':', 1); END;
    PERFORM set_config('moaum.actor_office', 'academic', true);
    BEGIN PERFORM people.classify_student(s2, 'UNDERGRADUATE', 'UTME', NULL, '  '); EXCEPTION WHEN check_violation THEN v_noreason := split_part(SQLERRM, ':', 1); END;
    BEGIN PERFORM people.classify_student(s2, 'JUPEB', NULL, NULL, 'CHECK V469'); EXCEPTION WHEN check_violation THEN v_jupeb_type := split_part(SQLERRM, ':', 1); END;
    PERFORM people.classify_student(s2, 'POSTGRADUATE', 'PG_APPLICATION', NULL, 'CHECK V469: first reading');
    PERFORM people.classify_student(s2, 'UNDERGRADUATE', 'UTME', 'ADIKPO', 'CHECK V469: the admission letter says UTME');
    SELECT * INTO c2b FROM people.student_classification WHERE student_id = s2;
    SELECT count(*), count(*) FILTER (WHERE superseded_at IS NULL) INTO v_decisions, v_current FROM people.classification_decision WHERE student_id = s2;
    SELECT count(*) INTO v_events FROM people.programme_type_event WHERE student_id = s2 AND event = 'CORRECTION';

    -- a student's centre is the Academic Office's or the Registry's to record
    PERFORM set_config('moaum.actor_office', 'hod', true);
    BEGIN UPDATE people.student SET centre_code = 'OTHER' WHERE id = s1; EXCEPTION WHEN check_violation THEN v_centre_hod := split_part(SQLERRM, ':', 1); END;
    PERFORM set_config('moaum.actor_office', 'academic', true);

    -- the JUPEB and Preliminary learners, as their own types, in the one view
    INSERT INTO jupeb.account (email, password_hash) VALUES ('zz.check469a@example.com', '$2a$12$abcdefghijklmnopqrstuuabcdefghijklmnopqrstuvwxyz12345') RETURNING id INTO jacc;
    INSERT INTO jupeb.account (email, password_hash) VALUES ('zz.check469b@example.com', '$2a$12$abcdefghijklmnopqrstuuabcdefghijklmnopqrstuvwxyz12345') RETURNING id INTO jacc2;
    INSERT INTO jupeb.application (account_id, session, application_no, surname, first_name, email, state, subjects_registered_at)
    VALUES (jacc, v_ses, 'JUPEB/APP/2069/469001', 'CHECKV469J', 'Learner', 'zz.check469a@example.com', 'STUDENT', now()) RETURNING id INTO japp;
    INSERT INTO jupeb.application (account_id, session, application_no, surname, first_name, email, state)
    VALUES (jacc2, v_ses, 'JUPEB/APP/2069/469002', 'CHECKV469K', 'Applicant', 'zz.check469b@example.com', 'DRAFT') RETURNING id INTO jdraft;
    INSERT INTO admissions.candidate (id, session, surname, other_names, programme, entry_mode, entry_level, offer_state, sex)
    VALUES (cand, v_ses, 'CHECKV469P', 'Progressed', 'Preliminary Science', 'PRELIMINARY', 0, 'ADMITTED', 'F');
    INSERT INTO admissions.applicant_account (id, session, candidate_id, email, phone, password_hash)
    VALUES (acct, v_ses, cand, 'zz.check469p@example.com', '08034690001', 'SET_ON_FIRST_LOGIN');
    INSERT INTO admissions.application (id, account_id, candidate_id, session, application_no) VALUES (app, acct, cand, v_ses, 'APP/69/469001');
    INSERT INTO admissions.prelim_review (application_id, route, state, target_programme) VALUES (app, 'PRELIMINARY_SCIENCE', 'ADMITTED', v_ug);

    SELECT * INTO lj FROM people.learner WHERE learner_id = japp;
    SELECT * INTO lp FROM people.learner WHERE learner_id = app;
    v_draft_absent := NOT EXISTS (SELECT 1 FROM people.learner WHERE learner_id = jdraft);
    v_register_ok := (SELECT count(*) FROM people.learner WHERE source = 'REGISTER') = (SELECT count(*) FROM people.student WHERE duplicate_of IS NULL)
                     AND NOT EXISTS (SELECT learner_id FROM people.learner GROUP BY learner_id HAVING count(*) > 1);

    -- a progression keeps the earlier record and names both types; once only; never to another surname
    PERFORM people.record_progression(s5, 'PRELIMINARY', 'app/69/469001', 'CHECK V469: admitted to the degree after Preliminary Science');
    SELECT * INTO lp2 FROM people.learner WHERE learner_id = app;
    SELECT kind INTO v_kind FROM people.programme_type_event WHERE application_id = app AND event = 'PROGRESSION';
    BEGIN PERFORM people.record_progression(s5, 'PRELIMINARY', 'APP/69/469001', 'again'); EXCEPTION WHEN unique_violation THEN v_dup := split_part(SQLERRM, ':', 1); END;
    BEGIN PERFORM people.record_progression(s1, 'JUPEB', 'JUPEB/APP/2069/469001', 'CHECK V469'); EXCEPTION WHEN check_violation THEN v_name := split_part(SQLERRM, ':', 1); END;

    -- the registry: a uuid id on every type, the centres and offices it binds, the future types present and switched off
    v_ids_ok := (SELECT count(DISTINCT id) = count(*) AND bool_and(id IS NOT NULL) FROM finance.programme_type);
    v_registry_ok := (SELECT count(*) = 6 FROM finance.programme_type
                       WHERE code IN ('UNDERGRADUATE', 'POSTGRADUATE', 'CCE', 'PRELIMINARY', 'SANDWICH', 'JUPEB') AND active AND default_centre IS NOT NULL)
                     AND (SELECT offices FROM finance.programme_type WHERE code = 'SANDWICH') = ARRAY['sandwich']
                     AND EXISTS (SELECT 1 FROM ref.office WHERE code = 'sandwich');
    v_future_ok := (SELECT count(*) = 4 AND NOT bool_or(active) FROM finance.programme_type WHERE code IN ('PRE_DEGREE', 'DIPLOMA', 'CERTIFICATE', 'PROFESSIONAL'));
    BEGIN UPDATE finance.programme_type SET offices = ARRAY['nosuchoffice'] WHERE code = 'OTHER'; EXCEPTION WHEN foreign_key_violation THEN v_bad_office := split_part(SQLERRM, ':', 1); END;

    PERFORM pg_temp.assert('V469: every learner is classified from structured fields — never a name; a record nothing claims or whose type does not admit its programme requires classification and counts as no type; only the Academic Office or the Registry decides, with a reason, every decision kept; JUPEB and Preliminary learners are their own types; a progression keeps the earlier record',
        coalesce(v_named_ug
            AND c2.programme_type IS NULL AND c2.proposed_type = 'POSTGRADUATE' AND c2.classification_status = 'REQUIRES_CLASSIFICATION' AND c2.classification_issue = 'CONFLICTING'
            AND c3.programme_type = 'CCE' AND c3.admission_route = 'CCE_JAMB' AND c3.centre_code = 'CCE' AND c3.study_mode = 'PART_TIME'
            AND c4.programme_type = 'POSTGRADUATE' AND c4.admission_route = 'PG_APPLICATION' AND c4.classification_status = 'CLASSIFIED'
            AND v_lecturer = 'CLASSIFICATION_OFFICE' AND v_noreason = 'CLASSIFICATION_REASON' AND v_jupeb_type = 'CLASSIFICATION_TYPE'
            AND c2b.programme_type = 'UNDERGRADUATE' AND c2b.type_source = 'DECISION' AND c2b.admission_route = 'UTME' AND c2b.centre_code = 'ADIKPO' AND c2b.centre_source = 'RECORDED'
            AND v_decisions = 2 AND v_current = 1 AND v_events = 2 AND v_centre_hod = 'STUDENT_CENTRE_LOCKED'
            AND lj.programme_type = 'JUPEB' AND lj.faculty_code IS NULL AND lj.status = 'ACTIVE' AND lj.admission_route = 'JUPEB_APPLICATION' AND lj.jupeb_registered AND v_draft_absent
            AND lp.programme_type = 'PRELIMINARY' AND lp.programme_is_target AND lp.programme_code = v_ug AND lp.faculty_code = v_fac AND lp.status = 'ADMITTED'
            AND lp.admission_route = 'PRELIMINARY_APPLICATION' AND lp.study_mode = 'FULL_TIME'
            AND lp2.status = 'PROGRESSED' AND v_kind = 'PRELIMINARY_TO_UNDERGRADUATE' AND v_dup = 'PROGRESSION_RECORDED' AND v_name = 'PROGRESSION_NAME'
            AND v_register_ok AND v_ids_ok AND v_registry_ok AND v_future_ok AND v_bad_office = 'PROGRAMME_TYPE_OFFICE', false),
        format('named %s | conflicting %s/%s/%s/%s | cce %s/%s/%s/%s | pg %s/%s | refusals %s, %s, %s | decided %s/%s/%s/%s/%s, decisions %s current %s events %s, hod centre %s | jupeb %s/%s/%s/%s/%s, draft absent %s | prelim %s/%s/%s/%s/%s/%s | progressed %s, kind %s, again %s, other surname %s | register %s ids %s registry %s future %s bad office %s',
               v_named_ug, c2.programme_type, c2.proposed_type, c2.classification_status, c2.classification_issue,
               c3.programme_type, c3.admission_route, c3.centre_code, c3.study_mode, c4.programme_type, c4.admission_route,
               v_lecturer, v_noreason, v_jupeb_type, c2b.programme_type, c2b.type_source, c2b.admission_route, c2b.centre_code, c2b.centre_source,
               v_decisions, v_current, v_events, v_centre_hod,
               lj.programme_type, lj.faculty_code, lj.status, lj.admission_route, lj.jupeb_registered, v_draft_absent,
               lp.programme_type, lp.programme_is_target, lp.programme_code = v_ug, lp.status, lp.admission_route, lp.study_mode,
               lp2.status, v_kind, v_dup, v_name, v_register_ok, v_ids_ok, v_registry_ok, v_future_ok, v_bad_office));
END $$;
-- ── V472. The course registration history upload is checked before it writes, and never rewrites what is on record: the check
--    runs the load and undoes it (nothing stays); the upload adds only what is missing, a new course at the units the programme
--    takes it at; a re-upload leaves a dropped course dropped and a course's units as they are, saying so row by row; the old
--    import keeps its counts over the loader ──
DO $$
DECLARE
    v_prog text; v_dept text; st uuid := gen_random_uuid(); v_ses text := '9989/9990';
    v_rows jsonb; pv jsonb; up jsonb; again jsonb; g record;
    before_e bigint; before_r bigint; before_s bigint; after_e bigint; after_r bigint; after_s bigint;
    u1 int; u2 int; st1 text; u2b int; st_after text;
    statuses text; again_statuses text;
BEGIN
    PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
    PERFORM set_config('moaum.actor_office', 'records', true);
    PERFORM set_config('moaum.reason', 'CHECK V472', true);
    SELECT p.code, p.dept_code INTO v_prog, v_dept FROM ref.programme p WHERE p.category = 'UNDER GRADUATE' AND NOT p.archived ORDER BY p.code LIMIT 1;
    INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state) VALUES
        ('ZZQ 101', 'Check V472 one', 3, 1, 100, v_dept, 'Core', 'LIVE'),
        ('ZZQ 102', 'Check V472 two', 2, 1, 100, v_dept, 'Core', 'LIVE');
    INSERT INTO catalogue.course_offer (course_code, programme_code, level, units) VALUES ('ZZQ 101', v_prog, 100, 4);
    INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
    VALUES (st, 'MOAUM/ADM/89/472001', 'MOAUM/ZZQ/89/4721', 'CHECKV472', 'One', v_prog, 'UTME', '9989/9990', 100, 100, 'ACTIVE', now());
    v_rows := jsonb_build_array(
        jsonb_build_object('line', '2', 'matric', 'MOAUM/ZZQ/89/4721', 'course', 'ZZQ 101', 'level', '100'),
        jsonb_build_object('line', '3', 'matric', 'MOAUM/ZZQ/89/4721', 'course', 'zzq101'),
        jsonb_build_object('line', '4', 'matric', 'MOAUM/ZZQ/89/4721', 'course', 'ZZQ102'),
        jsonb_build_object('line', '5', 'matric', 'MOAUM/ZZQ/89/9999', 'course', 'ZZQ 101'),
        jsonb_build_object('line', '6', 'matric', 'MOAUM/ZZQ/89/4721', 'course', 'ZZQ 999'));

    SELECT count(*) INTO before_e FROM registration.entry;
    SELECT count(*) INTO before_r FROM registration.course_registration;
    SELECT count(*) INTO before_s FROM policy.academic_session;
    pv := assessment.legacy_semester_load(v_ses, 1, v_rows, false, true);
    SELECT count(*) INTO after_e FROM registration.entry;
    SELECT count(*) INTO after_r FROM registration.course_registration;
    SELECT count(*) INTO after_s FROM policy.academic_session;
    SELECT string_agg((l->>'line') || ':' || (l->>'status'), ',' ORDER BY (l->>'line')) INTO statuses FROM jsonb_array_elements(pv->'lines') l;

    up := assessment.legacy_semester_load(v_ses, 1, v_rows, false, false);
    SELECT e.units INTO u1 FROM registration.entry e JOIN registration.course_registration r ON r.id = e.registration_id JOIN catalogue.offering o ON o.id = e.offering_id
     WHERE r.student_id = st AND o.course_code = 'ZZQ 101';
    SELECT e.units INTO u2 FROM registration.entry e JOIN registration.course_registration r ON r.id = e.registration_id JOIN catalogue.offering o ON o.id = e.offering_id
     WHERE r.student_id = st AND o.course_code = 'ZZQ 102';

    -- on record, differently: ZZQ 101 dropped, ZZQ 102 at 5 units; the same file again leaves both
    UPDATE registration.entry e SET status = CASE o.course_code WHEN 'ZZQ 101' THEN 'DROPPED' ELSE e.status END,
                                    units = CASE o.course_code WHEN 'ZZQ 102' THEN 5 ELSE e.units END
      FROM registration.course_registration r, catalogue.offering o
     WHERE r.id = e.registration_id AND o.id = e.offering_id AND r.student_id = st;
    again := assessment.legacy_semester_load(v_ses, 1, v_rows, false, false);
    SELECT string_agg((l->>'line') || ':' || (l->>'status'), ',' ORDER BY (l->>'line')) INTO again_statuses FROM jsonb_array_elements(again->'lines') l;
    SELECT e.status INTO st1 FROM registration.entry e JOIN registration.course_registration r ON r.id = e.registration_id JOIN catalogue.offering o ON o.id = e.offering_id
     WHERE r.student_id = st AND o.course_code = 'ZZQ 101';
    SELECT e.units INTO u2b FROM registration.entry e JOIN registration.course_registration r ON r.id = e.registration_id JOIN catalogue.offering o ON o.id = e.offering_id
     WHERE r.student_id = st AND o.course_code = 'ZZQ 102';

    -- the old import's counts, over the loader: a result for the dropped course approves it, a missing student is held
    SELECT * INTO g FROM assessment.import_legacy_semester(v_ses, 1, jsonb_build_array(
        jsonb_build_object('matric', 'MOAUM/ZZQ/89/4721', 'course', 'ZZQ 101', 'total', '70'),
        jsonb_build_object('matric', 'MOAUM/ZZQ/89/9998', 'course', 'ZZQ 101', 'total', '50')), true);
    SELECT e.status INTO st_after FROM registration.entry e JOIN registration.course_registration r ON r.id = e.registration_id JOIN catalogue.offering o ON o.id = e.offering_id
     WHERE r.student_id = st AND o.course_code = 'ZZQ 101';

    PERFORM pg_temp.assert('V472: the registration history upload is checked first and the check leaves nothing; only what is missing is added, at the programme''s units; a re-upload leaves a dropped course and a course''s units as they are, row by row; the old import keeps its counts',
        coalesce(before_e = after_e AND before_r = after_r AND before_s = after_s
            AND statuses = '2:ADDED,3:DUPLICATE_IN_FILE,4:ADDED,5:NO_STUDENT,6:NO_COURSE'
            AND (pv->>'entries')::int = 2 AND (up->>'entries')::int = 2 AND (up->>'registrations')::int = 1
            AND (SELECT string_agg(l->>'status', ',' ORDER BY (l->>'line')) FROM jsonb_array_elements(up->'lines') l) = 'DUPLICATE_IN_FILE,NO_STUDENT,NO_COURSE'
            AND u1 = 4 AND u2 = 2
            AND again_statuses = '2:DROPPED_ON_RECORD,3:DUPLICATE_IN_FILE,4:UNITS_DIFFER,5:NO_STUDENT,6:NO_COURSE' AND (again->>'entries')::int = 0
            AND st1 = 'DROPPED' AND u2b = 5
            AND g.results = 1 AND g.held = 1 AND g.rows = 2 AND st_after = 'APPROVED', false),
        format('check left entries %s→%s regs %s→%s sessions %s→%s | check %s | upload entries %s regs %s, units %s/%s | again %s, dropped kept %s, units kept %s | old import results %s held %s rows %s, approved %s',
               before_e, after_e, before_r, after_r, before_s, after_s, statuses, up->>'entries', up->>'registrations', u1, u2,
               again_statuses, st1, u2b, g.results, g.held, g.rows, st_after));
END $$;


-- ── V474: PAYDirect answered on time — each notified payment recorded first, settled after ──
-- A payment Interswitch reports is recorded once by its PaymentLogId (a repeat counted on its row, a reversal its own row);
-- one settler takes it at a time; it ends SETTLED with its outcome, or FAILED for the sweeper, and a settled payment stays
-- settled; what still waits is listed once it has been quiet, never what a settler holds. The block undoes its writes.
DO $$
DECLARE a uuid; a2 uuid; r uuid; first jsonb; second jsonb; reps int; rows_for int; st text; oc text; claimed_after boolean;
        open_quiet boolean; open_now boolean; open_held boolean; stays text; failed_state text; failed_err text; msg text;
        lid text := 'CHK474-' || floor(random() * 1e9)::bigint;
BEGIN
    BEGIN
        a := finance.paydirect_receive(lid, false, 'moaum-fee-chk-474', 100, '{"PaymentLogId": "x", "CustReference": "MOAUM-FEE-CHK-474"}'::jsonb);
        a2 := finance.paydirect_receive(lid, false, 'MOAUM-FEE-CHK-474', 100, '{"PaymentLogId": "x", "CustReference": "MOAUM-FEE-CHK-474"}'::jsonb);
        r := finance.paydirect_receive(lid, true, 'MOAUM-FEE-CHK-474', 100, '{"IsReversal": "True"}'::jsonb);
        SELECT repeats INTO reps FROM finance.paydirect_inbox WHERE id = a;
        SELECT count(*) INTO rows_for FROM finance.paydirect_inbox WHERE payment_log_id = lid;
        -- one settler at a time
        first := finance.paydirect_claim(a);
        second := finance.paydirect_claim(a);
        open_held := a IN (SELECT finance.paydirect_open(interval '0 seconds', 1000));
        PERFORM finance.paydirect_done(a, true, 'confirmed', NULL);
        SELECT state, outcome, claimed_at IS NOT NULL INTO st, oc, claimed_after FROM finance.paydirect_inbox WHERE id = a;
        PERFORM finance.paydirect_done(a, false, NULL, 'a later failure');
        SELECT state INTO stays FROM finance.paydirect_inbox WHERE id = a;
        -- a failure waits for the sweeper, listed once quiet
        PERFORM finance.paydirect_claim(r);
        PERFORM finance.paydirect_done(r, false, NULL, 'the portal was busy');
        SELECT state, last_error INTO failed_state, failed_err FROM finance.paydirect_inbox WHERE id = r;
        open_now := r IN (SELECT finance.paydirect_open(interval '0 seconds', 1000));
        open_quiet := r IN (SELECT finance.paydirect_open(interval '1 hour', 1000));
        RAISE EXCEPTION 'the V474 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V474 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V474: a notified payment is recorded once by its PaymentLogId (a repeat counted, a reversal its own record), taken by one settler at a time, ends SETTLED or FAILED for the sweeper, stays settled, and is listed to settle only when quiet and not held',
        coalesce(a = a2 AND r <> a AND reps = 1 AND rows_for = 2 AND first IS NOT NULL AND second IS NULL AND NOT open_held
                 AND st = 'SETTLED' AND oc = 'confirmed' AND NOT claimed_after AND stays = 'SETTLED'
                 AND failed_state = 'FAILED' AND failed_err = 'the portal was busy' AND open_now AND NOT open_quiet, false),
        format('one record %s/%s, reversal apart %s, repeats %s, rows %s | claims %s/%s, held listed %s | %s %s claim left %s, then %s | failed %s "%s" listed now %s quiet %s',
               a = a2, rows_for, r <> a, reps, rows_for, first IS NOT NULL, second IS NOT NULL, open_held, st, oc, claimed_after, stays, failed_state, failed_err, open_now, open_quiet));
END $$;
-- ── V475. Spillover students brought to their level: a record below the level the cohort engine computes is listed with its
--    basis — a spillover student (past the programme's length) at the programme's final level, certain; one only the count of
--    sessions supports, for review; one above it never — and the Academic Office or the Registry raises them on a reason, the
--    spillover and own-registration ones by default, the others only when chosen; no level is lowered; each change is on the
--    cohort decision history ──
DO $$
DECLARE
    y int := 2186; v_prog text; v_dept text; v_fac text;
    s1 uuid := gen_random_uuid(); s2 uuid := gen_random_uuid(); s3 uuid := gen_random_uuid();
    c1 record; c2 record; in3 boolean; d record; a record; b record; e record;
    v_hod text; v_noreason text; l1 int; l2 int; l3 int; l2b int; dec record; conflict_gone boolean;
BEGIN
  BEGIN   -- the check's own sessions and students, undone at the end so no later check sees them
    PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
    PERFORM set_config('moaum.actor_office', 'registrar', true);
    PERFORM set_config('moaum.reason', 'CHECK V475', true);
    UPDATE policy.academic_session SET state = 'CLOSED', completed_at = now() WHERE state = 'CURRENT';
    INSERT INTO policy.academic_session (id, name, starts_on, ends_on, state)
    SELECT gen_random_uuid(), format('%s/%s', x, x + 1), make_date(x, 10, 1), make_date(x + 1, 9, 30), 'CLOSED' FROM generate_series(y - 5, y) x
    ON CONFLICT (name) DO NOTHING;
    UPDATE policy.academic_session SET state = 'CURRENT', made_current_at = now(), senate_minute = 'SEN/2186/01' WHERE name = format('%s/%s', y, y + 1);
    PERFORM set_config('moaum.actor_office', 'academic', true);
    SELECT dept_code, faculty_code INTO v_dept, v_fac FROM ref.programme WHERE category = 'UNDER GRADUATE' AND NOT archived ORDER BY code LIMIT 1;
    SELECT 'C' || lpad(x::text, 5, '0') INTO v_prog FROM generate_series(90000, 99999) x
     WHERE NOT EXISTS (SELECT 1 FROM ref.programme p WHERE p.code = 'C' || lpad(x::text, 5, '0')) ORDER BY x DESC LIMIT 1;
    INSERT INTO ref.programme (code, name, dept_code, faculty_code, category, min_score, final_level) VALUES (v_prog, 'B.Sc. CHECK V475', v_dept, v_fac, 'UNDER GRADUATE', 0, 400);
    INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at) VALUES
        (s1, 'MOAUM/ADM/75/475001', 'MOAUM/ZZL/75/4751', 'CHECKV475', 'Spillover', v_prog, 'UTME', format('%s/%s', y - 5, y - 4), 100, 100, 'ACTIVE', now()),
        (s2, 'MOAUM/ADM/75/475002', 'MOAUM/ZZL/75/4752', 'CHECKV475', 'Counted', v_prog, 'UTME', format('%s/%s', y - 2, y - 1), 100, 100, 'ACTIVE', now()),
        (s3, 'MOAUM/ADM/75/475003', 'MOAUM/ZZL/75/4753', 'CHECKV475', 'Higher', v_prog, 'UTME', format('%s/%s', y - 1, y), 100, 300, 'ACTIVE', now());

    SELECT * INTO c1 FROM people.level_correction WHERE student_id = s1;
    SELECT * INTO c2 FROM people.level_correction WHERE student_id = s2;
    in3 := EXISTS (SELECT 1 FROM people.level_correction WHERE student_id = s3);

    PERFORM set_config('moaum.actor_office', 'hod', true);
    BEGIN PERFORM people.apply_level_corrections(ARRAY[s1], NULL, NULL, NULL, NULL, 'not mine', NULL, 500, false);
    EXCEPTION WHEN insufficient_privilege THEN v_hod := split_part(SQLERRM, ':', 1); END;
    PERFORM set_config('moaum.actor_office', 'academic', true);
    BEGIN PERFORM people.apply_level_corrections(ARRAY[s1], NULL, NULL, NULL, NULL, ' ', NULL, 500, false);
    EXCEPTION WHEN check_violation THEN v_noreason := split_part(SQLERRM, ':', 1); END;

    SELECT * INTO d FROM people.apply_level_corrections(ARRAY[s1, s2, s3], NULL, NULL, NULL, NULL, NULL, NULL, 500, true);
    SELECT * INTO a FROM people.apply_level_corrections(ARRAY[s1, s2, s3], NULL, NULL, NULL, NULL, 'CHECK V475: migrated at 100 Level', 'CHK-475', 500, false);
    SELECT current_level INTO l1 FROM people.student WHERE id = s1;
    SELECT current_level INTO l2 FROM people.student WHERE id = s2;
    SELECT current_level INTO l3 FROM people.student WHERE id = s3;
    SELECT * INTO dec FROM people.cohort_decision WHERE student_id = s1 ORDER BY decided_at DESC LIMIT 1;
    conflict_gone := (SELECT current_level = computed_level AND NOT ('LEVEL_CONFLICT' = ANY (issues)) FROM people.academic_position WHERE student_id = s1);
    SELECT * INTO b FROM people.apply_level_corrections(ARRAY[s2], ARRAY['ARITHMETIC'], NULL, NULL, NULL, 'CHECK V475: chosen after review', NULL, 500, false);
    SELECT current_level INTO l2b FROM people.student WHERE id = s2;
    SELECT * INTO e FROM people.apply_level_corrections(ARRAY[s3], ARRAY['SPILLOVER', 'REGISTRATION', 'ARITHMETIC'], NULL, NULL, NULL, 'CHECK V475: never lowered', NULL, 500, false);
    RAISE EXCEPTION 'CHECK_V475_UNDONE' USING ERRCODE = 'P0001';
  EXCEPTION WHEN raise_exception THEN
    IF SQLERRM <> 'CHECK_V475_UNDONE' THEN RAISE; END IF;
  END;

    PERFORM pg_temp.assert('V475: a record below the computed level is listed with its basis and raised on a reason — spillover by default, a sessions-only one when chosen, never one above it, never lowered, each change on the cohort history',
        coalesce(c1.basis = 'SPILLOVER' AND c1.proposed_level = 400 AND c1.current_level = 100 AND c1.spillover_state = 'SPILLOVER_YEAR_2'
            AND c2.basis = 'ARITHMETIC' AND c2.proposed_level = 300 AND NOT in3
            AND v_hod = 'LEVEL_CORRECTION_OFFICE' AND v_noreason = 'LEVEL_CORRECTION_REASON'
            AND d.selected = 1 AND d.corrected = 0 AND d.spillover = 1
            AND a.corrected = 1 AND a.remaining = 0 AND l1 = 400 AND l2 = 100 AND l3 = 300
            AND dec.rule = 'LEVEL_SPILLOVER' AND dec.previous_level = 100 AND dec.new_level = 400 AND dec.batch_ref = 'CHK-475' AND conflict_gone
            AND b.corrected = 1 AND l2b = 300 AND e.selected = 0 AND e.corrected = 0, false),
        format('spillover %s %s→%s %s | counted %s →%s | higher listed %s | hod %s no reason %s | dry %s/%s/%s | applied %s left %s levels %s/%s/%s | decision %s %s→%s %s conflict gone %s | chosen %s → %s | higher %s/%s',
               c1.basis, c1.current_level, c1.proposed_level, c1.spillover_state, c2.basis, c2.proposed_level, in3, v_hod, v_noreason,
               d.selected, d.corrected, d.spillover, a.corrected, a.remaining, l1, l2, l3, dec.rule, dec.previous_level, dec.new_level, dec.batch_ref, conflict_gone,
               b.corrected, l2b, e.selected, e.corrected));
END $$;

-- ── V473. An issued document belongs to a student on the register: the key is there and validated; a document naming a
--          student not on the register is refused; a student and the documents removed together in one transaction (as the
--          operational reset does, students first) pass; no document here names a missing student. The block undoes its
--          writes ──
DO $$
DECLARE who uuid := gen_random_uuid(); st uuid := gen_random_uuid(); d1 uuid := gen_random_uuid(); d2 uuid := gen_random_uuid();
        v_valid boolean; v_deferrable boolean; together text := 'refused'; stranger text := 'accepted'; orphans int; msg text;
BEGIN
    SELECT c.convalidated, c.condeferrable INTO v_valid, v_deferrable FROM pg_constraint c WHERE c.conname = 'issued_student_id_fkey' AND c.conrelid = 'credentials.issued'::regclass;
    orphans := (SELECT count(*) FROM credentials.orphaned_documents());
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'registrar', true);
        PERFORM set_config('moaum.reason', 'check V473', true);
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status)
        VALUES (st, 'MOAUM/ADM/60/947301', 'CHECKV473', 'One', (SELECT code FROM ref.programme WHERE NOT coalesce(archived, false) ORDER BY code LIMIT 1), 'UTME',
                (SELECT name FROM policy.academic_session ORDER BY name LIMIT 1), 100, 100, 'ADMITTED');
        INSERT INTO credentials.issued (id, kind, student_id, verification_code, statement, signature, issuing_name, issued_on, issued_by, issued_office)
        VALUES (d1, 'TRANSCRIPT', st, credentials.new_code(), '{}'::jsonb, '\x00'::bytea, 'Check V473', current_date, who, 'registrar');
        -- removed together, the student first, as the reset does: nothing is left naming a missing student
        BEGIN
            DELETE FROM people.student WHERE id = st;
            DELETE FROM credentials.issued WHERE id = d1;
            SET CONSTRAINTS credentials.issued_student_id_fkey IMMEDIATE;
            together := 'accepted';
        EXCEPTION WHEN foreign_key_violation THEN together := 'refused';
        END;
        -- a document naming a student who is not on the register
        BEGIN
            INSERT INTO credentials.issued (id, kind, student_id, verification_code, statement, signature, issuing_name, issued_on, issued_by, issued_office)
            VALUES (d2, 'TRANSCRIPT', gen_random_uuid(), credentials.new_code(), '{}'::jsonb, '\x00'::bytea, 'Check V473', current_date, who, 'registrar');
            SET CONSTRAINTS credentials.issued_student_id_fkey IMMEDIATE;
            stranger := 'accepted';
        EXCEPTION WHEN foreign_key_violation THEN stranger := 'refused';
        END;
        RAISE EXCEPTION 'the V473 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V473 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V473: an issued document names a student on the register — refused for a stranger, removed with its student in one transaction, none orphaned',
        coalesce(v_valid AND v_deferrable AND together = 'accepted' AND stranger = 'refused' AND orphans = 0, false),
        format('key validated %s deferrable %s | removed together: %s | a stranger''s document: %s | orphaned %s', v_valid, v_deferrable, together, stranger, orphans));
END $$;
-- ── V476. A student's own progression counts as evidence for their level: one who registered in the session just before at
--    one level below the computed level is raised by default with the spillover students; one who registered this session at
--    a lower level, or two sessions back, stays for review ──
DO $$
DECLARE
    y int := 2186; v_prog text; v_dept text; v_fac text; who uuid := gen_random_uuid();
    s1 uuid := gen_random_uuid(); s2 uuid := gen_random_uuid(); s3 uuid := gen_random_uuid();
    b1 text; b2 text; b3 text; p1 int; a record; l1 int; l2 int; l3 int;
BEGIN
  BEGIN   -- the check's own sessions and students, undone at the end
    PERFORM set_config('moaum.actor_id', who::text, true);
    PERFORM set_config('moaum.actor_office', 'registrar', true);
    PERFORM set_config('moaum.reason', 'CHECK V476', true);
    UPDATE policy.academic_session SET state = 'CLOSED', completed_at = now() WHERE state = 'CURRENT';
    INSERT INTO policy.academic_session (id, name, starts_on, ends_on, state)
    SELECT gen_random_uuid(), format('%s/%s', x, x + 1), make_date(x, 10, 1), make_date(x + 1, 9, 30), 'CLOSED' FROM generate_series(y - 5, y) x
    ON CONFLICT (name) DO NOTHING;
    UPDATE policy.academic_session SET state = 'CURRENT', made_current_at = now(), senate_minute = 'SEN/2186/01' WHERE name = format('%s/%s', y, y + 1);
    PERFORM set_config('moaum.actor_office', 'academic', true);
    SELECT dept_code, faculty_code INTO v_dept, v_fac FROM ref.programme WHERE category = 'UNDER GRADUATE' AND NOT archived ORDER BY code LIMIT 1;
    SELECT 'C' || lpad(x::text, 5, '0') INTO v_prog FROM generate_series(90000, 99999) x
     WHERE NOT EXISTS (SELECT 1 FROM ref.programme p WHERE p.code = 'C' || lpad(x::text, 5, '0')) ORDER BY x DESC LIMIT 1;
    INSERT INTO ref.programme (code, name, dept_code, faculty_code, category, min_score, final_level) VALUES (v_prog, 'LL.B CHECK V476', v_dept, v_fac, 'UNDER GRADUATE', 0, 500);
    -- three Direct Entry students of 2183/2184 at 200, a five-level programme: the engine puts each at 500 in 2186/2187
    INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at) VALUES
        (s1, 'MOAUM/ADM/76/476001', 'MOAUM/ZZD/76/4761', 'CHECKV476', 'Last session', v_prog, 'DIRECT_ENTRY', format('%s/%s', y - 3, y - 2), 200, 400, 'ACTIVE', now()),
        (s2, 'MOAUM/ADM/76/476002', 'MOAUM/ZZD/76/4762', 'CHECKV476', 'This session', v_prog, 'DIRECT_ENTRY', format('%s/%s', y - 3, y - 2), 200, 400, 'ACTIVE', now()),
        (s3, 'MOAUM/ADM/76/476003', 'MOAUM/ZZD/76/4763', 'CHECKV476', 'Long ago', v_prog, 'DIRECT_ENTRY', format('%s/%s', y - 3, y - 2), 200, 300, 'ACTIVE', now());
    INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, submitted_at, approved_at, approved_by) VALUES
        (gen_random_uuid(), s1, format('%s/%s', y - 1, y), 1, 400, 'APPROVED', now(), now(), who),
        (gen_random_uuid(), s2, format('%s/%s', y, y + 1), 1, 400, 'APPROVED', now(), now(), who),
        (gen_random_uuid(), s3, format('%s/%s', y - 2, y - 1), 1, 300, 'APPROVED', now(), now(), who);
    SELECT basis, proposed_level INTO b1, p1 FROM people.level_correction WHERE student_id = s1;
    SELECT basis INTO b2 FROM people.level_correction WHERE student_id = s2;
    SELECT basis INTO b3 FROM people.level_correction WHERE student_id = s3;
    SELECT * INTO a FROM people.apply_level_corrections(ARRAY[s1, s2, s3], NULL, NULL, NULL, NULL, 'CHECK V476: own progression', NULL, 500, false);
    SELECT current_level INTO l1 FROM people.student WHERE id = s1;
    SELECT current_level INTO l2 FROM people.student WHERE id = s2;
    SELECT current_level INTO l3 FROM people.student WHERE id = s3;
    RAISE EXCEPTION 'CHECK_V476_UNDONE' USING ERRCODE = 'P0001';
  EXCEPTION WHEN raise_exception THEN
    IF SQLERRM <> 'CHECK_V476_UNDONE' THEN RAISE; END IF;
  END;
    PERFORM pg_temp.assert('V476: a student who registered in the session just before at one level below is raised by default; one registered this session lower, or two sessions back, stays for review',
        coalesce(b1 = 'REGISTRATION' AND p1 = 500 AND b2 = 'ARITHMETIC' AND b3 = 'ARITHMETIC'
            AND a.corrected = 1 AND a.registration = 1 AND l1 = 500 AND l2 = 400 AND l3 = 300, false),
        format('last session %s →%s | this session %s | long ago %s | applied %s (registration %s) | levels %s/%s/%s', b1, p1, b2, b3, a.corrected, a.registration, l1, l2, l3));
END $$;

-- ── V477. Pay on Quickteller payments unreported after a day: a reference opened on Pay on Quickteller 30 hours before, one
--          opened 2 hours before and one opened on a card gateway 30 hours before. Only the first is listed; at 10:00 Lagos
--          time a Bursary office holder is told of it by e-mail and on the portal, the same day not again, and at 07:00 nobody.
--          The block undoes its writes ──
DO $$
DECLARE who uuid := gen_random_uuid(); bur uuid := gen_random_uuid(); st uuid := gen_random_uuid(); v_ses text;
        at10 timestamptz := (date_trunc('day', now() AT TIME ZONE 'Africa/Lagos') + interval '10 hours') AT TIME ZONE 'Africa/Lagos';
        at07 timestamptz; listed text; told1 int; told2 int; told3 int; got text; got2 int; msg text;
BEGIN
    at07 := at10 + interval '21 hours';   -- 07:00 the next day
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM set_config('moaum.reason', 'check V477', true);
        UPDATE finance.paydirect_setting SET watch_enabled = true;
        INSERT INTO iam.person (id, surname, given_names, email) VALUES (bur, 'CHECKV477', 'Bursar', 'zz.check477@example.com');
        INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from)
        VALUES (gen_random_uuid(), bur, 'bursar', 'institution', NULL, 'check V477', who, current_date - 1);
        v_ses := (SELECT name FROM policy.academic_session ORDER BY name LIMIT 1);
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status)
        VALUES (st, 'MOAUM/ADM/60/947701', 'CHECKV477', 'Payer', (SELECT code FROM ref.programme WHERE NOT coalesce(archived, false) ORDER BY code LIMIT 1), 'UTME', v_ses, 100, 100, 'ADMITTED');
        INSERT INTO finance.payment_reference (student_id, session, reference, purpose, amount, expires_at) VALUES
          (st, v_ses, 'MOAUM-FEE-947701-0001', 'check V477', 53488.42, now() + interval '30 days'),
          (st, v_ses, 'MOAUM-FEE-947701-0002', 'check V477', 100.00, now() + interval '30 days'),
          (st, v_ses, 'MOAUM-FEE-947701-0003', 'check V477', 200.00, now() + interval '30 days');
        INSERT INTO finance.gateway_attempt (reference, gateway, kind, account_id, opened_at) VALUES
          ('MOAUM-FEE-947701-0001', 'paydirect', 'FEE', st, at10 - interval '30 hours'),
          ('MOAUM-FEE-947701-0002', 'paydirect', 'FEE', st, at10 - interval '2 hours'),
          ('MOAUM-FEE-947701-0003', 'paystack', 'FEE', st, at10 - interval '30 hours');
        listed := (SELECT string_agg(u.reference, ',' ORDER BY u.reference) FROM finance.paydirect_unreported(at10) u WHERE u.reference LIKE 'MOAUM-FEE-947701-%');
        told1 := finance.watch_paydirect_unreported(at10);
        -- the e-mail carries the list; the portal notice says how many and what to do
        got := (SELECT string_agg(n.channel || CASE WHEN n.body LIKE '%MOAUM-FEE-947701-0001%' THEN '+list' ELSE '' END, ',' ORDER BY n.channel)
                  FROM platform.notice n WHERE n.about_kind = 'person' AND n.about_id = bur AND n.template_key = 'PAYDIRECT_UNREPORTED');
        told2 := finance.watch_paydirect_unreported(at10 + interval '3 hours');
        got2 := (SELECT count(*) FROM platform.notice n WHERE n.about_kind = 'person' AND n.about_id = bur AND n.template_key = 'PAYDIRECT_UNREPORTED');
        told3 := finance.watch_paydirect_unreported(at07);
        RAISE EXCEPTION 'the V477 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V477 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V477: a Pay on Quickteller payment unreported after a day is told to the Bursary once a day, in the working day — not one opened hours ago, not a card checkout',
        coalesce(listed = 'MOAUM-FEE-947701-0001' AND told1 >= 1 AND got = 'EMAIL+list,PORTAL' AND got2 = 2 AND told3 = 0, false),
        format('listed %s | told at 10:00 %s, to the bursar by %s | three hours later %s, notices kept %s | at 07:00 %s', listed, told1, got, told2, got2, told3));
END $$;


-- ── V478: department course allocation templates, issued and numbered ──
-- A template is issued for a department of the register, numbered in its year (CAT-YYYY-NNNNNN), one after another, with the
-- department's faculty, the programme type, session and semester, and what it carried; an unknown department, or no person
-- acting, is refused. An import record carries the template it came from, the programme type and the ticket. The block undoes
-- its writes.
DO $$
DECLARE r1 record; r2 record; d text; f text; fmt_ok boolean; seq_ok boolean; rec_ok boolean; bad_dept text := ''; no_actor text := ''; cols int; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', '00000000-0000-0000-0000-000000000000', true);
        PERFORM set_config('moaum.actor_office', 'ict', true);
        PERFORM set_config('moaum.reason', 'check V478', true);
        SELECT code, faculty_code INTO d, f FROM ref.department WHERE ended_on IS NULL ORDER BY code LIMIT 1;
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), '9998/9999', date '9998-01-01', date '9998-12-31') ON CONFLICT (name) DO NOTHING;
        SELECT * INTO r1 FROM catalogue.issue_allocation_template(lower(d), 'UNDERGRADUATE', '9998/9999', 1, 3, 4, 2, 1, NULL);
        SELECT * INTO r2 FROM catalogue.issue_allocation_template(d, 'POSTGRADUATE', '9998/9999', 2, 0, 0, 0, 0, NULL);
        fmt_ok := r1.reference ~ '^CAT-[0-9]{4}-[0-9]{6}$' AND r2.reference ~ '^CAT-[0-9]{4}-[0-9]{6}$' AND r1.version = 1;
        seq_ok := right(r2.reference, 6)::int = right(r1.reference, 6)::int + 1;
        rec_ok := EXISTS (SELECT 1 FROM catalogue.allocation_template t WHERE t.id = r1.id AND t.dept_code = d AND t.faculty_code IS NOT DISTINCT FROM f
                           AND t.programme_type = 'UNDERGRADUATE' AND t.session = '9998/9999' AND t.semester = 1 AND t.classes = 3 AND t.lecturers = 4
                           AND t.programmes = 2 AND t.allocations = 1 AND t.issued_office = 'ict');
        BEGIN PERFORM catalogue.issue_allocation_template('ZZNODEPT', 'UNDERGRADUATE', '9998/9999', 1, 0, 0, 0, 0, NULL);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS bad_dept = MESSAGE_TEXT; END;
        PERFORM set_config('moaum.actor_id', '', true);
        BEGIN PERFORM catalogue.issue_allocation_template(d, 'UNDERGRADUATE', '9998/9999', 1, 0, 0, 0, 0, NULL);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS no_actor = MESSAGE_TEXT; END;
        SELECT count(*) INTO cols FROM information_schema.columns
         WHERE table_schema = 'catalogue' AND table_name = 'allocation_import' AND column_name IN ('template_id', 'programme_type', 'ticket_id');
        RAISE EXCEPTION 'the V478 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V478 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V478: a department course allocation template is issued for a department of the register, numbered CAT-YYYY-NNNNNN one after another, with its faculty, programme type, session, semester and counts; an unknown department or no person acting refused; an import carries its template, programme type and ticket',
        coalesce(fmt_ok AND seq_ok AND rec_ok AND bad_dept LIKE 'ALLOC_TEMPLATE_DEPT:%' AND no_actor LIKE 'ALLOC_TEMPLATE_ACTOR:%' AND cols = 3, false),
        format('format %s sequence %s record %s | unknown department "%s" | no actor "%s" | import columns %s', fmt_ok, seq_ok, rec_ok, bad_dept, no_actor, cols));
END $$;
-- ── V479. The Post-UTME paid applicants report: one row an application; paid only when an APPLICATION fee reference is
--    confirmed — a pending, a reversed or an acceptance-only payment is never paid, a second confirmed attempt is counted and
--    never a second row; a Preliminary applicant is not a Post-UTME applicant; JAMB's aggregate and gender from CAPS, a Direct
--    Entry candidate without an aggregate, the old portal's placeholder contacts said to be missing; each download recorded ──
DO $$
DECLARE
    ses text := '9479/9480'; who uuid := gen_random_uuid(); v_batch uuid := gen_random_uuid(); pcode text; pname text;
    r record; cand uuid; acct uuid; app uuid; apps jsonb := '{}'::jsonb;
    n_rows int; n_apps int; n_paid int; st text; p1 record; d1 record; prelim_in boolean; ex_rows int; ex_bad text; ex_filters jsonb;
BEGIN
  BEGIN   -- the check's own applicants, undone at the end
    PERFORM set_config('moaum.actor_id', who::text, true);
    PERFORM set_config('moaum.actor_office', 'academic', true);
    PERFORM set_config('moaum.reason', 'CHECK V479', true);
    SELECT code, name INTO pcode, pname FROM ref.programme WHERE category = 'UNDER GRADUATE' AND NOT archived ORDER BY code LIMIT 1;
    INSERT INTO admissions.caps_batch (id, session, source, list_kind, file_sha256, rows_read, downloaded_on, uploaded_by, uploaded_office)
    VALUES (v_batch, ses, 'CAPS_DOWNLOAD', 'UTME', '\xB479'::bytea, 1, current_date, who, 'academic');
    -- P1 paid on two attempts (gender and aggregate only on JAMB's record), P2 pending, P3 reversed, P4 acceptance fee only,
    -- D1 Direct Entry paid with the old portal's placeholder contacts, R1 a Preliminary applicant who paid
    FOR r IN SELECT * FROM (VALUES
        ('P1', 'UTME', '20947990001', 100, 'zz.check479p1@example.com', '08034790001', '479001'),
        ('P2', 'UTME', '20947990002', 100, 'zz.check479p2@example.com', '08034790002', '479002'),
        ('P3', 'UTME', '20947990003', 100, 'zz.check479p3@example.com', '08034790003', '479003'),
        ('P4', 'UTME', '20947990004', 100, 'zz.check479p4@example.com', '08034790004', '479004'),
        ('D1', 'DIRECT_ENTRY', '20947990005', 200, '20947990005@migrate.moau.local', '00000000000', '479005'),
        ('R1', 'PRELIMINARY', NULL, 0, 'zz.check479r1@example.com', '08034790006', '479006')
    ) AS t(tag, mode, jamb, lvl, email, phone, seq)
    LOOP
        cand := gen_random_uuid(); acct := gen_random_uuid(); app := gen_random_uuid();
        INSERT INTO admissions.candidate (id, session, jamb_reg_no, surname, other_names, programme, entry_mode, entry_level, offer_state, sex)
        VALUES (cand, ses, r.jamb, 'CHECKV479', r.tag, CASE WHEN r.mode = 'PRELIMINARY' THEN 'Preliminary Science' ELSE pname END, r.mode, r.lvl, 'PROPOSED',
                CASE WHEN r.tag = 'P1' THEN NULL ELSE 'M' END);
        INSERT INTO admissions.applicant_account (id, session, candidate_id, jamb_key, email, phone, password_hash)
        VALUES (acct, ses, cand, r.jamb, r.email, r.phone, 'SET_ON_FIRST_LOGIN');
        INSERT INTO admissions.application (id, account_id, candidate_id, session, application_no) VALUES (app, acct, cand, ses, 'APP/79/' || r.seq);
        apps := apps || jsonb_build_object(r.tag, app);
    END LOOP;
    INSERT INTO admissions.caps_row (id, batch_id, session, jamb_reg_no, raw, surname, other_names, jamb_code, aggregate, entry_mode, sex)
    VALUES (gen_random_uuid(), v_batch, ses, '20947990001', '{}'::jsonb, 'CHECKV479', 'P1', pcode, 260, 'UTME', 'F');
    INSERT INTO admissions.fee_reference (id, application_id, kind, reference, amount, expires_at, confirmed_at, confirmed_by, channel, receipt_no) VALUES
        (gen_random_uuid(), (apps->>'P1')::uuid, 'APPLICATION', 'CHK479-P1-A', 2000, now() + interval '1 day', now() - interval '2 days', who, 'CARD', 'RC479-P1-A'),
        (gen_random_uuid(), (apps->>'P1')::uuid, 'APPLICATION', 'CHK479-P1-B', 2000, now() + interval '1 day', now() - interval '1 day', who, 'CARD', 'RC479-P1-B'),
        (gen_random_uuid(), (apps->>'P1')::uuid, 'APPLICATION', 'CHK479-P1-C', 2000, now() + interval '1 day', NULL, NULL, NULL, NULL),
        (gen_random_uuid(), (apps->>'P2')::uuid, 'APPLICATION', 'CHK479-P2-A', 2000, now() + interval '1 day', NULL, NULL, NULL, NULL),
        (gen_random_uuid(), (apps->>'P3')::uuid, 'APPLICATION', 'CHK479-P3-A', 2000, now() + interval '1 day', NULL, NULL, NULL, NULL),
        (gen_random_uuid(), (apps->>'P4')::uuid, 'ACCEPTANCE', 'CHK479-P4-A', 5000, now() + interval '1 day', now() - interval '1 day', who, 'CARD', 'RC479-P4-A'),
        (gen_random_uuid(), (apps->>'D1')::uuid, 'APPLICATION', 'CHK479-D1-A', 2000, now() + interval '1 day', now() - interval '1 day', who, 'BANK', 'RC479-D1-A'),
        (gen_random_uuid(), (apps->>'R1')::uuid, 'APPLICATION', 'CHK479-R1-A', 2000, now() + interval '1 day', now() - interval '1 day', who, 'CARD', 'RC479-R1-A');
    -- the Bursary reversed P3's payment: the reversal keeps what was confirmed, the reference no longer is
    INSERT INTO admissions.fee_reversal (fee_reference_id, application_id, reference, kind, amount, confirmed_at, confirmed_by, channel, receipt_no, reason, reversed_by, reversed_office)
    SELECT f.id, f.application_id, f.reference, f.kind, f.amount, now() - interval '3 days', who, 'CARD', 'RC479-P3-A', 'CHECK V479: paid on a wrong reference', who, 'bursar'
      FROM admissions.fee_reference f WHERE f.reference = 'CHK479-P3-A';

    SELECT count(*), count(DISTINCT application_id), count(*) FILTER (WHERE payment_status = 'VERIFIED') INTO n_rows, n_apps, n_paid
      FROM admissions.post_utme_paid_applicants(ses);
    SELECT string_agg(other_names || '=' || payment_status, ',' ORDER BY other_names) INTO st FROM admissions.post_utme_paid_applicants(ses);
    SELECT * INTO p1 FROM admissions.post_utme_paid_applicants(ses) WHERE other_names = 'P1';
    SELECT * INTO d1 FROM admissions.post_utme_paid_applicants(ses) WHERE other_names = 'D1';
    prelim_in := EXISTS (SELECT 1 FROM admissions.post_utme_paid_applicants(ses) WHERE other_names = 'R1');

    -- a download is recorded with its filters and rows; a format the report does not offer is refused
    INSERT INTO admissions.report_export (report, session, format, filters, row_count, exported_by, office)
    VALUES ('POST_UTME_PAID_APPLICANTS', ses, 'XLSX', '{"status": "VERIFIED", "gender": "F"}', 2, who, 'academic');
    SELECT count(*), (array_agg(filters))[1] INTO ex_rows, ex_filters FROM admissions.report_export WHERE session = ses AND exported_by = who;
    BEGIN
        INSERT INTO admissions.report_export (report, session, format, row_count) VALUES ('POST_UTME_PAID_APPLICANTS', ses, 'CSV', 0);
        ex_bad := 'accepted';
    EXCEPTION WHEN check_violation THEN ex_bad := 'refused';
    END;
    RAISE EXCEPTION 'CHECK_V479_UNDONE' USING ERRCODE = 'P0001';
  EXCEPTION WHEN raise_exception THEN
    IF SQLERRM <> 'CHECK_V479_UNDONE' THEN RAISE; END IF;
  END;
    PERFORM pg_temp.assert('V479: a Post-UTME applicant is paid only on a confirmed APPLICATION fee — one row an application, attempts counted, a reversal or an acceptance fee never paid, Preliminary not listed; JAMB''s aggregate and gender, placeholder contacts missing',
        coalesce(n_rows = 5 AND n_apps = 5 AND n_paid = 2 AND NOT prelim_in
            AND st = 'D1=VERIFIED,P1=VERIFIED,P2=PENDING,P3=REVERSED,P4=NOT_STARTED'
            AND p1.verified_payments = 2 AND p1.payment_reference = 'CHK479-P1-A' AND p1.receipt_no = 'RC479-P1-A' AND p1.sex = 'F' AND p1.utme_aggregate = 260
            AND p1.programme_code = pcode AND p1.faculty_code IS NOT NULL AND p1.full_name = 'CHECKV479, P1' AND cardinality(p1.missing) = 0
            AND d1.utme_aggregate IS NULL AND d1.phone IS NULL AND d1.email IS NULL AND array_to_string(d1.missing, ',') = 'PHONE,EMAIL', false),
        format('rows %s (apps %s, paid %s) | %s | P1 attempts %s ref %s sex %s agg %s prog %s missing %s | D1 agg %s phone %s email %s missing %s | prelim listed %s',
               n_rows, n_apps, n_paid, st, p1.verified_payments, p1.payment_reference, p1.sex, p1.utme_aggregate, p1.programme_code, p1.missing,
               d1.utme_aggregate, d1.phone, d1.email, d1.missing, prelim_in));
    PERFORM pg_temp.assert('V479: each download of the report is recorded — the session, the format, the filters and the rows; only Excel or PDF',
        coalesce(ex_rows = 1 AND ex_filters->>'gender' = 'F' AND ex_bad = 'refused', false),
        format('recorded %s filters %s | CSV %s', ex_rows, ex_filters, ex_bad));
END $$;


-- ── V481: a Pay on Quickteller payment recorded and not settled is told ──
-- A payment Interswitch reported and still not settled ten minutes after it last reported it is listed (a fresh one, or a
-- settled one, is not); the Bursary's and the Directorate of ICT's office holders are told; told again in the same hour,
-- nobody is (the event key). The block undoes its writes.
DO $$
DECLARE p uuid := gen_random_uuid(); stale uuid; fresh uuid; done uuid; listed text; told1 int; told2 int; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', '00000000-0000-0000-0000-000000000000', true);
        PERFORM set_config('moaum.actor_office', 'ict', true);
        PERFORM set_config('moaum.reason', 'check V481', true);
        INSERT INTO iam.person (id, staff_number, surname, given_names, email) VALUES (p, 'ZZ-CHK-481', 'CHECKV481', 'Invented', 'check481@example.com');
        INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from)
        VALUES (gen_random_uuid(), p, 'bursar', 'platform', NULL, 'check V481', p, current_date);
        stale := finance.paydirect_receive('CHK481-1', false, 'MOAUM-FEE-CHK-4811', 5000, '{"PaymentLogId": "CHK481-1"}'::jsonb);
        fresh := finance.paydirect_receive('CHK481-2', false, 'MOAUM-FEE-CHK-4812', 5000, '{"PaymentLogId": "CHK481-2"}'::jsonb);
        done := finance.paydirect_receive('CHK481-3', false, 'MOAUM-FEE-CHK-4813', 5000, '{"PaymentLogId": "CHK481-3"}'::jsonb);
        UPDATE finance.paydirect_inbox SET last_received_at = now() - interval '20 minutes', received_at = now() - interval '20 minutes' WHERE id IN (stale, done);
        PERFORM finance.paydirect_done(done, true, 'confirmed', NULL);
        PERFORM finance.paydirect_done(stale, false, NULL, 'the database was busy');
        SELECT string_agg(u.payment_log_id, ',' ORDER BY u.payment_log_id) INTO listed FROM finance.paydirect_unsettled(now()) u WHERE u.payment_log_id LIKE 'CHK481-%';
        told1 := finance.watch_paydirect_inbox(now());
        told2 := finance.watch_paydirect_inbox(now());
        RAISE EXCEPTION 'the V481 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V481 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V481: a Pay on Quickteller payment reported and not settled past ten minutes is listed (not a fresh or settled one) and told to the Bursary and the Directorate of ICT, once an hour',
        coalesce(listed = 'CHK481-1' AND told1 > 0 AND told2 = 0, false),
        format('listed %s | told %s then %s', listed, told1, told2));
END $$;


-- ── V482: prerequisites at registration ──
-- The rule starts ADVISORY; only the Academic Office sets it, with a reason. A course's prerequisite is unmet until a published
-- graded pass is on the student's record, and met for a student who entered above its level; under ADVISORY the ICT Support
-- check is advisory and names it, under ENFORCED a rule the override sets aside. The block undoes its writes.
DO $$
DECLARE st uuid := gen_random_uuid(); de uuid := gen_random_uuid(); o1 uuid := gen_random_uuid(); o2 uuid := gen_random_uuid();
        reg uuid := gen_random_uuid(); sh uuid := gen_random_uuid(); prog text; v_ses text;
        start_mode text; office_refused boolean := false; before text; de_unmet text; after_pass text;
        adv_rule text; enf_rule text; enf_passed text; msg text;
BEGIN
    start_mode := registration.prerequisite_mode();
    BEGIN
        PERFORM set_config('moaum.actor_id', '00000000-0000-0000-0000-000000000000', true);
        PERFORM set_config('moaum.reason', 'check V482', true);
        PERFORM set_config('moaum.actor_office', 'hod', true);
        BEGIN
            PERFORM registration.set_prerequisite_mode('ENFORCED', 'check V482');
        EXCEPTION WHEN check_violation THEN office_refused := SQLERRM LIKE 'PREREQUISITE_MODE_OFFICE:%';
        END;
        PERFORM set_config('moaum.actor_office', 'academic', true);
        prog := (SELECT p.code FROM ref.programme p WHERE p.category = 'UNDER GRADUATE' AND NOT coalesce(p.archived, false) ORDER BY p.code LIMIT 1);
        v_ses := (SELECT name FROM policy.academic_session ORDER BY name LIMIT 1);
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, state) VALUES
          ('ZQP 101', 'Check prerequisite course', 2, 1, 100, (SELECT dept_code FROM ref.programme WHERE code = prog), 'LIVE'),
          ('ZQP 201', 'Check course with a prerequisite', 2, 1, 200, (SELECT dept_code FROM ref.programme WHERE code = prog), 'LIVE');
        INSERT INTO catalogue.course_prerequisite (course_code, requires_code) VALUES ('ZQP 201', 'ZQP 101');
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status) VALUES
          (st, 'MOAUM/ADM/60/948201', 'CHECKV482', 'Utme', prog, 'UTME', v_ses, 100, 200, 'ADMITTED'),
          (de, 'MOAUM/ADM/60/948202', 'CHECKV482', 'Direct', prog, 'DIRECT_ENTRY', v_ses, 200, 200, 'ADMITTED');
        before := array_to_string(registration.prerequisites_unmet(st, 'ZQP 201'), ',');
        de_unmet := array_to_string(registration.prerequisites_unmet(de, 'ZQP 201'), ',');
        INSERT INTO catalogue.offering (id, course_code, session, semester) VALUES (o1, 'ZQP 101', v_ses, 1), (o2, 'ZQP 201', v_ses, 1);
        -- under ADVISORY the support check is advisory and says what is not yet passed
        SELECT k.advisory || ':' || k.overridable || ':' || k.passed || ':' || (k.message LIKE 'Not yet passed: ZQP 101.%') INTO adv_rule
          FROM registration.support_add_checks(st, v_ses, 1, o2) k WHERE k.rule = 'PREREQUISITES';
        PERFORM registration.set_prerequisite_mode('ENFORCED', 'check V482');
        SELECT k.advisory || ':' || k.overridable || ':' || k.passed INTO enf_rule
          FROM registration.support_add_checks(st, v_ses, 1, o2) k WHERE k.rule = 'PREREQUISITES';
        -- the pass published: met
        INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, submitted_at, approved_at)
        VALUES (reg, st, v_ses, 1, 100, 'APPROVED', now(), now());
        INSERT INTO registration.entry (registration_id, offering_id, units, status) VALUES (reg, o1, 2, 'APPROVED');
        INSERT INTO assessment.score_sheet (id, offering_id, stage, senate_minute, published_at, submitted_at) VALUES (sh, o1, 'PUBLISHED', 'SEN/CHK/482', now(), now());
        INSERT INTO assessment.score (sheet_id, student_id, ca, exam, outcome) VALUES (sh, st, 25, 45, 'GRADED');
        after_pass := array_to_string(registration.prerequisites_unmet(st, 'ZQP 201'), ',');
        SELECT k.passed::text INTO enf_passed FROM registration.support_add_checks(st, v_ses, 2, o2) k WHERE k.rule = 'PREREQUISITES';
        RAISE EXCEPTION 'the V482 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V482 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V482: prerequisites start advisory and only the Academic Office enforces them; a prerequisite is unmet until a published pass (met for a student who entered above it); advisory at the support desk, then a rule the override sets aside',
        coalesce(start_mode = 'ADVISORY' AND office_refused AND before = 'ZQP 101' AND de_unmet = '' AND adv_rule = 'true:false:true:true'
                 AND enf_rule = 'false:true:false' AND after_pass = '' AND enf_passed = 'true' AND registration.prerequisite_mode() = 'ADVISORY', false),
        format('start %s | hod refused %s | unmet %s | DE unmet %s | advisory %s | enforced %s | after pass %s / %s | now %s',
               start_mode, office_refused, before, de_unmet, adv_rule, enf_rule, after_pass, enf_passed, registration.prerequisite_mode()));
END $$;


-- ── V483: postgraduate specialisations ──
-- A postgraduate programme's specialisations are its own (an undergraduate programme has none); a binding named for one is on
-- that specialisation's students' menus only, a binding named for none on every student's; a student without one sees the
-- courses for every student; a student reads only a specialisation of their own programme. The block undoes its writes.
DO $$
DECLARE pg text; other text; ug text; v_ses text; lvl int; a uuid; b uuid; foreign_spec uuid; s_a uuid := gen_random_uuid(); s_b uuid := gen_random_uuid();
        s_none uuid := gen_random_uuid(); ug_refused boolean := false; other_refused boolean := false;
        menu_a text; menu_b text; menu_none text; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', '00000000-0000-0000-0000-000000000000', true);
        PERFORM set_config('moaum.actor_office', 'pgschool', true);
        PERFORM set_config('moaum.reason', 'check V483', true);
        SELECT p.code, admissions.pg_award_level(p.pg_award) INTO pg, lvl FROM ref.programme p
         WHERE p.category = 'POST GRADUATE' AND NOT coalesce(p.archived, false) ORDER BY p.code LIMIT 1;
        other := (SELECT p.code FROM ref.programme p WHERE p.category = 'POST GRADUATE' AND p.code <> pg AND NOT coalesce(p.archived, false) ORDER BY p.code LIMIT 1);
        ug := (SELECT p.code FROM ref.programme p WHERE p.category = 'UNDER GRADUATE' AND NOT coalesce(p.archived, false) ORDER BY p.code LIMIT 1);
        v_ses := (SELECT name FROM policy.academic_session ORDER BY name LIMIT 1);
        BEGIN
            PERFORM catalogue.save_specialisation(ug, 'OPT', 'An undergraduate option');
        EXCEPTION WHEN check_violation THEN ug_refused := SQLERRM LIKE 'PG_SPECIALISATION_PROGRAMME:%';
        END;
        a := catalogue.save_specialisation(pg, 'mon', 'Check monetary');
        b := catalogue.save_specialisation(pg, 'DEV', 'Check development');
        foreign_spec := catalogue.save_specialisation(other, 'MON', 'Check monetary');
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, state) VALUES
          ('ZZS 801', 'Check course for every student', 3, 1, lvl, (SELECT dept_code FROM ref.programme WHERE code = pg), 'LIVE'),
          ('ZZS 802', 'Check course for one specialisation', 3, 1, lvl, (SELECT dept_code FROM ref.programme WHERE code = pg), 'LIVE');
        INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES ('ZZS 801', pg, lvl, 'Core'), ('ZZS 802', pg, lvl, 'Elective')
        ON CONFLICT DO NOTHING;
        PERFORM catalogue.set_offer_specialisations('ZZS 802', pg, lvl, ARRAY[a]);
        INSERT INTO catalogue.offering (id, course_code, session, semester, stream) VALUES
          (gen_random_uuid(), 'ZZS 801', v_ses, 1, 'PG'), (gen_random_uuid(), 'ZZS 802', v_ses, 1, 'PG')
        ON CONFLICT (course_code, session, semester, stream) DO NOTHING;
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status) VALUES
          (s_a, 'MOAUM/ADM/60/948301', 'CHECKV483', 'Monetary', pg, 'POSTGRADUATE', v_ses, lvl, lvl, 'ADMITTED'),
          (s_b, 'MOAUM/ADM/60/948302', 'CHECKV483', 'Development', pg, 'POSTGRADUATE', v_ses, lvl, lvl, 'ADMITTED'),
          (s_none, 'MOAUM/ADM/60/948303', 'CHECKV483', 'None', pg, 'POSTGRADUATE', v_ses, lvl, lvl, 'ADMITTED');
        PERFORM people.set_student_specialisation(s_a, a);
        PERFORM people.set_student_specialisation(s_b, b);
        BEGIN
            PERFORM people.set_student_specialisation(s_none, foreign_spec);
        EXCEPTION WHEN check_violation THEN other_refused := SQLERRM LIKE 'PG_SPECIALISATION_OTHER:%';
        END;
        SELECT string_agg(m.course_code, ',' ORDER BY m.course_code) INTO menu_a FROM registration.student_menu(s_a, v_ses, 1) m WHERE m.course_code LIKE 'ZZS %';
        SELECT string_agg(m.course_code, ',' ORDER BY m.course_code) INTO menu_b FROM registration.student_menu(s_b, v_ses, 1) m WHERE m.course_code LIKE 'ZZS %';
        SELECT string_agg(m.course_code, ',' ORDER BY m.course_code) INTO menu_none FROM registration.student_menu(s_none, v_ses, 1) m WHERE m.course_code LIKE 'ZZS %';
        RAISE EXCEPTION 'the V483 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V483 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V483: a postgraduate programme''s specialisation course reaches only its students; a course for every student reaches them all; a student reads only their own programme''s specialisation',
        coalesce(ug_refused AND other_refused AND menu_a = 'ZZS 801,ZZS 802' AND menu_b = 'ZZS 801' AND menu_none = 'ZZS 801', false),
        format('undergraduate refused %s | other programme''s refused %s | MON %s | DEV %s | none %s', ug_refused, other_refused, menu_a, menu_b, menu_none));
END $$;


-- ── V484: the structure upload reads a postgraduate programme's levels and bases ──
-- A postgraduate programme's rows are bound at 700, 800 or 900 — the programme's own award level when a row gives none or one
-- outside them — and as Deficiency or Research where the status says so; an undergraduate programme's rows are read as before
-- (a level outside 100 to 600 at 100, R a Required course on a Core binding). The block undoes its writes.
DO $$
DECLARE pg text; ug text; award int; got text; ug_got text; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', '00000000-0000-0000-0000-000000000000', true);
        PERFORM set_config('moaum.actor_office', 'ict', true);
        PERFORM set_config('moaum.reason', 'check V484', true);
        SELECT p.code, admissions.pg_award_level(p.pg_award) INTO pg, award FROM ref.programme p JOIN ref.department d ON d.code = p.dept_code
         WHERE p.category = 'POST GRADUATE' AND NOT coalesce(p.archived, false) ORDER BY p.code LIMIT 1;
        SELECT p.code INTO ug FROM ref.programme p JOIN ref.department d ON d.code = p.dept_code
         WHERE p.category = 'UNDER GRADUATE' AND NOT coalesce(p.archived, false) ORDER BY p.code LIMIT 1;
        PERFORM catalogue.import_courses(pg, '[{"code": "ZQR 801", "title": "Check advanced seminar", "units": "3", "status": "C"},
                                               {"code": "ZQR 811", "title": "Check dissertation", "units": "6", "status": "Research", "level": "900"},
                                               {"code": "ZQR 802", "title": "Check deficiency course", "units": "2", "status": "DEF", "level": "300"}]'::jsonb, NULL);
        SELECT string_agg(co.course_code || '@' || co.level || ':' || co.basis, ',' ORDER BY co.course_code) INTO got
          FROM catalogue.course_offer co WHERE co.programme_code = pg AND co.course_code LIKE 'ZQR %';
        PERFORM catalogue.import_courses(ug, '[{"code": "ZQR 101", "title": "Check undergraduate course", "units": "2", "status": "R", "level": "700"}]'::jsonb, NULL);
        SELECT co.course_code || '@' || co.level || ':' || co.basis || ':' || c.kind INTO ug_got
          FROM catalogue.course_offer co JOIN catalogue.course c ON c.code = co.course_code WHERE co.programme_code = ug AND co.course_code = 'ZQR 101';
        RAISE EXCEPTION 'the V484 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V484 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V484: the structure upload binds a postgraduate programme''s rows at 700, 800 or 900 (its award level by default) and as Deficiency or Research where the status says so; an undergraduate programme''s rows as before',
        coalesce(got = format('ZQR 801@%s:Core,ZQR 802@%s:Deficiency,ZQR 811@900:Research', award, award) AND ug_got = 'ZQR 101@100:Core:Required', false),
        format('postgraduate %s (award level %s) | undergraduate %s', got, award, ug_got));
END $$;
-- ── V485. A student's password reset to the matriculation number at the ICT Support Desk: the desk may reset a matriculated
--    student in a status its policy allows, never one without a number, a record merged into another, a withdrawn student, or
--    any while the policy is off; the ledger takes the reset and the unlock without ever a value in them ──
DO $$
DECLARE
    who uuid := gen_random_uuid(); v_prog text; act uuid := gen_random_uuid(); adm uuid := gen_random_uuid(); grad uuid := gen_random_uuid();
    wd uuid := gen_random_uuid(); twin uuid := gen_random_uuid(); r_act text; r_adm text; r_grad text; r_wd text; r_twin text; r_off text;
    acct_open boolean; ledger_ok text; leak text; unlock_leak text; bad_status text; module text; msg text;
BEGIN
  BEGIN   -- the check's own students, undone at the end
    PERFORM set_config('moaum.actor_id', who::text, true);
    PERFORM set_config('moaum.actor_office', 'ict', true);
    PERFORM set_config('moaum.reason', 'CHECK V485', true);
    INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (who, 'ZZ-CHECK-V485', 'CHECKV485', 'Agent');
    SELECT code INTO v_prog FROM ref.programme WHERE category = 'UNDER GRADUATE' AND NOT archived ORDER BY code LIMIT 1;
    INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at) VALUES
        (act, 'MOAUM/ADM/85/485001', 'MOAU/ZZ/CHK/85/48501', 'CHECKV485', 'Active', v_prog, 'UTME', '2085/2086', 100, 200, 'ACTIVE', now()),
        (adm, 'MOAUM/ADM/85/485002', NULL, 'CHECKV485', 'Admitted', v_prog, 'UTME', '2085/2086', 100, 100, 'ADMITTED', NULL),
        (grad, 'MOAUM/ADM/85/485003', 'MOAU/ZZ/CHK/85/48503', 'CHECKV485', 'Graduated', v_prog, 'UTME', '2085/2086', 100, 400, 'GRADUATED', now()),
        (wd, 'MOAUM/ADM/85/485004', 'MOAU/ZZ/CHK/85/48504', 'CHECKV485', 'Withdrawn', v_prog, 'UTME', '2085/2086', 100, 100, 'WITHDRAWN', now()),
        -- a record the Registry merged into the active student's (V431)
        (twin, 'MOAUM/ADM/85/485005', NULL, 'CHECKV485', 'Merged', v_prog, 'UTME', '2085/2086', 100, 100, 'ADMITTED', NULL);
    UPDATE people.student SET status = 'WITHDRAWN', duplicate_of = act WHERE id = twin;
    SELECT coalesce(refusal, 'ELIGIBLE') INTO r_grad FROM iam.student_reset_check(grad);
    SELECT coalesce(refusal, 'ELIGIBLE') INTO r_adm FROM iam.student_reset_check(adm);
    SELECT coalesce(refusal, 'ELIGIBLE') INTO r_wd FROM iam.student_reset_check(wd);
    SELECT coalesce(refusal, 'ELIGIBLE') INTO r_twin FROM iam.student_reset_check(twin);
    SELECT coalesce(refusal, 'ELIGIBLE') INTO r_act FROM iam.student_reset_check(act);
    SELECT has_account INTO acct_open FROM iam.student_reset_check(act);
    UPDATE helpdesk.setting SET student_reset_enabled = false WHERE row_no;
    SELECT coalesce(refusal, 'ELIGIBLE') INTO r_off FROM iam.student_reset_check(act);
    UPDATE helpdesk.setting SET student_reset_enabled = true WHERE row_no;
    -- the ledger: the reset and the unlock, never a value in either
    PERFORM helpdesk.record_support_action(act, NULL, 'PASSWORD_RESET', NULL, NULL, NULL, 'CHECK V485: student forgot the portal password', NULL, NULL,
        '{"method": "DEFAULT_CREDENTIAL", "summary": "Password reset to the default student credential"}'::jsonb);
    PERFORM helpdesk.record_support_action(act, NULL, 'ACCOUNT_UNLOCKED', NULL, NULL, NULL, 'CHECK V485: locked after failed sign-ins', NULL, NULL, '{}'::jsonb);
    SELECT string_agg(action || '/' || coalesce(method, '-') || '/' || helpdesk.support_module(action), ',' ORDER BY action) INTO ledger_ok
      FROM helpdesk.support_action WHERE student_id = act;
    BEGIN
        PERFORM helpdesk.record_support_action(act, NULL, 'PASSWORD_RESET', NULL, NULL, 'MOAU/ZZ/CHK/85/48501', 'CHECK V485: a value written', NULL, NULL,
            '{"method": "DEFAULT_CREDENTIAL"}'::jsonb);
        leak := 'written';
    EXCEPTION WHEN check_violation THEN leak := 'refused';
    END;
    BEGIN
        PERFORM helpdesk.record_support_action(act, NULL, 'ACCOUNT_UNLOCKED', NULL, 'LOCKED', NULL, 'CHECK V485: a value written', NULL, NULL, '{}'::jsonb);
        unlock_leak := 'written';
    EXCEPTION WHEN check_violation THEN unlock_leak := 'refused';
    END;
    BEGIN
        UPDATE helpdesk.setting SET student_reset_statuses = ARRAY['ACTIVE', 'WITHDRAWN'] WHERE row_no;
        bad_status := 'accepted';
    EXCEPTION WHEN check_violation THEN bad_status := 'refused';
    END;
    module := helpdesk.support_module('ACCOUNT_UNLOCKED');
    RAISE EXCEPTION 'CHECK_V485_UNDONE' USING ERRCODE = 'P0001';
  EXCEPTION WHEN raise_exception THEN
    GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
    IF msg <> 'CHECK_V485_UNDONE' THEN RAISE; END IF;
  END;
    PERFORM pg_temp.assert('V485: the desk resets to the default credential only a matriculated student in an allowed status, never a merged record, while the policy is on',
        coalesce(r_act = 'ELIGIBLE' AND NOT acct_open AND r_grad = 'ELIGIBLE' AND r_adm = 'RESET_NO_MATRIC' AND r_wd = 'RESET_STATUS'
            AND r_twin = 'RESET_MERGED_RECORD' AND r_off = 'RESET_DISABLED', false),
        format('active %s (account %s) | graduated %s | admitted %s | withdrawn %s | merged %s | policy off %s', r_act, acct_open, r_grad, r_adm, r_wd, r_twin, r_off));
    PERFORM pg_temp.assert('V485: the ledger takes a reset to the default credential and an unlock, in Authentication, never with a value; a withdrawn status is never in the policy',
        coalesce(ledger_ok = 'ACCOUNT_UNLOCKED/-/AUTHENTICATION,PASSWORD_RESET/DEFAULT_CREDENTIAL/AUTHENTICATION' AND leak = 'refused' AND unlock_leak = 'refused'
            AND bad_status = 'refused' AND module = 'AUTHENTICATION', false),
        format('ledger %s | a value on the reset %s, on the unlock %s | WITHDRAWN in the policy %s | module %s', ledger_ok, leak, unlock_leak, bad_status, module));
END $$;
-- ── V480. A payer's receipt for a Pay on Quickteller payment: a day paid tomorrow (Lagos) and a Payment Log Id of two
--          characters are refused; a receipt is kept, a second replaces it (one a reference), and it confirms nothing; the
--          Bursary's list shows it waiting; the list Interswitch is sent carries it and a reference opened on Pay on
--          Quickteller 30 hours before with no receipt, and not a card checkout; once confirmed, it is off that list and a
--          receipt for it is refused. The block undoes its writes ──
DO $$
DECLARE who uuid := gen_random_uuid(); st uuid := gen_random_uuid(); v_ses text; today date := (now() AT TIME ZONE 'Africa/Lagos')::date;
        refused_day text; refused_log text; refused_paid text; kept int; log_now text; still_open boolean; listed text; ask text; ask_log text;
        after_paid text; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'student', true);
        PERFORM set_config('moaum.reason', 'check V480', true);
        v_ses := (SELECT name FROM policy.academic_session ORDER BY name LIMIT 1);
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status)
        VALUES (st, 'MOAUM/ADM/60/948001', 'CHECKV480', 'Payer', (SELECT code FROM ref.programme WHERE NOT coalesce(archived, false) ORDER BY code LIMIT 1), 'UTME', v_ses, 100, 100, 'ADMITTED');
        INSERT INTO finance.payment_reference (student_id, session, reference, purpose, amount, expires_at) VALUES
          (st, v_ses, 'MOAUM-FEE-948001-0001', 'check V480', 53488.42, now() + interval '30 days'),
          (st, v_ses, 'MOAUM-FEE-948001-0002', 'check V480', 100.00, now() + interval '30 days'),
          (st, v_ses, 'MOAUM-FEE-948001-0003', 'check V480', 200.00, now() + interval '30 days');
        INSERT INTO finance.gateway_attempt (reference, gateway, kind, account_id, opened_at) VALUES
          ('MOAUM-FEE-948001-0001', 'paydirect', 'FEE', st, now() - interval '2 hours'),
          ('MOAUM-FEE-948001-0002', 'paydirect', 'FEE', st, now() - interval '30 hours'),
          ('MOAUM-FEE-948001-0003', 'paystack', 'FEE', st, now() - interval '30 hours');
        BEGIN
            PERFORM finance.paydirect_claim_set('MOAUM-FEE-948001-0001', st, 'PL-480001', today + 1, NULL, NULL, NULL);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS refused_day = MESSAGE_TEXT;
        END;
        BEGIN
            PERFORM finance.paydirect_claim_set('MOAUM-FEE-948001-0001', st, ' P4 ', today, NULL, NULL, NULL);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS refused_log = MESSAGE_TEXT;
        END;
        PERFORM finance.paydirect_claim_set('moaum-fee-948001-0001', st, 'PL-480000', today - 1, NULL, 'bank', NULL);
        PERFORM finance.paydirect_claim_set('MOAUM-FEE-948001-0001', st, ' PL-480001 ', today, 53488.42, 'quickteller', 'Paid on the app');
        SELECT count(*), max(payment_log_id) INTO kept, log_now FROM finance.paydirect_claim WHERE reference = 'MOAUM-FEE-948001-0001';
        still_open := (SELECT confirmed_at IS NULL FROM finance.payment_reference WHERE reference = 'MOAUM-FEE-948001-0001');
        listed := (SELECT string_agg(c.reference || ':' || c.payment_log_id || ':' || c.channel || ':' || (c.confirmed_at IS NULL), ',')
                     FROM finance.paydirect_claims() c WHERE c.reference LIKE 'MOAUM-FEE-948001-%');
        SELECT string_agg(a.reference, ',' ORDER BY a.reference), string_agg(coalesce(a.payment_log_id, '-'), ',' ORDER BY a.reference) INTO ask, ask_log
          FROM finance.paydirect_ask_list() a WHERE a.reference LIKE 'MOAUM-FEE-948001-%';
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM finance.confirm_payment('MOAUM-FEE-948001-0001', 'Quickteller · WEB', 'check V480');
        PERFORM set_config('moaum.actor_office', 'student', true);
        after_paid := coalesce((SELECT string_agg(a.reference, ',' ORDER BY a.reference) FROM finance.paydirect_ask_list() a WHERE a.reference LIKE 'MOAUM-FEE-948001-%'), '');
        BEGIN
            PERFORM finance.paydirect_claim_set('MOAUM-FEE-948001-0001', st, 'PL-480002', today, NULL, NULL, NULL);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS refused_paid = MESSAGE_TEXT;
        END;
        RAISE EXCEPTION 'the V480 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V480 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V480: a payer reports the receipt of a Pay on Quickteller payment — one a reference, confirming nothing — and the list Interswitch is sent carries it beside the references unreported after an hour, until it is confirmed',
        coalesce(refused_day LIKE 'PAY_CLAIM_DATE%' AND refused_log LIKE 'PAY_CLAIM_LOG_ID%' AND kept = 1 AND log_now = 'PL-480001' AND still_open
                 AND listed = 'MOAUM-FEE-948001-0001:PL-480001:QUICKTELLER:true'
                 AND ask = 'MOAUM-FEE-948001-0001,MOAUM-FEE-948001-0002' AND ask_log = 'PL-480001,-'
                 AND after_paid = 'MOAUM-FEE-948001-0002' AND refused_paid LIKE 'PAY_CLAIM_CONFIRMED%', false),
        format('tomorrow %s | two characters %s | kept %s, log id %s, open %s | Bursary list %s | ask list %s (%s) | after paid %s | receipt after paid %s',
               refused_day, refused_log, kept, log_now, still_open, listed, ask, ask_log, after_paid, refused_paid));
END $$;
-- ── V491. Course registration approved automatically: the rule by session and semester (the semester's over the session's over the
--    standing HOD rule); a submitted registration whose courses are on the student's menu approved with approval_mode AUTO and no
--    approver, told once; a course not offered or a student not in study held for review with the reason; the waiting
--    registrations of an AUTO semester judged, a HOD semester's left alone; a reset keeping the registration on its record,
--    carryovers kept, a second reset doing nothing; never a locked registration, one with a mark, or where the rule closes it ──
DO $$
DECLARE acad uuid := gen_random_uuid(); S text := '9491/9492'; pa text := 'C00023';
        stu uuid := gen_random_uuid(); other uuid := gen_random_uuid(); wd uuid := gen_random_uuid(); pend uuid := gen_random_uuid(); marked uuid := gen_random_uuid();
        reg uuid := gen_random_uuid(); reg2 uuid := gen_random_uuid(); reg3 uuid := gen_random_uuid(); reg4 uuid := gen_random_uuid(); reg5 uuid := gen_random_uuid();
        o1 uuid := gen_random_uuid(); o2 uuid := gen_random_uuid(); o3 uuid := gen_random_uuid(); sheet uuid := gen_random_uuid();
        m_default text; m_session text; m_semester text; r_ok text; r_mode text; r_entries text; notices int; notices2 int; r_offer text; r_withdrawn text;
        pend_n record; reg4_state text; rs jsonb; rs2 jsonb; st_after text; kept text; hist text; r_marks text; r_locked text; r_off text; r_fees text; msg text;
BEGIN
  BEGIN
    PERFORM set_config('moaum.reason', 'CHECK V491', true);
    PERFORM set_config('moaum.actor_id', acad::text, true);
    PERFORM set_config('moaum.actor_office', 'academic', true);
    INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9491-10-01', date '9492-08-31') ON CONFLICT (name) DO NOTHING;
    INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state)
    SELECT x.code, x.title, 3, 1, 100, p.dept_code, 'Core', 'LIVE' FROM ref.programme p,
           (VALUES ('CCX 191', 'Check auto one'), ('CCX 192', 'Check auto two'), ('CCX 193', 'Check not offered')) x(code, title) WHERE p.code = pa;
    INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES ('CCX 191', pa, 100, 'Core'), ('CCX 192', pa, 100, 'Core');
    INSERT INTO catalogue.offering (id, course_code, session, semester) VALUES (o1, 'CCX 191', S, 1), (o2, 'CCX 192', S, 1), (o3, 'CCX 193', S, 1);
    INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at) VALUES
        (stu, 'MOAUM/ADM/49/491001', 'MOAUM/CHK/49/4911', 'ZZV491', 'Auto', pa, 'UTME', S, 100, 100, 'ACTIVE', now()),
        (other, 'MOAUM/ADM/49/491002', 'MOAUM/CHK/49/4912', 'ZZV491', 'Not offered', pa, 'UTME', S, 100, 100, 'ACTIVE', now()),
        (wd, 'MOAUM/ADM/49/491003', 'MOAUM/CHK/49/4913', 'ZZV491', 'Withdrawn', pa, 'UTME', S, 100, 100, 'WITHDRAWN', now()),
        (pend, 'MOAUM/ADM/49/491004', 'MOAUM/CHK/49/4914', 'ZZV491', 'Second semester', pa, 'UTME', S, 100, 100, 'ACTIVE', now()),
        (marked, 'MOAUM/ADM/49/491005', 'MOAUM/CHK/49/4915', 'ZZV491', 'Marked', pa, 'UTME', S, 100, 100, 'ACTIVE', now());
    -- the rule: the standing rule is the Head's; the session approves automatically, its second semester by the Head
    m_default := registration.approval_mode(S, 1);
    INSERT INTO registration.approval_policy (session, semester, mode, allow_student_reset, card_on_approval, reason) VALUES
        (S, NULL, 'AUTO_APPROVAL', true, true, 'CHECK V491: approved automatically'),
        (S, 2, 'HOD_APPROVAL_REQUIRED', false, true, 'CHECK V491: the second semester by the Head');
    m_session := registration.approval_mode(S, 1);
    m_semester := registration.approval_mode(S, 2);
    INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, submitted_at) VALUES
        (reg, stu, S, 1, 100, 'SUBMITTED', now()), (reg2, other, S, 1, 100, 'SUBMITTED', now()), (reg3, wd, S, 1, 100, 'SUBMITTED', now()),
        (reg4, pend, S, 2, 100, 'SUBMITTED', now());
    INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, submitted_at, approved_at) VALUES
        (reg5, marked, S, 1, 100, 'APPROVED', now(), now());
    INSERT INTO registration.entry (registration_id, offering_id, units, entry_type) VALUES
        (reg, o1, 3, 'CURRENT'), (reg, o2, 3, 'CARRYOVER'), (reg2, o1, 3, 'CURRENT'), (reg2, o3, 3, 'CURRENT'), (reg3, o1, 3, 'CURRENT'),
        (reg4, o1, 3, 'CURRENT'), (reg5, o1, 3, 'CURRENT');
    -- a submitted registration whose courses are on the student's menu: approved by the rule, the student told once
    r_ok := registration.auto_approve(reg);
    SELECT status || '/' || coalesce(approval_mode, '-') || '/' || (approved_by IS NULL) INTO r_mode FROM registration.course_registration WHERE id = reg;
    SELECT string_agg(status, ',' ORDER BY status) INTO r_entries FROM registration.entry WHERE registration_id = reg;
    SELECT count(*) INTO notices FROM platform.notice WHERE template_key = 'REG_AUTO_APPROVED' AND about_id = stu;
    PERFORM registration.auto_approve(reg);
    SELECT count(*) INTO notices2 FROM platform.notice WHERE template_key = 'REG_AUTO_APPROVED' AND about_id = stu;
    -- a course not offered to the student, a student not in study: not approved, each with its reason
    r_offer := registration.auto_approve(reg2);
    r_withdrawn := registration.auto_approve(reg3);
    -- the waiting registrations: the AUTO semester's judged (the check's students' fees are not stated: held for review), the Head's left alone
    SELECT * INTO pend_n FROM registration.auto_approve_pending(S, NULL);
    SELECT r.status || '/' || (ar.registration_id IS NULL) INTO reg4_state
      FROM registration.course_registration r LEFT JOIN registration.approval_review ar ON ar.registration_id = r.id WHERE r.id = reg4;
    -- the reset: kept on its record, the chosen course gone, the carryover kept, a draft again; a second reset does nothing
    PERFORM set_config('moaum.actor_id', stu::text, true);
    PERFORM set_config('moaum.actor_office', 'student', true);
    -- school fees stated for the session and not paid: the student could not register again, so the student's own reset waits;
    -- the reset itself is the same on the desk's behalf
    INSERT INTO finance.fee_schedule (session, item, amount, level) VALUES (S, 'School fees', 100000, 100);
    r_fees := split_part(registration.reset_refusal(stu, S, 1, 'STUDENT_PORTAL'), ':', 1);
    rs := registration.student_reset(stu, S, 1, 'CHECK V491: wrong courses from the old portal', 'ICT_SUPPORT');
    SELECT status || '/' || coalesce(approval_mode, '-') || '/' || (approved_at IS NULL) INTO st_after FROM registration.course_registration WHERE id = reg;
    SELECT string_agg(o.course_code || ':' || e.entry_type || ':' || e.status, ',') INTO kept FROM registration.entry e JOIN catalogue.offering o ON o.id = e.offering_id WHERE e.registration_id = reg;
    SELECT previous_status || '/' || previous_approval_mode || '/' || course_count || '/' || units || '/' || source INTO hist FROM registration.registration_reset WHERE registration_id = reg;
    rs2 := registration.student_reset(stu, S, 1, 'CHECK V491: second click', 'ICT_SUPPORT');
    -- never reset: a mark entered, a locked registration, a semester whose rule closes the reset to students
    INSERT INTO assessment.score_sheet (id, offering_id) VALUES (sheet, o1);
    INSERT INTO assessment.score (sheet_id, student_id, ca, exam) VALUES (sheet, marked, 20, 40);
    r_marks := split_part(registration.reset_refusal(marked, S, 1, 'STUDENT_PORTAL'), ':', 1);
    UPDATE registration.course_registration SET status = 'LOCKED', approved_at = now() WHERE id = reg3;
    r_locked := split_part(registration.reset_refusal(wd, S, 1, 'STUDENT_PORTAL'), ':', 1);
    r_off := split_part(registration.reset_refusal(pend, S, 2, 'STUDENT_PORTAL'), ':', 1);
    RAISE EXCEPTION 'CHECK_V491_UNDONE' USING ERRCODE = 'P0001';
  EXCEPTION WHEN raise_exception THEN
    GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
    IF msg <> 'CHECK_V491_UNDONE' THEN RAISE; END IF;
  END;
    PERFORM pg_temp.assert('V491: a registration is approved by the rule of its semester, session or the standing HOD rule — on the student''s menu approved AUTO with no approver and told once; a course not offered or a student not in study held with the reason; a HOD semester left to the Head',
        coalesce(m_default = 'HOD_APPROVAL_REQUIRED' AND m_session = 'AUTO_APPROVAL' AND m_semester = 'HOD_APPROVAL_REQUIRED'
            AND r_ok = 'approved' AND r_mode = 'APPROVED/AUTO/true' AND r_entries = 'APPROVED,APPROVED' AND notices >= 1 AND notices2 = notices
            AND r_offer LIKE 'REG_COURSE_NOT_OFFERED: CCX 193%' AND r_withdrawn LIKE 'REG_STUDENT_NOT_ELIGIBLE%'
            AND pend_n.considered = 2 AND pend_n.approved = 0 AND pend_n.review = 2 AND reg4_state = 'SUBMITTED/true', false),
        format('rule %s/%s/%s | %s %s entries %s notices %s→%s | not offered "%s" | withdrawn "%s" | pending %s | the Head''s semester %s',
               m_default, m_session, m_semester, r_ok, r_mode, r_entries, notices, notices2, r_offer, r_withdrawn, pend_n, reg4_state));
    PERFORM pg_temp.assert('V491: a reset keeps the registration on its record, removes the chosen courses, keeps the carryover, makes it a draft, and a second does nothing; never with a mark, locked, where the rule closes it, or (for the student) before the fees are cleared',
        coalesce((rs->>'reset')::boolean AND st_after = 'DRAFT/-/true' AND kept = 'CCX 192:CARRYOVER:REGISTERED'
            AND hist = 'APPROVED/AUTO/2/6/ICT_SUPPORT' AND (rs2->>'alreadyClear')::boolean AND r_fees = 'REG_RESET_FEES'
            AND r_marks = 'REG_RESET_HAS_RESULTS' AND r_locked = 'REG_RESET_LOCKED' AND r_off = 'REG_RESET_OFF', false),
        format('reset %s | after %s kept %s | record %s | again %s | fees %s marks %s locked %s rule %s', rs, st_after, kept, hist, rs2, r_fees, r_marks, r_locked, r_off));
END $$;


-- ── V486: connections waited for are told to ICT, and the slowest screens' reads stand ──
-- While requests wait for a database connection, each Directorate of ICT office holder is told once an hour (the event key);
-- the three restated reads still answer (a session with no applications, the course review). The block undoes its writes.
DO $$
DECLARE who uuid := gen_random_uuid(); first_told int; again int; msg text; ns int; sr int; rv bigint;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', '00000000-0000-0000-0000-000000000000', true);
        PERFORM set_config('moaum.actor_office', 'ict', true);
        PERFORM set_config('moaum.reason', 'check V486', true);
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (who, 'ZZ-CHK-486', 'CHECKV486', 'Director');
        INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from)
        VALUES (gen_random_uuid(), who, 'ict', 'institution', NULL, 'check V486', who, current_date - 1);
        first_told := platform.tell_pool_waiting(75, 4, 10, '2031-01-01 10:15+01');
        again := platform.tell_pool_waiting(140, 6, 10, '2031-01-01 10:40+01');
        SELECT count(*) INTO ns FROM admissions.non_sitter_post_utme('1901/1902');
        SELECT count(*) INTO sr FROM admissions.screening_register('1901/1902');
        SELECT total INTO rv FROM catalogue.review_summary();
        RAISE EXCEPTION 'the V486 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V486 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V486: requests waiting for a database connection are told to each Directorate of ICT office holder once an hour; the restated screening and course-review reads answer',
        coalesce(first_told > 0 AND again = 0 AND ns = 0 AND sr = 0 AND rv IS NOT NULL, false),
        format('told %s then %s | non-sitters %s, register %s, courses reviewed %s', first_told, again, ns, sr, rv));
END $$;


-- ── V487: prerequisites uploaded, and whom enforcing stops ──
-- A file's rows are written row by row: a new prerequisite added, one recorded already said so, a course requiring itself,
-- a row closing a loop and a course the pool does not hold refused. The student's passes read as assessment.student_results
-- reads them; whom enforcing stops lists a student of the programme who has not passed a prerequisite, and not one who has.
-- The block undoes its writes.
DO $$
DECLARE st uuid := gen_random_uuid(); ok_st uuid := gen_random_uuid(); o1 uuid := gen_random_uuid(); reg uuid := gen_random_uuid();
        sh uuid := gen_random_uuid(); prog text; v_ses text; outcomes text; same boolean; listed text; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', '00000000-0000-0000-0000-000000000000', true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        PERFORM set_config('moaum.reason', 'check V487', true);
        prog := (SELECT p.code FROM ref.programme p WHERE p.category = 'UNDER GRADUATE' AND NOT coalesce(p.archived, false) ORDER BY p.code LIMIT 1);
        v_ses := (SELECT name FROM policy.academic_session ORDER BY name LIMIT 1);
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, state) VALUES
          ('ZQU 101', 'Check upload first', 2, 1, 100, (SELECT dept_code FROM ref.programme WHERE code = prog), 'LIVE'),
          ('ZQU 201', 'Check upload second', 2, 1, 200, (SELECT dept_code FROM ref.programme WHERE code = prog), 'LIVE'),
          ('ZQU 301', 'Check upload third', 2, 1, 300, (SELECT dept_code FROM ref.programme WHERE code = prog), 'LIVE');
        INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES ('ZQU 201', prog, 200, 'Core');
        SELECT string_agg(l.outcome, ',' ORDER BY l.row_no) INTO outcomes FROM catalogue.load_prerequisites(
            '[{"course": "ZQU 201", "requires": "ZQU 101"}, {"course": "zqu 201", "requires": "ZQU 101"}, {"course": "ZQU 301", "requires": "ZQU 301"},
              {"course": "ZQU 101", "requires": "ZQU 201"}, {"course": "ZQU 999", "requires": "ZQU 101"}, {"course": "ZQU 301", "requires": ""}]'::jsonb) l;
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status) VALUES
          (st, 'MOAUM/ADM/60/948701', 'CHECKV487', 'Unpassed', prog, 'UTME', v_ses, 100, 200, 'ADMITTED'),
          (ok_st, 'MOAUM/ADM/60/948702', 'CHECKV487', 'Passed', prog, 'UTME', v_ses, 100, 200, 'ADMITTED');
        INSERT INTO catalogue.offering (id, course_code, session, semester) VALUES (o1, 'ZQU 101', v_ses, 1);
        INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, submitted_at, approved_at)
        VALUES (reg, ok_st, v_ses, 1, 100, 'APPROVED', now(), now());
        INSERT INTO registration.entry (registration_id, offering_id, units, status) VALUES (reg, o1, 2, 'APPROVED');
        INSERT INTO assessment.score_sheet (id, offering_id, stage, senate_minute, published_at, submitted_at) VALUES (sh, o1, 'PUBLISHED', 'SEN/CHK/487', now(), now());
        INSERT INTO assessment.score (sheet_id, student_id, ca, exam, outcome) VALUES (sh, ok_st, 25, 45, 'GRADED');
        -- the passes, as the results read them
        same := registration.passed_codes(ok_st) = ARRAY(SELECT DISTINCT f.course_code FROM assessment.student_results(ok_st) f
                                                          WHERE f.published AND f.outcome = 'GRADED' AND f.points > 0)
                AND registration.passed_codes(ok_st, ARRAY['ZQU 101']) = ARRAY['ZQU 101'] AND registration.passed_codes(st) = '{}';
        SELECT string_agg(i.name || ':' || i.unmet, ',') INTO listed FROM registration.prerequisite_impact('ZQU 201') i WHERE i.name LIKE 'CHECKV487%';
        RAISE EXCEPTION 'the V487 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V487 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V487: an upload adds what is new and says what is recorded, refuses a course requiring itself, a loop and a course not in the pool; passes read as the results read them; whom enforcing stops lists the student who has not passed',
        coalesce(outcomes = 'ADDED,ALREADY,SELF,CYCLE,NO_COURSE,INCOMPLETE' AND same AND listed = 'CHECKV487, Unpassed:ZQU 101', false),
        format('outcomes %s | passes as the results read them %s | listed %s', outcomes, same, listed));
END $$;


-- ── V488: a postgraduate specialisation from the application to the transcript ──
-- An application takes one of its programme's running specialisations (never another programme's); at admission it becomes
-- the student's; a file sets students' specialisations row by row; the coursework audit counts the courses for every student
-- and the student's specialisation's, never another's; the statement names the specialisation. The block undoes its writes.
DO $$
DECLARE pg text; lvl int; v_ses text; mon uuid; dev uuid; app_id uuid := gen_random_uuid(); applicant uuid := gen_random_uuid();
        st uuid := gen_random_uuid(); other uuid := gen_random_uuid(); refused boolean := false; carried text; loaded text;
        audit text; stmt text; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', '00000000-0000-0000-0000-000000000000', true);
        PERFORM set_config('moaum.actor_office', 'pgschool', true);
        PERFORM set_config('moaum.reason', 'check V488', true);
        SELECT p.code, admissions.pg_award_level(p.pg_award) INTO pg, lvl FROM ref.programme p
         WHERE p.category = 'POST GRADUATE' AND NOT coalesce(p.archived, false) ORDER BY p.code LIMIT 1;
        v_ses := (SELECT name FROM policy.academic_session ORDER BY name LIMIT 1);
        mon := catalogue.save_specialisation(pg, 'CMON', 'Check monetary 488');
        dev := catalogue.save_specialisation(pg, 'CDEV', 'Check development 488');
        -- the application, and its specialisation
        INSERT INTO admissions.pg_applicant (id, session, surname, other_names, email, password_hash)
        VALUES (applicant, v_ses, 'CHECKV488', 'Applicant', 'check-v488@example.test', crypt('check v488', gen_salt('bf', 12)));
        INSERT INTO admissions.pg_application (id, applicant_id, session, application_no, programme_code, entry_level, state, submitted_at)
        VALUES (app_id, applicant, v_ses, 'PG/99/948801', pg, lvl, 'SUBMITTED', now());
        BEGIN
            PERFORM admissions.pg_set_specialisation(app_id, (SELECT ps.id::text FROM catalogue.programme_specialisation ps WHERE ps.programme_code <> pg LIMIT 1));
            PERFORM admissions.pg_set_specialisation(app_id, 'NOPE');
        EXCEPTION WHEN check_violation THEN refused := SQLERRM LIKE 'PG_SPECIALISATION_OTHER:%';
        END;
        PERFORM admissions.pg_set_specialisation(app_id, 'cmon');
        -- admitted: the specialisation becomes the student's
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status) VALUES
          (st, 'MOAUM/ADM/60/948801', 'CHECKV488', 'Student', pg, 'POSTGRADUATE', v_ses, lvl, lvl, 'ADMITTED'),
          (other, 'MOAUM/ADM/60/948802', 'CHECKV488', 'Other', pg, 'POSTGRADUATE', v_ses, lvl, lvl, 'ADMITTED');
        UPDATE admissions.pg_application SET student_id = st, state = 'ADMITTED', admitted_at = now() WHERE id = app_id;
        SELECT ps.code INTO carried FROM people.student_specialisation ss JOIN catalogue.programme_specialisation ps ON ps.id = ss.specialisation_id WHERE ss.student_id = st;
        -- a file sets the other student's, and refuses an unknown number and code
        SELECT string_agg(l.outcome, ',' ORDER BY l.row_no) INTO loaded FROM people.load_student_specialisations(pg,
            '[{"number": "MOAUM/ADM/60/948802", "specialisation": "cdev"}, {"number": "MOAUM/ADM/60/948801", "specialisation": "CMON"},
              {"number": "MOAUM/ADM/60/999999", "specialisation": "CMON"}, {"number": "MOAUM/ADM/60/948802", "specialisation": "NOPE"}]'::jsonb) l;
        -- the coursework audit: the course for every student and the student's own specialisation's, never the other's
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, state) VALUES
          ('ZQS 801', 'Check core for all', 3, 1, lvl, (SELECT dept_code FROM ref.programme WHERE code = pg), 'LIVE'),
          ('ZQS 802', 'Check core for CMON', 3, 1, lvl, (SELECT dept_code FROM ref.programme WHERE code = pg), 'LIVE'),
          ('ZQS 803', 'Check core for CDEV', 3, 1, lvl, (SELECT dept_code FROM ref.programme WHERE code = pg), 'LIVE');
        INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES ('ZQS 801', pg, lvl, 'Core'), ('ZQS 802', pg, lvl, 'Core'), ('ZQS 803', pg, lvl, 'Core');
        PERFORM catalogue.set_offer_specialisations('ZQS 802', pg, lvl, ARRAY[mon]);
        PERFORM catalogue.set_offer_specialisations('ZQS 803', pg, lvl, ARRAY[dev]);
        SELECT string_agg(a.course_code || ':' || a.state, ',' ORDER BY a.course_code) INTO audit FROM admissions.pg_coursework_audit(st) a WHERE a.course_code LIKE 'ZQS %';
        stmt := credentials.build_statement(st, 'TRANSCRIPT', NULL, NULL)->>'specialisation';
        RAISE EXCEPTION 'the V488 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V488 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V488: an application takes its own programme''s specialisation and the student keeps it at admission; a file sets students'' specialisations; the coursework audit counts every student''s courses and their specialisation''s; the transcript names it',
        coalesce(refused AND carried = 'CMON' AND loaded = 'SET,ALREADY,NO_STUDENT,NO_SPECIALISATION'
                 AND audit = 'ZQS 801:OUTSTANDING,ZQS 802:OUTSTANDING' AND stmt = 'Check monetary 488', false),
        format('other''s refused %s | carried %s | file %s | audit %s | transcript %s', refused, carried, loaded, audit, stmt));
END $$;
-- ── V492. The GST & EPS examination permit: exactly the GST and EPS courses on the student's approved registration for the semester
--    (never a departmental course, another semester's or one the student did not register), no permit without one, a draft never;
--    issued once with its reference and counted, a reset taking the courses off and a new registration putting the new ones on
--    under the same number; withdrawn only by the office whose course it carries, with a reason; its log written once ──
DO $$
DECLARE S text := '9592/9593'; pa text := 'C00023'; acad uuid := gen_random_uuid(); dept text;
        stu uuid := gen_random_uuid(); dep uuid := gen_random_uuid(); dra uuid := gen_random_uuid();
        reg uuid := gen_random_uuid(); reg2 uuid := gen_random_uuid(); reg3 uuid := gen_random_uuid(); reg4 uuid := gen_random_uuid();
        st jsonb; st2 jsonb; st_dep jsonb; st_draft jsonb; st_unpaid jsonb; i1 jsonb; i2 jsonb; i3 jsonb; after_reset jsonb; ref text;
        courses text; courses2 text; courses3 text; events text; n_permits int; short_reason text; once text; revoked jsonb; restored jsonb; msg text;
BEGIN
  BEGIN
    PERFORM set_config('moaum.reason', 'CHECK V492', true);
    PERFORM set_config('moaum.actor_id', acad::text, true);
    PERFORM set_config('moaum.actor_office', 'academic', true);
    INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9592-10-01', date '9593-08-31') ON CONFLICT (name) DO NOTHING;
    SELECT dept_code INTO dept FROM ref.programme WHERE code = pa;
    INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state) VALUES
        ('GST 929', 'Check permit English', 2, 1, 100, dept, 'GST', 'LIVE'), ('GST 928', 'Check permit Peoples', 2, 1, 100, dept, 'GST', 'LIVE'),
        ('GST 927', 'Check permit never registered', 2, 1, 100, dept, 'GST', 'LIVE'), ('EPS 929', 'Check permit Entrepreneurship', 2, 1, 100, dept, 'GST', 'LIVE'),
        ('ZZP 929', 'Check permit departmental', 3, 1, 100, dept, 'Core', 'LIVE');
    INSERT INTO catalogue.offering (id, course_code, session, semester)
    SELECT gen_random_uuid(), c, S, sem FROM unnest(ARRAY['GST 929', 'GST 928', 'GST 927', 'EPS 929', 'ZZP 929']) c, unnest(ARRAY[1, 2]) sem;
    INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at) VALUES
        (stu, 'MOAUM/ADM/59/592001', 'MOAUM/CHK/59/5921', 'ZZV492', 'Permit', pa, 'UTME', S, 100, 100, 'ACTIVE', now()),
        (dep, 'MOAUM/ADM/59/592002', 'MOAUM/CHK/59/5922', 'ZZV492', 'Departmental only', pa, 'UTME', S, 100, 100, 'ACTIVE', now()),
        (dra, 'MOAUM/ADM/59/592003', 'MOAUM/CHK/59/5923', 'ZZV492', 'Draft', pa, 'UTME', S, 100, 100, 'ACTIVE', now());
    INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, submitted_at, approved_at) VALUES
        (reg, stu, S, 1, 100, 'APPROVED', now(), now()), (reg2, stu, S, 2, 100, 'APPROVED', now(), now()), (reg3, dep, S, 1, 100, 'APPROVED', now(), now());
    INSERT INTO registration.course_registration (id, student_id, session, semester, level, status) VALUES (reg4, dra, S, 1, 100, 'DRAFT');
    -- the student: GST 929, EPS 929 and a departmental course in the first semester, GST 928 in the second; GST 927 runs, registered by nobody
    INSERT INTO registration.entry (registration_id, offering_id, units, entry_type, status)
    SELECT x.r, o.id, 2, 'CURRENT', 'APPROVED' FROM (VALUES (reg, 'GST 929', 1), (reg, 'EPS 929', 1), (reg, 'ZZP 929', 1), (reg2, 'GST 928', 2),
                                                              (reg3, 'ZZP 929', 1), (reg4, 'GST 929', 1)) x(r, c, sem)
      JOIN catalogue.offering o ON o.course_code = x.c AND o.session = S AND o.semester = x.sem;
    st := registration.gst_eps_permit_state(stu, S, 1);
    SELECT string_agg((c->>'course_code') || ':' || (c->>'course_type'), ',' ORDER BY c->>'course_type' DESC, c->>'course_code') INTO courses FROM jsonb_array_elements(st->'courses') c;
    st2 := registration.gst_eps_permit_state(stu, S, 2);
    st_dep := registration.gst_eps_permit_state(dep, S, 1);
    st_draft := registration.gst_eps_permit_state(dra, S, 1);
    -- the school fees stated and not paid: the examination card's own condition holds the permit
    INSERT INTO finance.fee_schedule (session, item, amount, level) VALUES (S, 'School fees', 100000, 100);
    st_unpaid := registration.gst_eps_permit_state(stu, S, 1);
    PERFORM set_config('moaum.actor_office', 'bursar', true);
    PERFORM finance.confirm_payment(finance.new_reference(stu, S, 100000, NULL), 'Bank transfer', 'CHECK V492');
    -- issued twice: one permit, counted twice, its courses logged
    PERFORM set_config('moaum.actor_id', stu::text, true);
    PERFORM set_config('moaum.actor_office', 'student', true);
    i1 := registration.issue_gst_eps_permit(stu, S, 1, 'VIEW');
    i2 := registration.issue_gst_eps_permit(stu, S, 1, 'PRINT');
    ref := i1->'permit'->>'reference';
    SELECT count(*) INTO n_permits FROM registration.gst_eps_permit WHERE student_id = stu;
    SELECT string_agg(action, ',' ORDER BY action) INTO events FROM registration.gst_eps_permit_event e JOIN registration.gst_eps_permit p ON p.id = e.permit_id WHERE p.student_id = stu;
    -- the log is written once
    BEGIN
        UPDATE registration.gst_eps_permit_event SET reason = 'changed' WHERE permit_id = (SELECT id FROM registration.gst_eps_permit WHERE student_id = stu);
        once := 'updated';
    EXCEPTION WHEN check_violation THEN once := 'refused';
    END;
    -- withdrawn only by the office whose course it carries (both offices here), restored with a reason
    PERFORM set_config('moaum.actor_office', 'gst', true);
    BEGIN
        PERFORM registration.revoke_gst_eps_permit((SELECT id FROM registration.gst_eps_permit WHERE student_id = stu), 'GST', 'short');
        short_reason := 'accepted';
    EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS short_reason = MESSAGE_TEXT;
    END;
    short_reason := split_part(short_reason, ':', 1);
    revoked := registration.revoke_gst_eps_permit((SELECT id FROM registration.gst_eps_permit WHERE student_id = stu), 'GST', 'CHECK V492: presented by another candidate');
    restored := registration.revoke_gst_eps_permit((SELECT id FROM registration.gst_eps_permit WHERE student_id = stu), 'EPS', 'CHECK V492: the office confirmed the candidate', true);
    -- a reset takes the courses off; registered again with GST 928 instead, the same permit carries the new courses only
    PERFORM registration.student_reset(stu, S, 1, 'CHECK V492: wrong courses', 'ICT_SUPPORT');
    after_reset := registration.gst_eps_permit_state(stu, S, 1);
    INSERT INTO registration.entry (registration_id, offering_id, units, entry_type, status)
    SELECT reg, o.id, 2, 'CURRENT', 'APPROVED' FROM catalogue.offering o WHERE o.course_code = 'GST 928' AND o.session = S AND o.semester = 1;
    UPDATE registration.course_registration SET status = 'APPROVED', submitted_at = now(), approved_at = now() WHERE id = reg;
    PERFORM set_config('moaum.actor_office', 'student', true);
    i3 := registration.issue_gst_eps_permit(stu, S, 1, 'DOWNLOAD');
    SELECT string_agg(c->>'course_code', ',' ORDER BY c->>'course_code') INTO courses3 FROM jsonb_array_elements(i3->'courses') c;
    SELECT string_agg(c->>'course_code', ',') INTO courses2 FROM jsonb_array_elements(st2->'courses') c;
    RAISE EXCEPTION 'CHECK_V492_UNDONE' USING ERRCODE = 'P0001';
  EXCEPTION WHEN raise_exception THEN
    GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
    IF msg <> 'CHECK_V492_UNDONE' THEN RAISE; END IF;
  END;
    PERFORM pg_temp.assert('V492: a GST & EPS permit carries exactly the GST and EPS courses on the approved registration for its semester — never a departmental course, another semester''s or one not registered; none without one, none for a draft, none until the examination card''s fees are cleared',
        coalesce(courses = 'GST 929:GST,EPS 929:EPS' AND (st->>'gstCount')::int = 1 AND (st->>'epsCount')::int = 1 AND (st->>'units')::int = 4
            AND courses2 = 'GST 928' AND st_dep->>'code' = 'GST_EPS_PERMIT_NO_COURSES' AND jsonb_array_length(st_dep->'courses') = 0
            AND st_draft->>'code' = 'GST_EPS_PERMIT_NOT_APPROVED' AND jsonb_array_length(st_draft->'courses') = 0
            AND st_unpaid->>'code' = 'GST_EPS_PERMIT_NOT_CLEARED', false),
        format('first %s (%s) | second %s | departmental only %s | draft %s | unpaid %s', courses, st->>'units', courses2, st_dep->>'code', st_draft->>'code', st_unpaid->>'code'));
    PERFORM pg_temp.assert('V492: a permit is issued once with its reference and counted; its log is written once; withdrawn only with a reason by an office whose course it carries, and restored; a reset takes its courses off and a new registration puts the new ones on under the same number',
        coalesce(ref ~ '^GST-EPS/9592/[0-9]{6,}$' AND i2->'permit'->>'reference' = ref AND n_permits = 1 AND (i2->'permit'->>'viewed')::int = 1 AND (i2->'permit'->>'printed')::int = 1
            AND events = 'GST_EPS_PERMIT_GENERATED,GST_EPS_PERMIT_PRINTED,GST_EPS_PERMIT_VIEWED' AND once = 'refused' AND short_reason = 'GST_EPS_PERMIT_REASON'
            AND revoked->>'code' = 'GST_EPS_PERMIT_REVOKED' AND (restored->>'available')::boolean
            AND after_reset->>'code' = 'GST_EPS_PERMIT_NOT_APPROVED' AND jsonb_array_length(after_reset->'courses') = 0
            AND i3->'permit'->>'reference' = ref AND courses3 = 'GST 928', false),
        format('reference %s / %s, permits %s, counts %s/%s | log %s, update %s | short reason %s | revoked %s, restored %s | after reset %s | again %s %s',
               ref, i2->'permit'->>'reference', n_permits, i2->'permit'->>'viewed', i2->'permit'->>'printed', events, once, short_reason,
               revoked->>'code', restored->>'available', after_reset->>'code', i3->'permit'->>'reference', courses3));
END $$;


-- ── V493: graduation follows the register ──
-- A finalist is enrolled at the final level the register states for the programme — a change there is followed — and a
-- postgraduate on a programme without research is a finalist by coursework once every required course is passed. The block
-- undoes its writes.
DO $$
DECLARE ug text; pg text; lvl int; v_ses text; st uuid := gen_random_uuid(); pgs uuid := gen_random_uuid();
        o uuid := gen_random_uuid(); reg uuid := gen_random_uuid(); sh uuid := gen_random_uuid();
        at400 boolean; at500 boolean; basis text; level_of int; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', '00000000-0000-0000-0000-000000000000', true);
        PERFORM set_config('moaum.actor_office', 'ict', true);
        PERFORM set_config('moaum.reason', 'check V493', true);
        v_ses := (SELECT name FROM policy.academic_session ORDER BY name LIMIT 1);
        ug := (SELECT p.code FROM ref.programme p WHERE p.category = 'UNDER GRADUATE' AND NOT coalesce(p.archived, false) ORDER BY p.code LIMIT 1);
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status)
        VALUES (st, 'MOAUM/ADM/60/949301', 'CHECKV493', 'Finalist', ug, 'UTME', v_ses, 100, 500, 'ADMITTED');
        INSERT INTO people.enrolment (id, student_id, session, level) VALUES (gen_random_uuid(), st, v_ses, 500);
        UPDATE ref.programme SET final_level = 400 WHERE code = ug;
        at400 := EXISTS (SELECT 1 FROM records.graduation_finalists(v_ses) f WHERE f.student_id = st);
        UPDATE ref.programme SET final_level = 500 WHERE code = ug;   -- the register says five years now
        at500 := EXISTS (SELECT 1 FROM records.graduation_finalists(v_ses) f WHERE f.student_id = st AND f.basis = 'LEVEL');
        level_of := records.final_level_of(st);
        -- a postgraduate on a programme without research, every required course passed in the session
        SELECT p.code, admissions.pg_award_level(p.pg_award) INTO pg, lvl FROM ref.programme p
         WHERE p.category = 'POST GRADUATE' AND NOT coalesce(p.pg_research, false) AND NOT coalesce(p.archived, false) ORDER BY p.code LIMIT 1;
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status)
        VALUES (pgs, 'MOAUM/ADM/60/949302', 'CHECKV493', 'Postgraduate', pg, 'POSTGRADUATE', v_ses, lvl, lvl, 'ADMITTED');
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, state)
        VALUES ('ZQG 801', 'Check required course', 3, 1, lvl, (SELECT dept_code FROM ref.programme WHERE code = pg), 'LIVE');
        INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES ('ZQG 801', pg, lvl, 'Core');
        INSERT INTO catalogue.offering (id, course_code, session, semester, stream) VALUES (o, 'ZQG 801', v_ses, 1, 'PG');
        INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, submitted_at, approved_at)
        VALUES (reg, pgs, v_ses, 1, lvl, 'APPROVED', now(), now());
        INSERT INTO registration.entry (registration_id, offering_id, units, status) VALUES (reg, o, 3, 'APPROVED');
        UPDATE people.student SET status = 'ACTIVE', matric_no = 'MOAUM/PGC/60/94930', matriculated_at = now() WHERE id = pgs;
        INSERT INTO assessment.score_sheet (id, offering_id, stage, senate_minute, published_at, submitted_at) VALUES (sh, o, 'PUBLISHED', 'SEN/CHK/493', now(), now());
        INSERT INTO assessment.score (sheet_id, student_id, ca, exam, outcome) VALUES (sh, pgs, 30, 45, 'GRADED');
        SELECT f.basis INTO basis FROM records.graduation_finalists(v_ses) f WHERE f.student_id = pgs;
        RAISE EXCEPTION 'the V493 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V493 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V493: a finalist is enrolled at the final level the register states (a change followed); a postgraduate without research is a finalist by coursework once every required course is passed',
        coalesce(NOT at400 AND at500 AND level_of = 500 AND basis = 'COURSEWORK', false),
        format('at 500 with final 400 %s | with final 500 %s (final level of %s) | postgraduate %s', at400, at500, level_of, basis));
END $$;


-- ── V494: a department's fee figures agree with the registration gate ──
-- A student with no fee stated for the session, nothing due, is not cleared by the department's figures, as the gate refuses
-- them. The block undoes its writes.
DO $$
DECLARE st uuid := gen_random_uuid(); sch uuid := gen_random_uuid(); v_ses text; set_says boolean; gate_says boolean; stated boolean; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', '00000000-0000-0000-0000-000000000000', true);
        PERFORM set_config('moaum.actor_office', 'ict', true);
        PERFORM set_config('moaum.reason', 'check V494', true);
        v_ses := (SELECT name FROM policy.academic_session ORDER BY name DESC LIMIT 1);
        -- a clearance scheme in force for the reading (the same one block 19 states), where the suite has none in force now
        IF policy.in_force('clearance', 'UNIVERSITY', current_date) IS NULL THEN
            INSERT INTO policy.version (id, kind, scope, validity, instrument, decided_by)
            VALUES (sch, 'clearance', 'UNIVERSITY', daterange(current_date - 1, NULL), 'CHECK V494', 'bursar');
            INSERT INTO policy.clearance_scheme VALUES (sch, true);
            INSERT INTO policy.clearance_rule VALUES
                (sch,'REGISTRATION','INSTALMENT_1'), (sch,'ID_CARD','INSTALMENT_1'), (sch,'LIBRARY','INSTALMENT_1'), (sch,'HOSTEL','INSTALMENT_1'),
                (sch,'EXAMINATION','INSTALMENT_2'), (sch,'RESULTS','PAID_IN_FULL'), (sch,'TRANSCRIPT','PAID_IN_FULL'), (sch,'CONVOCATION','PAID_IN_FULL');
        END IF;
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status)
        VALUES (st, 'MOAUM/ADM/60/949401', 'CHECKV494', 'Unstated', (SELECT p.code FROM ref.programme p WHERE p.category = 'UNDER GRADUATE' AND NOT coalesce(p.archived, false) ORDER BY p.code LIMIT 1),
                'UTME', v_ses, 100, 100, 'ADMITTED');
        stated := finance.fee_stated(st, v_ses);
        SELECT cl.clears INTO set_says FROM finance.session_clears(v_ses, 'REGISTRATION') cl WHERE cl.student_id = st;
        gate_says := finance.clears(st, v_ses, 'REGISTRATION');
        RAISE EXCEPTION 'the V494 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V494 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V494: a student with no fee stated is not counted cleared by the department''s figures, as the registration gate refuses them',
        coalesce((stated OR (set_says IS NOT DISTINCT FROM false)) AND set_says IS NOT DISTINCT FROM gate_says, false),
        format('fee stated %s | department figures %s | gate %s', stated, set_says, gate_says));
END $$;


-- ── V495: the minimum course registration load by curriculum ──
-- CCMAS and BMAS each bind an undergraduate to their own minimum (15 and 18 by the standing rule); a session's or a semester's own
-- rule wins where set; a CCE load the Centre stated and a postgraduate's level keep their own; only the Directorate of ICT sets it,
-- a whole number from 1 no higher than the lowest undergraduate maximum, with a reason; the standing rule is never removed; each
-- change is logged with the value before and after, one rule a scope; a registration below the minimum is listed. The block undoes
-- its writes.
DO $$
DECLARE s1 text := '2391/2392'; s2 text := '2392/2393'; c uuid := gen_random_uuid(); b uuid := gen_random_uuid(); g uuid := gen_random_uuid();
        e uuid := gen_random_uuid(); ug text; pg text; pglvl int; maxu int; o uuid := gen_random_uuid(); rb uuid := gen_random_uuid(); rc uuid := gen_random_uuid();
        std_c int; std_b int; basis_c text; cur_c text; pg_basis text; pg_min int; cce_basis text; cce_min int; max_c int;
        s1_c int; s2_c int; s1_sem2 int; s1_sem1 int; two_arg int; four_arg int; after_change int;
        r_office text; r_zero text; r_over text; r_reason text; r_standing text; r_curr text; n_scope int; hist text; removed_back int;
        listed_b boolean; listed_c boolean; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', '00000000-0000-0000-0000-000000000000', true);
        PERFORM set_config('moaum.actor_office', 'ict', true);
        PERFORM set_config('moaum.reason', 'check V495', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES
            (gen_random_uuid(), s1, DATE '2391-10-01', DATE '2392-08-31'), (gen_random_uuid(), s2, DATE '2392-10-01', DATE '2393-08-31');
        ug := (SELECT p.code FROM ref.programme p WHERE p.category = 'UNDER GRADUATE' AND NOT coalesce(p.archived, false) ORDER BY p.code LIMIT 1);
        SELECT p.code, admissions.pg_award_level(p.pg_award) INTO pg, pglvl FROM ref.programme p
         WHERE p.category = 'POST GRADUATE' AND NOT coalesce(p.archived, false) ORDER BY p.code LIMIT 1;
        maxu := (SELECT min(max_units) FROM policy.level_limit WHERE level BETWEEN 100 AND 600);
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, study_mode) VALUES
            (c, 'MOAUM/ADM/91/949501', 'CHECKV495', 'Ccmas', ug, 'UTME', s1, 100, 100, 'ADMITTED', 'FULL_TIME'),
            (b, 'MOAUM/ADM/91/949502', 'CHECKV495', 'Bmas', ug, 'UTME', s1, 100, 100, 'ADMITTED', 'FULL_TIME'),
            (g, 'MOAUM/ADM/91/949503', 'CHECKV495', 'Postgraduate', pg, 'POSTGRADUATE', s1, pglvl, pglvl, 'ADMITTED', 'FULL_TIME'),
            (e, 'MOAUM/ADM/91/949504', 'CHECKV495', 'Cce', ug, 'CCE', s1, 100, 100, 'ADMITTED', 'PART_TIME');
        UPDATE people.student SET curriculum_version = CASE WHEN id = b OR id = g THEN 'BMAS' ELSE 'CCMAS' END WHERE id IN (c, b, g, e);
        INSERT INTO policy.route_level_limit (route, level, min_units, max_units) VALUES ('CCE', 100, 6, 12)
        ON CONFLICT (route, level) DO UPDATE SET min_units = 6, max_units = 12;

        -- the standing rules, and who each binds
        SELECT u.min_units, u.basis, u.curriculum, u.max_units INTO std_c, basis_c, cur_c, max_c FROM registration.unit_rule(c, 100, s1, 1) u;
        std_b := (SELECT u.min_units FROM registration.unit_rule(b, 100, s1, 1) u);
        SELECT u.basis, u.min_units INTO pg_basis, pg_min FROM registration.unit_rule(g, pglvl, s1, 1) u;
        SELECT u.basis, u.min_units INTO cce_basis, cce_min FROM registration.unit_rule(e, 100, s1, 1) u;

        -- a session's own, and a semester's within it
        PERFORM registration.set_unit_minimum('CCMAS', s1, NULL, 16, 'Check: CCMAS sixteen for the session');
        PERFORM registration.set_unit_minimum('CCMAS', s1, 2, 17, 'Check: CCMAS seventeen in the second semester');
        s1_c := (SELECT u.min_units FROM registration.unit_rule(c, 100, s1, NULL) u);
        s1_sem1 := (SELECT u.min_units FROM registration.unit_rule(c, 100, s1, 1) u);
        s1_sem2 := (SELECT u.min_units FROM registration.unit_rule(c, 100, s1, 2) u);
        s2_c := (SELECT u.min_units FROM registration.unit_rule(c, 100, s2, 1) u);
        PERFORM registration.set_unit_minimum('CCMAS', s1, NULL, 16, 'Check: the same rule set again');
        n_scope := (SELECT count(*) FROM registration.unit_minimum WHERE curriculum = 'CCMAS' AND session = s1 AND semester IS NULL);
        PERFORM registration.set_unit_minimum('CCMAS', s1, NULL, 18, 'Check: CCMAS raised to eighteen');
        after_change := (SELECT u.min_units FROM registration.unit_rule(c, 100, s1, 1) u);
        PERFORM registration.set_unit_minimum('CCMAS', s1, 2, NULL, 'Check: the second semester follows the session again');
        removed_back := (SELECT u.min_units FROM registration.unit_rule(c, 100, s1, 2) u);
        hist := (SELECT string_agg(replace(x.event, 'COURSE_REGISTRATION_MIN_CREDIT_', '') || ':' || coalesce(x.semester::text, '-') || ':' || coalesce(x.before_units::text, '-') || '>' || coalesce(x.after_units::text, '-'), ' ' ORDER BY x.changed_at, x.id)
                   FROM registration.unit_minimum_change x WHERE x.session = s1);
        -- the two-argument form reads the student's current session
        two_arg := (SELECT l.min_units FROM registration.unit_limit(c, 100) l);
        four_arg := (SELECT l.min_units FROM registration.unit_limit(c, 100, people.student_current_session(c), NULL) l);

        -- refusals
        PERFORM set_config('moaum.actor_office', 'academic', true);
        BEGIN PERFORM registration.set_unit_minimum('CCMAS', s1, NULL, 15, 'Check: not the Directorate'); r_office := 'SET';
        EXCEPTION WHEN insufficient_privilege THEN r_office := 'REFUSED'; END;
        PERFORM set_config('moaum.actor_office', 'ict', true);
        BEGIN PERFORM registration.set_unit_minimum('CCMAS', s2, NULL, 0, 'Check: zero units'); r_zero := 'SET';
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_zero := split_part(msg, ':', 1); END;
        BEGIN PERFORM registration.set_unit_minimum('BMAS', s2, NULL, maxu + 1, 'Check: above the maximum'); r_over := 'SET';
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_over := split_part(msg, ':', 1); END;
        BEGIN PERFORM registration.set_unit_minimum('BMAS', s2, NULL, 18, 'short'); r_reason := 'SET';
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_reason := split_part(msg, ':', 1); END;
        BEGIN PERFORM registration.set_unit_minimum('BMAS', NULL, NULL, NULL, 'Check: the standing rule removed'); r_standing := 'REMOVED';
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_standing := split_part(msg, ':', 1); END;
        BEGIN PERFORM registration.set_unit_minimum('NUCX', NULL, NULL, 12, 'Check: no such curriculum'); r_curr := 'SET';
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; r_curr := split_part(msg, ':', 1); END;

        -- the registrations below the minimum that binds them: BMAS 15 of 18 is listed, CCMAS 18 of 18 is not
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, state)
        VALUES ('ZQM 101', 'Check load course', 3, 1, 100, (SELECT dept_code FROM ref.programme WHERE code = ug), 'LIVE');
        INSERT INTO catalogue.offering (id, course_code, session, semester, stream) VALUES (o, 'ZQM 101', s1, 1, 'REGULAR');
        INSERT INTO registration.course_registration (id, student_id, session, semester, level, status) VALUES
            (rb, b, s1, 1, 100, 'DRAFT'), (rc, c, s1, 1, 100, 'DRAFT');
        INSERT INTO registration.entry (registration_id, offering_id, units, status) VALUES (rb, o, 15, 'REGISTERED'), (rc, o, 18, 'REGISTERED');
        listed_b := EXISTS (SELECT 1 FROM registration.below_minimum(s1, 1) x WHERE x.registration_id = rb AND x.min_units = 18 AND x.units = 15 AND x.curriculum = 'BMAS');
        listed_c := EXISTS (SELECT 1 FROM registration.below_minimum(s1, 1) x WHERE x.registration_id = rc);
        RAISE EXCEPTION 'the V495 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V495 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V495: the minimum course load binds by curriculum (CCMAS 15, BMAS 18 standing; a session''s and a semester''s own win), a CCE load and a postgraduate''s level keep theirs; only ICT sets it, from 1 to the maximum, with a reason; the standing rule stays; each change logged; below-minimum listed',
        coalesce(std_c = 15 AND basis_c = 'CURRICULUM' AND cur_c = 'CCMAS' AND max_c = (SELECT max_units FROM policy.level_limit WHERE level = 100) AND std_b = 18
                 AND pg_basis = 'LEVEL' AND pg_min = (SELECT min_units FROM policy.level_limit WHERE level = pglvl) AND cce_basis = 'CCE' AND cce_min = 6
                 AND s1_c = 16 AND s1_sem1 = 16 AND s1_sem2 = 17 AND s2_c = 15 AND n_scope = 1 AND after_change = 18 AND removed_back = 18
                 AND hist = 'SET:-:->16 SET:2:->17 CHANGED:-:16>18 REMOVED:2:17>-' AND two_arg = four_arg
                 AND r_office = 'REFUSED' AND r_zero = 'REG_MIN_UNITS_POSITIVE' AND r_over = 'REG_MIN_UNITS_OVER_MAXIMUM' AND r_reason = 'REG_MIN_UNITS_REASON'
                 AND r_standing = 'REG_MIN_UNITS_STANDING' AND r_curr = 'REG_MIN_UNITS_CURRICULUM' AND listed_b AND NOT listed_c, false),
        format('standing %s %s %s max %s / %s | pg %s %s | cce %s %s | s1 %s sem1 %s sem2 %s s2 %s | one a scope %s | changed %s removed %s | %s | two/four %s/%s | refusals %s %s %s %s %s %s | listed %s %s',
               std_c, basis_c, cur_c, max_c, std_b, pg_basis, pg_min, cce_basis, cce_min, s1_c, s1_sem1, s1_sem2, s2_c, n_scope, after_change, removed_back, hist,
               two_arg, four_arg, r_office, r_zero, r_over, r_reason, r_standing, r_curr, listed_b, listed_c));
END $$;


-- ── V499: the old-portal fees reset reverses the ledger and keeps what it deleted ──
-- An old-portal record the ledger posted is deleted with its journal reversed (the books net to nothing for it) and kept on
-- finance.legacy_payment_reset; a portal payment is never touched; one a deferment fee points at is kept and counted; the batch
-- says what remains; the same payment loaded again is unposted and posts once. The block undoes its writes.
DO $$
DECLARE ses text := '2393/2394'; st uuid := gen_random_uuid(); leg text := 'MOAUM-LEG-CHK499-2393/2394-S1'; kept text := 'MOAUM-LEG-CHK499-2393/2394-S2';
        portal text := 'MOAUM-CHK499-PORTAL'; leg2 text := 'MOAUM-LEG-CHK499-2393/2394-S3';
        j uuid; r record; r2 record; v_status text; v_type text; n_rev int; net numeric; portal_left boolean; leg_left boolean; kept_left boolean;
        saved int; unposted_after boolean; n_payment_journals int; refused text; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', '00000000-0000-0000-0000-000000000000', true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM set_config('moaum.reason', 'check V499', true);
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status)
        VALUES (st, 'MOAUM/ADM/93/949901', 'CHECKV499', 'Legacy', (SELECT p.code FROM ref.programme p WHERE p.category = 'UNDER GRADUATE' AND NOT coalesce(p.archived, false) ORDER BY p.code LIMIT 1),
                'UTME', '2020/2021', 100, 100, 'ADMITTED');
        INSERT INTO finance.payment_reference (student_id, session, reference, purpose, amount, expires_at, confirmed_at, confirmed_by, channel, receipt_no) VALUES
            (st, ses, leg,    'School fees (legacy) first semester', 45000, now() + interval '1 day', now(), st, 'Legacy', 'CHK499-1'),
            (st, ses, kept,   'School fees (legacy) second semester', 45000, now() + interval '1 day', now(), st, 'Legacy', 'CHK499-2'),
            (st, ses, leg2,   'School fees (legacy) third semester', 5000, now() + interval '1 day', now(), st, 'Legacy', 'CHK499-3'),
            (st, ses, portal, 'School fees ' || ses, 10000, now() + interval '1 day', now(), st, 'Card · Paystack', 'CHK499-4');
        INSERT INTO people.deferment_fee (id, student_id, session, reference, amount, state, created_at) VALUES (gen_random_uuid(), st, ses, kept, 45000, 'CONFIRMED', now());
        -- the ledger posts the legacy payment as its sync does
        j := finance.gl_post(current_date, 'Fee receipt ' || leg, 'AUTO', 'PAYMENT', leg,
               jsonb_build_array(jsonb_build_object('account', '1010', 'debit', 45000, 'narration', 'check', 'session', ses),
                                 jsonb_build_object('account', finance.gl_income_account(finance.payment_category('School fees (legacy) first semester')), 'credit', 45000, 'narration', 'check', 'session', ses)));
        -- the word is asked for
        BEGIN PERFORM finance.reset_legacy_payments(ses, 'yes', 10); refused := 'NO';
        EXCEPTION WHEN check_violation THEN refused := 'REFUSED'; END;
        -- a batch of one, then the rest
        SELECT * INTO r FROM finance.reset_legacy_payments(ses, 'RESET', 1);
        SELECT * INTO r2 FROM finance.reset_legacy_payments(ses, 'RESET', 10);
        SELECT status, source_type INTO v_status, v_type FROM finance.gl_journal WHERE id = j;
        n_rev := (SELECT count(*) FROM finance.gl_journal WHERE reverses = j);
        net := (SELECT coalesce(sum(p.debit - p.credit), 0) FROM finance.gl_posting p
                 WHERE p.account = '1010' AND p.journal_id IN (SELECT j UNION SELECT id FROM finance.gl_journal WHERE reverses = j));
        portal_left := EXISTS (SELECT 1 FROM finance.payment_reference WHERE reference = portal);
        leg_left := EXISTS (SELECT 1 FROM finance.payment_reference WHERE reference IN (leg, leg2));
        kept_left := EXISTS (SELECT 1 FROM finance.payment_reference WHERE reference = kept);
        saved := (SELECT count(*) FROM finance.legacy_payment_reset WHERE student_id = st AND ledger_journal IS NOT DISTINCT FROM CASE WHEN reference = leg THEN j END);
        -- the same payment loaded again: unposted for the sync, and posted once
        INSERT INTO finance.payment_reference (student_id, session, reference, purpose, amount, expires_at, confirmed_at, confirmed_by, channel, receipt_no)
        VALUES (st, ses, leg, 'School fees (legacy) first semester', 45000, now() + interval '1 day', now(), st, 'Legacy', 'CHK499-5');
        unposted_after := NOT EXISTS (SELECT 1 FROM finance.gl_journal g WHERE g.source_type = 'PAYMENT' AND g.source_ref = leg);
        PERFORM finance.gl_post(current_date, 'Fee receipt ' || leg, 'AUTO', 'PAYMENT', leg,
               jsonb_build_array(jsonb_build_object('account', '1010', 'debit', 45000, 'narration', 'check', 'session', ses),
                                 jsonb_build_object('account', finance.gl_income_account(finance.payment_category('School fees (legacy) first semester')), 'credit', 45000, 'narration', 'check', 'session', ses)));
        n_payment_journals := (SELECT count(*) FROM finance.gl_journal WHERE source_type = 'PAYMENT' AND source_ref = leg);
        RAISE EXCEPTION 'the V499 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V499 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V499: the old-portal fees reset reverses each posted record''s ledger journal and frees its reference, keeps what it deleted, never touches a portal payment, keeps one a deferment fee points at, and works in batches',
        coalesce(refused = 'REFUSED' AND r.deleted = 1 AND r.remaining = 1 AND r.kept_in_use = 1 AND r2.deleted = 1 AND r2.remaining = 0
                 AND r.ledger_reversed + r2.ledger_reversed = 1 AND v_status = 'REVERSED' AND v_type = 'PAYMENT_RESET' AND n_rev = 1 AND net = 0
                 AND portal_left AND NOT leg_left AND kept_left AND saved = 2 AND unposted_after AND n_payment_journals = 1, false),
        format('refused %s | batch 1: %s | batch 2: %s | journal %s/%s reversals %s net %s | portal kept %s legacy left %s linked kept %s | saved %s | reload unposted %s journals %s',
               refused, r, r2, v_status, v_type, n_rev, net, portal_left, leg_left, kept_left, saved, unposted_after, n_payment_journals));
END $$;
-- ── V490. Reported receipts closed out: five references of one payer opened on Pay on Quickteller 30 hours before at 10:00
--          Lagos time. 0001's receipt waits; 0002's Payment Log Id (typed with spaces and a dash) came in Interswitch's
--          notification for 0002 short of the amount (SEEN); 0003's came in the collections report against 0009 (ELSEWHERE);
--          0004's the Bursary marks not found — refused without a note, the payer told — then the payer corrects it (WAITING
--          again) and the Bursary marks and reopens it; 0005 has no receipt. Interswitch is asked about 0001 and 0005 only;
--          the Bursary's daily list holds 0001, 0002, 0003 and 0005 with the receipts named; a confirmed reference's receipt
--          cannot be marked; the desk's act is a payment act. The block undoes its writes ──
DO $$
DECLARE who uuid := gen_random_uuid(); bur uuid := gen_random_uuid(); st uuid := gen_random_uuid(); v_ses text;
        at10 timestamptz := (date_trunc('day', now() AT TIME ZONE 'Africa/Lagos') + interval '10 hours') AT TIME ZONE 'Africa/Lagos';
        today date := (now() AT TIME ZONE 'Africa/Lagos')::date;
        states text; seen3 text; short_note text; no_actor text; told_payer int; reopened text; marked_again text; back text;
        ask text; waiting text; told int; mail text; confirmed_mark text; module text; con text; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM set_config('moaum.reason', 'check V490', true);
        UPDATE finance.paydirect_setting SET watch_enabled = true;
        INSERT INTO iam.person (id, surname, given_names, email) VALUES (bur, 'CHECKV490', 'Bursar', 'zz.check490@example.com');
        INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from)
        VALUES (gen_random_uuid(), bur, 'bursar', 'institution', NULL, 'check V490', who, current_date - 1);
        v_ses := (SELECT name FROM policy.academic_session ORDER BY name LIMIT 1);
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status)
        VALUES (st, 'MOAUM/ADM/60/949001', 'CHECKV490', 'Payer', (SELECT code FROM ref.programme WHERE NOT coalesce(archived, false) ORDER BY code LIMIT 1), 'UTME', v_ses, 100, 100, 'ADMITTED');
        INSERT INTO finance.payment_reference (student_id, session, reference, purpose, amount, expires_at)
        SELECT st, v_ses, 'MOAUM-FEE-949001-000' || g, 'check V490', 1000.00 * g, now() + interval '30 days' FROM generate_series(1, 5) g;
        INSERT INTO finance.payment_reference (student_id, session, reference, purpose, amount, expires_at)
        VALUES (st, v_ses, 'MOAUM-FEE-949001-0009', 'check V490: the number the payer typed on Quickteller', 3000.00, now() + interval '30 days');
        INSERT INTO finance.gateway_attempt (reference, gateway, kind, account_id, opened_at)
        SELECT 'MOAUM-FEE-949001-000' || g, 'paydirect', 'FEE', st, at10 - interval '30 hours' FROM generate_series(1, 5) g;
        -- the payer's receipts, as typed
        PERFORM set_config('moaum.actor_office', 'student', true);
        PERFORM finance.paydirect_claim_set('MOAUM-FEE-949001-0001', st, 'PL-490001', today, 1000, 'QUICKTELLER', NULL);
        PERFORM finance.paydirect_claim_set('MOAUM-FEE-949001-0002', st, ' pl 490-002 ', today, 2000, 'BANK', NULL);
        PERFORM finance.paydirect_claim_set('MOAUM-FEE-949001-0003', st, 'PL-490003', today, 3000, 'QUICKTELLER', NULL);
        PERFORM finance.paydirect_claim_set('MOAUM-FEE-949001-0004', st, 'PL-490004', today, 4000, 'QUICKTELLER', NULL);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        -- what Interswitch said: 0002's notification short of the amount; 0003's Log Id in the collections report against 0009
        INSERT INTO finance.gateway_event (gateway, source, event, reference, gateway_ref, amount, signature_ok, outcome, received_at)
        VALUES ('paydirect', 'WEBHOOK', 'notification', 'MOAUM-FEE-949001-0002', 'PL490002', 500.00, true, 'SHORT_PAID', at10 - interval '20 hours');
        INSERT INTO finance.paydirect_collection (biller_code, prn, amount, paid_at, channel, rrn, payer, state, reference, why)
        VALUES ('04255101', 'MOAUM-FEE-949001-0009', 3000.00, at10 - interval '25 hours', 'WEB', 'PL-490003', 'CHECKV490 Payer', 'MATCHED', 'MOAUM-FEE-949001-0009', NULL);
        -- the Bursary's word on 0004: refused without a note, refused without a person, then marked and the payer told
        BEGIN PERFORM finance.paydirect_claim_mark('MOAUM-FEE-949001-0004', true, 'no');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS short_note = MESSAGE_TEXT; END;
        PERFORM set_config('moaum.actor_id', '', true);
        BEGIN PERFORM finance.paydirect_claim_mark('MOAUM-FEE-949001-0004', true, 'Interswitch has no payment with this Log Id');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS no_actor = MESSAGE_TEXT; END;
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM finance.paydirect_claim_mark('MOAUM-FEE-949001-0004', true, 'Interswitch has no payment with this Log Id');
        told_payer := (SELECT count(*) FROM platform.notice n WHERE n.about_id = st AND n.template_key = 'PAYDIRECT_RECEIPT_NOT_FOUND'
                          AND n.body LIKE '%Interswitch has no payment with this Log Id%');
        states := (SELECT string_agg(right(c.reference, 4) || ':' || c.state, ',' ORDER BY c.reference)
                     FROM finance.paydirect_claims() c WHERE c.reference LIKE 'MOAUM-FEE-949001-%');
        seen3 := (SELECT c.seen_reference || '/' || c.seen_in FROM finance.paydirect_claims(30, 'moaum-fee-949001-0003') c);
        SELECT string_agg(right(a.reference, 4) || ':' || coalesce(a.payment_log_id, '-'), ',' ORDER BY a.reference) INTO ask
          FROM finance.paydirect_ask_list() a WHERE a.reference LIKE 'MOAUM-FEE-949001-%';
        SELECT string_agg(right(w.reference, 4) || ':' || coalesce(w.state, '-'), ',' ORDER BY w.reference) INTO waiting
          FROM finance.paydirect_waiting(at10) w WHERE w.reference LIKE 'MOAUM-FEE-949001-%';
        told := finance.watch_paydirect_unreported(at10);
        mail := (SELECT n.body FROM platform.notice n WHERE n.about_kind = 'person' AND n.about_id = bur AND n.template_key = 'PAYDIRECT_UNREPORTED' AND n.channel = 'EMAIL');
        -- the payer corrects 0004: waiting again; the Bursary marks it again and reopens it
        PERFORM set_config('moaum.actor_office', 'student', true);
        PERFORM finance.paydirect_claim_set('MOAUM-FEE-949001-0004', st, 'PL-490044', today, 4000, 'QUICKTELLER', 'the Log Id corrected');
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        reopened := (SELECT c.state || '/' || c.payment_log_id FROM finance.paydirect_claims(30, 'MOAUM-FEE-949001-0004') c);
        PERFORM finance.paydirect_claim_mark('MOAUM-FEE-949001-0004', true, 'Interswitch has no payment with this Log Id either');
        marked_again := (SELECT c.state FROM finance.paydirect_claims(30, 'MOAUM-FEE-949001-0004') c);
        PERFORM finance.paydirect_claim_mark('MOAUM-FEE-949001-0004', false, NULL);
        back := (SELECT c.state || coalesce('/' || c.not_found_note, '') FROM finance.paydirect_claims(30, 'MOAUM-FEE-949001-0004') c);
        -- confirmed, a receipt is the payment's: not marked
        PERFORM finance.confirm_payment('MOAUM-FEE-949001-0001', 'Quickteller · WEB', 'check V490');
        BEGIN PERFORM finance.paydirect_claim_mark('MOAUM-FEE-949001-0001', true, 'Interswitch has no payment with this Log Id');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS confirmed_mark = MESSAGE_TEXT; END;
        confirmed_mark := confirmed_mark || '/' || (SELECT c.state FROM finance.paydirect_claims(30, 'MOAUM-FEE-949001-0001') c);
        -- the desk's act is a payment act
        module := helpdesk.support_module('PAYMENT_RECEIPT_REPORTED');
        con := (SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conname = 'ck_hd_sa_action');
        RAISE EXCEPTION 'the V490 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V490 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V490: a reported receipt is matched against what Interswitch said — waiting, seen short, seen under another reference — or marked not found by the Bursary with the payer told, reopened by a corrected receipt; only what Interswitch can answer is sent to it; the daily list names the receipts; the desk''s act is a payment act',
        coalesce(states = '0001:WAITING,0002:SEEN,0003:ELSEWHERE,0004:NOT_FOUND' AND seen3 = 'MOAUM-FEE-949001-0009/COLLECTIONS'
                 AND short_note LIKE 'PAY_CLAIM_NOTE%' AND no_actor LIKE 'PAY_CLAIM_ACTOR%' AND told_payer >= 1
                 AND ask = '0001:PL-490001,0005:-' AND waiting = '0001:WAITING,0002:SEEN,0003:ELSEWHERE,0005:-'
                 AND told >= 1 AND mail LIKE '%MOAUM-FEE-949001-0001%receipt PL-490001%'
                 AND mail LIKE '%receipt PL-490003, paid % reported by Interswitch against MOAUM-FEE-949001-0009%'
                 AND mail LIKE '%Payers reported the receipt (its Payment Log Id) for 3 of them; Interswitch reported 1 of those against another reference%'
                 AND mail NOT LIKE '%MOAUM-FEE-949001-0004%'
                 AND reopened = 'WAITING/PL-490044' AND marked_again = 'NOT_FOUND' AND back = 'WAITING'
                 AND confirmed_mark LIKE 'PAY_CLAIM_CONFIRMED%/CONFIRMED'
                 AND module = 'PAYMENT' AND con LIKE '%PAYMENT_RECEIPT_REPORTED%', false),
        format('states %s | 0003 seen %s | short note %s | no actor %s | payer told %s | ask %s | waiting %s | told %s | mail %s | reopened %s, again %s, back %s | confirmed %s | module %s',
               states, seen3, short_note, no_actor, told_payer, ask, waiting, told, left(mail, 900), reopened, marked_again, back, confirmed_mark, module));
END $$;
-- ── V498. Old-portal payments: one way in, the payment number decides, payments on record twice withdrawn, reconciled against
--          the fee setup. X paid school fees on the old portal three times in the first semester (SCHOOL FEES, a MAKE UP, a part)
--          and once in the second; an earlier upload recorded only the first. The export with its payment numbers adds the other
--          two beside it, attaches the first's number to the record already there, skips the number repeated in the file, records
--          the second semester; loaded again, nothing changes. Q's semester was summed by the 15 Sep migration in whole naira
--          (₦200,000 for two payments of ₦99,999.80 and ₦100,000.10): both attach to it, nothing is added. The retired Payment
--          History Upload refuses; what it wrote twice is listed with W's whole-session record repeating its semester record
--          (the semester record keeps the number) and V's unnumbered record repeating a numbered payment; all withdrawn with a
--          reason, another amount kept. Reconciled: X under, Z matched, Y in a programme with no fee stated. Undoes its writes ──
DO $$
DECLARE who uuid := gen_random_uuid(); x uuid := gen_random_uuid(); y uuid := gen_random_uuid(); z uuid := gen_random_uuid();
        q uuid := gen_random_uuid(); w uuid := gen_random_uuid(); v uuid := gen_random_uuid();
        ses text := '9987/9988'; pa text; pb text; base text := 'MOAUM-LEG-MOAUMCHK879801-9987-9988';
        qbase text := 'MOAUM-LEG-MOAUMCHK879804-9987-9988'; wbase text := 'MOAUM-LEG-MOAUMCHK879805-9987-9988'; vbase text := 'MOAUM-LEG-MOAUMCHK879806-9987-9988';
        imp record; again record; qimp record; refs text; paid_x numeric; numbers text; q_refs text; q_numbers text; retired text; doubles text; short_reason text;
        w1 record; w2 record; reg text; kept_other boolean; w_number text; rec text; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM set_config('moaum.reason', 'check V498', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), ses, date '9987-10-01', date '9988-08-31') ON CONFLICT (name) DO NOTHING;
        SELECT code INTO pa FROM ref.programme WHERE NOT coalesce(archived, false) ORDER BY code LIMIT 1;
        SELECT code INTO pb FROM ref.programme WHERE NOT coalesce(archived, false) AND code <> pa ORDER BY code LIMIT 1;
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at) VALUES
          (x, 'MOAUM/ADM/87/980001', 'MOAUM/CHK/87/9801', 'ZZCHKV498X', 'Invented', pa, 'UTME', ses, 100, 100, 'ACTIVE', now()),
          (y, 'MOAUM/ADM/87/980002', 'MOAUM/CHK/87/9802', 'ZZCHKV498Y', 'Invented', pb, 'UTME', ses, 100, 100, 'ACTIVE', now()),
          (z, 'MOAUM/ADM/87/980003', 'MOAUM/CHK/87/9803', 'ZZCHKV498Z', 'Invented', pa, 'UTME', ses, 100, 100, 'ACTIVE', now()),
          (q, 'MOAUM/ADM/87/980004', 'MOAUM/CHK/87/9804', 'ZZCHKV498Q', 'Invented', pa, 'UTME', ses, 100, 100, 'ACTIVE', now()),
          (w, 'MOAUM/ADM/87/980005', 'MOAUM/CHK/87/9805', 'ZZCHKV498W', 'Invented', pa, 'UTME', ses, 100, 100, 'ACTIVE', now()),
          (v, 'MOAUM/ADM/87/980006', 'MOAUM/CHK/87/9806', 'ZZCHKV498V', 'Invented', pa, 'UTME', ses, 100, 100, 'ACTIVE', now());
        INSERT INTO finance.fee_schedule (session, item, amount, level, programme_code) VALUES (ses, 'School fees', 250000, NULL, pa);
        -- what the earlier uploads left
        INSERT INTO finance.payment_reference (student_id, session, reference, purpose, amount, expires_at, confirmed_at, confirmed_by, channel, receipt_no, note) VALUES
          (x, ses, base || '-S1', 'School fees (legacy) · semester 1', 100000, '9987-11-02', '9987-11-02', who, 'Legacy', 'LEG-' || base || '-S1', 'Imported from the old portal'),
          (z, ses, 'MOAUM-LEG-MOAUMCHK879803-9987-9988', 'School fees (legacy)', 250000, '9987-11-05', '9987-11-05', who, 'Legacy', 'LEG-MOAUM-LEG-MOAUMCHK879803-9987-9988', 'Imported from the old portal'),
          (y, ses, 'MOAUM-LEG-MOAUMCHK879802-9987-9988', 'School fees (legacy)', 90000, '9987-11-06', '9987-11-06', who, 'Legacy', 'LEG-MOAUM-LEG-MOAUMCHK879802-9987-9988', 'Imported from the old portal'),
          -- the 15 Sep migration: Q's first semester summed from two payments, in whole naira; W's first semester
          (q, ses, qbase || '-S1', 'School fees (legacy) · semester 1', 200000, '9987-11-10', '9987-11-10', who, 'Legacy', 'LEG-' || qbase || '-S1', '2 school-fees payment(s), migrated'),
          (w, ses, wbase || '-S1', 'School fees (legacy) · semester 1', 36556, '9987-11-12', '9987-11-12', who, 'Legacy', 'LEG-' || wbase || '-S1', '1 school-fees payment(s), migrated'),
          -- the 5 Oct upload: W's payment again as the whole session, with its number; V's payment twice, once numbered
          (w, ses, wbase, 'School fees (legacy)', 36555.80, '9987-11-12', '9987-11-12', who, 'Legacy', 'LEG-' || wbase, 'Imported from the old portal · old ref PRW0001'),
          (v, ses, vbase || '-S2', 'School fees (legacy) · semester 2', 41447.17, '9988-02-03', '9988-02-03', who, 'Legacy', 'LEG-' || vbase || '-S2', 'Imported from the old portal · old ref PRV0001'),
          (v, ses, vbase, 'School fees (legacy)', 41447, '9988-02-03', '9988-02-03', who, 'Legacy', 'LEG-' || vbase, 'Imported from the old portal');
        INSERT INTO finance.legacy_payref (payref, reference, amount) VALUES ('PRW0001', wbase, 36555.80), ('PRV0001', vbase || '-S2', 41447.17);
        -- the export, as the old portal writes it (matno, payref, treatedby)
        SELECT * INTO imp FROM finance.import_legacy_payments(jsonb_build_array(
            jsonb_build_object('matno', 'MOAUM/CHK/87/9801', 'session', ses, 'semester', 'First',  'amount', '100000', 'purpose', 'SCHOOL FEES',         'paidOn', '9987-11-02', 'payref', 'PR98798010001', 'channel', 'Interswitch'),
            jsonb_build_object('matno', 'MOAUM/CHK/87/9801', 'session', ses, 'semester', 'First',  'amount', '20000',  'purpose', 'SCHOOL FEES MAKE UP', 'paidOn', '9988-01-15', 'payref', 'PR98798010002', 'channel', 'Interswitch'),
            jsonb_build_object('matno', 'MOAUM/CHK/87/9801', 'session', ses, 'semester', 'First',  'amount', '30000',  'purpose', 'SCHOOL FEES',         'paidOn', '9988-02-01', 'payref', 'PR98798010003', 'channel', 'E-Wallet'),
            jsonb_build_object('matno', 'MOAUM/CHK/87/9801', 'session', ses, 'semester', 'First',  'amount', '20000',  'purpose', 'SCHOOL FEES MAKE UP', 'paidOn', '9988-01-15', 'payref', 'PR98798010002', 'channel', 'Interswitch'),
            jsonb_build_object('matno', 'MOAUM/CHK/87/9801', 'session', ses, 'semester', 'Second', 'amount', '50000',  'purpose', 'SCHOOL FEES',         'paidOn', '9988-03-01', 'payref', 'PR98798010004', 'channel', 'Old Record')));
        SELECT * INTO again FROM finance.import_legacy_payments(jsonb_build_array(
            jsonb_build_object('matno', 'MOAUM/CHK/87/9801', 'session', ses, 'semester', 'First',  'amount', '100000', 'purpose', 'SCHOOL FEES',         'paidOn', '9987-11-02', 'payref', 'PR98798010001'),
            jsonb_build_object('matno', 'MOAUM/CHK/87/9801', 'session', ses, 'semester', 'First',  'amount', '20000',  'purpose', 'SCHOOL FEES MAKE UP', 'paidOn', '9988-01-15', 'payref', 'PR98798010002'),
            jsonb_build_object('matno', 'MOAUM/CHK/87/9801', 'session', ses, 'semester', 'Second', 'amount', '50000',  'purpose', 'SCHOOL FEES',         'paidOn', '9988-03-01', 'payref', 'pr98798010004')));
        SELECT * INTO qimp FROM finance.import_legacy_payments(jsonb_build_array(
            jsonb_build_object('matno', 'MOAUM/CHK/87/9804', 'session', ses, 'semester', 'First', 'amount', '99999.80',  'purpose', 'SCHOOL FEES', 'paidOn', '9987-11-10', 'payref', 'PRQ0001'),
            jsonb_build_object('matno', 'MOAUM/CHK/87/9804', 'session', ses, 'semester', 'First', 'amount', '100000.10', 'purpose', 'SCHOOL FEES', 'paidOn', '9987-11-10', 'payref', 'PRQ0002')));
        refs := (SELECT string_agg(replace(reference, base, '') || '=' || amount::int, ',' ORDER BY reference) FROM finance.payment_reference WHERE student_id = x);
        paid_x := (SELECT sum(amount) FROM finance.payment_reference WHERE student_id = x AND purpose LIKE 'School fees%' AND confirmed_at IS NOT NULL);
        numbers := (SELECT string_agg(k.payref || '>' || replace(k.reference, base, ''), ',' ORDER BY k.payref) FROM finance.legacy_payref k WHERE k.reference LIKE base || '%');
        q_refs := (SELECT string_agg(replace(reference, qbase, '') || '=' || amount, ',' ORDER BY reference) FROM finance.payment_reference WHERE student_id = q);
        q_numbers := (SELECT string_agg(k.payref || '>' || replace(k.reference, qbase, '') || '=' || k.amount, ',' ORDER BY k.payref) FROM finance.legacy_payref k WHERE k.reference LIKE qbase || '%');
        -- the retired door
        BEGIN
            PERFORM finance.import_payments(jsonb_build_array(jsonb_build_object('matric', 'MOAUM/CHK/87/9801', 'session', ses, 'amount', '50000')));
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS retired = MESSAGE_TEXT;
        END;
        -- what it wrote before it was retired: the second semester's payment again (twice), and a payment of another amount
        INSERT INTO finance.payment_reference (student_id, session, reference, purpose, amount, generated_at, expires_at, confirmed_at, confirmed_by, channel, note, receipt_no) VALUES
          (x, ses, 'MIGR-CHKV498-0001', 'School fees ' || ses, 50000, '9988-03-01', '9988-03-02', '9988-03-01', who, 'MIGRATION', 'Migrated payment history', 'RCT-MIGR-CHKV498-0001'),
          (x, ses, 'MIGR-CHKV498-0002', 'School fees ' || ses, 50000, '9988-03-01', '9988-03-02', '9988-03-01', who, 'MIGRATION', 'Migrated payment history', 'RCT-MIGR-CHKV498-0002'),
          (x, ses, 'MIGR-CHKV498-0003', 'School fees ' || ses, 77, '9988-03-05', '9988-03-06', '9988-03-05', who, 'MIGRATION', 'Migrated payment history', 'RCT-MIGR-CHKV498-0003');
        doubles := (SELECT string_agg(regexp_replace(d.double_reference, '^MOAUM-LEG-MOAUMCHK8798', 'L') || ':' || d.double_kind || '>' || regexp_replace(d.kept_reference, '^MOAUM-LEG-MOAUMCHK8798', 'L'), ',' ORDER BY d.double_reference)
                      FROM finance.old_payment_doubles() d WHERE d.student_id IN (x, q, w, v, y, z));
        BEGIN
            PERFORM finance.withdraw_old_payment_doubles('no');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS short_reason = MESSAGE_TEXT;
        END;
        SELECT * INTO w1 FROM finance.withdraw_old_payment_doubles('CHECK V498: recorded twice by the earlier uploads', 1);
        SELECT * INTO w2 FROM finance.withdraw_old_payment_doubles('CHECK V498: recorded twice by the earlier uploads');
        reg := (SELECT string_agg(regexp_replace(o.reference, '^MOAUM-LEG-MOAUMCHK8798', 'L') || ':' || o.double_kind, ',' ORDER BY o.reference) FROM finance.old_payment_withdrawn o WHERE o.student_id IN (x, q, w, v));
        kept_other := EXISTS (SELECT 1 FROM finance.payment_reference WHERE reference = 'MIGR-CHKV498-0003');
        w_number := (SELECT k.reference FROM finance.legacy_payref k WHERE k.payref = 'PRW0001');
        -- reconciled against the fee setup
        rec := (SELECT string_agg(right(r.number, 4) || ':' || r.state || ':' || r.due::int || '/' || r.paid::int || '/' || r.paid_old_s1::int || '+' || r.paid_old_s2::int
                                  || '+' || r.paid_old_session::int || '+' || r.paid_payment_history::int || ':' || r.difference::int, ',' ORDER BY r.number)
                  FROM finance.old_fees_reconciliation(ses) r WHERE r.student_id IN (x, y, z));
        RAISE EXCEPTION 'the V498 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V498 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V498: the payment number decides (a make-up or second part beside the first, a summed record''s parts attached to it, within a naira), the retired Payment History Upload refuses, payments on record twice are withdrawn (a semester record keeps the number), and old payments are reconciled against the fee setup',
        coalesce(imp.rows = 5 AND imp.cleared = 3 AND imp.separate = 2 AND imp.matched = 1 AND imp.duplicates = 1
                 AND again.cleared = 0 AND again.duplicates = 3 AND again.matched = 0
                 AND refs = '-S1=100000,-S1-PR98798010002=20000,-S1-PR98798010003=30000,-S2=50000' AND paid_x = 200000
                 AND numbers = 'PR98798010001>-S1,PR98798010002>-S1-PR98798010002,PR98798010003>-S1-PR98798010003,PR98798010004>-S2'
                 AND qimp.matched = 2 AND qimp.cleared = 0 AND qimp.separate = 0 AND q_refs = '-S1=200000.00'
                 AND q_numbers = 'PRQ0001>-S1=99999.80,PRQ0002>-S1=100000.10'
                 AND retired LIKE 'PAYMENT_HISTORY_RETIRED%'
                 AND doubles = 'MIGR-CHKV498-0001:PAYMENT_HISTORY>L01-9987-9988-S2,MIGR-CHKV498-0002:PAYMENT_HISTORY>L01-9987-9988-S2,L05-9987-9988:WHOLE_SESSION>L05-9987-9988-S1,L06-9987-9988:UNNUMBERED>L06-9987-9988-S2'
                 AND short_reason LIKE 'PAY_DOUBLE_REASON%' AND w1.withdrawn = 1 AND w2.withdrawn = 3 AND w2.remaining = 0
                 AND reg = 'MIGR-CHKV498-0001:PAYMENT_HISTORY,MIGR-CHKV498-0002:PAYMENT_HISTORY,L05-9987-9988:WHOLE_SESSION,L06-9987-9988:UNNUMBERED'
                 AND kept_other AND w_number = wbase || '-S1'
                 AND rec = '9801:UNDER:250000/200077/150000+50000+0+77:-49923,9802:NO_FEE_STATED:0/90000/0+0+90000+0:90000,9803:MATCHED:250000/250000/0+0+250000+0:0', false),
        format('import %s/%s/sep %s/matched %s/dup %s | again %s/%s/%s | refs %s | paid %s | numbers %s | Q %s/%s/%s %s %s | retired %s | doubles %s | short %s | withdraw %s then %s/%s left %s | register %s | other kept %s | W number on %s | rec %s',
               imp.rows, imp.cleared, imp.separate, imp.matched, imp.duplicates, again.cleared, again.duplicates, again.matched, refs, paid_x, numbers,
               qimp.matched, qimp.cleared, qimp.separate, q_refs, q_numbers, left(retired, 40), doubles, left(short_reason, 30), w1.withdrawn, w2.withdrawn,
               w2.ledger_reversed, w2.remaining, reg, kept_other, w_number, rec));
END $$;
-- ── V498 (codes). A student as seen on AWS: the first semester paid (₦156,338) but recorded under the old portal's item code
--          "10048 (legacy)", so not counted; the GST fee and admission checking on record under their names and again under their
--          codes (10144, 10137) and the GST fee once more under an older label ("GST FEES (legacy)"); a POST UTME application
--          under 10046; a code the list does not name; and the second semester recorded again by the retired Payment History
--          Upload, dated with the day of the upload. The codes loaded, the import reads a code as its item; put right: school fees
--          and the application renamed (school fees count), the three repeats withdrawn, the unknown code left; the retired
--          door's row found by the day its payment number carries. The coded school fees and GST fee were posted to
--          the ledger first: both journals reversed and freed, the renamed record left for the sync to post under its item, once.
--          The block undoes its writes ──
DO $$
DECLARE who uuid := gen_random_uuid(); m uuid := gen_random_uuid(); nn uuid := gen_random_uuid(); ses text := '9987/9988'; pa text;
        mb text := 'MOAUM-LEG-MOAUMCHK879807-9987-9988'; nb text := 'MOAUM-LEG-MOAUMCHK879808-9987-9988';
        loaded int; acts text; first record; again_left int; m_refs text; paid_m numeric; corrected text; withdrawn text; n_ref text;
        ph text; no_actor text; msg text; j1 uuid; j2 uuid; led text; rev_n int; free_s1 boolean; net numeric; kept_j boolean;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM set_config('moaum.reason', 'check V498 codes', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), ses, date '9987-10-01', date '9988-08-31') ON CONFLICT (name) DO NOTHING;
        SELECT code INTO pa FROM ref.programme WHERE NOT coalesce(archived, false) ORDER BY code LIMIT 1;
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at) VALUES
          (m, 'MOAUM/ADM/87/980007', 'MOAUM/CHK/87/9807', 'ZZCHKV498M', 'Invented', pa, 'UTME', ses, 100, 100, 'ACTIVE', now()),
          (nn, 'MOAUM/ADM/87/980008', 'MOAUM/CHK/87/9808', 'ZZCHKV498N', 'Invented', pa, 'UTME', ses, 100, 100, 'ACTIVE', now());
        INSERT INTO finance.payment_reference (student_id, session, reference, purpose, amount, expires_at, confirmed_at, confirmed_by, channel, receipt_no, note)
        SELECT m, ses, mb || v.suffix, v.purpose, v.amount, v.day::timestamptz, v.day::timestamptz, who, 'Legacy', 'LEG-' || mb || v.suffix, 'Imported from the old portal'
          FROM (VALUES ('-S1-10048', '10048 (legacy) · semester 1', 156338.00, '2026-02-16'),
                       ('-S1-GST', 'GST fee ' || '9987/9988', 4000.00, '2026-02-23'),
                       ('-S1-10144', '10144 (legacy) · semester 1', 4000.00, '2026-02-23'),
                       ('-S1-GSTFEES', 'GST FEES (legacy) · semester 1', 4000.00, '2026-02-23'),
                       ('-S1-ADMISSIONCHECKING', 'ADMISSION CHECKING (legacy) · semester 1', 3000.00, '2025-12-09'),
                       ('-S1-10137', '10137 (legacy) · semester 1', 3000.00, '2025-12-09'),
                       ('-10046', '10046 (legacy)', 2000.00, '2025-10-11'),
                       ('-S1-77777', '77777 (legacy) · semester 1', 500.00, '2025-10-12'),
                       ('-S2', 'School fees (legacy) · semester 2', 67002.00, '2026-10-07')) v(suffix, purpose, amount, day);
        -- what the retired door wrote: the second semester again, its date the day of the upload, its reference the payment number
        INSERT INTO finance.payment_reference (student_id, session, reference, purpose, amount, generated_at, expires_at, confirmed_at, confirmed_by, channel, note, receipt_no)
        VALUES (m, ses, 'PR202610077059998', 'SCHOOL FEES', 67002.00, '2026-10-16', '2026-10-17', '2026-10-16', who, 'INTERSWITCH', 'Migrated payment history', 'RCT-MIGR-CHKV498M');
        -- the ledger posted two of them, as the sync posts a payment (under the other income account a code reads as)
        SELECT finance.gl_post(r.confirmed_at::date, 'Fee receipt ' || r.reference, 'AUTO', 'PAYMENT', r.reference,
                   jsonb_build_array(jsonb_build_object('account', '1010', 'debit', r.amount, 'narration', r.purpose, 'session', r.session),
                                     jsonb_build_object('account', finance.gl_income_account(finance.payment_category(r.purpose)), 'credit', r.amount,
                                                        'narration', r.purpose, 'session', r.session)))
          INTO j1 FROM finance.payment_reference r WHERE r.reference = mb || '-S1-10048';
        SELECT finance.gl_post(r.confirmed_at::date, 'Fee receipt ' || r.reference, 'AUTO', 'PAYMENT', r.reference,
                   jsonb_build_array(jsonb_build_object('account', '1010', 'debit', r.amount, 'narration', r.purpose, 'session', r.session),
                                     jsonb_build_object('account', finance.gl_income_account(finance.payment_category(r.purpose)), 'credit', r.amount,
                                                        'narration', r.purpose, 'session', r.session)))
          INTO j2 FROM finance.payment_reference r WHERE r.reference = mb || '-S1-10144';
        -- refused without a person; then the code list from the export's payment_type sheet
        PERFORM set_config('moaum.actor_id', '', true);
        BEGIN PERFORM finance.legacy_item_codes_set('[{"code": "10048", "description": "SCHOOL FEES"}]'::jsonb);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS no_actor = MESSAGE_TEXT; END;
        PERFORM set_config('moaum.actor_id', who::text, true);
        loaded := finance.legacy_item_codes_set('[{"pcode": 10048, "description": "SCHOOL FEES", "school": "S001"}, {"pcode": 10144, "description": "GST FEES"},
                                                  {"pcode": 10137, "description": "ADMISSION CHECKING"}, {"pcode": 10046, "description": "POST UTME APPLICATION"},
                                                  {"pcode": "", "description": "nothing"}]'::jsonb);
        acts := (SELECT string_agg(replace(x.reference, mb, '') || '>' || x.action || coalesce('>' || replace(x.target_reference, mb, ''), ''), ',' ORDER BY x.reference)
                   FROM finance.legacy_mislabelled() x WHERE x.student_id = m);
        ph := (SELECT d.double_kind || '>' || replace(d.kept_reference, mb, '') FROM finance.old_payment_doubles() d WHERE d.double_reference = 'PR202610077059998');
        SELECT * INTO first FROM finance.put_right_legacy_items('CHECK V498: recorded under the old portal''s codes');
        again_left := (SELECT count(*) FROM finance.legacy_mislabelled() x WHERE x.student_id = m AND x.action <> 'UNKNOWN_CODE');
        m_refs := (SELECT string_agg(replace(reference, mb, '') || '=' || amount::int || ':' || purpose, ',' ORDER BY reference)
                     FROM finance.payment_reference WHERE student_id = m AND reference LIKE 'MOAUM-LEG-%');
        paid_m := (SELECT sum(amount) FROM finance.payment_reference WHERE student_id = m AND purpose LIKE 'School fees%' AND confirmed_at IS NOT NULL);
        corrected := (SELECT string_agg(replace(c.old_reference, mb, '') || '>' || replace(c.new_reference, mb, '') || ':' || c.action, ',' ORDER BY c.old_reference)
                        FROM finance.legacy_item_corrected c WHERE c.old_reference LIKE mb || '%');
        withdrawn := (SELECT string_agg(replace(o.reference, mb, '') || '>' || replace(o.kept_reference, mb, ''), ',' ORDER BY o.reference)
                        FROM finance.old_payment_withdrawn o WHERE o.student_id = m AND o.double_kind = 'MISLABELLED');
        led := (SELECT string_agg(replace(split_part(g.source_ref, '#', 1), mb, '') || ':' || g.source_type || ':' || g.status, ',' ORDER BY g.source_ref)
                  FROM finance.gl_journal g WHERE g.id IN (j1, j2));
        rev_n := (SELECT count(*) FROM finance.gl_journal g WHERE g.reverses IN (j1, j2) AND g.status = 'POSTED');
        net := (SELECT sum(p.debit - p.credit) FROM finance.gl_posting p JOIN finance.gl_journal g ON g.id = p.journal_id
                 WHERE p.account <> '1010' AND (g.id IN (j1, j2) OR g.reverses IN (j1, j2)));
        free_s1 := NOT EXISTS (SELECT 1 FROM finance.gl_journal g WHERE g.source_type = 'PAYMENT' AND g.source_ref IN (mb || '-S1', mb || '-S1-10048'));
        kept_j := (SELECT c.ledger_journal = j1 AND c.reversal_journal IS NOT NULL FROM finance.legacy_item_corrected c WHERE c.old_reference = mb || '-S1-10048')
                  AND (SELECT o.ledger_journal = j2 AND o.reversal_journal IS NOT NULL FROM finance.old_payment_withdrawn o WHERE o.reference = mb || '-S1-10144');
        -- an export that carries codes: the import reads 10048 as school fees
        PERFORM finance.import_legacy_payments(jsonb_build_array(
            jsonb_build_object('matno', 'MOAUM/CHK/87/9808', 'session', ses, 'semester', 'First', 'amount', '50000', 'purpose', '10048', 'paidOn', '2026-01-20', 'payref', 'PRCHKV498N01')));
        n_ref := (SELECT replace(reference, nb, '') || ':' || purpose FROM finance.payment_reference WHERE student_id = nn);
        RAISE EXCEPTION 'the V498 codes check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V498 codes check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V498: a payment recorded under the old portal''s item code is put right — school fees renamed so they count, the same payment under its name withdrawn, an unknown code left — its ledger journal reversed and freed so the sync posts it under its item once, the import reads a code as its item, and the retired door''s row dated with the upload day is found by its payment number''s day',
        coalesce(no_actor LIKE 'LEGACY_CODES_ACTOR%' AND loaded = 4
                 AND acts = '-10046>RENAME>-POSTUTMEAPPLICATION,-S1-10048>RENAME>-S1,-S1-10137>DOUBLE>-S1-ADMISSIONCHECKING,-S1-10144>DOUBLE>-S1-GST,-S1-77777>UNKNOWN_CODE,-S1-GSTFEES>DOUBLE>-S1-GST'
                 AND ph = 'PAYMENT_HISTORY>-S2'
                 AND first.renamed = 2 AND first.relabelled = 0 AND first.withdrawn = 3 AND first.ledger_reversed = 2 AND first.unknown_codes >= 1 AND again_left = 0
                 AND led = '-S1-10048:PAYMENT_CORRECTED:REVERSED,-S1-10144:PAYMENT_WITHDRAWN:REVERSED' AND rev_n = 2 AND net = 0 AND free_s1 AND kept_j
                 AND m_refs = '-POSTUTMEAPPLICATION=2000:POST UTME APPLICATION (legacy),-S1=156338:School fees (legacy) · semester 1,-S1-77777=500:77777 (legacy) · semester 1,-S1-ADMISSIONCHECKING=3000:ADMISSION CHECKING (legacy) · semester 1,-S1-GST=4000:GST fee 9987/9988,-S2=67002:School fees (legacy) · semester 2'
                 AND paid_m = 223340
                 AND corrected = '-10046>-POSTUTMEAPPLICATION:RENAME,-S1-10048>-S1:RENAME'
                 AND withdrawn = '-S1-10137>-S1-ADMISSIONCHECKING,-S1-10144>-S1-GST,-S1-GSTFEES>-S1-GST'
                 AND n_ref = '-S1:School fees (legacy) · semester 1', false),
        format('no actor %s | codes %s | actions %s | retired door %s | put right %s renamed, %s relabelled, %s withdrawn, %s reversed, %s unknown, %s left | records %s | paid %s | corrected %s | withdrawn %s | import of a code %s | ledger %s, %s reversals, net %s, free %s, kept %s',
               left(no_actor, 30), loaded, acts, ph, first.renamed, first.relabelled, first.withdrawn, first.ledger_reversed, first.unknown_codes, again_left, m_refs, paid_m, corrected, withdrawn, n_ref,
               led, rev_n, net, free_s1, kept_j));
END $$;
-- ── V500. ICT Support: every agent in service resets a student's password and progresses or corrects a student's level — the
--    programme's levels only, the next one for a progression, never for a student not in study, a merged record or a postgraduate
--    progression; a stale screen refused, a second click doing nothing; on the level history with the session, never touching the
--    registration; only ICT Support's offices; the ledger takes the two level acts ──
DO $$
DECLARE S text := '9500/9501'; pa text := 'C00023'; pg text; fin int; agent uuid := gen_random_uuid();
        stu uuid := gen_random_uuid(); wd uuid := gen_random_uuid(); pgs uuid := gen_random_uuid(); reg uuid := gen_random_uuid();
        base text[]; caps text[]; act_def text; opts jsonb; pg_opts jsonb; r1 jsonb; r2 jsonb; r3 jsonb; hist text; reg_after text; lvl int;
        e_outside text; e_stale text; e_office text; e_status text; e_pg text; e_short text; msg text;
BEGIN
  BEGIN
    PERFORM set_config('moaum.reason', 'CHECK V500', true);
    PERFORM set_config('moaum.actor_id', agent::text, true);
    PERFORM set_config('moaum.actor_office', 'registrar', true);
    base := helpdesk.agent_baseline();
    caps := helpdesk.support_capabilities();
    SELECT pg_get_constraintdef(oid) INTO act_def FROM pg_constraint WHERE conname = 'ck_hd_sa_action';
    INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9500-10-01', date '9501-08-31') ON CONFLICT (name) DO NOTHING;
    fin := finance.final_level(pa);
    SELECT code INTO pg FROM ref.programme WHERE category = 'POST GRADUATE' ORDER BY code LIMIT 1;
    INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at) VALUES
        (stu, 'MOAUM/ADM/50/500001', 'MOAUM/CHK/50/5001', 'ZZV500', 'Level', pa, 'UTME', S, 100, 100, 'ACTIVE', now()),
        (wd, 'MOAUM/ADM/50/500002', 'MOAUM/CHK/50/5002', 'ZZV500', 'Withdrawn', pa, 'UTME', S, 100, 100, 'WITHDRAWN', now());
    IF pg IS NOT NULL THEN
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (pgs, 'MOAUM/ADM/50/500003', 'MOAUM/CHK/50/5003', 'ZZV500', 'Postgraduate', pg, 'POSTGRADUATE', S, people.pg_level_of(pg), people.pg_level_of(pg), 'ACTIVE', now());
        pg_opts := people.level_options(pgs);
    END IF;
    INSERT INTO registration.course_registration (id, student_id, session, semester, level, status) VALUES (reg, stu, S, 1, 100, 'DRAFT');
    opts := people.level_options(stu);
    -- another office is refused: the level fix of the Registry is apply_level_corrections, this is the support desk's
    BEGIN PERFORM people.support_set_level(stu, 'PROGRESS', NULL, 100, 'CHECK V500: progressed', S, 1, NULL); e_office := 'accepted';
    EXCEPTION WHEN insufficient_privilege THEN e_office := split_part(SQLERRM, ':', 1); END;
    PERFORM set_config('moaum.actor_office', 'ictagent', true);
    BEGIN PERFORM people.support_set_level(stu, 'PROGRESS', NULL, 100, 'short', S, 1, NULL); e_short := 'accepted';
    EXCEPTION WHEN check_violation THEN e_short := split_part(SQLERRM, ':', 1); END;
    r1 := people.support_set_level(stu, 'PROGRESS', NULL, 100, 'CHECK V500: left at 100 after promotion', S, 1, NULL);
    r2 := people.support_set_level(stu, 'PROGRESS', NULL, 100, 'CHECK V500: left at 100 after promotion', S, 1, NULL);
    BEGIN PERFORM people.support_set_level(stu, 'CORRECTION', 700, 200, 'CHECK V500: outside the programme', S, 1, NULL); e_outside := 'accepted';
    EXCEPTION WHEN check_violation THEN e_outside := split_part(SQLERRM, ':', 1); END;
    BEGIN PERFORM people.support_set_level(stu, 'CORRECTION', fin, 100, 'CHECK V500: a stale screen', S, 1, NULL); e_stale := 'accepted';
    EXCEPTION WHEN check_violation THEN e_stale := split_part(SQLERRM, ':', 1); END;
    r3 := people.support_set_level(stu, 'CORRECTION', fin, 200, 'CHECK V500: recorded at the wrong level', S, 1, NULL);
    BEGIN PERFORM people.support_set_level(wd, 'PROGRESS', NULL, 100, 'CHECK V500: not in study', S, 1, NULL); e_status := 'accepted';
    EXCEPTION WHEN check_violation THEN e_status := split_part(SQLERRM, ':', 1); END;
    IF pg IS NOT NULL THEN
        BEGIN PERFORM people.support_set_level(pgs, 'PROGRESS', NULL, people.pg_level_of(pg), 'CHECK V500: postgraduate', S, 1, NULL); e_pg := 'accepted';
        EXCEPTION WHEN check_violation THEN e_pg := split_part(SQLERRM, ':', 1); END;
    END IF;
    SELECT current_level INTO lvl FROM people.student WHERE id = stu;
    SELECT string_agg(previous_level || '>' || new_level || ':' || rule || ':' || session || '/' || semester || ':' || actor_office, ',' ORDER BY decided_at, previous_level)
      INTO hist FROM people.cohort_decision WHERE student_id = stu;
    SELECT level || '/' || status INTO reg_after FROM registration.course_registration WHERE id = reg;
    RAISE EXCEPTION 'CHECK_V500_UNDONE' USING ERRCODE = 'P0001';
  EXCEPTION WHEN raise_exception THEN
    GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
    IF msg <> 'CHECK_V500_UNDONE' THEN RAISE; END IF;
  END;
    PERFORM pg_temp.assert('V500: every ICT support agent in service holds the password reset, the level progression and correction and the two histories, not the whole support audit, the exports or record edits; the ledger takes LEVEL_PROGRESSED and LEVEL_CORRECTED in ACADEMIC_LEVEL',
        coalesce(base @> ARRAY['RESET_PASSWORD', 'PROGRESS_LEVEL', 'CORRECT_LEVEL', 'VIEW_LEVEL_HISTORY', 'VIEW_RESET_HISTORY', 'VIEW_STUDENT', 'MANAGE_REGISTRATION']
            AND NOT base && ARRAY['VIEW_SUPPORT_AUDIT', 'EXPORT_STUDENTS', 'EDIT_CONTACT', 'EDIT_PERSONAL', 'OVERRIDE_REGISTRATION']
            AND caps @> base AND act_def LIKE '%LEVEL_PROGRESSED%' AND act_def LIKE '%LEVEL_CORRECTED%' AND act_def LIKE '%PAYMENT_RECEIPT_REPORTED%'
            AND helpdesk.support_module('LEVEL_CORRECTED') = 'ACADEMIC_LEVEL' AND helpdesk.support_module('PASSWORD_RESET') = 'AUTHENTICATION', false),
        format('baseline %s | capabilities hold it %s | action list %s | module %s', base, caps @> base, act_def LIKE '%LEVEL_CORRECTED%', helpdesk.support_module('LEVEL_CORRECTED')));
    PERFORM pg_temp.assert('V500: a level is progressed to the programme''s next level or corrected to another of its levels by ICT Support alone, with a reason; never outside the programme, from a stale screen, for a student not in study or a postgraduate progression; a second click does nothing; on the level history with the session; the registration left as it was',
        coalesce((opts->'levels') = (SELECT to_jsonb(array_agg(l ORDER BY l)) FROM generate_series(100, fin, 100) l) AND (opts->>'nextLevel')::int = 200
            AND e_office = 'LEVEL_SUPPORT_OFFICE' AND e_short = 'LEVEL_REASON'
            AND r1->>'newLevel' = '200' AND NOT (r1->>'alreadyDone')::boolean AND (r2->>'alreadyDone')::boolean AND r2->>'decisionId' = r1->>'decisionId'
            AND e_outside = 'LEVEL_NOT_IN_PROGRAMME' AND e_stale = 'LEVEL_CHANGED' AND r3->>'newLevel' = fin::text AND lvl = fin AND e_status = 'LEVEL_STATUS'
            AND (pg IS NULL OR (e_pg = 'LEVEL_PG_PROGRESSION' AND jsonb_array_length(pg_opts->'levels') = 1))
            AND hist = '100>200:LEVEL_PROGRESS:' || S || '/1:ictagent,200>' || fin || ':LEVEL_CORRECTION:' || S || '/1:ictagent'
            AND reg_after = '100/DRAFT', false),
        format('levels %s next %s | office %s short %s | first %s again %s | outside %s stale %s corrected %s now %s | withdrawn %s | pg %s %s | history %s | registration %s',
               opts->'levels', opts->>'nextLevel', e_office, e_short, r1, r2, e_outside, e_stale, r3->>'newLevel', lvl, e_status, e_pg, pg_opts->'levels', hist, reg_after));
END $$;


-- ── V501: the examination card's own rule ──
-- A student whose registration is approved and whose fees are paid has the examination card, with every course registered —
-- departmental, GST and EPS — while the GST & EPS permit beside it carries only the GST and EPS ones; a registration not approved,
-- one with no course, or fees unpaid has no card, each with its reason. The block undoes its writes.
DO $$
DECLARE ses text := '2394/2395'; sch uuid := gen_random_uuid(); st uuid := gen_random_uuid(); dr uuid := gen_random_uuid(); reg uuid := gen_random_uuid(); dreg uuid := gen_random_uuid();
        prog text; dept text; unpaid jsonb; paid jsonb; draft jsonb; empty jsonb; permit_n int; codes text; ref text; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', '00000000-0000-0000-0000-000000000000', true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM set_config('moaum.reason', 'check V501', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), ses, DATE '2394-10-01', DATE '2395-08-31');
        SELECT p.code, p.dept_code INTO prog, dept FROM ref.programme p WHERE p.category = 'UNDER GRADUATE' AND NOT coalesce(p.archived, false) AND p.dept_code IS NOT NULL ORDER BY p.code LIMIT 1;
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status) VALUES
            (st, 'MOAUM/ADM/94/950101', 'CHECKV501', 'Card', prog, 'UTME', ses, 100, 100, 'ADMITTED'),
            (dr, 'MOAUM/ADM/94/950102', 'CHECKV501', 'Draft', prog, 'UTME', ses, 100, 100, 'ADMITTED');
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state) VALUES
            ('GST 391', 'Check Card English', 2, 1, 100, dept, 'GST', 'LIVE'), ('EPS 391', 'Check Card Enterprise', 2, 1, 100, dept, 'GST', 'LIVE'),
            ('ZQC 101', 'Check Card Departmental', 3, 1, 100, dept, 'Core', 'LIVE');
        INSERT INTO catalogue.offering (id, course_code, session, semester) SELECT gen_random_uuid(), c, ses, 1 FROM unnest(ARRAY['GST 391', 'EPS 391', 'ZQC 101']) c;
        INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, submitted_at, approved_at) VALUES
            (reg, st, ses, 1, 100, 'APPROVED', now(), now()), (dreg, dr, ses, 1, 100, 'SUBMITTED', now(), NULL);
        INSERT INTO registration.entry (registration_id, offering_id, units, entry_type, status)
        SELECT reg, o.id, c.units, 'CURRENT', 'APPROVED' FROM catalogue.offering o JOIN catalogue.course c ON c.code = o.course_code
         WHERE o.session = ses AND o.course_code IN ('GST 391', 'EPS 391', 'ZQC 101');
        INSERT INTO registration.entry (registration_id, offering_id, units, entry_type, status)
        SELECT dreg, o.id, 3, 'CURRENT', 'REGISTERED' FROM catalogue.offering o WHERE o.session = ses AND o.course_code = 'ZQC 101';
        INSERT INTO finance.fee_schedule (session, item, amount, level, programme_code) VALUES (ses, 'School fees (check V501)', 50000, 100, prog);
        -- a clearance scheme in force for the reading (the examination cleared on the first instalment), where the suite has none
        IF policy.in_force('clearance', 'UNIVERSITY', current_date) IS NULL THEN
            INSERT INTO policy.version (id, kind, scope, validity, instrument, decided_by)
            VALUES (sch, 'clearance', 'UNIVERSITY', daterange(current_date - 1, NULL), 'CHECK V501', 'bursar');
            INSERT INTO policy.clearance_scheme VALUES (sch, true);
            INSERT INTO policy.clearance_rule SELECT sch, p.code, CASE p.code WHEN 'HOSTEL' THEN 'NEVER_GATED' ELSE 'INSTALMENT_1' END FROM ref.clearance_purpose p;
        END IF;
        unpaid := registration.exam_card_state(st, ses, 1);
        ref := finance.new_purpose_reference(st, ses, 50000, 'School fees ' || ses);
        PERFORM finance.confirm_payment(ref, 'BANK_BRANCH', 'teller for check V501');
        paid := registration.exam_card_state(st, ses, 1);
        codes := (SELECT string_agg(x->>'course_code', ',' ORDER BY x->>'course_code') FROM jsonb_array_elements(paid->'courses') x);
        permit_n := jsonb_array_length(registration.gst_eps_permit_state(st, ses, 1)->'courses');
        draft := registration.exam_card_state(dr, ses, 1);
        DELETE FROM registration.entry WHERE registration_id = reg;
        empty := registration.exam_card_state(st, ses, 1);
        RAISE EXCEPTION 'the V501 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V501 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V501: the examination card carries every registered course for an approved, paid registration (the GST & EPS permit only its GST and EPS ones); unpaid, not approved or empty has no card, with the reason',
        coalesce(unpaid->>'code' = 'EXAM_CARD_NOT_CLEARED' AND (paid->>'available')::boolean AND (paid->>'count')::int = 3 AND (paid->>'units')::int = 7
                 AND (paid->>'gstEpsCount')::int = 2 AND codes = 'EPS 391,GST 391,ZQC 101' AND permit_n = 2
                 AND draft->>'code' = 'EXAM_CARD_NOT_APPROVED' AND empty->>'code' = 'EXAM_CARD_NO_COURSES', false),
        format('unpaid %s | paid %s %s/%s gst %s [%s] permit %s | draft %s | empty %s', unpaid->>'code', paid->>'available', paid->>'count', paid->>'units',
               paid->>'gstEpsCount', codes, permit_n, draft->>'code', empty->>'code'));
END $$;


-- ── V503: the SIWES (attachment) semester ──
-- Where the SIWES course is the programme's only required course in the semester, the load is exactly that course's units
-- (minimum and maximum, no probation ceiling), and the other semester keeps the curriculum's minimum; where a required course sits
-- beside it (a practicum), the semester is an ordinary one with the curriculum's minimum. The block undoes its writes.
DO $$
DECLARE ses text := '2395/2396'; st uuid := gen_random_uuid(); prog text; dept text; s2 record; s1 record; lim2 record; prac record; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', '00000000-0000-0000-0000-000000000000', true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        PERFORM set_config('moaum.reason', 'check V503', true);
        SELECT p.code, p.dept_code INTO prog, dept FROM ref.programme p
         WHERE p.category = 'UNDER GRADUATE' AND NOT coalesce(p.archived, false) AND p.dept_code IS NOT NULL
           AND NOT EXISTS (SELECT 1 FROM catalogue.course_offer o WHERE o.programme_code = p.code AND o.level = 600)
         ORDER BY p.code LIMIT 1;
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status)
        VALUES (st, 'MOAUM/ADM/95/950301', 'CHECKV503', 'Siwes', prog, 'UTME', '2020/2021', 100, 600, 'ADMITTED');
        UPDATE people.student SET curriculum_version = 'CCMAS' WHERE id = st;
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state, industrial_training)
        VALUES ('ZQW 601', 'Check Industrial Training', 6, 2, 600, dept, 'Core', 'LIVE', true);
        INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES ('ZQW 601', prog, 600, 'Core');
        SELECT * INTO s2 FROM registration.unit_rule(st, 600, ses, 2);
        SELECT * INTO s1 FROM registration.unit_rule(st, 600, ses, 1);
        SELECT * INTO lim2 FROM registration.unit_limit(st, 600, ses, 2);
        -- a required course beside it: a practicum semester, an ordinary one
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state)
        VALUES ('ZQW 602', 'Check Required Course', 3, 2, 600, dept, 'Core', 'LIVE');
        INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES ('ZQW 602', prog, 600, 'Core');
        SELECT * INTO prac FROM registration.unit_rule(st, 600, ses, 2);
        RAISE EXCEPTION 'the V503 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V503 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V503: the attachment semester (SIWES alone) binds exactly the SIWES course''s units; the other semester, and a practicum beside required courses, keep the curriculum''s minimum',
        coalesce(s2.basis = 'SIWES' AND s2.min_units = 6 AND s2.max_units = 6 AND s2.probation_max_units IS NULL AND lim2.applies_to = 'SIWES (industrial training)'
                 AND s1.basis = 'CURRICULUM' AND s1.min_units = 15
                 AND prac.basis = 'CURRICULUM' AND prac.min_units = 15 AND prac.max_units = (SELECT max_units FROM policy.level_limit WHERE level = 600), false),
        format('attachment %s %s-%s probation %s (%s) | other semester %s %s | practicum %s %s-%s', s2.basis, s2.min_units, s2.max_units, s2.probation_max_units,
               lim2.applies_to, s1.basis, s1.min_units, prac.basis, prac.min_units, prac.max_units));
END $$;
-- ── V504: flexible course registration ──
-- The University's order of a registration's courses is carry-over (and deferred), GST, core, elective, from the entry's type and
-- the programme's own setup (course_offer.basis) — a course the programme takes as core is core though its department offers it
-- as an elective.
DO $$
BEGIN
    PERFORM pg_temp.assert('V504: a registration''s courses are ordered carry-over, GST, core, elective, the programme''s basis deciding core or elective',
        coalesce(registration.entry_category('CARRYOVER', 'Core', NULL) = 'CARRY_OVER' AND registration.entry_category('DEFERRED', 'Core', NULL) = 'CARRY_OVER'
                 AND registration.entry_category(NULL, 'Core', 'Carryover') = 'CARRY_OVER' AND registration.entry_category('CURRENT', 'GST', NULL) = 'GST'
                 AND registration.entry_category(NULL, 'Core', 'GST') = 'GST' AND registration.entry_category('ELECTIVE', 'Elective', 'Core') = 'CORE'
                 AND registration.entry_category('CURRENT', 'Core', 'Elective') = 'ELECTIVE' AND registration.entry_category('ELECTIVE', 'Core', NULL) = 'ELECTIVE'
                 AND registration.entry_category(NULL, 'Elective', NULL) = 'ELECTIVE' AND registration.entry_category('BORROWED', 'Core', NULL) = 'CORE'
                 AND registration.entry_rank('CARRYOVER', 'Core', NULL) < registration.entry_rank('GST', 'GST', NULL)
                 AND registration.entry_rank('GST', 'GST', NULL) < registration.entry_rank('CURRENT', 'Core', 'Core')
                 AND registration.entry_rank('CURRENT', 'Core', 'Core') < registration.entry_rank('ELECTIVE', 'Elective', 'Elective'), false),
        'registration.entry_category / entry_rank');
END $$;

-- A student adds a course beside the recommended list only where the engine allows it: a course of the programme at a lower level
-- (added, kept on saving, approved automatically), never a higher one while the rule is off, never one not part of the programme,
-- one not offered in the semester (named with the semester it runs in), one already passed, one whose result is pending (never a
-- carry-over), and never twice; a University-wide GST course is a GST course; with the rule off, only the recommended list. The
-- block undoes its writes.
DO $$
DECLARE ses text := '2396/2397'; st uuid := gen_random_uuid(); prog text; dept text; other_dept text; reg uuid; msg text;
        o101 uuid; o201 uuid; o301 uuid; ogst uuid; ooth uuid;
        c101 record; c301 record; c102 record; cpassed record; cawait record; ccarry record; cgst record; coth record; coff record; cmenu record;
        dup text; kept int; dropped int; approved text; held text; menu_order text; reg_order text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', '00000000-0000-0000-0000-000000000000', true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        PERFORM set_config('moaum.reason', 'check V504', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), ses, DATE '2396-10-01', DATE '2397-08-31');
        SELECT p.code, p.dept_code INTO prog, dept FROM ref.programme p
         WHERE p.category = 'UNDER GRADUATE' AND NOT coalesce(p.archived, false) AND p.dept_code IS NOT NULL
           AND registration.siwes_units(p.code, 200, 1) IS NULL ORDER BY p.code LIMIT 1;
        SELECT d.code INTO other_dept FROM ref.department d WHERE d.code <> dept ORDER BY d.code LIMIT 1;
        PERFORM registration.set_flex_policy(true, 'PROGRAMME', false, 'check V504: the default rule');
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status) VALUES
            (st, 'MOAUM/ADM/96/960101', 'CHECKV504', 'Flexible', prog, 'UTME', ses, 200, 200, 'ADMITTED');
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state, general_office) VALUES
            ('ZQV 101', 'Check Flex Lower', 2, 1, 100, dept, 'Core', 'LIVE', NULL), ('ZQV 102', 'Check Flex Second Semester', 2, 2, 100, dept, 'Core', 'LIVE', NULL),
            ('ZQV 103', 'Check Flex Passed', 2, 1, 100, dept, 'Core', 'LIVE', NULL), ('ZQV 104', 'Check Flex Pending', 2, 1, 100, dept, 'Core', 'LIVE', NULL),
            ('ZQV 105', 'Check Flex Carry', 2, 1, 100, dept, 'Core', 'LIVE', NULL),
            ('ZQV 201', 'Check Flex Current', 3, 1, 200, dept, 'Core', 'LIVE', NULL), ('ZQV 211', 'Check Flex Elective', 2, 1, 200, dept, 'Elective', 'LIVE', NULL),
            ('ZQV 301', 'Check Flex Higher', 3, 1, 300, dept, 'Core', 'LIVE', NULL),
            ('GST 396', 'Check Flex University GST', 2, 1, 200, dept, 'GST', 'LIVE', 'GST'), ('ZQX 201', 'Check Flex Elsewhere', 2, 1, 200, other_dept, 'Core', 'LIVE', NULL);
        INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES
            ('ZQV 101', prog, 100, 'Core'), ('ZQV 102', prog, 100, 'Core'), ('ZQV 103', prog, 100, 'Core'), ('ZQV 104', prog, 100, 'Core'), ('ZQV 105', prog, 100, 'Core'),
            ('ZQV 201', prog, 200, 'Core'), ('ZQV 211', prog, 200, 'Elective'), ('ZQV 301', prog, 300, 'Core');
        INSERT INTO catalogue.offering (id, course_code, session, semester)
        SELECT gen_random_uuid(), c, ses, CASE c WHEN 'ZQV 102' THEN 2 ELSE 1 END
          FROM unnest(ARRAY['ZQV 101', 'ZQV 102', 'ZQV 103', 'ZQV 104', 'ZQV 105', 'ZQV 201', 'ZQV 211', 'ZQV 301', 'GST 396', 'ZQX 201']) c;
        SELECT id INTO o101 FROM catalogue.offering WHERE course_code = 'ZQV 101' AND session = ses;
        SELECT id INTO o201 FROM catalogue.offering WHERE course_code = 'ZQV 201' AND session = ses;
        SELECT id INTO o301 FROM catalogue.offering WHERE course_code = 'ZQV 301' AND session = ses;
        SELECT id INTO ogst FROM catalogue.offering WHERE course_code = 'GST 396' AND session = ses;
        SELECT id INTO ooth FROM catalogue.offering WHERE course_code = 'ZQX 201' AND session = ses;
        -- the record as course_check reads it: one passed, one awaiting its result, one owed
        SELECT * INTO c101 FROM registration.course_check(st, ses, 1, 'ZQV 101', '{ZQV 103}', '{ZQV 104}', '{ZQV 105}', '{}');
        SELECT * INTO c301 FROM registration.course_check(st, ses, 1, 'ZQV 301', '{ZQV 103}', '{ZQV 104}', '{ZQV 105}', '{}');
        SELECT * INTO c102 FROM registration.course_check(st, ses, 1, 'ZQV 102', '{ZQV 103}', '{ZQV 104}', '{ZQV 105}', '{}');
        SELECT * INTO cpassed FROM registration.course_check(st, ses, 1, 'ZQV 103', '{ZQV 103}', '{ZQV 104}', '{ZQV 105}', '{}');
        SELECT * INTO cawait FROM registration.course_check(st, ses, 1, 'ZQV 104', '{ZQV 103}', '{ZQV 104}', '{ZQV 105}', '{}');
        SELECT * INTO ccarry FROM registration.course_check(st, ses, 1, 'ZQV 105', '{ZQV 103}', '{ZQV 104}', '{ZQV 105}', '{}');
        SELECT * INTO cgst FROM registration.course_check(st, ses, 1, 'GST 396', '{}', '{}', '{}', '{}');
        SELECT * INTO coth FROM registration.course_check(st, ses, 1, 'ZQX 201', '{}', '{}', '{}', '{}');
        SELECT * INTO cmenu FROM registration.course_check(st, ses, 1, 'ZQV 211', '{}', '{}', '{}', '{}');
        -- the student adds the lower-level course: on the draft, as the programme's at another level; a second time is refused
        PERFORM registration.student_add_other(st, ses, 1, o101);
        SELECT id INTO reg FROM registration.course_registration WHERE student_id = st AND session = ses AND semester = 1;
        BEGIN
            PERFORM registration.student_add_other(st, ses, 1, o101);
        EXCEPTION WHEN check_violation THEN dup := split_part(SQLERRM, ':', 1);
        END;
        BEGIN
            PERFORM registration.student_add_other(st, ses, 1, o301);
        EXCEPTION WHEN check_violation THEN held := split_part(SQLERRM, ':', 1);
        END;
        -- saving keeps the added course when the selection names it, and lets it go when not
        PERFORM registration.student_choose(reg, ARRAY[o201, o101]);
        kept := (SELECT count(*) FROM registration.entry WHERE registration_id = reg AND offering_id = o101 AND student_added_at IS NOT NULL AND added_as = 'PROGRAMME_OTHER_LEVEL');
        reg_order := (SELECT string_agg(c.code, ',' ORDER BY registration.entry_rank(e.entry_type, c.kind, co.basis), c.code)
                        FROM registration.entry e JOIN catalogue.offering o ON o.id = e.offering_id JOIN catalogue.course c ON c.code = o.course_code
                        LEFT JOIN catalogue.course_offer co ON co.course_code = c.code AND co.programme_code = prog AND co.level = 200
                       WHERE e.registration_id = reg);
        -- approved automatically: the added course passes the check again
        UPDATE registration.course_registration SET status = 'SUBMITTED', submitted_at = now() WHERE id = reg;
        approved := registration.auto_approve(reg);
        UPDATE registration.course_registration SET status = 'DRAFT', approved_at = NULL, approval_mode = NULL WHERE id = reg;
        UPDATE registration.entry SET status = 'REGISTERED' WHERE registration_id = reg;
        PERFORM registration.student_choose(reg, ARRAY[o201]);
        dropped := (SELECT count(*) FROM registration.entry WHERE registration_id = reg AND offering_id = o101);
        menu_order := (SELECT string_agg(m.course_code, ',') FROM registration.student_menu(st, ses, 1) m WHERE m.course_code IN ('ZQV 201', 'ZQV 211'));
        -- the rule off: a course beside the list is refused, the list's own course is not
        PERFORM registration.set_flex_policy(false, 'PROGRAMME', false, 'check V504: other courses closed');
        SELECT * INTO coff FROM registration.course_check(st, ses, 1, 'ZQV 101', '{}', '{}', '{}', '{}');
        SELECT * INTO cmenu FROM registration.course_check(st, ses, 1, 'ZQV 211', '{}', '{}', '{}', '{}');
        RAISE EXCEPTION 'the V504 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V504 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V504: a student adds a course beside the list only where the engine allows it — a lower level of the programme (kept, approved), never a higher one, another programme''s, one off this semester, passed, pending or twice; a University GST course is GST; the rule off holds the list',
        coalesce(c101.refusal IS NULL AND c101.category = 'CORE' AND c101.added_as = 'PROGRAMME_OTHER_LEVEL' AND c101.offering_id = o101
                 AND c301.refusal LIKE 'REG_HIGHER_LEVEL:%' AND c102.refusal LIKE 'REG_NOT_OFFERED_SEMESTER:%second semester%'
                 AND cpassed.refusal LIKE 'REG_ALREADY_PASSED:%' AND cawait.refusal LIKE 'REG_RESULT_AWAITED:%'
                 AND ccarry.refusal IS NULL AND ccarry.category = 'CARRY_OVER'
                 AND cgst.refusal IS NULL AND cgst.category = 'GST' AND cgst.added_as = 'UNIVERSITY_GST' AND coth.refusal LIKE 'REG_NOT_AVAILABLE:%'
                 AND dup = 'REG_ALREADY_ADDED' AND held = 'REG_HIGHER_LEVEL' AND kept = 1 AND approved = 'approved' AND dropped = 0
                 AND reg_order = 'ZQV 101,ZQV 201' AND menu_order = 'ZQV 201,ZQV 211'
                 AND coff.refusal LIKE 'REG_OTHER_COURSES_OFF:%' AND cmenu.refusal IS NULL AND cmenu.added_as IS NULL AND cmenu.category = 'ELECTIVE', false),
        format('101 %s/%s/%s | 301 %s | 102 %s | passed %s | pending %s | carry %s/%s | gst %s/%s | other %s | dup %s held %s kept %s approved %s dropped %s | order %s menu %s | off %s menu %s/%s',
               c101.category, c101.added_as, coalesce(c101.refusal, '-'), left(c301.refusal, 20), left(c102.refusal, 30), left(cpassed.refusal, 20), left(cawait.refusal, 20),
               ccarry.category, coalesce(ccarry.refusal, '-'), cgst.category, cgst.added_as, left(coth.refusal, 20), dup, held, kept, approved, dropped, reg_order, menu_order,
               left(coff.refusal, 25), cmenu.category, coalesce(cmenu.refusal, '-')));
END $$;
-- ── V502. What the retired Payment History Upload recorded, put right. A student whose payments that door recorded its own way:
--          the first semester as "SCHOOL FEES" dated the day of the upload (and posted to the ledger), the GST fee as "School
--          fees <session>", a payment Old Fees History already has, two the export does not name ("SCHOOL FEES", "GST FEES"), and
--          one a refund points at; and an Old Fees History record under a code a refund points at. The export loaded: the first
--          two taken over (their item, semester and day; the ledger posting let go), the repeat left as a double, the one a refund
--          points at left (its payment recorded beside it); the two the export does not name relabelled so they count, then
--          listed as left; the coded record a refund points at relabelled, never renamed; the export again changes nothing.
--          The block undoes its writes ──
DO $$
DECLARE who uuid := gen_random_uuid(); m uuid := gen_random_uuid(); ses text := '9985/9986'; pa text;
        mb text := 'MOAUM-LEG-MOAUMCHK859855-9985-9986'; j1 uuid; rows jsonb; first record; again record; done record;
        taken text; reg text; renamed_m boolean; led text; rev_n int; free_new boolean; mis text; dbl text; left_m text; linked_f boolean; g_purpose text;
        no_mis boolean; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM set_config('moaum.reason', 'check V502', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), ses, date '9985-10-01', date '9986-08-31') ON CONFLICT (name) DO NOTHING;
        SELECT code INTO pa FROM ref.programme WHERE NOT coalesce(archived, false) ORDER BY code LIMIT 1;
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (m, 'MOAUM/ADM/85/985501', 'MOAUM/CHK/85/9855', 'ZZCHKV502', 'Invented', pa, 'UTME', ses, 100, 100, 'ACTIVE', now());
        PERFORM finance.legacy_item_codes_set('[{"pcode": 10048, "description": "SCHOOL FEES"}]'::jsonb);
        -- what the retired door wrote (its channel and note, a receipt of its own, the day of the upload where it could not read one)
        INSERT INTO finance.payment_reference (student_id, session, reference, purpose, amount, generated_at, expires_at, confirmed_at, confirmed_by, channel, note, receipt_no)
        SELECT m, ses, v.ref, v.purpose, v.amount, v.day::timestamptz, v.day::timestamptz + interval '1 day', v.day::timestamptz, who, 'MIGRATION', 'Migrated payment history', 'RCT-CHKV502-' || v.tag
          FROM (VALUES ('PR202602100000001', 'SCHOOL FEES', 50000.00, '2026-10-16', 'A'),
                       ('PR202602230000002', 'School fees ' || '9985/9986', 4000.00, '2026-10-16', 'B'),
                       ('PR202603010000003', 'SCHOOL FEES', 20000.00, '2026-10-16', 'C'),
                       ('MIGR-CHKV502-D', 'SCHOOL FEES', 30000.00, '2026-10-16', 'D'),
                       ('PR202604040000005', 'GST FEES', 4500.00, '2026-10-16', 'E'),
                       ('PR202605050000006', 'SCHOOL FEES', 10000.00, '2026-10-16', 'F')) v(ref, purpose, amount, day, tag);
        -- Old Fees History already has the third payment, under its number; and a record under a code
        INSERT INTO finance.payment_reference (student_id, session, reference, purpose, amount, expires_at, confirmed_at, confirmed_by, channel, receipt_no, note)
        VALUES (m, ses, mb || '-S2', 'School fees (legacy) · semester 2', 20000.00, '2026-03-01', '2026-03-01', who, 'Legacy', 'LEG-' || mb || '-S2', 'Imported from the old portal · old ref PR202603010000003'),
               (m, ses, mb || '-S3-10048', '10048 (legacy) · semester 3', 7000.00, '2026-06-01', '2026-06-01', who, 'Legacy', 'LEG-' || mb || '-S3-10048', 'Imported from the old portal');
        INSERT INTO finance.legacy_payref (payref, reference, amount) VALUES ('PR202603010000003', mb || '-S2', 20000.00);
        -- a refund points at the sixth and at the coded record
        INSERT INTO finance.refund (reference, student_id, payer, reason, amount, proposed_by, source_reference)
        VALUES ('RF-CHKV502-F', m, 'ZZCHKV502', 'check V502', 1000, who, 'PR202605050000006'),
               ('RF-CHKV502-G', m, 'ZZCHKV502', 'check V502', 1000, who, mb || '-S3-10048');
        -- the ledger had posted the first as the sync posts a payment
        SELECT finance.gl_post(date '2026-10-16', 'Fee receipt PR202602100000001', 'AUTO', 'PAYMENT', 'PR202602100000001',
                   jsonb_build_array(jsonb_build_object('account', '1010', 'debit', 50000, 'narration', 'SCHOOL FEES', 'session', ses),
                                     jsonb_build_object('account', finance.gl_income_account(finance.payment_category('SCHOOL FEES')), 'credit', 50000, 'narration', 'SCHOOL FEES', 'session', ses)))
          INTO j1;

        -- the old portal's export, as Old Fees History reads it
        rows := jsonb_build_array(
            jsonb_build_object('matno', 'MOAUM/CHK/85/9855', 'session', ses, 'semester', 'First', 'amount', '50000', 'purpose', '10048', 'paidOn', '2026-02-10', 'payref', 'PR202602100000001'),
            jsonb_build_object('matno', 'MOAUM/CHK/85/9855', 'session', ses, 'semester', 'First', 'amount', '4000', 'purpose', 'GST FEES', 'paidOn', '2026-02-23', 'payref', 'PR202602230000002'),
            jsonb_build_object('matno', 'MOAUM/CHK/85/9855', 'session', ses, 'semester', 'Second', 'amount', '20000', 'purpose', 'SCHOOL FEES', 'paidOn', '2026-03-01', 'payref', 'PR202603010000003'),
            jsonb_build_object('matno', 'MOAUM/CHK/85/9855', 'session', ses, 'semester', 'Second', 'amount', '10000', 'purpose', 'SCHOOL FEES MAKE UP', 'paidOn', '2026-05-05', 'payref', 'PR202605050000006'));
        SELECT * INTO first FROM finance.import_legacy_payments(rows);
        taken := (SELECT string_agg(replace(reference, mb, '') || '=' || amount::int || ':' || purpose || ':' || channel || ':' || (confirmed_at AT TIME ZONE 'Africa/Lagos')::date
                                     || ':' || coalesce((SELECT k.payref FROM finance.legacy_payref k WHERE k.reference = p.reference), '-'), ',' ORDER BY reference COLLATE "C")
                    FROM finance.payment_reference p WHERE p.student_id = m AND p.reference LIKE mb || '-S1%');
        reg := (SELECT string_agg(c.old_reference || '>' || replace(c.new_reference, mb, ''), ',' ORDER BY c.old_reference COLLATE "C")
                  FROM finance.legacy_item_corrected c WHERE c.action = 'TAKEN_OVER' AND c.new_reference LIKE mb || '%');
        led := (SELECT g.source_type || ':' || g.status || ':' || split_part(g.source_ref, '#', 1) FROM finance.gl_journal g WHERE g.id = j1);
        rev_n := (SELECT count(*) FROM finance.gl_journal g WHERE g.reverses = j1);
        free_new := NOT EXISTS (SELECT 1 FROM finance.gl_journal g WHERE g.source_type = 'PAYMENT' AND g.source_ref IN (mb || '-S1', 'PR202602100000001'));
        dbl := (SELECT string_agg(d.double_reference || '>' || replace(d.kept_reference, mb, '') || coalesce(':' || d.linked, ''), ',' ORDER BY d.double_reference COLLATE "C")
                  FROM finance.old_payment_doubles() d WHERE d.student_id = m);
        mis := (SELECT string_agg(replace(x.reference, mb, '') || '>' || x.action || '>' || x.target_purpose, ',' ORDER BY x.reference COLLATE "C")
                  FROM finance.legacy_mislabelled() x WHERE x.student_id = m);
        linked_f := finance.payment_reference_linked('PR202605050000006', NULL);
        SELECT * INTO done FROM finance.put_right_legacy_items('CHECK V502: the retired door''s item names');
        renamed_m := EXISTS (SELECT 1 FROM finance.legacy_item_corrected c WHERE c.old_reference LIKE mb || '%' AND c.action = 'RENAME');
        no_mis := NOT EXISTS (SELECT 1 FROM finance.legacy_mislabelled() x WHERE x.student_id = m);
        g_purpose := (SELECT p.purpose FROM finance.payment_reference p WHERE p.reference = mb || '-S3-10048');
        left_m := (SELECT string_agg(l.reference || ':' || l.counts_as || ':' || l.purpose || ':' || coalesce(l.number_day::text, '-'), ',' ORDER BY l.reference COLLATE "C")
                     FROM finance.payment_history_left() l WHERE l.student_id = m);
        SELECT * INTO again FROM finance.import_legacy_payments(rows);
        RAISE EXCEPTION 'the V502 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V502 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V502: Old Fees History takes over what the retired Payment History Upload recorded under the payment number (its item, semester and day; the ledger posting let go), leaves a repeat to the doubles and a record a refund points at alone, relabels what the export does not name so it counts, and never renames a record something points at',
        coalesce(first.taken_over = 2 AND first.duplicates = 1 AND first.cleared = 1 AND again.taken_over = 0 AND again.duplicates = 4 AND again.cleared = 0
                 AND taken = '-S1=50000:School fees (legacy) · semester 1:Legacy:2026-02-10:PR202602100000001,-S1-GST=4000:GST fee 9985/9986:Legacy:2026-02-23:PR202602230000002'
                 AND reg = 'PR202602100000001>-S1,PR202602230000002>-S1-GST'
                 AND led = 'PAYMENT_CORRECTED:REVERSED:PR202602100000001' AND rev_n = 1 AND free_new
                 AND dbl = 'PR202603010000003>-S2,PR202605050000006>-S2-PR202605050000006:REFUND'
                 AND mis = 'MIGR-CHKV502-D>RELABEL>School fees 9985/9986,-S3-10048>RELABEL>School fees (legacy) · semester 3,PR202604040000005>RELABEL>GST fee 9985/9986'
                 AND linked_f AND done.relabelled >= 3 AND NOT renamed_m AND no_mis AND g_purpose = 'School fees (legacy) · semester 3'
                 AND left_m = 'MIGR-CHKV502-D:SCHOOL_FEES:School fees 9985/9986:-,PR202604040000005:GST:GST fee 9985/9986:2026-04-04', false),
        format('import %s taken, %s duplicates, %s cleared; again %s taken, %s duplicates, %s cleared | taken %s | register %s | ledger %s, %s reversals, free %s | doubles %s | to put right %s | linked %s | put right %s relabelled, renamed here %s, none left %s, coded %s | left %s',
               first.taken_over, first.duplicates, first.cleared, again.taken_over, again.duplicates, again.cleared, taken, reg, led, rev_n, free_new, dbl, mis,
               linked_f, done.relabelled, renamed_m, no_mis, g_purpose, left_m));
END $$;

-- ── V505: examination cards withheld, registrations below the minimum decided, students told of a new minimum ──
-- The withheld list gives exactly the card's own code for each approved registration it lists (unpaid: not cleared; no course);
-- a paid one is not listed. An approved registration below the minimum is accepted (it leaves the below-minimum list) or
-- returned (RETURNED, the student told); a locked one is refused. A raised minimum is counted before and told after to the
-- students whose drafts it leaves short. The block undoes its writes.
DO $$
DECLARE ses text := '2396/2397'; sch uuid := gen_random_uuid(); prog text; dept text;
        a uuid := gen_random_uuid(); b uuid := gen_random_uuid(); c uuid := gen_random_uuid(); d uuid := gen_random_uuid(); e uuid := gen_random_uuid();
        ra uuid := gen_random_uuid(); rb uuid := gen_random_uuid(); rc uuid := gen_random_uuid(); rd uuid := gen_random_uuid(); re uuid := gen_random_uuid();
        o uuid := gen_random_uuid(); ref text; w_a text; w_b text; w_c text; st_a text; st_c text; agree boolean;
        below_before int; below_after int; ret text; ret_status text; locked text; impact_draft int; told int; told_again int; notices int; notices_again int; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', '00000000-0000-0000-0000-000000000000', true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        PERFORM set_config('moaum.reason', 'check V505', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), ses, DATE '2396-10-01', DATE '2397-08-31');
        SELECT p.code, p.dept_code INTO prog, dept FROM ref.programme p
         WHERE p.category = 'UNDER GRADUATE' AND NOT coalesce(p.archived, false) AND p.dept_code IS NOT NULL ORDER BY p.code LIMIT 1;
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status) VALUES
            (a, 'MOAUM/ADM/96/950501', 'CHECKV505', 'Unpaid', prog, 'UTME', ses, 100, 100, 'ADMITTED'),
            (b, 'MOAUM/ADM/96/950502', 'CHECKV505', 'Empty', prog, 'UTME', ses, 100, 100, 'ADMITTED'),
            (c, 'MOAUM/ADM/96/950503', 'CHECKV505', 'Paid', prog, 'UTME', ses, 100, 100, 'ADMITTED'),
            (d, 'MOAUM/ADM/96/950504', 'CHECKV505', 'Short', prog, 'UTME', ses, 100, 100, 'ADMITTED'),
            (e, 'MOAUM/ADM/96/950505', 'CHECKV505', 'Draft', prog, 'UTME', ses, 100, 100, 'ADMITTED');
        UPDATE people.student SET curriculum_version = 'CCMAS' WHERE id IN (a, b, c, d, e);
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state) VALUES ('ZQX 101', 'Check Card Course', 6, 1, 100, dept, 'Core', 'LIVE');
        INSERT INTO catalogue.offering (id, course_code, session, semester) VALUES (o, 'ZQX 101', ses, 1);
        INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, submitted_at, approved_at) VALUES
            (ra, a, ses, 1, 100, 'APPROVED', now(), now()), (rb, b, ses, 1, 100, 'APPROVED', now(), now()), (rc, c, ses, 1, 100, 'APPROVED', now(), now()),
            (rd, d, ses, 1, 100, 'APPROVED', now(), now()), (re, e, ses, 1, 100, 'DRAFT', NULL, NULL);
        INSERT INTO registration.entry (registration_id, offering_id, units, entry_type, status) VALUES
            (ra, o, 6, 'CURRENT', 'APPROVED'), (rc, o, 6, 'CURRENT', 'APPROVED'), (rd, o, 6, 'CURRENT', 'APPROVED'), (re, o, 6, 'CURRENT', 'REGISTERED');
        INSERT INTO finance.fee_schedule (session, item, amount, level, programme_code) VALUES (ses, 'School fees (check V505)', 50000, 100, prog);
        IF policy.in_force('clearance', 'UNIVERSITY', current_date) IS NULL THEN
            INSERT INTO policy.version (id, kind, scope, validity, instrument, decided_by) VALUES (sch, 'clearance', 'UNIVERSITY', daterange(current_date - 1, NULL), 'CHECK V505', 'bursar');
            INSERT INTO policy.clearance_scheme VALUES (sch, true);
            INSERT INTO policy.clearance_rule SELECT sch, p.code, CASE p.code WHEN 'HOSTEL' THEN 'NEVER_GATED' ELSE 'INSTALMENT_1' END FROM ref.clearance_purpose p;
        END IF;
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        FOREACH ref IN ARRAY ARRAY[finance.new_purpose_reference(c, ses, 50000, 'School fees ' || ses), finance.new_purpose_reference(d, ses, 50000, 'School fees ' || ses)] LOOP
            PERFORM finance.confirm_payment(ref, 'BANK_BRANCH', 'teller for check V505');
        END LOOP;
        -- 1 · the withheld list, as the card's rule says
        SELECT w.code INTO w_a FROM registration.exam_cards_withheld(ses, 1) w WHERE w.student_id = a;
        SELECT w.code INTO w_b FROM registration.exam_cards_withheld(ses, 1) w WHERE w.student_id = b;
        SELECT w.code INTO w_c FROM registration.exam_cards_withheld(ses, 1) w WHERE w.student_id = c;
        st_a := registration.exam_card_state(a, ses, 1)->>'code';
        st_c := registration.exam_card_state(c, ses, 1)->>'code';
        agree := NOT EXISTS (SELECT 1 FROM registration.exam_cards_withheld(ses, 1) w
                              WHERE w.code IS DISTINCT FROM registration.exam_card_state(w.student_id, ses, 1)->>'code');
        -- 2 · below the minimum (6 of CCMAS 15): accepted, returned, a locked one refused
        PERFORM set_config('moaum.actor_office', 'academic', true);
        below_before := (SELECT count(*) FROM registration.below_minimum(ses, 1) x WHERE x.registration_id IN (rc, rd));
        PERFORM registration.decide_below_minimum(rc, 'ACCEPTED', 'Check: accepted as it stands by the Academic Office');
        ret := registration.decide_below_minimum(rd, 'RETURNED', 'Check: add courses to reach the minimum');
        ret_status := (SELECT status FROM registration.course_registration WHERE id = rd);
        below_after := (SELECT count(*) FROM registration.below_minimum(ses, 1) x WHERE x.registration_id IN (rc, rd));
        UPDATE registration.course_registration SET status = 'LOCKED' WHERE id = ra;
        BEGIN PERFORM registration.decide_below_minimum(ra, 'RETURNED', 'Check: a locked registration'); locked := 'DECIDED';
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; locked := split_part(msg, ':', 1); END;
        -- 3 · a raised minimum: counted, then told (the draft and the returned one), once for each minimum
        impact_draft := coalesce((SELECT x.registrations FROM registration.unit_minimum_impact('CCMAS', ses, NULL, 16) x WHERE x.status = 'DRAFT'), 0);
        PERFORM set_config('moaum.actor_office', 'ict', true);
        PERFORM registration.set_unit_minimum('CCMAS', ses, NULL, 16, 'Check: CCMAS sixteen for the session');
        told := registration.tell_unit_minimum_change('CCMAS', ses, NULL);
        notices := (SELECT count(*) FROM platform.notice x WHERE x.about_id IN (d, e) AND x.template_key = 'REG_MIN_UNITS_RAISED');
        told_again := registration.tell_unit_minimum_change('CCMAS', ses, NULL);
        notices_again := (SELECT count(*) FROM platform.notice x WHERE x.about_id IN (d, e) AND x.template_key = 'REG_MIN_UNITS_RAISED');
        RAISE EXCEPTION 'the V505 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V505 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V505: the withheld list gives the card''s own code (unpaid, no course; a paid one not listed); a registration below the minimum is accepted or returned, a locked one refused; a raised minimum counted, then told once',
        coalesce(w_a = 'EXAM_CARD_NOT_CLEARED' AND w_b = 'EXAM_CARD_NO_COURSES' AND w_c IS NULL AND st_a = w_a AND st_c IS NULL AND agree
                 AND below_before = 2 AND ret = 'RETURNED' AND ret_status = 'RETURNED' AND below_after = 1 AND locked = 'REG_LOAD_LOCKED'
                 AND impact_draft = 1 AND told = 2 AND notices >= 2 AND notices_again = notices, false),
        format('withheld a %s b %s c %s (card a %s c %s, agree %s) | below %s -> %s, returned %s/%s, locked %s | impact draft %s, told %s then %s, notices %s then %s',
               w_a, w_b, w_c, st_a, st_c, agree, below_before, below_after, ret, ret_status, locked, impact_draft, told, told_again, notices, notices_again));
END $$;
-- ── V507: Add Other Course lists the student's own courses ──
-- With nothing typed and no department chosen, the search lists the courses that concern the student — the programme's at every
-- level with a class in the session, the University GST/EPS courses — and a category alone narrows them; another department's
-- course is found only by searching for it. The block undoes its writes.
DO $$
DECLARE ses text := '2397/2398'; st uuid := gen_random_uuid(); prog text; dept text; other_dept text; msg text;
        own_codes text; core_codes text; gst_codes text; carry_n bigint; found_other text; listed_other text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', '00000000-0000-0000-0000-000000000000', true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        PERFORM set_config('moaum.reason', 'check V507', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), ses, DATE '2397-10-01', DATE '2398-08-31');
        SELECT p.code, p.dept_code INTO prog, dept FROM ref.programme p
         WHERE p.category = 'UNDER GRADUATE' AND NOT coalesce(p.archived, false) AND p.dept_code IS NOT NULL
           AND registration.siwes_units(p.code, 200, 1) IS NULL ORDER BY p.code LIMIT 1;
        SELECT d.code INTO other_dept FROM ref.department d WHERE d.code <> dept ORDER BY d.code LIMIT 1;
        PERFORM registration.set_flex_policy(true, 'PROGRAMME', false, 'check V507: the default rule');
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status) VALUES
            (st, 'MOAUM/ADM/97/970101', 'CHECKV507', 'Listed', prog, 'UTME', ses, 200, 200, 'ADMITTED');
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state, general_office) VALUES
            ('ZQY 101', 'Check List Lower', 2, 1, 100, dept, 'Core', 'LIVE', NULL), ('ZQY 201', 'Check List Current', 3, 1, 200, dept, 'Core', 'LIVE', NULL),
            ('ZQY 211', 'Check List Elective', 2, 1, 200, dept, 'Elective', 'LIVE', NULL), ('GST 397', 'Check List University GST', 2, 1, 200, dept, 'GST', 'LIVE', 'GST'),
            ('ZQZ 201', 'Check List Elsewhere', 2, 1, 200, other_dept, 'Core', 'LIVE', NULL);
        INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES
            ('ZQY 101', prog, 100, 'Core'), ('ZQY 201', prog, 200, 'Core'), ('ZQY 211', prog, 200, 'Elective');
        INSERT INTO catalogue.offering (id, course_code, session, semester)
        SELECT gen_random_uuid(), c, ses, 1 FROM unnest(ARRAY['ZQY 101', 'ZQY 201', 'ZQY 211', 'GST 397', 'ZQZ 201']) c;
        own_codes := (SELECT string_agg(x.course_code, ',' ORDER BY x.course_code) FROM registration.course_search(st, ses, 1, NULL, NULL, NULL, NULL, NULL, 100, 0) x
                       WHERE x.course_code LIKE 'ZQ%' OR x.course_code = 'GST 397');
        core_codes := (SELECT string_agg(x.course_code || ':' || x.category, ',' ORDER BY x.course_code) FROM registration.course_search(st, ses, 1, NULL, NULL, NULL, NULL, 'CORE', 100, 0) x
                        WHERE x.course_code LIKE 'ZQ%');
        gst_codes := (SELECT string_agg(x.course_code, ',' ORDER BY x.course_code) FROM registration.course_search(st, ses, 1, NULL, NULL, NULL, NULL, 'GST', 100, 0) x
                       WHERE x.course_code = 'GST 397' OR x.course_code LIKE 'ZQ%');
        carry_n := (SELECT count(*) FROM registration.course_search(st, ses, 1, NULL, NULL, NULL, NULL, 'CARRY_OVER', 100, 0));
        found_other := (SELECT x.course_code || ':' || split_part(x.refusal, ':', 1) FROM registration.course_search(st, ses, 1, 'ZQZ 201', NULL, NULL, NULL, NULL, 100, 0) x);
        listed_other := (SELECT max(x.course_code) FROM registration.course_search(st, ses, 1, NULL, NULL, NULL, NULL, NULL, 100, 0) x WHERE x.course_code = 'ZQZ 201');
        RAISE EXCEPTION 'the V507 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V507 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V507: with nothing typed the search lists the student''s own courses (programme at every level, University GST/EPS), a category alone narrows them; another department''s course is found only by a search',
        coalesce(own_codes = 'GST 397,ZQY 101,ZQY 201,ZQY 211' AND core_codes = 'ZQY 101:CORE,ZQY 201:CORE' AND gst_codes = 'GST 397' AND carry_n = 0
                 AND found_other = 'ZQZ 201:REG_NOT_AVAILABLE' AND listed_other IS NULL, false),
        format('own [%s] core [%s] gst [%s] carry %s | search %s listed %s', own_codes, core_codes, gst_codes, carry_n, found_other, listed_other));
END $$;
-- ── V506. Overpaid school fees decided, and a session's fees copied from another. Three students of one programme in a session
--          charged ₦100,000 (and the next session): one paid ₦120,000 in two old-portal payments, one ₦130,000, one exactly.
--          Refused without a person or a reason; the first carried into the next session (a CARRIED record there that its
--          position counts, its journal moving ₦20,000 of school-fees income across, never cash, never posted again by the
--          sync); the rest refunded (a refund raised against the payment that covers the excess); decided once; a rejected
--          refund decided again. The fee lines copied: a preview, then the copy of what the next session lacks, a line it
--          states kept; refused into an unknown session, from an empty one, or into itself. The block undoes its writes ──
DO $$
DECLARE who uuid := gen_random_uuid(); s1 uuid := gen_random_uuid(); s2 uuid := gen_random_uuid(); s3 uuid := gen_random_uuid();
        a text := '9983/9984'; b text := '9984/9985'; pa text; pb text; no_actor text; short_reason text; over_before text;
        first record; carried_rec text; jlines text; unposted_free boolean; pos_b numeric; rec_after_carry text; second record; rf text;
        rec_after_refund text; again record; redo record; refunds_s2 int; prev text; copied text; after_copy text;
        e_unknown text; e_empty text; e_self text; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM set_config('moaum.reason', 'check V506', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES
            (gen_random_uuid(), a, date '9983-10-01', date '9984-08-31'), (gen_random_uuid(), b, date '9984-10-01', date '9985-08-31')
        ON CONFLICT (name) DO NOTHING;
        SELECT code INTO pa FROM ref.programme WHERE NOT coalesce(archived, false) ORDER BY code LIMIT 1;
        SELECT code INTO pb FROM ref.programme WHERE NOT coalesce(archived, false) AND code <> pa ORDER BY code LIMIT 1;
        INSERT INTO finance.fee_schedule (session, item, amount, level, programme_code, kind) VALUES
            (a, 'School fees', 100000, NULL, pa, 'FEE'), (b, 'School fees', 100000, NULL, pa, 'FEE'), (a, 'Late payment', 5000, NULL, pb, 'LATE_PAYMENT');
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at) VALUES
          (s1, 'MOAUM/ADM/83/983101', 'MOAUM/CHK/83/9831', 'ZZCHKV506A', 'Invented', pa, 'UTME', a, 100, 100, 'ACTIVE', now()),
          (s2, 'MOAUM/ADM/83/983102', 'MOAUM/CHK/83/9832', 'ZZCHKV506B', 'Invented', pa, 'UTME', a, 100, 100, 'ACTIVE', now()),
          (s3, 'MOAUM/ADM/83/983103', 'MOAUM/CHK/83/9833', 'ZZCHKV506C', 'Invented', pa, 'UTME', a, 100, 100, 'ACTIVE', now());
        INSERT INTO finance.payment_reference (student_id, session, reference, purpose, amount, expires_at, confirmed_at, confirmed_by, channel, receipt_no, note)
        SELECT v.s, a, v.ref, v.purpose, v.amount, v.day::timestamptz, v.day::timestamptz, who, 'Legacy', 'LEG-' || v.ref, 'Imported from the old portal · old ref ' || v.payref
          FROM (VALUES (s1, 'MOAUM-LEG-MOAUMCHK839831-9983-9984-S1', 'School fees (legacy) · semester 1', 70000.00, '9983-11-02', 'PRCHK5061'),
                       (s1, 'MOAUM-LEG-MOAUMCHK839831-9983-9984-S2', 'School fees (legacy) · semester 2', 50000.00, '9984-03-02', 'PRCHK5062'),
                       (s2, 'MOAUM-LEG-MOAUMCHK839832-9983-9984-S1', 'School fees (legacy) · semester 1', 130000.00, '9983-11-03', 'PRCHK5063'),
                       (s3, 'MOAUM-LEG-MOAUMCHK839833-9983-9984-S1', 'School fees (legacy) · semester 1', 100000.00, '9983-11-04', 'PRCHK5064')) v(s, ref, purpose, amount, day, payref);

        -- refused without a person, and without a reason
        PERFORM set_config('moaum.actor_id', '', true);
        BEGIN PERFORM * FROM finance.decide_overpayments(a, 'CARRY', NULL, 'carried into the next session');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS no_actor = MESSAGE_TEXT; END;
        PERFORM set_config('moaum.actor_id', who::text, true);
        BEGIN PERFORM * FROM finance.decide_overpayments(a, 'CARRY', NULL, 'short');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS short_reason = MESSAGE_TEXT; END;

        over_before := (SELECT string_agg(x.number || ':' || x.excess::int || ':' || coalesce(x.decision, '-'), ',' ORDER BY x.number COLLATE "C")
                          FROM finance.overpaid(a) x WHERE x.student_id IN (s1, s2, s3));
        -- the first carried into the next session
        SELECT * INTO first FROM finance.decide_overpayments(a, 'carry', ARRAY[s1], 'CHECK V506: carried into the next session');
        carried_rec := (SELECT r.session || ':' || r.amount::int || ':' || r.channel || ':' || r.purpose FROM finance.payment_reference r
                         WHERE r.student_id = s1 AND r.session = b);
        jlines := (SELECT string_agg(p.account || ':' || p.debit::int || ':' || p.credit::int || ':' || p.session, ',' ORDER BY p.line)
                     FROM finance.gl_posting p JOIN finance.gl_journal g ON g.id = p.journal_id
                    WHERE g.source_type = 'PAYMENT' AND g.source_ref = (SELECT d.reference FROM finance.overpayment_decision d WHERE d.student_id = s1));
        unposted_free := NOT EXISTS (SELECT 1 FROM finance.payment_reference r WHERE r.student_id = s1 AND r.session = b
                                       AND NOT EXISTS (SELECT 1 FROM finance.gl_journal g WHERE g.source_type = 'PAYMENT' AND g.source_ref = r.reference));
        SELECT p.paid INTO pos_b FROM finance.position(s1, b) p;
        rec_after_carry := (SELECT string_agg(x.number || ':' || x.state || ':' || x.settled::int || ':' || coalesce(x.decision, '-'), ',' ORDER BY x.number COLLATE "C")
                              FROM finance.old_fees_reconciliation(a) x WHERE x.student_id IN (s1, s2, s3));
        -- the rest refunded, against the payment that covers the excess
        SELECT * INTO second FROM finance.decide_overpayments(a, 'REFUND', NULL, 'CHECK V506: refunded to the student');
        rf := (SELECT f.amount::int || ':' || f.state || ':' || coalesce(f.source_reference, '-') FROM finance.refund f
                WHERE f.reference = (SELECT d.reference FROM finance.overpayment_decision d WHERE d.student_id = s2 AND d.superseded_at IS NULL));
        rec_after_refund := (SELECT string_agg(x.number || ':' || x.state, ',' ORDER BY x.number COLLATE "C")
                               FROM finance.old_fees_reconciliation(a) x WHERE x.student_id IN (s1, s2));
        SELECT * INTO again FROM finance.decide_overpayments(a, 'REFUND', ARRAY[s1, s2], 'CHECK V506: decided once only');
        -- a refund the desk rejects leaves the excess to be decided again
        UPDATE finance.refund SET state = 'REJECTED', rejected_why = 'check V506'
         WHERE reference = (SELECT d.reference FROM finance.overpayment_decision d WHERE d.student_id = s2 AND d.superseded_at IS NULL);
        SELECT * INTO redo FROM finance.decide_overpayments(a, 'REFUND', ARRAY[s2], 'CHECK V506: refunded again after the rejection');
        refunds_s2 := (SELECT count(*) FROM finance.refund f WHERE f.student_id = s2);

        -- the fees copied: a preview, then the copy of what the next session lacks
        prev := (SELECT string_agg(c.kind || ':' || c.item || ':' || c.action || ':' || coalesce(c.target_amount::int::text, '-'), ',' ORDER BY c.kind, c.item)
                   FROM finance.copy_session_fees(a, b, false) c WHERE c.programme_code IN (pa, pb));
        copied := (SELECT string_agg(c.kind || ':' || c.action, ',' ORDER BY c.kind) FROM finance.copy_session_fees(a, b, true) c WHERE c.programme_code IN (pa, pb));
        after_copy := (SELECT string_agg(f.kind || ':' || f.item || ':' || f.amount::int || ':' || f.programme_code, ',' ORDER BY f.kind)
                         FROM finance.fee_schedule f WHERE f.session = b AND f.ended_at IS NULL AND f.programme_code IN (pa, pb))
                      || '|' || (SELECT string_agg(c.action, ',' ORDER BY c.kind) FROM finance.copy_session_fees(a, b, false) c WHERE c.programme_code IN (pa, pb));
        BEGIN PERFORM * FROM finance.copy_session_fees(a, '9971/9972', false);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS e_unknown = MESSAGE_TEXT; END;
        BEGIN PERFORM * FROM finance.copy_session_fees('9969/9970', b, false);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS e_empty = MESSAGE_TEXT; END;
        BEGIN PERFORM * FROM finance.copy_session_fees(a, a, false);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS e_self = MESSAGE_TEXT; END;
        RAISE EXCEPTION 'the V506 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V506 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V506: an overpaid student''s excess is carried into the next session (a CARRIED record its position counts, its journal moving the income across, never cash) or refunded through the Refunds desk, once, a rejected refund decided again; and a session''s fees are copied from another after a preview, a stated line never overwritten',
        coalesce(no_actor LIKE 'OVERPAY_ACTOR%' AND short_reason LIKE 'OVERPAY_REASON%'
                 AND over_before = 'MOAUM/CHK/83/9831:20000:-,MOAUM/CHK/83/9832:30000:-'
                 AND first.carried = 1 AND first.refunds = 0 AND first.remaining = 0
                 AND carried_rec = '9984/9985:20000:CARRIED:School fees 9984/9985 (carried from 9983/9984)'
                 AND jlines = '4010:20000:0:9983/9984,4010:0:20000:9984/9985' AND unposted_free AND pos_b = 20000
                 AND rec_after_carry = 'MOAUM/CHK/83/9831:OVER_SETTLED:20000:CARRY,MOAUM/CHK/83/9832:OVER:0:-,MOAUM/CHK/83/9833:MATCHED:0:-'
                 AND second.carried = 0 AND second.refunds = 1 AND second.remaining = 0
                 AND rf = '30000:PROPOSED:MOAUM-LEG-MOAUMCHK839832-9983-9984-S1'
                 AND rec_after_refund = 'MOAUM/CHK/83/9831:OVER_SETTLED,MOAUM/CHK/83/9832:OVER_SETTLED'
                 AND again.carried = 0 AND again.refunds = 0 AND redo.refunds = 1 AND refunds_s2 = 2
                 AND prev = 'FEE:School fees:KEPT:100000,LATE_PAYMENT:Late payment:COPY:-'
                 AND copied = 'FEE:KEPT,LATE_PAYMENT:COPY'
                 AND after_copy = 'FEE:School fees:100000:' || pa || ',LATE_PAYMENT:Late payment:5000:' || pb || '|KEPT,KEPT'
                 AND e_unknown LIKE 'FEE_COPY_SESSION:%' AND e_empty LIKE 'FEE_COPY_EMPTY%' AND e_self LIKE 'FEE_COPY_SESSIONS%', false),
        format('no actor %s | short %s | overpaid %s | carry %s/%s/%s, record %s, journal %s, free %s, position %s | after carry %s | refund %s/%s/%s %s | after refund %s | again %s/%s, redo %s, refunds %s | preview %s | copied %s | after %s | errors %s / %s / %s',
               left(no_actor, 20), left(short_reason, 20), over_before, first.carried, first.refunds, first.remaining, carried_rec, jlines, unposted_free, pos_b,
               rec_after_carry, second.carried, second.refunds, second.remaining, rf, rec_after_refund, again.carried, again.refunds, redo.refunds, refunds_s2,
               prev, copied, after_copy, left(e_unknown, 25), left(e_empty, 20), left(e_self, 22)));
END $$;

-- ── V508: overload approval ──
-- A student asks for a higher maximum for one semester (more than the maximum, at most the rule's extra above it), once at a time;
-- the Head of Department of another department cannot decide; the student's own grants a ceiling, which registration.unit_rule
-- then reads as the maximum (unit_rule_base keeps the rule before it); both are told. A withdrawn request may be asked again, a
-- refused one leaves the maximum as it was, a closed rule refuses asking, and only the student asks and the Head decides.
DO $$
DECLARE ses text := '2397/2398'; pa text; pb text; da text; db text; a uuid := gen_random_uuid(); b uuid := gen_random_uuid();
        ha uuid := gen_random_uuid(); hb uuid := gen_random_uuid(); lmax int; st jsonb; q1 uuid; q2 uuid; q3 uuid;
        too_many text; twice text; other text; granted text; max_after int; base_after int; told_hod int; told_student int;
        withdrawn text; again uuid; refused text; max_b int; closed text; wrong_ask text; wrong_decide text; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', '00000000-0000-0000-0000-000000000000', true);
        PERFORM set_config('moaum.actor_office', 'registrar', true);
        PERFORM set_config('moaum.reason', 'check V508', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), ses, DATE '2397-10-01', DATE '2398-08-31');
        SELECT p.code, p.dept_code INTO pa, da FROM ref.programme p
         WHERE p.category = 'UNDER GRADUATE' AND NOT coalesce(p.archived, false) AND p.dept_code IS NOT NULL ORDER BY p.code LIMIT 1;
        SELECT p.code, p.dept_code INTO pb, db FROM ref.programme p
         WHERE p.category = 'UNDER GRADUATE' AND NOT coalesce(p.archived, false) AND p.dept_code IS NOT NULL AND p.dept_code <> da ORDER BY p.code LIMIT 1;
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status) VALUES
            (a, 'MOAUM/ADM/97/950801', 'CHECKV508', 'Asks', pa, 'UTME', ses, 100, 100, 'ADMITTED'),
            (b, 'MOAUM/ADM/97/950802', 'CHECKV508', 'Withdraws', pa, 'UTME', ses, 100, 100, 'ADMITTED');
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (ha, 'CHECK/V508A', 'CHECKV508', 'Head A'), (hb, 'CHECK/V508B', 'CHECKV508', 'Head B');
        INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from, valid_to) VALUES
            (gen_random_uuid(), ha, 'hod', 'department', da, 'check V508', gen_random_uuid(), current_date - 1, NULL),
            (gen_random_uuid(), hb, 'hod', 'department', db, 'check V508', gen_random_uuid(), current_date - 1, NULL);
        lmax := (SELECT u.max_units FROM registration.unit_rule(a, 100, ses, 1) u);
        -- 1 · the student asks: too many refused, then within the ceiling, then not twice
        PERFORM set_config('moaum.actor_office', 'student', true);
        PERFORM set_config('moaum.actor_id', a::text, true);
        st := registration.overload_state(a, ses, 1);
        BEGIN PERFORM registration.request_overload(a, ses, 1, lmax + 7, 'Check: final year with two carry-overs'); too_many := 'ASKED';
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; too_many := split_part(msg, ':', 1); END;
        q1 := registration.request_overload(a, ses, 1, lmax + 4, 'Check: final year with two carry-overs');
        BEGIN PERFORM registration.request_overload(a, ses, 1, lmax + 2, 'Check: asking a second time'); twice := 'ASKED';
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; twice := split_part(msg, ':', 1); END;
        -- 2 · the other department's Head cannot decide; the student's own grants less than asked
        PERFORM set_config('moaum.actor_office', 'hod', true);
        PERFORM set_config('moaum.actor_id', hb::text, true);
        BEGIN PERFORM registration.decide_overload(q1, 'GRANTED', lmax + 2, 'Check: granted by another department'); other := 'DECIDED';
        EXCEPTION WHEN insufficient_privilege THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; other := split_part(msg, ':', 1); END;
        PERFORM set_config('moaum.actor_id', ha::text, true);
        granted := registration.decide_overload(q1, 'GRANTED', lmax + 2, 'Check: two units for the outstanding project');
        max_after := (SELECT u.max_units FROM registration.unit_rule(a, 100, ses, 1) u);
        base_after := (SELECT u.max_units FROM registration.unit_rule_base(a, 100, ses, 1) u);
        told_hod := (SELECT count(*) FROM platform.notice x WHERE x.about_id = ha AND x.template_key = 'OVERLOAD_REQUESTED');
        told_student := (SELECT count(*) FROM platform.notice x WHERE x.about_id = a AND x.template_key = 'OVERLOAD_GRANTED');
        -- 3 · a withdrawn request is asked again; a refused one leaves the maximum as it was
        PERFORM set_config('moaum.actor_office', 'student', true);
        PERFORM set_config('moaum.actor_id', b::text, true);
        q2 := registration.request_overload(b, ses, 1, lmax + 1, 'Check: asking, then withdrawing');
        withdrawn := registration.withdraw_overload(b, q2);
        again := registration.request_overload(b, ses, 1, lmax + 3, 'Check: asking again after withdrawing');
        PERFORM set_config('moaum.actor_office', 'hod', true);
        PERFORM set_config('moaum.actor_id', ha::text, true);
        refused := registration.decide_overload(again, 'REFUSED', NULL, 'Check: the load is already heavy enough');
        max_b := (SELECT u.max_units FROM registration.unit_rule(b, 100, ses, 1) u);
        -- 4 · a closed rule refuses asking; only the student asks, only the Head decides
        PERFORM set_config('moaum.actor_office', 'academic', true);
        PERFORM registration.set_overload_policy(false, 6, 'Check: overloads closed for the session');
        PERFORM set_config('moaum.actor_office', 'student', true);
        PERFORM set_config('moaum.actor_id', b::text, true);
        BEGIN PERFORM registration.request_overload(b, ses, 2, lmax + 1, 'Check: asking while closed'); closed := 'ASKED';
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; closed := split_part(msg, ':', 1); END;
        PERFORM set_config('moaum.actor_office', 'academic', true);
        PERFORM registration.set_overload_policy(true, 6, 'Check: overloads open again');
        PERFORM set_config('moaum.actor_office', 'lecturer', true);
        BEGIN PERFORM registration.request_overload(b, ses, 2, lmax + 1, 'Check: a lecturer asks'); wrong_ask := 'ASKED';
        EXCEPTION WHEN insufficient_privilege THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; wrong_ask := split_part(msg, ':', 1); END;
        PERFORM set_config('moaum.actor_office', 'student', true);
        q3 := registration.request_overload(b, ses, 2, lmax + 1, 'Check: asking for the second semester');
        PERFORM set_config('moaum.actor_office', 'academic', true);
        BEGIN PERFORM registration.decide_overload(q3, 'GRANTED', lmax + 1, 'Check: the Academic Office decides'); wrong_decide := 'DECIDED';
        EXCEPTION WHEN insufficient_privilege THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; wrong_decide := split_part(msg, ':', 1); END;
        RAISE EXCEPTION 'the V508 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V508 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V508: a student asks for an overload within the ceiling, once at a time; only their own Head of Department grants it, and the grant is the semester''s maximum; withdrawn, refused, closed and wrong offices as the rule says',
        coalesce((st->>'may_ask')::boolean AND (st->>'regular_max')::int = lmax AND (st->>'ceiling')::int = lmax + 6
                 AND too_many = 'REG_OVERLOAD_UNITS' AND q1 IS NOT NULL AND twice = 'REG_OVERLOAD_WAITING'
                 AND other = 'REG_OVERLOAD_OTHER_DEPT' AND granted = 'GRANTED' AND max_after = lmax + 2 AND base_after = lmax
                 AND told_hod = 1 AND told_student >= 1
                 AND withdrawn = 'WITHDRAWN' AND again IS NOT NULL AND refused = 'REFUSED' AND max_b = lmax
                 AND closed = 'REG_OVERLOAD_CLOSED' AND wrong_ask = 'REG_OVERLOAD_STUDENT' AND wrong_decide = 'REG_OVERLOAD_HOD', false),
        format('max %s state %s | too many %s, twice %s | other %s, granted %s -> max %s (base %s), told hod %s student %s | withdrawn %s, refused %s -> max %s | closed %s, lecturer %s, academic %s',
               lmax, st, too_many, twice, other, granted, max_after, base_after, told_hod, told_student, withdrawn, refused, max_b, closed, wrong_ask, wrong_decide));
END $$;

-- ── V509: a PG supervisor ended or replaced, a panel member removed ──
-- The last first supervisor is never ended alone (replaced instead); a change never takes effect in the future; a second
-- supervisor ends with the date and reason kept; a replacement ends the first supervisor and names the successor in the same role;
-- a panel member is removed (with or without another in the role) until the viva, never after it; only the School changes them;
-- every change is on the research log and the candidate is told of a supervisor change. The dates are Lagos dates, as the screen
-- sends them (V539: the database's own date is a day behind from midnight to one o'clock in Lagos). The block undoes its writes.
DO $$
DECLARE td date := (now() AT TIME ZONE 'Africa/Lagos')::date; st uuid := gen_random_uuid(); r uuid := gen_random_uuid(); prog text; a uuid; b uuid; x uuid; y uuid; c uuid; z uuid;
        last_first text; future text; ended_b text; replaced uuid; live_first text; a_succ boolean; z2 uuid; y_off boolean; examined text;
        wrong text; logged int; told int; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', '00000000-0000-0000-0000-000000000000', true);
        PERFORM set_config('moaum.actor_office', 'pgschool', true);
        PERFORM set_config('moaum.reason', 'check V509', true);
        SELECT p.code INTO prog FROM ref.programme p WHERE p.category = 'POST GRADUATE' AND NOT coalesce(p.archived, false) ORDER BY p.code LIMIT 1;
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status)
        VALUES (st, 'MOAUM/ADM/98/950901', 'CHECKV509', 'Candidate', prog, 'POSTGRADUATE', '2025/2026', 700, 700, 'ADMITTED');
        INSERT INTO admissions.pg_research (id, student_id, degree_kind, stage) VALUES (r, st, 'DISSERTATION', 'SUPERVISED');
        INSERT INTO admissions.pg_research_supervisor (research_id, name, role, assigned_at) VALUES (r, 'Dr Check First', 'FIRST', now() - interval '200 days') RETURNING id INTO a;
        INSERT INTO admissions.pg_research_supervisor (research_id, name, role, assigned_at) VALUES (r, 'Dr Check Second', 'SECOND', now() - interval '100 days') RETURNING id INTO b;
        INSERT INTO admissions.pg_research_panel (research_id, name, role, is_external) VALUES (r, 'Prof Check External', 'EXTERNAL', true) RETURNING id INTO x;
        INSERT INTO admissions.pg_research_panel (research_id, name, role) VALUES (r, 'Dr Check Internal', 'INTERNAL') RETURNING id INTO y;
        -- 1 · supervisors
        BEGIN PERFORM admissions.pg_end_supervisor(a, td, 'Check: the first supervisor retires'); last_first := 'ENDED';
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; last_first := split_part(msg, ':', 1); END;
        BEGIN PERFORM admissions.pg_end_supervisor(b, td + 1, 'Check: ending tomorrow'); future := 'ENDED';
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; future := split_part(msg, ':', 1); END;
        PERFORM admissions.pg_end_supervisor(b, td - 3, 'Check: the second supervisor left the University');
        ended_b := (SELECT ended_on::text || '/' || end_reason FROM admissions.pg_research_supervisor WHERE id = b);
        replaced := admissions.pg_replace_supervisor(a, 'Dr Check Successor', NULL, false, td, 'Check: the first supervisor retires');
        live_first := (SELECT string_agg(name, ',') FROM admissions.pg_research_supervisor WHERE research_id = r AND ended_at IS NULL);
        a_succ := (SELECT replaced_by = replaced AND ended_on = td FROM admissions.pg_research_supervisor WHERE id = a);
        -- 2 · the panel
        z2 := admissions.pg_remove_panel_member(x, td, 'Check: the external examiner declined', 'Prof Check Replacement', true);
        PERFORM admissions.pg_remove_panel_member(y, td, 'Check: the internal examiner is on leave', NULL, NULL);
        y_off := (SELECT removed_at IS NOT NULL AND replaced_by IS NULL FROM admissions.pg_research_panel WHERE id = y);
        UPDATE admissions.pg_research SET stage = 'VIVA_HELD' WHERE id = r;
        BEGIN PERFORM admissions.pg_remove_panel_member(z2, td, 'Check: after the viva', NULL, NULL); examined := 'REMOVED';
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; examined := split_part(msg, ':', 1); END;
        PERFORM set_config('moaum.actor_office', 'hod', true);
        BEGIN PERFORM admissions.pg_end_supervisor(replaced, td, 'Check: a Head of Department tries'); wrong := 'ENDED';
        EXCEPTION WHEN insufficient_privilege THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; wrong := split_part(msg, ':', 1); END;
        logged := (SELECT count(*) FROM admissions.pg_research_event WHERE research_id = r AND stage IN ('SUPERVISOR_ENDED', 'SUPERVISOR_REPLACED', 'PANEL_CHANGED'));
        told := (SELECT count(*) FROM platform.notice n WHERE n.about_id = st AND n.template_key = 'PG_SUPERVISOR_CHANGED');
        RAISE EXCEPTION 'the V509 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V509 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V509: the School ends or replaces a supervisor and removes a panel member with the date and reason kept; never the last first supervisor alone, a future date or a panel that examined',
        coalesce(last_first = 'PG_SUP_LAST_FIRST' AND future = 'PG_CHANGE_DATE' AND ended_b = (td - 3)::text || '/Check: the second supervisor left the University'
                 AND replaced IS NOT NULL AND live_first = 'Dr Check Successor' AND a_succ AND z2 IS NOT NULL AND y_off AND examined = 'PG_PANEL_EXAMINED'
                 AND wrong = 'PG_RESEARCH_SCHOOL' AND logged = 4 AND told >= 2, false),
        format('last first %s, future %s, ended b %s, live %s succ %s | panel z2 %s y off %s, examined %s | hod %s | logged %s told %s',
               last_first, future, ended_b, live_first, a_succ, z2, y_off, examined, wrong, logged, told));
END $$;

-- ── V510: a new appointment in HR ──
-- Human Resources sets a salary grade, then appoints: a new person is made (and an existing one linked by staff number) with the
-- establishment record and an ACTIVE employment record, keeping only the last four digits of an account; a second appointment of
-- the same person, an academic appointment without a department, a grade not set up or of the other category are refused with
-- their reasons; an upload appoints the rows that pass and lists the rest (a staff number repeated in the file refused); Excel day
-- numbers and DD/MM/YYYY are read; a grade in use keeps its category; only Human Resources appoints. The block undoes its writes.
DO $$
DECLARE dept text; old uuid := gen_random_uuid(); e1 uuid; e2 uuid; chk jsonb; again text; noDept jsonb; noGrade jsonb; wrongCat jsonb; link jsonb;
        many jsonb; dupes jsonb; emp record; rec record; inuse text; wrong text; d1 date; d2 date; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', '00000000-0000-0000-0000-000000000000', true);
        PERFORM set_config('moaum.actor_office', 'hrm', true);
        PERFORM set_config('moaum.reason', 'check V510', true);
        SELECT d.code INTO dept FROM ref.department d WHERE d.ended_on IS NULL ORDER BY d.code LIMIT 1;
        PERFORM hrm.set_grade('checkuass 9', 1, 'academic', 200000, 50000, 20000, 0, 'Check: an academic grade for the check');
        PERFORM hrm.set_grade('CHECKTISS 7', 2, 'NON-ACADEMIC', 90000, 20000, 10000, 0, 'Check: a non-academic grade for the check');
        -- 1 · a new member of staff
        chk := hrm.appointment_check(jsonb_build_object('staff_no', 'CHK/V510/1', 'surname', 'Checkvten', 'given_names', 'New Lecturer', 'category', 'ACADEMIC',
                    'grade', 'CHECKUASS 9', 'step', '1', 'appointment_date', '2026-10-01', 'department', dept, 'sex', 'F', 'account_number', '0123456789'));
        e1 := hrm.appoint(jsonb_build_object('staff_no', 'CHK/V510/1', 'surname', 'Checkvten', 'given_names', 'New Lecturer', 'category', 'ACADEMIC',
                    'grade', 'CHECKUASS 9', 'step', '1', 'appointment_date', '2026-10-01', 'department', dept, 'sex', 'F', 'account_number', '0123456789'));
        SELECT e.status, e.account_last4, e.grade, p.surname, sr.home_department AS dept INTO emp
          FROM hrm.employment e JOIN iam.person p ON p.id = e.person_id LEFT JOIN hrm.staff_record sr ON sr.person_id = p.id WHERE e.id = e1;
        BEGIN PERFORM hrm.appoint(jsonb_build_object('staff_no', 'CHK/V510/1', 'category', 'ACADEMIC', 'grade', 'CHECKUASS 9', 'step', '1',
                    'appointment_date', '2026-10-01', 'department', dept)); again := 'APPOINTED';
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; again := split_part(msg, ':', 1); END;
        -- 2 · the reasons a row is refused
        noDept := hrm.appointment_check(jsonb_build_object('staff_no', 'CHK/V510/2', 'surname', 'Checkvten', 'given_names', 'No Department', 'category', 'ACADEMIC',
                    'grade', 'CHECKUASS 9', 'step', '1', 'appointment_date', '2026-10-01'));
        noGrade := hrm.appointment_check(jsonb_build_object('staff_no', 'CHK/V510/3', 'surname', 'Checkvten', 'given_names', 'No Grade', 'category', 'ACADEMIC',
                    'grade', 'CHECKUASS 99', 'step', '1', 'appointment_date', '2026-10-01', 'department', dept));
        wrongCat := hrm.appointment_check(jsonb_build_object('staff_no', 'CHK/V510/4', 'surname', 'Checkvten', 'given_names', 'Wrong Category', 'category', 'NON_ACADEMIC',
                    'grade', 'CHECKUASS 9', 'step', '1', 'appointment_date', '2026-10-01', 'unit', dept));
        -- 3 · an existing person is linked by the staff number
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (old, 'CHK/V510/OLD', 'CHECKVTEN', 'Already Here');
        link := hrm.appointment_check(jsonb_build_object('staff_no', 'CHK/V510/OLD', 'category', 'NON_ACADEMIC', 'grade', 'checktiss 7', 'step', 2,
                    'appointment_date', '45678', 'department', dept));
        -- 4 · an upload: one passes, one fails, two repeat a staff number
        dupes := hrm.appointments_check(jsonb_build_array(
            jsonb_build_object('row', 2, 'staff_no', 'CHK/V510/5', 'surname', 'Checkvten', 'given_names', 'Twice A', 'category', 'NON_ACADEMIC', 'grade', 'CHECKTISS 7', 'step', 2, 'appointment_date', '01/10/2026', 'department', dept),
            jsonb_build_object('row', 3, 'staff_no', 'chk/v510/5', 'surname', 'Checkvten', 'given_names', 'Twice B', 'category', 'NON_ACADEMIC', 'grade', 'CHECKTISS 7', 'step', 2, 'appointment_date', '01/10/2026', 'department', dept)));
        many := hrm.appoint_many(jsonb_build_array(
            jsonb_build_object('row', 2, 'staff_no', 'CHK/V510/OLD', 'category', 'NON_ACADEMIC', 'grade', 'CHECKTISS 7', 'step', 2, 'appointment_date', '45678', 'department', dept, 'email', 'checkv510@example.test'),
            jsonb_build_object('row', 3, 'staff_no', 'CHK/V510/6', 'surname', 'Checkvten', 'given_names', 'No Date', 'category', 'NON_ACADEMIC', 'grade', 'CHECKTISS 7', 'step', 2, 'department', dept)));
        SELECT p.email, e.appointment_date INTO rec FROM iam.person p JOIN hrm.employment e ON e.person_id = p.id WHERE p.id = old;
        d1 := hrm.read_day('45678'); d2 := hrm.read_day('21/01/2025');
        -- 5 · a grade in use keeps its category; only Human Resources appoints
        BEGIN PERFORM hrm.set_grade('CHECKUASS 9', 1, 'NON_ACADEMIC', 1, 0, 0, 0, 'Check: changing a grade in use'); inuse := 'SET';
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; inuse := split_part(msg, ':', 1); END;
        PERFORM set_config('moaum.actor_office', 'registrar', true);
        BEGIN PERFORM hrm.appoint(jsonb_build_object('staff_no', 'CHK/V510/7')); wrong := 'APPOINTED';
        EXCEPTION WHEN insufficient_privilege THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; wrong := split_part(msg, ':', 1); END;
        RAISE EXCEPTION 'the V510 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V510 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V510: Human Resources appoints from a form or an upload after the grade is set up; a person in employment, a missing department, an unknown or other-category grade and a repeated staff number are refused with reasons',
        coalesce((chk->>'ok')::boolean AND chk->>'action' = 'CREATE' AND chk->>'account_last4' = '6789'
                 AND emp.status = 'ACTIVE' AND emp.account_last4 = '6789' AND emp.grade = 'CHECKUASS 9' AND emp.surname = 'CHECKVTEN' AND emp.dept = dept
                 AND again = 'HR_APPOINTMENT_INVALID'
                 AND NOT (noDept->>'ok')::boolean AND noDept->>'problems' LIKE '%names the department%'
                 AND NOT (noGrade->>'ok')::boolean AND noGrade->>'problems' LIKE '%not set up%'
                 AND NOT (wrongCat->>'ok')::boolean AND wrongCat->>'problems' LIKE '%academic grade%'
                 AND (link->>'ok')::boolean AND link->>'action' = 'LINK' AND link->>'person_id' = old::text
                 AND NOT (dupes->0->>'ok')::boolean AND NOT (dupes->1->>'ok')::boolean AND dupes->0->>'problems' LIKE '%repeated in the file (rows 2, 3)%'
                 AND (many->>'appointed')::int = 1 AND (many->>'skipped')::int = 1 AND many->'rows'->1->>'problems' LIKE '%date of appointment%'
                 AND rec.email = 'checkv510@example.test' AND rec.appointment_date = DATE '2025-01-21'
                 AND d1 = DATE '2025-01-21' AND d2 = DATE '2025-01-21' AND inuse = 'HR_GRADE_IN_USE' AND wrong = 'HR_APPOINT_OFFICE', false),
        format('chk %s | emp %s | again %s | noDept %s | noGrade %s | wrongCat %s | link %s | dupes %s | many %s | rec %s | days %s %s | inuse %s wrong %s',
               chk->>'ok', emp, again, noDept->'problems', noGrade->'problems', wrongCat->'problems', link->>'action', dupes->0->'problems', many, rec, d1, d2, inuse, wrong));
END $$;

-- ── V511: API keys checked on the integration door ──
-- A consumer is registered only with scopes on the list; its key answers the student status lookup with the minimal record (name
-- with initials, IN_STUDY), a matriculation number not on the register is NOT_FOUND, the daily quota refuses the call after it,
-- a key that is not one (or revoked) is BAD_KEY, a consumer without the scope NO_SCOPE; every call is on the request log. The
-- block undoes its writes.
DO $$
DECLARE st uuid := gen_random_uuid(); prog text; c uuid; other uuid; k text; ko text; unknown text; bad jsonb; ok jsonb; nf jsonb; over jsonb; noscope jsonb;
        revoked jsonb; logged text; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', '00000000-0000-0000-0000-000000000000', true);
        PERFORM set_config('moaum.actor_office', 'ict', true);
        PERFORM set_config('moaum.reason', 'check V511', true);
        SELECT p.code INTO prog FROM ref.programme p WHERE p.category = 'UNDER GRADUATE' AND NOT coalesce(p.archived, false) ORDER BY p.code LIMIT 1;
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (st, 'MOAUM/ADM/99/951101', 'CHK/V511/0001', 'CHECKVELEVEN', 'Ada Ngozi', prog, 'UTME', '2025/2026', 100, 200, 'ACTIVE', now());
        BEGIN PERFORM apimgmt.register_consumer('Check consumer', 'Check owner', 'students:status payments:read', 2); unknown := 'REGISTERED';
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; unknown := split_part(msg, ':', 1); END;
        c := apimgmt.register_consumer('Check consumer', 'Check owner', 'students:status', 2);
        k := apimgmt.issue_key(c, 30);
        INSERT INTO apimgmt.consumer (id, name, owner, scopes, created_by) VALUES (gen_random_uuid(), 'Check old consumer', 'Check owner', 'verify:read', '00000000-0000-0000-0000-000000000000') RETURNING id INTO other;
        ko := apimgmt.issue_key(other, 30);
        bad := apimgmt.student_status('mk_not_a_key', 'CHK/V511/0001', '127.0.0.1');
        ok := apimgmt.student_status(k, 'chk/v511/0001', '127.0.0.1');
        nf := apimgmt.student_status(k, 'CHK/V511/9999', '127.0.0.1');
        over := apimgmt.student_status(k, 'CHK/V511/0001', '127.0.0.1');
        noscope := apimgmt.student_status(ko, 'CHK/V511/0001', '127.0.0.1');
        PERFORM apimgmt.revoke_key((SELECT id FROM apimgmt.key WHERE consumer_id = other));
        revoked := apimgmt.student_status(ko, 'CHK/V511/0001', '127.0.0.1');
        logged := (SELECT string_agg(outcome, ',' ORDER BY at, outcome) FROM apimgmt.request_log WHERE subject IN ('CHK/V511/0001', 'CHK/V511/9999'));
        RAISE EXCEPTION 'the V511 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V511 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V511: an API key answers only within its consumer''s scope and quota on the integration door, the student told minimally, every call logged',
        coalesce(unknown = 'API_SCOPE_UNKNOWN' AND bad->>'outcome' = 'BAD_KEY'
                 AND ok->>'outcome' = 'OK' AND ok->'student'->>'name' = 'CHECKVELEVEN, A. N.' AND ok->'student'->>'status' = 'IN_STUDY'
                 AND (ok->'student'->>'level')::int = 200 AND NOT (ok->'student' ? 'email') AND NOT (ok->'student' ? 'phone')
                 AND nf->>'outcome' = 'NOT_FOUND' AND over->>'outcome' = 'OVER_QUOTA' AND noscope->>'outcome' = 'NO_SCOPE' AND revoked->>'outcome' = 'BAD_KEY'
                 AND (SELECT count(*) FROM regexp_split_to_table(logged, ',')) = 6, false),
        format('unknown %s | bad %s | ok %s | nf %s | over %s | noscope %s | revoked %s | log %s', unknown, bad, ok, nf, over, noscope, revoked, logged));
END $$;
-- ── V512: a GST or EPS carry-over waits for the GST fee ──
-- A 400-level student who failed GST 976 owes it as a carry-over and owes the GST fee: the draft is made without it, adding it is
-- refused (GST_PAYMENT_REQUIRED, named a carry-over), one put on before comes off on saving while the student's core course goes on;
-- once the GST payment is confirmed the carry-over goes on at the next save, under carry-over, with the GST/EPS registration log
-- saying so (carry-over registered, payment verified). The block undoes its writes.
DO $$
DECLARE who uuid := gen_random_uuid(); S0 text := '2398/2399'; S text := '2399/2400'; st uuid := gen_random_uuid(); prog text := 'C00023'; dept text;
        p0 uuid := gen_random_uuid(); ogst uuid := gen_random_uuid(); ocore uuid := gen_random_uuid(); sh uuid := gen_random_uuid();
        r0 uuid := gen_random_uuid(); reg uuid; ref text; msg text;
        carry boolean; hold_gst text; hold_core text; n_draft int; add_refused text; add_words text; after_cleanup text; hold_paid text;
        after_paid text; cat text; events text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        PERFORM set_config('moaum.reason', 'check V512', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S0, DATE '2398-10-01', DATE '2399-08-31'),
                                                                                 (gen_random_uuid(), S, DATE '2399-10-01', DATE '2400-08-31');
        UPDATE finance.gst_setting SET required_for_gst_eps = true, required_for_all = false, covers_eps = true WHERE id = 1;
        SELECT dept_code INTO dept FROM ref.programme WHERE code = prog;
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state, general_office) VALUES
            ('GST 976', 'Check Carry-over GST', 2, 1, 300, dept, 'GST', 'LIVE', 'GST'), ('ZQT 401', 'Check Final-year Core', 3, 1, 400, dept, 'Core', 'LIVE', NULL);
        INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES ('GST 976', prog, 300, 'GST'), ('ZQT 401', prog, 400, 'Core');
        INSERT INTO catalogue.offering (id, course_code, session, semester) VALUES (p0, 'GST 976', S0, 1), (ogst, 'GST 976', S, 1), (ocore, 'ZQT 401', S, 1);
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (st, 'MOAUM/ADM/98/980121', 'MOAUM/CHK/98/9812', 'CHECKV512', 'CarryGst', prog, 'UTME', S0, 100, 400, 'ACTIVE', now());
        UPDATE people.student SET curriculum_version = NULL WHERE id = st;
        -- last session: GST 976 failed, published
        INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, approved_at) VALUES (r0, st, S0, 1, 300, 'APPROVED', now());
        INSERT INTO registration.entry (registration_id, offering_id, units, status) VALUES (r0, p0, 2, 'APPROVED');
        INSERT INTO assessment.score_sheet (id, offering_id, stage, senate_minute, published_at, submitted_at) VALUES (sh, p0, 'PUBLISHED', 'SEN/2399/01', now(), now());
        INSERT INTO assessment.score (sheet_id, student_id, ca, exam, outcome) VALUES (sh, st, 10, 15, 'GRADED');
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM finance.state_gst_fee(S, 5000, NULL, NULL, NULL, NULL, current_date, 'V512 check', who, 'bursar');
        PERFORM set_config('moaum.actor_office', 'student', true);

        carry := EXISTS (SELECT 1 FROM registration.carryovers(st) WHERE course_code = 'GST 976');
        hold_gst := split_part(coalesce(registration.gst_course_hold(st, S, 'GST 976'), 'OPEN'), ':', 1);
        hold_core := coalesce(registration.gst_course_hold(st, S, 'ZQT 401'), 'OPEN');
        -- the draft is made without the unpaid GST carry-over
        reg := registration.student_draft(st, S, 1);
        n_draft := (SELECT count(*) FROM registration.entry WHERE registration_id = reg);
        -- adding it is refused, named a carry-over
        BEGIN
            PERFORM registration.student_add_other(st, S, 1, ogst);
            add_refused := 'ADDED';
        EXCEPTION WHEN check_violation THEN add_refused := split_part(SQLERRM, ':', 1); add_words := SQLERRM;
        END;
        -- one put on before (an earlier draft) comes off on saving; the core course goes on
        INSERT INTO registration.entry (registration_id, offering_id, units, entry_type) VALUES (reg, ogst, 2, 'CARRYOVER');
        PERFORM registration.student_choose(reg, ARRAY[ocore]);
        after_cleanup := (SELECT string_agg(o.course_code || ':' || e.entry_type, ',' ORDER BY o.course_code) FROM registration.entry e
                            JOIN catalogue.offering o ON o.id = e.offering_id WHERE e.registration_id = reg);
        -- the GST fee paid and confirmed: the carry-over goes on at the next save, under carry-over
        ref := finance.new_gst_reference(st, S);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM finance.confirm_payment(ref, 'Bank transfer', 'V512 check');
        PERFORM set_config('moaum.actor_office', 'student', true);
        hold_paid := coalesce(registration.gst_course_hold(st, S, 'GST 976'), 'OPEN');
        PERFORM registration.student_choose(reg, ARRAY[ocore]);
        after_paid := (SELECT string_agg(o.course_code || ':' || e.entry_type, ',' ORDER BY o.course_code) FROM registration.entry e
                         JOIN catalogue.offering o ON o.id = e.offering_id WHERE e.registration_id = reg);
        cat := (SELECT registration.entry_category(e.entry_type, c.kind, NULL) FROM registration.entry e JOIN catalogue.offering o ON o.id = e.offering_id
                  JOIN catalogue.course c ON c.code = o.course_code WHERE e.registration_id = reg AND c.code = 'GST 976');
        events := (SELECT string_agg(e.event, ',' ORDER BY e.event) FROM registration.gst_course_event e WHERE e.student_id = st);
        RAISE EXCEPTION 'the V512 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V512 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V512: a GST/EPS carry-over waits for the GST fee — never put on the draft or added unpaid (one put on before comes off), the other courses go on; once the payment is confirmed it goes on under carry-over, logged',
        coalesce(carry AND hold_gst = 'GST_PAYMENT_REQUIRED' AND hold_core = 'OPEN' AND n_draft = 0
                 AND add_refused = 'GST_PAYMENT_REQUIRED' AND add_words LIKE '%carry-over%' AND after_cleanup = 'ZQT 401:CURRENT'
                 AND hold_paid = 'OPEN' AND after_paid = 'GST 976:CARRYOVER,ZQT 401:CURRENT' AND cat = 'CARRY_OVER'
                 AND events = 'GST_CARRY_OVER_REGISTERED,GST_PAYMENT_VERIFIED', false),
        format('carry %s | hold %s/%s | draft %s | add %s | after cleanup %s | paid %s → %s (%s) | events %s',
               carry, hold_gst, hold_core, n_draft, add_refused, after_cleanup, hold_paid, after_paid, cat, events));
END $$;

-- ── V513: the staff without an employment record ──
-- A lecturer on a department's establishment with no employment record is listed ACADEMIC with that department; a person on
-- the establishment record with its unit and rank; a person in employment and a person whose record ended are not listed. The
-- block undoes its writes.
DO $$
DECLARE dept text; unit text; lec uuid := gen_random_uuid(); est uuid := gen_random_uuid(); emp uuid := gen_random_uuid(); gone uuid := gen_random_uuid();
        l record; e record; n_emp int; n_gone int; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', '00000000-0000-0000-0000-000000000000', true);
        PERFORM set_config('moaum.actor_office', 'hrm', true);
        PERFORM set_config('moaum.reason', 'check V513', true);
        SELECT d.code INTO dept FROM ref.department d WHERE d.ended_on IS NULL ORDER BY d.code LIMIT 1;
        SELECT u.code INTO unit FROM ref.unit u WHERE u.ended_on IS NULL ORDER BY u.code LIMIT 1;
        INSERT INTO iam.person (id, staff_number, surname, given_names, ended_on, ended_reason) VALUES
            (lec, 'CHK/V513/L', 'Checkvthirteen', 'Lecturer', NULL, NULL), (est, 'CHK/V513/E', 'Checkvthirteen', 'Establishment', NULL, NULL),
            (emp, 'CHK/V513/P', 'Checkvthirteen', 'Employed', NULL, NULL), (gone, 'CHK/V513/G', 'Checkvthirteen', 'Gone', current_date - 1, 'check V513: left');
        INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from)
        VALUES (gen_random_uuid(), lec, 'lecturer', 'department', dept, 'check V513', gen_random_uuid(), current_date - 1);
        INSERT INTO hrm.staff_record (person_id, home_unit, present_rank, category, sex) VALUES (est, unit, 'Senior Executive Officer', 'NON_ACADEMIC', 'F');
        IF NOT EXISTS (SELECT 1 FROM hrm.grade WHERE grade = 'CHKV513' AND step = 1) THEN
            INSERT INTO hrm.grade (grade, step, category, basic) VALUES ('CHKV513', 1, 'NON_ACADEMIC', 1);
        END IF;
        INSERT INTO hrm.employment (person_id, staff_no, grade, step, category, appointment_date) VALUES (emp, 'CHK/V513/P', 'CHKV513', 1, 'NON_ACADEMIC', current_date);
        SELECT * INTO l FROM hrm.staff_without_employment() x WHERE x.person_id = lec;
        SELECT * INTO e FROM hrm.staff_without_employment() x WHERE x.person_id = est;
        n_emp := (SELECT count(*) FROM hrm.staff_without_employment() x WHERE x.person_id = emp);
        n_gone := (SELECT count(*) FROM hrm.staff_without_employment() x WHERE x.person_id = gone);
        RAISE EXCEPTION 'the V513 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V513 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V513: the staff without an employment record are listed with what the portal holds (a lecturer ACADEMIC in the grant''s department, the establishment''s unit and rank); the employed and the ended are not',
        coalesce(l.category = 'ACADEMIC' AND l.department = dept AND l.source = 'LECTURER' AND l.surname = 'CHECKVTHIRTEEN'
                 AND e.category = 'NON_ACADEMIC' AND e.unit = unit AND e.rank = 'Senior Executive Officer' AND e.sex = 'F' AND e.source = 'ESTABLISHMENT'
                 AND n_emp = 0 AND n_gone = 0, false),
        format('lecturer %s/%s/%s | establishment %s/%s/%s/%s | employed %s ended %s', l.category, l.department, l.source, e.category, e.unit, e.rank, e.source, n_emp, n_gone));
END $$;

-- ── V514: overload requests no Head can decide, and waiting ones reminded ──
-- A request waiting five days in a department with a Head is reminded to that Head (once, not again the same day); a request in a
-- department with no Head is counted and the Academic Office told once a day which departments; a request of today is not
-- reminded yet. The block undoes its writes.
DO $$
DECLARE ses text := '2399/2400'; da text; pa text; dn text; pn text; head uuid := gen_random_uuid(); acad uuid := gen_random_uuid();
        a uuid := gen_random_uuid(); b uuid := gen_random_uuid(); c uuid := gen_random_uuid(); first jsonb; again jsonb; told_head int; told_head_again int; told_acad int; heads int; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', '00000000-0000-0000-0000-000000000000', true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        PERFORM set_config('moaum.reason', 'check V514', true);
        -- a department and programme with no Head on the portal, and another that gets one here
        SELECT p.code, p.dept_code INTO pn, dn FROM ref.programme p
         WHERE p.category = 'UNDER GRADUATE' AND NOT coalesce(p.archived, false) AND p.dept_code IS NOT NULL
           AND NOT EXISTS (SELECT 1 FROM registration.department_heads(p.dept_code)) ORDER BY p.code LIMIT 1;
        SELECT p.code, p.dept_code INTO pa, da FROM ref.programme p
         WHERE p.category = 'UNDER GRADUATE' AND NOT coalesce(p.archived, false) AND p.dept_code IS NOT NULL AND p.dept_code <> dn ORDER BY p.code LIMIT 1;
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (head, 'CHK/V514/H', 'Checkvfourteen', 'Head'), (acad, 'CHK/V514/A', 'Checkvfourteen', 'Academic');
        INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from) VALUES
            (gen_random_uuid(), head, 'hod', 'department', da, 'check V514', gen_random_uuid(), current_date - 1),
            (gen_random_uuid(), acad, 'academic', 'institution', NULL, 'check V514', gen_random_uuid(), current_date - 1);
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status) VALUES
            (a, 'MOAUM/ADM/99/951401', 'CHECKV514', 'Waiting', pa, 'UTME', ses, 100, 100, 'ADMITTED'),
            (b, 'MOAUM/ADM/99/951402', 'CHECKV514', 'No Head', pn, 'UTME', ses, 100, 100, 'ADMITTED'),
            (c, 'MOAUM/ADM/99/951403', 'CHECKV514', 'Today', pa, 'UTME', ses, 100, 100, 'ADMITTED');
        INSERT INTO registration.overload_request (student_id, session, semester, level, regular_max, requested_max, reason, requested_at) VALUES
            (a, ses, 1, 100, 24, 27, 'Check: waiting five days', now() - interval '5 days'),
            (b, ses, 1, 100, 24, 26, 'Check: no Head to decide', now() - interval '1 day'),
            (c, ses, 1, 100, 24, 25, 'Check: asked today', now());
        heads := (SELECT count(*) FROM registration.department_heads(da) h WHERE h = head);
        first := registration.remind_overloads(3);
        told_head := (SELECT count(*) FROM platform.notice x WHERE x.about_id = head AND x.template_key = 'OVERLOAD_WAITING');
        again := registration.remind_overloads(3);
        told_head_again := (SELECT count(*) FROM platform.notice x WHERE x.about_id = head AND x.template_key = 'OVERLOAD_WAITING');
        told_acad := (SELECT count(*) FROM platform.notice x WHERE x.about_id = acad AND x.template_key = 'OVERLOAD_NO_HEAD');
        RAISE EXCEPTION 'the V514 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V514 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V514: a request waiting past the days is reminded to its department''s Head once a day at most, one in a department with no Head is counted and told to the Academic Office; one of today waits',
        coalesce(heads = 1 AND (first->>'no_head')::int >= 1 AND told_head = 1 AND told_head_again = 1 AND told_acad = 1
                 AND (first->>'reminded_requests')::int >= 1, false),
        format('heads %s | first %s | again %s | told head %s then %s, academic %s', heads, first, again, told_head, told_head_again, told_acad));
END $$;

-- ── V515: the clearance in one pass agrees with the student's own ──
-- finance.session_clears_for gives, for the students named, what finance.clears gives each (a paid student cleared, an unpaid one
-- not), finance.session_clears the same for everyone, and the withheld list keeps the card's own code. The block undoes its writes.
DO $$
DECLARE ses text := '2398/2399'; sch uuid := gen_random_uuid(); prog text; a uuid := gen_random_uuid(); b uuid := gen_random_uuid(); ref text;
        one_a boolean; one_b boolean; each_a boolean; each_b boolean; all_a boolean; n int; agree boolean; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', '00000000-0000-0000-0000-000000000000', true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM set_config('moaum.reason', 'check V515', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), ses, DATE '2398-10-01', DATE '2399-08-31');
        SELECT p.code INTO prog FROM ref.programme p WHERE p.category = 'UNDER GRADUATE' AND NOT coalesce(p.archived, false) AND p.dept_code IS NOT NULL ORDER BY p.code LIMIT 1;
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status) VALUES
            (a, 'MOAUM/ADM/98/951501', 'CHECKV515', 'Paid', prog, 'UTME', ses, 100, 100, 'ADMITTED'),
            (b, 'MOAUM/ADM/98/951502', 'CHECKV515', 'Unpaid', prog, 'UTME', ses, 100, 100, 'ADMITTED');
        INSERT INTO finance.fee_schedule (session, item, amount, level, programme_code) VALUES (ses, 'School fees (check V515)', 40000, 100, prog);
        IF policy.in_force('clearance', 'UNIVERSITY', current_date) IS NULL THEN
            INSERT INTO policy.version (id, kind, scope, validity, instrument, decided_by) VALUES (sch, 'clearance', 'UNIVERSITY', daterange(current_date - 1, NULL), 'CHECK V515', 'bursar');
            INSERT INTO policy.clearance_scheme VALUES (sch, true);
            INSERT INTO policy.clearance_rule SELECT sch, p.code, CASE p.code WHEN 'HOSTEL' THEN 'NEVER_GATED' ELSE 'INSTALMENT_1' END FROM ref.clearance_purpose p;
        END IF;
        ref := finance.new_purpose_reference(a, ses, 40000, 'School fees ' || ses);
        PERFORM finance.confirm_payment(ref, 'BANK_BRANCH', 'teller for check V515');
        SELECT c.clears INTO one_a FROM finance.session_clears_for(ses, 'EXAMINATION', ARRAY[a, b]) c WHERE c.student_id = a;
        SELECT c.clears INTO one_b FROM finance.session_clears_for(ses, 'EXAMINATION', ARRAY[a, b]) c WHERE c.student_id = b;
        n := (SELECT count(*) FROM finance.session_clears_for(ses, 'EXAMINATION', ARRAY[a, b]));
        each_a := finance.clears(a, ses, 'EXAMINATION');
        each_b := finance.clears(b, ses, 'EXAMINATION');
        SELECT c.clears INTO all_a FROM finance.session_clears(ses, 'EXAMINATION') c WHERE c.student_id = a;
        agree := NOT EXISTS (SELECT 1 FROM finance.session_clears_or_null(ses, 'EXAMINATION', ARRAY[a, b]) c
                              WHERE c.clears IS DISTINCT FROM finance.clears_or_null(c.student_id, ses, 'EXAMINATION'));
        RAISE EXCEPTION 'the V515 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V515 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V515: the session''s clearance worked out at once for the students named agrees with each student''s own (paid cleared, unpaid not)',
        coalesce(n = 2 AND one_a AND NOT one_b AND one_a = each_a AND one_b = each_b AND all_a = each_a AND agree, false),
        format('n %s | one pass %s/%s | each %s/%s | all %s | agree %s', n, one_a, one_b, each_a, each_b, all_a, agree));
END $$;

-- ── V516: late registration by the Registry ──
-- With the window closed, the Registry registers a cleared student's own courses (the window set aside, every other rule held):
-- the registration is submitted, each entry names the Registry's reason, the late registration is recorded and the student told; a
-- course not on the student's list is blocked; another office, or no reason, is refused. The block undoes its writes.
DO $$
DECLARE ses text := '2400/2401'; sch uuid := gen_random_uuid(); prog text; dept text; st uuid := gen_random_uuid(); ref text; o1 uuid; o2 uuid; o3 uuid; oth uuid;
        win_aside boolean; win_blocks boolean; res jsonb; status text; reasons int; recorded int; told int; offlist text; wrong text; noreason text; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', '00000000-0000-0000-0000-000000000000', true);
        PERFORM set_config('moaum.actor_office', 'registrar', true);
        PERFORM set_config('moaum.reason', 'check V516', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), ses, DATE '2400-10-01', DATE '2401-08-31');
        SELECT p.code, p.dept_code INTO prog, dept FROM ref.programme p
         WHERE p.category = 'UNDER GRADUATE' AND NOT coalesce(p.archived, false) AND p.dept_code IS NOT NULL
           AND registration.siwes_units(p.code, 100, 1) IS NULL ORDER BY p.code LIMIT 1;
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status)
        VALUES (st, 'MOAUM/ADM/00/951601', 'CHECKV516', 'Late', prog, 'UTME', ses, 100, 100, 'ADMITTED');
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state) VALUES
            ('ZQL 101', 'Check Late One', 6, 1, 100, dept, 'Core', 'LIVE'), ('ZQL 102', 'Check Late Two', 6, 1, 100, dept, 'Core', 'LIVE'),
            ('ZQL 103', 'Check Late Three', 6, 1, 100, dept, 'Core', 'LIVE'), ('ZQL 199', 'Check Late Elsewhere', 3, 1, 100, dept, 'Core', 'LIVE');
        INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES ('ZQL 101', prog, 100, 'Core'), ('ZQL 102', prog, 100, 'Core'), ('ZQL 103', prog, 100, 'Core');
        INSERT INTO catalogue.offering (id, course_code, session, semester) SELECT gen_random_uuid(), c, ses, 1 FROM unnest(ARRAY['ZQL 101', 'ZQL 102', 'ZQL 103', 'ZQL 199']) c;
        SELECT id INTO o1 FROM catalogue.offering WHERE course_code = 'ZQL 101' AND session = ses;
        SELECT id INTO o2 FROM catalogue.offering WHERE course_code = 'ZQL 102' AND session = ses;
        SELECT id INTO o3 FROM catalogue.offering WHERE course_code = 'ZQL 103' AND session = ses;
        SELECT id INTO oth FROM catalogue.offering WHERE course_code = 'ZQL 199' AND session = ses;
        INSERT INTO finance.fee_schedule (session, item, amount, level, programme_code) VALUES (ses, 'School fees (check V516)', 30000, 100, prog);
        IF policy.in_force('clearance', 'UNIVERSITY', current_date) IS NULL THEN
            INSERT INTO policy.version (id, kind, scope, validity, instrument, decided_by) VALUES (sch, 'clearance', 'UNIVERSITY', daterange(current_date - 1, NULL), 'CHECK V516', 'bursar');
            INSERT INTO policy.clearance_scheme VALUES (sch, true);
            INSERT INTO policy.clearance_rule SELECT sch, p.code, CASE p.code WHEN 'HOSTEL' THEN 'NEVER_GATED' ELSE 'INSTALMENT_1' END FROM ref.clearance_purpose p;
        END IF;
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        ref := finance.new_purpose_reference(st, ses, 30000, 'School fees ' || ses);
        PERFORM finance.confirm_payment(ref, 'BANK_BRANCH', 'teller for check V516');
        PERFORM set_config('moaum.actor_office', 'ict', true);
        -- the semester's registration window opened, then closed: the student missed it
        PERFORM policy.window_act('COURSE_REGISTRATION', ses, 1, 'OPEN', NULL, NULL, NULL, false, 'check V516: window opened', '00000000-0000-0000-0000-000000000000', 'ict');
        PERFORM policy.window_act('COURSE_REGISTRATION', ses, 1, 'CLOSE', NULL, NULL, NULL, NULL, 'check V516: window closed', '00000000-0000-0000-0000-000000000000', 'ict');
        PERFORM set_config('moaum.actor_office', 'registrar', true);
        -- the window is set aside; nothing else blocks
        SELECT bool_or(c.set_aside) FILTER (WHERE c.rule = 'REGISTRATION_WINDOW'), bool_or(c.blocks) INTO win_aside, win_blocks
          FROM registration.registry_late_checks(st, ses, 1, o1) c;
        BEGIN PERFORM registration.registry_register(st, ses, 1, ARRAY[oth], 'Check: a course not on the student''s list'); offlist := 'REGISTERED';
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; offlist := split_part(msg, ':', 1); END;
        BEGIN PERFORM registration.registry_register(st, ses, 1, ARRAY[o1], 'too short'); noreason := 'REGISTERED';
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; noreason := split_part(msg, ':', 1); END;
        PERFORM set_config('moaum.actor_office', 'hod', true);
        BEGIN PERFORM registration.registry_register(st, ses, 1, ARRAY[o1], 'Check: a Head of Department tries'); wrong := 'REGISTERED';
        EXCEPTION WHEN insufficient_privilege THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; wrong := split_part(msg, ':', 1); END;
        PERFORM set_config('moaum.actor_office', 'registrar', true);
        res := registration.registry_register(st, ses, 1, ARRAY[o1, o2, o3], 'Check: admitted late by Senate''s decision');
        status := (SELECT r.status FROM registration.course_registration r WHERE r.id = (res->>'registrationId')::uuid);
        reasons := (SELECT count(*) FROM registration.entry e WHERE e.registration_id = (res->>'registrationId')::uuid AND e.support_override_reason LIKE 'Late registration by the Registry:%');
        recorded := (SELECT count(*) FROM registration.late_registration l WHERE l.student_id = st AND cardinality(l.offerings) = 3);
        told := (SELECT count(*) FROM platform.notice x WHERE x.about_id = st AND x.template_key = 'REG_LATE_BY_REGISTRY');
        RAISE EXCEPTION 'the V516 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V516 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V516: the Registry registers a cleared student late — the window set aside, every other rule held — recorded and told; a course off the list, another office and no reason refused',
        coalesce(win_aside AND NOT win_blocks AND offlist = 'REG_LATE_BLOCKED' AND noreason = 'REG_LATE_REASON' AND wrong = 'REG_LATE_OFFICE'
                 AND status IN ('SUBMITTED', 'APPROVED') AND (res->>'units')::int = 18 AND reasons = 3 AND recorded = 1 AND told = 1, false),
        format('window aside %s blocks %s | off list %s | no reason %s | hod %s | res %s status %s | reasons %s recorded %s told %s',
               win_aside, win_blocks, offlist, noreason, wrong, res, status, reasons, recorded, told));
END $$;

-- ── V517: the enrolment read for sponsors ──
-- A consumer holding students:enrolment learns, for a matriculation number and a session, that the student is in study,
-- registered (semester 1 submitted) and cleared or not by the Bursary — no amount; a consumer holding only students:status is
-- refused it; every call logged. The block undoes its writes.
DO $$
DECLARE ses text := '2401/2402'; prog text; st uuid := gen_random_uuid(); c uuid; c2 uuid; k text; k2 text; r jsonb; noscope jsonb; logged int; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', '00000000-0000-0000-0000-000000000000', true);
        PERFORM set_config('moaum.actor_office', 'ict', true);
        PERFORM set_config('moaum.reason', 'check V517', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), ses, DATE '2401-10-01', DATE '2402-08-31');
        SELECT p.code INTO prog FROM ref.programme p WHERE p.category = 'UNDER GRADUATE' AND NOT coalesce(p.archived, false) ORDER BY p.code LIMIT 1;
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (st, 'MOAUM/ADM/01/951701', 'CHK/V517/0001', 'CHECKVSEVENTEEN', 'Sponsored Student', prog, 'UTME', ses, 100, 100, 'ACTIVE', now());
        INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, submitted_at) VALUES (gen_random_uuid(), st, ses, 1, 100, 'SUBMITTED', now());
        c := apimgmt.register_consumer('Check sponsor', 'Check owner', 'students:enrolment', NULL);
        k := apimgmt.issue_key(c, 30);
        c2 := apimgmt.register_consumer('Check status only', 'Check owner', 'students:status', NULL);
        k2 := apimgmt.issue_key(c2, 30);
        r := apimgmt.student_enrolment(k, 'chk/v517/0001', ses, '127.0.0.1');
        noscope := apimgmt.student_enrolment(k2, 'CHK/V517/0001', ses, '127.0.0.1');
        logged := (SELECT count(*) FROM apimgmt.request_log l WHERE l.scope = 'students:enrolment' AND l.subject LIKE 'CHK/V517/0001%');
        RAISE EXCEPTION 'the V517 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V517 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V517: a sponsor with students:enrolment learns in study, registered (semesters) and the fee clearance — no amount; a key without the scope is refused; every call logged',
        coalesce(r->>'outcome' = 'OK' AND (r->'student'->>'in_study')::boolean AND (r->'student'->>'registered')::boolean
                 AND r->'student'->'semesters' = '[{"semester": 1, "status": "SUBMITTED"}]'::jsonb
                 AND r->'student'->>'fees_cleared_for_examination' IN ('CLEARED', 'NOT_CLEARED', 'UNKNOWN')
                 AND r->'student'->>'fees_cleared_for_registration' IN ('CLEARED', 'NOT_CLEARED', 'UNKNOWN') AND r->'student'->>'name' = 'CHECKVSEVENTEEN, S. S.'
                 AND NOT (r->'student' ? 'amount') AND NOT (r->'student' ? 'balance') AND noscope->>'outcome' = 'NO_SCOPE' AND logged = 2, false),
        format('r %s | noscope %s | logged %s', r, noscope, logged));
END $$;

-- ── V518: the save keeps only the semester's own courses ──
-- A student registered for a first-semester course saves the second semester with that course still in the selection (and a
-- course of another session): the save keeps the second semester's own course, leaves the others out, and refuses nothing. The
-- block undoes its writes.
DO $$
DECLARE ses text := '2402/2403'; other text := '2403/2404'; prog text; dept text; st uuid := gen_random_uuid(); o1 uuid; o2 uuid; o3 uuid;
        r1 uuid; r2 uuid; u2 int; codes text; refused text; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', '00000000-0000-0000-0000-000000000000', true);
        PERFORM set_config('moaum.actor_office', 'academic', true);
        PERFORM set_config('moaum.reason', 'check V518', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES
            (gen_random_uuid(), ses, DATE '2402-10-01', DATE '2403-08-31'), (gen_random_uuid(), other, DATE '2403-10-01', DATE '2404-08-31');
        SELECT p.code, p.dept_code INTO prog, dept FROM ref.programme p
         WHERE p.category = 'UNDER GRADUATE' AND NOT coalesce(p.archived, false) AND p.dept_code IS NOT NULL
           AND registration.siwes_units(p.code, 100, 1) IS NULL AND registration.siwes_units(p.code, 100, 2) IS NULL ORDER BY p.code LIMIT 1;
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status)
        VALUES (st, 'MOAUM/ADM/02/951801', 'CHECKV518', 'Two Semesters', prog, 'UTME', ses, 100, 100, 'ADMITTED');
        INSERT INTO catalogue.course (code, title, units, semester, level, dept_code, kind, state) VALUES
            ('ZQS 101', 'Check Semester One', 3, 1, 100, dept, 'Core', 'LIVE'), ('ZQS 102', 'Check Semester Two', 3, 2, 100, dept, 'Core', 'LIVE');
        INSERT INTO catalogue.course_offer (course_code, programme_code, level, basis) VALUES ('ZQS 101', prog, 100, 'Core'), ('ZQS 102', prog, 100, 'Core');
        INSERT INTO catalogue.offering (id, course_code, session, semester) VALUES (gen_random_uuid(), 'ZQS 101', ses, 1), (gen_random_uuid(), 'ZQS 102', ses, 2),
            (gen_random_uuid(), 'ZQS 102', other, 2);
        SELECT id INTO o1 FROM catalogue.offering WHERE course_code = 'ZQS 101' AND session = ses;
        SELECT id INTO o2 FROM catalogue.offering WHERE course_code = 'ZQS 102' AND session = ses;
        SELECT id INTO o3 FROM catalogue.offering WHERE course_code = 'ZQS 102' AND session = other;
        r1 := registration.student_draft(st, ses, 1);
        PERFORM registration.student_choose(r1, ARRAY[o1]);
        r2 := registration.student_draft(st, ses, 2);
        BEGIN
            u2 := registration.student_choose(r2, ARRAY[o1, o2, o3]);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; refused := split_part(msg, ':', 1);
        END;
        codes := (SELECT string_agg(o.course_code || '/' || o.semester, ',' ORDER BY o.course_code) FROM registration.entry e JOIN catalogue.offering o ON o.id = e.offering_id
                   WHERE e.registration_id = r2 AND e.status <> 'DROPPED');
        RAISE EXCEPTION 'the V518 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V518 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V518: a second-semester save that still carries the first semester''s course (and another session''s) keeps only its own, refusing nothing',
        coalesce(refused IS NULL AND u2 = 3 AND codes = 'ZQS 102/2', false),
        format('refused %s | units %s | entries %s', refused, u2, codes));
END $$;
-- ── V519. The overpaid are told, and every overpaid student is listed. In a session charged ₦100,000: one student overpaid ₦20,000
--          through old-portal payments, one ₦30,000 through two portal payments (no old-portal payment at all), one exactly.
--          Both overpaid are listed (old_portal telling them apart); the first carried and told so, the second refunded and
--          told the refund was raised, then told when the refunds desk paid it; each sees the decision on the fees page.
--          The block undoes its writes ──
DO $$
DECLARE who uuid := gen_random_uuid(); second uuid := gen_random_uuid(); s1 uuid := gen_random_uuid(); s2 uuid := gen_random_uuid();
        s3 uuid := gen_random_uuid(); a text := '9979/9980'; b text := '9980/9981'; pa text; listed text; told_carry text; told_raised text;
        told_paid text; rf uuid; mine1 text; mine2 text; once int; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM set_config('moaum.reason', 'check V519', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES
            (gen_random_uuid(), a, date '9979-10-01', date '9980-08-31'), (gen_random_uuid(), b, date '9980-10-01', date '9981-08-31')
        ON CONFLICT (name) DO NOTHING;
        SELECT code INTO pa FROM ref.programme WHERE NOT coalesce(archived, false) ORDER BY code LIMIT 1;
        INSERT INTO finance.fee_schedule (session, item, amount, level, programme_code, kind) VALUES (a, 'School fees', 100000, NULL, pa, 'FEE'), (b, 'School fees', 100000, NULL, pa, 'FEE');
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at) VALUES
          (s1, 'MOAUM/ADM/79/979101', 'MOAUM/CHK/79/9791', 'ZZCHKV519A', 'Invented', pa, 'UTME', a, 100, 100, 'ACTIVE', now()),
          (s2, 'MOAUM/ADM/79/979102', 'MOAUM/CHK/79/9792', 'ZZCHKV519B', 'Invented', pa, 'UTME', a, 100, 100, 'ACTIVE', now()),
          (s3, 'MOAUM/ADM/79/979103', 'MOAUM/CHK/79/9793', 'ZZCHKV519C', 'Invented', pa, 'UTME', a, 100, 100, 'ACTIVE', now());
        INSERT INTO people.student_contact (student_id, email, phone, updated_at) VALUES
          (s1, 'zzchkv519a@example.invalid', NULL, now()), (s2, 'zzchkv519b@example.invalid', NULL, now());
        INSERT INTO finance.payment_reference (student_id, session, reference, purpose, amount, expires_at, confirmed_at, confirmed_by, channel, receipt_no, note)
        SELECT v.s, a, v.ref, v.purpose, v.amount, v.day::timestamptz, v.day::timestamptz, who, v.channel, 'RCT-' || v.ref, 'check V519'
          FROM (VALUES (s1, 'MOAUM-LEG-MOAUMCHK799791-9979-9980-S1', 'School fees (legacy) · semester 1', 120000.00, '9979-11-02', 'Legacy'),
                       (s2, 'MOAUM-CHKV519-B-1', 'School fees 9979/9980', 70000.00, '9979-11-03', 'INTERSWITCH'),
                       (s2, 'MOAUM-CHKV519-B-2', 'School fees 9979/9980', 60000.00, '9979-11-05', 'INTERSWITCH'),
                       (s3, 'MOAUM-LEG-MOAUMCHK799793-9979-9980-S1', 'School fees (legacy) · semester 1', 100000.00, '9979-11-04', 'Legacy')) v(s, ref, purpose, amount, day, channel);

        listed := (SELECT string_agg(x.number || ':' || x.excess::int || ':' || x.old_portal, ',' ORDER BY x.number COLLATE "C")
                     FROM finance.overpaid(a) x WHERE x.student_id IN (s1, s2, s3));
        PERFORM * FROM finance.decide_overpayments(a, 'CARRY', ARRAY[s1], 'CHECK V519: carried into the next session');
        told_carry := (SELECT string_agg(n.channel || ':' || n.subject, ',' ORDER BY n.channel) FROM platform.notice n
                        WHERE n.template_key = 'OVERPAYMENT_CARRIED' AND n.about_id = s1);
        PERFORM * FROM finance.decide_overpayments(a, 'REFUND', ARRAY[s2], 'CHECK V519: refunded to the student');
        told_raised := (SELECT string_agg(n.channel || ':' || n.subject, ',' ORDER BY n.channel) FROM platform.notice n
                         WHERE n.template_key = 'OVERPAYMENT_REFUND_RAISED' AND n.about_id = s2);
        -- the refunds desk: approved by a second officer, then paid (V533: into the account the student gave)
        SELECT f.id INTO rf FROM finance.refund f WHERE f.student_id = s2;
        PERFORM set_config('moaum.actor_id', second::text, true);
        PERFORM finance.approve_refund(rf);
        PERFORM finance.give_refund_account(s2, (SELECT f.reference FROM finance.refund f WHERE f.id = rf), 'First Bank', 'ZZCHKV519B Invented', '0000014579');
        PERFORM finance.pay_refund(rf, 'CHK-TRF-PAID', (now() AT TIME ZONE 'Africa/Lagos')::date);
        told_paid := (SELECT string_agg(n.channel || ':' || n.subject, ',' ORDER BY n.channel) FROM platform.notice n
                       WHERE n.template_key = 'OVERPAYMENT_REFUND_PAID' AND n.about_id = s2);
        once := (SELECT count(*) FROM platform.notice n WHERE n.template_key LIKE 'OVERPAYMENT_%' AND n.about_id IN (s1, s2) AND n.channel = 'EMAIL');
        mine1 := (SELECT string_agg(x.decision || ':' || coalesce(x.to_session, '-') || ':' || x.amount::int || ':' || coalesce(x.refund_state, '-'), ',') FROM finance.student_overpayments(s1) x);
        mine2 := (SELECT string_agg(x.decision || ':' || coalesce(x.to_session, '-') || ':' || x.amount::int || ':' || coalesce(x.refund_state, '-'), ',') FROM finance.student_overpayments(s2) x);
        RAISE EXCEPTION 'the V519 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V519 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V519: every overpaid student of a session is listed (old-portal or portal payments), and the student is told when the excess is carried, when a refund is raised and when it is paid, and sees it on the fees page',
        coalesce(listed = 'MOAUM/CHK/79/9791:20000:true,MOAUM/CHK/79/9792:30000:false'
                 AND told_carry LIKE '%EMAIL:Your overpaid 9979/9980 school fees count towards 9980/9981%'
                 AND told_raised LIKE '%EMAIL:A refund of your overpaid 9979/9980 school fees has been raised%'
                 AND told_paid LIKE '%EMAIL:Your refund of NGN 30,000.00 has been paid%' AND once = 3
                 AND mine1 = 'CARRY:9980/9981:20000:-' AND mine2 = 'REFUND:-:30000:PAID', false),
        format('listed %s | carried %s | raised %s | paid %s | e-mails %s | fees page %s / %s', listed, told_carry, told_raised, told_paid, once, mine1, mine2));
END $$;
-- ── V521: ICT Support opens the student's portal, read-only ──
-- Every agent in service holds the capability; the portal is opened by ICT Support alone, with a reason, as a portal session of the
-- student's that ends after its minutes, on the support ledger and the view's log; a merged record is not opened; another agent does
-- not end the view, the agent who opened it does, and the portal session ends with it. The block undoes its writes.
DO $$
DECLARE st uuid := gen_random_uuid(); merged uuid := gen_random_uuid(); a1 uuid := gen_random_uuid(); a2 uuid := gen_random_uuid();
        sid bytea := gen_random_bytes(32); sid2 bytea := gen_random_bytes(32); msg text; prog text;
        opened jsonb; by_bursar text; short_reason text; merged_refused text; by_other text; ended boolean; session_ended boolean; ledger int; minutes int;
        in_baseline boolean;
BEGIN
    BEGIN
        PERFORM set_config('moaum.reason', 'check V521', true);
        PERFORM set_config('moaum.actor_id', a1::text, true);
        PERFORM set_config('moaum.actor_office', 'ict', true);
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES (a1, 'CHK-V521-A1', 'CHECKV521', 'AgentOne'), (a2, 'CHK-V521-A2', 'CHECKV521', 'AgentTwo');
        SELECT code INTO prog FROM ref.programme WHERE category = 'UNDER GRADUATE' AND NOT coalesce(archived, false) ORDER BY code LIMIT 1;
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status) VALUES
            (st, 'MOAUM/ADM/97/970521', 'CHECKV521', 'Viewed', prog, 'UTME', '2020/2021', 100, 100, 'ADMITTED'),
            (merged, 'MOAUM/ADM/97/970522', 'CHECKV521', 'Merged', prog, 'UTME', '2020/2021', 100, 100, 'ADMITTED');
        UPDATE people.student SET duplicate_of = st WHERE id = merged;
        in_baseline := 'VIEW_STUDENT_PORTAL' = ANY (helpdesk.agent_baseline()) AND 'VIEW_STUDENT_PORTAL' = ANY (helpdesk.support_capabilities());
        -- another office is refused
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        BEGIN PERFORM helpdesk.open_portal_view(st, NULL, 'Checking the student''s portal', sid, 30); by_bursar := 'OPENED';
        EXCEPTION WHEN insufficient_privilege THEN by_bursar := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_office', 'ictagent', true);
        BEGIN PERFORM helpdesk.open_portal_view(st, NULL, 'short', sid, 30); short_reason := 'OPENED';
        EXCEPTION WHEN check_violation THEN short_reason := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM helpdesk.open_portal_view(merged, NULL, 'Checking the student''s portal', sid2, 30); merged_refused := 'OPENED';
        EXCEPTION WHEN check_violation THEN merged_refused := split_part(SQLERRM, ':', 1); END;
        opened := helpdesk.open_portal_view(st, NULL, 'The student says the registration page shows no courses', sid, 30);
        minutes := (SELECT round(extract(epoch FROM absolute_end - issued_at) / 60) FROM platform.session WHERE id = sid AND person_id = st AND active_office = 'student');
        ledger := (SELECT count(*) FROM helpdesk.support_action WHERE student_id = st AND action = 'STUDENT_PORTAL_VIEWED' AND agent_id = a1);
        -- another agent does not end it
        PERFORM set_config('moaum.actor_id', a2::text, true);
        BEGIN PERFORM helpdesk.end_portal_view((opened->>'viewId')::uuid); by_other := 'ENDED';
        EXCEPTION WHEN insufficient_privilege THEN by_other := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_id', a1::text, true);
        ended := helpdesk.end_portal_view((opened->>'viewId')::uuid);
        session_ended := (SELECT ended_at IS NOT NULL FROM platform.session WHERE id = sid);
        RAISE EXCEPTION 'the V521 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V521 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V521: ICT Support alone opens a student''s portal, with a reason, as a portal session of the student''s that ends after its minutes, on the ledger; never a merged record; another agent does not end it, the agent does and the session ends',
        coalesce(in_baseline AND by_bursar = 'SUPPORT_VIEW_OFFICE' AND short_reason = 'SUPPORT_VIEW_REASON' AND merged_refused = 'SUPPORT_VIEW_MERGED'
                 AND opened ? 'viewId' AND minutes = 30 AND ledger = 1 AND by_other = 'SUPPORT_VIEW_NOT_YOURS' AND ended AND session_ended, false),
        format('baseline %s | bursar %s | short %s | merged %s | opened %s, %s min, ledger %s | other %s | ended %s, session %s',
               in_baseline, by_bursar, short_reason, merged_refused, opened ? 'viewId', minutes, ledger, by_other, ended, session_ended));
END $$;

-- ── V522: the hanging-payment and fee-gap alerts reach the Students Account Officer too ──
-- A Students Account Officer, a Bursary office holder and the holder of another office: a Pay on Quickteller payment unreported
-- after a day and a live undergraduate of a session whose open semester has no fee line. The officer is told of both, as the
-- Bursar is; the other office is told of neither. The block undoes its writes.
DO $$
DECLARE who uuid := gen_random_uuid(); sao uuid := gen_random_uuid(); bur uuid := gen_random_uuid(); oth uuid := gen_random_uuid();
        st uuid := gen_random_uuid(); payer uuid := gen_random_uuid(); v_ses text := '9939/9940'; v_prog text; v_any text;
        at10 timestamptz := (date_trunc('day', now() AT TIME ZONE 'Africa/Lagos') + interval '10 hours') AT TIME ZONE 'Africa/Lagos';
        unrep_sao int; unrep_bur int; unrep_oth int; gaps_sao int; gaps_bur int; gaps_oth int; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM set_config('moaum.reason', 'check V522', true);
        UPDATE finance.paydirect_setting SET watch_enabled = true;
        INSERT INTO iam.person (id, surname, given_names, email) VALUES
            (sao, 'CHECKV522', 'Students Account Officer', 'zz.check522.sao@example.com'),
            (bur, 'CHECKV522', 'Bursar', 'zz.check522.bur@example.com'),
            (oth, 'CHECKV522', 'Registrar', 'zz.check522.reg@example.com');
        INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from) VALUES
            (gen_random_uuid(), sao, 'studentaccounts', 'institution', NULL, 'check V522', who, current_date - 1),
            (gen_random_uuid(), bur, 'bursar', 'institution', NULL, 'check V522', who, current_date - 1),
            (gen_random_uuid(), oth, 'registrar', 'institution', NULL, 'check V522', who, current_date - 1);
        -- a Pay on Quickteller payment opened 30 hours before 10:00 and not reported
        v_any := (SELECT name FROM policy.academic_session ORDER BY name LIMIT 1);
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status)
        VALUES (payer, 'MOAUM/ADM/60/952201', 'CHECKV522', 'Payer', (SELECT code FROM ref.programme WHERE NOT coalesce(archived, false) ORDER BY code LIMIT 1), 'UTME', v_any, 100, 100, 'ADMITTED');
        INSERT INTO finance.payment_reference (student_id, session, reference, purpose, amount, expires_at)
        VALUES (payer, v_any, 'MOAUM-FEE-952201-0001', 'check V522', 52200.00, now() + interval '30 days');
        INSERT INTO finance.gateway_attempt (reference, gateway, kind, account_id, opened_at)
        VALUES ('MOAUM-FEE-952201-0001', 'paydirect', 'FEE', payer, at10 - interval '30 hours');
        PERFORM finance.watch_paydirect_unreported(at10);
        -- a live undergraduate whose open semester has no fee line
        SELECT p.code INTO v_prog FROM ref.programme p
         WHERE NOT coalesce(p.archived, false) AND coalesce(p.category, '') <> 'POST GRADUATE' AND p.faculty_code IS NOT NULL
           AND p.faculty_code NOT IN (SELECT r.faculty_code FROM finance.faculty_fee_source r)
         ORDER BY p.code LIMIT 1;
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), v_ses, date '9939-10-01', date '9940-08-31') ON CONFLICT (name) DO NOTHING;
        INSERT INTO policy.semester (id, session, number, state) VALUES (gen_random_uuid(), v_ses, 1, 'OPEN')
            ON CONFLICT (session, number) DO UPDATE SET state = excluded.state;
        INSERT INTO finance.fee_schedule (session, item, amount, level, semester) VALUES (v_ses, 'Check V522: another level', 1000, 900, 1);
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, study_mode, entry_session, entry_level, current_level, status)
        VALUES (st, 'MOAUM/ADM/39/952202', 'CHECKV522', 'No Fee', v_prog, 'UTME', 'FULL_TIME', v_ses, 100, 100, 'ADMITTED');
        PERFORM finance.watch_fee_gaps(v_ses);
        SELECT count(*) FILTER (WHERE n.about_id = sao), count(*) FILTER (WHERE n.about_id = bur), count(*) FILTER (WHERE n.about_id = oth)
          INTO unrep_sao, unrep_bur, unrep_oth
          FROM platform.notice n WHERE n.about_kind = 'person' AND n.template_key = 'PAYDIRECT_UNREPORTED' AND n.about_id IN (sao, bur, oth);
        SELECT count(*) FILTER (WHERE n.about_id = sao), count(*) FILTER (WHERE n.about_id = bur), count(*) FILTER (WHERE n.about_id = oth)
          INTO gaps_sao, gaps_bur, gaps_oth
          FROM platform.notice n WHERE n.about_kind = 'person' AND n.template_key = 'FEE_GAPS' AND n.about_id IN (sao, bur, oth)
           AND n.event_key LIKE 'fee-gaps:' || v_ses || ':%';
        RAISE EXCEPTION 'the V522 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V522 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V522: the Students Account Officer is told of unreported Quickteller payments and of students with no fee stated, as the Bursar is; another office is not',
        coalesce(unrep_sao > 0 AND unrep_bur > 0 AND unrep_oth = 0 AND gaps_sao > 0 AND gaps_bur > 0 AND gaps_oth = 0, false),
        format('unreported: officer %s, bursar %s, other %s | no fee stated: officer %s, bursar %s, other %s', unrep_sao, unrep_bur, unrep_oth, gaps_sao, gaps_bur, gaps_oth));
END $$;

-- ── V523: the export log ──
-- A lecturer exports a report: it is recorded for the person and the office acting (not what the screen says), with the report,
-- format, rows, filters, screen and serial, and the audit spine holds the entry; the log is not changed or emptied; an export with
-- no one acting, or in another format, is refused. The block undoes its writes.
DO $$
DECLARE who uuid := gen_random_uuid(); id1 uuid; got text; spine int; upd text; del text; noactor text; badfmt text; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'lecturer', true);
        id1 := platform.log_export('  Class list — BIO 101 ', 'xlsx', 42, '{"Session": "2025/2026", "Course": "BIO 101"}'::jsonb,
                                   '/lecturer/classes?course=BIO%20101', 'MOAUM/CLS/20261017/101500-07');
        SELECT format('%s|%s|%s|%s|%s|%s|%s|%s', l.person_id = who, l.office, l.report, l.format, l.row_count, l.filters->>'Course', l.screen, l.serial)
          INTO got FROM platform.export_log l WHERE l.id = id1;
        SELECT count(*) INTO spine FROM audit.entries e WHERE e.subject_id = id1 AND e.actor_id = who AND e.actor_office = 'lecturer';
        BEGIN UPDATE platform.export_log SET row_count = 1 WHERE id = id1;
        EXCEPTION WHEN insufficient_privilege THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; upd := split_part(msg, ':', 1); END;
        BEGIN DELETE FROM platform.export_log WHERE id = id1;
        EXCEPTION WHEN insufficient_privilege THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; del := split_part(msg, ':', 1); END;
        BEGIN PERFORM platform.log_export('Payments', 'DOCX', 1, '{}'::jsonb, NULL, NULL);   -- V529: CSV and PDF are kept; DOCX is not
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; badfmt := split_part(msg, ':', 1); END;
        PERFORM set_config('moaum.actor_id', '', true);
        BEGIN PERFORM platform.log_export('Payments', 'PRINT', 1, '{}'::jsonb, NULL, NULL);
        EXCEPTION WHEN insufficient_privilege THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; noactor := split_part(msg, ':', 1); END;
        RAISE EXCEPTION 'the V523 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V523 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V523: an export is recorded for the person and office acting, with its report, rows, filters and serial, on the audit spine; the log is append-only',
        coalesce(got = 't|lecturer|Class list — BIO 101|XLSX|42|BIO 101|/lecturer/classes?course=BIO%20101|MOAUM/CLS/20261017/101500-07'
                 AND spine = 1 AND upd = 'EXPORT_LOG_APPEND_ONLY' AND del = 'EXPORT_LOG_APPEND_ONLY'
                 AND badfmt = 'EXPORT_LOG_FORMAT' AND noactor = 'EXPORT_LOG_NO_ACTOR', false),
        format('row %s | spine %s | update %s | delete %s | csv %s | no actor %s', got, spine, upd, del, badfmt, noactor));
END $$;

-- ── V524: the unpaid registrations read once for each fee profile agree with each registration's own ──
-- Two students of one profile (one paid, one not) and one of another level with no fee stated, each on a submitted registration:
-- the unpaid list names the unpaid and the unstated, not the paid, and for every registration of the session it agrees with
-- finance.semester_cleared, finance.fee_stated and finance.due_for_semester of the student; the session's charges read at once
-- (finance.session_charges, the Records fees view's wide read) agree with each student's own. The block undoes its writes.
DO $$
DECLARE ses text := '2410/2411'; prog text; a uuid := gen_random_uuid(); b uuid := gen_random_uuid(); c uuid := gen_random_uuid(); ref text;
        has_a boolean; has_b boolean; has_c boolean; b_row text; c_row text; b_ok boolean; c_ok boolean; charges_agree boolean; disagree int; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', '00000000-0000-0000-0000-000000000000', true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM set_config('moaum.reason', 'check V524', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), ses, DATE '2410-10-01', DATE '2411-08-31');
        SELECT p.code INTO prog FROM ref.programme p WHERE p.category = 'UNDER GRADUATE' AND NOT coalesce(p.archived, false) AND p.dept_code IS NOT NULL ORDER BY p.code LIMIT 1;
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status) VALUES
            (a, 'MOAUM/ADM/98/952401', 'CHECKV524', 'Paid', prog, 'UTME', ses, 100, 100, 'ADMITTED'),
            (b, 'MOAUM/ADM/98/952402', 'CHECKV524', 'Unpaid', prog, 'UTME', ses, 100, 100, 'ADMITTED'),
            (c, 'MOAUM/ADM/98/952403', 'CHECKV524', 'Unstated', prog, 'UTME', ses, 100, 200, 'ADMITTED');
        INSERT INTO finance.fee_schedule (session, item, amount, level, programme_code) VALUES (ses, 'School fees (check V524)', 40000, 100, prog);
        ref := finance.new_purpose_reference(a, ses, 40000, 'School fees ' || ses);
        PERFORM finance.confirm_payment(ref, 'BANK_BRANCH', 'teller for check V524');
        INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, submitted_at) VALUES
            (gen_random_uuid(), a, ses, 1, 100, 'SUBMITTED', now()),
            (gen_random_uuid(), b, ses, 1, 100, 'SUBMITTED', now()),
            (gen_random_uuid(), c, ses, 1, 200, 'SUBMITTED', now());
        has_a := EXISTS (SELECT 1 FROM finance.registrations_without_fees(ses) x WHERE x.student_id = a);
        has_b := EXISTS (SELECT 1 FROM finance.registrations_without_fees(ses) x WHERE x.student_id = b);
        has_c := EXISTS (SELECT 1 FROM finance.registrations_without_fees(ses) x WHERE x.student_id = c);
        SELECT format('%s/%s/%s', x.stated, x.due, x.paid), x.stated AND x.due = 40000 AND x.paid = 0 INTO b_row, b_ok FROM finance.registrations_without_fees(ses) x WHERE x.student_id = b;
        SELECT format('%s/%s/%s', x.stated, x.due, x.paid), NOT x.stated AND x.due IS NULL AND x.paid = 0 INTO c_row, c_ok FROM finance.registrations_without_fees(ses) x WHERE x.student_id = c;
        SELECT count(*) INTO disagree
          FROM registration.course_registration r
          LEFT JOIN finance.registrations_without_fees(ses) x ON x.registration_id = r.id
         WHERE r.session = ses AND r.status IN ('SUBMITTED', 'APPROVED', 'LOCKED')
           AND ((x.registration_id IS NOT NULL) IS DISTINCT FROM NOT finance.semester_cleared(r.student_id, ses, r.semester)
                OR (x.registration_id IS NOT NULL AND (x.stated IS DISTINCT FROM finance.fee_stated(r.student_id, ses)
                    OR x.due IS DISTINCT FROM CASE WHEN x.stated THEN finance.due_for_semester(r.student_id, ses, r.semester) END)));
        charges_agree := NOT EXISTS (
            SELECT 1 FROM unnest(ARRAY[a, b, c]) x(id) LEFT JOIN finance.session_charges(ses) sc ON sc.student_id = x.id
             WHERE coalesce(sc.total, 0) <> (SELECT coalesce(sum(ch.amount), 0) FROM finance.charges(x.id, ses) ch));
        RAISE EXCEPTION 'the V524 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V524 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V524: the unpaid registrations read once for each fee profile name the unpaid and the unstated, not the paid, and agree with each registration''s own clearance, statement and due; the session''s charges agree',
        coalesce(NOT has_a AND has_b AND has_c AND b_ok AND c_ok AND disagree = 0 AND charges_agree, false),
        format('paid %s | unpaid %s %s | unstated %s %s | disagree %s | charges agree %s', has_a, has_b, b_row, has_c, c_row, disagree, charges_agree));
END $$;
-- ── V526. ICT Support's student password resets have no hourly limit unless the Director of ICT states one: the desk's
--          setting is empty (no limit), a limit may still be stated (1 to 500), and a limit outside that is refused. The block
--          undoes its writes ──
DO $$
DECLARE now_limit int; nullable boolean; stated int; refused boolean := false; msg text;
BEGIN
    SELECT g.student_reset_hourly INTO now_limit FROM helpdesk.setting g WHERE g.row_no;
    nullable := (SELECT c.is_nullable = 'YES' FROM information_schema.columns c
                  WHERE c.table_schema = 'helpdesk' AND c.table_name = 'setting' AND c.column_name = 'student_reset_hourly');
    BEGIN
        PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
        PERFORM set_config('moaum.actor_office', 'ict', true);
        PERFORM set_config('moaum.reason', 'check V526', true);
        UPDATE helpdesk.setting SET student_reset_hourly = 40 WHERE row_no;
        SELECT g.student_reset_hourly INTO stated FROM helpdesk.setting g WHERE g.row_no;
        BEGIN
            UPDATE helpdesk.setting SET student_reset_hourly = 0 WHERE row_no;
        EXCEPTION WHEN check_violation THEN refused := true;
        END;
        RAISE EXCEPTION 'the V526 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V526 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V526: ICT Support''s student password resets have no hourly limit unless one is stated (1 to 500)',
        coalesce(now_limit IS NULL AND nullable AND stated = 40 AND refused, false),
        format('limit now %s | nullable %s | stated %s | 0 refused %s', coalesce(now_limit::text, 'none'), nullable, stated, refused));
END $$;
-- ── V527: school fees payment swap ──
-- A verified school-fees payment credited to student A is swapped to student B: only a confirmed school-fees payment, between two
-- distinct students, with a reason and the confirmation; another officer decides (never the initiator, never the Students Account
-- Officer); approved, the credit moves and nothing else — reference, amount and confirmation unchanged, A's paid down and B's up by
-- the amount, the session's school fees received unchanged — with the whole timeline; the payment is not swapped twice; a reversal
-- takes it back and marks the swap REVERSED. The block undoes its writes.
DO $$
DECLARE S text := '2471/2472'; prog text; o1 uuid := gen_random_uuid(); o2 uuid := gen_random_uuid(); o3 uuid := gen_random_uuid();
        a uuid := gen_random_uuid(); b uuid := gen_random_uuid(); ref text; hostel text; pending text; pay uuid; sw uuid; rv uuid; msg text;
        ok_check boolean; same text; not_fees text; not_verified text; short_reason text; no_confirm text; open_again text; self_decide text;
        sao_decide text; done jsonb; a_paid numeric; b_paid numeric; owner uuid; unchanged boolean; events text; twice text; back jsonb;
        owner_back uuid; first_status text; swaps_a int; fc text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.reason', 'check V527', true);
        PERFORM set_config('moaum.actor_id', o2::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        INSERT INTO iam.person (id, staff_number, surname, given_names) VALUES
            (o1, 'CHK-V527-1', 'CHECKV527', 'Accounts'), (o2, 'CHK-V527-2', 'CHECKV527', 'Bursar'), (o3, 'CHK-V527-3', 'CHECKV527', 'Deputy');
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, DATE '2471-10-01', DATE '2472-08-31');
        SELECT code INTO prog FROM ref.programme WHERE category = 'UNDER GRADUATE' AND NOT coalesce(archived, false) ORDER BY code LIMIT 1;
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status) VALUES
            (a, 'MOAUM/ADM/00/990271', 'CHECKV527', 'Credited', prog, 'UTME', S, 100, 100, 'ADMITTED'),
            (b, 'MOAUM/ADM/00/990272', 'CHECKV527', 'Owner', prog, 'UTME', S, 100, 100, 'ADMITTED');
        INSERT INTO finance.fee_schedule (session, item, amount, level, programme_code) VALUES (S, 'School fees (check V527)', 300000, 100, prog);
        ref := finance.new_purpose_reference(a, S, 200000, 'School fees ' || S);
        PERFORM finance.confirm_payment(ref, 'BANK_BRANCH', 'teller for check V527');
        SELECT id INTO pay FROM finance.payment_reference WHERE reference = ref;
        hostel := finance.new_purpose_reference(a, S, 5000, 'Hostel fee ' || S);
        PERFORM finance.confirm_payment(hostel, 'BANK_BRANCH', 'teller for check V527');
        pending := finance.new_purpose_reference(a, S, 1000, 'School fees ' || S);
        ok_check := (finance.payment_swap_check(pay, b)->>'ok')::boolean;
        same := split_part(finance.payment_swap_check(pay, a)->'refusals'->>0, ':', 1);
        not_fees := split_part(finance.payment_swap_check((SELECT id FROM finance.payment_reference WHERE reference = hostel), b)->'refusals'->>0, ':', 1);
        not_verified := split_part(finance.payment_swap_check((SELECT id FROM finance.payment_reference WHERE reference = pending), b)->'refusals'->>0, ':', 1);
        -- initiated by the Students Account Officer: a reason and the confirmation
        PERFORM set_config('moaum.actor_id', o1::text, true);
        PERFORM set_config('moaum.actor_office', 'studentaccounts', true);
        BEGIN PERFORM finance.initiate_payment_swap(pay, b, 'wrong', NULL, true); short_reason := 'MADE';
        EXCEPTION WHEN check_violation THEN short_reason := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM finance.initiate_payment_swap(pay, b, 'Student B paid on student A''s account; teller confirmed', NULL, false); no_confirm := 'MADE';
        EXCEPTION WHEN check_violation THEN no_confirm := split_part(SQLERRM, ':', 1); END;
        sw := finance.initiate_payment_swap(pay, b, 'Student B paid on student A''s account; teller confirmed', 'Teller 0042', true);
        BEGIN PERFORM finance.initiate_payment_swap(pay, b, 'Student B paid on student A''s account; teller confirmed', NULL, true); open_again := 'MADE';
        EXCEPTION WHEN check_violation THEN open_again := split_part(SQLERRM, ':', 1); END;
        -- never decided by the officer who initiated it, nor by the Students Account Officer
        BEGIN PERFORM finance.decide_payment_swap(sw, true, NULL, true); sao_decide := 'DECIDED';
        EXCEPTION WHEN insufficient_privilege THEN sao_decide := split_part(SQLERRM, ':', 1); END;
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        BEGIN PERFORM finance.decide_payment_swap(sw, true, NULL, true); self_decide := 'DECIDED';
        EXCEPTION WHEN insufficient_privilege THEN self_decide := split_part(SQLERRM, ':', 1); END;
        -- the Bursar approves: executed at once
        PERFORM set_config('moaum.actor_id', o2::text, true);
        done := finance.decide_payment_swap(sw, true, 'Teller seen', true);
        SELECT student_id, (reference = ref AND amount = 200000 AND confirmed_at IS NOT NULL) INTO owner, unchanged FROM finance.payment_reference WHERE id = pay;
        a_paid := (finance.position(a, S)).paid;
        b_paid := (finance.position(b, S)).paid;
        events := (SELECT string_agg(action, ',' ORDER BY at, action) FROM finance.payment_swap_event WHERE swap_id = sw);
        BEGIN PERFORM finance.initiate_payment_swap(pay, a, 'Trying to swap the same payment again to see the refusal', NULL, true); twice := 'MADE';
        EXCEPTION WHEN check_violation THEN twice := split_part(SQLERRM, ':', 1); END;
        -- the College's Finance Controller neither initiates nor decides a swap
        PERFORM set_config('moaum.actor_office', 'financecontroller', true);
        BEGIN PERFORM finance.initiate_payment_swap(pay, a, 'The College Finance Controller tries to swap it back again', NULL, true); fc := 'MADE';
        EXCEPTION WHEN insufficient_privilege THEN fc := split_part(SQLERRM, ':', 1); END;
        -- the reversal, by the Bursar, decided by another Bursar officer
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        rv := finance.initiate_payment_swap(NULL, NULL, 'The first swap was made on the wrong student; taken back', NULL, true, sw);
        PERFORM set_config('moaum.actor_id', o3::text, true);
        back := finance.decide_payment_swap(rv, true, NULL, true);
        SELECT student_id INTO owner_back FROM finance.payment_reference WHERE id = pay;
        SELECT status INTO first_status FROM finance.payment_swap WHERE id = sw;
        swaps_a := (SELECT count(*) FROM finance.payment_swaps_of(a));
        RAISE EXCEPTION 'the V527 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V527 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V527: a verified school-fees payment is swapped to its owner only with a reason, the confirmation and another officer''s approval — the credit moves and nothing else, the accounts reconcile, never twice; a reversal takes it back',
        coalesce(ok_check AND same = 'SWAP_SAME_STUDENT' AND not_fees = 'SWAP_NOT_SCHOOL_FEES' AND not_verified = 'SWAP_NOT_VERIFIED'
                 AND short_reason = 'SWAP_REASON' AND no_confirm = 'SWAP_CONFIRM' AND open_again = 'SWAP_OPEN'
                 AND sao_decide = 'SWAP_OFFICE' AND self_decide = 'SWAP_SAME_OFFICER'
                 AND done->>'status' = 'COMPLETED' AND owner = b AND unchanged AND a_paid = 0 AND b_paid = 200000
                 AND events = 'PAYMENT_SWAP_INITIATED,PAYMENT_SWAP_APPROVED,PAYMENT_SWAP_EXECUTION_STARTED,PAYMENT_ALLOCATION_REMOVED,PAYMENT_ALLOCATION_CREATED,PAYMENT_SWAP_COMPLETED'
                 AND twice = 'SWAP_ALREADY_SWAPPED' AND fc = 'SWAP_OFFICE' AND back->>'status' = 'COMPLETED' AND owner_back = a AND first_status = 'REVERSED' AND swaps_a = 2, false),
        format('check %s same %s fees %s verified %s | reason %s confirm %s open %s | sao %s self %s | done %s owner b %s unchanged %s paid %s/%s | events %s | twice %s fc %s | back %s owner a %s first %s swaps %s',
               ok_check, same, not_fees, not_verified, short_reason, no_confirm, open_again, sao_decide, self_decide, done->>'status', owner = b, unchanged,
               a_paid, b_paid, events, twice, fc, back->>'status', owner_back = a, first_status, swaps_a));
END $$;

-- ── V529: unusual exports told to Internal Audit ──
-- A lecturer's export of 1,200 rows is told to the Director and the Deputy Director of Audit, not to the lecturer; with the watch at
-- three exports an hour, the third small export tells them once and the fourth does not; the Director's own large export is told to
-- the Deputy only; a switched-off watch tells nobody; a server-built PDF is recorded and a DOCX refused; the flags read as told.
-- The block undoes its writes.
DO $$
DECLARE lec uuid := gen_random_uuid(); aud uuid := gen_random_uuid(); dep uuid := gen_random_uuid(); big uuid; s3 uuid; s4 uuid; own uuid; off uuid; pdf uuid;
        big_aud int; big_dep int; big_lec int; burst_told int; fourth_told int; own_aud int; own_dep int; off_told int; docx text;
        f_large boolean; f_burst boolean; f_small boolean; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', aud::text, true);
        PERFORM set_config('moaum.actor_office', 'super', true);
        PERFORM set_config('moaum.reason', 'check V529', true);
        INSERT INTO iam.person (id, surname, given_names, email) VALUES
            (lec, 'CHECKV529', 'Lecturer', 'zz.check529.lec@example.com'),
            (aud, 'CHECKV529', 'Auditor', 'zz.check529.aud@example.com'),
            (dep, 'CHECKV529', 'Deputy', 'zz.check529.dep@example.com');
        INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, scope_id, instrument, granted_by, valid_from) VALUES
            (gen_random_uuid(), aud, 'audit', 'institution', NULL, 'check V529', aud, current_date - 1),
            (gen_random_uuid(), dep, 'deputyaudit', 'institution', NULL, 'check V529', aud, current_date - 1);
        UPDATE platform.export_watch SET enabled = true, large_rows = 1000, burst_count = 3, burst_minutes = 60;
        -- the lecturer: one large export, then small ones
        PERFORM set_config('moaum.actor_id', lec::text, true);
        PERFORM set_config('moaum.actor_office', 'lecturer', true);
        big := platform.log_export('Class lists (check V529)', 'XLSX', 1200, '{}'::jsonb, '/check', 'CHK/V529/1');
        PERFORM platform.log_export('Small list (check V529)', 'PRINT', 5, '{}'::jsonb, '/check', 'CHK/V529/2');   -- the second within the hour
        s3 := platform.log_export('Small list (check V529)', 'PRINT', 5, '{}'::jsonb, '/check', 'CHK/V529/3');     -- the third: the limit
        s4 := platform.log_export('Small list (check V529)', 'PRINT', 5, '{}'::jsonb, '/check', 'CHK/V529/4');     -- the fourth: told already
        pdf := platform.log_export('Paid applicants (check V529)', 'pdf', 30, '{}'::jsonb, '/admissions/paid-applicants/pdf', NULL);
        BEGIN PERFORM platform.log_export('Letters (check V529)', 'DOCX', 1, '{}'::jsonb, NULL, NULL);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; docx := split_part(msg, ':', 1); END;
        SELECT count(*) FILTER (WHERE n.about_id = aud), count(*) FILTER (WHERE n.about_id = dep), count(*) FILTER (WHERE n.about_id = lec)
          INTO big_aud, big_dep, big_lec FROM platform.notice n WHERE n.template_key = 'EXPORT_UNUSUAL' AND n.event_key = 'export-large:' || big;
        SELECT count(*) INTO burst_told FROM platform.notice n WHERE n.template_key = 'EXPORT_UNUSUAL' AND n.event_key = 'export-burst:' || s3 AND n.about_id = aud;
        SELECT count(*) INTO fourth_told FROM platform.notice n WHERE n.template_key = 'EXPORT_UNUSUAL' AND n.event_key LIKE '%:' || s4;
        -- the Director's own large export: the Deputy is told, the Director is not
        PERFORM set_config('moaum.actor_id', aud::text, true);
        PERFORM set_config('moaum.actor_office', 'audit', true);
        own := platform.log_export('Export log (check V529)', 'XLSX', 5000, '{}'::jsonb, '/audit/exports', NULL);
        SELECT count(*) FILTER (WHERE n.about_id = aud), count(*) FILTER (WHERE n.about_id = dep) INTO own_aud, own_dep
          FROM platform.notice n WHERE n.template_key = 'EXPORT_UNUSUAL' AND n.event_key = 'export-large:' || own;
        -- switched off: nobody is told
        PERFORM set_config('moaum.actor_office', 'super', true);
        UPDATE platform.export_watch SET enabled = false;
        PERFORM set_config('moaum.actor_id', lec::text, true);
        PERFORM set_config('moaum.actor_office', 'lecturer', true);
        off := platform.log_export('Class lists again (check V529)', 'XLSX', 9000, '{}'::jsonb, '/check', NULL);
        SELECT count(*) INTO off_told FROM platform.notice n WHERE n.template_key = 'EXPORT_UNUSUAL' AND n.event_key LIKE '%:' || off;
        SELECT u.large INTO f_large FROM platform.export_unusual(big) u;
        SELECT u.burst INTO f_burst FROM platform.export_unusual(s3) u;
        SELECT u.large OR u.burst INTO f_small FROM platform.export_unusual(pdf) u;   -- the fifth is in the window too
        RAISE EXCEPTION 'the V529 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V529 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V529: a large export or many in an hour is told to Internal Audit once, never to the person who made it; a switched-off watch tells nobody; PDF recorded, DOCX refused',
        coalesce(big_aud > 0 AND big_dep > 0 AND big_lec = 0 AND burst_told > 0 AND fourth_told = 0 AND own_aud = 0 AND own_dep > 0 AND off_told = 0
                 AND pdf IS NOT NULL AND docx = 'EXPORT_LOG_FORMAT' AND f_large AND f_burst AND f_small, false),
        format('large: auditor %s, deputy %s, lecturer %s | burst %s, fourth %s | own: auditor %s, deputy %s | off %s | pdf %s, docx %s | flags %s/%s/%s',
               big_aud, big_dep, big_lec, burst_told, fourth_told, own_aud, own_dep, off_told, pdf IS NOT NULL, docx, f_large, f_burst, f_small));
END $$;

-- ── V530: who opened a student's record ──
-- The Registrar opens a student's record twice within ten minutes: one view; ICT Support opens its record of the student: another;
-- the student reading their own portal is no view; a view is not changed or removed, but goes with its student when the student
-- record itself is removed. The block undoes its writes.
DO $$
DECLARE st uuid := gen_random_uuid(); reg uuid := gen_random_uuid(); agent uuid := gen_random_uuid(); prog text;
        first_ boolean; second_ boolean; support_ boolean; own boolean; views int; offices text; upd text; del text; gone int; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', reg::text, true);
        PERFORM set_config('moaum.actor_office', 'registrar', true);
        PERFORM set_config('moaum.reason', 'check V530', true);
        SELECT p.code INTO prog FROM ref.programme p WHERE NOT coalesce(p.archived, false) ORDER BY p.code LIMIT 1;
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status)
        VALUES (st, 'MOAUM/ADM/98/953001', 'CHECKV530', 'Viewed', prog, 'UTME', '2020/2021', 100, 100, 'ADMITTED');
        first_ := people.log_record_view(st, 'STUDENT_RECORD');
        second_ := people.log_record_view(st, 'STUDENT_RECORD');   -- within ten minutes: the same view
        PERFORM set_config('moaum.actor_id', agent::text, true);
        PERFORM set_config('moaum.actor_office', 'ictagent', true);
        support_ := people.log_record_view(st, 'SUPPORT_RECORD');
        PERFORM set_config('moaum.actor_id', st::text, true);
        PERFORM set_config('moaum.actor_office', 'student', true);
        own := people.log_record_view(st, 'STUDENT_RECORD');
        SELECT count(*), string_agg(v.office || '/' || v.record, ',' ORDER BY v.office) INTO views, offices FROM people.record_view v WHERE v.student_id = st;
        PERFORM set_config('moaum.actor_id', reg::text, true);
        PERFORM set_config('moaum.actor_office', 'registrar', true);
        BEGIN UPDATE people.record_view SET office = 'super' WHERE student_id = st;
        EXCEPTION WHEN insufficient_privilege THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; upd := split_part(msg, ':', 1); END;
        BEGIN DELETE FROM people.record_view WHERE student_id = st;
        EXCEPTION WHEN insufficient_privilege THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; del := split_part(msg, ':', 1); END;
        DELETE FROM people.student WHERE id = st;
        SELECT count(*) INTO gone FROM people.record_view v WHERE v.student_id = st;
        RAISE EXCEPTION 'the V530 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V530 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V530: an office opening a student''s record is recorded once in ten minutes, the student''s own reading is not, and the log is append-only',
        coalesce(first_ AND NOT second_ AND support_ AND NOT own AND views = 2 AND offices = 'ictagent/SUPPORT_RECORD,registrar/STUDENT_RECORD'
                 AND upd = 'RECORD_VIEW_APPEND_ONLY' AND del = 'RECORD_VIEW_APPEND_ONLY' AND gone = 0, false),
        format('first %s, again %s, support %s, own %s | %s views: %s | update %s, delete %s | with the student gone %s', first_, second_, support_, own, views, offices, upd, del, gone));
END $$;

-- ── V531: the CGPA and the fee positions read at once agree with each student's own ──
-- assessment.scope_cgpa gives every student with an approved registration the CGPA assessment.student_gpa gives on the student's
-- latest semester (the results block's student, two sessions with a repeated course, among them); finance.fee_positions_of gives
-- each student named what finance.fee_stated and finance.position give, for a paid and an unpaid student of one profile and one of
-- another level with no fee stated. The block undoes its writes.
DO $$
DECLARE ses text := '2412/2413'; prog text; a uuid := gen_random_uuid(); b uuid := gen_random_uuid(); c uuid := gen_random_uuid(); ref text;
        students int; with_cgpa int; cgpa_differ int; chk_cgpa numeric; chk_each numeric; pos_differ int; pos_n int; a_full boolean; c_stated boolean; msg text;
BEGIN
    -- the CGPA: every registered student on the database
    WITH s AS (SELECT DISTINCT r.student_id FROM registration.course_registration r WHERE r.status IN ('APPROVED', 'LOCKED')),
    each_ AS (SELECT s.student_id, (SELECT g.cgpa FROM assessment.student_gpa(s.student_id) g ORDER BY g.session DESC, g.semester DESC LIMIT 1) AS cgpa FROM s),
    once AS (SELECT * FROM assessment.scope_cgpa((SELECT array_agg(s.student_id) FROM s)))
    SELECT count(*), count(e.cgpa), count(*) FILTER (WHERE e.cgpa IS DISTINCT FROM o.cgpa)
      INTO students, with_cgpa, cgpa_differ
      FROM each_ e LEFT JOIN once o ON o.student_id = e.student_id;
    SELECT o.cgpa INTO chk_cgpa FROM people.student st CROSS JOIN LATERAL assessment.scope_cgpa(ARRAY[st.id]) o WHERE st.matric_no = 'MOAUM/CHK/99/0002';
    SELECT g.cgpa INTO chk_each FROM people.student st CROSS JOIN LATERAL assessment.student_gpa(st.id) g
     WHERE st.matric_no = 'MOAUM/CHK/99/0002' ORDER BY g.session DESC, g.semester DESC LIMIT 1;
    -- the fee positions: a paid and an unpaid student of one profile, and one with no fee stated
    BEGIN
        PERFORM set_config('moaum.actor_id', '00000000-0000-0000-0000-000000000000', true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM set_config('moaum.reason', 'check V531', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), ses, DATE '2412-10-01', DATE '2413-08-31');
        SELECT p.code INTO prog FROM ref.programme p WHERE p.category = 'UNDER GRADUATE' AND NOT coalesce(p.archived, false) AND p.dept_code IS NOT NULL ORDER BY p.code LIMIT 1;
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status) VALUES
            (a, 'MOAUM/ADM/98/953101', 'CHECKV531', 'Paid', prog, 'UTME', ses, 100, 100, 'ADMITTED'),
            (b, 'MOAUM/ADM/98/953102', 'CHECKV531', 'Unpaid', prog, 'UTME', ses, 100, 100, 'ADMITTED'),
            (c, 'MOAUM/ADM/98/953103', 'CHECKV531', 'Unstated', prog, 'UTME', ses, 100, 200, 'ADMITTED');
        INSERT INTO finance.fee_schedule (session, item, amount, level, programme_code) VALUES (ses, 'School fees (check V531)', 40000, 100, prog);
        ref := finance.new_purpose_reference(a, ses, 40000, 'School fees ' || ses);
        PERFORM finance.confirm_payment(ref, 'BANK_BRANCH', 'teller for check V531');
        SELECT count(*), count(*) FILTER (WHERE (finance.fee_stated(o.student_id, ses), p.due, p.paid, p.balance, p.instalments_paid, p.paid_in_full, p.has_arrears)
                                                IS DISTINCT FROM (o.stated, o.due, o.paid, o.balance, o.instalments_paid, o.paid_in_full, o.has_arrears))
          INTO pos_n, pos_differ
          FROM finance.fee_positions_of(ses, ARRAY[a, b, c]) o CROSS JOIN LATERAL finance.position(o.student_id, ses) p;
        SELECT o.paid_in_full INTO a_full FROM finance.fee_positions_of(ses, ARRAY[a]) o;
        SELECT o.stated INTO c_stated FROM finance.fee_positions_of(ses, ARRAY[c]) o;
        RAISE EXCEPTION 'the V531 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V531 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V531: the CGPA and the fee positions read at once agree with each student''s own',
        coalesce(students > 0 AND with_cgpa > 0 AND cgpa_differ = 0 AND chk_cgpa IS NOT NULL AND chk_cgpa = chk_each
                 AND pos_n = 3 AND pos_differ = 0 AND a_full AND NOT c_stated, false),
        format('cgpa: %s students, %s with one, %s differ, results student %s/%s | positions: %s, %s differ, paid in full %s, unstated %s',
               students, with_cgpa, cgpa_differ, chk_cgpa, chk_each, pos_n, pos_differ, a_full, c_stated));
END $$;
-- ── V528. The student's bank account for a refund, and the oversight of password resets. A student overpaid ₦25,000 is refunded:
--          refused for another student's refund and a short account number; given while the refund awaits approval (the refund
--          takes bank, name and the last four digits, the fees page shows it) and changed then; once approved with it, refused. A
--          second refund approved with no account takes one, once. The notice asks for the account. An agent's resets in a day:
--          the Head told when they reach the figure set (once), not before nor again, and at the next reset when the figure is
--          lowered below the day's count; each agent's counts read. The block undoes its writes ──
DO $$
DECLARE who uuid := gen_random_uuid(); second uuid := gen_random_uuid(); s uuid := gen_random_uuid(); other uuid := gen_random_uuid();
        a text := '9977/9978'; b text := '9978/9979'; pa text; rf text; rf2 text; e_mine text; e_short text; e_closed text; e_closed2 text;
        snap text; page_shows text; changed text; second_given text; asks boolean; agent uuid := gen_random_uuid(); head uuid := gen_random_uuid();
        told_before int; told_at int; told_after int; counts text; agent2 uuid := gen_random_uuid(); lowered text; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM set_config('moaum.reason', 'check V528', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES
            (gen_random_uuid(), a, date '9977-10-01', date '9978-08-31'), (gen_random_uuid(), b, date '9978-10-01', date '9979-08-31')
        ON CONFLICT (name) DO NOTHING;
        SELECT code INTO pa FROM ref.programme WHERE NOT coalesce(archived, false) ORDER BY code LIMIT 1;
        INSERT INTO finance.fee_schedule (session, item, amount, level, programme_code, kind) VALUES (a, 'School fees', 100000, NULL, pa, 'FEE');
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at) VALUES
          (s, 'MOAUM/ADM/77/977101', 'MOAUM/CHK/77/9771', 'ZZCHKV528A', 'Invented', pa, 'UTME', a, 100, 100, 'ACTIVE', now()),
          (other, 'MOAUM/ADM/77/977102', 'MOAUM/CHK/77/9772', 'ZZCHKV528B', 'Invented', pa, 'UTME', a, 100, 100, 'ACTIVE', now());
        INSERT INTO finance.payment_reference (student_id, session, reference, purpose, amount, expires_at, confirmed_at, confirmed_by, channel, receipt_no, note)
        VALUES (s, a, 'MOAUM-CHKV528-1', 'School fees ' || a, 125000, '9977-11-02', '9977-11-02', who, 'INTERSWITCH', 'RCT-MOAUM-CHKV528-1', 'check V528');
        PERFORM * FROM finance.decide_overpayments(a, 'REFUND', ARRAY[s], 'CHECK V528: refunded to the student');
        SELECT d.reference INTO rf FROM finance.overpayment_decision d WHERE d.student_id = s AND d.superseded_at IS NULL;
        asks := (SELECT t.sms_body LIKE '%Give your bank account%' FROM platform.notice_template t WHERE t.key = 'OVERPAYMENT_REFUND_RAISED');

        BEGIN PERFORM finance.give_refund_account(other, rf, 'First Bank', 'Invented Other', '0123456789');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS e_mine = MESSAGE_TEXT; END;
        BEGIN PERFORM finance.give_refund_account(s, rf, 'First Bank', 'ZZCHKV528A Invented', '12345');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS e_short = MESSAGE_TEXT; END;
        PERFORM finance.give_refund_account(s, rf, 'First Bank', 'ZZCHKV528A Invented', '0123 456 784');
        snap := (SELECT f.bank_name || ':' || f.account_name || ':' || f.account_last4 FROM finance.refund f WHERE f.reference = rf);
        page_shows := (SELECT x.bank_name || ':' || x.account_last4 || ':' || x.account_open FROM finance.student_overpayments(s) x WHERE x.reference = rf);
        PERFORM finance.give_refund_account(s, rf, 'Access Bank', 'ZZCHKV528A Invented', '9876543215');
        changed := (SELECT f.bank_name || ':' || f.account_last4 || '|' || ra.account_number FROM finance.refund f JOIN finance.refund_account ra ON ra.refund_id = f.id WHERE f.reference = rf);
        -- approved by a second officer: the account is fixed
        PERFORM set_config('moaum.actor_id', second::text, true);
        PERFORM finance.approve_refund((SELECT f.id FROM finance.refund f WHERE f.reference = rf));
        BEGIN PERFORM finance.give_refund_account(s, rf, 'Zenith Bank', 'ZZCHKV528A Invented', '1111111111');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS e_closed = MESSAGE_TEXT; END;
        -- a refund approved with no account takes one, once
        PERFORM set_config('moaum.actor_id', who::text, true);
        rf2 := finance.propose_refund(s, 'ZZCHKV528A, Invented', 'check V528: a second refund', 1000, NULL, NULL, NULL, NULL);
        PERFORM set_config('moaum.actor_id', second::text, true);
        PERFORM finance.approve_refund((SELECT f.id FROM finance.refund f WHERE f.reference = rf2));
        PERFORM finance.give_refund_account(s, rf2, 'GTBank', 'ZZCHKV528A Invented', '2222222223');
        second_given := (SELECT f.state || ':' || f.account_last4 FROM finance.refund f WHERE f.reference = rf2);
        BEGIN PERFORM finance.give_refund_account(s, rf2, 'GTBank', 'ZZCHKV528A Invented', '3333333333');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS e_closed2 = MESSAGE_TEXT; END;

        -- the oversight: the Head told when an agent's resets in a day reach the figure, once
        PERFORM set_config('moaum.actor_office', 'ict', true);
        INSERT INTO iam.person (id, surname, given_names, email) VALUES (agent, 'ZZCHKV528AGENT', 'Invented', NULL), (head, 'ZZCHKV528HEAD', 'Invented', 'zzchkv528head@example.com');
        INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, instrument, granted_by, valid_from)
        VALUES (gen_random_uuid(), head, 'helpdeskhead', 'institution', 'check V528', who, current_date - 1);
        UPDATE helpdesk.setting SET student_reset_alert_daily = 2 WHERE row_no;
        INSERT INTO helpdesk.support_action (student_id, agent_id, agent_office, action, reason, method, at, outcome)
        VALUES (s, agent, 'ictagent', 'PASSWORD_RESET', 'check V528: reset', 'DEFAULT_CREDENTIAL', now(), 'COMPLETED');
        told_before := (SELECT count(*) FROM platform.notice n WHERE n.template_key = 'SUPPORT_RESET_ALERT' AND n.about_id = head);
        INSERT INTO helpdesk.support_action (student_id, agent_id, agent_office, action, reason, method, at, outcome)
        VALUES (other, agent, 'ictagent', 'PASSWORD_RESET', 'check V528: reset', 'DEFAULT_CREDENTIAL', now(), 'COMPLETED');
        told_at := (SELECT count(*) FROM platform.notice n WHERE n.template_key = 'SUPPORT_RESET_ALERT' AND n.about_id = head AND n.channel = 'EMAIL'
                     AND n.subject = 'ZZCHKV528AGENT, Invented has reset 2 student passwords today');
        INSERT INTO helpdesk.support_action (student_id, agent_id, agent_office, action, reason, method, at, outcome)
        VALUES (s, agent, 'ictagent', 'PASSWORD_RESET', 'check V528: reset', 'DEFAULT_CREDENTIAL', now(), 'COMPLETED');
        told_after := (SELECT count(*) FROM platform.notice n WHERE n.template_key = 'SUPPORT_RESET_ALERT' AND n.about_id = head AND n.channel = 'EMAIL');
        counts := (SELECT c.name || ':' || c.today || ':' || c.week || ':' || c.alert_at FROM helpdesk.reset_counts() c WHERE c.agent_id = agent);
        -- a second agent past a figure set during the day: told at the next reset, with the day's count
        INSERT INTO iam.person (id, surname, given_names) VALUES (agent2, 'ZZCHKV528AGENTB', 'Invented');
        UPDATE helpdesk.setting SET student_reset_alert_daily = NULL WHERE row_no;
        INSERT INTO helpdesk.support_action (student_id, agent_id, agent_office, action, reason, method, at, outcome)
        SELECT x, agent2, 'ictagent', 'PASSWORD_RESET', 'check V528: reset', 'DEFAULT_CREDENTIAL', now(), 'COMPLETED' FROM unnest(ARRAY[s, other]) x;
        UPDATE helpdesk.setting SET student_reset_alert_daily = 1 WHERE row_no;
        INSERT INTO helpdesk.support_action (student_id, agent_id, agent_office, action, reason, method, at, outcome)
        VALUES (s, agent2, 'ictagent', 'PASSWORD_RESET', 'check V528: reset', 'DEFAULT_CREDENTIAL', now(), 'COMPLETED');
        lowered := (SELECT string_agg(n.subject, ',') FROM platform.notice n WHERE n.template_key = 'SUPPORT_RESET_ALERT' AND n.about_id = head AND n.channel = 'EMAIL'
                     AND n.event_key LIKE 'reset-alert:' || agent2 || ':%');
        RAISE EXCEPTION 'the V528 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V528 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V528: a student gives the bank account a refund is paid into (while it awaits approval, or once after approval with none), never redirecting approved money; and the Head of ICT Support is told, once, when an agent''s resets in a day reach the figure set, each agent''s counts read',
        coalesce(e_mine LIKE 'REFUND_ACCOUNT_NOT_YOURS%' AND e_short LIKE 'REFUND_ACCOUNT_NUMBER%' AND asks
                 AND snap = 'First Bank of Nigeria:ZZCHKV528A Invented:6784' AND page_shows = 'First Bank of Nigeria:6784:true'
                 AND changed = 'Access Bank:3215|9876543215' AND e_closed LIKE 'REFUND_ACCOUNT_CLOSED%'
                 AND second_given = 'APPROVED:2223' AND e_closed2 LIKE 'REFUND_ACCOUNT_CLOSED%'
                 AND told_before = 0 AND told_at = 1 AND told_after = 1 AND counts = 'ZZCHKV528AGENT, Invented:3:3:2'
                 AND lowered = 'ZZCHKV528AGENTB, Invented has reset 3 student passwords today', false),
        format('not yours %s | short %s | asks %s | snapshot %s | page %s | changed %s | closed %s | second %s, again %s | told %s/%s/%s | counts %s | lowered %s',
               left(e_mine, 26), left(e_short, 24), asks, snap, page_shows, changed, left(e_closed, 24), second_given, left(e_closed2, 24),
               told_before, told_at, told_after, counts, lowered));
END $$;
-- ── V532: e-mail over SMTP at the mail provider's pace ──
-- Microsoft 365's limits for one mailbox stand by default (30 a minute, 10,000 a day); each attempt over SMTP is counted and
-- the allowance is what is left of the tighter limit, never below none; empty limits mean no limit; a limit out of range, or a
-- day's below a minute's, is refused. The block undoes its writes.
DO $$
DECLARE msg text; d_min int; d_day int; a0 int; a1 int; tried_min bigint; at_limit int; none_left int; unlimited int; r_zero text; r_order text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.reason', 'check V532', true);
        PERFORM set_config('moaum.actor_id', '00000000-0000-0000-0000-000000000000', true);
        PERFORM set_config('moaum.actor_office', 'ict', true);
        SELECT p.per_minute, p.per_day INTO d_min, d_day FROM platform.smtp_pace() p;
        PERFORM platform.set_smtp_pace(5, 100, NULL, 'ict');
        DELETE FROM platform.smtp_attempt;
        a0 := (SELECT p.allowance FROM platform.smtp_pace() p);
        PERFORM platform.smtp_attempted(true);
        PERFORM platform.smtp_attempted(false);
        SELECT p.allowance, p.last_minute INTO a1, tried_min FROM platform.smtp_pace() p;
        PERFORM platform.smtp_attempted(true); PERFORM platform.smtp_attempted(true); PERFORM platform.smtp_attempted(true);
        at_limit := (SELECT p.allowance FROM platform.smtp_pace() p);
        PERFORM platform.smtp_attempted(true);
        none_left := (SELECT p.allowance FROM platform.smtp_pace() p);
        PERFORM platform.set_smtp_pace(NULL, NULL, NULL, 'ict');
        unlimited := coalesce((SELECT p.allowance FROM platform.smtp_pace() p), -1);
        BEGIN PERFORM platform.set_smtp_pace(0, 100, NULL, 'ict'); r_zero := 'SET';
        EXCEPTION WHEN check_violation THEN r_zero := split_part(SQLERRM, ':', 1); END;
        BEGIN PERFORM platform.set_smtp_pace(50, 10, NULL, 'ict'); r_order := 'SET';
        EXCEPTION WHEN check_violation THEN r_order := split_part(SQLERRM, ':', 1); END;
        RAISE EXCEPTION 'the V532 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V532 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V532: e-mail over SMTP goes at the provider''s pace — Microsoft 365''s 30 a minute and 10,000 a day by default, each attempt counted, none past the tighter limit, empty for no limit, a limit out of range refused',
        coalesce(d_min = 30 AND d_day = 10000 AND a0 = 5 AND a1 = 3 AND tried_min = 2 AND at_limit = 0 AND none_left = 0 AND unlimited = -1
                 AND r_zero = 'NOTICE_PACE_RANGE' AND r_order = 'NOTICE_PACE_RANGE', false),
        format('default %s/%s | allowance %s then %s (tried %s) | at limit %s, past %s | unlimited %s | zero %s order %s',
               d_min, d_day, a0, a1, tried_min, at_limit, none_left, unlimited, r_zero, r_order));
END $$;
-- ── V533. Refunds paid only into a full, checked account. The CBN's own example holds (011 + 000001457 → 0000014579); a bank is
--          found by its code, name or another name; a number one digit off at a checked bank is refused, a payment service
--          bank's is not checked. A refund raised at the desk with no account is not paid (REFUND_NO_ACCOUNT); the account the desk
--          records on it once approved sends it back for approval, which the officer who recorded it may not give; another
--          approves and it is paid. A refund raised with the last four digits is completed by the desk without a new approval;
--          a different account on an approved refund goes back. The student's rule stands. Names compared, a warning only. The
--          block undoes its writes ──
DO $$
DECLARE maker uuid := gen_random_uuid(); checker uuid := gen_random_uuid(); third uuid := gen_random_uuid(); s uuid := gen_random_uuid();
        example int; found text; slip text; opay text; rf1 text; rf2 text; id1 uuid; id2 uuid; e_nopay text; st_after text; e_same text;
        paid1 text; st_complete text; paid2 text; st_change text; e_student text; e_digit text; src text; share_yes boolean; share_no boolean; mfb text := 'ALLOWED'; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', maker::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM set_config('moaum.reason', 'check V533', true);
        example := finance.nuban_check_digit('011', '000001457');
        found := (finance.bank_of('GTB')).code || ',' || (finance.bank_of('first bank of nigeria')).code || ',' || (finance.bank_of('057')).name;
        slip := coalesce(finance.account_number_problem('First Bank', '0000014578'), 'none') || ',' || coalesce(finance.account_number_problem('First Bank', '0000014579'), 'none');
        opay := coalesce(finance.account_number_problem('OPay', '8012345678'), 'none') || ',' || coalesce(finance.account_number_problem('Another bank', '123'), 'none');
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
        SELECT s, 'MOAUM/ADM/76/976101', 'MOAUM/CHK/76/9761', 'ZZCHKV533', 'Invented', code, 'UTME', policy.university_current_session(), 100, 100, 'ACTIVE', now()
          FROM ref.programme WHERE NOT coalesce(archived, false) ORDER BY code LIMIT 1;
        -- raised at the desk with no account: approved, never paid
        rf1 := finance.propose_refund(s, 'ZZCHKV533, Invented', 'check V533: no account', 1000, NULL, NULL, NULL, NULL);
        id1 := (SELECT id FROM finance.refund WHERE reference = rf1);
        PERFORM set_config('moaum.actor_id', checker::text, true);
        PERFORM finance.approve_refund(id1);
        BEGIN PERFORM finance.pay_refund(id1, 'CHK-TRF-PAID', (now() AT TIME ZONE 'Africa/Lagos')::date);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; e_nopay := split_part(msg, ':', 1); END;
        -- the account recorded by an officer on the approved refund: back for approval, not by that officer
        st_after := finance.desk_refund_account(id1, 'GTB', 'ZZCHKV533 Invented', '2222222223');
        BEGIN PERFORM finance.approve_refund(id1);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; e_same := split_part(msg, ':', 1); END;
        PERFORM set_config('moaum.actor_id', third::text, true);
        PERFORM finance.approve_refund(id1);
        PERFORM finance.pay_refund(id1, 'CHK-TRF-PAID', (now() AT TIME ZONE 'Africa/Lagos')::date);
        paid1 := (SELECT f.state || ':' || a.source || ':' || a.bank_code || ':' || f.account_last4 FROM finance.refund f JOIN finance.refund_account a ON a.refund_id = f.id WHERE f.id = id1);
        -- raised with the last four digits: the desk completes the number without a new approval; a different account goes back
        PERFORM set_config('moaum.actor_id', maker::text, true);
        rf2 := finance.propose_refund(s, 'ZZCHKV533, Invented', 'check V533: last four', 1000, 'First Bank', 'ZZCHKV533 Invented', '6784', NULL);
        id2 := (SELECT id FROM finance.refund WHERE reference = rf2);
        PERFORM set_config('moaum.actor_id', checker::text, true);
        PERFORM finance.approve_refund(id2);
        BEGIN PERFORM finance.desk_refund_account(id2, 'First Bank', 'ZZCHKV533 Invented', '0123456789');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; e_digit := split_part(msg, ':', 1); END;
        st_complete := finance.desk_refund_account(id2, 'First Bank', 'ZZCHKV533 Invented', '0123 456 784');
        BEGIN PERFORM finance.give_refund_account(s, rf2, 'Access Bank', 'ZZCHKV533 Invented', '9876543215');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; e_student := split_part(msg, ':', 1); END;
        st_change := finance.desk_refund_account(id2, 'Access Bank', 'ZZCHKV533 Invented', '9876543215');
        PERFORM set_config('moaum.actor_id', third::text, true);
        PERFORM finance.approve_refund(id2);
        PERFORM finance.pay_refund(id2, 'CHK-TRF-PAID', (now() AT TIME ZONE 'Africa/Lagos')::date);
        paid2 := (SELECT f.state || ':' || a.bank_name || ':' || a.account_number FROM finance.refund f JOIN finance.refund_account a ON a.refund_id = f.id WHERE f.id = id2);
        -- a microfinance bank's numbers are never checked by the banks' check digit
        BEGIN UPDATE finance.bank SET nuban_check = true WHERE code = '565';
        EXCEPTION WHEN check_violation THEN mfb := 'REFUSED'; END;
        share_yes := finance.names_share('ZZCHKV533 Invented', 'ZZCHKV533, Invented');
        share_no := finance.names_share('Someone Else', 'ZZCHKV533, Invented');
        RAISE EXCEPTION 'the V533 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V533 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V533: a refund is paid only into a full account on record, its number checked against the bank; the account the desk records on an approved refund goes back for another officer''s approval unless it completes the one approved',
        coalesce(example = 9 AND found = '058,011,Zenith Bank' AND slip = 'REFUND_ACCOUNT_CHECK_DIGIT,none' AND opay = 'none,REFUND_ACCOUNT_NUMBER'
                 AND e_nopay = 'REFUND_NO_ACCOUNT' AND st_after = 'PROPOSED' AND e_same = 'REFUND_ACCOUNT_SAME_OFFICER' AND paid1 = 'PAID:DESK:058:2223'
                 AND e_digit = 'REFUND_ACCOUNT_CHECK_DIGIT' AND st_complete = 'APPROVED' AND e_student = 'REFUND_ACCOUNT_CLOSED' AND st_change = 'PROPOSED'
                 AND paid2 = 'PAID:Access Bank:9876543215' AND share_yes AND NOT share_no AND mfb = 'REFUSED', false),
        format('example %s found %s slip %s opay %s | no account %s, recorded %s, same %s, paid %s | digit %s complete %s student %s change %s paid %s | names %s/%s | microfinance %s',
               example, found, slip, opay, e_nopay, st_after, e_same, paid1, e_digit, st_complete, e_student, st_change, paid2, share_yes, share_no, mfb));
END $$;
-- ── V534. A refund marked paid with its evidence; every payout account checked. A student overpaid ₦25,000 is refunded into the
--          account they gave and approved: paid with no transfer reference, a date to come, or one before the approval is
--          refused; a refund set PAID by hand without them is refused; paid with them, the student is told the reference and the
--          date and the fees page shows them. A wallet withdrawal's account one digit off is refused, the right one kept with the
--          bank as it is listed; a JUPEB claim's account is checked by its trigger. The block undoes its writes ──
DO $$
DECLARE who uuid := gen_random_uuid(); second uuid := gen_random_uuid(); s uuid := gen_random_uuid(); a text := '9975/9976'; b text := '9976/9977'; pa text;
        rf text; rid uuid; e_ref text; e_future text; e_before text; e_hand text; paid text; told text; page text; e_wd text; wd text; claim_checked boolean; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM set_config('moaum.reason', 'check V534', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES
            (gen_random_uuid(), a, date '9975-10-01', date '9976-08-31'), (gen_random_uuid(), b, date '9976-10-01', date '9977-08-31')
        ON CONFLICT (name) DO NOTHING;
        SELECT code INTO pa FROM ref.programme WHERE NOT coalesce(archived, false) ORDER BY code LIMIT 1;
        INSERT INTO finance.fee_schedule (session, item, amount, level, programme_code, kind) VALUES (a, 'School fees', 100000, NULL, pa, 'FEE');
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
        VALUES (s, 'MOAUM/ADM/75/975101', 'MOAUM/CHK/75/9751', 'ZZCHKV534', 'Invented', pa, 'UTME', a, 100, 100, 'ACTIVE', now());
        INSERT INTO people.student_contact (student_id, email, updated_at) VALUES (s, 'zzchkv534@example.invalid', now());
        INSERT INTO finance.payment_reference (student_id, session, reference, purpose, amount, expires_at, confirmed_at, confirmed_by, channel, receipt_no, note)
        VALUES (s, a, 'MOAUM-CHKV534-1', 'School fees ' || a, 125000, '9975-11-02', '9975-11-02', who, 'INTERSWITCH', 'RCT-MOAUM-CHKV534-1', 'check V534');
        PERFORM * FROM finance.decide_overpayments(a, 'REFUND', ARRAY[s], 'CHECK V534: refunded to the student');
        SELECT f.reference, f.id INTO rf, rid FROM finance.refund f WHERE f.student_id = s;
        PERFORM finance.give_refund_account(s, rf, '011', 'ZZCHKV534 Invented', '0000014579');
        PERFORM set_config('moaum.actor_id', second::text, true);
        PERFORM finance.approve_refund(rid);
        BEGIN PERFORM finance.pay_refund(rid, '  ', current_date);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; e_ref := split_part(msg, ':', 1); END;
        BEGIN PERFORM finance.pay_refund(rid, 'FT-CHK-534', current_date + 2);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; e_future := split_part(msg, ':', 1); END;
        BEGIN PERFORM finance.pay_refund(rid, 'FT-CHK-534', current_date - 30);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; e_before := split_part(msg, ':', 1); END;
        BEGIN UPDATE finance.refund SET state = 'PAID', paid_at = now(), paid_by = second WHERE id = rid;
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; e_hand := split_part(msg, ':', 1); END;
        PERFORM finance.pay_refund(rid, ' FT-CHK-534 ', (now() AT TIME ZONE 'Africa/Lagos')::date);
        paid := (SELECT f.state || ':' || f.paid_reference || ':' || (f.paid_on = (now() AT TIME ZONE 'Africa/Lagos')::date) FROM finance.refund f WHERE f.id = rid);
        told := (SELECT n.body FROM platform.notice n WHERE n.template_key = 'OVERPAYMENT_REFUND_PAID' AND n.about_id = s AND n.channel = 'EMAIL');
        page := (SELECT x.refund_state || ':' || x.paid_reference || ':' || (x.paid_on IS NOT NULL) FROM finance.student_overpayments(s) x);
        -- a wallet withdrawal's account, checked as it is requested
        BEGIN INSERT INTO finance.wallet_withdrawal (student_id, session, amount, bank_name, account_no, account_name, requested_by)
              VALUES (s, a, 1000, 'Zenith', '0123456789', 'ZZCHKV534 Invented', who);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; e_wd := split_part(msg, ':', 1); END;
        INSERT INTO finance.wallet_withdrawal (student_id, session, amount, bank_name, account_no, account_name, requested_by)
        VALUES (s, a, 1000, 'zenith', '0123 4567-88', 'ZZCHKV534 Invented', who);
        wd := (SELECT w.bank_name || ':' || w.account_no FROM finance.wallet_withdrawal w WHERE w.student_id = s);
        claim_checked := EXISTS (SELECT 1 FROM pg_trigger t WHERE t.tgname = 'trg_claim_account_checked' AND t.tgrelid = 'jupeb.refund_claim'::regclass AND NOT t.tgisinternal);
        RAISE EXCEPTION 'the V534 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V534 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V534: a refund is marked paid only with the bank transfer reference and the date the money left (not after today, not before approval), the student told both; every account money is paid out to is checked against its bank',
        coalesce(e_ref = 'REFUND_PAID_REFERENCE' AND e_future = 'REFUND_PAID_DATE' AND e_before = 'REFUND_PAID_DATE' AND e_hand = 'REFUND_PAID_EVIDENCE'
                 AND paid = 'PAID:FT-CHK-534:true' AND told LIKE '%transfer reference is FT-CHK-534%' AND page = 'PAID:FT-CHK-534:true'
                 AND e_wd = 'REFUND_ACCOUNT_CHECK_DIGIT' AND wd = 'Zenith Bank:0123456788' AND claim_checked, false),
        format('reference %s future %s before %s by hand %s | paid %s | told %s | page %s | wallet %s, %s | claim trigger %s',
               e_ref, e_future, e_before, e_hand, paid, left(told, 160), page, e_wd, wd, claim_checked));
END $$;
-- ── V539: a PG change dated today is today in Lagos, whatever the database's clock ──
-- V509's rule took today from the database's clock and the start of a role in Lagos time, a day apart from midnight to one
-- o'clock in Lagos. With the session's clock far east of Lagos (UTC+14) and far west of it (UTC−12) — between them one is on
-- another date than Lagos at every hour — and in UTC, a change dated today in Lagos is taken for a role that began just now,
-- and tomorrow in Lagos is the future. The block undoes its settings.
DO $$
DECLARE td date := (now() AT TIME ZONE 'Africa/Lagos')::date; zone text; took text; ahead text; outcome text := ''; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_office', 'pgschool', true);
        FOREACH zone IN ARRAY ARRAY['Pacific/Kiritimati', 'Etc/GMT+12', 'UTC'] LOOP
            PERFORM set_config('TimeZone', zone, true);
            BEGIN PERFORM admissions.pg_school_check(td, now(), 'Check V539: a change dated today'); took := 'TAKEN';
            EXCEPTION WHEN check_violation THEN took := split_part(SQLERRM, ':', 1); END;
            BEGIN PERFORM admissions.pg_school_check(td + 1, now() - interval '30 days', 'Check V539: a change dated tomorrow'); ahead := 'TAKEN';
            EXCEPTION WHEN check_violation THEN ahead := split_part(SQLERRM, ':', 1); END;
            outcome := outcome || zone || '=' || took || '/' || ahead || ' ';
        END LOOP;
        RAISE EXCEPTION 'the V539 check undoes its settings';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V539 check undoes its settings' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V539: a postgraduate supervisor or panel change dated today in Lagos is taken whatever the database''s clock, for a role begun that day, and tomorrow in Lagos is refused',
        btrim(outcome) = 'Pacific/Kiritimati=TAKEN/PG_CHANGE_DATE Etc/GMT+12=TAKEN/PG_CHANGE_DATE UTC=TAKEN/PG_CHANGE_DATE', btrim(outcome));
END $$;

-- ── V535: the fees structure upload replaces only what it names, refuses a name it does not hold, and shows its effect first ──
-- A structure naming one faculty is refused as the whole session while another faculty has lines in force (the two-argument form
-- too, as every caller before V535 sent it); uploaded for what it names it replaces that faculty's lines alone; a faculty the
-- portal does not hold refuses it; the preview of either upload says what it would change and keeps nothing; the whole session,
-- meant, ends the other faculty's line. The block undoes its writes.
DO $$
DECLARE S text := '9935/9936'; msg text; other text; e_partial text; e_old text; e_unknown text; e jsonb; e_whole jsonb; e_lines jsonb;
        before_preview int; after_preview int; listed text; whole text;
BEGIN
    PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
    PERFORM set_config('moaum.actor_office', 'bursar', true);
    SELECT f.code INTO other FROM ref.faculty f WHERE f.code <> 'SC' AND EXISTS (SELECT 1 FROM ref.programme p WHERE p.faculty_code = f.code) ORDER BY f.code LIMIT 1;
    BEGIN
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9935-09-01', date '9936-08-31') ON CONFLICT (name) DO NOTHING;
        PERFORM finance.import_fee_structure(S, jsonb_build_array(
            jsonb_build_object('faculty', 'SC', 'level', '100', 'semester', '1', 'entryMode', 'UTME', 'amount', '50000'),
            jsonb_build_object('faculty', other, 'level', '100', 'semester', '1', 'entryMode', 'UTME', 'amount', '60000')), 'SESSION', true);
        BEGIN PERFORM finance.import_fee_structure(S, '[{"faculty":"SC","level":"100","semester":"1","entryMode":"UTME","amount":"55000"}]', 'SESSION', false);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; e_partial := split_part(msg, ':', 1); END;
        BEGIN PERFORM finance.import_fee_structure(S, '[{"faculty":"SC","level":"100","semester":"1","entryMode":"UTME","amount":"55000"}]');
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; e_old := split_part(msg, ':', 1); END;
        BEGIN PERFORM finance.import_fee_structure(S, '[{"faculty":"ZZ No Such Faculty","level":"100","amount":"1"}]', 'LISTED', false);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; e_unknown := split_part(msg, ':', 1); END;
        before_preview := (SELECT count(*) FROM finance.fee_schedule WHERE session = S AND ended_at IS NULL);
        e := finance.fee_upload_effect(S, '[{"faculty":"SC","level":"100","semester":"1","entryMode":"UTME","amount":"55000"}]', 'STRUCTURE', 'LISTED');
        e_whole := finance.fee_upload_effect(S, '[{"faculty":"SC","level":"100","semester":"1","entryMode":"UTME","amount":"55000"}]', 'STRUCTURE', 'SESSION');
        e_lines := finance.fee_upload_effect(S, '[{"programmeCode":"C00023","level":"300","entryMode":"UTME","semester":"1","amount":"81000"}]', 'LINES', NULL);
        after_preview := (SELECT count(*) FROM finance.fee_schedule WHERE session = S AND ended_at IS NULL);
        PERFORM finance.import_fee_structure(S, '[{"faculty":"SC","level":"100","semester":"1","entryMode":"UTME","amount":"55000"}]', 'LISTED', false);
        listed := (SELECT string_agg(faculty_code || '=' || amount::int, ',' ORDER BY faculty_code = 'SC' DESC) FROM finance.fee_schedule WHERE session = S AND ended_at IS NULL);
        PERFORM finance.import_fee_structure(S, '[{"faculty":"SC","level":"100","semester":"1","entryMode":"UTME","amount":"56000"}]', 'SESSION', true);
        whole := (SELECT string_agg(faculty_code || '=' || amount::int, ',') FROM finance.fee_schedule WHERE session = S AND ended_at IS NULL);
        RAISE EXCEPTION 'the V535 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V535 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V535: a fees structure replaces only the faculties it names unless the whole session is meant, refuses a faculty the portal does not hold, and its effect is shown first with nothing kept',
        coalesce(e_partial = 'FEE_STRUCTURE_PARTIAL' AND e_old = 'FEE_STRUCTURE_PARTIAL' AND e_unknown = 'FEE_STRUCTURE_UNKNOWN'
                 AND (e->'totals'->>'changed')::int = 1 AND (e->'totals'->>'ended')::int = 0
                 AND (e->'changes'->0->>'old')::numeric = 50000 AND (e->'changes'->0->>'new')::numeric = 55000
                 AND EXISTS (SELECT 1 FROM jsonb_array_elements(e_whole->'groups') g WHERE g->>'facultyCode' = other AND (g->>'losesAll')::boolean)
                 AND (e_lines->'totals'->>'new')::int = 1 AND before_preview = 2 AND after_preview = 2
                 AND listed = 'SC=55000,' || other || '=60000' AND whole = 'SC=56000', false),
        format('partial %s / two-argument %s / unknown %s | listed preview %s %s | whole preview %s | lines preview %s | in force %s → %s | listed %s | whole %s',
               e_partial, e_old, e_unknown, e->'totals', e->'changes', e_whole->'groups', e_lines->'totals', before_preview, after_preview, listed, whole));
END $$;

-- ── V536: the Registry's records check ──
-- Each live student whose record is inconsistent is listed by what is wrong, and only for that: a level beyond the programme and
-- its spillover years, the postgraduate entry mode on an undergraduate programme, an undergraduate level on a postgraduate one,
-- Direct Entry at 100 Level, no state of origin, a state the register spells otherwise; a consistent record and a graduated one
-- are not listed; every kind names the offices that correct it. The block undoes its writes.
DO $$
DECLARE msg text; pg text; fin int; got text; clean int; kinds int;
        a uuid := gen_random_uuid(); b uuid := gen_random_uuid(); c uuid := gen_random_uuid(); d uuid := gen_random_uuid();
        e uuid := gen_random_uuid(); f uuid := gen_random_uuid(); ok uuid := gen_random_uuid(); gone uuid := gen_random_uuid();
BEGIN
    PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
    PERFORM set_config('moaum.actor_office', 'registrar', true);
    SELECT code INTO pg FROM ref.programme WHERE category = 'POST GRADUATE' AND NOT archived ORDER BY code LIMIT 1;
    fin := finance.final_level('C00023');
    BEGIN
        INSERT INTO people.student (id, matric_no, surname, other_names, state_of_origin, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at) VALUES
            (a, 'MOAUM/RCK/35/0001', 'ZZCHKV536', 'Beyond', 'Benue', 'C00023', 'UTME', '2015/2016', 100, fin + 300, 'ACTIVE', now()),
            (b, 'MOAUM/RCK/35/0002', 'ZZCHKV536', 'PgEntry', 'Benue', 'C00023', 'POSTGRADUATE', '2023/2024', 100, 200, 'ACTIVE', now()),
            (c, 'MOAUM/RCK/35/0003', 'ZZCHKV536', 'PgLow', 'Benue', pg, 'POSTGRADUATE', '2024/2025', 700, 100, 'ACTIVE', now()),
            (d, 'MOAUM/RCK/35/0004', 'ZZCHKV536', 'DeHundred', 'Benue', 'C00023', 'DIRECT_ENTRY', '2025/2026', 200, 100, 'ACTIVE', now()),
            (e, 'MOAUM/RCK/35/0005', 'ZZCHKV536', 'NoState', NULL, 'C00023', 'UTME', '2025/2026', 100, 100, 'ACTIVE', now()),
            (f, 'MOAUM/RCK/35/0006', 'ZZCHKV536', 'Spelt', 'Benuw', 'C00023', 'UTME', '2025/2026', 100, 100, 'ACTIVE', now()),
            (ok, 'MOAUM/RCK/35/0007', 'ZZCHKV536', 'Consistent', 'Cross River', 'C00023', 'TRANSFER', '2025/2026', 200, 200, 'ACTIVE', now()),
            (gone, 'MOAUM/RCK/35/0008', 'ZZCHKV536', 'Graduated', NULL, 'C00023', 'POSTGRADUATE', '2015/2016', 100, 900, 'GRADUATED', now());
        got := (SELECT string_agg(split_part(x.matric_no, '/', 4) || ':' || x.issue, ',' ORDER BY x.matric_no, x.issue)
                  FROM people.record_issues() x WHERE x.matric_no LIKE 'MOAUM/RCK/35/%');
        clean := (SELECT count(*) FROM people.record_issues() x WHERE x.student_id IN (ok, gone));
        RAISE EXCEPTION 'the V536 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V536 check undoes its writes' THEN RAISE; END IF;
    END;
    kinds := (SELECT count(*) FROM people.record_issue_kind WHERE cardinality(offices) > 0 AND corrects <> '' AND how <> '');
    PERFORM pg_temp.assert('V536: the records check lists each live student whose record is inconsistent by what is wrong, and every kind names the offices that correct it',
        coalesce(got = '0001:LEVEL_BEYOND_PROGRAMME,0002:UG_POSTGRADUATE_ENTRY,0003:PG_UNDERGRADUATE_LEVEL,0004:DIRECT_ENTRY_AT_100,0005:NO_STATE_OF_ORIGIN,0006:STATE_NOT_ON_REGISTER'
                 AND clean = 0 AND kinds = (SELECT count(*) FROM people.record_issue_kind) AND kinds = 12, false),
        format('found %s | consistent or graduated listed %s | kinds with offices %s', got, clean, kinds));
END $$;

-- ── V537: the slowest screens read their figures in one pass, with the same answers ──
-- Every student's payment position at once is finance.payment_position for each (a balance under one naira is paid, a part
-- payment is a part payment, the second semester is charged what the first leaves), the session's charges are finance.charges
-- summed, and every application's Post-UTME standing read in one pass is admissions.putme_eligibility's. The block undoes its writes.
DO $$
DECLARE S text := '9933/9934'; msg text; full_ uuid := gen_random_uuid(); kobo uuid := gen_random_uuid(); part uuid := gen_random_uuid();
        none_ uuid := gen_random_uuid(); bursar uuid := gen_random_uuid(); pos_differ int; charges_differ int; statuses text; putme_differ int; apps int;
BEGIN
    PERFORM set_config('moaum.actor_id', bursar::text, true);
    PERFORM set_config('moaum.actor_office', 'bursar', true);
    BEGIN
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), S, date '9933-09-01', date '9934-08-31') ON CONFLICT (name) DO NOTHING;
        PERFORM finance.import_fee_structure(S, '[{"faculty":"SC","level":"100","semester":"1","entryMode":"UTME","amount":"60000.40"},
                                                  {"faculty":"SC","level":"100","semester":"2","entryMode":"UTME","amount":"40000"}]', 'LISTED', false);
        INSERT INTO people.student (id, matric_no, surname, other_names, state_of_origin, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at) VALUES
            (full_, 'MOAUM/V537/33/0001', 'ZZCHKV537', 'Full', 'Kano', 'C00023', 'UTME', S, 100, 100, 'ACTIVE', now()),
            (kobo, 'MOAUM/V537/33/0002', 'ZZCHKV537', 'Kobo', 'Kano', 'C00023', 'UTME', S, 100, 100, 'ACTIVE', now()),
            (part, 'MOAUM/V537/33/0003', 'ZZCHKV537', 'Part', 'Kano', 'C00023', 'UTME', S, 100, 100, 'ACTIVE', now()),
            (none_, 'MOAUM/V537/33/0004', 'ZZCHKV537', 'None', 'Kano', 'C00023', 'UTME', S, 100, 100, 'ACTIVE', now());
        INSERT INTO finance.payment_reference (student_id, session, reference, purpose, amount, expires_at, confirmed_at, confirmed_by, channel, receipt_no) VALUES
            (full_, S, 'MOAUM-FEE-V537-0001', 'School fees ' || S, 100000.40, now() + interval '1 day', now() - interval '1 hour', bursar, 'Card', 'RCPT-V537-0001'),
            (kobo, S, 'MOAUM-FEE-V537-0002', 'School fees ' || S, 60000, now() + interval '1 day', now() - interval '1 hour', bursar, 'Card', 'RCPT-V537-0002'),
            (kobo, S, 'MOAUM-FEE-V537-0003', 'School fees ' || S, 40000, now() + interval '1 day', now() - interval '1 hour', bursar, 'Card', 'RCPT-V537-0003'),
            (part, S, 'MOAUM-FEE-V537-0004', 'School fees ' || S, 30000, now() + interval '1 day', now(), bursar, 'Card', 'RCPT-V537-0004');
        pos_differ := (SELECT count(*) FROM (VALUES (NULL::int), (1), (2)) q(sem)
                         CROSS JOIN LATERAL (SELECT sp.* FROM finance.session_positions(S, q.sem) sp WHERE sp.student_id IN (full_, kobo, part, none_)) a
                         CROSS JOIN LATERAL finance.payment_position(a.student_id, S, q.sem) b
                        WHERE (a.payable, a.paid, a.outstanding, a.status, a.payments, a.last_reference, a.last_channel, a.last_paid_at)
                              IS DISTINCT FROM (b.payable, b.paid, b.outstanding, b.status, b.payments, b.last_reference, b.last_channel, b.last_paid_at));
        statuses := (SELECT string_agg(split_part(st.matric_no, '/', 4) || ':' || sp.status || ':' || coalesce(sp.last_reference, '-'), ',' ORDER BY st.matric_no)
                       FROM finance.session_positions(S, NULL) sp JOIN people.student st ON st.id = sp.student_id WHERE st.id IN (full_, kobo, part, none_));
        charges_differ := (SELECT count(*) FROM finance.session_charges(S) c
                            WHERE c.student_id IN (full_, kobo, part, none_)
                              AND c.total IS DISTINCT FROM (SELECT coalesce(sum(x.amount), 0) FROM finance.charges(c.student_id, S) x));
        RAISE EXCEPTION 'the V537 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V537 check undoes its writes' THEN RAISE; END IF;
    END;
    SELECT count(*) INTO apps FROM admissions.application;
    putme_differ := (SELECT count(*) FROM (SELECT DISTINCT session FROM admissions.application) ss
                       CROSS JOIN LATERAL admissions.putme_candidates(ss.session) c
                       CROSS JOIN LATERAL admissions.putme_eligibility(c.application_id) e
                      WHERE (c.status, c.why) IS DISTINCT FROM (e.status, e.why));
    PERFORM pg_temp.assert('V537: every student''s payment position read at once is finance.payment_position for each, the session''s charges are finance.charges summed, and the Post-UTME standing read in one pass is admissions.putme_eligibility''s',
        coalesce(pos_differ = 0 AND charges_differ = 0 AND putme_differ = 0
                 AND statuses = '0001:FULLY_PAID:MOAUM-FEE-V537-0001,0002:FULLY_PAID:MOAUM-FEE-V537-0003,0003:PART_PAYMENT:MOAUM-FEE-V537-0004,0004:NOT_PAID:-', false),
        format('positions differing %s | %s | charges differing %s | Post-UTME standings differing %s of %s applications', pos_differ, statuses, charges_differ, putme_differ, apps));
END $$;
-- ── V540. The money-out trail. A wallet withdrawal approved by one officer is refused to that officer, refused without a transfer
--          reference, for a date to come or one before its approval, and refused PAID by hand without them; paid by another with
--          them, the student is told the reference and the date and the queue shows the date. A refund approved five days ago and
--          paid three days ago is posted on the ledger on the day it was paid, not today. The Paid-out report holds both, the
--          shared transfer reference counted on each. The block undoes its writes ──
DO $$
DECLARE who uuid := gen_random_uuid(); approver uuid := gen_random_uuid(); payer uuid := gen_random_uuid(); s uuid := gen_random_uuid(); a text := '9973/9974';
        wd uuid; rf text; rid uuid; e_same text; e_ref text; e_future text; e_before text; e_hand text; paid text; told text; queue text;
        posted text; report text; v_today date := (now() AT TIME ZONE 'Africa/Lagos')::date; msg text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM set_config('moaum.reason', 'check V540', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), a, date '9973-10-01', date '9974-08-31')
        ON CONFLICT (name) DO NOTHING;
        INSERT INTO iam.person (id, surname, given_names) VALUES (who, 'ZZCHKV540', 'Maker'), (approver, 'ZZCHKV540', 'Approver'), (payer, 'ZZCHKV540', 'Payer');
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
        SELECT s, 'MOAUM/ADM/73/973101', 'MOAUM/CHK/73/9731', 'ZZCHKV540', 'Invented', code, 'UTME', a, 100, 100, 'ACTIVE', now()
          FROM ref.programme WHERE NOT coalesce(archived, false) ORDER BY code LIMIT 1;
        INSERT INTO people.student_contact (student_id, email, updated_at) VALUES (s, 'zzchkv540@example.invalid', now());
        -- a wallet withdrawal, approved by one officer
        PERFORM finance.credit_wallet(s, a, 5000, 'check V540 credit', 'SCHOLARSHIP');
        INSERT INTO finance.wallet_withdrawal (student_id, session, amount, bank_name, account_no, account_name, state, requested_by, decided_at, decided_by)
        VALUES (s, a, 1000, 'Zenith', '0123456788', 'ZZCHKV540 Invented', 'APPROVED', s, now(), approver) RETURNING id INTO wd;
        PERFORM set_config('moaum.actor_id', approver::text, true);
        BEGIN PERFORM finance.pay_withdrawal(wd, 'FT-CHK-540', v_today);
        EXCEPTION WHEN check_violation THEN e_same := 'REFUSED'; END;
        PERFORM set_config('moaum.actor_id', payer::text, true);
        BEGIN PERFORM finance.pay_withdrawal(wd, ' ', v_today);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; e_ref := split_part(msg, ':', 1); END;
        BEGIN PERFORM finance.pay_withdrawal(wd, 'FT-CHK-540', v_today + 2);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; e_future := split_part(msg, ':', 1); END;
        BEGIN PERFORM finance.pay_withdrawal(wd, 'FT-CHK-540', v_today - 30);
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; e_before := split_part(msg, ':', 1); END;
        BEGIN UPDATE finance.wallet_withdrawal SET state = 'PAID', paid_at = now(), paid_by = payer WHERE id = wd;
        EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT; e_hand := split_part(msg, ':', 1); END;
        PERFORM finance.pay_withdrawal(wd, ' FT-CHK-540 ', v_today);
        paid := (SELECT w.state || ':' || w.paid_ref || ':' || (w.paid_on = v_today) FROM finance.wallet_withdrawal w WHERE w.id = wd);
        told := (SELECT n.body FROM platform.notice n WHERE n.about_id = s AND n.channel = 'EMAIL' AND n.subject = 'Your refund is paid');
        queue := (SELECT q.state || ':' || (q.paid_on = v_today) FROM finance.withdrawal_queue(a) q WHERE q.id = wd);
        -- a refund approved five days ago and paid three days ago: on the ledger on the day it was paid
        PERFORM set_config('moaum.actor_id', who::text, true);
        rf := finance.propose_refund(s, 'ZZCHKV540, Invented', 'check V540: paid three days ago', 2000, NULL, NULL, NULL, NULL);
        rid := (SELECT id FROM finance.refund WHERE reference = rf);
        PERFORM finance.desk_refund_account(rid, 'GTB', 'ZZCHKV540 Invented', '2222222223');
        PERFORM set_config('moaum.actor_id', approver::text, true);
        PERFORM finance.approve_refund(rid);
        UPDATE finance.refund SET approved_at = now() - interval '5 days' WHERE id = rid;
        PERFORM set_config('moaum.actor_id', payer::text, true);
        PERFORM finance.pay_refund(rid, 'ft-chk-540', v_today - 3);
        PERFORM * FROM finance.gl_sync(NULL::int);
        posted := (SELECT (j.entry_date = v_today - 3)::text FROM finance.gl_journal j WHERE j.source_type = 'REFUND' AND j.source_ref = rf);
        report := (SELECT string_agg(p.kind || ':' || p.paid_on::text || ':' || p.transfer_reference || ':' || p.same_reference || ':' || p.account_number
                                     || ':' || coalesce(p.approved_by_name, '-') || '/' || coalesce(p.paid_by_name, '-'), ',' ORDER BY p.kind)
                     FROM finance.paid_out(v_today - 10, v_today) p WHERE p.number = 'MOAUM/CHK/73/9731');
        RAISE EXCEPTION 'the V540 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V540 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V540: a wallet withdrawal is paid only by another officer with the transfer reference and the date the money left (the student told both); a paid refund is posted on the day the money left; the Paid-out report holds both with the shared reference counted',
        coalesce(e_same = 'REFUSED' AND e_ref = 'WALLET_PAID_REFERENCE' AND e_future = 'WALLET_PAID_DATE' AND e_before = 'WALLET_PAID_DATE' AND e_hand = 'WALLET_PAID_EVIDENCE'
                 AND paid = 'PAID:FT-CHK-540:true' AND told LIKE '%bank transfer reference FT-CHK-540%' AND queue = 'PAID:true' AND posted = 'true'
                 AND report = 'REFUND:' || (v_today - 3)::text || ':ft-chk-540:1:2222222223:ZZCHKV540, Approver/ZZCHKV540, Payer,'
                           || 'WALLET:' || v_today::text || ':FT-CHK-540:1:0123456788:ZZCHKV540, Approver/ZZCHKV540, Payer', false),
        format('same officer %s, reference %s, future %s, before %s, by hand %s | paid %s | told %s | queue %s | posted on the day paid %s | report %s',
               e_same, e_ref, e_future, e_before, e_hand, paid, left(told, 140), queue, posted, report));
END $$;

-- ── V541: the readers the screens open read in one pass, with the same answers ──
-- Over 1,000 invented students, none of the readers the slowest screens open (the fee profiles, the session's charges and
-- positions, the collection by faculty, the students with no fee stated, the voluntary withdrawals due, the records check, the course issues, the catalogue
-- review and the code owners) calls any function as often as once a student; every course's issues read at once are
-- catalogue.course_issues' for each course, and every applicant's O'Level score read at once is admissions.olevel_score's.
-- The block undoes its writes.
DO $$
DECLARE msg text; n int := 1000; heavy text; reader text; before jsonb; issues_differ int; scores_differ int; checked int;
BEGIN
    PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
    PERFORM set_config('moaum.actor_office', 'registrar', true);
    BEGIN
        INSERT INTO people.student (id, matric_no, surname, other_names, state_of_origin, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
        SELECT gen_random_uuid(), 'MOAUM/V541/31/' || lpad(i::text, 4, '0'), 'ZZCHKV541', 'Student ' || i, CASE WHEN i % 3 = 0 THEN 'Benue' ELSE 'Kano' END,
               'C00023', CASE WHEN i % 5 = 0 THEN 'DIRECT_ENTRY' ELSE 'UTME' END, '2019/2020', 100, 100 * (1 + i % 6), 'ACTIVE', now()
          FROM generate_series(1, n) i;
        -- from here every function called outside a plan is counted (an inlined one costs nothing as a call), each reader apart
        PERFORM set_config('track_functions', 'all', true);
        FOREACH reader IN ARRAY ARRAY[
            'SELECT count(*) FROM finance.fee_profiles()',
            'SELECT sum(c.total) FROM finance.session_charges(''9931/9932'') c',
            'SELECT sum(length(p::text)) FROM finance.session_positions(''9931/9932'', NULL) p',
            'SELECT sum(c.due) FROM finance.collection_by_faculty(''9931/9932'') c',
            'SELECT count(*) FROM registration.voluntary_withdrawals_due()',
            'SELECT count(*) FROM people.record_issues()',
            'SELECT count(*) FROM finance.fee_gaps(''9931/9932'')',
            'SELECT count(*) FROM catalogue.course_issues_all()',
            'SELECT count(*) FROM catalogue.review_summary()',
            'SELECT count(*) FROM catalogue.code_owners()'] LOOP
            before := (SELECT coalesce(jsonb_object_agg(f.funcid::text, f.calls), '{}'::jsonb) FROM pg_stat_xact_user_functions f);
            EXECUTE reader;
            heavy := nullif(concat_ws('; ', heavy,
                (SELECT string_agg(f.schemaname || '.' || f.funcname || ' ' || (f.calls - coalesce((before ->> f.funcid::text)::bigint, 0)) || ' in ' || reader, ', ')
                   FROM pg_stat_xact_user_functions f WHERE f.calls - coalesce((before ->> f.funcid::text)::bigint, 0) >= n)), '');
        END LOOP;
        RAISE EXCEPTION 'the V541 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V541 check undoes its writes' THEN RAISE; END IF;
    END;
    issues_differ := (SELECT count(*) FROM (SELECT c.code, catalogue.course_issues(c.code) FROM catalogue.course c
                                            EXCEPT ALL SELECT * FROM catalogue.course_issues_all()) x)
                   + (SELECT count(*) FROM (SELECT * FROM catalogue.course_issues_all()
                                            EXCEPT ALL SELECT c.code, catalogue.course_issues(c.code) FROM catalogue.course c) x);
    SELECT count(*), count(*) FILTER (WHERE (o.sittings, o.relevant_known, o.points, o.bonus, o.total) IS DISTINCT FROM (s.sittings, s.relevant_known, s.points, s.bonus, s.total))
      INTO checked, scores_differ
      FROM (SELECT DISTINCT a.session FROM admissions.application a) ss
     CROSS JOIN LATERAL admissions.olevel_scores(ss.session) s
     CROSS JOIN LATERAL admissions.olevel_score(ss.session, s.jamb_key, s.programme_code) o;
    PERFORM pg_temp.assert('V541: the readers the slowest screens open call no function once a student, and the course issues and O''Level scores read at once are the per-course and per-candidate answers',
        coalesce(heavy IS NULL AND issues_differ = 0 AND scores_differ = 0, false),
        format('called once a student or more: %s | course issues differing %s | O''Level scores differing %s of %s', coalesce(heavy, 'none'), issues_differ, scores_differ, checked));
END $$;

-- ── V542: a state of origin is kept to the register's spelling ──
-- A spelling of a state is given the register's name (Cross-River, NASSARAWA, Fct-Abuja, Benue State); a country is a country
-- (Cameroun, Benin Republic); a student's state written in another spelling is stored as the register names it, by insert and by
-- update, and a country is kept as written; the records check no longer lists a country as a state spelt another way, and names
-- the department's postgraduate programmes for a postgraduate record on an undergraduate programme. The block undoes its writes.
DO $$
DECLARE msg text; named text; got text; listed int; sugg text; ug text;
        a uuid := gen_random_uuid(); b uuid := gen_random_uuid(); c uuid := gen_random_uuid();
BEGIN
    PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
    PERFORM set_config('moaum.actor_office', 'registrar', true);
    named := concat_ws(',', ref.state_named('Cross-River'), ref.state_named('NASSARAWA'), ref.state_named('Fct-Abuja'), ref.state_named('Benue State'),
                       coalesce(ref.state_named('Cameroun'), '-'), ref.country_named('Cameroun'), ref.country_named('BENIN REPUBLIC'));
    SELECT u.code INTO ug FROM ref.programme u
     WHERE u.category = 'UNDER GRADUATE' AND NOT u.archived
       AND EXISTS (SELECT 1 FROM ref.programme g WHERE g.dept_code = u.dept_code AND g.category = 'POST GRADUATE' AND NOT g.archived)
     ORDER BY u.code LIMIT 1;
    BEGIN
        INSERT INTO people.student (id, matric_no, surname, other_names, state_of_origin, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at) VALUES
            (a, 'MOAUM/V542/31/0001', 'ZZCHKV542', 'Spelt', 'Cross-River', 'C00023', 'UTME', '2025/2026', 100, 100, 'ACTIVE', now()),
            (b, 'MOAUM/V542/31/0002', 'ZZCHKV542', 'Abroad', 'Cameroun', 'C00023', 'UTME', '2025/2026', 100, 100, 'ACTIVE', now()),
            (c, 'MOAUM/V542/31/0003', 'ZZCHKV542', 'Postgraduate', 'Benue', ug, 'POSTGRADUATE', '2025/2026', 100, 700, 'ACTIVE', now());
        got := (SELECT string_agg(state_of_origin, ',' ORDER BY matric_no) FROM people.student WHERE id IN (a, b));
        UPDATE people.student SET state_of_origin = 'akwa-ibom' WHERE id = a;
        got := got || '|' || (SELECT state_of_origin FROM people.student WHERE id = a);
        UPDATE people.student SET state_of_origin = '  ' WHERE id = a;
        got := got || '|' || coalesce((SELECT state_of_origin FROM people.student WHERE id = a), 'none');
        listed := (SELECT count(*) FROM people.record_issues() x WHERE x.student_id IN (a, b) AND x.issue = 'STATE_NOT_ON_REGISTER');
        sugg := (SELECT x.suggestion FROM people.record_issues() x WHERE x.student_id = c AND x.issue = 'UG_POSTGRADUATE_ENTRY');
        RAISE EXCEPTION 'the V542 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V542 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V542: a state of origin is kept to the register''s spelling, a country stays a country, and the records check suggests what a record should say',
        coalesce(named = 'Cross River,Nasarawa,Federal Capital Territory,Benue,-,Cameroon,Benin'
                 AND got = 'Cross River,Cameroun|Akwa Ibom|none' AND listed = 0
                 AND (ug IS NULL OR sugg LIKE 'Postgraduate programmes of the department: %'), false),
        format('named %s | stored %s | listed as spelt otherwise %s | suggestion %s (programme %s)', named, got, listed, sugg, ug));
END $$;

-- ── V546: the live database's slowest statements, answered whether or not they are kept ──
-- platform.slow_statements answers on any database: where pg_stat_statements is loaded, the statements of this database ordered as
-- asked (each with calls, mean, worst and total time, at least the calls asked for); where it is not installed or not loaded (CI's
-- PostgreSQL), available false with the reason — never an error; the screens of the heavier functions are named; a function name not
-- written as schema.name is refused.
DO $$
DECLARE r jsonb; t jsonb; ok_rows boolean := true; refused boolean := false; named int;
BEGIN
    r := platform.slow_statements('MEAN', 1, 20);
    t := platform.slow_statements('nonsense', 0, 0);
    IF (r->>'available')::boolean THEN
        ok_rows := r->>'order' = 'MEAN' AND t->>'order' = 'MEAN' AND jsonb_array_length(t->'rows') <= 1
               AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r->'rows') x WHERE (x->>'calls')::bigint < 1 OR x->>'query' IS NULL)
               AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r->'rows') WITH ORDINALITY x(v, i)
                                 JOIN jsonb_array_elements(r->'rows') WITH ORDINALITY y(v, i) ON y.i = x.i + 1
                                WHERE (y.v->>'mean_ms')::numeric > (x.v->>'mean_ms')::numeric);
    ELSE
        ok_rows := r->>'reason' IS NOT NULL AND r->'rows' = '[]'::jsonb AND NOT (t->>'available')::boolean;
    END IF;
    named := (SELECT count(*) FROM platform.statement_screen WHERE function_name IN ('finance.session_positions', 'admissions.pipeline_stats', 'people.record_issues'));
    BEGIN
        INSERT INTO platform.statement_screen (function_name, screens) VALUES ('Not A Function; drop', 'nowhere');
    EXCEPTION WHEN check_violation THEN refused := true;
    END;
    PERFORM pg_temp.assert('V546: the slowest statements are read where they are kept and said to be unavailable where they are not, the heavier functions name their screens, and a bad name is refused',
        coalesce(ok_rows AND named = 3 AND refused, false),
        format('available %s (%s) | rows in order %s | screens named %s | bad name refused %s', r->>'available', coalesce(r->>'reason', r->>'order'), ok_rows, named, refused));
END $$;

-- ── V547: clearing the schedule shows what it would end and keeps nothing ──
-- For an invented session with a faculty-wide line, a programme line and a CCE line, finance.fee_upload_effect(…, 'CLEAR', scope)
-- ends every line (ALL), the full-time ones alone (FULL_TIME) or the CCE one alone (CCE), names the faculty and the programme left
-- with no fee, and leaves every line in force afterwards; an action it does not know is refused. The block undoes its writes.
DO $$
DECLARE msg text; fac text; prog text; e_all jsonb; e_ft jsonb; e_cce jsonb; still int; refused boolean := false;
BEGIN
    PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
    PERFORM set_config('moaum.actor_office', 'bursar', true);
    SELECT pr.code, pr.faculty_code INTO prog, fac FROM ref.programme pr WHERE NOT pr.archived AND pr.faculty_code IS NOT NULL ORDER BY pr.code LIMIT 1;
    BEGIN
        INSERT INTO finance.fee_schedule (session, item, amount, faculty_code, entry_mode) VALUES ('2947/2948', 'Tuition (V547 check)', 50000, fac, 'UTME');
        INSERT INTO finance.fee_schedule (session, item, amount, programme_code) VALUES ('2947/2948', 'Laboratory (V547 check)', 7000, prog);
        INSERT INTO finance.fee_schedule (session, item, amount, faculty_code, entry_mode) VALUES ('2947/2948', 'Tuition (V547 check, CCE)', 90000, fac, 'CCE');
        e_all := finance.fee_upload_effect('2947/2948', '[]'::jsonb, 'CLEAR', 'ALL');
        e_ft := finance.fee_upload_effect('2947/2948', '[]'::jsonb, 'CLEAR', 'FULL_TIME');
        e_cce := finance.fee_upload_effect('2947/2948', '[]'::jsonb, 'clear', 'CCE');
        still := (SELECT count(*) FROM finance.fee_schedule WHERE session = '2947/2948' AND ended_at IS NULL);
        BEGIN
            PERFORM finance.fee_upload_effect('2947/2948', '[]'::jsonb, 'EMPTY', NULL);
        EXCEPTION WHEN check_violation THEN refused := true;
        END;
        RAISE EXCEPTION 'the V547 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V547 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V547: clearing the schedule is shown first — the lines of each kind it would end and what is left with no fee — and nothing is kept',
        coalesce((e_all->'result'->>'ended')::int = 3 AND (e_all->>'linesAfter')::int = 0 AND e_all->>'scope' = 'ALL'
                 AND (e_ft->'result'->>'ended')::int = 2 AND (e_ft->>'linesAfter')::int = 1
                 AND (e_cce->'result'->>'ended')::int = 1 AND (e_cce->>'linesAfter')::int = 2 AND e_cce->>'scope' = 'CCE'
                 AND (SELECT count(*) FROM jsonb_array_elements(e_all->'groups') g WHERE (g->>'losesAll')::boolean) = 2
                 AND (SELECT count(*) FROM jsonb_array_elements(e_cce->'groups') g WHERE (g->>'losesAll')::boolean) = 0
                 AND still = 3 AND refused
                 AND NOT EXISTS (SELECT 1 FROM finance.fee_schedule WHERE session = '2947/2948'), false),
        format('ended all %s / full-time %s / CCE %s | left with no fee (all) %s | in force after the previews %s | unknown action refused %s',
               e_all->'result'->>'ended', e_ft->'result'->>'ended', e_cce->'result'->>'ended',
               (SELECT string_agg(coalesce(g->>'programme', g->>'faculty'), ', ') FROM jsonb_array_elements(e_all->'groups') g WHERE (g->>'losesAll')::boolean), still, refused));
END $$;

-- ── V548: the records check acted on ──
-- A state of origin a student gives on the Biodata form reaches an empty record (Kogi), the home state waits for the Registry
-- (and the records check says so) until the Registry gives it; the students with no state are told at most once a week each, and
-- only that issue is told; a postgraduate record on an undergraduate programme is moved with a reason to a postgraduate
-- programme at 800 Level, and an undergraduate record is not moved here. The block undoes its writes.
DO $$
DECLARE msg text; fac text; pgp text; a uuid := gen_random_uuid(); b uuid := gen_random_uuid(); c uuid := gen_random_uuid(); d uuid := gen_random_uuid();
        st_a text; st_b text; st_b2 text; sugg text; t1 jsonb; t2 jsonb; told_c int; refused_issue boolean := false;
        moved jsonb; after_move text; refused_reason boolean := false; refused_ug boolean := false; listed_d int;
BEGIN
    PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
    PERFORM set_config('moaum.actor_office', 'records', true);
    SELECT faculty_code INTO fac FROM ref.programme WHERE code = 'C00023';
    SELECT code INTO pgp FROM ref.programme WHERE category = 'POST GRADUATE' AND NOT archived ORDER BY code LIMIT 1;
    BEGIN
        INSERT INTO people.student (id, matric_no, surname, other_names, state_of_origin, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at) VALUES
            (a, 'MOAUM/V548/31/0001', 'ZZCHKV548', 'Kogi', NULL, 'C00023', 'UTME', '2025/2026', 100, 100, 'ACTIVE', now()),
            (b, 'MOAUM/V548/31/0002', 'ZZCHKV548', 'Home', NULL, 'C00023', 'UTME', '2025/2026', 100, 100, 'ACTIVE', now()),
            (c, 'MOAUM/V548/31/0003', 'ZZCHKV548', 'Silent', NULL, 'C00023', 'UTME', '2025/2026', 100, 100, 'ACTIVE', now()),
            (d, 'MOAUM/V548/31/0004', 'ZZCHKV548', 'Postgraduate', 'Benue', 'C00023', 'POSTGRADUATE', '2025/2026', 700, 700, 'ACTIVE', now());
        -- the students' own answers
        PERFORM set_config('moaum.actor_office', 'student', true);
        PERFORM set_config('moaum.actor_id', a::text, true);
        INSERT INTO people.biodata (student_id, field, value) VALUES (a, 'state_of_origin', 'kogi');
        PERFORM set_config('moaum.actor_id', b::text, true);
        INSERT INTO people.biodata (student_id, field, value) VALUES (b, 'state_of_origin', 'Benue');
        st_a := (SELECT state_of_origin FROM people.student WHERE id = a);
        st_b := coalesce((SELECT state_of_origin FROM people.student WHERE id = b), 'none');
        sugg := (SELECT x.suggestion FROM people.record_issues('NO_STATE_OF_ORIGIN', fac) x WHERE x.student_id = b);
        -- the students told, once a week
        PERFORM set_config('moaum.actor_office', 'records', true);
        PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
        t1 := people.tell_record_issue('NO_STATE_OF_ORIGIN', fac);
        t2 := people.tell_record_issue('no_state_of_origin', fac);
        told_c := (SELECT count(*) FROM people.record_issue_notice WHERE student_id = c);
        BEGIN
            PERFORM people.tell_record_issue('UG_POSTGRADUATE_ENTRY', fac);
        EXCEPTION WHEN check_violation THEN refused_issue := true;
        END;
        -- the Registry confirms the home state
        UPDATE people.biodata SET value = 'Benue' WHERE student_id = b AND field = 'state_of_origin';
        st_b2 := (SELECT state_of_origin FROM people.student WHERE id = b);
        -- a postgraduate record moved
        BEGIN
            PERFORM people.move_record_to_programme(d, coalesce(pgp, 'NONE'), 800, 'short');
        EXCEPTION WHEN check_violation THEN refused_reason := true;
        END;
        BEGIN
            PERFORM people.move_record_to_programme(c, coalesce(pgp, 'NONE'), 800, 'not a postgraduate record at all');
        EXCEPTION WHEN check_violation THEN refused_ug := true;
        END;
        IF pgp IS NOT NULL THEN
            moved := people.move_record_to_programme(d, pgp, 800, 'The School of Postgraduate Studies'' admission list');
            after_move := (SELECT programme_code || '/' || current_level || '/' || entry_mode FROM people.student WHERE id = d);
            listed_d := (SELECT count(*) FROM people.record_issues() x WHERE x.student_id = d);
        END IF;
        RAISE EXCEPTION 'the V548 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V548 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V548: a state given on the Biodata form reaches the record (the home state by the Registry), the students with none are told once a week, and a postgraduate record is moved to its programme with a reason',
        coalesce(st_a = 'Kogi' AND st_b = 'none' AND sugg LIKE 'The student gave Benue on the Biodata form%' AND st_b2 = 'Benue'
                 AND (t1->>'told')::int + (t1->>'unreached')::int >= 1 AND (t1->>'waitingForRegistry')::int >= 1
                 AND (t2->>'told')::int = 0 AND (t2->>'toldThisWeekAlready')::int = (t1->>'told')::int + (t1->>'unreached')::int
                 AND told_c = 1 AND refused_issue AND refused_reason AND refused_ug
                 AND (pgp IS NULL OR (after_move = pgp || '/800/POSTGRADUATE' AND listed_d = 0 AND moved->>'from' = 'C00023')), false),
        format('Kogi → %s | Benue by the student → %s (%s), by the Registry → %s | told %s then %s, the silent one %s time(s) | other issue refused %s | move: short reason refused %s, undergraduate refused %s, moved %s (%s, listed after %s)',
               st_a, st_b, sugg, st_b2, t1, t2, told_c, refused_issue, refused_reason, refused_ug, moved, after_move, listed_d));
END $$;

-- ── V549: each student's CGPA kept, made stale by what changes it ──
-- Worked out for every student, the kept CGPA is assessment.scope_cgpa's for each; an amended score makes its student's kept CGPA
-- stale while the reader already gives the new figure; a statement on the grading makes every kept CGPA stale; a student
-- removed with a registration takes the kept row along. The block undoes its writes.
DO $$
DECLARE msg text; r jsonb; loops int := 0; left_after int; differ int; p record; was numeric; fresh_after boolean; read_now numeric;
        computed numeric; held int; stale_all int; gone boolean := false; x uuid := gen_random_uuid(); xr uuid := gen_random_uuid(); xo uuid; xs text;
BEGIN
    PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
    PERFORM set_config('moaum.actor_office', 'exams', true);
    BEGIN
        LOOP
            r := assessment.refresh_kept_cgpa(2000);
            loops := loops + 1;
            EXIT WHEN (r->>'left')::int = 0 OR loops > 200;
        END LOOP;
        left_after := (r->>'left')::int;
        SELECT count(*) INTO differ
          FROM people.student s
          LEFT JOIN assessment.cgpa_kept k ON k.student_id = s.id
          LEFT JOIN assessment.scope_cgpa(ARRAY(SELECT id FROM people.student)) g ON g.student_id = s.id
         WHERE k.student_id IS NULL OR k.kept_gen IS DISTINCT FROM k.stale_gen OR k.cgpa IS DISTINCT FROM g.cgpa;
        -- an amended score
        SELECT s.sheet_id, s.student_id INTO p FROM assessment.score s
          JOIN assessment.score_sheet sh ON sh.id = s.sheet_id AND sh.stage = 'PUBLISHED'
          JOIN registration.course_registration cr ON cr.student_id = s.student_id AND cr.status IN ('APPROVED', 'LOCKED')
          JOIN registration.entry e ON e.registration_id = cr.id AND e.offering_id = sh.offering_id AND e.status IN ('REGISTERED', 'APPROVED')
         WHERE s.outcome = 'GRADED' ORDER BY s.student_id LIMIT 1;
        IF p.student_id IS NOT NULL THEN
            was := (SELECT k.cgpa FROM assessment.cgpa_kept k WHERE k.student_id = p.student_id);
            INSERT INTO assessment.score (sheet_id, student_id, version, ca, exam, outcome, reason)
            SELECT p.sheet_id, p.student_id, max(v.version) + 1, 5, 5, 'GRADED', 'the V549 check'
              FROM assessment.score v WHERE v.sheet_id = p.sheet_id AND v.student_id = p.student_id;
            fresh_after := (SELECT k.kept_gen = k.stale_gen FROM assessment.cgpa_kept k WHERE k.student_id = p.student_id);
            read_now := (SELECT g.cgpa FROM assessment.kept_cgpa(ARRAY[p.student_id]) g);
            computed := (SELECT g.cgpa FROM assessment.scope_cgpa(ARRAY[p.student_id]) g);
        END IF;
        -- the grading
        UPDATE policy.grade_band SET points = points WHERE false;
        held := (SELECT count(*) FROM assessment.cgpa_kept);
        stale_all := (SELECT count(*) FROM assessment.cgpa_kept WHERE kept_gen IS DISTINCT FROM stale_gen);
        -- a student removed with a registration
        SELECT o.id, o.session INTO xo, xs FROM catalogue.offering o JOIN policy.academic_session a ON a.name = o.session ORDER BY o.id LIMIT 1;
        INSERT INTO people.student (id, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level)
        VALUES (x, 'MOAUM/ADM/49/549001', 'ZZCHKV549', 'Removed', 'C00023', 'UTME', coalesce(xs, '2025/2026'), 100, 100);
        IF xo IS NOT NULL THEN
            INSERT INTO registration.course_registration (id, student_id, session, semester, level, status) VALUES (xr, x, xs, 1, 100, 'DRAFT');
            INSERT INTO registration.entry (registration_id, offering_id, units, status) VALUES (xr, xo, 3, 'REGISTERED');
        END IF;
        DELETE FROM registration.entry WHERE registration_id = xr;
        DELETE FROM registration.course_registration WHERE id = xr;
        DELETE FROM people.student WHERE id = x;
        gone := NOT EXISTS (SELECT 1 FROM assessment.cgpa_kept WHERE student_id = x);
        RAISE EXCEPTION 'the V549 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V549 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V549: the kept CGPA is scope_cgpa''s for every student, an amended score makes it stale while the reader gives the new figure, and the grading makes every one stale',
        coalesce(left_after = 0 AND differ = 0
                 AND (p.student_id IS NULL OR (NOT fresh_after AND read_now IS NOT DISTINCT FROM computed))
                 AND held > 0 AND stale_all = held AND gone, false),
        format('batches %s, left %s | differing from scope_cgpa %s | amended: %s → kept %s (current %s), read now %s, worked out %s | stale after the grading %s of %s | removed student''s row gone %s',
               loops, left_after, differ, p.student_id, was, fresh_after, read_now, computed, stale_all, held, gone));
END $$;

-- ── V550: the biodata counts are the statuses' own ──
-- people.biodata_status_counts, restated to hand people.biodata_statuses the students as one value, counts what the statuses of
-- the same students say: every student the biodata applies to, by status, and the migrated ones.
DO $$
DECLARE c record; d record;
BEGIN
    SELECT * INTO c FROM people.biodata_status_counts();
    SELECT count(*)::int AS total, count(*) FILTER (WHERE x.status = 'UP_TO_DATE')::int AS up_to_date, count(*) FILTER (WHERE x.status = 'INCOMPLETE')::int AS incomplete,
           count(*) FILTER (WHERE x.status = 'REVIEW_REQUIRED')::int AS review_required, count(*) FILTER (WHERE x.status = 'OUTDATED')::int AS outdated,
           count(*) FILTER (WHERE x.migrated)::int AS migrated
      INTO d FROM people.biodata_statuses(ARRAY(SELECT s.id FROM people.student s WHERE people.biodata_applicable(s.status))) x;
    PERFORM pg_temp.assert('V550: the biodata counts are what the statuses of the same students say',
        coalesce(c.total = (SELECT count(*) FROM people.student s WHERE people.biodata_applicable(s.status)) AND c.total = d.total
                 AND c.up_to_date = d.up_to_date AND c.incomplete = d.incomplete AND c.review_required = d.review_required
                 AND c.outdated = d.outdated AND c.migrated = d.migrated, false),
        format('counted %s / %s up to date / %s incomplete / %s to review / %s outdated / %s migrated; the statuses: %s', c.total, c.up_to_date, c.incomplete, c.review_required, c.outdated, c.migrated, d));
END $$;
-- ── V545. The money-out trail checked. Four refunds and a wallet withdrawal paid with transfer references; a statement uploaded:
--          a debit with a payout's reference and amount MATCHED, one found in the description MATCHED, one for the sum of the two
--          payouts sharing a reference MATCHED for both, one with nothing UNMATCHED, a reference with another amount AMOUNT_DIFFERS,
--          a credit not a payout; what was paid and not on it listed missing. The wallet on the ledger: a payment applied from the
--          wallet before it came onto the ledger stays Dr Bank, one after is Dr Student deposits & wallet, a top-up Cr it; a grant
--          credit Dr Grants, a NELFUND credit Dr Bank, a withdrawal paid Cr Bank — Disbursements on the day paid; the balance held
--          before is opened once against Opening balance / suspense. A refund approved ten days ago and unpaid is overdue at seven
--          and told once a day. Jaiz is checked, TAJ and Titan Trust not; a bank's paid accounts counted. The block undoes its writes ──
DO $$
DECLARE maker uuid := gen_random_uuid(); checker uuid := gen_random_uuid(); payer uuid := gen_random_uuid(); bursar uuid := gen_random_uuid();
        s uuid := gen_random_uuid(); a text := '9971/9972'; v_today date := (now() AT TIME ZONE 'Africa/Lagos')::date; v_from timestamptz;
        rf text; rid uuid; wd uuid; stmt uuid; lines text; missing text; pre text; app text; top text; grant_credit text; loan_credit text; wout text;
        had_opening boolean; v_open numeric; opening_ok boolean; rfu text; unpaid text; told int; told_again int; told_me bigint;
        banks text; evidence text; msg text; k text; amt numeric;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', maker::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM set_config('moaum.reason', 'check V545', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), a, date '9971-10-01', date '9972-08-31')
        ON CONFLICT (name) DO NOTHING;
        INSERT INTO iam.person (id, surname, given_names, email) VALUES (maker, 'ZZCHKV545', 'Maker', NULL), (checker, 'ZZCHKV545', 'Checker', NULL),
               (payer, 'ZZCHKV545', 'Payer', NULL), (bursar, 'ZZCHKV545', 'Bursar', 'zzchkv545bursar@example.invalid');
        INSERT INTO iam.office_assignment (id, person_id, office_code, scope_kind, instrument, granted_by, valid_from)
        VALUES (gen_random_uuid(), bursar, 'bursar', 'institution', 'check V545', maker, current_date - 1);
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
        SELECT s, 'MOAUM/ADM/71/971101', 'MOAUM/CHK/71/9711', 'ZZCHKV545', 'Invented', code, 'UTME', a, 100, 100, 'ACTIVE', now()
          FROM ref.programme WHERE NOT coalesce(archived, false) ORDER BY code LIMIT 1;

        -- refunds paid with transfer references: A 3,000; C 500 and 700 under one reference; D 900 (not on the statement)
        FOREACH k IN ARRAY ARRAY['A:3000', 'C:500', 'C:700', 'D:900'] LOOP
            amt := split_part(k, ':', 2)::numeric;
            PERFORM set_config('moaum.actor_id', maker::text, true);
            rf := finance.propose_refund(NULL, 'ZZCHKV545, ' || split_part(k, ':', 1), 'check V545 ' || k, amt, NULL, NULL, NULL, NULL);
            rid := (SELECT id FROM finance.refund WHERE reference = rf);
            PERFORM finance.desk_refund_account(rid, 'GTB', 'ZZCHKV545 Invented', '2222222223');
            PERFORM set_config('moaum.actor_id', checker::text, true);
            PERFORM finance.approve_refund(rid);
            PERFORM set_config('moaum.actor_id', payer::text, true);
            PERFORM finance.pay_refund(rid, 'FT-ZZ545-' || split_part(k, ':', 1), v_today);
        END LOOP;
        -- a wallet withdrawal paid, B 1,000, from a grant credited after the wallet came onto the ledger
        PERFORM set_config('moaum.actor_id', maker::text, true);
        PERFORM finance.credit_wallet(s, a, 5000, 'check V545 scholarship', 'SCHOLARSHIP');
        INSERT INTO finance.wallet_withdrawal (student_id, session, amount, bank_name, account_no, account_name, state, requested_by, decided_at, decided_by)
        VALUES (s, a, 1000, 'Zenith', '0123456788', 'ZZCHKV545 Invented', 'APPROVED', s, now(), checker) RETURNING id INTO wd;
        PERFORM set_config('moaum.actor_id', payer::text, true);
        PERFORM finance.pay_withdrawal(wd, 'FT-ZZ545-B', v_today);

        -- the statement
        stmt := finance.load_bank_statement('CHECK V545 disbursements', 'check.csv', jsonb_build_array(
            jsonb_build_object('date', v_today::text, 'reference', 'FT-ZZ545-A', 'description', 'Transfer', 'debit', '3,000.00'),
            jsonb_build_object('date', v_today::text, 'reference', '', 'description', 'TRF/FT-ZZ545-B/ZZCHKV545', 'debit', '1000'),
            jsonb_build_object('date', v_today::text, 'reference', 'FT-ZZ545-C', 'description', 'bulk', 'debit', '1200'),
            jsonb_build_object('date', v_today::text, 'reference', 'ZZ545-NOTHING', 'description', 'charges', 'debit', '50'),
            jsonb_build_object('date', v_today::text, 'reference', 'FT-ZZ545-A', 'description', 'again', 'debit', '2999'),
            jsonb_build_object('date', v_today::text, 'reference', '', 'description', 'inflow', 'credit', '5000')));
        lines := (SELECT string_agg(l.line_no || ':' || l.status || ':' || coalesce(l.matched_reference, '-') || ':' || coalesce(l.expected_amount::int::text, '-') || ':' || l.matched_payouts, ',' ORDER BY l.line_no)
                    FROM finance.bank_statement_line l WHERE l.statement_id = stmt);
        missing := (SELECT string_agg(m.transfer_reference, ',' ORDER BY m.transfer_reference) FROM finance.statement_missing(stmt) m WHERE m.transfer_reference LIKE 'FT-ZZ545-%');

        -- the wallet on the ledger
        PERFORM set_config('moaum.actor_id', maker::text, true);
        SELECT ws.gl_from INTO v_from FROM finance.wallet_setting ws WHERE ws.one;
        INSERT INTO finance.payment_reference (student_id, session, reference, purpose, amount, expires_at, confirmed_at, confirmed_by, channel, receipt_no, note) VALUES
            (s, a, 'MOAUM-ZZ545-PRE', 'School fees ' || a, 400, now(), v_from - interval '1 day', maker, 'NELFUND wallet', 'RCT-ZZ545-PRE', 'check V545'),
            (s, a, 'MOAUM-ZZ545-APP', 'School fees ' || a, 600, now(), now(), maker, 'NELFUND wallet', 'RCT-ZZ545-APP', 'check V545'),
            (s, a, 'MOAUM-ZZ545-TOP', 'Wallet top-up ' || a, 250, now(), now(), maker, 'INTERSWITCH', 'RCT-ZZ545-TOP', 'check V545');
        PERFORM finance.credit_wallet(s, a, 2000, 'check V545 NELFUND', 'NELFUND');
        -- a credit recorded before the wallet came onto the ledger
        INSERT INTO finance.wallet_entry (student_id, session, kind, amount, reference, note, source_code, recorded_at)
        VALUES (s, a, 'CREDIT', 777, 'ZZ545-OLD', 'check V545 before the ledger', 'NELFUND', NULL);
        had_opening := EXISTS (SELECT 1 FROM finance.gl_journal j WHERE j.source_type = 'WALLET' AND j.source_ref = 'WALLET-OPENING');
        v_open := finance.wallet_opening_balance();
        PERFORM * FROM finance.gl_sync(NULL::int);
        pre := (SELECT string_agg(p.account, '>' ORDER BY p.line) FROM finance.gl_journal j JOIN finance.gl_posting p ON p.journal_id = j.id WHERE j.source_type = 'PAYMENT' AND j.source_ref = 'MOAUM-ZZ545-PRE');
        app := (SELECT string_agg(p.account, '>' ORDER BY p.line) FROM finance.gl_journal j JOIN finance.gl_posting p ON p.journal_id = j.id WHERE j.source_type = 'PAYMENT' AND j.source_ref = 'MOAUM-ZZ545-APP');
        top := (SELECT string_agg(p.account, '>' ORDER BY p.line) FROM finance.gl_journal j JOIN finance.gl_posting p ON p.journal_id = j.id WHERE j.source_type = 'PAYMENT' AND j.source_ref = 'MOAUM-ZZ545-TOP');
        grant_credit := (SELECT string_agg(p.account, '>' ORDER BY p.line) FROM finance.wallet_entry e JOIN finance.gl_journal j ON j.source_type = 'WALLET' AND j.source_ref = 'WALLET-' || e.id
                           JOIN finance.gl_posting p ON p.journal_id = j.id WHERE e.student_id = s AND e.note = 'Bursary credit: check V545 scholarship');
        loan_credit := (SELECT string_agg(p.account, '>' ORDER BY p.line) FROM finance.wallet_entry e JOIN finance.gl_journal j ON j.source_type = 'WALLET' AND j.source_ref = 'WALLET-' || e.id
                          JOIN finance.gl_posting p ON p.journal_id = j.id WHERE e.student_id = s AND e.note = 'Bursary credit: check V545 NELFUND');
        wout := (SELECT string_agg(p.account, '>' ORDER BY p.line) || ':' || (max(j.entry_date) = v_today) FROM finance.wallet_withdrawal w
                   JOIN finance.gl_journal j ON j.source_type = 'WALLET' AND j.source_ref = 'WALLET-' || w.entry_id JOIN finance.gl_posting p ON p.journal_id = j.id WHERE w.id = wd);
        opening_ok := CASE WHEN had_opening THEN (SELECT count(*) = 1 FROM finance.gl_journal j WHERE j.source_type = 'WALLET' AND j.source_ref = 'WALLET-OPENING')
                           ELSE (SELECT string_agg(p.account || '=' || (p.debit + p.credit), '>' ORDER BY p.line) FROM finance.gl_journal j JOIN finance.gl_posting p ON p.journal_id = j.id
                                  WHERE j.source_type = 'WALLET' AND j.source_ref = 'WALLET-OPENING') = '3900=' || abs(v_open) || '>2100=' || abs(v_open) END
                      AND v_open >= 777;

        -- approved, not paid: ten days waiting, the Bursary's figure seven
        PERFORM set_config('moaum.actor_id', maker::text, true);
        rfu := finance.propose_refund(NULL, 'ZZCHKV545, U', 'check V545 unpaid', 1500, NULL, NULL, NULL, NULL);
        PERFORM set_config('moaum.actor_id', checker::text, true);
        PERFORM finance.approve_refund((SELECT id FROM finance.refund WHERE reference = rfu));
        UPDATE finance.refund SET approved_at = now() - interval '10 days' WHERE reference = rfu;
        UPDATE finance.payout_watch SET unpaid_days = 7 WHERE row_no;
        unpaid := (SELECT u.kind || ':' || u.days_waiting || ':' || u.overdue || ':' || u.account_ready FROM finance.unpaid_payouts() u WHERE u.reference = rfu);
        told := finance.watch_unpaid_payouts();
        told_again := finance.watch_unpaid_payouts();
        told_me := (SELECT count(*) FROM platform.notice n WHERE n.template_key = 'UNPAID_PAYOUTS' AND n.about_id = bursar AND n.channel = 'EMAIL');

        -- the banks
        banks := (SELECT string_agg(b.code || '=' || b.nuban_check, ',' ORDER BY b.code) FROM finance.bank b WHERE b.code IN ('101', '102', '103', '105', '301', '302', '303'));
        evidence := (SELECT (e.paid_accounts >= 1 AND e.passing = e.paid_accounts)::text FROM finance.bank_evidence() e WHERE e.code = '058');
        RAISE EXCEPTION 'the V545 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V545 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V545: a bank statement''s debits are matched to what was paid out by reference and amount, the rest listed both ways; wallet money is held for students on the ledger from now on; approved but unpaid payouts are told once a day; the newer banks whose codes are confirmed are checked',
        coalesce(lines = '1:MATCHED:FT-ZZ545-A:3000:1,2:MATCHED:FT-ZZ545-B:1000:1,3:MATCHED:FT-ZZ545-C:1200:2,4:UNMATCHED:-:-:0,5:AMOUNT_DIFFERS:FT-ZZ545-A:3000:0,6:CREDIT:-:-:0'
                 AND missing = 'FT-ZZ545-D'
                 AND pre = '1010>4010' AND app = '2100>4010' AND top = '1010>2100' AND grant_credit = '5240>2100' AND loan_credit = '1010>2100' AND wout = '2100>1020:true'
                 AND opening_ok
                 AND unpaid = 'REFUND:10:true:false' AND told >= 1 AND told_again = 0 AND told_me = 1
                 AND banks = '101=true,102=false,103=true,105=true,301=true,302=false,303=true' AND evidence = 'true', false),
        format('lines %s | missing %s | ledger pre %s app %s top %s grant %s loan %s out %s | opening %s (%s, had %s) | unpaid %s told %s/%s me %s | banks %s evidence %s',
               lines, missing, pre, app, top, grant_credit, loan_credit, wout, opening_ok, v_open, had_opening, unpaid, told, told_again, told_me, banks, evidence));
END $$;
-- ── V552. The collections statement matched and the wallet's opening balance settled. Payments issued to an invented student:
--          a credit with a confirmed reference and its amount MATCHED and reconciled, one with the reference written without its
--          hyphens and another amount AMOUNT_DIFFERS (a discrepancy recorded), one for a reference never confirmed
--          RECEIVED_NOT_CONFIRMED, the first reference again DUPLICATE, a NELFUND remittance by its reference MATCHED, a gateway's
--          one sum UNMATCHED until marked the settlement of the gateway's day (two payments reconciled, NGN 50 of charges), a debit
--          DEBIT; confirmed but not in the bank: only the payment no line found (not one from the old portal, not one reconciled
--          before); the unconfirmed credit goes to the bank credits once, proposed against its reference, and the second officer's
--          approval confirms it. The wallet's opening balance by source with the account each part belongs in; reclassified out of
--          suspense once posted, never to the wallet or suspense itself, never more than remains. The block undoes its writes ──
DO $$
DECLARE maker uuid := gen_random_uuid(); checker uuid := gen_random_uuid(); s uuid := gen_random_uuid(); a text := '9967/9968';
        v_today date := (now() AT TIME ZONE 'Africa/Lagos')::date; stmt uuid; lines text; recon text; before_settle text; groups text;
        settled jsonb; after_settle text; bad_settle text; bad_debit text; bc uuid; bc_state text; sent_twice text; not_unconfirmed text;
        confirmed_after boolean; listed_after boolean; had_opening boolean; breakdown text; not_posted text; st_posted numeric; st_recl numeric; st_rem numeric;
        after_recl numeric; after_rem numeric;
        reclass text; too_much text; wrong_account text; empty_lines text; second_ref text; msg text; v_line uuid; jid uuid;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', maker::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM set_config('moaum.reason', 'check V552', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), a, date '9967-10-01', date '9968-08-31')
        ON CONFLICT (name) DO NOTHING;
        INSERT INTO iam.person (id, surname, given_names, email) VALUES (maker, 'ZZCHKV552', 'Maker', NULL), (checker, 'ZZCHKV552', 'Checker', NULL);
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
        SELECT s, 'MOAUM/ADM/67/996701', 'MOAUM/CHK/67/9967', 'ZZCHKV552', 'Invented', code, 'UTME', a, 100, 100, 'ACTIVE', now()
          FROM ref.programme WHERE NOT coalesce(archived, false) ORDER BY code LIMIT 1;
        INSERT INTO finance.payment_reference (student_id, session, reference, purpose, amount, expires_at, confirmed_at, confirmed_by, channel, receipt_no, note) VALUES
            (s, a, 'MOAUM-FEE-996701-0001', 'School fees ' || a, 5000, now() + interval '7 days', now(), maker, 'Bank transfer', 'RCT-ZZ552-0001', 'check V552'),
            (s, a, 'MOAUM-FEE-996701-0002', 'School fees ' || a, 3000, now() + interval '7 days', now(), maker, 'Card · Paystack', 'RCT-ZZ552-0002', 'check V552'),
            (s, a, 'MOAUM-FEE-996701-0003', 'School fees ' || a, 2500, now() + interval '7 days', NULL, NULL, NULL, NULL, 'check V552'),
            (s, a, 'MOAUM-FEE-996701-0004', 'School fees ' || a, 1000, now() + interval '7 days', now(), maker, 'ZZ552 Gateway', 'RCT-ZZ552-0004', 'check V552'),
            (s, a, 'MOAUM-FEE-996701-0005', 'School fees ' || a, 1000, now() + interval '7 days', now(), maker, 'ZZ552 Gateway', 'RCT-ZZ552-0005', 'check V552'),
            (s, a, 'MOAUM-FEE-996701-0006', 'School fees ' || a, 700, now() + interval '7 days', now(), maker, 'Bank transfer', 'RCT-ZZ552-0006', 'check V552'),
            (s, a, 'MOAUM-FEE-996701-0007', 'School fees ' || a, 900, now() + interval '7 days', now(), maker, 'Legacy', 'RCT-ZZ552-0007', 'check V552'),
            (s, a, 'MOAUM-FEE-996701-0008', 'School fees ' || a, 400, now() + interval '7 days', now(), maker, 'Bank transfer', 'RCT-ZZ552-0008', 'check V552');
        PERFORM finance.reconcile_payment('MOAUM-FEE-996701-0008', 'MATCHED', 'ZZ552-BANK', 'check V552: reconciled before');
        INSERT INTO finance.nelfund_batch (ref, session, received_on, amount, rows_read, note) VALUES ('ZZ552-NELF', a, v_today - 2, 40000, 1, 'check V552');

        stmt := finance.load_collections_statement('CHECK V552 collections', 'collections.csv', jsonb_build_array(
            jsonb_build_object('date', v_today::text, 'reference', 'MOAUM-FEE-996701-0001', 'description', 'Transfer', 'credit', '5,000.00'),
            jsonb_build_object('date', v_today::text, 'reference', '', 'description', 'NIP TRF/MOAUMFEE9967010002/ZZCHKV552', 'credit', '3100'),
            jsonb_build_object('date', v_today::text, 'reference', '', 'description', 'Transfer MOAUM-FEE-996701-0003 ZZCHKV552', 'credit', '2500'),
            jsonb_build_object('date', v_today::text, 'reference', 'MOAUM-FEE-996701-0001', 'description', 'Transfer again', 'credit', '5000'),
            jsonb_build_object('date', v_today::text, 'reference', '', 'description', 'NELFUND REMITTANCE ZZ552-NELF', 'credit', '40000'),
            jsonb_build_object('date', v_today::text, 'reference', '', 'description', 'ZZ552 GATEWAY SETTLEMENT', 'credit', '1950'),
            jsonb_build_object('date', v_today::text, 'reference', '', 'description', 'charges', 'debit', '100')));
        lines := (SELECT string_agg(l.line_no || ':' || l.status || ':' || coalesce(l.matched_kind, '-') || ':' || coalesce(l.matched_reference, '-') || ':' || coalesce(l.expected_amount::int::text, '-'), ',' ORDER BY l.line_no)
                    FROM finance.bank_statement_line l WHERE l.statement_id = stmt);
        recon := (SELECT string_agg(right(pr.reference, 4) || '=' || pr.result, ',' ORDER BY pr.reference, pr.result)
                    FROM finance.payment_reconciliation pr WHERE pr.reference LIKE 'MOAUM-FEE-996701-%' AND pr.note LIKE 'Collections statement CHECK V552%');
        before_settle := (SELECT string_agg(right(n.reference, 4), ',' ORDER BY n.reference) FROM finance.collections_not_received(stmt) n WHERE n.reference LIKE 'MOAUM-FEE-996701-%');
        groups := (SELECT string_agg(u.channel || ':' || (u.day = v_today) || ':' || u.payments || ':' || u.total::int, ',') FROM finance.collections_unmatched(stmt) u WHERE u.channel = 'ZZ552 Gateway');

        -- the gateway's sum marked its day's settlement
        v_line := (SELECT l.id FROM finance.bank_statement_line l WHERE l.statement_id = stmt AND l.line_no = 6);
        settled := finance.settle_collections_line(v_line, 'ZZ552 Gateway', v_today);
        after_settle := (SELECT string_agg(right(n.reference, 4), ',' ORDER BY n.reference) FROM finance.collections_not_received(stmt) n WHERE n.reference LIKE 'MOAUM-FEE-996701-%');
        BEGIN
            PERFORM finance.settle_collections_line(v_line, 'ZZ552 Gateway', v_today);
        EXCEPTION WHEN check_violation THEN bad_settle := split_part(SQLERRM, ':', 1);
        END;
        BEGIN
            PERFORM finance.settle_collections_line((SELECT l.id FROM finance.bank_statement_line l WHERE l.statement_id = stmt AND l.line_no = 7), 'Bank transfer', v_today);
        EXCEPTION WHEN check_violation THEN bad_debit := split_part(SQLERRM, ':', 1);
        END;

        -- the credit never confirmed sent to the bank credits, once; the second officer's approval confirms it
        bc := finance.collections_line_to_bank_credit((SELECT l.id FROM finance.bank_statement_line l WHERE l.statement_id = stmt AND l.line_no = 3));
        bc_state := (SELECT c.state || ':' || c.proposed_reference || ':' || c.amount::int FROM finance.bank_credit c WHERE c.id = bc);
        BEGIN
            PERFORM finance.collections_line_to_bank_credit((SELECT l.id FROM finance.bank_statement_line l WHERE l.statement_id = stmt AND l.line_no = 3));
        EXCEPTION WHEN check_violation THEN sent_twice := split_part(SQLERRM, ':', 1);
        END;
        BEGIN
            PERFORM finance.collections_line_to_bank_credit((SELECT l.id FROM finance.bank_statement_line l WHERE l.statement_id = stmt AND l.line_no = 1));
        EXCEPTION WHEN check_violation THEN not_unconfirmed := split_part(SQLERRM, ':', 1);
        END;
        PERFORM set_config('moaum.actor_id', checker::text, true);
        PERFORM finance.approve_bank_credit(bc);
        PERFORM set_config('moaum.actor_id', maker::text, true);
        confirmed_after := (SELECT r.confirmed_at IS NOT NULL FROM finance.payment_reference r WHERE r.reference = 'MOAUM-FEE-996701-0003');
        listed_after := EXISTS (SELECT 1 FROM finance.collections_not_received(stmt) n WHERE n.reference = 'MOAUM-FEE-996701-0003');

        -- the wallet's opening balance: entries recorded before the wallet came onto the ledger
        had_opening := EXISTS (SELECT 1 FROM finance.gl_journal j WHERE j.source_type = 'WALLET' AND j.source_ref = 'WALLET-OPENING');
        INSERT INTO finance.wallet_entry (student_id, session, kind, amount, reference, note, source_code, recorded_at) VALUES
            (s, a, 'CREDIT', 3000, 'ZZ552-W1', 'check V552 loan', 'NELFUND', NULL),
            (s, a, 'APPLIED', 800, 'ZZ552-W2', 'check V552 applied', 'NELFUND', NULL),
            (s, a, 'CREDIT', 1000, 'ZZ552-W3', 'check V552 grant', 'SCHOLARSHIP', NULL),
            (s, a, 'TOPUP', 500, 'ZZ552-W4', 'check V552 own money', NULL, NULL),
            (s, a, 'CREDIT', 200, 'ZZ552-W5', 'check V552 no source', NULL, NULL);
        breakdown := (SELECT string_agg(b.source_code || ':' || b.nature || ':' || b.amount::int || ':' || coalesce(b.suggested_account, '-'), ',')
                        FROM finance.wallet_opening_breakdown() b WHERE b.session = a);
        IF NOT had_opening THEN
            BEGIN
                PERFORM finance.reclassify_wallet_opening(jsonb_build_array(jsonb_build_object('account', '1010', 'amount', 100)));
            EXCEPTION WHEN check_violation THEN not_posted := split_part(SQLERRM, ':', 1);
            END;
            PERFORM * FROM finance.gl_sync(NULL::int);
        END IF;
        SELECT o.posted, o.reclassified, o.remaining INTO st_posted, st_recl, st_rem FROM finance.wallet_opening_state() o;
        IF had_opening THEN
            -- an opening posted before this block holds the entries recorded then; reclassify within what remains of it
            not_posted := 'WALLET_OPENING_NOT_POSTED';
        END IF;
        BEGIN
            PERFORM finance.reclassify_wallet_opening(jsonb_build_array(jsonb_build_object('account', '1010', 'amount', st_rem + 1)));
        EXCEPTION WHEN check_violation THEN too_much := split_part(SQLERRM, ':', 1);
        END;
        BEGIN
            PERFORM finance.reclassify_wallet_opening(jsonb_build_array(jsonb_build_object('account', '2100', 'amount', 1)));
        EXCEPTION WHEN check_violation THEN wrong_account := split_part(SQLERRM, ':', 1);
        END;
        BEGIN
            PERFORM finance.reclassify_wallet_opening(jsonb_build_array(jsonb_build_object('account', '1010', 'amount', 0)));
        EXCEPTION WHEN check_violation THEN empty_lines := split_part(SQLERRM, ':', 1);
        END;
        IF st_rem >= 3900 THEN
            jid := finance.reclassify_wallet_opening(jsonb_build_array(
                       jsonb_build_object('account', '1010', 'amount', 2200), jsonb_build_object('account', '5240', 'amount', 1000),
                       jsonb_build_object('account', '4090', 'amount', 500)));
            reclass := (SELECT string_agg(p.account || (CASE WHEN p.debit > 0 THEN '+' ELSE '-' END) || (p.debit + p.credit)::int, ',' ORDER BY p.line)
                          FROM finance.gl_posting p WHERE p.journal_id = jid);
            jid := finance.reclassify_wallet_opening(jsonb_build_array(jsonb_build_object('account', '4090', 'amount', 200)));
            second_ref := (SELECT j.source_ref FROM finance.gl_journal j WHERE j.id = jid);
            SELECT o.reclassified, o.remaining INTO after_recl, after_rem FROM finance.wallet_opening_state() o;
        END IF;
        RAISE EXCEPTION 'the V552 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V552 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V552: a collections statement''s credits are matched to the payments the portal issued and confirmed and to NELFUND remittances, what the bank received and the portal never confirmed goes to the bank credits, a gateway''s sum settles its day, and what was confirmed and not seen in the bank is listed; the wallet''s opening balance is shown by source and reclassified out of suspense, never more than remains',
        coalesce(lines = '1:MATCHED:PAYMENT:MOAUM-FEE-996701-0001:5000,2:AMOUNT_DIFFERS:PAYMENT:MOAUM-FEE-996701-0002:3000,3:RECEIVED_NOT_CONFIRMED:PAYMENT:MOAUM-FEE-996701-0003:2500,'
                       || '4:DUPLICATE:PAYMENT:MOAUM-FEE-996701-0001:5000,5:MATCHED:NELFUND:ZZ552-NELF:40000,6:UNMATCHED:-:-:-,7:DEBIT:-:-:-'
                 AND recon = '0001=MATCHED,0002=DISCREPANCY'
                 AND before_settle = '0004,0005,0006' AND groups = 'ZZ552 Gateway:true:2:2000'
                 AND settled = '{"payments": 2, "total": 2000, "credited": 1950, "difference": 50}'::jsonb AND after_settle = '0006'
                 AND bad_settle = 'SETTLEMENT_LINE' AND bad_debit = 'SETTLEMENT_LINE'
                 AND bc_state = 'PROPOSED:MOAUM-FEE-996701-0003:2500' AND sent_twice = 'STATEMENT_LINE_SENT' AND not_unconfirmed = 'STATEMENT_LINE_NOT_UNCONFIRMED'
                 AND confirmed_after AND NOT listed_after
                 AND breakdown = 'NELFUND:LOAN:2200:1010,SCHOLARSHIP:GRANT:1000:5240,SELF:SELF:500:4090,UNATTRIBUTED:UNKNOWN:200:-'
                 AND not_posted = 'WALLET_OPENING_NOT_POSTED' AND st_posted > 0 AND (had_opening OR st_recl = 0 AND st_rem = st_posted)
                 AND too_much = 'WALLET_RECLASS_TOO_MUCH' AND wrong_account = 'WALLET_RECLASS_ACCOUNT' AND empty_lines = 'WALLET_RECLASS_EMPTY'
                 AND (had_opening AND st_rem < 3900
                      OR reclass = '1010+2200,5240+1000,4090+500,3900-3700' AND second_ref = 'WALLET-OPENING-RECLASS-2'
                         AND after_recl = st_recl + 3900 AND after_rem = st_rem - 3900), false),
        format('lines %s | recon %s | not received %s groups %s | settled %s after %s bad %s/%s | bank credit %s twice %s other %s confirmed %s listed %s | breakdown %s | not posted %s state %s/%s/%s (had %s) | too much %s account %s empty %s | reclass %s second %s after %s/%s',
               lines, recon, before_settle, groups, settled, after_settle, bad_settle, bad_debit, bc_state, sent_twice, not_unconfirmed, confirmed_after, listed_after,
               breakdown, not_posted, st_posted, st_recl, st_rem, had_opening, too_much, wrong_account, empty_lines, reclass, second_ref, after_recl, after_rem));
END $$;

-- ── V553: the Biodata form and the record kept in agreement ──
-- A student's own date of birth fills an empty record and leaves a stated one (which the records check then lists with both
-- dates), an office's corrects it, a date that is none changes nothing; the form's state is kept to the register's spelling and,
-- named otherwise than the record, is listed with both; a phone (+234…) and an e-mail given on the form fill an empty contact,
-- an unusable phone does not. The block undoes its writes.
DO $$
DECLARE msg text; a uuid := gen_random_uuid(); b uuid := gen_random_uuid();
        dob_a date; dob_b1 date; dob_b2 date; dob_b3 date; form_state text; rec_state text; phone_a text; email_a text; phone_b text;
        listed text; sugg_state text; sugg_dob text;
BEGIN
    PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
    PERFORM set_config('moaum.actor_office', 'records', true);
    BEGIN
        INSERT INTO people.student (id, matric_no, surname, other_names, state_of_origin, date_of_birth, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at) VALUES
            (a, 'MOAUM/V553/31/0001', 'ZZCHKV553', 'Empty', 'Benue', NULL, 'C00023', 'UTME', '2025/2026', 100, 100, 'ACTIVE', now()),
            (b, 'MOAUM/V553/31/0002', 'ZZCHKV553', 'Stated', 'Benue', date '2003-08-20', 'C00023', 'UTME', '2025/2026', 100, 100, 'ACTIVE', now());
        -- the students' own answers
        PERFORM set_config('moaum.actor_office', 'student', true);
        PERFORM set_config('moaum.actor_id', a::text, true);
        INSERT INTO people.biodata (student_id, field, value) VALUES (a, 'date_of_birth', '2004-05-06'), (a, 'mobile', '+234 803 123 4567'), (a, 'personal_email', ' Ada.V553@Example.com');
        PERFORM set_config('moaum.actor_id', b::text, true);
        INSERT INTO people.biodata (student_id, field, value) VALUES (b, 'date_of_birth', '2001-01-02'), (b, 'state_of_origin', 'kogi state'), (b, 'mobile', '12345');
        dob_a := (SELECT date_of_birth FROM people.student WHERE id = a);
        dob_b1 := (SELECT date_of_birth FROM people.student WHERE id = b);
        form_state := (SELECT value FROM people.biodata WHERE student_id = b AND field = 'state_of_origin');
        rec_state := (SELECT state_of_origin FROM people.student WHERE id = b);
        SELECT c.phone, c.email INTO phone_a, email_a FROM people.student_contact c WHERE c.student_id = a;
        phone_b := coalesce((SELECT c.phone FROM people.student_contact c WHERE c.student_id = b), 'none');
        listed := (SELECT string_agg(x.issue, ',' ORDER BY x.issue) FROM people.record_issues() x WHERE x.student_id = b);
        sugg_state := (SELECT x.suggestion FROM people.record_issues('FORM_STATE_DIFFERS') x WHERE x.student_id = b);
        sugg_dob := (SELECT x.suggestion FROM people.record_issues('FORM_BIRTH_DATE_DIFFERS') x WHERE x.student_id = b);
        -- an office corrects; a date that is none changes nothing
        PERFORM set_config('moaum.actor_office', 'records', true);
        PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
        UPDATE people.biodata SET value = '1999-12-31' WHERE student_id = b AND field = 'date_of_birth';
        dob_b2 := (SELECT date_of_birth FROM people.student WHERE id = b);
        UPDATE people.biodata SET value = 'last year' WHERE student_id = b AND field = 'date_of_birth';
        dob_b3 := (SELECT date_of_birth FROM people.student WHERE id = b);
        RAISE EXCEPTION 'the V553 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V553 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V553: the Biodata form reaches the record by its rules, keeps the register''s spelling, fills an empty contact, and the records check lists a form at odds with the record',
        coalesce(dob_a = date '2004-05-06' AND dob_b1 = date '2003-08-20' AND dob_b2 = date '1999-12-31' AND dob_b3 = date '1999-12-31'
                 AND form_state = 'Kogi' AND rec_state = 'Benue' AND phone_a = '08031234567' AND email_a = 'ada.v553@example.com' AND phone_b = 'none'
                 AND listed = 'FORM_BIRTH_DATE_DIFFERS,FORM_STATE_DIFFERS'
                 AND sugg_state = 'The Biodata form says Kogi; the record says Benue'
                 AND sugg_dob = 'The Biodata form says 2 Jan 2001; the record says 20 Aug 2003', false),
        format('dob: filled %s, kept %s, office %s, not a date %s | form state %s, record %s | contact %s %s, unusable phone %s | listed %s | %s | %s',
               dob_a, dob_b1, dob_b2, dob_b3, form_state, rec_state, phone_a, email_a, phone_b, listed, sugg_state, sugg_dob));
END $$;

-- ── V555: Slow Statements over a period, a reset for ICT, ICT told of a statement turned slow ──
-- Over the last week the statements are read by the snapshots (or since the reset while none is kept), or said to be unavailable
-- where they are not kept — never an error; a snapshot is taken or said to be impossible; a statement whose average over the last
-- day (1,000 ms) is at least twice the week before's (300 ms) is kept as an alert once a day, a steady one is not; a reset needs a
-- reason and is refused, with its reason, where the statistics are not kept. The block undoes its writes.
DO $$
DECLARE msg text; w jsonb; snap jsonb; first int; again int; alerted text; refused_reason boolean := false; reset_answer text;
        t0 timestamptz := timestamptz '2947-03-17 00:05+01';
BEGIN
    PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
    PERFORM set_config('moaum.actor_office', 'ict', true);
    w := platform.slow_statements('MEAN', 1, 5, 7);
    BEGIN
        snap := platform.take_statement_snapshot();
        INSERT INTO platform.statement_snapshot (taken_at, queryid, query, calls, total_ms, rows) VALUES
          (t0 - interval '8 days', 9547001, 'SELECT * FROM finance.fee_gaps($1)', 0, 0, 0),
          (t0 - interval '1 day', 9547001, 'SELECT * FROM finance.fee_gaps($1)', 100, 30000, 100),
          (t0, 9547001, 'SELECT * FROM finance.fee_gaps($1)', 150, 80000, 150),
          (t0 - interval '8 days', 9547002, 'SELECT * FROM finance.steady($1)', 0, 0, 0),
          (t0 - interval '1 day', 9547002, 'SELECT * FROM finance.steady($1)', 100, 1000, 100),
          (t0, 9547002, 'SELECT * FROM finance.steady($1)', 150, 1500, 150);
        first := platform.tell_slower_statements(t0);
        again := platform.tell_slower_statements(t0);
        alerted := (SELECT string_agg(queryid || ':' || mean_ms || '/' || before_ms, ',') FROM platform.statement_alert WHERE queryid IN (9547001, 9547002));
        BEGIN
            PERFORM platform.reset_statement_stats('x');
        EXCEPTION WHEN check_violation THEN refused_reason := SQLERRM LIKE 'STATEMENTS_RESET_REASON%';
        END;
        BEGIN
            reset_answer := CASE WHEN platform.reset_statement_stats('the check of V555') ? 'reset_at' THEN 'reset' END;
        EXCEPTION WHEN check_violation OR insufficient_privilege THEN reset_answer := split_part(SQLERRM, ':', 1);
        END;
        RAISE EXCEPTION 'the V555 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V555 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V555: the statements over a period, the nightly snapshot, a statement turned slow told once a day, and a reset with its reason',
        coalesce(CASE WHEN (w->>'available')::boolean THEN w->>'period' IN ('DAYS', 'RESET') ELSE w->>'reason' IS NOT NULL END
                 AND (snap->>'available') IS NOT NULL
                 AND first = 1 AND again = 0 AND alerted = '9547001:1000.0/300.0' AND refused_reason
                 AND reset_answer IN ('reset', 'STATEMENTS_NOT_KEPT', 'STATEMENTS_RESET_REFUSED'), false),
        format('week %s | snapshot %s | slower %s then %s, kept %s | short reason refused %s | reset %s', w - 'rows', snap, first, again, alerted, refused_reason, reset_answer));
END $$;

-- ── V556: e-mail held while the mail server refuses the portal ──
-- A failure of the account or the server holds e-mail 5 minutes, the next 10; the e-mail provider then reads FAILING with the
-- failure in words before the server's error (never STUCK); the hold is ended by an e-mail that goes, or ICT's settings. The block
-- undoes its writes.
DO $$
DECLARE msg text; u1 timestamptz; u2 timestamptz; st jsonb; email record; resumed boolean; after jsonb;
BEGIN
    PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
    PERFORM set_config('moaum.actor_office', 'ict', true);
    BEGIN
        PERFORM platform.smtp_resume();
        u1 := platform.smtp_hold('SIGN_IN', 'The server refused the sign-in.', 'MailAuthenticationException: 535 5.7.139 Authentication unsuccessful');
        u2 := platform.smtp_hold('SIGN_IN', 'The server refused the sign-in.', 'MailAuthenticationException: 535 5.7.139 Authentication unsuccessful');
        st := platform.smtp_pause_state();
        SELECT p.state, p.last_error INTO email FROM platform.provider_status() p WHERE p.channel = 'EMAIL';
        resumed := platform.smtp_resume();
        after := platform.smtp_pause_state();
        RAISE EXCEPTION 'the V556 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V556 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V556: e-mail is held 5 then 10 minutes after the server refuses the portal, read as FAILING in words, and resumed',
        coalesce(u1 BETWEEN now() + interval '299 seconds' AND now() + interval '301 seconds'
                 AND u2 BETWEEN now() + interval '599 seconds' AND now() + interval '601 seconds'
                 AND (st->>'held')::boolean AND (st->>'paused')::boolean AND (st->>'failures')::int = 2
                 AND (email.state = 'OFF' OR (email.state = 'FAILING' AND email.last_error LIKE 'The server refused the sign-in. — e-mail waits until % — MailAuthenticationException%'))
                 AND resumed AND NOT (after->>'held')::boolean, false),
        format('held until %s then %s | state %s | provider %s: %s | resumed %s, after %s', u1, u2, st, email.state, email.last_error, resumed, after));
END $$;
-- ── V558. The student lifecycle reconciliation: the cohort engine's position read as a recommendation — spillover year 1 and 2
--    (a planned next session moves nobody), the maximum spillover, the final year as a graduation candidate, a graduated student
--    never — with a confidence; reviewed and verified by the Registry only (a low-confidence record never in bulk); reconciled once
--    a session, revalidated at that moment — a spillover confirmed ACTIVE with the level raised, the maximum only on the officer's
--    choice of DORMANT or WITHDRAWN (never GRADUATED), a graduation candidate listed for the Senate with the status kept — and
--    corrected on a reason, the status, the level and a graduation-list entry put back, once; no matriculation number moves ──
DO $$
DECLARE
    y int := 2187; v_prog text; v_dept text; v_fac text; cur text;
    s1 uuid := gen_random_uuid(); s2 uuid := gen_random_uuid(); s3 uuid := gen_random_uuid(); s4 uuid := gen_random_uuid();
    s5 uuid := gen_random_uuid(); s6 uuid := gen_random_uuid();
    r1 record; r2 record; r3 record; r4 record; in5 boolean; m record; m2 record; v_ict text; v_note text;
    v_ref text; rc1 uuid; rc3 uuid; rc4 uuid; v_changed text; v_twice text; v_nolimit text; v_grad text; v_never text;
    l1 int; st1 text; st3 text; st4 text; sc3 text; dec1 text; g4 uuid; out4 text;
    c3 text; l1b int; restored boolean; g4_gone boolean; v_again text; matrics_kept boolean; review1 text;
BEGIN
  BEGIN   -- the check's own sessions, programme and students, undone at the end so no later check sees them
    PERFORM set_config('moaum.actor_id', gen_random_uuid()::text, true);
    PERFORM set_config('moaum.actor_office', 'registrar', true);
    PERFORM set_config('moaum.reason', 'CHECK V558', true);
    UPDATE policy.academic_session SET state = 'CLOSED', completed_at = now() WHERE state = 'CURRENT';
    INSERT INTO policy.academic_session (id, name, starts_on, ends_on, state)
    SELECT gen_random_uuid(), format('%s/%s', x, x + 1), make_date(x, 10, 1), make_date(x + 1, 9, 30), 'CLOSED' FROM generate_series(y - 6, y) x
    ON CONFLICT (name) DO NOTHING;
    INSERT INTO policy.academic_session (id, name, starts_on, ends_on, state) VALUES (gen_random_uuid(), format('%s/%s', y + 1, y + 2), make_date(y + 1, 10, 1), make_date(y + 2, 9, 30), 'PLANNED')
    ON CONFLICT (name) DO NOTHING;
    cur := format('%s/%s', y, y + 1);
    UPDATE policy.academic_session SET state = 'CURRENT', made_current_at = now(), senate_minute = 'SEN/2187/01' WHERE name = cur;
    SELECT dept_code, faculty_code INTO v_dept, v_fac FROM ref.programme WHERE category = 'UNDER GRADUATE' AND NOT archived ORDER BY code LIMIT 1;
    SELECT 'C' || lpad(x::text, 5, '0') INTO v_prog FROM generate_series(90000, 99999) x
     WHERE NOT EXISTS (SELECT 1 FROM ref.programme p WHERE p.code = 'C' || lpad(x::text, 5, '0')) ORDER BY x DESC LIMIT 1;
    INSERT INTO ref.programme (code, name, dept_code, faculty_code, category, min_score, final_level) VALUES (v_prog, 'B.Sc. CHECK V558', v_dept, v_fac, 'UNDER GRADUATE', 0, 400);
    -- no two-digit year in the numbers: the entry session is the only evidence of the cohort
    INSERT INTO people.student (id, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at) VALUES
        (s1, 'MOAUM/ZZL/LCK/55801', 'CHECKV558', 'Spillover One', v_prog, 'UTME', format('%s/%s', y - 4, y - 3), 100, 300, 'ACTIVE', now()),
        (s2, 'MOAUM/ZZL/LCK/55802', 'CHECKV558', 'Spillover Two', v_prog, 'UTME', format('%s/%s', y - 5, y - 4), 100, 400, 'ACTIVE', now()),
        (s3, 'MOAUM/ZZL/LCK/55803', 'CHECKV558', 'Maximum', v_prog, 'UTME', format('%s/%s', y - 6, y - 5), 100, 400, 'ACTIVE', now()),
        (s4, 'MOAUM/ZZL/LCK/55804', 'CHECKV558', 'Final Year', v_prog, 'UTME', format('%s/%s', y - 3, y - 2), 100, 400, 'ACTIVE', now()),
        (s5, 'MOAUM/ZZL/LCK/55805', 'CHECKV558', 'Graduated', v_prog, 'UTME', format('%s/%s', y - 6, y - 5), 100, 400, 'GRADUATED', now()),
        (s6, 'MOAUM/ZZL/LCK/55806', 'CHECKV558', 'Moved', v_prog, 'UTME', format('%s/%s', y - 4, y - 3), 100, 400, 'ACTIVE', now());
    INSERT INTO registration.course_registration (id, student_id, session, semester, level, status, submitted_at)
    SELECT gen_random_uuid(), x, cur, 1, 400, 'SUBMITTED', now() FROM unnest(ARRAY[s1, s3, s4, s6]) x;
    PERFORM people.refresh_academic_positions(ARRAY[s1, s2, s3, s4, s5, s6]);

    SELECT * INTO r1 FROM people.lifecycle_recommendation WHERE student_id = s1;
    SELECT * INTO r2 FROM people.lifecycle_recommendation WHERE student_id = s2;
    SELECT * INTO r3 FROM people.lifecycle_recommendation WHERE student_id = s3;
    SELECT * INTO r4 FROM people.lifecycle_recommendation WHERE student_id = s4;
    in5 := EXISTS (SELECT 1 FROM people.lifecycle_recommendation WHERE student_id = s5);

    -- ICT reads; it does not review
    PERFORM set_config('moaum.actor_office', 'ict', true);
    BEGIN PERFORM people.lifecycle_mark(ARRAY[s1], 'VERIFIED', NULL, false, NULL, NULL, NULL);
    EXCEPTION WHEN insufficient_privilege THEN v_ict := split_part(SQLERRM, ':', 1); END;
    PERFORM set_config('moaum.actor_office', 'registrar', true);
    BEGIN PERFORM people.lifecycle_mark(ARRAY[s1], 'REJECTED', ' ', false, NULL, NULL, NULL);
    EXCEPTION WHEN check_violation THEN v_note := split_part(SQLERRM, ':', 1); END;
    SELECT * INTO m FROM people.lifecycle_mark(ARRAY[s1, s2, s3, s4, s6], 'VERIFIED', NULL, false, NULL, NULL, NULL);
    SELECT * INTO m2 FROM people.lifecycle_mark(ARRAY[s2], 'VERIFIED', NULL, true, NULL, NULL, NULL);

    v_ref := people.lifecycle_open_batch('CHECK V558', 'The University');
    PERFORM people.lifecycle_prepare(ARRAY[s1, s3, s4, s6]);
    -- one record moves after it was verified: three sessions beyond now, not one
    UPDATE people.student SET entry_session = format('%s/%s', y - 6, y - 5) WHERE id = s6;
    BEGIN PERFORM people.lifecycle_reconcile(v_ref, s6, 'SPILLOVER_YEAR_1', NULL, NULL, 'CHECK V558 reason', NULL, NULL, NULL);
    EXCEPTION WHEN check_violation THEN v_changed := split_part(SQLERRM, ':', 1); END;
    rc1 := people.lifecycle_reconcile(v_ref, s1, 'SPILLOVER_YEAR_1', NULL, NULL, 'CHECK V558 reason', NULL, NULL, NULL);
    BEGIN PERFORM people.lifecycle_reconcile(v_ref, s1, 'SPILLOVER_YEAR_1', NULL, NULL, 'CHECK V558 again', NULL, NULL, NULL);
    EXCEPTION WHEN check_violation THEN v_twice := split_part(SQLERRM, ':', 1); END;
    BEGIN PERFORM people.lifecycle_reconcile(v_ref, s3, 'MAXIMUM_SPILLOVER_REACHED', NULL, NULL, 'CHECK V558 reason', NULL, NULL, NULL);
    EXCEPTION WHEN check_violation THEN v_nolimit := split_part(SQLERRM, ':', 1); END;
    BEGIN PERFORM people.lifecycle_reconcile(v_ref, s3, 'MAXIMUM_SPILLOVER_REACHED', 'STATUS_CHANGED', 'GRADUATED', 'CHECK V558 reason', NULL, NULL, NULL);
    EXCEPTION WHEN check_violation THEN v_grad := split_part(SQLERRM, ':', 1); END;
    rc3 := people.lifecycle_reconcile(v_ref, s3, 'MAXIMUM_SPILLOVER_REACHED', 'STATUS_CHANGED', 'DORMANT', 'CHECK V558 no registration since', NULL, NULL, NULL);
    rc4 := people.lifecycle_reconcile(v_ref, s4, 'GRADUATION_CANDIDATE', NULL, NULL, 'CHECK V558 final year', NULL, NULL, NULL);
    -- the graduation audit's entry (GraduationService places it in the API), recorded on the reconciliation
    INSERT INTO records.graduand (id, student_id, session, cgpa, award, unmet) VALUES (gen_random_uuid(), s4, cur, NULL, 'B.Sc. CHECK V558', 'No published result on the record')
    RETURNING id INTO g4;
    PERFORM people.lifecycle_graduand_placed(rc4, g4, true, 'No published result on the record');
    BEGIN
        INSERT INTO people.lifecycle_reconciliation (batch_ref, student_id, effective_session, recommendation, confidence, outcome, previous_status, new_status, explanation, reason, reconciled_by)
        VALUES (v_ref, s5, cur, 'GRADUATION_CANDIDATE', 'HIGH', 'STATUS_CHANGED', 'ACTIVE', 'GRADUATED', 'x', 'x', gen_random_uuid());
    EXCEPTION WHEN check_violation THEN v_never := 'REFUSED'; END;
    SELECT current_level, status INTO l1, st1 FROM people.student WHERE id = s1;
    SELECT status INTO st3 FROM people.student WHERE id = s3;
    SELECT status INTO st4 FROM people.student WHERE id = s4;
    SELECT from_status || '>' || to_status INTO sc3 FROM people.status_change WHERE student_id = s3 ORDER BY effective_on DESC, id DESC LIMIT 1;
    SELECT rule || ':' || previous_level || '>' || new_level INTO dec1 FROM people.cohort_decision WHERE student_id = s1 ORDER BY decided_at DESC LIMIT 1;
    SELECT outcome INTO out4 FROM people.lifecycle_reconciliation WHERE id = rc4;
    SELECT review_state INTO review1 FROM people.lifecycle_recommendation WHERE student_id = s1;

    -- corrected: the status, the level and the graduation-list entry put back, once
    PERFORM people.lifecycle_correct(rc3, 'CHECK V558 reconciled in error', NULL, NULL, NULL);
    PERFORM people.lifecycle_correct(rc1, 'CHECK V558 reconciled in error', NULL, NULL, NULL);
    PERFORM people.lifecycle_correct(rc4, 'CHECK V558 reconciled in error', NULL, NULL, NULL);
    SELECT status INTO c3 FROM people.student WHERE id = s3;
    SELECT current_level INTO l1b FROM people.student WHERE id = s1;
    SELECT level_restored INTO restored FROM people.lifecycle_reconciliation WHERE id = rc1;
    g4_gone := NOT EXISTS (SELECT 1 FROM records.graduand WHERE id = g4);
    BEGIN PERFORM people.lifecycle_correct(rc1, 'CHECK V558 again', NULL, NULL, NULL);
    EXCEPTION WHEN check_violation THEN v_again := split_part(SQLERRM, ':', 1); END;
    matrics_kept := (SELECT count(*) FROM people.student WHERE id IN (s1, s2, s3, s4, s5, s6) AND matric_no LIKE 'MOAUM/ZZL/LCK/5580_') = 6;
    RAISE EXCEPTION 'CHECK_V558_UNDONE' USING ERRCODE = 'P0001';
  EXCEPTION WHEN raise_exception THEN
    IF SQLERRM <> 'CHECK_V558_UNDONE' THEN RAISE; END IF;
  END;

    PERFORM pg_temp.assert('V558: the cohort engine''s position read as a recommendation with a confidence, reviewed by the Registry only (a low-confidence record never verified in bulk), reconciled once a session after revalidation — spillover confirmed ACTIVE with the level raised, the maximum only on the officer''s choice and never GRADUATED, a graduation candidate listed with the status kept — and corrected once, the status, level and list entry put back; no matriculation number moves',
        coalesce(r1.recommendation = 'SPILLOVER_YEAR_1' AND r1.spillover_years = 1 AND r1.confidence = 'HIGH'
            AND r2.recommendation = 'SPILLOVER_YEAR_2' AND r2.confidence = 'LOW'
            AND r3.recommendation = 'MAXIMUM_SPILLOVER_REACHED' AND r4.recommendation = 'GRADUATION_CANDIDATE' AND r4.candidate_basis = 'FINAL_YEAR' AND NOT in5
            AND v_ict = 'LIFECYCLE_OFFICE' AND v_note = 'LIFECYCLE_REVIEW_NOTE' AND m.marked = 4 AND m.low = 1 AND m2.marked = 1
            AND v_ref ~ '^RECON/[0-9]{4}/[0-9]{6}$' AND v_changed = 'LIFECYCLE_CHANGED' AND v_twice = 'LIFECYCLE_ALREADY'
            AND v_nolimit = 'LIFECYCLE_LIMIT_OUTCOME' AND v_grad = 'LIFECYCLE_LIMIT_OUTCOME' AND v_never = 'REFUSED'
            AND l1 = 400 AND st1 = 'ACTIVE' AND st3 = 'DORMANT' AND sc3 = 'ACTIVE>DORMANT' AND st4 = 'ACTIVE' AND out4 = 'GRADUATION_LIST'
            AND dec1 = 'LIFECYCLE_SPILLOVER_YEAR_1:300>400' AND review1 = 'RECONCILED'
            AND c3 = 'ACTIVE' AND l1b = 300 AND restored AND g4_gone AND v_again = 'LIFECYCLE_CORRECTED' AND matrics_kept, false),
        format('recs %s/%s(%s) %s %s %s/%s %s/%s graduated listed %s | ict %s note %s | marked %s low %s single %s | batch %s | changed %s twice %s no limit %s graduated %s never %s | s1 %s %s s3 %s %s s4 %s %s | decision %s review %s | corrected %s %s restored %s list gone %s again %s | matrics %s',
               r1.recommendation, r1.spillover_years, r1.confidence, r2.recommendation, r2.confidence, r3.recommendation, r3.confidence, r4.recommendation, r4.candidate_basis, in5,
               v_ict, v_note, m.marked, m.low, m2.marked, v_ref, v_changed, v_twice, v_nolimit, v_grad, v_never, l1, st1, st3, sc3, st4, out4, dec1, review1,
               c3, l1b, restored, g4_gone, v_again, matrics_kept));
END $$;
-- ── V557. The bank reconciliation statement. Last month, for an invented student: payments confirmed — one on the collections
--          statement, one at another amount, two settled in a gateway's day with NGN 50 kept as charges, one not yet in the bank,
--          one through a migration that never passes the bank — a credit for a reference never confirmed, an inflow no one found,
--          the bank's charges accounted for with a journal, and a NELFUND remittance of 2,000 of which 1,500 is credited to the
--          student; refunds paid, one on the disbursement statement and one not, a debit no one found and a transfer in. Each is the
--          item it should be with its effect; the difference is the ledger's balance less the statement's adjusted by the items.
--          A reconciliation is prepared and signed by another officer, only once explained; a signed one is kept, and its lines
--          and period are no longer changed. The block undoes its writes ──
DO $$
DECLARE maker uuid := gen_random_uuid(); checker uuid := gen_random_uuid(); s uuid := gen_random_uuid(); a text := '9963/9964';
        v_today date := (now() AT TIME ZONE 'Africa/Lagos')::date; m_from date; m_to date; d1 date; d2 date; t1 timestamptz; t2 timestamptz;
        cs uuid; ds uuid; k text; rf text; rid uuid; v_expense text; v_charges uuid; v_charges_no bigint;
        coll text; coll_after text; disb text; f jsonb; fd jsonb; wide jsonb; booked_ok boolean;
        bad_matched text; bad_account text; bad_note text; rec uuid; same_officer text; unexplained text; signed jsonb; kept text; signed_line text;
        taken text; open_period text; rec2 uuid; disb_signed text; items_kept int; msg text;
BEGIN
    BEGIN
        m_from := (date_trunc('month', v_today) - interval '1 month')::date;
        m_to := (date_trunc('month', v_today) - interval '1 day')::date;
        d1 := m_from + 9; d2 := m_from + 11;
        t1 := (d1::timestamp + interval '10 hours') AT TIME ZONE 'Africa/Lagos';
        t2 := (d2::timestamp + interval '10 hours') AT TIME ZONE 'Africa/Lagos';
        PERFORM set_config('moaum.actor_id', maker::text, true);
        PERFORM set_config('moaum.actor_office', 'bursar', true);
        PERFORM set_config('moaum.reason', 'check V557', true);
        INSERT INTO policy.academic_session (id, name, starts_on, ends_on) VALUES (gen_random_uuid(), a, date '9963-10-01', date '9964-08-31')
        ON CONFLICT (name) DO NOTHING;
        INSERT INTO iam.person (id, surname, given_names, email) VALUES (maker, 'ZZCHKV557', 'Maker', NULL), (checker, 'ZZCHKV557', 'Checker', NULL);
        INSERT INTO people.student (id, admission_no, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
        SELECT s, 'MOAUM/ADM/63/996301', 'MOAUM/CHK/63/9963', 'ZZCHKV557', 'Invented', code, 'UTME', a, 100, 100, 'ACTIVE', now()
          FROM ref.programme WHERE NOT coalesce(archived, false) ORDER BY code LIMIT 1;
        INSERT INTO finance.payment_reference (student_id, session, reference, purpose, amount, generated_at, expires_at, confirmed_at, confirmed_by, channel, receipt_no, note) VALUES
            (s, a, 'MOAUM-FEE-996301-0001', 'School fees ' || a, 5000, t1 - interval '1 day', t1 + interval '7 days', t1, maker, 'Bank transfer', 'RCT-ZZ557-0001', 'check V557'),
            (s, a, 'MOAUM-FEE-996301-0002', 'School fees ' || a, 3000, t1 - interval '1 day', t1 + interval '7 days', t1, maker, 'Card · Paystack', 'RCT-ZZ557-0002', 'check V557'),
            (s, a, 'MOAUM-FEE-996301-0003', 'School fees ' || a, 1000, t2 - interval '1 day', t2 + interval '7 days', t2, maker, 'ZZ557 Gateway', 'RCT-ZZ557-0003', 'check V557'),
            (s, a, 'MOAUM-FEE-996301-0004', 'School fees ' || a, 1000, t2 - interval '1 day', t2 + interval '7 days', t2, maker, 'ZZ557 Gateway', 'RCT-ZZ557-0004', 'check V557'),
            (s, a, 'MOAUM-FEE-996301-0005', 'School fees ' || a, 700, t2 - interval '1 day', t2 + interval '7 days', t2, maker, 'Bank transfer', 'RCT-ZZ557-0005', 'check V557'),
            (s, a, 'MOAUM-FEE-996301-0006', 'School fees ' || a, 900, t2 - interval '1 day', t2 + interval '7 days', t2, maker, 'MIGRATION', 'RCT-ZZ557-0006', 'check V557'),
            (s, a, 'MOAUM-FEE-996301-0007', 'School fees ' || a, 2500, t2 - interval '1 day', now() + interval '7 days', NULL, NULL, NULL, NULL, 'check V557');
        INSERT INTO finance.nelfund_batch (ref, session, received_on, amount, rows_read, note) VALUES ('ZZ557-NELF', a, d1, 2000, 2, 'check V557');
        INSERT INTO finance.wallet_entry (student_id, session, kind, amount, reference, note, source_code, at)
        VALUES (s, a, 'CREDIT', 1500, 'ZZ557-NELF', 'NELFUND institutional charges, check V557', 'NELFUND', t1);
        -- refunds paid: A on the disbursement statement, B not yet
        FOREACH k IN ARRAY ARRAY['A:3000', 'B:900'] LOOP
            PERFORM set_config('moaum.actor_id', maker::text, true);
            rf := finance.propose_refund(NULL, 'ZZCHKV557, ' || split_part(k, ':', 1), 'check V557 ' || k, split_part(k, ':', 2)::numeric, NULL, NULL, NULL, NULL);
            rid := (SELECT id FROM finance.refund WHERE reference = rf);
            PERFORM finance.desk_refund_account(rid, 'GTB', 'ZZCHKV557 Invented', '2222222223');
            PERFORM set_config('moaum.actor_id', checker::text, true);
            PERFORM finance.approve_refund(rid);
            UPDATE finance.refund SET approved_at = m_from - 5 WHERE id = rid;
            PERFORM finance.pay_refund(rid, 'FT-ZZ557-' || split_part(k, ':', 1), CASE split_part(k, ':', 1) WHEN 'A' THEN d1 ELSE d2 END);
        END LOOP;
        PERFORM set_config('moaum.actor_id', maker::text, true);
        PERFORM * FROM finance.gl_sync(NULL::int);
        -- the bank's charges accounted for with a journal
        v_expense := (SELECT code FROM finance.gl_account WHERE type = 'EXPENSE' AND postable AND active ORDER BY code LIMIT 1);
        v_charges := finance.gl_post(d2, 'CHECK V557 bank charges', 'MANUAL', 'ADJUSTMENT', NULL, jsonb_build_array(
                         jsonb_build_object('account', v_expense, 'debit', 25, 'narration', 'check V557'), jsonb_build_object('account', '1010', 'credit', 25, 'narration', 'check V557')));
        v_charges_no := (SELECT journal_no FROM finance.gl_journal WHERE id = v_charges);

        -- the statements, each covering the whole month
        cs := finance.load_collections_statement('CHECK V557 collections', 'c.csv', jsonb_build_array(
            jsonb_build_object('date', m_from::text, 'reference', '', 'description', 'CHECK V557 CHARGES', 'debit', '25'),
            jsonb_build_object('date', d1::text, 'reference', 'MOAUM-FEE-996301-0001', 'description', 'Transfer', 'credit', '5000'),
            jsonb_build_object('date', d1::text, 'reference', '', 'description', 'NIP/MOAUMFEE9963010002', 'credit', '3100'),
            jsonb_build_object('date', d1::text, 'reference', '', 'description', 'NELFUND REMITTANCE ZZ557-NELF', 'credit', '2000'),
            jsonb_build_object('date', d2::text, 'reference', '', 'description', 'ZZ557 GATEWAY SETTLEMENT', 'credit', '1950'),
            jsonb_build_object('date', d2::text, 'reference', '', 'description', 'TRF MOAUM-FEE-996301-0007', 'credit', '2500'),
            jsonb_build_object('date', m_to::text, 'reference', '', 'description', 'CHECK V557 UNKNOWN INFLOW', 'credit', '400')));
        PERFORM finance.settle_collections_line((SELECT id FROM finance.bank_statement_line WHERE statement_id = cs AND line_no = 5), 'ZZ557 Gateway', d2);
        ds := finance.load_bank_statement('CHECK V557 disbursements', 'd.csv', jsonb_build_array(
            jsonb_build_object('date', m_from::text, 'reference', '', 'description', 'CHECK V557 UNKNOWN DEBIT', 'debit', '60'),
            jsonb_build_object('date', d1::text, 'reference', 'FT-ZZ557-A', 'description', 'Transfer', 'debit', '3000'),
            jsonb_build_object('date', m_to::text, 'reference', '', 'description', 'CHECK V557 FUNDING IN', 'credit', '10000')));

        -- the items, before and after the charges line is accounted for
        coll := (SELECT string_agg(i.kind || ':' || CASE WHEN i.reference LIKE 'MOAUM-FEE-996301-%' THEN right(i.reference, 4) WHEN i.line_id IS NOT NULL THEN i.reference ELSE coalesce(left(i.description, 30), '-') END || ':' || i.effect::int, ',' ORDER BY i.kind, i.reference, i.effect)
                   FROM finance.bank_reconciliation_items('1010', m_from, m_to) i
                  WHERE i.reference LIKE 'MOAUM-FEE-996301-%' OR i.reference = 'ZZ557-NELF' OR i.description LIKE '%CHECK V557%' OR i.journal_no = v_charges_no);
        BEGIN
            PERFORM finance.book_statement_line((SELECT id FROM finance.bank_statement_line WHERE statement_id = cs AND line_no = 2), v_charges_no, 'x');
        EXCEPTION WHEN check_violation THEN bad_matched := split_part(SQLERRM, ':', 1);
        END;
        BEGIN
            PERFORM finance.book_statement_line((SELECT id FROM finance.bank_statement_line WHERE statement_id = cs AND line_no = 1),
                                                (SELECT j.journal_no FROM finance.gl_journal j WHERE j.source_type = 'REFUND' AND j.source_ref = rf), 'x');
        EXCEPTION WHEN check_violation THEN bad_account := split_part(SQLERRM, ':', 1);
        END;
        BEGIN
            PERFORM finance.book_statement_line((SELECT id FROM finance.bank_statement_line WHERE statement_id = cs AND line_no = 1), v_charges_no, ' ');
        EXCEPTION WHEN check_violation THEN bad_note := split_part(SQLERRM, ':', 1);
        END;
        PERFORM finance.book_statement_line((SELECT id FROM finance.bank_statement_line WHERE statement_id = cs AND line_no = 1), v_charges_no, 'The bank''s charges for the month');
        coll_after := (SELECT string_agg(i.kind || ':' || CASE WHEN i.reference LIKE 'MOAUM-FEE-996301-%' THEN right(i.reference, 4) WHEN i.line_id IS NOT NULL THEN i.reference ELSE coalesce(left(i.description, 30), '-') END || ':' || i.effect::int, ',' ORDER BY i.kind, i.reference, i.effect)
                         FROM finance.bank_reconciliation_items('1010', m_from, m_to) i
                        WHERE i.reference LIKE 'MOAUM-FEE-996301-%' OR i.reference = 'ZZ557-NELF' OR i.description LIKE '%CHECK V557%' OR i.journal_no = v_charges_no);
        booked_ok := coll_after = 'AMOUNT_DIFFERENCE:0002:-100,BANK_CREDIT_NOT_IN_LEDGER:CHECK V557 UNKNOWN INFLOW:-400,BANK_CREDIT_NOT_IN_LEDGER:0007:-2500,'
                                 || 'GATEWAY_CHARGES:ZZ557 GATEWAY SETTLEMENT:50,NELFUND_NOT_CREDITED:ZZ557-NELF:-500,RECEIPT_NOT_IN_BANK:0005:700,RECEIPT_OUTSIDE_BANK:0006:900';
        disb := (SELECT string_agg(i.kind || ':' || CASE WHEN i.description LIKE '%FT-ZZ557-%' THEN substring(i.description from 'FT-ZZ557-.') WHEN i.line_id IS NOT NULL THEN i.reference ELSE coalesce(left(i.description, 30), '-') END || ':' || i.effect::int, ',' ORDER BY i.kind, i.effect)
                   FROM finance.bank_reconciliation_items('1020', m_from, m_to) i
                  WHERE i.description LIKE '%FT-ZZ557-%' OR i.description LIKE '%CHECK V557%');
        f := finance.bank_reconciliation_figures('1010', m_from, m_to, 1000);
        wide := finance.bank_reconciliation_figures('1020', m_from, m_to + 3, 1000);

        -- prepared with a difference of 7: not signed by its preparer, nor unexplained; prepared again with a note, signed by another
        rec := finance.prepare_bank_reconciliation('1010', m_from, m_to, (f->>'ledger_balance')::numeric - (f->>'items_effect')::numeric + 7, NULL);
        BEGIN
            PERFORM finance.sign_bank_reconciliation(rec);
        EXCEPTION WHEN check_violation THEN same_officer := split_part(SQLERRM, ':', 1);
        END;
        PERFORM set_config('moaum.actor_id', checker::text, true);
        BEGIN
            PERFORM finance.sign_bank_reconciliation(rec);
        EXCEPTION WHEN check_violation THEN unexplained := split_part(SQLERRM, ':', 1);
        END;
        PERFORM set_config('moaum.actor_id', maker::text, true);
        PERFORM finance.prepare_bank_reconciliation('1010', m_from, m_to, (f->>'ledger_balance')::numeric - (f->>'items_effect')::numeric + 7, 'NGN 7 of cash deposited at the branch is being traced');
        PERFORM set_config('moaum.actor_id', checker::text, true);
        signed := finance.sign_bank_reconciliation(rec);
        items_kept := (SELECT jsonb_array_length(r.items) FROM finance.bank_reconciliation r WHERE r.id = rec);
        BEGIN
            UPDATE finance.bank_reconciliation SET note = 'changed' WHERE id = rec;
        EXCEPTION WHEN check_violation THEN kept := split_part(SQLERRM, ':', 1);
        END;
        PERFORM set_config('moaum.actor_id', maker::text, true);
        BEGIN
            PERFORM finance.book_statement_line((SELECT id FROM finance.bank_statement_line WHERE statement_id = cs AND line_no = 1), NULL, NULL);
        EXCEPTION WHEN check_violation THEN signed_line := split_part(SQLERRM, ':', 1);
        END;
        BEGIN
            PERFORM finance.prepare_bank_reconciliation('1010', m_from + 3, m_to + 3, 1, NULL);
        EXCEPTION WHEN check_violation THEN taken := split_part(SQLERRM, ':', 1);
        END;
        -- the month that runs is not signed
        rec2 := finance.prepare_bank_reconciliation('1010', m_to + 1, (date_trunc('month', v_today) + interval '1 month - 1 day')::date, 1, 'x');
        PERFORM set_config('moaum.actor_id', checker::text, true);
        BEGIN
            PERFORM finance.sign_bank_reconciliation(rec2);
        EXCEPTION WHEN check_violation THEN open_period := split_part(SQLERRM, ':', 1);
        END;
        -- the disbursement account, closing so that nothing is left: signed with no note
        PERFORM set_config('moaum.actor_id', maker::text, true);
        fd := finance.bank_reconciliation_figures('1020', m_from, m_to, 0);
        rec2 := finance.prepare_bank_reconciliation('1020', m_from, m_to, (fd->>'ledger_balance')::numeric - (fd->>'items_effect')::numeric, NULL);
        PERFORM set_config('moaum.actor_id', checker::text, true);
        PERFORM finance.sign_bank_reconciliation(rec2);
        disb_signed := (SELECT r.state || ':' || r.difference::int FROM finance.bank_reconciliation r WHERE r.id = rec2);
        RAISE EXCEPTION 'the V557 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V557 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V557: the bank reconciliation sets the ledger''s balance beside the statement''s with every item between them — on the ledger and not in the bank, in the bank and not on the ledger, a difference, a gateway''s charges — a line accounted for with a journal is no item, and a reconciliation is signed by another officer once explained and is then kept',
        coalesce(coll = 'AMOUNT_DIFFERENCE:0002:-100,BANK_CREDIT_NOT_IN_LEDGER:CHECK V557 UNKNOWN INFLOW:-400,BANK_CREDIT_NOT_IN_LEDGER:0007:-2500,'
                     || 'BANK_DEBIT_NOT_IN_LEDGER:CHECK V557 CHARGES:25,GATEWAY_CHARGES:ZZ557 GATEWAY SETTLEMENT:50,LEDGER_CREDIT_NOT_IN_BANK:CHECK V557 bank charges:-25,'
                     || 'NELFUND_NOT_CREDITED:ZZ557-NELF:-500,RECEIPT_NOT_IN_BANK:0005:700,RECEIPT_OUTSIDE_BANK:0006:900'
                 AND bad_matched = 'LINE_NOT_FOR_JOURNAL' AND bad_account = 'LINE_JOURNAL_ACCOUNT' AND bad_note = 'LINE_JOURNAL_NOTE' AND booked_ok
                 AND disb = 'BANK_CREDIT_NOT_IN_LEDGER:CHECK V557 FUNDING IN:-10000,BANK_DEBIT_NOT_IN_LEDGER:CHECK V557 UNKNOWN DEBIT:60,PAYOUT_NOT_IN_BANK:FT-ZZ557-B:-900'
                 AND (f->>'missing_days')::int = 0 AND (f->>'unposted')::int = 0 AND (f->>'period_ended')::boolean
                 AND (f->>'difference')::numeric = (f->>'ledger_balance')::numeric - (1000 + (f->>'items_effect')::numeric)
                 AND (wide->>'missing_days')::int = 3
                 AND same_officer = 'RECON_SAME_OFFICER' AND unexplained = 'RECON_DIFFERENCE_UNEXPLAINED' AND (signed->>'difference')::numeric = -7 AND items_kept > 0
                 AND kept = 'RECON_SIGNED' AND signed_line = 'RECON_SIGNED_PERIOD' AND taken = 'RECON_PERIOD_TAKEN' AND open_period = 'RECON_PERIOD_OPEN'
                 AND disb_signed = 'SIGNED:0', false),
        format('collections %s | after booking %s | refusals %s/%s/%s | disbursements %s | figures missing %s unposted %s ended %s difference %s (ledger %s, effect %s) | wide missing %s | sign %s/%s signed %s items %s kept %s line %s taken %s open %s | 1020 %s',
               coll, coll_after, bad_matched, bad_account, bad_note, disb, f->>'missing_days', f->>'unposted', f->>'period_ended', f->>'difference', f->>'ledger_balance', f->>'items_effect',
               wide->>'missing_days', same_officer, unexplained, signed->>'difference', items_kept, kept, signed_line, taken, open_period, disb_signed));
END $$;

-- ── V559. The bulk student password reset: an agent posted to a faculty with BULK_RESET_PASSWORD reaches that faculty's students
-- only — one with a matriculation number may be reset, one without is MATRICULATION NUMBER NOT AVAILABLE, one in another faculty is
-- ACCESS NOT AUTHORIZED with nothing of the record shown, an id that names no student is not found — while the Head reaches the
-- University, and an agent without the capability nobody; an operation is opened once for one key (BPR/YYYY/NNNNNN, one item a
-- student however often chosen), refused without a reason or a student, and counted as its students are reset: a student failed or
-- never found counts against it, an item is FAILED only with its code; a cancelled one stays cancelled, its counts kept. The block
-- undoes its writes.
DO $$
DECLARE who uuid := gen_random_uuid(); agent uuid; plain uuid; q text; fac text; prog_in text; prog_out text;
        a uuid := gen_random_uuid(); b uuid := gen_random_uuid(); c uuid := gen_random_uuid(); d uuid := gen_random_uuid();
        codes text; head_codes text; plain_codes text; hidden boolean; op uuid; op2 uuid; ref text; items int; total int;
        short text; empty text; tally text; counts text; bad_item text; msg text; known boolean; op3 uuid; cancelled text;
BEGIN
    BEGIN
        PERFORM set_config('moaum.actor_id', who::text, true);
        PERFORM set_config('moaum.actor_office', 'helpdeskhead', true);
        PERFORM set_config('moaum.reason', 'CHECK V559', true);
        known := 'BULK_RESET_PASSWORD' = ANY (helpdesk.support_capabilities());
        SELECT code, faculty_code INTO prog_in, fac FROM ref.programme WHERE code = 'C00023';
        SELECT code INTO prog_out FROM ref.programme WHERE faculty_code <> fac AND NOT coalesce(archived, false) ORDER BY code LIMIT 1;
        SELECT code INTO q FROM helpdesk.queue WHERE active ORDER BY ordinal LIMIT 1;
        INSERT INTO iam.person (id, surname, given_names) VALUES (gen_random_uuid(), 'CHECKBULK', 'Agent') RETURNING id INTO agent;
        INSERT INTO iam.person (id, surname, given_names) VALUES (gen_random_uuid(), 'CHECKBULK', 'Plain') RETURNING id INTO plain;
        INSERT INTO helpdesk.agent_assignment (person_id, queue_code, scope_kind, scope_ref, capabilities) VALUES
            (agent, q, 'FACULTY', fac, ARRAY['VIEW_STUDENT', 'RESET_PASSWORD', 'BULK_RESET_PASSWORD']),
            (plain, q, 'FACULTY', fac, ARRAY['VIEW_STUDENT', 'RESET_PASSWORD']);
        INSERT INTO people.student (id, matric_no, admission_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at) VALUES
            (a, 'MOAUM/CHK/59/055901', 'MOAUM/ADM/59/559001', 'CHECKBULKA', 'In', prog_in, 'UTME', '2059/2060', 100, 100, 'ACTIVE', now()),
            (b, NULL, 'MOAUM/ADM/59/559002', 'CHECKBULKB', 'No Number', prog_in, 'UTME', '2059/2060', 100, 100, 'ADMITTED', NULL),
            (c, 'MOAUM/CHK/59/055903', 'MOAUM/ADM/59/559003', 'CHECKBULKC', 'Outside', prog_out, 'UTME', '2059/2060', 100, 100, 'ACTIVE', now());
        SELECT string_agg(x.code, ',' ORDER BY x.code), bool_and(x.full_name IS NULL AND x.matric_no IS NULL) FILTER (WHERE x.code IN ('OUT_OF_SCOPE', 'NOT_FOUND'))
          INTO codes, hidden FROM helpdesk.bulk_reset_check(agent, false, ARRAY[a, b, c, d]) x;
        SELECT string_agg(x.code, ',' ORDER BY x.code) INTO head_codes FROM helpdesk.bulk_reset_check(who, true, ARRAY[a, c]) x;
        SELECT string_agg(x.code, ',' ORDER BY x.code) INTO plain_codes FROM helpdesk.bulk_reset_check(plain, false, ARRAY[a]) x;
        BEGIN
            PERFORM helpdesk.start_bulk_reset(agent, 'ictagent', false, ARRAY[a], '{}'::jsonb, 'short', true, NULL);
        EXCEPTION WHEN check_violation THEN short := split_part(SQLERRM, ':', 1);
        END;
        BEGIN
            PERFORM helpdesk.start_bulk_reset(agent, 'ictagent', false, ARRAY[]::uuid[], '{}'::jsonb, 'Students reported login issues', true, NULL);
        EXCEPTION WHEN check_violation THEN empty := split_part(SQLERRM, ':', 1);
        END;
        op := helpdesk.start_bulk_reset(agent, 'ictagent', false, ARRAY[a, b, c, a, d], '{}'::jsonb, 'Students reported login issues', true, 'check-v559');
        op2 := helpdesk.start_bulk_reset(agent, 'ictagent', false, ARRAY[a], '{}'::jsonb, 'Students reported login issues', true, 'check-v559');
        SELECT r.reference, r.total INTO ref, total FROM helpdesk.bulk_reset r WHERE r.id = op;
        items := (SELECT count(*) FROM helpdesk.bulk_reset_item WHERE bulk_id = op);
        BEGIN
            UPDATE helpdesk.bulk_reset_item SET status = 'FAILED', processed_at = now() WHERE bulk_id = op AND student_id = b;
        EXCEPTION WHEN check_violation THEN bad_item := 'REFUSED';
        END;
        UPDATE helpdesk.bulk_reset_item SET status = 'RESET', processed_at = now() WHERE bulk_id = op AND student_id = a;
        UPDATE helpdesk.bulk_reset_item SET status = 'FAILED', failure_code = 'RESET_NO_MATRIC', processed_at = now() WHERE bulk_id = op AND student_id = b;
        tally := helpdesk.bulk_reset_tally(op);   -- c still waits
        UPDATE helpdesk.bulk_reset_item SET status = 'FAILED', failure_code = 'OUT_OF_SCOPE', processed_at = now() WHERE bulk_id = op AND student_id = c;
        tally := tally || '>' || helpdesk.bulk_reset_tally(op);
        SELECT r.succeeded || '/' || r.failed || '/' || r.total INTO counts FROM helpdesk.bulk_reset r WHERE r.id = op;
        -- cancelled with one student reset as the cancel came
        op3 := helpdesk.start_bulk_reset(agent, 'ictagent', false, ARRAY[a, c], '{}'::jsonb, 'Students reported login issues', true, 'check-v559-cancel');
        UPDATE helpdesk.bulk_reset SET status = 'CANCELLED' WHERE id = op3;
        UPDATE helpdesk.bulk_reset_item SET status = 'RESET', processed_at = now() WHERE bulk_id = op3 AND student_id = a;
        UPDATE helpdesk.bulk_reset_item SET status = 'FAILED', failure_code = 'CANCELLED', processed_at = now() WHERE bulk_id = op3 AND status = 'PENDING';
        cancelled := helpdesk.bulk_reset_tally(op3);
        cancelled := cancelled || ':' || (SELECT r.succeeded || '/' || r.failed || '/' || r.total FROM helpdesk.bulk_reset r WHERE r.id = op3);
        RAISE EXCEPTION 'the V559 check undoes its writes';
    EXCEPTION WHEN raise_exception THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg <> 'the V559 check undoes its writes' THEN RAISE; END IF;
    END;
    PERFORM pg_temp.assert('V559: a bulk password reset reaches only the students in the agent''s BULK_RESET_PASSWORD scope (the Head the University), names why a student may not be reset without showing one out of reach, is opened once for one key under BPR/YYYY/NNNNNN with one item a student, and counts a student failed or never found against it — a cancelled one too',
        coalesce(known AND codes = 'ELIGIBLE,NOT_FOUND,OUT_OF_SCOPE,RESET_NO_MATRIC' AND hidden AND head_codes = 'ELIGIBLE,ELIGIBLE' AND plain_codes = 'OUT_OF_SCOPE'
                 AND short = 'SUPPORT_REASON_SHORT' AND empty = 'BULK_RESET_EMPTY' AND op = op2 AND ref ~ '^BPR/\d{4}/\d{6}$' AND items = 3 AND total = 4
                 AND bad_item = 'REFUSED' AND tally = 'PROCESSING>COMPLETED_WITH_EXCEPTIONS' AND counts = '1/3/4' AND cancelled = 'CANCELLED:1/1/2', false),
        format('known %s | codes %s hidden %s | head %s | plain %s | refusals %s/%s | same %s ref %s items %s total %s | bad item %s | tally %s counts %s | cancelled %s',
               known, codes, hidden, head_codes, plain_codes, short, empty, op = op2, ref, items, total, bad_item, tally, counts, cancelled));
END $$;
-- ── V561. Possible bank double charges: old-portal records of one student, session, item, day and amount under two payment
--    numbers are listed; only the Bursary checks them with the bank, naming at least one and never all as not received; the
--    student's excess is held from carrying or refunding until checked; a payment the bank never received is withdrawn only when
--    another Bursary officer approves — kept on the withdrawn list, its payment number remembered so the export loaded again
--    never brings it back; a portal payment is never withdrawn here ──
DO $$
DECLARE
    y int := 2188; v_prog text; v_dept text; v_fac text; ses text; st uuid := gen_random_uuid();
    r1 text; r2 text; b1 uuid := gen_random_uuid(); b2 uuid := gen_random_uuid();
    listed int; v_ict text; v_all text; held record; v_ref text; v_same text; v_state text; waiting int;
    left_n int; kind text; remembered int; imp record; v_portal text; listed_after int; told int;
BEGIN
  BEGIN   -- the check's own sessions, programme, student and payments, undone at the end
    PERFORM set_config('moaum.actor_id', b1::text, true);
    PERFORM set_config('moaum.actor_office', 'bursar', true);
    PERFORM set_config('moaum.reason', 'CHECK V561', true);
    ses := format('%s/%s', y, y + 1);
    INSERT INTO policy.academic_session (id, name, starts_on, ends_on, state) VALUES
        (gen_random_uuid(), ses, make_date(y, 10, 1), make_date(y + 1, 9, 30), 'PLANNED'),
        (gen_random_uuid(), format('%s/%s', y + 1, y + 2), make_date(y + 1, 10, 1), make_date(y + 2, 9, 30), 'PLANNED')
    ON CONFLICT (name) DO NOTHING;
    SELECT dept_code, faculty_code INTO v_dept, v_fac FROM ref.programme WHERE category = 'UNDER GRADUATE' AND NOT archived ORDER BY code LIMIT 1;
    SELECT 'C' || lpad(x::text, 5, '0') INTO v_prog FROM generate_series(90000, 99999) x
     WHERE NOT EXISTS (SELECT 1 FROM ref.programme p WHERE p.code = 'C' || lpad(x::text, 5, '0')) ORDER BY x DESC LIMIT 1;
    INSERT INTO ref.programme (code, name, dept_code, faculty_code, category, min_score, final_level) VALUES (v_prog, 'B.Sc. CHECK V561', v_dept, v_fac, 'UNDER GRADUATE', 0, 400);
    INSERT INTO finance.fee_schedule (session, item, amount, level, programme_code) VALUES (ses, 'School fees', 121849.80, NULL, v_prog);
    INSERT INTO people.student (id, matric_no, surname, other_names, programme_code, entry_mode, entry_session, entry_level, current_level, status, matriculated_at)
    VALUES (st, 'MOAUM/ZZL/DBL/56101', 'CHECKV561', 'Double Charge', v_prog, 'UTME', ses, 100, 200, 'ACTIVE', now());
    r1 := 'MOAUM-LEG-MOAUMZZLDBL56101-' || replace(ses, '/', '-') || '-S1';
    r2 := r1 || '-PR21881123062528751';
    INSERT INTO finance.payment_reference (student_id, session, reference, purpose, amount, expires_at, confirmed_at, confirmed_by, channel, note, receipt_no) VALUES
        (st, ses, r1, 'School fees (legacy) · semester 1', 85294, make_date(y, 11, 23), make_timestamptz(y, 11, 23, 9, 0, 0, 'Africa/Lagos'), b1, 'Legacy', 'Imported from the old portal', 'LEG-' || r1),
        (st, ses, r2, 'School fees (legacy) · semester 1', 85294, make_date(y, 11, 23), make_timestamptz(y, 11, 23, 10, 0, 0, 'Africa/Lagos'), b1, 'Legacy', 'Imported from the old portal', 'LEG-' || r2);
    INSERT INTO finance.legacy_payref (payref, reference, amount) VALUES ('PR21881123061111111', r1, 85294), ('PR21881123062528751', r2, 85294);

    SELECT count(*) INTO listed FROM finance.possible_double_charges(ses) d WHERE d.student_id = st AND d.payments = 2 AND d.verdict IS NULL;
    PERFORM set_config('moaum.actor_office', 'ict', true);
    BEGIN PERFORM finance.check_double_charge(st, ses, 'School fees (legacy) · semester 1', make_date(y, 11, 23), 85294, 'RECEIVED', 'Zenith statement', NULL, NULL);
    EXCEPTION WHEN insufficient_privilege THEN v_ict := split_part(SQLERRM, ':', 1); END;
    PERFORM set_config('moaum.actor_office', 'bursar', true);
    BEGIN PERFORM finance.check_double_charge(st, ses, 'School fees (legacy) · semester 1', make_date(y, 11, 23), 85294, 'NOT_RECEIVED', 'Zenith statement', NULL, ARRAY[r1, r2]);
    EXCEPTION WHEN check_violation THEN v_all := split_part(SQLERRM, ':', 1); END;
    SELECT * INTO held FROM finance.decide_overpayments(ses, 'CARRY', ARRAY[st], 'CHECK V561: carried after the bank answers', 100);

    PERFORM finance.check_double_charge(st, ses, 'School fees (legacy) · semester 1', make_date(y, 11, 23), 85294, 'NOT_RECEIVED',
                                        'Zenith statement: one credit of 85,294', 'CHECK V561', ARRAY[r2]);
    SELECT request_ref INTO v_ref FROM finance.payment_not_received WHERE reference = r2 AND state = 'PROPOSED';
    SELECT open_requests INTO waiting FROM finance.possible_double_charges(ses) d WHERE d.student_id = st;
    BEGIN PERFORM finance.decide_not_received(v_ref, true, NULL);
    EXCEPTION WHEN insufficient_privilege THEN v_same := split_part(SQLERRM, ':', 1); END;
    PERFORM set_config('moaum.actor_id', b2::text, true);
    v_state := finance.decide_not_received(v_ref, true, 'CHECK V561 statement seen');
    SELECT count(*) INTO left_n FROM finance.payment_reference WHERE student_id = st;
    SELECT double_kind INTO kind FROM finance.old_payment_withdrawn WHERE reference = r2;
    SELECT count(*) INTO remembered FROM finance.legacy_payref_withdrawn WHERE payref = 'PR21881123062528751';
    SELECT count(*) INTO told FROM platform.notice WHERE template_key = 'PAYMENT_NOT_RECEIVED_REMOVED' AND about_id = st;
    SELECT count(*) INTO listed_after FROM finance.possible_double_charges(ses) d WHERE d.student_id = st;
    SELECT * INTO imp FROM finance.import_legacy_payments(jsonb_build_array(jsonb_build_object('matric', 'MOAUM/ZZL/DBL/56101', 'session', ses, 'semester', 'First',
        'amount', '85294', 'purpose', 'SCHOOL FEES', 'paidOn', format('%s-11-23', y), 'receiptNo', 'PR21881123062528751')));
    INSERT INTO finance.payment_reference (student_id, session, reference, purpose, amount, expires_at, confirmed_at, confirmed_by, channel, note, receipt_no)
    VALUES (st, ses, 'MOAUM-CHK561-PORTAL', 'School fees ' || ses, 1000, now(), now(), b1, 'INTERSWITCH', 'portal', 'RCT-MOAUM-CHK561-PORTAL');
    BEGIN PERFORM finance.propose_not_received('MOAUM-CHK561-PORTAL', 'Zenith statement', 'CHECK V561 a portal payment', NULL, NULL);
    EXCEPTION WHEN check_violation THEN v_portal := split_part(SQLERRM, ':', 1); END;
    RAISE EXCEPTION 'CHECK_V561_UNDONE' USING ERRCODE = 'P0001';
  EXCEPTION WHEN raise_exception THEN
    IF SQLERRM <> 'CHECK_V561_UNDONE' THEN RAISE; END IF;
  END;

    PERFORM pg_temp.assert('V561: old-portal payments of one day and amount under two payment numbers are listed, checked with the bank by the Bursary only (at least one received), the excess held until then, and one the bank never received withdrawn only on another officer''s approval — kept, its number remembered, the student told; a portal payment is never withdrawn here',
        coalesce(listed = 1 AND v_ict = 'PAY_CHECK_OFFICE' AND v_all = 'PAY_CHECK_NOT_RECEIVED_LIST'
            AND held.carried = 0 AND held.held = 1 AND held.remaining = 0
            AND v_ref ~ '^PNR/[0-9]{4}/[0-9]{6}$' AND waiting = 1 AND v_same = 'PAY_NOT_RECEIVED_SAME_OFFICER' AND v_state = 'APPROVED'
            AND left_n = 1 AND kind = 'NOT_RECEIVED' AND remembered = 1 AND told >= 1 AND listed_after = 0
            AND imp.duplicates = 1 AND imp.cleared = 0 AND v_portal = 'PAY_NOT_RECEIVED_NOT_OLD_PORTAL', false),
        format('listed %s | ict %s all %s | decide carried %s held %s left %s | request %s waiting %s same %s state %s | records left %s kind %s remembered %s told %s listed after %s | import dup %s cleared %s | portal %s',
               listed, v_ict, v_all, held.carried, held.held, held.remaining, v_ref, waiting, v_same, v_state, left_n, kind, remembered, told, listed_after,
               imp.duplicates, imp.cleared, v_portal));
END $$;
-- ── result ────────────────────────────────────────────────────────────────
-- A check that ERRORS never reaches its assert, so counting only failures
-- reports green over an aborted block. The count of checks that actually ran
-- is therefore part of the result.
SELECT CASE
    WHEN (SELECT count(*) FROM ran) <> :EXPECTED
        THEN E'\n=== ' || (SELECT count(*) FROM ran) || ' of ' || :EXPECTED ||
             ' checks RAN — ' || (:EXPECTED - (SELECT count(*) FROM ran)) ||
             ' errored before asserting anything ==='
    WHEN (SELECT count(*) FROM failures) = 0
        THEN E'\n=== FOUNDATION GREEN — ' || :EXPECTED || ' properties, all holding ==='
    ELSE E'\n=== ' || (SELECT count(*) FROM failures) || ' FAILED: ' ||
         (SELECT string_agg(name, '; ') FROM failures) || ' ==='
END;
